SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."invoices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "invoice_number" integer NOT NULL,
    "subject" "text" NOT NULL,
    "currency_code" "text" NOT NULL,
    "customer_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "billing_address_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "service_properties" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "document_frozen_at" timestamp with time zone,
    "payment_term_id" "uuid",
    "payment_term_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "due_date_source" "text" DEFAULT 'term'::"text" NOT NULL,
    "issue_date" "date" NOT NULL,
    "due_date" "date" NOT NULL,
    "issued_at" timestamp with time zone,
    "issued_by" "uuid",
    "issue_method" "text",
    "recognized_at" timestamp with time zone,
    "marked_received_at" timestamp with time zone,
    "marked_received_by" "uuid",
    "written_off_at" timestamp with time zone,
    "written_off_by" "uuid",
    "write_off_note" "text",
    "voided_at" timestamp with time zone,
    "voided_by" "uuid",
    "void_reason" "text",
    "void_note" "text",
    "predecessor_invoice_id" "uuid",
    "root_invoice_id" "uuid" NOT NULL,
    "replacement_kind" "text",
    "replaced_at" timestamp with time zone,
    "replaced_by_invoice_id" "uuid",
    "frozen_status_label" "text",
    "discount_name" "text",
    "discount_type" "text",
    "discount_value" bigint,
    "tax_source" "text" DEFAULT 'not_configured'::"text" NOT NULL,
    "tax_name" "text",
    "tax_rate_basis_points" integer DEFAULT 0 NOT NULL,
    "tax_rate_id" "uuid",
    "subtotal_minor" bigint DEFAULT 0 NOT NULL,
    "discount_minor" bigint DEFAULT 0 NOT NULL,
    "tax_minor" bigint DEFAULT 0 NOT NULL,
    "total_minor" bigint DEFAULT 0 NOT NULL,
    "revision" integer DEFAULT 0 NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_effective_receivable" boolean GENERATED ALWAYS AS (((("issued_at" IS NOT NULL) OR ("recognized_at" IS NOT NULL)) AND ("voided_at" IS NULL) AND ("replaced_at" IS NULL) AND ("written_off_at" IS NULL))) STORED,
    "contract_disclaimer" "text",
    "online_partial_payments_allowed" boolean DEFAULT false NOT NULL,
    CONSTRAINT "invoices_billing_address_snapshot_check" CHECK (("jsonb_typeof"("billing_address_snapshot") = 'object'::"text")),
    CONSTRAINT "invoices_contract_disclaimer_check" CHECK ((("contract_disclaimer" IS NULL) OR ("char_length"("contract_disclaimer") <= 5000))),
    CONSTRAINT "invoices_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "invoices_customer_snapshot_check" CHECK (("jsonb_typeof"("customer_snapshot") = 'object'::"text")),
    CONSTRAINT "invoices_discount_check" CHECK (((("discount_type" IS NULL) AND ("discount_value" IS NULL) AND ("discount_name" IS NULL)) OR (("discount_type" = ANY (ARRAY['fixed'::"text", 'percentage'::"text"])) AND (("discount_value" >= 0) AND ("discount_value" <=
CASE
    WHEN ("discount_type" = 'percentage'::"text") THEN (10000)::bigint
    ELSE '9000000000000000000'::bigint
END)) AND ("discount_name" IS NOT NULL)))),
    CONSTRAINT "invoices_discount_minor_check" CHECK ((("discount_minor" >= 0) AND ("discount_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "invoices_discount_name_check" CHECK ((("discount_name" IS NULL) OR (("char_length"(TRIM(BOTH FROM "discount_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "discount_name")) <= 80)))),
    CONSTRAINT "invoices_discount_within_subtotal" CHECK (("discount_minor" <= "subtotal_minor")),
    CONSTRAINT "invoices_due_date_source_check" CHECK (("due_date_source" = ANY (ARRAY['term'::"text", 'custom'::"text"]))),
    CONSTRAINT "invoices_due_date_source_shape" CHECK (((("due_date_source" = 'term'::"text") AND ("payment_term_id" IS NOT NULL)) OR (("due_date_source" = 'custom'::"text") AND ("payment_term_id" IS NULL)))),
    CONSTRAINT "invoices_due_not_before_issue" CHECK (("due_date" >= "issue_date")),
    CONSTRAINT "invoices_frozen_status_label_check" CHECK (("frozen_status_label" = ANY (ARRAY['draft'::"text", 'awaiting_payment'::"text", 'past_due'::"text", 'paid'::"text", 'bad_debt'::"text", 'voided'::"text"]))),
    CONSTRAINT "invoices_frozen_when_real" CHECK ((("document_frozen_at" IS NOT NULL) = (("issued_at" IS NOT NULL) OR ("recognized_at" IS NOT NULL)))),
    CONSTRAINT "invoices_invoice_number_check" CHECK (("invoice_number" >= 1)),
    CONSTRAINT "invoices_issue_facts_complete" CHECK ((("issued_at" IS NULL) = ("issue_method" IS NULL))),
    CONSTRAINT "invoices_issue_method_check" CHECK (("issue_method" = ANY (ARRAY['sent'::"text", 'marked_sent'::"text"]))),
    CONSTRAINT "invoices_not_its_own_predecessor" CHECK ((("predecessor_invoice_id" IS NULL) OR ("predecessor_invoice_id" <> "id"))),
    CONSTRAINT "invoices_payment_term_snapshot_check" CHECK (("jsonb_typeof"("payment_term_snapshot") = 'object'::"text")),
    CONSTRAINT "invoices_replaced_facts_complete" CHECK (((("replaced_at" IS NULL) = ("replaced_by_invoice_id" IS NULL)) AND (("replaced_at" IS NULL) = ("frozen_status_label" IS NULL)))),
    CONSTRAINT "invoices_replacement_kind_check" CHECK (("replacement_kind" = ANY (ARRAY['correction'::"text", 'rebill'::"text"]))),
    CONSTRAINT "invoices_replacement_kind_needs_predecessor" CHECK ((("predecessor_invoice_id" IS NULL) = ("replacement_kind" IS NULL))),
    CONSTRAINT "invoices_revision_check" CHECK (("revision" >= 0)),
    CONSTRAINT "invoices_service_properties_check" CHECK (("jsonb_typeof"("service_properties") = 'array'::"text")),
    CONSTRAINT "invoices_subject_check" CHECK ((("char_length"(TRIM(BOTH FROM "subject")) >= 2) AND ("char_length"(TRIM(BOTH FROM "subject")) <= 160))),
    CONSTRAINT "invoices_subtotal_minor_check" CHECK ((("subtotal_minor" >= 0) AND ("subtotal_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "invoices_tax_check" CHECK (((("tax_rate_basis_points" >= 0) AND ("tax_rate_basis_points" <= 10000)) AND ((("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL)) OR ("tax_name" IS NOT NULL)))),
    CONSTRAINT "invoices_tax_minor_check" CHECK ((("tax_minor" >= 0) AND ("tax_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "invoices_tax_name_check" CHECK ((("tax_name" IS NULL) OR (("char_length"(TRIM(BOTH FROM "tax_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "tax_name")) <= 80)))),
    CONSTRAINT "invoices_tax_source_check" CHECK (("tax_source" = ANY (ARRAY['not_configured'::"text", 'business_default'::"text", 'property_default'::"text", 'saved_rate'::"text", 'no_tax'::"text", 'custom'::"text"]))),
    CONSTRAINT "invoices_tax_source_consistency" CHECK (
CASE "tax_source"
    WHEN 'not_configured'::"text" THEN (("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL) AND ("tax_rate_id" IS NULL))
    WHEN 'no_tax'::"text" THEN (("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL) AND ("tax_rate_id" IS NULL))
    WHEN 'custom'::"text" THEN (("tax_rate_basis_points" > 0) AND ("tax_name" IS NOT NULL) AND ("tax_rate_id" IS NULL))
    WHEN 'saved_rate'::"text" THEN (("tax_rate_basis_points" > 0) AND ("tax_name" IS NOT NULL) AND ("tax_rate_id" IS NOT NULL))
    ELSE ((("tax_rate_basis_points" > 0) AND ("tax_name" IS NOT NULL) AND ("tax_rate_id" IS NOT NULL)) OR (("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL) AND ("tax_rate_id" IS NULL)))
END),
    CONSTRAINT "invoices_total_minor_check" CHECK ((("total_minor" >= 0) AND ("total_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "invoices_void_excludes_closure" CHECK ((("voided_at" IS NULL) OR (("written_off_at" IS NULL) AND ("marked_received_at" IS NULL)))),
    CONSTRAINT "invoices_void_facts_complete" CHECK ((("voided_at" IS NULL) = ("void_reason" IS NULL))),
    CONSTRAINT "invoices_void_note_check" CHECK ((("void_note" IS NULL) OR ("char_length"("void_note") <= 2000))),
    CONSTRAINT "invoices_void_note_needs_void" CHECK ((("void_note" IS NULL) OR ("voided_at" IS NOT NULL))),
    CONSTRAINT "invoices_void_reason_check" CHECK (("void_reason" = ANY (ARRAY['duplicate'::"text", 'created_in_error'::"text", 'client_request'::"text", 'other'::"text"]))),
    CONSTRAINT "invoices_write_off_note_check" CHECK ((("write_off_note" IS NULL) OR ("char_length"("write_off_note") <= 2000))),
    CONSTRAINT "invoices_write_off_note_needs_write_off" CHECK ((("write_off_note" IS NULL) OR ("written_off_at" IS NOT NULL)))
);


ALTER TABLE "public"."invoices" OWNER TO "postgres";


COMMENT ON TABLE "public"."invoices" IS 'The customer''s bill: a frozen snapshot of what is charged, not a view of live work. Members read this table and never write it; every row is created and changed by a checked command function. The six contract statuses are derived from the issue, recognition, closure, void and replacement facts stored here plus the money applied to it, so no status column can drift out of date.';



COMMENT ON COLUMN "public"."invoices"."recognized_at" IS 'When a draft became a settled bill through full payment (contract decision D1). It is not an issue date and creates no delivery or communication fact.';



COMMENT ON COLUMN "public"."invoices"."root_invoice_id" IS 'The first invoice in this correction/rebill chain, set to the invoice''s own id when it starts one. Source claims attach here, which is what stops a replacement from becoming a second way to bill the same work.';



COMMENT ON COLUMN "public"."invoices"."is_effective_receivable" IS 'The one effective-receivable predicate. Balances, payment reminders, collection commands and Client Hub all read this rather than restating the rule, so they cannot disagree about what a client owes.';



COMMENT ON COLUMN "public"."invoices"."contract_disclaimer" IS 'The terms the customer is agreeing to by paying this bill. Plain text the contractor types on the draft. Frozen the moment the invoice is issued (document_frozen_at set) -- update_invoice_contract_disclaimer is the only writer and refuses once that is set, same rule quotes use for their contract_disclaimer.';



CREATE OR REPLACE FUNCTION "private"."apply_invoice_allocation"("invoice_row" "public"."invoices", "target_payment_event_id" "uuid", "target_deposit_event_id" "uuid", "new_amount_minor" bigint, "actor" "uuid", "new_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  allocation_id uuid;
  remaining bigint;
begin
  if new_amount_minor is null or new_amount_minor <= 0 then
    raise exception 'A payment amount must be more than zero.' using errcode = 'check_violation';
  end if;

  remaining := invoice_row.total_minor
    - private.invoice_allocated_minor(invoice_row.organization_id, invoice_row.id);
  if new_amount_minor > remaining then
    raise exception 'That is more than invoice #% still owes.', invoice_row.invoice_number
      using errcode = 'check_violation',
      detail = format('%s remaining, %s offered', remaining, new_amount_minor);
  end if;

  insert into public.invoice_payment_allocations (
    organization_id, invoice_id, invoice_number, client_id, entry_type, amount_minor, currency_code,
    payment_event_id, deposit_event_id, reason, actor_user_id
  ) values (
    invoice_row.organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'applied', new_amount_minor, invoice_row.currency_code,
    target_payment_event_id, target_deposit_event_id, nullif(trim(coalesce(new_reason, '')), ''), actor
  )
  returning id into allocation_id;

  perform private.record_invoice_event(
    invoice_row.organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.payment_applied', actor, invoice_row.revision, new_reason,
    jsonb_build_object(
      'allocation_id', allocation_id,
      'amount_minor', new_amount_minor,
      'source', case when target_deposit_event_id is not null then 'quote_deposit' else 'payment' end
    ),
    true, null
  );

  perform private.recognize_invoice_if_settled(
    invoice_row.organization_id, invoice_row.id, actor
  );

  return allocation_id;
end;
$$;


ALTER FUNCTION "private"."apply_invoice_allocation"("invoice_row" "public"."invoices", "target_payment_event_id" "uuid", "target_deposit_event_id" "uuid", "new_amount_minor" bigint, "actor" "uuid", "new_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_employee_seat_available"("target_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  seat_limit record;
  seats_used integer;
begin
  perform pg_advisory_xact_lock(hashtext('employee_seats:' || target_organization_id::text));

  select *
  into seat_limit
  from public.effective_employee_seat_limit(target_organization_id);

  seats_used := private.employee_seats_used(target_organization_id);

  if not seat_limit.is_unlimited and seats_used >= coalesce(seat_limit.value, 0) then
    raise exception 'No employee seats are available for this organization.'
      using errcode = 'check_violation';
  end if;
end;
$$;


ALTER FUNCTION "private"."assert_employee_seat_available"("target_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."assert_employee_seat_available"("target_organization_id" "uuid") IS 'Advisory-lock-guarded seat check for the future invitation/restoration command primitives (item 3). Not an RPC target -- called only from other SECURITY DEFINER commands, like private.member_has_permission.';



CREATE TABLE IF NOT EXISTS "public"."organization_members" (
    "organization_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "role" "text" DEFAULT 'owner'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "work_phone" "text",
    "job_title" "text",
    "schedule_color" "text",
    "access_revision" integer DEFAULT 1 NOT NULL,
    "profile_revision" integer DEFAULT 1 NOT NULL,
    "status_changed_at" timestamp with time zone,
    "status_changed_by" "uuid",
    "deactivated_at" timestamp with time zone,
    "removed_at" timestamp with time zone,
    "display_name_at_removal" "text",
    "identity_cleanup_state" "text" DEFAULT 'not_required'::"text" NOT NULL,
    "identity_cleanup_error" "text",
    "identity_cleanup_nonce" "uuid",
    "identity_cleanup_lease_expires_at" timestamp with time zone,
    "availability_revision" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "organization_members_availability_revision_check" CHECK (("availability_revision" >= 1)),
    CONSTRAINT "organization_members_display_name_at_removal_check" CHECK ((("display_name_at_removal" IS NULL) OR (("char_length"("btrim"("display_name_at_removal")) >= 1) AND ("char_length"("btrim"("display_name_at_removal")) <= 160)))),
    CONSTRAINT "organization_members_identity_cleanup_lease_pair_check" CHECK (((("identity_cleanup_nonce" IS NULL) AND ("identity_cleanup_lease_expires_at" IS NULL)) OR (("identity_cleanup_nonce" IS NOT NULL) AND ("identity_cleanup_lease_expires_at" IS NOT NULL)))),
    CONSTRAINT "organization_members_identity_cleanup_state_check" CHECK (("identity_cleanup_state" = ANY (ARRAY['not_required'::"text", 'required'::"text", 'ban_applied'::"text", 'email_released'::"text", 'done'::"text"]))),
    CONSTRAINT "organization_members_job_title_check" CHECK ((("job_title" IS NULL) OR (("char_length"("btrim"("job_title")) >= 1) AND ("char_length"("btrim"("job_title")) <= 80)))),
    CONSTRAINT "organization_members_removed_keeps_a_name_check" CHECK ((("status" <> 'removed'::"text") OR ("display_name_at_removal" IS NOT NULL))),
    CONSTRAINT "organization_members_role_check" CHECK (("role" = ANY (ARRAY['owner'::"text", 'admin'::"text", 'office'::"text", 'sales'::"text", 'field'::"text", 'finance'::"text"]))),
    CONSTRAINT "organization_members_schedule_color_check" CHECK ((("schedule_color" IS NULL) OR ("schedule_color" ~ '^#[0-9A-Fa-f]{6}$'::"text"))),
    CONSTRAINT "organization_members_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'active'::"text", 'deactivated'::"text", 'removed'::"text"]))),
    CONSTRAINT "organization_members_work_phone_check" CHECK ((("work_phone" IS NULL) OR (("char_length"("btrim"("work_phone")) >= 1) AND ("char_length"("btrim"("work_phone")) <= 40))))
);


ALTER TABLE "public"."organization_members" OWNER TO "postgres";


COMMENT ON COLUMN "public"."organization_members"."status" IS 'pending (invited, no access), active, deactivated (access denied, seat freed), removed (tombstone).';



COMMENT ON COLUMN "public"."organization_members"."access_revision" IS 'Bumped by role and permission saves so a stale editor conflicts instead of overwriting.';



COMMENT ON COLUMN "public"."organization_members"."profile_revision" IS 'Bumped by member detail saves, independently of access_revision.';



COMMENT ON COLUMN "public"."organization_members"."display_name_at_removal" IS 'Name snapshot taken at permanent removal so attribution never depends on an Auth record.';



COMMENT ON COLUMN "public"."organization_members"."identity_cleanup_state" IS 'Ledger for the Auth steps that cannot share this transaction. Advanced only by the 3B/3E worker.';



COMMENT ON COLUMN "public"."organization_members"."identity_cleanup_nonce" IS 'Short worker lease. It coordinates the Auth ban and email release without holding a database transaction across the network call.';



COMMENT ON COLUMN "public"."organization_members"."availability_revision" IS 'Bumped by every accepted availability save. The Availability section sends the value it read; a stale one conflicts instead of overwriting an edit the screen never saw.';



CREATE OR REPLACE FUNCTION "private"."assert_membership_is_editable"("membership" "public"."organization_members") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if membership.status not in ('pending', 'active') then
    raise exception 'Restore this person before changing their access.' using errcode = 'check_violation';
  end if;
end;
$$;


ALTER FUNCTION "private"."assert_membership_is_editable"("membership" "public"."organization_members") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_scope_is_supported"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  supported_model text;
begin
  if new.access_scope = 'all' then
    return new;
  end if;

  select scope_model into supported_model
  from public.permissions
  where key = new.permission_key;

  if supported_model is distinct from 'assigned_or_all' then
    raise exception
      'Permission % does not support an assigned scope, because no domain enforces it yet.',
      new.permission_key
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."assert_scope_is_supported"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_single_active_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  subject_organization_id uuid;
  active_owner_count integer;
  present_member_count integer;
begin
  subject_organization_id := coalesce(new.organization_id, old.organization_id);
  if subject_organization_id is null then
    return null;
  end if;

  select
    count(*) filter (where membership.role = 'owner' and membership.status = 'active'),
    count(*) filter (where membership.status <> 'removed')
  into active_owner_count, present_member_count
  from public.organization_members as membership
  where membership.organization_id = subject_organization_id;

  if present_member_count > 0 and active_owner_count <> 1 then
    raise exception
      'An organization with team members must have exactly one active owner, but % were found.',
      active_owner_count
      using errcode = 'check_violation';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."assert_single_active_owner"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_task_limit"("target_opportunity_id" "uuid", "target_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  existing integer;
begin
  select count(*)
  into existing
  from public.tasks as task
  where task.opportunity_id = target_opportunity_id
    and task.status = target_status;

  if existing >= 5 then
    raise exception '%',
      case target_status
        when 'open' then 'This opportunity already has five open tasks. Finish one first.'
        else 'This opportunity already has five completed tasks. Delete one first.'
      end
      using errcode = 'program_limit_exceeded';
  end if;
end;
$$;


ALTER FUNCTION "private"."assert_task_limit"("target_opportunity_id" "uuid", "target_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_team_invitation_overrides"("target_role" "text", "target_overrides" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if target_overrides is null or jsonb_typeof(target_overrides) <> 'array' then
    raise exception 'The permission adjustments must be a list.' using errcode = 'check_violation';
  end if;

  if target_role = 'admin' and jsonb_array_length(target_overrides) <> 0 then
    raise exception 'Administrator invitations use standard administrator access.'
      using errcode = 'check_violation';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(target_overrides) as entry(item)
    where jsonb_typeof(entry.item) <> 'object'
      or (entry.item ->> 'permission_key') is null
      or (entry.item ->> 'override_state') not in ('grant', 'deny')
      or coalesce(entry.item ->> 'access_scope', 'all') <> 'all'
      or not exists (
        select 1 from public.permissions as permission
        where permission.key = entry.item ->> 'permission_key'
      )
  ) then
    raise exception 'One of those permission adjustments is not available.'
      using errcode = 'check_violation';
  end if;

  if exists (
    select entry.item ->> 'permission_key'
    from jsonb_array_elements(target_overrides) as entry(item)
    group by entry.item ->> 'permission_key'
    having count(*) > 1
  ) then
    raise exception 'The same permission was adjusted twice.' using errcode = 'check_violation';
  end if;
end;
$$;


ALTER FUNCTION "private"."assert_team_invitation_overrides"("target_role" "text", "target_overrides" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_website_chat_widget_available"("target_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  widget_limit record;
  widgets_used integer;
begin
  perform pg_advisory_xact_lock(hashtext('website_chat_widgets:' || target_organization_id::text));

  select * into widget_limit
  from public.effective_website_chat_widgets_limit(target_organization_id);

  widgets_used := private.website_chat_widgets_used(target_organization_id);

  if not widget_limit.is_unlimited and widgets_used >= coalesce(widget_limit.value, 0) then
    raise exception 'No Website Chat widgets are available for this organization.'
      using errcode = 'check_violation';
  end if;
end;
$$;


ALTER FUNCTION "private"."assert_website_chat_widget_available"("target_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."assert_website_chat_widget_available"("target_organization_id" "uuid") IS 'Advisory-lock-guarded widget-cap check. Not an RPC target -- called only from the commands below.';



CREATE OR REPLACE FUNCTION "private"."attach_communication_outbound_files"("target_organization_id" "uuid", "target_delivery_intent_id" "uuid", "target_attachments" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  total_bytes bigint;
  file_count integer;
begin
  if target_attachments is null or jsonb_array_length(target_attachments) = 0 then
    return;
  end if;

  select count(*), coalesce(sum((item ->> 'byte_size')::bigint), 0)
  into file_count, total_bytes
  from jsonb_array_elements(target_attachments) as item;

  if file_count > 10 then
    raise exception 'Attach at most 10 files to one email.' using errcode = 'check_violation';
  end if;
  if total_bytes > 20 * 1024 * 1024 then
    raise exception 'Attachments must total 20 MB or less.' using errcode = 'check_violation';
  end if;

  -- Defense in depth behind the API's own prefix check: a key issued for one organization can never be
  -- committed against another, matching how set_organization_logo guards its own prefix.
  if exists (
    select 1 from jsonb_array_elements(target_attachments) as item
    where item ->> 'object_key' not like target_organization_id::text || '/outbound-email-attachments/%'
  ) then
    raise exception 'That file does not belong to this business.' using errcode = 'check_violation';
  end if;

  insert into public.communication_outbound_attachments (
    organization_id, delivery_intent_id, file_name, mime_type, byte_size, object_key
  )
  select
    target_organization_id,
    target_delivery_intent_id,
    item ->> 'file_name',
    item ->> 'mime_type',
    (item ->> 'byte_size')::bigint,
    item ->> 'object_key'
  from jsonb_array_elements(target_attachments) as item
  on conflict (delivery_intent_id, object_key) do nothing;
end;
$$;


ALTER FUNCTION "private"."attach_communication_outbound_files"("target_organization_id" "uuid", "target_delivery_intent_id" "uuid", "target_attachments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."authorize_member_availability_command"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor_role text;
  target_membership public.organization_members;
begin
  if actor_user_id is null or target_user_id is null then
    raise exception 'An availability change needs both a person acting and a person to act on.'
      using errcode = 'check_violation';
  end if;

  select membership.role into actor_role
  from public.organization_members as membership
  where membership.organization_id = target_organization_id
    and membership.user_id = actor_user_id
    and membership.status = 'active';

  if actor_role is null then
    raise exception 'Only an active member of this organization can do that.'
      using errcode = 'check_violation';
  end if;

  if actor_user_id <> target_user_id and actor_role not in ('owner', 'admin') then
    raise exception 'Only an owner or administrator can change someone else''s availability.'
      using errcode = 'check_violation';
  end if;

  -- Locked with the authority check, so no window exists between "allowed" and "changed".
  select * into target_membership
  from public.organization_members as membership
  where membership.organization_id = target_organization_id
    and membership.user_id = target_user_id
  for update;

  if not found then
    raise exception 'That team member was not found.' using errcode = 'no_data_found';
  end if;

  perform private.assert_membership_is_editable(target_membership);

  return target_membership;
end;
$$;


ALTER FUNCTION "private"."authorize_member_availability_command"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."authorize_member_availability_command"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") IS 'The authority every availability command shares: the actor must be an active member, and may act on themselves or -- as an owner or administrator -- on anybody. Returns the target membership, locked.';



CREATE OR REPLACE FUNCTION "private"."authorize_team_member_command"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "owner_actor_required" boolean DEFAULT false) RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor_role text;
  target_membership public.organization_members;
begin
  if actor_user_id is null or target_user_id is null then
    raise exception 'A team change needs both a person acting and a person to act on.'
      using errcode = 'check_violation';
  end if;

  if actor_user_id = target_user_id then
    raise exception 'You cannot change your own access.' using errcode = 'check_violation';
  end if;

  select membership.role into actor_role
  from public.organization_members as membership
  where membership.organization_id = target_organization_id
    and membership.user_id = actor_user_id
    and membership.status = 'active';

  if actor_role is null or actor_role not in ('owner', 'admin') then
    raise exception 'Only an owner or administrator can manage the team.' using errcode = 'check_violation';
  end if;

  if owner_actor_required and actor_role <> 'owner' then
    raise exception 'Only the owner can do that.' using errcode = 'check_violation';
  end if;

  -- Locked here rather than in a second helper: every caller writes, and taking the lock together with the
  -- authority check means no window exists between "allowed" and "changed".
  select * into target_membership
  from public.organization_members as membership
  where membership.organization_id = target_organization_id
    and membership.user_id = target_user_id
  for update;

  if not found then
    raise exception 'That team member was not found.' using errcode = 'no_data_found';
  end if;

  -- The owner is never a target. Their role changes through item 5's ownership transfer and nothing else.
  if target_membership.role = 'owner' then
    raise exception 'The owner''s access changes by handing over ownership, not here.'
      using errcode = 'check_violation';
  end if;

  if target_membership.role = 'admin' and actor_role <> 'owner' then
    raise exception 'Only the owner can manage an administrator.' using errcode = 'check_violation';
  end if;

  return target_membership;
end;
$$;


ALTER FUNCTION "private"."authorize_team_member_command"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "owner_actor_required" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."authorize_team_member_command"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "owner_actor_required" boolean) IS 'The authority every team member command shares: nobody acts on themselves, the actor must be an active owner or administrator, the owner is never a target, and only the owner may manage an administrator. Returns the target membership row, locked for the rest of the transaction.';



CREATE OR REPLACE FUNCTION "private"."automation_conditions_outcome"("p_definition" "jsonb", "p_organization_id" "uuid", "p_quote_status" "text", "p_payload" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  condition_entry jsonb;
  condition_key text;
begin
  for condition_entry in
    select value from jsonb_array_elements(coalesce(p_definition -> 'conditions', '[]'::jsonb))
  loop
    condition_key := condition_entry ->> 'key';

    if condition_key = 'quote.current_status' then
      if p_quote_status is null or not exists (
        select 1
        from jsonb_array_elements_text(coalesce(condition_entry -> 'config' -> 'statuses', '[]'::jsonb)) as allowed(status)
        where allowed.status = p_quote_status
      ) then
        return 'condition_failed';
      end if;

    elsif condition_key = 'quote.recipient_attached' then
      if not exists (
        select 1
        from public.quote_recipients as r
        where r.organization_id = p_organization_id
          and r.id = (p_payload ->> 'quote_recipient_id')::uuid
      ) or not exists (
        select 1
        from public.client_contact_methods as m
        where m.organization_id = p_organization_id
          and m.id = (p_payload ->> 'client_contact_method_id')::uuid
          and m.kind = 'email'
      ) then
        return 'condition_failed';
      end if;

    else
      return 'condition_unavailable';
    end if;
  end loop;

  return 'pass';
end;
$$;


ALTER FUNCTION "private"."automation_conditions_outcome"("p_definition" "jsonb", "p_organization_id" "uuid", "p_quote_status" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."automation_enrollments_set_paused_reason"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
begin
  if new.state = 'paused' and old.state is distinct from 'paused' then
    new.paused_reason := case
      when new.customer_reply_after is distinct from old.customer_reply_after then 'customer_reply'
      else 'staff'
    end;
  elsif new.state <> 'paused' then
    new.paused_reason := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."automation_enrollments_set_paused_reason"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."automation_inquiry_client_id"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", OUT "subject_found" boolean, OUT "client_id" "uuid") RETURNS "record"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
begin
  subject_found := false;
  if p_subject_type = 'form_submission' then
    select true, nullif(s.result ->> 'client_id', '')::uuid into subject_found, client_id
    from private.form_submissions as s
    where s.organization_id = p_organization_id and s.id = p_subject_id;
  elsif p_subject_type = 'website_chat_session' then
    select true, s.client_id into subject_found, client_id
    from public.website_chat_sessions as s
    where s.organization_id = p_organization_id and s.id = p_subject_id;
  end if;
  subject_found := coalesce(subject_found, false);
end;
$$;


ALTER FUNCTION "private"."automation_inquiry_client_id"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", OUT "subject_found" boolean, OUT "client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."automation_inquiry_customer_reply_at"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_after" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  subject record;
  latest timestamptz;
  candidate timestamptz;
begin
  if p_after is null then
    return null;
  end if;

  select * into subject from private.automation_inquiry_client_id(p_organization_id, p_subject_type, p_subject_id);
  if not subject.subject_found then
    return null;
  end if;

  if p_subject_type = 'website_chat_session' then
    select max(m.created_at) into latest
    from public.website_chat_messages as m
    where m.session_id = p_subject_id and m.organization_id = p_organization_id
      and m.sender_type = 'visitor' and m.created_at > p_after;
  end if;

  if subject.client_id is not null then
    select max(m.created_at) into candidate
    from public.website_chat_messages as m
    where m.organization_id = p_organization_id and m.client_id = subject.client_id
      and m.sender_type = 'visitor' and m.created_at > p_after;
    latest := greatest(latest, candidate);

    select max(m.created_at) into candidate
    from public.communication_inbound_messages as m
    where m.organization_id = p_organization_id and m.client_id = subject.client_id
      and m.created_at > p_after and m.message_kind = 'reply' and m.review_status = 'accepted'
      and not m.automation_suppressed;
    latest := greatest(latest, candidate);
  end if;

  return latest;
end;
$$;


ALTER FUNCTION "private"."automation_inquiry_customer_reply_at"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_after" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."automation_inquiry_customer_reply_at"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_after" timestamp with time zone) IS 'The newest customer chat, email or text reply to a website inquiry created after p_after, or null. Null p_after (nothing sent to the customer yet) is always null.';



CREATE OR REPLACE FUNCTION "private"."automation_inquiry_stop_outcome"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_since" timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  subject record;
begin
  select * into subject from private.automation_inquiry_client_id(p_organization_id, p_subject_type, p_subject_id);
  if not subject.subject_found then
    return 'inquiry_not_found';
  end if;

  if p_subject_type = 'website_chat_session' and exists (
    select 1 from public.website_chat_messages as m
    where m.session_id = p_subject_id and m.organization_id = p_organization_id
      and m.sender_type = 'staff' and m.delivery_state = 'sent' and m.created_at >= p_since
  ) then
    return 'staff_replied';
  end if;

  if subject.client_id is not null and (
    exists (
      select 1 from public.website_chat_messages as m
      where m.organization_id = p_organization_id and m.client_id = subject.client_id
        and m.sender_type = 'staff' and m.delivery_state = 'sent' and m.created_at >= p_since
    )
    or exists (
      select 1 from public.communication_delivery_intents as i
      where i.organization_id = p_organization_id and i.client_id = subject.client_id
        and i.created_at >= p_since and i.send_kind = 'manual'
        and i.delivery_outcome in ('delivered', 'sms_delivered')
    )
  ) then
    return 'staff_replied';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."automation_inquiry_stop_outcome"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_since" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."automation_inquiry_stop_outcome"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_since" timestamp with time zone) IS 'Null while a website-inquiry enrollment may continue, else why it stops: inquiry_not_found, or staff_replied (a delivered staff chat message, email or text to that inquiry since p_since). Used by the worker transition and, from Stage 5, by the customer-message send.';



CREATE OR REPLACE FUNCTION "private"."automation_quote_stop_outcome"("p_organization_id" "uuid", "p_quote_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes%rowtype;
  wants_follow_ups boolean;
begin
  select * into quote_row
  from public.quotes
  where organization_id = p_organization_id and id = p_quote_id;

  if not found or quote_row.archived_at is not null then
    return 'quote_not_sendable';
  end if;

  if quote_row.status <> 'awaiting_response' then
    return 'quote_not_awaiting_response';
  end if;

  select p.quote_follow_ups into wants_follow_ups
  from public.client_communication_preferences as p
  where p.organization_id = p_organization_id and p.client_id = quote_row.client_id;

  if not coalesce(wants_follow_ups, true) then
    return 'follow_ups_declined';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."automation_quote_stop_outcome"("p_organization_id" "uuid", "p_quote_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."automation_quote_stop_outcome"("p_organization_id" "uuid", "p_quote_id" "uuid") IS 'Null when a quote follow-up may still run, or the plain reason it may not: the quote is gone/archived, no longer awaiting a response, or the client turned quote follow-ups off. Used by both the worker transition and the send.';



