    "events_deleted" integer DEFAULT 0 NOT NULL,
    "event_matches_deleted" integer DEFAULT 0 NOT NULL,
    "draft_receipts_deleted" integer DEFAULT 0 NOT NULL,
    "enrollment_receipts_deleted" integer DEFAULT 0 NOT NULL,
    "hit_cap" boolean DEFAULT false NOT NULL
);


ALTER TABLE "private"."automation_retention_runs" OWNER TO "postgres";


COMMENT ON TABLE "private"."automation_retention_runs" IS 'One row per automation retention sweep: what each category deleted and whether the run hit its batch cap. Bounded by the nightly cadence; not itself swept.';



CREATE OR REPLACE FUNCTION "private"."automation_retention_sweep"("p_batch" integer DEFAULT 2000, "p_max_batches" integer DEFAULT 25) RETURNS "private"."automation_retention_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  c_events_days constant integer := 180;
  c_work_days constant integer := 90;
  c_enrollment_days constant integer := 180;
  c_receipt_days constant integer := 30;

  v_now timestamptz := now();
  v_run_id uuid;
  v_result private.automation_retention_runs;
  v_deleted integer;
  v_compacted integer;
  v_matches integer;
  v_loops integer;
  v_last_full boolean;

  v_wi integer := 0;
  v_en integer := 0;
  v_ev integer := 0;
  v_em integer := 0;
  v_dr integer := 0;
  v_er integer := 0;
  v_hit_cap boolean := false;
begin
  if p_batch < 1 or p_batch > 10000 then
    raise exception 'The retention batch size is outside its safe bounds.' using errcode = 'check_violation';
  end if;
  if p_max_batches < 1 or p_max_batches > 500 then
    raise exception 'The retention batch cap is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  set local statement_timeout = '10min';
  set local lock_timeout = '5s';

  insert into private.automation_retention_runs default values returning id into v_run_id;

  v_loops := 0;
  loop
    delete from private.automation_work_items w
    using (
      select id
      from private.automation_work_items
      where state in ('done', 'cancelled')
        and updated_at < v_now - make_interval(days => c_work_days)
      order by updated_at, id
      limit p_batch
      for update skip locked
    ) d
    where w.id = d.id;
    get diagnostics v_deleted = row_count;
    v_wi := v_wi + v_deleted;
    v_loops := v_loops + 1;
    v_last_full := v_deleted >= p_batch;
    exit when not v_last_full or v_loops >= p_max_batches;
  end loop;
  v_hit_cap := v_hit_cap or (v_last_full and v_loops >= p_max_batches);

  v_loops := 0;
  loop
    with victims as (
      select id
      from private.automation_enrollments
      where state in ('completed', 'stopped', 'failed')
        and compacted_at is null
        and updated_at < v_now - make_interval(days => c_enrollment_days)
      order by updated_at, id
      limit p_batch
      for update skip locked
    ),
    wiped_items as (
      delete from private.automation_work_items w
      using victims
      where w.enrollment_id = victims.id
      returning 1
    ),
    compacted as (
      update private.automation_enrollments e
      set context = '{}'::jsonb,
        enrolled_by = null,
        paused_work_due_at = null,
        trigger_event_id = null,
        compacted_at = v_now
      from victims
      where e.id = victims.id
      returning 1
    )
    select (select count(*) from compacted), (select count(*) from wiped_items)
    into v_compacted, v_deleted;
    v_en := v_en + v_compacted;
    v_wi := v_wi + v_deleted;
    v_loops := v_loops + 1;
    v_last_full := v_compacted >= p_batch;
    exit when not v_last_full or v_loops >= p_max_batches;
  end loop;
  v_hit_cap := v_hit_cap or (v_last_full and v_loops >= p_max_batches);

  v_loops := 0;
  loop
    with victims as (
      select ev.id
      from private.automation_events ev
      where ev.processed_at is not null
        and ev.processed_at < v_now - make_interval(days => c_events_days)
        and not exists (
          select 1 from private.automation_enrollments en where en.trigger_event_id = ev.id
        )
      order by ev.processed_at, ev.id
      limit p_batch
      for update skip locked
    ),
    counted_matches as (
      select count(*)::integer as n
      from private.automation_event_matches m
      where m.event_id in (select id from victims)
    ),
    deleted_events as (
      delete from private.automation_events e
      using victims
      where e.id = victims.id
      returning 1
    )
    select (select count(*) from deleted_events), (select n from counted_matches)
    into v_deleted, v_matches;
    v_ev := v_ev + v_deleted;
    v_em := v_em + v_matches;
    v_loops := v_loops + 1;
    v_last_full := v_deleted >= p_batch;
    exit when not v_last_full or v_loops >= p_max_batches;
  end loop;
  v_hit_cap := v_hit_cap or (v_last_full and v_loops >= p_max_batches);

  v_loops := 0;
  loop
    delete from public.automation_draft_command_receipts r
    using (
      select id from public.automation_draft_command_receipts
      where created_at < v_now - make_interval(days => c_receipt_days)
      order by created_at, id
      limit p_batch
      for update skip locked
    ) d
    where r.id = d.id;
    get diagnostics v_deleted = row_count;
    v_dr := v_dr + v_deleted;
    v_loops := v_loops + 1;
    v_last_full := v_deleted >= p_batch;
    exit when not v_last_full or v_loops >= p_max_batches;
  end loop;
  v_hit_cap := v_hit_cap or (v_last_full and v_loops >= p_max_batches);

  v_loops := 0;
  loop
    delete from public.automation_enrollment_command_receipts r
    using (
      select id from public.automation_enrollment_command_receipts
      where created_at < v_now - make_interval(days => c_receipt_days)
      order by created_at, id
      limit p_batch
      for update skip locked
    ) d
    where r.id = d.id;
    get diagnostics v_deleted = row_count;
    v_er := v_er + v_deleted;
    v_loops := v_loops + 1;
    v_last_full := v_deleted >= p_batch;
    exit when not v_last_full or v_loops >= p_max_batches;
  end loop;
  v_hit_cap := v_hit_cap or (v_last_full and v_loops >= p_max_batches);

  update private.automation_retention_runs
  set finished_at = now(),
    work_items_deleted = v_wi,
    enrollments_compacted = v_en,
    events_deleted = v_ev,
    event_matches_deleted = v_em,
    draft_receipts_deleted = v_dr,
    enrollment_receipts_deleted = v_er,
    hit_cap = v_hit_cap
  where id = v_run_id;

  select * into v_result from private.automation_retention_runs where id = v_run_id;
  return v_result;
end;
$$;


ALTER FUNCTION "private"."automation_retention_sweep"("p_batch" integer, "p_max_batches" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."automation_retention_sweep"("p_batch" integer, "p_max_batches" integer) IS 'Deletes aged automation rows in id-ordered batches: settled work items (90d), processed events + matches (180d), terminal enrollments compacted to no-restart tombstones (180d), and idempotency receipts (30d). Restartable, bounded, and safe to re-run. Internal.';



CREATE OR REPLACE FUNCTION "private"."automation_retry_delay"("p_attempts" integer) RETURNS interval
    LANGUAGE "sql"
    SET "search_path" TO 'pg_catalog'
    AS $$
  select make_interval(
    secs => least(3600, 30 * power(2, greatest(coalesce(p_attempts, 1), 1) - 1)) * (0.5 + random() * 0.5)
  );
$$;


ALTER FUNCTION "private"."automation_retry_delay"("p_attempts" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."automation_retry_delay"("p_attempts" integer) IS 'Exponential backoff with full jitter: 30s doubling to a one-hour ceiling, then randomised across half the window so a burst of simultaneous failures does not retry in lockstep.';



CREATE OR REPLACE FUNCTION "private"."begin_invoice_command"("target_organization_id" "uuid", "new_action" "text", "new_idempotency_key" "text", "new_request_hash" "text", "actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  claimed uuid;
  existing private.invoice_command_receipts;
begin
  if char_length(trim(coalesce(new_idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(new_request_hash, ''))) < 1 then
    raise exception 'A request fingerprint is required.' using errcode = 'check_violation';
  end if;

  insert into private.invoice_command_receipts
    (organization_id, action, idempotency_key, request_hash, actor_id)
  values (target_organization_id, new_action, new_idempotency_key, new_request_hash, actor)
  on conflict (organization_id, action, idempotency_key) do nothing
  returning id into claimed;

  if claimed is not null then
    return null;
  end if;

  select * into existing
  from private.invoice_command_receipts
  where organization_id = target_organization_id
    and action = new_action
    and idempotency_key = new_idempotency_key;

  if existing.request_hash is distinct from new_request_hash then
    raise exception 'That action was already started with different details.' using errcode = 'P0409';
  end if;

  return coalesce(existing.result, '{}'::jsonb) || jsonb_build_object('applied', false);
end;
$$;


ALTER FUNCTION "private"."begin_invoice_command"("target_organization_id" "uuid", "new_action" "text", "new_idempotency_key" "text", "new_request_hash" "text", "actor" "uuid") OWNER TO "postgres";


