CREATE OR REPLACE FUNCTION "private"."calculate_invoice"("target_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  invoice_row public.invoices;
  line_subtotal numeric := 0;
  non_taxable_subtotal numeric := 0;
  taxable_subtotal numeric := 0;
  discount_amount numeric := 0;
  non_taxable_discount numeric := 0;
  taxable_discount numeric := 0;
  tax_amount numeric := 0;
  total_amount numeric := 0;
  line_count integer := 0;
  line_result jsonb := '[]'::jsonb;
begin
  select * into invoice_row from public.invoices where id = target_invoice_id;
  if invoice_row.id is null then
    raise exception 'That invoice was not found.' using errcode = 'no_data_found';
  end if;

  select coalesce(sum(line_total_minor), 0),
         coalesce(sum(line_total_minor) filter (where not is_taxable), 0),
         coalesce(sum(line_total_minor) filter (where is_taxable), 0),
         count(*)
  into line_subtotal, non_taxable_subtotal, taxable_subtotal, line_count
  from public.invoice_lines
  where organization_id = invoice_row.organization_id
    and invoice_id = invoice_row.id
    and line_kind = 'priced';

  if line_subtotal > 1000000000000 then
    raise exception 'That invoice value is too large.' using errcode = 'numeric_value_out_of_range';
  end if;

  if invoice_row.discount_type = 'fixed' then
    discount_amount := least(invoice_row.discount_value, line_subtotal);
  elsif invoice_row.discount_type = 'percentage' then
    discount_amount := round(line_subtotal * invoice_row.discount_value / 10000);
  end if;
  non_taxable_discount := least(discount_amount, non_taxable_subtotal);
  taxable_discount := discount_amount - non_taxable_discount;

  with priced as (
    select id, position, is_taxable, line_total_minor
    from public.invoice_lines
    where organization_id = invoice_row.organization_id
      and invoice_id = invoice_row.id
      and line_kind = 'priced'
  ),
  shared as (
    select priced.*,
      case when priced.is_taxable then taxable_subtotal else non_taxable_subtotal end as group_total,
      case when priced.is_taxable then taxable_discount else non_taxable_discount end as group_discount,
      row_number() over (partition by priced.is_taxable order by priced.position, priced.id) as group_rank
    from priced
  ),
  rounded as (
    select shared.*,
      case when shared.group_total = 0 or shared.group_discount = 0 then 0
        else floor(shared.group_discount * shared.line_total_minor / shared.group_total)
      end as raw_allocation
    from shared
  ),
  spread as (
    select rounded.*,
      rounded.group_discount - sum(rounded.raw_allocation) over (partition by rounded.is_taxable)
        as group_remainder
    from rounded
  ),
  allocated as (
    select spread.id, spread.position, spread.is_taxable, spread.line_total_minor,
      spread.raw_allocation + case when spread.group_rank <= spread.group_remainder then 1 else 0 end
        as line_discount
    from spread
  ),
  taxed as (
    select allocated.*,
      allocated.line_total_minor - allocated.line_discount as net_amount,
      case when allocated.is_taxable
        then round((allocated.line_total_minor - allocated.line_discount)
          * invoice_row.tax_rate_basis_points / 10000)
        else 0
      end as line_tax
    from allocated
  )
  select coalesce(sum(line_tax), 0),
    coalesce(jsonb_agg(jsonb_build_object(
      'line_id', id,
      'gross_minor', line_total_minor,
      'discount_minor', line_discount::bigint,
      'net_minor', net_amount::bigint,
      'tax_minor', line_tax::bigint,
      'total_minor', (net_amount + line_tax)::bigint
    ) order by position, id), '[]'::jsonb)
  into tax_amount, line_result
  from taxed;

  total_amount := line_subtotal - discount_amount + tax_amount;
  if total_amount > 1000000000000 then
    raise exception 'That invoice total is too large.' using errcode = 'numeric_value_out_of_range';
  end if;

  return jsonb_build_object(
    'invoice_id', invoice_row.id,
    'line_count', line_count,
    'subtotal_minor', line_subtotal::bigint,
    'discount_minor', discount_amount::bigint,
    'tax_minor', tax_amount::bigint,
    'total_minor', total_amount::bigint,
    'lines', line_result
  );
end;
$$;


ALTER FUNCTION "private"."calculate_invoice"("target_invoice_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."calculate_invoice"("target_invoice_id" "uuid") IS 'The only invoice arithmetic in the product, and the same rules as private.calculate_job: proportional discount allocation with largest-remainder spreading, then per-line exclusive tax. No route, screen or document recomputes this.';



CREATE OR REPLACE FUNCTION "private"."calculate_job"("target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  job_row public.jobs;
  line_subtotal numeric := 0;
  line_cost numeric := 0;
  non_taxable_subtotal numeric := 0;
  taxable_subtotal numeric := 0;
  discount_amount numeric := 0;
  non_taxable_discount numeric := 0;
  taxable_discount numeric := 0;
  tax_amount numeric := 0;
  total_amount numeric := 0;
  revenue numeric := 0;
  profit numeric := 0;
  margin_bps numeric;
  line_count integer := 0;
  line_result jsonb := '[]'::jsonb;
begin
  select * into job_row from public.jobs where id = target_job_id;
  if job_row.id is null then
    raise exception 'That job was not found.' using errcode = 'no_data_found';
  end if;

  select coalesce(sum(line_total_minor), 0), coalesce(sum(line_cost_total_minor), 0),
         coalesce(sum(line_total_minor) filter (where not is_taxable), 0),
         coalesce(sum(line_total_minor) filter (where is_taxable), 0), count(*)
  into line_subtotal, line_cost, non_taxable_subtotal, taxable_subtotal, line_count
  from public.job_line_items
  where organization_id = job_row.organization_id
    and job_id = job_row.id
    and line_kind = 'priced';

  if line_subtotal > 1000000000000 or line_cost > 1000000000000 then
    raise exception 'That job value is too large.' using errcode = 'numeric_value_out_of_range';
  end if;

  if job_row.discount_type = 'fixed' then
    discount_amount := least(job_row.discount_value, line_subtotal);
  elsif job_row.discount_type = 'percentage' then
    discount_amount := round(line_subtotal * job_row.discount_value / 10000);
  end if;
  non_taxable_discount := least(discount_amount, non_taxable_subtotal);
  taxable_discount := discount_amount - non_taxable_discount;

  with priced as (
    select id, position, is_taxable, line_total_minor
    from public.job_line_items
    where organization_id = job_row.organization_id
      and job_id = job_row.id
      and line_kind = 'priced'
  ),
  shared as (
    select priced.*,
      case when priced.is_taxable then taxable_subtotal else non_taxable_subtotal end as group_total,
      case when priced.is_taxable then taxable_discount else non_taxable_discount end as group_discount,
      row_number() over (partition by priced.is_taxable order by priced.position, priced.id) as group_rank
    from priced
  ),
  rounded as (
    select shared.*,
      case when shared.group_total = 0 or shared.group_discount = 0 then 0
        else floor(shared.group_discount * shared.line_total_minor / shared.group_total)
      end as raw_allocation
    from shared
  ),
  spread as (
    select rounded.*,
      rounded.group_discount - sum(rounded.raw_allocation) over (partition by rounded.is_taxable)
        as group_remainder
    from rounded
  ),
  allocated as (
    select spread.id, spread.position, spread.is_taxable, spread.line_total_minor,
      spread.raw_allocation + case when spread.group_rank <= spread.group_remainder then 1 else 0 end
        as line_discount
    from spread
  ),
  taxed as (
    select allocated.*,
      allocated.line_total_minor - allocated.line_discount as net_amount,
      case when allocated.is_taxable
        then round((allocated.line_total_minor - allocated.line_discount)
          * job_row.tax_rate_basis_points / 10000)
        else 0
      end as line_tax
    from allocated
  )
  select coalesce(sum(line_tax), 0),
    coalesce(jsonb_agg(jsonb_build_object(
      'line_id', id,
      'gross_minor', line_total_minor,
      'discount_minor', line_discount::bigint,
      'net_minor', net_amount::bigint,
      'tax_minor', line_tax::bigint,
      'total_minor', (net_amount + line_tax)::bigint
    ) order by position, id), '[]'::jsonb)
  into tax_amount, line_result
  from taxed;

  total_amount := line_subtotal - discount_amount + tax_amount;
  if total_amount > 1000000000000 then
    raise exception 'That job total is too large.' using errcode = 'numeric_value_out_of_range';
  end if;

  revenue := line_subtotal - discount_amount;
  profit := revenue - line_cost;
  margin_bps := case when revenue = 0 then null else round(profit * 10000 / revenue) end;

  return jsonb_build_object(
    'job_id', job_row.id,
    'line_count', line_count,
    'subtotal_minor', line_subtotal::bigint,
    'discount_minor', discount_amount::bigint,
    'tax_minor', tax_amount::bigint,
    'total_minor', total_amount::bigint,
    'cost_minor', line_cost::bigint,
    'profit_minor', profit::bigint,
    'margin_basis_points', margin_bps::bigint,
    'lines', line_result
  );
end;
$$;


ALTER FUNCTION "private"."calculate_job"("target_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."calculate_quote_version"("target_version_id" "uuid", "selected_addon_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  version_row public.quote_versions;
  selected_subtotal numeric := 0;
  selected_cost numeric := 0;
  non_taxable_subtotal numeric := 0;
  taxable_subtotal numeric := 0;
  discount_amount numeric := 0;
  non_taxable_discount numeric := 0;
  taxable_discount numeric := 0;
  tax_amount numeric := 0;
  total_amount numeric := 0;
  deposit_amount numeric := 0;
  deposit_item public.quote_version_schedule_items;
  revenue numeric := 0;
  profit numeric := 0;
  margin_bps numeric;
  line_count integer := 0;
  line_result jsonb := '[]'::jsonb;
  chosen_addons uuid[] := coalesce(selected_addon_ids, '{}'::uuid[]);
begin
  select * into version_row from public.quote_versions where id = target_version_id;
  if version_row.id is null then
    raise exception 'That quote version was not found.' using errcode = 'no_data_found';
  end if;

  if exists (
    select 1 from unnest(chosen_addons) chosen(id)
    where not exists (
      select 1 from public.quote_version_lines line
      where line.id = chosen.id
        and line.organization_id = version_row.organization_id
        and line.quote_version_id = version_row.id
        and line.line_kind = 'priced' and line.selection_kind = 'optional'
    )
  ) then
    raise exception 'One or more selected add-ons do not belong to this quote version.'
      using errcode = 'check_violation';
  end if;

  select coalesce(sum(line_total_minor), 0), coalesce(sum(line_cost_total_minor), 0),
         coalesce(sum(line_total_minor) filter (where not is_taxable), 0),
         coalesce(sum(line_total_minor) filter (where is_taxable), 0), count(*)
  into selected_subtotal, selected_cost, non_taxable_subtotal, taxable_subtotal, line_count
  from public.quote_version_lines
  where organization_id = version_row.organization_id
    and quote_id = version_row.quote_id
    and quote_version_id = version_row.id
    and line_kind = 'priced'
    and (
      selection_kind = 'required'
      or (selection_kind = 'optional' and id = any(chosen_addons))
    );

  if selected_subtotal > 9223372036854775807 or selected_cost > 9223372036854775807 then
    raise exception 'The selected quote value is too large.' using errcode = 'numeric_value_out_of_range';
  end if;

  if version_row.discount_type = 'fixed' then
    discount_amount := least(version_row.discount_value, selected_subtotal);
  elsif version_row.discount_type = 'percentage' then
    discount_amount := round(selected_subtotal * version_row.discount_value / 10000);
  end if;
  non_taxable_discount := least(discount_amount, non_taxable_subtotal);
  taxable_discount := discount_amount - non_taxable_discount;

  with selected as (
    select id, position, is_taxable, line_total_minor
    from public.quote_version_lines
    where organization_id = version_row.organization_id
      and quote_id = version_row.quote_id
      and quote_version_id = version_row.id
      and line_kind = 'priced'
      and (
        selection_kind = 'required'
        or (selection_kind = 'optional' and id = any(chosen_addons))
      )
  ),
  shared as (
    select selected.*,
      case when selected.is_taxable then taxable_subtotal else non_taxable_subtotal end as group_total,
      case when selected.is_taxable then taxable_discount else non_taxable_discount end as group_discount,
      row_number() over (partition by selected.is_taxable order by selected.position, selected.id)
        as group_rank
    from selected
  ),
  rounded as (
    select shared.*,
      case when shared.group_total = 0 or shared.group_discount = 0 then 0
        else floor(shared.group_discount * shared.line_total_minor / shared.group_total)
      end as raw_allocation
    from shared
  ),
  spread as (
    select rounded.*,
      rounded.group_discount - sum(rounded.raw_allocation) over (partition by rounded.is_taxable)
        as group_remainder
    from rounded
  ),
  allocated as (
    select spread.id, spread.position, spread.is_taxable, spread.line_total_minor,
      spread.raw_allocation + case when spread.group_rank <= spread.group_remainder then 1 else 0 end
        as line_discount
    from spread
  ),
  taxed as (
    select allocated.*,
      allocated.line_total_minor - allocated.line_discount as net_amount,
      case when allocated.is_taxable
        then round((allocated.line_total_minor - allocated.line_discount)
          * version_row.tax_rate_basis_points / 10000)
        else 0
      end as line_tax
    from allocated
  )
  select coalesce(sum(line_tax), 0),
    coalesce(jsonb_agg(jsonb_build_object(
      'line_id', id,
      'gross_minor', line_total_minor,
      'discount_minor', line_discount::bigint,
      'net_minor', net_amount::bigint,
      'tax_minor', line_tax::bigint,
      'total_minor', (net_amount + line_tax)::bigint
    ) order by position, id), '[]'::jsonb)
  into tax_amount, line_result
  from taxed;

  total_amount := selected_subtotal - discount_amount + tax_amount;
  if total_amount > 9223372036854775807 then
    raise exception 'The selected quote total is too large.' using errcode = 'numeric_value_out_of_range';
  end if;

  -- A percentage deposit is a share of what the customer's current selection actually totals, so it moves
  -- with add-ons exactly like tax does; a fixed deposit is capped the same way a fixed discount is.
  if version_row.deposit_type is not null then
    select * into deposit_item
    from public.quote_version_schedule_items
    where organization_id = version_row.organization_id
      and quote_version_id = version_row.id
      and is_deposit;
    if deposit_item.id is null then
      raise exception 'This quote''s deposit is missing its required installment.'
        using errcode = 'check_violation';
    end if;
    if deposit_item.value_type = 'fixed' then
      deposit_amount := least(deposit_item.value, total_amount);
    else
      deposit_amount := round(total_amount * deposit_item.value / 10000);
    end if;
  end if;

  revenue := selected_subtotal - discount_amount;
  profit := revenue - selected_cost;
  margin_bps := case when revenue = 0 then null else round(profit * 10000 / revenue) end;

  return jsonb_build_object(
    'quote_version_id', version_row.id,
    'selected_addon_ids', to_jsonb(chosen_addons),
    'selected_line_count', line_count,
    'subtotal_minor', selected_subtotal::bigint,
    'discount_minor', discount_amount::bigint,
    'tax_minor', tax_amount::bigint,
    'total_minor', total_amount::bigint,
    'deposit_required_minor', deposit_amount::bigint,
    'cost_minor', selected_cost::bigint,
    'profit_minor', profit::bigint,
    'margin_basis_points', margin_bps::bigint,
    'lines', line_result
  );
end;
$$;


ALTER FUNCTION "private"."calculate_quote_version"("target_version_id" "uuid", "selected_addon_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_manage_linked_entity"("target_organization_id" "uuid", "target_entity_type" "text", "target_entity_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select private.can_manage_linked_record(
    target_organization_id, target_entity_type, target_entity_id, null
  );
$$;


ALTER FUNCTION "private"."can_manage_linked_entity"("target_organization_id" "uuid", "target_entity_type" "text", "target_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_manage_linked_record"("target_organization_id" "uuid", "target_entity_type" "text", "target_entity_id" "uuid", "target_record_owner" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select private.can_view_linked_entity(target_organization_id, target_entity_type, target_entity_id)
    and case target_entity_type
      when 'client' then private.has_permission(target_organization_id, 'customers.edit')
      when 'property' then private.has_permission(target_organization_id, 'property.manage')
      when 'request' then true
      when 'quote' then private.has_permission(target_organization_id, 'quotes.edit')
      when 'job_expense' then true
      when 'job' then private.field_record_write_allowed(target_organization_id, target_record_owner)
      when 'visit' then private.field_record_write_allowed(target_organization_id, target_record_owner)
      else false
    end;
$$;


