CREATE OR REPLACE FUNCTION "private"."can_view_assessment"("target_organization_id" "uuid", "target_assessment_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select target_organization_id = private.current_organization()
    and (
      private.current_permission_scope('jobs.view') <> 'assigned'
      or private.is_assigned_to_assessment(target_organization_id, target_assessment_id)
    );
$$;


ALTER FUNCTION "private"."can_view_assessment"("target_organization_id" "uuid", "target_assessment_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."can_view_assessment"("target_organization_id" "uuid", "target_assessment_id" "uuid") IS 'Whether the caller may see this assessment. Unlike a job, an assessment is not gated on holding jobs.view -- it is visible to every member unless their scope narrows it, which is what it was before Part 15a-3. Only the ''assigned'' scope narrows it.';



CREATE OR REPLACE FUNCTION "private"."can_view_client"("target_organization_id" "uuid", "target_client_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select private.is_organization_member(target_organization_id)
    and (
      private.has_permission(target_organization_id, 'customers.view')
      or private.client_is_assigned_to_current_user(target_organization_id, target_client_id)
    );
$$;


ALTER FUNCTION "private"."can_view_client"("target_organization_id" "uuid", "target_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_view_job"("target_organization_id" "uuid", "target_job_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select target_organization_id = private.current_organization()
    and (
      private.current_permission_scope('jobs.view') = 'all'
      or (
        private.current_permission_scope('jobs.view') = 'assigned'
        and private.is_assigned_to_job(target_organization_id, target_job_id)
      )
    );
$$;


ALTER FUNCTION "private"."can_view_job"("target_organization_id" "uuid", "target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."can_view_job"("target_organization_id" "uuid", "target_job_id" "uuid") IS 'Whether the caller may see this job. For single-entity lookups only -- the scanning read policies inline this same rule so the scope half can be hoisted to one evaluation per statement. The trailing jobs existence check this used to carry is gone: every caller reaches jobs through a composite (organization_id, job_id) foreign key, so referential integrity already guarantees it.';



CREATE OR REPLACE FUNCTION "private"."can_view_job_expense"("target_organization_id" "uuid", "target_expense_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public.job_expenses as expense
    where expense.id = target_expense_id
      and expense.organization_id = target_organization_id
      and private.can_view_job(target_organization_id, expense.job_id)
      and (
        private.has_permission(target_organization_id, 'expenses.manage_team')
        or (
          expense.created_by = (select auth.uid())
          and private.has_permission(target_organization_id, 'expenses.record')
        )
      )
  );
$$;


ALTER FUNCTION "private"."can_view_job_expense"("target_organization_id" "uuid", "target_expense_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_view_linked_entity"("target_organization_id" "uuid", "target_entity_type" "text", "target_entity_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(
    case target_entity_type
      when 'client' then private.can_view_client(target_organization_id, target_entity_id)
      when 'property' then private.can_view_property(target_organization_id, target_entity_id)
      when 'request' then private.can_view_request(target_organization_id, target_entity_id)
      when 'quote' then private.can_view_quote(target_organization_id, target_entity_id)
      when 'job_expense' then private.can_view_job_expense(target_organization_id, target_entity_id)
      when 'job' then private.can_view_job(target_organization_id, target_entity_id)
      when 'visit' then private.can_view_visit(target_organization_id, target_entity_id)
      else false
    end,
    false
  );
$$;


ALTER FUNCTION "private"."can_view_linked_entity"("target_organization_id" "uuid", "target_entity_type" "text", "target_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_view_property"("target_organization_id" "uuid", "target_property_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select private.can_view_client(target_organization_id, owning.client_id)
  from public.properties as owning
  where owning.id = target_property_id
    and owning.organization_id = target_organization_id;
