ALTER FUNCTION "private"."can_view_property"("target_organization_id" "uuid", "target_property_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_view_quote"("target_organization_id" "uuid", "target_quote_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select private.has_permission(target_organization_id, 'quotes.view')
    and exists (
      select 1
      from public.quotes
      where id = target_quote_id
        and organization_id = target_organization_id
    );
$$;


ALTER FUNCTION "private"."can_view_quote"("target_organization_id" "uuid", "target_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_view_request"("target_organization_id" "uuid", "target_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
      select 1
      from public.organization_members as membership
      join public.organizations as organization
        on organization.id = membership.organization_id
      where membership.organization_id = target_organization_id
        and membership.user_id = (select auth.uid())
        and membership.status = 'active'
        and organization.lifecycle_status = 'active'
        -- private.has_permission, inlined, for requests.view.
        and coalesce(
          (
            select override.override_state = 'grant'
            from public.organization_member_permission_overrides as override
            where override.organization_id = membership.organization_id
              and override.user_id = membership.user_id
              and override.permission_key = 'requests.view'
          ),
          exists (
            select 1
            from public.role_permissions as role_permission
            where role_permission.role = membership.role
              and role_permission.permission_key = 'requests.view'
          )
        )
        -- private.permission_scope, inlined, and then the assigned test itself.
        and (
          coalesce(
            (
              select case
                when override.override_state = 'deny' then 'none'
                else override.access_scope
              end
              from public.organization_member_permission_overrides as override
              where override.organization_id = membership.organization_id
                and override.user_id = membership.user_id
                and override.permission_key = 'requests.view'
            ),
            (
              select role_permission.access_scope
              from public.role_permissions as role_permission
              where role_permission.role = membership.role
                and role_permission.permission_key = 'requests.view'
            ),
            'none'
          ) <> 'assigned'
          or exists (
            select 1
            from public.assessments as assessment
            join public.assessment_assignees as assignee
              on assignee.assessment_id = assessment.id
            where assessment.organization_id = target_organization_id
              and assessment.request_id = target_request_id
              and assignee.user_id = membership.user_id
          )
        )
    );
$$;


ALTER FUNCTION "private"."can_view_request"("target_organization_id" "uuid", "target_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."can_view_request"("target_organization_id" "uuid", "target_request_id" "uuid") IS 'Whether the caller may see this request, and the seam Request pricing and linked records inherit. Single statement for the same per-row-cost reason private.can_view_job documents; change has_permission/permission_scope for requests.view and you must change this too. "Assigned" means the request''s own assessment, if it has one, lists this member as an assignee. Deliberately does not check that the request row exists: as the SELECT policy on public.requests it would not see a row being inserted by the current statement, which broke INSERT ... RETURNING.';



CREATE OR REPLACE FUNCTION "private"."can_view_visit"("target_organization_id" "uuid", "target_visit_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public.job_visits as visit
    where visit.id = target_visit_id
      and visit.organization_id = target_organization_id
      and private.can_view_job(visit.organization_id, visit.job_id)
  );
$$;


ALTER FUNCTION "private"."can_view_visit"("target_organization_id" "uuid", "target_visit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_write_job_expense"("target_organization_id" "uuid", "actor_id" "uuid", "subject_created_by" "uuid", "job_is_closed" boolean) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select private.member_has_permission(target_organization_id, actor_id, 'jobs.view')
    and (
      private.member_has_permission(target_organization_id, actor_id, 'expenses.manage_team')
      or (
        subject_created_by = actor_id
        and not job_is_closed
        and private.member_has_permission(target_organization_id, actor_id, 'expenses.record')
      )
    );
$$;


ALTER FUNCTION "private"."can_write_job_expense"("target_organization_id" "uuid", "actor_id" "uuid", "subject_created_by" "uuid", "job_is_closed" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."can_write_job_expense"("target_organization_id" "uuid", "actor_id" "uuid", "subject_created_by" "uuid", "job_is_closed" boolean) IS 'Whether this person may record or change this expense: anyone''s with expenses.manage_team, the ones they recorded themselves with expenses.record while the job is still open. Closing a job locks the crew out of its expenses, not the manager correcting them.';



CREATE OR REPLACE FUNCTION "private"."can_write_job_time"("target_organization_id" "uuid", "actor_id" "uuid", "subject_user_id" "uuid", "job_is_closed" boolean) RETURNS boolean
