ALTER FUNCTION "private"."can_write_job_time"("target_organization_id" "uuid", "actor_id" "uuid", "subject_user_id" "uuid", "job_is_closed" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."can_write_job_time"("target_organization_id" "uuid", "actor_id" "uuid", "subject_user_id" "uuid", "job_is_closed" boolean) IS 'Whether this person may record or change these hours: anyone''s with time.track_team, their own with time.track_own while the job is still open. Closing a job locks the crew out of its hours, not the manager correcting them.';



CREATE OR REPLACE FUNCTION "private"."checklist_answer_is_complete"("item_type" "text", "value" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case
    when value is null then false
    when item_type = 'checkbox' then value = to_jsonb(true)
    when jsonb_typeof(value) = 'string' then length(trim(value #>> '{}')) > 0
    else jsonb_typeof(value) <> 'null'
  end;
$$;


ALTER FUNCTION "private"."checklist_answer_is_complete"("item_type" "text", "value" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."checklist_answer_is_complete"("item_type" "text", "value" "jsonb") IS 'Whether one answer counts as given. A blank string and an unticked required checkbox are both blank; every other present value counts. The single definition behind the outstanding-work warning.';



CREATE OR REPLACE FUNCTION "private"."checklist_item_shape_is_valid"("item_type" "text", "options" "text"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case
    when item_type = 'dropdown' then options is not null and cardinality(options) between 1 and 50
    else options is null
  end;
$$;


ALTER FUNCTION "private"."checklist_item_shape_is_valid"("item_type" "text", "options" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."checklist_item_shape_is_valid"("item_type" "text", "options" "text"[]) IS 'Whether a checklist question is internally consistent: only a dropdown carries choices, and a dropdown without choices cannot be answered.';



CREATE OR REPLACE FUNCTION "private"."checklist_value_matches_type"("item_type" "text", "options" "text"[], "value" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select case
    when value is null or jsonb_typeof(value) = 'null' then true
    when item_type = 'checkbox' then jsonb_typeof(value) = 'boolean'
    when item_type = 'number' then jsonb_typeof(value) = 'number'
    when item_type = 'date' then
      jsonb_typeof(value) = 'string'
      and (value #>> '{}') ~ '^\d{4}-\d{2}-\d{2}$'
    when item_type = 'dropdown' then
      jsonb_typeof(value) = 'string'
      and (value #>> '{}') = any (coalesce(options, array[]::text[]))
    when item_type in ('short_text', 'long_text') then
      jsonb_typeof(value) = 'string'
      and length(value #>> '{}') <= case item_type when 'short_text' then 500 else 5000 end
    else false
  end;
$_$;


ALTER FUNCTION "private"."checklist_value_matches_type"("item_type" "text", "options" "text"[], "value" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."checklist_value_matches_type"("item_type" "text", "options" "text"[], "value" "jsonb") IS 'Whether an answer is legal for its question type. Lives in a function, not a check constraint, because the question type sits on a different table from the answer.';



CREATE OR REPLACE FUNCTION "private"."clean_website_chat_privacy_policy_url"("raw_url" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  cleaned text := nullif(trim(coalesce(raw_url, '')), '');
begin
  if cleaned is null then
    return null;
  end if;
  if cleaned not like 'https://%' or char_length(cleaned) > 500 then
    raise exception 'Enter a privacy policy link starting with https://, up to 500 characters.'
      using errcode = 'check_violation';
  end if;
  return cleaned;
end;
$$;


ALTER FUNCTION "private"."clean_website_chat_privacy_policy_url"("raw_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."client_is_assigned_to_current_user"("target_organization_id" "uuid", "target_client_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public.job_visit_assignments as assignment
    join public.jobs as job
      on job.organization_id = assignment.organization_id
     and job.id = assignment.job_id
    where assignment.organization_id = target_organization_id
      and assignment.user_id = (select auth.uid())
      and job.client_id = target_client_id
  );
$$;


