      then 'provider_deferred' else new.delivery_outcome end,
    p_occurred_at => coalesce(new.delivery_outcome_at, now()),
    p_reason_message => new.delivery_outcome_detail,
    p_actor_kind => 'provider'
  );
  return new;
end;
