CREATE TABLE IF NOT EXISTS "public"."communication_delivery_intents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "client_contact_method_id" "uuid" NOT NULL,
    "channel" "text" DEFAULT 'email'::"text" NOT NULL,
    "direction" "text" DEFAULT 'outbound'::"text" NOT NULL,
    "logical_send_key" "text" NOT NULL,
    "recipient_email" "text",
    "subject" "text",
    "html_content" "text",
    "text_content" "text",
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "provider_message_id" "text",
    "accepted_at" timestamp with time zone,
    "failure_code" "text",
    "failure_message" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "send_kind" "text" DEFAULT 'manual'::"text" NOT NULL,
    "sender_id" "uuid",
    "allowance_class" "text" DEFAULT 'optional'::"text" NOT NULL,
    "quote_id" "uuid",
    "resent_from_intent_id" "uuid",
    "reply_alias_id" "uuid",
    "delivery_outcome" "text",
    "delivery_outcome_at" timestamp with time zone,
    "delivery_outcome_detail" "text",
    "retry_class" "text" DEFAULT 'standard'::"text" NOT NULL,
    "retry_window_ends_at" timestamp with time zone,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '24:00:00'::interval) NOT NULL,
    "quote_version_id" "uuid",
    "quote_recipient_id" "uuid",
    "quote_access_link_id" "uuid",
    "invoice_id" "uuid",
    "client_payment_event_id" "uuid",
    "recipient_phone" "text",
    "sms_sender_identity_id" "uuid",
    CONSTRAINT "communication_delivery_intents_accepted_check" CHECK ((("status" = 'submitted'::"text") = (("accepted_at" IS NOT NULL) AND ("provider_message_id" IS NOT NULL)))),
    CONSTRAINT "communication_delivery_intents_allowance_class_check" CHECK (("allowance_class" = ANY (ARRAY['optional'::"text", 'essential'::"text"]))),
    CONSTRAINT "communication_delivery_intents_channel_check" CHECK (("channel" = ANY (ARRAY['email'::"text", 'sms'::"text"]))),
    CONSTRAINT "communication_delivery_intents_channel_payload_check" CHECK (((("channel" = 'email'::"text") AND ("recipient_email" IS NOT NULL) AND (POSITION(('@'::"text") IN ("recipient_email")) > 1) AND ("recipient_phone" IS NULL) AND ("subject" IS NOT NULL) AND (("char_length"(TRIM(BOTH FROM "subject")) >= 1) AND ("char_length"(TRIM(BOTH FROM "subject")) <= 998)) AND ("html_content" IS NOT NULL) AND ("char_length"(TRIM(BOTH FROM "html_content")) > 0) AND ("text_content" IS NOT NULL) AND ("char_length"(TRIM(BOTH FROM "text_content")) > 0) AND ("sms_sender_identity_id" IS NULL)) OR (("channel" = 'sms'::"text") AND ("recipient_email" IS NULL) AND ("recipient_phone" IS NOT NULL) AND ("recipient_phone" ~ '^\+[1-9][0-9]{7,14}$'::"text") AND ("subject" IS NULL) AND ("html_content" IS NULL) AND ("text_content" IS NULL) AND ("sender_id" IS NULL) AND ("reply_alias_id" IS NULL)))),
    CONSTRAINT "communication_delivery_intents_delivery_outcome_check" CHECK (("delivery_outcome" = ANY (ARRAY['delivered'::"text", 'soft_bounce'::"text", 'hard_bounce'::"text", 'complaint'::"text", 'deferred'::"text", 'blocked'::"text", 'unsubscribed'::"text", 'sms_delivered'::"text", 'sms_undelivered'::"text", 'sms_failed'::"text", 'sms_needs_checking'::"text"]))),
    CONSTRAINT "communication_delivery_intents_direction_check" CHECK (("direction" = 'outbound'::"text")),
    CONSTRAINT "communication_delivery_intents_logical_send_key_check" CHECK ((("char_length"(TRIM(BOTH FROM "logical_send_key")) >= 1) AND ("char_length"(TRIM(BOTH FROM "logical_send_key")) <= 200))),
    CONSTRAINT "communication_delivery_intents_quote_identity_check" CHECK (((("quote_version_id" IS NULL) AND ("quote_recipient_id" IS NULL) AND ("quote_access_link_id" IS NULL)) OR (("quote_id" IS NOT NULL) AND ("quote_version_id" IS NOT NULL) AND ("quote_recipient_id" IS NOT NULL) AND ("quote_access_link_id" IS NOT NULL)))),
    CONSTRAINT "communication_delivery_intents_retry_class_check" CHECK (("retry_class" = ANY (ARRAY['standard'::"text", 'payment_receipt'::"text", 'appointment_reminder'::"text", 'optional_followup'::"text"]))),
    CONSTRAINT "communication_delivery_intents_send_kind_check" CHECK (("send_kind" = ANY (ARRAY['manual'::"text", 'automated'::"text"]))),
    CONSTRAINT "communication_delivery_intents_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'claimed'::"text", 'submitted'::"text", 'failed'::"text", 'cancelled'::"text", 'submission_unknown'::"text"]))),
    CONSTRAINT "communication_delivery_intents_text_content_check" CHECK (("char_length"(TRIM(BOTH FROM "text_content")) > 0))
);


ALTER TABLE "public"."communication_delivery_intents" OWNER TO "postgres";


COMMENT ON COLUMN "public"."communication_delivery_intents"."sender_id" IS 'The queued sender preference. The worker may submit only the sender returned by the atomic claim.';



COMMENT ON COLUMN "public"."communication_delivery_intents"."retry_class" IS 'Which useful-life clock this message runs on. Set by the caller; the deadline itself is derived.';



COMMENT ON COLUMN "public"."communication_delivery_intents"."retry_window_ends_at" IS 'Required for appointment_reminder, optional for optional_followup: the caller''s own boundary.';



COMMENT ON COLUMN "public"."communication_delivery_intents"."expires_at" IS 'Derived deadline. Past it the claim cancels the message instead of releasing it.';



COMMENT ON COLUMN "public"."communication_delivery_intents"."quote_version_id" IS 'The published quote version this email actually delivered. Immutable send-time identity for Automation.';



COMMENT ON COLUMN "public"."communication_delivery_intents"."quote_recipient_id" IS 'The quote_recipients row this email was addressed to at send time.';



COMMENT ON COLUMN "public"."communication_delivery_intents"."quote_access_link_id" IS 'The access link minted for this send. Later sends rotate the link; this one stays pinned to this email.';



COMMENT ON COLUMN "public"."communication_delivery_intents"."client_payment_event_id" IS 'The recorded payment this email is a receipt for. Restrict-on-delete so a payment with a sent receipt cannot be deleted out from under it.';



CREATE OR REPLACE FUNCTION "private"."communication_sms_enqueue_operational_core"("p_organization_id" "uuid", "p_client_id" "uuid", "p_client_contact_method_id" "uuid", "p_sender_id" "uuid", "p_subject" "text", "p_body" "text", "p_send_kind" "text", "p_logical_send_key" "text", "p_created_by" "uuid", "p_attachments" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  recipient public.client_contact_methods;
  recipient_e164 text;
  sender public.communication_sms_sender_identities;
  registration public.communication_sms_registrations;
  outbound record;
  consent text;
  v_encoding text;
  v_segment_count integer;
  rate public.communication_sms_retail_rates;
  cost_minor bigint;
  currency text := 'USD';
  settled bigint;
  reserved bigint;
  promo_balance bigint;
  promo_reserved bigint;
  promo_available bigint;
  purchased_available bigint;
  promo_used bigint;
  purchased_used bigint;
  available timestamptz;
  intent public.communication_delivery_intents;
  existing public.communication_delivery_intents;
  existing_raw_body text;
  source_key text;
  v_attachment jsonb;
  v_delivery_mode text;
  v_effective_body text;
  v_attachment_id uuid;
  v_attachment_bytes bigint;
begin
  -- 1. Shape.
  if p_subject is null or p_subject not in ('service', 'work_updates', 'billing_updates') then
    raise exception 'a send must name a valid operational subject' using errcode = 'P0001';
  end if;
  if p_body is null or char_length(trim(p_body)) = 0 then
    raise exception 'a send needs a message body' using errcode = 'P0001';
  end if;
  if p_send_kind is null or p_send_kind not in ('manual', 'automated') then
    raise exception 'a send must be manual or automated' using errcode = 'P0001';
  end if;
  if p_logical_send_key is null or char_length(trim(p_logical_send_key)) = 0 then
    raise exception 'a send must carry a logical send key' using errcode = 'P0001';
  end if;
  if jsonb_array_length(coalesce(p_attachments, '[]'::jsonb)) > 1 then
    raise exception 'Attach at most one file to a text message.' using errcode = 'check_violation';
  end if;

  -- 2. Resolve the recipient: an active phone on this customer in this organization, normalized to E.164.
  select method.* into recipient
  from public.client_contact_methods method
  join public.clients client
    on client.organization_id = method.organization_id and client.id = method.client_id
  where method.organization_id = p_organization_id
    and method.id = p_client_contact_method_id
    and method.client_id = p_client_id
    and method.kind = 'phone'
    and client.deleted_at is null
  for share of method, client;

  if recipient.id is null then
    raise exception 'Choose an active phone number for this customer.' using errcode = 'foreign_key_violation';
  end if;
  recipient_e164 := '+' || recipient.normalized_value;
  if recipient_e164 !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception 'That customer phone number is not a valid mobile number.' using errcode = 'P0001';
  end if;

  -- 3. Resolve the sending number: the chosen one, or the organization default. Must be a live, SMS-capable
  --    number tied to a registration.
  if p_sender_id is not null then
    select s.* into sender
    from public.communication_sms_sender_identities s
    where s.organization_id = p_organization_id
      and s.id = p_sender_id
      and s.lifecycle_state = 'ready'
      and s.capable_sms
    for share of s;
  else
    select s.* into sender
    from public.communication_sms_sender_identities s
    where s.organization_id = p_organization_id
      and s.is_default_sender
      and s.lifecycle_state = 'ready'
      and s.capable_sms
    for share of s;
  end if;

  if sender.id is null then
    raise exception 'No ready SMS number is available to send from.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;
  if sender.registration_id is null or sender.country_code is null or sender.sender_type is null then
    raise exception 'This SMS number is not fully set up to send yet.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  -- 3.5. Delivery mode (Stage 6D-3): a picture goes as real MMS only when both the sender is MMS-capable and
  --      its registered country is US/Canada (Twilio's hard technical limit -- see 6D-2's own header note for
  --      why this is the only country signal this system has). Anything else with an attachment -- a
  --      non-image file, or an image the sender/destination cannot carry as MMS -- gets a secure link instead
  --      of a refusal, per the approved 6D contract. No exception is raised for ineligibility any more.
  if jsonb_array_length(coalesce(p_attachments, '[]'::jsonb)) = 1 then
    v_attachment := p_attachments -> 0;
    if (v_attachment ->> 'mime_type') in ('image/jpeg', 'image/jpg', 'image/png', 'image/gif')
       and sender.capable_mms and sender.country_code in ('US', 'CA') then
      v_delivery_mode := 'inline_media';
    else
      v_delivery_mode := 'secure_link';
    end if;
  end if;

  v_effective_body := case
    when v_delivery_mode = 'secure_link' then p_body || E'\n\n' || (v_attachment ->> 'link_url')
    else p_body
  end;

  select r.* into registration
  from public.communication_sms_registrations r
  where r.organization_id = p_organization_id and r.id = sender.registration_id;
  if registration.id is null then
    raise exception 'This SMS number is not fully set up to send yet.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  -- 4. Idempotency: a repeat of the same logical send returns the already-queued intent unchanged; the same
  --    key with a different frozen payload is a conflict. Compared against raw_body (what the user actually
  --    typed), never the wire body -- see this migration's header note on why the wire body can legitimately
  --    differ attempt to attempt for a secure-link send. Return the replay before re-running any live gate.
  select i.* into existing
  from public.communication_delivery_intents i
  where i.organization_id = p_organization_id and i.logical_send_key = trim(p_logical_send_key);

  if existing.id is not null then
    select snap.raw_body into existing_raw_body
    from public.communication_sms_message_snapshots snap
    where snap.delivery_intent_id = existing.id;

    if existing.channel = 'sms'
      and existing.recipient_phone = recipient_e164
      and existing.sms_sender_identity_id = sender.id
      and existing.send_kind = p_send_kind
      and existing_raw_body = p_body then
      return existing;
    end if;
    raise exception 'This message was already queued with different details.' using errcode = 'unique_violation';
  end if;

  -- 5. Readiness and holds in one read.
  select * into outbound
  from public.communication_sms_outbound_state(
    p_organization_id, sender.country_code, sender.sender_type, registration.use_case
  );
  if outbound.state = 'outbound_paused' then
    raise exception 'Outbound SMS is paused for this organization right now.'
      using errcode = 'object_not_in_prerequisite_state';
  elsif outbound.state <> 'ready' then
    raise exception 'This organization is not ready to send SMS yet.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  -- 6. Consent for this exact number and this one subject. Unknown or opted-out refuses.
  consent := public.communication_sms_consent_status(
    p_organization_id, p_client_contact_method_id, p_subject
  );
  if consent = 'opted_out' then
    raise exception 'This customer has opted out of text messages.' using errcode = 'P0001';
  elsif consent <> 'opted_in' then
    raise exception 'There is no SMS consent on file for this customer and message type.'
      using errcode = 'P0001';
  end if;

  -- 7. Freeze the segment estimate against the wire body (with any secure link already appended), so the
  --     charge, the "too long to send" refusal and the frozen snapshot all agree on what is actually sent.
  select est.encoding, est.segment_count into v_encoding, v_segment_count
  from public.communication_sms_estimate_segments(v_effective_body) est;
  if v_segment_count > 10 then
    raise exception 'This message is too long to send as one text.' using errcode = 'P0001';
  end if;

  -- 8. Freeze the applicable retail rate and the estimated cost (rounded up so the reservation never
  --    under-holds). A real MMS photo bills as one flat message_unit='mms' charge, matching how Twilio itself
  --    bills a picture text -- per segment only applies to plain text.
  if v_delivery_mode = 'inline_media' then
    select rr.* into rate
    from public.communication_sms_effective_retail_rate(
      sender.country_code, sender.sender_type, 'mms', currency, now()
    ) rr;
    if rate.id is null then
      raise exception 'No picture-message price is published for this destination yet.'
        using errcode = 'object_not_in_prerequisite_state';
    end if;
    cost_minor := ceil(rate.retail_rate_major * 100)::bigint;
  else
    select rr.* into rate
    from public.communication_sms_effective_retail_rate(
      sender.country_code, sender.sender_type, 'segment', currency, now()
    ) rr;
    if rate.id is null then
      raise exception 'No SMS price is published for this destination yet.'
        using errcode = 'object_not_in_prerequisite_state';
    end if;
    cost_minor := ceil(v_segment_count * rate.retail_rate_major * 100)::bigint;
  end if;

  -- 9. Serialize on the organization's credit account and check spendable balance.
  insert into public.communication_sms_credit_accounts (organization_id, currency_code)
  values (p_organization_id, currency)
  on conflict (organization_id) do nothing;

  select settled_balance_minor, reserved_balance_minor into settled, reserved
  from public.communication_sms_credit_accounts
  where organization_id = p_organization_id
  for update;

  promo_balance := public.communication_sms_promotional_balance(p_organization_id);
  select coalesce(sum(reserved_promotional_minor), 0) into promo_reserved
  from public.communication_sms_credit_reservations
  where organization_id = p_organization_id and state in ('reserved', 'submission_unknown', 'settled');
  promo_available := greatest(promo_balance - promo_reserved, 0);
  purchased_available := settled - reserved;

  if promo_available + purchased_available < cost_minor then
    raise exception 'There is not enough SMS balance to send this message.' using errcode = 'P0402';
  end if;

  promo_used := least(cost_minor, promo_available);
  purchased_used := cost_minor - promo_used;

  -- 10. Schedule for quiet hours (now unless inside the window).
  available := public.communication_sms_quiet_hours_available_at(now());

  -- 11. Create the durable send intent.
  begin
    insert into public.communication_delivery_intents (
      organization_id, client_id, client_contact_method_id, channel, logical_send_key,
      recipient_phone, sms_sender_identity_id, send_kind, allowance_class, created_by
    ) values (
      p_organization_id, p_client_id, p_client_contact_method_id, 'sms', trim(p_logical_send_key),
      recipient_e164, sender.id, p_send_kind, 'optional', p_created_by
    )
    returning * into intent;
  exception when unique_violation then
    select i.* into existing
    from public.communication_delivery_intents i
    where i.organization_id = p_organization_id and i.logical_send_key = trim(p_logical_send_key);
    select snap.raw_body into existing_raw_body
    from public.communication_sms_message_snapshots snap
    where snap.delivery_intent_id = existing.id;
    if existing.channel = 'sms'
      and existing.recipient_phone = recipient_e164
      and existing.sms_sender_identity_id = sender.id
      and existing.send_kind = p_send_kind
      and existing_raw_body = p_body then
      return existing;
    end if;
    raise exception 'This message was already queued with different details.' using errcode = 'unique_violation';
  end;

  -- 12. Freeze the wire body (with any link already appended), the raw draft text, encoding and segment count.
  insert into public.communication_sms_message_snapshots (
    delivery_intent_id, organization_id, body, raw_body, encoding, segment_count
  ) values (
    intent.id, p_organization_id, v_effective_body, p_body, v_encoding, v_segment_count
  );

  -- 13. Reserve the estimated cost.
  source_key := 'send:' || trim(p_logical_send_key);
  update public.communication_sms_credit_accounts
  set reserved_balance_minor = reserved_balance_minor + purchased_used,
      updated_at = now()
  where organization_id = p_organization_id;

  insert into public.communication_sms_credit_reservations (
    organization_id, delivery_intent_id, source_key, amount_minor, segment_count,
    reserved_promotional_minor, reserved_purchased_minor
  ) values (
    p_organization_id, intent.id, source_key, cost_minor, v_segment_count,
    promo_used, purchased_used
  );

  -- 14. Persist the attachment (if any) and, for a secure-link delivery, the access link the body already
  --     names. Re-validates size and the caller's own object-key prefix server-side (advisory checks
  --     already ran in TS) -- a real MMS photo keeps 6D-2's own 5 MB/image-only ceiling; anything going out
  --     as a link gets the same 20 MB ceiling every other outbound attachment (email) already uses.
  if v_delivery_mode is not null then
    v_attachment_bytes := (v_attachment ->> 'byte_size')::bigint;
    if v_attachment ->> 'object_key' not like p_organization_id::text || '/outbound-sms-attachments/%' then
      raise exception 'That file does not belong to this business.' using errcode = 'check_violation';
    end if;
    if v_delivery_mode = 'inline_media' and v_attachment_bytes > 5 * 1024 * 1024 then
      raise exception 'A picture must be 5 MB or smaller to send as a text message.'
        using errcode = 'check_violation';
    end if;
    if v_delivery_mode = 'secure_link' and v_attachment_bytes > 20 * 1024 * 1024 then
      raise exception 'A file must be 20 MB or smaller to send as a text message.'
        using errcode = 'check_violation';
    end if;

    insert into public.communication_outbound_attachments (
      organization_id, delivery_intent_id, file_name, mime_type, byte_size, object_key, delivery_mode
    ) values (
      p_organization_id, intent.id, v_attachment ->> 'file_name', v_attachment ->> 'mime_type',
      v_attachment_bytes, v_attachment ->> 'object_key', v_delivery_mode
    )
    on conflict (delivery_intent_id, object_key) do update set delivery_mode = excluded.delivery_mode
    returning id into v_attachment_id;

    if v_delivery_mode = 'secure_link' then
      insert into public.communication_sms_attachment_access_links (
        organization_id, delivery_intent_id, attachment_id, token_hash
      ) values (
        p_organization_id, intent.id, v_attachment_id,
        decode(v_attachment ->> 'access_token_hash', 'hex')
      )
      on conflict (token_hash) do nothing;
    end if;
  end if;

  -- 15. Hand the send to the outbox, scheduled for quiet hours.
  insert into public.communication_outbox_events (
    organization_id, delivery_intent_id, channel, available_at
  ) values (
    p_organization_id, intent.id, 'sms', available
  );

  return intent;
end;
$_$;


ALTER FUNCTION "private"."communication_sms_enqueue_operational_core"("p_organization_id" "uuid", "p_client_id" "uuid", "p_client_contact_method_id" "uuid", "p_sender_id" "uuid", "p_subject" "text", "p_body" "text", "p_send_kind" "text", "p_logical_send_key" "text", "p_created_by" "uuid", "p_attachments" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."communication_sms_enqueue_operational_core"("p_organization_id" "uuid", "p_client_id" "uuid", "p_client_contact_method_id" "uuid", "p_sender_id" "uuid", "p_subject" "text", "p_body" "text", "p_send_kind" "text", "p_logical_send_key" "text", "p_created_by" "uuid", "p_attachments" "jsonb") IS 'The one SMS eligibility/write engine shared by every caller: consent, destination, readiness/holds, balance, segments/rate, quiet hours, idempotency, delivery-mode resolution (real MMS vs a secure link baked into the body) and the atomic intent/reservation/snapshot/attachment/outbox write. Takes no actor and does no permission check -- callers authorize themselves first. Service role only.';



CREATE OR REPLACE FUNCTION "private"."communication_sms_release_reservation"("p_delivery_intent_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  reservation public.communication_sms_credit_reservations;
begin
  select * into reservation
  from public.communication_sms_credit_reservations
  where delivery_intent_id = p_delivery_intent_id
  for update;

  if not found or reservation.state <> 'reserved' then
    return;
  end if;

  update public.communication_sms_credit_accounts
  set reserved_balance_minor = reserved_balance_minor - reservation.reserved_purchased_minor,
      updated_at = now()
  where organization_id = reservation.organization_id;

  update public.communication_sms_credit_reservations
  set state = 'released', settled_at = now()
  where id = reservation.id;
end;
$$;


ALTER FUNCTION "private"."communication_sms_release_reservation"("p_delivery_intent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."complete_invoice_command"("target_organization_id" "uuid", "new_action" "text", "new_idempotency_key" "text", "new_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  update private.invoice_command_receipts
  set result = coalesce(new_result, '{}'::jsonb)
  where organization_id = target_organization_id
    and action = new_action
    and idempotency_key = new_idempotency_key;

  if not found then
    raise exception 'That command receipt is missing.' using errcode = 'no_data_found';
  end if;

  return coalesce(new_result, '{}'::jsonb) || jsonb_build_object('applied', true);
end;
$$;


ALTER FUNCTION "private"."complete_invoice_command"("target_organization_id" "uuid", "new_action" "text", "new_idempotency_key" "text", "new_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."compute_form_available_slots"("target_organization_id" "uuid", "target_form_id" "uuid", "range_start" "date", "range_end" "date") RETURNS TABLE("slot_date" "date", "start_time" time without time zone, "end_time" time without time zone, "starts_at" timestamp with time zone, "ends_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  rules public.form_booking_rules;
  org_timezone text;
  hours_mode text;
  earliest_allowed timestamp;
  visit_duration interval;
  slot_interval interval;
  current_day date;
  current_weekday smallint;
  day_bands tsrange[];
  band tsrange;
  band_start timestamp;
  band_end timestamp;
  candidate_start timestamp;
  candidate_end timestamp;
  free_member uuid;
  max_range_days constant integer := 60;
  max_rows constant integer := 2000;
  returned_rows integer := 0;
begin
  if range_start is null or range_end is null or range_end < range_start then
    raise exception 'Give a valid date range.' using errcode = 'check_violation';
  end if;
  if range_end - range_start > max_range_days then
    raise exception 'Ask for at most % days at a time.', max_range_days using errcode = 'check_violation';
  end if;

  select * into rules
  from public.form_booking_rules
  where form_id = target_form_id and organization_id = target_organization_id;

  if rules.form_id is null then
    raise exception 'This form has no booking rules.' using errcode = 'check_violation';
  end if;

  select settings.timezone, settings.hours_mode into org_timezone, hours_mode
  from public.organization_settings as settings
  where settings.organization_id = target_organization_id;

  if hours_mode is null or hours_mode = 'not_configured' then
    return;
  end if;

  earliest_allowed := (now() + make_interval(mins => rules.min_notice_minutes)) at time zone org_timezone;
  visit_duration := make_interval(mins => rules.visit_duration_minutes);
  slot_interval := make_interval(mins => rules.slot_interval_minutes);

  current_day := range_start;
  while current_day <= range_end loop
    if exists (
      select 1 from public.schedule_events as event
      where event.organization_id = target_organization_id
        and event.event_date = current_day
        and event.start_time is null
    ) then
      current_day := current_day + 1;
      continue;
    end if;

    current_weekday := extract(dow from current_day)::smallint;
    day_bands := private.form_booking_day_bands(
      target_organization_id, hours_mode, current_day, current_weekday
    );

    foreach band in array day_bands loop
      band_start := lower(band);
      band_end := upper(band);
      candidate_start := band_start;

      while candidate_start + visit_duration <= band_end loop
        candidate_end := candidate_start + visit_duration;

        if candidate_start >= earliest_allowed
          and not private.form_booking_slot_blocked_by_team_event(
            target_organization_id, candidate_start, candidate_end, rules.buffer_minutes
          )
        then
          free_member := private.form_booking_free_member_for_slot(
            target_organization_id, candidate_start, candidate_end, rules.buffer_minutes, org_timezone
          );

          if free_member is not null then
            slot_date := candidate_start::date;
            start_time := candidate_start::time;
            end_time := candidate_end::time;
            starts_at := candidate_start at time zone org_timezone;
            ends_at := candidate_end at time zone org_timezone;
            return next;

            returned_rows := returned_rows + 1;
            if returned_rows >= max_rows then
              return;
            end if;
          end if;
        end if;

        candidate_start := candidate_start + slot_interval;
      end loop;
    end loop;

    current_day := current_day + 1;
  end loop;

  return;
end;
$$;


ALTER FUNCTION "private"."compute_form_available_slots"("target_organization_id" "uuid", "target_form_id" "uuid", "range_start" "date", "range_end" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."compute_form_available_slots"("target_organization_id" "uuid", "target_form_id" "uuid", "range_start" "date", "range_end" "date") IS 'The actual slot-computation loop, shared by the staff-only and public-safe readers below so there is exactly one place that decides what counts as an open slot.';



CREATE OR REPLACE FUNCTION "private"."create_chain_successor_draft"("predecessor" "public"."invoices", "link_kind" "text", "actor" "uuid") RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  successor public.invoices;
begin
  insert into public.invoices (
    organization_id, client_id, invoice_number, subject, currency_code,
    customer_snapshot, billing_address_snapshot, service_properties,
    payment_term_id, payment_term_snapshot, due_date_source, issue_date, due_date,
    predecessor_invoice_id, root_invoice_id, replacement_kind, created_by
  ) values (
    predecessor.organization_id,
    predecessor.client_id,
    private.allocate_invoice_number(predecessor.organization_id),
    predecessor.subject,
    -- The chain's currency, not today's setting. A correction to a bill written in the old currency stays in
    -- that currency or it is not a correction.
    predecessor.currency_code,
    predecessor.customer_snapshot,
    predecessor.billing_address_snapshot,
    predecessor.service_properties,
    predecessor.payment_term_id,
    predecessor.payment_term_snapshot,
    predecessor.due_date_source,
    -- Today's date for the replacement, with the predecessor's own interval to its due date preserved, so a
    -- Net 30 correction is still Net 30 rather than instantly overdue.
    private.organization_today(predecessor.organization_id),
    private.organization_today(predecessor.organization_id)
      + (predecessor.due_date - predecessor.issue_date),
    predecessor.id,
    predecessor.root_invoice_id,
    link_kind,
    actor
  )
  returning * into successor;

  insert into public.invoice_lines (
    organization_id, invoice_id, position, source_catalog_item_id, source_job_id, source_job_line_id,
    service_date, line_kind, category, name, description, unit_label, quantity, unit_price_minor,
    is_taxable, progress_original_amount_minor
  )
  select
    line.organization_id, successor.id, line.position, line.source_catalog_item_id, line.source_job_id,
    line.source_job_line_id, line.service_date, line.line_kind, line.category, line.name, line.description,
    line.unit_label, line.quantity, line.unit_price_minor, line.is_taxable,
    -- D3: already issued installment amounts are locked on the job, so the original amount travels with the
    -- line rather than being recalculated from a schedule the correction is not allowed to rewrite.
    line.progress_original_amount_minor
  from public.invoice_lines as line
  where line.organization_id = predecessor.organization_id
    and line.invoice_id = predecessor.id
  order by line.position, line.id;

  -- The discount and tax inputs come across too; store_invoice_money recalculates the totals from them so no
  -- amount is ever copied by hand.
  update public.invoices
  set discount_name = predecessor.discount_name,
      discount_type = predecessor.discount_type,
      discount_value = predecessor.discount_value,
      tax_source = predecessor.tax_source,
      tax_name = predecessor.tax_name,
      tax_rate_basis_points = predecessor.tax_rate_basis_points,
      tax_rate_id = predecessor.tax_rate_id
  where organization_id = successor.organization_id and id = successor.id;

  perform private.store_invoice_money(successor.id);

  select * into successor
  from public.invoices
  where organization_id = successor.organization_id and id = successor.id;

  return successor;
end;
$$;


ALTER FUNCTION "private"."create_chain_successor_draft"("predecessor" "public"."invoices", "link_kind" "text", "actor" "uuid") OWNER TO "postgres";


