COMMENT ON FUNCTION "private"."create_invoice_reminder"("target_organization_id" "uuid", "target_job_id" "uuid", "new_kind" "text", "new_due_on" "date", "actor" "uuid", "new_visit_id" "uuid", "new_note" "text") IS 'Raises one invoice reminder and logs it, or returns the open reminder already there. Checks tenancy only; the caller owns the permission check. Used by month-end, custom dates, and (Part 13) visit and close events.';



CREATE TABLE IF NOT EXISTS "public"."jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "property_id" "uuid" NOT NULL,
    "quote_id" "uuid",
    "quote_version_id" "uuid",
    "job_number" integer NOT NULL,
    "title" "text" NOT NULL,
    "job_type" "text" NOT NULL,
    "is_as_needed" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "price_basis" "text" NOT NULL,
    "billing_timing" "text" DEFAULT 'on_closure'::"text" NOT NULL,
    "currency_code" "text" NOT NULL,
    "instructions" "text",
    "arrival_window_minutes" integer,
    "arrival_window_style" "text",
    "contract_start_date" "date",
    "contract_end_date" "date",
    "subtotal_minor" bigint DEFAULT 0 NOT NULL,
    "discount_minor" bigint DEFAULT 0 NOT NULL,
    "tax_minor" bigint DEFAULT 0 NOT NULL,
    "total_minor" bigint DEFAULT 0 NOT NULL,
    "cost_minor" bigint DEFAULT 0 NOT NULL,
    "revision" integer DEFAULT 0 NOT NULL,
    "closed_at" timestamp with time zone,
    "closed_by" "uuid",
    "reopened_at" timestamp with time zone,
    "conversion_idempotency_key" "text",
    "conversion_request_hash" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "discount_name" "text",
    "discount_type" "text",
    "discount_value" bigint,
    "tax_source" "text" DEFAULT 'not_configured'::"text" NOT NULL,
    "tax_name" "text",
    "tax_rate_basis_points" integer DEFAULT 0 NOT NULL,
    "tax_rate_id" "uuid",
    CONSTRAINT "jobs_arrival_window_complete" CHECK ((("arrival_window_minutes" IS NULL) = ("arrival_window_style" IS NULL))),
    CONSTRAINT "jobs_arrival_window_minutes_check" CHECK ((("arrival_window_minutes" IS NULL) OR (("arrival_window_minutes" >= 15) AND ("arrival_window_minutes" <= 240)))),
    CONSTRAINT "jobs_arrival_window_style_check" CHECK ((("arrival_window_style" IS NULL) OR ("arrival_window_style" = ANY (ARRAY['after_start'::"text", 'centered'::"text"])))),
    CONSTRAINT "jobs_as_needed_is_recurring" CHECK (((NOT "is_as_needed") OR ("job_type" = 'recurring'::"text"))),
    CONSTRAINT "jobs_billing_timing_check" CHECK (("billing_timing" = ANY (ARRAY['on_closure'::"text", 'per_completed_visit'::"text", 'month_end'::"text", 'custom_dates'::"text", 'manual'::"text"]))),
    CONSTRAINT "jobs_closed_stamp_matches_status" CHECK ((("status" = 'closed'::"text") = ("closed_at" IS NOT NULL))),
    CONSTRAINT "jobs_contract_dates_ordered" CHECK ((("contract_start_date" IS NULL) OR ("contract_end_date" IS NULL) OR ("contract_end_date" >= "contract_start_date"))),
    CONSTRAINT "jobs_conversion_needs_quote" CHECK ((("conversion_idempotency_key" IS NULL) OR ("quote_id" IS NOT NULL))),
    CONSTRAINT "jobs_conversion_receipt_consistent" CHECK ((("conversion_idempotency_key" IS NULL) = ("conversion_request_hash" IS NULL))),
    CONSTRAINT "jobs_cost_minor_check" CHECK ((("cost_minor" >= 0) AND ("cost_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "jobs_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "jobs_discount_check" CHECK (((("discount_type" IS NULL) AND ("discount_value" IS NULL) AND ("discount_name" IS NULL)) OR (("discount_type" = ANY (ARRAY['fixed'::"text", 'percentage'::"text"])) AND (("discount_value" >= 0) AND ("discount_value" <=
CASE
    WHEN ("discount_type" = 'percentage'::"text") THEN (10000)::bigint
    ELSE '9000000000000000000'::bigint
END)) AND ("discount_name" IS NOT NULL)))),
    CONSTRAINT "jobs_discount_minor_check" CHECK ((("discount_minor" >= 0) AND ("discount_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "jobs_discount_name_check" CHECK ((("discount_name" IS NULL) OR (("char_length"(TRIM(BOTH FROM "discount_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "discount_name")) <= 80)))),
    CONSTRAINT "jobs_discount_within_subtotal" CHECK (("discount_minor" <= "subtotal_minor")),
    CONSTRAINT "jobs_instructions_check" CHECK ((("instructions" IS NULL) OR ("char_length"("instructions") <= 4000))),
    CONSTRAINT "jobs_job_number_check" CHECK (("job_number" >= 1)),
    CONSTRAINT "jobs_job_type_check" CHECK (("job_type" = ANY (ARRAY['one_off'::"text", 'recurring'::"text"]))),
    CONSTRAINT "jobs_price_basis_check" CHECK (("price_basis" = ANY (ARRAY['job_total'::"text", 'per_visit'::"text", 'fixed_per_period'::"text"]))),
    CONSTRAINT "jobs_price_basis_matches_type" CHECK (((("job_type" = 'one_off'::"text") AND ("price_basis" = 'job_total'::"text")) OR (("job_type" = 'recurring'::"text") AND ("price_basis" = ANY (ARRAY['per_visit'::"text", 'fixed_per_period'::"text"]))))),
    CONSTRAINT "jobs_quote_version_needs_quote" CHECK ((("quote_version_id" IS NULL) OR ("quote_id" IS NOT NULL))),
    CONSTRAINT "jobs_revision_check" CHECK (("revision" >= 0)),
    CONSTRAINT "jobs_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'closed'::"text"]))),
    CONSTRAINT "jobs_subtotal_minor_check" CHECK ((("subtotal_minor" >= 0) AND ("subtotal_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "jobs_tax_check" CHECK (((("tax_rate_basis_points" >= 0) AND ("tax_rate_basis_points" <= 10000)) AND ((("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL)) OR ("tax_name" IS NOT NULL)))),
    CONSTRAINT "jobs_tax_minor_check" CHECK ((("tax_minor" >= 0) AND ("tax_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "jobs_tax_name_check" CHECK ((("tax_name" IS NULL) OR (("char_length"(TRIM(BOTH FROM "tax_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "tax_name")) <= 80)))),
    CONSTRAINT "jobs_tax_source_check" CHECK (("tax_source" = ANY (ARRAY['not_configured'::"text", 'business_default'::"text", 'property_default'::"text", 'saved_rate'::"text", 'no_tax'::"text", 'custom'::"text"]))),
    CONSTRAINT "jobs_tax_source_consistency" CHECK (
CASE "tax_source"
    WHEN 'not_configured'::"text" THEN (("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL) AND ("tax_rate_id" IS NULL))
    WHEN 'no_tax'::"text" THEN (("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL) AND ("tax_rate_id" IS NULL))
    WHEN 'custom'::"text" THEN (("tax_rate_basis_points" > 0) AND ("tax_name" IS NOT NULL) AND ("tax_rate_id" IS NULL))
    WHEN 'saved_rate'::"text" THEN (("tax_rate_basis_points" > 0) AND ("tax_name" IS NOT NULL) AND ("tax_rate_id" IS NOT NULL))
    ELSE ((("tax_rate_basis_points" > 0) AND ("tax_name" IS NOT NULL) AND ("tax_rate_id" IS NOT NULL)) OR (("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL) AND ("tax_rate_id" IS NULL)))
END),
    CONSTRAINT "jobs_title_check" CHECK ((("char_length"(TRIM(BOTH FROM "title")) >= 2) AND ("char_length"(TRIM(BOTH FROM "title")) <= 160))),
    CONSTRAINT "jobs_total_minor_check" CHECK ((("total_minor" >= 0) AND ("total_minor" <= '1000000000000'::bigint)))
);


ALTER TABLE "public"."jobs" OWNER TO "postgres";


COMMENT ON TABLE "public"."jobs" IS 'Job identity and lifecycle. The agreement, never the appointment. Members may read this table and never write it: rows are created by private.create_job and changed by the commands added in later parts, each through its own checked function.';



COMMENT ON COLUMN "public"."jobs"."status" IS 'The only two stored states. Upcoming, Today, Late, Unscheduled, Action required, Requires invoicing, Archived and Ending soon are derived by the reader from visits, reminders and the clock.';



CREATE OR REPLACE FUNCTION "private"."create_job"("target_organization_id" "uuid", "target_client_id" "uuid", "target_property_id" "uuid", "new_title" "text", "new_job_type" "text", "new_price_basis" "text", "new_currency_code" "text", "actor" "uuid", "new_is_as_needed" boolean DEFAULT false, "new_billing_timing" "text" DEFAULT 'on_closure'::"text", "new_instructions" "text" DEFAULT NULL::"text", "source_quote_id" "uuid" DEFAULT NULL::"uuid", "source_quote_version_id" "uuid" DEFAULT NULL::"uuid", "idempotency_key" "text" DEFAULT NULL::"text", "request_hash" "text" DEFAULT NULL::"text") RETURNS "public"."jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  created public.jobs;
  clean_title text := nullif(trim(coalesce(new_title, '')), '');
begin
  if clean_title is null or char_length(clean_title) < 2 or char_length(clean_title) > 160 then
    raise exception 'A job needs a title between 2 and 160 characters.' using errcode = 'check_violation';
  end if;

  -- The property has to belong to the client, and both have to belong to the organization. The composite
  -- foreign keys already stop a cross-tenant row; this stops a same-tenant mismatch with a sentence a person
  -- can act on.
  if not exists (
    select 1 from public.properties
    where id = target_property_id
      and organization_id = target_organization_id
      and client_id = target_client_id
  ) then
    raise exception 'That property does not belong to that client.' using errcode = 'check_violation';
  end if;

  insert into public.jobs (
    organization_id, client_id, property_id, quote_id, quote_version_id, job_number, title,
    job_type, is_as_needed, price_basis, billing_timing, currency_code, instructions,
    conversion_idempotency_key, conversion_request_hash, created_by
  ) values (
    target_organization_id,
    target_client_id,
    target_property_id,
    source_quote_id,
    source_quote_version_id,
    private.allocate_job_number(target_organization_id),
    clean_title,
    new_job_type,
    coalesce(new_is_as_needed, false),
    new_price_basis,
    coalesce(new_billing_timing, 'on_closure'),
    new_currency_code,
    nullif(trim(coalesce(new_instructions, '')), ''),
    idempotency_key,
    request_hash,
    actor
  )
  returning * into created;

  insert into public.job_events (
    organization_id, job_id, event_type, actor_id, new_status, related_quote_id, metadata
  ) values (
    target_organization_id,
    created.id,
    'job_created',
    actor,
    'active',
    source_quote_id,
    jsonb_build_object('job_type', new_job_type, 'from_quote', source_quote_id is not null)
  );

  return created;
end;
$$;


ALTER FUNCTION "private"."create_job"("target_organization_id" "uuid", "target_client_id" "uuid", "target_property_id" "uuid", "new_title" "text", "new_job_type" "text", "new_price_basis" "text", "new_currency_code" "text", "actor" "uuid", "new_is_as_needed" boolean, "new_billing_timing" "text", "new_instructions" "text", "source_quote_id" "uuid", "source_quote_version_id" "uuid", "idempotency_key" "text", "request_hash" "text") OWNER TO "postgres";


