ALTER FUNCTION "private"."create_payment_alerts"("p_organization_id" "uuid", "p_kind" "text", "p_subject_type" "text", "p_subject_id" "uuid", "p_required_permission_1" "text", "p_required_permission_2" "text", "p_source_key" "text", "p_title" "text", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."current_communication_allowance_window"("target_organization_id" "uuid", "at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("window_starts_at" timestamp with time zone, "window_ends_at" timestamp with time zone, "commercial_event_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with zone as (
    select coalesce(
      (
        select settings.commercial_timezone
        from public.organization_commercial_settings as settings
        where settings.organization_id = target_organization_id
      ),
      'UTC'
    ) as name
  ), active_organization as (
    select organization.id, organization.created_at
    from public.organizations as organization
    where organization.id = target_organization_id
      and organization.lifecycle_status = 'active'
  ), local_today as (
    select ((at at time zone (select name from zone))::date) as value
  ), paid_access as (
    select (state.grace_ends_at is not null and state.grace_ends_at > at) as active,
           state.last_event_id
    from public.organization_commercial_state as state
    where state.organization_id = target_organization_id
  ), free_events as (
    select event.id,
           event.target_grant_id,
           event.action,
           event.starts_at,
           event.access_until_date,
           event.occurred_at,
           coalesce(event.target_grant_id, event.id) as root_id
    from public.organization_free_access_events as event
    where event.organization_id = target_organization_id
  ), free_latest as (
    select distinct on (root_id) root_id, action, access_until_date
    from free_events
    order by root_id, occurred_at desc, id desc
  ), free_access as (
    select true as active
    from free_events as root
    join free_latest as latest on latest.root_id = root.id
    where root.target_grant_id is null
      and latest.action <> 'end'
      and root.starts_at <= (select value from local_today)
      and (
        latest.access_until_date is null
        or latest.access_until_date >= (select value from local_today)
      )
    limit 1
  ), anchor as (
    select ((organization.created_at at time zone (select name from zone))::date) as value
    from active_organization as organization
  ), elapsed_months as (
    select (
      extract(year from age((select value from local_today), (select value from anchor))) * 12
      + extract(month from age((select value from local_today), (select value from anchor)))
    )::integer as value
  )
  select
    (
      (((select value from anchor) + make_interval(months => (select value from elapsed_months)))::timestamp)
      at time zone (select name from zone)
    ) as window_starts_at,
    (
      (((select value from anchor) + make_interval(months => (select value from elapsed_months) + 1))::timestamp)
      at time zone (select name from zone)
    ) as window_ends_at,
    (select last_event_id from paid_access) as commercial_event_id
  from active_organization
  where coalesce((select active from paid_access), false)
     or coalesce((select active from free_access), false);
$$;


ALTER FUNCTION "private"."current_communication_allowance_window"("target_organization_id" "uuid", "at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."current_communication_allowance_window"("target_organization_id" "uuid", "at" timestamp with time zone) IS 'The monthly allowance window covering `at` for one organization, anchored on its creation date in its commercial timezone. No row means no current access, and both channels stay fail-closed.';



CREATE OR REPLACE FUNCTION "private"."current_organization"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select membership.organization_id
  from public.organization_members as membership
  join public.organizations as organization
    on organization.id = membership.organization_id
  where membership.user_id = (select auth.uid())
    and membership.status = 'active'
    and organization.lifecycle_status = 'active';
$$;


ALTER FUNCTION "private"."current_organization"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."current_organization"() IS 'The caller''s one active organization, or null. Argument-free on purpose: a policy calls it as (select private.current_organization()) so Postgres evaluates it once per statement instead of once per scanned row. Sound only because organization_members carries UNIQUE (user_id).';



CREATE OR REPLACE FUNCTION "private"."current_permission_scope"("target_permission_key" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(
    (
      select case
        when override.override_state = 'deny' then 'none'
        else override.access_scope
      end
      from public.organization_member_permission_overrides as override
      where override.organization_id = membership.organization_id
        and override.user_id = membership.user_id
        and override.permission_key = target_permission_key
    ),
    (
      select role_permission.access_scope
      from public.role_permissions as role_permission
      where role_permission.role = membership.role
        and role_permission.permission_key = target_permission_key
    ),
    'none'
  )
  from public.organization_members as membership
  where membership.user_id = (select auth.uid())
    and membership.status = 'active';
$$;


ALTER FUNCTION "private"."current_permission_scope"("target_permission_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."current_permission_scope"("target_permission_key" "text") IS 'The caller''s access scope for one permission key: all, assigned or none. Argument-free with respect to the row, so a policy calls it as (select private.current_permission_scope(''key'')) and Postgres evaluates it once per statement. Replaces private.has_permission and private.permission_scope for policy use: scope <> ''none'' is exactly has_permission, because access_scope is NOT NULL on both source tables and a deny override is constrained to access_scope = ''all''.';



CREATE OR REPLACE FUNCTION "private"."deposit_event_available_minor"("target_organization_id" "uuid", "target_deposit_event_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case
    when deposit.event_type <> 'received' then 0
    when exists (
      select 1 from public.quote_deposit_events as reversal
      where reversal.organization_id = deposit.organization_id
        and reversal.reversed_event_id = deposit.id
    ) then 0
    else deposit.amount_minor
      - coalesce((
        select sum(refund.amount_minor)
        from public.client_payment_events as refund
        where refund.organization_id = deposit.organization_id
          and refund.original_deposit_event_id = deposit.id
          and refund.event_type = 'refunded'
          and not exists (
            select 1 from public.client_payment_events as undo
            where undo.organization_id = refund.organization_id
              and undo.original_event_id = refund.id
              and undo.event_type = 'reversed'
          )
      ), 0)
      - coalesce((
        select sum(case when entry.entry_type = 'applied'
          then entry.amount_minor else -entry.amount_minor end)
        from public.invoice_payment_allocations as entry
        where entry.organization_id = deposit.organization_id
          and entry.deposit_event_id = deposit.id
      ), 0)
  end::bigint
  from public.quote_deposit_events as deposit
  where deposit.organization_id = target_organization_id
    and deposit.id = target_deposit_event_id;
$$;


ALTER FUNCTION "private"."deposit_event_available_minor"("target_organization_id" "uuid", "target_deposit_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."effective_marketing_email_limit"("target_organization_id" "uuid", "at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("state" "text", "value" integer, "is_unlimited" boolean, "source" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with assignment as (
    select assignment.package_version_id
    from public.organization_package_assignments as assignment
    where assignment.organization_id = target_organization_id
    order by assignment.effective_at desc, assignment.id desc
    limit 1
  ), active_override as (
    select override.limit_state, override.limit_value, override.is_unlimited
    from public.organization_limit_overrides as override
    where override.organization_id = target_organization_id
      and override.limit_key = 'marketing_email_recipients'
      and override.starts_at <= at
      and (override.expires_at is null or override.expires_at > at)
  ), package_limit as (
    select version_limit.limit_state, version_limit.limit_value
    from public.platform_package_version_limits as version_limit
    where version_limit.package_version_id = (select package_version_id from assignment)
      and version_limit.limit_key = 'marketing_email_recipients'
  )
  select
    coalesce(override.limit_state, package.limit_state, 'not_included'),
    case
      when override.limit_state is not null then override.limit_value
      when package.limit_state = 'numeric' then package.limit_value
    end,
    coalesce(override.is_unlimited, package.limit_state = 'unlimited', false),
    case when override.limit_state is not null then 'override' else 'package' end
  from (select 1) as one
  left join active_override as override on true
  left join package_limit as package on true;
$$;


ALTER FUNCTION "private"."effective_marketing_email_limit"("target_organization_id" "uuid", "at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."effective_marketing_email_limit"("target_organization_id" "uuid", "at" timestamp with time zone) IS 'Single authority for the marketing_email_recipients limit. A missing row is not_included (unset).';



CREATE OR REPLACE FUNCTION "private"."effective_website_chat_conversation_limit"("target_organization_id" "uuid", "at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("state" "text", "value" integer, "is_unlimited" boolean, "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  assignment_package_version_id uuid;
  override_limit_state text;
  override_limit_value integer;
  override_is_unlimited boolean;
  override_found boolean;
  package_limit_state text;
  package_limit_value integer;
  package_found boolean;
begin
  select assignment.package_version_id
  into assignment_package_version_id
  from public.organization_package_assignments as assignment
  where assignment.organization_id = target_organization_id
    and assignment.effective_at <= at
  order by assignment.effective_at desc, assignment.id desc
  limit 1;

  select override.limit_state, override.limit_value, override.is_unlimited
  into override_limit_state, override_limit_value, override_is_unlimited
  from public.organization_limit_overrides as override
  where override.organization_id = target_organization_id
    and override.limit_key = 'website_chat_accepted_conversations'
    and override.starts_at <= at
    and (override.expires_at is null or override.expires_at > at);
  override_found := found;

  if assignment_package_version_id is not null then
    select version_limit.limit_state, version_limit.limit_value
    into package_limit_state, package_limit_value
    from public.platform_package_version_limits as version_limit
    where version_limit.package_version_id = assignment_package_version_id
      and version_limit.limit_key = 'website_chat_accepted_conversations';
    package_found := found;
  else
    package_found := false;
  end if;

  if override_found then
    state := override_limit_state;
    value := override_limit_value;
    is_unlimited := override_is_unlimited;
  elsif package_found then
    state := package_limit_state;
    value := case when package_limit_state = 'numeric' then package_limit_value else null end;
    is_unlimited := package_limit_state = 'unlimited';
  else
    state := 'not_included';
    value := null;
    is_unlimited := false;
  end if;

  source := case when override_found then 'override' else 'package' end;

  return next;
  return;
end;
$$;


