CREATE OR REPLACE FUNCTION "private"."enforce_member_access_event_shape"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  shape public.member_access_event_shapes%rowtype;
  entry record;
  value_kind text;
  missing_keys text;
begin
  select * into shape
  from public.member_access_event_shapes
  where event_type = new.event_type;

  if not found then
    raise exception 'There is no team history shape for %.', new.event_type using errcode = 'check_violation';
  end if;

  if shape.subject_kind = 'member'
    and (new.subject_user_id is null or new.subject_invitation_id is not null) then
    raise exception '% is about a team member and needs exactly one member subject.', new.event_type
      using errcode = 'check_violation';
  end if;

  if shape.subject_kind = 'invitation'
    and (new.subject_invitation_id is null or new.subject_user_id is not null) then
    raise exception '% is about an invitation and needs exactly one invitation subject.', new.event_type
      using errcode = 'check_violation';
  end if;

  if shape.subject_kind = 'organization'
    and num_nonnulls(new.subject_user_id, new.subject_invitation_id) > 0 then
    raise exception '% is about the organization itself and carries no subject.', new.event_type
      using errcode = 'check_violation';
  end if;

  select string_agg(required_key, ', ' order by required_key) into missing_keys
  from unnest(shape.required_summary_keys) as required_key
  where not new.summary ? required_key;

  if missing_keys is not null then
    raise exception '% is missing %.', new.event_type, missing_keys using errcode = 'check_violation';
  end if;

  for entry in select key, value from jsonb_each(new.summary) loop
    value_kind := shape.summary_keys ->> entry.key;

    if value_kind is null then
      raise exception '% may not carry %.', new.event_type, entry.key using errcode = 'check_violation';
    end if;

    if not private.member_access_summary_value_fits(value_kind, entry.value) then
      raise exception '% has an unusable value for %.', new.event_type, entry.key
        using errcode = 'check_violation';
    end if;
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_member_access_event_shape"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."enforce_member_access_event_shape"() IS 'Refuses any team history row whose subject or summary does not match its declared shape. This is what makes "no free text in team history" a database guarantee rather than a convention.';



CREATE OR REPLACE FUNCTION "private"."enqueue_automation_inquiry_email"("p_organization_id" "uuid", "p_client_id" "uuid", "p_logical_send_key" "text", "p_subject" "text", "p_body" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  authority public.organization_automation_authority;
  client_row public.clients;
  recipient public.client_contact_methods;
  sender public.communication_email_senders;
  sender_domain public.communication_email_domains;
  alias public.communication_reply_aliases;
  intent public.communication_delivery_intents;
  business_name text;
  rendered record;
begin
  select * into intent from public.communication_delivery_intents
    where organization_id = p_organization_id and logical_send_key = p_logical_send_key;
  if intent.id is not null then
    return jsonb_build_object('status', 'sent', 'reason', 'already_enqueued', 'intent_id', intent.id);
  end if;

  if coalesce(btrim(p_subject), '') = '' or coalesce(btrim(p_body), '') = '' then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'invalid_email_content');
  end if;

  if not private.organization_has_automations_feature(p_organization_id, now()) then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'automations_not_entitled');
  end if;
  select * into authority from public.organization_automation_authority
    where organization_id = p_organization_id;
  if coalesce(authority.operational_state, 'enabled') <> 'enabled'
    or coalesce(authority.security_state, 'active') <> 'active' then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'automation_suspended');
  end if;

  select * into client_row from public.clients
    where organization_id = p_organization_id and id = p_client_id and deleted_at is null for share;
  select * into recipient from public.client_contact_methods
    where organization_id = p_organization_id and client_id = p_client_id and kind = 'email'
    order by is_primary desc, created_at, id limit 1 for share;
  if client_row.id is null or recipient.id is null then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'no_email_address');
  end if;

  select * into sender from public.communication_email_senders
    where organization_id = p_organization_id and lifecycle_state = 'enabled' and allows_automated
      and is_organization_default
    order by created_at, id limit 1 for share;
  if sender.id is not null then
    select * into sender_domain from public.communication_email_domains
      where organization_id = sender.organization_id and id = sender.domain_id and purpose = 'sending'
        and lifecycle_state = 'verified' and provider_verified and provider_authenticated
        and ownership_status = 'passing' and dkim_status = 'passing' for share;
  end if;
  if sender.id is null or sender_domain.id is null then
    return jsonb_build_object('status', 'skipped_temporary', 'reason', 'email_sender_not_ready');
  end if;

  select organization.name into business_name from public.organizations as organization
    where organization.id = p_organization_id;

  -- No quote exists for an inquiry: quote variables render empty (the Stage 6 validator refuses them).
  select * into rendered from private.render_automation_email(
    p_subject, p_body,
    coalesce(nullif(btrim(client_row.display_name), ''), recipient.normalized_value),
    coalesce(business_name, ''), '', '');

  alias := public.ensure_communication_reply_alias(p_organization_id, sender.id, p_client_id, recipient.id);

  begin
    insert into public.communication_delivery_intents
      (organization_id, client_id, client_contact_method_id, logical_send_key, recipient_email, subject,
       html_content, text_content, send_kind, allowance_class, sender_id, reply_alias_id, created_by)
      values (p_organization_id, p_client_id, recipient.id, p_logical_send_key, recipient.normalized_value,
       rendered.subject, rendered.html_content, rendered.text_content,
       'automated', 'essential', sender.id, alias.id, null)
      returning * into intent;
  exception when unique_violation then
    select * into intent from public.communication_delivery_intents
      where organization_id = p_organization_id and logical_send_key = p_logical_send_key;
    return jsonb_build_object('status', 'sent', 'reason', 'already_enqueued', 'intent_id', intent.id);
  end;

  insert into public.communication_outbox_events (organization_id, delivery_intent_id)
    values (intent.organization_id, intent.id);

  return jsonb_build_object('status', 'sent', 'reason', 'enqueued', 'intent_id', intent.id);
end;
$$;


ALTER FUNCTION "private"."enqueue_automation_inquiry_email"("p_organization_id" "uuid", "p_client_id" "uuid", "p_logical_send_key" "text", "p_subject" "text", "p_body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."enqueue_automation_inquiry_email"("p_organization_id" "uuid", "p_client_id" "uuid", "p_logical_send_key" "text", "p_subject" "text", "p_body" "text") IS 'System-authorized automation email to a website inquiry''s client: entitlement, authority, email address and sender readiness, safe rendering, one intent per logical send key. Returns sent / skipped_permanent / skipped_temporary.';



CREATE OR REPLACE FUNCTION "private"."enqueue_automation_inquiry_message"("p_organization_id" "uuid", "p_client_id" "uuid", "p_key_suffix" "text", "p_config" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  sms_key text := 'automation-inquiry-message-sms:' || p_key_suffix;
  email_key text := 'automation-inquiry-message-email:' || p_key_suffix;
  existing public.communication_delivery_intents;
  authority public.organization_automation_authority;
  client_row public.clients;
  phone public.client_contact_methods;
  business_name text;
  sms_intent public.communication_delivery_intents;
  sms_reason text;
  result jsonb;
begin
  select * into existing from public.communication_delivery_intents
    where organization_id = p_organization_id and logical_send_key in (sms_key, email_key)
    order by created_at limit 1;
  if existing.id is not null then
    return jsonb_build_object('status', 'sent', 'reason', 'already_enqueued', 'channel', existing.channel,
      'intent_id', existing.id);
  end if;

  if p_client_id is null then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'no_customer_record');
  end if;

  if not private.organization_has_automations_feature(p_organization_id, now()) then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'automations_not_entitled');
  end if;
  select * into authority from public.organization_automation_authority
    where organization_id = p_organization_id;
  if coalesce(authority.operational_state, 'enabled') <> 'enabled'
    or coalesce(authority.security_state, 'active') <> 'active' then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'automation_suspended');
  end if;

  select * into client_row from public.clients
    where organization_id = p_organization_id and id = p_client_id and deleted_at is null;
  if client_row.id is null then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'no_customer_record');
  end if;

  if coalesce(btrim(p_config ->> 'sms_body'), '') = '' then
    sms_reason := 'no_sms_copy';
  else
    select * into phone from public.client_contact_methods
      where organization_id = p_organization_id and client_id = p_client_id and kind = 'phone' and is_primary;
    if phone.id is null then
      sms_reason := 'no_mobile_number';
    elsif public.communication_sms_consent_status(p_organization_id, phone.id, 'service') <> 'opted_in' then
      sms_reason := 'no_sms_consent';
    else
      select organization.name into business_name from public.organizations as organization
        where organization.id = p_organization_id;
      begin
        sms_intent := private.communication_sms_enqueue_operational_core(
          p_organization_id, p_client_id, phone.id, null, 'service',
          private.render_automation_sms(
            p_config ->> 'sms_body',
            coalesce(nullif(btrim(client_row.display_name), ''), phone.normalized_value),
            coalesce(business_name, ''), ''),
          'automated', sms_key, null);
        return jsonb_build_object('status', 'sent', 'reason', 'enqueued', 'channel', 'sms',
          'intent_id', sms_intent.id);
      exception
        when object_not_in_prerequisite_state or foreign_key_violation or sqlstate 'P0001' or sqlstate 'P0402' then
          sms_reason := left(sqlerrm, 200);
      end;
    end if;
  end if;

  result := private.enqueue_automation_inquiry_email(
    p_organization_id, p_client_id, email_key, p_config ->> 'email_subject', p_config ->> 'email_body');
  return result || jsonb_build_object('channel', 'email', 'sms_skipped_reason', sms_reason);
end;
$$;


ALTER FUNCTION "private"."enqueue_automation_inquiry_message"("p_organization_id" "uuid", "p_client_id" "uuid", "p_key_suffix" "text", "p_config" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."enqueue_automation_inquiry_message"("p_organization_id" "uuid", "p_client_id" "uuid", "p_key_suffix" "text", "p_config" "jsonb") IS 'Website-inquiry customer message: text if the client is SMS-eligible (copy, primary number, consent, and the shared SMS core accepts it), else email. One text and one email key per step. Returns the plain status shape plus the channel used.';



CREATE OR REPLACE FUNCTION "private"."ensure_communication_allowance_periods"("target_organization_id" "uuid", "at" timestamp with time zone DEFAULT "now"()) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  allowance_window record;
begin
  select * into allowance_window
  from private.current_communication_allowance_window(target_organization_id, at);
  if not found then
    return;
  end if;

  if not exists (
    select 1
    from public.communication_email_allowance_periods as period
    where period.organization_id = target_organization_id
      and period.starts_at <= at
      and period.ends_at > at
  ) then
    insert into public.communication_email_allowance_periods (
      organization_id, starts_at, ends_at, opened_by_commercial_event_id
    )
    values (
      target_organization_id,
      allowance_window.window_starts_at,
      allowance_window.window_ends_at,
      allowance_window.commercial_event_id
    )
    on conflict (organization_id, starts_at) do nothing;
  end if;

  if not exists (
    select 1
    from public.website_chat_allowance_periods as period
    where period.organization_id = target_organization_id
      and period.starts_at <= at
      and period.ends_at > at
  ) then
    insert into public.website_chat_allowance_periods (
      organization_id, starts_at, ends_at, opened_by_commercial_event_id
    )
    values (
      target_organization_id,
      allowance_window.window_starts_at,
      allowance_window.window_ends_at,
      allowance_window.commercial_event_id
    )
    on conflict (organization_id, starts_at) do nothing;
  end if;
end;
$$;


ALTER FUNCTION "private"."ensure_communication_allowance_periods"("target_organization_id" "uuid", "at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."ensure_communication_allowance_periods"("target_organization_id" "uuid", "at" timestamp with time zone) IS 'Opens the current allowance window for both Communications channels, if the organization has access and no period already covers the moment. Idempotent.';



CREATE OR REPLACE FUNCTION "private"."ensure_organization_commercial_rows"("target_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  operational_timezone text;
  baseline_timezone text;
begin
  if not exists (select 1 from public.organizations where id = target_organization_id) then
    raise exception 'Organization % was not found.', target_organization_id
      using errcode = 'foreign_key_violation';
  end if;

  select settings.timezone
  into operational_timezone
  from public.organization_settings as settings
  where settings.organization_id = target_organization_id;

  baseline_timezone := coalesce(nullif(trim(coalesce(operational_timezone, '')), ''), 'UTC');
  if not exists (
    select 1 from pg_catalog.pg_timezone_names as zone where zone.name = baseline_timezone
  ) then
    baseline_timezone := 'UTC';
  end if;

  insert into public.organization_commercial_settings (
    organization_id,
    commercial_timezone,
    timezone_source,
    imported_operational_timezone,
    imported_at
  )
  values (
    target_organization_id,
    baseline_timezone,
    'imported_operational',
    baseline_timezone,
    now()
  )
  on conflict (organization_id) do nothing;

  insert into public.organization_commercial_state (organization_id)
  values (target_organization_id)
  on conflict (organization_id) do nothing;
end;
$$;


