COMMENT ON FUNCTION "private"."ensure_organization_commercial_rows"("target_organization_id" "uuid") IS 'Creates the commercial settings and projection rows for an organization, importing the operational timezone once as the commercial baseline.';



CREATE OR REPLACE FUNCTION "private"."field_record_write_allowed"("target_organization_id" "uuid", "target_record_owner" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select private.has_permission(target_organization_id, 'field_records.manage_team')
    or (
      private.has_permission(target_organization_id, 'field_records.record')
      and (
        target_record_owner is null
        or target_record_owner = (select auth.uid())
      )
    );
$$;


ALTER FUNCTION "private"."field_record_write_allowed"("target_organization_id" "uuid", "target_record_owner" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."field_record_write_allowed"("target_organization_id" "uuid", "target_record_owner" "uuid") IS 'Jobber''s note rule: your own record is yours, and touching somebody else''s is what needs a permission. field_records.manage_team allows any, field_records.record allows the caller''s own. A null owner means the row has no author rather than that it belongs to everyone.';



CREATE TABLE IF NOT EXISTS "public"."organization_member_invitations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "invited_email" "text" NOT NULL,
    "role" "text" NOT NULL,
    "state" "text" DEFAULT 'reserving'::"text" NOT NULL,
    "invited_user_id" "uuid",
    "invited_by" "uuid",
    "token_hash" "text",
    "lease_nonce" "uuid",
    "lease_expires_at" timestamp with time zone,
    "auth_attempt_started_at" timestamp with time zone,
    "identity_cleanup_state" "text" DEFAULT 'not_required'::"text" NOT NULL,
    "identity_cleanup_error" "text",
    "last_sent_at" timestamp with time zone,
    "last_delivery_error" "text",
    "expires_at" timestamp with time zone,
    "accepted_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "auth_attempt_nonce" "uuid",
    "password_set_at" timestamp with time zone,
    "requested_permission_overrides" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "reconciliation_nonce" "uuid",
    "reconciliation_lease_expires_at" timestamp with time zone,
    CONSTRAINT "organization_member_invitations_accepted_at_check" CHECK ((("state" = 'accepted'::"text") = ("accepted_at" IS NOT NULL))),
    CONSTRAINT "organization_member_invitations_cancelled_at_check" CHECK ((("state" = 'cancelled'::"text") = ("cancelled_at" IS NOT NULL))),
    CONSTRAINT "organization_member_invitations_identity_cleanup_state_check" CHECK (("identity_cleanup_state" = ANY (ARRAY['not_required'::"text", 'required'::"text", 'ban_applied'::"text", 'email_released'::"text", 'done'::"text"]))),
    CONSTRAINT "organization_member_invitations_identity_matches_state_check" CHECK (((("state" = 'reserving'::"text") AND ("invited_user_id" IS NULL)) OR (("state" = ANY (ARRAY['invited'::"text", 'accepting'::"text", 'accepted'::"text"])) AND ("invited_user_id" IS NOT NULL)) OR ("state" = ANY (ARRAY['cancelled'::"text", 'expired'::"text", 'abandoned'::"text"])))),
    CONSTRAINT "organization_member_invitations_invited_email_check" CHECK (((("char_length"(TRIM(BOTH FROM "invited_email")) >= 3) AND ("char_length"(TRIM(BOTH FROM "invited_email")) <= 254)) AND ("invited_email" ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'::"text"))),
    CONSTRAINT "organization_member_invitations_password_set_requires_identity_" CHECK ((("password_set_at" IS NULL) OR ("invited_user_id" IS NOT NULL))),
    CONSTRAINT "organization_member_invitations_reconciliation_lease_pair_check" CHECK (((("reconciliation_nonce" IS NULL) AND ("reconciliation_lease_expires_at" IS NULL)) OR (("reconciliation_nonce" IS NOT NULL) AND ("reconciliation_lease_expires_at" IS NOT NULL)))),
    CONSTRAINT "organization_member_invitations_requested_overrides_array_check" CHECK (("jsonb_typeof"("requested_permission_overrides") = 'array'::"text")),
    CONSTRAINT "organization_member_invitations_role_check" CHECK (("role" = ANY (ARRAY['admin'::"text", 'office'::"text", 'sales'::"text", 'field'::"text", 'finance'::"text"]))),
    CONSTRAINT "organization_member_invitations_state_check" CHECK (("state" = ANY (ARRAY['reserving'::"text", 'invited'::"text", 'accepting'::"text", 'accepted'::"text", 'cancelled'::"text", 'expired'::"text", 'abandoned'::"text"])))
);


ALTER TABLE "public"."organization_member_invitations" OWNER TO "postgres";


COMMENT ON COLUMN "public"."organization_member_invitations"."state" IS 'reserving (no identity yet) -> invited (identity + delivery attempted) -> accepting (leased claim) -> accepted, or cancelled/expired/abandoned. See parts/03a-access-and-data-foundation.md invariants table.';



COMMENT ON COLUMN "public"."organization_member_invitations"."token_hash" IS 'sha256 hex of the acceptance token, following issueSetupLink (src/lib/server/jafar/setup-link.ts). The raw token is never stored.';



COMMENT ON COLUMN "public"."organization_member_invitations"."auth_attempt_started_at" IS 'Orphan Rule: stamped immediately before calling Auth. The sweep may only release the seat and mark abandoned while this is null; otherwise identity_cleanup_state moves to required and the seat stays held.';



COMMENT ON COLUMN "public"."organization_member_invitations"."last_delivery_error" IS 'Non-null while state = invited means the blueprint''s visible Delivery failed state. No separate enum value, matching issueSetupLink''s last_error convention.';



COMMENT ON COLUMN "public"."organization_member_invitations"."auth_attempt_nonce" IS 'Set by mark_team_invitation_auth_attempt_started immediately before an Auth call. Each call supersedes the last, so attach_team_invitation_identity can reject a stale attempt that finishes late.';



COMMENT ON COLUMN "public"."organization_member_invitations"."password_set_at" IS 'Stamped by record_invitation_password_set once Auth confirms the password write. Required by finalize_team_invitation -- an accepting row with a lapsed lease and no stamp is ambiguous, not expired.';



COMMENT ON COLUMN "public"."organization_member_invitations"."requested_permission_overrides" IS 'Validated invitation-time adjustments copied atomically to the pending membership when Auth identity attachment succeeds.';



COMMENT ON COLUMN "public"."organization_member_invitations"."reconciliation_nonce" IS 'Short worker lease. It coordinates Auth cleanup without holding a database transaction across the network call.';



CREATE OR REPLACE FUNCTION "private"."finalize_accepted_invitation"("target_invitation_id" "uuid") RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_row public.organization_member_invitations;
begin
  update public.organization_member_invitations
  set state = 'accepted', accepted_at = now()
  where id = target_invitation_id and state = 'accepting' and password_set_at is not null
  returning * into updated_row;

  if found then
    update public.organization_members
    set status = 'active', status_changed_at = now()
    where organization_id = updated_row.organization_id
      and user_id = updated_row.invited_user_id
      and status = 'pending';

    insert into public.organization_member_access_events (
      organization_id, event_type, actor_kind, actor_user_id, subject_invitation_id, summary
    )
    values (
      updated_row.organization_id, 'invitation.accepted', 'member', updated_row.invited_user_id,
      updated_row.id, jsonb_build_object('role', updated_row.role)
    );

    return updated_row;
  end if;

  select * into updated_row
  from public.organization_member_invitations
  where id = target_invitation_id;

  return updated_row;
end;
$$;


ALTER FUNCTION "private"."finalize_accepted_invitation"("target_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."financial_job_profitability_candidates"("target_organization_id" "uuid", "report_from" "date", "report_to" "date", "zone" "text", "window_start" timestamp with time zone, "window_end" timestamp with time zone) RETURNS TABLE("job_id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select job.id
  from public.jobs as job
  where job.organization_id = target_organization_id
    and job.status = 'closed'
    and job.price_basis = 'job_total'
    and job.closed_at >= window_start and job.closed_at < window_end
  union
  select visit.job_id
  from public.job_visits as visit
  join public.jobs as job
    on job.organization_id = visit.organization_id and job.id = visit.job_id
  where visit.organization_id = target_organization_id
    and visit.completed_at is not null
    and job.price_basis = 'per_visit'
    and coalesce(visit.visit_date, (visit.completed_at at time zone zone)::date) >= report_from
    and coalesce(visit.visit_date, (visit.completed_at at time zone zone)::date) < report_to
  union
  select reminder.job_id
  from public.job_invoice_reminders as reminder
  join public.jobs as job
    on job.organization_id = reminder.organization_id and job.id = reminder.job_id
  where reminder.organization_id = target_organization_id
    and reminder.reminder_kind in ('monthly_last_day', 'custom_date')
    and reminder.due_on >= report_from and reminder.due_on < report_to
    and job.price_basis = 'fixed_per_period'
  union
  select entry.job_id
  from public.job_time_entries as entry
  join public.jobs as job
    on job.organization_id = entry.organization_id and job.id = entry.job_id
  where entry.organization_id = target_organization_id
    and entry.started_at >= window_start and entry.started_at < window_end
    and job.price_basis <> 'job_total'
  union
  select expense.job_id
  from public.job_expenses as expense
  join public.jobs as job
    on job.organization_id = expense.organization_id and job.id = expense.job_id
  where expense.organization_id = target_organization_id
    and expense.expense_date >= report_from and expense.expense_date < report_to
    and job.price_basis <> 'job_total';
$$;


ALTER FUNCTION "private"."financial_job_profitability_candidates"("target_organization_id" "uuid", "report_from" "date", "report_to" "date", "zone" "text", "window_start" timestamp with time zone, "window_end" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."financial_job_profitability_candidates"("target_organization_id" "uuid", "report_from" "date", "report_to" "date", "zone" "text", "window_start" timestamp with time zone, "window_end" timestamp with time zone) IS 'Distinct Jobs with revenue, labor or expenses inside a report range: closed whole-price Jobs by closure instant, recurring Jobs by in-range completed Visits, due periods, labor or expenses.';



CREATE OR REPLACE FUNCTION "private"."financial_job_profitability_rows"("target_organization_id" "uuid", "target_job_ids" "uuid"[], "report_from" "date", "report_to" "date", "zone" "text", "window_start" timestamp with time zone, "window_end" timestamp with time zone) RETURNS TABLE("job_id" "uuid", "unit_count" integer, "revenue_minor" bigint, "item_cost_minor" bigint, "labor_cost_minor" bigint, "labor_minutes" bigint, "unrated_labor_count" bigint, "unrated_labor_minutes" bigint, "expense_cost_minor" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    job.id,
    case job.price_basis
      when 'job_total' then null::integer
      when 'per_visit' then visits.unit_count
      else periods.unit_count
    end,
    case job.price_basis
      when 'job_total' then job.total_minor - job.tax_minor
      when 'per_visit' then visits.revenue_minor
      else case when periods.unit_count > 0 then period_lines.price_minor * periods.unit_count end
    end,
    case job.price_basis
      when 'job_total' then job.cost_minor
      when 'per_visit' then visits.item_cost_minor
      else period_lines.cost_minor * periods.unit_count
    end,
    labor.cost_minor,
    labor.minutes,
    labor.unrated_count,
    labor.unrated_minutes,
    expense.cost_minor
  from public.jobs as job
  cross join lateral (
    select count(*)::integer as unit_count,
      coalesce(sum(priced.revenue_minor), 0)::bigint as revenue_minor,
      coalesce(sum(priced.item_cost_minor), 0)::bigint as item_cost_minor
    from public.job_visits as visit
    cross join lateral (
      select coalesce(sum(line.line_total_minor), 0) as revenue_minor,
        coalesce(sum(public.pricing_line_total_minor(line.quantity, line.unit_cost_minor)), 0) as item_cost_minor
      from private.job_visit_effective_lines(job.organization_id, job.id, visit.id) as line
      where line.line_kind = 'priced'
    ) as priced
    where job.price_basis = 'per_visit'
      and visit.organization_id = job.organization_id
      and visit.job_id = job.id
      and visit.completed_at is not null
      and coalesce(visit.visit_date, (visit.completed_at at time zone zone)::date) >= report_from
      and coalesce(visit.visit_date, (visit.completed_at at time zone zone)::date) < report_to
  ) as visits
  cross join lateral (
    select count(*)::integer as unit_count
    from public.job_invoice_reminders as reminder
    where job.price_basis = 'fixed_per_period'
      and reminder.organization_id = job.organization_id
      and reminder.job_id = job.id
      and reminder.reminder_kind in ('monthly_last_day', 'custom_date')
      and reminder.due_on >= report_from and reminder.due_on < report_to
  ) as periods
  cross join lateral (
    select coalesce(sum(line.line_total_minor), 0)::bigint as price_minor,
      coalesce(sum(line.line_cost_total_minor), 0)::bigint as cost_minor
    from public.job_line_items as line
    where job.price_basis = 'fixed_per_period'
      and line.organization_id = job.organization_id
      and line.job_id = job.id
      and line.line_kind = 'priced'
  ) as period_lines
  cross join lateral (
    select coalesce(sum(entry.cost_total_minor), 0)::bigint as cost_minor,
      coalesce(sum(entry.minutes), 0)::bigint as minutes,
      count(*) filter (where entry.cost_per_hour_minor is null) as unrated_count,
      coalesce(sum(entry.minutes) filter (where entry.cost_per_hour_minor is null), 0)::bigint as unrated_minutes
    from public.job_time_entries as entry
    where entry.organization_id = job.organization_id
      and entry.job_id = job.id
      and (job.price_basis = 'job_total'
        or (entry.started_at >= window_start and entry.started_at < window_end))
  ) as labor
  cross join lateral (
    select coalesce(sum(expense.total_minor), 0)::bigint as cost_minor
    from public.job_expenses as expense
    where expense.organization_id = job.organization_id
      and expense.job_id = job.id
      and (job.price_basis = 'job_total'
        or (expense.expense_date >= report_from and expense.expense_date < report_to))
  ) as expense
  where job.organization_id = target_organization_id
    and job.id = any(target_job_ids);
$$;


ALTER FUNCTION "private"."financial_job_profitability_rows"("target_organization_id" "uuid", "target_job_ids" "uuid"[], "report_from" "date", "report_to" "date", "zone" "text", "window_start" timestamp with time zone, "window_end" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."financial_job_profitability_rows"("target_organization_id" "uuid", "target_job_ids" "uuid"[], "report_from" "date", "report_to" "date", "zone" "text", "window_start" timestamp with time zone, "window_end" timestamp with time zone) IS 'Per-Job revenue, unit count, item cost, rated labor, unrated labor disclosure and expenses for a report range, paired per pricing basis exactly as public.job_costing pairs them. Revenue is null for a fixed-per-period Job with no period in range.';



CREATE OR REPLACE FUNCTION "private"."form_booking_day_bands"("target_organization_id" "uuid", "target_hours_mode" "text", "target_day" "date", "target_weekday" smallint) RETURNS "tsrange"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  bands tsrange[] := '{}';
  hours_row record;
  band_start timestamp;
  band_end timestamp;
begin
  -- "By appointment" means the business made a deliberate choice not to keep fixed hours -- the open window
  -- is the whole day, and member availability alone decides what is actually offered.
  if target_hours_mode = 'appointment_only' then
    return array[tsrange(target_day::timestamp, (target_day + 1)::timestamp, '[)')];
  end if;

  if target_hours_mode <> 'weekly' then
    return bands;
  end if;

  for hours_row in
    select *
    from public.organization_business_hours as hours
    where hours.organization_id = target_organization_id
      and hours.weekday = target_weekday
      and hours.is_open
    order by hours.period_index
  loop
    if hours_row.is_open_24h then
      band_start := target_day::timestamp;
      band_end := (target_day + 1)::timestamp;
    else
      band_start := target_day + hours_row.opens_at;
      -- A closing time at or before the opening time is the schema's way of saying the period runs past
      -- midnight (organization_business_hours_shape allows this on purpose -- see 20260822001257).
      band_end := case
        when hours_row.closes_at > hours_row.opens_at then target_day + hours_row.closes_at
        else (target_day + 1) + hours_row.closes_at
      end;
    end if;
    bands := bands || tsrange(band_start, band_end, '[)');
  end loop;

  return bands;
end;
$$;


ALTER FUNCTION "private"."form_booking_day_bands"("target_organization_id" "uuid", "target_hours_mode" "text", "target_day" "date", "target_weekday" smallint) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."form_booking_day_bands"("target_organization_id" "uuid", "target_hours_mode" "text", "target_day" "date", "target_weekday" smallint) IS 'The open local-time window(s) for one weekday under the organization''s confirmed hours mode. Business hours periods are pre-validated non-overlapping and ordered at save time, so they are trusted as given.';



CREATE OR REPLACE FUNCTION "private"."form_booking_free_member_for_slot"("target_organization_id" "uuid", "candidate_start" timestamp without time zone, "candidate_end" timestamp without time zone, "buffer_minutes" integer, "target_timezone" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  slot_buffer interval := make_interval(mins => buffer_minutes);
  padded_start timestamp := candidate_start - slot_buffer;
  padded_end timestamp := candidate_end + slot_buffer;
  member_id uuid;
begin
  for member_id in
    select membership.user_id
    from public.organization_members as membership
    where membership.organization_id = target_organization_id
      and membership.status = 'active'
    order by membership.user_id
  loop
    if not private.form_booking_member_is_available(
      target_organization_id, member_id, candidate_start, candidate_end
    ) then
      continue;
    end if;

    if exists (
      select 1
      from public.assessment_assignees as assignee
      join public.assessments as assessment on assessment.id = assignee.assessment_id
      where assignee.organization_id = target_organization_id
        and assignee.user_id = member_id
        and assessment.completed_at is null
        and assessment.starts_at is not null
        and (assessment.starts_at at time zone target_timezone) < padded_end
        and (assessment.ends_at at time zone target_timezone) > padded_start
    ) then
      continue;
    end if;

    if exists (
      select 1
      from public.job_visit_assignments as assignment
      join public.job_visits as visit on visit.id = assignment.visit_id
      where assignment.organization_id = target_organization_id
        and assignment.user_id = member_id
        and visit.completed_at is null
        and visit.start_time is not null
        and (visit.visit_date + visit.start_time) < padded_end
        and (visit.visit_date + coalesce(visit.end_time, visit.start_time)) > padded_start
    ) then
      continue;
    end if;

    return member_id;
  end loop;

  return null;
end;
$$;


ALTER FUNCTION "private"."form_booking_free_member_for_slot"("target_organization_id" "uuid", "candidate_start" timestamp without time zone, "candidate_end" timestamp without time zone, "buffer_minutes" integer, "target_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."form_booking_member_is_available"("target_organization_id" "uuid", "target_user_id" "uuid", "candidate_start" timestamp without time zone, "candidate_end" timestamp without time zone) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  slot_day date := candidate_start::date;
  exception_row public.organization_member_availability_exceptions;
  weekly_row public.organization_member_availability;
begin
  -- Availability is only ever modelled as a same-day band -- there is no overnight shift concept, unlike
  -- business hours. A slot that crosses midnight (only reachable from an overnight business-hours period)
  -- cannot be honestly checked against a same-day pattern, so nobody is considered available for it.
  if candidate_end::date <> slot_day then
    return false;
  end if;

  select * into exception_row
  from public.organization_member_availability_exceptions as exception_table
  where exception_table.organization_id = target_organization_id
    and exception_table.user_id = target_user_id
    and exception_table.exception_date = slot_day;

  if found then
    if not exception_row.is_working then
      return false;
    end if;
    return candidate_start >= (slot_day + exception_row.starts_at)
      and candidate_end <= (slot_day + exception_row.ends_at);
  end if;

  select * into weekly_row
  from public.organization_member_availability as weekly_table
  where weekly_table.organization_id = target_organization_id
    and weekly_table.user_id = target_user_id
    and weekly_table.weekday = extract(dow from slot_day)::smallint;

  -- No row at all means nobody has set a pattern for this person, which the rest of the product already
  -- treats as "nothing to warn about" rather than a default nine-to-five -- so it places no restriction here.
  if not found then
    return true;
  end if;

  if not weekly_row.is_working then
    return false;
  end if;

  return candidate_start >= (slot_day + weekly_row.starts_at)
    and candidate_end <= (slot_day + weekly_row.ends_at);
end;
$$;


ALTER FUNCTION "private"."form_booking_member_is_available"("target_organization_id" "uuid", "target_user_id" "uuid", "candidate_start" timestamp without time zone, "candidate_end" timestamp without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."form_booking_slot_blocked_by_team_event"("target_organization_id" "uuid", "candidate_start" timestamp without time zone, "candidate_end" timestamp without time zone, "buffer_minutes" integer) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public.schedule_events as event
    where event.organization_id = target_organization_id
      and event.start_time is not null
      and (event.event_date + event.start_time) - make_interval(mins => buffer_minutes) < candidate_end
      and (event.event_date + coalesce(event.end_time, event.start_time))
        + make_interval(mins => buffer_minutes) > candidate_start
  );
$$;


ALTER FUNCTION "private"."form_booking_slot_blocked_by_team_event"("target_organization_id" "uuid", "candidate_start" timestamp without time zone, "candidate_end" timestamp without time zone, "buffer_minutes" integer) OWNER TO "postgres";


