CREATE OR REPLACE FUNCTION "private"."invoice_allocated_minor"("target_organization_id" "uuid", "target_invoice_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(
    sum(case when entry_type = 'applied' then amount_minor else -amount_minor end), 0
  )::bigint
  from public.invoice_payment_allocations
  where organization_id = target_organization_id
    and invoice_id = target_invoice_id;
$$;


ALTER FUNCTION "private"."invoice_allocated_minor"("target_organization_id" "uuid", "target_invoice_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."invoice_allocated_minor"("target_organization_id" "uuid", "target_invoice_id" "uuid") IS 'Money currently applied to this invoice, in minor units: applications less unapplications. The only answer to that question in the product; callers never read the allocation table directly.';



CREATE OR REPLACE FUNCTION "private"."invoice_customer_document"("invoice_row" "public"."invoices", "business_name" "text", "derived_status" "text", "include_money" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  deposit_applied_minor bigint := 0;
  payment_received_minor bigint := 0;
  progress jsonb;
begin
  if include_money then
    select
      coalesce(sum(case when entry.deposit_event_id is not null then signed else 0 end), 0),
      coalesce(sum(case when entry.payment_event_id is not null then signed else 0 end), 0)
    into deposit_applied_minor, payment_received_minor
    from (
      select
        allocation.deposit_event_id,
        allocation.payment_event_id,
        case when allocation.entry_type = 'applied'
          then allocation.amount_minor else -allocation.amount_minor end as signed
      from public.invoice_payment_allocations as allocation
      where allocation.organization_id = invoice_row.organization_id
        and allocation.invoice_id = invoice_row.id
    ) as entry;
  end if;

  progress := private.invoice_progress_context(invoice_row);

  return jsonb_build_object(
    'business', jsonb_build_object('name', business_name),
    'invoice', jsonb_build_object(
      'invoice_number', invoice_row.invoice_number,
      'subject', invoice_row.subject,
      'currency_code', invoice_row.currency_code,
      'status', derived_status,
      'issue_date', invoice_row.issue_date,
      'due_date', invoice_row.due_date,
      'due_date_source', invoice_row.due_date_source,
      'payment_term_snapshot', invoice_row.payment_term_snapshot,
      'contract_disclaimer', invoice_row.contract_disclaimer
    ),
    'customer', invoice_row.customer_snapshot,
    'billing_address', invoice_row.billing_address_snapshot,
    'service_properties', invoice_row.service_properties,
    -- Which stage of the agreed payment schedule this bill is. Named, numbered, and nothing about the
    -- stages that come after it.
    'progress', case when progress is null then null else jsonb_build_object(
      'installment_number', progress -> 'installment_number',
      'description', progress -> 'description',
      'is_deposit', progress -> 'is_deposit'
    ) end,
    'lines', (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'line_id', line.id,
          'position', line.position,
          'line_kind', line.line_kind,
          'name', line.name,
          'description', line.description,
          'unit_label', line.unit_label,
          'quantity', line.quantity,
          'service_date', line.service_date
        )
        || case when include_money
             then jsonb_build_object(
               'unit_price_minor', line.unit_price_minor,
               'line_total_minor', line.line_total_minor)
             else '{}'::jsonb end
        -- The whole item, beside the share this bill asks for. Only on a progress bill, and only with the
        -- rest of the money.
        || case when include_money and progress is not null
             then jsonb_build_object(
               'progress_original_amount_minor', line.progress_original_amount_minor)
             else '{}'::jsonb end
        order by line.position, line.id
      ), '[]'::jsonb)
      from public.invoice_lines as line
      where line.organization_id = invoice_row.organization_id
        and line.invoice_id = invoice_row.id
    ),
    'money', case when include_money then jsonb_build_object(
      'subtotal_minor', invoice_row.subtotal_minor,
      'discount', case when invoice_row.discount_minor > 0 then jsonb_build_object(
        'name', invoice_row.discount_name,
        'type', invoice_row.discount_type,
        'value', invoice_row.discount_value,
        'amount_minor', invoice_row.discount_minor
      ) else null end,
      'tax', case when invoice_row.tax_minor > 0 then jsonb_build_object(
        'name', invoice_row.tax_name,
        'rate_basis_points', invoice_row.tax_rate_basis_points,
        'amount_minor', invoice_row.tax_minor
      ) else null end,
      'total_minor', invoice_row.total_minor,
      'deposit_applied_minor', deposit_applied_minor,
      'payment_received_minor', payment_received_minor,
      'balance_due_minor', invoice_row.total_minor - deposit_applied_minor - payment_received_minor
    ) else null end
  );
end;
$$;


ALTER FUNCTION "private"."invoice_customer_document"("invoice_row" "public"."invoices", "business_name" "text", "derived_status" "text", "include_money" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."invoice_customer_document"("invoice_row" "public"."invoices", "business_name" "text", "derived_status" "text", "include_money" boolean) IS 'The only definition of what a customer may see on a bill. Called by public.resolve_invoice_access_link for the customer and by public.invoice_customer_preview for staff. No cost, no margin, no internal note and no other client may ever be added here. Money is left out whole when include_money is false.';



CREATE OR REPLACE FUNCTION "private"."invoice_document_snapshot"("target_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  invoice_row public.invoices;
begin
  select * into invoice_row from public.invoices where id = target_invoice_id;
  if not found then
    raise exception 'That invoice was not found.' using errcode = 'P0404';
  end if;

  return jsonb_build_object(
    'invoice_id', invoice_row.id,
    'invoice_number', invoice_row.invoice_number,
    'revision', invoice_row.revision,
    'subject', invoice_row.subject,
    'currency_code', invoice_row.currency_code,
    'issue_date', invoice_row.issue_date,
    'due_date', invoice_row.due_date,
    'due_date_source', invoice_row.due_date_source,
    'payment_term_snapshot', invoice_row.payment_term_snapshot,
    'contract_disclaimer', invoice_row.contract_disclaimer,
    'customer_snapshot', invoice_row.customer_snapshot,
    'billing_address_snapshot', invoice_row.billing_address_snapshot,
    'service_properties', invoice_row.service_properties,
    'discount', jsonb_build_object(
      'name', invoice_row.discount_name,
      'type', invoice_row.discount_type,
      'value', invoice_row.discount_value
    ),
    'tax', jsonb_build_object(
      'source', invoice_row.tax_source,
      'name', invoice_row.tax_name,
      'rate_basis_points', invoice_row.tax_rate_basis_points
    ),
    'totals', jsonb_build_object(
      'subtotal_minor', invoice_row.subtotal_minor,
      'discount_minor', invoice_row.discount_minor,
      'tax_minor', invoice_row.tax_minor,
      'total_minor', invoice_row.total_minor
    ),
    'lines', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'line_id', line.id,
        'position', line.position,
        'line_kind', line.line_kind,
        'category', line.category,
        'name', line.name,
        'description', line.description,
        'unit_label', line.unit_label,
        'quantity', line.quantity,
        'unit_price_minor', line.unit_price_minor,
        'is_taxable', line.is_taxable,
        'service_date', line.service_date,
        'line_total_minor', line.line_total_minor
      ) order by line.position, line.id), '[]'::jsonb)
      from public.invoice_lines as line
      where line.organization_id = invoice_row.organization_id
        and line.invoice_id = invoice_row.id
    )
  );
end;
$$;


ALTER FUNCTION "private"."invoice_document_snapshot"("target_invoice_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."invoice_payment_terms" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "rule" "text" NOT NULL,
    "net_days" integer,
    "is_protected" boolean DEFAULT false NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    "archived_at" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "invoice_payment_terms_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "name")) >= 2) AND ("char_length"(TRIM(BOTH FROM "name")) <= 60))),
    CONSTRAINT "invoice_payment_terms_net_days_check" CHECK ((("net_days" IS NULL) OR (("net_days" >= 1) AND ("net_days" <= 365)))),
    CONSTRAINT "invoice_payment_terms_position_check" CHECK (("position" >= 0)),
    CONSTRAINT "invoice_payment_terms_protected_is_calendar" CHECK (((NOT "is_protected") OR ("rule" = ANY (ARRAY['on_receipt'::"text", 'month_end'::"text", 'next_month_end'::"text"])))),
    CONSTRAINT "invoice_payment_terms_rule_check" CHECK (("rule" = ANY (ARRAY['on_receipt'::"text", 'net_days'::"text", 'month_end'::"text", 'next_month_end'::"text"]))),
    CONSTRAINT "invoice_payment_terms_rule_shape" CHECK (((("rule" = 'net_days'::"text") AND ("net_days" IS NOT NULL)) OR (("rule" <> 'net_days'::"text") AND ("net_days" IS NULL))))
);


ALTER TABLE "public"."invoice_payment_terms" OWNER TO "postgres";


COMMENT ON TABLE "public"."invoice_payment_terms" IS 'Organization-owned named payment terms. The three calendar rules are seeded protected rows so every organization can always resolve a due date; net terms are ordinary rows staff may add, rename or remove.';



CREATE OR REPLACE FUNCTION "private"."invoice_due_date"("issue_date" "date", "term" "public"."invoice_payment_terms") RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case term.rule
    when 'on_receipt' then issue_date
    when 'net_days' then issue_date + term.net_days
    when 'month_end' then (date_trunc('month', issue_date::timestamp) + interval '1 month - 1 day')::date
    when 'next_month_end'
      then (date_trunc('month', issue_date::timestamp) + interval '2 months - 1 day')::date
  end;
$$;


ALTER FUNCTION "private"."invoice_due_date"("issue_date" "date", "term" "public"."invoice_payment_terms") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."invoice_due_date"("issue_date" "date", "term" "public"."invoice_payment_terms") IS 'The only due-date arithmetic in the product. Takes an organization-local issue date and a term row; never reads the clock, so no caller can leak a server or browser timezone into a due date.';



