CREATE OR REPLACE FUNCTION "private"."invoice_live_status"("voided_at" timestamp with time zone, "written_off_at" timestamp with time zone, "issued_at" timestamp with time zone, "recognized_at" timestamp with time zone, "marked_received_at" timestamp with time zone, "total_minor" bigint, "allocated_minor" bigint, "due_date" "date", "today" "date") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when voided_at is not null then 'voided'
    when written_off_at is not null then 'bad_debt'
    when issued_at is null and recognized_at is null then 'draft'
    -- Status-only closure. It extinguishes no debt, but the label the contractor sees is Paid.
    when marked_received_at is not null then 'paid'
    when allocated_minor >= total_minor then 'paid'
    when due_date < today then 'past_due'
    else 'awaiting_payment'
  end;
$$;


ALTER FUNCTION "private"."invoice_live_status"("voided_at" timestamp with time zone, "written_off_at" timestamp with time zone, "issued_at" timestamp with time zone, "recognized_at" timestamp with time zone, "marked_received_at" timestamp with time zone, "total_minor" bigint, "allocated_minor" bigint, "due_date" "date", "today" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."invoice_live_status"("voided_at" timestamp with time zone, "written_off_at" timestamp with time zone, "issued_at" timestamp with time zone, "recognized_at" timestamp with time zone, "marked_received_at" timestamp with time zone, "total_minor" bigint, "allocated_minor" bigint, "due_date" "date", "today" "date") IS 'The one rule for an invoice''s live contract status, as a pure function of its facts. Shared by private.invoice_status_label and the list/overview readers so a bill''s label is derived one way everywhere. A replaced bill''s frozen label is handled by its readers, not here.';



CREATE OR REPLACE FUNCTION "private"."invoice_progress_context"("invoice_row" "public"."invoices") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  -- Served by invoice_sources_root_idx (organization_id, root_invoice_id, source_kind, id), then the stage's
  -- own (organization_id, id) unique constraint. At most one installment claim exists per chain.
  select jsonb_build_object(
    'job_id', claim.job_id,
    'installment_id', claim.installment_id,
    'installment_number', claim.installment_number,
    'description', stage.description,
    'is_deposit', stage.is_deposit
  )
  from public.invoice_sources as claim
  join public.job_payment_schedule_items as stage
    on stage.organization_id = claim.organization_id and stage.id = claim.installment_id
  where claim.organization_id = invoice_row.organization_id
    and claim.root_invoice_id = invoice_row.root_invoice_id
    and claim.source_kind = 'installment'
  limit 1;
$$;


ALTER FUNCTION "private"."invoice_progress_context"("invoice_row" "public"."invoices") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."invoice_progress_context"("invoice_row" "public"."invoices") IS 'The payment stage a progress invoice bills, or null for an ordinary bill. Read live because both facts it returns are already permanent: the claim freezes the stage number and the guard trigger freezes the stage description once a claim exists. Carries no amount -- the money is on the invoice.';



