CREATE OR REPLACE FUNCTION "private"."job_derived_status"("stored_status" "text", "job_type" "text", "contract_end_date" "date", "today" "date", "has_due_reminder" boolean) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when stored_status = 'closed' and has_due_reminder then 'requires_invoicing'
    when stored_status = 'closed' then 'archived'
    when job_type = 'recurring'
      and contract_end_date is not null
      and contract_end_date >= today
      and contract_end_date <= today + 30 then 'ending_soon'
    when has_due_reminder then 'requires_invoicing'
    else 'unscheduled'
  end;
$$;


ALTER FUNCTION "private"."job_derived_status"("stored_status" "text", "job_type" "text", "contract_end_date" "date", "today" "date", "has_due_reminder" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."job_derived_status"("stored_status" "text", "job_type" "text", "contract_end_date" "date", "today" "date", "has_due_reminder" boolean) IS 'The job status a person reads, derived and never stored. A due invoice reminder shows as Requires invoicing (and outranks Archived on a closed-but-unbilled job); Archived otherwise wins on a closed job; a recurring agreement ending within 30 days beats an active Requires invoicing; everything else is Unscheduled.';



CREATE OR REPLACE FUNCTION "private"."job_document_snapshot"("target_organization_id" "uuid", "target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  job_row public.jobs;
  client_row public.clients;
  property_row public.properties;
begin
  select * into job_row
  from public.jobs
  where organization_id = target_organization_id and id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  select * into client_row
  from public.clients
  where organization_id = target_organization_id and id = job_row.client_id;

  select * into property_row
  from public.properties
  where organization_id = target_organization_id and id = job_row.property_id;

  return jsonb_build_object(
    'job_id', job_row.id,
    'job_number', job_row.job_number,
    'title', job_row.title,
    'job_type', job_row.job_type,
    'instructions', job_row.instructions,
    'currency_code', job_row.currency_code,
    'client', jsonb_build_object(
      'client_id', client_row.id,
      'display_name', client_row.display_name,
      'company_name', client_row.company_name,
      'first_name', client_row.first_name,
      'last_name', client_row.last_name
    ),
    'property', jsonb_build_object(
      'property_id', property_row.id,
      'label', property_row.label,
      'address_line1', property_row.address_line1,
      'address_line2', property_row.address_line2,
      'city', property_row.city,
      'state_region', property_row.state_region,
      'postal_code', property_row.postal_code,
      'country', property_row.country
    ),
    'lines', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'line_id', line.id,
        'position', line.position,
        'line_kind', line.line_kind,
        'category', line.category,
        'name', line.name,
        'description', line.description,
        'unit_label', line.unit_label,
        'quantity', line.quantity,
        'unit_price_minor', line.unit_price_minor,
        'is_taxable', line.is_taxable,
        'line_total_minor', line.line_total_minor
      ) order by line.position, line.id), '[]'::jsonb)
      from public.job_line_items as line
      where line.organization_id = target_organization_id and line.job_id = target_job_id
    ),
    'totals', jsonb_build_object(
      'subtotal_minor', job_row.subtotal_minor,
      'discount_minor', job_row.discount_minor,
      'tax_minor', job_row.tax_minor,
      'total_minor', job_row.total_minor
    )
  );
end;
$$;


ALTER FUNCTION "private"."job_document_snapshot"("target_organization_id" "uuid", "target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."job_document_snapshot"("target_organization_id" "uuid", "target_job_id" "uuid") IS 'The job as a document: identity, client, property, the priced work list and the totals. Frozen onto a signature at collection, and recomputed later only to answer "has this job changed since it was signed".';



CREATE OR REPLACE FUNCTION "private"."job_line_items_enforce_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  offending uuid;
begin
  select item.job_id into offending
  from public.job_line_items as item
  where item.job_id in (select distinct inserted.job_id from inserted)
  group by item.job_id
  having count(*) > 100
  limit 1;

  if offending is not null then
    raise exception 'A job can hold up to 100 lines.' using errcode = '54000';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."job_line_items_enforce_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."job_payment_schedule_items_guard_locked"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists (
    select 1 from public.invoice_sources as source
    where source.organization_id = old.organization_id and source.installment_id = old.id
  ) then
    return new;
  end if;

  if new.description is distinct from old.description
     or new.value_type is distinct from old.value_type
     or new.value is distinct from old.value
     or new.position is distinct from old.position
     or new.is_deposit is distinct from old.is_deposit
     or new.locked_amount_minor is distinct from old.locked_amount_minor then
    raise exception 'A payment stage that already has an invoice cannot be changed.'
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."job_payment_schedule_items_guard_locked"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."job_recurrence_dates"("frequency" "text", "interval_count" integer, "weekdays" smallint[], "monthly_mode" "text", "month_day" smallint, "ordinal_week" smallint, "ordinal_weekday" smallint, "start_date" "date", "end_date" "date") RETURNS SETOF "date"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  ceiling integer := private.job_recurrence_limit() + 1;
begin
  if start_date is null or end_date is null or end_date < start_date then
    return;
  end if;

  if frequency = 'daily' then
    return query
      select day::date
      from generate_series(start_date, end_date, make_interval(days => interval_count)) as day
      limit ceiling;

  elsif frequency = 'weekly' then
    -- Every day in the window that falls on one of the chosen weekdays, then thinned by the interval. Weeks are
    -- counted from the week the schedule starts and each week is aligned to its Sunday, so "every 2 weeks on
    -- Monday and Wednesday" keeps both days inside the same week rather than alternating between them.
    return query
      select day::date
      from generate_series(start_date, end_date, interval '1 day') as day
      where extract(dow from day)::smallint = any(weekdays)
        and (
          ((day::date - extract(dow from day)::integer)
           - (start_date - extract(dow from start_date)::integer)) / 7
        ) % interval_count = 0
      order by day
      limit ceiling;

  elsif frequency = 'monthly' then
    -- One candidate per month in the window, then keep the ones that exist and land inside it. A rule on the
    -- 31st simply has no February: the month is skipped rather than quietly moved to the 28th, which is what
    -- the iCalendar standard does and what "the 31st" plainly means. Anyone who wants February covered picks
    -- "the last day" instead.
    return query
      select occurrence
      from generate_series(
             date_trunc('month', start_date::timestamp),
             date_trunc('month', end_date::timestamp),
             make_interval(months => interval_count)
           ) as month_start
      cross join lateral (
        select case
                 when monthly_mode = 'last_day' then
                   (month_start + interval '1 month - 1 day')::date
                 when monthly_mode = 'day_of_month' then
                   case
                     when month_day <= extract(day from (month_start + interval '1 month - 1 day'))::integer
                       then (month_start + make_interval(days => month_day - 1))::date
                   end
                 else
                   private.nth_weekday_of_month(month_start::date, ordinal_week, ordinal_weekday)
               end as occurrence
      ) as candidate
      where occurrence is not null
        and occurrence between start_date and end_date
      order by occurrence
      limit ceiling;

  elsif frequency = 'yearly' then
    return query
      select day::date
      from generate_series(start_date, end_date, make_interval(years => interval_count)) as day
      limit ceiling;

  else
    raise exception 'That repeat frequency is not one we support.' using errcode = 'check_violation';
  end if;
end;
$$;


ALTER FUNCTION "private"."job_recurrence_dates"("frequency" "text", "interval_count" integer, "weekdays" smallint[], "monthly_mode" "text", "month_day" smallint, "ordinal_week" smallint, "ordinal_weekday" smallint, "start_date" "date", "end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."job_recurrence_limit"() RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$ select 400 $$;


ALTER FUNCTION "private"."job_recurrence_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."job_report_customer_document"("job_row" "public"."jobs", "business_name" "text", "include_price" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  report_row public.job_reports;
  client_row public.clients;
  property_row public.properties;
begin
  select * into report_row
  from public.job_reports
  where organization_id = job_row.organization_id and job_id = job_row.id;
  if not found then
    return null;
  end if;

  select * into client_row
  from public.clients
  where organization_id = job_row.organization_id and id = job_row.client_id;

  select * into property_row
  from public.properties
  where organization_id = job_row.organization_id and id = job_row.property_id;

  return jsonb_build_object(
    'business', jsonb_build_object('name', business_name),
    'job', jsonb_build_object(
      'job_number', job_row.job_number,
      'title', job_row.title,
      'job_type', job_row.job_type,
      'currency_code', job_row.currency_code
    ),
    'client', jsonb_build_object(
      'display_name', client_row.display_name,
      'company_name', client_row.company_name,
      'first_name', client_row.first_name,
      'last_name', client_row.last_name
    ),
    'property', jsonb_build_object(
      'label', property_row.label,
      'address_line1', property_row.address_line1,
      'address_line2', property_row.address_line2,
      'city', property_row.city,
      'state_region', property_row.state_region,
      'postal_code', property_row.postal_code,
      'country', property_row.country
    ),
    'summary', nullif(trim(coalesce(report_row.summary, '')), ''),
    -- Photos, resolved live. A row in the join table names an attachment; the file name and object key come
    -- from the attachment now, so a renamed file shows its new name. The object key is what the public file
    -- route allow-lists and streams.
    'photos', (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'attachment_id', photo.attachment_id,
          'file_name', att.file_name,
          'object_key', att.object_key
        ) order by att.created_at, photo.attachment_id
      ), '[]'::jsonb)
      from public.job_report_photos as photo
      join public.attachments as att
        on att.organization_id = photo.organization_id and att.id = photo.attachment_id
      where photo.organization_id = job_row.organization_id and photo.job_id = job_row.id
    ),
    -- Checklist answers, grouped by visit and resolved live. The inner join to visit_checklist_answers is
    -- what makes "always current" true: a cleared answer produces no row, so it drops off the report until
    -- it is answered again.
    'checklist', (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'visit_id', grp.visit_id,
          'visit_date', grp.visit_date,
          'items', grp.items
        ) order by grp.visit_date, grp.visit_id
      ), '[]'::jsonb)
      from (
        select sel.visit_id,
               visit.visit_date,
               jsonb_agg(
                 jsonb_build_object(
                   'item_id', item.id,
                   'label', item.label,
                   'item_type', item.item_type,
                   'value', answer.value
                 ) order by item.position, item.id
               ) as items
        from public.job_report_checklist_items as sel
        join public.job_visits as visit
          on visit.organization_id = sel.organization_id and visit.id = sel.visit_id
        join public.job_checklist_items as item
          on item.organization_id = sel.organization_id and item.id = sel.item_id
        join public.visit_checklist_answers as answer
          on answer.organization_id = sel.organization_id
         and answer.visit_id = sel.visit_id
         and answer.item_id = sel.item_id
        where sel.organization_id = job_row.organization_id and sel.job_id = job_row.id
        group by sel.visit_id, visit.visit_date
      ) as grp
    ),
    -- The work list, only when the report shows it, and its prices only when it shows those. The check
    -- constraint means include_price already implies include_service_details.
    'service_details', case when report_row.include_service_details then jsonb_build_object(
      'lines', (
        select coalesce(jsonb_agg(
          jsonb_build_object(
            'line_id', line.id,
            'position', line.position,
            'line_kind', line.line_kind,
            'category', line.category,
            'name', line.name,
            'description', line.description,
            'unit_label', line.unit_label,
            'quantity', line.quantity
          )
          || case when include_price
               then jsonb_build_object(
                 'unit_price_minor', line.unit_price_minor,
                 'line_total_minor', line.line_total_minor)
               else '{}'::jsonb end
          order by line.position, line.id
        ), '[]'::jsonb)
        from public.job_line_items as line
        where line.organization_id = job_row.organization_id and line.job_id = job_row.id
      ),
      'totals', case when include_price then jsonb_build_object(
        'subtotal_minor', job_row.subtotal_minor,
        'discount_minor', job_row.discount_minor,
        'tax_minor', job_row.tax_minor,
        'total_minor', job_row.total_minor
      ) else null end
    ) else null end,
    -- The chosen signature, as facts the customer may read. The drawn image is not streamed on the public
    -- page in this part -- the customer sees who signed, what they agreed to and when.
    'signature', (
      select case when sig.id is null then null else jsonb_build_object(
        'signer_name', sig.signer_name,
        'signer_role', sig.signer_role,
        'signature_type', sig.signature_type,
        'statement', sig.statement,
        'method', sig.method,
        'has_image', sig.image_object_key is not null,
        'collected_at', sig.collected_at
      ) end
      from public.job_signatures as sig
      where sig.organization_id = job_row.organization_id and sig.id = report_row.signature_id
    )
  );
end;
$$;


ALTER FUNCTION "private"."job_report_customer_document"("job_row" "public"."jobs", "business_name" "text", "include_price" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."job_report_customer_document"("job_row" "public"."jobs", "business_name" "text", "include_price" boolean) IS 'The only definition of what a customer may see on a work report. Called by public.resolve_job_report_access_link for the customer and public.job_report_customer_preview for staff. Resolves photos and checklist answers live, so it is always current. Prices leave only when include_price is true, and no cost, margin or internal note is ever added here.';



CREATE OR REPLACE FUNCTION "private"."job_report_has_content"("target_organization_id" "uuid", "target_job_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1 from public.job_reports as report
    where report.organization_id = target_organization_id
      and report.job_id = target_job_id
      and (
        report.include_service_details
        or report.signature_id is not null
        or nullif(trim(coalesce(report.summary, '')), '') is not null
        or exists (
          select 1 from public.job_report_photos as photo
          where photo.organization_id = target_organization_id and photo.job_id = target_job_id
        )
        or exists (
          select 1 from public.job_report_checklist_items as sel
          where sel.organization_id = target_organization_id and sel.job_id = target_job_id
        )
      )
  );
$$;


ALTER FUNCTION "private"."job_report_has_content"("target_organization_id" "uuid", "target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."job_report_has_content"("target_organization_id" "uuid", "target_job_id" "uuid") IS 'Whether a job''s report is a document or an empty shell. The one definition, used to gate issuing a link, to decide whether the customer door opens, and to log the feed only on the empty/not crossing.';



