CREATE OR REPLACE FUNCTION "private"."job_uninvoiced_work"("target_organization_id" "uuid", "target_job_id" "uuid", "job_price_basis" "text", "job_subtotal_minor" bigint, "job_total_minor" bigint, "as_of" "date") RETURNS TABLE("unit_kind" "text", "unit_count" integer, "uninvoiced_minor" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    case job_price_basis
      when 'per_visit' then 'visits'
      when 'fixed_per_period' then 'periods'
      else 'job'
    end as unit_kind,
    units.count::integer as unit_count,
    (case when job_price_basis = 'job_total' then job_total_minor else job_subtotal_minor end
      * units.count)::bigint as uninvoiced_minor
  from (
    select case job_price_basis
      when 'per_visit' then (
        select count(*)
        from public.job_visits as visit
        where visit.organization_id = target_organization_id
          and visit.job_id = target_job_id
          and visit.completed_at is not null
          and not exists (
            select 1
            from public.invoice_sources as claim
            where claim.organization_id = visit.organization_id
              and claim.visit_id = visit.id
              and claim.source_kind = 'visit'
          )
      )
      when 'fixed_per_period' then (
        select count(*)
        from public.job_invoice_reminders as reminder
        where reminder.organization_id = target_organization_id
          and reminder.job_id = target_job_id
          and reminder.status = 'pending'
          and reminder.due_on <= as_of
          and reminder.reminder_kind in ('monthly_last_day', 'custom_date')
      )
      else (
        select case when exists (
          select 1
          from public.invoice_sources as claim
          where claim.organization_id = target_organization_id
            and claim.job_id = target_job_id
        ) or exists (
          select 1
          from public.job_payment_schedule_items as stage
          where stage.organization_id = target_organization_id
            and stage.job_id = target_job_id
        ) then 0 else 1 end
      )
    end as count
  ) as units;
$$;


ALTER FUNCTION "private"."job_uninvoiced_work"("target_organization_id" "uuid", "target_job_id" "uuid", "job_price_basis" "text", "job_subtotal_minor" bigint, "job_total_minor" bigint, "as_of" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."job_uninvoiced_work"("target_organization_id" "uuid", "target_job_id" "uuid", "job_price_basis" "text", "job_subtotal_minor" bigint, "job_total_minor" bigint, "as_of" "date") IS 'How much of one job is still billable and in what units, stating the same three rules the billing screens already use: a whole job once, one copy per completed unbilled visit, or one copy per due pending period. Bounded to a single job. Callers own the permission check.';



CREATE OR REPLACE FUNCTION "private"."job_visit_assignment_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  select visit.job_id into new.job_id
  from public.job_visits as visit
  where visit.id = new.visit_id
    and visit.organization_id = new.organization_id;

  if new.job_id is null then
    raise exception 'That visit does not belong to this organization.'
      using errcode = 'foreign_key_violation';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."job_visit_assignment_job"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."job_visit_effective_lines"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid") RETURNS TABLE("id" "uuid", "is_override" boolean, "position" integer, "source_job_line_item_id" "uuid", "source_catalog_item_id" "uuid", "line_kind" "text", "category" "text", "is_labor" boolean, "name" "text", "description" "text", "unit_label" "text", "quantity" numeric, "unit_price_minor" bigint, "unit_cost_minor" bigint, "is_taxable" boolean, "image_attachment_id" "uuid", "line_total_minor" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    item.id, true, item.position, item.source_job_line_item_id, item.source_catalog_item_id,
    item.line_kind, item.category, item.is_labor, item.name, item.description, item.unit_label,
    item.quantity, item.unit_price_minor, item.unit_cost_minor, item.is_taxable,
    item.image_attachment_id, item.line_total_minor
  from public.job_visit_line_items as item
  where item.organization_id = target_organization_id
    and item.visit_id = target_visit_id

  union all

  select
    line.id, false, line.position, line.id, line.source_catalog_item_id,
    line.line_kind, line.category, line.is_labor, line.name, line.description, line.unit_label,
    line.quantity, line.unit_price_minor, line.unit_cost_minor, line.is_taxable,
    line.image_attachment_id, line.line_total_minor
  from public.job_line_items as line
  where line.organization_id = target_organization_id
    and line.job_id = target_job_id
    and not exists (
      select 1
      from public.job_visit_line_items as override
      where override.organization_id = target_organization_id
        and override.visit_id = target_visit_id
    )

  order by 3, 1;
$$;


ALTER FUNCTION "private"."job_visit_effective_lines"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."job_visit_effective_lines"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid") IS 'One visit''s effective lines: its own rows if it has any, otherwise the job''s. The single answer every reader, editor and biller uses, so none of them can price a visit differently from another.';



CREATE OR REPLACE FUNCTION "private"."job_visit_line_items_enforce_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  offending uuid;
begin
  select item.visit_id into offending
  from public.job_visit_line_items as item
  where item.visit_id in (select distinct inserted.visit_id from inserted)
  group by item.visit_id
  having count(*) > 100
  limit 1;

  if offending is not null then
    raise exception 'A visit can hold up to 100 lines.' using errcode = '54000';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."job_visit_line_items_enforce_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."job_visits_protect_completed"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.completed_at is not null and pg_trigger_depth() = 1 then
      raise exception 'A completed visit cannot be deleted. It is the record that the work happened.'
        using errcode = 'P0410';
    end if;
    return old;
  end if;

  if old.completed_at is not null and (
    new.visit_date is distinct from old.visit_date
    or new.start_time is distinct from old.start_time
    or new.end_time is distinct from old.end_time
    or new.all_day is distinct from old.all_day
  ) then
    raise exception 'A completed visit cannot be rescheduled. It is the record that the work happened.'
      using errcode = 'P0410';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."job_visits_protect_completed"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."job_visits_protect_completed"() IS 'Refuses to move a completed visit or to delete one on its own, while still letting the job''s or the organization''s own deletion cascade through it.';



CREATE OR REPLACE FUNCTION "private"."jobs_guard_identity_and_transitions"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.organization_id is distinct from old.organization_id then
    raise exception 'A job cannot be moved to another organization.' using errcode = 'check_violation';
  end if;
  if new.job_number is distinct from old.job_number then
    raise exception 'A job number cannot be changed.' using errcode = 'check_violation';
  end if;
  if new.job_type is distinct from old.job_type or new.is_as_needed is distinct from old.is_as_needed then
    raise exception 'A job type cannot be changed after the job is created. Create a new job instead.'
      using errcode = 'check_violation';
  end if;
  if new.client_id is distinct from old.client_id then
    raise exception 'A job cannot be moved to another client.' using errcode = 'check_violation';
  end if;
  -- Lineage is permanent in both directions: a converted job can never forget its quote, and a direct job can
  -- never claim one it did not come from.
  if new.quote_id is distinct from old.quote_id or new.quote_version_id is distinct from old.quote_version_id then
    raise exception 'Quote lineage cannot be changed.' using errcode = 'check_violation';
  end if;
  if new.created_at is distinct from old.created_at then
    raise exception 'A job creation time cannot be changed.' using errcode = 'check_violation';
  end if;

  if new.status is distinct from old.status then
    if not (
      (old.status = 'active' and new.status = 'closed')
      or (old.status = 'closed' and new.status = 'active')
    ) then
      raise exception 'A job cannot go from % to %.', old.status, new.status
        using errcode = 'check_violation';
    end if;

    if new.status = 'closed' and new.closed_at is null then
      new.closed_at := now();
    end if;
    if new.status = 'active' then
      new.closed_at := null;
      new.closed_by := null;
      new.reopened_at := now();
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."jobs_guard_identity_and_transitions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."jobs_sync_month_end_reminder"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.billing_timing = 'month_end' and new.status = 'active' then
    perform private.seed_next_month_end_reminder(new.organization_id, new.id, (select auth.uid()));
  elsif tg_op = 'UPDATE' and new.billing_timing <> 'month_end' then
    delete from public.job_invoice_reminders
    where organization_id = new.organization_id
      and job_id = new.id
      and reminder_kind = 'monthly_last_day'
      and status = 'pending';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "private"."jobs_sync_month_end_reminder"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."jobs_sync_month_end_reminder"() IS 'Keeps a month-end-billed job carrying its open month-end reminder, and clears it when the job moves off month-end billing. Fires on creation and on any change to billing_timing, so no writer has to remember.';



CREATE OR REPLACE FUNCTION "private"."linked_entity_exists"("target_organization_id" "uuid", "target_entity_type" "text", "target_entity_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case target_entity_type
    when 'client' then exists (
      select 1 from public.clients
      where id = target_entity_id and organization_id = target_organization_id
    )
    when 'property' then exists (
      select 1 from public.properties
      where id = target_entity_id and organization_id = target_organization_id
    )
    when 'request' then exists (
      select 1 from public.requests
      where id = target_entity_id and organization_id = target_organization_id
    )
    when 'quote' then exists (
      select 1 from public.quotes
      where id = target_entity_id and organization_id = target_organization_id
    )
    when 'job_expense' then exists (
      select 1 from public.job_expenses
      where id = target_entity_id and organization_id = target_organization_id
    )
    when 'job' then exists (
      select 1 from public.jobs
      where id = target_entity_id and organization_id = target_organization_id
    )
    when 'visit' then exists (
      select 1 from public.job_visits
      where id = target_entity_id and organization_id = target_organization_id
    )
    else false
  end;
$$;


ALTER FUNCTION "private"."linked_entity_exists"("target_organization_id" "uuid", "target_entity_type" "text", "target_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."lock_invoice_for_edit"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "required_permission" "text" DEFAULT 'invoices.edit'::"text") RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  invoice_row public.invoices;
begin
  if caller is null then
    raise exception 'You must be signed in to change an invoice.'
      using errcode = 'insufficient_privilege';
  end if;
  -- Issuing and deleting are their own permissions, so each command says which one this lock is for rather
  -- than making everybody who may delete a draft also able to edit one.
  if not private.member_has_permission(target_organization_id, caller, required_permission) then
    raise exception 'You do not have access to change this invoice.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into invoice_row
  from public.invoices
  where organization_id = target_organization_id and id = target_invoice_id
  for update;
  if not found then
    raise exception 'That invoice could not be found.' using errcode = 'P0404';
  end if;

  if invoice_row.voided_at is not null then
    raise exception 'A voided invoice cannot be changed.' using errcode = 'check_violation';
  end if;
  if invoice_row.replaced_at is not null then
    raise exception 'This invoice was replaced. Change the invoice that replaced it.'
      using errcode = 'check_violation';
  end if;
  if invoice_row.revision is distinct from expected_revision then
    raise exception 'Someone else changed this invoice. Reload to see the latest.'
      using errcode = 'P0409';
  end if;

  return invoice_row;
end;
$$;


ALTER FUNCTION "private"."lock_invoice_for_edit"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "required_permission" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."lock_invoice_for_edit"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "required_permission" "text") IS 'Shared entry check for every invoice edit: the named permission, a row lock, voided/replaced refused, and a stale revision refused as P0409.';



CREATE OR REPLACE FUNCTION "private"."lock_invoice_for_payment"("target_organization_id" "uuid", "target_invoice_id" "uuid") RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  invoice_row public.invoices;
begin
  select * into invoice_row
  from public.invoices
  where organization_id = target_organization_id and id = target_invoice_id
  for update;
  if not found then
    raise exception 'That invoice could not be found.' using errcode = 'P0404';
  end if;

  if invoice_row.voided_at is not null then
    raise exception 'A voided invoice cannot take or give up money.' using errcode = 'check_violation';
  end if;

  return invoice_row;
end;
$$;


ALTER FUNCTION "private"."lock_invoice_for_payment"("target_organization_id" "uuid", "target_invoice_id" "uuid") OWNER TO "postgres";


