    CONSTRAINT "organization_settings_address_line1_check" CHECK ((("address_line1" IS NULL) OR (("char_length"(TRIM(BOTH FROM "address_line1")) >= 1) AND ("char_length"(TRIM(BOTH FROM "address_line1")) <= 160)))),
