    CONSTRAINT "organization_settings_branding_revision_check" CHECK (("branding_revision" >= 1)),
    CONSTRAINT "organization_settings_cash_app_cashtag_check" CHECK ((("pay_by_app_cash_app_cashtag" IS NULL) OR ("char_length"("pay_by_app_cash_app_cashtag") <= 20))),
    CONSTRAINT "organization_settings_city_check" CHECK ((("city" IS NULL) OR (("char_length"(TRIM(BOTH FROM "city")) >= 1) AND ("char_length"(TRIM(BOTH FROM "city")) <= 120)))),
    CONSTRAINT "organization_settings_country_code_check" CHECK ((("country_code" IS NULL) OR ("country_code" ~ '^[A-Z]{2}$'::"text"))),
