    CONSTRAINT "organization_settings_description_check" CHECK ((("description" IS NULL) OR (("char_length"(TRIM(BOTH FROM "description")) >= 1) AND ("char_length"(TRIM(BOTH FROM "description")) <= 500)))),
    CONSTRAINT "organization_settings_e_transfer_email_check" CHECK ((("pay_by_app_e_transfer_email" IS NULL) OR ("char_length"("pay_by_app_e_transfer_email") <= 254))),
    CONSTRAINT "organization_settings_hours_mode_check" CHECK (("hours_mode" = ANY (ARRAY['not_configured'::"text", 'weekly'::"text", 'appointment_only'::"text"]))),
    CONSTRAINT "organization_settings_hours_revision_check" CHECK (("hours_revision" >= 1)),
