    CONSTRAINT "organization_settings_latitude_check" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)))),
    CONSTRAINT "organization_settings_locale_check" CHECK (("locale" ~ '^[A-Za-z]{2,3}(?:-[A-Za-z]{2,4})?$'::"text")),
    CONSTRAINT "organization_settings_location_geocode_status_check" CHECK (("location_geocode_status" = ANY (ARRAY['pending'::"text", 'succeeded'::"text", 'failed'::"text"]))),
    CONSTRAINT "organization_settings_location_pair" CHECK ((("latitude" IS NULL) = ("longitude" IS NULL))),
