    CONSTRAINT "organization_settings_paypal_me_username_check" CHECK ((("pay_by_app_paypal_me_username" IS NULL) OR ("char_length"("pay_by_app_paypal_me_username") <= 50))),
    CONSTRAINT "organization_settings_phone_check" CHECK ((("phone" IS NULL) OR (("char_length"(TRIM(BOTH FROM "phone")) >= 1) AND ("char_length"(TRIM(BOTH FROM "phone")) <= 32)))),
    CONSTRAINT "organization_settings_postal_code_check" CHECK ((("postal_code" IS NULL) OR (("char_length"(TRIM(BOTH FROM "postal_code")) >= 1) AND ("char_length"(TRIM(BOTH FROM "postal_code")) <= 20)))),
    CONSTRAINT "organization_settings_profile_revision_check" CHECK (("profile_revision" >= 1)),
    CONSTRAINT "organization_settings_quote_representative_name_check" CHECK ((("quote_representative_name" IS NULL) OR (("char_length"("quote_representative_name") >= 1) AND ("char_length"("quote_representative_name") <= 160)))),
    CONSTRAINT "organization_settings_quote_representative_needs_name" CHECK (((NOT "quote_representative_enabled") OR ("quote_representative_name" IS NOT NULL))),
    CONSTRAINT "organization_settings_quote_representative_title_check" CHECK ((("quote_representative_title" IS NULL) OR (("char_length"("quote_representative_title") >= 1) AND ("char_length"("quote_representative_title") <= 160)))),
    CONSTRAINT "organization_settings_quote_terms_check" CHECK ((("quote_terms" IS NULL) OR ("char_length"("quote_terms") <= 20000))),
