    CONSTRAINT "organization_settings_timezone_check" CHECK ((("char_length"(TRIM(BOTH FROM "timezone")) >= 1) AND ("char_length"(TRIM(BOTH FROM "timezone")) <= 64))),
    CONSTRAINT "organization_settings_trade_check" CHECK ((("trade" IS NULL) OR (("char_length"(TRIM(BOTH FROM "trade")) >= 1) AND ("char_length"(TRIM(BOTH FROM "trade")) <= 120)))),
