COMMENT ON COLUMN "public"."organization_settings"."pipeline_detailed_assessment_stages" IS 'Part 5C-iii. False (the default) shows the five-column board with one Assessment column. True expands it into the three protected assessment stages. Presentation only: it never changes Request state, transitions, history, or reporting.';



COMMENT ON COLUMN "public"."organization_settings"."location_geocode_status" IS 'Where geocoding the business address stands: pending (queued/not yet done, or the address changed since), succeeded (latitude/longitude stored), failed (address does not resolve). Maintained by the private.mark_organization_for_geocoding trigger and the geocoding worker -- the same pattern properties use.';



CREATE OR REPLACE FUNCTION "private"."lock_invoice_settings_for_edit"("target_organization_id" "uuid", "expected_revision" integer) RETURNS "public"."organization_settings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  settings_row public.organization_settings;
begin
  if caller is null then
    raise exception 'You must be signed in to change invoice settings.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'settings.invoices.manage') then
    raise exception 'You do not have access to invoice settings.' using errcode = 'insufficient_privilege';
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for update;
  if not found then
    raise exception 'That organization could not be found.' using errcode = 'P0404';
  end if;

  if settings_row.invoice_settings_revision is distinct from expected_revision then
    raise exception 'Someone else changed invoice settings. Reload to see the latest.'
      using errcode = 'P0409';
  end if;

  return settings_row;
end;
$$;


ALTER FUNCTION "private"."lock_invoice_settings_for_edit"("target_organization_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."lock_job_for_edit"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer) RETURNS "public"."jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
begin
  if caller is null then
    raise exception 'You must be signed in to edit a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.edit') then
    raise exception 'You do not have access to edit this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id
    and job.id = target_job_id
  for update;

  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  if current_job.revision is distinct from expected_revision then
    raise exception 'Someone else changed this job. Reload to see the latest.' using errcode = 'P0409';
  end if;

  return current_job;
end;
$$;


ALTER FUNCTION "private"."lock_job_for_edit"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."lock_job_for_edit"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer) IS 'Shared entry check for every staged job edit: jobs.edit, row lock, and a stale revision refused as P0409.';



CREATE TABLE IF NOT EXISTS "public"."quote_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "quote_id" "uuid" NOT NULL,
    "version_number" integer NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "currency_code" "text" NOT NULL,
    "client_display_name" "text" NOT NULL,
    "organization_name" "text" NOT NULL,
    "service_address_line1" "text",
    "service_address_line2" "text",
    "service_city" "text",
    "service_state_region" "text",
    "service_postal_code" "text",
    "service_country" "text",
    "subtotal_minor" bigint DEFAULT 0 NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "revision" integer DEFAULT 1 NOT NULL,
    "contract_disclaimer" "text",
    "introduction" "text",
    "client_message" "text",
    "show_quantities" boolean DEFAULT true NOT NULL,
    "show_unit_prices" boolean DEFAULT true NOT NULL,
    "show_line_totals" boolean DEFAULT true NOT NULL,
    "show_totals" boolean DEFAULT true NOT NULL,
    "discount_name" "text",
    "discount_type" "text",
    "discount_value" bigint,
    "tax_name" "text",
    "tax_rate_basis_points" integer DEFAULT 0 NOT NULL,
    "discount_minor" bigint DEFAULT 0 NOT NULL,
    "tax_minor" bigint DEFAULT 0 NOT NULL,
    "total_minor" bigint DEFAULT 0 NOT NULL,
    "cost_minor" bigint DEFAULT 0 NOT NULL,
    "profit_minor" bigint DEFAULT 0 NOT NULL,
    "margin_basis_points" bigint,
    "calculation" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "document_hash" "text",
    "published_at" timestamp with time zone,
    "deposit_type" "text",
    "deposit_required_minor" bigint DEFAULT 0 NOT NULL,
    "tax_source" "text" DEFAULT 'not_configured'::"text" NOT NULL,
    "tax_rate_id" "uuid",
    "representative_enabled" boolean DEFAULT false NOT NULL,
    "representative_name" "text",
    "representative_title" "text",
    "representative_signature_object_key" "text",
    "require_customer_signature" boolean DEFAULT false NOT NULL,
    "logo_object_key" "text",
    "brand_color" "text",
    CONSTRAINT "quote_versions_brand_color_check" CHECK ((("brand_color" IS NULL) OR ("brand_color" ~ '^#[0-9A-Fa-f]{6}$'::"text"))),
    CONSTRAINT "quote_versions_client_message_check" CHECK ((("client_message" IS NULL) OR ("char_length"("client_message") <= 5000))),
    CONSTRAINT "quote_versions_contract_disclaimer_check" CHECK ((("contract_disclaimer" IS NULL) OR ("char_length"("contract_disclaimer") <= 5000))),
    CONSTRAINT "quote_versions_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "quote_versions_deposit_type_check" CHECK ((("deposit_type" IS NULL) OR ("deposit_type" = ANY (ARRAY['deposit_only'::"text", 'schedule'::"text"])))),
    CONSTRAINT "quote_versions_discount_check" CHECK (((("discount_type" IS NULL) AND ("discount_value" IS NULL) AND ("discount_name" IS NULL)) OR (("discount_type" = ANY (ARRAY['fixed'::"text", 'percentage'::"text"])) AND (("discount_value" >= 0) AND ("discount_value" <=
CASE
    WHEN ("discount_type" = 'percentage'::"text") THEN (10000)::bigint
    ELSE '9000000000000000000'::bigint
END)) AND ("discount_name" IS NOT NULL)))),
    CONSTRAINT "quote_versions_discount_name_check" CHECK ((("discount_name" IS NULL) OR (("char_length"(TRIM(BOTH FROM "discount_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "discount_name")) <= 80)))),
    CONSTRAINT "quote_versions_introduction_check" CHECK ((("introduction" IS NULL) OR ("char_length"("introduction") <= 10000))),
    CONSTRAINT "quote_versions_number_matches_status" CHECK (((("status" = 'draft'::"text") AND ("version_number" = 0)) OR (("status" = 'published'::"text") AND ("version_number" >= 1)))),
    CONSTRAINT "quote_versions_publication_check" CHECK (((("status" = 'draft'::"text") AND ("published_at" IS NULL) AND ("document_hash" IS NULL)) OR (("status" = 'published'::"text") AND ("published_at" IS NOT NULL) AND ("document_hash" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "quote_versions_revision_check" CHECK (("revision" >= 1)),
    CONSTRAINT "quote_versions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text"]))),
    CONSTRAINT "quote_versions_subtotal_minor_check" CHECK (("subtotal_minor" >= 0)),
    CONSTRAINT "quote_versions_tax_check" CHECK (((("tax_rate_basis_points" >= 0) AND ("tax_rate_basis_points" <= 10000)) AND ((("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL)) OR ("tax_name" IS NOT NULL)))),
    CONSTRAINT "quote_versions_tax_name_check" CHECK ((("tax_name" IS NULL) OR (("char_length"(TRIM(BOTH FROM "tax_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "tax_name")) <= 80)))),
    CONSTRAINT "quote_versions_tax_source_check" CHECK (("tax_source" = ANY (ARRAY['not_configured'::"text", 'business_default'::"text", 'property_default'::"text", 'saved_rate'::"text", 'no_tax'::"text", 'custom'::"text"]))),
    CONSTRAINT "quote_versions_tax_source_consistency" CHECK (
CASE "tax_source"
    WHEN 'not_configured'::"text" THEN (("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL) AND ("tax_rate_id" IS NULL))
    WHEN 'no_tax'::"text" THEN (("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL) AND ("tax_rate_id" IS NULL))
    WHEN 'custom'::"text" THEN (("tax_rate_basis_points" > 0) AND ("tax_name" IS NOT NULL) AND ("tax_rate_id" IS NULL))
    WHEN 'saved_rate'::"text" THEN (("tax_rate_basis_points" > 0) AND ("tax_name" IS NOT NULL) AND ("tax_rate_id" IS NOT NULL))
    ELSE ((("tax_rate_basis_points" > 0) AND ("tax_name" IS NOT NULL) AND ("tax_rate_id" IS NOT NULL)) OR (("tax_rate_basis_points" = 0) AND ("tax_name" IS NULL) AND ("tax_rate_id" IS NULL)))
END),
    CONSTRAINT "quote_versions_totals_check" CHECK ((("subtotal_minor" >= 0) AND ("discount_minor" >= 0) AND ("tax_minor" >= 0) AND ("total_minor" >= 0) AND ("cost_minor" >= 0) AND ("discount_minor" <= "subtotal_minor") AND ("deposit_required_minor" >= 0) AND ("deposit_required_minor" <= "total_minor")))
);


ALTER TABLE "public"."quote_versions" OWNER TO "postgres";


COMMENT ON TABLE "public"."quote_versions" IS 'Quote-owned proposal snapshots. Part 2 writes exactly one draft per quote. Published versions and their immutability guards belong to Part 4; the status vocabulary is here so that part adds behavior rather than rewriting this constraint.';



COMMENT ON COLUMN "public"."quote_versions"."revision" IS 'Bumped by every command that changes this draft. A writer sends the revision it read; a mismatch is refused with P0409 so the loser reloads instead of overwriting work they never saw.';



COMMENT ON COLUMN "public"."quote_versions"."contract_disclaimer" IS 'The terms block on the quote document. Plain text the writer types; there is no settings-backed default to inherit from yet.';



COMMENT ON COLUMN "public"."quote_versions"."calculation" IS 'Database-owned itemized calculation for the version default selection. Consumers display it; they do not recalculate it.';



COMMENT ON COLUMN "public"."quote_versions"."document_hash" IS 'SHA-256 of canonical customer-visible version content, assigned only when the version is frozen.';



COMMENT ON COLUMN "public"."quote_versions"."deposit_required_minor" IS 'Database-owned, same as subtotal/discount/tax/total: the calculator''s answer for the current selection, not a value anything else may write.';



CREATE OR REPLACE FUNCTION "private"."lock_quote_draft"("target_quote_id" "uuid", "expected_revision" integer) RETURNS "public"."quote_versions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  draft_row public.quote_versions;
begin
  select * into quote_row from public.quotes where id = target_quote_id for update;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.edit'
     ) then
    raise exception 'You do not have access to change this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.status <> 'draft' then
    raise exception 'Only a draft quote can be changed.' using errcode = 'check_violation';
  end if;

  select * into draft_row
  from public.quote_versions
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and status = 'draft'
  for update;

  if draft_row.id is null then
    raise exception 'This quote has no draft to change.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from draft_row.revision then
    raise exception 'Someone else changed this quote while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  return draft_row;
end;
$$;


ALTER FUNCTION "private"."lock_quote_draft"("target_quote_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


