CREATE OR REPLACE FUNCTION "private"."mark_organization_for_geocoding"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.address_line1 is distinct from old.address_line1
     or new.address_line2 is distinct from old.address_line2
     or new.city is distinct from old.city
     or new.region is distinct from old.region
     or new.postal_code is distinct from old.postal_code
     or new.country_code is distinct from old.country_code
  then
    new.location_geocode_status := 'pending';
    new.latitude := null;
    new.longitude := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."mark_organization_for_geocoding"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."mark_property_for_geocoding"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    -- A new property's address has never been verified. Coordinates come only from our geocoder, so they start
    -- empty and the row waits in the pending queue regardless of what was supplied.
    new.geocode_status := 'pending';
    new.latitude := null;
    new.longitude := null;
    return new;
  end if;

  -- UPDATE: only a real change to a geocodable component invalidates the stored coordinates. `is distinct from`
  -- treats nulls correctly, so clearing or setting an optional line counts and a no-op rewrite does not. This
  -- also means the worker's own write of coordinates + status (which touches neither address column) never
  -- trips this trigger back to pending.
  if new.address_line1 is distinct from old.address_line1
     or new.address_line2 is distinct from old.address_line2
     or new.city is distinct from old.city
     or new.state_region is distinct from old.state_region
     or new.postal_code is distinct from old.postal_code
     or new.country is distinct from old.country then
    new.geocode_status := 'pending';
    new.latitude := null;
    new.longitude := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."mark_property_for_geocoding"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."marketing_compile_group_rules"("rules" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  allowed_keys constant text[] := array[
    'version', 'lifecycle', 'tags', 'cities', 'lead_sources', 'services', 'work_type',
    'last_completed_job', 'upcoming_work', 'include_client_ids', 'exclude_client_ids'
  ];
  rule_key text;
  conditions text[] := array[]::text[];
  predicate text;
  completed_job_mode text;
begin
  if rules is null or jsonb_typeof(rules) <> 'object' then
    raise exception 'Marketing group rules must be an object.' using errcode = '22023';
  end if;

  if coalesce(rules->>'version', '') <> '1' then
    raise exception 'Unsupported marketing group rule version.' using errcode = '22023';
  end if;

  for rule_key in select jsonb_object_keys(rules) loop
    if not (rule_key = any (allowed_keys)) then
      raise exception 'Unknown marketing group filter: %', rule_key using errcode = '22023';
    end if;
  end loop;

  if rules ? 'lifecycle' then
    conditions := array_append(conditions, $frag$
      c.lifecycle_status in (select jsonb_array_elements_text($1->'lifecycle'))$frag$);
  end if;

  if rules ? 'tags' then
    conditions := array_append(conditions, $frag$
      exists (
        select 1 from public.tag_assignments ta
        where ta.organization_id = c.organization_id
          and ta.entity_type = 'client'
          and ta.entity_id = c.id
          and ta.tag_id in (
            select value::uuid from jsonb_array_elements_text($1->'tags') as chosen(value)
          )
      )$frag$);
  end if;

  if rules ? 'cities' then
    conditions := array_append(conditions, $frag$
      exists (
        select 1 from public.properties p
        where p.organization_id = c.organization_id
          and p.client_id = c.id
          and p.deleted_at is null
          and lower(btrim(p.city)) in (
            select lower(btrim(value)) from jsonb_array_elements_text($1->'cities') as chosen(value)
          )
      )$frag$);
  end if;

  if rules ? 'lead_sources' then
    conditions := array_append(conditions, $frag$
      c.lead_source in (select jsonb_array_elements_text($1->'lead_sources'))$frag$);
  end if;

  if rules ? 'services' then
    conditions := array_append(conditions, $frag$
      exists (
        select 1
        from public.jobs j
        join public.job_line_items li
          on li.organization_id = j.organization_id and li.job_id = j.id
        where j.organization_id = c.organization_id
          and j.client_id = c.id
          and li.source_catalog_item_id in (
            select value::uuid from jsonb_array_elements_text($1->'services') as chosen(value)
          )
      )$frag$);
  end if;

  if rules ? 'work_type' then
    if (rules->>'work_type') not in ('one_off', 'recurring') then
      raise exception 'Unknown marketing group work type.' using errcode = '22023';
    end if;
    conditions := array_append(conditions, $frag$
      exists (
        select 1 from public.jobs j
        where j.organization_id = c.organization_id
          and j.client_id = c.id
          and j.job_type = ($1->>'work_type')
      )$frag$);
  end if;

  if rules ? 'last_completed_job' then
    completed_job_mode := rules#>>'{last_completed_job,mode}';
    if completed_job_mode = 'never' then
      conditions := array_append(conditions, $frag$
        not exists (
          select 1 from public.jobs j
          where j.organization_id = c.organization_id
            and j.client_id = c.id
            and j.status = 'closed'
        )$frag$);
    elsif completed_job_mode = 'within_days' then
      conditions := array_append(conditions, $frag$
        exists (
          select 1 from public.jobs j
          where j.organization_id = c.organization_id
            and j.client_id = c.id
            and j.status = 'closed'
            and j.closed_at >= now() - make_interval(
              days => (($1#>>'{last_completed_job,days}')::integer)
            )
        )$frag$);
    elsif completed_job_mode = 'before_days' then
      conditions := array_append(conditions, $frag$
        exists (
          select 1 from public.jobs j
          where j.organization_id = c.organization_id
            and j.client_id = c.id
            and j.status = 'closed'
        )
        and not exists (
          select 1 from public.jobs j
          where j.organization_id = c.organization_id
            and j.client_id = c.id
            and j.status = 'closed'
            and j.closed_at >= now() - make_interval(
              days => (($1#>>'{last_completed_job,days}')::integer)
            )
        )$frag$);
    else
      raise exception 'Unknown last completed job filter.' using errcode = '22023';
    end if;
  end if;

  if rules ? 'upcoming_work' then
    if jsonb_typeof(rules->'upcoming_work') <> 'boolean' then
      raise exception 'Upcoming work filter must be true or false.' using errcode = '22023';
    end if;
    predicate := $frag$
      exists (
        select 1
        from public.job_visits v
        join public.jobs j on j.organization_id = v.organization_id and j.id = v.job_id
        where v.organization_id = c.organization_id
          and j.client_id = c.id
          and v.visit_date >= current_date
          and v.completed_at is null
      )$frag$;
    if (rules->>'upcoming_work')::boolean then
      conditions := array_append(conditions, predicate);
    else
      conditions := array_append(conditions, 'not ' || predicate);
    end if;
  end if;

  if array_length(conditions, 1) is null then
    predicate := 'true';
  else
    predicate := '(' || array_to_string(conditions, ') and (') || ')';
  end if;

  if rules ? 'include_client_ids' then
    predicate := '(' || predicate || $frag$ or c.id in (
      select value::uuid from jsonb_array_elements_text($1->'include_client_ids') as chosen(value)
    ))$frag$;
  end if;

  if rules ? 'exclude_client_ids' then
    predicate := predicate || $frag$ and c.id not in (
      select value::uuid from jsonb_array_elements_text($1->'exclude_client_ids') as chosen(value)
    )$frag$;
  end if;

  return predicate;
end;
$_$;


ALTER FUNCTION "private"."marketing_compile_group_rules"("rules" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."marketing_compile_group_rules"("rules" "jsonb") IS 'Compiles a validated marketing group rule object into a boolean SQL fragment over public.clients c. Emits only fixed fragments; every value is read from the bound $1 parameter at run time.';



CREATE OR REPLACE FUNCTION "private"."marketing_evaluated_recipients_sql"("rules" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $_$
  select format($sql$
    with matched as (
      select c.id, c.organization_id, c.display_name, c.archived_at
      from public.clients c
      where c.organization_id = $2
        and c.deleted_at is null
        and (%s)
    ),
    evaluated as (
      select
        m.id as client_id,
        m.display_name,
        dest.method_id,
        dest.email,
        case
          when m.archived_at is not null then 'inactive_customer'
          when dest.method_id is null then 'missing_email'
          when consent.state = 'opted_out' and consent.source = 'complaint' then 'complaint'
          when consent.state = 'opted_out' then 'unsubscribed'
          when suppression.reason = 'complaint' then 'complaint'
          when suppression.reason = 'hard_bounce' then 'hard_bounce'
          when preference.contact_policy = 'do_not_disturb' then 'do_not_disturb'
          when preference.contact_policy = 'no_marketing' then 'no_marketing'
          when consent.state is distinct from 'opted_in' then 'no_consent'
          else null
        end as blocked_reason
      from matched m
      left join lateral (
        select cm.id as method_id, cm.normalized_value as email
        from public.client_contact_methods cm
        where cm.organization_id = m.organization_id
          and cm.client_id = m.id
          and cm.kind = 'email'
        order by cm.is_primary desc, cm.created_at, cm.id
        limit 1
      ) dest on true
      left join lateral (
        select state.state, event.source
        from public.client_marketing_consent_state state
        join public.client_marketing_consent_events event
          on event.organization_id = state.organization_id and event.id = state.source_event_id
        where state.organization_id = m.organization_id
          and state.client_contact_method_id = dest.method_id
      ) consent on true
      left join public.client_communication_preferences preference
        on preference.organization_id = m.organization_id and preference.client_id = m.id
      left join lateral (
        select active.reason
        from public.communication_email_suppressions active
        where active.organization_id = m.organization_id
          and active.recipient_email = dest.email
          and active.released_at is null
        order by case active.reason when 'complaint' then 0 else 1 end
        limit 1
      ) suppression on true
    )
    select client_id, display_name, method_id, email, blocked_reason from evaluated
  $sql$, private.marketing_compile_group_rules(rules));
$_$;


ALTER FUNCTION "private"."marketing_evaluated_recipients_sql"("rules" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."marketing_evaluated_recipients_sql"("rules" "jsonb") IS 'Builds the shared preview query: one row per matched Customer with the single reason, if any, that stops the campaign reaching them.';



CREATE OR REPLACE FUNCTION "private"."member_access_required_keys_are_allowed"("candidate" "jsonb", "required_keys" "text"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case
    when jsonb_typeof(candidate) <> 'object' then false
    else required_keys <@ array(select jsonb_object_keys(candidate))
  end;
$$;


ALTER FUNCTION "private"."member_access_required_keys_are_allowed"("candidate" "jsonb", "required_keys" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."member_access_required_keys_are_allowed"("candidate" "jsonb", "required_keys" "text"[]) IS 'True when every required summary key is also an allowed one. A shape that demands a key it forbids could never record anything.';



CREATE OR REPLACE FUNCTION "private"."member_access_summary_kinds_are_known"("candidate" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case
    when jsonb_typeof(candidate) <> 'object' then false
    else not exists (
      select 1
      from jsonb_each_text(candidate) as entry(summary_key, value_kind)
      where value_kind not in (
        'role', 'member_status', 'permission_key_list', 'profile_field_list', 'id', 'assignment_count',
        'availability_field_list'
      )
    )
  end;
$$;


ALTER FUNCTION "private"."member_access_summary_kinds_are_known"("candidate" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."member_access_summary_kinds_are_known"("candidate" "jsonb") IS 'True when every value in a shape''s summary_keys map names one of the known closed value kinds. None of them is free text -- that is the whole point of the allow-list.';



CREATE OR REPLACE FUNCTION "private"."member_access_summary_value_fits"("value_kind" "text", "candidate" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
begin
  case value_kind
    when 'role' then
      return jsonb_typeof(candidate) = 'string'
        and candidate #>> '{}' in ('owner', 'admin', 'office', 'sales', 'field', 'finance');
    when 'member_status' then
      return jsonb_typeof(candidate) = 'string'
        and candidate #>> '{}' in ('pending', 'active', 'deactivated', 'removed');
    when 'permission_key_list' then
      if jsonb_typeof(candidate) <> 'array' then
        return false;
      end if;
      return not exists (
        select 1
        from jsonb_array_elements(candidate) as element(item)
        where jsonb_typeof(element.item) <> 'string'
          or not exists (
            select 1 from public.permissions as permission where permission.key = element.item #>> '{}'
          )
      );
    when 'profile_field_list' then
      if jsonb_typeof(candidate) <> 'array' then
        return false;
      end if;
      return not exists (
        select 1
        from jsonb_array_elements(candidate) as element(item)
        where jsonb_typeof(element.item) <> 'string'
          or element.item #>> '{}' not in ('full_name', 'work_phone', 'job_title', 'schedule_color')
      );
    when 'availability_field_list' then
      if jsonb_typeof(candidate) <> 'array' then
        return false;
      end if;
      return not exists (
        select 1
        from jsonb_array_elements(candidate) as element(item)
        where jsonb_typeof(element.item) <> 'string'
          or element.item #>> '{}' not in ('weekly_pattern', 'exceptions')
      );
    when 'id' then
      return jsonb_typeof(candidate) = 'string'
        and (candidate #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
    when 'assignment_count' then
      return jsonb_typeof(candidate) = 'number'
        and (candidate #>> '{}')::numeric >= 0
        and (candidate #>> '{}')::numeric = floor((candidate #>> '{}')::numeric);
    else
      -- An unknown kind is a refusal, never a pass. A future kind must be added here on purpose.
      return false;
  end case;
end;
$_$;


ALTER FUNCTION "private"."member_access_summary_value_fits"("value_kind" "text", "candidate" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."member_access_summary_value_fits"("value_kind" "text", "candidate" "jsonb") IS 'Checks one summary value against its declared kind. Every kind is a closed vocabulary, and permission keys must name a real row in public.permissions. Anything unrecognised is refused.';



CREATE OR REPLACE FUNCTION "private"."member_has_permission"("target_organization_id" "uuid", "target_user_id" "uuid", "target_permission_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public.organization_members as membership
    where membership.organization_id = target_organization_id
      and membership.user_id = target_user_id
      and membership.status = 'active'
      and coalesce(
        (
          select override.override_state = 'grant'
          from public.organization_member_permission_overrides as override
          where override.organization_id = membership.organization_id
            and override.user_id = membership.user_id
            and override.permission_key = target_permission_key
        ),
        exists (
          select 1
          from public.role_permissions as role_permission
          where role_permission.role = membership.role
            and role_permission.permission_key = target_permission_key
        )
      )
  );
$$;


ALTER FUNCTION "private"."member_has_permission"("target_organization_id" "uuid", "target_user_id" "uuid", "target_permission_key" "text") OWNER TO "postgres";


