COMMENT ON FUNCTION "private"."member_organizations"() IS 'Organizations where the caller is an active member. Reads no column, so a policy written as `organization_id in (select private.member_organizations())` costs one lookup per query rather than one per row. Use this instead of is_organization_member(organization_id) in any policy over a table that grows.';



CREATE OR REPLACE FUNCTION "private"."member_permission_scope"("target_organization_id" "uuid", "target_user_id" "uuid", "target_permission_key" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(
    (
      select case
        when override.override_state = 'deny' then 'none'
        else override.access_scope
      end
      from public.organization_member_permission_overrides as override
      join public.organization_members as membership
        on membership.organization_id = override.organization_id
       and membership.user_id = override.user_id
      where override.organization_id = target_organization_id
        and override.user_id = target_user_id
        and override.permission_key = target_permission_key
        and membership.status = 'active'
    ),
    (
      select role_permission.access_scope
      from public.organization_members as membership
      join public.role_permissions as role_permission
        on role_permission.role = membership.role
      where membership.organization_id = target_organization_id
        and membership.user_id = target_user_id
        and membership.status = 'active'
        and role_permission.permission_key = target_permission_key
    ),
    'none'
  );
$$;


ALTER FUNCTION "private"."member_permission_scope"("target_organization_id" "uuid", "target_user_id" "uuid", "target_permission_key" "text") OWNER TO "postgres";


