COMMENT ON FUNCTION "private"."organization_calendars"() IS 'Today''s date in each organization''s own timezone, for the organizations the caller belongs to. A set rather than a lookup so a list query joins it once instead of calling it per row; a caller with no auth.uid() (superuser or service maintenance) gets every organization rather than a wrong answer.';



CREATE OR REPLACE FUNCTION "private"."organization_currency_lock_reason"("target_organization_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case
    when exists (
      select 1 from public.quotes
      where organization_id = target_organization_id
        and (current_published_version_id is not null or sent_at is not null)
    ) then 'quote_sent'
    when exists (
      select 1 from public.invoice_events
      where organization_id = target_organization_id
        and event_type in ('invoice.issued', 'invoice.recognized')
    ) then 'invoice_issued'
    when exists (
      select 1 from public.client_payment_events
      where organization_id = target_organization_id
    ) then 'money_received'
  end;
$$;


ALTER FUNCTION "private"."organization_currency_lock_reason"("target_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."organization_currency_lock_reason"("target_organization_id" "uuid") IS 'Why this organization''s currency is locked, or null when it is still free to change. The one predicate behind the settings reader, the business-profile save and the guard on organization_settings. It reads retained history on purpose, so refunding, voiding or deleting never unlocks it.';



CREATE OR REPLACE FUNCTION "private"."organization_grace_ends_at"("paid_through" "date", "commercial_timezone" "text") RETURNS timestamp with time zone
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case
    when paid_through is null then null
    else ((paid_through + 8)::timestamp) at time zone commercial_timezone
  end;
$$;


ALTER FUNCTION "private"."organization_grace_ends_at"("paid_through" "date", "commercial_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."organization_has_automations_feature"("p_organization_id" "uuid", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  override_state text;
  assignment_version_id uuid;
  organization_row public.organizations%rowtype;
  effective_package_key text;
begin
  select o.override_state into override_state
  from public.organization_feature_overrides as o
  where o.organization_id = p_organization_id
    and o.feature_key = 'automations'
    and o.starts_at <= p_at
    and (o.expires_at is null or o.expires_at > p_at)
  order by o.starts_at desc
  limit 1;
  if override_state is not null then
    return override_state = 'on';
  end if;

  select a.package_version_id into assignment_version_id
  from public.organization_package_assignments as a
  where a.organization_id = p_organization_id
  order by a.effective_at desc, a.id desc
  limit 1;

  if assignment_version_id is not null then
    return exists (
      select 1
      from public.platform_package_version_features as f
      where f.package_version_id = assignment_version_id
        and f.feature_key = 'automations'
    );
  end if;

  select * into organization_row from public.organizations where id = p_organization_id;
  if not found then
    return false;
  end if;

  effective_package_key := case
    when organization_row.scheduled_package_key is not null
      and organization_row.scheduled_package_effective_at is not null
      and organization_row.scheduled_package_effective_at <= p_at
    then organization_row.scheduled_package_key
    else organization_row.package_key
  end;

  return exists (
    select 1
    from public.package_features as pf
    where pf.package_key = effective_package_key
      and pf.feature_key = 'automations'
  );
end;
$$;


ALTER FUNCTION "private"."organization_has_automations_feature"("p_organization_id" "uuid", "p_at" timestamp with time zone) OWNER TO "postgres";


