        'commercial_timezone',
        'feature_key',
        'limit_key',
        'limit_state',
        'limit_value',
        'closure_deadline_at'
      )
      and jsonb_typeof(payload -> payload_key) in ('string', 'number', 'boolean', 'null')
    ),
    true
  )
  from jsonb_object_keys(payload) as payload_key;
$$;


