CREATE TABLE IF NOT EXISTS "public"."client_payment_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "amount_minor" bigint NOT NULL,
    "currency_code" "text" NOT NULL,
    "method" "text",
    "payment_date" "date" NOT NULL,
    "reference" "text",
    "note" "text",
    "actor_user_id" "uuid",
    "original_event_id" "uuid",
    "original_deposit_event_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "client_payment_events_amount_minor_check" CHECK ((("amount_minor" > 0) AND ("amount_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "client_payment_events_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "client_payment_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['received'::"text", 'refunded'::"text", 'reversed'::"text"]))),
    CONSTRAINT "client_payment_events_method_check" CHECK (("method" = ANY (ARRAY['other'::"text", 'bank_transfer'::"text", 'cash'::"text", 'check'::"text", 'card_external'::"text", 'paypal'::"text", 'venmo'::"text", 'zelle'::"text", 'cash_app'::"text", 'e_transfer'::"text", 'stripe_card'::"text", 'stripe_bank'::"text", 'stripe_other'::"text"]))),
    CONSTRAINT "client_payment_events_note_check" CHECK ((("note" IS NULL) OR ("char_length"("note") <= 2000))),
    CONSTRAINT "client_payment_events_reference_check" CHECK ((("reference" IS NULL) OR (("char_length"(TRIM(BOTH FROM "reference")) >= 1) AND ("char_length"(TRIM(BOTH FROM "reference")) <= 200)))),
    CONSTRAINT "client_payment_events_shape" CHECK (
CASE "event_type"
    WHEN 'received'::"text" THEN (("method" IS NOT NULL) AND ("original_event_id" IS NULL) AND ("original_deposit_event_id" IS NULL))
    WHEN 'refunded'::"text" THEN (("original_event_id" IS NOT NULL) <> ("original_deposit_event_id" IS NOT NULL))
    WHEN 'reversed'::"text" THEN (("method" IS NULL) AND ("original_event_id" IS NOT NULL) AND ("original_deposit_event_id" IS NULL))
    ELSE NULL::boolean
END)
);


ALTER TABLE "public"."client_payment_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."client_payment_events" IS 'Money that actually moved, recorded against a client. Immutable: a mistake is corrected by a reversing or refunding row that points at the original, never by an edit or a delete. Quote deposits stay in quote_deposit_events and are reused from there rather than copied in.';



COMMENT ON COLUMN "public"."client_payment_events"."original_deposit_event_id" IS 'Set when a refund returns money that arrived as a quote deposit. The foreign key is what stops a quote whose deposit an invoice has used from being deleted out from under that history.';



CREATE OR REPLACE FUNCTION "private"."payment_receipt_document"("receipt" "public"."client_payment_events", "business_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  snapshot_invoice public.invoices;
  recipient_name text;
  recipient_company text;
  recipient_address jsonb;
begin
  select invoice.* into snapshot_invoice
  from public.invoice_payment_allocations as allocation
  join public.invoices as invoice
    on invoice.organization_id = allocation.organization_id and invoice.id = allocation.invoice_id
  where allocation.organization_id = receipt.organization_id
    and allocation.payment_event_id = receipt.id
    and allocation.entry_type = 'applied'
  order by allocation.invoice_number
  limit 1;

  if snapshot_invoice.id is not null then
    recipient_name := coalesce(
      nullif(trim(snapshot_invoice.customer_snapshot->>'display_name'), ''),
      (select client.display_name from public.clients as client
        where client.organization_id = receipt.organization_id and client.id = receipt.client_id)
    );
    recipient_company := nullif(trim(snapshot_invoice.customer_snapshot->>'company_name'), '');
    recipient_address := snapshot_invoice.billing_address_snapshot;
  else
    select client.display_name, nullif(trim(client.company_name), '')
      into recipient_name, recipient_company
    from public.clients as client
    where client.organization_id = receipt.organization_id and client.id = receipt.client_id;
    recipient_address := null;
  end if;

  return jsonb_build_object(
    'business', jsonb_build_object('name', business_name),
    'receipt', jsonb_build_object(
      'amount_minor', receipt.amount_minor,
      'currency_code', receipt.currency_code,
      'transaction_date', receipt.payment_date,
      'method', receipt.method,
      'reference', receipt.reference,
      'details', receipt.note
    ),
    'recipient', jsonb_build_object(
      'display_name', recipient_name,
      'company_name', recipient_company,
      'address', case
        when recipient_address is null
          or recipient_address->>'source' = 'none'
          or coalesce(recipient_address->>'address_line1', '') = '' then null
        else jsonb_build_object(
          'address_line1', recipient_address->>'address_line1',
          'address_line2', recipient_address->>'address_line2',
          'city', recipient_address->>'city',
          'state_region', recipient_address->>'state_region',
          'postal_code', recipient_address->>'postal_code',
          'country', recipient_address->>'country'
        )
      end
    )
  );
end;
$$;


ALTER FUNCTION "private"."payment_receipt_document"("receipt" "public"."client_payment_events", "business_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."payment_receipt_document"("receipt" "public"."client_payment_events", "business_name" "text") IS 'The only definition of a customer payment receipt. Jobber''s field set exactly: business, amount paid, transaction date, method, reference, details note, and the recipient name + billing address from the settled invoice''s frozen snapshot. No receipt number, invoice number, line items or balance.';



CREATE OR REPLACE FUNCTION "private"."permission_scope"("target_organization_id" "uuid", "target_permission_key" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(
    (
      select case
        when override.override_state = 'deny' then 'none'
        else override.access_scope
      end
      from public.organization_member_permission_overrides as override
      join public.organization_members as membership
        on membership.organization_id = override.organization_id
       and membership.user_id = override.user_id
      where override.organization_id = target_organization_id
        and override.user_id = (select auth.uid())
        and override.permission_key = target_permission_key
        and membership.status = 'active'
    ),
    (
      select role_permission.access_scope
      from public.organization_members as membership
      join public.role_permissions as role_permission
        on role_permission.role = membership.role
      where membership.organization_id = target_organization_id
        and membership.user_id = (select auth.uid())
        and membership.status = 'active'
        and role_permission.permission_key = target_permission_key
    ),
    'none'
  );
$$;


ALTER FUNCTION "private"."permission_scope"("target_organization_id" "uuid", "target_permission_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."permitted_organizations"("target_permission_key" "text") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select membership.organization_id
  from public.organization_members as membership
  join public.organizations as organization
    on organization.id = membership.organization_id
  where membership.user_id = (select auth.uid())
    and membership.status = 'active'
    and organization.lifecycle_status = 'active'
    and coalesce(
      (
        select override.override_state = 'grant'
        from public.organization_member_permission_overrides as override
        where override.organization_id = membership.organization_id
          and override.user_id = membership.user_id
          and override.permission_key = target_permission_key
      ),
      exists (
        select 1
        from public.role_permissions as role_permission
        where role_permission.role = membership.role
          and role_permission.permission_key = target_permission_key
      )
    );
$$;


ALTER FUNCTION "private"."permitted_organizations"("target_permission_key" "text") OWNER TO "postgres";


