ALTER TABLE "public"."opportunities" OWNER TO "postgres";


COMMENT ON TABLE "public"."opportunities" IS 'Sales Pipeline opportunities. Members may read this table, never write it. Identity comes from the Request trigger, stage from the stage triggers, the Part 2 fields from public.pipeline_update_opportunity_details, and outcome from public.pipeline_mark_opportunity_lost / public.pipeline_reopen_opportunity. Any future write must arrive through a definer function that checks the caller, not through a new grant or policy.';



COMMENT ON COLUMN "public"."opportunities"."quote_id" IS 'Set on the card created by public.convert_request_to_quote. The Quote board columns arrive with the later Quote parts; until then this card is parked off the board.';



CREATE OR REPLACE FUNCTION "private"."pipeline_lock_opportunity_for_drag"("target_opportunity_id" "uuid") RETURNS "public"."opportunities"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_row public.opportunities;
begin
  select * into target_row
  from public.opportunities
  where id = target_opportunity_id
  for update;

  if target_row.id is null
     or not private.member_has_permission(
       target_row.organization_id, (select auth.uid()), 'pipeline.edit'
     ) then
    raise exception 'You do not have access to move this card.' using errcode = 'insufficient_privilege';
  end if;

  return target_row;
end;
$$;


