CREATE OR REPLACE FUNCTION "private"."quote_current_total_minor"("target_quote_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select version.total_minor
  from public.quotes as quote
  join public.quote_versions as version
    on version.id = coalesce(quote.draft_version_id, quote.current_published_version_id)
   and version.organization_id = quote.organization_id
  where quote.id = target_quote_id;
$$;


ALTER FUNCTION "private"."quote_current_total_minor"("target_quote_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."quotes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "property_id" "uuid" NOT NULL,
    "request_id" "uuid",
    "quote_number" integer NOT NULL,
    "title" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "currency_code" "text" NOT NULL,
    "draft_version_id" "uuid",
    "conversion_idempotency_key" "text",
    "conversion_request_hash" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "previous_status" "text",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    "current_published_version_id" "uuid",
    "sent_at" timestamp with time zone,
    "decision" "text",
    "decided_at" timestamp with time zone,
    "decision_method" "text",
    "decision_note" "text",
    "decided_by" "uuid",
    CONSTRAINT "quotes_archive_fields_agree" CHECK ((("status" = 'archived'::"text") = ("archived_at" IS NOT NULL))),
    CONSTRAINT "quotes_archive_reason_check" CHECK ((("archive_reason" IS NULL) OR (("char_length"(TRIM(BOTH FROM "archive_reason")) >= 3) AND ("char_length"(TRIM(BOTH FROM "archive_reason")) <= 500)))),
    CONSTRAINT "quotes_conversion_needs_request" CHECK ((("conversion_idempotency_key" IS NULL) OR ("request_id" IS NOT NULL))),
    CONSTRAINT "quotes_conversion_receipt_consistent" CHECK ((("conversion_idempotency_key" IS NULL) = ("conversion_request_hash" IS NULL))),
    CONSTRAINT "quotes_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "quotes_decided_status_matches_decision" CHECK ((("status" <> ALL (ARRAY['approved'::"text", 'declined'::"text"])) OR ("decision" = "status"))),
    CONSTRAINT "quotes_decision_check" CHECK ((("decision" IS NULL) OR ("decision" = ANY (ARRAY['approved'::"text", 'declined'::"text"])))),
    CONSTRAINT "quotes_decision_fields_agree" CHECK (((("decision" IS NULL) = ("decided_at" IS NULL)) AND (("decision" IS NULL) = ("decision_method" IS NULL)) AND (("decision" IS NOT NULL) OR ("decision_note" IS NULL)))),
    CONSTRAINT "quotes_decision_method_check" CHECK ((("decision_method" IS NULL) OR ("decision_method" = ANY (ARRAY['offline_verbal'::"text", 'online'::"text", 'in_person'::"text"])))),
    CONSTRAINT "quotes_decision_note_check" CHECK ((("decision_note" IS NULL) OR (("char_length"(TRIM(BOTH FROM "decision_note")) >= 3) AND ("char_length"(TRIM(BOTH FROM "decision_note")) <= 1000)))),
    CONSTRAINT "quotes_publication_is_dated" CHECK ((("current_published_version_id" IS NULL) OR ("sent_at" IS NOT NULL))),
    CONSTRAINT "quotes_quote_number_check" CHECK (("quote_number" >= 1)),
    CONSTRAINT "quotes_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'awaiting_response'::"text", 'changes_requested'::"text", 'approved'::"text", 'declined'::"text", 'archived'::"text", 'converted'::"text"]))),
    CONSTRAINT "quotes_title_check" CHECK ((("char_length"(TRIM(BOTH FROM "title")) >= 2) AND ("char_length"(TRIM(BOTH FROM "title")) <= 160)))
);


ALTER TABLE "public"."quotes" OWNER TO "postgres";


COMMENT ON TABLE "public"."quotes" IS 'Quote identity. Members may read this table, never write it. Part 2 creates rows only through public.convert_request_to_quote; direct creation and every later lifecycle command arrive in Part 3 and after, each through its own checked function.';



COMMENT ON COLUMN "public"."quotes"."previous_status" IS 'Where restore puts the quote back. Null unless the quote is archived.';



COMMENT ON COLUMN "public"."quotes"."sent_at" IS 'When this quote first went out. Stamped by publish_quote and never cleared - a revision does not unsend what the customer already saw.';



COMMENT ON COLUMN "public"."quotes"."decision" IS 'The decision that is current right now, not a history. Revising an answered quote clears it, because the answer belonged to a version that is no longer the one on the table.';



COMMENT ON COLUMN "public"."quotes"."decision_method" IS 'Part 5A only ever writes offline_verbal. online arrives with the customer page, in_person with signatures.';



CREATE OR REPLACE FUNCTION "private"."quote_customer_document"("quote_row" "public"."quotes", "version_row" "public"."quote_versions", "recipient_name" "text", "recipient_email" "text", "include_money" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'quote', jsonb_build_object(
      'quote_number', quote_row.quote_number,
      'status', quote_row.status,
      'sent_at', quote_row.sent_at,
      'decision', quote_row.decision,
      'decided_at', quote_row.decided_at
    ),
    'recipient', jsonb_build_object(
      'name', recipient_name,
      'email', recipient_email
    ),
    'business', jsonb_build_object(
      'name', version_row.organization_name,
      'brand_color', version_row.brand_color,
      'has_logo', version_row.logo_object_key is not null
    ),
    'document', jsonb_build_object(
      'version_number', version_row.version_number,
      'published_at', version_row.published_at,
      'currency_code', version_row.currency_code,
      'client_display_name', version_row.client_display_name,
      'service_address_line1', version_row.service_address_line1,
      'service_address_line2', version_row.service_address_line2,
      'service_city', version_row.service_city,
      'service_state_region', version_row.service_state_region,
      'service_postal_code', version_row.service_postal_code,
      'service_country', version_row.service_country,
      'introduction', version_row.introduction,
      'client_message', version_row.client_message,
      'contract_disclaimer', version_row.contract_disclaimer,
      'show_quantities', version_row.show_quantities,
      'show_unit_prices', version_row.show_unit_prices and include_money,
      'show_line_totals', version_row.show_line_totals and include_money,
      'show_totals', version_row.show_totals and include_money
    ),
    'lines', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', line.id, 'position', line.position, 'line_kind', line.line_kind,
            'selection_kind', line.selection_kind,
            'is_recommended', line.is_recommended, 'category', line.category,
            'name', line.name, 'description', line.description, 'unit_label', line.unit_label,
            'image_attachment_id', line.image_attachment_id
          )
          || case when version_row.show_quantities
               then jsonb_build_object('quantity', line.quantity) else '{}'::jsonb end
          || case when version_row.show_unit_prices and include_money
               then jsonb_build_object('unit_price_minor', line.unit_price_minor) else '{}'::jsonb end
          || case when version_row.show_line_totals and include_money
               then jsonb_build_object('line_total_minor', line.line_total_minor) else '{}'::jsonb end
          order by line.position, line.id
        )
        from public.quote_version_lines as line
        where line.organization_id = version_row.organization_id
          and line.quote_id = version_row.quote_id
          and line.quote_version_id = version_row.id
      ),
      '[]'::jsonb
    ),
    'attachments', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', version_attachment.attachment_id,
            'name', version_attachment.display_name,
            'mime_type', file.mime_type,
            'size_bytes', file.size_bytes
          )
          order by version_attachment.position, version_attachment.id
        )
        from public.quote_version_attachments as version_attachment
        join public.attachments as file on file.id = version_attachment.attachment_id
        where version_attachment.organization_id = version_row.organization_id
          and version_attachment.quote_id = version_row.quote_id
          and version_attachment.quote_version_id = version_row.id
          and version_attachment.customer_visible
      ),
      '[]'::jsonb
    ),
    'totals', case when version_row.show_totals and include_money then jsonb_build_object(
      'subtotal_minor', version_row.subtotal_minor,
      'discount_name', version_row.discount_name,
      'discount_minor', version_row.discount_minor,
      'tax_name', version_row.tax_name,
      'tax_rate_basis_points', version_row.tax_rate_basis_points,
      'tax_minor', version_row.tax_minor,
      'total_minor', version_row.total_minor
    ) else null end,
    'deposit', case
      when include_money and version_row.deposit_type is not null and version_row.deposit_required_minor > 0
      then jsonb_build_object(
        'required_minor', version_row.deposit_required_minor,
        'satisfied', exists (
          select 1 from public.quote_deposit_events received
          where received.organization_id = version_row.organization_id
            and received.quote_id = version_row.quote_id
            and received.quote_version_id = version_row.id
            and received.event_type = 'received'
            and not exists (
              select 1 from public.quote_deposit_events reversal
              where reversal.organization_id = received.organization_id
                and reversal.reversed_event_id = received.id
            )
        )
      )
      else null
    end
  );
$$;


ALTER FUNCTION "private"."quote_customer_document"("quote_row" "public"."quotes", "version_row" "public"."quote_versions", "recipient_name" "text", "recipient_email" "text", "include_money" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."quote_customer_document"("quote_row" "public"."quotes", "version_row" "public"."quote_versions", "recipient_name" "text", "recipient_email" "text", "include_money" boolean) IS 'The only definition of what a customer may see. Called by public.resolve_quote_access_link for the customer and by public.quote_customer_preview for staff. No cost, no margin, no catalog source, no private file and no second recipient may ever be added here.';



