CREATE OR REPLACE FUNCTION "private"."read_job_recurrence"("rule" "jsonb") RETURNS TABLE("frequency" "text", "interval_count" integer, "weekdays" smallint[], "monthly_mode" "text", "month_day" smallint, "ordinal_week" smallint, "ordinal_weekday" smallint, "start_date" "date", "end_mode" "text", "duration_count" integer, "duration_unit" "text", "end_date" "date", "start_time" time without time zone, "end_time" time without time zone, "all_day" boolean)
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  resolved_start date := nullif(rule->>'start_date', '')::date;
  resolved_end date;
  chosen_frequency text := coalesce(nullif(rule->>'frequency', ''), 'weekly');
  chosen_end_mode text := coalesce(nullif(rule->>'end_mode', ''), 'after');
  chosen_duration integer := nullif(rule->>'duration_count', '')::integer;
  chosen_unit text := nullif(rule->>'duration_unit', '');
begin
  if resolved_start is null then
    raise exception 'A repeating schedule needs a start date.' using errcode = 'check_violation';
  end if;

  -- The table's own constraints would catch these, but a person reading "violates check constraint
  -- job_recurrence_weekly_has_days" learns nothing. Say the thing they need to go and fix.
  if chosen_frequency = 'weekly' and coalesce(
    case when jsonb_typeof(rule->'weekdays') = 'array' then jsonb_array_length(rule->'weekdays') end, 0
  ) not between 1 and 7 then
    raise exception 'Pick at least one day of the week.' using errcode = 'check_violation';
  end if;
  if chosen_frequency = 'monthly'
    and coalesce(nullif(rule->>'monthly_mode', ''), '') not in ('day_of_month', 'last_day', 'day_of_week')
  then
    raise exception 'Choose how the monthly schedule picks its day.' using errcode = 'check_violation';
  end if;

  if chosen_end_mode = 'on' then
    resolved_end := nullif(rule->>'end_date', '')::date;
    if resolved_end is null then
      raise exception 'A repeating schedule needs an end date.' using errcode = 'check_violation';
    end if;
  else
    if chosen_duration is null or chosen_unit is null then
      raise exception 'A repeating schedule needs a length.' using errcode = 'check_violation';
    end if;
    -- "Ends after 6 months" runs to the day before the same date six months later, so a six-month agreement
    -- starting on the 1st ends on the last day of the sixth month rather than spilling a day into the seventh.
    resolved_end := (
      resolved_start
      + make_interval(
          days => case when chosen_unit = 'day' then chosen_duration else 0 end,
          weeks => case when chosen_unit = 'week' then chosen_duration else 0 end,
          months => case when chosen_unit = 'month' then chosen_duration else 0 end,
          years => case when chosen_unit = 'year' then chosen_duration else 0 end
        )
      - interval '1 day'
    )::date;
  end if;

  if resolved_end < resolved_start then
    raise exception 'A repeating schedule cannot end before it starts.' using errcode = 'check_violation';
  end if;
  if resolved_end > resolved_start + 3660 then
    raise exception 'A repeating schedule cannot run more than ten years.' using errcode = 'check_violation';
  end if;

  return query
    select
      chosen_frequency,
      coalesce(nullif(rule->>'interval_count', '')::integer, 1),
      case
        when jsonb_typeof(rule->'weekdays') = 'array' then (
          select array_agg((value #>> '{}')::smallint order by (value #>> '{}')::smallint)
          from jsonb_array_elements(rule->'weekdays') as day(value)
        )
      end,
      nullif(rule->>'monthly_mode', ''),
      nullif(rule->>'month_day', '')::smallint,
      nullif(rule->>'ordinal_week', '')::smallint,
      nullif(rule->>'ordinal_weekday', '')::smallint,
      resolved_start,
      chosen_end_mode,
      case when chosen_end_mode = 'after' then chosen_duration end,
      case when chosen_end_mode = 'after' then chosen_unit end,
      resolved_end,
      nullif(rule->>'start_time', '')::time,
      nullif(rule->>'end_time', '')::time,
      coalesce((rule->>'all_day')::boolean, false);
end;
$$;


ALTER FUNCTION "private"."read_job_recurrence"("rule" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."recognize_invoice_if_settled"("target_organization_id" "uuid", "target_invoice_id" "uuid", "actor" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  invoice_row public.invoices;
  applied bigint;
begin
  select * into invoice_row
  from public.invoices
  where organization_id = target_organization_id and id = target_invoice_id
  for update;
  if not found then
    raise exception 'That invoice could not be found.' using errcode = 'P0404';
  end if;

  if invoice_row.issued_at is not null or invoice_row.recognized_at is not null
     or invoice_row.voided_at is not null or invoice_row.total_minor <= 0 then
    return false;
  end if;

  applied := private.invoice_allocated_minor(target_organization_id, target_invoice_id);
  if applied < invoice_row.total_minor then
    return false;
  end if;

  update public.invoices
  set recognized_at = now(),
      document_frozen_at = coalesce(document_frozen_at, now()),
      revision = revision + 1
  where organization_id = target_organization_id and id = target_invoice_id;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.recognized', actor, invoice_row.revision + 1, null,
    jsonb_build_object('reason', 'paid_in_full'), false, null
  );

  return true;
end;
$$;


ALTER FUNCTION "private"."recognize_invoice_if_settled"("target_organization_id" "uuid", "target_invoice_id" "uuid", "actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_communication_email_reserve_exhaustion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  active_allowance record;
  organization_name text;
begin
  select * into active_allowance
  from private.resolve_communication_email_allowance(new.organization_id, now());
  if not found then
    return null;
  end if;

  insert into public.communication_email_allowance_alerts (
    organization_id, allowance_period_id, alert_kind
  ) values (new.organization_id, active_allowance.period_id, 'essential_reserve_exhausted')
  on conflict on constraint communication_email_allowance_alerts_once do nothing;
  if not found then
    return null;
  end if;

  select organization.name into organization_name
  from public.organizations as organization
  where organization.id = new.organization_id;

  insert into public.platform_owner_notifications (kind, severity, title, body, target_kind, target_id)
  values (
    'communication_email_essential_reserve_exhausted',
    'urgent',
    'Protected essential email reserve exhausted',
    coalesce(organization_name, 'An organization')
      || ' has used its whole protected essential email reserve for the current billing period. '
      || 'Requested quotes, invoices, receipts, security notices, and direct replies are being held '
      || 'until the period resets or the allowance is raised.',
    'organization',
    new.organization_id
  );
  return null;
end;
$$;


ALTER FUNCTION "private"."record_communication_email_reserve_exhaustion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_communication_message_event"("p_organization_id" "uuid", "p_delivery_intent_id" "uuid", "p_event_kind" "text", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_attempt_number" integer DEFAULT NULL::integer, "p_reason_code" "text" DEFAULT NULL::"text", "p_reason_message" "text" DEFAULT NULL::"text", "p_retry_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_actor_kind" "text" DEFAULT 'system'::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_actor_email" "text" DEFAULT NULL::"text", "p_related_intent_id" "uuid" DEFAULT NULL::"uuid", "p_related_inbound_message_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  latest public.communication_message_events;
  new_id uuid;
begin
  if p_event_kind = 'deferred' then
    select * into latest
    from public.communication_message_events
    where delivery_intent_id = p_delivery_intent_id
    order by seq desc
    limit 1;

    if latest.id is not null
      and latest.event_kind = 'deferred'
      and latest.reason_code is not distinct from p_reason_code then
      perform set_config('ucrm.message_event_collapse', 'on', true);
      update public.communication_message_events
      set repeat_count = repeat_count + 1,
        last_occurred_at = greatest(p_occurred_at, latest.last_occurred_at),
        retry_at = p_retry_at,
        reason_message = coalesce(p_reason_message, reason_message),
        attempt_number = coalesce(p_attempt_number, attempt_number)
      where id = latest.id;
      perform set_config('ucrm.message_event_collapse', 'off', true);
      return latest.id;
    end if;
  end if;

  insert into public.communication_message_events (
    organization_id, delivery_intent_id, event_kind, occurred_at, last_occurred_at,
    attempt_number, reason_code, reason_message, retry_at,
    actor_kind, actor_user_id, actor_email, related_intent_id, related_inbound_message_id
  ) values (
    p_organization_id, p_delivery_intent_id, p_event_kind, p_occurred_at, p_occurred_at,
    p_attempt_number, p_reason_code, nullif(btrim(coalesce(p_reason_message, '')), ''), p_retry_at,
    coalesce(p_actor_kind, 'system'), p_actor_user_id,
    nullif(btrim(coalesce(p_actor_email, '')), ''), p_related_intent_id, p_related_inbound_message_id
  )
  returning id into new_id;
  return new_id;
end;
$$;


ALTER FUNCTION "private"."record_communication_message_event"("p_organization_id" "uuid", "p_delivery_intent_id" "uuid", "p_event_kind" "text", "p_occurred_at" timestamp with time zone, "p_attempt_number" integer, "p_reason_code" "text", "p_reason_message" "text", "p_retry_at" timestamp with time zone, "p_actor_kind" "text", "p_actor_user_id" "uuid", "p_actor_email" "text", "p_related_intent_id" "uuid", "p_related_inbound_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_form_submission_marketing_consent"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  consent jsonb := new.contact -> 'email_marketing_consent';
  submitted_email text;
  target_client_id uuid;
  method_id uuid;
begin
  if consent is null or jsonb_typeof(consent) <> 'object' or (consent ->> 'given') is distinct from 'true'
    or coalesce(btrim(consent ->> 'disclosure'), '') = '' then
    return null;
  end if;

  submitted_email := lower(nullif(btrim(new.contact ->> 'email'), ''));
  target_client_id := nullif(new.result ->> 'client_id', '')::uuid;
  if submitted_email is null or target_client_id is null then
    return null;
  end if;

  -- Only the exact email the visitor typed, and only if it belongs to the client this submission became.
  -- client_contact_methods.normalized_value for email is lower(trim(value)), matched here exactly.
  select method.id into method_id
  from public.client_contact_methods as method
  where method.organization_id = new.organization_id and method.client_id = target_client_id
    and method.kind = 'email' and method.normalized_value = submitted_email;
  if method_id is null then
    return null;
  end if;

  insert into public.client_marketing_consent_events (
    organization_id, client_id, client_contact_method_id, event_kind, source, source_event_key,
    disclosure, evidence, occurred_at
  ) values (
    new.organization_id, target_client_id, method_id, 'opt_in', 'public_form', 'form_submission:' || new.id,
    left(consent ->> 'disclosure', 2000),
    jsonb_build_object(
      'channel', 'form',
      'form_id', new.form_id,
      'form_version_id', new.form_version_id,
      'form_submission_id', new.id
    ),
    new.created_at
  )
  on conflict (organization_id, source, source_event_key) do nothing;

  return null;
end;
$$;


ALTER FUNCTION "private"."record_form_submission_marketing_consent"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_form_submission_sms_consent"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  consent jsonb := new.contact -> 'sms_service_consent';
  submitted_phone text;
  target_client_id uuid;
  method_id uuid;
begin
  if consent is null or jsonb_typeof(consent) <> 'object' or (consent ->> 'given') is distinct from 'true'
    or coalesce(btrim(consent ->> 'disclosure'), '') = '' then
    return null;
  end if;

  submitted_phone := nullif(regexp_replace(coalesce(new.contact ->> 'phone', ''), '[^0-9]', '', 'g'), '');
  target_client_id := nullif(new.result ->> 'client_id', '')::uuid;
  if submitted_phone is null or target_client_id is null then
    return null;
  end if;

  -- Only the exact number the visitor typed, and only if it belongs to the client this submission became. When
  -- that number already belongs to someone else (an ambiguous match), no consent is attached to anyone.
  select method.id into method_id
  from public.client_contact_methods as method
  where method.organization_id = new.organization_id and method.client_id = target_client_id
    and method.kind = 'phone' and method.normalized_value = submitted_phone;
  if method_id is null then
    return null;
  end if;

  insert into public.communication_sms_consent_events (
    organization_id, client_id, client_contact_method_id, event_kind, source, source_event_key,
    subjects, proof_method, evidence, occurred_at
  ) values (
    new.organization_id, target_client_id, method_id, 'opt_in', 'system', 'form_submission:' || new.id,
    array['service', 'work_updates'], 'web_form',
    jsonb_build_object(
      'channel', 'form',
      'form_id', new.form_id,
      'form_version_id', new.form_version_id,
      'form_submission_id', new.id,
      'disclosure', left(consent ->> 'disclosure', 1000)
    ),
    new.created_at
  )
  on conflict (organization_id, source, source_event_key) do nothing;

  return null;
end;
$$;


ALTER FUNCTION "private"."record_form_submission_sms_consent"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_invoice_event"("target_organization_id" "uuid", "target_invoice_id" "uuid", "target_invoice_number" integer, "target_client_id" "uuid", "new_event_type" "text", "actor" "uuid", "new_invoice_revision" integer DEFAULT NULL::integer, "new_reason" "text" DEFAULT NULL::"text", "new_metadata" "jsonb" DEFAULT '{}'::"jsonb", "new_price_sensitive" boolean DEFAULT false, "new_prior_document_snapshot" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  event_id uuid;
begin
  insert into public.invoice_events (
    organization_id, invoice_id, invoice_number, client_id, event_type, actor_id,
    invoice_revision, reason, metadata, price_sensitive, prior_document_snapshot
  ) values (
    target_organization_id, target_invoice_id, target_invoice_number, target_client_id,
    new_event_type, actor, new_invoice_revision, nullif(trim(coalesce(new_reason, '')), ''),
    coalesce(new_metadata, '{}'::jsonb),
    coalesce(new_price_sensitive, false) or new_prior_document_snapshot is not null,
    new_prior_document_snapshot
  )
  returning id into event_id;

  return event_id;
end;
$$;


