CREATE OR REPLACE FUNCTION "private"."refresh_quote_draft_totals"("target_version_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  version_row public.quote_versions;
  default_addon_ids uuid[];
  calculated jsonb;
begin
  select * into version_row from public.quote_versions where id = target_version_id;

  select coalesce(array_agg(id order by position, id), '{}'::uuid[])
  into default_addon_ids
  from public.quote_version_lines
  where organization_id = version_row.organization_id
    and quote_id = version_row.quote_id
    and quote_version_id = version_row.id
    and line_kind = 'priced' and selection_kind = 'optional' and is_recommended;

  calculated := private.calculate_quote_version(version_row.id, default_addon_ids);

  update public.quote_versions set
    subtotal_minor = (calculated ->> 'subtotal_minor')::bigint,
    discount_minor = (calculated ->> 'discount_minor')::bigint,
    tax_minor = (calculated ->> 'tax_minor')::bigint,
    total_minor = (calculated ->> 'total_minor')::bigint,
    deposit_required_minor = (calculated ->> 'deposit_required_minor')::bigint,
    cost_minor = (calculated ->> 'cost_minor')::bigint,
    profit_minor = (calculated ->> 'profit_minor')::bigint,
    margin_basis_points = (calculated ->> 'margin_basis_points')::bigint,
    calculation = calculated
  where id = version_row.id;

  return calculated;
end;
$$;


ALTER FUNCTION "private"."refresh_quote_draft_totals"("target_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."reject_published_quote_child_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_version_id uuid;
begin
  target_version_id := case when tg_op = 'DELETE' then old.quote_version_id else new.quote_version_id end;
  if exists (
    select 1 from public.quote_versions
    where id = target_version_id and status = 'published'
  ) then
    raise exception 'Published quote version content cannot be changed or deleted.' using errcode = 'P0409';
  end if;
  if tg_op = 'UPDATE' and old.quote_version_id is distinct from new.quote_version_id and exists (
    select 1 from public.quote_versions
    where id = old.quote_version_id and status = 'published'
  ) then
    raise exception 'Published quote version content cannot be moved.' using errcode = 'P0409';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "private"."reject_published_quote_child_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."reject_published_quote_version_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if old.status = 'published' then
    raise exception 'Published quote versions cannot be changed or deleted.' using errcode = 'P0409';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "private"."reject_published_quote_version_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."render_automation_email"("p_subject" "text", "p_body" "text", "p_customer_name" "text", "p_business_name" "text", "p_quote_number" "text", "p_quote_url" "text") RETURNS TABLE("subject" "text", "html_content" "text", "text_content" "text")
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
declare
  rendered_subject text; rendered_html text; rendered_text text; link_html text;
begin
  rendered_subject := replace(replace(replace(replace(coalesce(p_subject, ''),
    '{{customer_name}}', p_customer_name),
    '{{business_name}}', p_business_name),
    '{{quote_number}}', p_quote_number),
    '{{quote_link}}', p_quote_url);
  link_html := '<a href="' || private.html_escape(p_quote_url) || '">'
    || private.html_escape(p_quote_url) || '</a>';
  rendered_html := private.html_escape(p_body);
  rendered_html := replace(replace(replace(replace(rendered_html,
    '{{customer_name}}', private.html_escape(p_customer_name)),
    '{{business_name}}', private.html_escape(p_business_name)),
    '{{quote_number}}', private.html_escape(p_quote_number)),
    '{{quote_link}}', link_html);
  rendered_html := '<p>' || regexp_replace(rendered_html, E'\r?\n', '<br>', 'g') || '</p>';
  rendered_text := replace(replace(replace(replace(coalesce(p_body, ''),
    '{{customer_name}}', p_customer_name),
    '{{business_name}}', p_business_name),
    '{{quote_number}}', p_quote_number),
    '{{quote_link}}', p_quote_url);
  subject := rendered_subject; html_content := rendered_html; text_content := rendered_text;
  return next;
end;
$$;


ALTER FUNCTION "private"."render_automation_email"("p_subject" "text", "p_body" "text", "p_customer_name" "text", "p_business_name" "text", "p_quote_number" "text", "p_quote_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."render_automation_email"("p_subject" "text", "p_body" "text", "p_customer_name" "text", "p_business_name" "text", "p_quote_number" "text", "p_quote_url" "text") IS 'Renders an automation email from author subject/body and the four allow-listed variables. The HTML body is escaped before variable substitution so no authored or customer text can inject markup.';



