    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select replace(replace(replace(
    coalesce(p_body, ''),
    '{{customer_name}}', coalesce(p_customer_name, '')),
