CREATE OR REPLACE FUNCTION "private"."replace_checklist_template_items"("target_organization_id" "uuid", "target_template_id" "uuid", "items" "jsonb") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  written integer;
begin
  if jsonb_typeof(items) <> 'array' or jsonb_array_length(items) = 0 then
    raise exception 'A checklist needs at least one question.' using errcode = 'P0400';
  end if;
  if jsonb_array_length(items) > 100 then
    raise exception 'A checklist can hold up to 100 questions.' using errcode = 'P0400';
  end if;

  delete from public.checklist_template_items
  where organization_id = target_organization_id and template_id = target_template_id;

  insert into public.checklist_template_items (
    organization_id, template_id, position, label, item_type, required, options
  )
  select
    target_organization_id,
    target_template_id,
    (ordinality - 1)::integer,
    trim(item.value ->> 'label'),
    item.value ->> 'item_type',
    coalesce((item.value ->> 'required')::boolean, false),
    case
      when item.value ->> 'item_type' = 'dropdown' then (
        select array_agg(trim(choice.value #>> '{}') order by choice.ordinality)
        from jsonb_array_elements(item.value -> 'options') with ordinality as choice(value, ordinality)
        where length(trim(choice.value #>> '{}')) > 0
      )
      else null
    end
  from jsonb_array_elements(items) with ordinality as item(value, ordinality);

  get diagnostics written = row_count;
  return written;
end;
$$;


ALTER FUNCTION "private"."replace_checklist_template_items"("target_organization_id" "uuid", "target_template_id" "uuid", "items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."replace_checklist_template_items"("target_organization_id" "uuid", "target_template_id" "uuid", "items" "jsonb") IS 'Rewrites a template''s questions from one array, in array order.';



CREATE OR REPLACE FUNCTION "private"."request_pipeline_stage"("request_status" "text", "has_assessment" boolean, "assessment_starts_at" timestamp with time zone, "assessment_completed_at" timestamp with time zone) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case
    -- The Request is no longer live commercial work, so it leaves the board but keeps its identity.
    when request_status in ('completed', 'converted', 'archived') then 'request_closed'
    when assessment_completed_at is not null or request_status = 'assessment_completed'
      then 'assessment_completed'
    when not has_assessment then 'new_request'
    when assessment_starts_at is null then 'assessment_unscheduled'
    else 'assessment_scheduled'
  end;
$$;


