CREATE OR REPLACE FUNCTION "private"."resolve_client_billing_address"("target_organization_id" "uuid", "target_client_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  client_row public.clients;
  billing_property public.properties;
begin
  select * into client_row
  from public.clients
  where organization_id = target_organization_id and id = target_client_id;
  if not found then
    raise exception 'That client could not be found.' using errcode = 'P0404';
  end if;

  if client_row.billing_address_line1 is not null then
    return jsonb_build_object(
      'source', 'client',
      'property_id', null,
      'address_line1', client_row.billing_address_line1,
      'address_line2', client_row.billing_address_line2,
      'city', client_row.billing_city,
      'state_region', client_row.billing_state_region,
      'postal_code', client_row.billing_postal_code,
      'country', client_row.billing_country
    );
  end if;

  select * into billing_property
  from public.properties
  where organization_id = target_organization_id
    and client_id = target_client_id
    and is_billing_address
    and deleted_at is null;

  if not found then
    return jsonb_build_object('source', 'none', 'property_id', null);
  end if;

  return jsonb_build_object(
    'source', 'property',
    'property_id', billing_property.id,
    'address_line1', billing_property.address_line1,
    'address_line2', billing_property.address_line2,
    'city', billing_property.city,
    'state_region', billing_property.state_region,
    'postal_code', billing_property.postal_code,
    'country', billing_property.country
  );
end;
$$;


ALTER FUNCTION "private"."resolve_client_billing_address"("target_organization_id" "uuid", "target_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."resolve_client_payment_term"("target_organization_id" "uuid", "target_client_id" "uuid", "invoice_term_override_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."invoice_payment_terms"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  client_row public.clients;
  settings_row public.organization_settings;
  resolved public.invoice_payment_terms;
  candidate_id uuid;
begin
  select * into client_row
  from public.clients
  where organization_id = target_organization_id and id = target_client_id;
  if not found then
    raise exception 'That client could not be found.' using errcode = 'P0404';
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id;

  candidate_id := coalesce(
    invoice_term_override_id,
    client_row.billing_payment_term_id,
    case
      when client_row.client_type = 'company' then settings_row.invoice_default_term_commercial_id
      else settings_row.invoice_default_term_residential_id
    end
  );

  if candidate_id is not null then
    select * into resolved
    from public.invoice_payment_terms
    where organization_id = target_organization_id and id = candidate_id;
    if found then
      return resolved;
    end if;
  end if;

  select * into resolved
  from public.invoice_payment_terms
  where organization_id = target_organization_id and rule = 'on_receipt' and is_protected;

  if not found then
    raise exception 'This organization has no payment terms set up.' using errcode = 'P0404';
  end if;

  return resolved;
end;
$$;


ALTER FUNCTION "private"."resolve_client_payment_term"("target_organization_id" "uuid", "target_client_id" "uuid", "invoice_term_override_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."resolve_communication_email_allowance"("target_organization_id" "uuid", "at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("period_id" "uuid", "period_starts_at" timestamp with time zone, "period_ends_at" timestamp with time zone, "operational_limit_state" "text", "operational_limit_value" integer, "essential_limit_state" "text", "essential_limit_value" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with active_period as (
    select period.id, period.starts_at, period.ends_at
    from public.communication_email_allowance_periods as period
    where period.organization_id = target_organization_id and period.starts_at <= at and period.ends_at > at
    order by period.starts_at desc limit 1
  ), package_version as (
    select assignment.package_version_id
    from public.organization_package_assignments as assignment
    where assignment.organization_id = target_organization_id and assignment.effective_at <= at
    order by assignment.effective_at desc, assignment.id desc limit 1
  ), resolved_limits as (
    select limit_key, limit_state, limit_value
    from public.platform_package_version_limits
    where package_version_id = (select package_version_id from package_version)
      and limit_key in ('operational_email_recipients', 'essential_email_recipients')
  ), active_overrides as (
    select limit_key, limit_state, limit_value
    from public.organization_limit_overrides
    where organization_id = target_organization_id
      and limit_key in ('operational_email_recipients', 'essential_email_recipients')
      and starts_at <= at and (expires_at is null or expires_at > at)
  )
  select period.id, period.starts_at, period.ends_at,
    coalesce(operational_override.limit_state, operational.limit_state),
    coalesce(operational_override.limit_value, operational.limit_value),
    coalesce(essential_override.limit_state, essential.limit_state),
    coalesce(essential_override.limit_value, essential.limit_value)
  from active_period as period
  left join resolved_limits as operational on operational.limit_key = 'operational_email_recipients'
  left join resolved_limits as essential on essential.limit_key = 'essential_email_recipients'
  left join active_overrides as operational_override on operational_override.limit_key = 'operational_email_recipients'
  left join active_overrides as essential_override on essential_override.limit_key = 'essential_email_recipients';
$$;


ALTER FUNCTION "private"."resolve_communication_email_allowance"("target_organization_id" "uuid", "at" timestamp with time zone) OWNER TO "postgres";


