CREATE OR REPLACE FUNCTION "private"."resolve_communication_email_retry_deadline"("p_retry_class" "text", "p_queued_at" timestamp with time zone, "p_window_ends_at" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case p_retry_class
    when 'standard' then p_queued_at + interval '24 hours'
    when 'payment_receipt' then p_queued_at + interval '72 hours'
    when 'appointment_reminder' then p_window_ends_at
    when 'optional_followup' then least(
      coalesce(p_window_ends_at, 'infinity'::timestamptz), p_queued_at + interval '24 hours')
  end;
$$;


ALTER FUNCTION "private"."resolve_communication_email_retry_deadline"("p_retry_class" "text", "p_queued_at" timestamp with time zone, "p_window_ends_at" timestamp with time zone) OWNER TO "postgres";


