CREATE OR REPLACE FUNCTION "private"."resolve_communication_email_warmup_ceiling"("p_organization_id" "uuid", "p_domain_id" "uuid", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  warmup_clock timestamptz;
  elapsed_days integer;
  chosen_stage text;
  ceiling integer;
begin
  select coalesce(domain.warmup_started_at, domain.verified_at)
  into warmup_clock
  from public.communication_email_domains domain
  where domain.organization_id = p_organization_id
    and domain.id = p_domain_id;

  if warmup_clock is null or warmup_clock > p_at then
    return null;
  end if;

  elapsed_days := floor(extract(epoch from (p_at - warmup_clock)) / 86400.0)::integer;

  if elapsed_days < 3 then
    chosen_stage := 'days_1_3';
  elsif elapsed_days < 7 then
    chosen_stage := 'days_4_7';
  elsif elapsed_days < 14 then
    chosen_stage := 'days_8_14';
  else
    return null;
  end if;

  select coalesce(
    (
      select org_stage.daily_ceiling
      from public.communication_email_warmup_stages org_stage
      where org_stage.scope = 'organization'
        and org_stage.organization_id = p_organization_id
        and org_stage.stage_key = chosen_stage
        and org_stage.effective_from <= p_at
        and org_stage.effective_to is null
    ),
    (
      select platform_stage.daily_ceiling
      from public.communication_email_warmup_stages platform_stage
      where platform_stage.scope = 'platform'
        and platform_stage.stage_key = chosen_stage
        and platform_stage.effective_from <= p_at
        and platform_stage.effective_to is null
    )
  )
  into ceiling;

  return ceiling;
end;
$$;


ALTER FUNCTION "private"."resolve_communication_email_warmup_ceiling"("p_organization_id" "uuid", "p_domain_id" "uuid", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."resolve_job_reminders_as_invoiced"("target_organization_id" "uuid", "target_invoice_id" "uuid", "actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  consumed_ids uuid[];
  reminder_row public.job_invoice_reminders;
  resolved_count integer := 0;
  month_end_jobs uuid[] := '{}'::uuid[];
  month_end_job_id uuid;
begin
  -- Which pending reminders did this bill's claims answer? Bounded work: the claims of one invoice, which
  -- claim_invoice_sources caps, joined to the reminders of those jobs. invoice_sources_root_idx serves the
  -- claim side and job_invoice_reminders_pending_due_idx serves the reminder side.
  select coalesce(array_agg(distinct reminder.id order by reminder.id), '{}'::uuid[])
    into consumed_ids
  from public.invoice_sources as claim
  join public.job_invoice_reminders as reminder
    on reminder.organization_id = claim.organization_id
   and reminder.job_id = claim.job_id
   and reminder.status = 'pending'
   and (
        claim.source_kind = 'job_total'
     or (claim.source_kind = 'reminder_period' and reminder.id = claim.reminder_id)
     or (claim.source_kind = 'visit'
         and reminder.reminder_kind = 'per_visit'
         and reminder.visit_id = claim.visit_id)
   )
  where claim.organization_id = target_organization_id
    and claim.root_invoice_id = target_invoice_id;

  if array_length(consumed_ids, 1) is null then
    return 0;
  end if;

  -- Locked in id order before the write, so two invoices racing over one job's reminders queue behind each
  -- other rather than deadlocking. Same lock ordering claim_invoice_sources uses for jobs and visits.
  perform 1
  from public.job_invoice_reminders
  where organization_id = target_organization_id
    and id = any(consumed_ids)
  order by id
  for update;

  for reminder_row in
    update public.job_invoice_reminders
    set status = 'resolved', resolution = 'invoiced', resolved_at = now(), resolved_by = actor
    where organization_id = target_organization_id
      and id = any(consumed_ids)
      -- Re-checked under the lock: a concurrent dismiss may have answered one of these first.
      and status = 'pending'
    returning *
  loop
    resolved_count := resolved_count + 1;

    -- related_invoice_id is what makes the job's own history say which bill answered this prompt, rather
    -- than only that something did.
    insert into public.job_events
      (organization_id, job_id, event_type, actor_id, related_invoice_id, metadata)
    values (
      target_organization_id,
      reminder_row.job_id,
      'invoice_reminder_invoiced',
      actor,
      target_invoice_id,
      jsonb_build_object('reminder_kind', reminder_row.reminder_kind, 'due_on', reminder_row.due_on)
    );

    -- A month-end reminder is a standing arrangement, not a one-off prompt: clearing one rolls the next one
    -- forward. Collected per job and rolled once below, so a job with a backlog does not seed a pile.
    if reminder_row.reminder_kind = 'monthly_last_day'
       and not (reminder_row.job_id = any(month_end_jobs)) then
      month_end_jobs := month_end_jobs || reminder_row.job_id;
    end if;
  end loop;

  -- After the loop, not inside it: seed_next_month_end_reminder is a no-op while any month-end reminder is
  -- still pending, so a job whose later months are still open correctly rolls nothing.
  foreach month_end_job_id in array month_end_jobs loop
    perform private.seed_next_month_end_reminder(target_organization_id, month_end_job_id, actor);
  end loop;

  return resolved_count;
end;
$$;


ALTER FUNCTION "private"."resolve_job_reminders_as_invoiced"("target_organization_id" "uuid", "target_invoice_id" "uuid", "actor" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."resolve_job_reminders_as_invoiced"("target_organization_id" "uuid", "target_invoice_id" "uuid", "actor" "uuid") IS 'Clears the invoice reminders a bill actually answered, read from the claims on that bill: every pending reminder on a job billed whole, the named reminder of a billed period, and the per-visit reminder of each billed visit. Rolls a job''s month-end reminder forward only when a month-end reminder was one of them. Called only by create_invoice_from_work, whose caller already proved invoices.create by billing the work.';



CREATE OR REPLACE FUNCTION "private"."resolve_property_tax"("target_organization_id" "uuid", "target_property_id" "uuid") RETURNS TABLE("source" "text", "name" "text", "rate_basis_points" integer, "rate_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  pinned_rate_id uuid;
  rate_row public.organization_tax_rates;
  default_source text;
  default_rate_id uuid;
begin
  select property.tax_rate_id into pinned_rate_id
  from public.properties as property
  where property.id = target_property_id and property.organization_id = target_organization_id;

  if pinned_rate_id is not null then
    select * into rate_row
    from public.organization_tax_rates
    where id = pinned_rate_id and organization_id = target_organization_id;

    if rate_row.id is not null then
      return query select 'property_default'::text, rate_row.name, rate_row.rate_basis_points, rate_row.id;
      return;
    end if;
    -- Fell through: the pinned rate is gone, which the delete command should never allow while pinned.
    -- Treat it the same as never having been configured rather than guess.
  end if;

  select settings.tax_default_source, settings.tax_default_rate_id
  into default_source, default_rate_id
  from public.organization_settings as settings
  where settings.organization_id = target_organization_id;

  if default_source = 'rate' then
    select * into rate_row
    from public.organization_tax_rates
    where id = default_rate_id and organization_id = target_organization_id;

    if rate_row.id is not null then
      return query select 'business_default'::text, rate_row.name, rate_row.rate_basis_points, rate_row.id;
      return;
    end if;
  elsif default_source = 'no_tax' then
    return query select 'business_default'::text, null::text, 0, null::uuid;
    return;
  end if;

  return query select 'not_configured'::text, null::text, 0, null::uuid;
end;
$$;


ALTER FUNCTION "private"."resolve_property_tax"("target_organization_id" "uuid", "target_property_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."restrict_platform_notification_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.id <> old.id
    or new.correlation_id is distinct from old.correlation_id
    or new.kind <> old.kind
    or new.severity <> old.severity
    or new.title <> old.title
    or new.body is distinct from old.body
    or new.target_kind <> old.target_kind
    or new.target_id is distinct from old.target_id
    or new.created_at <> old.created_at
  then
    raise exception 'Only the read state of a notification can change.' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


