CREATE TABLE IF NOT EXISTS "public"."invoice_payment_allocations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "invoice_id" "uuid" NOT NULL,
    "invoice_number" integer NOT NULL,
    "client_id" "uuid" NOT NULL,
    "entry_type" "text" NOT NULL,
    "amount_minor" bigint NOT NULL,
    "currency_code" "text" NOT NULL,
    "payment_event_id" "uuid",
    "deposit_event_id" "uuid",
    "reversed_allocation_id" "uuid",
    "reason" "text",
    "actor_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "invoice_payment_allocations_amount_minor_check" CHECK ((("amount_minor" > 0) AND ("amount_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "invoice_payment_allocations_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "invoice_payment_allocations_entry_type_check" CHECK (("entry_type" = ANY (ARRAY['applied'::"text", 'unapplied'::"text"]))),
    CONSTRAINT "invoice_payment_allocations_invoice_number_check" CHECK (("invoice_number" >= 1)),
    CONSTRAINT "invoice_payment_allocations_one_source" CHECK ((("payment_event_id" IS NOT NULL) <> ("deposit_event_id" IS NOT NULL))),
    CONSTRAINT "invoice_payment_allocations_reason_check" CHECK ((("reason" IS NULL) OR ("char_length"("reason") <= 2000))),
    CONSTRAINT "invoice_payment_allocations_reversal_shape" CHECK (((("entry_type" = 'applied'::"text") AND ("reversed_allocation_id" IS NULL)) OR (("entry_type" = 'unapplied'::"text") AND ("reversed_allocation_id" IS NOT NULL))))
);


ALTER TABLE "public"."invoice_payment_allocations" OWNER TO "postgres";


COMMENT ON TABLE "public"."invoice_payment_allocations" IS 'Retained entries saying which money sits on which bill. Immutable: taking money off an invoice appends an ''unapplied'' entry pointing at the application it reverses, and moving money is one of each in a single transaction. Not a child of the invoice, so a deleted draft never erases what happened to money.';



CREATE OR REPLACE FUNCTION "private"."reverse_invoice_allocation"("invoice_row" "public"."invoices", "allocation_row" "public"."invoice_payment_allocations", "actor" "uuid", "new_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  reversal_id uuid;
begin
  if allocation_row.entry_type <> 'applied' then
    raise exception 'Only a payment that was applied to an invoice can be taken back off.'
      using errcode = 'check_violation';
  end if;
  if exists (
    select 1 from public.invoice_payment_allocations as existing
    where existing.organization_id = allocation_row.organization_id
      and existing.reversed_allocation_id = allocation_row.id
  ) then
    raise exception 'That payment has already been taken off this invoice.' using errcode = 'check_violation';
  end if;
  if invoice_row.recognized_at is not null then
    raise exception 'This draft was settled by that payment, so it cannot be taken back off.'
      using errcode = 'check_violation';
  end if;

  insert into public.invoice_payment_allocations (
    organization_id, invoice_id, invoice_number, client_id, entry_type, amount_minor, currency_code,
    payment_event_id, deposit_event_id, reversed_allocation_id, reason, actor_user_id
  ) values (
    allocation_row.organization_id, allocation_row.invoice_id, allocation_row.invoice_number,
    allocation_row.client_id, 'unapplied', allocation_row.amount_minor, allocation_row.currency_code,
    allocation_row.payment_event_id, allocation_row.deposit_event_id, allocation_row.id,
    nullif(trim(coalesce(new_reason, '')), ''), actor
  )
  returning id into reversal_id;

  perform private.record_invoice_event(
    invoice_row.organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.payment_unapplied', actor, invoice_row.revision, new_reason,
    jsonb_build_object(
      'allocation_id', reversal_id,
      'reversed_allocation_id', allocation_row.id,
      'amount_minor', allocation_row.amount_minor,
      'source', case when allocation_row.deposit_event_id is not null then 'quote_deposit' else 'payment' end
    ),
    true, null
  );

  return reversal_id;
end;
$$;


ALTER FUNCTION "private"."reverse_invoice_allocation"("invoice_row" "public"."invoices", "allocation_row" "public"."invoice_payment_allocations", "actor" "uuid", "new_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."seed_invoice_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  receipt_term_id uuid;
begin
  perform private.seed_invoice_payment_terms(new.organization_id);

  select id into receipt_term_id
  from public.invoice_payment_terms
  where organization_id = new.organization_id and rule = 'on_receipt' and is_protected;

  if new.invoice_default_term_residential_id is null then
    new.invoice_default_term_residential_id := receipt_term_id;
  end if;
  if new.invoice_default_term_commercial_id is null then
    new.invoice_default_term_commercial_id := receipt_term_id;
  end if;

  return new;
end;
$$;


