CREATE OR REPLACE FUNCTION "private"."seed_next_month_end_reminder"("target_organization_id" "uuid", "target_job_id" "uuid", "actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  job_row public.jobs;
  last_due date;
  next_due date;
begin
  select * into job_row
  from public.jobs
  where organization_id = target_organization_id and id = target_job_id;

  if not found or job_row.billing_timing <> 'month_end' or job_row.status <> 'active' then
    return;
  end if;

  if exists (
    select 1 from public.job_invoice_reminders
    where organization_id = target_organization_id
      and job_id = target_job_id
      and reminder_kind = 'monthly_last_day'
      and status = 'pending'
  ) then
    return;
  end if;

  select max(due_on) into last_due
  from public.job_invoice_reminders
  where organization_id = target_organization_id
    and job_id = target_job_id
    and reminder_kind = 'monthly_last_day';

  if last_due is null then
    next_due := private.month_end_of(private.organization_today(target_organization_id));
  else
    next_due := private.month_end_of((last_due + interval '1 day')::date);
  end if;

  if job_row.contract_end_date is not null and next_due > job_row.contract_end_date then
    return;
  end if;

  perform private.create_invoice_reminder(
    target_organization_id, target_job_id, 'monthly_last_day', next_due, actor
  );
end;
$$;


ALTER FUNCTION "private"."seed_next_month_end_reminder"("target_organization_id" "uuid", "target_job_id" "uuid", "actor" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."seed_next_month_end_reminder"("target_organization_id" "uuid", "target_job_id" "uuid", "actor" "uuid") IS 'Keeps exactly one open month-end reminder on a month-end-billed active job, this month''s, honoring the contract end. Called on choosing month-end billing and on dismissing the current one, so the series rolls forward with no cron and no unbounded backlog.';



