CREATE OR REPLACE FUNCTION "private"."write_job_recurrence"("target_organization_id" "uuid", "target_job_id" "uuid", "rule" "jsonb", "first_position" integer DEFAULT 0) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  parsed record;
  written integer;
  ceiling integer := private.job_recurrence_limit();
begin
  select * into parsed from private.read_job_recurrence(rule);

  insert into public.job_recurrence_rules (
    job_id, organization_id, frequency, interval_count, weekdays, monthly_mode, month_day,
    ordinal_week, ordinal_weekday, start_date, end_mode, duration_count, duration_unit, end_date,
    start_time, end_time, all_day
  ) values (
    target_job_id, target_organization_id, parsed.frequency, parsed.interval_count, parsed.weekdays,
    parsed.monthly_mode, parsed.month_day, parsed.ordinal_week, parsed.ordinal_weekday, parsed.start_date,
    parsed.end_mode, parsed.duration_count, parsed.duration_unit, parsed.end_date,
    parsed.start_time, parsed.end_time, parsed.all_day
  )
  on conflict (job_id) do update set
    frequency = excluded.frequency,
    interval_count = excluded.interval_count,
    weekdays = excluded.weekdays,
    monthly_mode = excluded.monthly_mode,
    month_day = excluded.month_day,
    ordinal_week = excluded.ordinal_week,
    ordinal_weekday = excluded.ordinal_weekday,
    start_date = excluded.start_date,
    end_mode = excluded.end_mode,
    duration_count = excluded.duration_count,
    duration_unit = excluded.duration_unit,
    end_date = excluded.end_date,
    start_time = excluded.start_time,
    end_time = excluded.end_time,
    all_day = excluded.all_day;

  insert into public.job_visits (
    organization_id, job_id, position, visit_date, start_time, end_time, all_day, source
  )
  select
    target_organization_id,
    target_job_id,
    first_position + (row_number() over (order by day))::integer - 1,
    day,
    parsed.start_time,
    parsed.end_time,
    parsed.all_day,
    'generated'
  from private.job_recurrence_dates(
    parsed.frequency, parsed.interval_count, parsed.weekdays, parsed.monthly_mode,
    parsed.month_day, parsed.ordinal_week, parsed.ordinal_weekday, parsed.start_date, parsed.end_date
  ) as day;

  get diagnostics written = row_count;

  if written < 1 then
    raise exception 'That schedule does not land on any day. Check the days and dates.'
      using errcode = 'check_violation';
  end if;
  if written > ceiling then
    raise exception 'That schedule makes % visits. The most we create at once is %. Try a nearer end date.',
      written, ceiling using errcode = 'check_violation';
  end if;

  -- The contract window is what "Ending soon" reads, and it is the rule's window, not the last visit's date.
  update public.jobs
  set contract_start_date = parsed.start_date, contract_end_date = parsed.end_date
  where id = target_job_id and organization_id = target_organization_id;

  return written;
end;
$$;


ALTER FUNCTION "private"."write_job_recurrence"("target_organization_id" "uuid", "target_job_id" "uuid", "rule" "jsonb", "first_position" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."organization_ownership_transfers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "from_user_id" "uuid" NOT NULL,
    "to_user_id" "uuid" NOT NULL,
    "state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "resolved_by" "uuid",
    CONSTRAINT "organization_ownership_transfers_distinct_parties_check" CHECK (("from_user_id" <> "to_user_id")),
    CONSTRAINT "organization_ownership_transfers_resolution_check" CHECK (((("state" = 'pending'::"text") = ("resolved_at" IS NULL)) AND (("state" = 'pending'::"text") = ("resolved_by" IS NULL)))),
    CONSTRAINT "organization_ownership_transfers_state_check" CHECK (("state" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'declined'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."organization_ownership_transfers" OWNER TO "postgres";


COMMENT ON TABLE "public"."organization_ownership_transfers" IS 'One ownership handover: the owner asked, and the administrator has not yet answered. Until state leaves pending nothing about anyone''s role has changed. Read-only for authenticated; every write is one of the three SECURITY DEFINER commands in this migration.';



COMMENT ON COLUMN "public"."organization_ownership_transfers"."from_user_id" IS 'The owner who asked. Re-checked as the active owner at acceptance -- a transfer requested last month by someone who is no longer the owner cannot be accepted.';



COMMENT ON COLUMN "public"."organization_ownership_transfers"."to_user_id" IS 'The administrator who must accept. Also the subject of all four ownership.transfer_* history events, so one person''s team history reads as the whole story of the handover.';



COMMENT ON COLUMN "public"."organization_ownership_transfers"."resolved_by" IS 'Who ended it: the recipient on accept or decline, the requester on cancel. Never null once settled.';



CREATE OR REPLACE FUNCTION "public"."accept_ownership_transfer"("target_transfer_id" "uuid", "accepting_user_id" "uuid") RETURNS "public"."organization_ownership_transfers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  transfer public.organization_ownership_transfers;
begin
  select * into transfer
  from public.organization_ownership_transfers
  where id = target_transfer_id
  for update;

  if not found then
    raise exception 'That ownership handover no longer exists.' using errcode = 'no_data_found';
  end if;

  -- Taken after the row lock, and in that order every time, so accept and close never deadlock each other.
  perform pg_advisory_xact_lock(hashtext('ownership_transfer:' || transfer.organization_id::text));

  if transfer.state <> 'pending' then
    raise exception 'That ownership handover has already been answered.' using errcode = 'check_violation';
  end if;

  if transfer.to_user_id <> accepting_user_id then
    raise exception 'Only the person the handover was sent to can accept it.'
      using errcode = 'check_violation';
  end if;

  -- Standing is re-checked now, not trusted from request time: the requester may have been deactivated, or
  -- the recipient may have been demoted, since the request was made.
  if not exists (
    select 1
    from public.organization_members as membership
    where membership.organization_id = transfer.organization_id
      and membership.user_id = transfer.from_user_id
      and membership.role = 'owner'
      and membership.status = 'active'
  ) then
    raise exception 'The person who offered ownership is no longer the owner.'
      using errcode = 'check_violation';
  end if;

  if not exists (
    select 1
    from public.organization_members as membership
    where membership.organization_id = transfer.organization_id
      and membership.user_id = transfer.to_user_id
      and membership.role = 'admin'
      and membership.status = 'active'
  ) then
    raise exception 'Ownership can only be handed to an active administrator.'
      using errcode = 'check_violation';
  end if;

  -- Demote first, promote second. The at-most-one-owner partial index is checked on every write, so the
  -- other order would fail immediately; the deferred trigger then confirms exactly one owner at commit.
  update public.organization_members
  set role = 'admin',
      access_revision = access_revision + 1
  where organization_id = transfer.organization_id
    and user_id = transfer.from_user_id;

  update public.organization_members
  set role = 'owner',
      access_revision = access_revision + 1
  where organization_id = transfer.organization_id
    and user_id = transfer.to_user_id;

  update public.organization_ownership_transfers
  set state = 'accepted',
      resolved_at = now(),
      resolved_by = accepting_user_id
  where id = transfer.id
  returning * into transfer;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    transfer.organization_id, 'ownership.transfer_accepted', 'member', accepting_user_id,
    transfer.to_user_id, jsonb_build_object('transfer_id', transfer.id)
  );

  return transfer;
end;
$$;


ALTER FUNCTION "public"."accept_ownership_transfer"("target_transfer_id" "uuid", "accepting_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_ownership_transfer"("target_transfer_id" "uuid", "accepting_user_id" "uuid") IS 'The recipient takes over. Demotes the old owner to administrator before promoting the new one, in one transaction. Re-checks both sides'' standing first -- a stale request cannot be cashed in.';



CREATE OR REPLACE FUNCTION "public"."accept_website_chat_first_message"("widget_public_token" "uuid", "requesting_origin" "text", "new_session_token_hash" "text", "new_idempotency_key" "text", "visitor_name" "text", "visitor_phone_e164" "text", "visitor_email" "text", "message_body" "text", "consent_transactional_sms" boolean DEFAULT false, "visitor_ip_hash" "text" DEFAULT NULL::"text", "new_attribution" "jsonb" DEFAULT '{}'::"jsonb", "sms_consent_disclosure" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "statement_timeout" TO '5000'
    AS $$
declare
  widget record;
  normalized_origin text := lower(btrim(coalesce(requesting_origin, '')));
  origin_allowed boolean;
  clean_name text;
  given_name text;
  family_name text;
  first_space integer;
  clean_phone text;
  clean_email text;
  clean_body text;
  clean_idempotency_key text;
  match_phone text;
  match_email text;
  phone_candidate uuid;
  email_candidate uuid;
  phone_match_count integer := 0;
  email_match_count integer := 0;
  resolved_client_id uuid;
  resolved_match_status text;
  existing_session public.website_chat_sessions;
  existing_message_id uuid;
  limit_row record;
  active_period record;
  bucket record;
  new_session public.website_chat_sessions;
  new_message_id uuid;
  rate_check record;
  new_client_id uuid;
  clean_consent_disclosure text;
begin
  clean_idempotency_key := nullif(btrim(coalesce(new_idempotency_key, '')), '');
  -- One "Name" field, HighLevel's own shape, split the way HighLevel splits it: everything up to
  -- the first space is the given name, the whole remainder is the family name. Nothing the visitor
  -- typed is ever dropped, and a single-word name simply has no family name.
  clean_name := nullif(btrim(regexp_replace(coalesce(visitor_name, ''), '\s+', ' ', 'g')), '');
  first_space := position(' ' in coalesce(clean_name, ''));
  if first_space > 0 then
    given_name := substr(clean_name, 1, first_space - 1);
    family_name := nullif(btrim(substr(clean_name, first_space + 1)), '');
  else
    given_name := clean_name;
    family_name := null;
  end if;
  clean_phone := nullif(btrim(coalesce(visitor_phone_e164, '')), '');
  clean_email := lower(nullif(btrim(coalesce(visitor_email, '')), ''));
  clean_body := nullif(btrim(coalesce(message_body, '')), '');
  -- Service-SMS consent counts only with a phone number and the disclosure the route built from the business name
  -- the widget showed. A bare "true" (older widget builds pre-ticked the box) is not consent evidence.
  clean_consent_disclosure := case
    when coalesce(consent_transactional_sms, false) and clean_phone is not null
      then left(nullif(btrim(coalesce(sms_consent_disclosure, '')), ''), 1000)
  end;

  -- The name is bounded here, not only by the session's check constraint, because the Client is
  -- inserted first: a one character name would otherwise raise on `clients.display_name` instead of
  -- being refused. The route's own schema already refuses it; this is the command standing on its own.
  if normalized_origin = '' or clean_idempotency_key is null or clean_name is null
    or char_length(clean_name) < 2 or char_length(clean_name) > 120
    or clean_body is null or nullif(btrim(coalesce(new_session_token_hash, '')), '') is null then
    return jsonb_build_object('status', 'refused');
  end if;
  if clean_phone is null and clean_email is null then
    return jsonb_build_object('status', 'refused');
  end if;

  select w.id, w.organization_id, w.published, w.disabled_at, w.suspended_at, w.source_label
  into widget
  from public.website_chat_widgets w
  where w.public_token = widget_public_token;
  if not found then
    return jsonb_build_object('status', 'refused');
  end if;

  select exists (
    select 1 from public.website_chat_widget_origins o
    where o.widget_id = widget.id and o.origin = normalized_origin
  ) into origin_allowed;
  if not origin_allowed
    or widget.suspended_at is not null
    or widget.disabled_at is not null
    or not widget.published then
    return jsonb_build_object('status', 'refused');
  end if;

  -- A retry is answered from the existing session before any limit is consumed or any unit claimed.
  select * into existing_session
  from public.website_chat_sessions s
  where s.widget_id = widget.id and s.idempotency_key = clean_idempotency_key;
  if found then
    select m.id into existing_message_id
    from public.website_chat_messages m
    where m.session_id = existing_session.id
    order by m.created_at, m.id
    limit 1;
    return jsonb_build_object(
      'status', 'accepted',
      'replayed', true,
      'session_id', existing_session.id,
      'organization_id', existing_session.organization_id,
      'client_id', existing_session.client_id,
      'match_status', existing_session.match_status,
      'message_id', existing_message_id
    );
  end if;

  -- Layered flood control (WC0.3): one visitor, one widget, one organization.
  if visitor_ip_hash is not null then
    select * into rate_check
    from public.check_rate_limit('website_chat:first:ip:' || visitor_ip_hash, 3600, 5);
    if not rate_check.allowed then
      return jsonb_build_object('status', 'rate_limited');
    end if;
  end if;
  select * into rate_check
  from public.check_rate_limit('website_chat:first:widget:' || widget.id::text, 3600, 120);
  if not rate_check.allowed then
    return jsonb_build_object('status', 'rate_limited');
  end if;
  select * into rate_check
  from public.check_rate_limit('website_chat:first:org:' || widget.organization_id::text, 3600, 400);
  if not rate_check.allowed then
    return jsonb_build_object('status', 'rate_limited');
  end if;

  select * into limit_row
  from private.effective_website_chat_conversation_limit(widget.organization_id, now());
  if limit_row.state not in ('numeric', 'unlimited')
    or (limit_row.state = 'numeric' and limit_row.value is null) then
    return jsonb_build_object('status', 'unavailable', 'reason', 'not_entitled');
  end if;

  select p.id, p.starts_at, p.ends_at into active_period
  from public.website_chat_allowance_periods p
  where p.organization_id = widget.organization_id
    and p.starts_at <= now()
    and p.ends_at > now()
  order by p.starts_at desc
  limit 1;
  if not found then
    return jsonb_build_object('status', 'unavailable', 'reason', 'allowance_period_unavailable');
  end if;

  -- One row, locked for update: the serialization point for every concurrent visitor of this
  -- organization. Nothing below it can oversubscribe the period.
  -- The DO UPDATE branch is what makes this race-free: it locks the existing row for us, where a
  -- DO NOTHING followed by a SELECT ... FOR UPDATE would find nothing while a concurrent inserter
  -- was still uncommitted.
  insert into public.website_chat_capacity_buckets (organization_id, allowance_period_id)
  values (widget.organization_id, active_period.id)
  on conflict (organization_id, allowance_period_id) do update
    set accepted_count = public.website_chat_capacity_buckets.accepted_count
  returning * into bucket;

  if limit_row.state = 'numeric' and bucket.accepted_count >= limit_row.value then
    return jsonb_build_object('status', 'cap_reached');
  end if;

  -- Identity, organization-scoped and normalized exactly like client_contact_methods stores it.
  match_phone := nullif(regexp_replace(coalesce(clean_phone, ''), '[^0-9]', '', 'g'), '');
  match_email := clean_email;

  if match_phone is not null then
    select count(distinct method.client_id), min(method.client_id::text)::uuid
    into phone_match_count, phone_candidate
    from public.client_contact_methods method
    join public.clients client
      on client.organization_id = method.organization_id and client.id = method.client_id
    where method.organization_id = widget.organization_id
      and method.kind = 'phone'
      and method.normalized_value = match_phone
      and client.deleted_at is null;
    if phone_match_count <> 1 then
      phone_candidate := null;
    end if;
  end if;

  if match_email is not null then
    select count(distinct method.client_id), min(method.client_id::text)::uuid
    into email_match_count, email_candidate
    from public.client_contact_methods method
    join public.clients client
      on client.organization_id = method.organization_id and client.id = method.client_id
    where method.organization_id = widget.organization_id
      and method.kind = 'email'
      and method.normalized_value = match_email
      and client.deleted_at is null;
    if email_match_count <> 1 then
      email_candidate := null;
    end if;
  end if;

  if phone_match_count > 1 or email_match_count > 1
    or (phone_candidate is not null and email_candidate is not null
        and phone_candidate <> email_candidate) then
    -- Two identifiers pointing at different Clients, or one identifier pointing at several. UCRM
    -- never guesses and never merges: messaging stays usable behind a guarded identity.
    resolved_match_status := 'needs_review';
    resolved_client_id := null;
  elsif coalesce(phone_candidate, email_candidate) is not null then
    resolved_match_status := 'resolved';
    resolved_client_id := coalesce(phone_candidate, email_candidate);
  else
    -- Nobody matched: a new Lead. Public input creates a Client but never edits an existing one.
    resolved_match_status := 'resolved';
    insert into public.clients (
      organization_id, display_name, first_name, last_name, lifecycle_status, lead_source,
      client_type
    ) values (
      widget.organization_id, clean_name, given_name, family_name, 'lead',
      coalesce(widget.source_label, 'Website Chat'), 'person'
    ) returning id into new_client_id;
    resolved_client_id := new_client_id;

    if clean_phone is not null then
      insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
      values (widget.organization_id, new_client_id, 'phone', clean_phone, true);
    end if;
    if clean_email is not null then
      insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
      values (widget.organization_id, new_client_id, 'email', clean_email, true);
    end if;
  end if;

  insert into public.website_chat_sessions (
    organization_id, widget_id, client_id, match_status,
    candidate_client_id_by_phone, candidate_client_id_by_email,
    visitor_name, submitted_phone_e164, submitted_email,
    normalized_phone, normalized_email, session_token_hash, idempotency_key,
    attribution, consent_transactional_sms, sms_consent_disclosure, ip_hash
  ) values (
    widget.organization_id, widget.id, resolved_client_id, resolved_match_status,
    case when resolved_match_status = 'needs_review' then phone_candidate end,
    case when resolved_match_status = 'needs_review' then email_candidate end,
    clean_name, clean_phone, clean_email,
    match_phone, match_email, btrim(new_session_token_hash), clean_idempotency_key,
    case when jsonb_typeof(coalesce(new_attribution, '{}'::jsonb)) = 'object'
      then coalesce(new_attribution, '{}'::jsonb) else '{}'::jsonb end,
    clean_consent_disclosure is not null, clean_consent_disclosure,
    nullif(btrim(coalesce(visitor_ip_hash, '')), '')
  ) returning * into new_session;

  insert into public.website_chat_capacity_reservations (
    organization_id, allowance_period_id, session_id
  ) values (widget.organization_id, active_period.id, new_session.id);

  update public.website_chat_capacity_buckets
  set accepted_count = accepted_count + 1
  where organization_id = widget.organization_id
    and allowance_period_id = active_period.id;

  insert into public.website_chat_messages (
    organization_id, session_id, client_id, direction, sender_type, body, idempotency_key
  ) values (
    widget.organization_id, new_session.id, resolved_client_id, 'inbound', 'visitor',
    clean_body, clean_idempotency_key
  ) returning id into new_message_id;

  return jsonb_build_object(
    'status', 'accepted',
    'replayed', false,
    'session_id', new_session.id,
    'organization_id', new_session.organization_id,
    'client_id', new_session.client_id,
    'match_status', new_session.match_status,
    'message_id', new_message_id
  );
end;
$$;


ALTER FUNCTION "public"."accept_website_chat_first_message"("widget_public_token" "uuid", "requesting_origin" "text", "new_session_token_hash" "text", "new_idempotency_key" "text", "visitor_name" "text", "visitor_phone_e164" "text", "visitor_email" "text", "message_body" "text", "consent_transactional_sms" boolean, "visitor_ip_hash" "text", "new_attribution" "jsonb", "sms_consent_disclosure" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_website_chat_first_message"("widget_public_token" "uuid", "requesting_origin" "text", "new_session_token_hash" "text", "new_idempotency_key" "text", "visitor_name" "text", "visitor_phone_e164" "text", "visitor_email" "text", "message_body" "text", "consent_transactional_sms" boolean, "visitor_ip_hash" "text", "new_attribution" "jsonb", "sms_consent_disclosure" "text") IS 'The one place a Website Chat allowance unit is claimed. Validates origin and token, applies flood limits, claims one unit under a bucket lock, resolves or creates the Client, and writes the session and its first message in a single transaction.';



CREATE OR REPLACE FUNCTION "public"."acknowledge_onboarding_application_duplicate"("target_application_id" "uuid", "actor_email" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  app_stage text;
  app_possible_duplicate boolean;
  app_already_acknowledged boolean;
begin
  select stage, possible_duplicate, duplicate_acknowledged_at is not null
  into app_stage, app_possible_duplicate, app_already_acknowledged
  from public.platform_onboarding_applications
  where id = target_application_id
  for update;

  if not found then
    raise exception 'The onboarding application does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if not app_possible_duplicate then
    raise exception 'This application was not flagged as a possible duplicate.' using errcode = 'check_violation';
  end if;
  if app_already_acknowledged then
    raise exception 'This possible duplicate was already acknowledged.' using errcode = 'check_violation';
  end if;
  if app_stage not in ('new', 'awaiting_payment', 'needs_attention') then
    raise exception 'Only an unpaid application can have its duplicate flag acknowledged.'
      using errcode = 'check_violation';
  end if;

  update public.platform_onboarding_applications
  set duplicate_acknowledged_at = now(), duplicate_acknowledged_by_owner_email = actor_email
  where id = target_application_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key
  ) values (
    actor_email, 'onboarding_application.duplicate_acknowledged', 'onboarding_application',
    target_application_id::text
  );
end;
$$;


ALTER FUNCTION "public"."acknowledge_onboarding_application_duplicate"("target_application_id" "uuid", "actor_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_communication_worker_lease"("p_worker_name" "text", "p_ttl_seconds" integer) RETURNS "uuid"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  insert into private.communication_worker_leases as lease (worker_name, lease_token, acquired_at, expires_at)
  values (p_worker_name, gen_random_uuid(), now(), now() + make_interval(secs => greatest(p_ttl_seconds, 1)))
  on conflict (worker_name) do update
    set lease_token = excluded.lease_token,
      acquired_at = excluded.acquired_at,
      expires_at = excluded.expires_at
    where lease.expires_at <= now()
  returning lease_token;
$$;


ALTER FUNCTION "public"."acquire_communication_worker_lease"("p_worker_name" "text", "p_ttl_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acquire_communication_worker_lease"("p_worker_name" "text", "p_ttl_seconds" integer) IS 'Returns a new lease token if the named worker is free (or its prior lease expired), or NULL if a live lease is held. Callers that get NULL must not run and should report already_running.';



CREATE OR REPLACE FUNCTION "public"."activate_automation_recipe_version"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_schema_version" integer, "p_definition" "jsonb", "p_definition_hash" "text", "p_trigger_key" "text", "p_active_limit" integer, "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  existing_receipt public.automation_draft_command_receipts%rowtype;
  recipe public.automation_recipes%rowtype;
  active_count integer;
  next_version_number integer;
  new_version_id uuid;
  next_revision integer;
  command_result jsonb;
  cutoff_sequence bigint;
begin
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;
  if p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'An expected revision is required.' using errcode = 'check_violation';
  end if;
  if p_definition is null or jsonb_typeof(p_definition) <> 'object' then
    raise exception 'A recipe definition is required.' using errcode = 'check_violation';
  end if;
  if p_trigger_key is null or char_length(btrim(p_trigger_key)) = 0 then
    raise exception 'A trigger is required to activate.' using errcode = 'check_violation';
  end if;
  if p_definition_hash is null or char_length(btrim(p_definition_hash)) = 0 then
    raise exception 'A definition hash is required.' using errcode = 'check_violation';
  end if;

  perform pg_advisory_xact_lock(hashtext('automation-recipe:' || p_recipe_id::text));

  select * into existing_receipt
  from public.automation_draft_command_receipts
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_receipt.result || jsonb_build_object('idempotent_replay', true);
  end if;

  select * into recipe
  from public.automation_recipes
  where id = p_recipe_id and organization_id = p_organization_id
  for update;
  if not found then
    raise exception 'That automation does not exist.' using errcode = 'no_data_found';
  end if;
  if recipe.status = 'archived' then
    raise exception 'An archived automation is read-only.' using errcode = 'restrict_violation';
  end if;
  if recipe.status not in ('draft', 'active', 'paused') then
    raise exception 'This automation cannot be activated right now.' using errcode = 'restrict_violation';
  end if;

  if recipe.draft_revision <> p_expected_revision then
    return jsonb_build_object(
      'stale', true,
      'current_revision', recipe.draft_revision,
      'draft_updated_at', recipe.draft_updated_at,
      'draft_updated_by', recipe.draft_updated_by
    );
  end if;
  if recipe.draft_definition is null then
    raise exception 'This automation has no draft to activate.' using errcode = 'check_violation';
  end if;

  if p_active_limit is not null and recipe.status <> 'active' then
    select count(*) into active_count
    from public.automation_recipes
    where organization_id = p_organization_id and status = 'active';
    if active_count >= p_active_limit then
      raise exception
        'Activating this automation would pass your plan limit of % active automations. Pause or archive another one first.',
        p_active_limit
        using errcode = 'restrict_violation';
    end if;
  end if;

  select coalesce(max(version_number), 0) + 1 into next_version_number
  from public.automation_recipe_versions
  where recipe_id = p_recipe_id;

  select coalesce(max(seq), 0) into cutoff_sequence from private.automation_events;

  insert into public.automation_recipe_versions (
    recipe_id, organization_id, version_number, schema_version,
    definition, definition_hash, trigger_key, activation_cutoff_sequence,
    activation_cutoff_snapshot, activated_by
  ) values (
    p_recipe_id, p_organization_id, next_version_number, p_schema_version,
    p_definition, p_definition_hash, p_trigger_key, cutoff_sequence,
    pg_current_snapshot(), p_actor_user_id
  ) returning id into new_version_id;

  next_revision := recipe.draft_revision + 1;

  update public.automation_recipes
  set status = 'active',
      current_version_id = new_version_id,
      active_trigger_key = p_trigger_key,
      draft_definition = p_definition,
      draft_revision = next_revision
  where id = p_recipe_id and organization_id = p_organization_id;

  command_result := jsonb_build_object(
    'recipe_id', p_recipe_id,
    'status', 'active',
    'version_id', new_version_id,
    'version_number', next_version_number,
    'draft_revision', next_revision,
    'stale', false
  );

  insert into public.automation_draft_command_receipts (
    organization_id, idempotency_key, command, recipe_id, result
  ) values (
    p_organization_id, p_idempotency_key, 'activate', p_recipe_id, command_result
  );

  return command_result;
end;
$$;


ALTER FUNCTION "public"."activate_automation_recipe_version"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_schema_version" integer, "p_definition" "jsonb", "p_definition_hash" "text", "p_trigger_key" "text", "p_active_limit" integer, "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."activate_automation_recipe_version"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_schema_version" integer, "p_definition" "jsonb", "p_definition_hash" "text", "p_trigger_key" "text", "p_active_limit" integer, "p_idempotency_key" "uuid") IS 'Freezes an immutable recipe version from the reviewed draft and marks the recipe active. Idempotent per organization + key; enforces the active-recipes limit on a new activation and the caller-supplied revision.';



CREATE OR REPLACE FUNCTION "public"."activate_invoice_replacement"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "previewed_difference_minor" bigint, "new_issue_method" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  settings_row public.organization_settings;
  successor public.invoices;
  predecessor public.invoices;
  frozen_label text;
  actual_difference_minor bigint;
  issued public.invoices;
begin
  if caller is null then
    raise exception 'You must be signed in to activate a replacement.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.send') then
    raise exception 'You do not have access to issue an invoice.' using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  if new_issue_method not in ('sent', 'marked_sent') then
    raise exception 'An invoice is issued by sending it or by marking it sent.'
      using errcode = 'check_violation';
  end if;
  if previewed_difference_minor is null then
    raise exception 'Confirm the difference this replacement makes before applying it.'
      using errcode = 'check_violation';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'activate_invoice_replacement', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  -- Settings before invoices, matching every other currency-sensitive command.
  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for share;
  if not found then
    raise exception 'That organization could not be found.' using errcode = 'P0404';
  end if;

  select * into successor
  from public.invoices
  where organization_id = target_organization_id and id = target_invoice_id;
  if not found then
    raise exception 'That invoice could not be found.' using errcode = 'P0404';
  end if;
  if successor.predecessor_invoice_id is null then
    raise exception 'This invoice does not replace anything.' using errcode = 'check_violation';
  end if;

  -- Both rows locked in id order in one statement. Two people activating replacements in the same chain
  -- queue behind each other instead of deadlocking.
  perform 1
  from public.invoices
  where organization_id = target_organization_id
    and id in (successor.id, successor.predecessor_invoice_id)
  order by id
  for update;

  select * into successor
  from public.invoices
  where organization_id = target_organization_id and id = target_invoice_id;
  select * into predecessor
  from public.invoices
  where organization_id = target_organization_id and id = successor.predecessor_invoice_id;

  if successor.revision is distinct from expected_revision then
    raise exception 'Someone else changed this invoice. Reload to see the latest.' using errcode = 'P0409';
  end if;
  if successor.issued_at is not null or successor.recognized_at is not null then
    raise exception 'This replacement has already been activated.' using errcode = 'check_violation';
  end if;
  if successor.currency_code is distinct from settings_row.currency_code then
    raise exception 'This draft was written in a different currency. Refresh it before issuing it.'
      using errcode = 'check_violation';
  end if;
  if not exists (
    select 1 from public.invoice_lines
    where organization_id = target_organization_id and invoice_id = successor.id
  ) then
    raise exception 'An invoice needs at least one line before it can be issued.'
      using errcode = 'check_violation';
  end if;
  if predecessor.replaced_at is not null then
    raise exception 'That invoice has already been replaced.' using errcode = 'check_violation';
  end if;

  -- The stale-preview refusal. The user approved a specific change in what the customer owes; if the numbers
  -- moved underneath them, they approved something else.
  actual_difference_minor := successor.total_minor - predecessor.total_minor;
  if actual_difference_minor is distinct from previewed_difference_minor then
    raise exception 'These amounts changed since you reviewed them. Check the difference and try again.'
      using errcode = 'P0409',
      detail = format('reviewed %s, now %s', previewed_difference_minor, actual_difference_minor);
  end if;

  -- Read the label before anything is written, because the label is a statement about the bill as it stood
  -- one instant ago.
  frozen_label := private.invoice_status_label(predecessor);

  update public.invoices
  set issued_at = now(),
      issued_by = caller,
      issue_method = new_issue_method,
      document_frozen_at = now(),
      revision = successor.revision + 1
  where organization_id = target_organization_id and id = successor.id
  returning * into issued;

  update public.invoices
  set replaced_at = now(),
      replaced_by_invoice_id = successor.id,
      frozen_status_label = frozen_label,
      -- A voided predecessor is frozen against every other change by the identity guard, including its
      -- revision. Being marked as replaced is the one fact it may still accept.
      revision = case when predecessor.voided_at is null then predecessor.revision + 1
                      else predecessor.revision end,
      updated_at = now()
  where organization_id = target_organization_id and id = predecessor.id;

  perform private.record_invoice_event(
    target_organization_id, predecessor.id, predecessor.invoice_number, predecessor.client_id,
    'invoice.replaced', caller, null, null,
    jsonb_build_object(
      'replaced_by_invoice_id', successor.id,
      'replaced_by_invoice_number', successor.invoice_number,
      'replacement_kind', successor.replacement_kind,
      'frozen_status_label', frozen_label
    ),
    false, null
  );
  perform private.record_invoice_event(
    target_organization_id, issued.id, issued.invoice_number, issued.client_id,
    'invoice.replacement_activated', caller, issued.revision, null,
    jsonb_build_object(
      'predecessor_invoice_id', predecessor.id,
      'predecessor_invoice_number', predecessor.invoice_number,
      'replacement_kind', issued.replacement_kind,
      'difference_minor', actual_difference_minor,
      'method', new_issue_method
    ),
    true, null
  );

  return private.complete_invoice_command(
    target_organization_id, 'activate_invoice_replacement', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', issued.id,
      'invoice_number', issued.invoice_number,
      'revision', issued.revision,
      'issued_at', issued.issued_at,
      'issue_method', issued.issue_method,
      'replacement_kind', issued.replacement_kind,
      'predecessor_invoice_id', predecessor.id,
      'predecessor_invoice_number', predecessor.invoice_number,
      'predecessor_frozen_status_label', frozen_label,
      'difference_minor', actual_difference_minor
    )
  );
end;
$$;


ALTER FUNCTION "public"."activate_invoice_replacement"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "previewed_difference_minor" bigint, "new_issue_method" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."activate_invoice_replacement"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "previewed_difference_minor" bigint, "new_issue_method" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Issues a replacement and retires the invoice it replaces in one transaction, freezing that invoice''s status label so history never ages. Refuses when the difference the user reviewed no longer matches, and moves no money.';



CREATE OR REPLACE FUNCTION "public"."add_job_expense"("target_organization_id" "uuid", "target_job_id" "uuid", "name" "text", "expense_date" "date", "total_minor" bigint, "accounting_code" "text" DEFAULT NULL::"text", "description" "text" DEFAULT NULL::"text", "reimburse_to_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  job_closed boolean;
  new_expense public.job_expenses;
begin
  if caller is null then
    raise exception 'You must be signed in to record an expense.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  job_closed := current_job.status <> 'active';

  if not private.can_write_job_expense(target_organization_id, caller, caller, job_closed) then
    if job_closed then
      raise exception 'A closed job''s expenses can only be changed by someone who manages the team''s expenses.'
        using errcode = 'P0410';
    end if;
    raise exception 'You do not have access to record this expense.' using errcode = 'insufficient_privilege';
  end if;

  if reimburse_to_user_id is not null and not exists (
    select 1
    from public.organization_members as member
    where member.organization_id = target_organization_id
      and member.user_id = reimburse_to_user_id
      and member.status <> 'removed'
  ) then
    raise exception 'That person is not on this team.' using errcode = 'P0404';
  end if;

  insert into public.job_expenses (
    organization_id, job_id, name, accounting_code, description, expense_date, total_minor,
    reimburse_to_user_id, created_by
  )
  values (
    target_organization_id, target_job_id,
    trim(add_job_expense.name),
    nullif(trim(coalesce(add_job_expense.accounting_code, '')), ''),
    nullif(trim(coalesce(add_job_expense.description, '')), ''),
    add_job_expense.expense_date, add_job_expense.total_minor,
    add_job_expense.reimburse_to_user_id, caller
  )
  returning * into new_expense;

  insert into public.job_costing_events (
    organization_id, job_id, event_type, subject_kind, subject_id, actor_id, after_close, new_values
  )
  values (
    target_organization_id, target_job_id, 'expense_added', 'expense', new_expense.id, caller, job_closed,
    jsonb_build_object(
      'name', new_expense.name,
      'accounting_code', new_expense.accounting_code,
      'expense_date', new_expense.expense_date,
      'total_minor', new_expense.total_minor,
      'reimburse_to_user_id', new_expense.reimburse_to_user_id
    )
  );

  return jsonb_build_object('id', new_expense.id, 'after_close', job_closed);
end;
$$;


ALTER FUNCTION "public"."add_job_expense"("target_organization_id" "uuid", "target_job_id" "uuid", "name" "text", "expense_date" "date", "total_minor" bigint, "accounting_code" "text", "description" "text", "reimburse_to_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_job_expense"("target_organization_id" "uuid", "target_job_id" "uuid", "name" "text", "expense_date" "date", "total_minor" bigint, "accounting_code" "text", "description" "text", "reimburse_to_user_id" "uuid") IS 'Records an expense on a job -- materials, dump fees, a subcontractor. Needs expenses.manage_team, or expenses.record on an open job for the person''s own. Every expense is written to job_costing_events, flagged when the job is already closed. The receipt attaches separately as an attachment.';



CREATE OR REPLACE FUNCTION "public"."add_job_invoice_reminder"("target_organization_id" "uuid", "target_job_id" "uuid", "new_due_on" "date", "new_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  job_row public.jobs;
  reminder_id uuid;
begin
  if caller is null then
    raise exception 'You must be signed in to add an invoice reminder.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.edit') then
    raise exception 'You do not have access to edit this job.' using errcode = 'insufficient_privilege';
  end if;
  if new_due_on is null then
    raise exception 'Choose a date for this reminder.' using errcode = 'check_violation';
  end if;

  select * into job_row
  from public.jobs
  where organization_id = target_organization_id and id = target_job_id;

  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  reminder_id := private.create_invoice_reminder(
    target_organization_id, target_job_id, 'custom_date', new_due_on, caller, null, new_note
  );

  return jsonb_build_object('id', reminder_id);
end;
$$;


ALTER FUNCTION "public"."add_job_invoice_reminder"("target_organization_id" "uuid", "target_job_id" "uuid", "new_due_on" "date", "new_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_job_invoice_reminder"("target_organization_id" "uuid", "target_job_id" "uuid", "new_due_on" "date", "new_note" "text") IS 'Adds a custom-date invoice reminder to a job. Needs jobs.edit. Re-adding the same open date is a no-op that returns the existing reminder.';



CREATE OR REPLACE FUNCTION "public"."add_job_time_entry"("target_organization_id" "uuid", "target_job_id" "uuid", "target_user_id" "uuid", "started_at" timestamp with time zone, "minutes" integer, "target_visit_id" "uuid" DEFAULT NULL::"uuid", "notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  job_closed boolean;
  recorded_rate bigint;
  new_entry public.job_time_entries;
begin
  if caller is null then
    raise exception 'You must be signed in to record hours.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  -- No row lock. Hours are appended to a job, never derived from it, so two people recording time at once
  -- have nothing to fight over -- and locking the job here would make every timesheet entry queue behind
  -- whatever else is editing the job.
  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  job_closed := current_job.status <> 'active';

  if not private.can_write_job_time(target_organization_id, caller, target_user_id, job_closed) then
    if job_closed then
      raise exception 'A closed job''s hours can only be changed by someone who manages the team''s time.'
        using errcode = 'P0410';
    end if;
    raise exception 'You do not have access to record these hours.' using errcode = 'insufficient_privilege';
  end if;

  -- Hours belong to someone who works here. The foreign key would refuse a stranger anyway; this refuses a
  -- person who has left with a sentence instead of a constraint name.
  if not exists (
    select 1
    from public.organization_members as member
    where member.organization_id = target_organization_id
      and member.user_id = target_user_id
      and member.status <> 'removed'
  ) then
    raise exception 'That person is not on this team.' using errcode = 'P0404';
  end if;

  if target_visit_id is not null and not exists (
    select 1
    from public.job_visits as visit
    where visit.organization_id = target_organization_id
      and visit.job_id = target_job_id
      and visit.id = target_visit_id
  ) then
    raise exception 'That visit could not be found on this job.' using errcode = 'P0404';
  end if;

  -- The one and only read of the rate profile in this file. Null is kept as null: nobody has said what this
  -- person costs, and unrated hours are reported as unrated rather than valued at nothing.
  select profile.cost_per_hour_minor into recorded_rate
  from public.organization_member_cost_profiles as profile
  where profile.organization_id = target_organization_id
    and profile.user_id = target_user_id;

  insert into public.job_time_entries (
    organization_id, job_id, visit_id, user_id, started_at, minutes, notes, cost_per_hour_minor, created_by
  )
  values (
    target_organization_id, target_job_id, target_visit_id, target_user_id,
    add_job_time_entry.started_at, add_job_time_entry.minutes,
    nullif(trim(coalesce(add_job_time_entry.notes, '')), ''), recorded_rate, caller
  )
  returning * into new_entry;

  insert into public.job_costing_events (
    organization_id, job_id, event_type, subject_kind, subject_id, actor_id, after_close, new_values
  )
  values (
    target_organization_id, target_job_id, 'time_entry_added', 'time_entry', new_entry.id, caller, job_closed,
    jsonb_build_object(
      'user_id', new_entry.user_id,
      'visit_id', new_entry.visit_id,
      'started_at', new_entry.started_at,
      'minutes', new_entry.minutes,
      'cost_per_hour_minor', new_entry.cost_per_hour_minor,
      'cost_total_minor', new_entry.cost_total_minor
    )
  );

  return jsonb_build_object('id', new_entry.id, 'after_close', job_closed);
end;
$$;


ALTER FUNCTION "public"."add_job_time_entry"("target_organization_id" "uuid", "target_job_id" "uuid", "target_user_id" "uuid", "started_at" timestamp with time zone, "minutes" integer, "target_visit_id" "uuid", "notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_job_time_entry"("target_organization_id" "uuid", "target_job_id" "uuid", "target_user_id" "uuid", "started_at" timestamp with time zone, "minutes" integer, "target_visit_id" "uuid", "notes" "text") IS 'Records hours on a job, copying the person''s current cost rate onto the entry so a later rate change cannot re-cost finished work. Needs time.track_team for anyone else''s hours, time.track_own for their own on an open job. Every entry is written to job_costing_events, flagged when the job is already closed.';



CREATE OR REPLACE FUNCTION "public"."add_job_visits"("target_organization_id" "uuid", "target_job_id" "uuid", "visits" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  receipt_id uuid;
  existing_receipt public.job_command_receipts;
  visit_count integer;
  next_position integer;
  visit_element jsonb;
  new_visit public.job_visits;
  assignee_element jsonb;
  copy_source_id uuid;
  added_ids uuid[] := array[]::uuid[];
  final_result jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to schedule a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.schedule') then
    raise exception 'You do not have access to schedule this job.' using errcode = 'insufficient_privilege';
  end if;

  visit_count := coalesce(jsonb_array_length(visits), 0);
  if visit_count < 1 or visit_count > 20 then
    raise exception 'Between 1 and 20 visits can be added at once.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(new_idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(new_request_hash, ''))) < 1 then
    raise exception 'A request fingerprint is required.' using errcode = 'check_violation';
  end if;

  -- The job must exist in this organization and still be open. A closed job is not scheduled against; it is
  -- reopened first, which is an explicit later action. Not found and forbidden read the same to a stranger.
  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id
    and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  if current_job.status = 'closed' then
    raise exception 'A closed job cannot be scheduled. Reopen it first.' using errcode = 'P0410';
  end if;

  -- Claim the key before any work. on conflict do nothing waits for a racing transaction to commit and then
  -- returns no row, so the loser reads the winner's committed result instead of adding a second batch.
  insert into public.job_command_receipts (organization_id, action, idempotency_key, request_hash)
  values (target_organization_id, 'add_job_visits', new_idempotency_key, new_request_hash)
  on conflict (organization_id, action, idempotency_key) do nothing
  returning id into receipt_id;

  if receipt_id is null then
    select receipt.* into existing_receipt
    from public.job_command_receipts as receipt
    where receipt.organization_id = target_organization_id
      and receipt.action = 'add_job_visits'
      and receipt.idempotency_key = new_idempotency_key;

    if existing_receipt.request_hash is distinct from new_request_hash then
      raise exception 'Those visits were already added with different details.' using errcode = 'P0409';
    end if;

    return coalesce(existing_receipt.result, '{}'::jsonb) || jsonb_build_object('applied', false);
  end if;

  -- New visits append after the job's current visits. position orders the job's own list, not the calendar.
  select coalesce(max(visit.position), -1) + 1 into next_position
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id;

  for visit_element in select value from jsonb_array_elements(visits) as v(value)
  loop
    insert into public.job_visits (
      organization_id, job_id, position, visit_date, start_time, end_time, all_day, title, instructions,
      source
    ) values (
      target_organization_id,
      target_job_id,
      next_position,
      nullif(visit_element->>'visit_date', '')::date,
      nullif(visit_element->>'start_time', '')::time,
      nullif(visit_element->>'end_time', '')::time,
      coalesce((visit_element->>'all_day')::boolean, false),
      nullif(trim(visit_element->>'title'), ''),
      nullif(trim(visit_element->>'instructions'), ''),
      coalesce(nullif(visit_element->>'source', ''), 'manual')
    )
    returning * into new_visit;

    next_position := next_position + 1;
    added_ids := array_append(added_ids, new_visit.id);

    if jsonb_typeof(visit_element->'assignee_ids') = 'array' then
      for assignee_element in select value from jsonb_array_elements(visit_element->'assignee_ids') as a(value)
      loop
        insert into public.job_visit_assignments (organization_id, visit_id, user_id)
        values (target_organization_id, new_visit.id, (assignee_element #>> '{}')::uuid)
        on conflict do nothing;
      end loop;
    end if;

    -- A faithful copy of the source visit's own lines, or nothing at all. A source that carries no lines of
    -- its own copies nothing, which is exactly right: the copy then bills the job's lines, as it did.
    copy_source_id := nullif(visit_element->>'copy_lines_from_visit_id', '')::uuid;
    if copy_source_id is not null then
      -- The source must be another visit of this same job in this same organization. Anything else is a
      -- mistake or a probe, and raising rolls the whole add back rather than quietly mispricing the copy.
      if not exists (
        select 1
        from public.job_visits as source
        where source.organization_id = target_organization_id
          and source.job_id = target_job_id
          and source.id = copy_source_id
      ) then
        raise exception 'The visit being copied could not be found.' using errcode = 'P0404';
      end if;

      -- source_job_line_item_id rides along: its uniqueness is scoped to one visit, so the copy's rows
      -- cannot collide with the original's, and the copy keeps the same once-per-visit override provenance.
      insert into public.job_visit_line_items (
        organization_id, job_id, visit_id, position, source_job_line_item_id, source_catalog_item_id,
        line_kind, category, is_labor, name, description, unit_label, quantity, unit_price_minor,
        unit_cost_minor, is_taxable, image_attachment_id
      )
      select
        target_organization_id, target_job_id, new_visit.id, item.position, item.source_job_line_item_id,
        item.source_catalog_item_id, item.line_kind, item.category, item.is_labor, item.name,
        item.description, item.unit_label, item.quantity, item.unit_price_minor,
        item.unit_cost_minor, item.is_taxable, item.image_attachment_id
      from public.job_visit_line_items as item
      where item.organization_id = target_organization_id
        and item.visit_id = copy_source_id
      order by item.position;
    end if;
  end loop;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'visits_added',
    caller,
    jsonb_build_object('count', visit_count)
  );

  final_result := jsonb_build_object('applied', true, 'added_count', visit_count, 'visit_ids', to_jsonb(added_ids));
  update public.job_command_receipts set result = final_result where id = receipt_id;
  return final_result;
end;
$$;


ALTER FUNCTION "public"."add_job_visits"("target_organization_id" "uuid", "target_job_id" "uuid", "visits" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_job_visits"("target_organization_id" "uuid", "target_job_id" "uuid", "visits" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Appends 1-20 visits to an existing open job. Checks jobs.schedule, idempotent by key, appends a visits_added history row. A visit element may carry copy_lines_from_visit_id to reproduce that visit''s own lines exactly. Visit shape is guarded by the job_visits table constraints.';



CREATE OR REPLACE FUNCTION "public"."add_website_chat_widget_origin"("target_organization_id" "uuid", "target_widget_id" "uuid", "new_origin" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  clean_origin text;
  widget_exists boolean;
  existing_count integer;
  new_row public.website_chat_widget_origins;
begin
  if not private.has_permission(target_organization_id, 'conversations.manage_connections') then
    raise exception 'You do not have access to manage Website Chat.' using errcode = 'insufficient_privilege';
  end if;

  select exists(
    select 1 from public.website_chat_widgets
    where organization_id = target_organization_id and id = target_widget_id
  ) into widget_exists;
  if not widget_exists then
    raise exception 'That widget was not found.' using errcode = 'check_violation';
  end if;

  clean_origin := lower(btrim(coalesce(new_origin, '')));
  if clean_origin !~
    '^https?://[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+(:[0-9]{1,5})?$'
  then
    raise exception 'Enter a valid origin like https://example.com.' using errcode = 'check_violation';
  end if;

  select count(*) into existing_count
  from public.website_chat_widget_origins
  where widget_id = target_widget_id;
  if existing_count >= 20 then
    raise exception 'A widget can have at most 20 allowed domains.' using errcode = 'check_violation';
  end if;

  insert into public.website_chat_widget_origins (organization_id, widget_id, origin, created_by)
  values (target_organization_id, target_widget_id, clean_origin, (select auth.uid()))
  on conflict (widget_id, origin) do nothing
  returning * into new_row;

  if new_row.id is null then
    raise exception 'That domain is already allowed for this widget.' using errcode = 'unique_violation';
  end if;

  return to_jsonb(new_row);
end;
$_$;


ALTER FUNCTION "public"."add_website_chat_widget_origin"("target_organization_id" "uuid", "target_widget_id" "uuid", "new_origin" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_website_chat_widget_origin"("target_organization_id" "uuid", "target_widget_id" "uuid", "new_origin" "text") IS 'Adds one allowed origin to a Website Chat widget.';



CREATE OR REPLACE FUNCTION "public"."advance_automation_work_item"("p_work_item_id" "uuid", "p_claim_token" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  item private.automation_work_items%rowtype;
  enrollment private.automation_enrollments%rowtype;
  recipe_status text;
  definition jsonb;
  step jsonb;
  step_type text;
  stop_outcome text;
  organization_timezone text;
  wait_amount integer;
  wait_unit text;
  waited_days integer;
  waited_hours integer;
  waited_minutes integer;
  next_due timestamptz;
  customer_reply_at timestamptz;   -- Stage 3
begin
  if p_work_item_id is null or p_claim_token is null then
    raise exception 'A work item and its claim are required.' using errcode = 'check_violation';
  end if;

  select * into item from private.automation_work_items
  where id = p_work_item_id and claim_token = p_claim_token and state = 'pending' for update;
  if not found then return 'claim_lost'; end if;

  select * into enrollment from private.automation_enrollments where id = item.enrollment_id for update;
  if not found or enrollment.state <> 'active' then
    update private.automation_work_items
    set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'enrollment_inactive';
  end if;

  if enrollment.expires_at is not null and enrollment.expires_at <= now() then
    update private.automation_enrollments
    set state = 'stopped', stop_reason = 'enrollment_expired', stopped_at = now() where id = enrollment.id;
    update private.automation_work_items
    set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'enrollment_expired';
  end if;

  select recipe.status, version.definition into recipe_status, definition
  from private.automation_enrollments as e
  join public.automation_recipes as recipe on recipe.id = e.recipe_id
  join public.automation_recipe_versions as version on version.id = e.recipe_version_id
  where e.id = enrollment.id;

  if recipe_status is distinct from 'active' then
    update private.automation_enrollments
    set state = 'stopped', stop_reason = 'recipe_not_active', stopped_at = now() where id = enrollment.id;
    update private.automation_work_items
    set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'recipe_not_active';
  end if;

  step := (definition -> 'steps') -> item.step_index;

  if step is null then
    update private.automation_enrollments
    set state = 'completed', completed_at = now(), current_step_index = item.step_index
    where id = enrollment.id;
    update private.automation_work_items
    set state = 'done', claim_token = null, claimed_at = null where id = item.id;
    return 'completed';
  end if;

  if enrollment.subject_type = 'quote' then
    stop_outcome := private.automation_quote_stop_outcome(enrollment.organization_id, enrollment.subject_id);
    if stop_outcome is not null then
      update private.automation_enrollments
      set state = 'stopped', stop_reason = stop_outcome, stopped_at = now() where id = enrollment.id;
      update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
      return 'stop_condition_met';
    end if;
  end if;

  -- Stage 3: a website inquiry stops on a delivered staff reply at every transition, and pauses before a
  -- customer-facing step when the customer replied to what this enrollment already sent them.
  if enrollment.subject_type in ('form_submission', 'website_chat_session') then
    stop_outcome := private.automation_inquiry_stop_outcome(
      enrollment.organization_id, enrollment.subject_type, enrollment.subject_id, enrollment.anchor_at
    );
    if stop_outcome is not null then
      update private.automation_enrollments
      set state = 'stopped', stop_reason = stop_outcome, stopped_at = now() where id = enrollment.id;
      update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
      return 'stop_condition_met';
    end if;

    if step ->> 'type' = 'action' and step ->> 'key' in ('action.send_email', 'action.send_sms', 'action.send_customer_message') then
      customer_reply_at := private.automation_inquiry_customer_reply_at(
        enrollment.organization_id, enrollment.subject_type, enrollment.subject_id,
        enrollment.customer_reply_after
      );
      if customer_reply_at is not null then
        -- The same shape as a staff Pause, so the existing Resume restores this step at its original time.
        update private.automation_enrollments
        set state = 'paused', paused_work_due_at = item.due_at, current_step_index = item.step_index,
          customer_reply_after = customer_reply_at
        where id = enrollment.id;
        update private.automation_work_items
        set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
        return 'paused_customer_reply';
      end if;
    end if;
  end if;

  step_type := step ->> 'type';

  if step_type = 'wait' then
    wait_unit := step -> 'config' ->> 'unit';
    wait_amount := nullif(step -> 'config' ->> 'amount', '')::integer;
    if wait_unit not in ('minutes', 'hours', 'days') or wait_amount is null or wait_amount < 1 then
      raise exception 'This automation step has an unusable delay.' using errcode = 'check_violation';
    end if;

    select
      coalesce(sum(case when entry.step -> 'config' ->> 'unit' = 'days'
        then nullif(entry.step -> 'config' ->> 'amount', '')::integer else 0 end), 0),
      coalesce(sum(case when entry.step -> 'config' ->> 'unit' = 'hours'
        then nullif(entry.step -> 'config' ->> 'amount', '')::integer else 0 end), 0),
      coalesce(sum(case when entry.step -> 'config' ->> 'unit' = 'minutes'
        then nullif(entry.step -> 'config' ->> 'amount', '')::integer else 0 end), 0)
    into waited_days, waited_hours, waited_minutes
    from jsonb_array_elements(coalesce(definition -> 'steps', '[]'::jsonb))
      with ordinality as entry(step, position)
    where entry.position - 1 <= item.step_index and entry.step ->> 'type' = 'wait';

    select coalesce(nullif(btrim(settings.timezone), ''), 'UTC') into organization_timezone
    from public.organization_settings as settings
    where settings.organization_id = enrollment.organization_id;
    organization_timezone := coalesce(organization_timezone, 'UTC');

    -- Days land at the same local time of day; hours and minutes are real elapsed time. Round-tripping the
    -- anchor through local time only when days are waited keeps a short wait on a fall-back night exact.
    next_due := case
        when waited_days > 0 then
          ((enrollment.anchor_at at time zone organization_timezone) + make_interval(days => waited_days))
            at time zone organization_timezone
        else enrollment.anchor_at
      end
      + make_interval(hours => waited_hours, mins => waited_minutes);

    update private.automation_enrollments
    set current_step_index = item.step_index + 1 where id = enrollment.id;

    update private.automation_work_items
    set state = 'done', claim_token = null, claimed_at = null where id = item.id;

    insert into private.automation_work_items (organization_id, enrollment_id, step_index, due_at, available_at)
    values (enrollment.organization_id, enrollment.id, item.step_index + 1, next_due, next_due)
    on conflict (enrollment_id, step_index) do nothing;

    return 'waiting';
  end if;

  if step_type = 'action' then
    -- 7: distinguish which action effect the worker must run instead of always assuming email. The row stays
    -- claimed under its lease meanwhile; a lease that expires before the effect settles returns the row to
    -- the queue and the idempotent send key prevents a double.
    if (step ->> 'key') = 'action.send_email' then
      return 'action_due_email';
    elsif (step ->> 'key') = 'action.send_sms' then
      return 'action_due_sms';
    -- Stage 5: a website inquiry's text-or-email message.
    elsif (step ->> 'key') = 'action.send_customer_message' then
      return 'action_due_customer_message';
    else
      update private.automation_work_items
      set state = 'needs_attention', attention_reason = 'action_not_available', attention_at = now(),
        claim_token = null, claimed_at = null
      where id = item.id;
      return 'action_not_available';
    end if;
  end if;

  raise exception 'This automation step has an unknown type.' using errcode = 'check_violation';
end;
$$;


ALTER FUNCTION "public"."advance_automation_work_item"("p_work_item_id" "uuid", "p_claim_token" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."advance_automation_work_item"("p_work_item_id" "uuid", "p_claim_token" "uuid") IS 'Runs one claimed transition: rechecks enrollment, expiry, recipe state, and the domain stop conditions, then completes, schedules the next step from the original send, or returns action_due_email / action_due_sms / action_due_customer_message for the worker to run and settle the matching effect. A website inquiry stops on a delivered staff reply and returns paused_customer_reply before a customer-facing step the customer has since replied to. Claim-token guarded. Service role only.';



CREATE OR REPLACE FUNCTION "public"."apply_client_payment"("target_organization_id" "uuid", "target_invoice_id" "uuid", "target_payment_event_id" "uuid", "target_deposit_event_id" "uuid", "new_amount_minor" bigint, "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  settings_row public.organization_settings;
  invoice_row public.invoices;
  receipt public.client_payment_events;
  deposit public.quote_deposit_events;
  source_client_id uuid;
  source_currency text;
  available bigint;
  allocation_id uuid;
begin
  if caller is null then
    raise exception 'You must be signed in to apply a payment.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.record_payment') then
    raise exception 'You do not have access to apply payments here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  if (target_payment_event_id is not null) = (target_deposit_event_id is not null) then
    raise exception 'Apply either a recorded payment or a quote deposit, not both.'
      using errcode = 'check_violation';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'apply_client_payment', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for share;
  if not found then
    raise exception 'That organization could not be found.' using errcode = 'P0404';
  end if;

  invoice_row := private.lock_invoice_for_payment(target_organization_id, target_invoice_id);

  if target_payment_event_id is not null then
    select * into receipt
    from public.client_payment_events
    where organization_id = target_organization_id and id = target_payment_event_id
    for update;
    if not found then
      raise exception 'That payment could not be found.' using errcode = 'P0404';
    end if;
    source_client_id := receipt.client_id;
    source_currency := receipt.currency_code;
    available := private.payment_event_available_minor(target_organization_id, receipt.id);
  else
    select * into deposit
    from public.quote_deposit_events
    where organization_id = target_organization_id and id = target_deposit_event_id
    for update;
    if not found then
      raise exception 'That deposit could not be found.' using errcode = 'P0404';
    end if;
    select quote.client_id into source_client_id
    from public.quotes as quote
    where quote.organization_id = target_organization_id and quote.id = deposit.quote_id;
    source_currency := settings_row.currency_code;
    available := private.deposit_event_available_minor(target_organization_id, deposit.id);
  end if;

  if source_client_id is distinct from invoice_row.client_id then
    raise exception 'That money belongs to a different client.' using errcode = 'check_violation';
  end if;
  if source_currency is distinct from invoice_row.currency_code then
    raise exception 'That money was received in a different currency.' using errcode = 'check_violation';
  end if;
  if new_amount_minor is null or new_amount_minor <= 0 then
    raise exception 'A payment amount must be more than zero.' using errcode = 'check_violation';
  end if;
  if new_amount_minor > available then
    raise exception 'That money is already spent or refunded.' using errcode = 'check_violation',
      detail = format('%s available, %s offered', available, new_amount_minor);
  end if;

  allocation_id := private.apply_invoice_allocation(
    invoice_row, target_payment_event_id, target_deposit_event_id, new_amount_minor, caller, new_reason
  );

  return private.complete_invoice_command(
    target_organization_id, 'apply_client_payment', new_idempotency_key,
    jsonb_build_object(
      'allocation_id', allocation_id,
      'invoice_id', invoice_row.id,
      'invoice_number', invoice_row.invoice_number,
      'amount_minor', new_amount_minor,
      'source', case when target_deposit_event_id is not null then 'quote_deposit' else 'payment' end
    )
  );
end;
$$;


ALTER FUNCTION "public"."apply_client_payment"("target_organization_id" "uuid", "target_invoice_id" "uuid", "target_payment_event_id" "uuid", "target_deposit_event_id" "uuid", "new_amount_minor" bigint, "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_client_payment"("target_organization_id" "uuid", "target_invoice_id" "uuid", "target_payment_event_id" "uuid", "target_deposit_event_id" "uuid", "new_amount_minor" bigint, "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Puts money the client has already given -- a recorded payment or a quote deposit -- onto one of their bills, never more than that money still has left and never more than the bill still owes.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_administrator_email_recovery"("target_organization_id" "uuid", "target_user_id" "uuid", "old_email" "text", "new_email" "text", "evidence_summary" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members%rowtype;
  inserted_event public.access_audit_events%rowtype;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
begin
  if char_length(trim(coalesce(private_reason, ''))) not between 1 and 1000 then
    raise exception 'A recovery reason is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(evidence_summary, ''))) not between 1 and 1000 then
    raise exception 'An identity-verification note is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required.' using errcode = 'check_violation';
  end if;
  if command_time > now() then
    raise exception 'A recovery cannot be dated in the future.' using errcode = 'check_violation';
  end if;

  select * into membership
  from public.organization_members
  where organization_id = target_organization_id and user_id = target_user_id
  for update;
  if not found then
    raise exception 'Team member was not found in this organization.' using errcode = 'foreign_key_violation';
  end if;
  if membership.role not in ('owner', 'admin') then
    raise exception 'Administrator recovery only applies to an owner or admin.'
      using errcode = 'check_violation';
  end if;

  delete from auth.sessions where user_id = target_user_id;

  insert into public.access_audit_events (
    organization_id, actor_kind, actor_owner_email, event_type, target_type, target_key,
    before_state, after_state
  ) values (
    target_organization_id, 'platform_owner', trim(actor_owner_email),
    'organization_member.administrator_email_recovered', 'organization_member', target_user_id::text,
    jsonb_build_object('email', old_email),
    jsonb_build_object(
      'email', new_email,
      'reason', trim(private_reason),
      'evidence_summary', trim(evidence_summary)
    )
  ) returning * into inserted_event;

  return jsonb_build_object('event_id', inserted_event.id, 'occurred_at', inserted_event.created_at);
end;
$$;


ALTER FUNCTION "public"."apply_organization_administrator_email_recovery"("target_organization_id" "uuid", "target_user_id" "uuid", "old_email" "text", "new_email" "text", "evidence_summary" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_administrator_email_recovery"("target_organization_id" "uuid", "target_user_id" "uuid", "old_email" "text", "new_email" "text", "evidence_summary" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) IS 'Records administrator email recovery evidence and revokes sessions after a GoTrue email update already succeeded. Part 7.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_closure_restore"("target_organization_id" "uuid", "idempotency_key" "text", "restoration_evidence_note" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_state public.organization_commercial_state%rowtype;
  existing_event public.organization_commercial_events%rowtype;
  organization_row public.organizations%rowtype;
  open_closure_record public.organization_closure_records%rowtype;
  inserted_event public.organization_commercial_events%rowtype;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
begin
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(restoration_evidence_note, ''))) not between 1 and 1000 then
    raise exception 'A safe evidence note is required to restore an organization.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required.' using errcode = 'check_violation';
  end if;
  if command_time > now() then
    raise exception 'Restoration cannot be dated in the future.' using errcode = 'check_violation';
  end if;

  perform private.ensure_organization_commercial_rows(target_organization_id);

  select * into current_state
  from public.organization_commercial_state
  where organization_id = target_organization_id
  for update;

  select * into existing_event
  from public.organization_commercial_events
  where organization_id = target_organization_id
    and organization_commercial_events.idempotency_key = apply_organization_closure_restore.idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id, 'change_after', existing_event.change_after);
  end if;

  select * into organization_row
  from public.organizations
  where id = target_organization_id
  for update;
  if not found then
    raise exception 'Organization was not found.' using errcode = 'foreign_key_violation';
  end if;

  if organization_row.lifecycle_status <> 'pending_closure' then
    raise exception 'Only a closing organization can be restored.' using errcode = 'check_violation';
  end if;

  select * into open_closure_record
  from public.organization_closure_records
  where organization_id = target_organization_id
    and status = 'pending_closure'
  for update;
  if not found then
    raise exception 'No open closure window was found for this organization.'
      using errcode = 'check_violation';
  end if;

  update public.organization_closure_records
  set status = 'restored',
      restored_at = command_time,
      restored_by_owner_email = trim(actor_owner_email),
      restoration_evidence_note = trim(apply_organization_closure_restore.restoration_evidence_note)
  where id = open_closure_record.id;

  insert into public.organization_commercial_events (
    organization_id, event_kind, occurred_at, actor_owner_email, summary, private_reason,
    paid_through_effect, paid_through_before, paid_through_after, grace_ends_at_after,
    change_before, change_after, idempotency_key
  ) values (
    target_organization_id, 'organization_closure_restored', command_time, trim(actor_owner_email),
    'Organization closure restored.', trim(apply_organization_closure_restore.restoration_evidence_note),
    'unchanged', current_state.paid_through_date, current_state.paid_through_date, current_state.grace_ends_at,
    jsonb_build_object('lifecycle_status', 'pending_closure'),
    jsonb_build_object('lifecycle_status', open_closure_record.prior_lifecycle_status,
      'closure_record_id', open_closure_record.id),
    idempotency_key
  ) returning * into inserted_event;

  update public.organizations
  set lifecycle_status = open_closure_record.prior_lifecycle_status, updated_at = now()
  where id = target_organization_id;

  update public.organization_commercial_state
  set last_event_id = inserted_event.id,
      state_version = current_state.state_version + 1
  where organization_id = target_organization_id
    and state_version = current_state.state_version;
  if not found then
    raise exception 'The commercial state changed during this command. Retry the command.'
      using errcode = 'P0409';
  end if;

  insert into public.organization_safe_events (
    organization_id, commercial_event_id, safe_kind, safe_payload, occurred_at
  ) values (
    target_organization_id, inserted_event.id, 'closure_restored',
    jsonb_build_object('access_status', open_closure_record.prior_lifecycle_status),
    command_time
  );

  return jsonb_build_object('applied', true, 'event_id', inserted_event.id,
    'lifecycle_status', open_closure_record.prior_lifecycle_status);
end;
$$;


ALTER FUNCTION "public"."apply_organization_closure_restore"("target_organization_id" "uuid", "idempotency_key" "text", "restoration_evidence_note" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_closure_restore"("target_organization_id" "uuid", "idempotency_key" "text", "restoration_evidence_note" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) IS 'Restores an organization from an open closure window back to its prior lifecycle status, and records immutable reasoned history.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_closure_start"("target_organization_id" "uuid", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_state public.organization_commercial_state%rowtype;
  existing_event public.organization_commercial_events%rowtype;
  organization_row public.organizations%rowtype;
  inserted_event public.organization_commercial_events%rowtype;
  inserted_closure_record public.organization_closure_records%rowtype;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
  target_deadline_at timestamptz;
begin
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(private_reason, ''))) not between 1 and 1000 then
    raise exception 'A private reason is required to start closure.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required.' using errcode = 'check_violation';
  end if;
  if command_time > now() then
    raise exception 'Closure cannot be dated in the future.' using errcode = 'check_violation';
  end if;

  perform private.ensure_organization_commercial_rows(target_organization_id);

  select * into current_state
  from public.organization_commercial_state
  where organization_id = target_organization_id
  for update;

  select * into existing_event
  from public.organization_commercial_events
  where organization_id = target_organization_id
    and organization_commercial_events.idempotency_key = apply_organization_closure_start.idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id, 'change_after', existing_event.change_after);
  end if;

  select * into organization_row
  from public.organizations
  where id = target_organization_id
  for update;
  if not found then
    raise exception 'Organization was not found.' using errcode = 'foreign_key_violation';
  end if;

  if organization_row.lifecycle_status not in ('active', 'suspended') then
    raise exception 'Only an active or suspended organization can start closure.'
      using errcode = 'check_violation';
  end if;

  target_deadline_at := command_time + interval '30 days';

  insert into public.organization_closure_records (
    organization_id, reason, prior_lifecycle_status, started_at, started_by_owner_email, deadline_at
  ) values (
    target_organization_id, trim(private_reason), organization_row.lifecycle_status, command_time,
    trim(actor_owner_email), target_deadline_at
  ) returning * into inserted_closure_record;

  insert into public.organization_commercial_events (
    organization_id, event_kind, occurred_at, actor_owner_email, summary, private_reason,
    paid_through_effect, paid_through_before, paid_through_after, grace_ends_at_after,
    change_before, change_after, idempotency_key
  ) values (
    target_organization_id, 'organization_closure_started', command_time, trim(actor_owner_email),
    'Organization closure started.', trim(private_reason),
    'unchanged', current_state.paid_through_date, current_state.paid_through_date, current_state.grace_ends_at,
    jsonb_build_object('lifecycle_status', organization_row.lifecycle_status),
    jsonb_build_object('lifecycle_status', 'pending_closure', 'closure_record_id', inserted_closure_record.id,
      'deadline_at', target_deadline_at),
    idempotency_key
  ) returning * into inserted_event;

  update public.organizations
  set lifecycle_status = 'pending_closure', updated_at = now()
  where id = target_organization_id;

  update public.organization_commercial_state
  set last_event_id = inserted_event.id,
      state_version = current_state.state_version + 1
  where organization_id = target_organization_id
    and state_version = current_state.state_version;
  if not found then
    raise exception 'The commercial state changed during this command. Retry the command.'
      using errcode = 'P0409';
  end if;

  insert into public.organization_safe_events (
    organization_id, commercial_event_id, safe_kind, safe_payload, occurred_at
  ) values (
    target_organization_id, inserted_event.id, 'closure_started',
    jsonb_build_object('access_status', 'pending_closure', 'closure_deadline_at', target_deadline_at),
    command_time
  );

  return jsonb_build_object('applied', true, 'event_id', inserted_event.id,
    'closure_record_id', inserted_closure_record.id, 'deadline_at', target_deadline_at);
end;
$$;


ALTER FUNCTION "public"."apply_organization_closure_start"("target_organization_id" "uuid", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_closure_start"("target_organization_id" "uuid", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) IS 'Starts a 30-day recoverable closure window: blocks the organization, opens a closure record, and records immutable reasoned history.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_commercial_command"("target_organization_id" "uuid", "event_kind" "text", "idempotency_key" "text", "summary" "text", "paid_through_effect" "text", "paid_through_date" "date" DEFAULT NULL::"date", "actor_owner_email" "text" DEFAULT NULL::"text", "occurred_at" timestamp with time zone DEFAULT "now"(), "private_reason" "text" DEFAULT NULL::"text", "private_reference" "text" DEFAULT NULL::"text", "amount_usd_cents" integer DEFAULT NULL::integer, "original_confirmation_id" "uuid" DEFAULT NULL::"uuid", "source_event_id" "uuid" DEFAULT NULL::"uuid", "suspension_category" "text" DEFAULT NULL::"text", "commercial_timezone" "text" DEFAULT NULL::"text", "recalculate_deadline" boolean DEFAULT false, "is_legacy_import" boolean DEFAULT false, "safe_kind" "text" DEFAULT NULL::"text", "safe_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_state public.organization_commercial_state%rowtype;
  current_settings public.organization_commercial_settings%rowtype;
  existing_event public.organization_commercial_events%rowtype;
  next_paid_through date;
  next_paid_through_source text;
  next_timezone text;
  next_grace_ends_at timestamptz;
  next_grace_timezone text;
  inserted_event public.organization_commercial_events%rowtype;
begin
  if paid_through_effect not in ('set', 'unchanged') then
    raise exception 'The paid-through effect must be confirmed as set or unchanged.'
      using errcode = 'check_violation';
  end if;

  if paid_through_effect = 'set' and paid_through_date is null then
    raise exception 'A confirmed paid-through change requires the resulting paid-through date.'
      using errcode = 'check_violation';
  end if;

  if event_kind = 'commercial_timezone_changed' and commercial_timezone is null then
    raise exception 'A commercial timezone change requires the new timezone.'
      using errcode = 'check_violation';
  end if;

  perform private.ensure_organization_commercial_rows(target_organization_id);

  -- Serializes concurrent commands for one organization. Every command path takes this lock before
  -- reading the projection it is about to advance.
  select * into current_state
  from public.organization_commercial_state
  where organization_commercial_state.organization_id = target_organization_id
  for update;

  select * into existing_event
  from public.organization_commercial_events as event
  where event.organization_id = target_organization_id
    and event.idempotency_key = apply_organization_commercial_command.idempotency_key;

  if found then
    return jsonb_build_object(
      'applied', false,
      'event_id', existing_event.id,
      'organization_id', target_organization_id,
      'paid_through_date', current_state.paid_through_date,
      'paid_through_source', current_state.paid_through_source,
      'grace_ends_at', current_state.grace_ends_at,
      'state_version', current_state.state_version
    );
  end if;

  select * into current_settings
  from public.organization_commercial_settings
  where organization_commercial_settings.organization_id = target_organization_id;

  next_timezone := case
    when event_kind = 'commercial_timezone_changed' then commercial_timezone
    else current_settings.commercial_timezone
  end;

  next_paid_through := case
    when paid_through_effect = 'set' then paid_through_date
    else current_state.paid_through_date
  end;

  next_paid_through_source := case
    when paid_through_effect <> 'set' then current_state.paid_through_source
    when event_kind = 'initial_payment_confirmed' then 'provisioning'
    when event_kind = 'renewal_confirmed' then 'renewal'
    when event_kind = 'refund_recorded' then 'refund'
    when event_kind = 'payment_reversal_recorded' then 'reversal'
    else 'manual_correction'
  end;

  -- A commercial-timezone change preserves the existing deadline unless recalculation is confirmed.
  if event_kind = 'commercial_timezone_changed' and not recalculate_deadline then
    next_grace_ends_at := current_state.grace_ends_at;
    next_grace_timezone := current_state.grace_basis_timezone;
    if next_paid_through is not null and next_grace_ends_at is null then
      next_grace_ends_at := private.organization_grace_ends_at(next_paid_through, next_timezone);
      next_grace_timezone := next_timezone;
    end if;
  else
    next_grace_ends_at := private.organization_grace_ends_at(next_paid_through, next_timezone);
    next_grace_timezone := case when next_paid_through is null then null else next_timezone end;
  end if;

  insert into public.organization_commercial_events (
    organization_id,
    event_kind,
    occurred_at,
    actor_owner_email,
    summary,
    private_reason,
    private_reference,
    amount_usd_cents,
    original_confirmation_id,
    source_event_id,
    suspension_category,
    is_legacy_import,
    paid_through_effect,
    paid_through_before,
    paid_through_after,
    commercial_timezone_before,
    commercial_timezone_after,
    deadline_recalculated,
    grace_ends_at_after,
    idempotency_key
  )
  values (
    target_organization_id,
    apply_organization_commercial_command.event_kind,
    apply_organization_commercial_command.occurred_at,
    apply_organization_commercial_command.actor_owner_email,
    apply_organization_commercial_command.summary,
    apply_organization_commercial_command.private_reason,
    apply_organization_commercial_command.private_reference,
    apply_organization_commercial_command.amount_usd_cents,
    apply_organization_commercial_command.original_confirmation_id,
    apply_organization_commercial_command.source_event_id,
    apply_organization_commercial_command.suspension_category,
    apply_organization_commercial_command.is_legacy_import,
    apply_organization_commercial_command.paid_through_effect,
    current_state.paid_through_date,
    next_paid_through,
    case when event_kind = 'commercial_timezone_changed' then current_settings.commercial_timezone end,
    case when event_kind = 'commercial_timezone_changed' then next_timezone end,
    event_kind = 'commercial_timezone_changed' and recalculate_deadline,
    next_grace_ends_at,
    apply_organization_commercial_command.idempotency_key
  )
  returning * into inserted_event;

  if event_kind = 'commercial_timezone_changed' then
    update public.organization_commercial_settings
    set commercial_timezone = next_timezone,
        timezone_source = 'owner_set'
    where organization_commercial_settings.organization_id = target_organization_id;
  end if;

  update public.organization_commercial_state
  set paid_through_date = next_paid_through,
      paid_through_source = next_paid_through_source,
      grace_ends_at = next_grace_ends_at,
      grace_basis_timezone = next_grace_timezone,
      last_event_id = inserted_event.id,
      state_version = current_state.state_version + 1
  where organization_commercial_state.organization_id = target_organization_id
    and organization_commercial_state.state_version = current_state.state_version;

  if not found then
    raise exception 'The commercial state changed during this command. Retry the command.'
      using errcode = 'P0409';
  end if;

  if safe_kind is not null then
    insert into public.organization_safe_events (
      organization_id,
      commercial_event_id,
      safe_kind,
      safe_payload,
      occurred_at
    )
    values (
      target_organization_id,
      inserted_event.id,
      apply_organization_commercial_command.safe_kind,
      coalesce(apply_organization_commercial_command.safe_payload, '{}'::jsonb),
      apply_organization_commercial_command.occurred_at
    );
  end if;

  return jsonb_build_object(
    'applied', true,
    'event_id', inserted_event.id,
    'organization_id', target_organization_id,
    'paid_through_date', next_paid_through,
    'paid_through_source', next_paid_through_source,
    'grace_ends_at', next_grace_ends_at,
    'commercial_timezone', next_timezone,
    'state_version', current_state.state_version + 1
  );
end;
$$;


ALTER FUNCTION "public"."apply_organization_commercial_command"("target_organization_id" "uuid", "event_kind" "text", "idempotency_key" "text", "summary" "text", "paid_through_effect" "text", "paid_through_date" "date", "actor_owner_email" "text", "occurred_at" timestamp with time zone, "private_reason" "text", "private_reference" "text", "amount_usd_cents" integer, "original_confirmation_id" "uuid", "source_event_id" "uuid", "suspension_category" "text", "commercial_timezone" "text", "recalculate_deadline" boolean, "is_legacy_import" boolean, "safe_kind" "text", "safe_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_commercial_command"("target_organization_id" "uuid", "event_kind" "text", "idempotency_key" "text", "summary" "text", "paid_through_effect" "text", "paid_through_date" "date", "actor_owner_email" "text", "occurred_at" timestamp with time zone, "private_reason" "text", "private_reference" "text", "amount_usd_cents" integer, "original_confirmation_id" "uuid", "source_event_id" "uuid", "suspension_category" "text", "commercial_timezone" "text", "recalculate_deadline" boolean, "is_legacy_import" boolean, "safe_kind" "text", "safe_payload" "jsonb") IS 'Applies one owner commercial command atomically: private event, current projection, and contractor-safe event. Idempotent per organization and idempotency key.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_feature_exception"("target_organization_id" "uuid", "target_feature_key" "text", "target_override_state" "text", "target_starts_at" timestamp with time zone, "target_expires_at" timestamp with time zone, "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_state public.organization_commercial_state%rowtype;
  before_row public.organization_feature_overrides%rowtype;
  has_before boolean := false;
  before_json jsonb := '{}'::jsonb;
  after_json jsonb := '{}'::jsonb;
  inserted_event public.organization_commercial_events%rowtype;
  existing_event public.organization_commercial_events%rowtype;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
begin
  if target_override_state not in ('on', 'off', 'inherit') then
    raise exception 'The feature exception state is invalid.' using errcode = 'check_violation';
  end if;
  if target_starts_at is null or (target_expires_at is not null and target_expires_at <= target_starts_at) then
    raise exception 'A feature exception needs a valid start and optional later expiry.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(private_reason, ''))) not between 1 and 1000 then
    raise exception 'A private reason is required for a feature exception.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required.' using errcode = 'check_violation';
  end if;

  if not exists (select 1 from public.features where feature_key = target_feature_key) then
    raise exception 'The feature was not found.' using errcode = 'foreign_key_violation';
  end if;
  perform private.ensure_organization_commercial_rows(target_organization_id);
  select * into current_state from public.organization_commercial_state
  where organization_id = target_organization_id for update;
  select * into existing_event from public.organization_commercial_events
  where organization_id = target_organization_id and organization_commercial_events.idempotency_key = apply_organization_feature_exception.idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id, 'change_after', existing_event.change_after);
  end if;

  select * into before_row from public.organization_feature_overrides
  where organization_id = target_organization_id and feature_key = target_feature_key for update;
  has_before := found;
  if has_before then
    before_json := jsonb_build_object('feature_key', before_row.feature_key, 'override_state', before_row.override_state,
      'starts_at', before_row.starts_at, 'expires_at', before_row.expires_at,
      'reason', before_row.reason, 'is_legacy_import', before_row.is_legacy_import);
  end if;

  if target_override_state = 'inherit' then
    delete from public.organization_feature_overrides
    where organization_id = target_organization_id and feature_key = target_feature_key;
    after_json := jsonb_build_object('feature_key', target_feature_key, 'override_state', 'inherit');
  else
    insert into public.organization_feature_overrides (
      organization_id, feature_key, override_state, starts_at, expires_at, reason, actor_owner_email, is_legacy_import
    ) values (
      target_organization_id, target_feature_key, target_override_state, target_starts_at, target_expires_at,
      trim(private_reason), trim(actor_owner_email), false
    )
    on conflict (organization_id, feature_key) do update set
      override_state = excluded.override_state, starts_at = excluded.starts_at, expires_at = excluded.expires_at,
      reason = excluded.reason, actor_owner_email = excluded.actor_owner_email, is_legacy_import = false;
    after_json := jsonb_build_object('feature_key', target_feature_key, 'override_state', target_override_state,
      'starts_at', target_starts_at, 'expires_at', target_expires_at);
  end if;

  insert into public.organization_commercial_events (
    organization_id, event_kind, occurred_at, actor_owner_email, summary, private_reason,
    paid_through_effect, paid_through_before, paid_through_after, grace_ends_at_after,
    change_before, change_after, idempotency_key
  ) values (
    target_organization_id, 'feature_exception_changed', command_time, trim(actor_owner_email),
    'Feature access exception changed.', trim(private_reason), 'unchanged', current_state.paid_through_date,
    current_state.paid_through_date, current_state.grace_ends_at, before_json, after_json, idempotency_key
  ) returning * into inserted_event;
  update public.organization_commercial_state
  set last_event_id = inserted_event.id, state_version = current_state.state_version + 1
  where organization_id = target_organization_id and state_version = current_state.state_version;
  if not found then raise exception 'The commercial state changed during this command. Retry the command.' using errcode = 'P0409'; end if;
  insert into public.organization_safe_events (organization_id, commercial_event_id, safe_kind, safe_payload, occurred_at)
  values (target_organization_id, inserted_event.id, 'feature_access_changed',
    jsonb_build_object('feature_key', target_feature_key,
      'access_status', case when target_override_state = 'inherit' then 'inherited' else target_override_state end), command_time);
  return jsonb_build_object('applied', true, 'event_id', inserted_event.id, 'change_before', before_json, 'change_after', after_json);
end;
$$;


ALTER FUNCTION "public"."apply_organization_feature_exception"("target_organization_id" "uuid", "target_feature_key" "text", "target_override_state" "text", "target_starts_at" timestamp with time zone, "target_expires_at" timestamp with time zone, "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_feature_exception"("target_organization_id" "uuid", "target_feature_key" "text", "target_override_state" "text", "target_starts_at" timestamp with time zone, "target_expires_at" timestamp with time zone, "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) IS 'Atomically changes a feature exception projection and records immutable reasoned history.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_free_access_change"("target_organization_id" "uuid", "target_action" "text", "target_grant_id" "uuid", "target_starts_at" "date", "target_access_until_date" "date", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_state public.organization_commercial_state%rowtype;
  existing_event public.organization_commercial_events%rowtype;
  inserted_grant_event public.organization_free_access_events%rowtype;
  inserted_event public.organization_commercial_events%rowtype;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
  command_date date;
  current_package_version_id uuid;
  root_row record;
  has_active_grant boolean := false;
  active_until date;
  has_future_grant boolean := false;
  future_starts_at date;
  future_until date;
  has_acted_grant boolean := false;
  acted_root_id uuid;
  acted_starts_at date;
  acted_package_version_id uuid;
  acted_until date;
  effective_root_id uuid;
  effective_starts_at date;
  effective_package_version_id uuid;
  effective_until date;
  event_kind_value text;
  safe_kind_value text := 'free_access_updated';
  safe_status text;
begin
  if target_action not in ('grant', 'extend', 'convert_to_forever', 'end') then
    raise exception 'The free access action is invalid.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(private_reason, ''))) not between 1 and 500 then
    raise exception 'A private reason is required for a free access change.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required.' using errcode = 'check_violation';
  end if;
  if command_time > now() then
    raise exception 'Free access changes cannot be dated in the future.' using errcode = 'check_violation';
  end if;
  command_date := command_time::date;

  if target_action = 'grant' then
    if target_grant_id is not null then
      raise exception 'A new grant cannot reference an existing grant.' using errcode = 'check_violation';
    end if;
    if target_starts_at is null or target_starts_at < command_date then
      raise exception 'A free access grant needs a start date that is today or later.' using errcode = 'check_violation';
    end if;
  else
    if target_grant_id is null then
      raise exception 'This action must reference the grant it changes.' using errcode = 'check_violation';
    end if;
    if target_starts_at is not null then
      raise exception 'Only a new grant can set a start date.' using errcode = 'check_violation';
    end if;
  end if;

  if target_action in ('convert_to_forever', 'end') and target_access_until_date is not null then
    raise exception 'This action cannot include an end date.' using errcode = 'check_violation';
  end if;
  if target_action = 'extend' and target_access_until_date is null then
    raise exception 'An extension needs a new end date.' using errcode = 'check_violation';
  end if;

  perform private.ensure_organization_commercial_rows(target_organization_id);

  select * into current_state
  from public.organization_commercial_state
  where organization_id = target_organization_id
  for update;

  select * into existing_event
  from public.organization_commercial_events
  where organization_id = target_organization_id
    and organization_commercial_events.idempotency_key = apply_organization_free_access_change.idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id, 'change_after', existing_event.change_after);
  end if;

  -- Fold every non-ended grant chain for this organization to its latest state.
  for root_row in
    select grant_row.id as root_id, grant_row.starts_at, grant_row.package_version_id,
           latest.action, latest.access_until_date
    from public.organization_free_access_events as grant_row
    join lateral (
      select event.action, event.access_until_date
      from public.organization_free_access_events as event
      where event.organization_id = target_organization_id
        and coalesce(event.target_grant_id, event.id) = grant_row.id
      order by event.occurred_at desc, event.id desc
      limit 1
    ) as latest on true
    where grant_row.organization_id = target_organization_id
      and grant_row.target_grant_id is null
      and latest.action <> 'end'
  loop
    if root_row.starts_at <= command_date
       and (root_row.access_until_date is null or root_row.access_until_date >= command_date) then
      has_active_grant := true;
      active_until := root_row.access_until_date;
    elsif root_row.starts_at > command_date then
      has_future_grant := true;
      future_starts_at := root_row.starts_at;
      future_until := root_row.access_until_date;
    end if;
    if target_grant_id is not null and root_row.root_id = target_grant_id then
      has_acted_grant := true;
      acted_root_id := root_row.root_id;
      acted_starts_at := root_row.starts_at;
      acted_package_version_id := root_row.package_version_id;
      acted_until := root_row.access_until_date;
    end if;
  end loop;

  if target_action = 'grant' then
    select assignment.package_version_id into current_package_version_id
    from public.organization_package_assignments as assignment
    where assignment.organization_id = target_organization_id
    order by assignment.effective_at desc, assignment.id desc
    limit 1;
    if current_package_version_id is null then
      raise exception 'Assign a published package version before granting free access.' using errcode = 'check_violation';
    end if;

    if target_starts_at <= command_date then
      if has_active_grant then
        raise exception 'An active free access grant already exists. Extend it instead of granting a new one.'
          using errcode = 'check_violation';
      end if;
      if has_future_grant then
        if target_access_until_date is null or future_starts_at <= target_access_until_date then
          raise exception 'The new grant would overlap the already scheduled future grant.'
            using errcode = 'check_violation';
        end if;
      end if;
    else
      if has_future_grant then
        raise exception 'A future free access grant is already scheduled. End it before scheduling another.'
          using errcode = 'check_violation';
      end if;
      if has_active_grant then
        if active_until is null or target_starts_at <= active_until then
          raise exception 'The scheduled grant would overlap the currently active grant.'
            using errcode = 'check_violation';
        end if;
      end if;
    end if;

    effective_root_id := null;
    effective_starts_at := target_starts_at;
    effective_package_version_id := current_package_version_id;
    effective_until := target_access_until_date;
    event_kind_value := 'free_access_granted';
  else
    if not has_acted_grant then
      raise exception 'The referenced free access grant is not currently active or scheduled.'
        using errcode = 'check_violation';
    end if;
    if target_action = 'extend'
       and acted_until is not null
       and target_access_until_date <= acted_until then
      raise exception 'The new end date must be later than the current end date.' using errcode = 'check_violation';
    end if;
    if target_action = 'extend' and target_access_until_date <= command_date then
      raise exception 'The new end date must be later than today.' using errcode = 'check_violation';
    end if;
    if target_action in ('extend', 'convert_to_forever')
       and acted_starts_at <= command_date
       and has_future_grant then
      if target_action = 'convert_to_forever' or target_access_until_date >= future_starts_at then
        raise exception 'This change would overlap the already scheduled future grant.'
          using errcode = 'check_violation';
      end if;
    end if;

    effective_root_id := acted_root_id;
    effective_starts_at := acted_starts_at;
    effective_package_version_id := acted_package_version_id;
    effective_until := case when target_action = 'extend' then target_access_until_date else null end;
    event_kind_value := case target_action
      when 'extend' then 'free_access_extended'
      when 'convert_to_forever' then 'free_access_converted_forever'
      else 'free_access_ended'
    end;
  end if;

  insert into public.organization_free_access_events (
    organization_id, package_version_id, action, access_until_date, starts_at, target_grant_id,
    reason, actor_owner_email, occurred_at
  ) values (
    target_organization_id, effective_package_version_id, target_action, effective_until,
    effective_starts_at, effective_root_id, trim(private_reason), trim(actor_owner_email), command_time
  ) returning * into inserted_grant_event;

  insert into public.organization_commercial_events (
    organization_id, event_kind, occurred_at, actor_owner_email, summary, private_reason,
    paid_through_effect, paid_through_before, paid_through_after, grace_ends_at_after,
    change_before, change_after, idempotency_key
  ) values (
    target_organization_id, event_kind_value, command_time, trim(actor_owner_email),
    'Free access changed.', trim(private_reason), 'unchanged', current_state.paid_through_date,
    current_state.paid_through_date, current_state.grace_ends_at,
    coalesce(jsonb_build_object('grant_id', target_grant_id), '{}'::jsonb),
    jsonb_build_object('grant_id', coalesce(effective_root_id, inserted_grant_event.id), 'action', target_action,
      'starts_at', effective_starts_at, 'access_until_date', effective_until),
    idempotency_key
  ) returning * into inserted_event;

  update public.organization_commercial_state
  set last_event_id = inserted_event.id,
      state_version = current_state.state_version + 1
  where organization_id = target_organization_id
    and state_version = current_state.state_version;
  if not found then
    raise exception 'The commercial state changed during this command. Retry the command.'
      using errcode = 'P0409';
  end if;

  safe_status := case
    when target_action = 'end' then 'ended'
    when effective_until is null then 'forever'
    else 'until_date'
  end;

  insert into public.organization_safe_events (
    organization_id, commercial_event_id, safe_kind, safe_payload, occurred_at
  ) values (
    target_organization_id, inserted_event.id, safe_kind_value,
    jsonb_build_object('access_status', safe_status, 'free_access_until_date', effective_until,
      'effective_at', effective_starts_at),
    command_time
  );

  return jsonb_build_object('applied', true, 'event_id', inserted_event.id,
    'grant_id', coalesce(effective_root_id, inserted_grant_event.id),
    'starts_at', effective_starts_at, 'access_until_date', effective_until);
end;
$$;


ALTER FUNCTION "public"."apply_organization_free_access_change"("target_organization_id" "uuid", "target_action" "text", "target_grant_id" "uuid", "target_starts_at" "date", "target_access_until_date" "date", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_free_access_change"("target_organization_id" "uuid", "target_action" "text", "target_grant_id" "uuid", "target_starts_at" "date", "target_access_until_date" "date", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) IS 'Atomically applies one free access command, enforcing at most one active and one non-overlapping future grant, and records immutable reasoned history.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_late_renewal_reactivation"("target_organization_id" "uuid", "idempotency_key" "text", "summary" "text", "paid_through_effect" "text", "paid_through_date" "date" DEFAULT NULL::"date", "actor_owner_email" "text" DEFAULT NULL::"text", "occurred_at" timestamp with time zone DEFAULT "now"(), "private_reason" "text" DEFAULT NULL::"text", "private_reference" "text" DEFAULT NULL::"text", "amount_usd_cents" integer DEFAULT NULL::integer, "original_confirmation_id" "uuid" DEFAULT NULL::"uuid", "reactivate" boolean DEFAULT false, "safe_kind" "text" DEFAULT NULL::"text", "safe_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_lifecycle_status text;
  renewal_result jsonb;
  renewal_event_id uuid;
  reactivation_result jsonb;
begin
  if reactivate and (actor_owner_email is null or char_length(trim(actor_owner_email)) = 0) then
    raise exception 'An acting owner email is required to reactivate an organization.'
      using errcode = 'check_violation';
  end if;

  if reactivate then
    select lifecycle_status into current_lifecycle_status
    from public.organizations
    where id = target_organization_id
    for update;

    if current_lifecycle_status is null then
      raise exception 'Organization % was not found.', target_organization_id
        using errcode = 'foreign_key_violation';
    end if;

    if current_lifecycle_status <> 'suspended' then
      raise exception 'Only a suspended organization can be reactivated.'
        using errcode = 'check_violation';
    end if;
  end if;

  renewal_result := public.apply_organization_commercial_command(
    target_organization_id => target_organization_id,
    event_kind => 'renewal_confirmed',
    idempotency_key => idempotency_key,
    summary => summary,
    paid_through_effect => paid_through_effect,
    paid_through_date => paid_through_date,
    actor_owner_email => actor_owner_email,
    occurred_at => occurred_at,
    private_reason => private_reason,
    private_reference => private_reference,
    amount_usd_cents => amount_usd_cents,
    original_confirmation_id => original_confirmation_id,
    safe_kind => safe_kind,
    safe_payload => safe_payload
  );

  -- Not requested, or an idempotent replay of an already-applied renewal: reactivation (if any)
  -- already happened on the original call. Never reactivate on a retry.
  if not reactivate or (renewal_result ->> 'applied') <> 'true' then
    return renewal_result || jsonb_build_object('reactivated', false);
  end if;

  renewal_event_id := (renewal_result ->> 'event_id')::uuid;

  update public.organizations
  set lifecycle_status = 'active', updated_at = now()
  where id = target_organization_id;

  reactivation_result := public.apply_organization_commercial_command(
    target_organization_id => target_organization_id,
    event_kind => 'organization_reactivated',
    idempotency_key => idempotency_key || ':reactivation',
    summary => 'Organization reactivated after late renewal.',
    paid_through_effect => 'unchanged',
    actor_owner_email => actor_owner_email,
    occurred_at => occurred_at,
    private_reason => coalesce(private_reason, 'Reactivated after late renewal.'),
    source_event_id => renewal_event_id,
    safe_kind => 'account_reactivated'
  );

  insert into public.access_audit_events (
    organization_id, actor_kind, actor_owner_email, event_type, target_type, target_key,
    before_state, after_state
  ) values (
    target_organization_id, 'platform_owner', actor_owner_email, 'organization.lifecycle_changed',
    'organization.lifecycle_status', target_organization_id::text,
    jsonb_build_object('lifecycle_status', 'suspended'),
    jsonb_build_object('lifecycle_status', 'active')
  );

  return renewal_result || jsonb_build_object(
    'reactivated', true,
    'reactivation_event_id', reactivation_result ->> 'event_id'
  );
end;
$$;


ALTER FUNCTION "public"."apply_organization_late_renewal_reactivation"("target_organization_id" "uuid", "idempotency_key" "text", "summary" "text", "paid_through_effect" "text", "paid_through_date" "date", "actor_owner_email" "text", "occurred_at" timestamp with time zone, "private_reason" "text", "private_reference" "text", "amount_usd_cents" integer, "original_confirmation_id" "uuid", "reactivate" boolean, "safe_kind" "text", "safe_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_late_renewal_reactivation"("target_organization_id" "uuid", "idempotency_key" "text", "summary" "text", "paid_through_effect" "text", "paid_through_date" "date", "actor_owner_email" "text", "occurred_at" timestamp with time zone, "private_reason" "text", "private_reference" "text", "amount_usd_cents" integer, "original_confirmation_id" "uuid", "reactivate" boolean, "safe_kind" "text", "safe_payload" "jsonb") IS 'Records a renewal commercial event and, only when explicitly requested, reactivates a suspended organization in the same transaction as a distinct chained event.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_lifecycle_change"("target_organization_id" "uuid", "target_status" "text", "target_suspension_category" "text", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_state public.organization_commercial_state%rowtype;
  existing_event public.organization_commercial_events%rowtype;
  organization_row public.organizations%rowtype;
  inserted_event public.organization_commercial_events%rowtype;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
  command_date date;
  last_suspension public.organization_commercial_events%rowtype;
  commercial_timezone text;
  is_eligible boolean;
  active_owner_count integer;
begin
  if target_status not in ('active', 'suspended') then
    raise exception 'The organization status is invalid.' using errcode = 'check_violation';
  end if;
  if target_status = 'suspended'
     and coalesce(target_suspension_category, '') not in ('nonpayment', 'payment_dispute', 'security', 'support', 'other') then
    raise exception 'A suspension requires a valid category.' using errcode = 'check_violation';
  end if;
  if target_status = 'active' and target_suspension_category is not null then
    raise exception 'Reactivation cannot include a suspension category.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(private_reason, ''))) not between 1 and 1000 then
    raise exception 'A private reason is required for a lifecycle change.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required.' using errcode = 'check_violation';
  end if;
  if command_time > now() then
    raise exception 'Lifecycle changes cannot be dated in the future.' using errcode = 'check_violation';
  end if;
  command_date := command_time::date;

  perform private.ensure_organization_commercial_rows(target_organization_id);

  select * into current_state
  from public.organization_commercial_state
  where organization_id = target_organization_id
  for update;

  select * into existing_event
  from public.organization_commercial_events
  where organization_id = target_organization_id
    and organization_commercial_events.idempotency_key = apply_organization_lifecycle_change.idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id, 'change_after', existing_event.change_after);
  end if;

  select * into organization_row
  from public.organizations
  where id = target_organization_id
  for update;
  if not found then
    raise exception 'Organization was not found.' using errcode = 'foreign_key_violation';
  end if;

  if organization_row.lifecycle_status = target_status then
    raise exception 'The organization already has this status.' using errcode = 'check_violation';
  end if;
  if organization_row.lifecycle_status = 'pending_setup' then
    raise exception 'Legacy pending organizations must be reviewed before a lifecycle change.'
      using errcode = 'check_violation';
  end if;

  if target_status = 'active' then
    select count(*) into active_owner_count
    from public.organization_members
    where organization_id = target_organization_id and role = 'owner';
    if active_owner_count = 0 then
      raise exception 'Invite the first administrator before activation.' using errcode = 'check_violation';
    end if;

    select * into last_suspension
    from public.organization_commercial_events
    where organization_id = target_organization_id
      and event_kind = 'organization_suspended'
    order by organization_commercial_events.occurred_at desc, organization_commercial_events.id desc
    limit 1;

    if found and last_suspension.suspension_category in ('nonpayment', 'payment_dispute') then
      select commercial.commercial_timezone into commercial_timezone
      from public.organization_commercial_settings as commercial
      where commercial.organization_id = target_organization_id;

      is_eligible := current_state.paid_through_date is not null
        and (
          current_state.paid_through_date >= (now() at time zone coalesce(commercial_timezone, 'UTC'))::date
          or (current_state.grace_ends_at is not null and current_state.grace_ends_at >= now())
        );

      if not is_eligible then
        is_eligible := exists (
          select 1
          from public.organization_free_access_events as grant_row
          join lateral (
            select event.action, event.access_until_date
            from public.organization_free_access_events as event
            where event.organization_id = target_organization_id
              and coalesce(event.target_grant_id, event.id) = grant_row.id
            order by event.occurred_at desc, event.id desc
            limit 1
          ) as latest on true
          where grant_row.organization_id = target_organization_id
            and grant_row.target_grant_id is null
            and latest.action <> 'end'
            and grant_row.starts_at <= command_date
            and (latest.access_until_date is null or latest.access_until_date >= command_date)
        );
      end if;

      if not is_eligible then
        raise exception 'Restore paid-through eligibility or active free access before reactivating.'
          using errcode = 'check_violation';
      end if;
    end if;
  end if;

  insert into public.organization_commercial_events (
    organization_id, event_kind, occurred_at, actor_owner_email, summary, private_reason,
    suspension_category, paid_through_effect, paid_through_before, paid_through_after,
    grace_ends_at_after, change_before, change_after, idempotency_key
  ) values (
    target_organization_id,
    case when target_status = 'suspended' then 'organization_suspended' else 'organization_reactivated' end,
    command_time, trim(actor_owner_email),
    case when target_status = 'suspended' then 'Organization suspended.' else 'Organization reactivated.' end,
    trim(private_reason),
    case when target_status = 'suspended' then target_suspension_category else null end,
    'unchanged', current_state.paid_through_date, current_state.paid_through_date, current_state.grace_ends_at,
    jsonb_build_object('lifecycle_status', organization_row.lifecycle_status),
    jsonb_build_object('lifecycle_status', target_status),
    idempotency_key
  ) returning * into inserted_event;

  update public.organizations
  set lifecycle_status = target_status, updated_at = now()
  where id = target_organization_id;

  update public.organization_commercial_state
  set last_event_id = inserted_event.id,
      state_version = current_state.state_version + 1
  where organization_id = target_organization_id
    and state_version = current_state.state_version;
  if not found then
    raise exception 'The commercial state changed during this command. Retry the command.'
      using errcode = 'P0409';
  end if;

  insert into public.organization_safe_events (
    organization_id, commercial_event_id, safe_kind, safe_payload, occurred_at
  ) values (
    target_organization_id, inserted_event.id,
    case when target_status = 'suspended' then 'account_suspended' else 'account_reactivated' end,
    jsonb_build_object('access_status', target_status),
    command_time
  );

  return jsonb_build_object('applied', true, 'event_id', inserted_event.id, 'lifecycle_status', target_status);
end;
$$;


ALTER FUNCTION "public"."apply_organization_lifecycle_change"("target_organization_id" "uuid", "target_status" "text", "target_suspension_category" "text", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_lifecycle_change"("target_organization_id" "uuid", "target_status" "text", "target_suspension_category" "text", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) IS 'Atomically applies one categorized suspend/reactivate command with eligibility-checked reactivation, and records immutable reasoned history.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_limit_exception"("target_organization_id" "uuid", "target_limit_key" "text", "target_limit_state" "text", "target_limit_value" integer, "target_starts_at" timestamp with time zone, "target_expires_at" timestamp with time zone, "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_state public.organization_commercial_state%rowtype;
  before_row public.organization_limit_overrides%rowtype;
  before_json jsonb := '{}'::jsonb;
  after_json jsonb := '{}'::jsonb;
  inserted_event public.organization_commercial_events%rowtype;
  existing_event public.organization_commercial_events%rowtype;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
begin
  if target_limit_key not in (
    'employee_seats', 'operational_email_recipients', 'essential_email_recipients',
    'website_chat_widgets', 'website_chat_accepted_conversations',
    'automation_active_recipes', 'automation_max_conditions_per_recipe',
    'automation_max_steps_per_recipe', 'automation_max_customer_messages_per_enrollment',
    'automation_min_customer_message_spacing_minutes', 'automation_max_delay_days',
    'automation_max_enrollment_duration_days',
    'marketing_email_recipients'
  ) then
    raise exception 'The limit was not found.' using errcode = 'foreign_key_violation';
  end if;
  if target_limit_state not in ('unlimited', 'not_included', 'numeric', 'inherit') then
    raise exception 'The limit exception state is invalid.' using errcode = 'check_violation';
  end if;
  if target_limit_state = 'numeric' and (target_limit_value is null or target_limit_value < 0) then
    raise exception 'A numeric limit must be zero or greater.' using errcode = 'check_violation';
  end if;
  if target_limit_state <> 'numeric' and target_limit_value is not null then
    raise exception 'Only numeric limits can include a value.' using errcode = 'check_violation';
  end if;
  if target_starts_at is null or (target_expires_at is not null and target_expires_at <= target_starts_at) then
    raise exception 'A limit exception needs a valid start and optional later expiry.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(private_reason, ''))) not between 1 and 1000 then
    raise exception 'A private reason is required for a limit exception.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required.' using errcode = 'check_violation';
  end if;

  perform private.ensure_organization_commercial_rows(target_organization_id);
  select * into current_state from public.organization_commercial_state
  where organization_id = target_organization_id for update;
  select * into existing_event from public.organization_commercial_events
  where organization_id = target_organization_id
    and organization_commercial_events.idempotency_key = apply_organization_limit_exception.idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id, 'change_after', existing_event.change_after);
  end if;

  select * into before_row from public.organization_limit_overrides
  where organization_id = target_organization_id and limit_key = target_limit_key for update;
  if found then
    before_json := jsonb_build_object('limit_key', before_row.limit_key, 'limit_state', before_row.limit_state,
      'limit_value', before_row.limit_value, 'starts_at', before_row.starts_at, 'expires_at', before_row.expires_at,
      'reason', before_row.reason, 'is_legacy_import', before_row.is_legacy_import);
  end if;

  if target_limit_state = 'inherit' then
    delete from public.organization_limit_overrides
    where organization_id = target_organization_id and limit_key = target_limit_key;
    after_json := jsonb_build_object('limit_key', target_limit_key, 'limit_state', 'inherit');
  else
    insert into public.organization_limit_overrides (
      organization_id, limit_key, limit_state, limit_value, is_unlimited, starts_at, expires_at,
      reason, actor_owner_email, is_legacy_import
    ) values (
      target_organization_id, target_limit_key, target_limit_state,
      case when target_limit_state = 'numeric' then target_limit_value else null end,
      target_limit_state = 'unlimited', target_starts_at, target_expires_at,
      trim(private_reason), trim(actor_owner_email), false
    )
    on conflict (organization_id, limit_key) do update set
      limit_state = excluded.limit_state, limit_value = excluded.limit_value,
      is_unlimited = excluded.is_unlimited, starts_at = excluded.starts_at, expires_at = excluded.expires_at,
      reason = excluded.reason, actor_owner_email = excluded.actor_owner_email, is_legacy_import = false;
    after_json := jsonb_build_object('limit_key', target_limit_key, 'limit_state', target_limit_state,
      'limit_value', case when target_limit_state = 'numeric' then target_limit_value else null end,
      'starts_at', target_starts_at, 'expires_at', target_expires_at);
  end if;

  insert into public.organization_commercial_events (
    organization_id, event_kind, occurred_at, actor_owner_email, summary, private_reason,
    paid_through_effect, paid_through_before, paid_through_after, grace_ends_at_after,
    change_before, change_after, idempotency_key
  ) values (
    target_organization_id, 'limit_exception_changed', command_time, trim(actor_owner_email),
    'Limit access exception changed.', trim(private_reason), 'unchanged', current_state.paid_through_date,
    current_state.paid_through_date, current_state.grace_ends_at, before_json, after_json, idempotency_key
  ) returning * into inserted_event;
  update public.organization_commercial_state
  set last_event_id = inserted_event.id, state_version = current_state.state_version + 1
  where organization_id = target_organization_id and state_version = current_state.state_version;
  if not found then
    raise exception 'The commercial state changed during this command.' using errcode = 'serialization_failure';
  end if;
  insert into public.organization_safe_events (organization_id, commercial_event_id, safe_kind, safe_payload, occurred_at)
  values (target_organization_id, inserted_event.id, 'limit_access_changed',
    jsonb_build_object('limit_key', target_limit_key,
      'limit_state', case when target_limit_state = 'inherit' then 'inherited' else target_limit_state end,
      'limit_value', case when target_limit_state = 'numeric' then target_limit_value else null end), command_time);
  return jsonb_build_object('applied', true, 'event_id', inserted_event.id, 'change_before', before_json, 'change_after', after_json);
end;
$$;


ALTER FUNCTION "public"."apply_organization_limit_exception"("target_organization_id" "uuid", "target_limit_key" "text", "target_limit_state" "text", "target_limit_value" integer, "target_starts_at" timestamp with time zone, "target_expires_at" timestamp with time zone, "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_limit_exception"("target_organization_id" "uuid", "target_limit_key" "text", "target_limit_state" "text", "target_limit_value" integer, "target_starts_at" timestamp with time zone, "target_expires_at" timestamp with time zone, "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) IS 'Atomically changes a limit exception projection and records immutable reasoned history.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_member_profile_correction"("target_organization_id" "uuid", "target_user_id" "uuid", "new_full_name" "text", "email_changed" boolean, "old_email" "text", "new_email" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members%rowtype;
  inserted_event public.access_audit_events%rowtype;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
  before_state jsonb;
  after_state jsonb;
begin
  if char_length(trim(coalesce(private_reason, ''))) not between 1 and 1000 then
    raise exception 'A correction reason is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required.' using errcode = 'check_violation';
  end if;
  if command_time > now() then
    raise exception 'A correction cannot be dated in the future.' using errcode = 'check_violation';
  end if;

  select * into membership
  from public.organization_members
  where organization_id = target_organization_id and user_id = target_user_id
  for update;
  if not found then
    raise exception 'Team member was not found in this organization.' using errcode = 'foreign_key_violation';
  end if;

  if email_changed and membership.role in ('owner', 'admin') then
    raise exception 'An administrator email change must use administrator recovery.'
      using errcode = 'check_violation';
  end if;

  before_state := jsonb_build_object('full_name', (select full_name from public.profiles where id = target_user_id));
  after_state := jsonb_build_object('full_name', new_full_name);

  if new_full_name is not null and new_full_name is distinct from (before_state ->> 'full_name') then
    update public.profiles set full_name = new_full_name, updated_at = now() where id = target_user_id;
  end if;

  if email_changed then
    before_state := before_state || jsonb_build_object('email', old_email);
    after_state := after_state || jsonb_build_object('email', new_email);
    delete from auth.sessions where user_id = target_user_id;
  end if;

  insert into public.access_audit_events (
    organization_id, actor_kind, actor_owner_email, event_type, target_type, target_key,
    before_state, after_state
  ) values (
    target_organization_id, 'platform_owner', trim(actor_owner_email),
    'organization_member.profile_corrected', 'organization_member', target_user_id::text,
    before_state, after_state || jsonb_build_object('reason', trim(private_reason))
  ) returning * into inserted_event;

  return jsonb_build_object('event_id', inserted_event.id, 'occurred_at', inserted_event.created_at);
end;
$$;


ALTER FUNCTION "public"."apply_organization_member_profile_correction"("target_organization_id" "uuid", "target_user_id" "uuid", "new_full_name" "text", "email_changed" boolean, "old_email" "text", "new_email" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_member_profile_correction"("target_organization_id" "uuid", "target_user_id" "uuid", "new_full_name" "text", "email_changed" boolean, "old_email" "text", "new_email" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) IS 'Records a support correction to a team member''s name and (non-admin only) email; revokes sessions when email changed. Part 7.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_package_change"("target_organization_id" "uuid", "target_package_version_id" "uuid", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_state public.organization_commercial_state%rowtype;
  current_assignment public.organization_package_assignments%rowtype;
  current_version_id uuid;
  current_version jsonb;
  target_version record;
  inserted_assignment public.organization_package_assignments%rowtype;
  inserted_event public.organization_commercial_events%rowtype;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
  existing_event public.organization_commercial_events%rowtype;
begin
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(private_reason, ''))) not between 1 and 1000 then
    raise exception 'A private reason is required for a package change.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required.' using errcode = 'check_violation';
  end if;
  if command_time > now() then
    raise exception 'Commercial changes cannot be dated in the future.' using errcode = 'check_violation';
  end if;

  perform private.ensure_organization_commercial_rows(target_organization_id);

  select * into current_state
  from public.organization_commercial_state
  where organization_id = target_organization_id
  for update;

  select * into existing_event
  from public.organization_commercial_events
  where organization_id = target_organization_id
    and organization_commercial_events.idempotency_key = apply_organization_package_change.idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id,
      'organization_id', target_organization_id, 'change_after', existing_event.change_after);
  end if;

  select version.id, version.version_number, version.display_name, version.package_id,
         package.package_key, package.display_name as package_display_name,
         version.status as version_status, package.status as package_status
  into target_version
  from public.platform_package_versions as version
  join public.platform_packages as package on package.package_id = version.package_id
  where version.id = target_package_version_id;
  if not found then
    raise exception 'The package version was not found.' using errcode = 'foreign_key_violation';
  end if;
  if target_version.version_status <> 'published' or target_version.package_status <> 'published' then
    raise exception 'A package change must use a published package version.' using errcode = 'check_violation';
  end if;

  select * into current_assignment
  from public.organization_package_assignments
  where organization_id = target_organization_id
  order by effective_at desc, id desc
  limit 1;

  current_version_id := current_assignment.package_version_id;
  if current_version_id is null then
    select version.id into current_version_id
    from public.platform_package_versions as version
    join public.platform_packages as package on package.package_id = version.package_id
    join public.organizations as organization on organization.id = target_organization_id
    where package.package_key = organization.package_key
      and version.status = 'published'
      and package.status = 'published'
    order by version.version_number desc
    limit 1;
  end if;
  if current_version_id = target_package_version_id then
    raise exception 'The organization already uses this package version.' using errcode = 'check_violation';
  end if;

  select jsonb_build_object('package_version_id', version.id, 'version_number', version.version_number,
    'package_display_name', version.display_name)
  into current_version
  from public.platform_package_versions as version
  where version.id = current_version_id;

  insert into public.organization_package_assignments (
    organization_id, package_version_id, effective_at, assignment_source, reason
  ) values (
    target_organization_id, target_package_version_id, command_time, 'package_change', trim(private_reason)
  ) returning * into inserted_assignment;

  insert into public.organization_commercial_events (
    organization_id, event_kind, occurred_at, actor_owner_email, summary, private_reason,
    paid_through_effect, paid_through_before, paid_through_after, grace_ends_at_after,
    change_before, change_after, idempotency_key
  ) values (
    target_organization_id, 'package_version_changed', command_time, trim(actor_owner_email),
    'Package version changed.', trim(private_reason), 'unchanged', current_state.paid_through_date,
    current_state.paid_through_date, current_state.grace_ends_at, coalesce(current_version, '{}'::jsonb),
    jsonb_build_object('package_version_id', target_version.id, 'version_number', target_version.version_number,
      'package_display_name', target_version.display_name), idempotency_key
  ) returning * into inserted_event;

  update public.organization_commercial_state
  set last_event_id = inserted_event.id,
      state_version = current_state.state_version + 1
  where organization_id = target_organization_id
    and state_version = current_state.state_version;
  if not found then
    raise exception 'The commercial state changed during this command. Retry the command.'
      using errcode = 'P0409';
  end if;

  insert into public.organization_safe_events (
    organization_id, commercial_event_id, safe_kind, safe_payload, occurred_at
  ) values (
    target_organization_id, inserted_event.id, 'package_changed',
    jsonb_build_object('package_display_name', target_version.display_name,
      'package_version_number', target_version.version_number, 'effective_at', command_time), command_time
  );

  return jsonb_build_object('applied', true, 'event_id', inserted_event.id,
    'assignment_id', inserted_assignment.id, 'change_before', coalesce(current_version, '{}'::jsonb),
    'change_after', jsonb_build_object('package_version_id', target_version.id,
      'version_number', target_version.version_number, 'package_display_name', target_version.display_name));
end;
$$;


ALTER FUNCTION "public"."apply_organization_package_change"("target_organization_id" "uuid", "target_package_version_id" "uuid", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_package_change"("target_organization_id" "uuid", "target_package_version_id" "uuid", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) IS 'Immediately assigns a published package version and records immutable private and contractor-safe history.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_pending_setup_reconciliation"("target_organization_id" "uuid", "target_status" "text", "target_suspension_category" "text", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_state public.organization_commercial_state%rowtype;
  existing_event public.organization_commercial_events%rowtype;
  organization_row public.organizations%rowtype;
  inserted_event public.organization_commercial_events%rowtype;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
  readiness jsonb;
begin
  if target_status not in ('active', 'suspended') then
    raise exception 'The organization status is invalid.' using errcode = 'check_violation';
  end if;
  if target_status = 'suspended'
     and coalesce(target_suspension_category, '') not in ('nonpayment', 'payment_dispute', 'security', 'support', 'other') then
    raise exception 'A suspension requires a valid category.' using errcode = 'check_violation';
  end if;
  if target_status = 'active' and target_suspension_category is not null then
    raise exception 'Activation cannot include a suspension category.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(private_reason, ''))) not between 1 and 1000 then
    raise exception 'A reconciliation reason is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required.' using errcode = 'check_violation';
  end if;
  if command_time > now() then
    raise exception 'A reconciliation cannot be dated in the future.' using errcode = 'check_violation';
  end if;

  perform private.ensure_organization_commercial_rows(target_organization_id);

  select * into current_state
  from public.organization_commercial_state
  where organization_id = target_organization_id
  for update;

  select * into existing_event
  from public.organization_commercial_events
  where organization_id = target_organization_id
    and organization_commercial_events.idempotency_key = apply_organization_pending_setup_reconciliation.idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id, 'change_after', existing_event.change_after);
  end if;

  select * into organization_row
  from public.organizations
  where id = target_organization_id
  for update;
  if not found then
    raise exception 'Organization was not found.' using errcode = 'foreign_key_violation';
  end if;

  if organization_row.lifecycle_status <> 'pending_setup' then
    raise exception 'Only a legacy pending organization can be reconciled here.'
      using errcode = 'check_violation';
  end if;

  if target_status = 'active' then
    readiness := public.organization_legacy_readiness(target_organization_id);

    if not (readiness ->> 'package_assigned')::boolean then
      raise exception 'Assign a published package version before activating.' using errcode = 'check_violation';
    end if;
    if not (readiness ->> 'administrator_exists')::boolean then
      raise exception 'This organization needs an owner or admin before activating.' using errcode = 'check_violation';
    end if;
    if not (readiness ->> 'administrator_login_ready')::boolean then
      raise exception 'The administrator has not completed login setup yet.' using errcode = 'check_violation';
    end if;
    if not (
      (readiness ->> 'paid_through_eligible')::boolean
      or (readiness ->> 'free_access_active')::boolean
    ) then
      raise exception 'Record a paid-through date or active free access before activating.'
        using errcode = 'check_violation';
    end if;
  end if;

  insert into public.organization_commercial_events (
    organization_id, event_kind, occurred_at, actor_owner_email, summary, private_reason,
    suspension_category, paid_through_effect, paid_through_before, paid_through_after,
    grace_ends_at_after, change_before, change_after, idempotency_key
  ) values (
    target_organization_id,
    'pending_setup_resolved',
    command_time, trim(actor_owner_email),
    case when target_status = 'suspended'
      then 'Legacy organization reviewed and suspended.'
      else 'Legacy organization reviewed and activated.'
    end,
    trim(private_reason),
    case when target_status = 'suspended' then target_suspension_category else null end,
    'unchanged', current_state.paid_through_date, current_state.paid_through_date, current_state.grace_ends_at,
    jsonb_build_object('lifecycle_status', organization_row.lifecycle_status),
    jsonb_build_object('lifecycle_status', target_status),
    idempotency_key
  ) returning * into inserted_event;

  update public.organizations
  set lifecycle_status = target_status, updated_at = now()
  where id = target_organization_id;

  update public.organization_commercial_state
  set last_event_id = inserted_event.id,
      state_version = current_state.state_version + 1
  where organization_id = target_organization_id
    and state_version = current_state.state_version;
  if not found then
    raise exception 'The commercial state changed during this command. Retry the command.'
      using errcode = 'P0409';
  end if;

  insert into public.organization_safe_events (
    organization_id, commercial_event_id, safe_kind, safe_payload, occurred_at
  ) values (
    target_organization_id, inserted_event.id,
    case when target_status = 'suspended' then 'account_suspended' else 'account_reactivated' end,
    jsonb_build_object('access_status', target_status),
    command_time
  );

  return jsonb_build_object('applied', true, 'event_id', inserted_event.id, 'lifecycle_status', target_status);
end;
$$;


ALTER FUNCTION "public"."apply_organization_pending_setup_reconciliation"("target_organization_id" "uuid", "target_status" "text", "target_suspension_category" "text", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_pending_setup_reconciliation"("target_organization_id" "uuid", "target_status" "text", "target_suspension_category" "text", "idempotency_key" "text", "private_reason" "text", "actor_owner_email" "text", "occurred_at" timestamp with time zone) IS 'One-time transition of a legacy pending_setup organization to active or suspended. Activation requires the readiness checklist to pass; suspension only requires a category and reason. Distinct from apply_organization_lifecycle_change, which refuses pending_setup organizations.';



CREATE OR REPLACE FUNCTION "public"."apply_organization_purge"("target_organization_id" "uuid", "purge_trigger_kind" "text", "actor_owner_email" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  organization_row public.organizations%rowtype;
  closure_record public.organization_closure_records%rowtype;
  inserted_receipt public.organization_deletion_receipts%rowtype;
  member_user_ids uuid[];
  had_onboarding_provision boolean;
  provider_resources jsonb;
  auth_pending boolean;
  provider_pending boolean;
  receipt_status text;
  receipt_completed_at timestamptz;
begin
  if purge_trigger_kind not in ('scheduled', 'early_manual') then
    raise exception 'An invalid purge trigger kind was supplied.' using errcode = 'check_violation';
  end if;
  if purge_trigger_kind = 'early_manual'
    and char_length(trim(coalesce(actor_owner_email, ''))) not between 3 and 320 then
    raise exception 'An acting owner email is required for an early manual purge.'
      using errcode = 'check_violation';
  end if;

  select * into organization_row
  from public.organizations
  where id = target_organization_id
  for update;

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'already_purged');
  end if;

  select * into closure_record
  from public.organization_closure_records
  where organization_id = target_organization_id
    and status in ('pending_closure', 'purge_in_progress')
  for update;

  if not found then
    raise exception 'No open closure window was found for this organization.'
      using errcode = 'check_violation';
  end if;

  select coalesce(array_agg(distinct organization_members.user_id), array[]::uuid[])
  into member_user_ids
  from public.organization_members
  where organization_members.organization_id = target_organization_id;

  select exists (
    select 1
    from public.platform_onboarding_application_provisions
    where platform_onboarding_application_provisions.organization_id = target_organization_id
  ) into had_onboarding_provision;

  select coalesce(jsonb_agg(resource order by resource ->> 'kind', resource ->> 'provider_id'), '[]'::jsonb)
  into provider_resources
  from (
    select jsonb_build_object('kind', 'domain', 'provider_id', provider_domain_id::text) as resource
    from public.communication_email_domains
    where organization_id = target_organization_id
      and provider_domain_id is not null
      and lifecycle_state <> 'removed'
    union all
    select jsonb_build_object('kind', 'sender', 'provider_id', provider_sender_id::text) as resource
    from public.communication_email_senders
    where organization_id = target_organization_id
      and provider_sender_id is not null
      and lifecycle_state <> 'removed'
  ) as resources;

  auth_pending := coalesce(array_length(member_user_ids, 1), 0) > 0;
  provider_pending := jsonb_array_length(provider_resources) > 0;

  if auth_pending or provider_pending then
    receipt_status := 'in_progress';
    receipt_completed_at := null;
  else
    receipt_status := 'completed';
    receipt_completed_at := now();
  end if;

  perform set_config('app.organization_purge_in_progress', 'true', true);

  delete from public.organization_package_assignments
  where organization_id = target_organization_id;

  delete from public.organization_free_access_events
  where organization_id = target_organization_id;

  update public.platform_onboarding_application_provisions
  set organization_id = null
  where organization_id = target_organization_id;

  delete from public.organizations
  where id = target_organization_id;

  insert into public.organization_deletion_receipts (
    trigger_kind, status, completed_at, component_results,
    pending_auth_user_ids, pending_provider_resources
  ) values (
    purge_trigger_kind, receipt_status, receipt_completed_at,
    jsonb_build_object(
      'organization_data', 'succeeded',
      'package_assignments', 'succeeded',
      'free_access_history', 'succeeded',
      'onboarding_provision_unlinked', case when had_onboarding_provision then 'succeeded' else 'not_applicable' end,
      'provider_resources', case when provider_pending then 'pending' else 'not_applicable' end,
      'auth_users', case when auth_pending then 'pending' else 'not_applicable' end
    ),
    case when auth_pending then member_user_ids else null end,
    case when provider_pending then provider_resources else null end
  ) returning * into inserted_receipt;

  return jsonb_build_object(
    'applied', true,
    'operation_id', inserted_receipt.operation_id,
    'member_user_ids', to_jsonb(member_user_ids),
    'provider_resources', provider_resources
  );
end;
$$;


ALTER FUNCTION "public"."apply_organization_purge"("target_organization_id" "uuid", "purge_trigger_kind" "text", "actor_owner_email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_organization_purge"("target_organization_id" "uuid", "purge_trigger_kind" "text", "actor_owner_email" "text") IS 'Permanently erases an organization''s CRM data and history once its closure window is due or an early manual delete is confirmed. Returns the member Auth user ids and the org''s opaque Brevo provider resources for the caller to clean up from those separate HTTP-only systems afterward, and parks both durably on the receipt (pending_auth_user_ids, pending_provider_resources) so a later crash can still find and retry them. The receipt is completed only once both external legs finish.';



CREATE OR REPLACE FUNCTION "public"."apply_stripe_checkout_event"("target_organization_id" "uuid", "stripe_event_id" "text", "stripe_event_type" "text", "target_checkout_id" "uuid", "target_checkout_session_id" "text", "session_payment_status" "text", "session_amount_total" bigint, "session_currency" "text", "new_payment_intent_id" "text", "new_method" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  checkout public.payment_stripe_checkouts;
  invoice_row public.invoices;
  quote_row public.quotes;
  receipt public.client_payment_events;
  deposit_event public.quote_deposit_events;
  deposit_already_satisfied boolean;
  remaining bigint;
  applied bigint;
  result_outcome text;
  note text;
  receipt_email boolean;
  target_label text;
begin
  insert into public.payment_stripe_webhook_events (organization_id, stripe_event_id, event_type, outcome)
  values (target_organization_id, stripe_event_id, stripe_event_type, 'pending')
  on conflict do nothing;
  if not found then
    return jsonb_build_object('outcome', 'duplicate');
  end if;

  select * into checkout
  from public.payment_stripe_checkouts
  where organization_id = target_organization_id
    and (checkout_session_id = target_checkout_session_id
      or (id = target_checkout_id and checkout_session_id is null))
  for update;

  -- The session id is stored just after Stripe creates it; a confirmation that beats that write still finds
  -- its row through client_reference_id and fills the id in.
  if checkout.id is not null and checkout.checkout_session_id is null then
    update public.payment_stripe_checkouts set checkout_session_id = target_checkout_session_id
    where id = checkout.id;
  end if;

  target_label := case when checkout.kind = 'invoice' then 'invoice' else 'quote deposit' end;

  if checkout.id is null then
    result_outcome := 'unknown_session';
  elsif checkout.status = 'paid' then
    result_outcome := 'already_paid';
  elsif stripe_event_type = 'checkout.session.async_payment_failed' then
    update public.payment_stripe_checkouts set status = 'failed', updated_at = now() where id = checkout.id;
    if checkout.kind = 'invoice' then
      select * into invoice_row from public.invoices where id = checkout.invoice_id;
      perform private.create_payment_alerts(
        target_organization_id, 'invoice.online_payment_failed', 'invoice', checkout.invoice_id,
        'invoices.record_payment', 'invoices.view_price', 'stripe:' || checkout.id || ':failed',
        'Online payment failed on invoice #' || invoice_row.invoice_number,
        'The customer''s bank payment of ' || private.format_minor(checkout.amount_minor, checkout.currency_code)
          || ' did not go through. The invoice is still owed.'
      );
    else
      select * into quote_row from public.quotes where id = checkout.quote_id;
      perform private.create_payment_alerts(
        target_organization_id, 'quote.deposit_payment_failed', 'quote', checkout.quote_id,
        'quotes.record_deposit', 'quotes.view_price', 'stripe:' || checkout.id || ':failed',
        'Online deposit payment failed on quote #' || quote_row.quote_number,
        'The customer''s bank payment of ' || private.format_minor(checkout.amount_minor, checkout.currency_code)
          || ' did not go through. The deposit is still owed.'
      );
    end if;
    result_outcome := 'failed';
  elsif stripe_event_type = 'checkout.session.completed' and session_payment_status = 'unpaid' then
    -- A bank payment: the customer finished, the bank has not. Nothing is recorded until it clears.
    update public.payment_stripe_checkouts
    set status = 'processing', payment_intent_id = coalesce(new_payment_intent_id, payment_intent_id),
        updated_at = now()
    where id = checkout.id;
    result_outcome := 'processing';
  elsif (stripe_event_type = 'checkout.session.completed' and session_payment_status = 'paid')
     or stripe_event_type = 'checkout.session.async_payment_succeeded' then
    if session_amount_total is distinct from checkout.amount_minor + checkout.tip_minor
       or upper(session_currency) is distinct from checkout.currency_code then
      -- Stripe charged something other than what UCRM asked for. Record nothing; a person has to look.
      result_outcome := 'amount_mismatch';
      perform private.create_payment_alerts(
        target_organization_id,
        case when checkout.kind = 'invoice' then 'invoice.online_overpayment' else 'quote.deposit_overpaid' end,
        case when checkout.kind = 'invoice' then 'invoice' else 'quote' end,
        coalesce(checkout.invoice_id, checkout.quote_id),
        case when checkout.kind = 'invoice' then 'invoices.record_payment' else 'quotes.record_deposit' end,
        case when checkout.kind = 'invoice' then 'invoices.view_price' else 'quotes.view_price' end,
        'stripe:' || checkout.id || ':mismatch',
        'Check an online payment in Stripe',
        'Stripe reported a payment that does not match what the ' || target_label
          || ' asked for, so it was not recorded. Compare it in your Stripe dashboard.'
      );
    elsif checkout.kind = 'invoice' then
      -- The currency lock reads the ledger, so settings are held first, exactly as a recorded payment does.
      perform 1 from public.organization_settings where organization_id = target_organization_id for share;

      select * into invoice_row
      from public.invoices
      where organization_id = target_organization_id and id = checkout.invoice_id
      for update;

      note := 'Paid online through Stripe.';
      if checkout.tip_minor > 0 then
        note := note || ' Includes a tip of ' || private.format_minor(checkout.tip_minor, checkout.currency_code)
          || ', not applied to the invoice.';
      end if;

      insert into public.client_payment_events (
        organization_id, client_id, event_type, amount_minor, currency_code, method, payment_date,
        reference, note, actor_user_id
      ) values (
        target_organization_id, checkout.client_id, 'received', checkout.amount_minor, checkout.currency_code,
        coalesce(new_method, 'stripe_other'), private.organization_today(target_organization_id),
        coalesce(new_payment_intent_id, checkout.payment_intent_id), note, null
      )
      returning * into receipt;

      -- Only what the bill still owes. A voided or written-off bill, or one someone paid in cash meanwhile,
      -- takes nothing more; the rest stays as the client's credit until the contractor refunds it.
      if invoice_row.voided_at is null and invoice_row.is_effective_receivable
         and invoice_row.written_off_at is null and invoice_row.currency_code = checkout.currency_code then
        remaining := invoice_row.total_minor
          - private.invoice_allocated_minor(target_organization_id, invoice_row.id);
      else
        remaining := 0;
      end if;
      applied := least(checkout.amount_minor, greatest(remaining, 0));

      if applied > 0 then
        perform private.apply_invoice_allocation(
          invoice_row, receipt.id, null, applied, null, 'Paid online through Stripe'
        );
      end if;

      update public.payment_stripe_checkouts
      set status = 'paid', payment_event_id = receipt.id, applied_minor = applied,
          payment_intent_id = coalesce(new_payment_intent_id, payment_intent_id),
          completed_at = now(), updated_at = now()
      where id = checkout.id;

      perform private.create_payment_alerts(
        target_organization_id, 'invoice.paid_online', 'invoice', checkout.invoice_id,
        'invoices.record_payment', 'invoices.view_price', 'stripe:' || checkout.id || ':paid',
        'Invoice #' || invoice_row.invoice_number || ' paid online',
        private.format_minor(checkout.amount_minor, checkout.currency_code) || ' received through Stripe'
          || case when checkout.tip_minor > 0
               then ' plus a ' || private.format_minor(checkout.tip_minor, checkout.currency_code) || ' tip.'
               else '.' end
      );

      if applied < checkout.amount_minor then
        perform private.create_payment_alerts(
          target_organization_id, 'invoice.online_overpayment', 'invoice', checkout.invoice_id,
          'invoices.record_payment', 'invoices.view_price', 'stripe:' || checkout.id || ':overpaid',
          'Refund needed on invoice #' || invoice_row.invoice_number,
          private.format_minor(checkout.amount_minor - applied, checkout.currency_code)
            || ' more than the invoice owed was paid online. It is held as client credit; refund it in Stripe '
            || 'if the customer should get it back.'
        );
      end if;

      select online_receipt_email_enabled into receipt_email
      from public.organization_settings where organization_id = target_organization_id;
      result_outcome := 'paid';
    else
      -- A quote deposit. A deposit is recorded in full or not at all, and only once per version (see
      -- record_quote_deposit_event); Stripe's confirmation follows the exact same rule.
      select * into quote_row from public.quotes where id = checkout.quote_id for update;

      deposit_already_satisfied := exists (
        select 1 from public.quote_deposit_events received
        where received.organization_id = target_organization_id
          and received.quote_id = checkout.quote_id
          and received.quote_version_id = checkout.quote_version_id
          and received.event_type = 'received'
          and not exists (
            select 1 from public.quote_deposit_events reversal
            where reversal.organization_id = received.organization_id
              and reversal.reversed_event_id = received.id
          )
      );

      if deposit_already_satisfied then
        -- Recorded some other way (cash, or a second tab) while this one was open. The checkout row is left
        -- as it was; the money still needs a human to look at it, so it is never silently swallowed.
        result_outcome := 'already_recorded_elsewhere';
        perform private.create_payment_alerts(
          target_organization_id, 'quote.deposit_overpaid', 'quote', checkout.quote_id,
          'quotes.record_deposit', 'quotes.view_price', 'stripe:' || checkout.id || ':already_recorded',
          'Refund needed on quote #' || quote_row.quote_number,
          'A deposit payment of ' || private.format_minor(checkout.amount_minor, checkout.currency_code)
            || ' came in through Stripe, but this quote''s deposit was already recorded another way. '
            || 'Refund it in Stripe if the customer should get it back.'
        );
      else
        insert into public.quote_deposit_events (
          organization_id, quote_id, quote_version_id, event_type, amount_minor, method, reference, note,
          actor_user_id, idempotency_key
        ) values (
          target_organization_id, checkout.quote_id, checkout.quote_version_id, 'received', checkout.amount_minor,
          coalesce(new_method, 'stripe_other'), coalesce(new_payment_intent_id, checkout.payment_intent_id),
          'Paid online through Stripe.', null, 'stripe:' || checkout.id
        )
        returning * into deposit_event;

        update public.payment_stripe_checkouts
        set status = 'paid', quote_deposit_event_id = deposit_event.id, applied_minor = checkout.amount_minor,
            payment_intent_id = coalesce(new_payment_intent_id, payment_intent_id),
            completed_at = now(), updated_at = now()
        where id = checkout.id;

        perform private.create_payment_alerts(
          target_organization_id, 'quote.deposit_paid_online', 'quote', checkout.quote_id,
          'quotes.record_deposit', 'quotes.view_price', 'stripe:' || checkout.id || ':paid',
          'Deposit paid online on quote #' || quote_row.quote_number,
          private.format_minor(checkout.amount_minor, checkout.currency_code) || ' received through Stripe.'
        );
      end if;

      result_outcome := coalesce(result_outcome, 'paid');
    end if;
  else
    result_outcome := 'ignored';
  end if;

  update public.payment_stripe_webhook_events set outcome = result_outcome
  where organization_id = target_organization_id
    and payment_stripe_webhook_events.stripe_event_id = apply_stripe_checkout_event.stripe_event_id;

  return jsonb_build_object(
    'outcome', result_outcome,
    'invoice_id', checkout.invoice_id,
    'payment_event_id', receipt.id,
    'send_receipt', result_outcome = 'paid' and checkout.kind = 'invoice' and coalesce(receipt_email, false)
  );
end;
$$;


ALTER FUNCTION "public"."apply_stripe_checkout_event"("target_organization_id" "uuid", "stripe_event_id" "text", "stripe_event_type" "text", "target_checkout_id" "uuid", "target_checkout_session_id" "text", "session_payment_status" "text", "session_amount_total" bigint, "session_currency" "text", "new_payment_intent_id" "text", "new_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_stripe_dispute_event"("target_organization_id" "uuid", "stripe_event_id" "text", "stripe_event_type" "text", "target_payment_intent_id" "text", "dispute_amount_minor" bigint, "dispute_currency" "text", "dispute_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  checkout public.payment_stripe_checkouts;
  invoice_row public.invoices;
  quote_row public.quotes;
  result_outcome text;
  reason_note text;
begin
  insert into public.payment_stripe_webhook_events (organization_id, stripe_event_id, event_type, outcome)
  values (target_organization_id, stripe_event_id, stripe_event_type, 'pending')
  on conflict do nothing;
  if not found then
    return jsonb_build_object('outcome', 'duplicate');
  end if;

  select * into checkout
  from public.payment_stripe_checkouts
  where organization_id = target_organization_id
    and payment_intent_id = target_payment_intent_id
    and status = 'paid';

  reason_note := case when dispute_reason is not null then ' (reason: ' || dispute_reason || ')' else '' end;

  if checkout.id is null then
    result_outcome := 'unknown_payment';
  elsif checkout.kind = 'invoice' then
    select * into invoice_row from public.invoices where id = checkout.invoice_id;
    perform private.create_payment_alerts(
      target_organization_id, 'invoice.payment_disputed', 'invoice', checkout.invoice_id,
      'invoices.record_payment', 'invoices.view_price', 'stripe:dispute:' || stripe_event_id,
      'A customer disputed a payment on invoice #' || invoice_row.invoice_number,
      private.format_minor(dispute_amount_minor, dispute_currency) || ' is disputed with their bank' ||
        reason_note || '. Respond in your Stripe dashboard -- UCRM cannot resolve a dispute itself.'
    );
    result_outcome := 'alerted';
  else
    select * into quote_row from public.quotes where id = checkout.quote_id;
    perform private.create_payment_alerts(
      target_organization_id, 'quote.deposit_disputed', 'quote', checkout.quote_id,
      'quotes.record_deposit', 'quotes.view_price', 'stripe:dispute:' || stripe_event_id,
      'A customer disputed a deposit on quote #' || quote_row.quote_number,
      private.format_minor(dispute_amount_minor, dispute_currency) || ' is disputed with their bank' ||
        reason_note || '. Respond in your Stripe dashboard -- UCRM cannot resolve a dispute itself.'
    );
    result_outcome := 'alerted';
  end if;

  update public.payment_stripe_webhook_events set outcome = result_outcome
  where organization_id = target_organization_id
    and payment_stripe_webhook_events.stripe_event_id = apply_stripe_dispute_event.stripe_event_id;

  return jsonb_build_object('outcome', result_outcome);
end;
$$;


ALTER FUNCTION "public"."apply_stripe_dispute_event"("target_organization_id" "uuid", "stripe_event_id" "text", "stripe_event_type" "text", "target_payment_intent_id" "text", "dispute_amount_minor" bigint, "dispute_currency" "text", "dispute_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_stripe_dispute_event"("target_organization_id" "uuid", "stripe_event_id" "text", "stripe_event_type" "text", "target_payment_intent_id" "text", "dispute_amount_minor" bigint, "dispute_currency" "text", "dispute_reason" "text") IS 'Alerts the contractor that a Stripe payment was disputed. Writes no ledger row -- docs/online-payments-behavior-contract.md is explicit that UCRM never tries to resolve a dispute itself. Service role only.';



CREATE OR REPLACE FUNCTION "public"."apply_stripe_refund_event"("target_organization_id" "uuid", "stripe_event_id" "text", "stripe_event_type" "text", "target_stripe_refund_id" "text", "target_payment_intent_id" "text", "refund_status" "text", "refund_amount_minor" bigint, "refund_currency" "text", "refund_failure_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  refund public.payment_stripe_refunds;
  checkout public.payment_stripe_checkouts;
  original_receipt public.client_payment_events;
  original_deposit public.quote_deposit_events;
  ledger_event_id uuid;
  result_outcome text;
  refund_note text;
  invoice_row public.invoices;
  quote_row public.quotes;
begin
  insert into public.payment_stripe_webhook_events (organization_id, stripe_event_id, event_type, outcome)
  values (target_organization_id, stripe_event_id, stripe_event_type, 'pending')
  on conflict do nothing;
  if not found then
    return jsonb_build_object('outcome', 'duplicate');
  end if;

  select * into refund
  from public.payment_stripe_refunds
  where organization_id = target_organization_id and stripe_refund_id = target_stripe_refund_id
  for update;

  if refund.id is null then
    -- First sight of this refund. Either the dashboard made it (no reservation exists), or this webhook beat
    -- the reservation's own stripe_refund_id write -- both are found the same way, by the payment it refunds.
    select * into checkout
    from public.payment_stripe_checkouts
    where organization_id = target_organization_id
      and payment_intent_id = target_payment_intent_id
      and status = 'paid';

    if checkout.id is null then
      result_outcome := 'unknown_payment';
      update public.payment_stripe_webhook_events set outcome = result_outcome
        where organization_id = target_organization_id
          and payment_stripe_webhook_events.stripe_event_id = apply_stripe_refund_event.stripe_event_id;
      return jsonb_build_object('outcome', result_outcome);
    end if;

    insert into public.payment_stripe_refunds (
      organization_id, checkout_id, stripe_refund_id, amount_minor, currency_code, status
    ) values (
      target_organization_id, checkout.id, target_stripe_refund_id, refund_amount_minor,
      refund_currency, 'pending'
    )
    returning * into refund;
  else
    select * into checkout
    from public.payment_stripe_checkouts
    where organization_id = target_organization_id and id = refund.checkout_id;
  end if;

  if refund.status in ('succeeded', 'failed') then
    -- Already the last word. Stripe does not regress a refund's status, but a redelivered or racing event
    -- must never be told twice.
    result_outcome := 'already_' || refund.status;
  elsif refund_status = 'failed' then
    update public.payment_stripe_refunds
    set status = 'failed', failure_message = left(refund_failure_message, 300), updated_at = now(),
        completed_at = now()
    where id = refund.id;

    if checkout.kind = 'invoice' then
      select * into invoice_row from public.invoices where id = checkout.invoice_id;
      perform private.create_payment_alerts(
        target_organization_id, 'invoice.online_refund_failed', 'invoice', checkout.invoice_id,
        'invoices.record_payment', 'invoices.view_price', 'stripe:refund:' || refund.id || ':failed',
        'A Stripe refund failed on invoice #' || invoice_row.invoice_number,
        coalesce(refund_failure_message, 'Stripe could not send this refund.')
          || ' Check it in your Stripe dashboard.'
      );
    else
      select * into quote_row from public.quotes where id = checkout.quote_id;
      perform private.create_payment_alerts(
        target_organization_id, 'quote.deposit_refund_failed', 'quote', checkout.quote_id,
        'quotes.record_deposit', 'quotes.view_price', 'stripe:refund:' || refund.id || ':failed',
        'A Stripe refund failed on quote #' || quote_row.quote_number,
        coalesce(refund_failure_message, 'Stripe could not send this refund.')
          || ' Check it in your Stripe dashboard.'
      );
    end if;
    result_outcome := 'failed';
  elsif refund_status = 'succeeded' then
    refund_note := case when refund.requested_by is not null
      then 'Refunded through Stripe from UCRM.' else 'Refunded through Stripe (seen in your Stripe dashboard).' end;

    if checkout.kind = 'invoice' then
      select * into original_receipt
      from public.client_payment_events
      where organization_id = target_organization_id and id = checkout.payment_event_id
      for update;

      insert into public.client_payment_events (
        organization_id, client_id, event_type, amount_minor, currency_code, method, payment_date,
        reference, note, actor_user_id, original_event_id
      ) values (
        target_organization_id, checkout.client_id, 'refunded', refund_amount_minor,
        original_receipt.currency_code, original_receipt.method,
        private.organization_today(target_organization_id), target_stripe_refund_id, refund_note,
        refund.requested_by, original_receipt.id
      )
      returning id into ledger_event_id;
    else
      select * into original_deposit
      from public.quote_deposit_events
      where organization_id = target_organization_id and id = checkout.quote_deposit_event_id
      for update;

      insert into public.client_payment_events (
        organization_id, client_id, event_type, amount_minor, currency_code, method, payment_date,
        reference, note, actor_user_id, original_deposit_event_id
      ) values (
        target_organization_id, checkout.client_id, 'refunded', refund_amount_minor,
        checkout.currency_code, original_deposit.method,
        private.organization_today(target_organization_id), target_stripe_refund_id, refund_note,
        refund.requested_by, original_deposit.id
      )
      returning id into ledger_event_id;
    end if;

    update public.payment_stripe_refunds
    set status = 'succeeded', refund_event_id = ledger_event_id, completed_at = now(), updated_at = now()
    where id = refund.id;
    result_outcome := 'succeeded';
  else
    result_outcome := 'pending';
  end if;

  update public.payment_stripe_webhook_events set outcome = result_outcome
  where organization_id = target_organization_id
    and payment_stripe_webhook_events.stripe_event_id = apply_stripe_refund_event.stripe_event_id;

  return jsonb_build_object('outcome', result_outcome, 'refund_id', refund.id);
end;
$$;


ALTER FUNCTION "public"."apply_stripe_refund_event"("target_organization_id" "uuid", "stripe_event_id" "text", "stripe_event_type" "text", "target_stripe_refund_id" "text", "target_payment_intent_id" "text", "refund_status" "text", "refund_amount_minor" bigint, "refund_currency" "text", "refund_failure_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_stripe_refund_event"("target_organization_id" "uuid", "stripe_event_id" "text", "stripe_event_type" "text", "target_stripe_refund_id" "text", "target_payment_intent_id" "text", "refund_status" "text", "refund_amount_minor" bigint, "refund_currency" "text", "refund_failure_message" "text") IS 'Records a client_payment_events refund exactly once per Stripe refund id, whichever of the webhook or the synchronous refunds.create() response tells it first. Service role only.';



CREATE OR REPLACE FUNCTION "public"."apply_visit_to_future"("target_organization_id" "uuid", "target_job_id" "uuid", "source_visit_id" "uuid", "copy_time_of_day" boolean, "copy_assigned_team" boolean, "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  source_visit public.job_visits;
  receipt_id uuid;
  existing_receipt public.job_command_receipts;
  target_ids uuid[];
  updated_count integer;
  final_result jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to schedule a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.schedule') then
    raise exception 'You do not have access to schedule this job.' using errcode = 'insufficient_privilege';
  end if;

  if not coalesce(copy_time_of_day, false) and not coalesce(copy_assigned_team, false) then
    raise exception 'Choose at least one setting to apply to the later visits.'
      using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(new_idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(new_request_hash, ''))) < 1 then
    raise exception 'A request fingerprint is required.' using errcode = 'check_violation';
  end if;

  select visit.* into source_visit
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.id = source_visit_id;
  if not found then
    raise exception 'That visit could not be found.' using errcode = 'P0404';
  end if;
  if source_visit.visit_date is null then
    raise exception 'Give this visit a date before applying it to later visits.'
      using errcode = 'check_violation';
  end if;

  insert into public.job_command_receipts (organization_id, action, idempotency_key, request_hash)
  values (target_organization_id, 'apply_visit_to_future', new_idempotency_key, new_request_hash)
  on conflict (organization_id, action, idempotency_key) do nothing
  returning id into receipt_id;

  if receipt_id is null then
    select receipt.* into existing_receipt
    from public.job_command_receipts as receipt
    where receipt.organization_id = target_organization_id
      and receipt.action = 'apply_visit_to_future'
      and receipt.idempotency_key = new_idempotency_key;

    if existing_receipt.request_hash is distinct from new_request_hash then
      raise exception 'These settings were already applied differently.' using errcode = 'P0409';
    end if;

    return coalesce(existing_receipt.result, '{}'::jsonb) || jsonb_build_object('applied', false);
  end if;

  select coalesce(array_agg(visit.id order by visit.visit_date, visit.position), array[]::uuid[])
  into target_ids
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.id <> source_visit_id
    and visit.completed_at is null
    and visit.visit_date is not null
    and visit.visit_date > source_visit.visit_date;

  updated_count := coalesce(array_length(target_ids, 1), 0);

  if updated_count > 0 then
    if coalesce(copy_time_of_day, false) then
      update public.job_visits
      set start_time = source_visit.start_time,
          end_time = source_visit.end_time,
          all_day = source_visit.all_day,
          revision = revision + 1,
          updated_at = now()
      where organization_id = target_organization_id
        and id = any(target_ids);
    end if;

    if coalesce(copy_assigned_team, false) then
      delete from public.job_visit_assignments
      where organization_id = target_organization_id
        and visit_id = any(target_ids);

      insert into public.job_visit_assignments (organization_id, visit_id, user_id)
      select target_organization_id, target_visit, assignment.user_id
      from unnest(target_ids) as target_visit
      cross join public.job_visit_assignments as assignment
      where assignment.organization_id = target_organization_id
        and assignment.visit_id = source_visit_id
      on conflict do nothing;

      if not coalesce(copy_time_of_day, false) then
        update public.job_visits
        set revision = revision + 1,
            updated_at = now()
        where organization_id = target_organization_id
          and id = any(target_ids);
      end if;
    end if;
  end if;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, related_visit_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'visits_updated_forward',
    caller,
    source_visit_id,
    jsonb_build_object(
      'count', updated_count,
      'time_of_day', coalesce(copy_time_of_day, false),
      'assigned_team', coalesce(copy_assigned_team, false)
    )
  );

  final_result := jsonb_build_object('applied', true, 'updated_count', updated_count);
  update public.job_command_receipts set result = final_result where id = receipt_id;
  return final_result;
end;
$$;


ALTER FUNCTION "public"."apply_visit_to_future"("target_organization_id" "uuid", "target_job_id" "uuid", "source_visit_id" "uuid", "copy_time_of_day" boolean, "copy_assigned_team" boolean, "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_visit_to_future"("target_organization_id" "uuid", "target_job_id" "uuid", "source_visit_id" "uuid", "copy_time_of_day" boolean, "copy_assigned_team" boolean, "new_idempotency_key" "text", "new_request_hash" "text") IS 'Copies one visit''s time of day and/or assigned crew onto the same job''s later dated, incomplete visits. Checks jobs.schedule, skips completed and undated visits, is idempotent by key, and appends a visits_updated_forward history row with the count.';



CREATE OR REPLACE FUNCTION "public"."archive_form"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  form_row public.forms;
begin
  if not private.has_permission(target_organization_id, 'settings.forms.manage') then
    raise exception 'You do not have access to manage forms.' using errcode = 'insufficient_privilege';
  end if;

  select * into form_row from public.forms
  where id = target_form_id and organization_id = target_organization_id
  for update;

  if form_row.id is null then
    raise exception 'That form was not found.' using errcode = 'check_violation';
  end if;
  if expected_revision is distinct from form_row.revision then
    raise exception 'Someone else changed this form while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;
  if form_row.archived_at is not null then
    return jsonb_build_object('form_id', form_row.id, 'archived', true, 'revision', form_row.revision);
  end if;

  update public.forms
  set archived_at = now(), is_default = false, is_enabled = false,
      revision = revision + 1, updated_by = (select auth.uid()), updated_at = now()
  where id = form_row.id
  returning * into form_row;

  return jsonb_build_object('form_id', form_row.id, 'archived', true, 'revision', form_row.revision);
end;
$$;


ALTER FUNCTION "public"."archive_form"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_quote"("target_quote_id" "uuid", "reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  clean_reason text;
begin
  clean_reason := nullif(trim(coalesce(reason, '')), '');

  select * into quote_row from public.quotes where id = target_quote_id for update;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.edit'
     ) then
    raise exception 'You do not have access to archive this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.status = 'archived' then
    return jsonb_build_object('applied', false, 'status', quote_row.status);
  end if;

  if quote_row.status = 'converted' then
    raise exception 'A converted quote cannot be archived.' using errcode = 'check_violation';
  end if;

  if quote_row.status = 'approved' and clean_reason is null then
    raise exception 'Give a reason for archiving an approved quote.' using errcode = 'check_violation';
  end if;

  update public.quotes
  set previous_status = quote_row.status,
      status = 'archived',
      archived_at = now(),
      archive_reason = clean_reason
  where id = quote_row.id;

  return jsonb_build_object('applied', true, 'status', 'archived');
end;
$$;


ALTER FUNCTION "public"."archive_quote"("target_quote_id" "uuid", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_job_checklist"("target_organization_id" "uuid", "target_job_id" "uuid", "target_template_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  source_template public.checklist_templates;
  new_checklist public.job_checklists;
  copied integer;
begin
  if caller is null then
    raise exception 'You must be signed in to attach a checklist.' using errcode = 'insufficient_privilege';
  end if;
  if not private.can_view_job(target_organization_id, target_job_id)
    or not private.member_has_permission(target_organization_id, caller, 'jobs.edit') then
    raise exception 'You do not have access to change this job.' using errcode = 'insufficient_privilege';
  end if;

  if not exists (
    select 1 from public.jobs
    where organization_id = target_organization_id and id = target_job_id and status = 'active'
  ) then
    raise exception 'A closed job cannot take a new checklist.' using errcode = 'P0410';
  end if;

  select library.* into source_template
  from public.checklist_templates as library
  where library.organization_id = target_organization_id and library.id = target_template_id;
  if not found then
    raise exception 'That checklist could not be found.' using errcode = 'P0404';
  end if;
  if source_template.archived_at is not null then
    raise exception 'That checklist is archived.' using errcode = 'P0400';
  end if;

  if exists (
    select 1 from public.job_checklists
    where organization_id = target_organization_id
      and job_id = target_job_id
      and source_template_id = target_template_id
  ) then
    raise exception 'That checklist is already on this job.' using errcode = 'P0409';
  end if;

  insert into public.job_checklists (organization_id, job_id, source_template_id, name, attached_by)
  values (target_organization_id, target_job_id, target_template_id, source_template.name, caller)
  returning * into new_checklist;

  insert into public.job_checklist_items (
    organization_id, job_id, job_checklist_id, position, label, item_type, required, options
  )
  select
    target_organization_id, target_job_id, new_checklist.id,
    item.position, item.label, item.item_type, item.required, item.options
  from public.checklist_template_items as item
  where item.organization_id = target_organization_id and item.template_id = target_template_id;

  get diagnostics copied = row_count;
  if copied = 0 then
    raise exception 'That checklist has no questions on it yet.' using errcode = 'P0400';
  end if;

  return jsonb_build_object('id', new_checklist.id, 'question_count', copied);
end;
$$;


ALTER FUNCTION "public"."attach_job_checklist"("target_organization_id" "uuid", "target_job_id" "uuid", "target_template_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attach_job_checklist"("target_organization_id" "uuid", "target_job_id" "uuid", "target_template_id" "uuid") IS 'Copies a template''s questions onto a job. Needs jobs.edit. The copy is what every visit answers.';



CREATE OR REPLACE FUNCTION "public"."attach_team_invitation_identity"("target_invitation_id" "uuid", "target_invited_user_id" "uuid", "target_attempt_nonce" "uuid", "target_token_hash" "text", "target_expires_at" timestamp with time zone) RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_row public.organization_member_invitations;
begin
  update public.organization_member_invitations
  set state = 'invited',
      invited_user_id = target_invited_user_id,
      token_hash = target_token_hash,
      expires_at = target_expires_at
  where id = target_invitation_id
    and state = 'reserving'
    and auth_attempt_nonce = target_attempt_nonce
  returning * into updated_row;

  if not found then
    raise exception 'Invitation % cannot attach that Auth identity.', target_invitation_id
      using errcode = 'check_violation';
  end if;

  insert into public.organization_members (organization_id, user_id, role, status)
  values (updated_row.organization_id, target_invited_user_id, updated_row.role, 'pending');

  insert into public.organization_member_permission_overrides (
    organization_id, user_id, permission_key, override_state, access_scope
  )
  select
    updated_row.organization_id,
    target_invited_user_id,
    entry.item ->> 'permission_key',
    entry.item ->> 'override_state',
    'all'
  from jsonb_array_elements(updated_row.requested_permission_overrides) as entry(item);

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_invitation_id, summary
  )
  values (
    updated_row.organization_id, 'invitation.sent', 'member', updated_row.invited_by, updated_row.id,
    jsonb_build_object('role', updated_row.role)
  );

  return updated_row;
end;
$$;


ALTER FUNCTION "public"."attach_team_invitation_identity"("target_invitation_id" "uuid", "target_invited_user_id" "uuid", "target_attempt_nonce" "uuid", "target_token_hash" "text", "target_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_active_enrollment_counts"("p_organization_id" "uuid", "p_recipe_ids" "uuid"[]) RETURNS TABLE("recipe_id" "uuid", "active_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select e.recipe_id, count(*)::bigint as active_count
  from private.automation_enrollments e
  where e.organization_id = p_organization_id
    and e.recipe_id = any (p_recipe_ids)
    and e.state = 'active'
  group by e.recipe_id;
$$;


ALTER FUNCTION "public"."automation_active_enrollment_counts"("p_organization_id" "uuid", "p_recipe_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."automation_active_enrollment_counts"("p_organization_id" "uuid", "p_recipe_ids" "uuid"[]) IS 'Safe projection: how many subjects are currently enrolled (state = active) in each of the given recipes. Reads private.automation_enrollments under a security-definer boundary; exposes only the bounded count.';



CREATE OR REPLACE FUNCTION "public"."automation_inquiry_enrollments"("p_organization_id" "uuid", "p_request_id" "uuid", "p_chat_session_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("enrollment_id" "uuid", "recipe_id" "uuid", "recipe_name" "text", "version_number" integer, "subject_type" "text", "state" "text", "source" "text", "current_step_index" integer, "next_due_at" timestamp with time zone, "customer_messages_sent" integer, "stop_reason" "text", "paused_reason" "text", "held_reason" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
  with subjects as (
    select 'form_submission'::text as subject_type, s.id as subject_id
    from private.form_submissions as s
    where p_request_id is not null
      and s.organization_id = p_organization_id
      and s.result ->> 'request_id' is not null
      and s.result ->> 'request_id' = p_request_id::text
    union all
    select 'website_chat_session', w.id
    from public.website_chat_sessions as w
    where p_chat_session_id is not null
      and w.organization_id = p_organization_id
      and w.id = p_chat_session_id
  )
  select
    e.id,
    e.recipe_id,
    r.name,
    v.version_number,
    e.subject_type,
    e.state,
    e.source,
    e.current_step_index,
    coalesce(e.paused_work_due_at, work.due_at),
    e.customer_messages_sent,
    e.stop_reason,
    e.paused_reason,
    coalesce(attention.attention_reason, work.last_error_code),
    e.created_at,
    e.updated_at
  from subjects
  join private.automation_enrollments as e
    on e.organization_id = p_organization_id
    and e.subject_type = subjects.subject_type
    and e.subject_id = subjects.subject_id
  join public.automation_recipes as r on r.id = e.recipe_id and r.organization_id = e.organization_id
  join public.automation_recipe_versions as v on v.id = e.recipe_version_id
  left join lateral (
    select w.due_at, w.last_error_code
    from private.automation_work_items as w
    where w.enrollment_id = e.id and w.state = 'pending'
    order by w.step_index
    limit 1
  ) as work on true
  left join lateral (
    select w.attention_reason
    from private.automation_work_items as w
    where w.enrollment_id = e.id and w.state = 'needs_attention'
    order by w.step_index desc
    limit 1
  ) as attention on true
  order by e.updated_at desc, e.id desc
  limit least(greatest(coalesce(p_limit, 20), 1), 50);
$$;


ALTER FUNCTION "public"."automation_inquiry_enrollments"("p_organization_id" "uuid", "p_request_id" "uuid", "p_chat_session_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."automation_inquiry_enrollments"("p_organization_id" "uuid", "p_request_id" "uuid", "p_chat_session_id" "uuid", "p_limit" integer) IS 'Safe follow-up summaries for the website inquiry behind a Request (its form submission) or a chat session: recipe/version/state/next step/messages sent/stop, pause and hold reasons. Service role only.';



CREATE OR REPLACE FUNCTION "public"."automation_recipe_history"("p_organization_id" "uuid", "p_recipe_id" "uuid", "p_before_happened_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("id" "uuid", "happened_at" timestamp with time zone, "outcome" "text", "detail" "text", "subject_type" "text", "subject_id" "uuid", "enrollment_state" "text", "customer_messages_sent" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select em.id, em.created_at as happened_at, em.outcome, em.detail, ev.subject_type, ev.subject_id,
         en.state as enrollment_state, en.customer_messages_sent
  from private.automation_event_matches em
  join private.automation_events ev on ev.id = em.event_id
  left join private.automation_enrollments en on en.id = em.enrollment_id
  where em.organization_id = p_organization_id and em.recipe_id = p_recipe_id
    and (p_before_happened_at is null or em.created_at < p_before_happened_at
      or (em.created_at = p_before_happened_at and em.id < p_before_id))
  order by em.created_at desc, em.id desc
  limit least(greatest(coalesce(p_limit, 25), 1), 50);
$$;


ALTER FUNCTION "public"."automation_recipe_history"("p_organization_id" "uuid", "p_recipe_id" "uuid", "p_before_happened_at" timestamp with time zone, "p_before_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."automation_recipe_history"("p_organization_id" "uuid", "p_recipe_id" "uuid", "p_before_happened_at" timestamp with time zone, "p_before_id" "uuid", "p_limit" integer) IS 'Safe projection: one recipe''s history, newest first, keyset-paginated. Each row is one (event, recipe) decision -- enrolled, or the plain reason it was not. Reads private engine tables under a security-definer boundary and exposes summaries only: never the enrollment context snapshot, event payload, message body, or any worker/lease state (docs/automation-behavior-contract.md § Query, index, and count).';



CREATE OR REPLACE FUNCTION "public"."automation_record_enrollments"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("enrollment_id" "uuid", "recipe_id" "uuid", "recipe_name" "text", "version_number" integer, "state" "text", "source" "text", "current_step_index" integer, "next_due_at" timestamp with time zone, "customer_messages_sent" integer, "stop_reason" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
  select
    e.id,
    e.recipe_id,
    r.name,
    v.version_number,
    e.state,
    e.source,
    e.current_step_index,
    coalesce(
      e.paused_work_due_at,
      (select w.due_at
       from private.automation_work_items w
       where w.enrollment_id = e.id and w.state = 'pending'
       order by w.step_index
       limit 1)
    ) as next_due_at,
    e.customer_messages_sent,
    e.stop_reason,
    e.created_at,
    e.updated_at
  from private.automation_enrollments e
  join public.automation_recipes r
    on r.id = e.recipe_id and r.organization_id = e.organization_id
  join public.automation_recipe_versions v
    on v.id = e.recipe_version_id
  where e.organization_id = p_organization_id
    and e.subject_type = p_subject_type
    and e.subject_id = p_subject_id
  order by e.updated_at desc, e.id desc
  limit least(coalesce(p_limit, 20), 50);
$$;


ALTER FUNCTION "public"."automation_record_enrollments"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."automation_record_enrollments"("p_organization_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_limit" integer) IS 'Safe per-record enrollment summaries (recipe/version/state/next-step/messages/source) for the Quote detail controls. Never exposes context, payload, or worker/lease state. Service role only.';



CREATE OR REPLACE FUNCTION "public"."begin_communication_email_domain_removal"("target_organization_id" "uuid", "target_domain_id" "uuid", "expected_live_sender_count" integer, "expected_live_replacement_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_domain public.communication_email_domains;
  actual_live_sender_count integer;
  actual_live_replacement_count integer;
begin
  if expected_live_sender_count < 0 or expected_live_replacement_count < 0 then
    raise exception 'Expected removal impact cannot be negative.' using errcode = 'check_violation';
  end if;

  select * into target_domain
  from public.communication_email_domains
  where organization_id = target_organization_id
    and id = target_domain_id
    and purpose = 'sending'
    and lifecycle_state <> 'removed'
  for update;

  if not found then
    return jsonb_build_object('status', 'not_found');
  end if;

  select count(*)::integer into actual_live_sender_count
  from public.communication_email_senders
  where organization_id = target_organization_id
    and domain_id = target_domain_id
    and lifecycle_state <> 'removed';

  select count(*)::integer into actual_live_replacement_count
  from public.communication_email_domains
  where organization_id = target_organization_id
    and replacement_of_domain_id = target_domain_id
    and lifecycle_state <> 'removed';

  if actual_live_sender_count <> expected_live_sender_count
    or actual_live_replacement_count <> expected_live_replacement_count then
    return jsonb_build_object(
      'status', 'impact_changed',
      'live_sender_count', actual_live_sender_count,
      'live_replacement_count', actual_live_replacement_count
    );
  end if;

  if actual_live_sender_count > 0 or actual_live_replacement_count > 0 then
    return jsonb_build_object(
      'status', 'blocked',
      'live_sender_count', actual_live_sender_count,
      'live_replacement_count', actual_live_replacement_count
    );
  end if;

  update public.communication_email_domains
  set lifecycle_state = 'removal_pending', provider_cleanup_error = null, updated_at = now()
  where organization_id = target_organization_id and id = target_domain_id;

  return jsonb_build_object(
    'status', 'started',
    'domain_name', target_domain.domain_name,
    'previous_lifecycle_state', target_domain.lifecycle_state,
    'live_sender_count', actual_live_sender_count,
    'live_replacement_count', actual_live_replacement_count
  );
end;
$$;


ALTER FUNCTION "public"."begin_communication_email_domain_removal"("target_organization_id" "uuid", "target_domain_id" "uuid", "expected_live_sender_count" integer, "expected_live_replacement_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."begin_communication_email_domain_removal"("target_organization_id" "uuid", "target_domain_id" "uuid", "expected_live_sender_count" integer, "expected_live_replacement_count" integer) IS 'Atomically checks the confirmed impact and starts sending-domain removal. Provider cleanup stays outside the transaction.';



CREATE OR REPLACE FUNCTION "public"."begin_communication_email_sender_create"("target_organization_id" "uuid", "target_domain_id" "uuid", "target_email_address" "text", "target_display_name" "text", "target_assigned_user_id" "uuid", "target_is_organization_default" boolean, "target_allows_manual" boolean, "target_allows_automated" boolean, "actor_user_id" "uuid", "command_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  selected_domain public.communication_email_domains;
  selected_sender public.communication_email_senders;
  existing_event public.communication_email_authority_events;
  desired_state jsonb;
begin
  if command_idempotency_key is null or char_length(btrim(command_idempotency_key)) not between 1 and 180 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;

  target_email_address := lower(btrim(target_email_address));
  target_display_name := btrim(target_display_name);
  desired_state := jsonb_build_object(
    'domain_id', target_domain_id,
    'email_address', target_email_address,
    'display_name', target_display_name,
    'assigned_user_id', target_assigned_user_id,
    'is_organization_default', target_is_organization_default,
    'allows_manual', target_allows_manual,
    'allows_automated', target_allows_automated
  );

  select * into existing_event
  from public.communication_email_authority_events
  where organization_id = target_organization_id
    and idempotency_key = command_idempotency_key;

  if found then
    if existing_event.event_type <> 'sender.create.started'
      or existing_event.after_state is distinct from desired_state then
      raise exception 'The idempotency key was already used for another command.'
        using errcode = 'unique_violation';
    end if;

    select * into strict selected_sender
    from public.communication_email_senders
    where organization_id = target_organization_id and id = existing_event.target_id;

    return jsonb_build_object('replayed', true, 'sender', to_jsonb(selected_sender));
  end if;

  select * into selected_domain
  from public.communication_email_domains
  where organization_id = target_organization_id and id = target_domain_id
  for update;

  if not found or selected_domain.purpose <> 'sending'
    or selected_domain.lifecycle_state <> 'verified'
    or not selected_domain.provider_verified
    or not selected_domain.provider_authenticated
    or selected_domain.ownership_status <> 'passing'
    or selected_domain.dkim_status <> 'passing' then
    raise exception 'A verified healthy sending domain is required.' using errcode = 'check_violation';
  end if;

  if split_part(target_email_address, '@', 2) <> selected_domain.domain_name then
    raise exception 'The sender address must use the selected sending domain.' using errcode = 'check_violation';
  end if;

  if not target_allows_manual and not target_allows_automated then
    raise exception 'An enabled sender must allow manual or automated email.' using errcode = 'check_violation';
  end if;

  if target_assigned_user_id is not null and not exists (
    select 1 from public.organization_members
    where organization_id = target_organization_id
      and user_id = target_assigned_user_id and status = 'active'
  ) then
    raise exception 'The assigned sender member must be active.' using errcode = 'check_violation';
  end if;

  if target_is_organization_default then
    perform 1 from public.communication_email_senders
    where organization_id = target_organization_id
      and lifecycle_state = 'enabled' and is_organization_default
    for update;
  end if;

  insert into public.communication_email_senders (
    organization_id, domain_id, email_address, display_name, lifecycle_state,
    assigned_user_id, is_organization_default, allows_manual, allows_automated, created_by
  ) values (
    target_organization_id, target_domain_id, target_email_address, target_display_name,
    'pending_verification', target_assigned_user_id, target_is_organization_default,
    target_allows_manual, target_allows_automated, actor_user_id
  ) returning * into selected_sender;

  insert into public.communication_email_authority_events (
    organization_id, actor_kind, actor_user_id, event_type, target_type, target_id,
    after_state, idempotency_key
  ) values (
    target_organization_id, 'contractor_user', actor_user_id, 'sender.create.started',
    'sender', selected_sender.id, desired_state, command_idempotency_key
  );

  return jsonb_build_object('replayed', false, 'sender', to_jsonb(selected_sender));
end;
$$;


ALTER FUNCTION "public"."begin_communication_email_sender_create"("target_organization_id" "uuid", "target_domain_id" "uuid", "target_email_address" "text", "target_display_name" "text", "target_assigned_user_id" "uuid", "target_is_organization_default" boolean, "target_allows_manual" boolean, "target_allows_automated" boolean, "actor_user_id" "uuid", "command_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_communication_email_sender_update"("target_organization_id" "uuid", "target_sender_id" "uuid", "target_display_name" "text", "target_assigned_user_id" "uuid", "target_is_organization_default" boolean, "target_allows_manual" boolean, "target_allows_automated" boolean, "target_enabled" boolean, "actor_user_id" "uuid", "command_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  selected_sender public.communication_email_senders;
  selected_domain public.communication_email_domains;
  existing_event public.communication_email_authority_events;
  desired_state jsonb;
begin
  if command_idempotency_key is null or char_length(btrim(command_idempotency_key)) not between 1 and 180 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;

  target_display_name := btrim(target_display_name);
  desired_state := jsonb_build_object(
    'display_name', target_display_name,
    'assigned_user_id', target_assigned_user_id,
    'is_organization_default', target_is_organization_default,
    'allows_manual', target_allows_manual,
    'allows_automated', target_allows_automated,
    'enabled', target_enabled
  );

  select * into existing_event from public.communication_email_authority_events
  where organization_id = target_organization_id and idempotency_key = command_idempotency_key;
  if found then
    if existing_event.event_type <> 'sender.update.started'
      or existing_event.target_id <> target_sender_id
      or existing_event.after_state is distinct from desired_state then
      raise exception 'The idempotency key was already used for another command.'
        using errcode = 'unique_violation';
    end if;
    select * into strict selected_sender
    from public.communication_email_senders
    where organization_id = target_organization_id and id = target_sender_id;
    return jsonb_build_object('replayed', true, 'sender', to_jsonb(selected_sender));
  end if;

  select * into strict selected_sender from public.communication_email_senders
  where organization_id = target_organization_id and id = target_sender_id
  for update;

  if selected_sender.lifecycle_state in ('removal_pending', 'removed') then
    raise exception 'The sender can no longer be changed.' using errcode = 'check_violation';
  end if;

  if target_enabled then
    select * into strict selected_domain from public.communication_email_domains
    where organization_id = target_organization_id and id = selected_sender.domain_id
    for update;
    if selected_domain.lifecycle_state <> 'verified' or not selected_domain.provider_verified
      or not selected_domain.provider_authenticated or selected_domain.ownership_status <> 'passing'
      or selected_domain.dkim_status <> 'passing' then
      raise exception 'A verified healthy sending domain is required.' using errcode = 'check_violation';
    end if;
    if not target_allows_manual and not target_allows_automated then
      raise exception 'An enabled sender must allow manual or automated email.' using errcode = 'check_violation';
    end if;
    if target_assigned_user_id is not null and not exists (
      select 1 from public.organization_members
      where organization_id = target_organization_id
        and user_id = target_assigned_user_id and status = 'active'
    ) then
      raise exception 'The assigned sender member must be active.' using errcode = 'check_violation';
    end if;
  end if;

  insert into public.communication_email_authority_events (
    organization_id, actor_kind, actor_user_id, event_type, target_type, target_id,
    before_state, after_state, idempotency_key
  ) values (
    target_organization_id, 'contractor_user', actor_user_id, 'sender.update.started', 'sender',
    target_sender_id, to_jsonb(selected_sender), desired_state, command_idempotency_key
  );

  return jsonb_build_object('replayed', false, 'sender', to_jsonb(selected_sender));
end;
$$;


