CREATE OR REPLACE FUNCTION "public"."cancel_communication_conversation_reply"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_delivery_intent_id" "uuid") RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  intent public.communication_delivery_intents;
  outbox public.communication_outbox_events;
begin
  if not private.member_has_permission(target_organization_id, target_actor_user_id, 'conversations.send') then
    raise exception 'You do not have permission to cancel a scheduled message.' using errcode = 'insufficient_privilege';
  end if;

  select * into intent
  from public.communication_delivery_intents
  where organization_id = target_organization_id and id = target_delivery_intent_id
  for update;

  if intent.id is null then
    raise exception 'That scheduled message could not be found.' using errcode = 'no_data_found';
  end if;

  select * into outbox
  from public.communication_outbox_events
  where delivery_intent_id = intent.id
  for update;

  if outbox.id is null or outbox.status <> 'pending' or outbox.available_at <= now() then
    raise exception 'This message has already started sending and can no longer be cancelled.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  update public.communication_outbox_events
  set status = 'cancelled'
  where id = outbox.id;

  update public.communication_delivery_intents
  set status = 'cancelled'
  where id = intent.id
  returning * into intent;

  return intent;
end;
$$;


ALTER FUNCTION "public"."cancel_communication_conversation_reply"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_delivery_intent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_communication_message"("p_delivery_intent_id" "uuid", "p_reason" "text", "p_actor_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  outbox public.communication_outbox_events;
  intent public.communication_delivery_intents;
  clean_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  clean_actor text := nullif(btrim(coalesce(p_actor_email, '')), '');
begin
  if clean_actor is null then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if clean_reason is null or char_length(clean_reason) < 3 or char_length(clean_reason) > 1000 then
    raise exception 'A reason of 3 to 1000 characters is required.' using errcode = 'check_violation';
  end if;

  select * into outbox from public.communication_outbox_events
  where delivery_intent_id = p_delivery_intent_id for update;
  if outbox.id is null then
    raise exception 'That message was not found.' using errcode = 'no_data_found';
  end if;
  select * into intent from public.communication_delivery_intents
  where id = p_delivery_intent_id for update;

  if outbox.status = 'cancelled' then
    return jsonb_build_object('changed', false, 'delivery_intent_id', p_delivery_intent_id,
      'outbox_status', outbox.status);
  end if;
  if outbox.status = 'submitted' then
    raise exception 'That message was already accepted by the provider.'
      using errcode = 'check_violation';
  end if;
  if outbox.status = 'processing' then
    raise exception 'That message is being sent right now.' using errcode = 'check_violation';
  end if;

  update public.communication_outbox_events
  set status = 'cancelled', claimed_at = null, claim_token = null,
    last_error = 'Cancelled by the platform owner.'
  where id = outbox.id;

  update public.communication_delivery_intents
  set status = 'cancelled', provider_message_id = null, accepted_at = null,
    failure_code = 'cancelled_by_platform_owner',
    failure_message = 'Cancelled by the platform owner.'
  where id = intent.id;

  update public.communication_email_capacity_reservations
  set reservation_state = 'released', settled_at = now()
  where delivery_intent_id = intent.id
    and reservation_state in ('reserved', 'submission_unknown');

  perform private.record_communication_message_event(
    p_organization_id => intent.organization_id,
    p_delivery_intent_id => intent.id,
    p_event_kind => 'administrative_intervention',
    p_attempt_number => outbox.attempt_count,
    p_reason_code => 'platform_owner_cancel',
    p_reason_message => clean_reason,
    p_actor_kind => 'platform_owner',
    p_actor_email => clean_actor
  );

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    clean_actor, 'communications.message_cancelled', 'communication_delivery_intent', intent.id::text,
    jsonb_build_object('organization_id', intent.organization_id, 'intent_status', intent.status,
      'outbox_status', outbox.status, 'failure_code', intent.failure_code,
      'attempt_count', outbox.attempt_count),
    jsonb_build_object('intent_status', 'cancelled', 'outbox_status', 'cancelled',
      'reason', clean_reason)
  );

  return jsonb_build_object('changed', true, 'delivery_intent_id', intent.id,
    'outbox_status', 'cancelled');
end;
$$;


ALTER FUNCTION "public"."cancel_communication_message"("p_delivery_intent_id" "uuid", "p_reason" "text", "p_actor_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_team_invitation"("target_invitation_id" "uuid", "target_cancelled_by" "uuid") RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current_row public.organization_member_invitations;
  updated_row public.organization_member_invitations;
begin
  select * into current_row
  from public.organization_member_invitations
  where id = target_invitation_id
  for update;

  if not found then
    raise exception 'Invitation % does not exist.', target_invitation_id using errcode = 'check_violation';
  end if;

  if current_row.state = 'reserving' and current_row.invited_user_id is null then
    update public.organization_member_invitations
    set state = 'cancelled',
        token_hash = null,
        lease_nonce = null,
        lease_expires_at = null,
        cancelled_at = now(),
        cancelled_by = target_cancelled_by
    where id = target_invitation_id
    returning * into updated_row;

    insert into public.organization_member_access_events (
      organization_id, event_type, actor_kind, actor_user_id, subject_invitation_id, summary
    )
    values (
      updated_row.organization_id, 'invitation.cancelled', 'member', target_cancelled_by, updated_row.id,
      '{}'::jsonb
    );

    return updated_row;
  end if;

  if current_row.state in ('reserving', 'invited') then
    update public.organization_member_invitations
    set state = 'cancelled',
        token_hash = null,
        lease_nonce = null,
        lease_expires_at = null,
        cancelled_at = now(),
        cancelled_by = target_cancelled_by,
        identity_cleanup_state = 'required',
        identity_cleanup_error = null
    where id = target_invitation_id
    returning * into updated_row;

    insert into public.organization_member_access_events (
      organization_id, event_type, actor_kind, actor_user_id, subject_invitation_id, summary
    )
    values (
      updated_row.organization_id, 'invitation.cancelled', 'member', target_cancelled_by, updated_row.id,
      '{}'::jsonb
    );

    return updated_row;
  end if;

  if current_row.state = 'accepting' then
    if current_row.lease_expires_at > now() then
      raise exception
        'Invitation % has an open acceptance lease; it cannot be cancelled until the lease expires.',
        target_invitation_id
        using errcode = 'check_violation';
    end if;

    -- Not a cancellation: the lapsed lease may still finalize as accepted (settle_expired_acceptance calls
    -- private.finalize_accepted_invitation itself, which logs invitation.accepted), or it may flag the
    -- identity for reconciliation with no terminal outcome yet. Either way, "cancelled" would be a lie.
    return private.settle_expired_acceptance(target_invitation_id);
  end if;

  raise exception 'Invitation % is % and cannot be cancelled.', target_invitation_id, current_row.state
    using errcode = 'check_violation';
end;
$$;


ALTER FUNCTION "public"."cancel_team_invitation"("target_invitation_id" "uuid", "target_cancelled_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_item_cost"("target_item_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  organizations uuid[];
  org uuid;
  can_cost boolean;
  answer jsonb;
begin
  if target_item_ids is null or cardinality(target_item_ids) = 0 then
    return '{}'::jsonb;
  end if;

  select array_agg(distinct item.organization_id) into organizations
  from public.catalog_items as item
  where item.id = any(target_item_ids);

  if organizations is null then
    return '{}'::jsonb;
  end if;
  if array_length(organizations, 1) > 1 then
    raise exception 'Those price list items do not belong to one organization.'
      using errcode = 'check_violation';
  end if;
  org := organizations[1];

  if not private.member_has_permission(org, caller, 'catalog.view') then
    raise exception 'You do not have access to this price list.' using errcode = 'insufficient_privilege';
  end if;

  can_cost := private.member_has_permission(org, caller, 'quotes.view_cost');
  if not can_cost then
    return '{}'::jsonb;
  end if;

  select coalesce(jsonb_object_agg(item.id::text, item.unit_cost_minor), '{}'::jsonb)
  into answer
  from public.catalog_items as item
  where item.organization_id = org
    and item.id = any(target_item_ids);

  return answer;
end;
$$;


ALTER FUNCTION "public"."catalog_item_cost"("target_item_ids" "uuid"[]) OWNER TO "postgres";


