CREATE OR REPLACE FUNCTION "public"."change_team_member_role"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "new_role" "text", "keep_adjustments" boolean, "expected_access_revision" integer) RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor_role text;
  membership public.organization_members;
  previous_role text;
  dropped_keys text[];
begin
  membership := private.authorize_team_member_command(
    target_organization_id, actor_user_id, target_user_id
  );
  perform private.assert_membership_is_editable(membership);

  if expected_access_revision is null or expected_access_revision <> membership.access_revision then
    raise exception 'Someone else changed this person''s access while you were editing.'
      using errcode = 'P0409';
  end if;

  -- Ownership has one road, and this is not it.
  if new_role = 'owner' then
    raise exception 'Ownership is handed over, never assigned.' using errcode = 'check_violation';
  end if;

  if new_role is null or new_role not in ('admin', 'office', 'sales', 'field', 'finance') then
    raise exception '% is not a role.', coalesce(new_role, 'nothing') using errcode = 'check_violation';
  end if;

  select membership_actor.role into actor_role
  from public.organization_members as membership_actor
  where membership_actor.organization_id = target_organization_id
    and membership_actor.user_id = actor_user_id;

  if new_role = 'admin' and actor_role <> 'owner' then
    raise exception 'Only the owner can make someone an administrator.' using errcode = 'check_violation';
  end if;

  if new_role = membership.role then
    raise exception 'That person already has this role.' using errcode = 'check_violation';
  end if;

  previous_role := membership.role;

  with dropped as (
    delete from public.organization_member_permission_overrides as override
    where override.organization_id = target_organization_id
      and override.user_id = target_user_id
      and (
        keep_adjustments is not true
        or (
          override.override_state = 'grant'
          and exists (
            select 1
            from public.role_permissions as role_permission
            where role_permission.role = new_role
              and role_permission.permission_key = override.permission_key
          )
        )
        or (
          override.override_state = 'deny'
          and not exists (
            select 1
            from public.role_permissions as role_permission
            where role_permission.role = new_role
              and role_permission.permission_key = override.permission_key
          )
        )
      )
    returning override.permission_key
  )
  select coalesce(array_agg(dropped.permission_key order by dropped.permission_key), '{}'::text[])
  into dropped_keys
  from dropped;

  update public.organization_members as membership_row
  set role = new_role,
      access_revision = membership_row.access_revision + 1
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  returning * into membership;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    target_organization_id, 'member.role_changed', 'member', actor_user_id, target_user_id,
    jsonb_build_object('previous_role', previous_role, 'new_role', new_role)
  );

  -- A second line, only when adjustments actually went. One Save that both changed the role and dropped
  -- three adjustments should read as both facts in the history, not as a role change that quietly did more.
  if array_length(dropped_keys, 1) is not null then
    insert into public.organization_member_access_events (
      organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
    )
    values (
      target_organization_id, 'member.permissions_changed', 'member', actor_user_id, target_user_id,
      jsonb_build_object('removed_permissions', to_jsonb(dropped_keys))
    );
  end if;

  return membership;
end;
$$;


ALTER FUNCTION "public"."change_team_member_role"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "new_role" "text", "keep_adjustments" boolean, "expected_access_revision" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."change_team_member_role"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "new_role" "text", "keep_adjustments" boolean, "expected_access_revision" integer) IS 'Moves one member to another standard role. Drops the individual adjustments the new role makes meaningless -- or all of them when keep_adjustments is false. Never assigns ownership.';



CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("target_bucket_key" "text", "target_window_seconds" integer, "target_max_attempts" integer) RETURNS TABLE("allowed" boolean, "retry_after_seconds" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  bucket_window timestamptz;
  current_count integer;
begin
  if target_window_seconds <= 0 or target_max_attempts <= 0 then
    raise exception 'target_window_seconds and target_max_attempts must be positive.'
      using errcode = 'check_violation';
  end if;

  bucket_window := to_timestamp(
    floor(extract(epoch from now()) / target_window_seconds) * target_window_seconds
  );

  -- Opportunistic cleanup, scoped to this bucket_key only (cheap: hits the primary key index,
  -- never a full table scan) so the table doesn't grow unbounded across many distinct callers.
  delete from public.platform_rate_limit_buckets
  where platform_rate_limit_buckets.bucket_key = target_bucket_key
    and platform_rate_limit_buckets.window_start < bucket_window;

  insert into public.platform_rate_limit_buckets (bucket_key, window_start, attempt_count)
  values (target_bucket_key, bucket_window, 1)
  on conflict (bucket_key, window_start)
  do update set attempt_count = platform_rate_limit_buckets.attempt_count + 1
  returning platform_rate_limit_buckets.attempt_count into current_count;

  return query select
    current_count <= target_max_attempts,
    case
      when current_count <= target_max_attempts then 0
      else greatest(
        1,
        ceil(extract(epoch from (bucket_window + make_interval(secs => target_window_seconds) - now())))::integer
      )
    end;
end;
$$;


ALTER FUNCTION "public"."check_rate_limit"("target_bucket_key" "text", "target_window_seconds" integer, "target_max_attempts" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_templates_list"("target_organization_id" "uuid", "include_archived" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  templates jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to view checklists.' using errcode = 'insufficient_privilege';
  end if;
  if target_organization_id is distinct from private.current_organization() then
    raise exception 'You do not have access to these checklists.' using errcode = 'insufficient_privilege';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', template.id, 'name', template.name,
      'archived', template.archived_at is not null,
      'updated_at', template.updated_at,
      'items', coalesce(questions.items, '[]'::jsonb)) order by template.name), '[]'::jsonb)
  into templates
  from public.checklist_templates as template
  left join lateral (
    select jsonb_agg(jsonb_build_object(
      'id', item.id, 'position', item.position, 'label', item.label,
      'item_type', item.item_type, 'required', item.required,
      'options', coalesce(to_jsonb(item.options), 'null'::jsonb)) order by item.position) as items
    from public.checklist_template_items as item
    where item.organization_id = template.organization_id and item.template_id = template.id
  ) as questions on true
  where template.organization_id = target_organization_id
    and (include_archived or template.archived_at is null);
  return jsonb_build_object('templates', templates,
    'can_manage', private.member_has_permission(target_organization_id, caller, 'settings.checklists.manage'));
end;
$$;


ALTER FUNCTION "public"."checklist_templates_list"("target_organization_id" "uuid", "include_archived" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."checklist_templates_list"("target_organization_id" "uuid", "include_archived" boolean) IS 'The Settings library, with each checklist''s questions.';



CREATE OR REPLACE FUNCTION "public"."claim_automation_work_items"("p_batch_size" integer DEFAULT 25, "p_per_organization_cap" integer DEFAULT 5, "p_lease_seconds" integer DEFAULT 120, "p_max_attempts" integer DEFAULT 8, "p_worker" "text" DEFAULT NULL::"text") RETURNS TABLE("work_item_id" "uuid", "claim_token" "uuid", "organization_id" "uuid", "enrollment_id" "uuid", "step_index" integer, "attempts" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_token uuid := gen_random_uuid();
  v_worker text := left(coalesce(nullif(btrim(p_worker), ''), 'automation-worker'), 100);
  v_candidate_window integer;
begin
  if p_batch_size < 1 or p_batch_size > 200 then
    raise exception 'The claim batch size is outside its safe bounds.' using errcode = 'check_violation';
  end if;
  if p_per_organization_cap < 1 or p_per_organization_cap > p_batch_size then
    raise exception 'The per-organization cap is outside its safe bounds.' using errcode = 'check_violation';
  end if;
  if p_lease_seconds < 30 or p_lease_seconds > 900 then
    raise exception 'The claim lease is outside its safe bounds.' using errcode = 'check_violation';
  end if;
  if p_max_attempts < 1 or p_max_attempts > 20 then
    raise exception 'The attempt cap is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  update private.automation_work_items as w
  set state = 'needs_attention',
    attention_reason = 'max_attempts',
    attention_at = now(),
    claim_token = null,
    claimed_at = null
  where w.id in (
    select doomed.id
    from private.automation_work_items as doomed
    where doomed.state = 'pending'
      and doomed.available_at <= now()
      and doomed.attempts >= p_max_attempts
    order by doomed.available_at, doomed.id
    limit p_batch_size
    for update skip locked
  );

  v_candidate_window := least(p_batch_size * 4, 400);

  return query
  with candidates as (
    select w.id, w.available_at, w.organization_id
    from private.automation_work_items as w
    where w.state = 'pending'
      and w.available_at <= now()
      and w.attempts < p_max_attempts
    order by w.available_at, w.id
    limit v_candidate_window
  ),
  due as (
    select
      candidates.id,
      candidates.available_at,
      row_number() over (
        partition by candidates.organization_id order by candidates.available_at, candidates.id
      ) as per_organization_rank
    from candidates
  ),
  ranked as (
    select
      due.id,
      row_number() over (
        order by (due.per_organization_rank > p_per_organization_cap), due.available_at, due.id
      ) as pick_order
    from due
  ),
  picked as (
    select ranked.id from ranked where ranked.pick_order <= p_batch_size
  ),
  locked as (
    select w.id
    from private.automation_work_items as w
    where w.id in (select picked.id from picked)
    order by w.available_at, w.id
    for update skip locked
  )
  update private.automation_work_items as w
  set claim_token = v_token,
    claimed_at = now(),
    claimed_by = v_worker,
    attempts = w.attempts + 1,
    available_at = now() + make_interval(secs => p_lease_seconds),
    last_error_code = null,
    last_error_message = null
  from locked
  where w.id = locked.id
  returning w.id, w.claim_token, w.organization_id, w.enrollment_id, w.step_index, w.attempts;
end;
$$;


ALTER FUNCTION "public"."claim_automation_work_items"("p_batch_size" integer, "p_per_organization_cap" integer, "p_lease_seconds" integer, "p_max_attempts" integer, "p_worker" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_automation_work_items"("p_batch_size" integer, "p_per_organization_cap" integer, "p_lease_seconds" integer, "p_max_attempts" integer, "p_worker" "text") IS 'Atomically claims a bounded, organization-fair batch of due work under a per-row lease. Safe to run from any number of workers at once: there is no global lock, and an abandoned claim recovers when its lease passes. Service role only.';



CREATE OR REPLACE FUNCTION "public"."claim_cancelled_team_invitation_cleanup"("target_organization_id" "uuid", "target_invitation_id" "uuid", "target_lease_nonce" "uuid", "target_lease_seconds" integer DEFAULT 300) RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  claimed_row public.organization_member_invitations;
begin
  if target_lease_seconds not between 30 and 1800 then
    raise exception 'The reconciliation lease is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  update public.organization_member_invitations
  set reconciliation_nonce = target_lease_nonce,
      reconciliation_lease_expires_at = now() + make_interval(secs => target_lease_seconds)
  where id = target_invitation_id
    and organization_id = target_organization_id
    and state = 'cancelled'
    and identity_cleanup_state = 'required'
    and invited_user_id is not null
    and (
      reconciliation_lease_expires_at is null
      or reconciliation_lease_expires_at < now()
    )
  returning * into claimed_row;

  if not found then
    raise exception 'The cancelled invitation is not available for cleanup.'
      using errcode = 'P0409';
  end if;

  return claimed_row;
end;
$$;


ALTER FUNCTION "public"."claim_cancelled_team_invitation_cleanup"("target_organization_id" "uuid", "target_invitation_id" "uuid", "target_lease_nonce" "uuid", "target_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_communication_forward_event"() RETURNS TABLE("forward_event_id" "uuid", "claim_token" "uuid", "recipient_emails" "text"[], "subject" "text", "html_content" "text", "text_content" "text", "sender_id" "uuid", "sender_email" "text", "sender_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  candidate record;
  selected_sender public.communication_email_senders;
  sender_domain public.communication_email_domains;
  assigned_member_status text;
  new_claim_token uuid;
begin
  for candidate in
    select event.*
    from public.communication_forward_events event
    where event.status in ('queued', 'failed') and event.available_at <= now()
    order by event.available_at, event.created_at, event.id
    limit 50
    for update skip locked
  loop
    select sender.* into selected_sender
    from public.communication_email_senders sender
    where sender.organization_id = candidate.organization_id and sender.id = candidate.sender_id
    for share;

    assigned_member_status := null;
    if selected_sender.assigned_user_id is not null then
      select member.status into assigned_member_status from public.organization_members member
      where member.organization_id = selected_sender.organization_id
        and member.user_id = selected_sender.assigned_user_id
      for share;
    end if;
    select domain.* into sender_domain from public.communication_email_domains domain
    where domain.organization_id = selected_sender.organization_id and domain.id = selected_sender.domain_id
    for share;

    if selected_sender.id is null or selected_sender.lifecycle_state <> 'enabled'
      or not selected_sender.allows_manual
      or (selected_sender.assigned_user_id is not null and assigned_member_status is distinct from 'active')
      or sender_domain.id is null or sender_domain.purpose <> 'sending'
      or sender_domain.lifecycle_state not in ('verified')
      or not sender_domain.provider_verified or not sender_domain.provider_authenticated
      or sender_domain.ownership_status <> 'passing' or sender_domain.dkim_status <> 'passing' then
      update public.communication_forward_events
      set status = 'failed', available_at = 'infinity'::timestamptz,
        failure_code = 'forward_sender_review_required',
        failure_message = 'The original sender is no longer eligible. Review and reassign this message.'
      where id = candidate.id;
      continue;
    end if;

    new_claim_token := gen_random_uuid();
    update public.communication_forward_events
    set status = 'claimed', claimed_at = now(), claim_token = new_claim_token,
      attempt_count = attempt_count + 1, failure_code = null, failure_message = null
    where id = candidate.id;

    return query select candidate.id, new_claim_token, candidate.recipient_emails, candidate.subject,
      candidate.html_content, candidate.text_content, selected_sender.id, selected_sender.email_address,
      selected_sender.display_name;
    return;
  end loop;
end;
$$;


ALTER FUNCTION "public"."claim_communication_forward_event"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_inbound_attachments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "inbound_message_id" "uuid" NOT NULL,
    "file_name" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "byte_size" bigint NOT NULL,
    "object_key" "text",
    "status" "text" DEFAULT 'pending_import'::"text" NOT NULL,
    "failure_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "claim_token" "uuid",
    "provider_download_token" "text",
    "provider" "text" DEFAULT 'brevo'::"text" NOT NULL,
    CONSTRAINT "communication_inbound_attachments_byte_size_check" CHECK (("byte_size" >= 0)),
    CONSTRAINT "communication_inbound_attachments_claim_check" CHECK ((("claimed_at" IS NULL) = ("claim_token" IS NULL))),
    CONSTRAINT "communication_inbound_attachments_file_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "file_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "file_name")) <= 255))),
    CONSTRAINT "communication_inbound_attachments_mime_type_check" CHECK ((("char_length"(TRIM(BOTH FROM "mime_type")) >= 1) AND ("char_length"(TRIM(BOTH FROM "mime_type")) <= 127))),
    CONSTRAINT "communication_inbound_attachments_provider_check" CHECK (("provider" = ANY (ARRAY['brevo'::"text", 'twilio'::"text"]))),
    CONSTRAINT "communication_inbound_attachments_status_check" CHECK (("status" = ANY (ARRAY['pending_import'::"text", 'pending_scan'::"text", 'available'::"text", 'blocked_type'::"text", 'blocked_size'::"text", 'infected'::"text", 'scan_failed'::"text", 'import_failed'::"text"])))
);


ALTER TABLE "public"."communication_inbound_attachments" OWNER TO "postgres";


COMMENT ON COLUMN "public"."communication_inbound_attachments"."provider" IS 'Denormalized from the parent inbound message -- brevo for email, twilio for SMS/MMS.';



CREATE OR REPLACE FUNCTION "public"."claim_communication_inbound_attachment_imports"("batch_size" integer DEFAULT 20) RETURNS SETOF "public"."communication_inbound_attachments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  new_claim_token uuid;
begin
  if batch_size not between 1 and 100 then
    raise exception 'The inbound attachment import batch is outside its safe bounds.'
      using errcode = 'check_violation';
  end if;

  new_claim_token := gen_random_uuid();

  return query
  update public.communication_inbound_attachments attachment
  set claimed_at = now(), claim_token = new_claim_token
  from (
    select id
    from public.communication_inbound_attachments
    where status = 'pending_import'
      and (claimed_at is null or claimed_at <= now() - interval '10 minutes')
    order by created_at, id
    limit batch_size
    for update skip locked
  ) due
  where attachment.id = due.id
  returning attachment.*;
end;
$$;


ALTER FUNCTION "public"."claim_communication_inbound_attachment_imports"("batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_communication_outbox_event"() RETURNS TABLE("outbox_event_id" "uuid", "delivery_intent_id" "uuid", "claim_token" "uuid", "recipient_email" "text", "subject" "text", "html_content" "text", "text_content" "text", "logical_send_key" "text", "sender_id" "uuid", "sender_email" "text", "sender_name" "text", "reply_to_email" "text", "reply_to_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  candidate record;
  current_recipient public.client_contact_methods;
  selected_sender public.communication_email_senders;
  sender_domain public.communication_email_domains;
  assigned_member_status text;
  active_allowance record;
  allowance_limit_state text;
  allowance_limit_value integer;
  accepted_recipient_count integer;
  reserved_recipient_count integer;
  new_claim_token uuid;
  alias public.communication_reply_aliases;
  alias_domain public.communication_email_domains;
  holding_pause public.communication_email_sending_pauses%rowtype;
  hold_code text;
  hold_message text;
  today_start timestamptz := date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
  warmup_ceiling integer;
  warmup_used_today integer;
  short_term_max integer;
  short_term_window integer;
  short_term_used integer;
  short_term_oldest_at timestamptz;
  short_term_retry_at timestamptz;
  provider_capacity integer;
  provider_reserve_percent integer;
  provider_reserve integer;
  provider_effective_cap integer;
  current_period_start timestamptz := date_trunc('month', now() at time zone 'UTC') at time zone 'UTC';
  platform_accepted bigint;
  platform_reserved bigint;
begin
  if exists (
    select 1 from public.communication_email_sending_pauses
    where scope = 'platform' and released_at is null
  ) then
    return;
  end if;

  for candidate in
    select
      event.id as event_id,
      event.delivery_intent_id,
      intent.organization_id,
      intent.client_id,
      intent.client_contact_method_id,
      intent.recipient_email,
      intent.subject,
      intent.html_content,
      intent.text_content,
      intent.logical_send_key,
      intent.send_kind,
      intent.allowance_class,
      intent.retry_class,
      intent.expires_at,
      intent.sender_id,
      intent.reply_alias_id,
      intent.created_by
    from public.communication_outbox_events event
    join public.communication_delivery_intents intent on intent.id = event.delivery_intent_id
    where event.channel = 'email' and event.status in ('pending', 'failed') and event.available_at <= now()
    order by event.available_at, event.created_at, event.id
    limit 50
    for update of event skip locked
  loop
    if candidate.expires_at <= now() then
      hold_message := case candidate.retry_class
        when 'payment_receipt' then
          'This receipt could not be sent within 72 hours, so UCRM cancelled it. Send it again once sending is working.'
        when 'appointment_reminder' then
          'This reminder was not sent before its appointment window passed, so UCRM cancelled it.'
        when 'optional_followup' then
          'This follow-up passed its send window before it could go out, so UCRM cancelled it.'
        else
          'This message could not be sent within 24 hours, so UCRM cancelled it. Send it again once sending is working.'
      end;
      update public.communication_delivery_intents
      set status = 'cancelled', provider_message_id = null, accepted_at = null,
        failure_code = 'retry_deadline_passed', failure_message = hold_message
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set status = 'cancelled', claimed_at = null, claim_token = null, last_error = hold_message
      where id = candidate.event_id;
      continue;
    end if;

    hold_code := null;
    hold_message := null;

    if exists (
      select 1 from public.organizations org
      where org.id = candidate.organization_id
        and org.lifecycle_status = 'suspended'
    ) then
      hold_code := 'organization_suspended';
      hold_message := 'Sending is suspended for this organization. UCRM will retry once it is reactivated.';
    elsif exists (
      select 1 from public.organization_closure_records closure
      where closure.organization_id = candidate.organization_id
        and closure.status in ('pending_closure', 'purge_in_progress')
    ) then
      hold_code := 'organization_closing';
      hold_message := 'This organization is closing. UCRM will retry if the closure is reversed.';
    end if;

    if hold_code is not null then
      update public.communication_delivery_intents
      set failure_code = hold_code, failure_message = hold_message
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set available_at = least(now() + interval '1 hour', candidate.expires_at), last_error = hold_message
      where id = candidate.event_id;
      continue;
    end if;

    current_recipient := null;
    select method.* into current_recipient
    from public.client_contact_methods method
    where method.organization_id = candidate.organization_id
      and method.id = candidate.client_contact_method_id
    for share;

    if current_recipient.id is null
      or current_recipient.client_id <> candidate.client_id
      or current_recipient.kind <> 'email'
      or current_recipient.normalized_value <> candidate.recipient_email then
      update public.communication_delivery_intents
      set status = 'cancelled', provider_message_id = null, accepted_at = null,
        failure_code = 'recipient_no_longer_eligible',
        failure_message = 'The queued recipient is no longer an active email method for this customer.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set status = 'cancelled', claimed_at = null, claim_token = null,
        last_error = 'The queued recipient is no longer an active email method for this customer.'
      where id = candidate.event_id;
      continue;
    end if;

    if exists (
      select 1
      from public.communication_email_suppressions suppression
      where suppression.organization_id = candidate.organization_id
        and suppression.recipient_email = candidate.recipient_email
        and suppression.released_at is null
        and (
          suppression.reason in ('hard_bounce', 'complaint')
          or (suppression.reason = 'unsubscribe' and candidate.allowance_class = 'optional')
        )
    ) then
      update public.communication_delivery_intents
      set status = 'cancelled', provider_message_id = null, accepted_at = null,
        failure_code = 'recipient_suppressed',
        failure_message = 'This recipient address is on the organization suppression list.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set status = 'cancelled', claimed_at = null, claim_token = null,
        last_error = 'This recipient address is on the organization suppression list.'
      where id = candidate.event_id;
      continue;
    end if;

    holding_pause := null;
    select pause.* into holding_pause
    from public.communication_email_sending_pauses pause
    where pause.scope = 'organization'
      and pause.organization_id = candidate.organization_id
      and pause.released_at is null
      and (pause.applies_to = 'all' or candidate.allowance_class = 'optional')
    order by case when pause.applies_to = 'all' then 0 else 1 end
    limit 1;

    if holding_pause.id is not null then
      if holding_pause.source = 'auto_reputation' then
        hold_code := 'sending_paused_reputation';
        hold_message := 'Optional email is paused while this organization''s delivery reputation is reviewed.';
      else
        hold_code := 'sending_paused_organization';
        hold_message := 'Sending for this organization is paused. UCRM will retry when it resumes.';
      end if;
      update public.communication_delivery_intents
      set failure_code = hold_code, failure_message = hold_message
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set available_at = least(now() + interval '5 minutes', candidate.expires_at), last_error = hold_message
      where id = candidate.event_id;
      continue;
    end if;

    selected_sender := null;
    if candidate.sender_id is not null then
      select sender.* into selected_sender
      from public.communication_email_senders sender
      where sender.organization_id = candidate.organization_id and sender.id = candidate.sender_id
      for share;
    elsif candidate.send_kind = 'automated' then
      select sender.* into selected_sender
      from public.communication_email_senders sender
      where sender.organization_id = candidate.organization_id
        and sender.is_organization_default and sender.lifecycle_state <> 'removed'
      order by sender.created_at, sender.id limit 1 for share;
    end if;

    if selected_sender.id is null then
      if candidate.send_kind = 'manual' then
        update public.communication_delivery_intents set status = 'failed', provider_message_id = null,
          accepted_at = null, failure_code = 'manual_sender_review_required',
          failure_message = 'The original sender is no longer eligible. Review and reassign this message.'
        where id = candidate.delivery_intent_id;
        update public.communication_outbox_events set status = 'failed', available_at = 'infinity'::timestamptz,
          claimed_at = null, claim_token = null,
          last_error = 'The original sender is no longer eligible. Review and reassign this message.'
        where id = candidate.event_id;
      else
        update public.communication_delivery_intents set status = 'cancelled', provider_message_id = null,
          accepted_at = null, failure_code = 'automated_sender_invalid',
          failure_message = 'The configured automated sender is no longer valid.'
        where id = candidate.delivery_intent_id;
        update public.communication_outbox_events set status = 'cancelled', claimed_at = null, claim_token = null,
          last_error = 'The configured automated sender is no longer valid.'
        where id = candidate.event_id;
      end if;
      continue;
    end if;

    assigned_member_status := null;
    if selected_sender.assigned_user_id is not null then
      select member.status into assigned_member_status from public.organization_members member
      where member.organization_id = selected_sender.organization_id and member.user_id = selected_sender.assigned_user_id
      for share;
    end if;
    sender_domain := null;
    select domain.* into sender_domain from public.communication_email_domains domain
    where domain.organization_id = selected_sender.organization_id and domain.id = selected_sender.domain_id
    for share;

    if selected_sender.lifecycle_state = 'pending_verification'
      or (sender_domain.id is not null and sender_domain.lifecycle_state not in ('removal_pending', 'removed')
        and (sender_domain.lifecycle_state <> 'verified' or not sender_domain.provider_verified
          or not sender_domain.provider_authenticated or sender_domain.ownership_status <> 'passing'
          or sender_domain.dkim_status <> 'passing')) then
      update public.communication_delivery_intents set failure_code = 'sender_domain_temporarily_unavailable',
        failure_message = 'The sending domain is temporarily unavailable. UCRM will check again.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set available_at = least(now() + interval '15 minutes', candidate.expires_at),
        last_error = 'The sending domain is temporarily unavailable. UCRM will check again.'
      where id = candidate.event_id;
      continue;
    end if;

    if selected_sender.lifecycle_state <> 'enabled'
      or (candidate.send_kind = 'manual' and not selected_sender.allows_manual)
      or (candidate.send_kind = 'automated' and not selected_sender.allows_automated)
      or (selected_sender.assigned_user_id is not null and assigned_member_status is distinct from 'active')
      or sender_domain.id is null or sender_domain.purpose <> 'sending'
      or sender_domain.lifecycle_state in ('removal_pending', 'removed') then
      if candidate.send_kind = 'manual' then
        update public.communication_delivery_intents set status = 'failed', provider_message_id = null,
          accepted_at = null, failure_code = 'manual_sender_review_required',
          failure_message = 'The original sender is no longer eligible. Review and reassign this message.'
        where id = candidate.delivery_intent_id;
        update public.communication_outbox_events set status = 'failed', available_at = 'infinity'::timestamptz,
          claimed_at = null, claim_token = null,
          last_error = 'The original sender is no longer eligible. Review and reassign this message.'
        where id = candidate.event_id;
      else
        update public.communication_delivery_intents set status = 'cancelled', provider_message_id = null,
          accepted_at = null, failure_code = 'automated_sender_invalid',
          failure_message = 'The configured automated sender is no longer valid.'
        where id = candidate.delivery_intent_id;
        update public.communication_outbox_events set status = 'cancelled', claimed_at = null, claim_token = null,
          last_error = 'The configured automated sender is no longer valid.'
        where id = candidate.event_id;
      end if;
      continue;
    end if;

    warmup_ceiling := private.resolve_communication_email_warmup_ceiling(
      candidate.organization_id, sender_domain.id, now());
    if warmup_ceiling is not null then
      select
        coalesce((
          select sum(usage.recipient_count)
          from public.communication_email_usage_events usage
          join public.communication_delivery_intents used_intent on used_intent.id = usage.delivery_intent_id
          join public.communication_email_senders used_sender on used_sender.id = used_intent.sender_id
          where usage.organization_id = candidate.organization_id
            and usage.occurred_at >= today_start
            and used_sender.domain_id = sender_domain.id
        ), 0)
      + coalesce((
          select sum(reservation.recipient_count)
          from public.communication_email_capacity_reservations reservation
          join public.communication_delivery_intents reserved_intent on reserved_intent.id = reservation.delivery_intent_id
          join public.communication_email_senders reserved_sender on reserved_sender.id = reserved_intent.sender_id
          where reservation.organization_id = candidate.organization_id
            and reservation.reservation_state in ('reserved', 'submission_unknown')
            and reservation.reserved_at >= today_start
            and reserved_sender.domain_id = sender_domain.id
        ), 0)
      into warmup_used_today;

      if warmup_used_today + 1 > warmup_ceiling then
        update public.communication_delivery_intents
        set failure_code = 'email_warmup_ceiling_reached',
          failure_message = 'This sending domain is still warming up and has reached today''s limit. UCRM will retry tomorrow.'
        where id = candidate.delivery_intent_id;
        update public.communication_outbox_events
        set available_at = least(today_start + interval '1 day', candidate.expires_at),
          last_error = 'This sending domain is still warming up and has reached today''s limit. UCRM will retry tomorrow.'
        where id = candidate.event_id;
        continue;
      end if;
    end if;

    select rate.max_recipients, rate.window_minutes
    into short_term_max, short_term_window
    from private.resolve_communication_email_short_term_rate(candidate.organization_id, now()) rate;

    if short_term_max is not null then
      select
        coalesce((
          select sum(usage.recipient_count)
          from public.communication_email_usage_events usage
          where usage.organization_id = candidate.organization_id
            and usage.occurred_at > now() - make_interval(mins => short_term_window)
        ), 0)
      + coalesce((
          select sum(reservation.recipient_count)
          from public.communication_email_capacity_reservations reservation
          where reservation.organization_id = candidate.organization_id
            and reservation.reservation_state in ('reserved', 'submission_unknown')
            and reservation.reserved_at > now() - make_interval(mins => short_term_window)
        ), 0)
      into short_term_used;

      select min(usage.occurred_at) into short_term_oldest_at
      from public.communication_email_usage_events usage
      where usage.organization_id = candidate.organization_id
        and usage.occurred_at > now() - make_interval(mins => short_term_window);

      if short_term_used + 1 > short_term_max then
        short_term_retry_at := coalesce(short_term_oldest_at, now())
          + make_interval(mins => short_term_window);
        if short_term_retry_at <= now() then
          short_term_retry_at := now() + interval '1 minute';
        end if;
        update public.communication_delivery_intents
        set failure_code = 'email_short_term_rate_limited',
          failure_message = format(
            'This organization has reached its short-term sending limit (%s recipients per %s minutes). UCRM will retry shortly.',
            short_term_max, short_term_window)
        where id = candidate.delivery_intent_id;
        update public.communication_outbox_events
        set available_at = least(short_term_retry_at, candidate.expires_at),
          last_error = 'Short-term sending limit reached. UCRM will retry shortly.'
        where id = candidate.event_id;
        continue;
      end if;
    end if;

    select cap.capacity, cap.reserve_percent
    into provider_capacity, provider_reserve_percent
    from private.resolve_communication_email_provider_capacity(now()) cap;

    if provider_capacity is not null then
      provider_reserve := ceil(provider_capacity::numeric * provider_reserve_percent / 100.0)::integer;
      if candidate.allowance_class = 'optional' then
        provider_effective_cap := provider_capacity - provider_reserve;
      else
        provider_effective_cap := provider_capacity;
      end if;

      select coalesce(usage.accepted_recipients, 0) into platform_accepted
      from public.communication_email_platform_period_usage usage
      where usage.period_start = current_period_start;
      platform_accepted := coalesce(platform_accepted, 0);

      select coalesce(sum(reservation.recipient_count), 0) into platform_reserved
      from public.communication_email_capacity_reservations reservation
      where reservation.reservation_state in ('reserved', 'submission_unknown')
        and reservation.reserved_at >= current_period_start;

      if platform_accepted + platform_reserved + 1 > provider_effective_cap then
        if candidate.allowance_class = 'optional' then
          hold_message := 'The platform has reached its reserved monthly sending capacity. Essential email still sends; other email will retry.';
          update public.communication_delivery_intents
          set failure_code = 'email_platform_capacity_reserved', failure_message = hold_message
          where id = candidate.delivery_intent_id;
        else
          hold_message := 'The platform has reached its monthly provider sending capacity. UCRM will retry shortly.';
          update public.communication_delivery_intents
          set failure_code = 'email_platform_capacity_reached', failure_message = hold_message
          where id = candidate.delivery_intent_id;
        end if;
        update public.communication_outbox_events
        set available_at = least(now() + interval '15 minutes', candidate.expires_at), last_error = hold_message
        where id = candidate.event_id;
        continue;
      end if;
    end if;

    select * into active_allowance
    from private.resolve_communication_email_allowance(candidate.organization_id, now());
    if not found then
      update public.communication_delivery_intents set failure_code = 'email_allowance_period_unavailable',
        failure_message = 'No active email allowance period is available. UCRM will check again.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set available_at = least(now() + interval '15 minutes', candidate.expires_at),
        last_error = 'No active email allowance period is available. UCRM will check again.'
      where id = candidate.event_id;
      continue;
    end if;

    if candidate.allowance_class = 'optional' then
      allowance_limit_state := active_allowance.operational_limit_state;
      allowance_limit_value := active_allowance.operational_limit_value;
    else
      allowance_limit_state := active_allowance.essential_limit_state;
      allowance_limit_value := active_allowance.essential_limit_value;
    end if;
    if allowance_limit_state not in ('numeric', 'unlimited')
      or (allowance_limit_state = 'numeric' and allowance_limit_value is null) then
      update public.communication_delivery_intents set failure_code = 'email_allowance_unavailable',
        failure_message = 'Email allowance is unavailable. UCRM will check again.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set available_at = least(now() + interval '15 minutes', candidate.expires_at),
        last_error = 'Email allowance is unavailable. UCRM will check again.'
      where id = candidate.event_id;
      continue;
    end if;

    insert into public.communication_email_capacity_buckets (
      organization_id, allowance_period_id, allowance_class
    ) values (candidate.organization_id, active_allowance.period_id, candidate.allowance_class)
    on conflict do nothing;
    perform 1 from public.communication_email_capacity_buckets bucket
    where bucket.organization_id = candidate.organization_id
      and bucket.allowance_period_id = active_allowance.period_id
      and bucket.allowance_class = candidate.allowance_class
    for update;

    if allowance_limit_state = 'numeric' then
      select coalesce(sum(usage.recipient_count), 0)::integer into accepted_recipient_count
      from public.communication_email_usage_events usage
      where usage.organization_id = candidate.organization_id
        and usage.allowance_period_id = active_allowance.period_id
        and usage.allowance_class = candidate.allowance_class;
      select coalesce(sum(reservation.recipient_count), 0)::integer into reserved_recipient_count
      from public.communication_email_capacity_reservations reservation
      where reservation.organization_id = candidate.organization_id
        and reservation.allowance_period_id = active_allowance.period_id
        and reservation.allowance_class = candidate.allowance_class
        and reservation.reservation_state in ('reserved', 'submission_unknown');
      if accepted_recipient_count + reserved_recipient_count >= allowance_limit_value then
        update public.communication_delivery_intents set failure_code = 'email_allowance_exhausted',
          failure_message = 'Email allowance is currently exhausted. UCRM will check again.'
        where id = candidate.delivery_intent_id;
        update public.communication_outbox_events
        set available_at = least(now() + interval '15 minutes', candidate.expires_at),
          last_error = 'Email allowance is currently exhausted. UCRM will check again.'
        where id = candidate.event_id;
        continue;
      end if;
    end if;

    insert into public.communication_email_capacity_reservations (
      organization_id, delivery_intent_id, allowance_period_id, allowance_class, reservation_state, reserved_at, settled_at
    ) values (
      candidate.organization_id, candidate.delivery_intent_id, active_allowance.period_id,
      candidate.allowance_class, 'reserved', now(), null
    ) on conflict on constraint communication_email_capacity_reservations_delivery_intent_key do update set
      organization_id = excluded.organization_id,
      allowance_period_id = excluded.allowance_period_id,
      allowance_class = excluded.allowance_class,
      reservation_state = 'reserved', reserved_at = now(), settled_at = null
    where public.communication_email_capacity_reservations.reservation_state = 'released';
    if not found then
      raise exception 'The email capacity reservation is not available for this delivery intent.'
        using errcode = 'object_not_in_prerequisite_state';
    end if;

    alias := null;
    alias_domain := null;
    if candidate.reply_alias_id is not null then
      select rep_alias.* into alias from public.communication_reply_aliases rep_alias
      where rep_alias.id = candidate.reply_alias_id and rep_alias.organization_id = candidate.organization_id
      for share;
      if alias.id is not null then
        select * into alias_domain from public.communication_email_domains
        where id = alias.receiving_domain_id and organization_id = candidate.organization_id
        for share;
      end if;
    end if;

    new_claim_token := gen_random_uuid();
    update public.communication_outbox_events set status = 'processing', claimed_at = now(), claim_token = new_claim_token,
      attempt_count = attempt_count + 1, last_error = null where id = candidate.event_id;
    update public.communication_delivery_intents set status = 'claimed', sender_id = selected_sender.id,
      failure_code = null, failure_message = null where id = candidate.delivery_intent_id;
    return query select candidate.event_id, candidate.delivery_intent_id, new_claim_token,
      candidate.recipient_email, candidate.subject, candidate.html_content, candidate.text_content,
      candidate.logical_send_key, selected_sender.id, selected_sender.email_address, selected_sender.display_name,
      case when alias.id is not null and alias_domain.id is not null
        then alias.alias_local_part || '@' || alias_domain.domain_name else null end,
      case when alias.id is not null then selected_sender.display_name else null end;
    return;
  end loop;
end;
$$;


ALTER FUNCTION "public"."claim_communication_outbox_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_communication_sms_outbox_event"() RETURNS TABLE("outbox_event_id" "uuid", "delivery_intent_id" "uuid", "organization_id" "uuid", "twilio_account_id" "uuid", "subaccount_sid" "text", "messaging_service_sid" "text", "claim_token" "uuid", "attempt_number" integer, "recipient_phone" "text", "sender_phone" "text", "body" "text", "encoding" "text", "segment_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  candidate record;
  recipient public.client_contact_methods;
  sender public.communication_sms_sender_identities;
  registration public.communication_sms_registrations;
  account public.communication_twilio_accounts;
  outbound record;
  latest_consent text;
  snapshot public.communication_sms_message_snapshots;
  reservation_state text;
  available timestamptz;
  new_claim_token uuid;
  new_attempt integer;
  hold_message text;
begin
  for candidate in
    select event.id as event_id, event.delivery_intent_id, event.attempt_count,
      intent.organization_id, intent.client_id, intent.client_contact_method_id,
      intent.recipient_phone, intent.sms_sender_identity_id
    from public.communication_outbox_events event
    join public.communication_delivery_intents intent on intent.id = event.delivery_intent_id
    where event.channel = 'sms' and event.status in ('pending', 'failed') and event.available_at <= now()
    order by event.available_at, event.created_at, event.id
    limit 50
    for update of event skip locked
  loop
    -- 1. Recipient still an active phone on this customer, unchanged from the frozen E.164 number.
    recipient := null;
    select method.* into recipient
    from public.client_contact_methods method
    join public.clients client
      on client.organization_id = method.organization_id and client.id = method.client_id
    where method.organization_id = candidate.organization_id
      and method.id = candidate.client_contact_method_id
      and method.client_id = candidate.client_id
      and method.kind = 'phone'
      and client.deleted_at is null
    for share of method, client;

    if recipient.id is null or ('+' || recipient.normalized_value) <> candidate.recipient_phone then
      perform private.communication_sms_release_reservation(candidate.delivery_intent_id);
      update public.communication_delivery_intents
      set status = 'cancelled', failure_code = 'recipient_no_longer_eligible',
        failure_message = 'The queued phone number is no longer active for this customer.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set status = 'cancelled', claimed_at = null, claim_token = null,
        last_error = 'The queued phone number is no longer active for this customer.'
      where id = candidate.event_id;
      continue;
    end if;

    -- 2. A customer STOP after enqueue is a global opt-out: cancel rather than send. Consent is derived from the
    --    append-only events; the governing event for the number is the most recent opt-in/opt-out (HELP never
    --    changes eligibility). A global opt-out therefore beats any earlier subject opt-in, which is exactly the
    --    STOP-racing-a-claim case. Subject scope was fully enforced at enqueue and cannot tighten afterwards.
    latest_consent := (
      select case when governing.event_kind = 'opt_out' then 'opted_out' else 'opted_in' end
      from public.communication_sms_consent_events governing
      where governing.organization_id = candidate.organization_id
        and governing.client_contact_method_id = candidate.client_contact_method_id
        and governing.event_kind in ('opt_in', 'opt_out')
      order by governing.occurred_at desc, governing.received_at desc, governing.id desc
      limit 1
    );
    if latest_consent is distinct from 'opted_in' then
      perform private.communication_sms_release_reservation(candidate.delivery_intent_id);
      update public.communication_delivery_intents
      set status = 'cancelled', failure_code = 'recipient_opted_out',
        failure_message = 'This customer opted out of text messages before this one was sent.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set status = 'cancelled', claimed_at = null, claim_token = null,
        last_error = 'This customer opted out of text messages before this one was sent.'
      where id = candidate.event_id;
      continue;
    end if;

    -- 3. Sending number: must still exist and be live. A released number is gone for good (cancel); any other
    --    not-ready state is transient (defer and re-check).
    sender := null;
    select s.* into sender
    from public.communication_sms_sender_identities s
    where s.organization_id = candidate.organization_id and s.id = candidate.sms_sender_identity_id
    for share of s;

    if sender.id is null or sender.lifecycle_state = 'released' then
      perform private.communication_sms_release_reservation(candidate.delivery_intent_id);
      update public.communication_delivery_intents
      set status = 'cancelled', failure_code = 'sms_sender_unavailable',
        failure_message = 'The number this text would have sent from is no longer available.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set status = 'cancelled', claimed_at = null, claim_token = null,
        last_error = 'The number this text would have sent from is no longer available.'
      where id = candidate.event_id;
      continue;
    end if;

    if sender.lifecycle_state <> 'ready' or not sender.capable_sms
      or sender.registration_id is null or sender.country_code is null or sender.sender_type is null then
      update public.communication_delivery_intents
      set failure_code = 'sms_sender_not_ready',
        failure_message = 'This SMS number is not ready to send right now. UCRM will try again.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set available_at = now() + interval '15 minutes',
        last_error = 'This SMS number is not ready to send right now. UCRM will try again.'
      where id = candidate.event_id;
      continue;
    end if;

    select r.* into registration
    from public.communication_sms_registrations r
    where r.organization_id = candidate.organization_id and r.id = sender.registration_id;
    if registration.id is null then
      update public.communication_delivery_intents
      set failure_code = 'sms_registration_unavailable',
        failure_message = 'This SMS number is not ready to send right now. UCRM will try again.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set available_at = now() + interval '15 minutes',
        last_error = 'This SMS number is not ready to send right now. UCRM will try again.'
      where id = candidate.event_id;
      continue;
    end if;

    -- 4. Readiness and holds in one read (effective mode/package, approved registration, and any active
    --    platform/organization/provider outbound hold). A pause defers, never cancels -- inbound and STOP/START
    --    stay available through it, and a lifted pause re-runs every check here.
    select * into outbound
    from public.communication_sms_outbound_state(
      candidate.organization_id, sender.country_code, sender.sender_type, registration.use_case
    );
    if outbound.state <> 'ready' then
      hold_message := case when outbound.state = 'outbound_paused'
        then 'Outbound texting is paused for this organization. UCRM will try again when it resumes.'
        else 'This organization is not ready to send SMS right now. UCRM will try again.' end;
      update public.communication_delivery_intents
      set failure_code = 'sms_outbound_not_ready', failure_message = hold_message
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set available_at = now() + interval '5 minutes', last_error = hold_message
      where id = candidate.event_id;
      continue;
    end if;

    -- 5. The Twilio subaccount and Messaging Service the worker sends through must be present and live.
    account := null;
    select a.* into account
    from public.communication_twilio_accounts a
    where a.organization_id = candidate.organization_id
    for share of a;
    if account.id is null or account.messaging_service_sid is null
      or account.lifecycle_state not in ('ready', 'restricted') then
      update public.communication_delivery_intents
      set failure_code = 'sms_provider_account_not_ready',
        failure_message = 'This organization''s texting service is not ready. UCRM will try again.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set available_at = now() + interval '15 minutes',
        last_error = 'This organization''s texting service is not ready. UCRM will try again.'
      where id = candidate.event_id;
      continue;
    end if;

    -- 6. Quiet hours: if now falls inside the platform window, reschedule to the window end instead of sending.
    available := public.communication_sms_quiet_hours_available_at(now());
    if available > now() then
      update public.communication_delivery_intents
      set failure_code = 'sms_quiet_hours',
        failure_message = 'This text is waiting for quiet hours to end before it goes out.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set available_at = available,
        last_error = 'This text is waiting for quiet hours to end before it goes out.'
      where id = candidate.event_id;
      continue;
    end if;

    -- 7. The credit reservation frozen at enqueue must still be holding funds; a released/settled reservation
    --    means this send has already been resolved and must not be sent again.
    -- Fixed 2026-09-23: qualified against the table alias -- was a bare `delivery_intent_id`, ambiguous with
    -- this function's own RETURNS TABLE column of the same name (see migration header).
    select r.state into reservation_state
    from public.communication_sms_credit_reservations r
    where r.delivery_intent_id = candidate.delivery_intent_id;
    if reservation_state is distinct from 'reserved' then
      update public.communication_delivery_intents
      set status = 'cancelled', failure_code = 'sms_reservation_not_held',
        failure_message = 'This text no longer has a held balance and was not sent.'
      where id = candidate.delivery_intent_id;
      update public.communication_outbox_events
      set status = 'cancelled', claimed_at = null, claim_token = null,
        last_error = 'This text no longer has a held balance and was not sent.'
      where id = candidate.event_id;
      continue;
    end if;

    -- Fixed 2026-09-23: same ambiguity as step 7, against communication_sms_message_snapshots.
    select snap.* into snapshot
    from public.communication_sms_message_snapshots snap
    where snap.delivery_intent_id = candidate.delivery_intent_id;

    -- 8. Claim: mark the outbox processing under a fresh token, mark the intent claimed, and record the 'started'
    --    attempt so one attempt exists before the worker's provider call. The attempt number equals the new
    --    outbox attempt_count, so retries append distinct attempt rows.
    new_claim_token := gen_random_uuid();
    new_attempt := candidate.attempt_count + 1;

    update public.communication_outbox_events
    set status = 'processing', claimed_at = now(), claim_token = new_claim_token,
      attempt_count = new_attempt, last_error = null
    where id = candidate.event_id;
    update public.communication_delivery_intents
    set status = 'claimed', failure_code = null, failure_message = null
    where id = candidate.delivery_intent_id;
    insert into public.communication_sms_submission_attempts (
      organization_id, delivery_intent_id, attempt_number, claim_token, provider, outcome
    ) values (
      candidate.organization_id, candidate.delivery_intent_id, new_attempt, new_claim_token, 'twilio', 'started'
    );

    return query select candidate.event_id, candidate.delivery_intent_id, candidate.organization_id,
      account.id, account.subaccount_sid, account.messaging_service_sid, new_claim_token, new_attempt,
      candidate.recipient_phone, sender.phone_number, snapshot.body, snapshot.encoding, snapshot.segment_count;
    return;
  end loop;
end;
$$;


ALTER FUNCTION "public"."claim_communication_sms_outbox_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_form_booking_reservation"("target_organization_id" "uuid", "target_form_id" "uuid", "target_user_id" "uuid", "new_starts_at" timestamp with time zone, "new_ends_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  reservation_id uuid;
begin
  if new_starts_at is null or new_ends_at is null or new_ends_at <= new_starts_at then
    raise exception 'A reservation must end after it starts.' using errcode = 'check_violation';
  end if;

  begin
    insert into private.form_booking_reservations (
      organization_id, form_id, user_id, starts_at, ends_at
    ) values (
      target_organization_id, target_form_id, target_user_id, new_starts_at, new_ends_at
    )
    returning id into reservation_id;
  exception
    when exclusion_violation then
      return null;
  end;

  return reservation_id;
end;
$$;


ALTER FUNCTION "public"."claim_form_booking_reservation"("target_organization_id" "uuid", "target_form_id" "uuid", "target_user_id" "uuid", "new_starts_at" timestamp with time zone, "new_ends_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_form_booking_reservation"("target_organization_id" "uuid", "target_form_id" "uuid", "target_user_id" "uuid", "new_starts_at" timestamp with time zone, "new_ends_at" timestamp with time zone) IS 'Atomically claims {person, window}. Returns the new reservation id, or null if someone already holds an overlapping window for that person -- never raises for the ordinary "lost the race" case.';



CREATE OR REPLACE FUNCTION "public"."claim_invoice_sources"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_sources" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  invoice_row public.invoices;
  property_count integer;
  requested_job_count integer;
  matched_job_count integer;
  entry record;
  reminder_row public.job_invoice_reminders;
  period_start date;
  period_end date;
  visit_row public.job_visits;
  schedule_item_row public.job_payment_schedule_items;
  claimed_count integer := 0;
  consumed_count integer := 0;
begin
  if caller is null then
    raise exception 'You must be signed in to bill work.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.create') then
    raise exception 'You do not have access to bill work here.' using errcode = 'insufficient_privilege';
  end if;

  if new_sources is null or jsonb_typeof(new_sources) <> 'array'
     or jsonb_array_length(new_sources) = 0 then
    raise exception 'Choose at least one piece of work to bill.' using errcode = 'check_violation';
  end if;
  -- The bounded batch Part 2 sized. A larger selection is split rather than held under these locks.
  if jsonb_array_length(new_sources) > 100 then
    raise exception 'An invoice can cover at most 100 pieces of work at once.'
      using errcode = 'check_violation';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'claim_invoice_sources', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  invoice_row := private.lock_invoice_for_edit(
    target_organization_id, target_invoice_id, expected_revision, 'invoices.create'
  );

  if invoice_row.issued_at is not null or invoice_row.recognized_at is not null then
    raise exception 'This bill has already been issued, so the work on it is settled.'
      using errcode = 'check_violation',
      hint = 'Correct the invoice instead; a correction carries the same work forward.';
  end if;
  -- A successor already inherits its chain's claims. Letting it add more would make a correction a way to
  -- bill new work under an old bill's history.
  if invoice_row.id is distinct from invoice_row.root_invoice_id then
    raise exception 'This invoice replaces another one, so it already covers that bill''s work.'
      using errcode = 'check_violation';
  end if;

  property_count := jsonb_array_length(invoice_row.service_properties);

  -- Lock every job this call touches, in id order, before touching any visit. That is the lock order the
  -- job and schedule commands already use, so an invoice and a visit reschedule cannot deadlock each other.
  select count(distinct source.job_id) into requested_job_count
  from jsonb_array_elements(new_sources) as element(value)
  cross join lateral (select nullif(element.value->>'job_id', '')::uuid as job_id) as source;

  -- The lock itself, as its own statement: row locking is not allowed inside a subquery, and the counting
  -- below is a separate question from the ordering that keeps this deadlock-free.
  perform 1
  from public.jobs as job
  where job.organization_id = target_organization_id
    and job.id in (
      select nullif(element.value->>'job_id', '')::uuid
      from jsonb_array_elements(new_sources) as element(value)
    )
  order by job.id
  for share;

  select count(*) into matched_job_count
  from public.jobs as job
  where job.organization_id = target_organization_id
    and job.client_id = invoice_row.client_id
    and job.id in (
      select nullif(element.value->>'job_id', '')::uuid
      from jsonb_array_elements(new_sources) as element(value)
    );

  if requested_job_count = 0 then
    raise exception 'Every piece of billable work belongs to a job.' using errcode = 'check_violation';
  end if;
  if matched_job_count <> requested_job_count then
    raise exception 'One of those jobs does not belong to this invoice''s client.'
      using errcode = 'check_violation';
  end if;

  for entry in
    select
      coalesce(element.value->>'kind', '') as kind,
      nullif(element.value->>'job_id', '')::uuid as job_id,
      nullif(element.value->>'visit_id', '')::uuid as visit_id,
      nullif(element.value->>'reminder_id', '')::uuid as reminder_id,
      nullif(element.value->>'installment_number', '')::integer as installment_number,
      nullif(element.value->>'installment_id', '')::uuid as installment_id,
      nullif(element.value->>'service_property_index', '')::integer as service_property_index
    from jsonb_array_elements(new_sources) as element(value)
    -- A stable processing order so two concurrent batches over overlapping work queue behind each other
    -- rather than each holding half of what the other needs.
    order by 2, 1, 3, 4, 5
  loop
    if entry.kind not in ('job_total', 'visit', 'reminder_period', 'installment') then
      raise exception 'Billable work is a whole job, a visit, a billing period or an installment.'
        using errcode = 'check_violation';
    end if;
    if entry.job_id is null then
      raise exception 'Every piece of billable work names the job it belongs to.'
        using errcode = 'check_violation';
    end if;
    if entry.kind = 'installment' and (entry.installment_number is null or entry.installment_id is null) then
      raise exception 'An installment claim needs its position and identity in the payment schedule.'
        using errcode = 'check_violation';
    end if;
    if entry.service_property_index is not null
       and (entry.service_property_index < 0 or entry.service_property_index >= property_count) then
      raise exception 'That work points at a service address this invoice does not carry.'
        using errcode = 'check_violation';
    end if;

    -- The two exclusive ways to bill one job. Checked before the insert so the contractor gets a sentence
    -- rather than a unique-index violation.
    if entry.kind = 'job_total' then
      if exists (
        select 1 from public.invoice_sources as claim
        where claim.organization_id = target_organization_id and claim.job_id = entry.job_id
      ) then
        raise exception 'Some of this job''s work has already been billed, so it cannot be billed as a whole.'
          using errcode = 'unique_violation',
          hint = 'Bill the remaining visits or periods instead, or void the invoice that already covers it.';
      end if;
    elsif exists (
      select 1 from public.invoice_sources as claim
      where claim.organization_id = target_organization_id
        and claim.job_id = entry.job_id
        and claim.source_kind = 'job_total'
    ) then
      raise exception 'This whole job has already been billed on another invoice.'
        using errcode = 'unique_violation';
    end if;

    if entry.kind = 'visit' then
      select * into visit_row
      from public.job_visits
      where organization_id = target_organization_id
        and id = entry.visit_id
        and job_id = entry.job_id
      for update;
      if not found then
        raise exception 'That visit does not belong to the job being billed.' using errcode = 'P0404';
      end if;

    elsif entry.kind = 'reminder_period' then
      select * into reminder_row
      from public.job_invoice_reminders
      where organization_id = target_organization_id
        and id = entry.reminder_id
        and job_id = entry.job_id
      for update;
      if not found then
        raise exception 'That billing reminder does not belong to the job being billed.'
          using errcode = 'P0404';
      end if;
      if reminder_row.reminder_kind not in ('monthly_last_day', 'custom_date') then
        raise exception 'That reminder covers a single visit, so bill the visit itself.'
          using errcode = 'check_violation';
      end if;

      -- The period's boundaries come from the reminder rows themselves, never from the clock: it runs from
      -- the day after the previous billing reminder up to and including this one's date.
      period_end := reminder_row.due_on;
      select max(previous.due_on) into period_start
      from public.job_invoice_reminders as previous
      where previous.organization_id = target_organization_id
        and previous.job_id = entry.job_id
        and previous.reminder_kind in ('monthly_last_day', 'custom_date')
        and previous.due_on < period_end;
      period_start := coalesce(period_start + 1, '-infinity'::date);

    elsif entry.kind = 'installment' then
      -- The amount is locked by `create_installment_invoice` before this claim is ever attempted, in the
      -- same transaction. Nothing else ever writes `locked_amount_minor`, so seeing it unset here means this
      -- claim was reached some other way — a stage cannot be billed before its amount is final.
      select * into schedule_item_row
      from public.job_payment_schedule_items
      where organization_id = target_organization_id
        and id = entry.installment_id
        and job_id = entry.job_id
      for update;
      if not found then
        raise exception 'That payment stage does not belong to the job being billed.'
          using errcode = 'P0404';
      end if;
      if schedule_item_row.locked_amount_minor is null then
        raise exception 'That payment stage has not been priced and locked yet.'
          using errcode = 'check_violation',
          hint = 'Create the invoice from the job''s Billing card so its amount is locked first.';
      end if;
    end if;

    begin
      insert into public.invoice_sources (
        organization_id, root_invoice_id, client_id, source_kind,
        job_id, visit_id, reminder_id, installment_number, installment_id, service_property_index, claimed_by
      ) values (
        target_organization_id, invoice_row.root_invoice_id, invoice_row.client_id, entry.kind,
        entry.job_id, entry.visit_id, entry.reminder_id, entry.installment_number, entry.installment_id,
        entry.service_property_index, caller
      );
      claimed_count := claimed_count + 1;
    exception when unique_violation then
      raise exception 'That work has already been billed on another invoice.'
        using errcode = 'unique_violation',
        detail = format('%s on job %s', entry.kind, entry.job_id),
        hint = 'Open the invoice that already covers it, or void that invoice and bill this work again.';
    end;

    -- A period bill consumes its own visits. Claiming them here is what stops somebody billing April''s
    -- visits individually next week, and it is done under the same locks as the period claim itself.
    if entry.kind = 'reminder_period' then
      for visit_row in
        select visit.*
        from public.job_visits as visit
        where visit.organization_id = target_organization_id
          and visit.job_id = entry.job_id
          and visit.completed_at is not null
          and visit.visit_date is not null
          and visit.visit_date between period_start and period_end
        order by visit.id
        for update
      loop
        begin
          insert into public.invoice_sources (
            organization_id, root_invoice_id, client_id, source_kind,
            job_id, visit_id, service_property_index, claimed_by
          ) values (
            target_organization_id, invoice_row.root_invoice_id, invoice_row.client_id, 'visit',
            entry.job_id, visit_row.id, entry.service_property_index, caller
          );
          consumed_count := consumed_count + 1;
        exception when unique_violation then
          raise exception 'A visit inside that billing period has already been billed separately.'
            using errcode = 'unique_violation',
            detail = format('visit %s on %s', visit_row.id, visit_row.visit_date),
            hint = 'Bill the remaining periods, or void the invoice that already covers that visit.';
        end;
      end loop;
    end if;
  end loop;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.work_claimed', caller, invoice_row.revision, null,
    jsonb_build_object('claimed_count', claimed_count, 'consumed_visit_count', consumed_count),
    false, null
  );

  return private.complete_invoice_command(
    target_organization_id, 'claim_invoice_sources', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', invoice_row.id,
      'root_invoice_id', invoice_row.root_invoice_id,
      'claimed_count', claimed_count,
      'consumed_visit_count', consumed_count
    )
  );
end;
$$;


ALTER FUNCTION "public"."claim_invoice_sources"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_sources" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_invoice_sources"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_sources" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Attaches source work to a draft invoice''s chain so the same job, visit, billing period or installment cannot be billed twice. A fixed-period claim also consumes the completed visits inside its period.';



CREATE OR REPLACE FUNCTION "public"."claim_member_identity_cleanup"("target_lease_nonce" "uuid", "target_batch_size" integer DEFAULT 25, "target_lease_seconds" integer DEFAULT 300) RETURNS SETOF "public"."organization_members"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if target_batch_size not between 1 and 100 or target_lease_seconds not between 30 and 1800 then
    raise exception 'The identity cleanup lease is outside its safe bounds.'
      using errcode = 'check_violation';
  end if;

  return query
    with claimable as (
      select membership.organization_id, membership.user_id
      from public.organization_members as membership
      where membership.identity_cleanup_state in ('required', 'ban_applied', 'email_released')
        and (
          membership.identity_cleanup_lease_expires_at is null
          or membership.identity_cleanup_lease_expires_at < now()
        )
      order by
        coalesce(membership.identity_cleanup_lease_expires_at, '-infinity'::timestamptz),
        membership.removed_at,
        membership.user_id
      limit target_batch_size
      for update skip locked
    )
    update public.organization_members as membership
    set identity_cleanup_nonce = target_lease_nonce,
        identity_cleanup_lease_expires_at = now() + make_interval(secs => target_lease_seconds)
    from claimable
    where membership.organization_id = claimable.organization_id
      and membership.user_id = claimable.user_id
    returning membership.*;
end;
$$;


ALTER FUNCTION "public"."claim_member_identity_cleanup"("target_lease_nonce" "uuid", "target_batch_size" integer, "target_lease_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_member_identity_cleanup"("target_lease_nonce" "uuid", "target_batch_size" integer, "target_lease_seconds" integer) IS 'Leases a bounded batch of removed members whose Auth cleanup is unfinished. Concurrent runs skip each other''s rows instead of waiting.';



CREATE OR REPLACE FUNCTION "public"."claim_onboarding_application_provision"("target_application_id" "uuid", "stale_after" interval DEFAULT '00:02:00'::interval) RETURNS TABLE("claim_status" "text", "organization_id" "uuid", "administrator_user_id" "uuid", "attempt_count" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  did_insert boolean;
  row_data public.platform_onboarding_application_provisions%rowtype;
begin
  insert into public.platform_onboarding_application_provisions (application_id, status, attempt_count)
  values (target_application_id, 'pending', 1)
  on conflict (application_id) do nothing
  returning true into did_insert;

  if did_insert then
    return query select 'claimed'::text, null::uuid, null::uuid, 1;
    return;
  end if;

  select * into row_data
  from public.platform_onboarding_application_provisions
  where application_id = target_application_id
  for update;

  if row_data.status = 'succeeded' then
    return query
      select 'already_succeeded'::text, row_data.organization_id, row_data.administrator_user_id,
        row_data.attempt_count;
    return;
  end if;

  if row_data.status = 'pending' and row_data.updated_at > (now() - stale_after) then
    return query select 'in_progress'::text, null::uuid, null::uuid, row_data.attempt_count;
    return;
  end if;

  update public.platform_onboarding_application_provisions
  set status = 'pending', attempt_count = row_data.attempt_count + 1, last_error = null
  where application_id = target_application_id;

  return query
    select 'claimed'::text, null::uuid, row_data.administrator_user_id, row_data.attempt_count + 1;
end;
$$;


ALTER FUNCTION "public"."claim_onboarding_application_provision"("target_application_id" "uuid", "stale_after" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_pending_organization_for_geocoding"() RETURNS TABLE("organization_id" "uuid", "address_line1" "text", "city" "text", "region" "text", "postal_code" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select s.organization_id, s.address_line1, s.city, s.region, s.postal_code
  from public.organization_settings as s
  where s.location_geocode_status = 'pending' and s.address_line1 is not null
  order by s.updated_at
  for update skip locked
  limit 1;
$$;


ALTER FUNCTION "public"."claim_pending_organization_for_geocoding"() OWNER TO "postgres";


