CREATE OR REPLACE FUNCTION "public"."claim_team_invitation"("target_token_hash" "text", "target_email" "text", "target_lease_nonce" "uuid", "target_lease_seconds" integer DEFAULT 900) RETURNS TABLE("claimed" boolean, "invitation_id" "uuid", "organization_id" "uuid", "invited_user_id" "uuid", "role" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_row public.organization_member_invitations;
begin
  update public.organization_member_invitations
  set state = 'accepting',
      lease_nonce = target_lease_nonce,
      lease_expires_at = now() + make_interval(secs => target_lease_seconds)
  where token_hash = target_token_hash
    and lower(invited_email) = lower(target_email)
    and expires_at > now()
    and (
      state = 'invited'
      or (
        state = 'accepting'
        and lease_expires_at < now()
        and password_set_at is null
        and identity_cleanup_state = 'not_required'
      )
    )
  returning * into updated_row;

  if found then
    return query
      select true, updated_row.id, updated_row.organization_id, updated_row.invited_user_id, updated_row.role;
  else
    return query select false, null::uuid, null::uuid, null::uuid, null::text;
  end if;
end;
$$;


ALTER FUNCTION "public"."claim_team_invitation"("target_token_hash" "text", "target_email" "text", "target_lease_nonce" "uuid", "target_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_team_invitation_reconciliation"("target_lease_nonce" "uuid", "target_batch_size" integer DEFAULT 25, "target_lease_seconds" integer DEFAULT 300) RETURNS SETOF "public"."organization_member_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if target_batch_size not between 1 and 100 or target_lease_seconds not between 30 and 1800 then
    raise exception 'The reconciliation lease is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  return query
    with claimable as (
      select invitation.id
      from public.organization_member_invitations as invitation
      where invitation.identity_cleanup_state = 'required'
        and (
          invitation.reconciliation_lease_expires_at is null
          or invitation.reconciliation_lease_expires_at < now()
        )
      order by
        coalesce(invitation.reconciliation_lease_expires_at, '-infinity'::timestamptz),
        invitation.created_at,
        invitation.id
      limit target_batch_size
      for update skip locked
    )
    update public.organization_member_invitations as invitation
    set reconciliation_nonce = target_lease_nonce,
        reconciliation_lease_expires_at = now() + make_interval(secs => target_lease_seconds)
    from claimable
    where invitation.id = claimable.id
    returning invitation.*;
end;
$$;


ALTER FUNCTION "public"."claim_team_invitation_reconciliation"("target_lease_nonce" "uuid", "target_batch_size" integer, "target_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_team_notification_emails"("p_batch_size" integer DEFAULT 25, "p_lease_seconds" integer DEFAULT 120) RETURNS TABLE("notification_id" "uuid", "claim_token" "uuid", "organization_id" "uuid", "organization_name" "text", "recipient_email" "text", "kind" "text", "subject_type" "text", "subject_id" "uuid", "title" "text", "body" "text", "attempts" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  candidate record;
  token uuid;
begin
  if p_batch_size < 1 or p_batch_size > 100 or p_lease_seconds < 30 or p_lease_seconds > 900 then
    raise exception 'The alert email claim is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  for candidate in
    select q.id, q.organization_id, q.user_id, q.kind, q.subject_type, q.subject_id, q.title, q.body,
      q.email_attempts, o.name as organization_name, nullif(btrim(u.email), '') as email
    from public.team_notifications as q
    join public.organizations as o on o.id = q.organization_id
    left join auth.users as u on u.id = q.user_id
    where q.email_state = 'pending' and q.email_available_at <= now()
      and (q.email_claimed_until is null or q.email_claimed_until < now())
    order by q.email_available_at, q.id
    limit p_batch_size
    for update of q skip locked
  loop
    if candidate.email is null
      or not private.member_receives_inquiry_alerts(candidate.organization_id, candidate.user_id) then
      update public.team_notifications
      set email_state = 'not_needed', email_claim_token = null, email_claimed_until = null
      where id = candidate.id;
      continue;
    end if;

    token := gen_random_uuid();
    update public.team_notifications
    set email_claim_token = token, email_claimed_until = now() + make_interval(secs => p_lease_seconds)
    where id = candidate.id;

    notification_id := candidate.id;
    claim_token := token;
    organization_id := candidate.organization_id;
    organization_name := candidate.organization_name;
    recipient_email := candidate.email;
    kind := candidate.kind;
    subject_type := candidate.subject_type;
    subject_id := candidate.subject_id;
    title := candidate.title;
    body := candidate.body;
    attempts := candidate.email_attempts;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."claim_team_notification_emails"("p_batch_size" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."client_account_balance"("target_client_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  organizations uuid[];
  org uuid;
  answer jsonb;
begin
  if target_client_ids is null or cardinality(target_client_ids) = 0 then
    return '{}'::jsonb;
  end if;

  select array_agg(distinct client.organization_id) into organizations
  from public.clients as client
  where client.id = any(target_client_ids);

  if organizations is null then
    return '{}'::jsonb;
  end if;
  if array_length(organizations, 1) > 1 then
    raise exception 'Those clients do not belong to one organization.' using errcode = 'check_violation';
  end if;
  org := organizations[1];

  if not private.member_has_permission(org, caller, 'invoices.view') then
    raise exception 'You do not have access to these clients'' billing.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(org, caller, 'invoices.view_price') then
    return '{}'::jsonb;
  end if;

  select coalesce(jsonb_object_agg(client.id::text, jsonb_build_object(
      'currency_code', settings.currency_code,
      'outstanding_minor', outstanding.amount_minor + coalesce(opening.receivable_minor, 0),
      'available_credit_minor', credit.amount_minor + coalesce(opening.credit_minor, 0),
      'account_balance_minor',
        (outstanding.amount_minor + coalesce(opening.receivable_minor, 0))
        - (credit.amount_minor + coalesce(opening.credit_minor, 0))
    )), '{}'::jsonb)
  into answer
  from public.clients as client
  cross join public.organization_settings as settings
  -- What the effective bills still ask for. The partial index on is_effective_receivable is what keeps this
  -- to the client's open ledger instead of their whole billing history.
  cross join lateral (
    select coalesce(sum(invoice.total_minor - coalesce(entry.applied_minor, 0)), 0)::bigint as amount_minor
    from public.invoices as invoice
    left join lateral (
      select sum(case when entry.entry_type = 'applied'
        then entry.amount_minor else -entry.amount_minor end) as applied_minor
      from public.invoice_payment_allocations as entry
      where entry.organization_id = invoice.organization_id
        and entry.invoice_id = invoice.id
    ) as entry on true
    where invoice.organization_id = client.organization_id
      and invoice.client_id = client.id
      and invoice.is_effective_receivable
  ) as outstanding
  cross join lateral (
    select (
      -- Manual receipts that were not reversed away.
      coalesce((
        select sum(receipt.amount_minor)
        from public.client_payment_events as receipt
        where receipt.organization_id = client.organization_id
          and receipt.client_id = client.id
          and receipt.event_type = 'received'
          and not exists (
            select 1 from public.client_payment_events as correction
            where correction.organization_id = receipt.organization_id
              and correction.original_event_id = receipt.id
              and correction.event_type = 'reversed'
          )
      ), 0)
      -- Quote deposits, reused where they already live, minus the ones the quote workspace reversed.
      + coalesce((
        select sum(deposit.amount_minor)
        from public.quote_deposit_events as deposit
        join public.quotes as quote
          on quote.organization_id = deposit.organization_id and quote.id = deposit.quote_id
        where deposit.organization_id = client.organization_id
          and quote.client_id = client.id
          and deposit.event_type = 'received'
          and not exists (
            select 1 from public.quote_deposit_events as reversal
            where reversal.organization_id = deposit.organization_id
              and reversal.reversed_event_id = deposit.id
          )
      ), 0)
      -- Money actually sent back is no longer the client's to spend.
      - coalesce((
        select sum(refund.amount_minor)
        from public.client_payment_events as refund
        where refund.organization_id = client.organization_id
          and refund.client_id = client.id
          and refund.event_type = 'refunded'
      ), 0)
      -- Money committed to a bill is not available, whichever kind of receipt it came from.
      - coalesce((
        select sum(case when entry.entry_type = 'applied'
          then entry.amount_minor else -entry.amount_minor end)
        from public.invoice_payment_allocations as entry
        where entry.organization_id = client.organization_id
          and entry.client_id = client.id
      ), 0)
    )::bigint as amount_minor
  ) as credit
  left join lateral (
    select receivable_minor, credit_minor
    from private.client_opening_balance_totals(org, array[client.id])
  ) as opening on true
  where client.organization_id = org
    and client.id = any(target_client_ids)
    and settings.organization_id = org;

  return answer;
end;
$$;


ALTER FUNCTION "public"."client_account_balance"("target_client_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."client_account_balance"("target_client_ids" "uuid"[]) IS 'The two client-level money numbers the contract keeps apart: what their effective bills still ask for, and money of theirs that is neither refunded nor already committed to a bill -- each widened by the Client''s active opening-balance facts. Never counts a receipt twice and never counts a voided, superseded, written-off or replaced fact.';



CREATE OR REPLACE FUNCTION "public"."client_billable_work"("target_organization_id" "uuid", "target_client_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  today date;
  billable jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to bill work.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.create') then
    raise exception 'You do not have access to bill work here.' using errcode = 'insufficient_privilege';
  end if;
  -- The picker's whole purpose is to compare amounts before choosing. A reader who cannot see job prices
  -- would get a list of blanks, which is worse than an honest refusal.
  if not private.member_has_permission(target_organization_id, caller, 'jobs.view_price') then
    raise exception 'You do not have access to job prices, so there is nothing to compare here.'
      using errcode = 'insufficient_privilege';
  end if;

  select calendar.today into today
  from private.organization_calendars() as calendar
  where calendar.organization_id = target_organization_id;

  select coalesce(jsonb_agg(entry order by entry->>'created_at' desc), '[]'::jsonb) into billable
  from (
    select jsonb_build_object(
      'job_id', job.id,
      'job_number', job.job_number,
      'title', job.title,
      'job_type', job.job_type,
      'created_at', job.created_at,
      'currency_code', job.currency_code,
      'derived_status', private.job_derived_status(
        job.status,
        job.job_type,
        job.contract_end_date,
        today,
        exists (
          select 1
          from public.job_invoice_reminders as reminder
          where reminder.organization_id = job.organization_id
            and reminder.job_id = job.id
            and reminder.status = 'pending'
            and reminder.due_on <= today
        )
      ),
      'property_id', job.property_id,
      'property_label', property.label,
      'property_address_line1', property.address_line1,
      'property_city', property.city,
      'property_state_region', property.state_region,
      'property_postal_code', property.postal_code,
      'subtotal_minor', job.subtotal_minor,
      -- Nothing on this job has been billed -- that is the only way it reaches this list -- so everything it
      -- is worth is still uninvoiced. 5b's per-visit billing is what makes these two figures diverge.
      'uninvoiced_minor', job.total_minor,
      'total_minor', job.total_minor,
      'line_count', (
        select count(*) from public.job_line_items as line
        where line.organization_id = job.organization_id
          and line.job_id = job.id
          and line.line_kind = 'priced'
      ),
      'last_visit_date', visits.last_visit_date,
      'visit_count', coalesce(visits.visit_count, 0),
      'completed_visit_count', coalesce(visits.completed_visit_count, 0),
      -- The reminder that put this job in "Requires invoicing", so the screen can say why it is here and the
      -- command below knows which prompt this bill answers.
      'due_reminder_id', (
        select reminder.id
        from public.job_invoice_reminders as reminder
        where reminder.organization_id = job.organization_id
          and reminder.job_id = job.id
          and reminder.status = 'pending'
          and reminder.due_on <= today
        order by reminder.due_on, reminder.id
        limit 1
      )
    ) as entry
    from public.jobs as job
    left join public.properties as property
      on property.organization_id = job.organization_id and property.id = job.property_id
    left join lateral (
      select
        max(visit.visit_date) as last_visit_date,
        count(*) as visit_count,
        count(*) filter (where visit.completed_at is not null) as completed_visit_count
      from public.job_visits as visit
      where visit.organization_id = job.organization_id and visit.job_id = job.id
    ) as visits on true
    where job.organization_id = target_organization_id
      and job.client_id = target_client_id
      -- Any claim at all disqualifies the job from being billed as a whole, which is the same rule
      -- claim_invoice_sources enforces. Checking it here means the picker never offers work the next screen
      -- would refuse.
      and not exists (
        select 1
        from public.invoice_sources as claim
        where claim.organization_id = job.organization_id
          and claim.job_id = job.id
      )
    order by job.created_at desc, job.id
    limit 100
  ) as candidates;

  return billable;
end;
$$;


ALTER FUNCTION "public"."client_billable_work"("target_organization_id" "uuid", "target_client_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."client_billable_work"("target_organization_id" "uuid", "target_client_id" "uuid") IS 'Every job of one client that no invoice has claimed yet, with the figures the "select work to invoice" picker compares. Scoped to one client and capped at the 100 sources one invoice can claim. Needs invoices.create and jobs.view_price.';



CREATE OR REPLACE FUNCTION "public"."client_spendable_credit"("target_organization_id" "uuid", "target_client_id" "uuid") RETURNS TABLE("source" "text", "source_id" "uuid", "quote_id" "uuid", "quote_number" integer, "method" "text", "reference" "text", "currency_code" "text", "amount_minor" bigint, "available_minor" bigint, "received_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
begin
  if caller is null then
    raise exception 'You must be signed in to see a client''s credit.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.record_payment') then
    raise exception 'You do not have access to apply payments here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  return query
  select spendable.source, spendable.source_id, spendable.quote_id, spendable.quote_number,
    spendable.method, spendable.reference, spendable.currency_code, spendable.amount_minor,
    spendable.available_minor, spendable.received_at
  from (
    select 'payment'::text as source, receipt.id as source_id, null::uuid as quote_id,
      null::integer as quote_number, receipt.method, receipt.reference, receipt.currency_code,
      receipt.amount_minor::bigint as amount_minor,
      private.payment_event_available_minor(receipt.organization_id, receipt.id) as available_minor,
      receipt.created_at as received_at
    from public.client_payment_events as receipt
    where receipt.organization_id = target_organization_id
      and receipt.client_id = target_client_id
      and receipt.event_type = 'received'

    union all

    select 'deposit'::text, deposit.id, quote.id, quote.quote_number, deposit.method, deposit.reference,
      quote.currency_code, deposit.amount_minor::bigint,
      private.deposit_event_available_minor(deposit.organization_id, deposit.id),
      deposit.created_at
    from public.quote_deposit_events as deposit
    join public.quotes as quote
      on quote.organization_id = deposit.organization_id and quote.id = deposit.quote_id
    where deposit.organization_id = target_organization_id
      and quote.client_id = target_client_id
      and deposit.event_type = 'received'
  ) as spendable
  where spendable.available_minor > 0
  order by spendable.received_at, spendable.source_id;
end;
$$;


ALTER FUNCTION "public"."client_spendable_credit"("target_organization_id" "uuid", "target_client_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."client_spendable_credit"("target_organization_id" "uuid", "target_client_id" "uuid") IS 'Lists the payments and quote deposits a client has given that still have money left to put on a bill, with how much is left on each.';



CREATE OR REPLACE FUNCTION "public"."clone_quote_version_to_draft"("target_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  source_row public.quote_versions;
  new_draft public.quote_versions;
begin
  select * into quote_row from public.quotes where id = target_quote_id for update;
  if quote_row.id is null or not private.member_has_permission(
    quote_row.organization_id, (select auth.uid()), 'quotes.edit'
  ) then
    raise exception 'You do not have access to revise this quote.' using errcode = 'insufficient_privilege';
  end if;
  if quote_row.draft_version_id is not null then
    raise exception 'This quote already has a draft.' using errcode = 'P0409';
  end if;
  select * into source_row from public.quote_versions
  where organization_id = quote_row.organization_id and id = quote_row.current_published_version_id
  for share;
  if source_row.id is null or source_row.status <> 'published' then
    raise exception 'This quote has no published version to revise.' using errcode = 'check_violation';
  end if;

  insert into public.quote_versions (
    organization_id, quote_id, version_number, status, currency_code, client_display_name,
    organization_name, logo_object_key, brand_color, service_address_line1, service_address_line2,
    service_city, service_state_region, service_postal_code, service_country, subtotal_minor, created_by,
    revision, contract_disclaimer, introduction, client_message, show_quantities, show_unit_prices,
    show_line_totals, show_totals, discount_name, discount_type, discount_value, tax_name,
    tax_rate_basis_points, representative_enabled, representative_name, representative_title,
    representative_signature_object_key, require_customer_signature
  ) values (
    source_row.organization_id, source_row.quote_id, 0, 'draft', source_row.currency_code,
    source_row.client_display_name, source_row.organization_name, source_row.logo_object_key,
    source_row.brand_color, source_row.service_address_line1,
    source_row.service_address_line2, source_row.service_city, source_row.service_state_region,
    source_row.service_postal_code, source_row.service_country, source_row.subtotal_minor,
    (select auth.uid()), 1, source_row.contract_disclaimer, source_row.introduction,
    source_row.client_message, source_row.show_quantities, source_row.show_unit_prices,
    source_row.show_line_totals, source_row.show_totals, source_row.discount_name,
    source_row.discount_type, source_row.discount_value, source_row.tax_name, source_row.tax_rate_basis_points,
    source_row.representative_enabled, source_row.representative_name, source_row.representative_title,
    source_row.representative_signature_object_key, source_row.require_customer_signature
  ) returning * into new_draft;

  insert into public.quote_version_lines (
    organization_id, quote_id, quote_version_id, position, source_catalog_item_id, category, is_labor,
    name, description, unit_label, quantity, unit_price_minor, unit_cost_minor, is_taxable,
    image_attachment_id, line_kind, selection_kind, is_recommended
  ) select line.organization_id, line.quote_id, new_draft.id, line.position,
    line.source_catalog_item_id, line.category, line.is_labor, line.name, line.description,
    line.unit_label, line.quantity, line.unit_price_minor, line.unit_cost_minor, line.is_taxable,
    line.image_attachment_id, line.line_kind, line.selection_kind, line.is_recommended
  from public.quote_version_lines line
  where line.quote_version_id = source_row.id order by line.position, line.id;

  insert into public.quote_version_attachments (
    organization_id, quote_id, quote_version_id, attachment_id, position, customer_visible, display_name
  ) select organization_id, quote_id, new_draft.id, attachment_id, position, customer_visible, display_name
  from public.quote_version_attachments where quote_version_id = source_row.id order by position, id;

  perform private.refresh_quote_draft_totals(new_draft.id);

  update public.quotes set draft_version_id = new_draft.id where id = quote_row.id;
  return jsonb_build_object('quote_id', quote_row.id, 'quote_version_id', new_draft.id, 'revision', 1);
end;
$$;


ALTER FUNCTION "public"."clone_quote_version_to_draft"("target_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_job"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  incomplete_count integer;
  new_reminder_id uuid;
begin
  if caller is null then
    raise exception 'You must be signed in to close a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.close') then
    raise exception 'You do not have access to close this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id
  for update;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  if current_job.status = 'closed' then
    return jsonb_build_object('applied', true, 'already_closed', true, 'revision', current_job.revision);
  end if;
  if current_job.revision is distinct from expected_revision then
    raise exception 'Someone else changed this job. Reload to see the latest.' using errcode = 'P0409';
  end if;

  select count(*) into incomplete_count
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.completed_at is null;
  if incomplete_count > 0 then
    raise exception
      'This job still has % incomplete visit(s). Finish or remove them before closing.', incomplete_count
      using errcode = 'check_violation';
  end if;

  update public.jobs
  set status = 'closed', revision = current_job.revision + 1, updated_at = now()
  where organization_id = target_organization_id and id = target_job_id;

  if current_job.billing_timing = 'on_closure' then
    new_reminder_id := private.create_invoice_reminder(
      target_organization_id,
      target_job_id,
      'on_completion',
      private.organization_today(target_organization_id),
      caller
    );
  end if;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, new_status, metadata)
  values (target_organization_id, target_job_id, 'job_closed', caller, 'closed', '{}'::jsonb);

  return jsonb_build_object(
    'applied', true,
    'already_closed', false,
    'revision', current_job.revision + 1,
    'reminder_id', new_reminder_id
  );
end;
$$;


ALTER FUNCTION "public"."close_job"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."close_job"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer) IS 'Closes a job that has zero incomplete visits. Checks jobs.close, refuses a stale revision (P0409) and a job with incomplete visits still open (check_violation), is idempotent on an already-closed job, and fires the on_completion reminder when the job bills on closure.';



CREATE OR REPLACE FUNCTION "public"."close_ownership_transfer"("target_transfer_id" "uuid", "actor_user_id" "uuid") RETURNS "public"."organization_ownership_transfers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  transfer public.organization_ownership_transfers;
  closed_state text;
  closed_event text;
begin
  select * into transfer
  from public.organization_ownership_transfers
  where id = target_transfer_id
  for update;

  if not found then
    raise exception 'That ownership handover no longer exists.' using errcode = 'no_data_found';
  end if;

  perform pg_advisory_xact_lock(hashtext('ownership_transfer:' || transfer.organization_id::text));

  if transfer.state <> 'pending' then
    raise exception 'That ownership handover has already been answered.' using errcode = 'check_violation';
  end if;

  if actor_user_id = transfer.from_user_id then
    closed_state := 'cancelled';
    closed_event := 'ownership.transfer_cancelled';
  elsif actor_user_id = transfer.to_user_id then
    closed_state := 'declined';
    closed_event := 'ownership.transfer_declined';
  else
    raise exception 'Only the owner who asked or the person asked can end a handover.'
      using errcode = 'check_violation';
  end if;

  update public.organization_ownership_transfers
  set state = closed_state,
      resolved_at = now(),
      resolved_by = actor_user_id
  where id = transfer.id
  returning * into transfer;

  -- The recipient stays the subject even when the owner cancels, so all four events read as one story on
  -- that person's team history.
  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    transfer.organization_id, closed_event, 'member', actor_user_id, transfer.to_user_id,
    jsonb_build_object('transfer_id', transfer.id)
  );

  return transfer;
end;
$$;


ALTER FUNCTION "public"."close_ownership_transfer"("target_transfer_id" "uuid", "actor_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."close_ownership_transfer"("target_transfer_id" "uuid", "actor_user_id" "uuid") IS 'Ends a pending handover. The requester closing it is a cancellation, the recipient closing it is a decline -- the database decides which, so the history can never be mislabelled.';



CREATE OR REPLACE FUNCTION "public"."collect_job_signature"("target_organization_id" "uuid", "target_job_id" "uuid", "new_signature_type" "text", "new_signer_name" "text", "new_statement" "text", "new_method" "text", "new_signer_role" "text" DEFAULT NULL::"text", "target_visit_id" "uuid" DEFAULT NULL::"uuid", "new_image_object_key" "text" DEFAULT NULL::"text", "new_image_byte_size" integer DEFAULT NULL::integer, "supplied_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  job_row public.jobs;
  visit_row public.job_visits;
  clean_signer text;
  clean_role text;
  clean_statement text;
  snapshot jsonb;
  snapshot_hash text;
  new_signature public.job_signatures;
begin
  if caller is null then
    raise exception 'You must be signed in to collect a signature.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'field_records.record')
    and not private.member_has_permission(target_organization_id, caller, 'field_records.manage_team') then
    raise exception 'You do not have access to collect a signature.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.can_view_job(target_organization_id, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  if new_signature_type is null
    or new_signature_type not in ('work_authorization', 'work_completion', 'other') then
    raise exception 'That is not a kind of signature.' using errcode = 'P0400';
  end if;

  clean_signer := nullif(trim(coalesce(new_signer_name, '')), '');
  if clean_signer is null or char_length(clean_signer) > 120 then
    raise exception 'A signature needs the name of the person signing.' using errcode = 'P0400';
  end if;

  clean_role := nullif(trim(coalesce(new_signer_role, '')), '');
  if clean_role is not null and char_length(clean_role) > 60 then
    raise exception 'That description of the signer is too long.' using errcode = 'P0400';
  end if;

  clean_statement := nullif(trim(coalesce(new_statement, '')), '');
  if clean_statement is null or char_length(clean_statement) > 500 then
    raise exception 'A signature needs the sentence the signer is agreeing to.' using errcode = 'P0400';
  end if;

  if new_method is null or new_method not in ('typed', 'drawn') then
    raise exception 'That is not a way to sign.' using errcode = 'P0400';
  end if;
  if (new_method = 'drawn') <> (new_image_object_key is not null)
    or (new_image_object_key is null) <> (new_image_byte_size is null) then
    raise exception 'That signature is incomplete.' using errcode = 'P0400';
  end if;

  if target_visit_id is not null then
    select * into visit_row
    from public.job_visits
    where organization_id = target_organization_id
      and id = target_visit_id
      and job_id = target_job_id;
    if not found then
      raise exception 'That visit is not on this job.' using errcode = 'P0404';
    end if;
  end if;

  select * into job_row
  from public.jobs
  where organization_id = target_organization_id and id = target_job_id
  for update;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  snapshot := private.job_document_snapshot(target_organization_id, target_job_id);
  snapshot_hash := encode(extensions.digest(snapshot::text, 'sha256'), 'hex');

  insert into public.job_signatures (
    organization_id, job_id, visit_id, signature_type, signer_name, signer_role, statement, method,
    document_snapshot, document_hash, image_object_key, image_byte_size, evidence, collected_by
  ) values (
    target_organization_id, target_job_id, target_visit_id, new_signature_type, clean_signer, clean_role,
    clean_statement, new_method, snapshot, snapshot_hash, new_image_object_key, new_image_byte_size,
    coalesce(supplied_evidence, '{}'::jsonb), caller
  )
  returning * into new_signature;

  insert into public.activity_events (
    organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
  ) values (
    target_organization_id,
    case when target_visit_id is null then 'job' else 'visit' end,
    coalesce(target_visit_id, target_job_id),
    'job.signature_collected',
    'Collected ' || clean_signer || '''s signature ('
      || case new_signature_type
           when 'work_authorization' then 'work authorization'
           when 'work_completion' then 'work completion'
           else 'other'
         end
      || ')',
    caller,
    jsonb_build_object(
      'job_id', target_job_id,
      'signature_type', new_signature_type,
      'method', new_method,
      'visit_id', target_visit_id,
      'has_image', new_image_object_key is not null
    )
  );

  return jsonb_build_object(
    'id', new_signature.id,
    'collected_at', new_signature.collected_at,
    'has_image', new_signature.image_object_key is not null
  );
end;
$$;


ALTER FUNCTION "public"."collect_job_signature"("target_organization_id" "uuid", "target_job_id" "uuid", "new_signature_type" "text", "new_signer_name" "text", "new_statement" "text", "new_method" "text", "new_signer_role" "text", "target_visit_id" "uuid", "new_image_object_key" "text", "new_image_byte_size" integer, "supplied_evidence" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."collect_job_signature"("target_organization_id" "uuid", "target_job_id" "uuid", "new_signature_type" "text", "new_signer_name" "text", "new_statement" "text", "new_method" "text", "new_signer_role" "text", "target_visit_id" "uuid", "new_image_object_key" "text", "new_image_byte_size" integer, "supplied_evidence" "jsonb") IS 'Records a signature against a job, freezing the job document and its hash onto the row. Needs field_records.record. Staff-collected only -- there is no customer-facing path to this, and no way to undo it afterwards.';



CREATE TABLE IF NOT EXISTS "public"."import_batches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "entity_type" "text" DEFAULT 'client'::"text" NOT NULL,
    "created_by" "uuid",
    "source_filename" "text" NOT NULL,
    "storage_object_key" "text" NOT NULL,
    "file_row_count" integer,
    "match_action" "text" DEFAULT 'skip'::"text" NOT NULL,
    "column_mapping" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'uploaded'::"text" NOT NULL,
    "consent_affirmed_at" timestamp with time zone,
    "created_count" integer DEFAULT 0 NOT NULL,
    "updated_count" integer DEFAULT 0 NOT NULL,
    "skipped_count" integer DEFAULT 0 NOT NULL,
    "held_count" integer DEFAULT 0 NOT NULL,
    "error_count" integer DEFAULT 0 NOT NULL,
    "error_file_object_key" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "import_batches_created_count_check" CHECK (("created_count" >= 0)),
    CONSTRAINT "import_batches_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['client'::"text", 'opening_balance'::"text"]))),
    CONSTRAINT "import_batches_error_count_check" CHECK (("error_count" >= 0)),
    CONSTRAINT "import_batches_error_file_object_key_check" CHECK ((("error_file_object_key" IS NULL) OR ("char_length"("error_file_object_key") <= 512))),
    CONSTRAINT "import_batches_file_row_count_check" CHECK ((("file_row_count" IS NULL) OR ("file_row_count" >= 0))),
    CONSTRAINT "import_batches_held_count_check" CHECK (("held_count" >= 0)),
    CONSTRAINT "import_batches_match_action_check" CHECK (("match_action" = ANY (ARRAY['skip'::"text", 'update'::"text"]))),
    CONSTRAINT "import_batches_skipped_count_check" CHECK (("skipped_count" >= 0)),
    CONSTRAINT "import_batches_source_filename_check" CHECK ((("char_length"("source_filename") >= 1) AND ("char_length"("source_filename") <= 260))),
    CONSTRAINT "import_batches_status_check" CHECK (("status" = ANY (ARRAY['uploaded'::"text", 'mapped'::"text", 'reviewed'::"text", 'importing'::"text", 'completed'::"text", 'failed'::"text", 'canceled'::"text"]))),
    CONSTRAINT "import_batches_storage_object_key_check" CHECK ((("char_length"("storage_object_key") >= 1) AND ("char_length"("storage_object_key") <= 512))),
    CONSTRAINT "import_batches_updated_count_check" CHECK (("updated_count" >= 0))
);


ALTER TABLE "public"."import_batches" OWNER TO "postgres";


COMMENT ON TABLE "public"."import_batches" IS 'One uploaded import file: its R2 location, column mapping, match action, consent affirmation, and running per-outcome counts. Read directly by the import screens (RLS); written only by the import /api RPCs and the service-role worker.';



COMMENT ON COLUMN "public"."import_batches"."entity_type" IS 'What this batch imports. ''client'' creates/updates Clients (Part 1). ''opening_balance'' writes public.client_opening_balances facts (financial reconciliation Part 6) and never touches Job, Invoice, or Payment history.';



CREATE OR REPLACE FUNCTION "public"."commit_import_batch"("payload" "jsonb") RETURNS "public"."import_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_batch_id uuid := (payload->>'batch_id')::uuid;
  target_batch public.import_batches;
  consent_affirmed boolean := coalesce((payload->>'consent_affirmed')::boolean, false);
  skipped integer;
  held integer;
  errored integer;
  to_import integer;
begin
  if target_batch_id is null then
    raise exception 'batch_id is required.' using errcode = 'invalid_parameter_value';
  end if;

  select * into target_batch from public.import_batches where id = target_batch_id for update;
  if not found then
    raise exception 'That import was not found.' using errcode = 'no_data_found';
  end if;

  if not private.has_permission(target_batch.organization_id, 'customers.create') then
    raise exception 'You do not have permission to change this import.'
      using errcode = 'insufficient_privilege';
  end if;

  if target_batch.status <> 'reviewed' then
    raise exception 'This import can no longer be committed.'
      using errcode = 'invalid_parameter_value';
  end if;

  if not consent_affirmed then
    raise exception 'Confirm these contacts agreed to hear from you before importing.'
      using errcode = 'check_violation';
  end if;

  update public.import_rows
  set status = case planned_action
    when 'create' then 'ready'
    when 'update' then 'ready'
    when 'skip' then 'skipped'
    when 'hold' then 'held'
    when 'error' then 'failed'
    else status
  end
  where batch_id = target_batch_id
    and status = 'pending_review';

  select
    count(*) filter (where planned_action = 'skip'),
    count(*) filter (where planned_action = 'hold'),
    count(*) filter (where planned_action = 'error'),
    count(*) filter (where planned_action in ('create', 'update'))
  into skipped, held, errored, to_import
  from public.import_rows
  where batch_id = target_batch_id;

  update public.import_batches
  set consent_affirmed_at = now(),
      skipped_count = skipped,
      held_count = held,
      error_count = errored,
      status = case when to_import = 0 then 'completed' else 'importing' end
  where id = target_batch_id
  returning * into target_batch;

  return target_batch;
end;
$$;


ALTER FUNCTION "public"."commit_import_batch"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."commit_import_batch"("payload" "jsonb") IS 'Commits a reviewed client import in one transaction: refuses without an affirmed consent flag (and stamps consent_affirmed_at), settles skip/hold/error rows to their final status, queues create/update rows as ''ready'' for the step-5b worker, and seeds the batch''s skipped/held/error counts. Moves the batch to ''importing'', or straight to ''completed'' when there is nothing to drain. Backstops the caller permission against the batch''s own org (rule 12; SECURITY DEFINER).';



CREATE OR REPLACE FUNCTION "public"."commit_opening_balance_import_batch"("payload" "jsonb") RETURNS "public"."import_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_batch_id uuid := (payload->>'batch_id')::uuid;
  target_batch public.import_batches;
  held integer;
  errored integer;
  to_import integer;
begin
  if target_batch_id is null then
    raise exception 'batch_id is required.' using errcode = 'invalid_parameter_value';
  end if;

  select * into target_batch from public.import_batches where id = target_batch_id for update;
  if not found then
    raise exception 'That import was not found.' using errcode = 'no_data_found';
  end if;

  if target_batch.entity_type <> 'opening_balance' then
    raise exception 'This import is not an opening-balances import.' using errcode = 'invalid_parameter_value';
  end if;

  if not private.has_permission(target_batch.organization_id, 'invoices.create') then
    raise exception 'You do not have permission to change this import.'
      using errcode = 'insufficient_privilege';
  end if;

  if target_batch.status <> 'reviewed' then
    raise exception 'This import can no longer be committed.'
      using errcode = 'invalid_parameter_value';
  end if;

  -- No skip outcome for this entity_type (Review never plans one), so unlike commit_import_batch there is
  -- nothing to settle to 'skipped'. hold/error settle exactly like the client importer; create/update queue.
  update public.import_rows
  set status = case planned_action
    when 'create' then 'ready'
    when 'update' then 'ready'
    when 'hold' then 'held'
    when 'error' then 'failed'
    else status
  end
  where batch_id = target_batch_id
    and status = 'pending_review';

  select
    count(*) filter (where planned_action = 'hold'),
    count(*) filter (where planned_action = 'error'),
    count(*) filter (where planned_action in ('create', 'update'))
  into held, errored, to_import
  from public.import_rows
  where batch_id = target_batch_id;

  update public.import_batches
  set held_count = held,
      error_count = errored,
      status = case when to_import = 0 then 'completed' else 'importing' end
  where id = target_batch_id
  returning * into target_batch;

  return target_batch;
end;
$$;


ALTER FUNCTION "public"."commit_opening_balance_import_batch"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."commit_opening_balance_import_batch"("payload" "jsonb") IS 'Commits a reviewed opening-balances import: settles hold/error rows to their final status, queues create/update rows as ''ready'' for the shared step-5b worker, and seeds the batch''s held/error counts. No consent gate -- an opening balance never contacts a customer. SECURITY DEFINER; self-checks invoices.create.';



