CREATE TABLE IF NOT EXISTS "public"."communication_sms_credit_topup_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "requested_amount_minor" bigint NOT NULL,
    "currency_code" "text" DEFAULT 'USD'::"text" NOT NULL,
    "offsite_reference" "text",
    "note" "text",
    "status" "text" DEFAULT 'awaiting_confirmation'::"text" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "decided_by" "uuid",
    "decided_at" timestamp with time zone,
    "decision_reason" "text",
    "settled_amount_minor" bigint,
    CONSTRAINT "communication_sms_credit_topup_requests_currency_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "communication_sms_credit_topup_requests_lifecycle_check" CHECK (((("status" = 'awaiting_confirmation'::"text") AND ("decided_at" IS NULL) AND ("decided_by" IS NULL) AND ("settled_amount_minor" IS NULL)) OR (("status" = 'confirmed'::"text") AND ("decided_at" IS NOT NULL) AND ("decided_by" IS NOT NULL) AND ("settled_amount_minor" IS NOT NULL) AND ("settled_amount_minor" > 0)) OR (("status" = 'rejected'::"text") AND ("decided_at" IS NOT NULL) AND ("decided_by" IS NOT NULL) AND ("settled_amount_minor" IS NULL)) OR (("status" = 'cancelled'::"text") AND ("decided_at" IS NOT NULL) AND ("settled_amount_minor" IS NULL)))),
    CONSTRAINT "communication_sms_credit_topup_requests_note_check" CHECK ((("note" IS NULL) OR ("char_length"("note") <= 2000))),
    CONSTRAINT "communication_sms_credit_topup_requests_reason_check" CHECK ((("decision_reason" IS NULL) OR ("char_length"("decision_reason") <= 2000))),
    CONSTRAINT "communication_sms_credit_topup_requests_reference_check" CHECK ((("offsite_reference" IS NULL) OR (("char_length"(TRIM(BOTH FROM "offsite_reference")) >= 1) AND ("char_length"(TRIM(BOTH FROM "offsite_reference")) <= 500)))),
    CONSTRAINT "communication_sms_credit_topup_requests_requested_amount_check" CHECK (("requested_amount_minor" > 0)),
    CONSTRAINT "communication_sms_credit_topup_requests_status_check" CHECK (("status" = ANY (ARRAY['awaiting_confirmation'::"text", 'confirmed'::"text", 'rejected'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."communication_sms_credit_topup_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."communication_sms_credit_topup_requests" IS 'Offsite SMS credit top-up requests. Creates no spendable credit until Jafar confirms receipt; confirming posts one immutable ledger credit and raises the settled balance. Server-owned; writes via the communication_sms_*_credit_topup command functions only.';



CREATE OR REPLACE FUNCTION "public"."communication_sms_cancel_credit_topup"("p_request_id" "uuid", "p_cancelled_by" "uuid") RETURNS "public"."communication_sms_credit_topup_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  req public.communication_sms_credit_topup_requests;
begin
  update public.communication_sms_credit_topup_requests
  set status = 'cancelled',
      decided_by = p_cancelled_by,
      decided_at = now()
  where id = p_request_id and status = 'awaiting_confirmation'
  returning * into req;

  if not found then
    raise exception 'top-up request % is not awaiting confirmation and cannot be cancelled', p_request_id
      using errcode = 'P0001';
  end if;

  return req;
end;
$$;


ALTER FUNCTION "public"."communication_sms_cancel_credit_topup"("p_request_id" "uuid", "p_cancelled_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_confirm_credit_topup"("p_request_id" "uuid", "p_decided_by" "uuid", "p_settled_amount_minor" bigint, "p_decision_reason" "text" DEFAULT NULL::"text") RETURNS "public"."communication_sms_credit_topup_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  req public.communication_sms_credit_topup_requests;
  new_balance bigint;
begin
  if p_settled_amount_minor is null or p_settled_amount_minor <= 0 then
    raise exception 'a confirmed top-up must record a positive settled amount'
      using errcode = 'P0001';
  end if;

  select * into req
  from public.communication_sms_credit_topup_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'top-up request % not found', p_request_id using errcode = 'P0001';
  end if;
  if req.status <> 'awaiting_confirmation' then
    raise exception 'top-up request % is % and can no longer be confirmed', p_request_id, req.status
      using errcode = 'P0001';
  end if;

  -- Ensure the organization has a credit account, then raise its settled balance.
  insert into public.communication_sms_credit_accounts (organization_id, currency_code)
  values (req.organization_id, req.currency_code)
  on conflict (organization_id) do nothing;

  update public.communication_sms_credit_accounts
  set settled_balance_minor = settled_balance_minor + p_settled_amount_minor,
      updated_at = now()
  where organization_id = req.organization_id
  returning settled_balance_minor into new_balance;

  -- One immutable purchased-credit entry, keyed to this request so a retry cannot post twice.
  insert into public.communication_sms_credit_ledger_entries (
    organization_id, source_key, entry_kind, amount_minor, balance_after_minor
  ) values (
    req.organization_id, 'topup:' || req.id::text, 'credit', p_settled_amount_minor, new_balance
  );

  update public.communication_sms_credit_topup_requests
  set status = 'confirmed',
      decided_by = p_decided_by,
      decided_at = now(),
      decision_reason = p_decision_reason,
      settled_amount_minor = p_settled_amount_minor
  where id = p_request_id
  returning * into req;

  return req;
end;
$$;


ALTER FUNCTION "public"."communication_sms_confirm_credit_topup"("p_request_id" "uuid", "p_decided_by" "uuid", "p_settled_amount_minor" bigint, "p_decision_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_consent_status"("p_organization_id" "uuid", "p_client_contact_method_id" "uuid", "p_subject" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(
    (
      select case when governing.event_kind = 'opt_in' then 'opted_in' else 'opted_out' end
      from public.communication_sms_consent_events governing
      where governing.organization_id = p_organization_id
        and governing.client_contact_method_id = p_client_contact_method_id
        and (
          governing.event_kind = 'opt_out'
          or (governing.event_kind = 'opt_in' and p_subject = any(governing.subjects))
        )
      order by governing.occurred_at desc, governing.received_at desc, governing.id desc
      limit 1
    ),
    'unknown'
  );
$$;


ALTER FUNCTION "public"."communication_sms_consent_status"("p_organization_id" "uuid", "p_client_contact_method_id" "uuid", "p_subject" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."communication_sms_consent_status"("p_organization_id" "uuid", "p_client_contact_method_id" "uuid", "p_subject" "text") IS 'Current SMS consent for one exact customer contact method and one operational subject (opted_in / opted_out / unknown), derived on read from append-only evidence. Unknown blocks sending.';



