    CONSTRAINT "communication_sms_credit_reservations_funding_check" CHECK ((("reserved_promotional_minor" >= 0) AND ("reserved_purchased_minor" >= 0) AND ("amount_minor" = ("reserved_promotional_minor" + "reserved_purchased_minor")))),
    CONSTRAINT "communication_sms_credit_reservations_price_check_attempts_chec" CHECK (("price_check_attempts" >= 0)),
    CONSTRAINT "communication_sms_credit_reservations_reported_currency_check" CHECK ((("reported_provider_price_currency" IS NULL) OR ("reported_provider_price_currency" ~ '^[A-Z]{3}$'::"text"))),
    CONSTRAINT "communication_sms_credit_reservations_reported_price_check" CHECK ((("reported_provider_price_minor" IS NULL) OR ("reported_provider_price_minor" >= 0))),
    CONSTRAINT "communication_sms_credit_reservations_reported_segments_check" CHECK ((("reported_segment_count" IS NULL) OR (("reported_segment_count" >= 1) AND ("reported_segment_count" <= 10)))),
    CONSTRAINT "communication_sms_credit_reservations_segments_check" CHECK ((("segment_count" >= 1) AND ("segment_count" <= 10))),
    CONSTRAINT "communication_sms_credit_reservations_settlement_check" CHECK (((("state" = 'reserved'::"text") AND ("settled_at" IS NULL)) OR (("state" <> 'reserved'::"text") AND ("settled_at" IS NOT NULL)))),
    CONSTRAINT "communication_sms_credit_reservations_source_check" CHECK ((("char_length"(TRIM(BOTH FROM "source_key")) >= 1) AND ("char_length"(TRIM(BOTH FROM "source_key")) <= 200))),
    CONSTRAINT "communication_sms_credit_reservations_state_check" CHECK (("state" = ANY (ARRAY['reserved'::"text", 'settled'::"text", 'released'::"text", 'submission_unknown'::"text"])))
);


