COMMENT ON COLUMN "public"."communication_sms_credit_reservations"."reserved_promotional_minor" IS 'The part of this reservation funded from Promotional Credit (spent first). Netted out of the live promotional balance while the reservation is active so concurrent sends cannot double-spend the same promotional grant.';



COMMENT ON COLUMN "public"."communication_sms_credit_reservations"."reserved_purchased_minor" IS 'The part of this reservation funded from Purchased Credit, held against communication_sms_credit_accounts.reserved_balance_minor.';



COMMENT ON COLUMN "public"."communication_sms_credit_reservations"."reported_provider_price_minor" IS 'Twilio''s own billed cost for this message, informational only -- never used to compute the contractor''s retail charge (see this migration''s header).';



CREATE OR REPLACE FUNCTION "public"."communication_sms_defer_price_reconciliation"("p_delivery_intent_id" "uuid", "p_last_error" "text" DEFAULT NULL::"text") RETURNS "public"."communication_sms_credit_reservations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  reservation public.communication_sms_credit_reservations;
  next_attempts integer;
  backoff_hours integer;
  max_attempts constant integer := 8;
begin
  select * into reservation
  from public.communication_sms_credit_reservations
  where delivery_intent_id = p_delivery_intent_id
  for update;

  if not found or reservation.state <> 'reserved' then
    return reservation;
  end if;

  next_attempts := reservation.price_check_attempts + 1;
  backoff_hours := least(power(2, next_attempts - 1)::numeric, 24)::integer;

  update public.communication_sms_credit_reservations
  set price_check_attempts = next_attempts,
      price_check_available_at = now() + make_interval(hours => backoff_hours)
  where id = reservation.id
  returning * into reservation;

  if next_attempts >= max_attempts then
    insert into public.communication_sms_reconciliation_items (
      organization_id, delivery_intent_id, reason, last_error
    ) values (
      reservation.organization_id, reservation.delivery_intent_id, 'billing_mismatch',
      coalesce(nullif(trim(p_last_error), ''), 'Twilio never reported a final price for this message.')
    )
    on conflict (delivery_intent_id, reason) where status in ('open', 'processing', 'failed')
      and delivery_intent_id is not null do nothing;
  end if;

  return reservation;
end;
$$;


ALTER FUNCTION "public"."communication_sms_defer_price_reconciliation"("p_delivery_intent_id" "uuid", "p_last_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_effective_mode"("p_organization_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case
    when m.organization_id is null then 'off'
    when m.override_mode is not null then m.override_mode
    when m.chosen_mode = 'off' or m.package_max_mode = 'off' then 'off'
    else 'operational'
  end
  from (select p_organization_id as org) q
  left join public.communication_sms_org_modes m on m.organization_id = q.org;
$$;


