CREATE OR REPLACE FUNCTION "public"."communication_sms_effective_retail_rate"("p_destination" "text", "p_sender_type" "text", "p_message_unit" "text", "p_currency_code" "text" DEFAULT 'USD'::"text", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS "public"."communication_sms_retail_rates"
