CREATE OR REPLACE FUNCTION "public"."communication_sms_enqueue_operational"("p_organization_id" "uuid", "p_actor" "uuid", "p_client_id" "uuid", "p_client_contact_method_id" "uuid", "p_sender_id" "uuid", "p_subject" "text", "p_body" "text", "p_send_kind" "text", "p_logical_send_key" "text", "p_attachments" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
begin
  if p_actor is null then
    raise exception 'a send must record who sent it' using errcode = 'P0001';
  end if;

  if not private.member_has_permission(p_organization_id, p_actor, 'conversations.send')
    or not private.member_has_permission(p_organization_id, p_actor, 'customers.view') then
    raise exception 'You do not have permission to send a customer message.'
      using errcode = 'insufficient_privilege';
  end if;

  return private.communication_sms_enqueue_operational_core(
    p_organization_id, p_client_id, p_client_contact_method_id, p_sender_id,
    p_subject, p_body, p_send_kind, p_logical_send_key, p_actor, p_attachments);
end;
$$;


ALTER FUNCTION "public"."communication_sms_enqueue_operational"("p_organization_id" "uuid", "p_actor" "uuid", "p_client_id" "uuid", "p_client_contact_method_id" "uuid", "p_sender_id" "uuid", "p_subject" "text", "p_body" "text", "p_send_kind" "text", "p_logical_send_key" "text", "p_attachments" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."communication_sms_enqueue_operational"("p_organization_id" "uuid", "p_actor" "uuid", "p_client_id" "uuid", "p_client_contact_method_id" "uuid", "p_sender_id" "uuid", "p_subject" "text", "p_body" "text", "p_send_kind" "text", "p_logical_send_key" "text", "p_attachments" "jsonb") IS 'Human-authorized SMS send: checks the actor''s permission, then delegates every live gate (including delivery-mode resolution) and the atomic write to private.communication_sms_enqueue_operational_core. Service role only.';



CREATE OR REPLACE FUNCTION "public"."communication_sms_estimate_segments"("p_body" "text") RETURNS TABLE("encoding" "text", "segment_count" integer)
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  gsm_basic constant text :=
    '@£$¥èéùìòÇØøÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !"#¤%&''()*+,-./0123456789:;<=>?'
    || '¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà'
    || chr(10) || chr(13);
  gsm_ext constant text := '^{}\[~]|€' || chr(12);
  ch text;
  is_gsm boolean := true;
  units integer := 0;
begin
  if p_body is null or char_length(p_body) = 0 then
    raise exception 'an SMS needs a message body' using errcode = 'P0001';
  end if;

  foreach ch in array regexp_split_to_array(p_body, '') loop
    if position(ch in gsm_ext) > 0 then
      units := units + 2;
    elsif position(ch in gsm_basic) > 0 then
      units := units + 1;
    else
      is_gsm := false;
      exit;
    end if;
  end loop;

  if is_gsm then
    encoding := 'gsm7';
    segment_count := case when units <= 160 then 1 else ceil(units::numeric / 153) end;
  else
    encoding := 'ucs2';
    -- UTF-16 code units: characters beyond the Basic Multilingual Plane (e.g. most emoji) take two.
    units := 0;
    foreach ch in array regexp_split_to_array(p_body, '') loop
      units := units + case when ascii(ch) > 65535 then 2 else 1 end;
    end loop;
    segment_count := case when units <= 70 then 1 else ceil(units::numeric / 67) end;
  end if;

  return next;
end;
$_$;


ALTER FUNCTION "public"."communication_sms_estimate_segments"("p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_grant_promotional_credit"("p_organization_id" "uuid", "p_amount_minor" bigint, "p_expires_at" timestamp with time zone, "p_reason" "text", "p_idempotency_key" "text", "p_granted_by" "uuid" DEFAULT NULL::"uuid", "p_currency_code" "text" DEFAULT 'USD'::"text") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "currency_code" "text", "amount_minor" bigint, "reason" "text", "granted_by" "uuid", "granted_at" timestamp with time zone, "expires_at" timestamp with time zone, "status" "text", "revoked_by" "uuid", "revoked_at" timestamp with time zone, "revoke_reason" "text", "idempotency_key" "text", "applied" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
declare
  r public.communication_sms_promotional_credits%rowtype;
  already_applied boolean := false;
begin
  if p_idempotency_key is null or char_length(trim(p_idempotency_key)) < 8 then
    raise exception 'a promotional grant must record an idempotency key' using errcode = 'P0001';
  end if;
  if p_amount_minor is null or p_amount_minor <= 0 then
    raise exception 'a promotional grant must be a positive amount' using errcode = 'P0001';
  end if;
  if p_reason is null or char_length(trim(p_reason)) = 0 then
    raise exception 'a promotional grant must record a reason' using errcode = 'P0001';
  end if;
  if p_expires_at is null or p_expires_at <= now() then
    raise exception 'a promotional grant must expire in the future' using errcode = 'P0001';
  end if;

  select * into r
  from public.communication_sms_promotional_credits c
  where c.organization_id = p_organization_id and c.idempotency_key = p_idempotency_key;

  if not found then
    begin
      insert into public.communication_sms_promotional_credits (
        organization_id, amount_minor, expires_at, reason, granted_by, currency_code, idempotency_key
      ) values (
        p_organization_id, p_amount_minor, p_expires_at, p_reason, p_granted_by,
        coalesce(p_currency_code, 'USD'), p_idempotency_key
      )
      returning * into r;
      already_applied := true;
    exception when unique_violation then
      select * into r
      from public.communication_sms_promotional_credits c
      where c.organization_id = p_organization_id and c.idempotency_key = p_idempotency_key;
    end;
  end if;

  return query select r.*, already_applied;
end;
$$;


ALTER FUNCTION "public"."communication_sms_grant_promotional_credit"("p_organization_id" "uuid", "p_amount_minor" bigint, "p_expires_at" timestamp with time zone, "p_reason" "text", "p_idempotency_key" "text", "p_granted_by" "uuid", "p_currency_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_list_price_reconciliation_candidates"("p_limit" integer DEFAULT 100) RETURNS TABLE("delivery_intent_id" "uuid", "organization_id" "uuid", "provider_message_id" "text", "twilio_account_id" "uuid", "subaccount_sid" "text", "price_check_attempts" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    reservation.delivery_intent_id,
    reservation.organization_id,
    intent.provider_message_id,
    account.id as twilio_account_id,
    account.subaccount_sid,
    reservation.price_check_attempts
  from public.communication_sms_credit_reservations reservation
  join public.communication_delivery_intents intent
    on intent.id = reservation.delivery_intent_id and intent.channel = 'sms'
  join public.communication_twilio_accounts account
    on account.organization_id = reservation.organization_id
  where reservation.state = 'reserved'
    and reservation.price_check_available_at <= now()
    and intent.status = 'submitted'
  order by reservation.price_check_available_at, reservation.reserved_at
  limit greatest(p_limit, 0);
$$;


ALTER FUNCTION "public"."communication_sms_list_price_reconciliation_candidates"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_list_usage_reconciliation_candidates"("p_limit" integer DEFAULT 50, "p_lag_days" integer DEFAULT 2, "p_overlap_days" integer DEFAULT 3, "p_max_window_days" integer DEFAULT 14) RETURNS TABLE("organization_id" "uuid", "twilio_account_id" "uuid", "subaccount_sid" "text", "window_start" "date", "window_end" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    account.organization_id,
    account.id as twilio_account_id,
    account.subaccount_sid,
    greatest(
      coalesce(
        account.usage_reconciled_through - (greatest(p_overlap_days, 1) - 1),
        (current_date - p_lag_days)
      ),
      (current_date - p_lag_days) - (greatest(p_max_window_days, 1) - 1)
    ) as window_start,
    current_date - p_lag_days as window_end
  from public.communication_twilio_accounts account
  where account.lifecycle_state in ('ready', 'restricted')
    and (
      account.usage_reconciled_through is null
      or account.usage_reconciled_through < current_date - p_lag_days
    )
  order by coalesce(account.usage_reconciliation_checked_at, to_timestamp(0)), account.organization_id
  limit greatest(p_limit, 0);
$$;


ALTER FUNCTION "public"."communication_sms_list_usage_reconciliation_candidates"("p_limit" integer, "p_lag_days" integer, "p_overlap_days" integer, "p_max_window_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_opted_out_count"("p_organization_id" "uuid", "p_since" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select count(*)::integer
  from (
    select distinct on (governing.client_contact_method_id)
      governing.client_contact_method_id, governing.event_kind, governing.occurred_at
    from public.communication_sms_consent_events governing
    where governing.organization_id = p_organization_id
      and governing.event_kind in ('opt_in', 'opt_out')
    order by governing.client_contact_method_id, governing.occurred_at desc, governing.received_at desc,
      governing.id desc
  ) current_state
  where current_state.event_kind = 'opt_out'
    and (p_since is null or current_state.occurred_at >= p_since);
$$;


