COMMENT ON FUNCTION "public"."communication_sms_opted_out_count"("p_organization_id" "uuid", "p_since" timestamp with time zone) IS 'Count of an organization''s customer numbers currently opted out of SMS (global, subject-independent), optionally scoped to those whose opt-out occurred at or after p_since. Derived on read from communication_sms_consent_events using the same governing-event rule as communication_sms_consent_status().';



CREATE OR REPLACE FUNCTION "public"."communication_sms_outbound_state"("p_organization_id" "uuid", "p_country_code" "text", "p_sender_type" "text", "p_use_case" "text") RETURNS TABLE("state" "text", "effective_mode" "text", "registration_status" "text", "live_sender_count" integer, "pause_scope" "text", "pause_reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  h record;
begin
  select * into r
  from public.communication_sms_readiness(
    p_organization_id, p_country_code, p_sender_type, p_use_case
  );

  effective_mode := r.effective_mode;
  registration_status := r.registration_status;
  live_sender_count := r.live_sender_count;
  state := r.readiness_state;
  pause_scope := null;
  pause_reason := null;

  if r.readiness_state = 'ready' then
    select * into h from public.communication_sms_active_outbound_hold(p_organization_id);
    if found then
      state := 'outbound_paused';
      pause_scope := h.scope;
      pause_reason := h.reason;
    end if;
  end if;

  return next;
end;
$$;


ALTER FUNCTION "public"."communication_sms_outbound_state"("p_organization_id" "uuid", "p_country_code" "text", "p_sender_type" "text", "p_use_case" "text") OWNER TO "postgres";


