    CONSTRAINT "communication_sms_holds_lifecycle_check" CHECK (((("status" = 'active'::"text") AND ("released_at" IS NULL) AND ("released_by" IS NULL) AND ("release_reason" IS NULL)) OR (("status" = 'released'::"text") AND ("released_at" IS NOT NULL) AND ("released_by" IS NOT NULL)))),
    CONSTRAINT "communication_sms_holds_reason_check" CHECK ((("char_length"(TRIM(BOTH FROM "reason")) >= 1) AND ("char_length"(TRIM(BOTH FROM "reason")) <= 2000))),
    CONSTRAINT "communication_sms_holds_release_reason_check" CHECK ((("release_reason" IS NULL) OR ("char_length"("release_reason") <= 2000))),
    CONSTRAINT "communication_sms_holds_scope_check" CHECK (("scope" = ANY (ARRAY['platform'::"text", 'organization'::"text", 'provider'::"text"]))),
    CONSTRAINT "communication_sms_holds_scope_org_check" CHECK (((("scope" = 'platform'::"text") AND ("organization_id" IS NULL)) OR (("scope" = ANY (ARRAY['organization'::"text", 'provider'::"text"])) AND ("organization_id" IS NOT NULL)))),
    CONSTRAINT "communication_sms_holds_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'released'::"text"])))
);


