COMMENT ON TABLE "public"."communication_sms_holds" IS 'Reasoned outbound-SMS holds at platform, organization or provider scope. Pauses OUTBOUND only; inbound and STOP/START/HELP remain a runtime concern the worker keeps available. Server-owned; writes via the communication_sms_place_hold / communication_sms_release_hold commands only.';



CREATE OR REPLACE FUNCTION "public"."communication_sms_place_hold"("p_scope" "text", "p_organization_id" "uuid", "p_reason" "text", "p_placed_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."communication_sms_holds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  hold public.communication_sms_holds;
begin
  if p_reason is null or char_length(trim(p_reason)) = 0 then
    raise exception 'a hold must record a reason' using errcode = 'P0001';
  end if;

  begin
    insert into public.communication_sms_holds (scope, organization_id, reason, placed_by)
    values (p_scope, p_organization_id, p_reason, p_placed_by)
    returning * into hold;
  exception when unique_violation then
    raise exception 'an active % hold already exists for this target', p_scope using errcode = 'P0001';
  end;

  return hold;
end;
$$;


