CREATE OR REPLACE FUNCTION "public"."communication_sms_quiet_hours_available_at"("p_at" timestamp with time zone DEFAULT "now"()) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  policy public.communication_sms_quiet_hours_policy;
  local_ts timestamp;
  local_time time;
  in_window boolean;
  window_end_local timestamp;
begin
  select * into policy from public.communication_sms_quiet_hours_policy where id;
  if not found or not policy.enabled then
    return p_at;
  end if;

  local_ts := p_at at time zone policy.time_zone;
  local_time := local_ts::time;

  if policy.quiet_start <= policy.quiet_end then
    in_window := local_time >= policy.quiet_start and local_time < policy.quiet_end;
  else
    -- Window wraps midnight: quiet from quiet_start to end-of-day and from start-of-day to quiet_end.
    in_window := local_time >= policy.quiet_start or local_time < policy.quiet_end;
  end if;

  if not in_window then
    return p_at;
  end if;

  if local_time < policy.quiet_end then
    -- In the early-morning tail of the window: the end is later today (local).
    window_end_local := local_ts::date + policy.quiet_end;
  else
    -- At or after quiet_start: the end is tomorrow morning (local).
    window_end_local := (local_ts::date + 1) + policy.quiet_end;
  end if;

  return window_end_local at time zone policy.time_zone;
end;
$$;


ALTER FUNCTION "public"."communication_sms_quiet_hours_available_at"("p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_readiness"("p_organization_id" "uuid", "p_country_code" "text", "p_sender_type" "text", "p_use_case" "text") RETURNS TABLE("readiness_state" "text", "effective_mode" "text", "registration_status" "text", "live_sender_count" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  mode text := public.communication_sms_effective_mode(p_organization_id);
  reg public.communication_sms_registrations;
  live_count integer := 0;
begin
  effective_mode := mode;

  if mode = 'off' then
    readiness_state := 'not_included';
    registration_status := null;
    live_sender_count := 0;
    return next;
    return;
  end if;

  select * into reg
  from public.communication_sms_registrations
  where organization_id = p_organization_id
    and country_code = p_country_code
    and sender_type = p_sender_type
    and use_case = p_use_case;

  if not found then
    readiness_state := 'needs_setup';
    registration_status := null;
    live_sender_count := 0;
    return next;
    return;
  end if;

  registration_status := reg.status;

  if reg.status <> 'approved' then
    readiness_state := reg.status;
    live_sender_count := 0;
    return next;
    return;
  end if;

  select count(*) into live_count
  from public.communication_sms_sender_identities s
  where s.organization_id = p_organization_id
    and s.registration_id = reg.id
    and s.capable_sms
    and s.lifecycle_state = 'ready';

  live_sender_count := live_count;
  readiness_state := case when live_count >= 1 then 'ready' else 'finishing_setup' end;
  return next;
end;
$$;


ALTER FUNCTION "public"."communication_sms_readiness"("p_organization_id" "uuid", "p_country_code" "text", "p_sender_type" "text", "p_use_case" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_record_adjustment"("p_organization_id" "uuid", "p_amount_minor" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_actor" "uuid" DEFAULT NULL::"uuid", "p_currency_code" "text" DEFAULT 'USD'::"text") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "reservation_id" "uuid", "source_key" "text", "entry_kind" "text", "amount_minor" bigint, "balance_after_minor" bigint, "occurred_at" timestamp with time zone, "reason" "text", "applied" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
declare
  r public.communication_sms_credit_ledger_entries%rowtype;
  already_applied boolean := false;
  v_source_key text;
  reserved bigint;
  new_balance bigint;
begin
  if p_idempotency_key is null or char_length(trim(p_idempotency_key)) < 8 then
    raise exception 'an adjustment must record an idempotency key' using errcode = 'P0001';
  end if;
  if p_amount_minor is null or p_amount_minor = 0 then
    raise exception 'an adjustment must move a non-zero amount' using errcode = 'P0001';
  end if;
  if p_reason is null or char_length(trim(p_reason)) = 0 then
    raise exception 'an adjustment must record a reason' using errcode = 'P0001';
  end if;

  v_source_key := 'adjustment:' || p_idempotency_key;

  select * into r
  from public.communication_sms_credit_ledger_entries e
  where e.organization_id = p_organization_id
    and e.source_key = v_source_key
    and e.entry_kind = 'adjustment';

  if found then
    return query select r.*, already_applied;
    return;
  end if;

  insert into public.communication_sms_credit_accounts (organization_id, currency_code)
  values (p_organization_id, coalesce(p_currency_code, 'USD'))
  on conflict (organization_id) do nothing;

  -- Check the resulting balance before writing it, so a refused correction returns a clear business error
  -- rather than the raw balances-check violation, while the constraint stays the backstop.
  select settled_balance_minor, reserved_balance_minor into new_balance, reserved
  from public.communication_sms_credit_accounts
  where organization_id = p_organization_id
  for update;

  new_balance := new_balance + p_amount_minor;

  if new_balance < reserved then
    raise exception 'adjustment would drive the settled balance below the reserved funds'
      using errcode = 'P0001';
  end if;

  update public.communication_sms_credit_accounts
  set settled_balance_minor = new_balance,
      updated_at = now()
  where organization_id = p_organization_id;

  begin
    insert into public.communication_sms_credit_ledger_entries (
      organization_id, source_key, entry_kind, amount_minor, balance_after_minor, occurred_at, reason
    ) values (
      p_organization_id, v_source_key, 'adjustment', p_amount_minor, new_balance, now(), trim(p_reason)
    )
    returning * into r;
    already_applied := true;
  exception when unique_violation then
    -- Lost a race with a concurrent identical retry; the balance update above is a no-op replay risk only
    -- if two racing writers both pass the balance check -- read back the winner's row instead of erroring.
    select * into r
    from public.communication_sms_credit_ledger_entries e
    where e.organization_id = p_organization_id
      and e.source_key = v_source_key
      and e.entry_kind = 'adjustment';
  end;

  return query select r.*, already_applied;
end;
$$;


ALTER FUNCTION "public"."communication_sms_record_adjustment"("p_organization_id" "uuid", "p_amount_minor" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_actor" "uuid", "p_currency_code" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_sms_consent_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "client_contact_method_id" "uuid" NOT NULL,
    "event_kind" "text" NOT NULL,
    "source" "text" NOT NULL,
    "source_event_key" "text" NOT NULL,
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "occurred_at" timestamp with time zone NOT NULL,
    "received_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "subjects" "text"[],
    "proof_method" "text",
    CONSTRAINT "communication_sms_consent_events_evidence_check" CHECK (("jsonb_typeof"("evidence") = 'object'::"text")),
    CONSTRAINT "communication_sms_consent_events_kind_check" CHECK (("event_kind" = ANY (ARRAY['opt_in'::"text", 'opt_out'::"text", 'help_requested'::"text"]))),
    CONSTRAINT "communication_sms_consent_events_source_check" CHECK (("source" = ANY (ARRAY['client_reply'::"text", 'staff'::"text", 'import'::"text", 'system'::"text"]))),
    CONSTRAINT "communication_sms_consent_events_source_key_check" CHECK ((("char_length"(TRIM(BOTH FROM "source_event_key")) >= 1) AND ("char_length"(TRIM(BOTH FROM "source_event_key")) <= 300))),
    CONSTRAINT "communication_sms_consent_events_subject_scope_check" CHECK (((("event_kind" = 'opt_in'::"text") AND ("subjects" IS NOT NULL) AND ("array_length"("subjects", 1) >= 1) AND ("subjects" <@ ARRAY['service'::"text", 'work_updates'::"text", 'billing_updates'::"text"]) AND ("array_position"("subjects", NULL::"text") IS NULL) AND ("proof_method" = ANY (ARRAY['customer_sms'::"text", 'web_form'::"text", 'signed_agreement'::"text", 'client_reply'::"text"]))) OR (("event_kind" = ANY (ARRAY['opt_out'::"text", 'help_requested'::"text"])) AND ("subjects" IS NULL) AND (("proof_method" IS NULL) OR ("proof_method" = ANY (ARRAY['customer_sms'::"text", 'client_reply'::"text", 'provider_keyword'::"text"]))))))
);


ALTER TABLE "public"."communication_sms_consent_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."communication_sms_consent_events" IS 'Append-only SMS consent evidence. Current eligibility is projected separately so delayed events can be ordered by occurred_at, received_at and id.';



COMMENT ON COLUMN "public"."communication_sms_consent_events"."subjects" IS 'For an opt-in, the operational subjects the customer agreed to (service, work_updates, billing_updates). Null for a global opt-out or HELP request. Marketing consent is separate and out of A2 scope.';



COMMENT ON COLUMN "public"."communication_sms_consent_events"."proof_method" IS 'How an opt-in was proven: customer_sms, web_form or signed_agreement for recorded proof, client_reply for a customer text. Verbal is not an accepted method and cannot be stored.';



CREATE OR REPLACE FUNCTION "public"."communication_sms_record_consent_proof"("p_organization_id" "uuid", "p_actor" "uuid", "p_client_id" "uuid", "p_client_contact_method_id" "uuid", "p_proof_method" "text", "p_subjects" "text"[], "p_occurred_at" timestamp with time zone, "p_source_event_key" "text", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."communication_sms_consent_events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor_role text;
  method public.client_contact_methods;
  event public.communication_sms_consent_events;
begin
  if p_actor is null then
    raise exception 'recording consent proof must record who did it' using errcode = 'P0001';
  end if;

  select membership.role into actor_role
  from public.organization_members membership
  where membership.organization_id = p_organization_id
    and membership.user_id = p_actor
    and membership.status = 'active';

  if actor_role is null or actor_role not in ('owner', 'admin') then
    raise exception 'Only an owner or administrator can record customer SMS consent proof.'
      using errcode = 'insufficient_privilege';
  end if;

  if p_proof_method is null or p_proof_method not in ('customer_sms', 'web_form', 'signed_agreement') then
    raise exception 'Consent proof must be a customer text, web-form consent, or a signed agreement.'
      using errcode = 'P0001';
  end if;

  if p_subjects is null or array_length(p_subjects, 1) is null then
    raise exception 'Choose at least one thing this consent covers.' using errcode = 'P0001';
  end if;
  if not (p_subjects <@ array['service', 'work_updates', 'billing_updates']::text[])
     or array_position(p_subjects, null) is not null then
    raise exception 'Consent can only cover service, work updates, or billing updates.'
      using errcode = 'P0001';
  end if;

  if p_occurred_at is null then
    raise exception 'Consent proof must record when the customer agreed.' using errcode = 'P0001';
  end if;
  if p_occurred_at > now() then
    raise exception 'Consent proof cannot be dated in the future.' using errcode = 'P0001';
  end if;

  if p_source_event_key is null or char_length(btrim(p_source_event_key)) = 0 then
    raise exception 'Consent proof must carry an idempotency key.' using errcode = 'P0001';
  end if;

  select cm.* into method
  from public.client_contact_methods cm
  join public.clients client
    on client.organization_id = cm.organization_id and client.id = cm.client_id
  where cm.organization_id = p_organization_id
    and cm.id = p_client_contact_method_id
    and cm.client_id = p_client_id
    and cm.kind = 'phone'
    and client.deleted_at is null;

  if method.id is null then
    raise exception 'Choose an active phone number for this customer.' using errcode = 'P0001';
  end if;

  insert into public.communication_sms_consent_events (
    organization_id, client_id, client_contact_method_id, event_kind, source, source_event_key,
    subjects, proof_method, evidence, occurred_at, created_by
  ) values (
    p_organization_id, p_client_id, p_client_contact_method_id, 'opt_in', 'staff', btrim(p_source_event_key),
    p_subjects, p_proof_method, coalesce(p_evidence, '{}'::jsonb), p_occurred_at, p_actor
  )
  on conflict (organization_id, source, source_event_key) do nothing
  returning * into event;

  if event.id is null then
    select * into event
    from public.communication_sms_consent_events
    where organization_id = p_organization_id and source = 'staff'
      and source_event_key = btrim(p_source_event_key);
  end if;

  return event;
end;
$$;


ALTER FUNCTION "public"."communication_sms_record_consent_proof"("p_organization_id" "uuid", "p_actor" "uuid", "p_client_id" "uuid", "p_client_contact_method_id" "uuid", "p_proof_method" "text", "p_subjects" "text"[], "p_occurred_at" timestamp with time zone, "p_source_event_key" "text", "p_evidence" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."communication_sms_record_consent_proof"("p_organization_id" "uuid", "p_actor" "uuid", "p_client_id" "uuid", "p_client_contact_method_id" "uuid", "p_proof_method" "text", "p_subjects" "text"[], "p_occurred_at" timestamp with time zone, "p_source_event_key" "text", "p_evidence" "jsonb") IS 'Owner/admin-only command to record external SMS opt-in proof for one exact customer phone number and one or more operational subjects. Idempotent by (organization, staff source, source_event_key). Verbal consent is refused. The /api/* layer supplies the authenticated actor and a stable idempotency key.';



CREATE OR REPLACE FUNCTION "public"."communication_sms_record_refund"("p_organization_id" "uuid", "p_amount_minor" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "reservation_id" "uuid", "source_key" "text", "entry_kind" "text", "amount_minor" bigint, "balance_after_minor" bigint, "occurred_at" timestamp with time zone, "reason" "text", "applied" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
declare
  r public.communication_sms_credit_ledger_entries%rowtype;
  already_applied boolean := false;
  v_source_key text;
  reserved bigint;
  new_balance bigint;
begin
  if p_idempotency_key is null or char_length(trim(p_idempotency_key)) < 8 then
    raise exception 'a refund must record an idempotency key' using errcode = 'P0001';
  end if;
  if p_amount_minor is null or p_amount_minor <= 0 then
    raise exception 'a refund must be a positive amount' using errcode = 'P0001';
  end if;
  if p_reason is null or char_length(trim(p_reason)) = 0 then
    raise exception 'a refund must record a reason' using errcode = 'P0001';
  end if;

  v_source_key := 'refund:' || p_idempotency_key;

  select * into r
  from public.communication_sms_credit_ledger_entries e
  where e.organization_id = p_organization_id
    and e.source_key = v_source_key
    and e.entry_kind = 'refund';

  if found then
    return query select r.*, already_applied;
    return;
  end if;

  -- Check the resulting balance before writing it, so an over-refund returns a clear business error rather
  -- than the raw balances-check violation, while the constraint stays the backstop.
  select settled_balance_minor, reserved_balance_minor into new_balance, reserved
  from public.communication_sms_credit_accounts
  where organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'organization % has no credit account to refund from', p_organization_id
      using errcode = 'P0001';
  end if;

  new_balance := new_balance - p_amount_minor;

  if new_balance < reserved then
    raise exception 'refund exceeds the unreserved settled balance' using errcode = 'P0001';
  end if;

  update public.communication_sms_credit_accounts
  set settled_balance_minor = new_balance,
      updated_at = now()
  where organization_id = p_organization_id;

  begin
    insert into public.communication_sms_credit_ledger_entries (
      organization_id, source_key, entry_kind, amount_minor, balance_after_minor, occurred_at, reason
    ) values (
      p_organization_id, v_source_key, 'refund', -p_amount_minor, new_balance, now(), trim(p_reason)
    )
    returning * into r;
    already_applied := true;
  exception when unique_violation then
    select * into r
    from public.communication_sms_credit_ledger_entries e
    where e.organization_id = p_organization_id
      and e.source_key = v_source_key
      and e.entry_kind = 'refund';
  end;

  return query select r.*, already_applied;
end;
$$;


ALTER FUNCTION "public"."communication_sms_record_refund"("p_organization_id" "uuid", "p_amount_minor" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_sms_registrations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "country_code" "text" NOT NULL,
    "sender_type" "text" NOT NULL,
    "use_case" "text" NOT NULL,
    "status" "text" DEFAULT 'waiting_for_info'::"text" NOT NULL,
    "provider_registration_sid" "text",
    "attested_by" "uuid",
    "attested_at" timestamp with time zone,
    "submitted_at" timestamp with time zone,
    "provider_outcome" "text",
    "required_fixes" "text",
    "last_checked_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "draft_questionnaire_version" integer DEFAULT 1 NOT NULL,
    "draft_answers" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "draft_revision" integer DEFAULT 1 NOT NULL,
    "draft_updated_by" "uuid",
    "draft_updated_at" timestamp with time zone,
    CONSTRAINT "communication_sms_registrations_attestation_check" CHECK ((("attested_at" IS NULL) = ("attested_by" IS NULL))),
    CONSTRAINT "communication_sms_registrations_country_check" CHECK (("country_code" ~ '^[A-Z]{2}$'::"text")),
    CONSTRAINT "communication_sms_registrations_draft_answers_check" CHECK ((("jsonb_typeof"("draft_answers") = 'object'::"text") AND ("octet_length"(("draft_answers")::"text") <= 65536))),
    CONSTRAINT "communication_sms_registrations_draft_revision_check" CHECK (("draft_revision" >= 1)),
    CONSTRAINT "communication_sms_registrations_draft_version_check" CHECK (("draft_questionnaire_version" >= 1)),
    CONSTRAINT "communication_sms_registrations_fixes_check" CHECK ((("required_fixes" IS NULL) OR ("char_length"("required_fixes") <= 2000))),
    CONSTRAINT "communication_sms_registrations_lifecycle_check" CHECK (((("status" = 'waiting_for_info'::"text") AND ("submitted_at" IS NULL) AND ("provider_outcome" IS NULL) AND ("required_fixes" IS NULL)) OR (("status" = 'under_review'::"text") AND ("submitted_at" IS NOT NULL) AND ("attested_at" IS NOT NULL) AND ("required_fixes" IS NULL)) OR (("status" = 'action_needed'::"text") AND ("submitted_at" IS NOT NULL) AND ("attested_at" IS NOT NULL) AND ("required_fixes" IS NOT NULL)) OR (("status" = 'approved'::"text") AND ("submitted_at" IS NOT NULL) AND ("attested_at" IS NOT NULL) AND ("provider_outcome" IS NOT NULL)))),
    CONSTRAINT "communication_sms_registrations_outcome_check" CHECK ((("provider_outcome" IS NULL) OR ("char_length"("provider_outcome") <= 2000))),
    CONSTRAINT "communication_sms_registrations_provider_sid_check" CHECK ((("provider_registration_sid" IS NULL) OR (("char_length"(TRIM(BOTH FROM "provider_registration_sid")) >= 1) AND ("char_length"(TRIM(BOTH FROM "provider_registration_sid")) <= 100)))),
    CONSTRAINT "communication_sms_registrations_sender_type_check" CHECK (("sender_type" = ANY (ARRAY['long_code'::"text", 'toll_free'::"text", 'short_code'::"text", 'alphanumeric'::"text"]))),
    CONSTRAINT "communication_sms_registrations_status_check" CHECK (("status" = ANY (ARRAY['waiting_for_info'::"text", 'under_review'::"text", 'action_needed'::"text", 'approved'::"text"]))),
    CONSTRAINT "communication_sms_registrations_use_case_check" CHECK ((("char_length"(TRIM(BOTH FROM "use_case")) >= 1) AND ("char_length"(TRIM(BOTH FROM "use_case")) <= 200)))
);


ALTER TABLE "public"."communication_sms_registrations" OWNER TO "postgres";


COMMENT ON TABLE "public"."communication_sms_registrations" IS 'Current SMS sender registration per (org, country, sender type, use case). Drives the plain readiness state; re-submissions reuse the row and communication_sms_registration_events keeps the immutable history. Server-owned; writes via the communication_sms_*_registration commands only.';



CREATE OR REPLACE FUNCTION "public"."communication_sms_record_registration_check"("p_registration_id" "uuid", "p_checked_by" "uuid" DEFAULT NULL::"uuid", "p_detail" "text" DEFAULT NULL::"text") RETURNS "public"."communication_sms_registrations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  reg public.communication_sms_registrations;
begin
  update public.communication_sms_registrations
  set last_checked_at = now(),
      updated_at = now()
  where id = p_registration_id
  returning * into reg;

  if not found then
    raise exception 'registration % not found', p_registration_id using errcode = 'P0001';
  end if;

  insert into public.communication_sms_registration_events (
    registration_id, organization_id, event_type, from_status, to_status, detail, created_by
  ) values (
    reg.id, reg.organization_id, 'readiness_checked', reg.status, reg.status, p_detail, p_checked_by
  );

  return reg;
end;
$$;


ALTER FUNCTION "public"."communication_sms_record_registration_check"("p_registration_id" "uuid", "p_checked_by" "uuid", "p_detail" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_record_registration_outcome"("p_registration_id" "uuid", "p_status" "text", "p_decided_by" "uuid" DEFAULT NULL::"uuid", "p_provider_outcome" "text" DEFAULT NULL::"text", "p_required_fixes" "text" DEFAULT NULL::"text") RETURNS "public"."communication_sms_registrations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  reg public.communication_sms_registrations;
begin
  if p_status not in ('approved', 'action_needed') then
    raise exception 'a registration outcome must be approved or action_needed, not %', p_status
      using errcode = 'P0001';
  end if;
  if p_status = 'approved' and (p_provider_outcome is null or char_length(trim(p_provider_outcome)) = 0) then
    raise exception 'an approved registration must record a provider outcome' using errcode = 'P0001';
  end if;
  if p_status = 'action_needed' and (p_required_fixes is null or char_length(trim(p_required_fixes)) = 0) then
    raise exception 'an action_needed registration must record the required fixes' using errcode = 'P0001';
  end if;

  select * into reg
  from public.communication_sms_registrations
  where id = p_registration_id
  for update;

  if not found then
    raise exception 'registration % not found', p_registration_id using errcode = 'P0001';
  end if;
  if reg.status <> 'under_review' then
    raise exception 'registration % is % and has no pending review to decide', p_registration_id, reg.status
      using errcode = 'P0001';
  end if;

  update public.communication_sms_registrations
  set status = p_status,
      provider_outcome = case when p_status = 'approved' then p_provider_outcome else null end,
      required_fixes = case when p_status = 'action_needed' then p_required_fixes else null end,
      last_checked_at = now(),
      updated_at = now()
  where id = reg.id
  returning * into reg;

  insert into public.communication_sms_registration_events (
    registration_id, organization_id, event_type, from_status, to_status, provider_outcome, detail, created_by
  ) values (
    reg.id, reg.organization_id, p_status, 'under_review', reg.status,
    case when p_status = 'approved' then p_provider_outcome else null end,
    case when p_status = 'action_needed' then p_required_fixes else null end,
    p_decided_by
  );

  return reg;
end;
$$;


ALTER FUNCTION "public"."communication_sms_record_registration_outcome"("p_registration_id" "uuid", "p_status" "text", "p_decided_by" "uuid", "p_provider_outcome" "text", "p_required_fixes" "text") OWNER TO "postgres";


