);


ALTER TABLE "public"."communication_sms_usage_reconciliation_findings" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_record_usage_reconciliation_finding"("p_organization_id" "uuid", "p_usage_date" "date", "p_our_message_count" integer, "p_our_price_minor" bigint, "p_provider_message_count" integer, "p_provider_price_minor" bigint, "p_price_currency" "text") RETURNS "public"."communication_sms_usage_reconciliation_findings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  finding public.communication_sms_usage_reconciliation_findings;
  drifted boolean;
  synthetic_key text;
begin
  drifted := p_our_message_count <> p_provider_message_count or p_our_price_minor <> p_provider_price_minor;
  synthetic_key := 'usage-window:' || p_organization_id::text || ':' || p_usage_date::text;

  insert into public.communication_sms_usage_reconciliation_findings (
    organization_id, usage_date, our_message_count, our_price_minor,
    provider_message_count, provider_price_minor, price_currency, status, checked_at
  ) values (
    p_organization_id, p_usage_date, p_our_message_count, p_our_price_minor,
    p_provider_message_count, p_provider_price_minor, p_price_currency,
    case when drifted then 'drift' else 'matched' end, now()
  )
  on conflict (organization_id, usage_date) do update
    set our_message_count = excluded.our_message_count,
        our_price_minor = excluded.our_price_minor,
        provider_message_count = excluded.provider_message_count,
        provider_price_minor = excluded.provider_price_minor,
        price_currency = excluded.price_currency,
        status = excluded.status,
        checked_at = excluded.checked_at
  returning * into finding;

  if drifted then
    insert into public.communication_sms_reconciliation_items (
      organization_id, provider_message_id, reason, last_error
    ) values (
      p_organization_id, synthetic_key, 'usage_window_drift',
      format(
        'Twilio reported %s outbound SMS for %s (%s minor units) but our own settled records show %s (%s minor units).',
        p_provider_message_count, p_usage_date, p_provider_price_minor, p_our_message_count, p_our_price_minor
      )
    )
    on conflict (organization_id, provider_message_id, reason)
      where status in ('open', 'processing', 'failed') and delivery_intent_id is null
      do nothing;
  else
    update public.communication_sms_reconciliation_items
    set status = 'resolved', resolved_at = now()
    where organization_id = p_organization_id
      and provider_message_id = synthetic_key
      and reason = 'usage_window_drift'
      and status in ('open', 'processing', 'failed');
  end if;

  return finding;
end;
$$;


ALTER FUNCTION "public"."communication_sms_record_usage_reconciliation_finding"("p_organization_id" "uuid", "p_usage_date" "date", "p_our_message_count" integer, "p_our_price_minor" bigint, "p_provider_message_count" integer, "p_provider_price_minor" bigint, "p_price_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_reject_credit_topup"("p_request_id" "uuid", "p_decided_by" "uuid", "p_decision_reason" "text") RETURNS "public"."communication_sms_credit_topup_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  req public.communication_sms_credit_topup_requests;
begin
  if p_decision_reason is null or char_length(trim(p_decision_reason)) = 0 then
    raise exception 'a rejected top-up must record a reason' using errcode = 'P0001';
  end if;

  update public.communication_sms_credit_topup_requests
  set status = 'rejected',
      decided_by = p_decided_by,
      decided_at = now(),
      decision_reason = p_decision_reason
  where id = p_request_id and status = 'awaiting_confirmation'
  returning * into req;

  if not found then
    raise exception 'top-up request % is not awaiting confirmation and cannot be rejected', p_request_id
      using errcode = 'P0001';
  end if;

  return req;
end;
$$;


ALTER FUNCTION "public"."communication_sms_reject_credit_topup"("p_request_id" "uuid", "p_decided_by" "uuid", "p_decision_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_release_hold"("p_hold_id" "uuid", "p_released_by" "uuid", "p_release_reason" "text") RETURNS "public"."communication_sms_holds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  hold public.communication_sms_holds;
begin
  if p_released_by is null then
    raise exception 'releasing a hold must record who released it' using errcode = 'P0001';
  end if;
  if p_release_reason is null or char_length(trim(p_release_reason)) = 0 then
    raise exception 'releasing a hold must record a reason' using errcode = 'P0001';
  end if;

  update public.communication_sms_holds
  set status = 'released',
      released_by = p_released_by,
      released_at = now(),
      release_reason = p_release_reason
  where id = p_hold_id and status = 'active'
  returning * into hold;

  if not found then
    raise exception 'hold % is not active and cannot be released', p_hold_id using errcode = 'P0001';
  end if;

  return hold;
end;
$$;


ALTER FUNCTION "public"."communication_sms_release_hold"("p_hold_id" "uuid", "p_released_by" "uuid", "p_release_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_sms_sender_identities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "phone_number" "text" NOT NULL,
    "display_name" "text",
    "lifecycle_state" "text" DEFAULT 'pending_setup'::"text" NOT NULL,
    "allows_manual" boolean DEFAULT false NOT NULL,
    "allows_automated" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "country_code" "text",
    "sender_type" "text",
    "capable_sms" boolean DEFAULT false NOT NULL,
    "capable_mms" boolean DEFAULT false NOT NULL,
    "capable_voice" boolean DEFAULT false NOT NULL,
    "registration_id" "uuid",
    "is_default_sender" boolean DEFAULT false NOT NULL,
    CONSTRAINT "communication_sms_sender_identities_country_check" CHECK ((("country_code" IS NULL) OR ("country_code" ~ '^[A-Z]{2}$'::"text"))),
    CONSTRAINT "communication_sms_sender_identities_display_name_check" CHECK ((("display_name" IS NULL) OR (("char_length"(TRIM(BOTH FROM "display_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "display_name")) <= 80)))),
    CONSTRAINT "communication_sms_sender_identities_lifecycle_check" CHECK (("lifecycle_state" = ANY (ARRAY['pending_setup'::"text", 'ready'::"text", 'restricted'::"text", 'suspended'::"text", 'released'::"text"]))),
    CONSTRAINT "communication_sms_sender_identities_phone_check" CHECK (("phone_number" ~ '^\+[1-9][0-9]{7,14}$'::"text")),
    CONSTRAINT "communication_sms_sender_identities_release_check" CHECK ((("lifecycle_state" <> 'released'::"text") OR ((NOT "allows_manual") AND (NOT "allows_automated")))),
    CONSTRAINT "communication_sms_sender_identities_sender_type_check" CHECK ((("sender_type" IS NULL) OR ("sender_type" = ANY (ARRAY['long_code'::"text", 'toll_free'::"text", 'short_code'::"text", 'alphanumeric'::"text"]))))
);


ALTER TABLE "public"."communication_sms_sender_identities" OWNER TO "postgres";


COMMENT ON COLUMN "public"."communication_sms_sender_identities"."is_default_sender" IS 'The organization''s chosen default outbound SMS sending number. At most one per organization; a contractor owner/admin sets it through communication_sms_set_default_sender.';



CREATE OR REPLACE FUNCTION "public"."communication_sms_rename_sender"("p_organization_id" "uuid", "p_sender_id" "uuid", "p_display_name" "text", "p_actor" "uuid") RETURNS "public"."communication_sms_sender_identities"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  sender public.communication_sms_sender_identities;
  cleaned text;
begin
  if p_actor is null then
    raise exception 'a number change must record who made it' using errcode = 'P0001';
  end if;
  cleaned := nullif(btrim(p_display_name), '');
  if cleaned is not null and char_length(cleaned) > 60 then
    raise exception 'a number name must be 60 characters or fewer' using errcode = 'P0001';
  end if;

  select * into sender
  from public.communication_sms_sender_identities
  where id = p_sender_id and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'number not found' using errcode = 'P0001';
  end if;
  if sender.lifecycle_state = 'released' then
    raise exception 'a released number can no longer be changed' using errcode = 'P0001';
  end if;

  update public.communication_sms_sender_identities
  set display_name = cleaned,
      updated_at = now()
  where id = sender.id
  returning * into sender;

  return sender;
end;
$$;


ALTER FUNCTION "public"."communication_sms_rename_sender"("p_organization_id" "uuid", "p_sender_id" "uuid", "p_display_name" "text", "p_actor" "uuid") OWNER TO "postgres";


