CREATE TABLE IF NOT EXISTS "public"."communication_sms_promotional_credits" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "currency_code" "text" DEFAULT 'USD'::"text" NOT NULL,
    "amount_minor" bigint NOT NULL,
    "reason" "text" NOT NULL,
    "granted_by" "uuid",
    "granted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "revoked_by" "uuid",
    "revoked_at" timestamp with time zone,
    "revoke_reason" "text",
    "idempotency_key" "text" NOT NULL,
    CONSTRAINT "communication_sms_promotional_credits_amount_check" CHECK (("amount_minor" > 0)),
    CONSTRAINT "communication_sms_promotional_credits_currency_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "communication_sms_promotional_credits_expiry_check" CHECK (("expires_at" > "granted_at")),
    CONSTRAINT "communication_sms_promotional_credits_idempotency_check" CHECK ((("char_length"(TRIM(BOTH FROM "idempotency_key")) >= 8) AND ("char_length"(TRIM(BOTH FROM "idempotency_key")) <= 200))),
    CONSTRAINT "communication_sms_promotional_credits_lifecycle_check" CHECK (((("status" = 'active'::"text") AND ("revoked_at" IS NULL) AND ("revoked_by" IS NULL) AND ("revoke_reason" IS NULL)) OR (("status" = 'revoked'::"text") AND ("revoked_at" IS NOT NULL) AND ("revoked_by" IS NOT NULL)))),
    CONSTRAINT "communication_sms_promotional_credits_reason_check" CHECK ((("char_length"(TRIM(BOTH FROM "reason")) >= 1) AND ("char_length"(TRIM(BOTH FROM "reason")) <= 2000))),
    CONSTRAINT "communication_sms_promotional_credits_revoke_reason_check" CHECK ((("revoke_reason" IS NULL) OR ("char_length"("revoke_reason") <= 2000))),
    CONSTRAINT "communication_sms_promotional_credits_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'revoked'::"text"])))
);


ALTER TABLE "public"."communication_sms_promotional_credits" OWNER TO "postgres";


COMMENT ON TABLE "public"."communication_sms_promotional_credits" IS 'Jafar-granted, expiring SMS promotional credit, tracked separately from purchased (settled) credit. Expiry is derived on read (active and expires_at > now()), never a stored status, so the balance cannot go stale. Server-owned; writes via the communication_sms_grant/revoke_promotional_credit commands only.';



COMMENT ON COLUMN "public"."communication_sms_promotional_credits"."idempotency_key" IS 'Caller-supplied retry key. unique(organization_id, idempotency_key) makes a repeated grant call a safe no-op replay instead of a second grant.';



CREATE OR REPLACE FUNCTION "public"."communication_sms_revoke_promotional_credit"("p_credit_id" "uuid", "p_revoked_by" "uuid", "p_reason" "text") RETURNS "public"."communication_sms_promotional_credits"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  grant_row public.communication_sms_promotional_credits;
begin
  if p_revoked_by is null then
    raise exception 'revoking a promotional grant must record who revoked it' using errcode = 'P0001';
  end if;
  if p_reason is null or char_length(trim(p_reason)) = 0 then
    raise exception 'revoking a promotional grant must record a reason' using errcode = 'P0001';
  end if;

  update public.communication_sms_promotional_credits
  set status = 'revoked',
      revoked_by = p_revoked_by,
      revoked_at = now(),
      revoke_reason = p_reason
  where id = p_credit_id and status = 'active'
  returning * into grant_row;

  if not found then
    raise exception 'promotional grant % is not active and cannot be revoked', p_credit_id
      using errcode = 'P0001';
  end if;

  return grant_row;
end;
$$;


ALTER FUNCTION "public"."communication_sms_revoke_promotional_credit"("p_credit_id" "uuid", "p_revoked_by" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_save_registration_draft"("p_organization_id" "uuid", "p_registration_id" "uuid", "p_expected_revision" integer, "p_questionnaire_version" integer, "p_answers" "jsonb", "p_actor" "uuid") RETURNS "public"."communication_sms_registrations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare reg public.communication_sms_registrations;
begin
  if p_actor is null then raise exception 'a registration draft must record its editor' using errcode = 'P0001'; end if;
  if p_questionnaire_version is null or p_questionnaire_version < 1 then
    raise exception 'the questionnaire version is invalid' using errcode = 'P0001';
  end if;
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    raise exception 'registration answers must be an object' using errcode = 'P0001';
  end if;

  select * into reg from public.communication_sms_registrations
  where id = p_registration_id and organization_id = p_organization_id for update;
  if not found then raise exception 'registration not found' using errcode = 'P0001'; end if;
  if reg.status not in ('waiting_for_info', 'action_needed') then
    raise exception 'this registration cannot be edited while it is under review or approved' using errcode = 'P0001';
  end if;
  if p_expected_revision is distinct from reg.draft_revision then
    raise exception 'registration draft changed' using errcode = 'P0001',
      detail = json_build_object('code', 'revision_conflict', 'current_revision', reg.draft_revision,
        'updated_by', reg.draft_updated_by, 'updated_at', reg.draft_updated_at)::text;
  end if;

  update public.communication_sms_registrations
  set draft_questionnaire_version = p_questionnaire_version, draft_answers = p_answers,
      draft_revision = draft_revision + 1, draft_updated_by = p_actor, draft_updated_at = now(), updated_at = now()
  where id = reg.id returning * into reg;

  insert into public.communication_sms_registration_events
    (registration_id, organization_id, event_type, from_status, to_status, detail, created_by)
  values (reg.id, reg.organization_id, 'info_updated', reg.status, reg.status,
    'Contractor registration answers saved', p_actor);
  return reg;
end;
$$;


ALTER FUNCTION "public"."communication_sms_save_registration_draft"("p_organization_id" "uuid", "p_registration_id" "uuid", "p_expected_revision" integer, "p_questionnaire_version" integer, "p_answers" "jsonb", "p_actor" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_sms_compliance_settings" (
    "organization_id" "uuid" NOT NULL,
    "opt_out_enabled" boolean DEFAULT true NOT NULL,
    "opt_out_text" "text",
    "sender_info_enabled" boolean DEFAULT true NOT NULL,
    "sender_info_text" "text",
    "periodic_reinsert_days" integer DEFAULT 30 NOT NULL,
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "communication_sms_compliance_settings_opt_out_text_check" CHECK ((("opt_out_text" IS NULL) OR (("char_length"("btrim"("opt_out_text")) >= 1) AND ("char_length"("btrim"("opt_out_text")) <= 320)))),
    CONSTRAINT "communication_sms_compliance_settings_reinsert_days_check" CHECK ((("periodic_reinsert_days" >= 1) AND ("periodic_reinsert_days" <= 60))),
    CONSTRAINT "communication_sms_compliance_settings_sender_info_text_check" CHECK ((("sender_info_text" IS NULL) OR (("char_length"("btrim"("sender_info_text")) >= 1) AND ("char_length"("btrim"("sender_info_text")) <= 320))))
);


ALTER TABLE "public"."communication_sms_compliance_settings" OWNER TO "postgres";


COMMENT ON TABLE "public"."communication_sms_compliance_settings" IS 'Per-organization SMS compliance preferences (opt-out language, sender identification and re-insertion interval), following HighLevel''s SMS Compliance tab. One row per organization; a missing row means defaults. Server-owned: written only through communication_sms_set_compliance_settings.';



CREATE OR REPLACE FUNCTION "public"."communication_sms_set_compliance_settings"("p_organization_id" "uuid", "p_opt_out_enabled" boolean, "p_opt_out_text" "text", "p_sender_info_enabled" boolean, "p_sender_info_text" "text", "p_periodic_reinsert_days" integer, "p_actor" "uuid") RETURNS "public"."communication_sms_compliance_settings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings public.communication_sms_compliance_settings;
  opt_out_clean text;
  sender_info_clean text;
begin
  if p_actor is null then
    raise exception 'a compliance change must record who made it' using errcode = 'P0001';
  end if;
  if p_opt_out_enabled is null or p_sender_info_enabled is null then
    raise exception 'the compliance toggles are required' using errcode = 'P0001';
  end if;
  if p_periodic_reinsert_days is null or p_periodic_reinsert_days < 1 or p_periodic_reinsert_days > 60 then
    raise exception 'the re-insertion interval must be between 1 and 60 days' using errcode = 'P0001';
  end if;

  opt_out_clean := nullif(btrim(p_opt_out_text), '');
  sender_info_clean := nullif(btrim(p_sender_info_text), '');
  if opt_out_clean is not null and char_length(opt_out_clean) > 320 then
    raise exception 'the opt-out wording is too long' using errcode = 'P0001';
  end if;
  if sender_info_clean is not null and char_length(sender_info_clean) > 320 then
    raise exception 'the sender information is too long' using errcode = 'P0001';
  end if;

  insert into public.communication_sms_compliance_settings (
    organization_id, opt_out_enabled, opt_out_text, sender_info_enabled, sender_info_text,
    periodic_reinsert_days, updated_by, updated_at
  ) values (
    p_organization_id, p_opt_out_enabled, opt_out_clean, p_sender_info_enabled, sender_info_clean,
    p_periodic_reinsert_days, p_actor, now()
  )
  on conflict (organization_id) do update
  set opt_out_enabled = excluded.opt_out_enabled,
      opt_out_text = excluded.opt_out_text,
      sender_info_enabled = excluded.sender_info_enabled,
      sender_info_text = excluded.sender_info_text,
      periodic_reinsert_days = excluded.periodic_reinsert_days,
      updated_by = excluded.updated_by,
      updated_at = now()
  returning * into settings;

  return settings;
end;
$$;


ALTER FUNCTION "public"."communication_sms_set_compliance_settings"("p_organization_id" "uuid", "p_opt_out_enabled" boolean, "p_opt_out_text" "text", "p_sender_info_enabled" boolean, "p_sender_info_text" "text", "p_periodic_reinsert_days" integer, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_set_default_sender"("p_organization_id" "uuid", "p_sender_id" "uuid", "p_actor" "uuid") RETURNS "public"."communication_sms_sender_identities"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  sender public.communication_sms_sender_identities;
begin
  if p_actor is null then
    raise exception 'a number change must record who made it' using errcode = 'P0001';
  end if;

  select * into sender
  from public.communication_sms_sender_identities
  where id = p_sender_id and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'number not found' using errcode = 'P0001';
  end if;
  if sender.lifecycle_state <> 'ready' then
    raise exception 'only a ready number can be made the default sending number' using errcode = 'P0001';
  end if;
  if not sender.capable_sms then
    raise exception 'the default sending number must be able to send SMS' using errcode = 'P0001';
  end if;

  update public.communication_sms_sender_identities
  set is_default_sender = false, updated_at = now()
  where organization_id = p_organization_id
    and is_default_sender
    and id <> sender.id;

  update public.communication_sms_sender_identities
  set is_default_sender = true, updated_at = now()
  where id = sender.id
  returning * into sender;

  return sender;
end;
$$;


ALTER FUNCTION "public"."communication_sms_set_default_sender"("p_organization_id" "uuid", "p_sender_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_sms_org_modes" (
    "organization_id" "uuid" NOT NULL,
    "package_max_mode" "text" DEFAULT 'operational'::"text" NOT NULL,
