    CONSTRAINT "communication_sms_org_modes_override_check" CHECK ((("override_mode" IS NULL) OR ("override_mode" = ANY (ARRAY['off'::"text", 'operational'::"text"])))),
    CONSTRAINT "communication_sms_org_modes_override_reason_check" CHECK ((("override_reason" IS NULL) OR ("char_length"("override_reason") <= 2000))),
    CONSTRAINT "communication_sms_org_modes_package_check" CHECK (("package_max_mode" = ANY (ARRAY['off'::"text", 'operational'::"text"])))
);


ALTER TABLE "public"."communication_sms_org_modes" OWNER TO "postgres";


COMMENT ON TABLE "public"."communication_sms_org_modes" IS 'Per-organization SMS mode inputs: package ceiling, contractor choice and an optional Jafar override. The effective mode is derived by communication_sms_effective_mode; a missing row means SMS is off (not included).';



CREATE OR REPLACE FUNCTION "public"."communication_sms_set_org_mode"("p_organization_id" "uuid", "p_set_by" "uuid" DEFAULT NULL::"uuid", "p_package_max_mode" "text" DEFAULT NULL::"text", "p_chosen_mode" "text" DEFAULT NULL::"text", "p_override_mode" "text" DEFAULT NULL::"text", "p_override_reason" "text" DEFAULT NULL::"text", "p_clear_override" boolean DEFAULT false) RETURNS "public"."communication_sms_org_modes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  mode public.communication_sms_org_modes;
  effective_package text;
  effective_chosen text;
begin
  insert into public.communication_sms_org_modes (organization_id, set_by)
  values (p_organization_id, p_set_by)
  on conflict (organization_id) do nothing;

  select * into mode
  from public.communication_sms_org_modes
  where organization_id = p_organization_id
  for update;

  effective_package := coalesce(p_package_max_mode, mode.package_max_mode);
  effective_chosen := coalesce(p_chosen_mode, mode.chosen_mode);

  if effective_package = 'off' and effective_chosen = 'operational' then
    raise exception 'chosen SMS mode operational exceeds the package maximum off' using errcode = 'P0001';
  end if;

  update public.communication_sms_org_modes
  set package_max_mode = effective_package,
      chosen_mode = effective_chosen,
      override_mode = case
        when p_clear_override then null
        when p_override_mode is not null then p_override_mode
        else mode.override_mode
      end,
      override_reason = case
        when p_clear_override then null
        when p_override_mode is not null then p_override_reason
        else mode.override_reason
      end,
      set_by = coalesce(p_set_by, mode.set_by),
      updated_at = now()
  where organization_id = p_organization_id
  returning * into mode;

  return mode;
end;
$$;


ALTER FUNCTION "public"."communication_sms_set_org_mode"("p_organization_id" "uuid", "p_set_by" "uuid", "p_package_max_mode" "text", "p_chosen_mode" "text", "p_override_mode" "text", "p_override_reason" "text", "p_clear_override" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_sms_quiet_hours_policy" (
    "id" boolean DEFAULT true NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "quiet_start" time without time zone DEFAULT '21:00:00'::time without time zone NOT NULL,
    "quiet_end" time without time zone DEFAULT '08:00:00'::time without time zone NOT NULL,
    "time_zone" "text" DEFAULT 'America/New_York'::"text" NOT NULL,
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "communication_sms_quiet_hours_policy_singleton" CHECK ("id")
);


ALTER TABLE "public"."communication_sms_quiet_hours_policy" OWNER TO "postgres";


COMMENT ON TABLE "public"."communication_sms_quiet_hours_policy" IS 'The single platform quiet-hours window for normal outbound SMS. A send inside the window is rescheduled to the window end rather than sent immediately. Recipient-local time and per-country legal rules are a later launch-gate refinement; today the window is evaluated in time_zone.';



CREATE OR REPLACE FUNCTION "public"."communication_sms_set_quiet_hours_policy"("p_enabled" boolean, "p_quiet_start" time without time zone, "p_quiet_end" time without time zone, "p_time_zone" "text", "p_actor" "uuid") RETURNS "public"."communication_sms_quiet_hours_policy"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  policy public.communication_sms_quiet_hours_policy;
begin
  if p_actor is null then
    raise exception 'a quiet-hours change must record who made it' using errcode = 'P0001';
  end if;
  if p_enabled is null then
    raise exception 'the quiet-hours toggle is required' using errcode = 'P0001';
  end if;
  if p_quiet_start is null or p_quiet_end is null then
    raise exception 'the quiet-hours window needs a start and end time' using errcode = 'P0001';
  end if;
  if p_quiet_start = p_quiet_end then
    raise exception 'the quiet-hours window cannot start and end at the same time' using errcode = 'P0001';
  end if;
  if p_time_zone is null or char_length(btrim(p_time_zone)) = 0 then
    raise exception 'the quiet-hours window needs a time zone' using errcode = 'P0001';
  end if;
  -- Reject an unknown IANA zone up front with a clear message instead of failing later at send time.
  begin
    perform now() at time zone p_time_zone;
  exception when others then
    raise exception 'that is not a known time zone' using errcode = 'P0001';
  end;

  update public.communication_sms_quiet_hours_policy
  set enabled = p_enabled,
      quiet_start = p_quiet_start,
      quiet_end = p_quiet_end,
      time_zone = btrim(p_time_zone),
      updated_by = p_actor,
      updated_at = now()
  where id
  returning * into policy;

  return policy;
end;
$$;


ALTER FUNCTION "public"."communication_sms_set_quiet_hours_policy"("p_enabled" boolean, "p_quiet_start" time without time zone, "p_quiet_end" time without time zone, "p_time_zone" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_set_retail_rate"("p_destination" "text", "p_sender_type" "text", "p_message_unit" "text", "p_retail_rate_major" numeric, "p_set_by" "uuid", "p_currency_code" "text" DEFAULT 'USD'::"text", "p_provider_cost_major" numeric DEFAULT NULL::numeric, "p_effective_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."communication_sms_retail_rates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  rate public.communication_sms_retail_rates;
  effective timestamptz := coalesce(p_effective_from, now());
begin
  if effective < now() then
    raise exception 'a retail rate takes effect now or in the future, never retroactively'
      using errcode = 'P0001';
  end if;

  insert into public.communication_sms_retail_rates (
    destination, sender_type, message_unit, currency_code,
    retail_rate_major, provider_cost_major, effective_from, set_by, note
  ) values (
    p_destination, p_sender_type, p_message_unit, coalesce(p_currency_code, 'USD'),
    p_retail_rate_major, p_provider_cost_major, effective, p_set_by, p_note
  )
  returning * into rate;

  return rate;
end;
$$;


ALTER FUNCTION "public"."communication_sms_set_retail_rate"("p_destination" "text", "p_sender_type" "text", "p_message_unit" "text", "p_retail_rate_major" numeric, "p_set_by" "uuid", "p_currency_code" "text", "p_provider_cost_major" numeric, "p_effective_from" timestamp with time zone, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_set_sender_capabilities"("p_sender_identity_id" "uuid", "p_country_code" "text", "p_sender_type" "text", "p_capable_sms" boolean, "p_capable_mms" boolean DEFAULT false, "p_capable_voice" boolean DEFAULT false, "p_registration_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."communication_sms_sender_identities"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  sender public.communication_sms_sender_identities;
begin
  update public.communication_sms_sender_identities
  set country_code = p_country_code,
      sender_type = p_sender_type,
      capable_sms = coalesce(p_capable_sms, false),
      capable_mms = coalesce(p_capable_mms, false),
      capable_voice = coalesce(p_capable_voice, false),
      registration_id = p_registration_id,
      updated_at = now()
  where id = p_sender_identity_id
  returning * into sender;

  if not found then
    raise exception 'sender identity % not found', p_sender_identity_id using errcode = 'P0001';
  end if;

  return sender;
end;
$$;


ALTER FUNCTION "public"."communication_sms_set_sender_capabilities"("p_sender_identity_id" "uuid", "p_country_code" "text", "p_sender_type" "text", "p_capable_sms" boolean, "p_capable_mms" boolean, "p_capable_voice" boolean, "p_registration_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_settle_reservation_price"("p_delivery_intent_id" "uuid", "p_reported_segment_count" integer, "p_reported_provider_price_minor" bigint, "p_reported_provider_price_currency" "text", "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."communication_sms_credit_reservations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  reservation public.communication_sms_credit_reservations;
  settled bigint;
  reserved bigint;
  per_segment_minor numeric;
  corrected_amount_minor bigint;
  delta bigint;
begin
  select * into reservation
  from public.communication_sms_credit_reservations
  where delivery_intent_id = p_delivery_intent_id
  for update;

  if not found then
    raise exception 'No SMS credit reservation exists for this delivery intent.' using errcode = 'P0001';
  end if;

  if reservation.state <> 'reserved' then
    return reservation;
  end if;

  update public.communication_sms_credit_reservations
  set reported_segment_count = p_reported_segment_count,
      reported_provider_price_minor = p_reported_provider_price_minor,
      reported_provider_price_currency = p_reported_provider_price_currency,
      price_checked_at = now()
  where id = reservation.id;

  select settled_balance_minor, reserved_balance_minor into settled, reserved
  from public.communication_sms_credit_accounts
  where organization_id = reservation.organization_id
  for update;

  update public.communication_sms_credit_accounts
  set settled_balance_minor = settled - reservation.reserved_purchased_minor,
      reserved_balance_minor = reserved - reservation.reserved_purchased_minor,
      updated_at = now()
  where organization_id = reservation.organization_id;

  insert into public.communication_sms_credit_ledger_entries (
    organization_id, reservation_id, source_key, entry_kind, amount_minor, balance_after_minor, occurred_at
  ) values (
    reservation.organization_id, reservation.id, 'charge:' || reservation.source_key, 'charge',
    -reservation.reserved_purchased_minor, settled - reservation.reserved_purchased_minor, now()
  );

  update public.communication_sms_credit_reservations
  set state = 'settled', settled_at = now()
  where id = reservation.id;

  if p_reported_segment_count is not null and p_reported_segment_count <> reservation.segment_count then
    per_segment_minor := reservation.amount_minor::numeric / reservation.segment_count;
    corrected_amount_minor := ceil(p_reported_segment_count * per_segment_minor)::bigint;
    delta := corrected_amount_minor - reservation.amount_minor;
    if delta <> 0 then
      perform public.communication_sms_record_adjustment(
        reservation.organization_id,
        -delta,
        format(
          'SMS segment recount: Twilio billed %s segment(s) for this message; %s were estimated at send time.',
          p_reported_segment_count, reservation.segment_count
        ),
        'price-reconciliation:' || reservation.delivery_intent_id::text,
        p_actor
      );
    end if;
  end if;

  select * into reservation
  from public.communication_sms_credit_reservations
  where id = reservation.id;

  return reservation;
end;
$$;


ALTER FUNCTION "public"."communication_sms_settle_reservation_price"("p_delivery_intent_id" "uuid", "p_reported_segment_count" integer, "p_reported_provider_price_minor" bigint, "p_reported_provider_price_currency" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_spendable_balance"("p_organization_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(
    (select settled_balance_minor - reserved_balance_minor
     from public.communication_sms_credit_accounts
     where organization_id = p_organization_id),
    0
  )::bigint
  + public.communication_sms_promotional_balance(p_organization_id);
$$;


ALTER FUNCTION "public"."communication_sms_spendable_balance"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_start_registration"("p_organization_id" "uuid", "p_country_code" "text", "p_sender_type" "text", "p_use_case" "text", "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."communication_sms_registrations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  reg public.communication_sms_registrations;
  existed boolean := false;
begin
  select * into reg
  from public.communication_sms_registrations
  where organization_id = p_organization_id
    and country_code = p_country_code
    and sender_type = p_sender_type
    and use_case = p_use_case
  for update;

  existed := found;

  if not existed then
    insert into public.communication_sms_registrations (
      organization_id, country_code, sender_type, use_case
    ) values (
      p_organization_id, p_country_code, p_sender_type, p_use_case
    )
    returning * into reg;
  else
    update public.communication_sms_registrations
    set updated_at = now()
    where id = reg.id
    returning * into reg;
  end if;

  insert into public.communication_sms_registration_events (
    registration_id, organization_id, event_type, to_status, created_by
  ) values (
    reg.id, reg.organization_id,
    case when existed then 'info_updated' else 'started' end,
    reg.status, p_actor
  );

  return reg;
end;
$$;


ALTER FUNCTION "public"."communication_sms_start_registration"("p_organization_id" "uuid", "p_country_code" "text", "p_sender_type" "text", "p_use_case" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_submit_registration"("p_registration_id" "uuid", "p_attested_by" "uuid", "p_provider_registration_sid" "text" DEFAULT NULL::"text") RETURNS "public"."communication_sms_registrations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  reg public.communication_sms_registrations;
  prior_status text;
begin
  if p_attested_by is null then
    raise exception 'a registration submission must be attested by a user' using errcode = 'P0001';
  end if;

  select * into reg
  from public.communication_sms_registrations
  where id = p_registration_id
  for update;

  if not found then
    raise exception 'registration % not found', p_registration_id using errcode = 'P0001';
  end if;
  if reg.status not in ('waiting_for_info', 'action_needed') then
    raise exception 'registration % is % and cannot be submitted', p_registration_id, reg.status
      using errcode = 'P0001';
  end if;

  prior_status := reg.status;

  update public.communication_sms_registrations
  set status = 'under_review',
      attested_by = p_attested_by,
      attested_at = now(),
      submitted_at = now(),
      provider_registration_sid = coalesce(p_provider_registration_sid, provider_registration_sid),
      required_fixes = null,
      updated_at = now()
  where id = reg.id
  returning * into reg;

  insert into public.communication_sms_registration_events (
    registration_id, organization_id, event_type, from_status, to_status, created_by
  ) values (
    reg.id, reg.organization_id,
    case when prior_status = 'action_needed' then 'resubmitted' else 'submitted' end,
    prior_status, reg.status, p_attested_by
  );

  return reg;
end;
$$;


ALTER FUNCTION "public"."communication_sms_submit_registration"("p_registration_id" "uuid", "p_attested_by" "uuid", "p_provider_registration_sid" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_submit_registration_answers"("p_organization_id" "uuid", "p_registration_id" "uuid", "p_expected_revision" integer, "p_questionnaire_version" integer, "p_answers" "jsonb", "p_attestation_version" "text", "p_attestation_text" "text", "p_attested_by" "uuid", "p_attestor_email" "text") RETURNS "public"."communication_sms_registrations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  reg public.communication_sms_registrations;
  prior_status text;
  next_submission_number integer;
begin
  if p_attested_by is null then raise exception 'a registration submission must be attested by a user' using errcode = 'P0001'; end if;
  if p_questionnaire_version is null or p_questionnaire_version < 1 then
    raise exception 'the questionnaire version is invalid' using errcode = 'P0001';
  end if;
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' or p_answers = '{}'::jsonb then
    raise exception 'complete registration answers are required' using errcode = 'P0001';
  end if;
  if p_attestation_version is null or char_length(trim(p_attestation_version)) = 0
     or p_attestation_text is null or char_length(trim(p_attestation_text)) = 0 then
    raise exception 'the attestation wording is required' using errcode = 'P0001';
  end if;
  if p_attestor_email is null or char_length(trim(p_attestor_email)) < 3 then
    raise exception 'the authenticated attestor email is required' using errcode = 'P0001';
  end if;

  select * into reg from public.communication_sms_registrations
  where id = p_registration_id and organization_id = p_organization_id for update;
  if not found then raise exception 'registration not found' using errcode = 'P0001'; end if;
  if reg.status not in ('waiting_for_info', 'action_needed') then
    raise exception 'this registration cannot be submitted while it is under review or approved' using errcode = 'P0001';
  end if;
  if p_expected_revision is distinct from reg.draft_revision then
    raise exception 'registration draft changed' using errcode = 'P0001',
      detail = json_build_object('code', 'revision_conflict', 'current_revision', reg.draft_revision)::text;
  end if;

  prior_status := reg.status;
  select coalesce(max(submission_number), 0) + 1 into next_submission_number
  from public.communication_sms_registration_submissions where registration_id = reg.id;

  insert into public.communication_sms_registration_submissions
    (organization_id, registration_id, submission_number, questionnaire_version, answers,
     attestation_version, attestation_text, attested_by, attestor_email)
  values (reg.organization_id, reg.id, next_submission_number, p_questionnaire_version, p_answers,
    trim(p_attestation_version), trim(p_attestation_text), p_attested_by, lower(trim(p_attestor_email)));

  update public.communication_sms_registrations
  set status = 'under_review', draft_questionnaire_version = p_questionnaire_version,
      draft_answers = p_answers, draft_revision = draft_revision + 1, draft_updated_by = p_attested_by,
      draft_updated_at = now(), attested_by = p_attested_by, attested_at = now(),
      submitted_at = now(), required_fixes = null, updated_at = now()
  where id = reg.id returning * into reg;

  insert into public.communication_sms_registration_events
    (registration_id, organization_id, event_type, from_status, to_status, detail, created_by)
  values (reg.id, reg.organization_id,
    case when prior_status = 'action_needed' then 'resubmitted' else 'submitted' end,
    prior_status, reg.status, 'Contractor submission ' || next_submission_number::text, p_attested_by);
  return reg;
end;
$$;


ALTER FUNCTION "public"."communication_sms_submit_registration_answers"("p_organization_id" "uuid", "p_registration_id" "uuid", "p_expected_revision" integer, "p_questionnaire_version" integer, "p_answers" "jsonb", "p_attestation_version" "text", "p_attestation_text" "text", "p_attested_by" "uuid", "p_attestor_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_sms_usage_reconciliation_our_totals"("p_organization_id" "uuid", "p_window_start" "date", "p_window_end" "date") RETURNS TABLE("usage_date" "date", "message_count" integer, "price_minor" bigint, "price_currency" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    (intent.accepted_at at time zone 'utc')::date as usage_date,
    count(*)::integer as message_count,
    coalesce(sum(reservation.reported_provider_price_minor), 0)::bigint as price_minor,
    max(reservation.reported_provider_price_currency) as price_currency
  from public.communication_delivery_intents intent
  join public.communication_sms_credit_reservations reservation
    on reservation.delivery_intent_id = intent.id
  where intent.organization_id = p_organization_id
    and intent.channel = 'sms'
    and intent.status = 'submitted'
    and (intent.accepted_at at time zone 'utc')::date between p_window_start and p_window_end
  group by 1
  order by 1;
$$;


ALTER FUNCTION "public"."communication_sms_usage_reconciliation_our_totals"("p_organization_id" "uuid", "p_window_start" "date", "p_window_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_twilio_complete_auth_token_rotation"("p_account_id" "uuid", "p_retire_after" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  staged_count integer;
  current_count integer;
begin
  select count(*) into staged_count
  from public.communication_twilio_credentials
  where twilio_account_id = p_account_id
    and credential_purpose = 'auth_token'
    and lifecycle_state = 'staged';

  select count(*) into current_count
  from public.communication_twilio_credentials
  where twilio_account_id = p_account_id
    and credential_purpose = 'auth_token'
    and lifecycle_state = 'current';

  if staged_count <> 1 or current_count <> 1 then
    raise exception 'auth token rotation requires exactly one staged and one current credential'
      using errcode = 'P0001';
  end if;

  delete from public.communication_twilio_credentials
  where twilio_account_id = p_account_id
    and credential_purpose = 'auth_token'
    and lifecycle_state = 'prior';

  update public.communication_twilio_credentials
  set lifecycle_state = 'prior', retire_after = p_retire_after, updated_at = now()
  where twilio_account_id = p_account_id
    and credential_purpose = 'auth_token'
    and lifecycle_state = 'current';

  update public.communication_twilio_credentials
  set lifecycle_state = 'current', retire_after = null, updated_at = now()
  where twilio_account_id = p_account_id
    and credential_purpose = 'auth_token'
    and lifecycle_state = 'staged';
end;
$$;


ALTER FUNCTION "public"."communication_twilio_complete_auth_token_rotation"("p_account_id" "uuid", "p_retire_after" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_twilio_complete_restricted_key_rotation"("p_account_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  staged_count integer;
  current_count integer;
begin
  select count(*) into staged_count
  from public.communication_twilio_credentials
  where twilio_account_id = p_account_id
    and credential_purpose = 'restricted_api_key'
    and lifecycle_state = 'staged';

  select count(*) into current_count
  from public.communication_twilio_credentials
  where twilio_account_id = p_account_id
    and credential_purpose = 'restricted_api_key'
    and lifecycle_state = 'current';

  if staged_count <> 1 or current_count <> 1 then
    raise exception 'restricted key rotation requires exactly one staged and one current credential'
      using errcode = 'P0001';
  end if;

  delete from public.communication_twilio_credentials
  where twilio_account_id = p_account_id
    and credential_purpose = 'restricted_api_key'
    and lifecycle_state = 'current';

  update public.communication_twilio_credentials
  set lifecycle_state = 'current', updated_at = now()
  where twilio_account_id = p_account_id
    and credential_purpose = 'restricted_api_key'
    and lifecycle_state = 'staged';
end;
$$;


ALTER FUNCTION "public"."communication_twilio_complete_restricted_key_rotation"("p_account_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_twilio_accounts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "provider" "text" DEFAULT 'twilio'::"text" NOT NULL,
    "subaccount_sid" "text" NOT NULL,
    "messaging_service_sid" "text",
    "lifecycle_state" "text" DEFAULT 'provisioning'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "usage_reconciled_through" "date",
    "usage_reconciliation_checked_at" timestamp with time zone,
    CONSTRAINT "communication_twilio_accounts_lifecycle_check" CHECK (("lifecycle_state" = ANY (ARRAY['provisioning'::"text", 'ready'::"text", 'restricted'::"text", 'suspended'::"text", 'closed'::"text"]))),
    CONSTRAINT "communication_twilio_accounts_messaging_service_sid_check" CHECK ((("messaging_service_sid" IS NULL) OR ("messaging_service_sid" ~ '^MG[0-9A-Fa-f]{32}$'::"text"))),
    CONSTRAINT "communication_twilio_accounts_provider_check" CHECK (("provider" = 'twilio'::"text")),
    CONSTRAINT "communication_twilio_accounts_subaccount_sid_check" CHECK (("subaccount_sid" ~ '^AC[0-9A-Fa-f]{32}$'::"text"))
);


ALTER TABLE "public"."communication_twilio_accounts" OWNER TO "postgres";


COMMENT ON COLUMN "public"."communication_twilio_accounts"."usage_reconciled_through" IS 'Last usage_date (GMT) whose Twilio Usage Records window has already been compared against our own settled totals for this org. Null until the first check ever runs.';



CREATE OR REPLACE FUNCTION "public"."communication_twilio_store_provisioned_subaccount"("p_organization_id" "uuid", "p_subaccount_sid" "text", "p_auth_token_credential_id" "uuid", "p_encryption_key_id" "text", "p_nonce" "bytea", "p_ciphertext" "bytea", "p_authentication_tag" "bytea") RETURNS "public"."communication_twilio_accounts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  acct public.communication_twilio_accounts;
begin
  insert into public.communication_twilio_accounts (organization_id, subaccount_sid)
  values (p_organization_id, p_subaccount_sid)
  returning * into acct;

  insert into public.communication_twilio_credentials (
    id, organization_id, twilio_account_id, credential_purpose, lifecycle_state,
    encryption_key_id, nonce, ciphertext, authentication_tag
  ) values (
    p_auth_token_credential_id, p_organization_id, acct.id, 'auth_token', 'current',
    p_encryption_key_id, p_nonce, p_ciphertext, p_authentication_tag
  );

  return acct;
end;
$$;


