CREATE OR REPLACE FUNCTION "public"."complete_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  current_visit public.job_visits;
  remaining_incomplete integer;
  new_reminder_id uuid;
  final_visit boolean := false;
begin
  if caller is null then
    raise exception 'You must be signed in to complete a visit.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.complete') then
    raise exception 'You do not have access to complete this visit.' using errcode = 'insufficient_privilege';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id
  for update;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  if current_job.status = 'closed' then
    raise exception 'A closed job''s visits cannot be changed. Reopen the job first.' using errcode = 'P0410';
  end if;

  select visit.* into current_visit
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.id = target_visit_id
  for update;
  if not found then
    raise exception 'That visit could not be found.' using errcode = 'P0404';
  end if;

  if current_visit.completed_at is not null then
    return jsonb_build_object(
      'applied', true, 'already_completed', true, 'revision', current_visit.revision, 'final_visit', false
    );
  end if;

  update public.job_visits
  set completed_at = now(), completed_by = caller, revision = revision + 1, updated_at = now()
  where organization_id = target_organization_id and id = target_visit_id
  returning * into current_visit;

  -- Internal to-do, raised the moment the billable event happens; private.create_invoice_reminder is the
  -- one primitive every reminder is born through (Part 11b), and it is already a no-op if one is open.
  if current_job.billing_timing = 'per_completed_visit' then
    new_reminder_id := private.create_invoice_reminder(
      target_organization_id,
      target_job_id,
      'per_visit',
      private.organization_today(target_organization_id),
      caller,
      target_visit_id
    );
  end if;

  select count(*) into remaining_incomplete
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.completed_at is null;

  -- Only a one-off job asks the question. A recurring job's incomplete visits are its future occurrences,
  -- not open work to close out.
  final_visit := remaining_incomplete = 0 and current_job.job_type = 'one_off';

  insert into public.job_events (organization_id, job_id, event_type, actor_id, related_visit_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'visit_completed',
    caller,
    target_visit_id,
    jsonb_build_object('final_visit', final_visit)
  );

  return jsonb_build_object(
    'applied', true,
    'already_completed', false,
    'revision', current_visit.revision,
    'final_visit', final_visit,
    'reminder_id', new_reminder_id
  );
end;
$$;


ALTER FUNCTION "public"."complete_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid") IS 'Marks a visit complete. Checks jobs.complete, refuses on a closed job (P0410), is idempotent on an already-completed visit, fires the per_visit reminder when the job bills per completed visit, and reports final_visit when this was the last incomplete visit of a one-off job.';



CREATE OR REPLACE FUNCTION "public"."confirm_onboarding_application_payment"("target_application_id" "uuid", "actor_email" "text", "amount_usd_cents" integer, "private_reference" "text", "mismatch_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  app_stage text;
  app_package_version_id uuid;
begin
  select stage, package_version_id into app_stage, app_package_version_id
  from public.platform_onboarding_applications
  where id = target_application_id
  for update;

  if not found then
    raise exception 'The onboarding application does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if app_stage not in ('new', 'awaiting_payment', 'needs_attention') then
    raise exception 'This application can no longer be confirmed for payment.' using errcode = 'check_violation';
  end if;

  insert into public.platform_onboarding_application_payment_confirmations (
    application_id, actor_owner_email, amount_usd_cents, private_reference,
    package_version_id, mismatch_reason
  ) values (
    target_application_id, actor_email, amount_usd_cents, private_reference,
    app_package_version_id, mismatch_reason
  );

  update public.platform_onboarding_applications
  set stage = 'payment_confirmed', payment_reversed_at = null
  where id = target_application_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, after_state
  ) values (
    actor_email, 'onboarding_application.payment_confirmed', 'onboarding_application',
    target_application_id::text,
    jsonb_build_object('amount_usd_cents', amount_usd_cents, 'mismatch_reason', mismatch_reason)
  );
end;
$$;


ALTER FUNCTION "public"."confirm_onboarding_application_payment"("target_application_id" "uuid", "actor_email" "text", "amount_usd_cents" integer, "private_reference" "text", "mismatch_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_onboarding_application_setup_link"("target_token_hash" "text", "target_email" "text") RETURNS TABLE("consumed" boolean, "application_id" "uuid", "administrator_user_id" "uuid")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_row record;
begin
  update public.platform_onboarding_application_setup_links as links
  set consumed_at = now()
  where links.token_hash = target_token_hash
    and links.consumed_at is null
    and links.expires_at > now()
    and links.intended_email = target_email
  returning links.application_id, links.administrator_user_id
  into updated_row;

  if found then
    return query select true, updated_row.application_id, updated_row.administrator_user_id;
  else
    return query select false, null::uuid, null::uuid;
  end if;
end;
$$;


ALTER FUNCTION "public"."consume_onboarding_application_setup_link"("target_token_hash" "text", "target_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_quote_to_job"("target_quote_id" "uuid", "idempotency_key" "text", "request_hash" "text", "new_job_type" "text" DEFAULT 'one_off'::"text", "new_price_basis" "text" DEFAULT NULL::"text", "new_title" "text" DEFAULT NULL::"text", "new_billing_timing" "text" DEFAULT 'on_closure'::"text", "new_is_as_needed" boolean DEFAULT false, "new_instructions" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  version_row public.quote_versions;
  existing_job public.jobs;
  created_job public.jobs;
  chosen_addons uuid[];
  resolved_basis text;
  resolved_title text;
  copied_count integer;
  copied_stage_count integer := 0;
  calculated jsonb;
begin
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(request_hash, ''))) < 1 then
    raise exception 'A quote fingerprint is required.' using errcode = 'check_violation';
  end if;
  if new_job_type not in ('one_off', 'recurring') then
    raise exception 'A job is either one-off or recurring.' using errcode = 'check_violation';
  end if;

  select * into quote_row from public.quotes where id = target_quote_id for update;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.convert'
     )
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'jobs.create'
     ) then
    raise exception 'You do not have access to turn this quote into a job.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into existing_job
  from public.jobs
  where organization_id = quote_row.organization_id
    and quote_id = target_quote_id
  for update;

  if found then
    if existing_job.conversion_idempotency_key is not distinct from idempotency_key
       and existing_job.conversion_request_hash is not distinct from request_hash then
      return jsonb_build_object(
        'applied', false,
        'job_id', existing_job.id,
        'job_number', existing_job.job_number,
        'quote_id', quote_row.id,
        'quote_status', quote_row.status
      );
    end if;

    raise exception 'This quote already has a job.' using errcode = 'P0409';
  end if;

  if quote_row.status <> 'approved' then
    raise exception 'Only an approved quote can become a job.' using errcode = 'check_violation';
  end if;

  if not public.quote_ready_for_job(target_quote_id) then
    raise exception 'This quote is not ready for a job yet.' using errcode = 'check_violation';
  end if;

  select * into version_row
  from public.quote_versions
  where organization_id = quote_row.organization_id
    and id = quote_row.current_published_version_id
  for update;

  if version_row.id is null then
    raise exception 'This quote has no approved version to copy.' using errcode = 'check_violation';
  end if;

  resolved_basis := coalesce(
    new_price_basis,
    case when new_job_type = 'one_off' then 'job_total' else 'per_visit' end
  );
  resolved_title := coalesce(nullif(trim(coalesce(new_title, '')), ''), quote_row.title);

  created_job := private.create_job(
    quote_row.organization_id,
    quote_row.client_id,
    quote_row.property_id,
    resolved_title,
    new_job_type,
    resolved_basis,
    quote_row.currency_code,
    (select auth.uid()),
    coalesce(new_is_as_needed, false),
    coalesce(new_billing_timing, 'on_closure'),
    new_instructions,
    quote_row.id,
    version_row.id,
    idempotency_key,
    request_hash
  );

  update public.jobs
  set discount_name = version_row.discount_name,
      discount_type = version_row.discount_type,
      discount_value = version_row.discount_value,
      tax_source = version_row.tax_source,
      tax_name = version_row.tax_name,
      tax_rate_basis_points = version_row.tax_rate_basis_points,
      tax_rate_id = version_row.tax_rate_id
  where id = created_job.id;

  select coalesce(array_agg((chosen.value #>> '{}')::uuid), '{}'::uuid[])
  into chosen_addons
  from jsonb_array_elements(
    case
      when jsonb_typeof(version_row.calculation->'selected_addon_ids') = 'array'
        then version_row.calculation->'selected_addon_ids'
      else '[]'::jsonb
    end
  ) as chosen(value);

  insert into public.job_line_items (
    organization_id, job_id, position, source_catalog_item_id, line_kind, category, is_labor,
    name, description, unit_label, quantity, unit_price_minor, unit_cost_minor, is_taxable,
    image_attachment_id
  )
  select
    created_job.organization_id,
    created_job.id,
    (row_number() over (order by line.position, line.id))::integer - 1,
    line.source_catalog_item_id,
    line.line_kind,
    line.category,
    line.is_labor,
    line.name,
    line.description,
    line.unit_label,
    line.quantity,
    line.unit_price_minor,
    line.unit_cost_minor,
    line.is_taxable,
    line.image_attachment_id
  from public.quote_version_lines as line
  where line.organization_id = quote_row.organization_id
    and line.quote_id = quote_row.id
    and line.quote_version_id = version_row.id
    and (line.selection_kind = 'required' or line.id = any(chosen_addons));

  get diagnostics copied_count = row_count;

  calculated := private.store_job_money(created_job.id);

  if (calculated->>'total_minor')::bigint is distinct from version_row.total_minor then
    raise exception 'The job total does not match the approved quote total.' using errcode = 'check_violation';
  end if;

  if version_row.deposit_type = 'schedule' and created_job.job_type = 'one_off' then
    insert into public.job_payment_schedule_items (
      organization_id, job_id, position, description, value_type, value, is_deposit
    )
    select
      created_job.organization_id,
      created_job.id,
      (row_number() over (order by item.position, item.id))::integer - 1,
      item.description,
      item.value_type,
      item.value,
      item.is_deposit
    from public.quote_version_schedule_items as item
    where item.organization_id = quote_row.organization_id
      and item.quote_id = quote_row.id
      and item.quote_version_id = version_row.id;

    get diagnostics copied_stage_count = row_count;

    perform private.price_job_payment_schedule(created_job.id);
  end if;

  update public.quotes set status = 'converted' where id = quote_row.id;

  insert into public.job_events (
    organization_id, job_id, event_type, actor_id, new_status, related_quote_id, metadata
  ) values (
    created_job.organization_id,
    created_job.id,
    'job_converted_from_quote',
    (select auth.uid()),
    'active',
    quote_row.id,
    jsonb_build_object(
      'quote_number', quote_row.quote_number,
      'quote_version_number', version_row.version_number,
      'line_count', copied_count,
      'payment_stage_count', copied_stage_count
    )
  );

  insert into public.activity_events (
    organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
  ) values (
    quote_row.organization_id, 'quote', quote_row.id, 'quote.converted',
    'Turned this quote into a job',
    (select auth.uid()),
    jsonb_build_object(
      'job_number', created_job.job_number,
      'version_number', version_row.version_number,
      'line_count', copied_count
    )
  );

  return jsonb_build_object(
    'applied', true,
    'job_id', created_job.id,
    'job_number', created_job.job_number,
    'job_type', created_job.job_type,
    'price_basis', created_job.price_basis,
    'line_count', copied_count,
    'payment_stage_count', copied_stage_count,
    'quote_id', quote_row.id,
    'quote_status', 'converted'
  );
end;
$$;


ALTER FUNCTION "public"."convert_quote_to_job"("target_quote_id" "uuid", "idempotency_key" "text", "request_hash" "text", "new_job_type" "text", "new_price_basis" "text", "new_title" "text", "new_billing_timing" "text", "new_is_as_needed" boolean, "new_instructions" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."convert_quote_to_job"("target_quote_id" "uuid", "idempotency_key" "text", "request_hash" "text", "new_job_type" "text", "new_price_basis" "text", "new_title" "text", "new_billing_timing" "text", "new_is_as_needed" boolean, "new_instructions" "text") IS 'The one quote-to-job handoff. Copies the approved version''s selected scope and payment schedule into job-owned rows, makes the quote terminally converted, and returns the first job again for a retry carrying the same key.';



CREATE OR REPLACE FUNCTION "public"."convert_request_to_quote"("target_request_id" "uuid", "idempotency_key" "text", "request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  request_row public.requests;
  source_opportunity public.opportunities;
  existing_quote public.quotes;
  new_quote public.quotes;
  new_version public.quote_versions;
  new_opportunity_id uuid;
  allocated_number integer;
  organization_currency text;
  organization_name text;
  client_name text;
  property_row public.properties;
  copied_count integer;
  copied_subtotal bigint;
begin
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(request_hash, ''))) < 1 then
    raise exception 'A request fingerprint is required.' using errcode = 'check_violation';
  end if;

  -- Lock order matches the outcome engine: the pipeline card first, then its request. Two commands racing
  -- on the same work therefore queue up instead of deadlocking against each other.
  select * into source_opportunity
  from public.opportunities
  where request_id = target_request_id
  for update;

  select * into request_row
  from public.requests
  where id = target_request_id
  for update;

  -- One answer for "no such request" and "not your request": a stranger learns nothing either way.
  if request_row.id is null
     or not private.member_has_permission(
       request_row.organization_id, (select auth.uid()), 'quotes.create'
     ) then
    raise exception 'You do not have access to create a quote from this request.'
      using errcode = 'insufficient_privilege';
  end if;

  -- Idempotency is checked before state. A retry that arrives after the first call already succeeded must
  -- be recognised as the same command, not rejected as "already converted".
  select * into existing_quote
  from public.quotes
  where organization_id = request_row.organization_id
    and request_id = target_request_id
  for update;

  if found then
    if existing_quote.conversion_idempotency_key is not distinct from idempotency_key
       and existing_quote.conversion_request_hash is not distinct from request_hash then
      return jsonb_build_object(
        'applied', false,
        'quote_id', existing_quote.id,
        'quote_number', existing_quote.quote_number,
        'quote_version_id', existing_quote.draft_version_id,
        'status', existing_quote.status
      );
    end if;

    raise exception 'This request already has a quote.' using errcode = 'P0409';
  end if;

  -- A finished assessment is still convertible: in Jobber that is exactly the moment the office is meant
  -- to price the work. Completed, converted, and archived requests are not live work any more.
  if request_row.status not in ('new', 'unscheduled', 'assessment_completed') then
    raise exception 'This request cannot be turned into a quote right now.' using errcode = 'check_violation';
  end if;

  select settings.currency_code into organization_currency
  from public.organization_settings as settings
  where settings.organization_id = request_row.organization_id;

  select organization.name into organization_name
  from public.organizations as organization
  where organization.id = request_row.organization_id;

  select client.display_name into client_name
  from public.clients as client
  where client.id = request_row.client_id;

  select * into property_row
  from public.properties
  where id = request_row.property_id;

  allocated_number := private.allocate_quote_number(request_row.organization_id);

  insert into public.quotes (
    organization_id, client_id, property_id, request_id, quote_number, title, currency_code,
    conversion_idempotency_key, conversion_request_hash, created_by
  ) values (
    request_row.organization_id,
    request_row.client_id,
    request_row.property_id,
    target_request_id,
    allocated_number,
    request_row.title,
    coalesce(organization_currency, 'USD'),
    idempotency_key,
    request_hash,
    (select auth.uid())
  )
  returning * into new_quote;

  insert into public.quote_versions (
    organization_id, quote_id, version_number, status, currency_code,
    client_display_name, organization_name,
    service_address_line1, service_address_line2, service_city,
    service_state_region, service_postal_code, service_country,
    created_by
  ) values (
    new_quote.organization_id,
    new_quote.id,
    1,
    'draft',
    new_quote.currency_code,
    client_name,
    organization_name,
    property_row.address_line1,
    property_row.address_line2,
    property_row.city,
    property_row.state_region,
    property_row.postal_code,
    property_row.country,
    (select auth.uid())
  )
  returning * into new_version;

  -- The copy is what makes the quote its own document. From here the catalog and the request can change
  -- as much as anyone likes and these numbers do not move.
  insert into public.quote_version_lines (
    organization_id, quote_id, quote_version_id, position, source_catalog_item_id, category, is_labor,
    name, description, unit_label, quantity, unit_price_minor, unit_cost_minor, is_taxable,
    image_attachment_id
  )
  select
    line.organization_id, new_quote.id, new_version.id, line.position, line.catalog_item_id,
    line.category, line.is_labor, line.name, line.description, line.unit_label,
    line.quantity, line.unit_price_minor, line.unit_cost_minor, line.is_taxable,
    line.image_attachment_id
  from public.request_pricing_lines as line
  where line.organization_id = request_row.organization_id
    and line.request_id = target_request_id;

  select coalesce(sum(line.line_total_minor), 0), count(*)
  into copied_subtotal, copied_count
  from public.quote_version_lines as line
  where line.organization_id = new_quote.organization_id
    and line.quote_id = new_quote.id
    and line.quote_version_id = new_version.id;

  update public.quote_versions set subtotal_minor = copied_subtotal where id = new_version.id;
  update public.quotes set draft_version_id = new_version.id where id = new_quote.id;

  -- The quote gets its own card. The stage trigger parks it off the board.
  insert into public.opportunities (organization_id, client_id, property_id, quote_id, title)
  values (new_quote.organization_id, new_quote.client_id, new_quote.property_id, new_quote.id, new_quote.title)
  returning id into new_opportunity_id;

  -- Only work still to be done follows the quote. A task somebody already finished belongs to the request
  -- as history and stays where it happened. No limit check is needed: the new card starts empty and the
  -- old one already respected the five-open cap.
  if source_opportunity.id is not null then
    update public.tasks
    set opportunity_id = new_opportunity_id
    where organization_id = new_quote.organization_id
      and opportunity_id = source_opportunity.id
      and status = 'open';
  end if;

  -- This one update is also what takes the original request card off the board: the Part 1 resync trigger
  -- recomputes its stage from the new status without any extra code here.
  update public.requests set status = 'converted' where id = target_request_id;

  return jsonb_build_object(
    'applied', true,
    'quote_id', new_quote.id,
    'quote_number', new_quote.quote_number,
    'quote_version_id', new_version.id,
    'status', new_quote.status,
    'line_count', copied_count,
    'subtotal_minor', copied_subtotal
  );
end;
$$;


ALTER FUNCTION "public"."convert_request_to_quote"("target_request_id" "uuid", "idempotency_key" "text", "request_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."correct_onboarding_application"("target_application_id" "uuid", "actor_email" "text", "correction_reason" "text", "new_business_name" "text", "new_main_contact_name" "text", "new_main_contact_email" "text", "new_main_contact_phone" "text", "new_initial_administrator_name" "text", "new_initial_administrator_email" "text", "new_trade" "text", "new_city_country" "text", "new_time_zone" "text", "new_note" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current record;
  before_state jsonb;
  after_state jsonb;
begin
  select stage, business_name, main_contact_name, main_contact_email, main_contact_phone,
    initial_administrator_name, initial_administrator_email, trade, city_country, time_zone, note
  into current
  from public.platform_onboarding_applications
  where id = target_application_id
  for update;

  if not found then
    raise exception 'The onboarding application does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if current.stage not in ('new', 'awaiting_payment', 'payment_confirmed', 'needs_attention') then
    raise exception 'This application can no longer be corrected.' using errcode = 'check_violation';
  end if;

  before_state := jsonb_build_object(
    'business_name', current.business_name,
    'main_contact_name', current.main_contact_name,
    'main_contact_email', current.main_contact_email,
    'main_contact_phone', current.main_contact_phone,
    'initial_administrator_name', current.initial_administrator_name,
    'initial_administrator_email', current.initial_administrator_email,
    'trade', current.trade,
    'city_country', current.city_country,
    'time_zone', current.time_zone,
    'note', current.note
  );
  after_state := jsonb_build_object(
    'business_name', new_business_name,
    'main_contact_name', new_main_contact_name,
    'main_contact_email', new_main_contact_email,
    'main_contact_phone', new_main_contact_phone,
    'initial_administrator_name', new_initial_administrator_name,
    'initial_administrator_email', new_initial_administrator_email,
    'trade', new_trade,
    'city_country', new_city_country,
    'time_zone', new_time_zone,
    'note', new_note
  );

  update public.platform_onboarding_applications
  set business_name = new_business_name,
    main_contact_name = new_main_contact_name,
    main_contact_email = new_main_contact_email,
    main_contact_phone = new_main_contact_phone,
    initial_administrator_name = new_initial_administrator_name,
    initial_administrator_email = new_initial_administrator_email,
    trade = new_trade,
    city_country = new_city_country,
    time_zone = new_time_zone,
    note = new_note
  where id = target_application_id;

  insert into public.platform_onboarding_application_corrections (
    application_id, actor_owner_email, reason, before_state, after_state
  ) values (
    target_application_id, actor_email, correction_reason, before_state, after_state
  );

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor_email, 'onboarding_application.corrected', 'onboarding_application',
    target_application_id::text, before_state, after_state || jsonb_build_object('reason', correction_reason)
  );
end;
$$;


ALTER FUNCTION "public"."correct_onboarding_application"("target_application_id" "uuid", "actor_email" "text", "correction_reason" "text", "new_business_name" "text", "new_main_contact_name" "text", "new_main_contact_email" "text", "new_main_contact_phone" "text", "new_initial_administrator_name" "text", "new_initial_administrator_email" "text", "new_trade" "text", "new_city_country" "text", "new_time_zone" "text", "new_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."correct_onboarding_application_package"("target_application_id" "uuid", "actor_email" "text", "new_package_version_id" "uuid", "correction_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current record;
  already_paid boolean;
  version_status text;
  package_status text;
  new_snapshot jsonb;
  before_state jsonb;
  after_state jsonb;
begin
  select stage, package_version_id, package_snapshot
  into current
  from public.platform_onboarding_applications
  where id = target_application_id
  for update;

  if not found then
    raise exception 'The onboarding application does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if current.stage not in ('new', 'awaiting_payment', 'needs_attention') then
    raise exception 'This application can no longer be corrected.' using errcode = 'check_violation';
  end if;

  select exists (
    select 1
    from public.platform_onboarding_application_payment_confirmations
    where application_id = target_application_id
  ) into already_paid;

  if already_paid then
    raise exception 'The package can no longer be changed after payment is confirmed.' using errcode = 'check_violation';
  end if;

  if new_package_version_id = current.package_version_id then
    raise exception 'Choose a different package to change.' using errcode = 'check_violation';
  end if;

  select version.status, package.status, jsonb_build_object(
    'display_name', version.display_name,
    'public_description', version.public_description,
    'value_explanation', version.value_explanation,
    'price_usd_cents', version.price_usd_cents,
    'currency', version.currency,
    'billing_period', version.billing_period,
    'version_number', version.version_number
  )
  into version_status, package_status, new_snapshot
  from public.platform_package_versions as version
  join public.platform_packages as package on package.package_id = version.package_id
  where version.id = new_package_version_id;

  if version_status is null then
    raise exception 'The selected package no longer exists.' using errcode = 'foreign_key_violation';
  end if;
  if version_status <> 'published' or package_status <> 'published' then
    raise exception 'The selected package is not available.' using errcode = 'check_violation';
  end if;

  before_state := jsonb_build_object(
    'package_version_id', current.package_version_id,
    'package_snapshot', current.package_snapshot
  );
  after_state := jsonb_build_object(
    'package_version_id', new_package_version_id,
    'package_snapshot', new_snapshot
  );

  update public.platform_onboarding_applications
  set package_version_id = new_package_version_id,
    package_snapshot = new_snapshot
  where id = target_application_id;

  insert into public.platform_onboarding_application_corrections (
    application_id, actor_owner_email, reason, before_state, after_state
  ) values (
    target_application_id, actor_email, correction_reason, before_state, after_state
  );

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor_email, 'onboarding_application.package_corrected', 'onboarding_application',
    target_application_id::text, before_state, after_state || jsonb_build_object('reason', correction_reason)
  );
end;
$$;


ALTER FUNCTION "public"."correct_onboarding_application_package"("target_application_id" "uuid", "actor_email" "text", "new_package_version_id" "uuid", "correction_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_automation_recipe_draft"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_name" "text", "p_source" "text", "p_preset_key" "text", "p_preset_version" integer, "p_definition" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  clean_name text := btrim(coalesce(p_name, ''));
  existing_receipt public.automation_draft_command_receipts%rowtype;
  new_recipe public.automation_recipes%rowtype;
begin
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(clean_name) not between 1 and 120 then
    raise exception 'A recipe name of 1 to 120 characters is required.' using errcode = 'check_violation';
  end if;
  if p_source not in ('preset', 'custom') then
    raise exception 'A recipe source of preset or custom is required.' using errcode = 'check_violation';
  end if;
  if p_source = 'preset' and (p_preset_key is null or p_preset_version is null) then
    raise exception 'A preset recipe requires its preset lineage.' using errcode = 'check_violation';
  end if;
  if p_source = 'custom' and (p_preset_key is not null or p_preset_version is not null) then
    raise exception 'A custom recipe carries no preset lineage.' using errcode = 'check_violation';
  end if;
  if p_definition is null or jsonb_typeof(p_definition) <> 'object' then
    raise exception 'A recipe definition is required.' using errcode = 'check_violation';
  end if;
  if not exists (select 1 from public.organizations where id = p_organization_id) then
    raise exception 'That organization does not exist.' using errcode = 'foreign_key_violation';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('automation-draft-cmd:' || p_organization_id::text || ':' || p_idempotency_key::text)
  );

  select * into existing_receipt
  from public.automation_draft_command_receipts
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_receipt.result || jsonb_build_object('idempotent_replay', true);
  end if;

  insert into public.automation_recipes (
    organization_id, name, status, source, preset_key, preset_version,
    draft_definition, draft_revision, draft_updated_by, draft_updated_at, created_by
  ) values (
    p_organization_id, clean_name, 'draft', p_source,
    case when p_source = 'preset' then p_preset_key end,
    case when p_source = 'preset' then p_preset_version end,
    p_definition, 1, p_actor_user_id, now(), p_actor_user_id
  ) returning * into new_recipe;

  insert into public.automation_draft_command_receipts (
    organization_id, idempotency_key, command, recipe_id, result
  ) values (
    p_organization_id, p_idempotency_key, 'create_draft', new_recipe.id,
    jsonb_build_object('recipe_id', new_recipe.id, 'draft_revision', new_recipe.draft_revision)
  );

  return jsonb_build_object('recipe_id', new_recipe.id, 'draft_revision', new_recipe.draft_revision);
end;
$$;


ALTER FUNCTION "public"."create_automation_recipe_draft"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_name" "text", "p_source" "text", "p_preset_key" "text", "p_preset_version" integer, "p_definition" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_automation_recipe_draft"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_name" "text", "p_source" "text", "p_preset_key" "text", "p_preset_version" integer, "p_definition" "jsonb", "p_idempotency_key" "uuid") IS 'Creates a new automation recipe as a draft. Idempotent per organization + key; advisory-locked so a retried submit replays instead of duplicating.';



CREATE OR REPLACE FUNCTION "public"."create_catalog_item"("target_organization_id" "uuid", "new_category" "text", "new_name" "text", "new_description" "text", "new_unit_label" "text", "new_is_labor" boolean, "new_unit_price_minor" bigint, "new_unit_cost_minor" bigint, "new_is_taxable" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  clean_name text;
  new_row public.catalog_items;
begin
  if not private.has_permission(target_organization_id, 'settings.price_book.manage') then
    raise exception 'You do not have access to manage the Price Book.' using errcode = 'insufficient_privilege';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) < 2 or char_length(clean_name) > 160 then
    raise exception 'Give this item a name between 2 and 160 characters.' using errcode = 'check_violation';
  end if;

  if exists (
    select 1 from public.catalog_items
    where organization_id = target_organization_id
      and archived_at is null
      and lower(name) = lower(clean_name)
  ) then
    raise exception 'An active Price Book item is already named "%".', clean_name
      using errcode = 'unique_violation';
  end if;

  insert into public.catalog_items (
    organization_id, category, name, description, unit_label, is_labor,
    unit_price_minor, unit_cost_minor, is_taxable, created_by, updated_by
  )
  values (
    target_organization_id, new_category, clean_name, new_description, new_unit_label,
    coalesce(new_is_labor, false), coalesce(new_unit_price_minor, 0), coalesce(new_unit_cost_minor, 0),
    coalesce(new_is_taxable, true), (select auth.uid()), (select auth.uid())
  )
  returning * into new_row;

  return jsonb_build_object('id', new_row.id, 'name', new_row.name, 'revision', new_row.revision);
end;
$$;


ALTER FUNCTION "public"."create_catalog_item"("target_organization_id" "uuid", "new_category" "text", "new_name" "text", "new_description" "text", "new_unit_label" "text", "new_is_labor" boolean, "new_unit_price_minor" bigint, "new_unit_cost_minor" bigint, "new_is_taxable" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_checklist_template"("target_organization_id" "uuid", "name" "text", "items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  new_template public.checklist_templates;
begin
  if caller is null then
    raise exception 'You must be signed in to build a checklist.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'settings.checklists.manage') then
    raise exception 'You do not have access to build checklists.' using errcode = 'insufficient_privilege';
  end if;
  insert into public.checklist_templates (organization_id, name, created_by)
  values (target_organization_id, trim(create_checklist_template.name), caller)
  returning * into new_template;
  perform private.replace_checklist_template_items(target_organization_id, new_template.id, items);
  return jsonb_build_object('id', new_template.id);
end;
$$;


ALTER FUNCTION "public"."create_checklist_template"("target_organization_id" "uuid", "name" "text", "items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_checklist_template"("target_organization_id" "uuid", "name" "text", "items" "jsonb") IS 'Builds a reusable checklist. Needs checklists.manage.';



CREATE TABLE IF NOT EXISTS "public"."clients" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "display_name" "text" NOT NULL,
    "first_name" "text",
    "last_name" "text",
    "company_name" "text",
    "lifecycle_status" "text" DEFAULT 'lead'::"text" NOT NULL,
    "lead_source" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_type" "text" DEFAULT 'person'::"text" NOT NULL,
    "lead_temperature" "text",
    "next_follow_up_at" timestamp with time zone,
    "converted_to_customer_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "billing_payment_term_id" "uuid",
    "billing_address_line1" "text",
    "billing_address_line2" "text",
    "billing_city" "text",
    "billing_state_region" "text",
    "billing_postal_code" "text",
    "billing_country" "text",
    CONSTRAINT "clients_billing_address_complete" CHECK (((("billing_address_line1" IS NULL) AND ("billing_city" IS NULL) AND ("billing_country" IS NULL) AND ("billing_address_line2" IS NULL) AND ("billing_state_region" IS NULL) AND ("billing_postal_code" IS NULL)) OR ((("char_length"(TRIM(BOTH FROM "billing_address_line1")) >= 2) AND ("char_length"(TRIM(BOTH FROM "billing_address_line1")) <= 200)) AND (("char_length"(TRIM(BOTH FROM "billing_city")) >= 1) AND ("char_length"(TRIM(BOTH FROM "billing_city")) <= 120)) AND (("char_length"(TRIM(BOTH FROM "billing_country")) >= 2) AND ("char_length"(TRIM(BOTH FROM "billing_country")) <= 80))))),
    CONSTRAINT "clients_client_type_check" CHECK (("client_type" = ANY (ARRAY['person'::"text", 'company'::"text"]))),
    CONSTRAINT "clients_converted_customer_check" CHECK ((("lifecycle_status" <> 'customer'::"text") OR ("converted_to_customer_at" IS NOT NULL))),
    CONSTRAINT "clients_display_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "display_name")) >= 2) AND ("char_length"(TRIM(BOTH FROM "display_name")) <= 160))),
    CONSTRAINT "clients_lead_temperature_check" CHECK ((("lead_temperature" IS NULL) OR ("lead_temperature" = ANY (ARRAY['hot'::"text", 'warm'::"text", 'cold'::"text"])))),
    CONSTRAINT "clients_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['lead'::"text", 'customer'::"text"])))
);


ALTER TABLE "public"."clients" OWNER TO "postgres";


COMMENT ON COLUMN "public"."clients"."billing_payment_term_id" IS 'Client-level payment term override. Null means the organization default for this client type applies.';



COMMENT ON COLUMN "public"."clients"."billing_address_line1" IS 'First line of a custom billing address. Mutually exclusive with a property carrying is_billing_address, enforced by public.set_client_billing.';



CREATE OR REPLACE FUNCTION "public"."create_client"("payload" "jsonb") RETURNS "public"."clients"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  created_client public.clients;
  new_property_id uuid;
  new_note_id uuid;
  email_value text := nullif(trim(payload->>'email'), '');
  phone_value text := nullif(trim(payload->>'phone'), '');
  property_payload jsonb := payload->'property';
  initial_note_value text := nullif(trim(payload->>'initial_note'), '');
  preferences jsonb := payload->'preferences';
  tag_ids jsonb := payload->'tag_ids';
begin
  insert into public.clients (
    organization_id,
    display_name,
    client_type,
    first_name,
    last_name,
    company_name,
    lifecycle_status,
    lead_source,
    lead_temperature,
    next_follow_up_at
  )
  values (
    (payload->>'organization_id')::uuid,
    payload->>'display_name',
    coalesce(nullif(payload->>'client_type', ''), 'person'),
    nullif(trim(payload->>'first_name'), ''),
    nullif(trim(payload->>'last_name'), ''),
    nullif(trim(payload->>'company_name'), ''),
    coalesce(nullif(payload->>'lifecycle_status', ''), 'lead'),
    nullif(trim(payload->>'lead_source'), ''),
    nullif(payload->>'lead_temperature', ''),
    nullif(payload->>'next_follow_up_at', '')::timestamptz
  )
  returning * into created_client;

  if email_value is not null then
    insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
    values (created_client.organization_id, created_client.id, 'email', email_value, true);
  end if;

  if phone_value is not null then
    insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
    values (created_client.organization_id, created_client.id, 'phone', phone_value, true);
  end if;

  if property_payload is not null and jsonb_typeof(property_payload) = 'object' then
    insert into public.properties (
      organization_id,
      client_id,
      label,
      address_line1,
      address_line2,
      city,
      state_region,
      postal_code,
      country,
      access_notes,
      is_billing_address
    )
    values (
      created_client.organization_id,
      created_client.id,
      coalesce(nullif(trim(property_payload->>'label'), ''), 'Primary property'),
      property_payload->>'address_line1',
      nullif(trim(property_payload->>'address_line2'), ''),
      property_payload->>'city',
      nullif(trim(property_payload->>'state_region'), ''),
      nullif(trim(property_payload->>'postal_code'), ''),
      coalesce(nullif(property_payload->>'country', ''), 'US'),
      nullif(trim(property_payload->>'access_notes'), ''),
      coalesce((property_payload->>'is_billing_address')::boolean, false)
    )
    returning id into new_property_id;
  end if;

  if initial_note_value is not null then
    insert into public.notes (organization_id, body, created_by)
    values (created_client.organization_id, initial_note_value, (select auth.uid()))
    returning id into new_note_id;

    insert into public.note_links (organization_id, note_id, entity_type, entity_id)
    values (created_client.organization_id, new_note_id, 'client', created_client.id);
  end if;

  -- The preference row already exists: an after-insert trigger creates it for every client.
  if preferences is not null and jsonb_typeof(preferences) = 'object' then
    update public.client_communication_preferences as saved
    set
      appointment_reminders = coalesce((preferences->>'appointment_reminders')::boolean, saved.appointment_reminders),
      quote_follow_ups = coalesce((preferences->>'quote_follow_ups')::boolean, saved.quote_follow_ups),
      invoice_reminders = coalesce((preferences->>'invoice_reminders')::boolean, saved.invoice_reminders),
      job_follow_ups = coalesce((preferences->>'job_follow_ups')::boolean, saved.job_follow_ups),
      review_requests = coalesce((preferences->>'review_requests')::boolean, saved.review_requests),
      contact_policy = coalesce(nullif(preferences->>'contact_policy', ''), saved.contact_policy)
    where saved.organization_id = created_client.organization_id
      and saved.client_id = created_client.id;
  end if;

  -- The tag has to belong to this organization; the composite foreign key enforces that.
  if tag_ids is not null and jsonb_typeof(tag_ids) = 'array' then
    insert into public.tag_assignments (organization_id, tag_id, entity_type, entity_id, created_by)
    select
      created_client.organization_id,
      chosen.value::uuid,
      'client',
      created_client.id,
      (select auth.uid())
    from jsonb_array_elements_text(tag_ids) as chosen(value)
    on conflict (tag_id, entity_type, entity_id) do nothing;
  end if;

  return created_client;
end;
$$;


ALTER FUNCTION "public"."create_client"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_form"("target_organization_id" "uuid", "new_outcome" "text", "new_name" "text", "new_public_slug" "text", "new_title" "text", "new_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  clean_name text;
  clean_title text;
  clean_description text;
  clean_slug text;
  new_form public.forms;
  new_version public.form_versions;
  default_content jsonb := jsonb_build_object(
    'contact', jsonb_build_object(
      'name', jsonb_build_object('required', true),
      'email', jsonb_build_object('shown', true, 'required', true, 'marketing_consent', false),
      'phone', jsonb_build_object('shown', true, 'required', false, 'marketing_consent', false),
      'company', jsonb_build_object('shown', false, 'required', false),
      'address', jsonb_build_object('shown', true, 'required', false)
    ),
    'sections', jsonb_build_array(),
    'photos', jsonb_build_object('enabled', false, 'max', 10),
    'confirmation', jsonb_build_object(
      'title', 'Thanks — we got your request',
      'message', 'We''ll be in touch shortly to talk about your project.',
      'redirect_url', null
    )
  );
begin
  if not private.has_permission(target_organization_id, 'settings.forms.manage') then
    raise exception 'You do not have access to manage forms.' using errcode = 'insufficient_privilege';
  end if;

  if new_outcome not in ('request', 'assessment', 'job') then
    raise exception 'Choose what this form creates: a request, an assessment, or a job.'
      using errcode = 'check_violation';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) > 120 then
    raise exception 'Give this form a name up to 120 characters.' using errcode = 'check_violation';
  end if;

  clean_slug := nullif(trim(coalesce(new_public_slug, '')), '');
  if clean_slug is null or clean_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' or char_length(clean_slug) > 140 then
    raise exception 'That form link is invalid.' using errcode = 'check_violation';
  end if;

  clean_title := nullif(trim(coalesce(new_title, '')), '');
  if clean_title is null or char_length(clean_title) > 160 then
    raise exception 'Give this form a title customers will see, up to 160 characters.'
      using errcode = 'check_violation';
  end if;

  clean_description := nullif(trim(coalesce(new_description, '')), '');
  if clean_description is not null and char_length(clean_description) > 2000 then
    raise exception 'The form description is too long.' using errcode = 'check_violation';
  end if;

  insert into public.forms (organization_id, outcome, name, public_slug, created_by, updated_by)
  values (
    target_organization_id, new_outcome, clean_name, clean_slug, (select auth.uid()), (select auth.uid())
  )
  returning * into new_form;

  insert into public.form_versions (
    organization_id, form_id, version_number, status, title, description, content, created_by, updated_by
  ) values (
    target_organization_id, new_form.id, 1, 'draft', clean_title, clean_description, default_content,
    (select auth.uid()), (select auth.uid())
  )
  returning * into new_version;

  update public.forms set draft_version_id = new_version.id where id = new_form.id;

  if new_outcome in ('assessment', 'job') then
    insert into public.form_booking_rules (form_id, organization_id)
    values (new_form.id, target_organization_id);
  end if;

  return jsonb_build_object(
    'form_id', new_form.id, 'outcome', new_form.outcome, 'name', new_form.name,
    'public_slug', new_form.public_slug,
    'is_enabled', new_form.is_enabled, 'is_default', new_form.is_default, 'revision', new_form.revision,
    'draft_version_id', new_version.id, 'draft_version_number', new_version.version_number,
    'draft_revision', new_version.revision
  );
end;
$_$;


ALTER FUNCTION "public"."create_form"("target_organization_id" "uuid", "new_outcome" "text", "new_name" "text", "new_public_slug" "text", "new_title" "text", "new_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_form_draft"("target_organization_id" "uuid", "target_form_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  form_row public.forms;
  published_row public.form_versions;
  new_version public.form_versions;
  next_version_number integer;
begin
  if not private.has_permission(target_organization_id, 'settings.forms.manage') then
    raise exception 'You do not have access to manage forms.' using errcode = 'insufficient_privilege';
  end if;

  select * into form_row from public.forms
  where id = target_form_id and organization_id = target_organization_id
  for update;
  if form_row.id is null then
    raise exception 'That form was not found.' using errcode = 'check_violation';
  end if;
  if form_row.archived_at is not null then
    raise exception 'Restore this form before starting a new draft.' using errcode = 'check_violation';
  end if;
  if form_row.draft_version_id is not null then
    raise exception 'This form already has a draft in progress.' using errcode = 'check_violation';
  end if;
  if form_row.current_published_version_id is null then
    raise exception 'This form has no published version to revise.' using errcode = 'check_violation';
  end if;

  select * into published_row from public.form_versions
  where id = form_row.current_published_version_id and organization_id = target_organization_id;

  select coalesce(max(version_number), 0) + 1 into next_version_number
  from public.form_versions
  where form_id = form_row.id;

  insert into public.form_versions (
    organization_id, form_id, version_number, status, title, description, content, created_by, updated_by
  ) values (
    target_organization_id, form_row.id, next_version_number, 'draft',
    published_row.title, published_row.description, published_row.content,
    (select auth.uid()), (select auth.uid())
  )
  returning * into new_version;

  update public.forms set draft_version_id = new_version.id where id = form_row.id;

  return jsonb_build_object(
    'form_id', form_row.id, 'draft_version_id', new_version.id,
    'draft_version_number', new_version.version_number, 'revision', new_version.revision
  );
end;
$$;


ALTER FUNCTION "public"."create_form_draft"("target_organization_id" "uuid", "target_form_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_import_batch"("payload" "jsonb") RETURNS "public"."import_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_organization_id uuid := (payload->>'organization_id')::uuid;
  created_batch public.import_batches;
begin
  if target_organization_id is null then
    raise exception 'organization_id is required.' using errcode = 'invalid_parameter_value';
  end if;

  -- Backstop the route's permission check. Importing clients is a create action, so it rides the same
  -- `customers.create` key the single-client create path uses.
  if not private.has_permission(target_organization_id, 'customers.create') then
    raise exception 'You do not have permission to import clients here.'
      using errcode = 'insufficient_privilege';
  end if;

  insert into public.import_batches (
    organization_id,
    created_by,
    entity_type,
    source_filename,
    storage_object_key,
    file_row_count
  )
  values (
    target_organization_id,
    (select auth.uid()),
    'client',
    payload->>'source_filename',
    payload->>'storage_object_key',
    (payload->>'file_row_count')::integer
  )
  returning * into created_batch;

  return created_batch;
end;
$$;


ALTER FUNCTION "public"."create_import_batch"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_installment_invoice"("target_organization_id" "uuid", "target_job_id" "uuid", "target_installment_id" "uuid", "new_subject" "text", "new_service_property_ids" "uuid"[], "new_payment_term_id" "uuid", "new_custom_due_date" "date", "new_issue_date" "date", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  job_row public.jobs;
  stage_row public.job_payment_schedule_items;
  priced jsonb;
  stage_entry jsonb;
  stage_amount_minor bigint;
  progress_lines jsonb;
  draft jsonb;
  created_invoice_id uuid;
  invoice_row public.invoices;
  deposit_row record;
  deposit_available bigint;
  deposit_remaining bigint;
  deposit_share bigint;
  deposit_applied_total bigint := 0;
begin
  if caller is null then
    raise exception 'You must be signed in to create an invoice.' using errcode = 'insufficient_privilege';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'create_installment_invoice', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  -- Lock order: the job, then the one stage this call bills. A second call for the same stage blocks here
  -- until the first commits, and then sees the stage already locked below rather than racing it.
  select * into job_row
  from public.jobs
  where organization_id = target_organization_id and id = target_job_id
  for share;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  if job_row.job_type <> 'one_off' then
    raise exception 'Only a one-off job carries a payment schedule.' using errcode = 'check_violation';
  end if;

  select * into stage_row
  from public.job_payment_schedule_items
  where organization_id = target_organization_id and id = target_installment_id and job_id = target_job_id
  for update;
  if not found then
    raise exception 'That payment stage could not be found.' using errcode = 'P0404';
  end if;
  if stage_row.locked_amount_minor is not null then
    raise exception 'That payment stage has already been billed.'
      using errcode = 'unique_violation',
      hint = 'Open its invoice from the job''s Billing card instead of creating a new one.';
  end if;

  -- Priced as the schedule stands right now. A stage that no longer reconciles with the job total cannot be
  -- billed until the schedule is corrected — the same rule the Billing card already explains.
  priced := private.price_job_payment_schedule(target_job_id, null);
  select entry into stage_entry
  from jsonb_array_elements(priced -> 'items') as entry
  where nullif(entry ->> 'installment_id', '')::uuid = target_installment_id;
  if stage_entry is null then
    raise exception 'That payment stage could not be priced.' using errcode = 'check_violation';
  end if;
  stage_amount_minor := (stage_entry ->> 'amount_minor')::bigint;

  update public.job_payment_schedule_items
  set locked_amount_minor = stage_amount_minor
  where organization_id = target_organization_id and id = target_installment_id;

  progress_lines := private.progress_invoice_lines(target_organization_id, target_job_id, stage_amount_minor);

  draft := public.create_invoice_draft(
    target_organization_id, job_row.client_id, new_subject, progress_lines, new_service_property_ids,
    new_payment_term_id, new_custom_due_date, new_issue_date, new_idempotency_key, new_request_hash
  );
  created_invoice_id := (draft ->> 'invoice_id')::uuid;

  perform public.claim_invoice_sources(
    target_organization_id, created_invoice_id, (draft ->> 'revision')::integer,
    jsonb_build_array(jsonb_build_object(
      'kind', 'installment',
      'job_id', target_job_id,
      'installment_id', target_installment_id,
      'installment_number', stage_row.position + 1
    )),
    new_idempotency_key, new_request_hash
  );

  -- A live Quote deposit is spent on the first stage only, once, up to what the stage still owes. A job
  -- authored without a Quote behind it (`quote_id is null`) never has one to apply.
  if stage_row.position = 0 and job_row.quote_id is not null then
    deposit_remaining := stage_amount_minor;
    for deposit_row in
      select deposit.id
      from public.quote_deposit_events as deposit
      where deposit.organization_id = target_organization_id
        and deposit.quote_id = job_row.quote_id
        and deposit.quote_version_id = job_row.quote_version_id
        and deposit.event_type = 'received'
      order by deposit.created_at
    loop
      exit when deposit_remaining <= 0;
      deposit_available := private.deposit_event_available_minor(target_organization_id, deposit_row.id);
      if deposit_available > 0 then
        deposit_share := least(deposit_available, deposit_remaining);
        select * into invoice_row from public.invoices where id = created_invoice_id;
        perform private.apply_invoice_allocation(
          invoice_row, null, deposit_row.id, deposit_share, caller,
          'Quote deposit applied to the first payment stage.'
        );
        deposit_applied_total := deposit_applied_total + deposit_share;
        deposit_remaining := deposit_remaining - deposit_share;
      end if;
    end loop;
  end if;

  return private.complete_invoice_command(
    target_organization_id, 'create_installment_invoice', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', created_invoice_id,
      'invoice_number', (draft ->> 'invoice_number')::integer,
      'revision', (draft ->> 'revision')::integer,
      'installment_id', target_installment_id,
      'amount_minor', stage_amount_minor,
      'deposit_applied_minor', deposit_applied_total
    )
  );
end;
$$;


ALTER FUNCTION "public"."create_installment_invoice"("target_organization_id" "uuid", "target_job_id" "uuid", "target_installment_id" "uuid", "new_subject" "text", "new_service_property_ids" "uuid"[], "new_payment_term_id" "uuid", "new_custom_due_date" "date", "new_issue_date" "date", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_invoice_draft"("target_organization_id" "uuid", "target_client_id" "uuid", "new_subject" "text", "new_lines" "jsonb", "new_service_property_ids" "uuid"[], "new_payment_term_id" "uuid", "new_custom_due_date" "date", "new_issue_date" "date", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  settings_row public.organization_settings;
  term_row public.invoice_payment_terms;
  clean_subject text := nullif(trim(coalesce(new_subject, '')), '');
  issue_on date;
  due_on date;
  term_source text;
  created public.invoices;
  line_count integer;
  money jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to create an invoice.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.create') then
    raise exception 'You do not have access to create an invoice here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  if clean_subject is null or char_length(clean_subject) < 2 or char_length(clean_subject) > 160 then
    raise exception 'An invoice needs a subject between 2 and 160 characters.'
      using errcode = 'check_violation';
  end if;
  if new_lines is null or jsonb_typeof(new_lines) <> 'array' or jsonb_array_length(new_lines) = 0 then
    raise exception 'An invoice needs at least one line.' using errcode = 'check_violation';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'create_invoice_draft', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for share;
  if not found then
    raise exception 'That organization could not be found.' using errcode = 'P0404';
  end if;

  if not exists (
    select 1 from public.clients
    where organization_id = target_organization_id and id = target_client_id and deleted_at is null
  ) then
    raise exception 'That client could not be found.' using errcode = 'P0404';
  end if;

  issue_on := coalesce(new_issue_date, private.organization_today(target_organization_id));

  if new_custom_due_date is not null then
    if new_payment_term_id is not null then
      raise exception 'Choose either a payment term or a custom due date, not both.'
        using errcode = 'check_violation';
    end if;
    if new_custom_due_date < issue_on then
      raise exception 'A due date cannot be before the invoice date.' using errcode = 'check_violation';
    end if;
    term_source := 'custom';
    due_on := new_custom_due_date;
  else
    term_row := private.resolve_client_payment_term(
      target_organization_id, target_client_id, new_payment_term_id
    );
    term_source := 'term';
    due_on := private.invoice_due_date(issue_on, term_row);
    due_on := greatest(due_on, issue_on);
  end if;

  insert into public.invoices (
    organization_id, client_id, invoice_number, subject, currency_code,
    customer_snapshot, billing_address_snapshot, service_properties,
    payment_term_id, payment_term_snapshot, due_date_source, issue_date, due_date, created_by
  ) values (
    target_organization_id,
    target_client_id,
    private.allocate_invoice_number(target_organization_id),
    clean_subject,
    settings_row.currency_code,
    private.build_invoice_customer_snapshot(target_organization_id, target_client_id),
    private.resolve_client_billing_address(target_organization_id, target_client_id),
    private.build_invoice_service_properties(
      target_organization_id, target_client_id, new_service_property_ids
    ),
    case when term_source = 'term' then term_row.id end,
    case when term_source = 'term' then jsonb_build_object(
      'term_id', term_row.id, 'name', term_row.name, 'rule', term_row.rule, 'net_days', term_row.net_days
    ) else jsonb_build_object('rule', 'custom_date') end,
    term_source,
    issue_on,
    due_on,
    caller
  )
  returning * into created;

  insert into public.invoice_lines (
    organization_id, invoice_id, position, source_catalog_item_id, source_job_id, source_job_line_id,
    service_date, line_kind, category, name, description, unit_label, quantity, unit_price_minor,
    is_taxable, progress_original_amount_minor
  )
  select
    target_organization_id,
    created.id,
    (row_number() over (order by (line.value->>'position')::integer, line.ordinality) - 1)::integer,
    nullif(line.value->>'source_catalog_item_id', '')::uuid,
    nullif(line.value->>'source_job_id', '')::uuid,
    nullif(line.value->>'source_job_line_id', '')::uuid,
    nullif(line.value->>'service_date', '')::date,
    coalesce(line.value->>'line_kind', 'priced'),
    nullif(line.value->>'category', ''),
    line.value->>'name',
    nullif(line.value->>'description', ''),
    nullif(line.value->>'unit_label', ''),
    (line.value->>'quantity')::numeric,
    (line.value->>'unit_price_minor')::bigint,
    coalesce((line.value->>'is_taxable')::boolean, true),
    nullif(line.value->>'progress_original_amount_minor', '')::bigint
  from jsonb_array_elements(new_lines) with ordinality as line(value, ordinality);

  get diagnostics line_count = row_count;

  money := private.store_invoice_money(created.id);

  perform private.record_invoice_event(
    target_organization_id, created.id, created.invoice_number, target_client_id,
    'invoice.created', caller, created.revision, null,
    jsonb_build_object('line_count', line_count, 'due_date_source', term_source), false, null
  );

  return private.complete_invoice_command(
    target_organization_id, 'create_invoice_draft', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', created.id,
      'invoice_number', created.invoice_number,
      'revision', created.revision,
      'issue_date', created.issue_date,
      'due_date', created.due_date,
      'currency_code', created.currency_code,
      'line_count', line_count,
      'totals', money - 'lines'
    )
  );
end;
$$;


ALTER FUNCTION "public"."create_invoice_draft"("target_organization_id" "uuid", "target_client_id" "uuid", "new_subject" "text", "new_lines" "jsonb", "new_service_property_ids" "uuid"[], "new_payment_term_id" "uuid", "new_custom_due_date" "date", "new_issue_date" "date", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_invoice_draft"("target_organization_id" "uuid", "target_client_id" "uuid", "new_subject" "text", "new_lines" "jsonb", "new_service_property_ids" "uuid"[], "new_payment_term_id" "uuid", "new_custom_due_date" "date", "new_issue_date" "date", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Creates a draft invoice with its customer, billing-address, service-property and payment-term snapshots, its lines and its calculated money, in one transaction. A retry carrying the same key returns the first invoice instead of creating a second one.';



CREATE OR REPLACE FUNCTION "public"."create_invoice_from_work"("target_organization_id" "uuid", "target_client_id" "uuid", "new_subject" "text", "new_lines" "jsonb", "new_service_property_ids" "uuid"[], "new_payment_term_id" "uuid", "new_custom_due_date" "date", "new_issue_date" "date", "new_sources" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  draft jsonb;
  claimed jsonb;
  created_invoice_id uuid;
  reminders_resolved integer := 0;
  invoice_row public.invoices;
  deposit_row record;
  deposit_available bigint;
  deposit_share bigint;
  deposit_remaining bigint;
  deposit_applied_total bigint := 0;
begin
  if caller is null then
    raise exception 'You must be signed in to bill work.' using errcode = 'insufficient_privilege';
  end if;

  if new_sources is null or jsonb_typeof(new_sources) <> 'array'
     or jsonb_array_length(new_sources) = 0 then
    raise exception 'Choose at least one piece of work to bill.' using errcode = 'check_violation';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'create_invoice_from_work', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  -- The draft first: it is what the claims attach to. Permission, currency lock, subject, line and terms
  -- validation all happen inside it, so nothing is re-checked here.
  draft := public.create_invoice_draft(
    target_organization_id, target_client_id, new_subject, new_lines, new_service_property_ids,
    new_payment_term_id, new_custom_due_date, new_issue_date, new_idempotency_key, new_request_hash
  );
  created_invoice_id := (draft->>'invoice_id')::uuid;

  -- A fresh draft is at revision 1; passing the figure the draft actually reports keeps this honest rather
  -- than assuming it.
  claimed := public.claim_invoice_sources(
    target_organization_id, created_invoice_id, (draft->>'revision')::integer, new_sources,
    new_idempotency_key, new_request_hash
  );

  -- Deposits, after the claims, because the claims are what say which work -- and so which quote -- this
  -- bill covers. Only receipts on the exact quote version the job was made from count, which is the same
  -- pairing stage billing uses; a job authored without a quote behind it never has one. The invoice is
  -- locked and re-read each time because applying an allocation can settle it and move its revision on,
  -- and the invoice is taken before the deposit, the order every money command in this schema uses.
  select * into invoice_row
  from public.invoices
  where organization_id = target_organization_id and id = created_invoice_id
  for update;
  deposit_remaining := invoice_row.total_minor
    - private.invoice_allocated_minor(target_organization_id, created_invoice_id);

  for deposit_row in
    select distinct deposit.id, deposit.created_at
    from public.invoice_sources as claim
    join public.jobs as job
      on job.organization_id = claim.organization_id and job.id = claim.job_id
    join public.quote_deposit_events as deposit
      on deposit.organization_id = job.organization_id
      and deposit.quote_id = job.quote_id
      and deposit.quote_version_id = job.quote_version_id
    where claim.organization_id = target_organization_id
      and claim.root_invoice_id = created_invoice_id
      and job.quote_id is not null
      and deposit.event_type = 'received'
    order by deposit.created_at, deposit.id
  loop
    exit when deposit_remaining <= 0;

    perform 1
    from public.quote_deposit_events
    where organization_id = target_organization_id and id = deposit_row.id
    for update;

    deposit_available := private.deposit_event_available_minor(target_organization_id, deposit_row.id);
    if deposit_available > 0 then
      deposit_share := least(deposit_available, deposit_remaining);

      select * into invoice_row
      from public.invoices
      where organization_id = target_organization_id and id = created_invoice_id;

      perform private.apply_invoice_allocation(
        invoice_row, null, deposit_row.id, deposit_share, caller,
        'Quote deposit applied to the bill for that quote''s work.'
      );

      deposit_applied_total := deposit_applied_total + deposit_share;
      deposit_remaining := deposit_remaining - deposit_share;
    end if;
  end loop;

  -- Whatever work went on the bill, the prompts that asked for *that work* are answered. The claim command
  -- reports the chain root the claims were filed under, which for a fresh draft is the draft itself; taking
  -- it from the response rather than assuming it keeps the two in step.
  reminders_resolved := private.resolve_job_reminders_as_invoiced(
    target_organization_id, (claimed->>'root_invoice_id')::uuid, caller
  );

  return private.complete_invoice_command(
    target_organization_id, 'create_invoice_from_work', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', created_invoice_id,
      'invoice_number', (draft->>'invoice_number')::integer,
      'revision', (draft->>'revision')::integer,
      'claimed_count', (claimed->>'claimed_count')::integer,
      'consumed_visit_count', (claimed->>'consumed_visit_count')::integer,
      'reminders_resolved', reminders_resolved,
      'deposit_applied_minor', deposit_applied_total
    )
  );
end;
$$;


ALTER FUNCTION "public"."create_invoice_from_work"("target_organization_id" "uuid", "target_client_id" "uuid", "new_subject" "text", "new_lines" "jsonb", "new_service_property_ids" "uuid"[], "new_payment_term_id" "uuid", "new_custom_due_date" "date", "new_issue_date" "date", "new_sources" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_invoice_from_work"("target_organization_id" "uuid", "target_client_id" "uuid", "new_subject" "text", "new_lines" "jsonb", "new_service_property_ids" "uuid"[], "new_payment_term_id" "uuid", "new_custom_due_date" "date", "new_issue_date" "date", "new_sources" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Creates a draft invoice for a client''s job work and claims that work in the same transaction, credits any deposit already paid on the quote behind that work, then clears the invoice reminders that work answered. Composes create_invoice_draft and claim_invoice_sources so a bill can never exist without owning its sources, and never asks a client to pay a deposit twice.';



CREATE OR REPLACE FUNCTION "public"."create_invoices_in_batch"("target_organization_id" "uuid", "new_job_ids" "uuid"[], "new_complete_visit_ids" "uuid"[], "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  today date;
  default_tax_rate_id uuid;
  job_ids uuid[];
  visit_ids uuid[];
  found_jobs integer;
  visit_row public.job_visits;
  found_visits integer := 0;
  visits_completed integer := 0;
  group_row record;
  group_index integer := 0;
  client_label text;
  job_id uuid;
  payload jsonb;
  group_lines jsonb;
  group_sources jsonb;
  positioned jsonb;
  created jsonb;
  results jsonb := '[]'::jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to bill work.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.create') then
    raise exception 'You do not have access to bill work here.' using errcode = 'insufficient_privilege';
  end if;
  -- A batch is a screenful of amounts being committed at once; somebody who cannot see job prices cannot
  -- check what they are about to send. The same honest refusal the queue and the picker give.
  perform private.require_invoice_price_access(target_organization_id);

  select coalesce(array_agg(distinct id), '{}'::uuid[]) into job_ids
  from unnest(coalesce(new_job_ids, '{}'::uuid[])) as id;
  select coalesce(array_agg(distinct id), '{}'::uuid[]) into visit_ids
  from unnest(coalesce(new_complete_visit_ids, '{}'::uuid[])) as id;

  if cardinality(job_ids) = 0 then
    raise exception 'Choose at least one job to bill.' using errcode = 'check_violation';
  end if;
  -- The cap Jafar set: one page of the queue. Larger selections are billed as several batches rather than
  -- held under these locks for longer than a request should last.
  if cardinality(job_ids) > 25 then
    raise exception 'A batch can cover at most 25 jobs at once.' using errcode = 'check_violation',
      hint = 'Bill this page, then select the next one.';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'create_invoices_in_batch', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  today := private.organization_today(target_organization_id);

  select settings.tax_default_rate_id into default_tax_rate_id
  from public.organization_settings as settings
  where settings.organization_id = target_organization_id
  for share;

  select count(*) into found_jobs
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = any(job_ids);
  if found_jobs <> cardinality(job_ids) then
    raise exception 'One of those jobs could not be found.' using errcode = 'P0404';
  end if;

  -- Ticked visits first, so the work they represent is complete before anything asks what is billable.
  -- complete_job_visit checks jobs.complete for itself: billing does not confer the right to declare field
  -- work finished, and a member who may bill but not complete is refused here rather than silently skipped.
  if cardinality(visit_ids) > 0 then
    for visit_row in
      select visit.*
      from public.job_visits as visit
      where visit.organization_id = target_organization_id and visit.id = any(visit_ids)
      order by visit.job_id, visit.id
    loop
      found_visits := found_visits + 1;
      -- The DB half of "never auto-selected": a visit can only be completed by this command if the
      -- contractor named it, and it must belong to a job actually in the batch.
      if not (visit_row.job_id = any(job_ids)) then
        raise exception 'One of those visits belongs to a job that is not in this batch.'
          using errcode = 'check_violation';
      end if;
      if visit_row.completed_at is null then
        perform public.complete_job_visit(target_organization_id, visit_row.job_id, visit_row.id);
        visits_completed := visits_completed + 1;
      end if;
    end loop;

    if found_visits <> cardinality(visit_ids) then
      raise exception 'One of those visits could not be found.' using errcode = 'P0404';
    end if;
  end if;

  for group_row in
    with selected as (
      select
        job.id,
        job.job_number,
        job.title,
        job.client_id,
        job.property_id,
        coalesce(property.tax_rate_id, default_tax_rate_id) as tax_group
      from public.jobs as job
      left join public.properties as property
        on property.organization_id = job.organization_id and property.id = job.property_id
      where job.organization_id = target_organization_id and job.id = any(job_ids)
    )
    select
      selected.client_id,
      selected.tax_group,
      count(*)::integer as job_count,
      array_agg(selected.id order by selected.job_number, selected.id) as group_job_ids,
      (array_agg(selected.title order by selected.job_number, selected.id))[1] as first_title,
      array_remove(array_agg(distinct selected.property_id), null) as property_ids
    from selected
    group by selected.client_id, selected.tax_group
    -- Deterministic, and therefore part of the idempotency contract: the same selection retried with the
    -- same key derives the same per-group sub-keys in the same order.
    order by selected.client_id, selected.tax_group nulls first
  loop
    group_index := group_index + 1;
    group_lines := '[]'::jsonb;
    group_sources := '[]'::jsonb;

    foreach job_id in array group_row.group_job_ids loop
      payload := private.job_batch_billing_payload(target_organization_id, job_id, today);
      group_lines := group_lines || (payload->'lines');
      group_sources := group_sources || (payload->'sources');
    end loop;

    -- Named the way the contractor knows the client, so the refusal below points at a row on the screen.
    select coalesce(nullif(trim(coalesce(client.company_name, '')), ''), client.display_name, 'That client')
    into client_label
    from public.clients as client
    where client.organization_id = target_organization_id and client.id = group_row.client_id;

    -- The two ceilings a single invoice actually has. Both are refused by name, because the contractor's only
    -- move is to unpick that client's rows and bill them separately.
    if jsonb_array_length(group_sources) > 100 then
      raise exception
        'Client % has % pieces of work waiting, which is more than the 100 one invoice can cover.',
        client_label,
        jsonb_array_length(group_sources)
        using errcode = 'check_violation',
        hint = 'Bill some of that client''s jobs on their own first.';
    end if;
    if jsonb_array_length(group_lines) > 100 then
      raise exception 'Client %''s work comes to % lines, which is more than one invoice can hold.',
        client_label,
        jsonb_array_length(group_lines)
        using errcode = 'check_violation',
        hint = 'Bill some of that client''s jobs on their own first.';
    end if;

    -- create_invoice_draft orders lines by their stated position, so the group's own assembly order is
    -- stamped on now that every job has contributed.
    select coalesce(
      jsonb_agg(
        element.value || jsonb_build_object('position', element.ordinality - 1)
        order by element.ordinality
      ),
      '[]'::jsonb
    ) into positioned
    from jsonb_array_elements(group_lines) with ordinality as element(value, ordinality);

    created := public.create_invoice_from_work(
      target_organization_id,
      group_row.client_id,
      -- One job bills under its own name, the way Jobber does it; several share the neutral default. Same
      -- rule the single-job composer applies when several jobs are picked for one client.
      case when group_row.job_count = 1 then group_row.first_title else 'For services rendered' end,
      positioned,
      group_row.property_ids,
      null,
      null,
      null,
      group_sources,
      new_idempotency_key || ':' || group_index::text,
      new_request_hash
    );

    results := results || jsonb_build_array(jsonb_build_object(
      'invoice_id', created->'invoice_id',
      'invoice_number', created->'invoice_number',
      'client_id', group_row.client_id,
      'job_count', group_row.job_count,
      'claimed_count', created->'claimed_count'
    ));
  end loop;

  return private.complete_invoice_command(
    target_organization_id, 'create_invoices_in_batch', new_idempotency_key,
    jsonb_build_object(
      'invoice_count', jsonb_array_length(results),
      'job_count', cardinality(job_ids),
      'visits_completed', visits_completed,
      'invoices', results
    )
  );
end;
$$;


ALTER FUNCTION "public"."create_invoices_in_batch"("target_organization_id" "uuid", "new_job_ids" "uuid"[], "new_complete_visit_ids" "uuid"[], "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_invoices_in_batch"("target_organization_id" "uuid", "new_job_ids" "uuid"[], "new_complete_visit_ids" "uuid"[], "new_idempotency_key" "text", "new_request_hash" "text") IS 'Bills up to 25 selected jobs at once: one draft per client per effective tax rate, each claiming its own work and clearing the reminders that asked for it, with any explicitly ticked unfinished visits completed in the same transaction. All-or-nothing. Each group takes a derived sub-key so a retry cannot replay one group''s draft as another''s.';



CREATE OR REPLACE FUNCTION "public"."create_job_with_visits"("target_organization_id" "uuid", "target_client_id" "uuid", "target_property_id" "uuid", "new_title" "text", "new_instructions" "text", "invoice_on_close" boolean, "scope_lines" "jsonb", "visits" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text", "new_job_type" "text" DEFAULT 'one_off'::"text", "new_is_as_needed" boolean DEFAULT false, "new_recurrence" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  receipt_id uuid;
  existing_receipt public.job_command_receipts;
  organization_currency text;
  created_job public.jobs;
  visit_element jsonb;
  new_visit public.job_visits;
  assignee_element jsonb;
  visit_count integer;
  line_count integer;
  calculated jsonb;
  final_result jsonb;
  job_type text := coalesce(nullif(trim(coalesce(new_job_type, '')), ''), 'one_off');
  as_needed boolean := coalesce(new_is_as_needed, false);
  has_rule boolean := new_recurrence is not null and jsonb_typeof(new_recurrence) = 'object';
begin
  if caller is null then
    raise exception 'You must be signed in to create a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.create') then
    raise exception 'You do not have access to create a job here.'
      using errcode = 'insufficient_privilege';
  end if;

  if char_length(trim(coalesce(new_idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(new_request_hash, ''))) < 1 then
    raise exception 'A job fingerprint is required.' using errcode = 'check_violation';
  end if;

  if job_type not in ('one_off', 'recurring') then
    raise exception 'A job is either one-off or recurring.' using errcode = 'check_violation';
  end if;

  visit_count := coalesce(jsonb_array_length(visits), 0);

  -- The three shapes, each refused in the words of the thing the person actually did. A one-off is the visits
  -- they typed; a recurring job is the rule they set; an as-needed job is deliberately empty and stays empty.
  if job_type = 'one_off' then
    if has_rule or as_needed then
      raise exception 'A one-off job does not repeat. Create a recurring job instead.'
        using errcode = 'check_violation';
    end if;
    if visit_count < 1 or visit_count > 20 then
      raise exception 'A one-off job is created with between 1 and 20 visits.' using errcode = 'check_violation';
    end if;
  elsif as_needed then
    if has_rule or visit_count > 0 then
      raise exception 'An as-needed job starts with no schedule and no visits.' using errcode = 'check_violation';
    end if;
  else
    if not has_rule then
      raise exception 'A recurring job needs a repeat schedule.' using errcode = 'check_violation';
    end if;
    if visit_count > 0 then
      raise exception 'A recurring job builds its own visits from the schedule.'
        using errcode = 'check_violation';
    end if;
  end if;

  -- Claim the idempotency key before doing any work. on conflict do nothing waits for a racing transaction
  -- to commit and then returns no row, so the loser reads the winner's committed result instead of building
  -- a second job.
  insert into public.job_command_receipts (organization_id, action, idempotency_key, request_hash)
  values (target_organization_id, 'create_job', new_idempotency_key, new_request_hash)
  on conflict (organization_id, action, idempotency_key) do nothing
  returning id into receipt_id;

  if receipt_id is null then
    select receipt.* into existing_receipt
    from public.job_command_receipts as receipt
    where receipt.organization_id = target_organization_id
      and receipt.action = 'create_job'
      and receipt.idempotency_key = new_idempotency_key;

    if existing_receipt.request_hash is distinct from new_request_hash then
      raise exception 'That job was already started with different details.' using errcode = 'P0409';
    end if;

    return coalesce(existing_receipt.result, '{}'::jsonb) || jsonb_build_object('applied', false);
  end if;

  select settings.currency_code into organization_currency
  from public.organization_settings as settings
  where settings.organization_id = target_organization_id;
  organization_currency := coalesce(organization_currency, 'USD');

  -- The job row, its number, its guards and its first history event. A one-off is priced as a whole and
  -- reminded on close; repeating work defaults to a fixed amount each period, which is the shape Jobber opens
  -- on too. Part 11 owns changing that -- this only has to be a defensible starting point the guards accept.
  created_job := private.create_job(
    target_organization_id,
    target_client_id,
    target_property_id,
    new_title,
    job_type,
    case when job_type = 'one_off' then 'job_total' else 'fixed_per_period' end,
    organization_currency,
    caller,
    as_needed,
    case
      when job_type = 'recurring' then 'month_end'
      when coalesce(invoice_on_close, true) then 'on_closure'
      else 'manual'
    end,
    new_instructions,
    null,
    null,
    null,
    null
  );

  -- The job's own scope. The 100-line cap is a table trigger; the shape of each line is a table constraint.
  insert into public.job_line_items (
    organization_id, job_id, position, source_catalog_item_id, line_kind, category, is_labor,
    name, description, unit_label, quantity, unit_price_minor, unit_cost_minor, is_taxable
  )
  select
    created_job.organization_id,
    created_job.id,
    (row_number() over (order by (line.value->>'position')::integer, ordinality) - 1)::integer,
    nullif(line.value->>'source_catalog_item_id', '')::uuid,
    coalesce(line.value->>'line_kind', 'priced'),
    nullif(line.value->>'category', ''),
    coalesce((line.value->>'is_labor')::boolean, false),
    line.value->>'name',
    nullif(line.value->>'description', ''),
    nullif(line.value->>'unit_label', ''),
    (line.value->>'quantity')::numeric,
    (line.value->>'unit_price_minor')::bigint,
    (line.value->>'unit_cost_minor')::bigint,
    coalesce((line.value->>'is_taxable')::boolean, true)
  from jsonb_array_elements(coalesce(scope_lines, '[]'::jsonb)) with ordinality as line(value, ordinality);

  get diagnostics line_count = row_count;

  if has_rule then
    -- Generated visits carry the schedule's own time and no assignees; who goes is decided per visit, exactly
    -- as it is for a one-off.
    visit_count := private.write_job_recurrence(created_job.organization_id, created_job.id, new_recurrence);

    insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
    values (
      created_job.organization_id,
      created_job.id,
      'visits_generated',
      caller,
      jsonb_build_object('visit_count', visit_count, 'reason', 'created')
    );
  else
    -- The visits, in the order the form listed them, each with its own people. A visit's shape is checked by
    -- the table's constraints; an assignee who is not a member of this organization is refused by the
    -- assignment's composite foreign key.
    for visit_element in select value from jsonb_array_elements(coalesce(visits, '[]'::jsonb)) as v(value)
    loop
      insert into public.job_visits (
        organization_id, job_id, position, visit_date, start_time, end_time, all_day, title, instructions,
        source
      ) values (
        created_job.organization_id,
        created_job.id,
        (visit_element->>'position')::integer,
        nullif(visit_element->>'visit_date', '')::date,
        nullif(visit_element->>'start_time', '')::time,
        nullif(visit_element->>'end_time', '')::time,
        coalesce((visit_element->>'all_day')::boolean, false),
        nullif(trim(visit_element->>'title'), ''),
        nullif(trim(visit_element->>'instructions'), ''),
        'manual'
      )
      returning * into new_visit;

      if jsonb_typeof(visit_element->'assignee_ids') = 'array' then
        for assignee_element in select value from jsonb_array_elements(visit_element->'assignee_ids') as a(value)
        loop
          insert into public.job_visit_assignments (organization_id, visit_id, user_id)
          values (created_job.organization_id, new_visit.id, (assignee_element #>> '{}')::uuid)
          on conflict do nothing;
        end loop;
      end if;
    end loop;
  end if;

  calculated := private.store_job_money(created_job.id);

  final_result := jsonb_build_object(
    'applied', true,
    'job_id', created_job.id,
    'job_number', created_job.job_number,
    'job_type', job_type,
    'is_as_needed', as_needed,
    'visit_count', visit_count,
    'line_count', line_count,
    'total_minor', (calculated->>'total_minor')::bigint
  );

  update public.job_command_receipts set result = final_result where id = receipt_id;

  return final_result;
end;
$$;


ALTER FUNCTION "public"."create_job_with_visits"("target_organization_id" "uuid", "target_client_id" "uuid", "target_property_id" "uuid", "new_title" "text", "new_instructions" "text", "invoice_on_close" boolean, "scope_lines" "jsonb", "visits" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text", "new_job_type" "text", "new_is_as_needed" boolean, "new_recurrence" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_job_with_visits"("target_organization_id" "uuid", "target_client_id" "uuid", "target_property_id" "uuid", "new_title" "text", "new_instructions" "text", "invoice_on_close" boolean, "scope_lines" "jsonb", "visits" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text", "new_job_type" "text", "new_is_as_needed" boolean, "new_recurrence" "jsonb") IS 'The one direct job create. One-off with typed visits, recurring generated from a rule, or as-needed with neither. Written in one transaction, idempotent per (organization, key) through job_command_receipts.';



CREATE OR REPLACE FUNCTION "public"."create_note"("target_organization_id" "uuid", "target_entity_type" "text", "target_entity_id" "uuid", "new_body" "text", "new_pinned" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "organization_id" "uuid", "body" "text", "pinned" boolean, "created_by" "uuid", "edited_by" "uuid", "edited_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "link_id" "uuid", "entity_type" "text", "entity_id" "uuid", "link_created_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  inserted_note public.notes;
  inserted_link public.note_links;
begin
  insert into public.notes (organization_id, body, pinned, created_by)
  values (target_organization_id, new_body, coalesce(new_pinned, false), (select auth.uid()))
  returning * into inserted_note;

  insert into public.note_links (organization_id, note_id, entity_type, entity_id)
  values (target_organization_id, inserted_note.id, target_entity_type, target_entity_id)
  returning * into inserted_link;

  return query
  select
    inserted_note.id, inserted_note.organization_id, inserted_note.body, inserted_note.pinned,
    inserted_note.created_by, inserted_note.edited_by, inserted_note.edited_at, inserted_note.created_at,
    inserted_note.updated_at, inserted_link.id, inserted_link.entity_type, inserted_link.entity_id,
    inserted_link.created_at;
end;
$$;


ALTER FUNCTION "public"."create_note"("target_organization_id" "uuid", "target_entity_type" "text", "target_entity_id" "uuid", "new_body" "text", "new_pinned" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_opening_balance_import_batch"("payload" "jsonb") RETURNS "public"."import_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_organization_id uuid := (payload->>'organization_id')::uuid;
  created_batch public.import_batches;
begin
  if target_organization_id is null then
    raise exception 'organization_id is required.' using errcode = 'invalid_parameter_value';
  end if;

  if not private.has_permission(target_organization_id, 'invoices.create') then
    raise exception 'You do not have permission to import opening balances here.'
      using errcode = 'insufficient_privilege';
  end if;

  insert into public.import_batches (
    organization_id,
    created_by,
    entity_type,
    source_filename,
    storage_object_key,
    file_row_count,
    -- Opening balances have no skip/update choice (a match is always a correction, never a duplicate or a
    -- silent overwrite) -- 'update' is stored only because the column is not null; Review never reads it for
    -- this entity_type.
    match_action
  )
  values (
    target_organization_id,
    (select auth.uid()),
    'opening_balance',
    payload->>'source_filename',
    payload->>'storage_object_key',
    (payload->>'file_row_count')::integer,
    'update'
  )
  returning * into created_batch;

  return created_batch;
end;
$$;


ALTER FUNCTION "public"."create_opening_balance_import_batch"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_opening_balance_import_batch"("payload" "jsonb") IS 'Records one uploaded, already-parsed opening-balances CSV as a draft import_batches row (entity_type = ''opening_balance''). SECURITY DEFINER; self-checks invoices.create.';



CREATE OR REPLACE FUNCTION "public"."create_organization_tax_rate"("target_organization_id" "uuid", "new_name" "text", "new_rate_basis_points" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  clean_name text;
  new_row public.organization_tax_rates;
begin
  if not private.has_permission(target_organization_id, 'settings.taxes.manage') then
    raise exception 'You do not have access to manage taxes.' using errcode = 'insufficient_privilege';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) > 80 then
    raise exception 'Give this tax rate a name up to 80 characters.' using errcode = 'check_violation';
  end if;

  if new_rate_basis_points is null or new_rate_basis_points <= 0 or new_rate_basis_points > 10000 then
    raise exception 'A tax rate is greater than 0%% and no more than 100%%.' using errcode = 'check_violation';
  end if;

  insert into public.organization_tax_rates (organization_id, name, rate_basis_points, created_by, updated_by)
  values (target_organization_id, clean_name, new_rate_basis_points, (select auth.uid()), (select auth.uid()))
  returning * into new_row;

  return jsonb_build_object(
    'id', new_row.id, 'name', new_row.name, 'rate_basis_points', new_row.rate_basis_points,
    'is_active', new_row.is_active, 'revision', new_row.revision
  );
end;
$$;


ALTER FUNCTION "public"."create_organization_tax_rate"("target_organization_id" "uuid", "new_name" "text", "new_rate_basis_points" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_quote"("target_client_id" "uuid", "target_property_id" "uuid", "quote_title" "text", "disclaimer" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  client_row public.clients;
  property_row public.properties;
  new_quote public.quotes;
  new_version public.quote_versions;
  allocated_number integer;
  organization_currency text;
  organization_display_name text;
  clean_title text;
  clean_disclaimer text;
  resolved_tax record;
  quote_settings public.organization_settings;
begin
  clean_title := nullif(trim(coalesce(quote_title, '')), '');
  if clean_title is null or char_length(clean_title) < 2 or char_length(clean_title) > 160 then
    raise exception 'A quote needs a title between 2 and 160 characters.' using errcode = 'check_violation';
  end if;

  clean_disclaimer := nullif(trim(coalesce(disclaimer, '')), '');
  if clean_disclaimer is not null and char_length(clean_disclaimer) > 5000 then
    raise exception 'The contract disclaimer is too long.' using errcode = 'check_violation';
  end if;

  select * into client_row from public.clients where id = target_client_id;

  -- One answer for "no such client" and "not your client": a stranger learns nothing either way.
  if client_row.id is null
     or not private.member_has_permission(
       client_row.organization_id, (select auth.uid()), 'quotes.create'
     ) then
    raise exception 'You do not have access to create a quote for this client.'
      using errcode = 'insufficient_privilege';
  end if;

  if client_row.deleted_at is not null then
    raise exception 'That client is no longer available.' using errcode = 'check_violation';
  end if;
  if client_row.archived_at is not null then
    raise exception 'That client is archived. Restore them before quoting new work.'
      using errcode = 'check_violation';
  end if;

  select * into property_row
  from public.properties
  where id = target_property_id
    and organization_id = client_row.organization_id
    and client_id = client_row.id;

  if property_row.id is null
     or property_row.deleted_at is not null
     or property_row.archived_at is not null then
    raise exception 'Choose a live property belonging to this client.' using errcode = 'check_violation';
  end if;

  select * into quote_settings
  from public.organization_settings
  where organization_id = client_row.organization_id;

  organization_currency := quote_settings.currency_code;

  select organization.name into organization_display_name
  from public.organizations as organization
  where organization.id = client_row.organization_id;

  allocated_number := private.allocate_quote_number(client_row.organization_id);

  select * into resolved_tax
  from private.resolve_property_tax(client_row.organization_id, property_row.id);

  -- No disclaimer typed by the caller falls back to the Quote Settings default. An explicit disclaimer
  -- (used by conversion flows that already compose their own) always wins.
  if clean_disclaimer is null then
    clean_disclaimer := quote_settings.quote_terms;
  end if;

  insert into public.quotes (
    organization_id, client_id, property_id, quote_number, title, currency_code, created_by
  ) values (
    client_row.organization_id,
    client_row.id,
    property_row.id,
    allocated_number,
    clean_title,
    coalesce(organization_currency, 'USD'),
    (select auth.uid())
  )
  returning * into new_quote;

  insert into public.quote_versions (
    organization_id, quote_id, version_number, status, currency_code,
    client_display_name, organization_name, logo_object_key, brand_color, contract_disclaimer,
    service_address_line1, service_address_line2, service_city,
    service_state_region, service_postal_code, service_country,
    tax_source, tax_name, tax_rate_basis_points, tax_rate_id,
    representative_enabled, representative_name, representative_title, representative_signature_object_key,
    require_customer_signature,
    created_by
  ) values (
    new_quote.organization_id,
    new_quote.id,
    1,
    'draft',
    new_quote.currency_code,
    client_row.display_name,
    organization_display_name,
    quote_settings.logo_object_key,
    quote_settings.brand_color,
    clean_disclaimer,
    property_row.address_line1,
    property_row.address_line2,
    property_row.city,
    property_row.state_region,
    property_row.postal_code,
    property_row.country,
    resolved_tax.source, resolved_tax.name, resolved_tax.rate_basis_points, resolved_tax.rate_id,
    coalesce(quote_settings.quote_representative_enabled, false),
    quote_settings.quote_representative_name,
    quote_settings.quote_representative_title,
    quote_settings.quote_representative_signature_object_key,
    coalesce(quote_settings.quote_require_customer_signature, false),
    (select auth.uid())
  )
  returning * into new_version;

  update public.quotes set draft_version_id = new_version.id where id = new_quote.id;

  -- Same card the conversion command creates, for the same reason: every quote is one piece of commercial
  -- work with one identity. The stage trigger parks it off the board until the Quote columns exist.
  insert into public.opportunities (organization_id, client_id, property_id, quote_id, title)
  values (new_quote.organization_id, new_quote.client_id, new_quote.property_id, new_quote.id, new_quote.title);

  return jsonb_build_object(
    'quote_id', new_quote.id,
    'quote_number', new_quote.quote_number,
    'quote_version_id', new_version.id,
    'status', new_quote.status,
    'revision', new_version.revision
  );
end;
$$;


ALTER FUNCTION "public"."create_quote"("target_client_id" "uuid", "target_property_id" "uuid", "quote_title" "text", "disclaimer" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_similar_quote"("target_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  source_quote public.quotes;
  source_version public.quote_versions;
  organization_display_name text;
  allocated_number integer;
  new_quote public.quotes;
  new_version public.quote_versions;
begin
  select * into source_quote from public.quotes where id = target_quote_id;
  if source_quote.id is null or not private.member_has_permission(
    source_quote.organization_id, (select auth.uid()), 'quotes.edit'
  ) then
    raise exception 'You do not have access to copy this quote.' using errcode = 'insufficient_privilege';
  end if;

  select * into source_version from public.quote_versions
  where organization_id = source_quote.organization_id
    and id = coalesce(source_quote.draft_version_id, source_quote.current_published_version_id);
  if source_version.id is null then
    raise exception 'This quote has no version to copy.' using errcode = 'check_violation';
  end if;

  select organization.name into organization_display_name
  from public.organizations as organization
  where organization.id = source_quote.organization_id;

  allocated_number := private.allocate_quote_number(source_quote.organization_id);

  insert into public.quotes (
    organization_id, client_id, property_id, quote_number, title, currency_code, created_by
  ) values (
    source_quote.organization_id,
    source_quote.client_id,
    source_quote.property_id,
    allocated_number,
    left(source_quote.title || ' (copy)', 160),
    source_quote.currency_code,
    (select auth.uid())
  )
  returning * into new_quote;

  insert into public.quote_versions (
    organization_id, quote_id, version_number, status, currency_code, client_display_name,
    organization_name, service_address_line1, service_address_line2, service_city, service_state_region,
    service_postal_code, service_country, subtotal_minor, created_by, revision, contract_disclaimer,
    introduction, client_message, show_quantities, show_unit_prices, show_line_totals, show_totals,
    discount_name, discount_type, discount_value, tax_name, tax_rate_basis_points, deposit_type
  ) values (
    new_quote.organization_id, new_quote.id, 1, 'draft', source_version.currency_code,
    source_version.client_display_name, coalesce(organization_display_name, source_version.organization_name),
    source_version.service_address_line1, source_version.service_address_line2, source_version.service_city,
    source_version.service_state_region, source_version.service_postal_code, source_version.service_country,
    source_version.subtotal_minor, (select auth.uid()), 1, source_version.contract_disclaimer,
    source_version.introduction, source_version.client_message, source_version.show_quantities,
    source_version.show_unit_prices, source_version.show_line_totals, source_version.show_totals,
    source_version.discount_name, source_version.discount_type, source_version.discount_value,
    source_version.tax_name, source_version.tax_rate_basis_points, source_version.deposit_type
  )
  returning * into new_version;

  insert into public.quote_version_lines (
    organization_id, quote_id, quote_version_id, position, source_catalog_item_id, category, is_labor,
    name, description, unit_label, quantity, unit_price_minor, unit_cost_minor, is_taxable,
    image_attachment_id, line_kind, selection_kind, is_recommended
  )
  select line.organization_id, new_quote.id, new_version.id, line.position,
    line.source_catalog_item_id, line.category, line.is_labor, line.name, line.description,
    line.unit_label, line.quantity, line.unit_price_minor, line.unit_cost_minor, line.is_taxable,
    line.image_attachment_id, line.line_kind, line.selection_kind, line.is_recommended
  from public.quote_version_lines line
  where line.organization_id = source_version.organization_id
    and line.quote_id = source_version.quote_id
    and line.quote_version_id = source_version.id
  order by line.position, line.id;

  insert into public.quote_version_schedule_items (
    organization_id, quote_id, quote_version_id, position, description, value_type, value, is_deposit
  )
  select item.organization_id, new_quote.id, new_version.id, item.position, item.description,
    item.value_type, item.value, item.is_deposit
  from public.quote_version_schedule_items item
  where item.organization_id = source_version.organization_id
    and item.quote_id = source_version.quote_id
    and item.quote_version_id = source_version.id
  order by item.position, item.id;

  insert into public.quote_version_attachments (
    organization_id, quote_id, quote_version_id, attachment_id, position, customer_visible, display_name
  )
  select att.organization_id, new_quote.id, new_version.id, att.attachment_id, att.position,
    att.customer_visible, att.display_name
  from public.quote_version_attachments att
  where att.organization_id = source_version.organization_id
    and att.quote_id = source_version.quote_id
    and att.quote_version_id = source_version.id
  order by att.position, att.id;

  perform private.refresh_quote_draft_totals(new_version.id);

  update public.quotes set draft_version_id = new_version.id where id = new_quote.id;

  insert into public.opportunities (organization_id, client_id, property_id, quote_id, title)
  values (
    new_quote.organization_id, new_quote.client_id, new_quote.property_id, new_quote.id, new_quote.title
  );

  return jsonb_build_object('quote_id', new_quote.id, 'quote_number', new_quote.quote_number);
end;
$$;


ALTER FUNCTION "public"."create_similar_quote"("target_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_website_chat_widget"("target_organization_id" "uuid", "new_name" "text", "new_launcher_position" "text", "new_teaser_text" "text", "new_greeting_text" "text", "new_contact_requirement" "text", "new_availability_visibility_mode" "text", "new_source_label" "text", "new_privacy_policy_url" "text", "new_channel_options" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  clean_name text;
  clean_teaser text;
  clean_greeting text;
  clean_source text;
  clean_privacy text;
  option_count integer;
  option_item jsonb;
  new_row public.website_chat_widgets;
begin
  if not private.has_permission(target_organization_id, 'conversations.manage_connections') then
    raise exception 'You do not have access to manage Website Chat.' using errcode = 'insufficient_privilege';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) > 120 then
    raise exception 'Give this widget a name up to 120 characters.' using errcode = 'check_violation';
  end if;
  if new_launcher_position not in ('bottom_left', 'bottom_right') then
    raise exception 'Choose a valid launcher position.' using errcode = 'check_violation';
  end if;
  if new_contact_requirement not in ('phone', 'email', 'either') then
    raise exception 'Choose a valid identity requirement.' using errcode = 'check_violation';
  end if;
  if new_availability_visibility_mode not in ('hidden', 'show_when_available', 'always') then
    raise exception 'Choose a valid availability visibility mode.' using errcode = 'check_violation';
  end if;

  new_channel_options := coalesce(new_channel_options, '[]'::jsonb);
  if jsonb_typeof(new_channel_options) <> 'array' then
    raise exception 'Channel options must be a list.' using errcode = 'check_violation';
  end if;
  option_count := jsonb_array_length(new_channel_options);
  if option_count > 5 then
    raise exception 'Choose at most 5 additional channel options.' using errcode = 'check_violation';
  end if;
  for option_item in select * from jsonb_array_elements(new_channel_options) loop
    if (option_item ->> 'type') not in ('whatsapp', 'messenger') then
      raise exception 'Each channel option needs a valid type.' using errcode = 'check_violation';
    end if;
    if coalesce(trim(option_item ->> 'destination'), '') = '' then
      raise exception 'Each channel option needs a destination.' using errcode = 'check_violation';
    end if;
  end loop;

  clean_teaser := nullif(trim(coalesce(new_teaser_text, '')), '');
  clean_greeting := nullif(trim(coalesce(new_greeting_text, '')), '');
  clean_source := nullif(trim(coalesce(new_source_label, '')), '');
  clean_privacy := private.clean_website_chat_privacy_policy_url(new_privacy_policy_url);

  perform private.assert_website_chat_widget_available(target_organization_id);

  insert into public.website_chat_widgets (
    organization_id, name, launcher_position, teaser_text, greeting_text, contact_requirement,
    availability_visibility_mode, source_label, privacy_policy_url, channel_options, created_by, updated_by
  ) values (
    target_organization_id, clean_name, new_launcher_position, clean_teaser, clean_greeting,
    new_contact_requirement, new_availability_visibility_mode, clean_source, clean_privacy,
    new_channel_options, (select auth.uid()), (select auth.uid())
  ) returning * into new_row;

  return to_jsonb(new_row);
end;
$$;


ALTER FUNCTION "public"."create_website_chat_widget"("target_organization_id" "uuid", "new_name" "text", "new_launcher_position" "text", "new_teaser_text" "text", "new_greeting_text" "text", "new_contact_requirement" "text", "new_availability_visibility_mode" "text", "new_source_label" "text", "new_privacy_policy_url" "text", "new_channel_options" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deactivate_team_member"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members;
  previous_status text;
  unassigned_assessments integer;
  unassigned_visits integer;
  unassigned_tasks integer;
begin
  membership := private.authorize_team_member_command(
    target_organization_id, actor_user_id, target_user_id
  );

  if membership.status = 'deactivated' then
    raise exception 'That person is already deactivated.' using errcode = 'check_violation';
  end if;

  if membership.status <> 'active' then
    raise exception 'Only an active team member can be deactivated.' using errcode = 'check_violation';
  end if;

  previous_status := membership.status;

  -- Junction rows have no "unassigned" state to set, so they are deleted outright. A Task keeps existing
  -- (assignee_user_id is nullable, matching "a Task without anyone responsible is normal").
  with removed as (
    delete from public.assessment_assignees as assignee
    using public.assessments as assessment
    where assignee.assessment_id = assessment.id
      and assignee.organization_id = target_organization_id
      and assignee.user_id = target_user_id
      and assessment.completed_at is null
    returning assignee.assessment_id
  )
  select count(*) into unassigned_assessments from removed;

  with removed as (
    delete from public.job_visit_assignments as assignee
    using public.job_visits as visit
    where assignee.visit_id = visit.id
      and assignee.organization_id = target_organization_id
      and assignee.user_id = target_user_id
      and visit.completed_at is null
    returning assignee.visit_id
  )
  select count(*) into unassigned_visits from removed;

  with updated as (
    update public.tasks as task
    set assignee_user_id = null
    where task.organization_id = target_organization_id
      and task.assignee_user_id = target_user_id
      and task.status = 'open'
    returning task.id
  )
  select count(*) into unassigned_tasks from updated;

  -- The seat is freed by this write alone: private.employee_seats_used counts pending and active
  -- memberships, so nothing else has to remember to release it.
  update public.organization_members as membership_row
  set status = 'deactivated',
      deactivated_at = now(),
      status_changed_at = now(),
      status_changed_by = actor_user_id,
      access_revision = membership_row.access_revision + 1
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  returning * into membership;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    target_organization_id, 'member.deactivated', 'member', actor_user_id, target_user_id,
    jsonb_build_object('previous_status', previous_status)
  );

  -- A second line, only when something was actually unassigned -- same reasoning as change_team_member_role's
  -- dropped-adjustments line: one action that did two things reads as two facts in the history, not one.
  if unassigned_assessments > 0 or unassigned_visits > 0 or unassigned_tasks > 0 then
    insert into public.organization_member_access_events (
      organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
    )
    values (
      target_organization_id, 'member.work_unassigned', 'member', actor_user_id, target_user_id,
      jsonb_build_object(
        'unassigned_assessments', unassigned_assessments,
        'unassigned_visits', unassigned_visits,
        'unassigned_tasks', unassigned_tasks
      )
    );
  end if;

  return membership;
end;
$$;


ALTER FUNCTION "public"."deactivate_team_member"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."deactivate_team_member"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") IS 'Takes away a member''s access, frees their seat, and unassigns their incomplete assessments, visits and open tasks -- keeping everything they ever finished. Ending their live sessions is not needed here: every request already re-checks status=''active'' at the door. Removal only sets identity_cleanup_state.';



CREATE OR REPLACE FUNCTION "public"."decide_communication_email_suppression_removal"("p_request_id" "uuid", "p_actor_email" "text", "p_decision" "text", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor_email text := lower(btrim(coalesce(p_actor_email, '')));
  clean_note text := nullif(btrim(coalesce(p_note, '')), '');
  target_request public.communication_email_suppression_removal_requests%rowtype;
  target_suppression public.communication_email_suppressions%rowtype;
  approving boolean;
begin
  if char_length(actor_email) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if p_decision not in ('approve', 'deny') then
    raise exception 'The decision must be approve or deny.' using errcode = 'check_violation';
  end if;
  approving := p_decision = 'approve';
  if not approving and (clean_note is null or char_length(clean_note) not between 1 and 1000) then
    raise exception 'A note of 1 to 1000 characters is required to deny a request.'
      using errcode = 'check_violation';
  end if;

  select * into target_request
  from public.communication_email_suppression_removal_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'That removal request was not found.' using errcode = 'no_data_found';
  end if;
  if target_request.status <> 'pending' then
    raise exception 'That removal request has already been decided.' using errcode = 'check_violation';
  end if;

  select * into target_suppression
  from public.communication_email_suppressions
  where id = target_request.suppression_id
  for update;

  update public.communication_email_suppression_removal_requests
  set status = case when approving then 'approved' else 'denied' end,
    decided_by_kind = 'platform_owner',
    decided_by_email = actor_email,
    decided_at = now(),
    decision_note = clean_note
  where id = p_request_id;

  if approving and target_suppression.id is not null and target_suppression.released_at is null then
    update public.communication_email_suppressions
    set released_at = now(),
      released_by_owner_email = actor_email,
      released_by_kind = 'platform_owner',
      released_by_user_id = null,
      released_reason = 'Complaint-suppression removal approved by the platform owner.'
    where id = target_suppression.id;
  end if;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor_email,
    case when approving
      then 'communications.email_suppression_removal_approved'
      else 'communications.email_suppression_removal_denied' end,
    'communication_email_suppression',
    target_request.suppression_id::text,
    jsonb_build_object(
      'request_id', target_request.id,
      'organization_id', target_request.organization_id,
      'recipient_email', target_request.recipient_email,
      'suppression_reason', target_request.suppression_reason,
      'requested_by', target_request.requested_by_email,
      'request_reason', target_request.request_reason
    ),
    jsonb_build_object('decision', p_decision, 'note', clean_note)
  );

  return public.communication_email_suppression_removal_request_json(p_request_id);
end;
$$;


ALTER FUNCTION "public"."decide_communication_email_suppression_removal"("p_request_id" "uuid", "p_actor_email" "text", "p_decision" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_catalog_item"("target_organization_id" "uuid", "target_item_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  item_row public.catalog_items;
begin
  if not private.has_permission(target_organization_id, 'settings.price_book.manage') then
    raise exception 'You do not have access to manage the Price Book.' using errcode = 'insufficient_privilege';
  end if;

  select * into item_row
  from public.catalog_items
  where id = target_item_id and organization_id = target_organization_id
  for update;

  if item_row.id is null then
    raise exception 'That Price Book item was not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from item_row.revision then
    raise exception 'Someone else changed this item while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  delete from public.catalog_items where id = item_row.id;

  return jsonb_build_object('status', 'deleted', 'id', item_row.id);
end;
$$;


ALTER FUNCTION "public"."delete_catalog_item"("target_organization_id" "uuid", "target_item_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_invoice_draft"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  invoice_row public.invoices;
begin
  if caller is null then
    raise exception 'You must be signed in to delete an invoice.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.delete') then
    raise exception 'You do not have access to delete an invoice.'
      using errcode = 'insufficient_privilege';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'delete_invoice_draft', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  invoice_row := private.lock_invoice_for_edit(
    target_organization_id, target_invoice_id, expected_revision, 'invoices.delete'
  );

  if invoice_row.issued_at is not null or invoice_row.recognized_at is not null then
    raise exception 'An invoice that has been issued or settled cannot be deleted. Void it instead.'
      using errcode = 'check_violation';
  end if;
  if private.invoice_allocated_minor(target_organization_id, target_invoice_id) <> 0 then
    raise exception 'Return the money on this draft to client credit before deleting it.'
      using errcode = 'check_violation';
  end if;
  if exists (
    select 1 from public.invoices
    where organization_id = target_organization_id and predecessor_invoice_id = target_invoice_id
  ) then
    raise exception 'Another invoice replaces this one, so it cannot be deleted.'
      using errcode = 'check_violation';
  end if;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.draft_deleted', caller, invoice_row.revision, null, '{}'::jsonb, false, null
  );

  delete from public.invoices
  where organization_id = target_organization_id and id = target_invoice_id;

  return private.complete_invoice_command(
    target_organization_id, 'delete_invoice_draft', new_idempotency_key,
    jsonb_build_object('invoice_id', invoice_row.id, 'invoice_number', invoice_row.invoice_number)
  );
end;
$$;


ALTER FUNCTION "public"."delete_invoice_draft"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_job_expense"("target_organization_id" "uuid", "target_job_id" "uuid", "target_expense_id" "uuid", "reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  job_closed boolean;
  existing public.job_expenses;
begin
  if caller is null then
    raise exception 'You must be signed in to remove an expense.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.status <> 'active' into job_closed
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  select expense.* into existing
  from public.job_expenses as expense
  where expense.organization_id = target_organization_id
    and expense.job_id = target_job_id
    and expense.id = target_expense_id
  for update;
  if not found then
    raise exception 'That expense could not be found.' using errcode = 'P0404';
  end if;

  if not private.can_write_job_expense(target_organization_id, caller, existing.created_by, job_closed) then
    if job_closed then
      raise exception 'A closed job''s expenses can only be changed by someone who manages the team''s expenses.'
        using errcode = 'P0410';
    end if;
    raise exception 'You do not have access to remove this expense.' using errcode = 'insufficient_privilege';
  end if;

  insert into public.job_costing_events (
    organization_id, job_id, event_type, subject_kind, subject_id, actor_id, after_close,
    reason, prior_values
  )
  values (
    target_organization_id, target_job_id, 'expense_deleted', 'expense', target_expense_id, caller,
    job_closed,
    nullif(trim(coalesce(delete_job_expense.reason, '')), ''),
    jsonb_build_object(
      'name', existing.name,
      'accounting_code', existing.accounting_code,
      'expense_date', existing.expense_date,
      'total_minor', existing.total_minor,
      'reimburse_to_user_id', existing.reimburse_to_user_id
    )
  );

  delete from public.job_expenses as expense
  where expense.organization_id = target_organization_id
    and expense.id = target_expense_id;

  return jsonb_build_object('id', target_expense_id, 'after_close', job_closed);
end;
$$;


ALTER FUNCTION "public"."delete_job_expense"("target_organization_id" "uuid", "target_job_id" "uuid", "target_expense_id" "uuid", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_job_expense"("target_organization_id" "uuid", "target_job_id" "uuid", "target_expense_id" "uuid", "reason" "text") IS 'Removes a recorded expense, writing the whole row to job_costing_events first so deleting an expense never deletes the evidence that it existed. Same permissions as correcting one. Receipt files are removed by the browser through the attachment route beforehand.';



CREATE OR REPLACE FUNCTION "public"."delete_job_invoice_reminder"("target_organization_id" "uuid", "target_reminder_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  reminder_row public.job_invoice_reminders;
begin
  if caller is null then
    raise exception 'You must be signed in to delete an invoice reminder.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.edit') then
    raise exception 'You do not have access to edit this job.' using errcode = 'insufficient_privilege';
  end if;

  select * into reminder_row
  from public.job_invoice_reminders
  where organization_id = target_organization_id and id = target_reminder_id;

  if not found then
    raise exception 'That reminder does not exist.' using errcode = 'P0404';
  end if;
  if reminder_row.reminder_kind <> 'custom_date' then
    raise exception 'Only a custom-date reminder can be deleted. Dismiss the others instead.'
      using errcode = 'check_violation';
  end if;

  delete from public.job_invoice_reminders
  where organization_id = target_organization_id and id = target_reminder_id;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    reminder_row.job_id,
    'invoice_reminder_deleted',
    caller,
    jsonb_build_object('due_on', reminder_row.due_on)
  );

  return jsonb_build_object('id', target_reminder_id, 'deleted', true);
end;
$$;


ALTER FUNCTION "public"."delete_job_invoice_reminder"("target_organization_id" "uuid", "target_reminder_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_job_invoice_reminder"("target_organization_id" "uuid", "target_reminder_id" "uuid") IS 'Deletes a mistaken custom-date reminder. Other kinds must be dismissed, not deleted. Needs jobs.edit.';



CREATE OR REPLACE FUNCTION "public"."delete_job_time_entry"("target_organization_id" "uuid", "target_job_id" "uuid", "target_entry_id" "uuid", "reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  job_closed boolean;
  existing public.job_time_entries;
begin
  if caller is null then
    raise exception 'You must be signed in to remove hours.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.status <> 'active' into job_closed
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  select entry.* into existing
  from public.job_time_entries as entry
  where entry.organization_id = target_organization_id
    and entry.job_id = target_job_id
    and entry.id = target_entry_id
  for update;
  if not found then
    raise exception 'Those hours could not be found.' using errcode = 'P0404';
  end if;

  if not private.can_write_job_time(target_organization_id, caller, existing.user_id, job_closed) then
    if job_closed then
      raise exception 'A closed job''s hours can only be changed by someone who manages the team''s time.'
        using errcode = 'P0410';
    end if;
    raise exception 'You do not have access to remove these hours.' using errcode = 'insufficient_privilege';
  end if;

  -- The trail is written first and keeps the whole row. job_costing_events holds subject_id as a plain id
  -- precisely so the evidence outlives the entry it describes.
  insert into public.job_costing_events (
    organization_id, job_id, event_type, subject_kind, subject_id, actor_id, after_close,
    reason, prior_values
  )
  values (
    target_organization_id, target_job_id, 'time_entry_deleted', 'time_entry', target_entry_id, caller,
    job_closed,
    nullif(trim(coalesce(delete_job_time_entry.reason, '')), ''),
    jsonb_build_object(
      'user_id', existing.user_id,
      'visit_id', existing.visit_id,
      'started_at', existing.started_at,
      'minutes', existing.minutes,
      'cost_per_hour_minor', existing.cost_per_hour_minor,
      'cost_total_minor', existing.cost_total_minor
    )
  );

  delete from public.job_time_entries as entry
  where entry.organization_id = target_organization_id
    and entry.id = target_entry_id;

  return jsonb_build_object('id', target_entry_id, 'after_close', job_closed);
end;
$$;


ALTER FUNCTION "public"."delete_job_time_entry"("target_organization_id" "uuid", "target_job_id" "uuid", "target_entry_id" "uuid", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_job_time_entry"("target_organization_id" "uuid", "target_job_id" "uuid", "target_entry_id" "uuid", "reason" "text") IS 'Removes recorded hours, writing the whole entry to job_costing_events first so deleting an entry never deletes the evidence that it existed. Same permissions as correcting one.';



CREATE OR REPLACE FUNCTION "public"."delete_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_visit public.job_visits;
begin
  if caller is null then
    raise exception 'You must be signed in to schedule a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.schedule') then
    raise exception 'You do not have access to schedule this job.' using errcode = 'insufficient_privilege';
  end if;

  select visit.* into current_visit
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.id = target_visit_id
  for update;
  if not found then
    raise exception 'That visit could not be found.' using errcode = 'P0404';
  end if;

  if current_visit.completed_at is not null then
    raise exception 'A completed visit cannot be removed.' using errcode = 'P0410';
  end if;

  if current_visit.revision is distinct from expected_revision then
    raise exception 'Someone else changed this visit. Reload to see the latest.' using errcode = 'P0409';
  end if;

  delete from public.job_visits
  where organization_id = target_organization_id
    and id = target_visit_id;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, related_visit_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'visit_deleted',
    caller,
    target_visit_id,
    '{}'::jsonb
  );

  return jsonb_build_object('applied', true);
end;
$$;


ALTER FUNCTION "public"."delete_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid", "expected_revision" integer) IS 'Removes one incomplete visit and its assignments. Checks jobs.schedule, refuses a completed visit (P0410) and a stale revision (P0409), and appends a visit_deleted history row.';



CREATE OR REPLACE FUNCTION "public"."delete_member_availability_exception"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "target_exception_id" "uuid", "expected_availability_revision" integer) RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members;
  removed_count integer;
begin
  membership := private.authorize_member_availability_command(
    target_organization_id, actor_user_id, target_user_id
  );

  if expected_availability_revision is null
    or expected_availability_revision <> membership.availability_revision then
    raise exception 'Someone else changed this person''s availability while you were editing.'
      using errcode = 'P0409';
  end if;

  delete from public.organization_member_availability_exceptions
  where id = target_exception_id
    and organization_id = target_organization_id
    and user_id = target_user_id;

  get diagnostics removed_count = row_count;

  if removed_count = 0 then
    return membership;
  end if;

  update public.organization_members as membership_row
  set availability_revision = membership_row.availability_revision + 1
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  returning * into membership;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    target_organization_id, 'member.availability_updated', 'member', actor_user_id, target_user_id,
    jsonb_build_object('changed', jsonb_build_array('exceptions'))
  );

  return membership;
end;
$$;


ALTER FUNCTION "public"."delete_member_availability_exception"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "target_exception_id" "uuid", "expected_availability_revision" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_member_availability_exception"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "target_exception_id" "uuid", "expected_availability_revision" integer) IS 'Removes one dated exception, returning that date to the ordinary weekly pattern.';



CREATE OR REPLACE FUNCTION "public"."delete_organization_tax_rate"("target_organization_id" "uuid", "target_rate_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  rate_row public.organization_tax_rates;
  pinned_count integer;
  is_business_default boolean;
begin
  if not private.has_permission(target_organization_id, 'settings.taxes.manage') then
    raise exception 'You do not have access to manage taxes.' using errcode = 'insufficient_privilege';
  end if;

  select * into rate_row
  from public.organization_tax_rates
  where id = target_rate_id and organization_id = target_organization_id
  for update;

  if rate_row.id is null then
    raise exception 'That tax rate was not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from rate_row.revision then
    raise exception 'Someone else changed this tax rate while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  select count(*) into pinned_count
  from public.properties
  where organization_id = target_organization_id and tax_rate_id = target_rate_id;

  if pinned_count > 0 then
    raise exception 'Reassign the % properties using this tax rate before deleting it.', pinned_count
      using errcode = 'check_violation';
  end if;

  select exists (
    select 1 from public.organization_settings
    where organization_id = target_organization_id and tax_default_rate_id = target_rate_id
  ) into is_business_default;

  if is_business_default then
    raise exception 'This is the Business default tax. Choose a different default before deleting it.'
      using errcode = 'check_violation';
  end if;

  delete from public.organization_tax_rates where id = rate_row.id;

  return jsonb_build_object('status', 'deleted', 'id', rate_row.id);
end;
$$;


ALTER FUNCTION "public"."delete_organization_tax_rate"("target_organization_id" "uuid", "target_rate_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_property"("p_property_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_client_id uuid;
  v_was_primary boolean;
  v_next_property_id uuid;
begin
  select client_id, is_primary
    into v_client_id, v_was_primary
    from public.properties
   where id = p_property_id
     and deleted_at is null
     for update;

  if not found then
    raise exception 'That property could not be found.' using errcode = 'P0002';
  end if;

  update public.properties
     set deleted_at = now(),
         is_billing_address = false
   where id = p_property_id;

  if v_was_primary then
    select id
      into v_next_property_id
      from public.properties
     where client_id = v_client_id
       and deleted_at is null
     order by created_at, id
     limit 1;

    if v_next_property_id is not null then
      update public.properties set is_primary = true where id = v_next_property_id;
    end if;
  end if;
end;
$$;


ALTER FUNCTION "public"."delete_property"("p_property_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_quote"("target_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  touched_version_count integer;
begin
  select * into quote_row from public.quotes where id = target_quote_id for update;
  if quote_row.id is null or not private.member_has_permission(
    quote_row.organization_id, (select auth.uid()), 'quotes.edit'
  ) then
    raise exception 'You do not have access to delete this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.request_id is not null then
    raise exception 'A quote made from a request cannot be deleted. Archive it instead.'
      using errcode = 'check_violation';
  end if;
  if quote_row.status <> 'draft' then
    raise exception 'Only a draft that has never been sent can be deleted. Archive it instead.'
      using errcode = 'check_violation';
  end if;

  -- Never published, ever -- not just "not published right now". A quote revised back to draft after
  -- being published, declined, or archived still carries that history in a sibling version row.
  select count(*) into touched_version_count
  from public.quote_versions
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and status <> 'draft';
  if touched_version_count > 0 then
    raise exception 'This quote has already been sent. Archive it instead.' using errcode = 'check_violation';
  end if;

  -- quote_versions, quote_version_lines, quote_version_attachments, and opportunities.quote_id all cascade
  -- from this one delete. The remaining version is still `draft`, so the published-row guard triggers never
  -- fire.
  delete from public.quotes where id = quote_row.id;

  return jsonb_build_object('quote_id', quote_row.id, 'quote_number', quote_row.quote_number);
end;
$$;


ALTER FUNCTION "public"."delete_quote"("target_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dismiss_job_invoice_reminder"("target_organization_id" "uuid", "target_reminder_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  reminder_row public.job_invoice_reminders;
begin
  if caller is null then
    raise exception 'You must be signed in to change an invoice reminder.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.edit') then
    raise exception 'You do not have access to edit this job.' using errcode = 'insufficient_privilege';
  end if;

  update public.job_invoice_reminders
  set status = 'resolved', resolution = 'dismissed', resolved_at = now(), resolved_by = caller
  where organization_id = target_organization_id
    and id = target_reminder_id
    and status = 'pending'
  returning * into reminder_row;

  if not found then
    raise exception 'That reminder was already handled or does not exist.' using errcode = 'P0404';
  end if;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    reminder_row.job_id,
    'invoice_reminder_dismissed',
    caller,
    jsonb_build_object('reminder_kind', reminder_row.reminder_kind, 'due_on', reminder_row.due_on)
  );

  if reminder_row.reminder_kind = 'monthly_last_day' then
    perform private.seed_next_month_end_reminder(target_organization_id, reminder_row.job_id, caller);
  end if;

  return jsonb_build_object('id', reminder_row.id, 'status', 'resolved');
end;
$$;


