CREATE OR REPLACE FUNCTION "public"."duplicate_automation_recipe"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_name" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  clean_name text := btrim(coalesce(p_name, ''));
  existing_receipt public.automation_draft_command_receipts%rowtype;
  source public.automation_recipes%rowtype;
  new_recipe public.automation_recipes%rowtype;
  command_result jsonb;
begin
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;
  if p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'An expected revision is required.' using errcode = 'check_violation';
  end if;
  if char_length(clean_name) not between 1 and 120 then
    raise exception 'A recipe name of 1 to 120 characters is required.' using errcode = 'check_violation';
  end if;

  perform pg_advisory_xact_lock(hashtext('automation-recipe:' || p_recipe_id::text));

  select * into existing_receipt
  from public.automation_draft_command_receipts
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_receipt.result || jsonb_build_object('idempotent_replay', true);
  end if;

  select * into source
  from public.automation_recipes
  where id = p_recipe_id and organization_id = p_organization_id
  for update;
  if not found then
    raise exception 'That automation does not exist.' using errcode = 'no_data_found';
  end if;
  if source.draft_revision <> p_expected_revision then
    return jsonb_build_object(
      'stale', true,
      'current_revision', source.draft_revision,
      'draft_updated_at', source.draft_updated_at,
      'draft_updated_by', source.draft_updated_by
    );
  end if;
  if source.draft_definition is null then
    raise exception 'This automation has no definition to copy.' using errcode = 'check_violation';
  end if;

  insert into public.automation_recipes (
    organization_id, name, status, source, preset_key, preset_version,
    draft_definition, draft_revision, draft_updated_by, draft_updated_at, created_by
  ) values (
    p_organization_id, clean_name, 'draft', source.source, source.preset_key, source.preset_version,
    source.draft_definition, 1, p_actor_user_id, now(), p_actor_user_id
  ) returning * into new_recipe;

  command_result := jsonb_build_object(
    'recipe_id', new_recipe.id,
    'status', 'draft',
    'draft_revision', new_recipe.draft_revision,
    'stale', false
  );

  insert into public.automation_draft_command_receipts (
    organization_id, idempotency_key, command, recipe_id, result
  ) values (
    p_organization_id, p_idempotency_key, 'duplicate', new_recipe.id, command_result
  );

  return command_result;
end;
$$;


ALTER FUNCTION "public"."duplicate_automation_recipe"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_name" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."duplicate_automation_recipe"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_name" "text", "p_idempotency_key" "uuid") IS 'Copies a recipe''s current definition into a new independent draft. Idempotent per organization + key; guards the source revision. The copy is a draft and does not count against the active-recipes limit.';



CREATE OR REPLACE FUNCTION "public"."effective_automation_limits"("target_organization_id" "uuid", "at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("limit_key" "text", "state" "text", "value" integer, "is_unlimited" boolean, "source" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with keys (limit_key) as (
    values
      ('automation_active_recipes'),
      ('automation_max_conditions_per_recipe'),
      ('automation_max_steps_per_recipe'),
      ('automation_max_customer_messages_per_enrollment'),
      ('automation_min_customer_message_spacing_minutes'),
      ('automation_max_delay_days'),
      ('automation_max_enrollment_duration_days')
  ),
  current_assignment as (
    select assignment.package_version_id
    from public.organization_package_assignments as assignment
    where assignment.organization_id = target_organization_id
    order by assignment.effective_at desc, assignment.id desc
    limit 1
  ),
  package_limit as (
    select version_limit.limit_key, version_limit.limit_state, version_limit.limit_value
    from public.platform_package_version_limits as version_limit
    where version_limit.package_version_id = (select package_version_id from current_assignment)
      and version_limit.limit_key in (
        'automation_active_recipes', 'automation_max_conditions_per_recipe',
        'automation_max_steps_per_recipe', 'automation_max_customer_messages_per_enrollment',
        'automation_min_customer_message_spacing_minutes', 'automation_max_delay_days',
        'automation_max_enrollment_duration_days'
      )
  ),
  active_override as (
    select override.limit_key, override.limit_state, override.limit_value, override.is_unlimited
    from public.organization_limit_overrides as override
    where override.organization_id = target_organization_id
      and override.limit_key in (
        'automation_active_recipes', 'automation_max_conditions_per_recipe',
        'automation_max_steps_per_recipe', 'automation_max_customer_messages_per_enrollment',
        'automation_min_customer_message_spacing_minutes', 'automation_max_delay_days',
        'automation_max_enrollment_duration_days'
      )
      and override.starts_at <= at
      and (override.expires_at is null or override.expires_at > at)
  )
  select
    keys.limit_key,
    coalesce(active_override.limit_state, package_limit.limit_state, 'not_included') as state,
    case
      when active_override.limit_key is not null then
        case when active_override.limit_state = 'numeric' then active_override.limit_value end
      when package_limit.limit_key is not null then
        case when package_limit.limit_state = 'numeric' then package_limit.limit_value end
      else null
    end as value,
    case
      when active_override.limit_key is not null then active_override.is_unlimited
      when package_limit.limit_key is not null then package_limit.limit_state = 'unlimited'
      else false
    end as is_unlimited,
    case when active_override.limit_key is not null then 'override' else 'package' end as source
  from keys
  left join package_limit on package_limit.limit_key = keys.limit_key
  left join active_override on active_override.limit_key = keys.limit_key
  order by keys.limit_key;
$$;


ALTER FUNCTION "public"."effective_automation_limits"("target_organization_id" "uuid", "at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."effective_automation_limits"("target_organization_id" "uuid", "at" timestamp with time zone) IS 'Single authority for the seven Automation limits. One snapshot; override then package then not_included.';



CREATE OR REPLACE FUNCTION "public"."effective_employee_seat_limit"("target_organization_id" "uuid", "at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("state" "text", "value" integer, "is_unlimited" boolean, "source" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  assignment_package_version_id uuid;
  override_limit_state text;
  override_limit_value integer;
  override_is_unlimited boolean;
  override_found boolean;
  package_limit_state text;
  package_limit_value integer;
  package_is_unlimited boolean;
  package_found boolean;
  organization_package_key text;
  organization_scheduled_package_key text;
  organization_scheduled_effective_at timestamptz;
  effective_package_key text;
begin
  select assignment.package_version_id
  into assignment_package_version_id
  from public.organization_package_assignments as assignment
  where assignment.organization_id = target_organization_id
  order by assignment.effective_at desc, assignment.id desc
  limit 1;

  select override.limit_state, override.limit_value, override.is_unlimited
  into override_limit_state, override_limit_value, override_is_unlimited
  from public.organization_limit_overrides as override
  where override.organization_id = target_organization_id
    and override.limit_key = 'employee_seats'
    and override.starts_at <= at
    and (override.expires_at is null or override.expires_at > at);
  override_found := found;

  if assignment_package_version_id is not null then
    select version_limit.limit_state, version_limit.limit_value
    into package_limit_state, package_limit_value
    from public.platform_package_version_limits as version_limit
    where version_limit.package_version_id = assignment_package_version_id
      and version_limit.limit_key = 'employee_seats';
    package_found := found;

    if override_found then
      state := override_limit_state;
      value := override_limit_value;
      is_unlimited := override_is_unlimited;
    elsif package_found then
      state := package_limit_state;
      value := case when package_limit_state = 'numeric' then package_limit_value else null end;
      is_unlimited := package_limit_state = 'unlimited';
    else
      state := 'not_included';
      value := null;
      is_unlimited := false;
    end if;
  else
    select organization.package_key, organization.scheduled_package_key,
           organization.scheduled_package_effective_at
    into organization_package_key, organization_scheduled_package_key, organization_scheduled_effective_at
    from public.organizations as organization
    where organization.id = target_organization_id;

    effective_package_key := case
      when organization_scheduled_package_key is not null
        and organization_scheduled_effective_at is not null
        and organization_scheduled_effective_at <= at
      then organization_scheduled_package_key
      else organization_package_key
    end;

    select package_limit.limit_value, package_limit.is_unlimited
    into package_limit_value, package_is_unlimited
    from public.package_limits as package_limit
    where package_limit.package_key = effective_package_key
      and package_limit.limit_key = 'employee_seats';
    package_found := found;

    if override_found then
      state := override_limit_state;
      value := override_limit_value;
      is_unlimited := override_is_unlimited;
    elsif package_found then
      is_unlimited := coalesce(package_is_unlimited, false);
      value := package_limit_value;
      state := case
        when package_is_unlimited then 'unlimited'
        when package_limit_value is null then 'not_included'
        else 'numeric'
      end;
    else
      state := 'not_included';
      value := null;
      is_unlimited := false;
    end if;
  end if;

  source := case when override_found then 'override' else 'package' end;

  return next;
  return;
end;
$$;


ALTER FUNCTION "public"."effective_employee_seat_limit"("target_organization_id" "uuid", "at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."effective_employee_seat_limit"("target_organization_id" "uuid", "at" timestamp with time zone) IS 'Single authority for the employee_seats limit. effective.ts calls this instead of re-deriving it.';



