CREATE OR REPLACE FUNCTION "public"."end_website_chat_session"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    SET "statement_timeout" TO '5000'
    AS $$
declare
  target_session public.website_chat_sessions;
  organization_name text;
  closed_moment timestamptz := now();
begin
  if not private.member_has_permission(
    target_organization_id, target_actor_user_id, 'conversations.send'
  ) then
    raise exception 'You do not have permission to manage this conversation.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into target_session
  from public.website_chat_sessions s
  where s.organization_id = target_organization_id and s.id = target_session_id
  for update;
  if not found then
    raise exception 'That conversation is not available.' using errcode = 'foreign_key_violation';
  end if;

  if target_session.closed_at is not null then
    raise exception 'This conversation has already ended.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  select o.name into organization_name
  from public.organizations o
  where o.id = target_organization_id;

  update public.website_chat_sessions
  set closed_at = closed_moment,
      closed_reason = 'staff_ended',
      closed_by = target_actor_user_id,
      last_activity_at = closed_moment
  where id = target_session.id;

  insert into public.website_chat_messages (
    organization_id, session_id, client_id, direction, sender_type, body
  ) values (
    target_session.organization_id, target_session.id, target_session.client_id,
    'outbound', 'system', organization_name || ' ended this conversation.'
  );

  return jsonb_build_object(
    'status', 'closed', 'session_id', target_session.id, 'closed_at', closed_moment
  );
end;
$$;


ALTER FUNCTION "public"."end_website_chat_session"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_session_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."end_website_chat_session"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_session_id" "uuid") IS 'Ends a Website Chat session: closed_at, closed_reason, closed_by AND the sender_type = ''system'' part in one transaction. WC4.4''s inherited contract -- the visitor learns a session ended only from that part arriving in the thread.';



CREATE OR REPLACE FUNCTION "public"."enqueue_automation_quote_email"("p_organization_id" "uuid", "p_quote_id" "uuid", "p_logical_send_key" "text", "p_subject" "text", "p_body" "text", "p_quote_url" "text", "p_quote_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  authority public.organization_automation_authority;
  quote_row public.quotes;
  version_row public.quote_versions;
  client_row public.clients;
  recipient public.client_contact_methods;
  quote_recipient public.quote_recipients;
  sender public.communication_email_senders;
  sender_domain public.communication_email_domains;
  alias public.communication_reply_aliases;
  intent public.communication_delivery_intents;
  access_link_id uuid;
  rendered record;
  customer_name text;
  stop_outcome text;
begin
  if p_quote_url !~ '^https?://[^[:space:]]+$'
    or p_quote_token_hash is null or octet_length(p_quote_token_hash) <> 32 then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'invalid_link');
  end if;

  if coalesce(btrim(p_subject), '') = '' or coalesce(btrim(p_body), '') = '' then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'invalid_email_content');
  end if;

  select * into intent from public.communication_delivery_intents
    where organization_id = p_organization_id and logical_send_key = p_logical_send_key for share;
  if intent.id is not null then
    if intent.quote_id is distinct from p_quote_id then
      return jsonb_build_object('status', 'skipped_permanent', 'reason', 'idempotency_conflict');
    end if;
    return jsonb_build_object('status', 'sent', 'reason', 'already_enqueued', 'intent_id', intent.id);
  end if;

  if not private.organization_has_automations_feature(p_organization_id, now()) then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'automations_not_entitled');
  end if;

  select * into authority from public.organization_automation_authority
    where organization_id = p_organization_id;
  if coalesce(authority.operational_state, 'enabled') <> 'enabled'
    or coalesce(authority.security_state, 'active') <> 'active' then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'automation_suspended');
  end if;

  -- 6F-1: one shared stop check.
  stop_outcome := private.automation_quote_stop_outcome(p_organization_id, p_quote_id);
  if stop_outcome is not null then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', stop_outcome);
  end if;

  select * into quote_row from public.quotes
    where organization_id = p_organization_id and id = p_quote_id for share;
  if quote_row.id is null then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'quote_not_sendable');
  end if;

  select * into version_row from public.quote_versions
    where organization_id = quote_row.organization_id and id = quote_row.current_published_version_id
      and quote_id = quote_row.id and status = 'published' for share;
  select * into client_row from public.clients
    where organization_id = quote_row.organization_id and id = quote_row.client_id and deleted_at is null for share;
  select * into recipient from public.client_contact_methods
    where organization_id = quote_row.organization_id and client_id = quote_row.client_id and kind = 'email'
    order by is_primary desc, created_at, id limit 1 for share;
  if version_row.id is null or client_row.id is null or recipient.id is null then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'recipient_unavailable');
  end if;

  select * into sender from public.communication_email_senders
    where organization_id = quote_row.organization_id and lifecycle_state = 'enabled' and allows_automated
      and is_organization_default
    order by created_at, id limit 1 for share;
  if sender.id is not null then
    select * into sender_domain from public.communication_email_domains
      where organization_id = sender.organization_id and id = sender.domain_id and purpose = 'sending'
        and lifecycle_state = 'verified' and provider_verified and provider_authenticated
        and ownership_status = 'passing' and dkim_status = 'passing' for share;
  end if;
  if sender.id is null or sender_domain.id is null then
    return jsonb_build_object('status', 'skipped_temporary', 'reason', 'sender_not_ready');
  end if;

  customer_name := coalesce(nullif(btrim(client_row.display_name), ''), recipient.normalized_value);
  select * into rendered from private.render_automation_email(
    p_subject, p_body, customer_name, version_row.organization_name,
    quote_row.quote_number::text, p_quote_url);

  alias := public.ensure_communication_reply_alias(
    quote_row.organization_id, sender.id, quote_row.client_id, recipient.id);

  insert into public.quote_recipients (organization_id, quote_id, display_name, email, created_by)
    values (quote_row.organization_id, quote_row.id, customer_name, recipient.normalized_value, null)
    on conflict (organization_id, quote_id, email) do update set display_name = excluded.display_name
    returning * into quote_recipient;
  update public.quote_access_links set revoked_at = now(), revoked_reason = 'rotated'
    where organization_id = quote_row.organization_id and quote_id = quote_row.id
      and recipient_id = quote_recipient.id and revoked_at is null;
  insert into public.quote_access_links
    (organization_id, quote_id, quote_version_id, recipient_id, token_hash, issued_by)
    values (quote_row.organization_id, quote_row.id, version_row.id, quote_recipient.id, p_quote_token_hash, null)
    returning id into access_link_id;

  begin
    insert into public.communication_delivery_intents
      (organization_id, client_id, client_contact_method_id, quote_id, quote_version_id, quote_recipient_id,
       quote_access_link_id, logical_send_key, recipient_email, subject, html_content, text_content,
       send_kind, allowance_class, sender_id, reply_alias_id, created_by)
      values (quote_row.organization_id, quote_row.client_id, recipient.id, quote_row.id, version_row.id,
       quote_recipient.id, access_link_id, p_logical_send_key, recipient.normalized_value,
       rendered.subject, rendered.html_content, rendered.text_content,
       'automated', 'essential', sender.id, alias.id, null)
      returning * into intent;
  exception when unique_violation then
    select * into intent from public.communication_delivery_intents
      where organization_id = p_organization_id and logical_send_key = p_logical_send_key;
    return jsonb_build_object('status', 'sent', 'reason', 'already_enqueued', 'intent_id', intent.id);
  end;

  insert into public.communication_outbox_events (organization_id, delivery_intent_id)
    values (intent.organization_id, intent.id);

  return jsonb_build_object('status', 'sent', 'reason', 'enqueued', 'intent_id', intent.id);
end;
$_$;


ALTER FUNCTION "public"."enqueue_automation_quote_email"("p_organization_id" "uuid", "p_quote_id" "uuid", "p_logical_send_key" "text", "p_subject" "text", "p_body" "text", "p_quote_url" "text", "p_quote_token_hash" "bytea") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_automation_quote_email"("p_organization_id" "uuid", "p_quote_id" "uuid", "p_logical_send_key" "text", "p_subject" "text", "p_body" "text", "p_quote_url" "text", "p_quote_token_hash" "bytea") IS 'System-authorized automation email send: re-checks entitlement, authority, the quote stop conditions (awaiting response and the client''s follow-up preference), recipient, and sender readiness, renders safe copy, and enqueues one delivery intent idempotently on the logical send key. Returns sent / skipped_permanent / skipped_temporary. Service role only.';



CREATE OR REPLACE FUNCTION "public"."enqueue_automation_quote_sms"("p_organization_id" "uuid", "p_quote_id" "uuid", "p_logical_send_key" "text", "p_body" "text", "p_sender_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  authority public.organization_automation_authority;
  quote_row public.quotes;
  version_row public.quote_versions;
  client_row public.clients;
  recipient public.client_contact_methods;
  sender public.communication_sms_sender_identities;
  stop_outcome text;
  customer_name text;
  rendered_body text;
  intent public.communication_delivery_intents;
begin
  if coalesce(btrim(p_body), '') = '' then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'invalid_sms_content');
  end if;

  if not private.organization_has_automations_feature(p_organization_id, now()) then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'automations_not_entitled');
  end if;

  select * into authority from public.organization_automation_authority
    where organization_id = p_organization_id;
  if coalesce(authority.operational_state, 'enabled') <> 'enabled'
    or coalesce(authority.security_state, 'active') <> 'active' then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'automation_suspended');
  end if;

  -- The same quote stop check the email send uses: gone/archived, not awaiting a response, or the client
  -- turned quote follow-ups off. Channel-agnostic by design (private.automation_quote_stop_outcome).
  stop_outcome := private.automation_quote_stop_outcome(p_organization_id, p_quote_id);
  if stop_outcome is not null then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', stop_outcome);
  end if;

  select * into quote_row from public.quotes
    where organization_id = p_organization_id and id = p_quote_id for share;
  if quote_row.id is null then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'quote_not_sendable');
  end if;

  select * into version_row from public.quote_versions
    where organization_id = quote_row.organization_id and id = quote_row.current_published_version_id
      and quote_id = quote_row.id and status = 'published' for share;
  select * into client_row from public.clients
    where organization_id = quote_row.organization_id and id = quote_row.client_id and deleted_at is null for share;
  if version_row.id is null or client_row.id is null then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'recipient_unavailable');
  end if;

  -- The customer's current primary SMS-capable number only. Never a silent fallback to another saved number
  -- (docs/automation-behavior-contract.md § SMS customer action) -- no primary is a permanent skip.
  select * into recipient from public.client_contact_methods
    where organization_id = quote_row.organization_id and client_id = quote_row.client_id
      and kind = 'phone' and is_primary for share;
  if recipient.id is null then
    return jsonb_build_object('status', 'skipped_permanent', 'reason', 'recipient_unavailable');
  end if;

  -- Sender: an authored pin if the step named one, else the number this customer's SMS conversation has been
  -- using, else the organization default. Unattended Automation never infers a sender from a staff assignment
  -- (docs/automation-behavior-contract.md § SMS customer action).
  if p_sender_id is not null then
    select s.* into sender from public.communication_sms_sender_identities s
      where s.organization_id = quote_row.organization_id and s.id = p_sender_id
        and s.lifecycle_state = 'ready' and s.capable_sms;
  else
    select s.* into sender
    from public.communication_sms_sender_identities s
    where s.organization_id = quote_row.organization_id
      and s.lifecycle_state = 'ready' and s.capable_sms
      and s.id = (
        select di.sms_sender_identity_id
        from public.communication_delivery_intents di
        where di.organization_id = quote_row.organization_id
          and di.client_id = quote_row.client_id and di.channel = 'sms'
        order by di.created_at desc
        limit 1
      );
    if sender.id is null then
      select s.* into sender from public.communication_sms_sender_identities s
        where s.organization_id = quote_row.organization_id and s.is_default_sender
          and s.lifecycle_state = 'ready' and s.capable_sms;
    end if;
  end if;
  if sender.id is null then
    return jsonb_build_object('status', 'skipped_temporary', 'reason', 'sender_not_ready');
  end if;

  customer_name := coalesce(nullif(btrim(client_row.display_name), ''), recipient.normalized_value);
  rendered_body := private.render_automation_sms(
    p_body, customer_name, version_row.organization_name, quote_row.quote_number::text);

  begin
    intent := private.communication_sms_enqueue_operational_core(
      quote_row.organization_id, quote_row.client_id, recipient.id, sender.id,
      'service', rendered_body, 'automated', p_logical_send_key, null);
  exception
    when object_not_in_prerequisite_state or sqlstate 'P0402' then
      return jsonb_build_object('status', 'skipped_temporary', 'reason', left(sqlerrm, 200));
    when unique_violation or foreign_key_violation or sqlstate 'P0001' then
      return jsonb_build_object('status', 'skipped_permanent', 'reason', left(sqlerrm, 200));
  end;

  return jsonb_build_object('status', 'sent', 'reason', 'enqueued', 'intent_id', intent.id);
end;
$$;


ALTER FUNCTION "public"."enqueue_automation_quote_sms"("p_organization_id" "uuid", "p_quote_id" "uuid", "p_logical_send_key" "text", "p_body" "text", "p_sender_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_automation_quote_sms"("p_organization_id" "uuid", "p_quote_id" "uuid", "p_logical_send_key" "text", "p_body" "text", "p_sender_id" "uuid") IS 'System-authorized automation SMS send: re-checks entitlement, authority, and the quote stop conditions, resolves the primary customer number and the continuity/default/pinned sender, renders safe copy, and enqueues through the shared SMS core idempotently on the logical send key. Returns sent / skipped_permanent / skipped_temporary. Service role only.';



CREATE OR REPLACE FUNCTION "public"."enqueue_communication_email"("target_organization_id" "uuid", "target_client_id" "uuid", "target_contact_method_id" "uuid", "target_logical_send_key" "text", "target_recipient_email" "text", "target_subject" "text", "target_html_content" "text", "target_text_content" "text") RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  intent public.communication_delivery_intents;
begin
  if not private.is_organization_member(target_organization_id)
    or not private.has_permission(target_organization_id, 'conversations.send') then
    raise exception 'You do not have permission to send a customer message.' using errcode = 'insufficient_privilege';
  end if;

  if not exists (
    select 1
    from public.client_contact_methods
    where organization_id = target_organization_id
      and id = target_contact_method_id
      and client_id = target_client_id
      and kind = 'email'
      and normalized_value = lower(trim(target_recipient_email))
  ) then
    raise exception 'The recipient email does not belong to this client.' using errcode = 'foreign_key_violation';
  end if;

  insert into public.communication_delivery_intents (
    organization_id, client_id, client_contact_method_id, logical_send_key, recipient_email,
    subject, html_content, text_content, created_by
  ) values (
    target_organization_id, target_client_id, target_contact_method_id, target_logical_send_key,
    lower(trim(target_recipient_email)), target_subject, target_html_content, target_text_content,
    (select auth.uid())
  ) on conflict (organization_id, logical_send_key) do update
    set logical_send_key = excluded.logical_send_key
  returning * into intent;

  insert into public.communication_outbox_events (organization_id, delivery_intent_id)
  values (intent.organization_id, intent.id)
  on conflict (delivery_intent_id) do nothing;

  return intent;
end;
$$;


ALTER FUNCTION "public"."enqueue_communication_email"("target_organization_id" "uuid", "target_client_id" "uuid", "target_contact_method_id" "uuid", "target_logical_send_key" "text", "target_recipient_email" "text", "target_subject" "text", "target_html_content" "text", "target_text_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_conversation_reply_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_client_id" "uuid", "target_logical_send_key" "text", "target_subject" "text", "target_html_content" "text", "target_text_content" "text", "target_attachments" "jsonb" DEFAULT '[]'::"jsonb", "target_available_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  recipient public.client_contact_methods;
  latest_contact_method_id uuid;
  sender public.communication_email_senders;
  sender_domain public.communication_email_domains;
  intent public.communication_delivery_intents;
  alias public.communication_reply_aliases;
begin
  if not private.member_has_permission(target_organization_id, target_actor_user_id, 'conversations.send')
    or not private.member_has_permission(target_organization_id, target_actor_user_id, 'customers.view') then
    raise exception 'You do not have permission to send a customer message.' using errcode = 'insufficient_privilege';
  end if;

  if target_available_at is not null and target_available_at <= now() then
    raise exception 'Choose a send time in the future.' using errcode = 'check_violation';
  end if;

  if not exists (
    select 1 from public.organizations organization
    where organization.id = target_organization_id and organization.lifecycle_status = 'active'
  ) then
    raise exception 'This organization cannot send customer email right now.' using errcode = 'object_not_in_prerequisite_state';
  end if;

  -- The reply always goes to whichever address this conversation most recently used, not necessarily
  -- the customer's primary address -- falls back to primary only when the conversation itself has no
  -- resolvable prior activity (should not happen for an already-open conversation, kept defensive).
  select client_contact_method_id into latest_contact_method_id
  from (
    select client_contact_method_id, created_at
    from public.communication_delivery_intents
    where organization_id = target_organization_id and client_id = target_client_id
    union all
    select client_contact_method_id, created_at
    from public.communication_inbound_messages
    where organization_id = target_organization_id and client_id = target_client_id
  ) activity
  order by created_at desc
  limit 1;

  select method.* into recipient
  from public.client_contact_methods method
  join public.clients client
    on client.organization_id = method.organization_id and client.id = method.client_id
  where method.organization_id = target_organization_id
    and method.client_id = target_client_id
    and method.kind = 'email'
    and client.deleted_at is null
    and (latest_contact_method_id is null or method.id = latest_contact_method_id)
  order by method.is_primary desc, method.created_at, method.id
  limit 1
  for share of method, client;

  if recipient.id is null then
    raise exception 'This customer has no active email address to reply to.' using errcode = 'foreign_key_violation';
  end if;

  -- The actor's enabled manual sender is resolved and locked before its one referenced domain, exactly
  -- like enqueue_manual_communication_email. The worker repeats these authority checks before submission.
  select email_sender.* into sender
  from public.communication_email_senders email_sender
  where email_sender.organization_id = target_organization_id
    and email_sender.assigned_user_id = target_actor_user_id
    and email_sender.lifecycle_state = 'enabled'
    and email_sender.allows_manual
  order by email_sender.is_organization_default desc, email_sender.created_at, email_sender.id
  limit 1
  for share of email_sender;

  if sender.id is not null then
    select domain.* into sender_domain
    from public.communication_email_domains domain
    where domain.organization_id = target_organization_id
      and domain.id = sender.domain_id
      and domain.purpose = 'sending'
      and domain.lifecycle_state = 'verified'
      and domain.provider_verified
      and domain.provider_authenticated
      and domain.ownership_status = 'passing'
      and domain.dkim_status = 'passing'
    for share of domain;
  end if;

  if sender.id is null or sender_domain.id is null then
    raise exception 'Your assigned email sender is not ready. Ask an administrator to review it.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  alias := public.ensure_communication_reply_alias(target_organization_id, sender.id, target_client_id, recipient.id);

  insert into public.communication_delivery_intents (
    organization_id, client_id, client_contact_method_id, logical_send_key, recipient_email,
    subject, html_content, text_content, send_kind, allowance_class, sender_id, reply_alias_id, created_by
  ) values (
    target_organization_id, target_client_id, recipient.id, target_logical_send_key,
    recipient.normalized_value, target_subject, target_html_content, target_text_content,
    'manual', 'essential', sender.id, alias.id, target_actor_user_id
  ) on conflict (organization_id, logical_send_key) do update
    set logical_send_key = excluded.logical_send_key
  returning * into intent;

  perform private.attach_communication_outbound_files(
    intent.organization_id, intent.id, target_attachments
  );

  insert into public.communication_outbox_events (organization_id, delivery_intent_id, available_at)
  values (intent.organization_id, intent.id, coalesce(target_available_at, now()))
  on conflict (delivery_intent_id) do nothing;

  return intent;
end;
$$;


ALTER FUNCTION "public"."enqueue_conversation_reply_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_client_id" "uuid", "target_logical_send_key" "text", "target_subject" "text", "target_html_content" "text", "target_text_content" "text", "target_attachments" "jsonb", "target_available_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_conversation_reply_sms"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_client_id" "uuid", "target_logical_send_key" "text", "target_body" "text", "target_attachments" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  recipient public.client_contact_methods;
  latest_contact_method_id uuid;
  intent public.communication_delivery_intents;
begin
  select client_contact_method_id into latest_contact_method_id
  from (
    select client_contact_method_id, created_at
    from public.communication_delivery_intents
    where organization_id = target_organization_id and client_id = target_client_id and channel = 'sms'
    union all
    select client_contact_method_id, created_at
    from public.communication_inbound_messages
    where organization_id = target_organization_id and client_id = target_client_id and channel = 'sms'
  ) activity
  order by created_at desc
  limit 1;

  select method.* into recipient
  from public.client_contact_methods method
  join public.clients client
    on client.organization_id = method.organization_id and client.id = method.client_id
  where method.organization_id = target_organization_id
    and method.client_id = target_client_id
    and method.kind = 'phone'
    and client.deleted_at is null
    and (latest_contact_method_id is null or method.id = latest_contact_method_id)
  order by method.is_primary desc, method.created_at, method.id
  limit 1
  for share of method, client;

  if recipient.id is null then
    raise exception 'This customer has no active phone number to reply to.' using errcode = 'foreign_key_violation';
  end if;

  intent := public.communication_sms_enqueue_operational(
    target_organization_id, target_actor_user_id, target_client_id, recipient.id,
    null, 'service', target_body, 'manual', target_logical_send_key, target_attachments
  );

  return intent;
end;
$$;


ALTER FUNCTION "public"."enqueue_conversation_reply_sms"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_client_id" "uuid", "target_logical_send_key" "text", "target_body" "text", "target_attachments" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_conversation_reply_sms"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_client_id" "uuid", "target_logical_send_key" "text", "target_body" "text", "target_attachments" "jsonb") IS 'Resolves the SMS reply recipient from this conversation''s own most recent activity (falling back to the primary phone), then delegates the send -- including attachment delivery-mode resolution -- straight to communication_sms_enqueue_operational with subject ''service'' and the organization''s default sender.';



CREATE TABLE IF NOT EXISTS "public"."communication_forward_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "source_inbound_message_id" "uuid" NOT NULL,
    "sender_id" "uuid" NOT NULL,
    "recipient_emails" "text"[] NOT NULL,
    "logical_send_key" "text" NOT NULL,
    "subject" "text" NOT NULL,
    "html_content" "text" NOT NULL,
    "text_content" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "provider_message_id" "text",
    "accepted_at" timestamp with time zone,
    "failure_code" "text",
    "failure_message" "text",
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "claim_token" "uuid",
    "finalized_claim_token" "uuid",
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "last_error" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "communication_forward_events_accepted_check" CHECK ((("status" = 'submitted'::"text") = (("accepted_at" IS NOT NULL) AND ("provider_message_id" IS NOT NULL)))),
    CONSTRAINT "communication_forward_events_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "communication_forward_events_claim_check" CHECK ((("status" = 'claimed'::"text") = (("claimed_at" IS NOT NULL) AND ("claim_token" IS NOT NULL)))),
    CONSTRAINT "communication_forward_events_html_content_check" CHECK (("char_length"(TRIM(BOTH FROM "html_content")) > 0)),
    CONSTRAINT "communication_forward_events_logical_send_key_check" CHECK ((("char_length"(TRIM(BOTH FROM "logical_send_key")) >= 1) AND ("char_length"(TRIM(BOTH FROM "logical_send_key")) <= 200))),
    CONSTRAINT "communication_forward_events_recipients_bounds" CHECK ((("array_length"("recipient_emails", 1) >= 1) AND ("array_length"("recipient_emails", 1) <= 10))),
    CONSTRAINT "communication_forward_events_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'claimed'::"text", 'submitted'::"text", 'failed'::"text", 'cancelled'::"text", 'submission_unknown'::"text"]))),
    CONSTRAINT "communication_forward_events_subject_check" CHECK ((("char_length"(TRIM(BOTH FROM "subject")) >= 1) AND ("char_length"(TRIM(BOTH FROM "subject")) <= 998))),
    CONSTRAINT "communication_forward_events_text_content_check" CHECK (("char_length"(TRIM(BOTH FROM "text_content")) > 0))
);


ALTER TABLE "public"."communication_forward_events" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_inbound_message_forward"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_source_inbound_message_id" "uuid", "target_logical_send_key" "text", "target_recipient_emails" "text"[], "target_subject" "text", "target_html_content" "text", "target_text_content" "text", "target_attachment_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "public"."communication_forward_events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  source_message public.communication_inbound_messages;
  sender public.communication_email_senders;
  sender_domain public.communication_email_domains;
  event public.communication_forward_events;
  available_attachment_count integer;
  requested_attachment_count integer;
begin
  if not private.member_has_permission(target_organization_id, target_actor_user_id, 'conversations.forward')
    or not private.member_has_permission(target_organization_id, target_actor_user_id, 'customers.view') then
    raise exception 'You do not have permission to forward a message.' using errcode = 'insufficient_privilege';
  end if;

  if not exists (
    select 1 from public.organizations organization
    where organization.id = target_organization_id and organization.lifecycle_status = 'active'
  ) then
    raise exception 'This organization cannot forward email right now.' using errcode = 'object_not_in_prerequisite_state';
  end if;

  select message.* into source_message
  from public.communication_inbound_messages message
  where message.organization_id = target_organization_id
    and message.id = target_source_inbound_message_id
  for share;

  if source_message.id is null then
    raise exception 'This message does not exist.' using errcode = 'no_data_found';
  end if;
  if source_message.client_id is null then
    raise exception 'Resolve this message to a conversation before forwarding it.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  if target_recipient_emails is null or array_length(target_recipient_emails, 1) is null
    or array_length(target_recipient_emails, 1) > 10 then
    raise exception 'Choose between 1 and 10 recipients.' using errcode = 'check_violation';
  end if;
  if exists (
    select 1 from unnest(target_recipient_emails) recipient_email where position('@' in recipient_email) < 2
  ) then
    raise exception 'Enter a valid email address for every recipient.' using errcode = 'check_violation';
  end if;

  requested_attachment_count := coalesce(array_length(target_attachment_ids, 1), 0);
  if requested_attachment_count > 0 then
    select count(*) into available_attachment_count
    from public.communication_inbound_attachments attachment
    where attachment.organization_id = target_organization_id
      and attachment.inbound_message_id = target_source_inbound_message_id
      and attachment.status = 'available'
      and attachment.id = any(target_attachment_ids);
    if available_attachment_count <> requested_attachment_count then
      raise exception 'One or more attachments are no longer available to forward.'
        using errcode = 'object_not_in_prerequisite_state';
    end if;
  end if;

  -- Same sender resolution as enqueue_conversation_reply_email: the actor's own enabled manual sender,
  -- locked before its one referenced domain. The claim function repeats this check defensively.
  select email_sender.* into sender
  from public.communication_email_senders email_sender
  where email_sender.organization_id = target_organization_id
    and email_sender.assigned_user_id = target_actor_user_id
    and email_sender.lifecycle_state = 'enabled'
    and email_sender.allows_manual
  order by email_sender.is_organization_default desc, email_sender.created_at, email_sender.id
  limit 1
  for share of email_sender;

  if sender.id is not null then
    select domain.* into sender_domain
    from public.communication_email_domains domain
    where domain.organization_id = target_organization_id
      and domain.id = sender.domain_id
      and domain.purpose = 'sending'
      and domain.lifecycle_state = 'verified'
      and domain.provider_verified
      and domain.provider_authenticated
      and domain.ownership_status = 'passing'
      and domain.dkim_status = 'passing'
    for share of domain;
  end if;

  if sender.id is null or sender_domain.id is null then
    raise exception 'Your assigned email sender is not ready. Ask an administrator to review it.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  insert into public.communication_forward_events (
    organization_id, client_id, source_inbound_message_id, sender_id, recipient_emails,
    logical_send_key, subject, html_content, text_content, created_by
  ) values (
    target_organization_id, source_message.client_id, target_source_inbound_message_id, sender.id,
    target_recipient_emails, target_logical_send_key, target_subject, target_html_content,
    target_text_content, target_actor_user_id
  ) on conflict (organization_id, logical_send_key) do update
    set logical_send_key = excluded.logical_send_key
  returning * into event;

  if requested_attachment_count > 0 then
    insert into public.communication_forward_attachments (organization_id, forward_event_id, inbound_attachment_id)
    select target_organization_id, event.id, attachment_id
    from unnest(target_attachment_ids) attachment_id
    on conflict (forward_event_id, inbound_attachment_id) do nothing;
  end if;

  return event;
end;
$$;


ALTER FUNCTION "public"."enqueue_inbound_message_forward"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_source_inbound_message_id" "uuid", "target_logical_send_key" "text", "target_recipient_emails" "text"[], "target_subject" "text", "target_html_content" "text", "target_text_content" "text", "target_attachment_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_invoice_communication_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_invoice_id" "uuid", "target_logical_send_key" "text", "target_invoice_url" "text", "target_invoice_token_hash" "bytea") RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  invoice_row public.invoices; client_row public.clients;
  recipient public.client_contact_methods;
  business_name text;
  sender public.communication_email_senders; sender_domain public.communication_email_domains;
  intent public.communication_delivery_intents;
begin
  if not private.member_has_permission(target_organization_id, target_actor_user_id, 'invoices.send')
    or not private.member_has_permission(target_organization_id, target_actor_user_id, 'conversations.send') then
    raise exception 'You do not have permission to send this invoice by email.' using errcode = 'insufficient_privilege';
  end if;
  if target_invoice_url !~ '^https?://[^[:space:]]+$' or target_invoice_token_hash is null
    or octet_length(target_invoice_token_hash) <> 32 then
    raise exception 'The invoice delivery link is not available.' using errcode = 'check_violation';
  end if;
  select * into intent from public.communication_delivery_intents
    where organization_id = target_organization_id and logical_send_key = target_logical_send_key for share;
  if intent.id is not null then
    if intent.invoice_id is distinct from target_invoice_id then
      raise exception 'This email retry does not match the original invoice.' using errcode = 'unique_violation';
    end if;
    return intent;
  end if;
  select * into invoice_row from public.invoices
    where organization_id = target_organization_id and id = target_invoice_id for share;
  if invoice_row.id is null or invoice_row.issued_at is null
    or invoice_row.voided_at is not null or invoice_row.replaced_at is not null then
    raise exception 'This invoice is not available to send.' using errcode = 'foreign_key_violation';
  end if;
  select * into client_row from public.clients
    where organization_id = invoice_row.organization_id and id = invoice_row.client_id and deleted_at is null for share;
  select * into recipient from public.client_contact_methods
    where organization_id = invoice_row.organization_id and client_id = invoice_row.client_id and kind = 'email'
    order by is_primary desc, created_at, id limit 1 for share;
  if client_row.id is null or recipient.id is null then
    raise exception 'This invoice needs an active customer email address before it can be sent.' using errcode = 'object_not_in_prerequisite_state';
  end if;
  select organization.name into business_name from public.organizations as organization
    where organization.id = invoice_row.organization_id;
  -- The organization's default automated sender, exactly as enqueue_quote_communication_email chooses it.
  -- (An earlier draft preferred a sender assigned to the client's owner, but clients carry no owner column,
  -- so that reference raised undefined_column on every real send.)
  select * into sender from public.communication_email_senders
    where organization_id = invoice_row.organization_id and lifecycle_state = 'enabled' and allows_automated
      and is_organization_default
    order by created_at, id limit 1 for share;
  if sender.id is not null then
    select * into sender_domain from public.communication_email_domains
      where organization_id = sender.organization_id and id = sender.domain_id and purpose = 'sending'
        and lifecycle_state = 'verified' and provider_verified and provider_authenticated
        and ownership_status = 'passing' and dkim_status = 'passing' for share;
  end if;
  if sender.id is null or sender_domain.id is null then
    raise exception 'No automated email sender is ready for this business.' using errcode = 'object_not_in_prerequisite_state';
  end if;
  update public.invoice_access_links set revoked_at = now(), revoked_reason = 'rotated'
    where organization_id = invoice_row.organization_id and invoice_id = invoice_row.id and revoked_at is null;
  insert into public.invoice_access_links (organization_id, invoice_id, recipient_name, recipient_email, token_hash, issued_by)
    values (invoice_row.organization_id, invoice_row.id,
      coalesce(nullif(trim(client_row.display_name), ''), recipient.normalized_value), recipient.normalized_value,
      target_invoice_token_hash, target_actor_user_id);
  insert into public.communication_delivery_intents (organization_id, client_id, client_contact_method_id, invoice_id, logical_send_key, recipient_email, subject, html_content, text_content, send_kind, allowance_class, sender_id, created_by)
    values (invoice_row.organization_id, invoice_row.client_id, recipient.id, invoice_row.id, target_logical_send_key, recipient.normalized_value,
      'Your invoice from ' || coalesce(nullif(trim(business_name), ''), 'your contractor'),
      '<p>Your invoice is ready to view.</p><p><a href="' || replace(target_invoice_url, '&', '&amp;') || '">View your invoice</a></p>',
      'Your invoice is ready to view. View it here: ' || target_invoice_url, 'automated', 'essential', sender.id, target_actor_user_id)
    returning * into intent;
  insert into public.communication_outbox_events (organization_id, delivery_intent_id) values (intent.organization_id, intent.id);
  perform private.record_invoice_event(
    invoice_row.organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.sent', target_actor_user_id, invoice_row.revision, null,
    jsonb_build_object('delivery_intent_id', intent.id, 'recipient_email', recipient.normalized_value)
  );
  return intent;
end;
$_$;


ALTER FUNCTION "public"."enqueue_invoice_communication_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_invoice_id" "uuid", "target_logical_send_key" "text", "target_invoice_url" "text", "target_invoice_token_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_manual_communication_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_client_id" "uuid", "target_contact_method_id" "uuid", "target_logical_send_key" "text", "target_subject" "text", "target_html_content" "text", "target_text_content" "text", "target_attachments" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  recipient public.client_contact_methods;
  sender public.communication_email_senders;
  sender_domain public.communication_email_domains;
  intent public.communication_delivery_intents;
  alias public.communication_reply_aliases;
begin
  if not private.member_has_permission(target_organization_id, target_actor_user_id, 'conversations.send')
    or not private.member_has_permission(target_organization_id, target_actor_user_id, 'customers.view') then
    raise exception 'You do not have permission to send a customer message.' using errcode = 'insufficient_privilege';
  end if;

  if not exists (
    select 1 from public.organizations organization
    where organization.id = target_organization_id and organization.lifecycle_status = 'active'
  ) then
    raise exception 'This organization cannot send customer email right now.' using errcode = 'object_not_in_prerequisite_state';
  end if;

  select method.* into recipient
  from public.client_contact_methods method
  join public.clients client
    on client.organization_id = method.organization_id and client.id = method.client_id
  where method.organization_id = target_organization_id
    and method.id = target_contact_method_id
    and method.client_id = target_client_id
    and method.kind = 'email'
    and client.deleted_at is null
  for share of method, client;

  if recipient.id is null then
    raise exception 'Choose an active email address for this customer.' using errcode = 'foreign_key_violation';
  end if;

  -- The actor's enabled manual sender is resolved and locked before its one referenced domain.
  -- The worker repeats these authority checks immediately before provider submission.
  select email_sender.* into sender
  from public.communication_email_senders email_sender
  where email_sender.organization_id = target_organization_id
    and email_sender.assigned_user_id = target_actor_user_id
    and email_sender.lifecycle_state = 'enabled'
    and email_sender.allows_manual
  order by email_sender.is_organization_default desc, email_sender.created_at, email_sender.id
  limit 1
  for share of email_sender;

  if sender.id is not null then
    select domain.* into sender_domain
    from public.communication_email_domains domain
    where domain.organization_id = target_organization_id
      and domain.id = sender.domain_id
      and domain.purpose = 'sending'
      and domain.lifecycle_state = 'verified'
      and domain.provider_verified
      and domain.provider_authenticated
      and domain.ownership_status = 'passing'
      and domain.dkim_status = 'passing'
    for share of domain;
  end if;

  if sender.id is null or sender_domain.id is null then
    raise exception 'Your assigned email sender is not ready. Ask an administrator to review it.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  alias := public.ensure_communication_reply_alias(target_organization_id, sender.id, target_client_id, recipient.id);

  insert into public.communication_delivery_intents (
    organization_id, client_id, client_contact_method_id, logical_send_key, recipient_email,
    subject, html_content, text_content, send_kind, allowance_class, sender_id, reply_alias_id, created_by
  ) values (
    target_organization_id, target_client_id, target_contact_method_id, target_logical_send_key,
    recipient.normalized_value, target_subject, target_html_content, target_text_content,
    'manual', 'optional', sender.id, alias.id, target_actor_user_id
  ) on conflict (organization_id, logical_send_key) do update
    set logical_send_key = excluded.logical_send_key
  returning * into intent;

  -- Same ordering as enqueue_conversation_reply_email: attached inside this transaction and before the
  -- outbox event, so the worker can never claim a message before its files are recorded.
  perform private.attach_communication_outbound_files(
    intent.organization_id, intent.id, target_attachments
  );

  insert into public.communication_outbox_events (organization_id, delivery_intent_id)
  values (intent.organization_id, intent.id)
  on conflict (delivery_intent_id) do nothing;

  return intent;
end;
$$;


ALTER FUNCTION "public"."enqueue_manual_communication_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_client_id" "uuid", "target_contact_method_id" "uuid", "target_logical_send_key" "text", "target_subject" "text", "target_html_content" "text", "target_text_content" "text", "target_attachments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_payment_receipt_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_payment_event_id" "uuid", "target_logical_send_key" "text", "target_receipt_url" "text", "target_receipt_token_hash" "bytea") RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  receipt public.client_payment_events; client_row public.clients;
  recipient public.client_contact_methods;
  business_name text; money_text text;
  sender public.communication_email_senders; sender_domain public.communication_email_domains;
  intent public.communication_delivery_intents;
begin
  -- A staff send names the person. The automatic receipt after an online payment names nobody, and is allowed
  -- only for a payment Stripe confirmed (checked once the payment is loaded below).
  if target_actor_user_id is not null and (
    not private.member_has_permission(target_organization_id, target_actor_user_id, 'invoices.record_payment')
    or not private.member_has_permission(target_organization_id, target_actor_user_id, 'conversations.send')) then
    raise exception 'You do not have permission to send this receipt by email.' using errcode = 'insufficient_privilege';
  end if;
  if target_receipt_url !~ '^https?://[^[:space:]]+$' or target_receipt_token_hash is null
    or octet_length(target_receipt_token_hash) <> 32 then
    raise exception 'The receipt link is not available.' using errcode = 'check_violation';
  end if;

  select * into intent from public.communication_delivery_intents
    where organization_id = target_organization_id and logical_send_key = target_logical_send_key for share;
  if intent.id is not null then
    if intent.client_payment_event_id is distinct from target_payment_event_id then
      raise exception 'This receipt retry does not match the original payment.' using errcode = 'unique_violation';
    end if;
    return intent;
  end if;

  select * into receipt from public.client_payment_events
    where organization_id = target_organization_id and id = target_payment_event_id for share;
  if receipt.id is null or receipt.event_type <> 'received' then
    raise exception 'This payment does not have a receipt to send.' using errcode = 'foreign_key_violation';
  end if;
  if target_actor_user_id is null and receipt.method not in ('stripe_card', 'stripe_bank', 'stripe_other') then
    raise exception 'You do not have permission to send this receipt by email.' using errcode = 'insufficient_privilege';
  end if;

  select * into client_row from public.clients
    where organization_id = receipt.organization_id and id = receipt.client_id and deleted_at is null for share;
  select * into recipient from public.client_contact_methods
    where organization_id = receipt.organization_id and client_id = receipt.client_id and kind = 'email'
    order by is_primary desc, created_at, id limit 1 for share;
  if client_row.id is null or recipient.id is null then
    raise exception 'This payment needs an active customer email address before a receipt can be sent.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  select organization.name into business_name from public.organizations as organization
    where organization.id = receipt.organization_id;

  -- The organization's default automated sender, exactly as the invoice and quote emails choose it.
  select * into sender from public.communication_email_senders
    where organization_id = receipt.organization_id and lifecycle_state = 'enabled' and allows_automated
      and is_organization_default
    order by created_at, id limit 1 for share;
  if sender.id is not null then
    select * into sender_domain from public.communication_email_domains
      where organization_id = sender.organization_id and id = sender.domain_id and purpose = 'sending'
        and lifecycle_state = 'verified' and provider_verified and provider_authenticated
        and ownership_status = 'passing' and dkim_status = 'passing' for share;
  end if;
  if sender.id is null or sender_domain.id is null then
    raise exception 'No automated email sender is ready for this business.' using errcode = 'object_not_in_prerequisite_state';
  end if;

  update public.payment_receipt_access_links set revoked_at = now(), revoked_reason = 'rotated'
    where organization_id = receipt.organization_id and client_payment_event_id = receipt.id and revoked_at is null;
  insert into public.payment_receipt_access_links (organization_id, client_payment_event_id, recipient_name, recipient_email, token_hash, issued_by)
    values (receipt.organization_id, receipt.id,
      coalesce(nullif(trim(client_row.display_name), ''), recipient.normalized_value), recipient.normalized_value,
      target_receipt_token_hash, target_actor_user_id);

  money_text := trim(to_char(receipt.amount_minor / 100.0, 'FM999G999G990D00')) || ' ' || receipt.currency_code;
  insert into public.communication_delivery_intents (organization_id, client_id, client_contact_method_id, client_payment_event_id, logical_send_key, recipient_email, subject, html_content, text_content, send_kind, allowance_class, sender_id, created_by)
    values (receipt.organization_id, receipt.client_id, recipient.id, receipt.id, target_logical_send_key, recipient.normalized_value,
      'Receipt for your payment to ' || coalesce(nullif(trim(business_name), ''), 'your contractor'),
      '<p>Thank you for your payment of ' || money_text || '.</p><p><a href="' || replace(target_receipt_url, '&', '&amp;') || '">View your receipt</a></p>',
      'Thank you for your payment of ' || money_text || '. View your receipt here: ' || target_receipt_url,
      'automated', 'essential', sender.id, target_actor_user_id)
    returning * into intent;
  insert into public.communication_outbox_events (organization_id, delivery_intent_id) values (intent.organization_id, intent.id);

  return intent;
end;
$_$;


ALTER FUNCTION "public"."enqueue_payment_receipt_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_payment_event_id" "uuid", "target_logical_send_key" "text", "target_receipt_url" "text", "target_receipt_token_hash" "bytea") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_payment_receipt_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_payment_event_id" "uuid", "target_logical_send_key" "text", "target_receipt_url" "text", "target_receipt_token_hash" "bytea") IS 'Queues one payment-receipt email as a hosted link (no PDF attachment -- we run no PDF engine). Idempotent on the logical send key; a deliberate resend passes a new key. A null actor is the automatic receipt for a Stripe-confirmed payment. Service role only.';



CREATE OR REPLACE FUNCTION "public"."enqueue_quote_communication_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_quote_id" "uuid", "target_logical_send_key" "text", "target_quote_url" "text", "target_quote_token_hash" "bytea") RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  quote_row public.quotes; version_row public.quote_versions; client_row public.clients;
  recipient public.client_contact_methods; quote_recipient public.quote_recipients;
  sender public.communication_email_senders; sender_domain public.communication_email_domains;
  intent public.communication_delivery_intents;
  alias public.communication_reply_aliases;
  access_link_id uuid;
begin
  if not private.member_has_permission(target_organization_id, target_actor_user_id, 'quotes.send')
    or not private.member_has_permission(target_organization_id, target_actor_user_id, 'conversations.send') then
    raise exception 'You do not have permission to send this quote by email.' using errcode = 'insufficient_privilege';
  end if;
  if target_quote_url !~ '^https?://[^[:space:]]+$' or target_quote_token_hash is null
    or octet_length(target_quote_token_hash) <> 32 then
    raise exception 'The quote delivery link is not available.' using errcode = 'check_violation';
  end if;
  select * into intent from public.communication_delivery_intents
    where organization_id = target_organization_id and logical_send_key = target_logical_send_key for share;
  if intent.id is not null then
    if intent.quote_id is distinct from target_quote_id then
      raise exception 'This email retry does not match the original quote.' using errcode = 'unique_violation';
    end if;
    return intent;
  end if;
  select * into quote_row from public.quotes
    where organization_id = target_organization_id and id = target_quote_id
      and status in ('awaiting_response', 'changes_requested', 'approved') and archived_at is null for share;
  if quote_row.id is null then raise exception 'This quote is not available to send.' using errcode = 'foreign_key_violation'; end if;
  select * into version_row from public.quote_versions
    where organization_id = quote_row.organization_id and id = quote_row.current_published_version_id
      and quote_id = quote_row.id and status = 'published' for share;
  select * into client_row from public.clients
    where organization_id = quote_row.organization_id and id = quote_row.client_id and deleted_at is null for share;
  select * into recipient from public.client_contact_methods
    where organization_id = quote_row.organization_id and client_id = quote_row.client_id and kind = 'email'
    order by is_primary desc, created_at, id limit 1 for share;
  if version_row.id is null or client_row.id is null or recipient.id is null then
    raise exception 'This quote needs an active customer email address before it can be sent.' using errcode = 'object_not_in_prerequisite_state';
  end if;
  select * into sender from public.communication_email_senders
    where organization_id = quote_row.organization_id and lifecycle_state = 'enabled' and allows_automated
      and is_organization_default
    order by created_at, id limit 1 for share;
  if sender.id is not null then
    select * into sender_domain from public.communication_email_domains
      where organization_id = sender.organization_id and id = sender.domain_id and purpose = 'sending'
        and lifecycle_state = 'verified' and provider_verified and provider_authenticated
        and ownership_status = 'passing' and dkim_status = 'passing' for share;
  end if;
  if sender.id is null or sender_domain.id is null then
    raise exception 'No automated email sender is ready for this business.' using errcode = 'object_not_in_prerequisite_state';
  end if;

  alias := public.ensure_communication_reply_alias(quote_row.organization_id, sender.id, quote_row.client_id, recipient.id);

  insert into public.quote_recipients (organization_id, quote_id, display_name, email, created_by)
    values (quote_row.organization_id, quote_row.id, coalesce(nullif(trim(client_row.display_name), ''), recipient.normalized_value), recipient.normalized_value, target_actor_user_id)
    on conflict (organization_id, quote_id, email) do update set display_name = excluded.display_name returning * into quote_recipient;
  update public.quote_access_links set revoked_at = now(), revoked_reason = 'rotated'
    where organization_id = quote_row.organization_id and quote_id = quote_row.id and recipient_id = quote_recipient.id and revoked_at is null;
  insert into public.quote_access_links (organization_id, quote_id, quote_version_id, recipient_id, token_hash, issued_by)
    values (quote_row.organization_id, quote_row.id, version_row.id, quote_recipient.id, target_quote_token_hash, target_actor_user_id)
    returning id into access_link_id;
  insert into public.communication_delivery_intents (organization_id, client_id, client_contact_method_id, quote_id, quote_version_id, quote_recipient_id, quote_access_link_id, logical_send_key, recipient_email, subject, html_content, text_content, send_kind, allowance_class, sender_id, reply_alias_id, created_by)
    values (quote_row.organization_id, quote_row.client_id, recipient.id, quote_row.id, version_row.id, quote_recipient.id, access_link_id, target_logical_send_key, recipient.normalized_value,
      'Your quote from ' || version_row.organization_name,
      '<p>Your quote is ready to review.</p><p><a href="' || replace(target_quote_url, '&', '&amp;') || '">View your quote</a></p>',
      'Your quote is ready to review. View it here: ' || target_quote_url, 'automated', 'essential', sender.id, alias.id, target_actor_user_id)
    returning * into intent;
  insert into public.communication_outbox_events (organization_id, delivery_intent_id) values (intent.organization_id, intent.id);
  return intent;
end;
$_$;


ALTER FUNCTION "public"."enqueue_quote_communication_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_quote_id" "uuid", "target_logical_send_key" "text", "target_quote_url" "text", "target_quote_token_hash" "bytea") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_reply_aliases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "receiving_domain_id" "uuid" NOT NULL,
    "sender_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "client_contact_method_id" "uuid" NOT NULL,
    "alias_local_part" "text" NOT NULL,
    "last_activity_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '90 days'::interval) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."communication_reply_aliases" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_communication_reply_alias"("target_organization_id" "uuid", "target_sender_id" "uuid", "target_client_id" "uuid", "target_contact_method_id" "uuid") RETURNS "public"."communication_reply_aliases"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare
  alias public.communication_reply_aliases;
  receiving_domain public.communication_email_domains;
begin
  update public.communication_reply_aliases
    set last_activity_at = now(), expires_at = now() + interval '90 days', updated_at = now()
    where organization_id = target_organization_id and sender_id = target_sender_id
      and client_id = target_client_id and client_contact_method_id = target_contact_method_id
    returning * into alias;
  if alias.id is not null then
    return alias;
  end if;

  select * into receiving_domain from public.communication_email_domains
  where organization_id = target_organization_id and purpose = 'receiving' and lifecycle_state = 'verified'
  order by created_at
  limit 1;
  if receiving_domain.id is null then
    return null;
  end if;

  loop
    begin
      insert into public.communication_reply_aliases (
        organization_id, receiving_domain_id, sender_id, client_id, client_contact_method_id, alias_local_part
      ) values (
        target_organization_id, receiving_domain.id, target_sender_id, target_client_id, target_contact_method_id,
        encode(gen_random_bytes(16), 'hex')
      ) returning * into alias;
      exit;
    exception when unique_violation then
      select * into alias from public.communication_reply_aliases
        where organization_id = target_organization_id and sender_id = target_sender_id
          and client_id = target_client_id and client_contact_method_id = target_contact_method_id;
      if alias.id is not null then exit; end if;
    end;
  end loop;

  return alias;
end;
$$;


ALTER FUNCTION "public"."ensure_communication_reply_alias"("target_organization_id" "uuid", "target_sender_id" "uuid", "target_client_id" "uuid", "target_contact_method_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_communication_email_reputation"("p_organization_id" "uuid", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  measured jsonb;
  worst_rank integer := 1;
  worst text := 'ok';
  breach jsonb;
  existing_pause public.communication_email_sending_pauses%rowtype;
  new_pause_id uuid;
  pause_reason text;
begin
  select
    coalesce(jsonb_agg(to_jsonb(m) order by m.signal, m.window_key), '[]'::jsonb),
    coalesce(max(case m.status when 'pause' then 3 when 'warn' then 2 else 1 end), 1)
  into measured, worst_rank
  from private.communication_email_reputation_metrics(p_organization_id, p_at) m;

  worst := case worst_rank when 3 then 'pause' when 2 then 'warn' else 'ok' end;

  insert into public.communication_email_reputation_state (
    organization_id, evaluated_at, worst_status, metrics, last_breach_at
  ) values (
    p_organization_id, p_at, worst, measured,
    case when worst = 'pause' then p_at end
  )
  on conflict (organization_id) do update set
    evaluated_at = excluded.evaluated_at,
    worst_status = excluded.worst_status,
    metrics = excluded.metrics,
    last_breach_at = coalesce(excluded.last_breach_at,
      public.communication_email_reputation_state.last_breach_at);

  if worst <> 'pause' then
    return jsonb_build_object('organization_id', p_organization_id, 'worst_status', worst,
      'paused', false, 'metrics', measured);
  end if;

  select entry into breach
  from jsonb_array_elements(measured) entry
  where entry ->> 'status' = 'pause'
  order by ((entry ->> 'rate')::numeric / nullif((entry ->> 'pause_rate')::numeric, 0)) desc nulls last
  limit 1;

  select * into existing_pause
  from public.communication_email_sending_pauses
  where scope = 'organization'
    and organization_id = p_organization_id
    and source = 'auto_reputation'
    and released_at is null
  for update;

  if found then
    return jsonb_build_object('organization_id', p_organization_id, 'worst_status', worst,
      'paused', true, 'pause_id', existing_pause.id, 'metrics', measured);
  end if;

  pause_reason := format(
    'Automatic pause: %s rate %s%% over the %s window is at or above the %s%% threshold (%s of %s recipients).',
    replace(breach ->> 'signal', '_', ' '), breach ->> 'rate',
    case breach ->> 'window_key' when 'rolling_24h' then 'rolling 24-hour' else 'rolling 7-day' end,
    breach ->> 'pause_rate', breach ->> 'event_count', breach ->> 'accepted_recipients'
  );

  insert into public.communication_email_sending_pauses (
    scope, organization_id, reason, engaged_by_owner_email, source, applies_to, evidence
  ) values (
    'organization', p_organization_id, pause_reason, 'system', 'auto_reputation', 'optional',
    jsonb_build_object('signal', breach ->> 'signal', 'window_key', breach ->> 'window_key',
      'rate', (breach ->> 'rate')::numeric, 'pause_rate', (breach ->> 'pause_rate')::numeric,
      'event_count', (breach ->> 'event_count')::bigint,
      'accepted_recipients', (breach ->> 'accepted_recipients')::bigint,
      'evaluated_at', p_at)
  )
  returning id into new_pause_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, after_state
  ) values (
    'system', 'communications.email_reputation_pause_engaged', 'organization',
    p_organization_id::text,
    jsonb_build_object('pause_id', new_pause_id, 'reason', pause_reason, 'metrics', measured)
  );

  return jsonb_build_object('organization_id', p_organization_id, 'worst_status', worst,
    'paused', true, 'pause_id', new_pause_id, 'metrics', measured);
end;
$$;


ALTER FUNCTION "public"."evaluate_communication_email_reputation"("p_organization_id" "uuid", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_team_invitations"() RETURNS SETOF "public"."organization_member_invitations"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select * from public.expire_team_invitations_bounded(100);
$$;


ALTER FUNCTION "public"."expire_team_invitations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_team_invitations_bounded"("target_batch_size" integer DEFAULT 25) RETURNS SETOF "public"."organization_member_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_row record;
  updated_row public.organization_member_invitations;
begin
  if target_batch_size not between 1 and 100 then
    raise exception 'The invitation expiry batch is outside its safe bounds.'
      using errcode = 'check_violation';
  end if;

  for target_row in
    select invitation.id
    from public.organization_member_invitations as invitation
    where
      (invitation.state = 'invited' and invitation.expires_at < now())
      or (
        invitation.state = 'accepting'
        and invitation.expires_at < now()
        and invitation.lease_expires_at < now()
      )
    order by invitation.expires_at, invitation.id
    limit target_batch_size
    for update skip locked
  loop
    select * into updated_row
    from public.organization_member_invitations
    where id = target_row.id;

    if updated_row.state = 'invited' then
      update public.organization_member_invitations
      set state = 'expired',
          token_hash = null,
          lease_nonce = null,
          lease_expires_at = null,
          identity_cleanup_state = 'required',
          identity_cleanup_error = null
      where id = target_row.id
      returning * into updated_row;

      insert into public.organization_member_access_events (
        organization_id, event_type, actor_kind, subject_invitation_id, summary
      )
      values (
        updated_row.organization_id, 'invitation.expired', 'system', updated_row.id, '{}'::jsonb
      );
    else
      -- Shares the settle path expire_team_invitations previously used alone: a completed password receipt
      -- finalizes as accepted (logging itself); an unknown outcome is flagged for reconciliation, not expired.
      updated_row := private.settle_expired_acceptance(target_row.id);
    end if;

    return next updated_row;
  end loop;

  return;
end;
$$;


ALTER FUNCTION "public"."expire_team_invitations_bounded"("target_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_communication_email_domain_removal"("target_organization_id" "uuid", "target_domain_id" "uuid", "actor_owner_email" "text", "removal_reason" "text", "command_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_domain public.communication_email_domains;
  existing_event public.communication_email_authority_events;
  removed_at timestamptz := clock_timestamp();
  final_state jsonb;
begin
  if nullif(btrim(actor_owner_email), '') is null then
    raise exception 'Platform owner attribution is required.' using errcode = 'check_violation';
  end if;
  if char_length(btrim(removal_reason)) not between 1 and 500 then
    raise exception 'A valid removal reason is required.' using errcode = 'check_violation';
  end if;
  if char_length(btrim(command_idempotency_key)) not between 1 and 200 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;

  select * into existing_event
  from public.communication_email_authority_events
  where organization_id = target_organization_id
    and target_id = target_domain_id
    and event_type = 'domain.removed'
    and idempotency_key = command_idempotency_key;

  if found then
    return existing_event.after_state || jsonb_build_object('status', 'replayed');
  end if;

  select * into target_domain
  from public.communication_email_domains
  where organization_id = target_organization_id and id = target_domain_id
  for update;

  if not found or target_domain.purpose <> 'sending' then
    return jsonb_build_object('status', 'not_found');
  end if;
  if target_domain.lifecycle_state <> 'removal_pending' then
    return jsonb_build_object('status', 'not_pending');
  end if;

  final_state := jsonb_build_object(
    'domain_name', target_domain.domain_name,
    'purpose', 'sending',
    'lifecycle_state', 'removed',
    'provider_cleanup_confirmed', true,
    'removed_at', removed_at
  );

  update public.communication_email_domains
  set lifecycle_state = 'removed',
      provider_domain_id = null,
      provider_verified = false,
      provider_authenticated = false,
      ownership_status = 'unchecked',
      dkim_status = 'unchecked',
      dmarc_status = 'unchecked',
      spf_status = 'unchecked',
      dns_records = '[]'::jsonb,
      verified_at = null,
      warmup_started_at = null,
      transition_until = null,
      provider_cleanup_error = null,
      updated_at = removed_at
  where organization_id = target_organization_id and id = target_domain_id;

  insert into public.communication_email_authority_events (
    organization_id, actor_kind, actor_owner_email, event_type, target_type, target_id,
    before_state, after_state, reason, idempotency_key, occurred_at
  ) values (
    target_organization_id, 'platform_owner', btrim(actor_owner_email), 'domain.removed',
    'domain', target_domain_id,
    jsonb_build_object(
      'domain_name', target_domain.domain_name,
      'lifecycle_state', target_domain.lifecycle_state
    ),
    final_state, btrim(removal_reason), command_idempotency_key, removed_at
  );

  return final_state || jsonb_build_object('status', 'completed');
end;
$$;


ALTER FUNCTION "public"."finalize_communication_email_domain_removal"("target_organization_id" "uuid", "target_domain_id" "uuid", "actor_owner_email" "text", "removal_reason" "text", "command_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_communication_email_domain_removal"("target_organization_id" "uuid", "target_domain_id" "uuid", "actor_owner_email" "text", "removal_reason" "text", "command_idempotency_key" "text") IS 'Atomically clears provider authority and writes the immutable receipt after provider-confirmed domain cleanup.';



CREATE TABLE IF NOT EXISTS "public"."communication_email_senders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "domain_id" "uuid" NOT NULL,
    "email_address" "text" NOT NULL,
    "display_name" "text" NOT NULL,
    "provider" "text" DEFAULT 'brevo'::"text" NOT NULL,
    "provider_sender_id" bigint,
    "lifecycle_state" "text" DEFAULT 'pending_verification'::"text" NOT NULL,
    "assigned_user_id" "uuid",
    "is_organization_default" boolean DEFAULT false NOT NULL,
    "allows_manual" boolean DEFAULT true NOT NULL,
    "allows_automated" boolean DEFAULT false NOT NULL,
    "restriction_reason" "text",
    "provider_cleanup_error" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "communication_email_senders_display_name_check" CHECK ((("char_length"("btrim"("display_name")) >= 1) AND ("char_length"("btrim"("display_name")) <= 160))),
    CONSTRAINT "communication_email_senders_email_address_check" CHECK ((("email_address" = "lower"("btrim"("email_address"))) AND (("char_length"("email_address") >= 3) AND ("char_length"("email_address") <= 320)) AND (POSITION(('@'::"text") IN ("email_address")) > 1))),
    CONSTRAINT "communication_email_senders_lifecycle_state_check" CHECK (("lifecycle_state" = ANY (ARRAY['pending_verification'::"text", 'enabled'::"text", 'restricted'::"text", 'disabled'::"text", 'removal_pending'::"text", 'removed'::"text"]))),
    CONSTRAINT "communication_email_senders_provider_check" CHECK (("provider" = 'brevo'::"text")),
    CONSTRAINT "communication_email_senders_removed_cleanup_check" CHECK ((("lifecycle_state" <> 'removed'::"text") OR ("provider_cleanup_error" IS NULL))),
    CONSTRAINT "communication_email_senders_restriction_check" CHECK ((("lifecycle_state" = 'restricted'::"text") = ("restriction_reason" IS NOT NULL))),
    CONSTRAINT "communication_email_senders_restriction_reason_check" CHECK ((("restriction_reason" IS NULL) OR (("char_length"("btrim"("restriction_reason")) >= 1) AND ("char_length"("btrim"("restriction_reason")) <= 500)))),
    CONSTRAINT "communication_email_senders_use_check" CHECK (("allows_manual" OR "allows_automated" OR ("lifecycle_state" <> 'enabled'::"text")))
);


ALTER TABLE "public"."communication_email_senders" OWNER TO "postgres";


COMMENT ON TABLE "public"."communication_email_senders" IS 'Stored contractor sender identities. Eligibility also requires a verified healthy sending domain and active assignment.';



CREATE OR REPLACE FUNCTION "public"."finalize_communication_email_sender_create"("target_organization_id" "uuid", "target_sender_id" "uuid", "provider_sender_id" bigint, "actor_user_id" "uuid", "command_idempotency_key" "text") RETURNS "public"."communication_email_senders"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  selected_sender public.communication_email_senders;
begin
  if not exists (
    select 1 from public.communication_email_authority_events
    where organization_id = target_organization_id and target_id = target_sender_id
      and event_type = 'sender.create.started' and idempotency_key = command_idempotency_key
  ) then
    raise exception 'The sender creation claim was not found.' using errcode = 'invalid_parameter_value';
  end if;

  select * into strict selected_sender
  from public.communication_email_senders
  where organization_id = target_organization_id and id = target_sender_id
  for update;

  if selected_sender.lifecycle_state = 'enabled' then
    if selected_sender.provider_sender_id is distinct from provider_sender_id then
      raise exception 'The provider sender outcome conflicts with the stored receipt.'
        using errcode = 'unique_violation';
    end if;
    return selected_sender;
  end if;

  if selected_sender.lifecycle_state <> 'pending_verification' then
    raise exception 'The sender is not awaiting provider creation.' using errcode = 'check_violation';
  end if;

  if selected_sender.is_organization_default then
    update public.communication_email_senders
    set is_organization_default = false
    where organization_id = target_organization_id and id <> target_sender_id
      and lifecycle_state = 'enabled' and is_organization_default;
  end if;

  update public.communication_email_senders
  set provider_sender_id = finalize_communication_email_sender_create.provider_sender_id,
      lifecycle_state = 'enabled', provider_cleanup_error = null
  where organization_id = target_organization_id and id = target_sender_id
  returning * into selected_sender;

  insert into public.communication_email_authority_events (
    organization_id, actor_kind, actor_user_id, event_type, target_type, target_id,
    after_state, idempotency_key
  ) values (
    target_organization_id, 'contractor_user', actor_user_id, 'sender.create.completed',
    'sender', target_sender_id, to_jsonb(selected_sender), command_idempotency_key || ':complete'
  ) on conflict (organization_id, idempotency_key) do nothing;

  return selected_sender;
end;
$$;


ALTER FUNCTION "public"."finalize_communication_email_sender_create"("target_organization_id" "uuid", "target_sender_id" "uuid", "provider_sender_id" bigint, "actor_user_id" "uuid", "command_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_communication_email_sender_update"("target_organization_id" "uuid", "target_sender_id" "uuid", "actor_user_id" "uuid", "command_idempotency_key" "text") RETURNS "public"."communication_email_senders"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  selected_sender public.communication_email_senders;
  desired_state jsonb;
begin
  select after_state into strict desired_state
  from public.communication_email_authority_events
  where organization_id = target_organization_id and target_id = target_sender_id
    and event_type = 'sender.update.started' and idempotency_key = command_idempotency_key;

  select * into strict selected_sender from public.communication_email_senders
  where organization_id = target_organization_id and id = target_sender_id
  for update;

  if exists (
    select 1 from public.communication_email_authority_events
    where organization_id = target_organization_id and target_id = target_sender_id
      and event_type = 'sender.update.completed'
      and idempotency_key = command_idempotency_key || ':complete'
  ) then
    return selected_sender;
  end if;

  if (desired_state ->> 'is_organization_default')::boolean
    and (desired_state ->> 'enabled')::boolean then
    update public.communication_email_senders
    set is_organization_default = false
    where organization_id = target_organization_id and id <> target_sender_id
      and lifecycle_state = 'enabled' and is_organization_default;
  end if;

  update public.communication_email_senders
  set display_name = desired_state ->> 'display_name',
      assigned_user_id = nullif(desired_state ->> 'assigned_user_id', '')::uuid,
      is_organization_default = (desired_state ->> 'is_organization_default')::boolean,
      allows_manual = (desired_state ->> 'allows_manual')::boolean,
      allows_automated = (desired_state ->> 'allows_automated')::boolean,
      lifecycle_state = case when (desired_state ->> 'enabled')::boolean then 'enabled' else 'disabled' end
  where organization_id = target_organization_id and id = target_sender_id
  returning * into selected_sender;

  insert into public.communication_email_authority_events (
    organization_id, actor_kind, actor_user_id, event_type, target_type, target_id,
    after_state, idempotency_key
  ) values (
    target_organization_id, 'contractor_user', actor_user_id, 'sender.update.completed', 'sender',
    target_sender_id, to_jsonb(selected_sender), command_idempotency_key || ':complete'
  );

  return selected_sender;
end;
$$;


ALTER FUNCTION "public"."finalize_communication_email_sender_update"("target_organization_id" "uuid", "target_sender_id" "uuid", "actor_user_id" "uuid", "command_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_communication_forward_event"("target_forward_event_id" "uuid", "target_claim_token" "uuid", "target_outcome" "text", "target_provider_message_id" "text" DEFAULT NULL::"text", "target_failure_code" "text" DEFAULT NULL::"text", "target_failure_message" "text" DEFAULT NULL::"text") RETURNS "public"."communication_forward_events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  claimed_event public.communication_forward_events;
  next_available_at timestamptz;
begin
  if target_outcome not in ('submitted', 'retry', 'submission_unknown', 'cancelled') then
    raise exception 'The forward outcome is invalid.' using errcode = 'check_violation';
  end if;

  select * into claimed_event from public.communication_forward_events where id = target_forward_event_id
  for update;
  if not found then
    raise exception 'The forward event does not exist.' using errcode = 'no_data_found';
  end if;

  if claimed_event.status <> 'claimed' then
    if claimed_event.finalized_claim_token is distinct from target_claim_token then
      raise exception 'The forward claim is no longer current.' using errcode = 'object_not_in_prerequisite_state';
    end if;
    return claimed_event;
  end if;

  if claimed_event.claim_token is distinct from target_claim_token then
    raise exception 'The forward claim token is invalid.' using errcode = 'insufficient_privilege';
  end if;

  if target_outcome = 'submitted' then
    if nullif(trim(target_provider_message_id), '') is null then
      raise exception 'A submitted forward requires a provider message identifier.' using errcode = 'not_null_violation';
    end if;
    update public.communication_forward_events
    set status = 'submitted', provider_message_id = trim(target_provider_message_id), accepted_at = now(),
      claimed_at = null, claim_token = null, finalized_claim_token = target_claim_token,
      failure_code = null, failure_message = null
    where id = claimed_event.id
    returning * into claimed_event;

  elsif target_outcome = 'retry' then
    next_available_at := case claimed_event.attempt_count
      when 1 then now() + interval '5 minutes'
      when 2 then now() + interval '30 minutes'
      when 3 then now() + interval '2 hours'
      when 4 then now() + interval '8 hours'
      when 5 then now() + interval '24 hours'
      else 'infinity'::timestamptz
    end;
    update public.communication_forward_events
    set status = 'failed', available_at = next_available_at, claimed_at = null, claim_token = null,
      finalized_claim_token = target_claim_token,
      failure_code = nullif(trim(target_failure_code), ''),
      failure_message = nullif(trim(target_failure_message), '')
    where id = claimed_event.id
    returning * into claimed_event;

  elsif target_outcome = 'submission_unknown' then
    update public.communication_forward_events
    set status = 'submission_unknown', claimed_at = null, claim_token = null,
      finalized_claim_token = target_claim_token,
      failure_code = nullif(trim(target_failure_code), ''),
      failure_message = nullif(trim(target_failure_message), '')
    where id = claimed_event.id
    returning * into claimed_event;

  else
    update public.communication_forward_events
    set status = 'cancelled', claimed_at = null, claim_token = null,
      finalized_claim_token = target_claim_token,
      failure_code = nullif(trim(target_failure_code), ''),
      failure_message = nullif(trim(target_failure_message), '')
    where id = claimed_event.id
    returning * into claimed_event;
  end if;

  return claimed_event;
end;
$$;


ALTER FUNCTION "public"."finalize_communication_forward_event"("target_forward_event_id" "uuid", "target_claim_token" "uuid", "target_outcome" "text", "target_provider_message_id" "text", "target_failure_code" "text", "target_failure_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_communication_inbound_attachment_import"("target_attachment_id" "uuid", "target_claim_token" "uuid", "target_status" "text", "target_object_key" "text" DEFAULT NULL::"text", "target_failure_reason" "text" DEFAULT NULL::"text", "target_byte_size" bigint DEFAULT NULL::bigint) RETURNS "public"."communication_inbound_attachments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_row public.communication_inbound_attachments;
begin
  if target_status not in ('pending_scan', 'blocked_type', 'blocked_size', 'import_failed') then
    raise exception 'The inbound attachment import outcome is not a valid target status.'
      using errcode = 'check_violation';
  end if;

  update public.communication_inbound_attachments
  set status = target_status,
    object_key = case when target_status = 'pending_scan' then target_object_key else object_key end,
    byte_size = coalesce(target_byte_size, byte_size),
    failure_reason = target_failure_reason,
    provider_download_token = null, claimed_at = null, claim_token = null
  where id = target_attachment_id and claim_token = target_claim_token
  returning * into updated_row;

  if updated_row.id is null then
    select * into updated_row from public.communication_inbound_attachments
    where id = target_attachment_id;
  end if;

  return updated_row;
end;
$$;


ALTER FUNCTION "public"."finalize_communication_inbound_attachment_import"("target_attachment_id" "uuid", "target_claim_token" "uuid", "target_status" "text", "target_object_key" "text", "target_failure_reason" "text", "target_byte_size" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_communication_outbox_event"("target_outbox_event_id" "uuid", "target_claim_token" "uuid", "target_outcome" "text", "target_provider_message_id" "text" DEFAULT NULL::"text", "target_failure_code" "text" DEFAULT NULL::"text", "target_failure_message" "text" DEFAULT NULL::"text") RETURNS TABLE("outbox_status" "text", "intent_status" "text", "attempt_count" integer, "available_at" timestamp with time zone, "usage_recorded" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  claimed_event public.communication_outbox_events;
  reservation public.communication_email_capacity_reservations;
  next_available_at timestamptz;
begin
  if target_outcome not in ('submitted', 'retry', 'submission_unknown', 'cancelled') then
    raise exception 'The communication outcome is invalid.' using errcode = 'check_violation';
  end if;
  select * into claimed_event from public.communication_outbox_events where id = target_outbox_event_id for update;
  if not found then raise exception 'The communication outbox event does not exist.' using errcode = 'no_data_found'; end if;
  if claimed_event.status <> 'processing' then
    if claimed_event.finalized_claim_token is distinct from target_claim_token then
      raise exception 'The communication claim is no longer current.' using errcode = 'object_not_in_prerequisite_state';
    end if;
    return query select claimed_event.status, intent.status, claimed_event.attempt_count, claimed_event.available_at,
      exists (select 1 from public.communication_email_usage_events usage where usage.delivery_intent_id = claimed_event.delivery_intent_id)
    from public.communication_delivery_intents intent where intent.id = claimed_event.delivery_intent_id;
    return;
  end if;
  if claimed_event.claim_token is distinct from target_claim_token then
    raise exception 'The communication claim token is invalid.' using errcode = 'insufficient_privilege';
  end if;
  select * into reservation from public.communication_email_capacity_reservations
  where delivery_intent_id = claimed_event.delivery_intent_id for update;

  if target_outcome = 'submitted' then
    if nullif(trim(target_provider_message_id), '') is null then
      raise exception 'A submitted email requires a provider message identifier.' using errcode = 'not_null_violation';
    end if;
    update public.communication_delivery_intents set status = 'submitted', provider_message_id = trim(target_provider_message_id),
      accepted_at = now(), failure_code = null, failure_message = null where id = claimed_event.delivery_intent_id;
    if reservation.id is null then
      insert into public.communication_email_usage_events (organization_id, delivery_intent_id, recipient_count)
      values (claimed_event.organization_id, claimed_event.delivery_intent_id, 1) on conflict (delivery_intent_id) do nothing;
    else
      update public.communication_email_capacity_reservations set reservation_state = 'accepted', settled_at = now()
      where id = reservation.id;
      insert into public.communication_email_usage_events (
        organization_id, delivery_intent_id, recipient_count, allowance_period_id, allowance_class
      ) values (
        claimed_event.organization_id, claimed_event.delivery_intent_id, reservation.recipient_count,
        reservation.allowance_period_id, reservation.allowance_class
      ) on conflict (delivery_intent_id) do nothing;
    end if;
    update public.communication_outbox_events set status = 'submitted', claimed_at = null, claim_token = null,
      finalized_claim_token = target_claim_token, last_error = null where id = claimed_event.id;
  elsif target_outcome = 'retry' then
    next_available_at := case claimed_event.attempt_count when 1 then now() + interval '5 minutes'
      when 2 then now() + interval '30 minutes' when 3 then now() + interval '2 hours'
      when 4 then now() + interval '8 hours' when 5 then now() + interval '24 hours' else 'infinity'::timestamptz end;
    update public.communication_delivery_intents set status = 'failed', provider_message_id = null, accepted_at = null,
      failure_code = nullif(trim(target_failure_code), ''), failure_message = nullif(trim(target_failure_message), '')
    where id = claimed_event.delivery_intent_id;
    if reservation.id is not null then update public.communication_email_capacity_reservations
      set reservation_state = 'released', settled_at = now() where id = reservation.id; end if;
    update public.communication_outbox_events set status = 'failed', available_at = next_available_at, claimed_at = null,
      claim_token = null, finalized_claim_token = target_claim_token, last_error = nullif(trim(target_failure_message), '')
    where id = claimed_event.id;
  elsif target_outcome = 'submission_unknown' then
    update public.communication_delivery_intents set status = 'submission_unknown', provider_message_id = null, accepted_at = null,
      failure_code = nullif(trim(target_failure_code), ''), failure_message = nullif(trim(target_failure_message), '')
    where id = claimed_event.delivery_intent_id;
    if reservation.id is not null then update public.communication_email_capacity_reservations
      set reservation_state = 'submission_unknown', settled_at = now() where id = reservation.id; end if;
    update public.communication_outbox_events set status = 'submission_unknown', claimed_at = null, claim_token = null,
      finalized_claim_token = target_claim_token, last_error = nullif(trim(target_failure_message), '') where id = claimed_event.id;
  else
    update public.communication_delivery_intents set status = 'cancelled', provider_message_id = null, accepted_at = null,
      failure_code = nullif(trim(target_failure_code), ''), failure_message = nullif(trim(target_failure_message), '')
    where id = claimed_event.delivery_intent_id;
    if reservation.id is not null then update public.communication_email_capacity_reservations
      set reservation_state = 'released', settled_at = now() where id = reservation.id; end if;
    update public.communication_outbox_events set status = 'cancelled', claimed_at = null, claim_token = null,
      finalized_claim_token = target_claim_token, last_error = nullif(trim(target_failure_message), '') where id = claimed_event.id;
  end if;
  return query select event.status, intent.status, event.attempt_count, event.available_at,
    exists (select 1 from public.communication_email_usage_events usage where usage.delivery_intent_id = event.delivery_intent_id)
  from public.communication_outbox_events event join public.communication_delivery_intents intent on intent.id = event.delivery_intent_id
  where event.id = claimed_event.id;
end;
$$;


ALTER FUNCTION "public"."finalize_communication_outbox_event"("target_outbox_event_id" "uuid", "target_claim_token" "uuid", "target_outcome" "text", "target_provider_message_id" "text", "target_failure_code" "text", "target_failure_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_communication_sms_outbox_event"("target_outbox_event_id" "uuid", "target_claim_token" "uuid", "target_outcome" "text", "target_provider_message_id" "text" DEFAULT NULL::"text", "target_failure_code" "text" DEFAULT NULL::"text", "target_failure_message" "text" DEFAULT NULL::"text") RETURNS TABLE("outbox_status" "text", "intent_status" "text", "attempt_count" integer, "available_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  claimed_event public.communication_outbox_events;
  next_available_at timestamptz;
begin
  if target_outcome not in ('submitted', 'retry', 'submission_unknown', 'cancelled') then
    raise exception 'The SMS outcome is invalid.' using errcode = 'check_violation';
  end if;

  select * into claimed_event
  from public.communication_outbox_events
  where id = target_outbox_event_id
  for update;

  if not found then
    raise exception 'The SMS outbox event does not exist.' using errcode = 'no_data_found';
  end if;
  if claimed_event.channel <> 'sms' then
    raise exception 'This is not an SMS outbox event.' using errcode = 'check_violation';
  end if;

  if claimed_event.status <> 'processing' then
    if claimed_event.finalized_claim_token is distinct from target_claim_token then
      raise exception 'The SMS claim is no longer current.' using errcode = 'object_not_in_prerequisite_state';
    end if;
    return query
    select claimed_event.status, intent.status, claimed_event.attempt_count, claimed_event.available_at
    from public.communication_delivery_intents intent
    where intent.id = claimed_event.delivery_intent_id;
    return;
  end if;

  if claimed_event.claim_token is distinct from target_claim_token then
    raise exception 'The SMS claim token is invalid.' using errcode = 'insufficient_privilege';
  end if;

  if target_outcome = 'submitted' then
    if nullif(trim(target_provider_message_id), '') is null then
      raise exception 'A submitted SMS requires a provider message identifier.' using errcode = 'not_null_violation';
    end if;

    update public.communication_delivery_intents
    set status = 'submitted', provider_message_id = trim(target_provider_message_id), accepted_at = now(),
      failure_code = null, failure_message = null
    where id = claimed_event.delivery_intent_id;

    update public.communication_sms_submission_attempts
    set outcome = 'accepted', provider_message_id = trim(target_provider_message_id), finished_at = now()
    where delivery_intent_id = claimed_event.delivery_intent_id and claim_token = target_claim_token;

    update public.communication_outbox_events
    set status = 'submitted', claimed_at = null, claim_token = null,
      finalized_claim_token = target_claim_token, last_error = null
    where id = claimed_event.id;

  elsif target_outcome = 'retry' then
    next_available_at := case claimed_event.attempt_count
      when 1 then now() + interval '5 minutes'
      when 2 then now() + interval '30 minutes'
      when 3 then now() + interval '2 hours'
      when 4 then now() + interval '8 hours'
      when 5 then now() + interval '24 hours'
      else 'infinity'::timestamptz
    end;

    update public.communication_delivery_intents
    set status = 'failed', provider_message_id = null, accepted_at = null,
      failure_code = nullif(trim(target_failure_code), ''),
      failure_message = nullif(trim(target_failure_message), '')
    where id = claimed_event.delivery_intent_id;

    update public.communication_sms_submission_attempts
    set outcome = 'rejected', error_code = nullif(trim(target_failure_code), ''), finished_at = now()
    where delivery_intent_id = claimed_event.delivery_intent_id and claim_token = target_claim_token;

    update public.communication_outbox_events
    set status = 'failed', available_at = next_available_at, claimed_at = null, claim_token = null,
      finalized_claim_token = target_claim_token, last_error = nullif(trim(target_failure_message), '')
    where id = claimed_event.id;

  elsif target_outcome = 'cancelled' then
    perform private.communication_sms_release_reservation(claimed_event.delivery_intent_id);

    update public.communication_delivery_intents
    set status = 'cancelled', provider_message_id = null, accepted_at = null,
      failure_code = nullif(trim(target_failure_code), ''),
      failure_message = nullif(trim(target_failure_message), '')
    where id = claimed_event.delivery_intent_id;

    update public.communication_sms_submission_attempts
    set outcome = 'rejected', error_code = nullif(trim(target_failure_code), ''), finished_at = now()
    where delivery_intent_id = claimed_event.delivery_intent_id and claim_token = target_claim_token;

    update public.communication_outbox_events
    set status = 'cancelled', claimed_at = null, claim_token = null,
      finalized_claim_token = target_claim_token, last_error = nullif(trim(target_failure_message), '')
    where id = claimed_event.id;

  else
    update public.communication_delivery_intents
    set status = 'submission_unknown', provider_message_id = nullif(trim(target_provider_message_id), ''),
      accepted_at = null, failure_code = nullif(trim(target_failure_code), ''),
      failure_message = nullif(trim(target_failure_message), '')
    where id = claimed_event.delivery_intent_id;

    update public.communication_sms_submission_attempts
    set outcome = 'submission_unknown', error_code = nullif(trim(target_failure_code), ''),
      provider_message_id = nullif(trim(target_provider_message_id), ''), finished_at = now()
    where delivery_intent_id = claimed_event.delivery_intent_id and claim_token = target_claim_token;

    update public.communication_sms_credit_reservations
    set state = 'submission_unknown', settled_at = now()
    where delivery_intent_id = claimed_event.delivery_intent_id and state = 'reserved';

    insert into public.communication_sms_reconciliation_items (
      organization_id, delivery_intent_id, provider_message_id, reason, last_error
    ) values (
      claimed_event.organization_id, claimed_event.delivery_intent_id,
      nullif(trim(target_provider_message_id), ''), 'submission_unknown',
      nullif(trim(target_failure_message), '')
    )
    on conflict (delivery_intent_id, reason) where status in ('open', 'processing', 'failed')
      and delivery_intent_id is not null do nothing;

    update public.communication_outbox_events
    set status = 'submission_unknown', claimed_at = null, claim_token = null,
      finalized_claim_token = target_claim_token, last_error = nullif(trim(target_failure_message), '')
    where id = claimed_event.id;
  end if;

  return query
  select event.status, intent.status, event.attempt_count, event.available_at
  from public.communication_outbox_events event
  join public.communication_delivery_intents intent on intent.id = event.delivery_intent_id
  where event.id = claimed_event.id;
end;
$$;


ALTER FUNCTION "public"."finalize_communication_sms_outbox_event"("target_outbox_event_id" "uuid", "target_claim_token" "uuid", "target_outcome" "text", "target_provider_message_id" "text", "target_failure_code" "text", "target_failure_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_organization_geocode"("p_organization_id" "uuid", "p_address_line1" "text", "p_city" "text", "p_region" "text", "p_postal_code" "text", "p_status" "text", "p_latitude" numeric, "p_longitude" numeric) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_count integer;
begin
  if p_status not in ('succeeded', 'failed') then
    raise exception 'finalize_organization_geocode: p_status must be succeeded or failed, got %', p_status;
  end if;

  update public.organization_settings as s
  set latitude = case when p_status = 'succeeded' then p_latitude else null end,
      longitude = case when p_status = 'succeeded' then p_longitude else null end,
      location_geocode_status = p_status
  where s.organization_id = p_organization_id
    and s.location_geocode_status = 'pending'
    and s.address_line1 is not distinct from p_address_line1
    and s.city is not distinct from p_city
    and s.region is not distinct from p_region
    and s.postal_code is not distinct from p_postal_code;

  get diagnostics updated_count = row_count;
  return updated_count > 0;
end;
$$;


ALTER FUNCTION "public"."finalize_organization_geocode"("p_organization_id" "uuid", "p_address_line1" "text", "p_city" "text", "p_region" "text", "p_postal_code" "text", "p_status" "text", "p_latitude" numeric, "p_longitude" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_property_geocode"("p_id" "uuid", "p_address_line1" "text", "p_city" "text", "p_state_region" "text", "p_postal_code" "text", "p_status" "text", "p_latitude" numeric, "p_longitude" numeric) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_count integer;
begin
  if p_status not in ('succeeded', 'failed') then
    raise exception 'finalize_property_geocode: p_status must be succeeded or failed, got %', p_status;
  end if;

  update public.properties as p
  set latitude  = case when p_status = 'succeeded' then p_latitude else null end,
      longitude = case when p_status = 'succeeded' then p_longitude else null end,
      geocode_status = p_status
  where p.id = p_id
    and p.geocode_status = 'pending'
    and p.address_line1 is not distinct from p_address_line1
    and p.city is not distinct from p_city
    and p.state_region is not distinct from p_state_region
    and p.postal_code is not distinct from p_postal_code;

  get diagnostics updated_count = row_count;
  return updated_count > 0;
end;
$$;


