      and job.price_basis = 'per_visit'
      and not exists (
        select 1 from public.invoice_sources as claim
        where claim.organization_id = visit.organization_id
          and claim.visit_id = visit.id and claim.source_kind = 'visit'
      )
    union all
    select 'period', reminder.due_on, reminder.job_id, job.subtotal_minor
    from public.job_invoice_reminders as reminder
    join public.jobs as job
      on job.organization_id = reminder.organization_id and job.id = reminder.job_id
    where reminder.organization_id = target_organization_id
      and reminder.status = 'pending'
      and reminder.due_on <= today
      and reminder.reminder_kind in ('monthly_last_day', 'custom_date')
      and job.price_basis = 'fixed_per_period'
    union all
    select 'job', (job.closed_at at time zone zone)::date, job.id, job.total_minor
    from public.jobs as job
    where job.organization_id = target_organization_id
      and job.status = 'closed'
      and job.closed_at >= window_start and job.closed_at < window_end
      and job.price_basis = 'job_total'
      and not exists (
        select 1 from public.invoice_sources as claim
        where claim.organization_id = job.organization_id and claim.job_id = job.id
      )
  )
  select coalesce(sum(unit.uninvoiced_minor), 0)::bigint,
    count(*)::bigint,
    count(*) filter (where unit.unit_kind = 'visit'),
    count(*) filter (where unit.unit_kind = 'period'),
    count(*) filter (where unit.unit_kind = 'job'),
    count(distinct unit.job_id)::bigint
  from unit
  where unit.work_date >= report_from and unit.work_date < report_to;
end;
$$;


ALTER FUNCTION "public"."financial_uninvoiced_work_summary"("target_organization_id" "uuid", "report_from" "date", "report_to" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."financial_uninvoiced_work_summary"("target_organization_id" "uuid", "report_from" "date", "report_to" "date") IS 'Whole-range uninvoiced-work totals over the same unit predicate as financial_uninvoiced_work_page.';



CREATE OR REPLACE FUNCTION "public"."find_team_invitation_auth_receipt"("target_invitation_id" "uuid") RETURNS TABLE("user_id" "uuid", "identity_invitation_id" "text", "password_set_invitation_id" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    auth_user.id,
    auth_user.raw_app_meta_data ->> 'team_invitation_identity_for',
    auth_user.raw_app_meta_data ->> 'invitation_password_set_for'
  from public.organization_member_invitations as invitation
  join auth.users as auth_user
    on (
      invitation.invited_user_id is not null
      and auth_user.id = invitation.invited_user_id
    ) or (
      invitation.invited_user_id is null
      and lower(auth_user.email) = lower(invitation.invited_email)
    )
  where invitation.id = target_invitation_id
  order by (auth_user.id = invitation.invited_user_id) desc, auth_user.id
  limit 1;
$$;


ALTER FUNCTION "public"."find_team_invitation_auth_receipt"("target_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."freeze_quote_version"("target_quote_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  draft_row public.quote_versions;
  default_addon_ids uuid[];
  next_version_number integer;
  calculated jsonb;
  canonical jsonb;
  frozen_hash text;
begin
  select * into quote_row from public.quotes where id = target_quote_id for update;
  if quote_row.id is null or not private.member_has_permission(
    quote_row.organization_id, (select auth.uid()), 'quotes.edit'
  ) then
    raise exception 'You do not have access to publish this quote.' using errcode = 'insufficient_privilege';
  end if;
  if quote_row.status <> 'draft' then
    raise exception 'Only a draft quote can be frozen.' using errcode = 'check_violation';
  end if;

  select * into draft_row from public.quote_versions
  where organization_id = quote_row.organization_id and quote_id = quote_row.id and status = 'draft'
  for update;
  if draft_row.id is null then
    raise exception 'This quote has no draft to freeze.' using errcode = 'check_violation';
  end if;
  if expected_revision is distinct from draft_row.revision then
    raise exception 'Someone else changed this quote while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  select coalesce(array_agg(id order by position, id), '{}'::uuid[])
  into default_addon_ids
  from public.quote_version_lines
  where organization_id = quote_row.organization_id and quote_version_id = draft_row.id
    and line_kind = 'priced' and selection_kind = 'optional' and is_recommended;

  calculated := private.calculate_quote_version(draft_row.id, default_addon_ids);
  select coalesce(max(version_number), 0) + 1 into next_version_number
  from public.quote_versions
  where organization_id = quote_row.organization_id and quote_id = quote_row.id and status = 'published';

  canonical := jsonb_build_object(
    'quote', jsonb_build_object('number', quote_row.quote_number, 'title', quote_row.title),
    'version', to_jsonb(draft_row) - array[
      'id','organization_id','quote_id','revision','status','version_number','created_by','created_at',
      'updated_at','published_at','document_hash','calculation','subtotal_minor','discount_minor','tax_minor',
      'total_minor','deposit_required_minor','cost_minor','profit_minor','margin_basis_points'
    ],
    'lines', (select coalesce(jsonb_agg(to_jsonb(line_row) - array[
      'id','organization_id','quote_id','quote_version_id','source_catalog_item_id','unit_cost_minor',
      'line_cost_total_minor','created_at','updated_at'
    ] order by position, id), '[]'::jsonb)
      from public.quote_version_lines line_row where quote_version_id = draft_row.id),
    'schedule_items', (select coalesce(jsonb_agg(to_jsonb(item_row) - array[
      'id','organization_id','quote_id','quote_version_id','created_at','updated_at'
    ] order by position, id), '[]'::jsonb)
      from public.quote_version_schedule_items item_row where quote_version_id = draft_row.id),
    'attachments', (select coalesce(jsonb_agg(to_jsonb(attachment_row) - array[
      'id','organization_id','quote_id','quote_version_id','created_at'
    ] order by position, id), '[]'::jsonb)
      from public.quote_version_attachments attachment_row
      where quote_version_id = draft_row.id and customer_visible),
    'calculation', calculated
  );
  frozen_hash := encode(extensions.digest(canonical::text, 'sha256'), 'hex');

  update public.quote_versions set
    status = 'published', version_number = next_version_number,
    subtotal_minor = (calculated ->> 'subtotal_minor')::bigint,
    discount_minor = (calculated ->> 'discount_minor')::bigint,
    tax_minor = (calculated ->> 'tax_minor')::bigint,
    total_minor = (calculated ->> 'total_minor')::bigint,
    deposit_required_minor = (calculated ->> 'deposit_required_minor')::bigint,
    cost_minor = (calculated ->> 'cost_minor')::bigint,
    profit_minor = (calculated ->> 'profit_minor')::bigint,
    margin_basis_points = (calculated ->> 'margin_basis_points')::bigint,
    calculation = calculated, document_hash = frozen_hash, published_at = now()
  where id = draft_row.id;

  update public.quotes set draft_version_id = null, current_published_version_id = draft_row.id
  where id = quote_row.id;

  return jsonb_build_object(
    'quote_id', quote_row.id, 'quote_version_id', draft_row.id,
    'version_number', next_version_number, 'document_hash', frozen_hash,
    'calculation', calculated
  );
end;
$$;


ALTER FUNCTION "public"."freeze_quote_version"("target_quote_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_communication_email_blocked_addresses"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with blocked as (
    select s.*
    from public.communication_email_suppressions s
    where s.organization_id = p_organization_id and s.released_at is null
    order by s.created_at desc, s.id desc
    limit 200
  )
  select jsonb_build_object(
    'blocked', coalesce((
      select jsonb_agg(jsonb_build_object(
        'suppression_id', b.id,
        'recipient_email', b.recipient_email,
        'reason', b.reason,
        'source', b.source,
        'created_at', b.created_at,
        'client_id', intent.client_id,
        'client_display_name', cl.display_name,
        'open_request', (
          select jsonb_build_object(
            'id', r.id,
            'request_reason', r.request_reason,
            'requested_by_email', r.requested_by_email,
            'created_at', r.created_at
          )
          from public.communication_email_suppression_removal_requests r
          where r.suppression_id = b.id and r.status = 'pending'
          limit 1
        )
      ) order by b.created_at desc, b.id desc)
      from blocked b
      left join public.communication_delivery_intents intent on intent.id = b.first_delivery_intent_id
      left join public.clients cl on cl.id = intent.client_id
    ), '[]'::jsonb),
    'blocked_total', (
      select count(*)
      from public.communication_email_suppressions s
      where s.organization_id = p_organization_id and s.released_at is null
    ),
    'recently_cleared', coalesce((
      select jsonb_agg(jsonb_build_object(
        'suppression_id', s.id,
        'recipient_email', s.recipient_email,
        'reason', s.reason,
        'released_at', s.released_at,
        'released_by_kind', s.released_by_kind,
        'released_reason', s.released_reason
      ) order by s.released_at desc, s.id desc)
      from (
        select *
        from public.communication_email_suppressions s2
        where s2.organization_id = p_organization_id and s2.released_at is not null
        order by s2.released_at desc, s2.id desc
        limit 25
      ) s
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."get_communication_email_blocked_addresses"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_communication_email_reputation"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
  select jsonb_build_object(
    'organization_id', p_organization_id,
    'measured_at', now(),
    'metrics', coalesce((
      select jsonb_agg(to_jsonb(m) order by m.signal, m.window_key)
      from private.communication_email_reputation_metrics(p_organization_id, now()) m
    ), '[]'::jsonb),
    'overrides', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id, 'signal', t.signal, 'window_key', t.window_key,
        'warn_rate', t.warn_rate, 'pause_rate', t.pause_rate,
        'min_sample_recipients', t.min_sample_recipients, 'min_event_count', t.min_event_count,
        'reason', t.reason, 'actor_owner_email', t.actor_owner_email,
        'effective_from', t.effective_from
      ) order by t.signal, t.window_key)
      from public.communication_email_reputation_thresholds t
      where t.scope = 'organization' and t.organization_id = p_organization_id and t.effective_to is null
    ), '[]'::jsonb),
    'reputation_pause', (
      select jsonb_build_object(
        'id', p.id, 'reason', p.reason, 'engaged_at', p.engaged_at, 'evidence', p.evidence
      )
      from public.communication_email_sending_pauses p
      where p.scope = 'organization' and p.organization_id = p_organization_id
        and p.source = 'auto_reputation' and p.released_at is null
      limit 1
    ),
    'state', (
      select jsonb_build_object(
        'worst_status', s.worst_status, 'evaluated_at', s.evaluated_at, 'last_breach_at', s.last_breach_at
      )
      from public.communication_email_reputation_state s
      where s.organization_id = p_organization_id
    )
  );
$$;


ALTER FUNCTION "public"."get_communication_email_reputation"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_communication_email_reputation_overview"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'platform_thresholds', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id, 'signal', t.signal, 'window_key', t.window_key, 'window_hours', t.window_hours,
        'warn_rate', t.warn_rate, 'pause_rate', t.pause_rate,
        'min_sample_recipients', t.min_sample_recipients, 'min_event_count', t.min_event_count,
        'reason', t.reason, 'actor_owner_email', t.actor_owner_email, 'effective_from', t.effective_from
      ) order by t.signal, t.window_key)
      from public.communication_email_reputation_thresholds t
      where t.scope = 'platform' and t.effective_to is null
    ), '[]'::jsonb),
    'attention_total', (
      select count(*)
      from public.communication_email_reputation_state s
      where s.worst_status <> 'ok'
    ),
    'attention_limit', 100,
    'attention', coalesce((
      select jsonb_agg(entry.payload order by entry.rank)
      from (
        select
          row_number() over (
            order by case s.worst_status when 'pause' then 0 else 1 end, s.evaluated_at desc
          ) as rank,
          jsonb_build_object(
            'organization_id', s.organization_id, 'organization_name', o.name,
            'worst_status', s.worst_status, 'evaluated_at', s.evaluated_at,
            'last_breach_at', s.last_breach_at, 'metrics', s.metrics,
            'reputation_pause_id', (
              select p.id from public.communication_email_sending_pauses p
              where p.scope = 'organization' and p.organization_id = s.organization_id
                and p.source = 'auto_reputation' and p.released_at is null
              limit 1
            )
          ) as payload
        from public.communication_email_reputation_state s
        join public.organizations o on o.id = s.organization_id
        where s.worst_status <> 'ok'
        order by case s.worst_status when 'pause' then 0 else 1 end, s.evaluated_at desc
        limit 100
      ) entry
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."get_communication_email_reputation_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_communication_email_sending_capacity_overview"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'warmup_stages', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', stage.id, 'stage_key', stage.stage_key, 'daily_ceiling', stage.daily_ceiling,
        'reason', stage.reason, 'actor_owner_email', stage.actor_owner_email,
        'effective_from', stage.effective_from
      ) order by array_position(
        array['days_1_3', 'days_4_7', 'days_8_14']::text[], stage.stage_key))
      from public.communication_email_warmup_stages stage
      where stage.scope = 'platform' and stage.effective_to is null
    ), '[]'::jsonb),
    'short_term', (
      select jsonb_build_object(
        'id', settings.id,
        'window_minutes', settings.short_term_window_minutes,
        'max_recipients', settings.short_term_max_recipients,
        'reason', settings.reason, 'actor_owner_email', settings.actor_owner_email,
        'effective_from', settings.effective_from
      )
      from public.communication_email_platform_sending_settings settings
      where settings.effective_to is null
    ),
    'provider_capacity', (
      select jsonb_build_object(
        'capacity', settings.provider_period_capacity,
        'reserve_percent', settings.reserve_percent,
        'reserve_recipients', case
          when settings.provider_period_capacity is null then null
          else ceil(settings.provider_period_capacity::numeric * settings.reserve_percent / 100.0)::integer
        end,
        'reason', settings.reason,
        'actor_owner_email', settings.actor_owner_email,
        'effective_from', settings.effective_from,
        'period_start', date_trunc('month', now() at time zone 'UTC') at time zone 'UTC',
        'period_end', (date_trunc('month', now() at time zone 'UTC') + interval '1 month') at time zone 'UTC',
        'period_accepted', coalesce((
          select usage.accepted_recipients
          from public.communication_email_platform_period_usage usage
          where usage.period_start = date_trunc('month', now() at time zone 'UTC') at time zone 'UTC'
        ), 0),
        'period_reserved', coalesce((
          select sum(reservation.recipient_count)
          from public.communication_email_capacity_reservations reservation
          where reservation.reservation_state in ('reserved', 'submission_unknown')
            and reservation.reserved_at >= date_trunc('month', now() at time zone 'UTC') at time zone 'UTC'
        ), 0)
      )
      from public.communication_email_platform_sending_settings settings
      where settings.effective_to is null
    ),
    'domains_warming_up', (
      select count(*)
      from public.communication_email_domains domain
      where domain.purpose = 'sending'
        and domain.lifecycle_state = 'verified'
        and coalesce(domain.warmup_started_at, domain.verified_at) is not null
        and coalesce(domain.warmup_started_at, domain.verified_at) > now() - interval '14 days'
    )
  );
$$;


ALTER FUNCTION "public"."get_communication_email_sending_capacity_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_communication_email_sending_health"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'platform_pause', (
      select jsonb_build_object(
        'id', p.id, 'reason', p.reason,
        'engaged_by', p.engaged_by_owner_email, 'engaged_at', p.engaged_at
      )
      from public.communication_email_sending_pauses p
      where p.scope = 'platform' and p.released_at is null
      order by p.engaged_at desc
      limit 1
    ),
    'organization_pauses', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id, 'organization_id', p.organization_id, 'organization_name', o.name,
        'reason', p.reason, 'engaged_by', p.engaged_by_owner_email, 'engaged_at', p.engaged_at,
        'source', p.source, 'applies_to', p.applies_to, 'evidence', p.evidence
      ) order by p.engaged_at desc)
      from public.communication_email_sending_pauses p
      join public.organizations o on o.id = p.organization_id
      where p.scope = 'organization' and p.released_at is null
    ), '[]'::jsonb),
    'held_email_count', (
      select count(*)
      from public.communication_outbox_events e
      join public.communication_delivery_intents i on i.id = e.delivery_intent_id
      where e.status in ('pending', 'failed')
        and i.failure_code in ('sending_paused_platform', 'sending_paused_organization',
          'sending_paused_reputation')
    ),
    'queued_email_count', (
      select count(*)
      from public.communication_outbox_events e
      where e.status in ('pending', 'failed')
    )
  );
$$;


ALTER FUNCTION "public"."get_communication_email_sending_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_communication_email_suppression_removal_queue"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'pending', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id,
        'suppression_id', r.suppression_id,
        'organization_id', r.organization_id,
        'organization_name', o.name,
        'recipient_email', r.recipient_email,
        'suppression_reason', r.suppression_reason,
        'requested_by_email', r.requested_by_email,
        'request_reason', r.request_reason,
        'request_evidence', r.request_evidence,
        'created_at', r.created_at,
        'suppression_created_at', s.created_at
      ) order by r.created_at, r.id)
      from (
        select *
        from public.communication_email_suppression_removal_requests
        where status = 'pending'
        order by created_at, id
        limit 100
      ) r
      join public.organizations o on o.id = r.organization_id
      left join public.communication_email_suppressions s on s.id = r.suppression_id
    ), '[]'::jsonb),
    'pending_total', (
      select count(*)
      from public.communication_email_suppression_removal_requests
      where status = 'pending'
    ),
    'recently_decided', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id,
        'organization_name', o.name,
        'recipient_email', r.recipient_email,
        'status', r.status,
        'decided_by_email', r.decided_by_email,
        'decided_at', r.decided_at,
        'decision_note', r.decision_note
      ) order by r.decided_at desc, r.id desc)
      from (
        select *
        from public.communication_email_suppression_removal_requests
        where status in ('approved', 'denied')
          and decided_by_kind = 'platform_owner'
        order by decided_at desc, id desc
        limit 20
      ) r
      join public.organizations o on o.id = r.organization_id
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."get_communication_email_suppression_removal_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_communication_email_worker_health"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'net'
    AS $$
  select jsonb_build_object(
    'worker_name', 'communications-email-outbox',
    'job_name', 'communications-email-outbox-wake-one-minute',
    'warn_oldest_due_seconds', 300,
    'critical_oldest_due_seconds', 900,
    'job', (
      select jsonb_build_object('active', j.active, 'schedule', j.schedule)
      from cron.job j
      where j.jobname = 'communications-email-outbox-wake-one-minute'
    ),
    'last_run', (
      select jsonb_build_object('status', d.status, 'ran_at', d.start_time, 'finished_at', d.end_time)
      from cron.job j
      join cron.job_run_details d on d.jobid = j.jobid
      where j.jobname = 'communications-email-outbox-wake-one-minute'
      order by d.start_time desc
      limit 1
    ),
    'last_successful_drain_at', (
      select max(l.finished_at)
      from private.communication_worker_wake_ledger l
      left join net._http_response r on r.id = l.net_request_id
      where l.worker_name = 'communications-email-outbox'
        and l.route_outcome is not null
        and l.route_outcome <> 'error'
        and coalesce(r.status_code, 0) between 200 and 299
    ),
    'recent_wakes', coalesce((
      select jsonb_agg(w order by w.dispatched_at desc)
      from (
        select
          l.dispatched_at,
          l.finished_at,
          l.route_outcome,
          l.claimed,
          l.submitted,
          l.retried,
          l.submission_unknown,
          r.status_code as http_status,
          r.timed_out as http_timed_out,
          nullif(r.error_msg, '') as http_error
        from private.communication_worker_wake_ledger l
        left join net._http_response r on r.id = l.net_request_id
        where l.worker_name = 'communications-email-outbox'
        order by l.dispatched_at desc
        limit 10
      ) w
    ), '[]'::jsonb),
    'recent_failed_wakes', (
      select count(*) from (
        select l.net_request_id, l.route_outcome
        from private.communication_worker_wake_ledger l
        where l.worker_name = 'communications-email-outbox'
        order by l.dispatched_at desc
        limit 2
      ) recent
      left join net._http_response r on r.id = recent.net_request_id
      where recent.route_outcome is null
        or recent.route_outcome = 'error'
        or coalesce(r.status_code, 0) not between 200 and 299
    ),
    'due_count', (
      select count(*) from public.communication_outbox_events
      where channel = 'email' and status in ('pending', 'failed') and available_at <= now()
    ),
    'oldest_due_age_seconds', (
      select extract(epoch from (now() - min(available_at)))::bigint
      from public.communication_outbox_events
      where channel = 'email' and status in ('pending', 'failed') and available_at <= now()
    ),
    'processing_count', (
      select count(*) from public.communication_outbox_events
      where channel = 'email' and status = 'processing'
    ),
    'oldest_claim_age_seconds', (
      select extract(epoch from (now() - min(claimed_at)))::bigint
      from public.communication_outbox_events
      where channel = 'email' and status = 'processing'
    ),
    'submission_unknown_count', (
      select count(*) from public.communication_outbox_events
      where channel = 'email' and status = 'submission_unknown'
    ),
    'recent_capped_wakes', (
      select count(*) from (
        select l.route_outcome
        from private.communication_worker_wake_ledger l
        where l.worker_name = 'communications-email-outbox'
        order by l.dispatched_at desc
        limit 10
      ) recent
      where recent.route_outcome in ('max_claims', 'time_budget')
    )
  );
$$;


ALTER FUNCTION "public"."get_communication_email_worker_health"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_communication_email_worker_health"() IS 'Platform-Owner read: email-worker cron/job status by stable name, recent wakes with real HTTP outcome, due backlog and oldest-due age, in-flight processing, unknown outcomes, and recent cap/budget pressure. Scoped to channel = ''email'' throughout (Stage 4C fix -- SMS shares this table).';



CREATE OR REPLACE FUNCTION "public"."get_communication_message_history"("p_organization_id" "uuid", "p_delivery_intent_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case when intent.id is null then null else jsonb_build_object(
    'message', jsonb_build_object(
      'id', intent.id,
      'organization_id', intent.organization_id,
      'organization_name', org.name,
      'client_id', intent.client_id,
      'subject', intent.subject,
      'recipient_email', intent.recipient_email,
      'send_kind', intent.send_kind,
      'allowance_class', intent.allowance_class,
      'logical_send_key', intent.logical_send_key,
      'status', intent.status,
      'delivery_outcome', intent.delivery_outcome,
      'failure_code', intent.failure_code,
      'failure_message', intent.failure_message,
      'provider_message_id', intent.provider_message_id,
      'quote_id', intent.quote_id,
      'resent_from_intent_id', intent.resent_from_intent_id,
      'sender_email', sender.email_address,
      'sender_display_name', sender.display_name,
      'created_at', intent.created_at,
      'accepted_at', intent.accepted_at,
      'outbox_status', outbox.status,
      'attempt_count', outbox.attempt_count,
      'available_at', outbox.available_at,
      'last_error', outbox.last_error
    ),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', history.id,
        'seq', history.seq,
        'event_kind', history.event_kind,
        'occurred_at', history.occurred_at,
        'last_occurred_at', history.last_occurred_at,
        'repeat_count', history.repeat_count,
        'attempt_number', history.attempt_number,
        'reason_code', history.reason_code,
        'reason_message', history.reason_message,
        'retry_at', history.retry_at,
        'actor_kind', history.actor_kind,
        'actor_email', coalesce(history.actor_email, actor_account.email),
        'actor_name', actor.full_name,
        'related_intent_id', history.related_intent_id,
        'related_inbound_message_id', history.related_inbound_message_id
      ) order by history.occurred_at, history.seq)
      from public.communication_message_events history
      left join public.profiles actor on actor.id = history.actor_user_id
      left join auth.users actor_account on actor_account.id = history.actor_user_id
      where history.delivery_intent_id = intent.id
    ), '[]'::jsonb)
  ) end
  from public.communication_delivery_intents intent
  join public.organizations org on org.id = intent.organization_id
  left join public.communication_email_senders sender on sender.id = intent.sender_id
  left join public.communication_outbox_events outbox on outbox.delivery_intent_id = intent.id
  where intent.id = p_delivery_intent_id
    and intent.organization_id = p_organization_id;
$$;


ALTER FUNCTION "public"."get_communication_message_history"("p_organization_id" "uuid", "p_delivery_intent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_communication_message_recovery_queue"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with troubled as (
    select outbox.*
    from public.communication_outbox_events outbox
    where outbox.status = 'failed'
      or (outbox.status = 'pending' and outbox.last_error is not null)
    order by outbox.updated_at desc, outbox.id desc
    limit 50
  )
  select jsonb_build_object(
    'messages', coalesce((
      select jsonb_agg(jsonb_build_object(
        'delivery_intent_id', intent.id,
        'organization_id', intent.organization_id,
        'organization_name', org.name,
        'subject', intent.subject,
        'recipient_email', intent.recipient_email,
        'send_kind', intent.send_kind,
        'allowance_class', intent.allowance_class,
        'intent_status', intent.status,
        'outbox_status', troubled.status,
        'attempt_count', troubled.attempt_count,
        'available_at', troubled.available_at,
        'failure_code', intent.failure_code,
        'last_error', troubled.last_error,
        'updated_at', troubled.updated_at,
        'created_at', intent.created_at
      ) order by troubled.updated_at desc, troubled.id desc)
      from troubled
      join public.communication_delivery_intents intent on intent.id = troubled.delivery_intent_id
      join public.organizations org on org.id = intent.organization_id
    ), '[]'::jsonb),
    'held_total', (
      select count(*) from public.communication_outbox_events where status = 'failed'
    ),
    'waiting_total', (
      select count(*) from public.communication_outbox_events
      where status = 'pending' and last_error is not null
    )
  );
$$;


ALTER FUNCTION "public"."get_communication_message_recovery_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_communication_provider_callback_health"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'processor_job_name', 'communications-provider-callback-processor',
    'unprocessed_count', (
      select count(*) from public.communication_provider_callback_events
      where channel = 'email' and processed_at is null
    ),
    'oldest_unprocessed_at', (
      select min(received_at) from public.communication_provider_callback_events
      where channel = 'email' and processed_at is null
    ),
    'oldest_unprocessed_age_seconds', (
      select extract(epoch from (now() - min(received_at)))::bigint
      from public.communication_provider_callback_events
      where channel = 'email' and processed_at is null
    ),
    'retrying_count', (
      select count(*) from public.communication_provider_callback_events
      where channel = 'email' and processed_at is null and processing_attempts > 0
    ),
    'parked_count', (
      select count(*) from public.communication_provider_callback_events
      where channel = 'email' and processed_at is not null and processing_error is not null
    ),
    'last_run', (
      select jsonb_build_object('status', d.status, 'ran_at', d.start_time, 'finished_at', d.end_time)
      from cron.job j
      join cron.job_run_details d on d.jobid = j.jobid
      where j.jobname = 'communications-provider-callback-processor'
      order by d.start_time desc
      limit 1
    ),
    'last_success_at', (
      select max(d.end_time)
      from cron.job j
      join cron.job_run_details d on d.jobid = j.jobid
      where j.jobname = 'communications-provider-callback-processor' and d.status = 'succeeded'
    ),
    'provider_blocking_24h', coalesce((
      select jsonb_object_agg(g.delivery_outcome, g.outcome_count)
      from (
        select delivery_outcome, count(*) as outcome_count
        from public.communication_delivery_intents
        where channel = 'email'
          and delivery_outcome in ('blocked', 'hard_bounce', 'complaint', 'unsubscribed')
          and delivery_outcome_at >= now() - interval '24 hours'
        group by delivery_outcome
      ) g
    ), '{}'::jsonb),
    'active_suppressions', coalesce((
      select jsonb_object_agg(s.reason, s.reason_count)
      from (
        select reason, count(*) as reason_count
        from public.communication_email_suppressions
        where released_at is null
        group by reason
      ) s
    ), '{}'::jsonb)
  );
$$;


ALTER FUNCTION "public"."get_communication_provider_callback_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_communication_sms_worker_health"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'net'
    AS $$
  select jsonb_build_object(
    'worker_name', 'communications-sms-outbox',
    'job_name', 'communications-sms-outbox-wake-one-minute',
    'warn_oldest_due_seconds', 300,
    'critical_oldest_due_seconds', 900,
    'job', (
      select jsonb_build_object('active', j.active, 'schedule', j.schedule)
      from cron.job j
      where j.jobname = 'communications-sms-outbox-wake-one-minute'
    ),
    'last_run', (
      select jsonb_build_object('status', d.status, 'ran_at', d.start_time, 'finished_at', d.end_time)
      from cron.job j
      join cron.job_run_details d on d.jobid = j.jobid
      where j.jobname = 'communications-sms-outbox-wake-one-minute'
      order by d.start_time desc
      limit 1
    ),
    'last_successful_drain_at', (
      select max(l.finished_at)
      from private.communication_worker_wake_ledger l
      left join net._http_response r on r.id = l.net_request_id
      where l.worker_name = 'communications-sms-outbox'
        and l.route_outcome is not null
        and l.route_outcome <> 'error'
        and coalesce(r.status_code, 0) between 200 and 299
    ),
    'recent_wakes', coalesce((
      select jsonb_agg(w order by w.dispatched_at desc)
      from (
        select
          l.dispatched_at,
          l.finished_at,
          l.route_outcome,
          l.claimed,
          l.submitted,
          l.retried,
          l.submission_unknown,
          r.status_code as http_status,
          r.timed_out as http_timed_out,
          nullif(r.error_msg, '') as http_error
        from private.communication_worker_wake_ledger l
        left join net._http_response r on r.id = l.net_request_id
        where l.worker_name = 'communications-sms-outbox'
        order by l.dispatched_at desc
        limit 10
      ) w
    ), '[]'::jsonb),
    'recent_failed_wakes', (
      select count(*) from (
        select l.net_request_id, l.route_outcome
        from private.communication_worker_wake_ledger l
        where l.worker_name = 'communications-sms-outbox'
        order by l.dispatched_at desc
        limit 2
      ) recent
      left join net._http_response r on r.id = recent.net_request_id
      where recent.route_outcome is null
        or recent.route_outcome = 'error'
        or coalesce(r.status_code, 0) not between 200 and 299
    ),
    'due_count', (
      select count(*) from public.communication_outbox_events
      where channel = 'sms' and status in ('pending', 'failed') and available_at <= now()
    ),
    'oldest_due_age_seconds', (
      select extract(epoch from (now() - min(available_at)))::bigint
      from public.communication_outbox_events
      where channel = 'sms' and status in ('pending', 'failed') and available_at <= now()
    ),
    'processing_count', (
      select count(*) from public.communication_outbox_events
      where channel = 'sms' and status = 'processing'
    ),
    'oldest_claim_age_seconds', (
      select extract(epoch from (now() - min(claimed_at)))::bigint
      from public.communication_outbox_events
      where channel = 'sms' and status = 'processing'
    ),
    'submission_unknown_count', (
      select count(*) from public.communication_outbox_events
      where channel = 'sms' and status = 'submission_unknown'
    ),
    'recent_capped_wakes', (
      select count(*) from (
        select l.route_outcome
        from private.communication_worker_wake_ledger l
        where l.worker_name = 'communications-sms-outbox'
        order by l.dispatched_at desc
        limit 10
      ) recent
      where recent.route_outcome in ('max_claims', 'time_budget')
    )
  );
$$;


ALTER FUNCTION "public"."get_communication_sms_worker_health"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_communication_sms_worker_health"() IS 'Platform-Owner read: sms-worker cron/job status by stable name, recent wakes with real HTTP outcome, due backlog and oldest-due age, in-flight processing, unknown outcomes, and recent cap/budget pressure. Scoped to channel = ''sms'' throughout.';



CREATE OR REPLACE FUNCTION "public"."get_form_available_slots"("target_organization_id" "uuid", "target_form_id" "uuid", "range_start" "date", "range_end" "date") RETURNS TABLE("slot_date" "date", "start_time" time without time zone, "end_time" time without time zone, "starts_at" timestamp with time zone, "ends_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not private.has_permission(target_organization_id, 'settings.forms.manage') then
    raise exception 'You do not have access to view booking availability.'
      using errcode = 'insufficient_privilege';
  end if;

  return query
  select * from private.compute_form_available_slots(target_organization_id, target_form_id, range_start, range_end);
end;
$$;


ALTER FUNCTION "public"."get_form_available_slots"("target_organization_id" "uuid", "target_form_id" "uuid", "range_start" "date", "range_end" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_form_available_slots"("target_organization_id" "uuid", "target_form_id" "uuid", "range_start" "date", "range_end" "date") IS 'Every bookable slot for one form across a date window (capped at 60 days). Staff-only (settings.forms.manage) -- see get_public_form_available_slots for the anonymous-safe path.';



CREATE OR REPLACE FUNCTION "public"."get_incomplete_assignments_for_member"("target_organization_id" "uuid", "target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  result jsonb;
begin
  if (select auth.uid()) is null or not exists (
    select 1
    from private.permitted_organizations('team.manage') as permitted(organization_id)
    where permitted.organization_id = target_organization_id
  ) then
    raise exception 'Team management is not available for this organization.'
      using errcode = '42501';
  end if;

  select jsonb_build_object(
    'assessments', coalesce((
      select jsonb_agg(jsonb_build_object('id', a.id, 'starts_at', a.starts_at))
      from (
        select assessment.id, assessment.starts_at
        from public.assessment_assignees as assignee
        join public.assessments as assessment on assessment.id = assignee.assessment_id
        where assignee.organization_id = target_organization_id
          and assignee.user_id = target_user_id
          and assessment.completed_at is null
        order by assessment.starts_at nulls last
        limit 50
      ) as a
    ), '[]'::jsonb),
    'assessments_total', (
      select count(*)
      from public.assessment_assignees as assignee
      join public.assessments as assessment on assessment.id = assignee.assessment_id
      where assignee.organization_id = target_organization_id
        and assignee.user_id = target_user_id
        and assessment.completed_at is null
    ),
    'visits', coalesce((
      select jsonb_agg(
        jsonb_build_object('id', v.id, 'visit_date', v.visit_date, 'start_time', v.start_time, 'title', v.title)
      )
      from (
        select visit.id, visit.visit_date, visit.start_time, visit.title
        from public.job_visit_assignments as assignee
        join public.job_visits as visit on visit.id = assignee.visit_id
        where assignee.organization_id = target_organization_id
          and assignee.user_id = target_user_id
          and visit.completed_at is null
        order by visit.visit_date nulls last, visit.start_time nulls last
        limit 50
      ) as v
    ), '[]'::jsonb),
    'visits_total', (
      select count(*)
      from public.job_visit_assignments as assignee
      join public.job_visits as visit on visit.id = assignee.visit_id
      where assignee.organization_id = target_organization_id
        and assignee.user_id = target_user_id
        and visit.completed_at is null
    ),
    'tasks', coalesce((
      select jsonb_agg(jsonb_build_object('id', t.id, 'title', t.title, 'due_on', t.due_on))
      from (
        select task.id, task.title, task.due_on
        from public.tasks as task
        where task.organization_id = target_organization_id
          and task.assignee_user_id = target_user_id
          and task.status = 'open'
        order by task.due_on nulls last
        limit 50
      ) as t
    ), '[]'::jsonb),
    'tasks_total', (
      select count(*)
      from public.tasks as task
      where task.organization_id = target_organization_id
        and task.assignee_user_id = target_user_id
        and task.status = 'open'
    )
  ) into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_incomplete_assignments_for_member"("target_organization_id" "uuid", "target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_incomplete_assignments_for_member"("target_organization_id" "uuid", "target_user_id" "uuid") IS 'What deactivate_team_member is about to unassign, for the confirmation dialog: up to 50 of each surface plus a true total. Every predicate matches deactivate_team_member exactly, so the preview and the result can never disagree.';



CREATE OR REPLACE FUNCTION "public"."get_organization_automation_authority"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'operational_state', coalesce(authority.operational_state, 'enabled'),
    'security_state', coalesce(authority.security_state, 'active'),
    'operational_reason', authority.operational_reason,
    'security_reason', authority.security_reason,
    'operational_changed_at', authority.operational_changed_at,
    'security_changed_at', authority.security_changed_at,
    'recent_events', coalesce((
      select jsonb_agg(to_jsonb(history) order by history.created_at desc, history.id desc)
      from (
        select id, axis, event_kind, reason, actor_owner_email, created_at
        from public.automation_authority_events
        where organization_id = p_organization_id
        order by created_at desc, id desc
        limit 20
      ) history
    ), '[]'::jsonb)
  )
  from (select 1) as one
  left join public.organization_automation_authority as authority
    on authority.organization_id = p_organization_id;
$$;


ALTER FUNCTION "public"."get_organization_automation_authority"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_organization_automation_authority"("p_organization_id" "uuid") IS 'Owner-only read model: current Automation authority state and recent reasoned history for one organization.';



CREATE OR REPLACE FUNCTION "public"."get_organization_automation_limits"("p_organization_id" "uuid", "at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with keys (limit_key) as (
    values
      ('automation_active_recipes'),
      ('automation_max_conditions_per_recipe'),
      ('automation_max_steps_per_recipe'),
      ('automation_max_customer_messages_per_enrollment'),
      ('automation_min_customer_message_spacing_minutes'),
      ('automation_max_delay_days'),
      ('automation_max_enrollment_duration_days')
  ),
  current_assignment as (
    select assignment.package_version_id
    from public.organization_package_assignments as assignment
    where assignment.organization_id = p_organization_id
    order by assignment.effective_at desc, assignment.id desc
    limit 1
  ),
  package_default as (
    select version_limit.limit_key, version_limit.limit_state, version_limit.limit_value
    from public.platform_package_version_limits as version_limit
    where version_limit.package_version_id = (select package_version_id from current_assignment)
      and version_limit.limit_key in (
        'automation_active_recipes', 'automation_max_conditions_per_recipe',
        'automation_max_steps_per_recipe', 'automation_max_customer_messages_per_enrollment',
        'automation_min_customer_message_spacing_minutes', 'automation_max_delay_days',
        'automation_max_enrollment_duration_days'
      )
  ),
  exception_row as (
    select override.limit_key, override.limit_state, override.limit_value, override.is_unlimited,
           override.reason, override.actor_owner_email, override.starts_at, override.expires_at,
           (override.starts_at <= at and (override.expires_at is null or override.expires_at > at)) as is_active
    from public.organization_limit_overrides as override
    where override.organization_id = p_organization_id
      and override.limit_key in (
        'automation_active_recipes', 'automation_max_conditions_per_recipe',
        'automation_max_steps_per_recipe', 'automation_max_customer_messages_per_enrollment',
        'automation_min_customer_message_spacing_minutes', 'automation_max_delay_days',
        'automation_max_enrollment_duration_days'
      )
  ),
  effective as (
    select resolved.limit_key, resolved.state, resolved.value, resolved.is_unlimited, resolved.source
    from public.effective_automation_limits(p_organization_id, at) as resolved
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'limit_key', keys.limit_key,
        'package_default', jsonb_build_object(
          'state', coalesce(package_default.limit_state, 'not_included'),
          'value', case when package_default.limit_state = 'numeric' then package_default.limit_value end
        ),
        'effective', jsonb_build_object(
          'state', effective.state,
          'value', effective.value,
          'is_unlimited', effective.is_unlimited,
          'source', effective.source
        ),
        'exception', case
          when exception_row.limit_key is null then null
          else jsonb_build_object(
            'state', exception_row.limit_state,
            'value', case when exception_row.limit_state = 'numeric' then exception_row.limit_value end,
            'is_unlimited', exception_row.is_unlimited,
            'is_active', exception_row.is_active,
            'reason', exception_row.reason,
            'actor_owner_email', exception_row.actor_owner_email,
            'starts_at', exception_row.starts_at,
            'expires_at', exception_row.expires_at
          )
        end
      )
      order by keys.limit_key
    ),
    '[]'::jsonb
  )
  from keys
  left join package_default on package_default.limit_key = keys.limit_key
  left join exception_row on exception_row.limit_key = keys.limit_key
  left join effective on effective.limit_key = keys.limit_key;
$$;


ALTER FUNCTION "public"."get_organization_automation_limits"("p_organization_id" "uuid", "at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_organization_automation_limits"("p_organization_id" "uuid", "at" timestamp with time zone) IS 'Owner-only read model: package default, effective value/source (from effective_automation_limits), and the reasoned/effective-dated exception for each of the seven Automation limits.';



CREATE OR REPLACE FUNCTION "public"."get_organization_communication_email_allowances"("target_organization_id" "uuid", "at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("limit_key" "text", "period_id" "uuid", "period_starts_at" timestamp with time zone, "period_ends_at" timestamp with time zone, "effective_state" "text", "effective_value" integer, "effective_source" "text", "fallback_state" "text", "fallback_value" integer, "override_state" "text", "override_value" integer, "override_starts_at" timestamp with time zone, "override_expires_at" timestamp with time zone, "override_reason" "text", "override_author_email" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
  with keys(limit_key) as (
    values ('operational_email_recipients'::text), ('essential_email_recipients'::text)
  ), current_assignment as (
    select assignment.package_version_id
    from public.organization_package_assignments as assignment
    where assignment.organization_id = target_organization_id and assignment.effective_at <= at
    order by assignment.effective_at desc, assignment.id desc
    limit 1
  ), package_limits as (
    select version_limit.limit_key, version_limit.limit_state, version_limit.limit_value
    from public.platform_package_version_limits as version_limit
    where version_limit.package_version_id = (select package_version_id from current_assignment)
      and version_limit.limit_key in ('operational_email_recipients', 'essential_email_recipients')
  ), stored_overrides as (
    select override.limit_key, override.limit_state, override.limit_value, override.starts_at,
      override.expires_at, override.reason, override.actor_owner_email,
      override.starts_at <= at and (override.expires_at is null or override.expires_at > at) as is_active
    from public.organization_limit_overrides as override
    where override.organization_id = target_organization_id
      and override.limit_key in ('operational_email_recipients', 'essential_email_recipients')
  ), allowance as (
    select * from private.resolve_communication_email_allowance(target_organization_id, at)
  )
  select
    key.limit_key,
    allowance.period_id,
    allowance.period_starts_at,
    allowance.period_ends_at,
    case key.limit_key
      when 'operational_email_recipients' then coalesce(
        case when override.is_active then override.limit_state end, allowance.operational_limit_state, package_limit.limit_state)
      else coalesce(
        case when override.is_active then override.limit_state end, allowance.essential_limit_state, package_limit.limit_state)
    end,
    case key.limit_key
      when 'operational_email_recipients' then coalesce(
        case when override.is_active then override.limit_value end, allowance.operational_limit_value, package_limit.limit_value)
      else coalesce(
        case when override.is_active then override.limit_value end, allowance.essential_limit_value, package_limit.limit_value)
    end,
    case when override.is_active then 'override' else 'package' end,
    package_limit.limit_state,
    package_limit.limit_value,
    override.limit_state,
    override.limit_value,
    override.starts_at,
    override.expires_at,
    override.reason,
    override.actor_owner_email
  from keys as key
  left join package_limits as package_limit on package_limit.limit_key = key.limit_key
  left join stored_overrides as override on override.limit_key = key.limit_key
  left join allowance on true
  order by key.limit_key;
$$;


ALTER FUNCTION "public"."get_organization_communication_email_allowances"("target_organization_id" "uuid", "at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organization_communication_email_usage"("p_organization_id" "uuid") RETURNS TABLE("period_id" "uuid", "period_starts_at" timestamp with time zone, "period_ends_at" timestamp with time zone, "organization_timezone" "text", "optional_limit_state" "text", "optional_limit_value" integer, "optional_used" integer, "essential_limit_state" "text", "essential_limit_value" integer, "essential_used" integer, "essential_reserve_exhausted" boolean, "essential_reserve_exhausted_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
  with allowance as (
    select * from private.resolve_communication_email_allowance(p_organization_id, now())
  ), counted as (
    select
      allowance.*,
      (
        select coalesce(sum(usage.recipient_count), 0)::integer
        from public.communication_email_usage_events usage
        where usage.organization_id = p_organization_id
          and usage.allowance_period_id = allowance.period_id
          and usage.allowance_class = 'optional'
      ) + (
        select coalesce(sum(reservation.recipient_count), 0)::integer
        from public.communication_email_capacity_reservations reservation
        where reservation.organization_id = p_organization_id
          and reservation.allowance_period_id = allowance.period_id
          and reservation.allowance_class = 'optional'
          and reservation.reservation_state in ('reserved', 'submission_unknown')
      ) as optional_used,
      (
        select coalesce(sum(usage.recipient_count), 0)::integer
        from public.communication_email_usage_events usage
        where usage.organization_id = p_organization_id
          and usage.allowance_period_id = allowance.period_id
          and usage.allowance_class = 'essential'
      ) + (
        select coalesce(sum(reservation.recipient_count), 0)::integer
        from public.communication_email_capacity_reservations reservation
        where reservation.organization_id = p_organization_id
          and reservation.allowance_period_id = allowance.period_id
          and reservation.allowance_class = 'essential'
          and reservation.reservation_state in ('reserved', 'submission_unknown')
      ) as essential_used
    from allowance
  )
  select
    counted.period_id,
    counted.period_starts_at,
    counted.period_ends_at,
    coalesce(settings.timezone, 'UTC'),
    counted.operational_limit_state,
    counted.operational_limit_value,
    counted.optional_used,
    counted.essential_limit_state,
    counted.essential_limit_value,
    counted.essential_used,
    counted.essential_limit_state = 'numeric'
      and counted.essential_limit_value is not null
      and counted.essential_used >= counted.essential_limit_value,
    alert.first_detected_at
  from counted
  left join public.organization_settings as settings on settings.organization_id = p_organization_id
  left join public.communication_email_allowance_alerts as alert
    on alert.organization_id = p_organization_id
    and alert.allowance_period_id = counted.period_id
    and alert.alert_kind = 'essential_reserve_exhausted'
  ;
$$;


ALTER FUNCTION "public"."get_organization_communication_email_usage"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organization_communication_website_chat_allowance"("target_organization_id" "uuid", "at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("limit_key" "text", "period_id" "uuid", "period_starts_at" timestamp with time zone, "period_ends_at" timestamp with time zone, "effective_state" "text", "effective_value" integer, "effective_source" "text", "fallback_state" "text", "fallback_value" integer, "override_state" "text", "override_value" integer, "override_starts_at" timestamp with time zone, "override_expires_at" timestamp with time zone, "override_reason" "text", "override_author_email" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with current_assignment as (
    select assignment.package_version_id
    from public.organization_package_assignments as assignment
    where assignment.organization_id = target_organization_id and assignment.effective_at <= at
    order by assignment.effective_at desc, assignment.id desc
    limit 1
  ), package_limit as (
    select version_limit.limit_state, version_limit.limit_value
    from public.platform_package_version_limits as version_limit
    where version_limit.package_version_id = (select package_version_id from current_assignment)
      and version_limit.limit_key = 'website_chat_accepted_conversations'
  ), stored_override as (
    select override.limit_state, override.limit_value, override.starts_at, override.expires_at,
      override.reason, override.actor_owner_email,
      override.starts_at <= at and (override.expires_at is null or override.expires_at > at) as is_active
    from public.organization_limit_overrides as override
    where override.organization_id = target_organization_id
      and override.limit_key = 'website_chat_accepted_conversations'
  )
  select
    'website_chat_accepted_conversations'::text,
    null::uuid,
    null::timestamptz,
    null::timestamptz,
    coalesce(case when stored_override.is_active then stored_override.limit_state end, package_limit.limit_state, 'not_included'),
    case when stored_override.is_active then stored_override.limit_value else package_limit.limit_value end,
    case when stored_override.is_active then 'override' else 'package' end,
    package_limit.limit_state,
    package_limit.limit_value,
    stored_override.limit_state,
    stored_override.limit_value,
    stored_override.starts_at,
    stored_override.expires_at,
    stored_override.reason,
    stored_override.actor_owner_email
  from (select 1) as one
  left join package_limit on true
  left join stored_override on true;
$$;


