COMMENT ON FUNCTION "public"."get_organization_communication_website_chat_allowance"("target_organization_id" "uuid", "at" timestamp with time zone) IS 'Owner-only read model for the website_chat_accepted_conversations allowance. Period fields are null until real usage periods exist.';



CREATE OR REPLACE FUNCTION "public"."get_organization_website_chat_authority"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with latest_suspension as (
    select e.*
    from public.communication_website_chat_authority_events e
    where e.organization_id = p_organization_id
      and e.event_kind in ('suspension_engaged', 'suspension_released')
    order by e.created_at desc, e.id desc
    limit 1
  ), widget_total as (
    select count(*)::integer as value
    from public.website_chat_widgets
    where organization_id = p_organization_id
  ), selected_widgets as (
    select w.*
    from public.website_chat_widgets w
    where w.organization_id = p_organization_id
    order by w.updated_at desc, w.id desc
    limit 100
  ), origin_counts as (
    select origin.widget_id, count(*)::integer as value
    from public.website_chat_widget_origins origin
    join selected_widgets selected on selected.id = origin.widget_id
    group by origin.widget_id
  )
  select jsonb_build_object(
    'suspension', (
      select case when event_kind = 'suspension_engaged' then jsonb_build_object(
        'event_id', id, 'reason', reason, 'engaged_by', actor_owner_email, 'engaged_at', created_at
      ) else null end
      from latest_suspension
    ),
    'widget_total_count', (select value from widget_total),
    'widgets_truncated', (select value > 100 from widget_total),
    'widgets', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', w.id, 'name', w.name, 'published', w.published,
        'disabled_at', w.disabled_at, 'suspended_at', w.suspended_at,
        'revision', w.revision, 'public_token', w.public_token,
        'allowed_origin_count', coalesce(origins.value, 0),
        'updated_at', w.updated_at
      ) order by w.updated_at desc, w.id desc)
      from selected_widgets w
      left join origin_counts origins on origins.widget_id = w.id
    ), '[]'::jsonb),
    'recent_events', coalesce((
      select jsonb_agg(to_jsonb(history) order by history.created_at desc, history.id desc)
      from (
        select id, widget_id, event_kind, reason, actor_owner_email, created_at
        from public.communication_website_chat_authority_events
        where organization_id = p_organization_id
        order by created_at desc, id desc
        limit 20
      ) history
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."get_organization_website_chat_authority"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_form_available_slots"("target_organization_slug" "text", "target_form_slug" "text", "range_start" "date", "range_end" "date") RETURNS TABLE("slot_date" "date", "start_time" time without time zone, "end_time" time without time zone, "starts_at" timestamp with time zone, "ends_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  resolved_organization_id uuid;
  resolved_form_id uuid;
begin
  select o.id, f.id into resolved_organization_id, resolved_form_id
  from public.organizations as o
  join public.forms as f on f.organization_id = o.id
  where o.slug = target_organization_slug
    and f.public_slug = target_form_slug
    and f.archived_at is null
    and f.is_enabled
    and f.current_published_version_id is not null
    and o.lifecycle_status = 'active';

  if resolved_form_id is null then
    raise exception 'That form is not available.' using errcode = 'check_violation';
  end if;

  return query
  select * from private.compute_form_available_slots(
    resolved_organization_id, resolved_form_id, range_start, range_end
  );
end;
$$;


