COMMENT ON FUNCTION "public"."get_public_form_available_slots"("target_organization_slug" "text", "target_form_slug" "text", "range_start" "date", "range_end" "date") IS 'The anonymous-safe counterpart to get_form_available_slots -- resolves the form by its public link instead of trusting an authenticated caller''s own organization.';



CREATE OR REPLACE FUNCTION "public"."get_team_member_detail"("target_organization_id" "uuid", "target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  result jsonb;
begin
  if (select auth.uid()) is null or not exists (
    select 1
    from private.permitted_organizations('team.manage') as permitted(organization_id)
    where permitted.organization_id = target_organization_id
  ) then
    raise exception 'Team management is not available for this organization.'
      using errcode = '42501';
  end if;

  select jsonb_build_object(
    'user_id', member.user_id,
    'display_name', profile.full_name,
    'avatar_url', profile.avatar_url,
    'role', member.role,
    'status', member.status,
    'access_revision', member.access_revision,
    'profile_revision', member.profile_revision,
    'work_phone', member.work_phone,
    'job_title', member.job_title,
    'schedule_color', member.schedule_color,
    'created_at', member.created_at,
    'deactivated_at', member.deactivated_at,
    'invitation', case when invitation.id is null then null else jsonb_build_object(
      'id', invitation.id,
      'email', invitation.invited_email,
      'state', invitation.state,
      'delivery_failed', invitation.last_delivery_error is not null,
      'last_sent_at', invitation.last_sent_at,
      'expires_at', invitation.expires_at
    ) end,
    'cost_per_hour_minor', cost.cost_per_hour_minor,
    'cost_rate_updated_at', cost.updated_at
  ) into result
  from public.organization_members as member
  left join public.profiles as profile on profile.id = member.user_id
  left join public.organization_member_cost_profiles as cost
    on cost.organization_id = member.organization_id and cost.user_id = member.user_id
  left join lateral (
    select candidate.id, candidate.invited_email, candidate.state, candidate.last_delivery_error,
           candidate.last_sent_at, candidate.expires_at
    from public.organization_member_invitations as candidate
    where candidate.organization_id = member.organization_id
      and candidate.invited_user_id = member.user_id
      and candidate.state in ('reserving', 'invited', 'accepting')
    order by candidate.created_at desc, candidate.id desc
    limit 1
  ) as invitation on true
  where member.organization_id = target_organization_id
    and member.user_id = target_user_id
    and member.status <> 'removed';

  if result is null then
    raise exception 'That team member was not found.' using errcode = 'P0002';
  end if;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_team_member_detail"("target_organization_id" "uuid", "target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_team_member_detail"("target_organization_id" "uuid", "target_user_id" "uuid") IS 'Returns one tenant-authorized Team member for the read-first details route, including their hourly cost rate; access editing remains separate.';



CREATE OR REPLACE FUNCTION "public"."get_website_chat_session_messages"("session_token_hash" "text", "requesting_origin" "text", "before_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "before_id" "uuid" DEFAULT NULL::"uuid", "page_size" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "statement_timeout" TO '5000'
    AS $$
declare
  target_session public.website_chat_sessions;
  widget record;
  normalized_origin text := lower(btrim(coalesce(requesting_origin, '')));
  origin_allowed boolean;
  effective_page_size integer := least(greatest(coalesce(page_size, 30), 1), 50);
  rate_check record;
  page jsonb;
  fetched integer;
begin
  if normalized_origin = '' or nullif(btrim(coalesce(session_token_hash, '')), '') is null then
    return jsonb_build_object('status', 'refused');
  end if;

  if (before_created_at is null) <> (before_id is null) then
    return jsonb_build_object('status', 'refused');
  end if;

  select * into target_session
  from public.website_chat_sessions s
  where s.session_token_hash = btrim(get_website_chat_session_messages.session_token_hash);
  if not found then
    return jsonb_build_object('status', 'refused');
  end if;

  select w.id, w.organization_id, w.disabled_at, w.suspended_at, w.published into widget
  from public.website_chat_widgets w
  where w.id = target_session.widget_id;
  if not found then
    return jsonb_build_object('status', 'refused');
  end if;

  select exists (
    select 1 from public.website_chat_widget_origins o
    where o.widget_id = widget.id and o.origin = normalized_origin
  ) into origin_allowed;
  if not origin_allowed then
    return jsonb_build_object('status', 'refused');
  end if;

  select * into rate_check
  from public.check_rate_limit('website_chat:read:' || target_session.id::text, 60, 90);
  if not rate_check.allowed then
    return jsonb_build_object('status', 'rate_limited');
  end if;

  with page_rows as materialized (
    select m.id, m.direction, m.sender_type, m.body, m.created_at
    from public.website_chat_messages m
    where m.organization_id = target_session.organization_id
      and m.session_id = target_session.id
      and (
        before_created_at is null
        or (m.created_at, m.id) < (before_created_at, before_id)
      )
    order by m.created_at desc, m.id desc
    limit effective_page_size + 1
  ),
  trimmed as (
    select * from page_rows
    order by created_at desc, id desc
    limit effective_page_size
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', trimmed.id,
      'direction', trimmed.direction,
      'sender_type', trimmed.sender_type,
      'body', trimmed.body,
      'created_at', trimmed.created_at
    ) order by trimmed.created_at desc, trimmed.id desc), '[]'::jsonb),
    (select count(*) from page_rows)
  into page, fetched
  from trimmed;

  return jsonb_build_object(
    'status', 'ok',
    'session_id', target_session.id,
    'closed_at', target_session.closed_at,
    'messages', page,
    'has_more', fetched > effective_page_size
  );
end;
$$;


ALTER FUNCTION "public"."get_website_chat_session_messages"("session_token_hash" "text", "requesting_origin" "text", "before_created_at" timestamp with time zone, "before_id" "uuid", "page_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_website_chat_session_messages"("session_token_hash" "text", "requesting_origin" "text", "before_created_at" timestamp with time zone, "before_id" "uuid", "page_size" integer) IS 'The only read path for a Website Chat visitor''s own conversation. Authorized by the session token hash plus an allowlisted origin, keyset-paginated, and narrowed to the fields a bubble needs -- never sender_user_id. A closed session still returns its history.';



CREATE OR REPLACE FUNCTION "public"."get_website_chat_widget_public_config"("widget_public_token" "uuid", "requesting_origin" "text") RETURNS TABLE("widget_id" "uuid", "organization_id" "uuid", "business_name" "text", "brand_color" "text", "launcher_position" "text", "teaser_text" "text", "greeting_text" "text", "contact_requirement" "text", "privacy_policy_url" "text", "status" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  widget record;
  normalized_origin text := lower(btrim(coalesce(requesting_origin, '')));
  origin_allowed boolean;
  entitlement_state text;
begin
  if normalized_origin = '' then
    return;
  end if;

  select w.id, w.organization_id, w.published, w.disabled_at, w.suspended_at,
         w.launcher_position, w.teaser_text, w.greeting_text, w.contact_requirement,
         w.privacy_policy_url
  into widget
  from public.website_chat_widgets w
  where w.public_token = widget_public_token;

  if not found then
    return;
  end if;

  select exists (
    select 1
    from public.website_chat_widget_origins o
    where o.widget_id = widget.id
      and o.origin = normalized_origin
  ) into origin_allowed;

  if not origin_allowed then
    return;
  end if;

  select l.state into entitlement_state
  from public.effective_website_chat_widgets_limit(widget.organization_id) l;

  widget_id := widget.id;
  organization_id := widget.organization_id;
  launcher_position := widget.launcher_position;
  teaser_text := widget.teaser_text;
  greeting_text := widget.greeting_text;
  contact_requirement := widget.contact_requirement;
  privacy_policy_url := widget.privacy_policy_url;

  select o.name, s.brand_color into business_name, brand_color
  from public.organizations o
  left join public.organization_settings s on s.organization_id = o.id
  where o.id = widget.organization_id;

  status := case
    when widget.suspended_at is not null then 'suspended'
    when widget.disabled_at is not null then 'disabled'
    when not widget.published then 'draft'
    when entitlement_state = 'not_included' then 'not_entitled'
    else 'live'
  end;

  return next;
end;
$$;


ALTER FUNCTION "public"."get_website_chat_widget_public_config"("widget_public_token" "uuid", "requesting_origin" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_website_chat_widget_public_config"("widget_public_token" "uuid", "requesting_origin" "text") IS 'Public-safe read for the Website Chat widget (WC3, extended by WC4.3). Resolves branding, the identity requirement, the privacy policy link and status only for a token/origin pair that is actually allowed; anything else returns no rows.';



CREATE OR REPLACE FUNCTION "public"."inquiry_alert_members"("p_organization_id" "uuid") RETURNS TABLE("user_id" "uuid", "role" "text", "full_name" "text", "email" "text", "can_receive" boolean, "chosen" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
  select m.user_id, m.role, p.full_name, u.email::text,
    private.member_receives_inquiry_alerts(m.organization_id, m.user_id),
    exists (
      select 1 from public.inquiry_alert_recipients as r
      where r.organization_id = m.organization_id and r.user_id = m.user_id
    )
  from public.organization_members as m
  left join public.profiles as p on p.id = m.user_id
  left join auth.users as u on u.id = m.user_id
  where m.organization_id = p_organization_id and m.status = 'active'
  order by (m.role = 'owner') desc, p.full_name nulls last, m.user_id
  limit 500;
$$;


ALTER FUNCTION "public"."inquiry_alert_members"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intake_automation_events"("p_batch_size" integer DEFAULT 25) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  candidate private.automation_events%rowtype;
  match_row record;
  authority public.organization_automation_authority%rowtype;
  quote_row public.quotes%rowtype;
  is_entitled boolean;
  wants_follow_ups boolean;
  subject_present boolean;
  duration_days integer;
  enrollment_expires_at timestamptz;
  re_entry_key text;
  match_outcome text;
  new_enrollment_id uuid;
  processed_count integer := 0;
  max_processing_attempts constant integer := 5;
begin
  if p_batch_size < 1 or p_batch_size > 200 then
    raise exception 'The intake batch size is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  for candidate in
    select *
    from private.automation_events
    where processed_at is null
      and available_at <= now()
    order by seq
    limit p_batch_size
    for update skip locked
  loop
    begin
      select * into authority
      from public.organization_automation_authority
      where organization_id = candidate.organization_id;

      is_entitled := private.organization_has_automations_feature(candidate.organization_id);

      quote_row := null;
      wants_follow_ups := true;
      if candidate.subject_type = 'quote' then
        select * into quote_row
        from public.quotes
        where organization_id = candidate.organization_id and id = candidate.subject_id;

        if quote_row.client_id is not null then
          select coalesce(p.quote_follow_ups, true) into wants_follow_ups
          from public.client_communication_preferences as p
          where p.organization_id = candidate.organization_id and p.client_id = quote_row.client_id;
          wants_follow_ups := coalesce(wants_follow_ups, true);
        end if;

        subject_present := quote_row.id is not null and quote_row.archived_at is null;
        re_entry_key := coalesce(candidate.payload ->> 'quote_version_id', '')
          || ':' || coalesce(candidate.payload ->> 'quote_recipient_id', '');
      elsif candidate.subject_type = 'form_submission' then
        select exists (
          select 1 from private.form_submissions as s
          where s.organization_id = candidate.organization_id and s.id = candidate.subject_id
            and s.status = 'processed'
        ) into subject_present;
        re_entry_key := 'form_submission:' || candidate.subject_id::text;
      elsif candidate.subject_type = 'website_chat_session' then
        select exists (
          select 1 from public.website_chat_sessions as s
          where s.organization_id = candidate.organization_id and s.id = candidate.subject_id
        ) into subject_present;
        re_entry_key := 'website_chat_session:' || candidate.subject_id::text;
      else
        subject_present := false;
        re_entry_key := candidate.subject_type || ':' || candidate.subject_id::text;
      end if;

      select case when limits.state = 'numeric' then limits.value end
      into duration_days
      from public.effective_automation_limits(candidate.organization_id) as limits
      where limits.limit_key = 'automation_max_enrollment_duration_days';

      enrollment_expires_at := case
        when duration_days is not null and duration_days > 0
        then now() + make_interval(days => duration_days)
      end;

      for match_row in
        select
          recipe.id as recipe_id,
          recipe.current_version_id,
          version.definition,
          version.activation_cutoff_snapshot,
          version.activation_cutoff_sequence
        from public.automation_recipes as recipe
        join public.automation_recipe_versions as version
          on version.id = recipe.current_version_id
        where recipe.organization_id = candidate.organization_id
          and recipe.status = 'active'
          and recipe.active_trigger_key = candidate.event_type
        order by recipe.id
      loop
        match_outcome := null;
        new_enrollment_id := null;

        if not is_entitled then
          match_outcome := 'not_entitled';
        elsif authority.organization_id is not null
          and (authority.operational_state <> 'enabled' or authority.security_state <> 'active') then
          match_outcome := 'authority_blocked';
        elsif (
            match_row.activation_cutoff_snapshot is not null
            and pg_visible_in_snapshot(candidate.created_xid, match_row.activation_cutoff_snapshot)
          ) or (
            match_row.activation_cutoff_snapshot is null
            and candidate.seq <= coalesce(match_row.activation_cutoff_sequence, 0)
          ) then
          match_outcome := 'before_activation';
        elsif not subject_present then
          match_outcome := 'subject_gone';
        elsif not wants_follow_ups then
          match_outcome := 'follow_ups_declined';
        else
          if candidate.subject_type = 'quote' then
            match_outcome := private.automation_conditions_outcome(
              match_row.definition, candidate.organization_id, quote_row.status, candidate.payload
            );
          elsif jsonb_array_length(coalesce(match_row.definition -> 'conditions', '[]'::jsonb)) > 0 then
            match_outcome := 'condition_unavailable';
          else
            match_outcome := 'pass';
          end if;

          if match_outcome = 'pass' then
            insert into private.automation_enrollments (
              organization_id, recipe_id, recipe_version_id, subject_type, subject_id,
              trigger_event_id, source, re_entry_key, context, expires_at, anchor_at
            ) values (
              candidate.organization_id, match_row.recipe_id, match_row.current_version_id,
              candidate.subject_type, candidate.subject_id, candidate.id, 'event',
              re_entry_key, candidate.payload, enrollment_expires_at,
              candidate.occurred_at
            )
            on conflict do nothing
            returning id into new_enrollment_id;

            if new_enrollment_id is null then
              match_outcome := 'already_enrolled';
            else
              match_outcome := 'enrolled';
              insert into private.automation_work_items (
                organization_id, enrollment_id, step_index, due_at, available_at
              ) values (
                candidate.organization_id, new_enrollment_id, 0, now(), now()
              )
              on conflict do nothing;
            end if;
          end if;
        end if;

        insert into private.automation_event_matches (
          event_id, organization_id, recipe_id, recipe_version_id, outcome, enrollment_id
        ) values (
          candidate.id, candidate.organization_id, match_row.recipe_id, match_row.current_version_id,
          match_outcome, new_enrollment_id
        )
        on conflict (event_id, recipe_id) do nothing;
      end loop;

      update private.automation_events
      set processed_at = now(), processing_error = null
      where id = candidate.id;
      processed_count := processed_count + 1;

    exception
      when others then
        update private.automation_events
        set processing_attempts = coalesce(processing_attempts, 0) + 1,
          processing_error = left(coalesce(sqlerrm, 'unknown error'), 1000),
          available_at = now() + private.automation_retry_delay(coalesce(processing_attempts, 0) + 1),
          processed_at = case
            when coalesce(processing_attempts, 0) + 1 >= max_processing_attempts then now()
            else processed_at
          end
        where id = candidate.id;
    end;
  end loop;

  return processed_count;
end;
$$;


ALTER FUNCTION "public"."intake_automation_events"("p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."intake_automation_events"("p_batch_size" integer) IS 'Bounded, replay-safe drain: unprocessed automation events become enrollments plus one first due-work item, or a recorded reason why not. Quotes honour the client''s quote-follow-up preference; a website inquiry (form submission or chat session) enrolls at most once per recipe. Enrollments anchor on the original fact. Service role only.';



CREATE OR REPLACE FUNCTION "public"."invoice_batch_deliverable_page"("target_organization_id" "uuid", "cursor_created" timestamp with time zone DEFAULT NULL::timestamp with time zone, "cursor_id" "uuid" DEFAULT NULL::"uuid", "page_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "invoice_number" integer, "subject" "text", "currency_code" "text", "due_date" "date", "issued_at" timestamp with time zone, "created_at" timestamp with time zone, "derived_status" "text", "revision" integer, "client_id" "uuid", "client_display_name" "text", "client_company_name" "text", "has_email" boolean, "last_sent_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  today date;
begin
  if not private.member_has_permission(target_organization_id, caller, 'invoices.view') then
    raise exception 'You do not have access to these invoices.' using errcode = 'insufficient_privilege';
  end if;
  if page_limit is null or page_limit < 1 or page_limit > 50 then
    page_limit := 20;
  end if;
  today := private.organization_today(target_organization_id);

  return query
    select
      invoice.id,
      invoice.invoice_number,
      invoice.subject,
      invoice.currency_code,
      invoice.due_date,
      invoice.issued_at,
      invoice.created_at,
      label.derived_status,
      invoice.revision,
      invoice.client_id,
      client.display_name as client_display_name,
      client.company_name as client_company_name,
      exists (
        select 1 from public.client_contact_methods as method
        where method.client_id = invoice.client_id and method.kind = 'email'
      ) as has_email,
      (
        select max(intent.created_at) from public.communication_delivery_intents as intent
        where intent.organization_id = invoice.organization_id and intent.invoice_id = invoice.id
      ) as last_sent_at
    from public.invoices as invoice
    left join public.clients as client
      on client.organization_id = invoice.organization_id and client.id = invoice.client_id
    left join lateral (
      select coalesce(sum(case when entry.entry_type = 'applied'
        then entry.amount_minor else -entry.amount_minor end), 0)::bigint as applied_minor
      from public.invoice_payment_allocations as entry
      where entry.organization_id = invoice.organization_id and entry.invoice_id = invoice.id
    ) as allocation on true
    cross join lateral (
      select private.invoice_live_status(
        invoice.voided_at, invoice.written_off_at, invoice.issued_at, invoice.recognized_at,
        invoice.marked_received_at, invoice.total_minor, allocation.applied_minor, invoice.due_date, today
      ) as derived_status
    ) as label
    where invoice.organization_id = target_organization_id
      and invoice.replaced_at is null
      and label.derived_status in ('draft', 'awaiting_payment', 'past_due')
      and (
        cursor_created is null or cursor_id is null
        or invoice.created_at < cursor_created
        or (invoice.created_at = cursor_created and invoice.id < cursor_id)
      )
    order by invoice.created_at desc, invoice.id desc
    limit page_limit;
end;
$$;


ALTER FUNCTION "public"."invoice_batch_deliverable_page"("target_organization_id" "uuid", "cursor_created" timestamp with time zone, "cursor_id" "uuid", "page_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."invoice_batch_deliverable_page"("target_organization_id" "uuid", "cursor_created" timestamp with time zone, "cursor_id" "uuid", "page_limit" integer) IS 'One keyset-paged page of invoices eligible for batch delivery (draft, awaiting payment, past due), newest first. Definer so status shows without invoices.view_price; reuses private.invoice_live_status. Adds revision, has_email and last_sent_at for the picker. Checks invoices.view and scopes to one organization.';



CREATE OR REPLACE FUNCTION "public"."invoice_customer_preview"("target_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  invoice_row public.invoices;
  can_see_price boolean;
  applied_minor bigint;
  derived_status text;
  business_name text;
begin
  select * into invoice_row from public.invoices where id = target_invoice_id;
  if invoice_row.id is null
     or not private.member_has_permission(invoice_row.organization_id, caller, 'invoices.view') then
    raise exception 'You do not have access to this invoice.' using errcode = 'insufficient_privilege';
  end if;

  can_see_price := private.member_has_permission(
    invoice_row.organization_id, caller, 'invoices.view_price');

  select coalesce(sum(case when entry.entry_type = 'applied'
    then entry.amount_minor else -entry.amount_minor end), 0)::bigint
  into applied_minor
  from public.invoice_payment_allocations as entry
  where entry.organization_id = invoice_row.organization_id and entry.invoice_id = invoice_row.id;

  derived_status := case
    when invoice_row.replaced_at is not null then invoice_row.frozen_status_label
    else private.invoice_live_status(
      invoice_row.voided_at, invoice_row.written_off_at, invoice_row.issued_at, invoice_row.recognized_at,
      invoice_row.marked_received_at, invoice_row.total_minor, applied_minor, invoice_row.due_date,
      private.organization_today(invoice_row.organization_id))
  end;

  select organization.name into business_name
  from public.organizations as organization
  where organization.id = invoice_row.organization_id;

  return jsonb_build_object(
    'document', private.invoice_customer_document(
      invoice_row, business_name, derived_status, can_see_price),
    'preview', jsonb_build_object(
      'is_issued', invoice_row.issued_at is not null,
      'is_replaced', invoice_row.replaced_at is not null,
      'prices_withheld', not can_see_price
    )
  );
end;
$$;


ALTER FUNCTION "public"."invoice_customer_preview"("target_invoice_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."invoice_customer_preview"("target_invoice_id" "uuid") IS 'Preview as client. Returns the same customer document the token page renders, for a signed-in member with invoices.view, without creating a link. Amounts withheld unless the member holds invoices.view_price.';



CREATE OR REPLACE FUNCTION "public"."invoice_detail"("target_organization_id" "uuid", "target_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  can_see_price boolean;
  today date;
  invoice_row public.invoices;
  applied_minor bigint;
  derived_status text;
  money jsonb;
  payment_history jsonb;
  current_document jsonb;
  document_history jsonb;
begin
  if not private.member_has_permission(target_organization_id, caller, 'invoices.view') then
    raise exception 'You do not have access to these invoices.' using errcode = 'insufficient_privilege';
  end if;
  can_see_price := private.member_has_permission(target_organization_id, caller, 'invoices.view_price');
  today := private.organization_today(target_organization_id);

  select * into invoice_row
  from public.invoices
  where organization_id = target_organization_id and id = target_invoice_id;
  if not found then
    raise exception 'That invoice could not be found.' using errcode = 'P0404';
  end if;

  select coalesce(sum(case when entry.entry_type = 'applied'
    then entry.amount_minor else -entry.amount_minor end), 0)::bigint
  into applied_minor
  from public.invoice_payment_allocations as entry
  where entry.organization_id = target_organization_id and entry.invoice_id = target_invoice_id;

  derived_status := case
    when invoice_row.replaced_at is not null then invoice_row.frozen_status_label
    else private.invoice_live_status(
      invoice_row.voided_at, invoice_row.written_off_at, invoice_row.issued_at, invoice_row.recognized_at,
      invoice_row.marked_received_at, invoice_row.total_minor, applied_minor, invoice_row.due_date, today)
  end;

  if can_see_price then
    money := jsonb_build_object(
      'subtotal_minor', invoice_row.subtotal_minor,
      'discount_minor', invoice_row.discount_minor,
      'discount_name', invoice_row.discount_name,
      'discount_type', invoice_row.discount_type,
      'discount_value', invoice_row.discount_value,
      'tax_minor', invoice_row.tax_minor,
      'tax_source', invoice_row.tax_source,
      'tax_name', invoice_row.tax_name,
      'tax_rate_id', invoice_row.tax_rate_id,
      'tax_rate_basis_points', invoice_row.tax_rate_basis_points,
      'total_minor', invoice_row.total_minor,
      'allocated_minor', applied_minor,
      'remaining_minor', invoice_row.total_minor - applied_minor
    );

    -- The bill's money history: one row per application/unapplication, newest last so the list reads
    -- top-to-bottom as it happened. A source is either a manual receipt (client_payment_events) or a reused
    -- quote deposit (quote_deposit_events); exactly one side of the two left joins is ever populated, per
    -- invoice_payment_allocations_one_source. Gated the same as money -- this is money, not just a fact of
    -- the bill's existence.
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', allocation.id,
      'payment_event_id', allocation.payment_event_id,
      'entry_type', allocation.entry_type,
      'amount_minor', allocation.amount_minor,
      'created_at', allocation.created_at,
      'source', case when allocation.deposit_event_id is not null then 'deposit' else 'payment' end,
      'method', coalesce(payment.method, deposit.method),
      'payment_date', coalesce(payment.payment_date, deposit.created_at::date),
      'reference', coalesce(payment.reference, deposit.reference),
      'note', coalesce(payment.note, deposit.note),
      'reason', allocation.reason
    ) order by allocation.created_at, allocation.id), '[]'::jsonb)
    into payment_history
    from public.invoice_payment_allocations as allocation
    left join public.client_payment_events as payment
      on payment.organization_id = target_organization_id and payment.id = allocation.payment_event_id
    left join public.quote_deposit_events as deposit
      on deposit.organization_id = target_organization_id and deposit.id = allocation.deposit_event_id
    where allocation.organization_id = target_organization_id
      and allocation.invoice_id = target_invoice_id;

    -- The document's own edit history. `before` is the snapshot the event itself carries; `after` is the
    -- next edit's `before`, or -- for the newest edit -- the document as it stands right now. Empty on a
    -- draft (nothing has frozen yet, so retain_prior_invoice_document never wrote a row) and empty on an
    -- issued bill nobody has edited since.
    current_document := private.invoice_document_snapshot(invoice_row.id);

    select coalesce(jsonb_agg(jsonb_build_object(
      'id', ordered.id,
      'created_at', ordered.created_at,
      'actor_name', profile.full_name,
      'reason', ordered.reason,
      'before', ordered.prior_document_snapshot,
      'after', coalesce(ordered.next_snapshot, current_document)
    ) order by ordered.created_at desc, ordered.id desc), '[]'::jsonb)
    into document_history
    from (
      select event.id, event.created_at, event.reason, event.actor_id, event.prior_document_snapshot,
             lead(event.prior_document_snapshot) over (order by event.created_at, event.id) as next_snapshot
      from public.invoice_events as event
      where event.organization_id = target_organization_id
        and event.invoice_id = target_invoice_id
        and event.event_type = 'invoice.document_edited'
    ) as ordered
    left join public.profiles as profile on profile.id = ordered.actor_id;
  else
    money := null;
    payment_history := null;
    document_history := null;
  end if;

  return jsonb_build_object(
    'invoice', jsonb_build_object(
      'id', invoice_row.id,
      'invoice_number', invoice_row.invoice_number,
      'revision', invoice_row.revision,
      'subject', invoice_row.subject,
      'currency_code', invoice_row.currency_code,
      'issue_date', invoice_row.issue_date,
      'due_date', invoice_row.due_date,
      'due_date_source', invoice_row.due_date_source,
      'payment_term_snapshot', invoice_row.payment_term_snapshot,
      'contract_disclaimer', invoice_row.contract_disclaimer,
      'customer_snapshot', invoice_row.customer_snapshot,
      'billing_address_snapshot', invoice_row.billing_address_snapshot,
      'service_properties', invoice_row.service_properties,
      'issued_at', invoice_row.issued_at,
      'issue_method', invoice_row.issue_method,
      'voided_at', invoice_row.voided_at,
      'void_reason', invoice_row.void_reason,
      'void_note', invoice_row.void_note,
      'written_off_at', invoice_row.written_off_at,
      'write_off_note', invoice_row.write_off_note,
      'marked_received_at', invoice_row.marked_received_at,
      'recognized_at', invoice_row.recognized_at,
      'replaced_at', invoice_row.replaced_at,
      'replaced_by_invoice_id', invoice_row.replaced_by_invoice_id,
      'predecessor_invoice_id', invoice_row.predecessor_invoice_id,
      'replacement_kind', invoice_row.replacement_kind,
      'is_replaced', invoice_row.replaced_at is not null,
      'derived_status', derived_status,
      'client_id', invoice_row.client_id,
      'created_at', invoice_row.created_at
    ),
    'client', (
      select case when client.id is null then null else jsonb_build_object(
        'id', client.id,
        'display_name', client.display_name,
        'company_name', client.company_name,
        'email', (
          select lower(trim(method.value))
          from public.client_contact_methods as method
          where method.organization_id = target_organization_id
            and method.client_id = client.id
            and method.kind = 'email'
          order by method.is_primary desc, method.created_at
          limit 1
        )
      ) end
      from public.clients as client
      where client.organization_id = target_organization_id and client.id = invoice_row.client_id
    ),
    'money', money,
    'payment_history', payment_history,
    'document_history', document_history,
    'progress', private.invoice_progress_context(invoice_row),
    'delivery', jsonb_build_object(
      'last_sent', (
        select case when intent.id is null then null else jsonb_build_object(
          'sent_at', intent.created_at,
          'status', intent.status,
          'recipient_email', intent.recipient_email
        ) end
        from public.communication_delivery_intents as intent
        where intent.organization_id = target_organization_id and intent.invoice_id = target_invoice_id
        order by intent.created_at desc, intent.id desc
        limit 1
      ),
      'views', (
        select jsonb_build_object(
          'first_viewed_at', min(link.first_viewed_at),
          'last_viewed_at', max(link.last_viewed_at),
          'view_count', coalesce(sum(link.view_count), 0)
        )
        from public.invoice_access_links as link
        where link.organization_id = target_organization_id and link.invoice_id = target_invoice_id
      )
    ),
    'lines', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', line.id,
        'position', line.position,
        'line_kind', line.line_kind,
        'category', line.category,
        'name', line.name,
        'description', line.description,
        'unit_label', line.unit_label,
        'quantity', line.quantity,
        'is_taxable', line.is_taxable,
        'service_date', line.service_date,
        'unit_price_minor', case when can_see_price then line.unit_price_minor else null end,
        'line_total_minor', case when can_see_price then line.line_total_minor else null end,
        'progress_original_amount_minor',
          case when can_see_price then line.progress_original_amount_minor else null end
      ) order by line.position, line.id), '[]'::jsonb)
      from public.invoice_lines as line
      where line.organization_id = target_organization_id and line.invoice_id = target_invoice_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."invoice_detail"("target_organization_id" "uuid", "target_invoice_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."invoice_detail"("target_organization_id" "uuid", "target_invoice_id" "uuid") IS 'One whole invoice for the detail screen: its frozen document, derived contract status, revision, money and payment_history (both gated on invoices.view_price), a delivery block with the last email sent and whether the customer has opened it, the client''s email, and the void / write-off notes. Definer; checks invoices.view and scopes to the one organization.';



CREATE OR REPLACE FUNCTION "public"."invoice_list_page"("target_organization_id" "uuid", "search_like" "text" DEFAULT NULL::"text", "search_number" bigint DEFAULT NULL::bigint, "status_filter" "text"[] DEFAULT NULL::"text"[], "sort_key" "text" DEFAULT 'created'::"text", "sort_dir" "text" DEFAULT 'desc'::"text", "created_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "created_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "cursor_created" timestamp with time zone DEFAULT NULL::timestamp with time zone, "cursor_number" bigint DEFAULT NULL::bigint, "cursor_id" "uuid" DEFAULT NULL::"uuid", "page_limit" integer DEFAULT 25, "client_id_filter" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "invoice_number" integer, "subject" "text", "currency_code" "text", "issue_date" "date", "due_date" "date", "issued_at" timestamp with time zone, "created_at" timestamp with time zone, "is_replaced" boolean, "derived_status" "text", "client_id" "uuid", "client_display_name" "text", "client_company_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  caller uuid := (select auth.uid());
  today date;
  ascending boolean := lower(sort_dir) = 'asc';
  sort_column text;
  comparison text;
  seek_clause text := '';
  statement text;
begin
  if not private.member_has_permission(target_organization_id, caller, 'invoices.view') then
    raise exception 'You do not have access to these invoices.' using errcode = 'insufficient_privilege';
  end if;
  if page_limit is null or page_limit < 1 or page_limit > 50 then
    page_limit := 25;
  end if;
  today := private.organization_today(target_organization_id);

  -- Whitelisted, never interpolated from caller text: only these two columns and two directions are ever
  -- placed into the statement, and every value travels as a bound parameter.
  sort_column := case when sort_key = 'number' then 'invoice.invoice_number' else 'invoice.created_at' end;
  comparison := case when ascending then '>' else '<' end;

  if sort_key = 'number' and cursor_number is not null and cursor_id is not null then
    seek_clause := format(
      ' and (invoice.invoice_number %1$s $10 or (invoice.invoice_number = $10 and invoice.id %1$s $11))',
      comparison
    );
  elsif sort_key <> 'number' and cursor_created is not null and cursor_id is not null then
    seek_clause := format(
      ' and (invoice.created_at %1$s $9 or (invoice.created_at = $9 and invoice.id %1$s $11))',
      comparison
    );
  end if;

  statement := format($q$
    select
      invoice.id,
      invoice.invoice_number,
      invoice.subject,
      invoice.currency_code,
      invoice.issue_date,
      invoice.due_date,
      invoice.issued_at,
      invoice.created_at,
      invoice.replaced_at is not null as is_replaced,
      label.derived_status,
      invoice.client_id,
      client.display_name as client_display_name,
      client.company_name as client_company_name
    from public.invoices as invoice
    left join public.clients as client
      on client.organization_id = invoice.organization_id and client.id = invoice.client_id
    left join lateral (
      select coalesce(sum(case when entry.entry_type = 'applied'
        then entry.amount_minor else -entry.amount_minor end), 0)::bigint as applied_minor
      from public.invoice_payment_allocations as entry
      where entry.organization_id = invoice.organization_id and entry.invoice_id = invoice.id
    ) as allocation on true
    cross join lateral (
      select case
        when invoice.replaced_at is not null then invoice.frozen_status_label
        else private.invoice_live_status(
          invoice.voided_at, invoice.written_off_at, invoice.issued_at, invoice.recognized_at,
          invoice.marked_received_at, invoice.total_minor, allocation.applied_minor, invoice.due_date, $2)
      end as derived_status
    ) as label
    where invoice.organization_id = $1
      and ($3::text is null or invoice.subject ilike $3
           or ($4::bigint is not null and invoice.invoice_number = $4))
      and ($5::timestamptz is null or invoice.created_at >= $5)
      and ($6::timestamptz is null or invoice.created_at <= $6)
      and ($7::text[] is null or label.derived_status = any($7))
      and ($12::uuid is null or invoice.client_id = $12)
      %1$s
    order by %2$s %3$s, invoice.id %3$s
    limit $8
  $q$, seek_clause, sort_column, case when ascending then 'asc' else 'desc' end);

  return query execute statement
    using target_organization_id, today, search_like, search_number, created_from, created_to,
          status_filter, page_limit, cursor_created, cursor_number, cursor_id, client_id_filter;
end;
$_$;


ALTER FUNCTION "public"."invoice_list_page"("target_organization_id" "uuid", "search_like" "text", "search_number" bigint, "status_filter" "text"[], "sort_key" "text", "sort_dir" "text", "created_from" timestamp with time zone, "created_to" timestamp with time zone, "cursor_created" timestamp with time zone, "cursor_number" bigint, "cursor_id" "uuid", "page_limit" integer, "client_id_filter" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."invoice_list_page"("target_organization_id" "uuid", "search_like" "text", "search_number" bigint, "status_filter" "text"[], "sort_key" "text", "sort_dir" "text", "created_from" timestamp with time zone, "created_to" timestamp with time zone, "cursor_created" timestamp with time zone, "cursor_number" bigint, "cursor_id" "uuid", "page_limit" integer, "client_id_filter" "uuid") IS 'One keyset-paged page of the Invoices list, with the derived contract status computed set-based. Definer so a reader without invoices.view_price still sees a bill''s status without ever selecting its amount; checks invoices.view and scopes every row to the one organization. client_id_filter narrows to one client''s bills (invoices_client_idx) -- used by the payment-move picker, optional everywhere else. No money -- that comes from public.invoice_money.';



CREATE OR REPLACE FUNCTION "public"."invoice_money"("target_invoice_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  organizations uuid[];
  org uuid;
  answer jsonb;
begin
  if target_invoice_ids is null or cardinality(target_invoice_ids) = 0 then
    return '{}'::jsonb;
  end if;

  select array_agg(distinct invoice.organization_id) into organizations
  from public.invoices as invoice
  where invoice.id = any(target_invoice_ids);

  if organizations is null then
    return '{}'::jsonb;
  end if;
  if array_length(organizations, 1) > 1 then
    raise exception 'Those invoices do not belong to one organization.' using errcode = 'check_violation';
  end if;
  org := organizations[1];

  if not private.member_has_permission(org, caller, 'invoices.view') then
    raise exception 'You do not have access to these invoices.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(org, caller, 'invoices.view_price') then
    return '{}'::jsonb;
  end if;

  select coalesce(jsonb_object_agg(invoice.id::text, jsonb_build_object(
      'currency_code', invoice.currency_code,
      'subtotal_minor', invoice.subtotal_minor,
      'discount_minor', invoice.discount_minor,
      'discount_name', invoice.discount_name,
      'discount_type', invoice.discount_type,
      'discount_value', invoice.discount_value,
      'tax_minor', invoice.tax_minor,
      'tax_rate_basis_points', invoice.tax_rate_basis_points,
      'total_minor', invoice.total_minor,
      'allocated_minor', allocation.applied_minor,
      'remaining_minor', invoice.total_minor - allocation.applied_minor
    )), '{}'::jsonb)
  into answer
  from public.invoices as invoice
  cross join lateral (
    select coalesce(
      sum(case when entry.entry_type = 'applied' then entry.amount_minor else -entry.amount_minor end), 0
    )::bigint as applied_minor
    from public.invoice_payment_allocations as entry
    where entry.organization_id = invoice.organization_id
      and entry.invoice_id = invoice.id
  ) as allocation
  where invoice.organization_id = org
    and invoice.id = any(target_invoice_ids);

  return answer;
end;
$$;


ALTER FUNCTION "public"."invoice_money"("target_invoice_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."invoice_money"("target_invoice_ids" "uuid"[]) IS 'Invoice amounts and what is left on them, for callers with price visibility. One permission check per call rather than per row, and one place that subtracts applied money from a total.';



CREATE OR REPLACE FUNCTION "public"."invoice_online_payment_context"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  link_row public.invoice_access_links;
  invoice_row public.invoices;
  settings_row public.organization_settings;
  connection_row public.payment_stripe_connections;
  lifecycle text;
  remaining bigint;
  processing bigint;
  recent_paid bigint;
  is_progress boolean;
  unavailable text;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row from public.invoice_access_links where token_hash = supplied_token_hash;
  if link_row.id is null
     or link_row.revoked_at is not null
     or (link_row.expires_at is not null and link_row.expires_at <= now()) then
    return null;
  end if;

  select * into invoice_row from public.invoices where id = link_row.invoice_id;
  if invoice_row.id is null
     or invoice_row.issued_at is null
     or invoice_row.voided_at is not null
     or invoice_row.replaced_at is not null then
    return null;
  end if;

  select organization.lifecycle_status into lifecycle
  from public.organizations as organization where organization.id = invoice_row.organization_id;
  select * into settings_row
  from public.organization_settings where organization_id = invoice_row.organization_id;
  select * into connection_row
  from public.payment_stripe_connections where organization_id = invoice_row.organization_id;

  remaining := invoice_row.total_minor
    - private.invoice_allocated_minor(invoice_row.organization_id, invoice_row.id);

  select coalesce(sum(checkout.amount_minor), 0)::bigint into processing
  from public.payment_stripe_checkouts as checkout
  where checkout.organization_id = invoice_row.organization_id
    and checkout.invoice_id = invoice_row.id
    and checkout.status = 'processing';

  select coalesce(sum(checkout.amount_minor + checkout.tip_minor), 0)::bigint into recent_paid
  from public.payment_stripe_checkouts as checkout
  where checkout.organization_id = invoice_row.organization_id
    and checkout.invoice_id = invoice_row.id
    and checkout.status = 'paid'
    and checkout.completed_at > now() - interval '30 minutes';

  is_progress := private.invoice_progress_context(invoice_row) is not null;

  unavailable := case
    when lifecycle is distinct from 'active' then 'business_unavailable'
    when connection_row.id is null then 'not_connected'
    when not settings_row.online_invoice_payments_enabled then 'turned_off'
    when not invoice_row.is_effective_receivable or invoice_row.written_off_at is not null then 'closed'
    when remaining - processing <= 0 then 'nothing_owed'
  end;

  return jsonb_build_object(
    'organization_id', invoice_row.organization_id,
    'invoice_id', invoice_row.id,
    'client_id', invoice_row.client_id,
    'invoice_number', invoice_row.invoice_number,
    'currency_code', invoice_row.currency_code,
    'available', unavailable is null,
    'unavailable_reason', unavailable,
    'balance_minor', greatest(remaining - processing, 0),
    'processing_minor', processing,
    'recent_paid_minor', recent_paid,
    'partial_allowed', invoice_row.online_partial_payments_allowed and not is_progress,
    'tips_enabled', coalesce(settings_row.online_tips_enabled, false),
    'tip_base_minor', greatest(invoice_row.subtotal_minor - invoice_row.discount_minor, 0),
    'livemode', connection_row.livemode,
    'stripe_account_id', connection_row.stripe_account_id,
    'pay_by_app', jsonb_build_object(
      'venmo_username', settings_row.pay_by_app_venmo_username,
      'cash_app_cashtag', settings_row.pay_by_app_cash_app_cashtag,
      'paypal_me_username', settings_row.pay_by_app_paypal_me_username,
      'zelle_contact', settings_row.pay_by_app_zelle_contact,
      'e_transfer_email', settings_row.pay_by_app_e_transfer_email,
      'bank_transfer_instructions', settings_row.pay_by_app_bank_transfer_instructions
    )
  );
end;
$$;


ALTER FUNCTION "public"."invoice_online_payment_context"("supplied_token_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invoice_status_counts"("target_organization_id" "uuid") RETURNS TABLE("derived_status" "text", "total" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  today date;
begin
  if not private.member_has_permission(target_organization_id, caller, 'invoices.view') then
    raise exception 'You do not have access to these invoices.' using errcode = 'insufficient_privilege';
  end if;
  today := private.organization_today(target_organization_id);

  return query
    select label.derived_status, count(*)::bigint as total
    from public.invoices as invoice
    left join lateral (
      select coalesce(sum(case when entry.entry_type = 'applied'
        then entry.amount_minor else -entry.amount_minor end), 0)::bigint as applied_minor
      from public.invoice_payment_allocations as entry
      where entry.organization_id = invoice.organization_id and entry.invoice_id = invoice.id
    ) as allocation on true
    cross join lateral (
      select case
        when invoice.replaced_at is not null then invoice.frozen_status_label
        else private.invoice_live_status(
          invoice.voided_at, invoice.written_off_at, invoice.issued_at, invoice.recognized_at,
          invoice.marked_received_at, invoice.total_minor, allocation.applied_minor, invoice.due_date, today)
      end as derived_status
    ) as label
    where invoice.organization_id = target_organization_id
    group by label.derived_status;
end;
$$;


ALTER FUNCTION "public"."invoice_status_counts"("target_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."invoice_status_counts"("target_organization_id" "uuid") IS 'Live count of this organization''s invoices by derived contract status, for the Invoices overview card. Derived from the same rule as public.invoice_list_page.';



CREATE OR REPLACE FUNCTION "public"."issue_client_marketing_unsubscribe_link"("target_organization_id" "uuid", "target_client_contact_method_id" "uuid", "supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  method_row public.client_contact_methods;
  link_row public.client_marketing_unsubscribe_links;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    raise exception 'An unsubscribe link needs a full-length token.' using errcode = 'check_violation';
  end if;

  select * into method_row
  from public.client_contact_methods
  where organization_id = target_organization_id
    and id = target_client_contact_method_id
    and kind = 'email';

  if method_row.id is null then
    raise exception 'That email address is not on this organization.' using errcode = 'check_violation';
  end if;

  insert into public.client_marketing_unsubscribe_links (
    organization_id, client_id, client_contact_method_id, token_hash
  ) values (
    method_row.organization_id, method_row.client_id, method_row.id, supplied_token_hash
  )
  returning * into link_row;

  return jsonb_build_object(
    'unsubscribe_link_id', link_row.id,
    'client_id', link_row.client_id,
    'client_contact_method_id', link_row.client_contact_method_id,
    'issued_at', link_row.issued_at
  );
end;
$$;


ALTER FUNCTION "public"."issue_client_marketing_unsubscribe_link"("target_organization_id" "uuid", "target_client_contact_method_id" "uuid", "supplied_token_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_issue_method" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  settings_row public.organization_settings;
  invoice_row public.invoices;
  issued public.invoices;
begin
  if caller is null then
    raise exception 'You must be signed in to issue an invoice.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.send') then
    raise exception 'You do not have access to issue an invoice.' using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  if new_issue_method not in ('sent', 'marked_sent') then
    raise exception 'An invoice is issued by sending it or by marking it sent.'
      using errcode = 'check_violation';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'issue_invoice', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for share;
  if not found then
    raise exception 'That organization could not be found.' using errcode = 'P0404';
  end if;

  invoice_row := private.lock_invoice_for_edit(
    target_organization_id, target_invoice_id, expected_revision, 'invoices.send'
  );

  if invoice_row.issued_at is not null then
    raise exception 'This invoice has already been issued.' using errcode = 'check_violation';
  end if;
  if invoice_row.recognized_at is not null then
    raise exception 'This invoice was already settled and cannot be issued.'
      using errcode = 'check_violation';
  end if;
  if invoice_row.currency_code is distinct from settings_row.currency_code then
    raise exception 'This draft was written in a different currency. Refresh it before issuing it.'
      using errcode = 'check_violation';
  end if;
  if not exists (
    select 1 from public.invoice_lines
    where organization_id = target_organization_id and invoice_id = target_invoice_id
  ) then
    raise exception 'An invoice needs at least one line before it can be issued.'
      using errcode = 'check_violation';
  end if;

  update public.invoices
  set issued_at = now(),
      issued_by = caller,
      issue_method = new_issue_method,
      document_frozen_at = now(),
      revision = invoice_row.revision + 1
  where organization_id = target_organization_id and id = target_invoice_id
  returning * into issued;

  perform private.record_invoice_event(
    target_organization_id, issued.id, issued.invoice_number, issued.client_id,
    'invoice.issued', caller, issued.revision, null,
    jsonb_build_object('method', new_issue_method), false, null
  );

  return private.complete_invoice_command(
    target_organization_id, 'issue_invoice', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', issued.id,
      'invoice_number', issued.invoice_number,
      'revision', issued.revision,
      'issued_at', issued.issued_at,
      'issue_method', issued.issue_method,
      'due_date', issued.due_date
    )
  );
end;
$$;


ALTER FUNCTION "public"."issue_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_issue_method" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."issue_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_issue_method" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Turns a draft into a receivable and freezes its document. Transport is a separate step: this records the issue fact for both sending and marking as sent, and a retry returns the first result.';



CREATE OR REPLACE FUNCTION "public"."issue_invoice_access_link"("target_invoice_id" "uuid", "supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  invoice_row public.invoices;
  client_name text;
  client_email text;
  link_row public.invoice_access_links;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    raise exception 'A customer link needs a full-length token.' using errcode = 'check_violation';
  end if;

  select * into invoice_row from public.invoices where id = target_invoice_id for update;

  if invoice_row.id is null
     or not private.member_has_permission(invoice_row.organization_id, caller, 'invoices.send') then
    raise exception 'You do not have access to share this invoice.' using errcode = 'insufficient_privilege';
  end if;

  if invoice_row.issued_at is null then
    raise exception 'Send this invoice before creating a customer link.' using errcode = 'check_violation';
  end if;
  if invoice_row.voided_at is not null or invoice_row.replaced_at is not null then
    raise exception 'This invoice can no longer be shared.' using errcode = 'check_violation';
  end if;

  select client.display_name,
         (
           select lower(trim(method.value))
           from public.client_contact_methods as method
           where method.organization_id = invoice_row.organization_id
             and method.client_id = invoice_row.client_id
             and method.kind = 'email'
           order by method.is_primary desc, method.created_at
           limit 1
         )
    into client_name, client_email
  from public.clients as client
  where client.organization_id = invoice_row.organization_id
    and client.id = invoice_row.client_id;

  if client_email is null then
    raise exception 'Add an email address to this client before creating a customer link.'
      using errcode = 'check_violation';
  end if;

  update public.invoice_access_links
  set revoked_at = now(), revoked_reason = 'rotated'
  where organization_id = invoice_row.organization_id
    and invoice_id = invoice_row.id
    and revoked_at is null;

  insert into public.invoice_access_links (
    organization_id, invoice_id, recipient_name, recipient_email, token_hash, issued_by
  ) values (
    invoice_row.organization_id, invoice_row.id,
    coalesce(nullif(trim(client_name), ''), client_email), client_email,
    supplied_token_hash, caller
  )
  returning * into link_row;

  perform private.record_invoice_event(
    invoice_row.organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.link_issued', caller, invoice_row.revision, null,
    jsonb_build_object('invoice_access_link_id', link_row.id, 'recipient_email', client_email)
  );

  return jsonb_build_object(
    'invoice_id', invoice_row.id,
    'invoice_access_link_id', link_row.id,
    'recipient_name', link_row.recipient_name,
    'recipient_email', link_row.recipient_email,
    'issued_at', link_row.issued_at,
    'expires_at', link_row.expires_at
  );
end;
$$;


ALTER FUNCTION "public"."issue_invoice_access_link"("target_invoice_id" "uuid", "supplied_token_hash" "bytea") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."issue_invoice_access_link"("target_invoice_id" "uuid", "supplied_token_hash" "bytea") IS 'Creates the customer''s door to an issued invoice and returns everything but the token, which only ever exists in the caller''s response. Rotates the invoice''s live links so asking twice never leaves two open.';



CREATE OR REPLACE FUNCTION "public"."issue_job_report_access_link"("target_job_id" "uuid", "supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  job_row public.jobs;
  report_row public.job_reports;
  business_name text;
  client_name text;
  client_email text;
  link_row public.job_report_access_links;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    raise exception 'A customer link needs a full-length token.' using errcode = 'check_violation';
  end if;

  select * into job_row from public.jobs where id = target_job_id for update;
  if job_row.id is null
     or not private.member_has_permission(job_row.organization_id, caller, 'jobs.edit')
     or not private.can_view_job(job_row.organization_id, target_job_id) then
    raise exception 'You do not have access to share this job.' using errcode = 'insufficient_privilege';
  end if;

  if not private.job_report_has_content(job_row.organization_id, target_job_id) then
    raise exception 'Add something to the work report before creating a customer link.'
      using errcode = 'check_violation';
  end if;

  select client.display_name,
         (
           select lower(trim(method.value))
           from public.client_contact_methods as method
           where method.organization_id = job_row.organization_id
             and method.client_id = job_row.client_id
             and method.kind = 'email'
           order by method.is_primary desc, method.created_at
           limit 1
         )
    into client_name, client_email
  from public.clients as client
  where client.organization_id = job_row.organization_id and client.id = job_row.client_id;

  if client_email is null then
    raise exception 'Add an email address to this client before creating a customer link.'
      using errcode = 'check_violation';
  end if;

  select * into report_row
  from public.job_reports
  where organization_id = job_row.organization_id and job_id = target_job_id;

  select organization.name into business_name
  from public.organizations as organization
  where organization.id = job_row.organization_id;

  update public.job_report_access_links
  set revoked_at = now(), revoked_reason = 'rotated'
  where organization_id = job_row.organization_id
    and job_id = target_job_id
    and revoked_at is null;

  insert into public.job_report_access_links (
    organization_id, job_id, recipient_name, recipient_email, token_hash, issued_by, frozen_document
  ) values (
    job_row.organization_id, target_job_id,
    coalesce(nullif(trim(client_name), ''), client_email), client_email,
    supplied_token_hash, caller,
    private.job_report_customer_document(job_row, business_name, coalesce(report_row.include_price, false))
  )
  returning * into link_row;

  insert into public.activity_events (
    organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
  ) values (
    job_row.organization_id, 'job', target_job_id, 'job.work_report_link_issued',
    'Shared the work report with the customer', caller,
    jsonb_build_object('job_report_access_link_id', link_row.id, 'recipient_email', client_email)
  );

  return jsonb_build_object(
    'job_id', target_job_id,
    'job_report_access_link_id', link_row.id,
    'recipient_name', link_row.recipient_name,
    'recipient_email', link_row.recipient_email,
    'issued_at', link_row.issued_at,
    'expires_at', link_row.expires_at
  );
end;
$$;


ALTER FUNCTION "public"."issue_job_report_access_link"("target_job_id" "uuid", "supplied_token_hash" "bytea") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."issue_job_report_access_link"("target_job_id" "uuid", "supplied_token_hash" "bytea") IS 'Creates the customer''s door to a job''s work report and freezes the current document onto the link at that moment, so a later report edit cannot change what this link shows. Returns everything but the token, which only ever exists in the caller''s response. Rotates the job''s live links so asking twice never leaves two open. Needs jobs.edit and a report with content.';



CREATE OR REPLACE FUNCTION "public"."issue_quote_access_link"("target_quote_id" "uuid", "supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  version_row public.quote_versions;
  recipient_row public.quote_recipients;
  link_row public.quote_access_links;
  client_name text;
  client_email text;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    raise exception 'A customer link needs a full-length token.' using errcode = 'check_violation';
  end if;

  select * into quote_row from public.quotes where id = target_quote_id for update;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.send'
     ) then
    raise exception 'You do not have access to share this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.current_published_version_id is null then
    raise exception 'Send this quote before creating a customer link.' using errcode = 'check_violation';
  end if;

  if quote_row.status = 'archived' then
    raise exception 'An archived quote cannot be shared.' using errcode = 'check_violation';
  end if;

  select * into version_row
  from public.quote_versions
  where id = quote_row.current_published_version_id;

  select client.display_name,
         (
           select lower(trim(method.value))
           from public.client_contact_methods as method
           where method.organization_id = quote_row.organization_id
             and method.client_id = quote_row.client_id
             and method.kind = 'email'
           order by method.is_primary desc, method.created_at
           limit 1
         )
    into client_name, client_email
  from public.clients as client
  where client.organization_id = quote_row.organization_id
    and client.id = quote_row.client_id;

  if client_email is null then
    raise exception 'Add an email address to this client before creating a customer link.'
      using errcode = 'check_violation';
  end if;

  insert into public.quote_recipients (
    organization_id, quote_id, display_name, email, created_by
  ) values (
    quote_row.organization_id, quote_row.id, coalesce(nullif(trim(client_name), ''), client_email),
    client_email, (select auth.uid())
  )
  on conflict (organization_id, quote_id, email) do update
    set display_name = excluded.display_name
  returning * into recipient_row;

  update public.quote_access_links
  set revoked_at = now(), revoked_reason = 'rotated'
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and recipient_id = recipient_row.id
    and revoked_at is null;

  insert into public.quote_access_links (
    organization_id, quote_id, quote_version_id, recipient_id, token_hash, issued_by
  ) values (
    quote_row.organization_id, quote_row.id, version_row.id, recipient_row.id,
    supplied_token_hash, (select auth.uid())
  )
  returning * into link_row;

  insert into public.activity_events (
    organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
  ) values (
    quote_row.organization_id, 'quote', quote_row.id, 'quote.link_issued',
    'Created a customer link for ' || recipient_row.email, (select auth.uid()),
    jsonb_build_object(
      'quote_version_id', version_row.id,
      'version_number', version_row.version_number,
      'quote_access_link_id', link_row.id
    )
  );

  return jsonb_build_object(
    'quote_id', quote_row.id,
    'quote_access_link_id', link_row.id,
    'quote_version_id', version_row.id,
    'version_number', version_row.version_number,
    'recipient_id', recipient_row.id,
    'recipient_name', recipient_row.display_name,
    'recipient_email', recipient_row.email,
    'issued_at', link_row.issued_at,
    'expires_at', link_row.expires_at
  );
end;
$$;


ALTER FUNCTION "public"."issue_quote_access_link"("target_quote_id" "uuid", "supplied_token_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."job_checklists_list"("target_organization_id" "uuid", "target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  checklists jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to view this job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.can_view_job(target_organization_id, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', checklist.id,
        'name', checklist.name,
        'source_template_id', checklist.source_template_id,
        'attached_at', checklist.attached_at,
		'answers_count', coalesce(answer_counts.total, 0),
        'items', coalesce(questions.items, '[]'::jsonb)
      )
      order by checklist.attached_at
    ),
    '[]'::jsonb
  )
  into checklists
  from public.job_checklists as checklist
  left join lateral (
    select jsonb_agg(
      jsonb_build_object(
        'id', item.id,
        'position', item.position,
        'label', item.label,
        'item_type', item.item_type,
        'required', item.required,
        'options', coalesce(to_jsonb(item.options), 'null'::jsonb)
      )
      order by item.position
    ) as items
    from public.job_checklist_items as item
    where item.organization_id = checklist.organization_id and item.job_checklist_id = checklist.id
  ) as questions on true
  left join lateral (
    select count(*) as total
    from public.visit_checklist_answers as answer
    join public.job_checklist_items as item
      on item.organization_id = answer.organization_id and item.id = answer.item_id
    where answer.organization_id = checklist.organization_id
      and item.job_checklist_id = checklist.id
  ) as answer_counts on true
  where checklist.organization_id = target_organization_id
    and checklist.job_id = target_job_id;

  return jsonb_build_object(
    'checklists', checklists,
    'can_edit', private.member_has_permission(target_organization_id, caller, 'jobs.edit')
  );
end;
$$;


ALTER FUNCTION "public"."job_checklists_list"("target_organization_id" "uuid", "target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_checklists_list"("target_organization_id" "uuid", "target_job_id" "uuid") IS 'The checklists attached to one job, with their frozen questions and saved-answer count for the removal warning -- the job page''s card and the source of every visit''s form.';



CREATE OR REPLACE FUNCTION "public"."job_combined_history"("target_job_id" "uuid", "result_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "source" "text", "event_type" "text", "summary" "text", "actor_id" "uuid", "created_at" timestamp with time zone, "metadata" "jsonb", "visit_id" "uuid", "visit_label" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select history.id,
         history.source,
         history.event_type,
         history.summary,
         history.actor_id,
         history.created_at,
         history.metadata,
         history.visit_id,
         history.visit_label
  from (
    select event.id,
           'job_event'::text as source,
           event.event_type,
           null::text as summary,
           event.actor_id,
           event.created_at,
           event.metadata,
           event.related_visit_id as visit_id,
           null::text as visit_label
    from public.job_events as event
    where event.organization_id = (
      select job.organization_id from public.jobs as job where job.id = target_job_id
    )
      and event.job_id = target_job_id

    union all

    select activity.id,
           'field_record'::text as source,
           activity.event_type,
           activity.summary,
           activity.actor_user_id as actor_id,
           activity.created_at,
           activity.metadata,
           null::uuid as visit_id,
           null::text as visit_label
    from public.activity_events as activity
    where activity.organization_id = (
      select job.organization_id from public.jobs as job where job.id = target_job_id
    )
      and activity.entity_type = 'job'
      and activity.entity_id = target_job_id

    union all

    select activity.id,
           'field_record'::text as source,
           activity.event_type,
           activity.summary,
           activity.actor_user_id as actor_id,
           activity.created_at,
           activity.metadata,
           visit.id as visit_id,
           coalesce(
             nullif(trim(visit.title), ''),
             case
               when visit.visit_date is not null then 'Visit on ' || to_char(visit.visit_date, 'Mon FMDD, YYYY')
               else 'Unscheduled visit'
             end
           ) as visit_label
    from public.job_visits as visit
    join public.activity_events as activity
      on activity.entity_type = 'visit'
     and activity.entity_id = visit.id
     and activity.organization_id = visit.organization_id
    where visit.organization_id = (
      select job.organization_id from public.jobs as job where job.id = target_job_id
    )
      and visit.job_id = target_job_id
  ) as history
  order by history.created_at desc, history.id desc
  limit least(greatest(coalesce(result_limit, 100), 1), 100);
$$;


ALTER FUNCTION "public"."job_combined_history"("target_job_id" "uuid", "result_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_combined_history"("target_job_id" "uuid", "result_limit" integer) IS 'Newest Job lifecycle and internal Job/Visit field-record events in one bounded, tenant-scoped timeline. Security invoker: the underlying Jobs and linked-record RLS remains the authority.';



CREATE OR REPLACE FUNCTION "public"."job_costing"("target_organization_id" "uuid", "target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  zone text;
  window_start date;
  window_end date;
  labor_from timestamptz;
  labor_until timestamptz;
  unit_count integer := 0;
  period_price bigint;
  period_cost bigint;
  labor_cost bigint;
  unrated_count integer;
  has_time boolean;
  expense_cost bigint;
  has_labor_line boolean;
  item_cost bigint;
  revenue bigint;
  total_cost bigint;
  profit bigint;
  margin_bp integer;
begin
  if caller is null then
    raise exception 'You must be signed in to view this job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  if not private.member_has_permission(target_organization_id, caller, 'jobs.view_cost') then
    raise exception 'You do not have access to this job''s costs.' using errcode = 'insufficient_privilege';
  end if;

  if current_job.price_basis = 'job_total' then
    select coalesce(sum(entry.cost_total_minor), 0),
           count(*) filter (where entry.cost_per_hour_minor is null),
           count(*) > 0
    into labor_cost, unrated_count, has_time
    from public.job_time_entries as entry
    where entry.organization_id = target_organization_id
      and entry.job_id = target_job_id;

    select coalesce(sum(expense.total_minor), 0)
    into expense_cost
    from public.job_expenses as expense
    where expense.organization_id = target_organization_id
      and expense.job_id = target_job_id;

    select exists (
      select 1
      from public.job_line_items as line
      where line.organization_id = target_organization_id
        and line.job_id = target_job_id
        and line.is_labor
    ) into has_labor_line;

    revenue := current_job.total_minor - current_job.tax_minor;
    total_cost := current_job.cost_minor + labor_cost + expense_cost;
    profit := revenue - total_cost;
    margin_bp := case when revenue > 0
      then round(profit::numeric * 10000 / revenue)::integer
      else null
    end;

    return jsonb_build_object(
      'costing_basis', 'one_off',
      'job_closed', current_job.status <> 'active',
      'revenue_minor', revenue,
      'item_cost_minor', current_job.cost_minor,
      'labor_cost_minor', labor_cost,
      'expense_cost_minor', expense_cost,
      'total_cost_minor', total_cost,
      'profit_minor', profit,
      'margin_basis_points', margin_bp,
      'unrated_labor_count', unrated_count,
      'labor_line_and_time', has_labor_line and has_time
    );
  end if;

  window_end := private.organization_today(target_organization_id);
  window_start := window_end - 29;

  select coalesce(nullif(btrim(settings.timezone), ''), 'UTC') into zone
  from public.organization_settings as settings
  where settings.organization_id = target_organization_id;
  zone := coalesce(zone, 'UTC');

  labor_from := (window_start::timestamp) at time zone zone;
  labor_until := ((window_end + 1)::timestamp) at time zone zone;

  if current_job.price_basis = 'per_visit' then
    with in_window as (
      select visit.id
      from public.job_visits as visit
      where visit.organization_id = target_organization_id
        and visit.job_id = target_job_id
        and visit.completed_at is not null
        and visit.visit_date between window_start and window_end
    ),
    priced_lines as (
      select line.line_total_minor, line.quantity, line.unit_cost_minor, line.is_labor
      from in_window
      cross join lateral private.job_visit_effective_lines(
        target_organization_id, target_job_id, in_window.id
      ) as line
      where line.line_kind = 'priced'
    )
    select
      (select count(*) from in_window)::integer,
      coalesce(sum(priced_lines.line_total_minor), 0),
      coalesce(sum(public.pricing_line_total_minor(
        priced_lines.quantity, priced_lines.unit_cost_minor
      )), 0),
      coalesce(bool_or(priced_lines.is_labor), false)
    into unit_count, revenue, item_cost, has_labor_line
    from priced_lines;

  else
    select count(*)::integer
    into unit_count
    from public.job_invoice_reminders as reminder
    where reminder.organization_id = target_organization_id
      and reminder.job_id = target_job_id
      and reminder.reminder_kind in ('monthly_last_day', 'custom_date')
      and reminder.due_on between window_start and window_end;

    select coalesce(sum(line.line_total_minor), 0),
           coalesce(sum(line.line_cost_total_minor), 0),
           coalesce(bool_or(line.is_labor), false)
    into period_price, period_cost, has_labor_line
    from public.job_line_items as line
    where line.organization_id = target_organization_id
      and line.job_id = target_job_id
      and line.line_kind = 'priced';

    if unit_count > 0 then
      revenue := period_price * unit_count;
      item_cost := period_cost * unit_count;
    else
      revenue := null;
      item_cost := 0;
    end if;
  end if;

  select coalesce(sum(entry.cost_total_minor), 0),
         count(*) filter (where entry.cost_per_hour_minor is null),
         count(*) > 0
  into labor_cost, unrated_count, has_time
  from public.job_time_entries as entry
  where entry.organization_id = target_organization_id
    and entry.job_id = target_job_id
    and entry.started_at >= labor_from
    and entry.started_at < labor_until;

  select coalesce(sum(expense.total_minor), 0)
  into expense_cost
  from public.job_expenses as expense
  where expense.organization_id = target_organization_id
    and expense.job_id = target_job_id
    and expense.expense_date between window_start and window_end;

  total_cost := item_cost + labor_cost + expense_cost;
  profit := case when revenue is null then null else revenue - total_cost end;
  margin_bp := case when revenue is not null and revenue > 0
    then round((revenue - total_cost)::numeric * 10000 / revenue)::integer
    else null
  end;

  return jsonb_build_object(
    'costing_basis', current_job.price_basis,
    'job_closed', current_job.status <> 'active',
    'window_start', window_start,
    'window_end', window_end,
    'unit_kind', case when current_job.price_basis = 'per_visit' then 'visits' else 'periods' end,
    'unit_count', unit_count,
    'revenue_minor', revenue,
    'item_cost_minor', item_cost,
    'labor_cost_minor', labor_cost,
    'expense_cost_minor', expense_cost,
    'total_cost_minor', total_cost,
    'profit_minor', profit,
    'margin_basis_points', margin_bp,
    'unrated_labor_count', unrated_count,
    'labor_line_and_time', has_labor_line and has_time
  );
end;
$$;


ALTER FUNCTION "public"."job_costing"("target_organization_id" "uuid", "target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_costing"("target_organization_id" "uuid", "target_job_id" "uuid") IS 'One job''s costing. A one-off job is measured over its whole life. A recurring job is measured over the last 30 days in the organization''s timezone, pairing costs with the revenue its pricing basis defines: per completed visit, or per billing period. Needs jobs.view_cost. Revenue, profit and margin are null when no period defines revenue in the window.';



CREATE OR REPLACE FUNCTION "public"."job_expenses_list"("target_organization_id" "uuid", "target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  page_size constant integer := 200;
  can_cost boolean;
  can_team boolean;
  can_own boolean;
  job_closed boolean;
  expenses jsonb;
  totals jsonb;
  expense_count integer;
begin
  if caller is null then
    raise exception 'You must be signed in to view this job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.status <> 'active' into job_closed
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  can_cost := private.member_has_permission(target_organization_id, caller, 'jobs.view_cost');
  can_team := private.member_has_permission(target_organization_id, caller, 'expenses.manage_team');
  can_own := private.member_has_permission(target_organization_id, caller, 'expenses.record');

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', visible.id,
          'name', visible.name,
          'accounting_code', visible.accounting_code,
          'description', visible.description,
          'expense_date', visible.expense_date,
          'reimburse_to_user_id', visible.reimburse_to_user_id,
          'reimburse_to_name', visible.reimburse_to_name,
          'created_by', visible.created_by,
          'receipt_count', visible.receipt_count,
          'can_edit', can_team or (visible.created_by = caller and can_own and not job_closed)
        )
        || (case when can_cost then jsonb_build_object('total_minor', visible.total_minor)
              else '{}'::jsonb end)
        order by visible.expense_date desc, visible.id desc
      ),
      '[]'::jsonb
    ),
    count(*)
  into expenses, expense_count
  from (
    select expense.id, expense.name, expense.accounting_code, expense.description, expense.expense_date,
           expense.total_minor, expense.reimburse_to_user_id, expense.created_by,
           profile.full_name as reimburse_to_name,
           (
             select count(*)
             from public.attachments as receipt
             where receipt.organization_id = expense.organization_id
               and receipt.entity_type = 'job_expense'
               and receipt.entity_id = expense.id
           ) as receipt_count
    from public.job_expenses as expense
    left join public.profiles as profile on profile.id = expense.reimburse_to_user_id
    where expense.organization_id = target_organization_id
      and expense.job_id = target_job_id
      and (can_team or (expense.created_by = caller and can_own))
    order by expense.expense_date desc, expense.id desc
    limit page_size
  ) as visible;

  select jsonb_build_object(
    'expense_count', count(*),
    'total_minor', case when can_cost then coalesce(sum(expense.total_minor), 0) else null end
  ) into totals
  from public.job_expenses as expense
  where expense.organization_id = target_organization_id
    and expense.job_id = target_job_id
    and (can_team or (expense.created_by = caller and can_own));

  return jsonb_build_object(
    'expenses', expenses,
    'totals', totals,
    'has_more', (totals->>'expense_count')::integer > expense_count,
    'job_closed', job_closed,
    'can_add', can_team or (can_own and not job_closed),
    'can_manage_team', can_team,
    'can_see_cost', can_cost
  );
end;
$$;


ALTER FUNCTION "public"."job_expenses_list"("target_organization_id" "uuid", "target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_expenses_list"("target_organization_id" "uuid", "target_job_id" "uuid") IS 'One job''s recorded expenses and their total, newest first. A reader with expenses.manage_team sees everyone''s and a reader with only expenses.record sees the ones they recorded. Totals need jobs.view_cost; without it the same rows come back with no money at all.';



CREATE OR REPLACE FUNCTION "public"."job_labor"("target_organization_id" "uuid", "target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  page_size constant integer := 200;
  can_cost boolean;
  can_team boolean;
  can_own boolean;
  job_closed boolean;
  entries jsonb;
  totals jsonb;
  entry_count integer;
begin
  if caller is null then
    raise exception 'You must be signed in to view this job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.status <> 'active' into job_closed
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  can_cost := private.member_has_permission(target_organization_id, caller, 'jobs.view_cost');
  can_team := private.member_has_permission(target_organization_id, caller, 'time.track_team');
  can_own := private.member_has_permission(target_organization_id, caller, 'time.track_own');

  -- The same own/team split the table's policy applies, restated here because this function is definer and
  -- the policy no longer stands between the reader and the rows.
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', visible.id,
          'user_id', visible.user_id,
          'user_name', visible.user_name,
          'visit_id', visible.visit_id,
          'visit_date', visible.visit_date,
          'started_at', visible.started_at,
          'minutes', visible.minutes,
          'notes', visible.notes,
          'can_edit', can_team or (visible.user_id = caller and can_own and not job_closed),
          'is_unrated', visible.cost_per_hour_minor is null
        )
        || (case when can_cost then jsonb_build_object(
              'cost_per_hour_minor', visible.cost_per_hour_minor,
              'cost_total_minor', visible.cost_total_minor
            ) else '{}'::jsonb end)
        order by visible.started_at desc, visible.id desc
      ),
      '[]'::jsonb
    ),
    count(*)
  into entries, entry_count
  from (
    select entry.id, entry.user_id, entry.visit_id, entry.started_at, entry.minutes, entry.notes,
           entry.cost_per_hour_minor, entry.cost_total_minor,
           profile.full_name as user_name,
           visit.visit_date
    from public.job_time_entries as entry
    left join public.profiles as profile on profile.id = entry.user_id
    left join public.job_visits as visit
      on visit.organization_id = entry.organization_id and visit.id = entry.visit_id
    where entry.organization_id = target_organization_id
      and entry.job_id = target_job_id
      and (can_team or (entry.user_id = caller and can_own))
    order by entry.started_at desc, entry.id desc
    limit page_size
  ) as visible;

  select jsonb_build_object(
    'entry_count', count(*),
    'minutes', coalesce(sum(entry.minutes), 0),
    'unrated_count', count(*) filter (where entry.cost_per_hour_minor is null),
    'cost_total_minor', case when can_cost then coalesce(sum(entry.cost_total_minor), 0) else null end
  ) into totals
  from public.job_time_entries as entry
  where entry.organization_id = target_organization_id
    and entry.job_id = target_job_id
    and (can_team or (entry.user_id = caller and can_own));

  return jsonb_build_object(
    'entries', entries,
    'totals', totals,
    -- More hours exist than the list shows. The totals still count all of them.
    'has_more', (totals->>'entry_count')::integer > entry_count,
    'job_closed', job_closed,
    'can_add', can_team or (can_own and not job_closed),
    'can_track_team', can_team,
    'can_see_cost', can_cost
  );
end;
$$;


ALTER FUNCTION "public"."job_labor"("target_organization_id" "uuid", "target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_labor"("target_organization_id" "uuid", "target_job_id" "uuid") IS 'One job''s recorded hours and their totals, newest first. A reader with time.track_team sees everyone''s and a reader with only time.track_own sees their own. Rates and costs need jobs.view_cost; without it the same rows come back with hours and no money at all.';



CREATE OR REPLACE FUNCTION "public"."job_line_money"("target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  org uuid;
  can_price boolean;
  can_cost boolean;
  answer jsonb;
begin
  select job.organization_id into org
  from public.jobs as job
  where job.id = target_job_id;

  if org is null then
    return '{}'::jsonb;
  end if;

  if not private.member_job_is_visible(org, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  can_price := private.member_has_permission(org, caller, 'jobs.view_price');
  can_cost := private.member_has_permission(org, caller, 'jobs.view_cost');
  if not can_price and not can_cost then
    return '{}'::jsonb;
  end if;

  select coalesce(jsonb_object_agg(item.id::text,
      (case when can_price then jsonb_build_object(
         'unit_price_minor', item.unit_price_minor,
         'line_total_minor', item.line_total_minor
       ) else '{}'::jsonb end)
      ||
      (case when can_cost then jsonb_build_object(
         'unit_cost_minor', item.unit_cost_minor,
         'line_cost_total_minor', item.line_cost_total_minor
       ) else '{}'::jsonb end)
    ), '{}'::jsonb)
  into answer
  from public.job_line_items as item
  where item.organization_id = org
    and item.job_id = target_job_id;

  return answer;
end;
$$;


ALTER FUNCTION "public"."job_line_money"("target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_line_money"("target_job_id" "uuid") IS 'Money for one job''s lines, keyed by line id. Prices need jobs.view_price and cost needs jobs.view_cost; a reader holding neither gets an empty object.';



CREATE OR REPLACE FUNCTION "public"."job_money"("target_job_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  organizations uuid[];
  org uuid;
  answer jsonb;
begin
  if target_job_ids is null or cardinality(target_job_ids) = 0 then
    return '{}'::jsonb;
  end if;

  select array_agg(distinct job.organization_id) into organizations
  from public.jobs as job
  where job.id = any(target_job_ids);

  if organizations is null then
    return '{}'::jsonb;
  end if;
  if array_length(organizations, 1) > 1 then
    raise exception 'Those jobs do not belong to one organization.' using errcode = 'check_violation';
  end if;
  org := organizations[1];

  if not private.member_has_permission(org, caller, 'jobs.view') then
    raise exception 'You do not have access to these jobs.' using errcode = 'insufficient_privilege';
  end if;

  if not private.member_has_permission(org, caller, 'jobs.view_price') then
    return '{}'::jsonb;
  end if;

  select coalesce(jsonb_object_agg(job.id::text,
      jsonb_build_object(
        'subtotal_minor', job.subtotal_minor,
        'discount_minor', job.discount_minor,
        'discount_name', job.discount_name,
        'discount_type', job.discount_type,
        'discount_value', job.discount_value,
        'tax_minor', job.tax_minor,
        'tax_name', job.tax_name,
        'tax_source', job.tax_source,
        'tax_rate_id', job.tax_rate_id,
        'tax_rate_basis_points', job.tax_rate_basis_points,
        'total_minor', job.total_minor
      )
    ), '{}'::jsonb)
  into answer
  from public.jobs as job
  where job.organization_id = org
    and job.id = any(target_job_ids)
    and private.member_job_is_visible(org, caller, job.id);

  return answer;
end;
$$;


ALTER FUNCTION "public"."job_money"("target_job_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_money"("target_job_ids" "uuid"[]) IS 'Selling-side money for a set of jobs, keyed by job id: subtotal, discount, tax and total. Needs jobs.view_price; a reader without it gets an empty object. Cost, profit and margin moved to job_costing in Part 14d.';



CREATE OR REPLACE FUNCTION "public"."job_report_customer_preview"("target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  job_row public.jobs;
  report_row public.job_reports;
  effective_include_price boolean;
  business_name text;
  document jsonb;
begin
  select * into job_row from public.jobs where id = target_job_id;
  if not found or not private.member_has_permission(job_row.organization_id, caller, 'jobs.view')
     or not private.can_view_job(job_row.organization_id, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  select * into report_row
  from public.job_reports
  where organization_id = job_row.organization_id and job_id = target_job_id;

  effective_include_price := coalesce(report_row.include_price, false)
    and private.member_has_permission(job_row.organization_id, caller, 'jobs.view_price');

  select organization.name into business_name
  from public.organizations as organization
  where organization.id = job_row.organization_id;

  document := private.job_report_customer_document(job_row, business_name, effective_include_price);

  return jsonb_build_object(
    'document', document,
    'preview', jsonb_build_object(
      'has_content', private.job_report_has_content(job_row.organization_id, target_job_id),
      'prices_withheld', coalesce(report_row.include_price, false) and not effective_include_price
    )
  );
end;
$$;


ALTER FUNCTION "public"."job_report_customer_preview"("target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_report_customer_preview"("target_job_id" "uuid") IS 'Preview as client. Returns the same customer document the token page renders, for a signed-in member with jobs.view, without creating a link. Amounts are withheld from the payload unless the report includes them and the member holds jobs.view_price.';



CREATE OR REPLACE FUNCTION "public"."job_report_state"("target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  org uuid;
  report_row public.job_reports;
begin
  if caller is null then
    raise exception 'You must be signed in to view this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.organization_id into org from public.jobs as job where job.id = target_job_id;
  if org is null then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  if not private.member_has_permission(org, caller, 'jobs.edit')
     or not private.can_view_job(org, target_job_id) then
    raise exception 'You do not have access to edit this job.' using errcode = 'insufficient_privilege';
  end if;

  select * into report_row
  from public.job_reports
  where organization_id = org and job_id = target_job_id;

  return jsonb_build_object(
    'report', jsonb_build_object(
      'include_service_details', coalesce(report_row.include_service_details, true),
      'include_price', coalesce(report_row.include_price, false),
      'signature_id', report_row.signature_id,
      'summary', report_row.summary,
      'photo_ids', (
        select coalesce(jsonb_agg(photo.attachment_id order by photo.created_at, photo.attachment_id),
          '[]'::jsonb)
        from public.job_report_photos as photo
        where photo.organization_id = org and photo.job_id = target_job_id
      ),
      'checklist', (
        select coalesce(jsonb_agg(jsonb_build_object('visit_id', sel.visit_id, 'item_id', sel.item_id)),
          '[]'::jsonb)
        from public.job_report_checklist_items as sel
        where sel.organization_id = org and sel.job_id = target_job_id
      )
    ),
    'has_content', private.job_report_has_content(org, target_job_id),
    'can_view_price', private.member_has_permission(org, caller, 'jobs.view_price'),
    'candidates', jsonb_build_object(
      -- Every image attached to the job itself or to any of its visits.
      'photos', (
        select coalesce(jsonb_agg(
          jsonb_build_object(
            'attachment_id', att.id,
            'file_name', att.file_name,
            'mime_type', att.mime_type,
            'entity_type', att.entity_type,
            'entity_id', att.entity_id,
            'created_at', att.created_at
          ) order by att.created_at, att.id
        ), '[]'::jsonb)
        from public.attachments as att
        where att.organization_id = org
          and att.mime_type like 'image/%'
          and (
            (att.entity_type = 'job' and att.entity_id = target_job_id)
            or (att.entity_type = 'visit' and att.entity_id in (
              select visit.id from public.job_visits as visit
              where visit.organization_id = org and visit.job_id = target_job_id
            ))
          )
      ),
      -- Answered checklist questions, grouped by the visit that answered them. Only answered ones are
      -- pickable: there is nothing to show a customer for a blank question.
      'visits', (
        select coalesce(jsonb_agg(
          jsonb_build_object(
            'visit_id', grp.visit_id,
            'visit_date', grp.visit_date,
            'items', grp.items
          ) order by grp.visit_date, grp.visit_id
        ), '[]'::jsonb)
        from (
          select visit.id as visit_id,
                 visit.visit_date,
                 jsonb_agg(
                   jsonb_build_object(
                     'item_id', item.id,
                     'label', item.label,
                     'item_type', item.item_type,
                     'value', answer.value
                   ) order by item.position, item.id
                 ) as items
          from public.visit_checklist_answers as answer
          join public.job_visits as visit
            on visit.organization_id = answer.organization_id and visit.id = answer.visit_id
          join public.job_checklist_items as item
            on item.organization_id = answer.organization_id and item.id = answer.item_id
          where answer.organization_id = org and answer.job_id = target_job_id
          group by visit.id, visit.visit_date
        ) as grp
      ),
      -- The job's signatures, so one can be shown on the report.
      'signatures', (
        select coalesce(jsonb_agg(
          jsonb_build_object(
            'id', sig.id,
            'signer_name', sig.signer_name,
            'signature_type', sig.signature_type,
            'collected_at', sig.collected_at
          ) order by sig.collected_at desc, sig.id desc
        ), '[]'::jsonb)
        from public.job_signatures as sig
        where sig.organization_id = org and sig.job_id = target_job_id
      )
    )
  );
end;
$$;


ALTER FUNCTION "public"."job_report_state"("target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_report_state"("target_job_id" "uuid") IS 'The work-report editor read: one job''s current selection plus the photos, answered checklist questions and signatures it could include. Needs jobs.edit and respects the assigned narrowing.';



CREATE OR REPLACE FUNCTION "public"."job_schedule_money"("target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  org uuid;
  priced jsonb;
  answer jsonb;
begin
  select job.organization_id into org from public.jobs as job where job.id = target_job_id;

  if org is null then
    return '{}'::jsonb;
  end if;

  if not private.member_job_is_visible(org, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  if not private.member_has_permission(org, caller, 'jobs.view_price') then
    return '{}'::jsonb;
  end if;

  begin
    priced := private.price_job_payment_schedule(target_job_id);
  exception when others then
    priced := null;
  end;

  select jsonb_build_object(
    'reconciles', priced is not null,
    'job_total_minor', (select job.total_minor from public.jobs as job where job.id = target_job_id),
    'stages', coalesce(jsonb_agg(jsonb_build_object(
      'installment_id', stage.id,
      'position', stage.position,
      'value_type', stage.value_type,
      'value', stage.value,
      'locked_amount_minor', stage.locked_amount_minor,
      'amount_minor', coalesce(stage.locked_amount_minor, (
        select (entry ->> 'amount_minor')::bigint
        from jsonb_array_elements(coalesce(priced -> 'items', '[]'::jsonb)) as entry
        where nullif(entry ->> 'installment_id', '')::uuid = stage.id
      ))
    ) order by stage.position, stage.id), '[]'::jsonb)
  )
  into answer
  from public.job_payment_schedule_items as stage
  where stage.organization_id = org and stage.job_id = target_job_id;

  return answer;
end;
$$;


ALTER FUNCTION "public"."job_schedule_money"("target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_schedule_money"("target_job_id" "uuid") IS 'Money for one job''s payment stages. Needs jobs.view_price; a reader without it gets an empty object.';



CREATE OR REPLACE FUNCTION "public"."job_schedule_stages"("target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  org uuid;
  job_total bigint;
  is_one_off boolean;
  can_price boolean;
  can_view_invoices boolean;
  can_price_invoices boolean;
  priced jsonb;
  today date;
  answer jsonb;
begin
  select job.organization_id, job.total_minor, job.job_type = 'one_off'
  into org, job_total, is_one_off
  from public.jobs as job
  where job.id = target_job_id;

  if org is null then
    return '{}'::jsonb;
  end if;

  if not private.member_job_is_visible(org, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  can_price := private.member_has_permission(org, caller, 'jobs.view_price');
  can_view_invoices := private.member_has_permission(org, caller, 'invoices.view');
  can_price_invoices := can_view_invoices
    and private.member_has_permission(org, caller, 'invoices.view_price');

  -- A job edited after one of its stages was invoiced can leave the schedule unable to reconcile. That is a
  -- real state the billing card has to show and explain, not an error it should die on, so the reader answers
  -- with the stored stages and says the schedule does not reconcile.
  if can_price then
    begin
      priced := private.price_job_payment_schedule(target_job_id);
    exception when others then
      priced := null;
    end;
  end if;

  today := private.organization_today(org);

  select jsonb_build_object(
    'job_id', target_job_id,
    'one_off', is_one_off,
    'reconciles', case when can_price then priced is not null else null end,
    'job_total_minor', case when can_price then job_total else null end,
    'stages', coalesce(jsonb_agg(jsonb_build_object(
      'installment_id', stage.id,
      'position', stage.position,
      'description', stage.description,
      'is_deposit', stage.is_deposit,
      -- The lock the write command enforces: this stage has been priced into a bill, so it is history
      -- rather than plan, and stays that way even if that bill was a draft somebody deleted.
      'locked', stage.locked_amount_minor is not null,
      'value_type', stage.value_type,
      'value', case when can_price then stage.value else null end,
      'amount_minor', case
        when not can_price then null
        else coalesce(stage.locked_amount_minor, (
          select (entry ->> 'amount_minor')::bigint
          from jsonb_array_elements(coalesce(priced -> 'items', '[]'::jsonb)) as entry
          where nullif(entry ->> 'installment_id', '')::uuid = stage.id
        ))
      end,
      'status', case
        when claim.root_invoice_id is null then 'remaining'
        when not can_view_invoices then 'invoiced'
        else private.invoice_live_status(
          active.voided_at, active.written_off_at, active.issued_at, active.recognized_at,
          active.marked_received_at, active.total_minor,
          private.invoice_allocated_minor(org, active.id), active.due_date, today
        )
      end,
      'invoice', case
        when claim.root_invoice_id is null or not can_view_invoices or active.id is null then null
        else jsonb_build_object(
          'id', active.id,
          'invoice_number', active.invoice_number,
          'total_minor', case when can_price_invoices then active.total_minor else null end,
          'balance_minor', case
            when can_price_invoices
              then active.total_minor - private.invoice_allocated_minor(org, active.id)
            else null
          end
        )
      end
    ) order by stage.position, stage.id), '[]'::jsonb)
  )
  into answer
  from public.job_payment_schedule_items as stage
  -- The claim names the chain's root, never the bill that happens to be active, so a correction inherits it.
  -- Served by invoice_sources_installment_id_unique_idx.
  left join lateral (
    select source.root_invoice_id
    from public.invoice_sources as source
    where source.organization_id = stage.organization_id
      and source.installment_id = stage.id
    limit 1
  ) as claim on true
  -- The bill that currently stands for that chain: everything before it has been replaced. Served by
  -- invoices_root_idx.
  left join lateral (
    select invoice.id, invoice.invoice_number, invoice.total_minor, invoice.due_date,
           invoice.voided_at, invoice.written_off_at, invoice.issued_at, invoice.recognized_at,
           invoice.marked_received_at
    from public.invoices as invoice
    where invoice.organization_id = org
      and invoice.root_invoice_id = claim.root_invoice_id
      and invoice.replaced_at is null
    order by invoice.created_at desc, invoice.id desc
    limit 1
  ) as active on claim.root_invoice_id is not null
  where stage.organization_id = org
    and stage.job_id = target_job_id;

  return answer;
end;
$$;


ALTER FUNCTION "public"."job_schedule_stages"("target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_schedule_stages"("target_job_id" "uuid") IS 'One job''s payment stages as the billing card draws them: the plan, whether each stage is billed, and the live invoice behind it. Amounts need jobs.view_price; the invoice needs invoices.view and its balance needs invoices.view_price.';



CREATE OR REPLACE FUNCTION "public"."job_signature_document"("target_signature_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  signature public.job_signatures;
  document jsonb;
  current_hash text;
begin
  if caller is null then
    raise exception 'You must be signed in to view this signature.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into signature from public.job_signatures where id = target_signature_id;
  if not found then
    raise exception 'That signature could not be found.' using errcode = 'P0404';
  end if;
  if not private.can_view_job(signature.organization_id, signature.job_id) then
    raise exception 'You do not have access to this signature.' using errcode = 'insufficient_privilege';
  end if;

  document := signature.document_snapshot;

  if not private.member_has_permission(signature.organization_id, caller, 'jobs.view_price') then
    document := (document - 'totals')
      || jsonb_build_object(
        'lines', (
          select coalesce(jsonb_agg(
            line - 'unit_price_minor' - 'line_total_minor'
            order by (line ->> 'position')::integer, line ->> 'line_id'
          ), '[]'::jsonb)
          from jsonb_array_elements(coalesce(document -> 'lines', '[]'::jsonb)) as line
        )
      );
  end if;

  current_hash := encode(
    extensions.digest(
      private.job_document_snapshot(signature.organization_id, signature.job_id)::text, 'sha256'
    ),
    'hex'
  );

  return jsonb_build_object(
    'id', signature.id,
    'job_id', signature.job_id,
    'signature_type', signature.signature_type,
    'statement', signature.statement,
    'signer_name', signature.signer_name,
    'signer_role', signature.signer_role,
    'method', signature.method,
    'has_image', signature.image_object_key is not null,
    'visit_id', signature.visit_id,
    'collected_at', signature.collected_at,
    'collected_by', signature.collected_by,
    'document_hash', signature.document_hash,
    'is_stale', signature.document_hash is distinct from current_hash,
    'document', document
  );
end;
$$;


ALTER FUNCTION "public"."job_signature_document"("target_signature_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_signature_document"("target_signature_id" "uuid") IS 'The frozen document one signature was given against, exactly as it stood then. Prices and totals are stripped for a reader without jobs.view_price; the work list is not.';



CREATE OR REPLACE FUNCTION "public"."job_signatures_for_job"("target_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  org uuid;
  current_hash text;
  signatures jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to view this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.organization_id into org from public.jobs as job where job.id = target_job_id;
  if org is null then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  if not private.can_view_job(org, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  current_hash := encode(
    extensions.digest(private.job_document_snapshot(org, target_job_id)::text, 'sha256'), 'hex'
  );

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', signature.id,
        'signature_type', signature.signature_type,
        'statement', signature.statement,
        'signer_name', signature.signer_name,
        'signer_role', signature.signer_role,
        'method', signature.method,
        'has_image', signature.image_object_key is not null,
        'visit_id', signature.visit_id,
        'visit_date', visit.visit_date,
        'collected_at', signature.collected_at,
        'collected_by', signature.collected_by,
        'is_stale', signature.document_hash is distinct from current_hash
      )
      order by signature.collected_at desc, signature.id desc
    ),
    '[]'::jsonb
  )
  into signatures
  from public.job_signatures as signature
  left join public.job_visits as visit
    on visit.organization_id = signature.organization_id and visit.id = signature.visit_id
  where signature.organization_id = org and signature.job_id = target_job_id;

  return jsonb_build_object(
    'signatures', signatures,
    'can_collect', private.member_has_permission(org, caller, 'field_records.record')
      or private.member_has_permission(org, caller, 'field_records.manage_team')
  );
end;
$$;


ALTER FUNCTION "public"."job_signatures_for_job"("target_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_signatures_for_job"("target_job_id" "uuid") IS 'One job''s collected signatures, newest first, each flagged is_stale when the job document no longer hashes to what was signed. Carries no money and no snapshot -- the signed document is its own read.';



CREATE OR REPLACE FUNCTION "public"."job_status_counts"("target_organization_id" "uuid") RETURNS TABLE("derived_status" "text", "total" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select counted.derived_status, count(*) as total
  from public.job_status_count_rows as counted
  where counted.organization_id = target_organization_id
  group by 1;
$$;


ALTER FUNCTION "public"."job_status_counts"("target_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_status_counts"("target_organization_id" "uuid") IS 'Live count of this organization''s jobs by derived status, for the Jobs overview card. Counts job_status_count_rows, whose due-reminder check is a bulk set-join so counting every job stays linear.';



CREATE OR REPLACE FUNCTION "public"."job_visit_lines"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  can_price boolean;
  can_cost boolean;
  wanted uuid[] := coalesce(target_visit_ids, '{}'::uuid[]);
  answer jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to view this job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  if cardinality(wanted) > 100 then
    raise exception 'Too many visits were asked for at once.' using errcode = '54000';
  end if;

  can_price := private.member_has_permission(target_organization_id, caller, 'jobs.view_price');
  can_cost := private.member_has_permission(target_organization_id, caller, 'jobs.view_cost');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'visit_id', visit.id,
        'visit_date', visit.visit_date,
        'completed', visit.completed_at is not null,
        'revision', visit.revision,
        'has_override', exists (
          select 1
          from public.job_visit_line_items as override
          where override.organization_id = target_organization_id
            and override.visit_id = visit.id
        ),
        'locked', visit.completed_at is not null or claimed.invoiced,
        'lock_reason', case
          when claimed.invoiced then 'invoiced'
          when visit.completed_at is not null then 'completed'
          else null
        end,
        'subtotal_minor', case when can_price then coalesce(effective.subtotal_minor, 0) else null end,
        'lines', coalesce(effective.lines, '[]'::jsonb)
      )
      order by visit.visit_date nulls last, visit.position, visit.id
    ),
    '[]'::jsonb
  ) into answer
  from public.job_visits as visit
  cross join lateral (
    select exists (
      select 1
      from public.invoice_sources as claim
      where claim.organization_id = target_organization_id
        and claim.visit_id = visit.id
        and claim.source_kind = 'visit'
    ) as invoiced
  ) as claimed
  cross join lateral (
    select
      sum(line.line_total_minor) filter (where line.line_kind = 'priced') as subtotal_minor,
      jsonb_agg(
        jsonb_build_object(
          'id', line.id,
          'is_override', line.is_override,
          'source_job_line_item_id', line.source_job_line_item_id,
          'catalog_item_id', line.source_catalog_item_id,
          'line_kind', line.line_kind,
          'category', line.category,
          'is_labor', line.is_labor,
          'name', line.name,
          'description', line.description,
          'unit_label', line.unit_label,
          'quantity', line.quantity,
          'is_taxable', line.is_taxable,
          'image_attachment_id', line.image_attachment_id
        )
        || (case when can_price then jsonb_build_object(
              'unit_price_minor', line.unit_price_minor,
              'line_total_minor', line.line_total_minor
            ) else '{}'::jsonb end)
        || (case when can_cost then jsonb_build_object(
              'unit_cost_minor', line.unit_cost_minor
            ) else '{}'::jsonb end)
        order by line.position, line.id
      ) as lines
    from private.job_visit_effective_lines(target_organization_id, target_job_id, visit.id) as line
  ) as effective
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.id = any(wanted);

  return jsonb_build_object('visits', answer);
end;
$$;


ALTER FUNCTION "public"."job_visit_lines"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."job_visit_lines"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_ids" "uuid"[]) IS 'Effective lines for up to 100 of one job''s visits, with each visit''s own subtotal, whether it carries its own set, and whether its pricing is locked. Prices need jobs.view_price, cost needs jobs.view_cost.';



CREATE OR REPLACE FUNCTION "public"."labor_cost_total_minor"("minutes" integer, "cost_per_hour_minor" bigint) RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case
    when minutes is null or cost_per_hour_minor is null then null
    else round(cost_per_hour_minor::numeric * minutes / 60)::bigint
  end;
$$;


ALTER FUNCTION "public"."labor_cost_total_minor"("minutes" integer, "cost_per_hour_minor" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."labor_cost_total_minor"("minutes" integer, "cost_per_hour_minor" bigint) IS 'Minutes at an hourly rate, in minor units. Null when the rate is unknown, which is not the same as zero: unrated hours are reported as unrated rather than valued at nothing.';



CREATE OR REPLACE FUNCTION "public"."list_communication_outbound_attachments"("target_delivery_intent_id" "uuid") RETURNS TABLE("file_name" "text", "mime_type" "text", "byte_size" bigint, "object_key" "text")
    LANGUAGE "sql" SECURITY DEFINER
