CREATE OR REPLACE FUNCTION "public"."list_team_directory"("target_organization_id" "uuid", "requested_status" "text" DEFAULT NULL::"text", "search_term" "text" DEFAULT NULL::"text", "page_limit" integer DEFAULT 25, "cursor_status_order" integer DEFAULT NULL::integer, "cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "cursor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  clean_search text := nullif(btrim(search_term), '');
  result jsonb;
begin
  if (select auth.uid()) is null or not exists (
    select 1
    from private.permitted_organizations('team.manage') as permitted(organization_id)
    where permitted.organization_id = target_organization_id
  ) then
    raise exception 'Team management is not available for this organization.'
      using errcode = '42501';
  end if;

  if requested_status is not null
     and requested_status not in ('pending', 'active', 'deactivated') then
    raise exception 'The team status filter is invalid.' using errcode = '22023';
  end if;

  if page_limit is null or page_limit < 1 or page_limit > 50 then
    raise exception 'The team page size must be between 1 and 50.' using errcode = '22023';
  end if;

  if clean_search is not null and char_length(clean_search) > 100 then
    raise exception 'The team search must be 100 characters or fewer.' using errcode = '22023';
  end if;

  if (cursor_status_order is null)::integer
     + (cursor_created_at is null)::integer
     + (cursor_user_id is null)::integer not in (0, 3) then
    raise exception 'The team cursor is incomplete.' using errcode = '22023';
  end if;

  with directory as materialized (
    select
      member.user_id,
      member.role,
      member.status,
      case member.status when 'pending' then 1 when 'active' then 2 else 3 end as status_order,
      member.access_revision,
      member.profile_revision,
      member.work_phone,
      member.job_title,
      member.schedule_color,
      member.created_at,
      member.deactivated_at,
      profile.full_name,
      profile.avatar_url,
      invitation.id as invitation_id,
      invitation.invited_email,
      invitation.state as invitation_state,
      invitation.last_delivery_error is not null as invitation_delivery_failed,
      invitation.last_sent_at,
      invitation.expires_at
    from public.organization_members as member
    left join public.profiles as profile on profile.id = member.user_id
    left join lateral (
      select candidate.id, candidate.invited_email, candidate.state, candidate.last_delivery_error,
             candidate.last_sent_at, candidate.expires_at
      from public.organization_member_invitations as candidate
      where candidate.organization_id = member.organization_id
        and candidate.invited_user_id = member.user_id
        and candidate.state in ('reserving', 'invited', 'accepting')
      order by candidate.created_at desc, candidate.id desc
      limit 1
    ) as invitation on true
    where member.organization_id = target_organization_id
      and member.status in ('pending', 'active', 'deactivated')
      and (requested_status is null or member.status = requested_status)
      and (
        clean_search is null
        or position(lower(clean_search) in lower(coalesce(profile.full_name, ''))) > 0
        or position(lower(clean_search) in lower(coalesce(invitation.invited_email, ''))) > 0
        or position(lower(clean_search) in lower(coalesce(member.job_title, ''))) > 0
        or position(lower(clean_search) in lower(coalesce(member.work_phone, ''))) > 0
      )
  ), page as materialized (
    select *
    from directory
    where cursor_status_order is null
       or status_order > cursor_status_order
       or (status_order = cursor_status_order and created_at < cursor_created_at)
       or (status_order = cursor_status_order and created_at = cursor_created_at
           and user_id > cursor_user_id)
    order by status_order, created_at desc, user_id
    limit page_limit + 1
  ), visible as materialized (
    select * from page
    order by status_order, created_at desc, user_id
    limit page_limit
  ), last_visible as (
    select status_order, created_at, user_id
    from visible
    order by status_order desc, created_at, user_id desc
    limit 1
  )
  select jsonb_build_object(
    'members', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'user_id', row.user_id,
          'display_name', row.full_name,
          'avatar_url', row.avatar_url,
          'role', row.role,
          'status', row.status,
          'access_revision', row.access_revision,
          'profile_revision', row.profile_revision,
          'work_phone', row.work_phone,
          'job_title', row.job_title,
          'schedule_color', row.schedule_color,
          'created_at', row.created_at,
          'deactivated_at', row.deactivated_at,
          'invitation', case when row.invitation_id is null then null else jsonb_build_object(
            'id', row.invitation_id,
            'email', row.invited_email,
            'state', row.invitation_state,
            'delivery_failed', row.invitation_delivery_failed,
            'last_sent_at', row.last_sent_at,
            'expires_at', row.expires_at
          ) end
        ) order by row.status_order, row.created_at desc, row.user_id
      ) from visible as row
    ), '[]'::jsonb),
    'next_cursor', case when (select count(*) from page) > page_limit then (
      select jsonb_build_object(
        'status_order', last_visible.status_order,
        'created_at', last_visible.created_at,
        'user_id', last_visible.user_id
      ) from last_visible
    ) else null end,
    'seats_used', private.employee_seats_used(target_organization_id)
  ) into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."list_team_directory"("target_organization_id" "uuid", "requested_status" "text", "search_term" "text", "page_limit" integer, "cursor_status_order" integer, "cursor_created_at" timestamp with time zone, "cursor_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_team_directory"("target_organization_id" "uuid", "requested_status" "text", "search_term" "text", "page_limit" integer, "cursor_status_order" integer, "cursor_created_at" timestamp with time zone, "cursor_user_id" "uuid") IS 'Returns one authorized, searchable, cursor-paged Team directory envelope. It deliberately omits raw permission maps and Auth-only sign-in details; Part 3D owns access editing.';



CREATE OR REPLACE FUNCTION "public"."manage_platform_package_automation_limits"("target_version_id" "uuid", "target_active_recipes_state" "text", "target_active_recipes_value" integer, "target_conditions_state" "text", "target_conditions_value" integer, "target_steps_state" "text", "target_steps_value" integer, "target_customer_messages_state" "text", "target_customer_messages_value" integer, "target_message_spacing_state" "text", "target_message_spacing_value" integer, "target_max_delay_state" "text", "target_max_delay_value" integer, "target_max_duration_state" "text", "target_max_duration_value" integer, "actor_email" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  version_row public.platform_package_versions%rowtype;
  states text[] := array[
    target_active_recipes_state, target_conditions_state, target_steps_state,
    target_customer_messages_state, target_message_spacing_state, target_max_delay_state,
    target_max_duration_state
  ];
  values_in integer[] := array[
    target_active_recipes_value, target_conditions_value, target_steps_value,
    target_customer_messages_value, target_message_spacing_value, target_max_delay_value,
    target_max_duration_value
  ];
  keys text[] := array[
    'automation_active_recipes', 'automation_max_conditions_per_recipe',
    'automation_max_steps_per_recipe', 'automation_max_customer_messages_per_enrollment',
    'automation_min_customer_message_spacing_minutes', 'automation_max_delay_days',
    'automation_max_enrollment_duration_days'
  ];
  i integer;
begin
  if char_length(trim(coalesce(actor_email, ''))) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;

  for i in 1 .. array_length(keys, 1) loop
    if states[i] not in ('unlimited', 'not_included', 'numeric') then
      raise exception 'Choose a valid Automation limit type.' using errcode = 'check_violation';
    end if;
    if states[i] = 'numeric' and coalesce(values_in[i], 0) < 1 then
      raise exception 'A numeric Automation limit must be at least one.' using errcode = 'check_violation';
    end if;
    if states[i] <> 'numeric' and values_in[i] is not null then
      raise exception 'Only a numeric Automation limit can include a value.' using errcode = 'check_violation';
    end if;
  end loop;

  select * into version_row
  from public.platform_package_versions
  where id = target_version_id
  for update;
  if not found or version_row.status <> 'draft' then
    raise exception 'Automation limits can only be changed on a draft package version.' using errcode = 'check_violation';
  end if;

  delete from public.platform_package_version_limits
  where package_version_id = version_row.id
    and limit_key = any (keys);

  for i in 1 .. array_length(keys, 1) loop
    insert into public.platform_package_version_limits (package_version_id, limit_key, limit_state, limit_value)
    values (
      version_row.id, keys[i], states[i],
      case when states[i] = 'numeric' then values_in[i] end
    );
  end loop;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, after_state
  ) values (
    lower(trim(actor_email)), 'package.automation_limits_changed', 'platform_package_version', version_row.id::text,
    jsonb_build_object(
      'active_recipes', jsonb_build_object('state', target_active_recipes_state, 'value', target_active_recipes_value),
      'conditions_per_recipe', jsonb_build_object('state', target_conditions_state, 'value', target_conditions_value),
      'steps_per_recipe', jsonb_build_object('state', target_steps_state, 'value', target_steps_value),
      'customer_messages_per_enrollment', jsonb_build_object('state', target_customer_messages_state, 'value', target_customer_messages_value),
      'message_spacing_minutes', jsonb_build_object('state', target_message_spacing_state, 'value', target_message_spacing_value),
      'max_delay_days', jsonb_build_object('state', target_max_delay_state, 'value', target_max_delay_value),
      'max_enrollment_duration_days', jsonb_build_object('state', target_max_duration_state, 'value', target_max_duration_value)
    )
  );
  return version_row.id;
end;
$$;


ALTER FUNCTION "public"."manage_platform_package_automation_limits"("target_version_id" "uuid", "target_active_recipes_state" "text", "target_active_recipes_value" integer, "target_conditions_state" "text", "target_conditions_value" integer, "target_steps_state" "text", "target_steps_value" integer, "target_customer_messages_state" "text", "target_customer_messages_value" integer, "target_message_spacing_state" "text", "target_message_spacing_value" integer, "target_max_delay_state" "text", "target_max_delay_value" integer, "target_max_duration_state" "text", "target_max_duration_value" integer, "actor_email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."manage_platform_package_automation_limits"("target_version_id" "uuid", "target_active_recipes_state" "text", "target_active_recipes_value" integer, "target_conditions_state" "text", "target_conditions_value" integer, "target_steps_state" "text", "target_steps_value" integer, "target_customer_messages_state" "text", "target_customer_messages_value" integer, "target_message_spacing_state" "text", "target_message_spacing_value" integer, "target_max_delay_state" "text", "target_max_delay_value" integer, "target_max_duration_state" "text", "target_max_duration_value" integer, "actor_email" "text") IS 'Owner-managed draft-only write for the seven Automation package limits.';



CREATE OR REPLACE FUNCTION "public"."manage_platform_package_email_allowances"("target_version_id" "uuid", "target_operational_state" "text", "target_operational_value" integer, "target_essential_state" "text", "target_essential_value" integer, "actor_email" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$ declare version_row public.platform_package_versions%rowtype; begin if char_length(trim(coalesce(actor_email, ''))) not between 3 and 320 then raise exception 'An owner email is required.' using errcode = 'check_violation'; end if; if target_operational_state not in ('unlimited','not_included','numeric') or target_essential_state not in ('unlimited','not_included','numeric') then raise exception 'Choose a valid email allowance type.' using errcode = 'check_violation'; end if; if (target_operational_state = 'numeric' and coalesce(target_operational_value,0) < 1) or (target_operational_state <> 'numeric' and target_operational_value is not null) or (target_essential_state = 'numeric' and coalesce(target_essential_value,0) < 1) or (target_essential_state <> 'numeric' and target_essential_value is not null) then raise exception 'A numeric email allowance must be at least one recipient.' using errcode = 'check_violation'; end if; select * into version_row from public.platform_package_versions where id=target_version_id for update; if not found or version_row.status <> 'draft' then raise exception 'Email allowances can only be changed on a draft package version.' using errcode = 'check_violation'; end if; delete from public.platform_package_version_limits where package_version_id=version_row.id and limit_key in ('operational_email_recipients','essential_email_recipients'); insert into public.platform_package_version_limits (package_version_id,limit_key,limit_state,limit_value) values (version_row.id,'operational_email_recipients',target_operational_state,case when target_operational_state='numeric' then target_operational_value end),(version_row.id,'essential_email_recipients',target_essential_state,case when target_essential_state='numeric' then target_essential_value end); insert into public.platform_owner_audit_events (actor_owner_email,event_type,target_type,target_key,after_state) values (lower(trim(actor_email)),'package.email_allowances_changed','platform_package_version',version_row.id::text,jsonb_build_object('operational_state',target_operational_state,'operational_value',target_operational_value,'essential_state',target_essential_state,'essential_value',target_essential_value)); return version_row.id; end; $$;


ALTER FUNCTION "public"."manage_platform_package_email_allowances"("target_version_id" "uuid", "target_operational_state" "text", "target_operational_value" integer, "target_essential_state" "text", "target_essential_value" integer, "actor_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manage_platform_package_marketing_allowance"("target_version_id" "uuid", "target_state" "text", "target_value" integer, "actor_email" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  version_row public.platform_package_versions%rowtype;
begin
  if char_length(trim(coalesce(actor_email, ''))) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if target_state not in ('unlimited', 'not_included', 'numeric') then
    raise exception 'Choose a valid Marketing allowance type.' using errcode = 'check_violation';
  end if;
  if (target_state = 'numeric' and coalesce(target_value, 0) < 1)
    or (target_state <> 'numeric' and target_value is not null) then
    raise exception 'A numeric Marketing allowance must be at least one recipient.' using errcode = 'check_violation';
  end if;

  select * into version_row
  from public.platform_package_versions
  where id = target_version_id
  for update;
  if not found or version_row.status <> 'draft' then
    raise exception 'The Marketing allowance can only be changed on a draft package version.' using errcode = 'check_violation';
  end if;

  delete from public.platform_package_version_limits
  where package_version_id = version_row.id
    and limit_key = 'marketing_email_recipients';

  insert into public.platform_package_version_limits (package_version_id, limit_key, limit_state, limit_value)
  values (version_row.id, 'marketing_email_recipients', target_state,
    case when target_state = 'numeric' then target_value end);

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, after_state
  ) values (
    lower(trim(actor_email)), 'package.marketing_allowance_changed', 'platform_package_version', version_row.id::text,
    jsonb_build_object('state', target_state, 'value', target_value)
  );
  return version_row.id;
end;
$$;


ALTER FUNCTION "public"."manage_platform_package_marketing_allowance"("target_version_id" "uuid", "target_state" "text", "target_value" integer, "actor_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manage_platform_package_version"("operation" "text", "target_package_key" "text", "target_version_id" "uuid" DEFAULT NULL::"uuid", "target_display_name" "text" DEFAULT NULL::"text", "target_public_description" "text" DEFAULT NULL::"text", "target_value_explanation" "text" DEFAULT NULL::"text", "target_price_usd_cents" integer DEFAULT NULL::integer, "target_feature_keys" "text"[] DEFAULT '{}'::"text"[], "target_limit_state" "text" DEFAULT NULL::"text", "target_limit_value" integer DEFAULT NULL::integer, "actor_email" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  package_row public.platform_packages%rowtype;
  version_row public.platform_package_versions%rowtype;
  before_state jsonb;
  after_state jsonb;
begin
  if operation not in ('create_draft', 'update_draft', 'publish', 'retire') then
    raise exception 'Unsupported package version operation.' using errcode = 'invalid_parameter_value';
  end if;
  if actor_email is null or char_length(trim(actor_email)) = 0 then
    raise exception 'An owner email is required.' using errcode = 'not_null_violation';
  end if;

  select * into package_row
  from public.platform_packages
  where package_key = target_package_key
    and status <> 'retired'
  for update;
  if not found then
    raise exception 'Package was not found.' using errcode = 'foreign_key_violation';
  end if;

  if operation = 'retire' then
    if exists (
      select 1 from public.organization_package_assignments as assignment
      join public.platform_package_versions as version on version.id = assignment.package_version_id
      where version.package_id = package_row.package_id and not exists (
        select 1 from public.organization_package_assignments as later_assignment
        where later_assignment.organization_id = assignment.organization_id
        and (later_assignment.effective_at, later_assignment.id) > (assignment.effective_at, assignment.id)
      )
    ) or exists (
      select 1 from public.organizations as organization
      where not exists (select 1 from public.organization_package_assignments as assignment where assignment.organization_id = organization.id)
      and (organization.package_key = package_row.package_key or organization.scheduled_package_key = package_row.package_key)
    ) then
      raise exception 'Move every organization away from this package before retiring it.' using errcode = 'check_violation';
    end if;

    before_state := to_jsonb(package_row);
    update public.platform_package_versions
    set status = 'retired', retired_at = coalesce(retired_at, now())
    where package_id = package_row.package_id and status = 'published';
    update public.platform_packages
    set status = 'retired'
    where package_id = package_row.package_id
    returning * into package_row;
    after_state := to_jsonb(package_row);

    insert into public.platform_owner_audit_events (
      actor_owner_email, event_type, target_type, target_key, before_state, after_state
    ) values (
      lower(trim(actor_email)), 'package.retire', 'platform_package',
      package_row.package_id::text, before_state, after_state
    );

    return package_row.package_id;
  end if;

  if operation = 'create_draft' then
    if target_display_name is null or target_public_description is null
      or target_price_usd_cents is null then
      raise exception 'Draft package name, description, and price are required.' using errcode = 'check_violation';
    end if;

    insert into public.platform_package_versions (
      package_id, version_number, display_name, public_description,
      value_explanation, price_usd_cents
    )
    select package_row.package_id, coalesce(max(version_number), 0) + 1,
      target_display_name, target_public_description,
      target_value_explanation, target_price_usd_cents
    from public.platform_package_versions
    where package_id = package_row.package_id
    returning * into version_row;
  else
    select * into version_row
    from public.platform_package_versions
    where id = target_version_id
      and package_id = package_row.package_id
    for update;
    if not found then
      raise exception 'Package version was not found.' using errcode = 'foreign_key_violation';
    end if;
    if operation in ('update_draft', 'publish') and version_row.status <> 'draft' then
      raise exception 'Only draft package versions can be changed.' using errcode = 'check_violation';
    end if;
  end if;

  if operation in ('create_draft', 'update_draft') then
    if target_display_name is null or target_public_description is null
      or target_price_usd_cents is null then
      raise exception 'Package name, description, and price are required.' using errcode = 'check_violation';
    end if;
    before_state := to_jsonb(version_row);
    if operation = 'update_draft' then
      update public.platform_package_versions
      set display_name = target_display_name,
          public_description = target_public_description,
          value_explanation = target_value_explanation,
          price_usd_cents = target_price_usd_cents
      where id = version_row.id;
      select * into version_row from public.platform_package_versions where id = version_row.id;
    end if;

    delete from public.platform_package_version_features where package_version_id = version_row.id;
    insert into public.platform_package_version_features (package_version_id, feature_key)
    select version_row.id, feature_key from unnest(target_feature_keys) as feature_key;

    delete from public.platform_package_version_limits where package_version_id = version_row.id;
    if target_limit_state is not null then
      insert into public.platform_package_version_limits (
        package_version_id, limit_key, limit_state, limit_value
      ) values (version_row.id, 'employee_seats', target_limit_state, target_limit_value);
    end if;
  end if;

  if operation = 'publish' then
    if version_row.public_description is null or char_length(trim(version_row.public_description)) = 0
      or version_row.price_usd_cents is null then
      raise exception 'A package version needs a description and price before publishing.' using errcode = 'check_violation';
    end if;
    if not exists (select 1 from public.platform_package_version_features where package_version_id = version_row.id)
      and (version_row.value_explanation is null or char_length(trim(version_row.value_explanation)) = 0) then
      raise exception 'A package version needs an included capability or value explanation.' using errcode = 'check_violation';
    end if;
    update public.platform_package_versions
    set status = 'retired', retired_at = now()
    where package_id = package_row.package_id and status = 'published';
    update public.platform_package_versions
    set status = 'published', published_at = now()
    where id = version_row.id
    returning * into version_row;
    update public.platform_packages
    set status = 'published',
        public_description = version_row.public_description,
        price_usd_cents = version_row.price_usd_cents,
        currency = version_row.currency,
        billing_period = version_row.billing_period
    where package_id = package_row.package_id;
  end if;

  after_state := to_jsonb(version_row);
  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    lower(trim(actor_email)), 'package.' || operation, 'platform_package_version',
    version_row.id::text, before_state, after_state
  );

  return version_row.id;
end;
$$;


ALTER FUNCTION "public"."manage_platform_package_version"("operation" "text", "target_package_key" "text", "target_version_id" "uuid", "target_display_name" "text", "target_public_description" "text", "target_value_explanation" "text", "target_price_usd_cents" integer, "target_feature_keys" "text"[], "target_limit_state" "text", "target_limit_value" integer, "actor_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manage_platform_package_website_chat_limits"("target_version_id" "uuid", "target_widgets_state" "text", "target_widgets_value" integer, "target_accepted_conversations_state" "text", "target_accepted_conversations_value" integer, "actor_email" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  version_row public.platform_package_versions%rowtype;
begin
  if char_length(trim(coalesce(actor_email, ''))) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if target_widgets_state not in ('unlimited', 'not_included', 'numeric')
    or target_accepted_conversations_state not in ('unlimited', 'not_included', 'numeric') then
    raise exception 'Choose a valid Website Chat limit type.' using errcode = 'check_violation';
  end if;
  if (target_widgets_state = 'numeric' and coalesce(target_widgets_value, 0) < 1)
    or (target_widgets_state <> 'numeric' and target_widgets_value is not null)
    or (target_accepted_conversations_state = 'numeric' and coalesce(target_accepted_conversations_value, 0) < 1)
    or (target_accepted_conversations_state <> 'numeric' and target_accepted_conversations_value is not null) then
    raise exception 'A numeric Website Chat limit must be at least one.' using errcode = 'check_violation';
  end if;

  select * into version_row
  from public.platform_package_versions
  where id = target_version_id
  for update;
  if not found or version_row.status <> 'draft' then
    raise exception 'Website Chat limits can only be changed on a draft package version.' using errcode = 'check_violation';
  end if;

  delete from public.platform_package_version_limits
  where package_version_id = version_row.id
    and limit_key in ('website_chat_widgets', 'website_chat_accepted_conversations');

  insert into public.platform_package_version_limits (package_version_id, limit_key, limit_state, limit_value)
  values
    (version_row.id, 'website_chat_widgets', target_widgets_state,
      case when target_widgets_state = 'numeric' then target_widgets_value end),
    (version_row.id, 'website_chat_accepted_conversations', target_accepted_conversations_state,
      case when target_accepted_conversations_state = 'numeric' then target_accepted_conversations_value end);

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, after_state
  ) values (
    lower(trim(actor_email)), 'package.website_chat_limits_changed', 'platform_package_version', version_row.id::text,
    jsonb_build_object(
      'widgets_state', target_widgets_state, 'widgets_value', target_widgets_value,
      'accepted_conversations_state', target_accepted_conversations_state,
      'accepted_conversations_value', target_accepted_conversations_value
    )
  );
  return version_row.id;
end;
$$;


ALTER FUNCTION "public"."manage_platform_package_website_chat_limits"("target_version_id" "uuid", "target_widgets_state" "text", "target_widgets_value" integer, "target_accepted_conversations_state" "text", "target_accepted_conversations_value" integer, "actor_email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."manage_platform_package_website_chat_limits"("target_version_id" "uuid", "target_widgets_state" "text", "target_widgets_value" integer, "target_accepted_conversations_state" "text", "target_accepted_conversations_value" integer, "actor_email" "text") IS 'Owner-managed draft-only write for the two Website Chat package limits.';



CREATE OR REPLACE FUNCTION "public"."manual_enroll_automation"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_max_enrollment_duration_days" integer, "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  existing_receipt public.automation_enrollment_command_receipts%rowtype;
  recipe public.automation_recipes%rowtype;
  live_overlap integer;
  new_enrollment_id uuid;
  expires timestamptz;
  command_result jsonb;
begin
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;
  if p_subject_type is distinct from 'quote' then
    raise exception 'This record type cannot be enrolled.' using errcode = 'check_violation';
  end if;

  select * into existing_receipt
  from public.automation_enrollment_command_receipts
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_receipt.result || jsonb_build_object('idempotent_replay', true);
  end if;

  perform pg_advisory_xact_lock(hashtext('automation-recipe:' || p_recipe_id::text));

  select * into recipe
  from public.automation_recipes
  where id = p_recipe_id and organization_id = p_organization_id
  for update;
  if not found then
    raise exception 'That automation does not exist.' using errcode = 'no_data_found';
  end if;
  if recipe.status <> 'active' or recipe.current_version_id is null then
    raise exception 'Only an active automation can enroll a record.' using errcode = 'restrict_violation';
  end if;

  select count(*) into live_overlap
  from private.automation_enrollments
  where organization_id = p_organization_id
    and recipe_id = p_recipe_id
    and subject_type = p_subject_type
    and subject_id = p_subject_id
    and state in ('active', 'paused');
  if live_overlap > 0 then
    raise exception 'This record is already enrolled in this automation.' using errcode = 'unique_violation';
  end if;

  expires := case
    when p_max_enrollment_duration_days is not null
      then now() + make_interval(days => p_max_enrollment_duration_days)
    else null
  end;

  insert into private.automation_enrollments (
    organization_id, recipe_id, recipe_version_id, subject_type, subject_id,
    trigger_event_id, source, state, current_step_index, re_entry_key, context,
    enrolled_by, expires_at
  ) values (
    p_organization_id, p_recipe_id, recipe.current_version_id, p_subject_type, p_subject_id,
    null, 'manual', 'active', 0, 'manual:' || p_idempotency_key::text,
    jsonb_build_object('source', 'manual', 'enrolled_by', p_actor_user_id, 'enrolled_at', now()),
    p_actor_user_id, expires
  )
  returning id into new_enrollment_id;

  insert into private.automation_work_items (
    organization_id, enrollment_id, step_index, due_at, available_at
  ) values (
    p_organization_id, new_enrollment_id, 0, now(), now()
  );

  command_result := jsonb_build_object(
    'enrollment_id', new_enrollment_id,
    'recipe_id', p_recipe_id,
    'version_id', recipe.current_version_id,
    'state', 'active'
  );

  insert into public.automation_enrollment_command_receipts (
    organization_id, idempotency_key, command, subject_type, subject_id, enrollment_id, result
  ) values (
    p_organization_id, p_idempotency_key, 'enroll', p_subject_type, p_subject_id, new_enrollment_id, command_result
  );

  return command_result;
end;
$$;


ALTER FUNCTION "public"."manual_enroll_automation"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_max_enrollment_duration_days" integer, "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."manual_enroll_automation"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_max_enrollment_duration_days" integer, "p_idempotency_key" "uuid") IS 'Manually enrolls one eligible record into an active automation and seeds its first step. Idempotent per organization + key; one live enrollment per subject+recipe. Service role only.';



CREATE OR REPLACE FUNCTION "public"."mark_member_identity_revoked"("target_organization_id" "uuid", "target_user_id" "uuid", "new_cleanup_state" "text", "cleanup_error" "text" DEFAULT NULL::"text") RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members;
  state_order constant text[] := array['not_required', 'required', 'ban_applied', 'email_released', 'done'];
  current_position integer;
  new_position integer;
begin
  select * into membership
  from public.organization_members as membership_row
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  for update;

  if not found then
    raise exception 'That team member was not found.' using errcode = 'no_data_found';
  end if;

  if membership.status <> 'removed' then
    raise exception 'Only a permanently removed person has an identity cleanup to record.'
      using errcode = 'check_violation';
  end if;

  new_position := array_position(state_order, new_cleanup_state);
  current_position := array_position(state_order, membership.identity_cleanup_state);

  if new_position is null or new_cleanup_state in ('not_required', 'required') then
    raise exception '% is not a cleanup step.', coalesce(new_cleanup_state, 'nothing')
      using errcode = 'check_violation';
  end if;

  -- Forward or standing still. A retry that reports a step already recorded is fine; a worker claiming the
  -- account was un-banned is not.
  if new_position < current_position then
    raise exception 'The identity cleanup has already gone past that step.' using errcode = 'check_violation';
  end if;

  update public.organization_members as membership_row
  set identity_cleanup_state = new_cleanup_state,
      identity_cleanup_error = cleanup_error
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  returning * into membership;

  -- One history line, written the first time the cleanup finishes. The intermediate steps are plumbing and
  -- belong in the ledger column, not in a contractor's team history.
  if new_cleanup_state = 'done' and current_position < new_position then
    insert into public.organization_member_access_events (
      organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
    )
    values (
      target_organization_id, 'member.identity_revoked', 'system', null, target_user_id, '{}'::jsonb
    );
  end if;

  return membership;
end;
$$;


ALTER FUNCTION "public"."mark_member_identity_revoked"("target_organization_id" "uuid", "target_user_id" "uuid", "new_cleanup_state" "text", "cleanup_error" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_member_identity_revoked"("target_organization_id" "uuid", "target_user_id" "uuid", "new_cleanup_state" "text", "cleanup_error" "text") IS 'Records how far the Auth cleanup after a permanent removal has got. Forward only, safe to repeat, and writes the single member.identity_revoked history line the first time it completes.';



CREATE OR REPLACE FUNCTION "public"."mark_onboarding_application_not_proceeding"("target_application_id" "uuid", "actor_email" "text", "reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  app_stage text;
  app_possible_duplicate boolean;
  app_already_acknowledged boolean;
  clean_reason text;
begin
  select stage, possible_duplicate, duplicate_acknowledged_at is not null
  into app_stage, app_possible_duplicate, app_already_acknowledged
  from public.platform_onboarding_applications
  where id = target_application_id
  for update;

  if not found then
    raise exception 'The onboarding application does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if app_stage not in ('new', 'awaiting_payment', 'needs_attention') then
    raise exception 'Only an unpaid application can be marked not proceeding.' using errcode = 'check_violation';
  end if;

  clean_reason := nullif(trim(coalesce(reason, '')), '');
  if app_possible_duplicate and not app_already_acknowledged and clean_reason is null then
    raise exception 'A private reason is required to close a possible duplicate.'
      using errcode = 'check_violation';
  end if;

  update public.platform_onboarding_applications
  set stage = 'not_proceeding', not_proceeding_at = now()
  where id = target_application_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, after_state
  ) values (
    actor_email, 'onboarding_application.not_proceeding', 'onboarding_application', target_application_id::text,
    case when clean_reason is null then null else jsonb_build_object('reason', clean_reason) end
  );
end;
$$;


ALTER FUNCTION "public"."mark_onboarding_application_not_proceeding"("target_application_id" "uuid", "actor_email" "text", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_onboarding_application_reviewed"("target_application_id" "uuid", "actor_email" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  app_stage text;
begin
  select stage into app_stage
  from public.platform_onboarding_applications
  where id = target_application_id
  for update;

  if not found then
    raise exception 'The onboarding application does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if app_stage <> 'new' then
    raise exception 'Only a new application can be marked reviewed.' using errcode = 'check_violation';
  end if;

  update public.platform_onboarding_applications
  set stage = 'awaiting_payment'
  where id = target_application_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key
  ) values (
    actor_email, 'onboarding_application.reviewed', 'onboarding_application', target_application_id::text
  );
end;
$$;


ALTER FUNCTION "public"."mark_onboarding_application_reviewed"("target_application_id" "uuid", "actor_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_team_invitation_auth_attempt_started"("target_invitation_id" "uuid", "target_attempt_nonce" "uuid") RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_row public.organization_member_invitations;
begin
  update public.organization_member_invitations
  set auth_attempt_started_at = now(), auth_attempt_nonce = target_attempt_nonce
  where id = target_invitation_id and state = 'reserving'
  returning * into updated_row;

  if not found then
    raise exception 'Invitation % is not reserving; an Auth attempt cannot be marked.', target_invitation_id
      using errcode = 'check_violation';
  end if;

  return updated_row;
end;
$$;


ALTER FUNCTION "public"."mark_team_invitation_auth_attempt_started"("target_invitation_id" "uuid", "target_attempt_nonce" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_team_notifications_read"("p_organization_id" "uuid", "p_user_id" "uuid", "p_notification_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  changed integer;
begin
  if p_notification_ids is not null and cardinality(p_notification_ids) > 100 then
    raise exception 'Mark at most 100 alerts at once.' using errcode = 'check_violation';
  end if;

  -- Null ids means "mark all as read".
  update public.team_notifications
  set read_at = now()
  where organization_id = p_organization_id and user_id = p_user_id and read_at is null
    and (p_notification_ids is null or id = any (p_notification_ids));

  get diagnostics changed = row_count;
  return changed;
end;
$$;


ALTER FUNCTION "public"."mark_team_notifications_read"("p_organization_id" "uuid", "p_user_id" "uuid", "p_notification_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."marketing_preview_counts"("target_organization_id" "uuid", "rules" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  result jsonb;
begin
  execute format($sql$
    select jsonb_build_object(
      'matches', count(*),
      'eligible', count(distinct email) filter (where blocked_reason is null),
      'excluded', count(*) - count(distinct email) filter (where blocked_reason is null),
      'excluded_by_reason', jsonb_build_object(
        'inactive_customer', count(*) filter (where blocked_reason = 'inactive_customer'),
        'missing_email', count(*) filter (where blocked_reason = 'missing_email'),
        'unsubscribed', count(*) filter (where blocked_reason = 'unsubscribed'),
        'complaint', count(*) filter (where blocked_reason = 'complaint'),
        'hard_bounce', count(*) filter (where blocked_reason = 'hard_bounce'),
        'do_not_disturb', count(*) filter (where blocked_reason = 'do_not_disturb'),
        'no_marketing', count(*) filter (where blocked_reason = 'no_marketing'),
        'no_consent', count(*) filter (where blocked_reason = 'no_consent'),
        'recent_marketing', 0,
        'duplicate_destination',
          count(*) filter (where blocked_reason is null) - count(distinct email) filter (where blocked_reason is null)
      )
    )
    from (%s) evaluated
  $sql$, private.marketing_evaluated_recipients_sql(rules))
  into result
  using rules, target_organization_id;

  return result;
end;
$_$;


ALTER FUNCTION "public"."marketing_preview_counts"("target_organization_id" "uuid", "rules" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."marketing_preview_counts"("target_organization_id" "uuid", "rules" "jsonb") IS 'Exact matches, eligible recipients, and excluded recipients by reason for one organization and rule set.';



CREATE OR REPLACE FUNCTION "public"."marketing_preview_recipients"("target_organization_id" "uuid", "rules" "jsonb", "status_filter" "text" DEFAULT 'all'::"text", "after_display_name" "text" DEFAULT NULL::"text", "after_client_id" "uuid" DEFAULT NULL::"uuid", "page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  result jsonb;
  bounded_page_size integer := least(greatest(coalesce(page_size, 50), 1), 200);
begin
  if status_filter is null or status_filter not in ('all', 'eligible', 'excluded') then
    raise exception 'Unknown recipient preview filter.' using errcode = '22023';
  end if;

  execute format($sql$
    select coalesce(jsonb_agg(row_to_json(page) order by page.display_name, page.client_id), '[]'::jsonb)
    from (
      select evaluated.client_id, evaluated.display_name, evaluated.email, evaluated.excluded_reason
      from (
        select
          client_id,
          display_name,
          email,
          coalesce(
            blocked_reason,
            case
              when row_number() over (
                partition by (case when blocked_reason is null then email end)
                order by display_name, client_id
              ) > 1 then 'duplicate_destination'
            end
          ) as excluded_reason
        from (%s) reachable
      ) evaluated
      where ($3 = 'all'
             or ($3 = 'eligible' and evaluated.excluded_reason is null)
             or ($3 = 'excluded' and evaluated.excluded_reason is not null))
        and ($4::text is null
             or (evaluated.display_name, evaluated.client_id) > ($4::text, $5::uuid))
      order by evaluated.display_name, evaluated.client_id
      limit $6
    ) page
  $sql$, private.marketing_evaluated_recipients_sql(rules))
  into result
  using rules, target_organization_id, status_filter, after_display_name, after_client_id,
        bounded_page_size;

  return result;
end;
$_$;


ALTER FUNCTION "public"."marketing_preview_recipients"("target_organization_id" "uuid", "rules" "jsonb", "status_filter" "text", "after_display_name" "text", "after_client_id" "uuid", "page_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."marketing_preview_recipients"("target_organization_id" "uuid", "rules" "jsonb", "status_filter" "text", "after_display_name" "text", "after_client_id" "uuid", "page_size" integer) IS 'One bounded keyset page of the Customers a rule set matches, each with the reason it would not reach them.';



CREATE OR REPLACE FUNCTION "public"."marketing_update_campaign_draft"("target_organization_id" "uuid", "target_campaign_id" "uuid", "actor_user_id" "uuid", "expected_revision" integer, "new_name" "text", "new_goal" "text", "new_customer_group_id" "uuid", "new_template_id" "uuid", "new_content" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  campaign_row public.marketing_campaigns;
  clean_name text;
  new_revision integer;
  new_updated_at timestamptz;
begin
  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) > 160 then
    raise exception 'Give this campaign a name under 160 characters.' using errcode = 'check_violation';
  end if;

  if new_goal not in ('bring_back', 'promote_service', 'announcement', 'blank') then
    raise exception 'Unknown campaign goal.' using errcode = 'check_violation';
  end if;

  if new_content is null or jsonb_typeof(new_content) <> 'object' then
    raise exception 'Campaign content must be an object.' using errcode = 'check_violation';
  end if;

  select * into campaign_row
  from public.marketing_campaigns
  where id = target_campaign_id and organization_id = target_organization_id
  for update;

  if campaign_row.id is null then
    raise exception 'This campaign no longer exists.' using errcode = 'check_violation';
  end if;

  if campaign_row.status <> 'draft' then
    raise exception 'Only a draft campaign can be changed.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from campaign_row.revision then
    raise exception 'Someone else changed this campaign while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  if new_customer_group_id is not null and not exists (
    select 1 from public.marketing_customer_groups g
    where g.id = new_customer_group_id
      and g.organization_id = target_organization_id
      and g.archived_at is null
  ) then
    raise exception 'Choose a saved customer group.' using errcode = 'check_violation';
  end if;

  if new_template_id is not null and not exists (
    select 1 from public.marketing_email_templates t
    where t.id = new_template_id and t.organization_id = target_organization_id
  ) then
    raise exception 'Choose a valid template.' using errcode = 'check_violation';
  end if;

  update public.marketing_campaigns
  set name = clean_name,
      goal = new_goal,
      customer_group_id = new_customer_group_id,
      template_id = new_template_id,
      content = new_content,
      revision = revision + 1,
      updated_by = actor_user_id
  where id = campaign_row.id
  returning revision, updated_at into new_revision, new_updated_at;

  return jsonb_build_object('revision', new_revision, 'updated_at', new_updated_at);
end;
$$;


ALTER FUNCTION "public"."marketing_update_campaign_draft"("target_organization_id" "uuid", "target_campaign_id" "uuid", "actor_user_id" "uuid", "expected_revision" integer, "new_name" "text", "new_goal" "text", "new_customer_group_id" "uuid", "new_template_id" "uuid", "new_content" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."marketing_update_campaign_draft"("target_organization_id" "uuid", "target_campaign_id" "uuid", "actor_user_id" "uuid", "expected_revision" integer, "new_name" "text", "new_goal" "text", "new_customer_group_id" "uuid", "new_template_id" "uuid", "new_content" "jsonb") IS 'Saves a campaign draft. Refuses with P0409 when expected_revision does not match the stored revision, so the caller reloads instead of overwriting a change it never saw. Only a draft-status campaign can be changed; M4''s launch/cancel commands own every other status transition.';



CREATE OR REPLACE FUNCTION "public"."match_active_opening_balances"("target_org" "uuid", "client_ids" "uuid"[]) RETURNS TABLE("client_id" "uuid", "balance_type" "text", "opening_balance_id" "uuid", "amount_minor" bigint, "as_of_date" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select fact.client_id, fact.balance_type, fact.id, fact.amount_minor, fact.as_of_date
  from public.client_opening_balances fact
  where fact.organization_id = target_org
    and fact.replaced_at is null
    and fact.client_id = any(client_ids)
    and private.has_permission(target_org, 'invoices.create');
$$;


ALTER FUNCTION "public"."match_active_opening_balances"("target_org" "uuid", "client_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."match_active_opening_balances"("target_org" "uuid", "client_ids" "uuid"[]) IS 'Every current (unreplaced) opening-balance fact for the named clients, one row per {client, balance_type}. Review uses this to turn a second file row for a client''s already-recorded balance type into a correction (predecessor_opening_balance_id) instead of a silent duplicate. SECURITY DEFINER so the read is guaranteed even when invoices.view is not separately granted alongside the invoices.create this whole flow requires; self-checked in the WHERE clause rather than trusting the caller, same backstop every import RPC uses.';



CREATE OR REPLACE FUNCTION "public"."match_import_clients"("target_org" "uuid", "emails" "text"[], "phones" "text"[]) RETURNS TABLE("client_id" "uuid", "matched_kind" "text", "matched_value" "text", "client_type" "text", "first_name" "text", "last_name" "text", "company_name" "text", "lead_source" "text", "has_email" boolean, "has_phone" boolean, "has_property" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    m.client_id,
    m.kind as matched_kind,
    m.normalized_value as matched_value,
    c.client_type,
    c.first_name,
    c.last_name,
    c.company_name,
    c.lead_source,
    exists (
      select 1 from public.client_contact_methods e
      where e.client_id = c.id and e.kind = 'email'
    ) as has_email,
    exists (
      select 1 from public.client_contact_methods p
      where p.client_id = c.id and p.kind = 'phone'
    ) as has_phone,
    exists (
      select 1 from public.properties pr
      where pr.client_id = c.id and pr.deleted_at is null
    ) as has_property
  from public.client_contact_methods m
  join public.clients c
    on c.id = m.client_id
   and c.organization_id = target_org
   and c.deleted_at is null
  where m.organization_id = target_org
    and (
      (m.kind = 'email' and m.normalized_value = any(emails))
      or (m.kind = 'phone' and m.normalized_value = any(phones))
    );
$$;


ALTER FUNCTION "public"."match_import_clients"("target_org" "uuid", "emails" "text"[], "phones" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mint_website_chat_realtime_grant"("session_token_hash" "text", "requesting_origin" "text", "proposed_topic" "text", "ttl_seconds" integer DEFAULT 1800) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "statement_timeout" TO '5000'
    AS $_$
declare
  target_session public.website_chat_sessions;
  widget record;
  normalized_origin text := lower(btrim(coalesce(requesting_origin, '')));
  origin_allowed boolean;
  effective_ttl integer := least(greatest(coalesce(ttl_seconds, 1800), 60), 1800);
  rate_check record;
  existing public.website_chat_realtime_grants;
  granted_topic text;
  granted_expiry timestamptz;
begin
  if normalized_origin = ''
     or nullif(btrim(coalesce(session_token_hash, '')), '') is null
     or coalesce(proposed_topic, '') !~ '^wc:[0-9a-f]{64}$' then
    return jsonb_build_object('status', 'refused');
  end if;

  select * into target_session
  from public.website_chat_sessions s
  where s.session_token_hash = btrim(mint_website_chat_realtime_grant.session_token_hash);
  if not found then
    return jsonb_build_object('status', 'refused');
  end if;

  select w.id, w.organization_id into widget
  from public.website_chat_widgets w
  where w.id = target_session.widget_id;
  if not found then
    return jsonb_build_object('status', 'refused');
  end if;

  select exists (
    select 1 from public.website_chat_widget_origins o
    where o.widget_id = widget.id and o.origin = normalized_origin
  ) into origin_allowed;
  if not origin_allowed then
    return jsonb_build_object('status', 'refused');
  end if;

  select * into rate_check
  from public.check_rate_limit('website_chat:realtime_mint:' || target_session.id::text, 60, 20);
  if not rate_check.allowed then
    return jsonb_build_object('status', 'rate_limited');
  end if;

  select * into existing
  from public.website_chat_realtime_grants g
  where g.session_id = target_session.id;

  if found and existing.expires_at > now() + interval '5 minutes' then
    granted_topic := existing.channel_topic;
    granted_expiry := existing.expires_at;
  else
    insert into public.website_chat_realtime_grants as g
      (session_id, organization_id, channel_topic, expires_at)
    values (
      target_session.id,
      target_session.organization_id,
      proposed_topic,
      now() + make_interval(secs => effective_ttl)
    )
    on conflict (session_id) do update
      set channel_topic = excluded.channel_topic,
          expires_at = excluded.expires_at,
          updated_at = now()
    returning g.channel_topic, g.expires_at into granted_topic, granted_expiry;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'session_id', target_session.id,
    'channel_topic', granted_topic,
    'expires_at', granted_expiry
  );
end;
$_$;


ALTER FUNCTION "public"."mint_website_chat_realtime_grant"("session_token_hash" "text", "requesting_origin" "text", "proposed_topic" "text", "ttl_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mint_website_chat_realtime_grant"("session_token_hash" "text", "requesting_origin" "text", "proposed_topic" "text", "ttl_seconds" integer) IS 'Authorizes one Website Chat session onto one short-lived private Realtime topic. Same authorization pair as every other public command -- the session secret plus an allowlisted origin -- and the same silent refusal shape.';



CREATE OR REPLACE FUNCTION "public"."move_client_payment"("target_organization_id" "uuid", "target_allocation_id" "uuid", "target_invoice_id" "uuid", "new_amount_minor" bigint, "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  allocation_row public.invoice_payment_allocations;
  from_invoice public.invoices;
  to_invoice public.invoices;
  first_id uuid;
  second_id uuid;
  reversal_id uuid;
  allocation_id uuid;
  moved bigint;
begin
  if caller is null then
    raise exception 'You must be signed in to move a payment.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.correct_payment') then
    raise exception 'You do not have access to correct payments here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  replayed := private.begin_invoice_command(
    target_organization_id, 'move_client_payment', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  select * into allocation_row
  from public.invoice_payment_allocations
  where organization_id = target_organization_id and id = target_allocation_id;
  if not found then
    raise exception 'That payment entry could not be found.' using errcode = 'P0404';
  end if;
  if allocation_row.invoice_id = target_invoice_id then
    raise exception 'That payment is already on that invoice.' using errcode = 'check_violation';
  end if;

  first_id := least(allocation_row.invoice_id, target_invoice_id);
  second_id := greatest(allocation_row.invoice_id, target_invoice_id);
  perform private.lock_invoice_for_payment(target_organization_id, first_id);
  perform private.lock_invoice_for_payment(target_organization_id, second_id);

  select * into from_invoice from public.invoices
  where organization_id = target_organization_id and id = allocation_row.invoice_id;
  select * into to_invoice from public.invoices
  where organization_id = target_organization_id and id = target_invoice_id;

  if to_invoice.client_id <> from_invoice.client_id then
    raise exception 'Money can only move between the same client''s invoices.'
      using errcode = 'check_violation';
  end if;
  if to_invoice.currency_code <> allocation_row.currency_code then
    raise exception 'That invoice was written in a different currency.' using errcode = 'check_violation';
  end if;

  moved := coalesce(new_amount_minor, allocation_row.amount_minor);
  if moved > allocation_row.amount_minor then
    raise exception 'That is more than the payment on invoice #%.', from_invoice.invoice_number
      using errcode = 'check_violation',
      detail = format('%s on the invoice, %s offered', allocation_row.amount_minor, moved);
  end if;

  reversal_id := private.reverse_invoice_allocation(from_invoice, allocation_row, caller, new_reason);
  allocation_id := private.apply_invoice_allocation(
    to_invoice, allocation_row.payment_event_id, allocation_row.deposit_event_id, moved, caller, new_reason
  );

  return private.complete_invoice_command(
    target_organization_id, 'move_client_payment', new_idempotency_key,
    jsonb_build_object(
      'reversed_allocation_id', allocation_row.id,
      'unapplied_allocation_id', reversal_id,
      'allocation_id', allocation_id,
      'from_invoice_id', from_invoice.id,
      'from_invoice_number', from_invoice.invoice_number,
      'invoice_id', to_invoice.id,
      'invoice_number', to_invoice.invoice_number,
      'amount_minor', moved,
      'returned_to_credit_minor', allocation_row.amount_minor - moved
    )
  );
end;
$$;


ALTER FUNCTION "public"."move_client_payment"("target_organization_id" "uuid", "target_allocation_id" "uuid", "target_invoice_id" "uuid", "new_amount_minor" bigint, "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."move_client_payment"("target_organization_id" "uuid", "target_allocation_id" "uuid", "target_invoice_id" "uuid", "new_amount_minor" bigint, "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Moves money from one of a client''s bills to another in one transaction, leaving both the entry that took it off and the entry that put it on. Moving part of it returns the rest to available credit.';



CREATE OR REPLACE FUNCTION "public"."move_job_visits"("target_organization_id" "uuid", "target_job_id" "uuid", "visit_ids" "jsonb", "day_offset" integer, "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  receipt_id uuid;
  existing_receipt public.job_command_receipts;
  id_list uuid[];
  moved_count integer;
  final_result jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to schedule a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.schedule') then
    raise exception 'You do not have access to schedule this job.' using errcode = 'insufficient_privilege';
  end if;

  if day_offset is null or day_offset = 0 then
    raise exception 'Choose how many days to move the visits.' using errcode = 'check_violation';
  end if;
  if abs(day_offset) > 3650 then
    raise exception 'Visits can only be moved within ten years.' using errcode = 'check_violation';
  end if;
  if jsonb_typeof(visit_ids) is distinct from 'array' or jsonb_array_length(visit_ids) < 1 then
    raise exception 'Choose at least one visit to move.' using errcode = 'check_violation';
  end if;
  if jsonb_array_length(visit_ids) > 100 then
    raise exception 'Up to 100 visits can be moved at once.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(new_idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(new_request_hash, ''))) < 1 then
    raise exception 'A request fingerprint is required.' using errcode = 'check_violation';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id
    and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  insert into public.job_command_receipts (organization_id, action, idempotency_key, request_hash)
  values (target_organization_id, 'move_job_visits', new_idempotency_key, new_request_hash)
  on conflict (organization_id, action, idempotency_key) do nothing
  returning id into receipt_id;

  if receipt_id is null then
    select receipt.* into existing_receipt
    from public.job_command_receipts as receipt
    where receipt.organization_id = target_organization_id
      and receipt.action = 'move_job_visits'
      and receipt.idempotency_key = new_idempotency_key;

    if existing_receipt.request_hash is distinct from new_request_hash then
      raise exception 'Those visits were already moved differently.' using errcode = 'P0409';
    end if;

    return coalesce(existing_receipt.result, '{}'::jsonb) || jsonb_build_object('applied', false);
  end if;

  select array_agg((element #>> '{}')::uuid) into id_list
  from jsonb_array_elements(visit_ids) as element;

  update public.job_visits
  set visit_date = visit_date + day_offset,
      revision = revision + 1,
      updated_at = now()
  where organization_id = target_organization_id
    and job_id = target_job_id
    and id = any(id_list)
    and visit_date is not null
    and completed_at is null;
  get diagnostics moved_count = row_count;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'visits_moved',
    caller,
    jsonb_build_object('count', moved_count, 'day_offset', day_offset)
  );

  final_result := jsonb_build_object('applied', true, 'moved_count', moved_count);
  update public.job_command_receipts set result = final_result where id = receipt_id;
  return final_result;
end;
$$;


ALTER FUNCTION "public"."move_job_visits"("target_organization_id" "uuid", "target_job_id" "uuid", "visit_ids" "jsonb", "day_offset" integer, "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."move_job_visits"("target_organization_id" "uuid", "target_job_id" "uuid", "visit_ids" "jsonb", "day_offset" integer, "new_idempotency_key" "text", "new_request_hash" "text") IS 'Shifts the dated, incomplete visits in the list by day_offset days. Checks jobs.schedule, idempotent by key, skips unscheduled and completed visits, and appends a visits_moved history row with the moved count.';



CREATE OR REPLACE FUNCTION "public"."open_invoice_stripe_checkout"("supplied_token_hash" "bytea", "new_amount_minor" bigint, "new_tip_minor" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  context jsonb;
  checkout_id uuid;
  balance bigint;
begin
  context := public.invoice_online_payment_context(supplied_token_hash);
  if context is null then
    raise exception 'This invoice is not available.' using errcode = 'P0404';
  end if;

  perform 1 from public.invoices
  where organization_id = (context->>'organization_id')::uuid and id = (context->>'invoice_id')::uuid
  for update;
  context := public.invoice_online_payment_context(supplied_token_hash);

  if not (context->>'available')::boolean then
    raise exception 'Online payment is not available for this invoice.' using errcode = 'check_violation',
      detail = context->>'unavailable_reason';
  end if;

  balance := (context->>'balance_minor')::bigint;
  if new_amount_minor is null or new_amount_minor <= 0 or new_amount_minor > balance then
    raise exception 'That amount is more than this invoice still owes.' using errcode = 'check_violation',
      detail = 'amount';
  end if;
  if new_amount_minor <> balance and not (context->>'partial_allowed')::boolean then
    raise exception 'This invoice has to be paid in full.' using errcode = 'check_violation',
      detail = 'amount';
  end if;
  if coalesce(new_tip_minor, 0) < 0
     or (coalesce(new_tip_minor, 0) > 0 and not (context->>'tips_enabled')::boolean)
     or coalesce(new_tip_minor, 0) > greatest(balance, (context->>'tip_base_minor')::bigint) then
    raise exception 'That tip cannot be added.' using errcode = 'check_violation', detail = 'tip';
  end if;

  insert into public.payment_stripe_checkouts (
    organization_id, invoice_id, client_id, stripe_account_id, livemode, amount_minor, tip_minor,
    currency_code
  ) values (
    (context->>'organization_id')::uuid, (context->>'invoice_id')::uuid, (context->>'client_id')::uuid,
    context->>'stripe_account_id', (context->>'livemode')::boolean, new_amount_minor,
    coalesce(new_tip_minor, 0), context->>'currency_code'
  )
  returning id into checkout_id;

  return context || jsonb_build_object('checkout_id', checkout_id);
end;
$$;


ALTER FUNCTION "public"."open_invoice_stripe_checkout"("supplied_token_hash" "bytea", "new_amount_minor" bigint, "new_tip_minor" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_quote_deposit_stripe_checkout"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  context jsonb;
  checkout_id uuid;
begin
  context := public.quote_online_deposit_context(supplied_token_hash);
  if context is null then
    raise exception 'This quote is not available.' using errcode = 'P0404';
  end if;

  perform 1 from public.quotes
  where organization_id = (context->>'organization_id')::uuid and id = (context->>'quote_id')::uuid
  for update;
  context := public.quote_online_deposit_context(supplied_token_hash);

  if not (context->>'available')::boolean then
    raise exception 'Online payment is not available for this quote.' using errcode = 'check_violation',
      detail = context->>'unavailable_reason';
  end if;

  insert into public.payment_stripe_checkouts (
    organization_id, kind, quote_id, quote_version_id, client_id, stripe_account_id, livemode,
    amount_minor, tip_minor, currency_code
  ) values (
    (context->>'organization_id')::uuid, 'quote_deposit', (context->>'quote_id')::uuid,
    (context->>'quote_version_id')::uuid, (context->>'client_id')::uuid, context->>'stripe_account_id',
    (context->>'livemode')::boolean, (context->>'deposit_required_minor')::bigint, 0,
    context->>'currency_code'
  )
  returning id into checkout_id;

  return context || jsonb_build_object('checkout_id', checkout_id);
end;
$$;


