CREATE OR REPLACE FUNCTION "public"."owner_organization_directory"("search_term" "text" DEFAULT NULL::"text", "attention_reason" "text" DEFAULT NULL::"text", "cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "cursor_id" "uuid" DEFAULT NULL::"uuid", "page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with org_context as (
    select
      o.id,
      o.name,
      o.slug,
      o.lifecycle_status,
      o.created_at,
      o.updated_at,
      coalesce(cs.commercial_timezone, 'UTC') as commercial_timezone,
      (now() at time zone coalesce(cs.commercial_timezone, 'UTC'))::date as today_date,
      st.paid_through_date,
      st.grace_ends_at
    from public.organizations o
    left join public.organization_commercial_settings cs on cs.organization_id = o.id
    left join public.organization_commercial_state st on st.organization_id = o.id
  ),
  member_counts as (
    select
      organization_id,
      count(*) as member_count,
      count(*) filter (where role = 'owner') as owner_count
    from public.organization_members
    group by organization_id
  ),
  free_access_latest as (
    select distinct on (event.organization_id, coalesce(event.target_grant_id, event.id))
      event.organization_id,
      event.action,
      event.starts_at,
      event.access_until_date
    from public.organization_free_access_events event
    order by event.organization_id, coalesce(event.target_grant_id, event.id), event.occurred_at desc, event.id desc
  ),
  free_access_summary as (
    select
      oc.id as organization_id,
      coalesce(bool_or(
        fal.action <> 'end'
        and fal.starts_at <= oc.today_date
        and (fal.access_until_date is null or fal.access_until_date >= oc.today_date)
      ), false) as free_access_active,
      coalesce(bool_or(
        fal.action <> 'end'
        and fal.starts_at <= oc.today_date
        and fal.access_until_date is not null
        and fal.access_until_date >= oc.today_date
        and (fal.access_until_date - oc.today_date) <= 7
      ), false) as free_access_expiring_soon
    from org_context oc
    left join free_access_latest fal on fal.organization_id = oc.id
    group by oc.id
  ),
  package_exception_summary as (
    select
      oc.id as organization_id,
      (
        exists (
          select 1 from public.organization_feature_overrides f
          where f.organization_id = oc.id
            and f.expires_at is not null
            and f.starts_at <= now()
            and ((f.expires_at at time zone oc.commercial_timezone)::date - oc.today_date) between 0 and 7
        )
        or exists (
          select 1 from public.organization_limit_overrides l
          where l.organization_id = oc.id
            and l.expires_at is not null
            and l.starts_at <= now()
            and ((l.expires_at at time zone oc.commercial_timezone)::date - oc.today_date) between 0 and 7
        )
      ) as package_exception_expiring_soon
    from org_context oc
  ),
  setup_recovery_summary as (
    select
      oc.id as organization_id,
      exists (
        select 1 from public.platform_operation_attempts op
        where op.target_kind = 'organization'
          and op.target_id = oc.id
          and op.status in ('pending', 'retrying')
      ) as setup_or_recovery_failed
    from org_context oc
  ),
  owner_emails as (
    select
      m.organization_id,
      array_agg(distinct u.email) filter (where u.email is not null) as owner_email_list
    from public.organization_members m
    join auth.users u on u.id = m.user_id
    where m.role = 'owner'
    group by m.organization_id
  ),
  computed as (
    select
      oc.id,
      oc.name,
      oc.slug,
      oc.lifecycle_status,
      oc.created_at,
      oc.updated_at,
      coalesce(mc.member_count, 0) as member_count,
      coalesce(mc.owner_count, 0) as owner_count,
      (
        oc.paid_through_date is not null
        and (oc.paid_through_date >= oc.today_date or (oc.grace_ends_at is not null and oc.grace_ends_at >= now()))
      ) as paid_through_eligible,
      coalesce(fas.free_access_active, false) as free_access_active,
      coalesce(fas.free_access_expiring_soon, false) as free_access_expiring_soon,
      coalesce(pes.package_exception_expiring_soon, false) as package_exception_expiring_soon,
      coalesce(srs.setup_or_recovery_failed, false) as setup_or_recovery_failed,
      coalesce(oe.owner_email_list, array[]::text[]) as owner_email_list
    from org_context oc
    left join member_counts mc on mc.organization_id = oc.id
    left join free_access_summary fas on fas.organization_id = oc.id
    left join package_exception_summary pes on pes.organization_id = oc.id
    left join setup_recovery_summary srs on srs.organization_id = oc.id
    left join owner_emails oe on oe.organization_id = oc.id
  ),
  reasoned as (
    select
      c.*,
      (c.lifecycle_status = 'active' and not c.paid_through_eligible and not c.free_access_active)
        as is_access_overdue,
      (c.free_access_expiring_soon or c.package_exception_expiring_soon) as is_expiring_soon,
      (c.owner_count = 0) as is_administrator_missing,
      (c.owner_count > 1) as is_administrator_ownership_unclear,
      c.setup_or_recovery_failed as is_setup_or_recovery_failed,
      (c.lifecycle_status = 'pending_setup') as is_legacy_review
    from computed c
  ),
  tagged as (
    select
      r.*,
      array_remove(
        array[
          case when is_access_overdue then 'access_overdue' end,
          case when is_administrator_missing then 'administrator_missing' end,
          case when is_administrator_ownership_unclear then 'administrator_ownership_unclear' end,
          case when is_setup_or_recovery_failed then 'setup_or_recovery_failed' end,
          case when is_expiring_soon then 'expiring_soon' end,
          case when is_legacy_review then 'legacy_review' end
        ],
        null
      ) as attention_reasons
    from reasoned r
  ),
  matching as (
    select t.*
    from tagged t
    where
      search_term is null
      or trim(search_term) = ''
      or t.name ilike '%' || search_term || '%'
      or t.slug ilike '%' || search_term || '%'
      or exists (select 1 from unnest(t.owner_email_list) as email where email ilike '%' || search_term || '%')
  ),
  filtered as (
    select m.*
    from matching m
    where attention_reason is null or attention_reason = any(m.attention_reasons)
  ),
  page as (
    select f.*
    from filtered f
    where cursor_created_at is null or (f.created_at, f.id) < (cursor_created_at, cursor_id)
    order by f.created_at desc, f.id desc
    limit least(greatest(coalesce(page_size, 50), 1), 100)
  ),
  page_meta as (
    select count(*) as returned_count from page
  ),
  page_last as (
    select created_at, id from page order by created_at asc, id asc limit 1
  ),
  totals as (
    select
      count(*) as all_count,
      count(*) filter (where lifecycle_status = 'active') as active_count,
      count(*) filter (where lifecycle_status = 'suspended') as suspended_count,
      count(*) filter (where lifecycle_status = 'pending_setup') as pending_setup_count,
      count(*) filter (where is_access_overdue) as access_overdue_count,
      count(*) filter (where is_expiring_soon) as expiring_soon_count,
      count(*) filter (where is_administrator_missing) as administrator_missing_count,
      count(*) filter (where is_administrator_ownership_unclear) as administrator_ownership_unclear_count,
      count(*) filter (where is_setup_or_recovery_failed) as setup_or_recovery_failed_count,
      count(*) filter (where is_legacy_review) as legacy_review_count
    from tagged
  ),
  matching_totals as (
    select count(*) as matching_count from filtered
  )
  select jsonb_build_object(
    'organizations', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', p.id,
            'name', p.name,
            'slug', p.slug,
            'lifecycle_status', p.lifecycle_status,
            'created_at', p.created_at,
            'updated_at', p.updated_at,
            'member_count', p.member_count,
            'attention_reasons', to_jsonb(p.attention_reasons)
          )
          order by p.created_at desc, p.id desc
        )
        from page p
      ),
      '[]'::jsonb
    ),
    'next_cursor', case
      when (select returned_count from page_meta) >= least(greatest(coalesce(page_size, 50), 1), 100)
        then (select jsonb_build_object('created_at', pl.created_at, 'id', pl.id) from page_last pl)
      else null
    end,
    'totals', jsonb_build_object(
      'all', (select all_count from totals),
      'active', (select active_count from totals),
      'suspended', (select suspended_count from totals),
      'pending_setup', (select pending_setup_count from totals),
      'matching', (select matching_count from matching_totals),
      'attention', jsonb_build_object(
        'access_overdue', (select access_overdue_count from totals),
        'expiring_soon', (select expiring_soon_count from totals),
        'administrator_missing', (select administrator_missing_count from totals),
        'administrator_ownership_unclear', (select administrator_ownership_unclear_count from totals),
        'setup_or_recovery_failed', (select setup_or_recovery_failed_count from totals),
        'legacy_review', (select legacy_review_count from totals)
      )
    )
  );
$$;


ALTER FUNCTION "public"."owner_organization_directory"("search_term" "text", "attention_reason" "text", "cursor_created_at" timestamp with time zone, "cursor_id" "uuid", "page_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."owner_organization_directory"("search_term" "text", "attention_reason" "text", "cursor_created_at" timestamp with time zone, "cursor_id" "uuid", "page_size" integer) IS 'Read-only, service_role-only search, attention-reason computation, and keyset pagination for the Platform Owner organization directory.';



CREATE OR REPLACE FUNCTION "public"."pause_automation_enrollment"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  existing_receipt public.automation_enrollment_command_receipts%rowtype;
  enrollment private.automation_enrollments%rowtype;
  pending_item private.automation_work_items%rowtype;
  v_has_pending boolean;
  v_pending_due timestamptz;
  command_result jsonb;
begin
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;

  select * into existing_receipt
  from public.automation_enrollment_command_receipts
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_receipt.result || jsonb_build_object('idempotent_replay', true);
  end if;

  select * into enrollment
  from private.automation_enrollments
  where id = p_enrollment_id and organization_id = p_organization_id
  for update;
  if not found then
    raise exception 'That enrollment does not exist.' using errcode = 'no_data_found';
  end if;
  if enrollment.state <> 'active' then
    raise exception 'Only an active enrollment can be paused.' using errcode = 'restrict_violation';
  end if;

  select * into pending_item
  from private.automation_work_items
  where enrollment_id = p_enrollment_id and state = 'pending'
  order by step_index
  limit 1
  for update;
  v_has_pending := found;
  v_pending_due := pending_item.due_at;

  if v_has_pending and pending_item.claim_token is null then
    update private.automation_work_items
    set state = 'cancelled'
    where id = pending_item.id;
  end if;

  update private.automation_enrollments
  set state = 'paused',
      paused_work_due_at = case when v_has_pending then v_pending_due else null end
  where id = p_enrollment_id;

  command_result := jsonb_build_object('enrollment_id', p_enrollment_id, 'state', 'paused');

  insert into public.automation_enrollment_command_receipts (
    organization_id, idempotency_key, command, subject_type, subject_id, enrollment_id, result
  ) values (
    p_organization_id, p_idempotency_key, 'pause', enrollment.subject_type, enrollment.subject_id,
    p_enrollment_id, command_result
  );

  return command_result;
end;
$$;


ALTER FUNCTION "public"."pause_automation_enrollment"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pause_automation_enrollment"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_idempotency_key" "uuid") IS 'Pauses an active enrollment and parks its next step at its original due time so resume never delays the reminder. Idempotent per organization + key. Service role only.';



CREATE OR REPLACE FUNCTION "public"."payment_detail"("target_organization_id" "uuid", "target_payment_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  payment_row public.client_payment_events;
begin
  if not private.member_has_permission(target_organization_id, caller, 'invoices.view')
     or not private.member_has_permission(target_organization_id, caller, 'invoices.view_price') then
    raise exception 'You do not have access to this payment.' using errcode = 'insufficient_privilege';
  end if;

  select * into payment_row
  from public.client_payment_events
  where organization_id = target_organization_id and id = target_payment_event_id;

  -- A refund or a reversal is a correction, not a receipt, and this screen is the receipt's home. Same answer
  -- as a payment that does not exist, so the screen cannot be used to find out which is which.
  if payment_row.id is null or payment_row.event_type <> 'received' then
    raise exception 'That payment could not be found.' using errcode = 'P0404';
  end if;

  return jsonb_build_object(
    'payment', jsonb_build_object(
      'id', payment_row.id,
      'amount_minor', payment_row.amount_minor,
      'currency_code', payment_row.currency_code,
      'method', payment_row.method,
      'payment_date', payment_row.payment_date,
      'reference', payment_row.reference,
      'note', payment_row.note,
      'created_at', payment_row.created_at
    ),
    -- The same client card the invoice screen shows, read the same way: the primary email lives in
    -- client_contact_methods, not on the client row, and the send dialog needs it to say who the receipt
    -- goes to.
    'client', (
      select jsonb_build_object(
        'id', client.id,
        'display_name', client.display_name,
        'company_name', client.company_name,
        'email', (
          select lower(trim(method.value))
          from public.client_contact_methods as method
          where method.organization_id = target_organization_id
            and method.client_id = client.id
            and method.kind = 'email'
          order by method.is_primary desc, method.created_at
          limit 1
        )
      )
      from public.clients as client
      where client.organization_id = target_organization_id and client.id = payment_row.client_id
    ),
    -- What this money was put against. Applications and the entries that take them back both appear, oldest
    -- first, so a payment that was moved off a bill reads as what happened rather than as a gap. The invoice
    -- number is the allocation's own copy, so it still reads as "Invoice #14" after that draft is gone --
    -- and invoice_id is left null for a bill that no longer exists, which is what makes the link safe.
    -- is_reversed is true on an 'applied' row once some later row has taken it back off (unapply or the first
    -- half of a move) -- unapply_client_payment and move_client_payment both refuse a second reversal of the
    -- same allocation, so the screen uses this to stop offering an action that can only fail.
    'applied_to', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'allocation_id', allocation.id,
        'invoice_id', invoice.id,
        'invoice_number', allocation.invoice_number,
        'subject', invoice.subject,
        'entry_type', allocation.entry_type,
        'amount_minor', allocation.amount_minor,
        'created_at', allocation.created_at,
        'is_reversed', exists (
          select 1 from public.invoice_payment_allocations as reversal
          where reversal.organization_id = allocation.organization_id
            and reversal.reversed_allocation_id = allocation.id
        )
      ) order by allocation.created_at, allocation.id), '[]'::jsonb)
      from public.invoice_payment_allocations as allocation
      left join public.invoices as invoice
        on invoice.organization_id = allocation.organization_id and invoice.id = allocation.invoice_id
      where allocation.organization_id = target_organization_id
        and allocation.payment_event_id = target_payment_event_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."payment_detail"("target_organization_id" "uuid", "target_payment_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."payment_detail"("target_organization_id" "uuid", "target_payment_event_id" "uuid") IS 'One recorded payment for its detail screen: the receipt fields, the client, and the invoices it was applied to, each application flagged is_reversed once it has been taken back off. Definer; requires invoices.view and invoices.view_price, because a payment with its amount withheld is nothing. Refunds and reversals are not found here -- this screen is the receipt''s home.';



CREATE OR REPLACE FUNCTION "public"."payment_receipt_preview"("target_payment_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  payment_row public.client_payment_events;
  business_name text;
begin
  select * into payment_row
  from public.client_payment_events
  where id = target_payment_event_id;

  if payment_row.id is null
     or payment_row.event_type <> 'received'
     or not private.member_has_permission(payment_row.organization_id, caller, 'invoices.view')
     or not private.member_has_permission(payment_row.organization_id, caller, 'invoices.view_price') then
    raise exception 'You do not have access to this payment.' using errcode = 'insufficient_privilege';
  end if;

  select organization.name into business_name
  from public.organizations as organization
  where organization.id = payment_row.organization_id;

  return private.payment_receipt_document(payment_row, business_name);
end;
$$;


ALTER FUNCTION "public"."payment_receipt_preview"("target_payment_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."payment_receipt_preview"("target_payment_event_id" "uuid") IS 'The customer''s receipt document for a signed-in member to print, without creating a link. Same builder the token page uses, so the printed copy and the emailed one can never disagree.';



CREATE OR REPLACE FUNCTION "public"."perform_automation_email_effect"("p_work_item_id" "uuid", "p_claim_token" "uuid", "p_quote_url" "text", "p_quote_token_hash" "bytea") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  item private.automation_work_items%rowtype; enrollment private.automation_enrollments%rowtype;
  recipe_status text; definition jsonb; step jsonb; logical_send_key text; result jsonb; status text;
begin
  if p_work_item_id is null or p_claim_token is null then
    raise exception 'A work item and its claim are required.' using errcode = 'check_violation';
  end if;
  select * into item from private.automation_work_items
    where id = p_work_item_id and claim_token = p_claim_token and state = 'pending' for update;
  if not found then return 'claim_lost'; end if;
  select * into enrollment from private.automation_enrollments where id = item.enrollment_id for update;
  if not found or enrollment.state <> 'active' then
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;
  if enrollment.expires_at is not null and enrollment.expires_at <= now() then
    update private.automation_enrollments
      set state = 'stopped', stop_reason = 'enrollment_expired', stopped_at = now() where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;
  select recipe.status, version.definition into recipe_status, definition
    from private.automation_enrollments e
    join public.automation_recipes recipe on recipe.id = e.recipe_id
    join public.automation_recipe_versions version on version.id = e.recipe_version_id
    where e.id = enrollment.id;
  if recipe_status = 'paused' then
    update private.automation_work_items
      set available_at = now() + private.automation_retry_delay(item.attempts),
        claim_token = null, claimed_at = null where id = item.id;
    return 'action_deferred';
  end if;
  if recipe_status is distinct from 'active' then
    update private.automation_enrollments
      set state = 'stopped', stop_reason = 'recipe_not_active', stopped_at = now() where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;
  step := (definition -> 'steps') -> item.step_index;
  if step is null or (step ->> 'type') <> 'action' or (step ->> 'key') <> 'action.send_email' then
    update private.automation_work_items
      set state = 'needs_attention', attention_reason = 'action_not_available', attention_at = now(),
        claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;
  logical_send_key := 'automation-quote-follow-up:' || enrollment.id || ':'
    || enrollment.recipe_version_id || ':' || item.step_index;
  result := public.enqueue_automation_quote_email(
    enrollment.organization_id, enrollment.subject_id, logical_send_key,
    step -> 'config' ->> 'subject', step -> 'config' ->> 'body', p_quote_url, p_quote_token_hash);
  status := result ->> 'status';
  if status = 'sent' then
    update private.automation_enrollments
      set current_step_index = item.step_index + 1, customer_messages_sent = customer_messages_sent + 1
      where id = enrollment.id;
    update private.automation_work_items
      set state = 'done', claim_token = null, claimed_at = null where id = item.id;
    insert into private.automation_work_items
      (organization_id, enrollment_id, step_index, due_at, available_at)
      values (enrollment.organization_id, enrollment.id, item.step_index + 1, now(), now())
      on conflict (enrollment_id, step_index) do nothing;
    return 'action_sent';
  elsif status = 'skipped_temporary' then
    update private.automation_work_items
      set available_at = now() + private.automation_retry_delay(item.attempts),
        last_error_code = left(result ->> 'reason', 100), claim_token = null, claimed_at = null
      where id = item.id;
    return 'action_deferred';
  else
    update private.automation_enrollments
      set state = 'stopped', stop_reason = left(result ->> 'reason', 100), stopped_at = now()
      where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', last_error_code = left(result ->> 'reason', 100),
        claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;
end;
$$;


ALTER FUNCTION "public"."perform_automation_email_effect"("p_work_item_id" "uuid", "p_claim_token" "uuid", "p_quote_url" "text", "p_quote_token_hash" "bytea") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."perform_automation_email_effect"("p_work_item_id" "uuid", "p_claim_token" "uuid", "p_quote_url" "text", "p_quote_token_hash" "bytea") IS 'Runs one claimed email action in a single transaction: rechecks enrollment/expiry/pause, enqueues the email idempotently, and settles the work item (advance on sent, back off on temporary, stop the enrollment on permanent). Claim-token guarded. Service role only.';



CREATE OR REPLACE FUNCTION "public"."perform_automation_inquiry_message_effect"("p_work_item_id" "uuid", "p_claim_token" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  item private.automation_work_items%rowtype;
  enrollment private.automation_enrollments%rowtype;
  recipe_status text;
  definition jsonb;
  step jsonb;
  stop_outcome text;
  customer_reply_at timestamptz;
  subject record;
  result jsonb;
  status text;
begin
  if p_work_item_id is null or p_claim_token is null then
    raise exception 'A work item and its claim are required.' using errcode = 'check_violation';
  end if;

  select * into item from private.automation_work_items
    where id = p_work_item_id and claim_token = p_claim_token and state = 'pending' for update;
  if not found then
    return 'claim_lost';
  end if;

  select * into enrollment from private.automation_enrollments where id = item.enrollment_id for update;
  if not found or enrollment.state <> 'active' then
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;
  if enrollment.expires_at is not null and enrollment.expires_at <= now() then
    update private.automation_enrollments
      set state = 'stopped', stop_reason = 'enrollment_expired', stopped_at = now() where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;

  select recipe.status, version.definition into recipe_status, definition
    from private.automation_enrollments e
    join public.automation_recipes recipe on recipe.id = e.recipe_id
    join public.automation_recipe_versions version on version.id = e.recipe_version_id
    where e.id = enrollment.id;
  if recipe_status = 'paused' then
    update private.automation_work_items
      set available_at = now() + private.automation_retry_delay(item.attempts),
        claim_token = null, claimed_at = null
      where id = item.id;
    return 'action_deferred';
  end if;
  if recipe_status is distinct from 'active' then
    update private.automation_enrollments
      set state = 'stopped', stop_reason = 'recipe_not_active', stopped_at = now() where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;

  step := (definition -> 'steps') -> item.step_index;
  if step is null or (step ->> 'type') <> 'action' or (step ->> 'key') <> 'action.send_customer_message'
    or enrollment.subject_type not in ('form_submission', 'website_chat_session') then
    update private.automation_work_items
      set state = 'needs_attention', attention_reason = 'action_not_available', attention_at = now(),
        claim_token = null, claimed_at = null
      where id = item.id;
    return 'action_cancelled';
  end if;

  -- The Stage 3 rules, re-read at the moment of sending: a person answered, or the customer replied.
  stop_outcome := private.automation_inquiry_stop_outcome(
    enrollment.organization_id, enrollment.subject_type, enrollment.subject_id, enrollment.anchor_at);
  if stop_outcome is not null then
    update private.automation_enrollments
      set state = 'stopped', stop_reason = stop_outcome, stopped_at = now() where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;

  customer_reply_at := private.automation_inquiry_customer_reply_at(
    enrollment.organization_id, enrollment.subject_type, enrollment.subject_id, enrollment.customer_reply_after);
  if customer_reply_at is not null then
    update private.automation_enrollments
      set state = 'paused', paused_work_due_at = item.due_at, current_step_index = item.step_index,
        customer_reply_after = customer_reply_at
      where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;

  select * into subject from private.automation_inquiry_client_id(
    enrollment.organization_id, enrollment.subject_type, enrollment.subject_id);

  result := private.enqueue_automation_inquiry_message(
    enrollment.organization_id, subject.client_id,
    enrollment.id || ':' || enrollment.recipe_version_id || ':' || item.step_index,
    step -> 'config');
  status := result ->> 'status';

  if status = 'sent' then
    if result ->> 'channel' = 'sms' then
      insert into private.automation_sms_email_fallbacks
        (organization_id, enrollment_id, step_index, sms_delivery_intent_id)
        values (enrollment.organization_id, enrollment.id, item.step_index, (result ->> 'intent_id')::uuid)
        on conflict do nothing;
    end if;
    -- From now on a customer message counts as a reply (Stage 3). An earlier reply-pause keeps its later mark.
    update private.automation_enrollments
      set current_step_index = item.step_index + 1,
        customer_messages_sent = customer_messages_sent
          + case when result ->> 'reason' = 'enqueued' then 1 else 0 end,
        customer_reply_after = coalesce(customer_reply_after, now())
      where id = enrollment.id;
    update private.automation_work_items
      set state = 'done', claim_token = null, claimed_at = null where id = item.id;
    insert into private.automation_work_items
      (organization_id, enrollment_id, step_index, due_at, available_at)
      values (enrollment.organization_id, enrollment.id, item.step_index + 1, now(), now())
      on conflict (enrollment_id, step_index) do nothing;
    return 'action_sent';
  elsif status = 'skipped_temporary' then
    update private.automation_work_items
      set available_at = now() + private.automation_retry_delay(item.attempts),
        last_error_code = left(result ->> 'reason', 100),
        claim_token = null, claimed_at = null
      where id = item.id;
    return 'action_deferred';
  else
    update private.automation_enrollments
      set state = 'stopped', stop_reason = left(result ->> 'reason', 100), stopped_at = now()
      where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', last_error_code = left(result ->> 'reason', 100),
        claim_token = null, claimed_at = null
      where id = item.id;
    return 'action_cancelled';
  end if;
end;
$$;


ALTER FUNCTION "public"."perform_automation_inquiry_message_effect"("p_work_item_id" "uuid", "p_claim_token" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."perform_automation_inquiry_message_effect"("p_work_item_id" "uuid", "p_claim_token" "uuid") IS 'Runs one claimed website-inquiry customer message in a single transaction: rechecks enrollment, expiry, recipe pause, staff reply (stop) and customer reply (pause), sends by text or email, watches a text for an email fallback, and settles the work item. Claim-token guarded. Service role only.';



CREATE OR REPLACE FUNCTION "public"."perform_automation_sms_effect"("p_work_item_id" "uuid", "p_claim_token" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  item private.automation_work_items%rowtype;
  enrollment private.automation_enrollments%rowtype;
  recipe_status text;
  definition jsonb;
  step jsonb;
  logical_send_key text;
  result jsonb;
  status text;
begin
  if p_work_item_id is null or p_claim_token is null then
    raise exception 'A work item and its claim are required.' using errcode = 'check_violation';
  end if;

  select * into item from private.automation_work_items
    where id = p_work_item_id and claim_token = p_claim_token and state = 'pending' for update;
  if not found then
    return 'claim_lost';
  end if;

  select * into enrollment from private.automation_enrollments where id = item.enrollment_id for update;
  if not found or enrollment.state <> 'active' then
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;
  if enrollment.expires_at is not null and enrollment.expires_at <= now() then
    update private.automation_enrollments
      set state = 'stopped', stop_reason = 'enrollment_expired', stopped_at = now() where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;

  -- Recheck pause immediately before the customer effect: a recipe paused since the claim holds this step.
  select recipe.status, version.definition into recipe_status, definition
    from private.automation_enrollments e
    join public.automation_recipes recipe on recipe.id = e.recipe_id
    join public.automation_recipe_versions version on version.id = e.recipe_version_id
    where e.id = enrollment.id;
  if recipe_status = 'paused' then
    update private.automation_work_items
      set available_at = now() + private.automation_retry_delay(item.attempts),
        claim_token = null, claimed_at = null
      where id = item.id;
    return 'action_deferred';
  end if;
  if recipe_status is distinct from 'active' then
    update private.automation_enrollments
      set state = 'stopped', stop_reason = 'recipe_not_active', stopped_at = now() where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', claim_token = null, claimed_at = null where id = item.id;
    return 'action_cancelled';
  end if;

  step := (definition -> 'steps') -> item.step_index;
  if step is null or (step ->> 'type') <> 'action' or (step ->> 'key') <> 'action.send_sms' then
    -- Not a textable action (or past the last step): nothing this adapter can do. Park for attention rather
    -- than guessing.
    update private.automation_work_items
      set state = 'needs_attention', attention_reason = 'action_not_available', attention_at = now(),
        claim_token = null, claimed_at = null
      where id = item.id;
    return 'action_cancelled';
  end if;

  logical_send_key := 'automation-quote-follow-up-sms:' || enrollment.id || ':'
    || enrollment.recipe_version_id || ':' || item.step_index;

  result := public.enqueue_automation_quote_sms(
    enrollment.organization_id,
    enrollment.subject_id,
    logical_send_key,
    step -> 'config' ->> 'body',
    nullif(step -> 'config' ->> 'sender_id', '')::uuid);
  status := result ->> 'status';

  if status = 'sent' then
    update private.automation_enrollments
      set current_step_index = item.step_index + 1,
        customer_messages_sent = customer_messages_sent + 1
      where id = enrollment.id;
    update private.automation_work_items
      set state = 'done', claim_token = null, claimed_at = null where id = item.id;
    insert into private.automation_work_items
      (organization_id, enrollment_id, step_index, due_at, available_at)
      values (enrollment.organization_id, enrollment.id, item.step_index + 1, now(), now())
      on conflict (enrollment_id, step_index) do nothing;
    return 'action_sent';
  elsif status = 'skipped_temporary' then
    update private.automation_work_items
      set available_at = now() + private.automation_retry_delay(item.attempts),
        last_error_code = left(result ->> 'reason', 100),
        claim_token = null, claimed_at = null
      where id = item.id;
    return 'action_deferred';
  else
    update private.automation_enrollments
      set state = 'stopped', stop_reason = left(result ->> 'reason', 100), stopped_at = now()
      where id = enrollment.id;
    update private.automation_work_items
      set state = 'cancelled', last_error_code = left(result ->> 'reason', 100),
        claim_token = null, claimed_at = null
      where id = item.id;
    return 'action_cancelled';
  end if;
end;
$$;


ALTER FUNCTION "public"."perform_automation_sms_effect"("p_work_item_id" "uuid", "p_claim_token" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."perform_automation_sms_effect"("p_work_item_id" "uuid", "p_claim_token" "uuid") IS 'Runs one claimed SMS action in a single transaction: rechecks enrollment/expiry/pause, enqueues the text idempotently, and settles the work item (advance on sent, back off on temporary, stop the enrollment on permanent). Claim-token guarded. Service role only.';



CREATE OR REPLACE FUNCTION "public"."pipeline_board_page"("target_organization_id" "uuid", "target_stage" "text", "page_limit" integer DEFAULT 25, "sort_key" "text" DEFAULT 'stage_entered_at'::"text", "sort_direction" "text" DEFAULT 'desc'::"text", "owner_filter" "text" DEFAULT 'all'::"text", "filter_owner_user_id" "uuid" DEFAULT NULL::"uuid", "created_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "created_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "cursor_sort_key" "text" DEFAULT NULL::"text", "cursor_phase" integer DEFAULT NULL::integer, "cursor_timestamp" timestamp with time zone DEFAULT NULL::timestamp with time zone, "cursor_value" numeric DEFAULT NULL::numeric, "cursor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "title" "text", "stage" "text", "stage_entered_at" timestamp with time zone, "outcome" "text", "created_at" timestamp with time zone, "request_id" "uuid", "request_status" "text", "client_id" "uuid", "client_display_name" "text", "client_company_name" "text", "property_id" "uuid", "property_label" "text", "property_address_line1" "text", "property_city" "text", "property_state_region" "text", "property_postal_code" "text", "owner_user_id" "uuid", "owner_full_name" "text", "owner_avatar_url" "text", "estimated_value" numeric, "expected_close_on" "date", "next_follow_up_on" "date", "task_id" "uuid", "task_title" "text", "task_due_on" "date", "quote_id" "uuid", "quote_status" "text", "assessment_starts_at" timestamp with time zone, "assessment_ends_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  caller_id uuid := (select auth.uid());
  caller_sees_money boolean;
  caller_sees_clients boolean;
  resolved_limit integer;
  sorting_by_value boolean;
  phase integer;
  select_body text;
  stage_predicate text;
  filters text := '';
  keyset text;
  ordering text;
  fetched integer;
begin
  -- The same rule the select policy applies: current member, active organization, pipeline.view.
  if target_organization_id is null
     or target_organization_id not in (select private.permitted_organizations('pipeline.view')) then
    raise exception 'You do not have access to this sales pipeline.'
      using errcode = 'insufficient_privilege';
  end if;

  -- One named logical column plus the seven real stages. Written out rather than assembled from a caller's
  -- list, so 'assessment' is the only grouping that exists and no other combination is reachable.
  if target_stage = 'assessment' then
    -- Spelled exactly as opportunities_board_assessment_group_idx spells it: the planner matches the two
    -- expressions before attempting a harder proof, and a mismatch here silently costs the index.
    stage_predicate :=
      $p$ and opportunity.stage in
        ('assessment_unscheduled', 'assessment_scheduled', 'assessment_completed')$p$;
  elsif target_stage in (
    'new_request', 'assessment_unscheduled', 'assessment_scheduled', 'assessment_completed',
    'quote_draft', 'quote_awaiting_response', 'quote_changes_requested'
  ) then
    stage_predicate := format(' and opportunity.stage = %L', target_stage);
  else
    raise exception 'That is not a board column.' using errcode = 'invalid_parameter_value';
  end if;

  if sort_key not in ('stage_entered_at', 'created_at', 'estimated_value')
     or sort_direction not in ('asc', 'desc')
     or owner_filter not in ('all', 'unassigned', 'member') then
    raise exception 'That is not a way to sort or filter the board.'
      using errcode = 'invalid_parameter_value';
  end if;

  if owner_filter = 'member' and filter_owner_user_id is null then
    raise exception 'Filtering by salesperson needs a salesperson.'
      using errcode = 'invalid_parameter_value';
  end if;

  -- A cursor is only valid for the order it was cut from. Paging on with a cursor from a different sort
  -- would silently skip and repeat cards, so it is refused instead. The column a cursor belongs to is
  -- checked by the route, which is the only place that knows the logical-column vocabulary.
  if cursor_sort_key is not null and cursor_sort_key <> sort_key then
    raise exception 'That page marker belongs to a different order.'
      using errcode = 'invalid_parameter_value';
  end if;

  -- One row over the asked-for page is how the caller detects there is more, so the cap is 50 plus one.
  resolved_limit := least(greatest(coalesce(page_limit, 25), 1), 51);

  caller_sees_money :=
    private.member_has_permission(target_organization_id, caller_id, 'pipeline.view_value');
  -- Asked once for the whole page. can_view_client is still called per row underneath, but only for a
  -- caller who lacks the blanket permission, so the ordinary page pays nothing for it.
  caller_sees_clients :=
    private.member_has_permission(target_organization_id, caller_id, 'customers.view');

  sorting_by_value := sort_key = 'estimated_value';

  -- Ordering by money is reading money. Withholding the amounts while handing over the ranking would
  -- give the column away one comparison at a time.
  if sorting_by_value and not caller_sees_money then
    raise exception 'You do not have access to values on this sales pipeline.'
      using errcode = 'insufficient_privilege';
  end if;

  select_body := format($body$
    select
      opportunity.id,
      opportunity.title,
      opportunity.stage,
      opportunity.stage_entered_at,
      opportunity.outcome,
      opportunity.created_at,
      opportunity.request_id,
      request.status,
      opportunity.client_id,
      case when client_visible.allowed then client.display_name end,
      case when client_visible.allowed then client.company_name end,
      opportunity.property_id,
      case when client_visible.allowed then property.label end,
      case when client_visible.allowed then property.address_line1 end,
      case when client_visible.allowed then property.city end,
      case when client_visible.allowed then property.state_region end,
      case when client_visible.allowed then property.postal_code end,
      opportunity.owner_user_id,
      case when owner_is_teammate.yes then owner_profile.full_name end,
      case when owner_is_teammate.yes then owner_profile.avatar_url end,
      case when %L::boolean then opportunity.estimated_value end,
      opportunity.expected_close_on,
      opportunity.next_follow_up_on,
      open_task.id,
      open_task.title,
      open_task.due_on,
      opportunity.quote_id,
      quote.status,
      assessment.starts_at,
      assessment.ends_at
    from public.opportunities as opportunity
    cross join lateral (
      select
        %L::boolean
        or private.can_view_client(opportunity.organization_id, opportunity.client_id) as allowed
    ) as client_visible
    cross join lateral (
      select exists (
        select 1
        from public.organization_members as owner_membership
        where owner_membership.organization_id = opportunity.organization_id
          and owner_membership.user_id = opportunity.owner_user_id
      ) as yes
    ) as owner_is_teammate
    left join lateral (
      select task.id, task.title, task.due_on
      from public.tasks as task
      where task.organization_id = opportunity.organization_id
        and task.opportunity_id = opportunity.id
        and task.status = 'open'
      order by task.due_on nulls last, task.created_at, task.id
      limit 1
    ) as open_task on true
    left join public.clients as client
      on client.id = opportunity.client_id
     and client.organization_id = opportunity.organization_id
    left join public.properties as property
      on property.id = opportunity.property_id
     and property.organization_id = opportunity.organization_id
    left join public.requests as request
      on request.id = opportunity.request_id
     and request.organization_id = opportunity.organization_id
    left join public.quotes as quote
      on quote.id = opportunity.quote_id
     and quote.organization_id = opportunity.organization_id
    left join public.profiles as owner_profile
      on owner_profile.id = opportunity.owner_user_id
    left join public.assessments as assessment
      on assessment.request_id = opportunity.request_id
     and assessment.organization_id = opportunity.organization_id
    where opportunity.organization_id = %L
      and opportunity.outcome = 'open'
  $body$, caller_sees_money, caller_sees_clients, target_organization_id) || stage_predicate;

  -- Only the clauses this request actually needs. "Or the filter is null" reads the same and costs the
  -- index scan.
  if owner_filter = 'unassigned' then
    filters := filters || ' and opportunity.owner_user_id is null';
  elsif owner_filter = 'member' then
    filters := filters || format(' and opportunity.owner_user_id = %L', filter_owner_user_id);
  end if;

  -- Calendar boundaries are worked out in the organization's timezone before they get here, so this only
  -- ever sees two instants. The upper bound is exclusive: it is the first moment of the day after.
  if created_from is not null then
    filters := filters || format(' and opportunity.created_at >= %L', created_from);
  end if;
  if created_to is not null then
    filters := filters || format(' and opportunity.created_at < %L', created_to);
  end if;

  if not sorting_by_value then
    -- Ties break the same way the sort runs, so the pair reads as one index range rather than as a
    -- filter over everything above it. This is also what keeps the grouped column's order globally
    -- correct: one keyset across all three assessment states, never three lists stitched together.
    if sort_direction = 'desc' then
      ordering := format(' order by opportunity.%1$I desc, opportunity.id desc', sort_key);
      keyset := case
        when cursor_id is null then ''
        else format(
          ' and (opportunity.%1$I, opportunity.id) < (%2$L::timestamptz, %3$L::uuid)',
          sort_key, cursor_timestamp, cursor_id)
      end;
    else
      ordering := format(' order by opportunity.%1$I asc, opportunity.id asc', sort_key);
      keyset := case
        when cursor_id is null then ''
        else format(
          ' and (opportunity.%1$I, opportunity.id) > (%2$L::timestamptz, %3$L::uuid)',
          sort_key, cursor_timestamp, cursor_id)
      end;
    end if;

    return query execute select_body || filters || keyset || ordering
      || format(' limit %s', resolved_limit);
    return;
  end if;

  -- Value sorting, phase by phase. Phase 1 is the estimated cards in the caller's chosen direction;
  -- phase 2 is the unestimated ones, always oldest id first, which is the order they already sit in.
  phase := coalesce(cursor_phase, 1);
  if phase not in (1, 2) then
    raise exception 'That page marker belongs to a different order.'
      using errcode = 'invalid_parameter_value';
  end if;

  if phase = 1 then
    if sort_direction = 'desc' then
      ordering := ' order by opportunity.estimated_value desc, opportunity.id desc';
      keyset := case
        when cursor_id is null then ''
        else format(
          ' and (opportunity.estimated_value, opportunity.id) < (%1$L::numeric, %2$L::uuid)',
          cursor_value, cursor_id)
      end;
    else
      ordering := ' order by opportunity.estimated_value asc, opportunity.id asc';
      keyset := case
        when cursor_id is null then ''
        else format(
          ' and (opportunity.estimated_value, opportunity.id) > (%1$L::numeric, %2$L::uuid)',
          cursor_value, cursor_id)
      end;
    end if;

    return query execute select_body || filters
      || ' and opportunity.estimated_value is not null' || keyset || ordering
      || format(' limit %s', resolved_limit);
    get diagnostics fetched = row_count;

    -- The estimated side is finished, so the rest of this page comes from the unestimated side, from its
    -- beginning. No unestimated card can have been returned before this point, so there is nothing to
    -- page past.
    if fetched < resolved_limit then
      return query execute select_body || filters
        || ' and opportunity.estimated_value is null'
        || ' order by opportunity.id asc'
        || format(' limit %s', resolved_limit - fetched);
    end if;
    return;
  end if;

  return query execute select_body || filters
    || ' and opportunity.estimated_value is null'
    || case when cursor_id is null then ''
            else format(' and opportunity.id > %L::uuid', cursor_id) end
    || ' order by opportunity.id asc'
    || format(' limit %s', resolved_limit);
end;
$_$;


ALTER FUNCTION "public"."pipeline_board_page"("target_organization_id" "uuid", "target_stage" "text", "page_limit" integer, "sort_key" "text", "sort_direction" "text", "owner_filter" "text", "filter_owner_user_id" "uuid", "created_from" timestamp with time zone, "created_to" timestamp with time zone, "cursor_sort_key" "text", "cursor_phase" integer, "cursor_timestamp" timestamp with time zone, "cursor_value" numeric, "cursor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_create_opportunity_note"("target_opportunity_id" "uuid", "target_entity_type" "text", "new_body" "text") RETURNS TABLE("id" "uuid", "body" "text", "pinned" boolean, "created_by" "uuid", "edited_by" "uuid", "edited_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "entity_type" "text", "entity_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  scope record;
  resolved_entity_id uuid;
  inserted_note public.notes;
  inserted_link public.note_links;
begin
  if target_entity_type not in ('request', 'client') then
    raise exception 'A Brief Note can only target the Request or the Client.'
      using errcode = 'check_violation';
  end if;

  select * into scope from private.pipeline_note_scope(target_opportunity_id, 'pipeline.edit');

  resolved_entity_id := case target_entity_type
    when 'request' then scope.request_id
    else scope.client_id
  end;

  if resolved_entity_id is null then
    raise exception 'This opportunity has no % to attach a note to.', target_entity_type
      using errcode = 'check_violation';
  end if;

  insert into public.notes (organization_id, body, created_by)
  values (scope.organization_id, new_body, (select auth.uid()))
  returning * into inserted_note;

  insert into public.note_links (organization_id, note_id, entity_type, entity_id)
  values (scope.organization_id, inserted_note.id, target_entity_type, resolved_entity_id)
  returning * into inserted_link;

  return query
  select
    inserted_note.id, inserted_note.body, inserted_note.pinned, inserted_note.created_by,
    inserted_note.edited_by, inserted_note.edited_at, inserted_note.created_at, inserted_note.updated_at,
    inserted_link.entity_type, inserted_link.entity_id;
end;
$$;


ALTER FUNCTION "public"."pipeline_create_opportunity_note"("target_opportunity_id" "uuid", "target_entity_type" "text", "new_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_create_opportunity_task"("target_opportunity_id" "uuid", "new_title" "text", "new_instructions" "text" DEFAULT NULL::"text", "new_assignee_user_id" "uuid" DEFAULT NULL::"uuid", "new_due_on" "date" DEFAULT NULL::"date") RETURNS TABLE("id" "uuid", "opportunity_id" "uuid", "title" "text", "instructions" "text", "assignee_user_id" "uuid", "due_on" "date", "status" "text", "completed_at" timestamp with time zone, "completed_by" "uuid", "created_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_organization_id uuid := private.pipeline_lock_task_parent(target_opportunity_id);
begin
  perform private.assert_task_limit(target_opportunity_id, 'open');

  return query
  insert into public.tasks as task (
    organization_id, opportunity_id, title, instructions, assignee_user_id, due_on, created_by
  )
  values (
    target_organization_id,
    target_opportunity_id,
    new_title,
    nullif(trim(coalesce(new_instructions, '')), ''),
    new_assignee_user_id,
    new_due_on,
    (select auth.uid())
  )
  returning
    task.id, task.opportunity_id, task.title, task.instructions, task.assignee_user_id, task.due_on,
    task.status, task.completed_at, task.completed_by, task.created_by, task.created_at, task.updated_at;
end;
$$;


ALTER FUNCTION "public"."pipeline_create_opportunity_task"("target_opportunity_id" "uuid", "new_title" "text", "new_instructions" "text", "new_assignee_user_id" "uuid", "new_due_on" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_delete_opportunity_note"("target_note_id" "uuid", "target_opportunity_id" "uuid", "target_entity_type" "text") RETURNS TABLE("unlinked" boolean, "note_deleted" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  scope record;
  resolved_entity_id uuid;
  remaining integer;
begin
  select * into scope from private.pipeline_note_scope(target_opportunity_id, 'pipeline.edit');

  resolved_entity_id := case target_entity_type
    when 'request' then scope.request_id
    when 'client' then scope.client_id
    else null
  end;

  delete from public.note_links as link
  where link.note_id = target_note_id
    and link.organization_id = scope.organization_id
    and link.entity_type = target_entity_type
    and link.entity_id = resolved_entity_id;

  if not found then
    raise exception 'That note is not on this opportunity.' using errcode = 'insufficient_privilege';
  end if;

  select count(*) into remaining from public.note_links as link where link.note_id = target_note_id;

  if remaining = 0 then
    delete from public.notes as note where note.id = target_note_id;
    return query select true, true;
  end if;

  return query select true, false;
end;
$$;


ALTER FUNCTION "public"."pipeline_delete_opportunity_note"("target_note_id" "uuid", "target_opportunity_id" "uuid", "target_entity_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_delete_task"("target_task_id" "uuid") RETURNS TABLE("id" "uuid", "opportunity_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  parent_id uuid;
begin
  select task.opportunity_id into parent_id from public.tasks as task where task.id = target_task_id;
  if parent_id is null then
    raise exception 'You do not have access to change this task.' using errcode = 'insufficient_privilege';
  end if;

  perform private.pipeline_lock_task_parent(parent_id);

  return query
  delete from public.tasks as task
  where task.id = target_task_id
  returning task.id, task.opportunity_id;
end;
$$;


ALTER FUNCTION "public"."pipeline_delete_task"("target_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_drag_opportunity"("target_opportunity_id" "uuid", "to_stage" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  opportunity_row public.opportunities;
begin
  opportunity_row := private.pipeline_lock_opportunity_for_drag(target_opportunity_id);

  if not private.pipeline_drag_transition_allowed(opportunity_row.stage, to_stage) then
    raise exception 'That card cannot be moved there.' using errcode = 'check_violation';
  end if;

  return jsonb_build_object(
    'organization_id', opportunity_row.organization_id,
    'request_id', opportunity_row.request_id,
    'quote_id', opportunity_row.quote_id,
    'from_stage', opportunity_row.stage
  );
end;
$$;


ALTER FUNCTION "public"."pipeline_drag_opportunity"("target_opportunity_id" "uuid", "to_stage" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_mark_opportunity_lost"("target_opportunity_id" "uuid", "idempotency_key" "text", "reason" "text" DEFAULT NULL::"text", "note" "text" DEFAULT NULL::"text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  opportunity_row public.opportunities;
  request_row public.requests;
  existing_event public.opportunity_outcome_events;
  inserted_event public.opportunity_outcome_events;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
  clean_reason text := nullif(trim(coalesce(reason, '')), '');
  clean_note text := nullif(trim(coalesce(note, '')), '');
begin
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if command_time > now() then
    raise exception 'An outcome cannot be dated in the future.' using errcode = 'check_violation';
  end if;
  if clean_reason is not null and clean_reason not in (
    'price_too_high', 'chose_another_contractor', 'no_response', 'project_postponed',
    'work_not_a_fit', 'duplicate_or_test_request', 'other'
  ) then
    raise exception 'Choose a valid lost reason.' using errcode = 'check_violation';
  end if;
  if clean_reason = 'other' and clean_note is null then
    raise exception 'Add a short note for "Other".' using errcode = 'check_violation';
  end if;

  opportunity_row := private.pipeline_lock_opportunity_for_outcome(target_opportunity_id);

  -- A retry of the same command returns the first result untouched, even if the opportunity has since
  -- moved on. This must run before the "must be open" check below, or a legitimate retry after the first
  -- call already applied would be rejected as a conflicting command instead of recognised as a repeat.
  select * into existing_event
  from public.opportunity_outcome_events
  where organization_id = opportunity_row.organization_id
    and opportunity_id = target_opportunity_id
    and opportunity_outcome_events.idempotency_key = pipeline_mark_opportunity_lost.idempotency_key;
  if found then
    return jsonb_build_object(
      'applied', false, 'event_id', existing_event.id, 'outcome', 'lost',
      'outcome_at', existing_event.occurred_at
    );
  end if;

  if opportunity_row.outcome <> 'open' then
    raise exception 'Only an open opportunity can be marked lost.' using errcode = 'check_violation';
  end if;
  if opportunity_row.request_id is null then
    -- Unreachable today: every Opportunity comes from a Request until Quotes exist. Refusing plainly is
    -- safer than fabricating Quote-side Lost behavior.
    raise exception 'Standalone opportunities cannot be marked lost yet.' using errcode = 'check_violation';
  end if;

  select * into request_row
  from public.requests
  where id = opportunity_row.request_id and organization_id = opportunity_row.organization_id
  for update;

  if request_row.id is null then
    raise exception 'The backing request could not be found.' using errcode = 'foreign_key_violation';
  end if;
  if request_row.status in ('archived', 'converted') then
    raise exception 'This request cannot be marked lost right now.' using errcode = 'check_violation';
  end if;

  perform set_config('pipeline.outcome_transition_request_id', request_row.id::text, true);

  update public.requests
  set status = 'archived'
  where id = request_row.id;

  insert into public.opportunity_outcome_events (
    organization_id, opportunity_id, event_type, occurred_at, actor_user_id,
    reason, note, prior_request_status, idempotency_key
  ) values (
    opportunity_row.organization_id, target_opportunity_id, 'lost', command_time, (select auth.uid()),
    clean_reason, clean_note, request_row.status, idempotency_key
  ) returning * into inserted_event;

  update public.opportunities
  set outcome = 'lost', outcome_at = command_time, current_outcome_event_id = inserted_event.id
  where id = target_opportunity_id;

  -- Only Tasks still open at this moment are this Lost event's to claim. A Task a person already finished
  -- keeps its own completed_by and no event id, so Reopen will never touch it. The five-completed limit is
  -- deliberately not re-checked here: it bounds active board work, and this card is leaving the board.
  update public.tasks
  set status = 'completed', completed_at = command_time, completed_by = null,
      completed_by_outcome_event_id = inserted_event.id
  where organization_id = opportunity_row.organization_id
    and opportunity_id = target_opportunity_id
    and status = 'open';

  return jsonb_build_object(
    'applied', true, 'event_id', inserted_event.id, 'outcome', 'lost', 'outcome_at', command_time
  );
end;
$$;


ALTER FUNCTION "public"."pipeline_mark_opportunity_lost"("target_opportunity_id" "uuid", "idempotency_key" "text", "reason" "text", "note" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_opportunity_notes"("target_opportunity_id" "uuid") RETURNS TABLE("id" "uuid", "body" "text", "pinned" boolean, "created_by" "uuid", "edited_by" "uuid", "edited_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "entity_type" "text", "entity_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  scope record;
begin
  select * into scope from private.pipeline_note_scope(target_opportunity_id, 'pipeline.view');

  return query
  select
    note.id, note.body, note.pinned, note.created_by, note.edited_by, note.edited_at,
    note.created_at, note.updated_at, link.entity_type, link.entity_id
  from public.note_links as link
  join public.notes as note on note.id = link.note_id
  where link.organization_id = scope.organization_id
    and (
      (link.entity_type = 'request' and link.entity_id = scope.request_id)
      or (link.entity_type = 'client' and link.entity_id = scope.client_id)
    )
  order by note.pinned desc, note.created_at desc;
end;
$$;


ALTER FUNCTION "public"."pipeline_opportunity_notes"("target_opportunity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_outcome_page"("target_organization_id" "uuid", "outcome_type" "text", "page_limit" integer DEFAULT 25, "sort_key" "text" DEFAULT 'outcome_at'::"text", "sort_direction" "text" DEFAULT 'desc'::"text", "outcome_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "outcome_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "cursor_sort_key" "text" DEFAULT NULL::"text", "cursor_phase" integer DEFAULT NULL::integer, "cursor_timestamp" timestamp with time zone DEFAULT NULL::timestamp with time zone, "cursor_numeric" numeric DEFAULT NULL::numeric, "cursor_text" "text" DEFAULT NULL::"text", "cursor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "title" "text", "outcome" "text", "created_at" timestamp with time zone, "outcome_at" timestamp with time zone, "client_id" "uuid", "client_display_name" "text", "client_company_name" "text", "estimated_value" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  caller_id uuid := (select auth.uid());
  caller_sees_money boolean;
  caller_sees_clients boolean;
  resolved_limit integer;
  select_body text;
  filters text := '';
  keyset text;
  ordering text;
  sort_expr text;
  phase integer;
  fetched integer;
begin
  if target_organization_id is null
     or target_organization_id not in (select private.permitted_organizations('pipeline.view')) then
    raise exception 'You do not have access to this sales pipeline.'
      using errcode = 'insufficient_privilege';
  end if;

  if outcome_type not in ('won', 'lost') then
    raise exception 'That is not a Sales Outcomes type.' using errcode = 'invalid_parameter_value';
  end if;
  if sort_key not in ('title', 'client', 'created', 'outcome_at', 'total')
     or sort_direction not in ('asc', 'desc') then
    raise exception 'That is not a way to sort Sales Outcomes.' using errcode = 'invalid_parameter_value';
  end if;

  -- A cursor is only valid for the order it was cut from. Paging on with a cursor from a different sort
  -- would silently skip and repeat rows.
  if cursor_sort_key is not null and cursor_sort_key <> sort_key then
    raise exception 'That page marker belongs to a different order.'
      using errcode = 'invalid_parameter_value';
  end if;

  resolved_limit := least(greatest(coalesce(page_limit, 25), 1), 51);

  caller_sees_money :=
    private.member_has_permission(target_organization_id, caller_id, 'pipeline.view_value');
  caller_sees_clients :=
    private.member_has_permission(target_organization_id, caller_id, 'customers.view');

  if sort_key = 'total' and not caller_sees_money then
    raise exception 'You do not have access to values on this sales pipeline.'
      using errcode = 'insufficient_privilege';
  end if;
  if sort_key = 'client' and not caller_sees_clients then
    raise exception 'You do not have access to client names on this sales pipeline.'
      using errcode = 'insufficient_privilege';
  end if;

  select_body := format($body$
    select
      opportunity.id,
      opportunity.title,
      opportunity.outcome,
      opportunity.created_at,
      opportunity.outcome_at,
      opportunity.client_id,
      case when client_visible.allowed then client.display_name end,
      case when client_visible.allowed then client.company_name end,
      case when %L::boolean then opportunity.estimated_value end
    from public.opportunities as opportunity
    cross join lateral (
      select
        %L::boolean
        or private.can_view_client(opportunity.organization_id, opportunity.client_id) as allowed
    ) as client_visible
    left join public.clients as client
      on client.id = opportunity.client_id
     and client.organization_id = opportunity.organization_id
    where opportunity.organization_id = %L
      and opportunity.outcome = %L
  $body$, caller_sees_money, caller_sees_clients, target_organization_id, outcome_type);

  if outcome_from is not null then
    filters := filters || format(' and opportunity.outcome_at >= %L', outcome_from);
  end if;
  if outcome_to is not null then
    filters := filters || format(' and opportunity.outcome_at < %L', outcome_to);
  end if;

  -- Total pages in two phases, the same way the board's value sort does: a null estimate cannot sit in a
  -- keyset row comparison, so the estimated rows and the unestimated ones are two separate ordered reads
  -- rather than one NULLS LAST that a cursor could not resume.
  if sort_key = 'total' then
    phase := coalesce(cursor_phase, 1);
    if phase not in (1, 2) then
      raise exception 'That page marker belongs to a different order.'
        using errcode = 'invalid_parameter_value';
    end if;

    if phase = 1 then
      if sort_direction = 'desc' then
        ordering := ' order by opportunity.estimated_value desc, opportunity.id desc';
        keyset := case
          when cursor_id is null then ''
          else format(
            ' and (opportunity.estimated_value, opportunity.id) < (%1$L::numeric, %2$L::uuid)',
            cursor_numeric, cursor_id)
        end;
      else
        ordering := ' order by opportunity.estimated_value asc, opportunity.id asc';
        keyset := case
          when cursor_id is null then ''
          else format(
            ' and (opportunity.estimated_value, opportunity.id) > (%1$L::numeric, %2$L::uuid)',
            cursor_numeric, cursor_id)
        end;
      end if;

      return query execute select_body || filters
        || ' and opportunity.estimated_value is not null' || keyset || ordering
        || format(' limit %s', resolved_limit);
      get diagnostics fetched = row_count;

      if fetched < resolved_limit then
        return query execute select_body || filters
          || ' and opportunity.estimated_value is null'
          || ' order by opportunity.id asc'
          || format(' limit %s', resolved_limit - fetched);
      end if;
      return;
    end if;

    return query execute select_body || filters
      || ' and opportunity.estimated_value is null'
      || case when cursor_id is null then ''
              else format(' and opportunity.id > %L::uuid', cursor_id) end
      || ' order by opportunity.id asc'
      || format(' limit %s', resolved_limit);
    return;
  end if;

  -- Every other sort is a single ordered read. Title, Created and Outcome date are never null; Client can
  -- be null only when the backing client row itself has been removed, which NULLS LAST is enough for --
  -- this is a report column, not money, and that edge is rare enough not to earn Total's two-phase split.
  sort_expr := case sort_key
    when 'title' then 'opportunity.title'
    when 'client' then 'client.display_name'
    when 'created' then 'opportunity.created_at'
    else 'opportunity.outcome_at'
  end;

  if sort_key in ('title', 'client') then
    if sort_direction = 'desc' then
      ordering := format(' order by %1$s desc nulls last, opportunity.id desc', sort_expr);
      keyset := case
        when cursor_id is null then ''
        else format(' and (%1$s, opportunity.id) < (%2$L::text, %3$L::uuid)', sort_expr, cursor_text, cursor_id)
      end;
    else
      ordering := format(' order by %1$s asc nulls last, opportunity.id asc', sort_expr);
      keyset := case
        when cursor_id is null then ''
        else format(' and (%1$s, opportunity.id) > (%2$L::text, %3$L::uuid)', sort_expr, cursor_text, cursor_id)
      end;
    end if;
  else
    if sort_direction = 'desc' then
      ordering := format(' order by %1$s desc, opportunity.id desc', sort_expr);
      keyset := case
        when cursor_id is null then ''
        else format(
          ' and (%1$s, opportunity.id) < (%2$L::timestamptz, %3$L::uuid)', sort_expr, cursor_timestamp, cursor_id)
      end;
    else
      ordering := format(' order by %1$s asc, opportunity.id asc', sort_expr);
      keyset := case
        when cursor_id is null then ''
        else format(
          ' and (%1$s, opportunity.id) > (%2$L::timestamptz, %3$L::uuid)', sort_expr, cursor_timestamp, cursor_id)
      end;
    end if;
  end if;

  return query execute select_body || filters || keyset || ordering
    || format(' limit %s', resolved_limit);
end;
$_$;


ALTER FUNCTION "public"."pipeline_outcome_page"("target_organization_id" "uuid", "outcome_type" "text", "page_limit" integer, "sort_key" "text", "sort_direction" "text", "outcome_from" timestamp with time zone, "outcome_to" timestamp with time zone, "cursor_sort_key" "text", "cursor_phase" integer, "cursor_timestamp" timestamp with time zone, "cursor_numeric" numeric, "cursor_text" "text", "cursor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_outcome_tiles"("target_organization_id" "uuid", "tile_from" timestamp with time zone, "tile_to" timestamp with time zone) RETURNS TABLE("outcome_key" "text", "closed_count" bigint, "value_total" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller_id uuid := (select auth.uid());
  caller_sees_money boolean;
begin
  if target_organization_id is null
     or target_organization_id not in (select private.permitted_organizations('pipeline.view')) then
    raise exception 'You do not have access to this sales pipeline.'
      using errcode = 'insufficient_privilege';
  end if;

  caller_sees_money :=
    private.member_has_permission(target_organization_id, caller_id, 'pipeline.view_value');

  -- Both outcome types are always returned, zero-filled, so a tile with nothing in the window still shows
  -- "Won (0)" instead of going missing.
  return query
  select
    outcome_type.outcome_key,
    coalesce(counted.closed_count, 0)::bigint,
    counted.value_total
  from unnest(array['won', 'lost']) as outcome_type(outcome_key)
  left join (
    select
      opportunity.outcome as outcome_key,
      count(*) as closed_count,
      case when caller_sees_money then sum(opportunity.estimated_value) end as value_total
    from public.opportunities as opportunity
    where opportunity.organization_id = target_organization_id
      and opportunity.outcome in ('won', 'lost')
      and opportunity.outcome_at >= tile_from
      and opportunity.outcome_at < tile_to
    group by opportunity.outcome
  ) as counted on counted.outcome_key = outcome_type.outcome_key;
end;
$$;


ALTER FUNCTION "public"."pipeline_outcome_tiles"("target_organization_id" "uuid", "tile_from" timestamp with time zone, "tile_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_reopen_opportunity"("target_opportunity_id" "uuid", "idempotency_key" "text", "reopen_explanation" "text", "occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  opportunity_row public.opportunities;
  lost_event public.opportunity_outcome_events;
  existing_event public.opportunity_outcome_events;
  inserted_event public.opportunity_outcome_events;
  command_time timestamptz := coalesce(occurred_at, clock_timestamp());
  clean_explanation text := nullif(trim(coalesce(reopen_explanation, '')), '');
  open_count integer;
  reopening_count integer;
begin
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if clean_explanation is null or char_length(clean_explanation) > 500 then
    raise exception 'A short explanation is required to reopen.' using errcode = 'check_violation';
  end if;
  if command_time > now() then
    raise exception 'An outcome cannot be dated in the future.' using errcode = 'check_violation';
  end if;

  opportunity_row := private.pipeline_lock_opportunity_for_outcome(target_opportunity_id);

  select * into existing_event
  from public.opportunity_outcome_events
  where organization_id = opportunity_row.organization_id
    and opportunity_id = target_opportunity_id
    and opportunity_outcome_events.idempotency_key = pipeline_reopen_opportunity.idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id, 'outcome', 'open');
  end if;

  if opportunity_row.outcome <> 'lost' or opportunity_row.current_outcome_event_id is null then
    raise exception 'Only a lost opportunity can be reopened.' using errcode = 'check_violation';
  end if;

  select * into lost_event
  from public.opportunity_outcome_events
  where id = opportunity_row.current_outcome_event_id
    and organization_id = opportunity_row.organization_id
  for update;

  if lost_event.id is null then
    raise exception 'No lost event was found to reopen.' using errcode = 'foreign_key_violation';
  end if;

  -- Almost always zero: at most five Tasks could have been open when Lost fired. This only fires when
  -- something opened new Tasks on an already-closed card, which the write path does not block today.
  select
    count(*) filter (where status = 'open'),
    count(*) filter (where completed_by_outcome_event_id = lost_event.id)
  into open_count, reopening_count
  from public.tasks
  where organization_id = opportunity_row.organization_id
    and opportunity_id = target_opportunity_id;

  if open_count + reopening_count > 5 then
    raise exception 'Reopening would leave more than five open tasks. Close some open tasks first.'
      using errcode = 'check_violation';
  end if;

  perform set_config('pipeline.outcome_transition_request_id', opportunity_row.request_id::text, true);

  update public.requests
  set status = lost_event.prior_request_status
  where id = opportunity_row.request_id;

  insert into public.opportunity_outcome_events (
    organization_id, opportunity_id, event_type, occurred_at, actor_user_id,
    reopen_explanation, restores_event_id, idempotency_key
  ) values (
    opportunity_row.organization_id, target_opportunity_id, 'reopened', command_time, (select auth.uid()),
    clean_explanation, lost_event.id, idempotency_key
  ) returning * into inserted_event;

  update public.opportunities
  set outcome = 'open', outcome_at = null, current_outcome_event_id = null
  where id = target_opportunity_id;

  update public.tasks
  set status = 'open', completed_at = null, completed_by = null, completed_by_outcome_event_id = null
  where organization_id = opportunity_row.organization_id
    and opportunity_id = target_opportunity_id
    and completed_by_outcome_event_id = lost_event.id;

  return jsonb_build_object('applied', true, 'event_id', inserted_event.id, 'outcome', 'open');
end;
$$;


ALTER FUNCTION "public"."pipeline_reopen_opportunity"("target_opportunity_id" "uuid", "idempotency_key" "text", "reopen_explanation" "text", "occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_set_task_completed"("target_task_id" "uuid", "is_completed" boolean) RETURNS TABLE("id" "uuid", "opportunity_id" "uuid", "title" "text", "instructions" "text", "assignee_user_id" "uuid", "due_on" "date", "status" "text", "completed_at" timestamp with time zone, "completed_by" "uuid", "created_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  parent_id uuid;
  current_status text;
  wanted_status text := case when is_completed then 'completed' else 'open' end;
begin
  select task.opportunity_id, task.status
  into parent_id, current_status
  from public.tasks as task
  where task.id = target_task_id;

  if parent_id is null then
    raise exception 'You do not have access to change this task.' using errcode = 'insufficient_privilege';
  end if;

  perform private.pipeline_lock_task_parent(parent_id);

  -- Asking for the state it is already in is not an error. A retried request, or two clicks on the same
  -- button, must not spend one of the five slots or move the completion time.
  if current_status = wanted_status then
    return query
    select
      task.id, task.opportunity_id, task.title, task.instructions, task.assignee_user_id, task.due_on,
      task.status, task.completed_at, task.completed_by, task.created_by, task.created_at, task.updated_at
    from public.tasks as task
    where task.id = target_task_id;
    return;
  end if;

  perform private.assert_task_limit(parent_id, wanted_status);

  return query
  update public.tasks as task
  set
    status = wanted_status,
    completed_at = case when is_completed then now() end,
    completed_by = case when is_completed then (select auth.uid()) end
  where task.id = target_task_id
  returning
    task.id, task.opportunity_id, task.title, task.instructions, task.assignee_user_id, task.due_on,
    task.status, task.completed_at, task.completed_by, task.created_by, task.created_at, task.updated_at;
end;
$$;


ALTER FUNCTION "public"."pipeline_set_task_completed"("target_task_id" "uuid", "is_completed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_stage_counts"("target_organization_id" "uuid", "owner_filter" "text" DEFAULT 'all'::"text", "filter_owner_user_id" "uuid" DEFAULT NULL::"uuid", "created_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "created_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("stage_key" "text", "open_count" bigint, "value_total" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  caller_id uuid := (select auth.uid());
  caller_sees_money boolean;
  filters text := '';
  counted text;
begin
  -- The same rule the select policy applies: current member, active organization, pipeline.view.
  if target_organization_id is null
     or target_organization_id not in (select private.permitted_organizations('pipeline.view')) then
    raise exception 'You do not have access to this sales pipeline.'
      using errcode = 'insufficient_privilege';
  end if;

  if owner_filter not in ('all', 'unassigned', 'member') then
    raise exception 'That is not a way to filter the board.'
      using errcode = 'invalid_parameter_value';
  end if;

  if owner_filter = 'member' and filter_owner_user_id is null then
    raise exception 'Filtering by salesperson needs a salesperson.'
      using errcode = 'invalid_parameter_value';
  end if;

  caller_sees_money :=
    private.member_has_permission(target_organization_id, caller_id, 'pipeline.view_value');

  if owner_filter = 'unassigned' then
    filters := filters || ' and opportunity.owner_user_id is null';
  elsif owner_filter = 'member' then
    filters := filters || format(' and opportunity.owner_user_id = %L', filter_owner_user_id);
  end if;

  -- Calendar boundaries are worked out in the organization's timezone before they get here, so this only
  -- ever sees two instants, and the upper one is the first moment of the day after. The same two the
  -- columns are paging with, so the heading and the cards cannot drift apart.
  if created_from is not null then
    filters := filters || format(' and opportunity.created_at >= %L', created_from);
  end if;
  if created_to is not null then
    filters := filters || format(' and opportunity.created_at < %L', created_to);
  end if;

  counted := format($body$
    select
      opportunity.stage as stage_key,
      count(*) as open_count,
      case when %L::boolean then sum(opportunity.estimated_value) end as value_total
    from public.opportunities as opportunity
    -- Matches the partial board indexes exactly: same tenant, same predicate.
    where opportunity.organization_id = %L
      and opportunity.outcome = 'open'
      and opportunity.stage <> 'request_closed'
  $body$, caller_sees_money, target_organization_id);

  -- Every protected stage is listed, so a column that filtered down to nothing still reports zero and
  -- keeps its heading, instead of going missing from the board.
  return query execute $head$
    select
      board_stage.stage_key,
      coalesce(counted.open_count, 0)::bigint,
      counted.value_total
    from unnest(array[
      'new_request',
      'assessment_unscheduled',
      'assessment_scheduled',
      'assessment_completed',
      'quote_draft',
      'quote_awaiting_response',
      'quote_changes_requested'
    ]) as board_stage(stage_key)
    left join (
  $head$ || counted || filters || $tail$
      group by opportunity.stage
    ) as counted on counted.stage_key = board_stage.stage_key
  $tail$;
end;
$_$;


ALTER FUNCTION "public"."pipeline_stage_counts"("target_organization_id" "uuid", "owner_filter" "text", "filter_owner_user_id" "uuid", "created_from" timestamp with time zone, "created_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_update_opportunity_details"("target_opportunity_id" "uuid", "set_owner" boolean DEFAULT false, "new_owner_user_id" "uuid" DEFAULT NULL::"uuid", "set_value" boolean DEFAULT false, "new_estimated_value" numeric DEFAULT NULL::numeric, "set_expected_close" boolean DEFAULT false, "new_expected_close_on" "date" DEFAULT NULL::"date", "set_next_follow_up" boolean DEFAULT false, "new_next_follow_up_on" "date" DEFAULT NULL::"date") RETURNS TABLE("id" "uuid", "owner_user_id" "uuid", "estimated_value" numeric, "expected_close_on" "date", "next_follow_up_on" "date", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_organization_id uuid;
  target_quote_id uuid;
  caller_id uuid := (select auth.uid());
  caller_sees_money boolean;
begin
  -- Definer rights skip row level security, so membership is checked here by hand rather than assumed.
  select opportunity.organization_id, opportunity.quote_id
  into target_organization_id, target_quote_id
  from public.opportunities as opportunity
  where opportunity.id = target_opportunity_id;

  if target_organization_id is null
     or not private.member_has_permission(target_organization_id, caller_id, 'pipeline.edit') then
    -- Same answer either way: a stranger learns nothing about whether the record exists.
    raise exception 'You do not have access to change this opportunity.'
      using errcode = 'insufficient_privilege';
  end if;

  caller_sees_money :=
    private.member_has_permission(target_organization_id, caller_id, 'pipeline.view_value');

  if set_value and not caller_sees_money then
    raise exception 'You do not have access to change values on the sales pipeline.'
      using errcode = 'insufficient_privilege';
  end if;

  if set_value and target_quote_id is not null then
    raise exception 'A quote-backed opportunity''s value comes from the quote and cannot be edited here.'
      using errcode = 'check_violation';
  end if;

  return query
  update public.opportunities as opportunity
  set
    owner_user_id = case when set_owner then new_owner_user_id else opportunity.owner_user_id end,
    estimated_value = case when set_value then new_estimated_value else opportunity.estimated_value end,
    expected_close_on =
      case when set_expected_close then new_expected_close_on else opportunity.expected_close_on end,
    next_follow_up_on =
      case when set_next_follow_up then new_next_follow_up_on else opportunity.next_follow_up_on end
  where opportunity.id = target_opportunity_id
  returning
    opportunity.id,
    opportunity.owner_user_id,
    -- Nothing is returned to somebody who may not see money, not even the value they did not change.
    case when caller_sees_money then opportunity.estimated_value end,
    opportunity.expected_close_on,
    opportunity.next_follow_up_on,
    opportunity.updated_at;
end;
$$;


ALTER FUNCTION "public"."pipeline_update_opportunity_details"("target_opportunity_id" "uuid", "set_owner" boolean, "new_owner_user_id" "uuid", "set_value" boolean, "new_estimated_value" numeric, "set_expected_close" boolean, "new_expected_close_on" "date", "set_next_follow_up" boolean, "new_next_follow_up_on" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_update_opportunity_note"("target_note_id" "uuid", "target_opportunity_id" "uuid", "new_body" "text") RETURNS TABLE("id" "uuid", "body" "text", "pinned" boolean, "created_by" "uuid", "edited_by" "uuid", "edited_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "entity_type" "text", "entity_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  scope record;
  target_link public.note_links;
  updated_note public.notes;
begin
  select * into scope from private.pipeline_note_scope(target_opportunity_id, 'pipeline.edit');

  select link.* into target_link
  from public.note_links as link
  where link.note_id = target_note_id
    and link.organization_id = scope.organization_id
    and (
      (link.entity_type = 'request' and link.entity_id = scope.request_id)
      or (link.entity_type = 'client' and link.entity_id = scope.client_id)
    )
  limit 1;

  if target_link.id is null then
    raise exception 'That note is not on this opportunity.' using errcode = 'insufficient_privilege';
  end if;

  update public.notes as note
  set body = new_body, edited_by = (select auth.uid()), edited_at = now()
  where note.id = target_note_id
  returning * into updated_note;

  return query
  select
    updated_note.id, updated_note.body, updated_note.pinned, updated_note.created_by,
    updated_note.edited_by, updated_note.edited_at, updated_note.created_at, updated_note.updated_at,
    target_link.entity_type, target_link.entity_id;
end;
$$;


ALTER FUNCTION "public"."pipeline_update_opportunity_note"("target_note_id" "uuid", "target_opportunity_id" "uuid", "new_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_update_opportunity_task"("target_task_id" "uuid", "new_title" "text", "new_instructions" "text" DEFAULT NULL::"text", "new_assignee_user_id" "uuid" DEFAULT NULL::"uuid", "new_due_on" "date" DEFAULT NULL::"date") RETURNS TABLE("id" "uuid", "opportunity_id" "uuid", "title" "text", "instructions" "text", "assignee_user_id" "uuid", "due_on" "date", "status" "text", "completed_at" timestamp with time zone, "completed_by" "uuid", "created_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  parent_id uuid;
begin
  select task.opportunity_id into parent_id from public.tasks as task where task.id = target_task_id;
  if parent_id is null then
    raise exception 'You do not have access to change this task.' using errcode = 'insufficient_privilege';
  end if;

  perform private.pipeline_lock_task_parent(parent_id);

  return query
  update public.tasks as task
  set
    title = new_title,
    instructions = nullif(trim(coalesce(new_instructions, '')), ''),
    assignee_user_id = new_assignee_user_id,
    due_on = new_due_on
  where task.id = target_task_id
  returning
    task.id, task.opportunity_id, task.title, task.instructions, task.assignee_user_id, task.due_on,
    task.status, task.completed_at, task.completed_by, task.created_by, task.created_at, task.updated_at;
end;
$$;


