CREATE OR REPLACE FUNCTION "public"."post_website_chat_message"("session_token_hash" "text", "requesting_origin" "text", "message_body" "text", "new_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "statement_timeout" TO '5000'
    AS $$
declare
  target_session public.website_chat_sessions;
  widget record;
  normalized_origin text := lower(btrim(coalesce(requesting_origin, '')));
  origin_allowed boolean;
  clean_body text;
  clean_idempotency_key text;
  existing_message_id uuid;
  new_message_id uuid;
  rate_check record;
begin
  clean_body := nullif(btrim(coalesce(message_body, '')), '');
  clean_idempotency_key := nullif(btrim(coalesce(new_idempotency_key, '')), '');

  if normalized_origin = '' or clean_body is null
    or nullif(btrim(coalesce(session_token_hash, '')), '') is null then
    return jsonb_build_object('status', 'refused');
  end if;

  select * into target_session
  from public.website_chat_sessions s
  where s.session_token_hash = btrim(post_website_chat_message.session_token_hash)
  for update;
  if not found then
    return jsonb_build_object('status', 'refused');
  end if;

  select w.id, w.disabled_at, w.suspended_at, w.published into widget
  from public.website_chat_widgets w
  where w.id = target_session.widget_id;

  select exists (
    select 1 from public.website_chat_widget_origins o
    where o.widget_id = target_session.widget_id and o.origin = normalized_origin
  ) into origin_allowed;

  if not origin_allowed
    or widget.suspended_at is not null
    or widget.disabled_at is not null
    or not widget.published then
    return jsonb_build_object('status', 'refused');
  end if;

  if target_session.closed_at is not null then
    return jsonb_build_object('status', 'session_closed');
  end if;

  if clean_idempotency_key is not null then
    select m.id into existing_message_id
    from public.website_chat_messages m
    where m.session_id = target_session.id and m.idempotency_key = clean_idempotency_key;
    if found then
      return jsonb_build_object(
        'status', 'accepted', 'replayed', true,
        'session_id', target_session.id, 'message_id', existing_message_id
      );
    end if;
  end if;

  select * into rate_check
  from public.check_rate_limit('website_chat:message:' || target_session.id::text, 60, 20);
  if not rate_check.allowed then
    return jsonb_build_object('status', 'rate_limited');
  end if;

  insert into public.website_chat_messages (
    organization_id, session_id, client_id, direction, sender_type, body, idempotency_key
  ) values (
    target_session.organization_id, target_session.id, target_session.client_id, 'inbound', 'visitor',
    clean_body, clean_idempotency_key
  ) returning id into new_message_id;

  update public.website_chat_sessions
  set last_activity_at = now()
  where id = target_session.id;

  return jsonb_build_object(
    'status', 'accepted', 'replayed', false,
    'session_id', target_session.id, 'message_id', new_message_id
  );
end;
$$;


ALTER FUNCTION "public"."post_website_chat_message"("session_token_hash" "text", "requesting_origin" "text", "message_body" "text", "new_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_website_chat_message"("session_token_hash" "text", "requesting_origin" "text", "message_body" "text", "new_idempotency_key" "text") IS 'Every Website Chat message after the first: origin and session checks, per-session flood limit, insert, and a last_activity_at bump. Never claims an allowance unit.';



CREATE OR REPLACE FUNCTION "public"."post_website_chat_staff_message"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_session_id" "uuid", "message_body" "text", "new_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    SET "statement_timeout" TO '5000'
    AS $$
declare
  target_session public.website_chat_sessions;
  clean_body text;
  clean_idempotency_key text;
  existing_message_id uuid;
  new_message_id uuid;
begin
  if not private.member_has_permission(
    target_organization_id, target_actor_user_id, 'conversations.send'
  ) then
    raise exception 'You do not have permission to send messages.'
      using errcode = 'insufficient_privilege';
  end if;

  clean_body := nullif(btrim(coalesce(message_body, '')), '');
  if clean_body is null then
    raise exception 'Write a message first.' using errcode = 'invalid_parameter_value';
  end if;
  clean_idempotency_key := nullif(btrim(coalesce(new_idempotency_key, '')), '');

  select * into target_session
  from public.website_chat_sessions s
  where s.organization_id = target_organization_id and s.id = target_session_id
  for update;
  if not found then
    raise exception 'That conversation is not available.' using errcode = 'foreign_key_violation';
  end if;

  if clean_idempotency_key is not null then
    select m.id into existing_message_id
    from public.website_chat_messages m
    where m.session_id = target_session.id and m.idempotency_key = clean_idempotency_key;
    if found then
      return jsonb_build_object(
        'status', 'sent', 'replayed', true,
        'session_id', target_session.id, 'message_id', existing_message_id
      );
    end if;
  end if;

  if target_session.closed_at is not null then
    raise exception 'This conversation has ended.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  insert into public.website_chat_messages (
    organization_id, session_id, client_id, direction, sender_type, sender_user_id, body,
    idempotency_key
  ) values (
    target_session.organization_id, target_session.id, target_session.client_id,
    'outbound', 'staff', target_actor_user_id, clean_body, clean_idempotency_key
  ) returning id into new_message_id;

  update public.website_chat_sessions
  set last_activity_at = now()
  where id = target_session.id;

  return jsonb_build_object(
    'status', 'sent', 'replayed', false,
    'session_id', target_session.id, 'message_id', new_message_id
  );
end;
$$;


ALTER FUNCTION "public"."post_website_chat_staff_message"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_session_id" "uuid", "message_body" "text", "new_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_website_chat_staff_message"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_session_id" "uuid", "message_body" "text", "new_idempotency_key" "text") IS 'A staff reply into a live Website Chat session. Re-checks conversations.send, refuses a closed session, and replays a retried send rather than duplicating it. The existing after-insert trigger delivers it to the visitor.';



CREATE OR REPLACE FUNCTION "public"."prepare_invoice_correction"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  predecessor public.invoices;
  successor public.invoices;
begin
  if caller is null then
    raise exception 'You must be signed in to correct an invoice.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.create') then
    raise exception 'You do not have access to create an invoice here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  replayed := private.begin_invoice_command(
    target_organization_id, 'prepare_invoice_correction', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  -- Refuses a voided or already-replaced predecessor and a stale revision on the caller's behalf.
  predecessor := private.lock_invoice_for_edit(
    target_organization_id, target_invoice_id, expected_revision, 'invoices.create'
  );

  if predecessor.issued_at is null and predecessor.recognized_at is null then
    raise exception 'A draft is edited directly rather than corrected.' using errcode = 'check_violation';
  end if;
  if predecessor.written_off_at is not null then
    raise exception 'Undo the write-off before correcting this bill.' using errcode = 'check_violation';
  end if;
  if predecessor.marked_received_at is not null then
    raise exception 'Reopen this bill before correcting it.' using errcode = 'check_violation';
  end if;
  if exists (
    select 1 from public.invoices as existing
    where existing.organization_id = target_organization_id
      and existing.predecessor_invoice_id = predecessor.id
  ) then
    raise exception 'A correction for this invoice already exists.' using errcode = 'unique_violation',
      hint = 'Open that correction and finish it, or delete it if it was a mistake.';
  end if;

  successor := private.create_chain_successor_draft(predecessor, 'correction', caller);

  perform private.record_invoice_event(
    target_organization_id, successor.id, successor.invoice_number, successor.client_id,
    'invoice.created_as_correction', caller, successor.revision, null,
    jsonb_build_object(
      'predecessor_invoice_id', predecessor.id,
      'predecessor_invoice_number', predecessor.invoice_number
    ),
    false, null
  );

  return private.complete_invoice_command(
    target_organization_id, 'prepare_invoice_correction', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', successor.id,
      'invoice_number', successor.invoice_number,
      'revision', successor.revision,
      'predecessor_invoice_id', predecessor.id,
      'root_invoice_id', successor.root_invoice_id,
      'replacement_kind', 'correction'
    )
  );
end;
$$;


ALTER FUNCTION "public"."prepare_invoice_correction"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prepare_invoice_correction"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_idempotency_key" "text", "new_request_hash" "text") IS 'Prepares a replacement draft beside an issued invoice, copying its document, lines and amounts. The original stays the live receivable until the replacement is activated.';



CREATE OR REPLACE FUNCTION "public"."prepare_team_invitation_identity_cleanup"("target_invitation_id" "uuid", "target_lease_nonce" "uuid") RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_invited_user_id uuid;
  prepared_row public.organization_member_invitations;
begin
  select invitation.invited_user_id
  into target_invited_user_id
  from public.organization_member_invitations as invitation
  where invitation.id = target_invitation_id
    and invitation.state in ('reserving', 'invited', 'accepting', 'cancelled', 'expired', 'abandoned')
    and invitation.identity_cleanup_state = 'required'
    and invitation.reconciliation_nonce = target_lease_nonce
    and invitation.reconciliation_lease_expires_at > now()
  for update;

  if not found then
    raise exception 'The invitation cleanup lease is no longer valid.'
      using errcode = 'P0409';
  end if;

  update public.organization_member_invitations
  set state = case
        when state in ('cancelled', 'expired', 'abandoned') then state
        else 'reserving'
      end,
      invited_user_id = null,
      token_hash = null,
      lease_nonce = null,
      lease_expires_at = null
  where id = target_invitation_id
  returning * into prepared_row;

  delete from public.organization_members
  where organization_id = prepared_row.organization_id
    and user_id = target_invited_user_id
    and status = 'pending';

  return prepared_row;
end;
$$;


