CREATE OR REPLACE FUNCTION "public"."preview_automation_manual_enrollment"("p_organization_id" "uuid", "p_recipe_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  recipe public.automation_recipes%rowtype;
  version public.automation_recipe_versions%rowtype;
  expected_messages integer;
  already_enrolled boolean;
  overlap_same integer;
  overlap_other integer;
begin
  if p_subject_type is distinct from 'quote' then
    return jsonb_build_object('eligible', false, 'reason', 'unsupported_subject');
  end if;

  select * into recipe
  from public.automation_recipes
  where id = p_recipe_id and organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('eligible', false, 'reason', 'recipe_not_found');
  end if;
  if recipe.status <> 'active' or recipe.current_version_id is null then
    return jsonb_build_object('eligible', false, 'reason', 'recipe_not_active');
  end if;

  select * into version
  from public.automation_recipe_versions
  where id = recipe.current_version_id and organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('eligible', false, 'reason', 'recipe_not_active');
  end if;

  select count(*) into expected_messages
  from jsonb_array_elements(version.definition -> 'steps') as step
  where step ->> 'type' = 'action';

  select
    count(*) filter (where recipe_id = p_recipe_id),
    count(*) filter (where recipe_id <> p_recipe_id)
  into overlap_same, overlap_other
  from private.automation_enrollments
  where organization_id = p_organization_id
    and subject_type = p_subject_type
    and subject_id = p_subject_id
    and state in ('active', 'paused');

  already_enrolled := overlap_same > 0;

  return jsonb_build_object(
    'eligible', not already_enrolled,
    'reason', case when already_enrolled then 'already_enrolled' else null end,
    'recipe_id', p_recipe_id,
    'recipe_name', recipe.name,
    'version_id', version.id,
    'version_number', version.version_number,
    'first_due_at', now(),
    'expected_message_count', expected_messages,
    'overlap_same_recipe', overlap_same,
    'overlap_other_recipes', overlap_other
  );
end;
$$;


ALTER FUNCTION "public"."preview_automation_manual_enrollment"("p_organization_id" "uuid", "p_recipe_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."preview_automation_manual_enrollment"("p_organization_id" "uuid", "p_recipe_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid") IS 'Read-only manual-enroll eligibility for one record: recipe version, first due time, expected message count, and same-subject overlap. Safe projection; service role only.';



CREATE OR REPLACE FUNCTION "public"."preview_job_recurrence"("rule" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  parsed record;
  found_dates date[];
  ceiling integer := private.job_recurrence_limit();
begin
  if (select auth.uid()) is null then
    raise exception 'You must be signed in.' using errcode = 'insufficient_privilege';
  end if;

  select * into parsed from private.read_job_recurrence(rule);

  select array_agg(day order by day) into found_dates
  from private.job_recurrence_dates(
    parsed.frequency, parsed.interval_count, parsed.weekdays, parsed.monthly_mode,
    parsed.month_day, parsed.ordinal_week, parsed.ordinal_weekday, parsed.start_date, parsed.end_date
  ) as day;

  return jsonb_build_object(
    'visit_count', coalesce(array_length(found_dates, 1), 0),
    'first_date', found_dates[1],
    'last_date', found_dates[array_length(found_dates, 1)],
    'end_date', parsed.end_date,
    'limit', ceiling,
    'over_limit', coalesce(array_length(found_dates, 1), 0) > ceiling
  );
end;
$$;


ALTER FUNCTION "public"."preview_job_recurrence"("rule" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."preview_job_recurrence"("rule" "jsonb") IS 'How many visits a repeat rule makes, and its first and last date. Pure date arithmetic on unsaved form input; shares private.job_recurrence_dates with generation so the count cannot disagree with the save.';



CREATE OR REPLACE FUNCTION "public"."preview_organization_closure_impact"("target_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  organization_row public.organizations%rowtype;
  open_closure public.organization_closure_records%rowtype;
  replies_since timestamptz;
  active_alias_count integer;
  queued_message_count integer;
  recent_reply_count integer;
begin
  select * into organization_row
  from public.organizations
  where id = target_organization_id;

  if not found then
    raise exception 'Organization was not found.' using errcode = 'foreign_key_violation';
  end if;

  select * into open_closure
  from public.organization_closure_records
  where organization_id = target_organization_id
    and status in ('pending_closure', 'purge_in_progress');

  replies_since := coalesce(open_closure.started_at, now() - interval '30 days');

  select count(*)::integer into active_alias_count
  from public.communication_reply_aliases
  where organization_id = target_organization_id
    and expires_at > now();

  select count(*)::integer into queued_message_count
  from public.communication_outbox_events
  where organization_id = target_organization_id
    and status in ('pending', 'processing', 'failed', 'submission_unknown');

  select count(*)::integer into recent_reply_count
  from public.communication_inbound_messages
  where organization_id = target_organization_id
    and created_at >= replies_since;

  return jsonb_build_object(
    'organization_id', target_organization_id,
    'lifecycle_status', organization_row.lifecycle_status,
    'closure_record_id', open_closure.id,
    'closure_started_at', open_closure.started_at,
    'closure_deadline_at', open_closure.deadline_at,
    'active_reply_aliases', active_alias_count,
    'queued_messages', queued_message_count,
    'recent_replies', recent_reply_count,
    'recent_replies_since', replies_since
  );
end;
$$;


ALTER FUNCTION "public"."preview_organization_closure_impact"("target_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."preview_organization_closure_impact"("target_organization_id" "uuid") IS 'What an early permanent deletion would destroy right now: active reply aliases, unfinished queued messages, and replies received since closure started.';



CREATE OR REPLACE FUNCTION "public"."preview_quote_version_totals"("target_quote_id" "uuid", "selected_addon_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  version_id uuid;
  calculated jsonb;
begin
  select * into quote_row from public.quotes where id = target_quote_id;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.view'
     ) then
    raise exception 'You do not have access to this quote.' using errcode = 'insufficient_privilege';
  end if;

  if not private.member_has_permission(
    quote_row.organization_id, (select auth.uid()), 'quotes.view_price'
  ) then
    raise exception 'You do not have access to the prices on this quote.'
      using errcode = 'insufficient_privilege';
  end if;

  version_id := coalesce(quote_row.draft_version_id, quote_row.current_published_version_id);
  if version_id is null then
    raise exception 'This quote has nothing to price yet.' using errcode = 'check_violation';
  end if;

  calculated := private.calculate_quote_version(version_id, selected_addon_ids);

  if private.member_has_permission(
    quote_row.organization_id, (select auth.uid()), 'quotes.view_cost'
  ) then
    return calculated;
  end if;
  return private.quote_customer_totals(calculated);
end;
$$;


ALTER FUNCTION "public"."preview_quote_version_totals"("target_quote_id" "uuid", "selected_addon_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."preview_quote_version_totals"("target_quote_id" "uuid", "selected_addon_ids" "uuid"[]) IS 'What the customer would pay with these optional add-ons selected. Requires quotes.view and quotes.view_price; cost, profit, and margin are included only for quotes.view_cost.';



CREATE OR REPLACE FUNCTION "public"."pricing_line_total_minor"("quantity" numeric, "unit_price_minor" bigint) RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select round(quantity * unit_price_minor)::bigint;
$$;


ALTER FUNCTION "public"."pricing_line_total_minor"("quantity" numeric, "unit_price_minor" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pricing_line_total_minor"("quantity" numeric, "unit_price_minor" bigint) IS 'The only line-total arithmetic in the product. Minor units in, minor units out, half away from zero. Stored generated columns on request_pricing_lines and quote_version_lines call it, so no application code may reimplement it.';



CREATE OR REPLACE FUNCTION "public"."process_automation_sms_email_fallbacks"("p_batch_size" integer DEFAULT 25) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  candidate private.automation_sms_email_fallbacks%rowtype;
  enrollment private.automation_enrollments%rowtype;
  recipe_status text;
  step jsonb;
  skip_reason text;
  subject record;
  result jsonb;
  processed_count integer := 0;
  max_attempts constant integer := 8;
begin
  if p_batch_size < 1 or p_batch_size > 200 then
    raise exception 'The fallback batch size is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  for candidate in
    select * from private.automation_sms_email_fallbacks
    where state = 'due' and available_at <= now()
    order by available_at
    limit p_batch_size
    for update skip locked
  loop
    begin
      skip_reason := null;
      select * into enrollment from private.automation_enrollments where id = candidate.enrollment_id;
      select recipe.status, version.definition -> 'steps' -> candidate.step_index into recipe_status, step
        from public.automation_recipes recipe
        join public.automation_recipe_versions version on version.id = enrollment.recipe_version_id
        where recipe.id = enrollment.recipe_id;

      if enrollment.state in ('stopped', 'failed') then
        skip_reason := coalesce(enrollment.stop_reason, 'enrollment_stopped');
      elsif enrollment.state = 'paused' then
        skip_reason := 'enrollment_paused';
      elsif enrollment.expires_at is not null and enrollment.expires_at <= now() then
        skip_reason := 'enrollment_expired';
      elsif recipe_status is distinct from 'active' and recipe_status is distinct from 'paused' then
        skip_reason := 'recipe_not_active';
      else
        skip_reason := private.automation_inquiry_stop_outcome(
          enrollment.organization_id, enrollment.subject_type, enrollment.subject_id, enrollment.anchor_at);
        if skip_reason is null and private.automation_inquiry_customer_reply_at(
            enrollment.organization_id, enrollment.subject_type, enrollment.subject_id,
            enrollment.customer_reply_after) is not null then
          skip_reason := 'customer_replied';
        end if;
      end if;

      if skip_reason is not null then
        update private.automation_sms_email_fallbacks
          set state = 'skipped', reason = left(skip_reason, 100), available_at = null
          where id = candidate.id;
      elsif recipe_status = 'paused' then
        update private.automation_sms_email_fallbacks
          set available_at = now() + private.automation_retry_delay(candidate.attempts + 1)
          where id = candidate.id;
      else
        select * into subject from private.automation_inquiry_client_id(
          enrollment.organization_id, enrollment.subject_type, enrollment.subject_id);
        result := private.enqueue_automation_inquiry_email(
          enrollment.organization_id, subject.client_id,
          'automation-inquiry-message-email:' || enrollment.id || ':' || enrollment.recipe_version_id || ':'
            || candidate.step_index,
          step -> 'config' ->> 'email_subject', step -> 'config' ->> 'email_body');

        if result ->> 'status' = 'sent' then
          update private.automation_sms_email_fallbacks
            set state = 'sent', email_delivery_intent_id = (result ->> 'intent_id')::uuid, reason = null,
              available_at = null
            where id = candidate.id;
          if result ->> 'reason' = 'enqueued' then
            update private.automation_enrollments
              set customer_messages_sent = customer_messages_sent + 1 where id = enrollment.id;
          end if;
        elsif result ->> 'status' = 'skipped_temporary' and candidate.attempts + 1 < max_attempts then
          update private.automation_sms_email_fallbacks
            set attempts = attempts + 1, reason = left(result ->> 'reason', 100),
              available_at = now() + private.automation_retry_delay(candidate.attempts + 1)
            where id = candidate.id;
        else
          update private.automation_sms_email_fallbacks
            set state = 'skipped', attempts = attempts + 1, reason = left(result ->> 'reason', 100),
              available_at = null
            where id = candidate.id;
        end if;
      end if;
      processed_count := processed_count + 1;
    exception
      when others then
        update private.automation_sms_email_fallbacks
          set attempts = attempts + 1, reason = left(coalesce(sqlerrm, 'unknown error'), 100),
            state = case when attempts + 1 >= max_attempts then 'skipped' else state end,
            available_at = case when attempts + 1 >= max_attempts then null
              else now() + private.automation_retry_delay(attempts + 1) end
          where id = candidate.id;
    end;
  end loop;

  return processed_count;
end;
$$;


ALTER FUNCTION "public"."process_automation_sms_email_fallbacks"("p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_automation_sms_email_fallbacks"("p_batch_size" integer) IS 'Bounded drain of due SMS-to-email fallbacks: skips when the enrollment stopped/paused/expired, a person answered or the customer replied, otherwise queues the step''s email once (logical send key). Temporary refusals back off up to eight attempts. Service role only.';



CREATE OR REPLACE FUNCTION "public"."process_communication_provider_callbacks"("batch_size" integer DEFAULT 500) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  candidate record;
  norm text;
  processed_count integer := 0;
  max_processing_attempts constant integer := 5;
  applied_outcome text;
begin
  if batch_size < 1 or batch_size > 2000 then
    raise exception 'The callback batch size is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  for candidate in
    select
      cb.id,
      cb.event_kind,
      cb.occurred_at,
      cb.received_at,
      cb.processing_attempts,
      cb.delivery_intent_id,
      intent.organization_id,
      intent.recipient_email,
      intent.delivery_outcome as current_outcome,
      intent.quote_id,
      intent.quote_version_id,
      intent.quote_recipient_id,
      intent.client_id,
      intent.client_contact_method_id
    from public.communication_provider_callback_events cb
    left join public.communication_delivery_intents intent on intent.id = cb.delivery_intent_id
    where cb.channel = 'email' and cb.processed_at is null
    order by cb.received_at, cb.id
    limit batch_size
    for update of cb skip locked
  loop
    norm := case lower(trim(candidate.event_kind))
      when 'delivered' then 'delivered'
      when 'soft_bounce' then 'soft_bounce'
      when 'hard_bounce' then 'hard_bounce'
      when 'invalid_email' then 'hard_bounce'
      when 'blocked' then 'blocked'
      when 'spam' then 'complaint'
      when 'complaint' then 'complaint'
      when 'deferred' then 'deferred'
      when 'unsubscribed' then 'unsubscribed'
      when 'list_addition' then 'other'
      when 'opened' then 'opened'
      when 'unique_opened' then 'opened'
      when 'click' then 'clicked'
      when 'proxy_open' then 'opened'
      else 'other'
    end;
    applied_outcome := null;

    begin
      if candidate.delivery_intent_id is null or candidate.organization_id is null then
        update public.communication_provider_callback_events
        set processed_at = now(), normalized_kind = norm
        where id = candidate.id;
        processed_count := processed_count + 1;
        continue;
      end if;

      if norm in ('delivered', 'soft_bounce', 'hard_bounce', 'complaint', 'deferred', 'blocked', 'unsubscribed') then
        update public.communication_delivery_intents
        set delivery_outcome = norm,
          delivery_outcome_at = coalesce(candidate.occurred_at, candidate.received_at),
          delivery_outcome_detail = nullif(trim(candidate.event_kind), '')
        where id = candidate.delivery_intent_id
          and (
            delivery_outcome is null
            or delivery_outcome not in ('hard_bounce', 'complaint')
            or norm in ('hard_bounce', 'complaint')
          )
        returning delivery_outcome into applied_outcome;
      end if;

      if applied_outcome = 'delivered'
        and candidate.quote_id is not null
        and candidate.quote_version_id is not null then
        perform private.emit_automation_event(
          candidate.organization_id,
          'quote.delivery_succeeded',
          'quote',
          candidate.quote_id,
          jsonb_build_object(
            'delivery_intent_id', candidate.delivery_intent_id,
            'quote_id', candidate.quote_id,
            'quote_version_id', candidate.quote_version_id,
            'quote_recipient_id', candidate.quote_recipient_id,
            'client_id', candidate.client_id,
            'client_contact_method_id', candidate.client_contact_method_id
          ),
          coalesce(candidate.occurred_at, candidate.received_at),
          'communications',
          candidate.delivery_intent_id
        );
      end if;

      if norm in ('complaint', 'hard_bounce') then
        insert into public.communication_email_suppressions (
          organization_id, recipient_email, reason, source, source_callback_event_id,
          first_delivery_intent_id, evidence
        ) values (
          candidate.organization_id, candidate.recipient_email, norm, 'provider_callback', candidate.id,
          candidate.delivery_intent_id,
          jsonb_build_object(
            'event_kind', candidate.event_kind,
            'occurred_at', candidate.occurred_at,
            'received_at', candidate.received_at
          )
        )
        on conflict (organization_id, recipient_email, reason) where released_at is null
        do nothing;
      elsif norm = 'unsubscribed' then
        insert into public.communication_email_suppressions (
          organization_id, recipient_email, reason, source, source_callback_event_id,
          first_delivery_intent_id, evidence
        ) values (
          candidate.organization_id, candidate.recipient_email, 'unsubscribe', 'provider_callback',
          candidate.id, candidate.delivery_intent_id,
          jsonb_build_object(
            'event_kind', candidate.event_kind,
            'occurred_at', candidate.occurred_at,
            'received_at', candidate.received_at
          )
        )
        on conflict (organization_id, recipient_email, reason) where released_at is null
        do nothing;
      end if;

      if norm in ('complaint', 'hard_bounce', 'unsubscribed') then
        insert into public.communication_email_reputation_state (organization_id, evaluation_requested_at)
        values (candidate.organization_id, now())
        on conflict (organization_id) do update
        set evaluation_requested_at = excluded.evaluation_requested_at;
      end if;

      update public.communication_provider_callback_events
      set processed_at = now(), normalized_kind = norm, organization_id = candidate.organization_id
      where id = candidate.id;
      processed_count := processed_count + 1;
    exception
      when others then
        update public.communication_provider_callback_events
        set processing_attempts = coalesce(processing_attempts, 0) + 1,
          processing_error = left(coalesce(sqlerrm, 'unknown error'), 1000),
          normalized_kind = coalesce(normalized_kind, norm),
          processed_at = case
            when coalesce(processing_attempts, 0) + 1 >= max_processing_attempts then now()
            else processed_at
          end
        where id = candidate.id;
    end;
  end loop;

  return processed_count;
end;
$$;


ALTER FUNCTION "public"."process_communication_provider_callbacks"("batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_communication_sms_provider_callbacks"("batch_size" integer DEFAULT 500) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  candidate record;
  norm text;
  current_outcome text;
  new_is_success boolean;
  new_is_failure boolean;
  cur_is_success boolean;
  cur_is_failure boolean;
  next_outcome text;
  processed_count integer := 0;
  max_processing_attempts constant integer := 5;
begin
  if batch_size < 1 or batch_size > 2000 then
    raise exception 'The callback batch size is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  for candidate in
    select
      cb.id,
      cb.event_kind,
      cb.occurred_at,
      cb.received_at,
      cb.delivery_intent_id,
      intent.organization_id,
      intent.delivery_outcome as current_outcome
    from public.communication_provider_callback_events cb
    left join public.communication_delivery_intents intent on intent.id = cb.delivery_intent_id
    where cb.channel = 'sms' and cb.processed_at is null
    order by cb.received_at, cb.id
    limit batch_size
    for update of cb skip locked
  loop
    norm := case lower(trim(candidate.event_kind))
      when 'delivered' then 'sms_delivered'
      when 'sent' then 'sms_sent'
      when 'undelivered' then 'sms_undelivered'
      when 'failed' then 'sms_failed'
      else 'other'
    end;

    begin
      if candidate.delivery_intent_id is null or candidate.organization_id is null then
        update public.communication_provider_callback_events
        set processed_at = now(), normalized_kind = norm
        where id = candidate.id;
        processed_count := processed_count + 1;
        continue;
      end if;

      if norm in ('sms_delivered', 'sms_undelivered', 'sms_failed') then
        current_outcome := candidate.current_outcome;
        new_is_success := norm = 'sms_delivered';
        new_is_failure := norm in ('sms_undelivered', 'sms_failed');
        cur_is_success := current_outcome = 'sms_delivered';
        cur_is_failure := current_outcome in ('sms_undelivered', 'sms_failed');
        next_outcome := null;

        if current_outcome is null
          or current_outcome not in ('sms_delivered', 'sms_undelivered', 'sms_failed', 'sms_needs_checking') then
          next_outcome := norm;
        elsif current_outcome = 'sms_needs_checking' then
          next_outcome := null;
        elsif (cur_is_success and new_is_failure) or (cur_is_failure and new_is_success) then
          next_outcome := 'sms_needs_checking';
        else
          next_outcome := null;
        end if;

        if next_outcome is not null then
          update public.communication_delivery_intents
          set delivery_outcome = next_outcome,
            delivery_outcome_at = coalesce(candidate.occurred_at, candidate.received_at),
            delivery_outcome_detail = nullif(trim(candidate.event_kind), '')
          where id = candidate.delivery_intent_id;
        end if;
      end if;

      update public.communication_provider_callback_events
      set processed_at = now(), normalized_kind = norm, organization_id = candidate.organization_id
      where id = candidate.id;
      processed_count := processed_count + 1;
    exception
      when others then
        update public.communication_provider_callback_events
        set processing_attempts = coalesce(processing_attempts, 0) + 1,
          processing_error = left(coalesce(sqlerrm, 'unknown error'), 1000),
          normalized_kind = coalesce(normalized_kind, norm),
          processed_at = case
            when coalesce(processing_attempts, 0) + 1 >= max_processing_attempts then now()
            else processed_at
          end
        where id = candidate.id;
    end;
  end loop;

  return processed_count;
end;
$$;


ALTER FUNCTION "public"."process_communication_sms_provider_callbacks"("batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_communication_sms_provider_callbacks"("batch_size" integer) IS 'Projects durable Twilio SMS status callbacks (channel=sms) onto delivery_outcome: terminal outcomes are never regressed, and a delivered vs failed/undelivered conflict becomes sms_needs_checking.';



CREATE OR REPLACE FUNCTION "public"."process_next_form_submission"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  submission private.form_submissions;
  form_row public.forms;
  rules public.form_booking_rules;
  org_active boolean;
  version_content jsonb;
  clean_name text;
  given_name text;
  family_name text;
  first_space integer;
  match_phone text;
  match_email text;
  phone_candidate uuid;
  email_candidate uuid;
  phone_match_count integer := 0;
  email_match_count integer := 0;
  resolved_client_id uuid;
  is_new_client boolean := false;
  new_client_id uuid;
  address jsonb;
  has_address boolean;
  resolved_property_id uuid;
  description_text text;
  org_timezone text;
  organization_currency text;
  new_request_id uuid;
  new_assessment_id uuid;
  created_job public.jobs;
  new_visit public.job_visits;
  catalog_row public.catalog_items;
  preferred_time_text text;
  outcome_kind text;
  calculated jsonb;
  outcome_payload jsonb;
begin
  select * into submission
  from private.form_submissions
  where status = 'pending'
  order by created_at
  for update skip locked
  limit 1;

  if not found then
    return jsonb_build_object('status', 'idle');
  end if;

  begin
    select * into form_row from public.forms where id = submission.form_id;
    select exists (
      select 1 from public.organizations
      where id = submission.organization_id and lifecycle_status = 'active'
    ) into org_active;

    if form_row.id is null or not org_active or form_row.archived_at is not null
      or not form_row.is_enabled or form_row.current_published_version_id is null
    then
      raise exception 'That form is no longer available.' using errcode = 'check_violation';
    end if;

    select settings.timezone, settings.currency_code into org_timezone, organization_currency
    from public.organization_settings as settings
    where settings.organization_id = submission.organization_id;
    org_timezone := coalesce(org_timezone, 'UTC');
    organization_currency := coalesce(organization_currency, 'USD');

    match_phone := nullif(regexp_replace(coalesce(submission.contact->>'phone', ''), '[^0-9]', '', 'g'), '');
    match_email := lower(nullif(trim(coalesce(submission.contact->>'email', '')), ''));

    if match_phone is not null then
      select count(distinct method.client_id), min(method.client_id::text)::uuid
      into phone_match_count, phone_candidate
      from public.client_contact_methods method
      join public.clients client
        on client.organization_id = method.organization_id and client.id = method.client_id
      where method.organization_id = submission.organization_id
        and method.kind = 'phone'
        and method.normalized_value = match_phone
        and client.deleted_at is null;
      if phone_match_count <> 1 then phone_candidate := null; end if;
    end if;

    if match_email is not null then
      select count(distinct method.client_id), min(method.client_id::text)::uuid
      into email_match_count, email_candidate
      from public.client_contact_methods method
      join public.clients client
        on client.organization_id = method.organization_id and client.id = method.client_id
      where method.organization_id = submission.organization_id
        and method.kind = 'email'
        and method.normalized_value = match_email
        and client.deleted_at is null;
      if email_match_count <> 1 then email_candidate := null; end if;
    end if;

    if phone_match_count > 1 or email_match_count > 1
      or (phone_candidate is not null and email_candidate is not null and phone_candidate <> email_candidate)
    then
      resolved_client_id := null;
    else
      resolved_client_id := coalesce(phone_candidate, email_candidate);
    end if;

    if resolved_client_id is null then
      is_new_client := true;
      clean_name := coalesce(
        nullif(btrim(regexp_replace(coalesce(submission.contact->>'name', ''), '\s+', ' ', 'g')), ''),
        'Website visitor'
      );
      first_space := position(' ' in clean_name);
      if first_space > 0 then
        given_name := substr(clean_name, 1, first_space - 1);
        family_name := nullif(btrim(substr(clean_name, first_space + 1)), '');
      else
        given_name := clean_name;
        family_name := null;
      end if;

      insert into public.clients (
        organization_id, display_name, first_name, last_name, lifecycle_status, lead_source, client_type
      ) values (
        submission.organization_id, clean_name, given_name, family_name, 'lead',
        'Website form: ' || form_row.name, 'person'
      ) returning id into new_client_id;
      resolved_client_id := new_client_id;

      if match_phone is not null then
        insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
        values (submission.organization_id, new_client_id, 'phone', match_phone, true)
        on conflict do nothing;
      end if;
      if match_email is not null then
        insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
        values (submission.organization_id, new_client_id, 'email', match_email, true)
        on conflict do nothing;
      end if;
    end if;

    address := submission.contact->'address';
    has_address := address is not null and jsonb_typeof(address) = 'object'
      and coalesce(nullif(btrim(address->>'line1'), ''), '') <> '';

    if not is_new_client and not has_address then
      select id into resolved_property_id from public.properties
      where client_id = resolved_client_id and is_primary and deleted_at is null
      limit 1;
    end if;

    if resolved_property_id is null then
      insert into public.properties (organization_id, client_id, address_line1, city, state_region, postal_code)
      values (
        submission.organization_id, resolved_client_id,
        coalesce(nullif(btrim(address->>'line1'), ''), 'Address not provided'),
        coalesce(nullif(btrim(address->>'city'), ''), 'Unknown'),
        nullif(btrim(address->>'state_region'), ''),
        nullif(btrim(address->>'postal_code'), '')
      ) returning id into resolved_property_id;
    end if;

    select fv.content into version_content
    from public.form_versions fv
    where fv.id = submission.form_version_id;

    select string_agg((q.value->>'label') || ': ' || a.answer_text, e'\n' order by s.section_ord, q.question_ord)
    into description_text
    from jsonb_array_elements(coalesce(version_content->'sections', '[]'::jsonb))
      with ordinality as s(value, section_ord)
    cross join lateral jsonb_array_elements(coalesce(s.value->'questions', '[]'::jsonb))
      with ordinality as q(value, question_ord)
    cross join lateral (
      select case jsonb_typeof(submission.answers -> (q.value->>'id'))
        when 'array' then (
          select string_agg(elem #>> '{}', ', ')
          from jsonb_array_elements(submission.answers -> (q.value->>'id')) as elem
        )
        when 'string' then submission.answers ->> (q.value->>'id')
        when 'number' then submission.answers ->> (q.value->>'id')
        when 'boolean' then case (submission.answers ->> (q.value->>'id'))
          when 'true' then 'Yes' when 'false' then 'No' else null end
        else null
      end as answer_text
    ) a
    where submission.answers ? (q.value->>'id') and coalesce(a.answer_text, '') <> '';

    if form_row.outcome = 'request' then
      insert into public.requests (organization_id, client_id, property_id, title, description)
      values (
        submission.organization_id, resolved_client_id, resolved_property_id,
        coalesce(nullif(btrim(form_row.name), ''), 'Website request'), description_text
      ) returning id into new_request_id;

      outcome_payload := jsonb_build_object(
        'outcome', 'request', 'client_id', resolved_client_id, 'property_id', resolved_property_id,
        'request_id', new_request_id
      );

    elsif form_row.outcome = 'assessment' then
      select * into rules from public.form_booking_rules
      where form_id = form_row.id and organization_id = submission.organization_id;

      outcome_kind := case
        when rules.requires_booking_approval or submission.assigned_user_id is null then 'needs_approval'
        else 'confirmed'
      end;

      if outcome_kind = 'needs_approval' then
        preferred_time_text := 'Customer requested '
          || to_char(submission.requested_starts_at at time zone org_timezone, 'Dy, Mon DD "at" HH12:MI AM')
          || ' - '
          || to_char(submission.requested_ends_at at time zone org_timezone, 'HH12:MI AM');
      end if;

      insert into public.requests (
        organization_id, client_id, property_id, title, description, status, preferred_time
      ) values (
        submission.organization_id, resolved_client_id, resolved_property_id,
        coalesce(nullif(btrim(form_row.name), ''), 'Website request'), description_text,
        case when outcome_kind = 'needs_approval' then 'needs_approval' else 'new' end,
        preferred_time_text
      ) returning id into new_request_id;

      if outcome_kind = 'confirmed' then
        insert into public.assessments (organization_id, request_id, starts_at, ends_at)
        values (
          submission.organization_id, new_request_id, submission.requested_starts_at, submission.requested_ends_at
        ) returning id into new_assessment_id;

        insert into public.assessment_assignees (organization_id, assessment_id, user_id)
        values (submission.organization_id, new_assessment_id, submission.assigned_user_id);
      end if;

      outcome_payload := jsonb_build_object(
        'outcome', case when outcome_kind = 'needs_approval' then 'assessment_needs_approval' else 'assessment' end,
        'client_id', resolved_client_id, 'property_id', resolved_property_id,
        'request_id', new_request_id, 'assessment_id', new_assessment_id
      );

    elsif form_row.outcome = 'job' then
      created_job := private.create_job(
        submission.organization_id, resolved_client_id, resolved_property_id,
        coalesce(nullif(btrim(form_row.name), ''), 'Website booking'),
        'one_off', 'job_total', organization_currency, null, false, 'on_closure',
        description_text, null, null, null, null
      );

      if submission.selected_catalog_item_id is not null then
        select * into catalog_row from public.catalog_items where id = submission.selected_catalog_item_id;
        if catalog_row.id is not null then
          insert into public.job_line_items (
            organization_id, job_id, position, source_catalog_item_id, line_kind, category, is_labor,
            name, description, unit_label, quantity, unit_price_minor, unit_cost_minor, is_taxable
          ) values (
            created_job.organization_id, created_job.id, 0, catalog_row.id, 'priced', catalog_row.category,
            catalog_row.is_labor, catalog_row.name, catalog_row.description, catalog_row.unit_label, 1,
            catalog_row.unit_price_minor, catalog_row.unit_cost_minor, catalog_row.is_taxable
          );
        end if;
      end if;

      insert into public.job_visits (organization_id, job_id, position, visit_date, start_time, end_time, source)
      values (
        created_job.organization_id, created_job.id, 0,
        (submission.requested_starts_at at time zone org_timezone)::date,
        (submission.requested_starts_at at time zone org_timezone)::time,
        (submission.requested_ends_at at time zone org_timezone)::time,
        'manual'
      ) returning * into new_visit;

      insert into public.job_visit_assignments (organization_id, visit_id, user_id)
      values (created_job.organization_id, new_visit.id, submission.assigned_user_id);

      calculated := private.store_job_money(created_job.id);

      outcome_payload := jsonb_build_object(
        'outcome', 'job', 'client_id', resolved_client_id, 'property_id', resolved_property_id,
        'job_id', created_job.id, 'job_number', created_job.job_number, 'visit_id', new_visit.id
      );
    end if;

    update private.form_submissions
    set status = 'processed', processed_at = now(), result = outcome_payload
    where id = submission.id;

    return jsonb_build_object('status', 'processed', 'submission_id', submission.id) || outcome_payload;
  exception
    when others then
      update private.form_submissions
      set status = 'failed', processed_at = now(), processing_error = sqlerrm
      where id = submission.id;
      return jsonb_build_object('status', 'failed', 'submission_id', submission.id, 'error', sqlerrm);
  end;
end;
$$;


ALTER FUNCTION "public"."process_next_form_submission"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_next_form_submission"() IS 'The worker''s one entry point. Claims the oldest pending form_submissions row (for update skip locked, same competing-consumer primitive as the geocoding queue), turns it into a Request, a Request + confirmed Assessment, a needs_approval Request, or a Job + first Visit, and marks it processed -- all in one transaction, so a crash mid-flight simply leaves it pending for the next wake to retry. Returns {status: idle} when the queue is empty.';



CREATE OR REPLACE FUNCTION "public"."process_next_import_row"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  row_rec public.import_rows;
  batch_rec public.import_batches;
  final_batch public.import_batches;
  client_payload jsonb;
  property_payload jsonb;
  email_value text;
  phone_value text;
  note_value text;
  new_client_id uuid;
  new_note_id uuid;
  ob_predecessor_id uuid;
  ob_predecessor public.client_opening_balances;
  ob_root_id uuid;
begin
  -- 1. Claim the oldest ready row across all committed batches, any entity type. The partial
  -- import_rows_ready_idx leads on exactly this ORDER BY, so the claim is a plain index walk with no sort
  -- (competing-consumer queue).
  select * into row_rec
  from public.import_rows
  where status = 'ready'
  order by created_at, source_row_number
  for update skip locked
  limit 1;

  if found then
    select * into batch_rec from public.import_batches where id = row_rec.batch_id;
    client_payload := row_rec.resolved_payload -> 'client';
    property_payload := row_rec.resolved_payload -> 'property';
    email_value := nullif(trim(row_rec.resolved_payload ->> 'email'), '');
    phone_value := nullif(trim(row_rec.resolved_payload ->> 'phone'), '');
    note_value := nullif(trim(client_payload ->> 'initial_note'), '');

    begin
      if batch_rec.entity_type = 'client' then
        if row_rec.planned_action = 'create' then
          -- 1a. The client itself. Every field is already validated and defaulted by the Review step; the
          -- column set mirrors public.create_client.
          insert into public.clients (
            organization_id, display_name, client_type, first_name, last_name, company_name,
            lifecycle_status, lead_source
          )
          values (
            row_rec.organization_id,
            client_payload ->> 'display_name',
            coalesce(nullif(client_payload ->> 'client_type', ''), 'person'),
            nullif(trim(client_payload ->> 'first_name'), ''),
            nullif(trim(client_payload ->> 'last_name'), ''),
            nullif(trim(client_payload ->> 'company_name'), ''),
            coalesce(nullif(client_payload ->> 'lifecycle_status', ''), 'lead'),
            nullif(trim(client_payload ->> 'lead_source'), '')
          )
          returning id into new_client_id;

          -- 1b. Contact methods. A brand-new client has neither yet, so each is the primary of its kind. A
          -- value that collides org-wide (including with a still-restorable soft-deleted client -- which the
          -- Review dry-run cannot see) raises unique_violation and is handled below as a friendly per-row
          -- failure.
          if email_value is not null then
            insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
            values (row_rec.organization_id, new_client_id, 'email', email_value, true);
          end if;
          if phone_value is not null then
            insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
            values (row_rec.organization_id, new_client_id, 'phone', phone_value, true);
          end if;

          -- 1c. First property (the before-insert trigger makes the first non-deleted property primary).
          if property_payload is not null and jsonb_typeof(property_payload) = 'object' then
            insert into public.properties (
              organization_id, client_id, label, address_line1, address_line2, city, state_region,
              postal_code, country
            )
            values (
              row_rec.organization_id, new_client_id,
              coalesce(nullif(trim(property_payload ->> 'label'), ''), 'Primary property'),
              property_payload ->> 'address_line1',
              nullif(trim(property_payload ->> 'address_line2'), ''),
              property_payload ->> 'city',
              nullif(trim(property_payload ->> 'state_region'), ''),
              nullif(trim(property_payload ->> 'postal_code'), ''),
              coalesce(nullif(property_payload ->> 'country', ''), 'US')
            );
          end if;

        elsif row_rec.planned_action = 'update' then
          new_client_id := row_rec.match_client_id;

          -- 1a. Only the fields Review decided to change are present in client_payload (it never writes a
          -- null to clear a field), so coalesce keeps the existing value for every absent key.
          update public.clients set
            first_name = coalesce(client_payload ->> 'first_name', first_name),
            last_name = coalesce(client_payload ->> 'last_name', last_name),
            company_name = coalesce(client_payload ->> 'company_name', company_name),
            lead_source = coalesce(client_payload ->> 'lead_source', lead_source),
            display_name = coalesce(client_payload ->> 'display_name', display_name)
          where id = new_client_id and organization_id = row_rec.organization_id;

          -- 1b. Contact methods are added only when Review put them here (the client lacked that kind or a
          -- toggle allowed it, and the value is new org-wide). Primary only if the client has none of that
          -- kind yet, so we never create a second primary. A collision is caught below.
          if email_value is not null then
            insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
            values (
              row_rec.organization_id, new_client_id, 'email', email_value,
              not exists (
                select 1 from public.client_contact_methods
                where client_id = new_client_id and kind = 'email'
              )
            );
          end if;
          if phone_value is not null then
            insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
            values (
              row_rec.organization_id, new_client_id, 'phone', phone_value,
              not exists (
                select 1 from public.client_contact_methods
                where client_id = new_client_id and kind = 'phone'
              )
            );
          end if;

          -- 1c. A property is added only when Review put one here (client had none, or the toggle allowed
          -- it).
          if property_payload is not null and jsonb_typeof(property_payload) = 'object' then
            insert into public.properties (
              organization_id, client_id, label, address_line1, address_line2, city, state_region,
              postal_code, country
            )
            values (
              row_rec.organization_id, new_client_id,
              coalesce(nullif(trim(property_payload ->> 'label'), ''), 'Primary property'),
              property_payload ->> 'address_line1',
              nullif(trim(property_payload ->> 'address_line2'), ''),
              property_payload ->> 'city',
              nullif(trim(property_payload ->> 'state_region'), ''),
              nullif(trim(property_payload ->> 'postal_code'), ''),
              coalesce(nullif(property_payload ->> 'country', ''), 'US')
            );
          end if;
        else
          -- Only create/update rows are ever 'ready'; anything else is a contract breach, not a data error.
          raise exception 'A ready import row had an unexpected action: %', row_rec.planned_action
            using errcode = 'check_violation';
        end if;

        -- 1d. The note is additive on both client paths, attributed to the office member who ran the import.
        -- Opening-balance rows never carry a client payload, so note_value is null for them and this never
        -- fires.
        if note_value is not null then
          insert into public.notes (organization_id, body, created_by)
          values (row_rec.organization_id, note_value, batch_rec.created_by)
          returning id into new_note_id;

          insert into public.note_links (organization_id, note_id, entity_type, entity_id)
          values (row_rec.organization_id, new_note_id, 'client', new_client_id);
        end if;

      elsif batch_rec.entity_type = 'opening_balance' then
        if row_rec.planned_action = 'create' then
          -- A fresh fact. The set-root trigger points root_opening_balance_id at the new row's own id.
          insert into public.client_opening_balances (
            organization_id, client_id, balance_type, amount_minor, currency_code, as_of_date, source_note,
            import_batch_id, import_row_id, created_by
          )
          values (
            row_rec.organization_id,
            (row_rec.resolved_payload ->> 'client_id')::uuid,
            row_rec.resolved_payload ->> 'balance_type',
            (row_rec.resolved_payload ->> 'amount_minor')::bigint,
            row_rec.resolved_payload ->> 'currency_code',
            (row_rec.resolved_payload ->> 'as_of_date')::date,
            nullif(trim(row_rec.resolved_payload ->> 'source_note'), ''),
            row_rec.batch_id, row_rec.id, batch_rec.created_by
          )
          returning id into new_client_id;

        elsif row_rec.planned_action = 'update' then
          -- A correction: lock the fact it replaces, insert the new fact carrying that fact's root, then mark
          -- the old one replaced. Never edits or deletes the old fact's own data (contract).
          ob_predecessor_id := (row_rec.resolved_payload ->> 'predecessor_opening_balance_id')::uuid;

          select * into ob_predecessor
          from public.client_opening_balances
          where id = ob_predecessor_id and organization_id = row_rec.organization_id
          for update;

          if not found then
            raise exception 'The opening balance fact this row corrects no longer exists.'
              using errcode = 'foreign_key_violation';
          end if;
          if ob_predecessor.replaced_at is not null then
            raise exception 'The opening balance fact this row corrects has already been replaced.'
              using errcode = 'check_violation';
          end if;
          ob_root_id := ob_predecessor.root_opening_balance_id;

          insert into public.client_opening_balances (
            organization_id, client_id, balance_type, amount_minor, currency_code, as_of_date, source_note,
            predecessor_opening_balance_id, root_opening_balance_id, import_batch_id, import_row_id, created_by
          )
          values (
            row_rec.organization_id,
            (row_rec.resolved_payload ->> 'client_id')::uuid,
            row_rec.resolved_payload ->> 'balance_type',
            (row_rec.resolved_payload ->> 'amount_minor')::bigint,
            row_rec.resolved_payload ->> 'currency_code',
            (row_rec.resolved_payload ->> 'as_of_date')::date,
            nullif(trim(row_rec.resolved_payload ->> 'source_note'), ''),
            ob_predecessor_id, ob_root_id,
            row_rec.batch_id, row_rec.id, batch_rec.created_by
          )
          returning id into new_client_id;

          update public.client_opening_balances
          set replaced_at = now(), replaced_by_opening_balance_id = new_client_id
          where id = ob_predecessor_id;
        else
          raise exception 'A ready import row had an unexpected action: %', row_rec.planned_action
            using errcode = 'check_violation';
        end if;

      else
        -- A contract breach (a batch entity_type the worker was never taught), not a data error.
        raise exception 'process_next_import_row does not know entity_type %', batch_rec.entity_type
          using errcode = 'check_violation';
      end if;

      -- 1e. Record the success: bump the batch's running count and mark the row imported. Names are generic
      -- across entity types: 'create' produced a brand-new row, 'update' corrected/changed an existing one.
      if row_rec.planned_action = 'create' then
        update public.import_batches set created_count = created_count + 1 where id = row_rec.batch_id;
      else
        update public.import_batches set updated_count = updated_count + 1 where id = row_rec.batch_id;
      end if;

      update public.import_rows
      set status = 'imported', result_client_id = new_client_id, processed_at = now()
      where id = row_rec.id;

      return jsonb_build_object(
        'status', 'processed', 'row_id', row_rec.id, 'batch_id', row_rec.batch_id,
        'action', row_rec.planned_action, 'client_id', new_client_id
      );
    exception
      when unique_violation then
        -- The one genuinely expected Client-import failure: the row's email/phone collides org-wide, usually
        -- with a client sitting in Recently Deleted that the Review dry-run could not see. Opening-balance
        -- rows have no unique constraint that can fire here; they fall through to "when others" instead.
        update public.import_rows
        set status = 'failed', processed_at = now(),
          error_message = 'This contact''s email or phone already belongs to another client in your account '
            || '(possibly one you deleted), so it was not imported.'
        where id = row_rec.id;
        update public.import_batches set error_count = error_count + 1 where id = row_rec.batch_id;
        return jsonb_build_object(
          'status', 'failed', 'row_id', row_rec.id, 'batch_id', row_rec.batch_id, 'error', 'duplicate_contact'
        );
      when others then
        update public.import_rows
        set status = 'failed', processed_at = now(), error_message = left(sqlerrm, 500)
        where id = row_rec.id;
        update public.import_batches set error_count = error_count + 1 where id = row_rec.batch_id;
        return jsonb_build_object(
          'status', 'failed', 'row_id', row_rec.id, 'batch_id', row_rec.batch_id, 'error', sqlerrm
        );
    end;
  end if;

  -- 2. No claimable ready row. Finalize one 'importing' batch whose queue is fully drained (no ready rows
  -- left, committed). SKIP LOCKED so two wakes cannot both finalize the same batch; the NOT EXISTS check reads
  -- committed state, so a row still being written by another wake (locked, status still 'ready') correctly
  -- keeps its batch out of this until it commits.
  select * into final_batch
  from public.import_batches
  where status = 'importing'
    and not exists (
      select 1 from public.import_rows r
      where r.batch_id = public.import_batches.id and r.status = 'ready'
    )
  order by created_at
  for update skip locked
  limit 1;

  if found then
    update public.import_batches set status = 'completed' where id = final_batch.id
    returning * into final_batch;
    return jsonb_build_object(
      'status', 'batch_completed', 'batch_id', final_batch.id,
      'organization_id', final_batch.organization_id,
      'error_count', final_batch.error_count, 'held_count', final_batch.held_count
    );
  end if;

  return jsonb_build_object('status', 'idle');
end;
$$;


ALTER FUNCTION "public"."process_next_import_row"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_next_import_row"() IS 'The shared assisted-import worker''s one entry point, for every entity_type the pipeline carries. Claims the oldest ready import_rows row across all batches (for update skip locked on import_rows_ready_idx), then branches on the row''s batch entity_type: ''client'' writes/updates public.clients (create_client is security-invoker/auth.uid; this worker runs as service_role); ''opening_balance'' inserts a public.client_opening_balances fact, or -- for a correction (planned_action=''update'') -- inserts the corrected fact and marks the predecessor replaced, in one transaction. Maintains the batch''s created/updated/error counts and records the row imported or failed -- never raising, so one bad row cannot wedge the queue. When no ready row is claimable it finalizes one fully-drained importing batch to completed. Returns {status: idle} when there is nothing to claim or finalize. (SECURITY DEFINER; service_role only.)';



CREATE OR REPLACE FUNCTION "public"."provision_organization_from_application"("target_application_id" "uuid", "target_organization_id" "uuid", "target_organization_name" "text", "target_slug" "text", "target_administrator_user_id" "uuid", "target_administrator_role" "text" DEFAULT 'owner'::"text", "target_actor_owner_email" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  app_stage text;
  app_payment_reversed_at timestamptz;
  app_package_version_id uuid;
  app_time_zone text;
  version_status text;
  package_status text;
  payment record;
  paid_through date;
begin
  if target_organization_name is null or char_length(trim(target_organization_name)) = 0 then
    raise exception 'An organization name is required for provisioning.' using errcode = 'check_violation';
  end if;
  if target_slug is null or char_length(trim(target_slug)) = 0 then
    raise exception 'An organization slug is required for provisioning.' using errcode = 'check_violation';
  end if;
  if target_actor_owner_email is null or char_length(trim(target_actor_owner_email)) = 0 then
    raise exception 'An acting owner email is required for provisioning.' using errcode = 'check_violation';
  end if;

  select stage, payment_reversed_at, package_version_id, time_zone
  into app_stage, app_payment_reversed_at, app_package_version_id, app_time_zone
  from public.platform_onboarding_applications
  where id = target_application_id
  for update;

  if not found then
    raise exception 'The onboarding application does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if app_stage not in ('payment_confirmed', 'needs_attention') then
    raise exception 'This application is not ready for provisioning.' using errcode = 'check_violation';
  end if;
  if app_payment_reversed_at is not null then
    raise exception 'The payment for this application was reversed. Confirm payment again before provisioning.'
      using errcode = 'check_violation';
  end if;

  select version.status, package.status
  into version_status, package_status
  from public.platform_package_versions as version
  join public.platform_packages as package on package.package_id = version.package_id
  where version.id = app_package_version_id;

  if version_status is null or package_status is null then
    raise exception 'The activated package version does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if version_status = 'draft' or package_status = 'draft' then
    raise exception 'The activated package version was never published.' using errcode = 'check_violation';
  end if;

  select amount_usd_cents, currency, private_reference, confirmed_at, mismatch_reason
  into payment
  from public.platform_onboarding_application_payment_confirmations
  where application_id = target_application_id
  order by confirmed_at desc
  limit 1;

  if not found then
    raise exception 'Payment must be confirmed before provisioning.' using errcode = 'check_violation';
  end if;

  paid_through := (payment.confirmed_at::date + interval '1 month')::date;

  insert into public.organizations (id, name, slug, lifecycle_status)
  values (target_organization_id, trim(target_organization_name), target_slug, 'active');

  insert into public.organization_package_assignments (
    organization_id, package_version_id, assignment_source, reason
  ) values (
    target_organization_id, app_package_version_id, 'provisioning',
    'Initial provisioning from paid onboarding application.'
  );

  update public.organization_settings
  set timezone = coalesce(nullif(trim(app_time_zone), ''), timezone)
  where organization_id = target_organization_id;

  perform public.apply_organization_commercial_command(
    target_organization_id => target_organization_id,
    event_kind => 'initial_payment_confirmed',
    idempotency_key => 'application:' || target_application_id::text || ':initial_payment',
    summary => 'Initial payment confirmed during provisioning.',
    paid_through_effect => 'set',
    paid_through_date => paid_through,
    actor_owner_email => target_actor_owner_email,
    occurred_at => payment.confirmed_at,
    private_reason => payment.mismatch_reason,
    private_reference => payment.private_reference,
    amount_usd_cents => payment.amount_usd_cents,
    safe_kind => 'payment_recorded',
    safe_payload => jsonb_build_object('paid_through_date', paid_through)
  );

  insert into public.organization_members (organization_id, user_id, role)
  values (target_organization_id, target_administrator_user_id, target_administrator_role);

  update public.platform_onboarding_applications
  set stage = 'account_created'
  where id = target_application_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, after_state
  ) values (
    target_actor_owner_email, 'onboarding_application.provisioned', 'organization',
    target_organization_id::text, jsonb_build_object('application_id', target_application_id)
  );

  return target_organization_id;
end;
$$;


ALTER FUNCTION "public"."provision_organization_from_application"("target_application_id" "uuid", "target_organization_id" "uuid", "target_organization_name" "text", "target_slug" "text", "target_administrator_user_id" "uuid", "target_administrator_role" "text", "target_actor_owner_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_form_draft"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  form_row public.forms;
  draft_row public.form_versions;
begin
  if not private.has_permission(target_organization_id, 'settings.forms.manage') then
    raise exception 'You do not have access to manage forms.' using errcode = 'insufficient_privilege';
  end if;

  select * into form_row from public.forms
  where id = target_form_id and organization_id = target_organization_id
  for update;
  if form_row.id is null then
    raise exception 'That form was not found.' using errcode = 'check_violation';
  end if;
  if form_row.archived_at is not null then
    raise exception 'An archived form cannot be published. Restore it first.'
      using errcode = 'check_violation';
  end if;
  if form_row.draft_version_id is null then
    raise exception 'This form has no draft to publish.' using errcode = 'check_violation';
  end if;

  select * into draft_row from public.form_versions
  where id = form_row.draft_version_id and organization_id = target_organization_id
  for update;

  if expected_revision is distinct from draft_row.revision then
    raise exception 'Someone else changed this draft while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  update public.form_versions
  set status = 'published', published_at = now(),
      updated_by = (select auth.uid()), updated_at = now()
  where id = draft_row.id
  returning * into draft_row;

  update public.forms
  set current_published_version_id = draft_row.id, draft_version_id = null,
      updated_by = (select auth.uid()), updated_at = now()
  where id = form_row.id;

  return jsonb_build_object(
    'form_id', form_row.id, 'published_version_id', draft_row.id,
    'version_number', draft_row.version_number, 'published_at', draft_row.published_at
  );
end;
$$;


ALTER FUNCTION "public"."publish_form_draft"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."platform_message_templates" (
    "template_key" "text" NOT NULL,
    "subject_draft" "text",
    "body_draft" "text" DEFAULT ''::"text" NOT NULL,
    "subject_published" "text",
    "body_published" "text",
    "published_version" integer DEFAULT 0 NOT NULL,
    "published_at" timestamp with time zone,
    "published_by_owner_email" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "platform_message_templates_published_check" CHECK ((("published_version" = 0) = ("published_at" IS NULL))),
    CONSTRAINT "platform_message_templates_published_version_check" CHECK (("published_version" >= 0)),
    CONSTRAINT "platform_message_templates_template_key_check" CHECK (("template_key" = ANY (ARRAY['received_page'::"text", 'application_receipt'::"text", 'password_setup'::"text", 'account_created_contact'::"text", 'organization_closure_started'::"text", 'organization_closure_fourteen_day_reminder'::"text", 'organization_closure_three_day_reminder'::"text", 'organization_closure_completed'::"text"])))
);


ALTER TABLE "public"."platform_message_templates" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_message_template"("target_template_key" "text", "actor_email" "text") RETURNS "public"."platform_message_templates"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current record;
  next_version integer;
  updated public.platform_message_templates;
begin
  if actor_email is null or char_length(trim(actor_email)) = 0 then
    raise exception 'An acting owner email is required to publish a template.' using errcode = 'check_violation';
  end if;

  select subject_draft, body_draft, published_version
  into current
  from public.platform_message_templates
  where template_key = target_template_key
  for update;

  if not found then
    raise exception 'The message template does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if current.body_draft is null or char_length(trim(current.body_draft)) = 0 then
    raise exception 'A template cannot be published with empty content.' using errcode = 'check_violation';
  end if;

  next_version := current.published_version + 1;

  update public.platform_message_templates
  set subject_published = current.subject_draft,
    body_published = current.body_draft,
    published_version = next_version,
    published_at = now(),
    published_by_owner_email = actor_email
  where template_key = target_template_key
  returning * into updated;

  insert into public.platform_message_template_versions (
    template_key, version, subject, body, published_by_owner_email
  ) values (
    target_template_key, next_version, current.subject_draft, current.body_draft, actor_email
  );

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, after_state
  ) values (
    actor_email, 'message_template.published', 'platform_message_template', target_template_key,
    jsonb_build_object('version', next_version)
  );

  return updated;
end;
$$;


ALTER FUNCTION "public"."publish_message_template"("target_template_key" "text", "actor_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_quote"("target_quote_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  published_row public.quote_versions;
  draft_row public.quote_versions;
  priced_line_count integer;
  frozen jsonb;
begin
  select * into quote_row from public.quotes where id = target_quote_id for update;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.send'
     ) then
    raise exception 'You do not have access to send this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.status = 'awaiting_response' then
    select * into published_row from public.quote_versions
    where id = quote_row.current_published_version_id;
    if published_row.id is not null and published_row.revision = expected_revision then
      return jsonb_build_object(
        'quote_id', quote_row.id, 'quote_version_id', published_row.id,
        'version_number', published_row.version_number, 'document_hash', published_row.document_hash,
        'sent_at', quote_row.sent_at, 'status', quote_row.status,
        'calculation', published_row.calculation, 'already_published', true
      );
    end if;
  end if;

  if quote_row.status <> 'draft' then
    raise exception 'Only a draft quote can be sent.' using errcode = 'check_violation';
  end if;

  select * into draft_row from public.quote_versions
  where organization_id = quote_row.organization_id and quote_id = quote_row.id and status = 'draft'
  for update;

  if draft_row.id is null then
    raise exception 'This quote has no draft to send.' using errcode = 'check_violation';
  end if;
  if expected_revision is distinct from draft_row.revision then
    raise exception 'Someone else changed this quote while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  -- A quote with nothing on it is not a proposal. Everything else the document needs was already required
  -- when the quote was created: a client, a property, a title, and a number.
  -- Named quote first, then version: that is the order quote_version_lines_version_idx is built in, and
  -- leaving quote_id out would drop the count to an organization-wide scan of every line ever quoted.
  select count(*) into priced_line_count
  from public.quote_version_lines
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and quote_version_id = draft_row.id
    and line_kind = 'priced';
  if priced_line_count = 0 then
    raise exception 'Add at least one line before sending this quote.' using errcode = 'check_violation';
  end if;

  -- Priced work needs a real tax answer before a customer sees it. "No tax" is a legitimate answer;
  -- nobody having looked at it yet is not.
  if draft_row.tax_source = 'not_configured' then
    raise exception 'Choose a tax rate or confirm No tax in Settings -> Taxes before sending this quote.'
      using errcode = 'check_violation';
  end if;

  -- The send date is stamped before the freeze, not after. quotes_publication_is_dated is a plain check
  -- constraint, so Postgres tests it the moment freeze points the quote at its new publication - stamping
  -- afterwards would fail on a row that is only half updated. Caught by the Part 5A database test.
  update public.quotes set sent_at = coalesce(sent_at, now()) where id = quote_row.id;

  frozen := public.freeze_quote_version(quote_row.id, expected_revision);

  update public.quotes
  set status = 'awaiting_response',
      decision = null, decided_at = null, decision_method = null,
      decision_note = null, decided_by = null
  where id = quote_row.id
  returning * into quote_row;

  insert into public.activity_events (
    organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
  ) values (
    quote_row.organization_id, 'quote', quote_row.id, 'quote.published',
    'Sent version ' || (frozen ->> 'version_number') || ' to the customer',
    (select auth.uid()),
    jsonb_build_object(
      'quote_version_id', frozen ->> 'quote_version_id',
      'version_number', (frozen ->> 'version_number')::integer
    )
  );

  return frozen
    || jsonb_build_object('sent_at', quote_row.sent_at, 'status', quote_row.status,
                          'already_published', false);
end;
$$;


ALTER FUNCTION "public"."publish_quote"("target_quote_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_website_chat_message_to_visitor"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  live_topic text;
begin
  select g.channel_topic into live_topic
  from public.website_chat_realtime_grants g
  where g.session_id = new.session_id
    and g.expires_at > now();

  if live_topic is not null then
    begin
      perform realtime.send(
        jsonb_build_object(
          'id', new.id,
          'direction', new.direction,
          'sender_type', new.sender_type,
          'body', new.body,
          'created_at', new.created_at
        ),
        'website_chat_message',
        live_topic,
        true
      );
    exception
      when others then
        null;
    end;
  end if;

  begin
    perform realtime.send(
      jsonb_build_object(
        'session_id', new.session_id,
        'message_id', new.id,
        'client_id', new.client_id
      ),
      'website_chat_activity',
      'wc-org:' || new.organization_id::text,
      true
    );
  exception
    when others then
      null;
  end;

  return null;
end;
$$;


ALTER FUNCTION "public"."publish_website_chat_message_to_visitor"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."publish_website_chat_message_to_visitor"() IS 'Broadcasts a new Website Chat message twice: the full payload to that session''s own private visitor topic when it has a live grant, and ids only to the organization''s staff topic so an open Conversations page re-reads. Best effort on both: a publish failure never fails the message.';



CREATE OR REPLACE FUNCTION "public"."quarantine_stale_communication_claims"("batch_size" integer DEFAULT 50, "stale_after" interval DEFAULT '00:15:00'::interval) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare quarantined_count integer;
begin
  if batch_size < 1 or batch_size > 100 then
    raise exception 'The stale communication batch is outside its safe bounds.' using errcode = 'check_violation';
  end if;
  if stale_after < interval '1 minute' or stale_after > interval '1 day' then
    raise exception 'The stale communication threshold is outside its safe bounds.' using errcode = 'check_violation';
  end if;
  with stale as (
    select id from public.communication_outbox_events where channel = 'email' and status = 'processing' and claimed_at <= now() - stale_after
    order by claimed_at, id limit batch_size for update skip locked
  ), quarantined as (
    update public.communication_outbox_events event set status = 'submission_unknown', finalized_claim_token = event.claim_token,
      claimed_at = null, claim_token = null, last_error = 'The worker lease expired before its provider outcome was recorded.'
    from stale where event.id = stale.id returning event.delivery_intent_id
  ), updated_reservations as (
    update public.communication_email_capacity_reservations reservation set reservation_state = 'submission_unknown', settled_at = now()
    from quarantined where reservation.delivery_intent_id = quarantined.delivery_intent_id
      and reservation.reservation_state = 'reserved' returning reservation.delivery_intent_id
  ), updated_intents as (
    update public.communication_delivery_intents intent set status = 'submission_unknown', failure_code = 'worker_lease_expired',
      failure_message = 'The worker lease expired before its provider outcome was recorded.'
    from quarantined where intent.id = quarantined.delivery_intent_id returning intent.id
  ) select count(*)::integer into quarantined_count from updated_intents;
  return quarantined_count;
end;
$$;


ALTER FUNCTION "public"."quarantine_stale_communication_claims"("batch_size" integer, "stale_after" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quarantine_stale_communication_forward_claims"("batch_size" integer DEFAULT 50, "stale_after" interval DEFAULT '00:15:00'::interval) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quarantined_count integer;
begin
  if batch_size < 1 or batch_size > 100 then
    raise exception 'The stale forward batch is outside its safe bounds.' using errcode = 'check_violation';
  end if;
  if stale_after < interval '1 minute' or stale_after > interval '1 day' then
    raise exception 'The stale forward threshold is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  with stale as (
    select id from public.communication_forward_events
    where status = 'claimed' and claimed_at <= now() - stale_after
    order by claimed_at, id
    limit batch_size
    for update skip locked
  )
  update public.communication_forward_events event
  set status = 'submission_unknown', finalized_claim_token = event.claim_token,
    claimed_at = null, claim_token = null,
    last_error = 'The worker lease expired before its provider outcome was recorded.'
  from stale
  where event.id = stale.id;
  get diagnostics quarantined_count = row_count;

  return quarantined_count;
end;
$$;


ALTER FUNCTION "public"."quarantine_stale_communication_forward_claims"("batch_size" integer, "stale_after" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quarantine_stale_communication_sms_claims"("batch_size" integer DEFAULT 50, "stale_after" interval DEFAULT '00:15:00'::interval) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quarantined_count integer;
begin
  if batch_size < 1 or batch_size > 100 then
    raise exception 'The stale SMS batch is outside its safe bounds.' using errcode = 'check_violation';
  end if;
  if stale_after < interval '1 minute' or stale_after > interval '1 day' then
    raise exception 'The stale SMS threshold is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  with stale as (
    select id, delivery_intent_id, organization_id, claim_token
    from public.communication_outbox_events
    where channel = 'sms' and status = 'processing' and claimed_at <= now() - stale_after
    order by claimed_at, id
    limit batch_size
    for update skip locked
  ), quarantined as (
    update public.communication_outbox_events event
    set status = 'submission_unknown', finalized_claim_token = event.claim_token,
      claimed_at = null, claim_token = null,
      last_error = 'The worker lease expired before its provider outcome was recorded.'
    from stale
    where event.id = stale.id
    returning event.delivery_intent_id, stale.organization_id, stale.claim_token
  ), updated_intents as (
    update public.communication_delivery_intents intent
    set status = 'submission_unknown', failure_code = 'worker_lease_expired',
      failure_message = 'The worker lease expired before its provider outcome was recorded.'
    from quarantined
    where intent.id = quarantined.delivery_intent_id
    returning intent.id
  ), updated_attempts as (
    update public.communication_sms_submission_attempts attempt
    set outcome = 'submission_unknown', error_code = 'worker_lease_expired', finished_at = now()
    from quarantined
    where attempt.delivery_intent_id = quarantined.delivery_intent_id
      and attempt.claim_token = quarantined.claim_token
      and attempt.outcome = 'started'
    returning attempt.id
  ), held_reservations as (
    update public.communication_sms_credit_reservations reservation
    set state = 'submission_unknown', settled_at = now()
    from quarantined
    where reservation.delivery_intent_id = quarantined.delivery_intent_id
      and reservation.state = 'reserved'
    returning reservation.id
  ), opened_items as (
    insert into public.communication_sms_reconciliation_items (
      organization_id, delivery_intent_id, reason, last_error
    )
    select quarantined.organization_id, quarantined.delivery_intent_id, 'submission_unknown',
      'The worker lease expired before its provider outcome was recorded.'
    from quarantined
    on conflict (delivery_intent_id, reason) where status in ('open', 'processing', 'failed')
      and delivery_intent_id is not null do nothing
    returning id
  )
  select count(*)::integer into quarantined_count from updated_intents;

  return quarantined_count;
end;
$$;


ALTER FUNCTION "public"."quarantine_stale_communication_sms_claims"("batch_size" integer, "stale_after" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_access_link_state"("target_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
begin
  select * into quote_row from public.quotes where id = target_quote_id;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.view'
     ) then
    raise exception 'You do not have access to this quote.' using errcode = 'insufficient_privilege';
  end if;

  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'quote_access_link_id', link.id,
          'quote_version_id', link.quote_version_id,
          'version_number', version.version_number,
          'recipient_name', recipient.display_name,
          'recipient_email', recipient.email,
          'issued_at', link.issued_at,
          'expires_at', link.expires_at,
          'first_viewed_at', link.first_viewed_at,
          'last_viewed_at', link.last_viewed_at,
          'view_count', link.view_count,
          'is_current_version', link.quote_version_id = quote_row.current_published_version_id
        )
        order by link.issued_at desc
      )
      from public.quote_access_links as link
      join public.quote_recipients as recipient on recipient.id = link.recipient_id
      join public.quote_versions as version on version.id = link.quote_version_id
      where link.organization_id = quote_row.organization_id
        and link.quote_id = quote_row.id
        and link.revoked_at is null
    ),
    '[]'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."quote_access_link_state"("target_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_current_signature"("target_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
begin
  select * into quote_row from public.quotes where id = target_quote_id;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.view'
     ) then
    raise exception 'You do not have access to this quote.' using errcode = 'insufficient_privilege';
  end if;

  return coalesce(
    (
      select jsonb_build_object(
        'quote_signature_id', signature.id,
        'signer_name', signature.signer_name,
        'method', signature.method,
        'signed_at', signature.signed_at,
        'has_image', signature.image_object_key is not null,
        'version_number', version.version_number
      )
      from public.quote_signatures as signature
      join public.quote_decisions as decision
        on decision.id = signature.quote_decision_id
      join public.quote_versions as version
        on version.id = signature.quote_version_id
      where signature.organization_id = quote_row.organization_id
        and signature.quote_id = quote_row.id
        and decision.is_current
    ),
    'null'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."quote_current_signature"("target_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_customer_preview"("target_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  version_row public.quote_versions;
  client_name text;
  client_email text;
  can_see_price boolean;
begin
  select * into quote_row from public.quotes where id = target_quote_id;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.view'
     ) then
    raise exception 'You do not have access to this quote.' using errcode = 'insufficient_privilege';
  end if;

  select * into version_row
  from public.quote_versions
  where id = coalesce(quote_row.current_published_version_id, quote_row.draft_version_id);

  if version_row.id is null then
    return null;
  end if;

  can_see_price := private.member_has_permission(
    quote_row.organization_id, (select auth.uid()), 'quotes.view_price'
  );

  select client.display_name,
         (
           select lower(trim(method.value))
           from public.client_contact_methods as method
           where method.organization_id = quote_row.organization_id
             and method.client_id = quote_row.client_id
             and method.kind = 'email'
           order by method.is_primary desc, method.created_at
           limit 1
         )
    into client_name, client_email
  from public.clients as client
  where client.organization_id = quote_row.organization_id
    and client.id = quote_row.client_id;

  return jsonb_build_object(
    'document', private.quote_customer_document(
      quote_row,
      version_row,
      coalesce(nullif(trim(client_name), ''), client_email, 'Your client'),
      client_email,
      can_see_price
    ),
    'preview', jsonb_build_object(
      'version_status', version_row.status,
      'version_number', version_row.version_number,
      'is_current_published', coalesce(version_row.id = quote_row.current_published_version_id, false),
      'prices_withheld', not can_see_price
    )
  );
end;
$$;


ALTER FUNCTION "public"."quote_customer_preview"("target_quote_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."quote_customer_preview"("target_quote_id" "uuid") IS 'Preview as client. Returns the same customer document the token page renders, for a signed-in member with quotes.view, without creating a recipient or a link. Prices are withheld from the payload unless the member holds quotes.view_price.';



CREATE OR REPLACE FUNCTION "public"."quote_line_money"("target_version_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  org uuid;
  can_price boolean;
  can_cost boolean;
  answer jsonb;
begin
  select version.organization_id into org
  from public.quote_versions as version
  where version.id = target_version_id;

  if org is null then
    return '{}'::jsonb;
  end if;

  if not private.member_has_permission(org, caller, 'quotes.view') then
    raise exception 'You do not have access to this quote.' using errcode = 'insufficient_privilege';
  end if;

  can_price := private.member_has_permission(org, caller, 'quotes.view_price');
  can_cost := private.member_has_permission(org, caller, 'quotes.view_cost');
  if not can_price and not can_cost then
    return '{}'::jsonb;
  end if;

  select coalesce(jsonb_object_agg(line.id::text,
      (case when can_price then jsonb_build_object(
         'unit_price_minor', line.unit_price_minor,
         'line_total_minor', line.line_total_minor
       ) else '{}'::jsonb end)
      ||
      (case when can_cost then jsonb_build_object(
         'unit_cost_minor', line.unit_cost_minor,
         'line_cost_total_minor', line.line_cost_total_minor
       ) else '{}'::jsonb end)
    ), '{}'::jsonb)
  into answer
  from public.quote_version_lines as line
  where line.organization_id = org
    and line.quote_version_id = target_version_id;

  return answer;
end;
$$;


ALTER FUNCTION "public"."quote_line_money"("target_version_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."quote_line_money"("target_version_id" "uuid") IS 'Money for one quote version''s lines, keyed by line id. Prices need quotes.view_price and cost needs quotes.view_cost; a reader holding neither gets an empty object.';



CREATE OR REPLACE FUNCTION "public"."quote_online_deposit_context"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  link_row public.quote_access_links;
  quote_row public.quotes;
  version_row public.quote_versions;
  settings_row public.organization_settings;
  connection_row public.payment_stripe_connections;
  lifecycle text;
  satisfied boolean;
  unavailable text;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row from public.quote_access_links where token_hash = supplied_token_hash;
  if link_row.id is null
     or link_row.revoked_at is not null
     or (link_row.expires_at is not null and link_row.expires_at <= now()) then
    return null;
  end if;

  select * into quote_row from public.quotes where id = link_row.quote_id;
  if quote_row.id is null
     or quote_row.status = 'archived'
     or quote_row.current_published_version_id is distinct from link_row.quote_version_id then
    return null;
  end if;

  select * into version_row from public.quote_versions where id = link_row.quote_version_id;
  if version_row.id is null or version_row.status <> 'published' then
    return null;
  end if;

  select organization.lifecycle_status into lifecycle
  from public.organizations as organization where organization.id = quote_row.organization_id;
  select * into settings_row
  from public.organization_settings where organization_id = quote_row.organization_id;
  select * into connection_row
  from public.payment_stripe_connections where organization_id = quote_row.organization_id;

  satisfied := exists (
    select 1 from public.quote_deposit_events received
    where received.organization_id = version_row.organization_id
      and received.quote_id = version_row.quote_id
      and received.quote_version_id = version_row.id
      and received.event_type = 'received'
      and not exists (
        select 1 from public.quote_deposit_events reversal
        where reversal.organization_id = received.organization_id
          and reversal.reversed_event_id = received.id
      )
  );

  unavailable := case
    when lifecycle is distinct from 'active' then 'business_unavailable'
    when connection_row.id is null then 'not_connected'
    when not settings_row.online_deposit_payments_enabled then 'turned_off'
    when quote_row.status <> 'approved' then 'not_approved'
    when version_row.deposit_type is null or version_row.deposit_required_minor <= 0 then 'no_deposit'
    when satisfied then 'already_paid'
  end;

  return jsonb_build_object(
    'organization_id', quote_row.organization_id,
    'quote_id', quote_row.id,
    'quote_version_id', version_row.id,
    'client_id', quote_row.client_id,
    'quote_number', quote_row.quote_number,
    'currency_code', version_row.currency_code,
    'available', unavailable is null,
    'unavailable_reason', unavailable,
    'deposit_required_minor', coalesce(version_row.deposit_required_minor, 0),
    'livemode', connection_row.livemode,
    'stripe_account_id', connection_row.stripe_account_id,
    'pay_by_app', jsonb_build_object(
      'venmo_username', settings_row.pay_by_app_venmo_username,
      'cash_app_cashtag', settings_row.pay_by_app_cash_app_cashtag,
      'paypal_me_username', settings_row.pay_by_app_paypal_me_username,
      'zelle_contact', settings_row.pay_by_app_zelle_contact,
      'e_transfer_email', settings_row.pay_by_app_e_transfer_email,
      'bank_transfer_instructions', settings_row.pay_by_app_bank_transfer_instructions
    )
  );
end;
$$;


ALTER FUNCTION "public"."quote_online_deposit_context"("supplied_token_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_preview_logo_object_key"("target_quote_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  version_row public.quote_versions;
begin
  select * into quote_row from public.quotes where id = target_quote_id;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.view'
     ) then
    raise exception 'You do not have access to this quote.' using errcode = 'insufficient_privilege';
  end if;

  select * into version_row
  from public.quote_versions
  where id = coalesce(quote_row.current_published_version_id, quote_row.draft_version_id);

  if version_row.id is null then
    return null;
  end if;

  return version_row.logo_object_key;
end;
$$;


ALTER FUNCTION "public"."quote_preview_logo_object_key"("target_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_ready_for_job"("target_quote_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  version_row public.quote_versions;
begin
  select * into quote_row from public.quotes where id = target_quote_id;
  if quote_row.id is null or not private.member_has_permission(
    quote_row.organization_id, (select auth.uid()), 'quotes.view'
  ) then
    raise exception 'You do not have access to this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.status <> 'approved' or quote_row.current_published_version_id is null then
    return false;
  end if;

  select * into version_row
  from public.quote_versions
  where organization_id = quote_row.organization_id and id = quote_row.current_published_version_id;

  if version_row.deposit_type is null or version_row.deposit_required_minor <= 0 then
    return true;
  end if;

  return exists (
    select 1 from public.quote_deposit_events received
    where received.organization_id = version_row.organization_id
      and received.quote_id = version_row.quote_id
      and received.quote_version_id = version_row.id
      and received.event_type = 'received'
      and not exists (
        select 1 from public.quote_deposit_events reversal
        where reversal.organization_id = received.organization_id
          and reversal.reversed_event_id = received.id
      )
  );
end;
$$;


