CREATE OR REPLACE FUNCTION "public"."quote_version_money"("target_version_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  organizations uuid[];
  org uuid;
  can_price boolean;
  can_cost boolean;
  answer jsonb;
begin
  if target_version_ids is null or cardinality(target_version_ids) = 0 then
    return '{}'::jsonb;
  end if;

  select array_agg(distinct version.organization_id) into organizations
  from public.quote_versions as version
  where version.id = any(target_version_ids);

  if organizations is null then
    return '{}'::jsonb;
  end if;
  if array_length(organizations, 1) > 1 then
    raise exception 'Those quote versions do not belong to one organization.'
      using errcode = 'check_violation';
  end if;
  org := organizations[1];

  if not private.member_has_permission(org, caller, 'quotes.view') then
    raise exception 'You do not have access to these quotes.' using errcode = 'insufficient_privilege';
  end if;

  can_price := private.member_has_permission(org, caller, 'quotes.view_price');
  can_cost := private.member_has_permission(org, caller, 'quotes.view_cost');
  if not can_price and not can_cost then
    return '{}'::jsonb;
  end if;

  select coalesce(jsonb_object_agg(version.id::text,
      (case when can_price then jsonb_build_object(
         'subtotal_minor', version.subtotal_minor,
         'discount_value', version.discount_value,
         'discount_minor', version.discount_minor,
         'tax_minor', version.tax_minor,
         'total_minor', version.total_minor,
         'deposit_required_minor', version.deposit_required_minor
       ) else '{}'::jsonb end)
      ||
      (case when can_cost then jsonb_build_object(
         'cost_minor', version.cost_minor,
         'profit_minor', version.profit_minor,
         'margin_basis_points', version.margin_basis_points,
         'calculation', version.calculation
       ) else '{}'::jsonb end)
    ), '{}'::jsonb)
  into answer
  from public.quote_versions as version
  where version.organization_id = org
    and version.id = any(target_version_ids);

  return answer;
end;
$$;


ALTER FUNCTION "public"."quote_version_money"("target_version_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."quote_version_money"("target_version_ids" "uuid"[]) IS 'Money for a set of quote versions, keyed by version id. Prices need quotes.view_price and cost, profit and margin need quotes.view_cost; a reader holding neither gets an empty object.';



CREATE OR REPLACE FUNCTION "public"."ready_to_bill_count"("target_organization_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  today date;
  total integer;
begin
  if caller is null
    or not private.member_has_permission(target_organization_id, caller, 'invoices.create')
    or not private.member_has_permission(target_organization_id, caller, 'jobs.view_price')
  then
    return 0;
  end if;

  today := private.organization_today(target_organization_id);

  select count(distinct reminder.job_id)::integer into total
  from public.job_invoice_reminders as reminder
  where reminder.organization_id = target_organization_id
    and reminder.status = 'pending'
    and reminder.due_on <= today;

  return coalesce(total, 0);
end;
$$;


ALTER FUNCTION "public"."ready_to_bill_count"("target_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ready_to_bill_count"("target_organization_id" "uuid") IS 'How many jobs owe an invoice today, counted over the same predicate ready_to_bill_page lists. Returns 0 rather than refusing when the caller may not bill, so the entry point can simply not appear.';



CREATE OR REPLACE FUNCTION "public"."ready_to_bill_page"("target_organization_id" "uuid", "search_like" "text" DEFAULT NULL::"text", "search_number" bigint DEFAULT NULL::bigint, "cursor_due_on" "date" DEFAULT NULL::"date", "cursor_reminder_id" "uuid" DEFAULT NULL::"uuid", "page_limit" integer DEFAULT 25) RETURNS TABLE("job_id" "uuid", "job_number" integer, "title" "text", "job_type" "text", "price_basis" "text", "billing_timing" "text", "currency_code" "text", "oldest_due_on" "date", "cursor_reminder" "uuid", "due_reminder_count" integer, "unit_kind" "text", "unit_count" integer, "uninvoiced_minor" bigint, "client_id" "uuid", "client_display_name" "text", "client_company_name" "text", "property_label" "text", "property_address_line1" "text", "property_city" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  today date;
begin
  if caller is null then
    raise exception 'You must be signed in to see what is ready to bill.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.create') then
    raise exception 'You do not have access to bill work here.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.view_price') then
    raise exception 'You do not have access to job prices, so there is nothing to compare here.'
      using errcode = 'insufficient_privilege';
  end if;

  if page_limit is null or page_limit < 1 or page_limit > 50 then
    page_limit := 25;
  end if;
  today := private.organization_today(target_organization_id);

  return query
  with candidate as (
    select reminder.id as reminder_id, reminder.job_id, reminder.due_on
    from public.job_invoice_reminders as reminder
    where reminder.organization_id = target_organization_id
      and reminder.status = 'pending'
      and reminder.due_on <= today
      and (
        cursor_due_on is null or cursor_reminder_id is null
        or (reminder.due_on, reminder.id) > (cursor_due_on, cursor_reminder_id)
      )
      and not exists (
        select 1
        from public.job_invoice_reminders as earlier
        where earlier.organization_id = reminder.organization_id
          and earlier.job_id = reminder.job_id
          and earlier.status = 'pending'
          and earlier.due_on <= today
          and (earlier.due_on, earlier.id) < (reminder.due_on, reminder.id)
      )
      and (
        search_like is null
        or exists (
          select 1
          from public.jobs as candidate_job
          left join public.clients as candidate_client
            on candidate_client.organization_id = candidate_job.organization_id
            and candidate_client.id = candidate_job.client_id
          where candidate_job.organization_id = reminder.organization_id
            and candidate_job.id = reminder.job_id
            and (
              candidate_job.title ilike search_like
              or candidate_client.display_name ilike search_like
              or candidate_client.company_name ilike search_like
              or (search_number is not null and candidate_job.job_number = search_number)
            )
        )
      )
    order by reminder.due_on, reminder.id
    limit page_limit
  )
  select
    job.id,
    job.job_number,
    job.title,
    job.job_type,
    job.price_basis,
    job.billing_timing,
    job.currency_code,
    candidate.due_on,
    candidate.reminder_id,
    (
      select count(*)::integer
      from public.job_invoice_reminders as counted
      where counted.organization_id = job.organization_id
        and counted.job_id = job.id
        and counted.status = 'pending'
        and counted.due_on <= today
    ),
    work.unit_kind,
    work.unit_count,
    work.uninvoiced_minor,
    job.client_id,
    client.display_name,
    client.company_name,
    property.label,
    property.address_line1,
    property.city
  from candidate
  join public.jobs as job
    on job.organization_id = target_organization_id and job.id = candidate.job_id
  left join public.clients as client
    on client.organization_id = job.organization_id and client.id = job.client_id
  left join public.properties as property
    on property.organization_id = job.organization_id and property.id = job.property_id
  cross join lateral private.job_uninvoiced_work(
    job.organization_id, job.id, job.price_basis, job.subtotal_minor, job.total_minor, today
  ) as work
  order by candidate.due_on, candidate.reminder_id;
end;
$$;


ALTER FUNCTION "public"."ready_to_bill_page"("target_organization_id" "uuid", "search_like" "text", "search_number" bigint, "cursor_due_on" "date", "cursor_reminder_id" "uuid", "page_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ready_to_bill_page"("target_organization_id" "uuid", "search_like" "text", "search_number" bigint, "cursor_due_on" "date", "cursor_reminder_id" "uuid", "page_limit" integer) IS 'One keyset page of jobs that owe an invoice today -- a pending reminder whose date has arrived -- oldest first, with the amount still waiting on each. The page is selected before the amounts are computed, so the per-job work is paid for 25 times, not once per job in the organization. Definer; checks invoices.create and jobs.view_price and scopes every row to the one organization.';



CREATE OR REPLACE FUNCTION "public"."rebill_voided_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  predecessor public.invoices;
  successor public.invoices;
begin
  if caller is null then
    raise exception 'You must be signed in to rebill an invoice.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.create') then
    raise exception 'You do not have access to create an invoice here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  replayed := private.begin_invoice_command(
    target_organization_id, 'rebill_voided_invoice', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  -- Locked directly rather than through lock_invoice_for_edit, which refuses voided invoices outright. That
  -- refusal is right for every other command; this one exists precisely to act on a voided bill.
  select * into predecessor
  from public.invoices
  where organization_id = target_organization_id and id = target_invoice_id
  for update;
  if not found then
    raise exception 'That invoice could not be found.' using errcode = 'P0404';
  end if;

  if predecessor.voided_at is null then
    raise exception 'Only a voided invoice is rebilled. Correct this one instead.'
      using errcode = 'check_violation';
  end if;
  -- The unique index would catch this anyway; catching it here names the invoice instead of the index.
  if exists (
    select 1 from public.invoices as existing
    where existing.organization_id = target_organization_id
      and existing.predecessor_invoice_id = predecessor.id
  ) then
    raise exception 'This invoice has already been rebilled.' using errcode = 'unique_violation',
      hint = 'Open the invoice that replaced it.';
  end if;

  successor := private.create_chain_successor_draft(predecessor, 'rebill', caller);

  perform private.record_invoice_event(
    target_organization_id, successor.id, successor.invoice_number, successor.client_id,
    'invoice.created_as_rebill', caller, successor.revision, null,
    jsonb_build_object(
      'predecessor_invoice_id', predecessor.id,
      'predecessor_invoice_number', predecessor.invoice_number
    ),
    false, null
  );

  return private.complete_invoice_command(
    target_organization_id, 'rebill_voided_invoice', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', successor.id,
      'invoice_number', successor.invoice_number,
      'revision', successor.revision,
      'predecessor_invoice_id', predecessor.id,
      'root_invoice_id', successor.root_invoice_id,
      'replacement_kind', 'rebill'
    )
  );
end;
$$;


ALTER FUNCTION "public"."rebill_voided_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rebill_voided_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Creates the explicit replacement draft for a voided invoice, inside the same chain so the work is billed again without ever being claimed twice. The voided bill stays exactly as it is until the replacement is activated.';



CREATE OR REPLACE FUNCTION "public"."record_automation_worker_wake_dispatch"("p_worker_name" "text", "p_job_name" "text", "p_wake_correlation_id" "uuid", "p_net_request_id" bigint) RETURNS "void"
