CREATE OR REPLACE FUNCTION "public"."record_client_marketing_unsubscribe"("supplied_token_hash" "bytea", "supplied_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.client_marketing_unsubscribe_links;
  method_value text;
  business_name text;
  current_state text;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  if supplied_evidence is null or jsonb_typeof(supplied_evidence) <> 'object' then
    raise exception 'Unsubscribe evidence must be an object.' using errcode = 'check_violation';
  end if;

  select * into link_row
  from public.client_marketing_unsubscribe_links
  where token_hash = supplied_token_hash;

  if link_row.id is null then
    return null;
  end if;

  select method.value into method_value
  from public.client_contact_methods as method
  where method.organization_id = link_row.organization_id
    and method.id = link_row.client_contact_method_id;

  if method_value is null then
    return null;
  end if;

  select organization.name into business_name
  from public.organizations as organization
  where organization.id = link_row.organization_id;

  -- Locks the projected row for this address where one exists, so a repeat click cannot read a stale
  -- "still opted in" and write a second event. With no row yet there is nothing to lock, and two clicks
  -- arriving in the same instant can both insert; that costs one extra evidence row and reaches the same
  -- state, which is the right trade for an append-only ledger.
  select state into current_state
  from public.client_marketing_consent_state
  where organization_id = link_row.organization_id
    and client_contact_method_id = link_row.client_contact_method_id
  for update;

  if coalesce(current_state, 'unknown') <> 'opted_out' then
    insert into public.client_marketing_consent_events (
      organization_id, client_id, client_contact_method_id, event_kind, source, source_event_key,
      disclosure, evidence, occurred_at, created_by
    ) values (
      link_row.organization_id,
      link_row.client_id,
      link_row.client_contact_method_id,
      'opt_out',
      'unsubscribe',
      link_row.id::text || ':' || gen_random_uuid()::text,
      null,
      supplied_evidence || jsonb_build_object(
        'channel', 'unsubscribe_link',
        'unsubscribe_link_id', link_row.id
      ),
      now(),
      null
    );
  end if;

  return jsonb_build_object(
    'business_name', business_name,
    'email', method_value,
    'already_unsubscribed', coalesce(current_state, 'unknown') = 'opted_out'
  );
end;
$$;


ALTER FUNCTION "public"."record_client_marketing_unsubscribe"("supplied_token_hash" "bytea", "supplied_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_client_payment"("target_organization_id" "uuid", "target_client_id" "uuid", "new_amount_minor" bigint, "new_method" "text", "new_payment_date" "date", "new_reference" "text", "new_note" "text", "new_allocations" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  settings_row public.organization_settings;
  receipt public.client_payment_events;
  invoice_row public.invoices;
  allocation jsonb;
  allocation_amount bigint;
  allocated_total bigint := 0;
  applied jsonb := '[]'::jsonb;
  allocation_id uuid;
begin
  if caller is null then
    raise exception 'You must be signed in to record a payment.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.record_payment') then
    raise exception 'You do not have access to record payments here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  if new_amount_minor is null or new_amount_minor <= 0 then
    raise exception 'A payment amount must be more than zero.' using errcode = 'check_violation';
  end if;
  if new_method is null
     or new_method not in ('other', 'bank_transfer', 'cash', 'check', 'card_external', 'paypal') then
    raise exception 'That is not a payment method this product records.' using errcode = 'check_violation';
  end if;
  if new_allocations is not null and jsonb_typeof(new_allocations) <> 'array' then
    raise exception 'Payment allocations must be a list.' using errcode = 'check_violation';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'record_client_payment', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for share;
  if not found then
    raise exception 'That organization could not be found.' using errcode = 'P0404';
  end if;

  if not exists (
    select 1 from public.clients
    where organization_id = target_organization_id and id = target_client_id and deleted_at is null
  ) then
    raise exception 'That client could not be found.' using errcode = 'P0404';
  end if;

  insert into public.client_payment_events (
    organization_id, client_id, event_type, amount_minor, currency_code, method, payment_date,
    reference, note, actor_user_id
  ) values (
    target_organization_id, target_client_id, 'received', new_amount_minor, settings_row.currency_code,
    new_method, coalesce(new_payment_date, private.organization_today(target_organization_id)),
    nullif(trim(coalesce(new_reference, '')), ''), nullif(trim(coalesce(new_note, '')), ''), caller
  )
  returning * into receipt;

  for allocation in
    select entry.value
    from jsonb_array_elements(coalesce(new_allocations, '[]'::jsonb)) as entry(value)
    order by (entry.value->>'invoice_id')::uuid
  loop
    allocation_amount := (allocation->>'amount_minor')::bigint;
    allocated_total := allocated_total + coalesce(allocation_amount, 0);
    if allocated_total > new_amount_minor then
      raise exception 'That is more than the payment received.' using errcode = 'check_violation';
    end if;

    invoice_row := private.lock_invoice_for_payment(
      target_organization_id, (allocation->>'invoice_id')::uuid
    );
    if invoice_row.client_id <> target_client_id then
      raise exception 'That invoice belongs to a different client.' using errcode = 'check_violation';
    end if;
    if invoice_row.currency_code <> receipt.currency_code then
      raise exception 'That invoice was written in a different currency.' using errcode = 'check_violation';
    end if;

    allocation_id := private.apply_invoice_allocation(
      invoice_row, receipt.id, null, allocation_amount, caller, allocation->>'reason'
    );
    applied := applied || jsonb_build_object(
      'allocation_id', allocation_id,
      'invoice_id', invoice_row.id,
      'invoice_number', invoice_row.invoice_number,
      'amount_minor', allocation_amount
    );
  end loop;

  return private.complete_invoice_command(
    target_organization_id, 'record_client_payment', new_idempotency_key,
    jsonb_build_object(
      'payment_event_id', receipt.id,
      'client_id', receipt.client_id,
      'amount_minor', receipt.amount_minor,
      'currency_code', receipt.currency_code,
      'payment_date', receipt.payment_date,
      'allocated_minor', allocated_total,
      'credit_minor', receipt.amount_minor - allocated_total,
      'allocations', applied
    )
  );
end;
$$;


ALTER FUNCTION "public"."record_client_payment"("target_organization_id" "uuid", "target_client_id" "uuid", "new_amount_minor" bigint, "new_method" "text", "new_payment_date" "date", "new_reference" "text", "new_note" "text", "new_allocations" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_client_payment"("target_organization_id" "uuid", "target_client_id" "uuid", "new_amount_minor" bigint, "new_method" "text", "new_payment_date" "date", "new_reference" "text", "new_note" "text", "new_allocations" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Records money received from a client and, optionally, which of their bills it pays, in one transaction. Anything not allocated stays as client credit. A retry carrying the same key returns the first receipt rather than recording the money twice.';



CREATE TABLE IF NOT EXISTS "public"."communication_inbound_messages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "reply_alias_id" "uuid",
    "client_id" "uuid",
    "client_contact_method_id" "uuid",
    "sender_id" "uuid",
    "owner_user_id" "uuid",
    "provider" "text" DEFAULT 'brevo'::"text" NOT NULL,
    "provider_message_id" "text",
    "in_reply_to_provider_message_id" "text",
    "in_reply_to_intent_id" "uuid",
    "direction" "text" DEFAULT 'inbound'::"text" NOT NULL,
    "sender_email" "text",
    "sender_name" "text",
    "to_recipients" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "cc_recipients" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "subject" "text" NOT NULL,
    "html_content" "text",
    "text_content" "text" NOT NULL,
    "message_kind" "text" DEFAULT 'reply'::"text" NOT NULL,
    "review_status" "text" DEFAULT 'accepted'::"text" NOT NULL,
    "review_reason" "text",
    "automation_suppressed" boolean DEFAULT false NOT NULL,
    "loop_detected_at" timestamp with time zone,
    "attachment_count" integer DEFAULT 0 NOT NULL,
    "provider_callback_event_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "review_resolved_at" timestamp with time zone,
    "review_resolved_by" "uuid",
    "channel" "text" DEFAULT 'email'::"text" NOT NULL,
    "sender_phone" "text",
    CONSTRAINT "communication_inbound_messages_attachment_count_check" CHECK (("attachment_count" >= 0)),
    CONSTRAINT "communication_inbound_messages_channel_check" CHECK (("channel" = ANY (ARRAY['email'::"text", 'sms'::"text"]))),
    CONSTRAINT "communication_inbound_messages_channel_provider_check" CHECK (((("channel" = 'email'::"text") AND ("provider" = 'brevo'::"text")) OR (("channel" = 'sms'::"text") AND ("provider" = 'twilio'::"text")))),
    CONSTRAINT "communication_inbound_messages_channel_sender_check" CHECK (((("channel" = 'email'::"text") AND ("sender_email" IS NOT NULL)) OR (("channel" = 'sms'::"text") AND ("sender_phone" IS NOT NULL) AND (("char_length"("btrim"("sender_phone")) >= 3) AND ("char_length"("btrim"("sender_phone")) <= 20))))),
    CONSTRAINT "communication_inbound_messages_direction_check" CHECK (("direction" = 'inbound'::"text")),
    CONSTRAINT "communication_inbound_messages_message_kind_check" CHECK (("message_kind" = ANY (ARRAY['reply'::"text", 'auto_response'::"text", 'delivery_notice'::"text", 'loop_detected'::"text"]))),
    CONSTRAINT "communication_inbound_messages_resolution_complete" CHECK (((("channel" = 'email'::"text") AND ((("client_id" IS NULL) AND ("client_contact_method_id" IS NULL) AND ("sender_id" IS NULL)) OR (("client_id" IS NOT NULL) AND ("client_contact_method_id" IS NOT NULL) AND ("sender_id" IS NOT NULL)))) OR (("channel" = 'sms'::"text") AND ("sender_id" IS NULL) AND ((("client_id" IS NULL) AND ("client_contact_method_id" IS NULL)) OR (("client_id" IS NOT NULL) AND ("client_contact_method_id" IS NOT NULL)))))),
    CONSTRAINT "communication_inbound_messages_review_reason_check" CHECK (("review_reason" = ANY (ARRAY['unknown_sender'::"text", 'ambiguous_sender'::"text", 'expired_alias'::"text"]))),
    CONSTRAINT "communication_inbound_messages_review_reason_matches_status" CHECK (((("review_status" = 'accepted'::"text") AND ("review_reason" IS NULL) AND ("review_resolved_at" IS NULL)) OR (("review_status" = 'accepted'::"text") AND ("review_reason" IS NOT NULL) AND ("review_resolved_at" IS NOT NULL)) OR (("review_status" = 'pending_review'::"text") AND ("review_reason" IS NOT NULL) AND ("review_resolved_at" IS NULL)) OR (("review_status" = 'dismissed'::"text") AND ("review_reason" IS NOT NULL) AND ("review_resolved_at" IS NOT NULL)))),
    CONSTRAINT "communication_inbound_messages_review_status_check" CHECK (("review_status" = ANY (ARRAY['accepted'::"text", 'pending_review'::"text", 'dismissed'::"text"])))
);


ALTER TABLE "public"."communication_inbound_messages" OWNER TO "postgres";


COMMENT ON COLUMN "public"."communication_inbound_messages"."channel" IS 'email or sms. Determines which of sender_email/sender_phone is populated and which provider is valid.';



COMMENT ON COLUMN "public"."communication_inbound_messages"."sender_phone" IS 'Raw From number for an sms row (E.164 as Twilio sends it). Null for email.';



CREATE OR REPLACE FUNCTION "public"."record_communication_inbound_message"("target_provider_message_id" "text" DEFAULT NULL::"text", "target_in_reply_to_provider_message_id" "text" DEFAULT NULL::"text", "target_provider_callback_event_id" "uuid" DEFAULT NULL::"uuid", "target_sender_email" "text" DEFAULT NULL::"text", "target_sender_name" "text" DEFAULT NULL::"text", "target_to_recipients" "jsonb" DEFAULT NULL::"jsonb", "target_cc_recipients" "jsonb" DEFAULT NULL::"jsonb", "target_subject" "text" DEFAULT NULL::"text", "target_html_content" "text" DEFAULT NULL::"text", "target_text_content" "text" DEFAULT NULL::"text", "target_message_kind" "text" DEFAULT NULL::"text", "target_candidate_recipients" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."communication_inbound_messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  candidate jsonb;
  matched_domain public.communication_email_domains;
  resolved_organization_id uuid;
  resolved_local_part text;
  alias public.communication_reply_aliases;
  contact_method public.client_contact_methods;
  resolved_client_id uuid;
  resolved_contact_method_id uuid;
  resolved_sender_id uuid;
  resolved_reply_alias_id uuid;
  resolved_review_status text;
  resolved_review_reason text;
  resolved_in_reply_to_intent_id uuid;
  resolved_message_kind text := target_message_kind;
  recent_count integer;
  inserted_row public.communication_inbound_messages;
begin
  for candidate in select value from jsonb_array_elements(target_candidate_recipients)
  loop
    select * into matched_domain from public.communication_email_domains
    where purpose = 'receiving' and lifecycle_state = 'verified'
      and domain_name = lower(candidate ->> 'domain_name')
    limit 1;

    if matched_domain.id is not null then
      resolved_organization_id := matched_domain.organization_id;
      resolved_local_part := lower(candidate ->> 'local_part');
      exit;
    end if;
  end loop;

  if resolved_organization_id is null then
    return null;
  end if;

  select * into alias from public.communication_reply_aliases
  where receiving_domain_id = matched_domain.id and alias_local_part = resolved_local_part;

  if alias.id is null then
    resolved_review_status := 'pending_review';
    resolved_review_reason := 'unknown_sender';
  elsif alias.expires_at < now() then
    resolved_review_status := 'pending_review';
    resolved_review_reason := 'expired_alias';
  else
    select * into contact_method from public.client_contact_methods
    where organization_id = resolved_organization_id
      and client_id = alias.client_id
      and kind = 'email'
      and normalized_value = lower(target_sender_email);

    if contact_method.id is null then
      resolved_review_status := 'pending_review';
      resolved_review_reason := 'ambiguous_sender';
    else
      resolved_review_status := 'accepted';
      resolved_client_id := alias.client_id;
      resolved_contact_method_id := contact_method.id;
      resolved_sender_id := alias.sender_id;
      resolved_reply_alias_id := alias.id;
    end if;
  end if;

  if target_in_reply_to_provider_message_id is not null then
    select id into resolved_in_reply_to_intent_id from public.communication_delivery_intents
    where organization_id = resolved_organization_id
      and provider_message_id = target_in_reply_to_provider_message_id;
  end if;

  select count(*) into recent_count from public.communication_inbound_messages
  where organization_id = resolved_organization_id
    and lower(sender_email) = lower(target_sender_email)
    and subject = target_subject
    and created_at > now() - interval '10 minutes';

  if recent_count >= 3 then
    resolved_message_kind := 'loop_detected';
  end if;

  insert into public.communication_inbound_messages (
    organization_id, reply_alias_id, client_id, client_contact_method_id, sender_id,
    provider_message_id, in_reply_to_provider_message_id, in_reply_to_intent_id,
    sender_email, sender_name, to_recipients, cc_recipients, subject, html_content, text_content,
    message_kind, review_status, review_reason, automation_suppressed, loop_detected_at,
    provider_callback_event_id
  ) values (
    resolved_organization_id, resolved_reply_alias_id, resolved_client_id, resolved_contact_method_id,
    resolved_sender_id, target_provider_message_id, target_in_reply_to_provider_message_id,
    resolved_in_reply_to_intent_id, target_sender_email, target_sender_name, target_to_recipients,
    target_cc_recipients, target_subject, target_html_content, target_text_content,
    resolved_message_kind, resolved_review_status, resolved_review_reason,
    (resolved_message_kind <> 'reply') or (resolved_review_status <> 'accepted'),
    case when resolved_message_kind = 'loop_detected' then now() else null end,
    target_provider_callback_event_id
  )
  on conflict (provider, provider_message_id) where provider_message_id is not null do nothing
  returning * into inserted_row;

  if inserted_row.id is null then
    return null;
  end if;

  return inserted_row;
end;
$$;


ALTER FUNCTION "public"."record_communication_inbound_message"("target_provider_message_id" "text", "target_in_reply_to_provider_message_id" "text", "target_provider_callback_event_id" "uuid", "target_sender_email" "text", "target_sender_name" "text", "target_to_recipients" "jsonb", "target_cc_recipients" "jsonb", "target_subject" "text", "target_html_content" "text", "target_text_content" "text", "target_message_kind" "text", "target_candidate_recipients" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_communication_sms_consent_event_from_reply"("target_organization_id" "uuid", "target_provider_message_id" "text", "target_from_number" "text", "target_event_kind" "text", "target_confirmed_by_provider" boolean) RETURNS "public"."communication_sms_consent_events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  normalized_from text := nullif(regexp_replace(coalesce(target_from_number, ''), '[^0-9]', '', 'g'), '');
  method public.client_contact_methods;
  inserted_row public.communication_sms_consent_events;
begin
  if normalized_from is null or target_event_kind not in ('opt_in', 'opt_out', 'help_requested') then
    return null;
  end if;

  select cm.* into method
  from public.client_contact_methods cm
  join public.clients client
    on client.organization_id = cm.organization_id and client.id = cm.client_id
  where cm.organization_id = target_organization_id
    and cm.kind = 'phone'
    and cm.normalized_value = normalized_from
    and client.deleted_at is null;

  if method.id is null then
    return null;
  end if;

  insert into public.communication_sms_consent_events (
    organization_id, client_id, client_contact_method_id, event_kind, source, source_event_key,
    subjects, proof_method, occurred_at
  ) values (
    target_organization_id, method.client_id, method.id, target_event_kind, 'client_reply',
    target_provider_message_id || ':' || method.id,
    case when target_event_kind = 'opt_in'
      then array['service', 'work_updates', 'billing_updates']
      else null end,
    case
      when target_event_kind = 'opt_in' then 'client_reply'
      when target_confirmed_by_provider then 'provider_keyword'
      else 'client_reply'
    end,
    now()
  )
  on conflict (organization_id, source, source_event_key) do nothing
  returning * into inserted_row;

  return inserted_row;
end;
$$;


ALTER FUNCTION "public"."record_communication_sms_consent_event_from_reply"("target_organization_id" "uuid", "target_provider_message_id" "text", "target_from_number" "text", "target_event_kind" "text", "target_confirmed_by_provider" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_communication_sms_consent_event_from_reply"("target_organization_id" "uuid", "target_provider_message_id" "text", "target_from_number" "text", "target_event_kind" "text", "target_confirmed_by_provider" boolean) IS 'Records one consent evidence row for whichever client_contact_methods row matches the sending number in this organization. No match means nothing to protect, so it does nothing.';



CREATE OR REPLACE FUNCTION "public"."record_communication_sms_inbound_message"("target_organization_id" "uuid", "target_provider_message_id" "text", "target_from_number" "text", "target_body" "text", "target_num_media" integer) RETURNS "public"."communication_inbound_messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  normalized_from text := nullif(regexp_replace(coalesce(target_from_number, ''), '[^0-9]', '', 'g'), '');
  resolved_client_id uuid;
  resolved_method_id uuid;
  new_client_id uuid;
  inserted_row public.communication_inbound_messages;
begin
  if normalized_from is null then
    return null;
  end if;

  -- client_contact_methods_org_value_unique_idx (organization_id, kind, normalized_value) guarantees at
  -- most one client can hold this number in this org -- unlike Website Chat's phone+email cross-check,
  -- SMS has only one identifier, so there is no ambiguous-match case to branch on here.
  select method.id, method.client_id into resolved_method_id, resolved_client_id
  from public.client_contact_methods method
  join public.clients client
    on client.organization_id = method.organization_id and client.id = method.client_id
  where method.organization_id = target_organization_id
    and method.kind = 'phone'
    and method.normalized_value = normalized_from
    and client.deleted_at is null;

  if resolved_method_id is null then
    -- Nobody matched: a new Lead, exactly like an unmatched Website Chat visitor. Two inbound texts from
    -- the same brand-new number can race here; client_contact_methods_org_value_unique_idx (organization,
    -- kind, normalized_value) is the tiebreaker. The loser discards its own just-created Lead and attaches
    -- to whichever contact method actually won, rather than erroring the whole request.
    insert into public.clients (
      organization_id, display_name, lifecycle_status, lead_source, client_type
    ) values (
      target_organization_id, target_from_number, 'lead', 'SMS', 'person'
    ) returning id into new_client_id;

    insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
    values (target_organization_id, new_client_id, 'phone', target_from_number, true)
    on conflict (organization_id, kind, normalized_value) do nothing
    returning id into resolved_method_id;

    if resolved_method_id is null then
      select method.id, method.client_id into resolved_method_id, resolved_client_id
      from public.client_contact_methods method
      where method.organization_id = target_organization_id
        and method.kind = 'phone'
        and method.normalized_value = normalized_from;
      delete from public.clients where organization_id = target_organization_id and id = new_client_id;
    else
      resolved_client_id := new_client_id;
    end if;
  end if;

  insert into public.communication_inbound_messages (
    organization_id, channel, client_id, client_contact_method_id, provider, provider_message_id,
    sender_phone, subject, text_content, attachment_count, message_kind, review_status
  ) values (
    target_organization_id, 'sms', resolved_client_id, resolved_method_id, 'twilio', target_provider_message_id,
    target_from_number, '', coalesce(target_body, ''), coalesce(target_num_media, 0), 'reply', 'accepted'
  )
  on conflict (provider, provider_message_id) where provider_message_id is not null do nothing
  returning * into inserted_row;

  return inserted_row;
end;
$$;


ALTER FUNCTION "public"."record_communication_sms_inbound_message"("target_organization_id" "uuid", "target_provider_message_id" "text", "target_from_number" "text", "target_body" "text", "target_num_media" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_communication_sms_inbound_message"("target_organization_id" "uuid", "target_provider_message_id" "text", "target_from_number" "text", "target_body" "text", "target_num_media" integer) IS 'Resolves an inbound SMS sender by normalized number (one match, or no match creating a new Lead) and records the message. Idempotent by (provider, provider_message_id).';



CREATE OR REPLACE FUNCTION "public"."record_communication_worker_wake_dispatch"("p_worker_name" "text", "p_job_name" "text", "p_wake_correlation_id" "uuid", "p_net_request_id" bigint) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  insert into private.communication_worker_wake_ledger (
    worker_name, job_name, wake_correlation_id, net_request_id, dispatched_at
  )
  values (p_worker_name, p_job_name, p_wake_correlation_id, p_net_request_id, now())
  on conflict (wake_correlation_id) do update
    set net_request_id = excluded.net_request_id,
      job_name = coalesce(private.communication_worker_wake_ledger.job_name, excluded.job_name);
$$;


ALTER FUNCTION "public"."record_communication_worker_wake_dispatch"("p_worker_name" "text", "p_job_name" "text", "p_wake_correlation_id" "uuid", "p_net_request_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_communication_worker_wake_result"("p_worker_name" "text", "p_wake_correlation_id" "uuid", "p_started_at" timestamp with time zone, "p_finished_at" timestamp with time zone, "p_route_outcome" "text", "p_stale_claims_quarantined" integer DEFAULT NULL::integer, "p_claimed" integer DEFAULT NULL::integer, "p_submitted" integer DEFAULT NULL::integer, "p_retried" integer DEFAULT NULL::integer, "p_cancelled" integer DEFAULT NULL::integer, "p_submission_unknown" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  insert into private.communication_worker_wake_ledger (
    worker_name, wake_correlation_id, started_at, finished_at, route_outcome,
    stale_claims_quarantined, claimed, submitted, retried, cancelled, submission_unknown
  )
  values (
    p_worker_name, p_wake_correlation_id, p_started_at, p_finished_at, p_route_outcome,
    p_stale_claims_quarantined, p_claimed, p_submitted, p_retried, p_cancelled, p_submission_unknown
  )
  on conflict (wake_correlation_id) do update
    set started_at = excluded.started_at,
      finished_at = excluded.finished_at,
      route_outcome = excluded.route_outcome,
      stale_claims_quarantined = excluded.stale_claims_quarantined,
      claimed = excluded.claimed,
      submitted = excluded.submitted,
      retried = excluded.retried,
      cancelled = excluded.cancelled,
      submission_unknown = excluded.submission_unknown;
$$;


ALTER FUNCTION "public"."record_communication_worker_wake_result"("p_worker_name" "text", "p_wake_correlation_id" "uuid", "p_started_at" timestamp with time zone, "p_finished_at" timestamp with time zone, "p_route_outcome" "text", "p_stale_claims_quarantined" integer, "p_claimed" integer, "p_submitted" integer, "p_retried" integer, "p_cancelled" integer, "p_submission_unknown" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_invitation_password_set"("target_invitation_id" "uuid", "target_lease_nonce" "uuid") RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_row public.organization_member_invitations;
begin
  update public.organization_member_invitations
  set password_set_at = now()
  where id = target_invitation_id
    and state = 'accepting'
    and lease_nonce = target_lease_nonce
    and lease_expires_at > now()
  returning * into updated_row;

  if not found then
    raise exception
      'Invitation % has no open lease matching %; the password-set receipt cannot be recorded.',
      target_invitation_id, target_lease_nonce
      using errcode = 'check_violation';
  end if;

  return updated_row;
end;
$$;


ALTER FUNCTION "public"."record_invitation_password_set"("target_invitation_id" "uuid", "target_lease_nonce" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_invoice_link_view"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.invoice_access_links;
  invoice_row public.invoices;
  was_first boolean;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row from public.invoice_access_links where token_hash = supplied_token_hash;
  if link_row.id is null
     or link_row.revoked_at is not null
     or (link_row.expires_at is not null and link_row.expires_at <= now()) then
    return null;
  end if;

  select * into invoice_row from public.invoices where id = link_row.invoice_id;
  if invoice_row.id is null
     or invoice_row.issued_at is null
     or invoice_row.voided_at is not null
     or invoice_row.replaced_at is not null then
    return null;
  end if;

  was_first := link_row.first_viewed_at is null;

  update public.invoice_access_links
  set first_viewed_at = coalesce(first_viewed_at, now()),
      last_viewed_at = now(),
      view_count = view_count + 1
  where id = link_row.id;

  if was_first then
    perform private.record_invoice_event(
      invoice_row.organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
      'invoice.viewed_by_client', null, invoice_row.revision, null,
      jsonb_build_object('invoice_access_link_id', link_row.id)
    );
  end if;

  return jsonb_build_object('recorded', true, 'first_view', was_first);
end;
$$;


ALTER FUNCTION "public"."record_invoice_link_view"("supplied_token_hash" "bytea") OWNER TO "postgres";


