CREATE OR REPLACE FUNCTION "public"."record_legacy_organization_package"("target_organization_id" "uuid", "target_package_version_id" "uuid", "target_paid_through_date" "date", "target_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  version_status text;
  package_status text;
  assignment_exists boolean;
begin
  if target_paid_through_date is null then
    raise exception 'A paid-through date is required for a legacy assignment.' using errcode = 'check_violation';
  end if;

  if target_reason is null or char_length(trim(target_reason)) not between 1 and 500 then
    raise exception 'A private reason is required for a legacy assignment.' using errcode = 'check_violation';
  end if;

  perform 1 from public.organizations where id = target_organization_id;
  if not found then
    raise exception 'The organization does not exist.' using errcode = 'foreign_key_violation';
  end if;

  select version.status, package.status
  into version_status, package_status
  from public.platform_package_versions as version
  join public.platform_packages as package on package.package_id = version.package_id
  where version.id = target_package_version_id;

  if version_status is null or package_status is null then
    raise exception 'The package version does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if version_status <> 'published' or package_status <> 'published' then
    raise exception 'A legacy organization must use a published package version.' using errcode = 'check_violation';
  end if;

  select exists (
    select 1 from public.organization_package_assignments
    where organization_id = target_organization_id
  ) into assignment_exists;
  if assignment_exists then
    raise exception 'This organization already has a versioned package assignment.' using errcode = 'unique_violation';
  end if;

  insert into public.organization_package_assignments (
    organization_id, package_version_id, assignment_source, reason
  ) values (
    target_organization_id, target_package_version_id, 'legacy_owner_action', trim(target_reason)
  );

  perform public.apply_organization_commercial_command(
    target_organization_id => target_organization_id,
    event_kind => 'paid_through_adjusted',
    idempotency_key => 'legacy-package-assignment:' || target_organization_id::text,
    summary => 'Legacy paid-through baseline recorded.',
    paid_through_effect => 'set',
    paid_through_date => target_paid_through_date,
    private_reason => trim(target_reason),
    is_legacy_import => true,
    safe_kind => 'access_period_updated',
    safe_payload => jsonb_build_object('paid_through_date', target_paid_through_date)
  );
end;
$$;


ALTER FUNCTION "public"."record_legacy_organization_package"("target_organization_id" "uuid", "target_package_version_id" "uuid", "target_paid_through_date" "date", "target_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_member_identity_cleanup_step"("target_organization_id" "uuid", "target_user_id" "uuid", "target_lease_nonce" "uuid", "new_cleanup_state" "text", "cleanup_error" "text" DEFAULT NULL::"text") RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members;
begin
  select membership_row.* into membership
  from public.organization_members as membership_row
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
    and membership_row.identity_cleanup_nonce = target_lease_nonce
    and membership_row.identity_cleanup_lease_expires_at > now()
  for update;

  if not found then
    raise exception 'The identity cleanup lease is no longer valid.'
      using errcode = 'serialization_failure';
  end if;

  membership := public.mark_member_identity_revoked(
    target_organization_id, target_user_id, new_cleanup_state, cleanup_error
  );

  if new_cleanup_state = 'done' then
    update public.organization_members as membership_row
    set identity_cleanup_nonce = null,
        identity_cleanup_lease_expires_at = null
    where membership_row.organization_id = target_organization_id
      and membership_row.user_id = target_user_id
    returning membership_row.* into membership;
  end if;

  return membership;
end;
$$;


ALTER FUNCTION "public"."record_member_identity_cleanup_step"("target_organization_id" "uuid", "target_user_id" "uuid", "target_lease_nonce" "uuid", "new_cleanup_state" "text", "cleanup_error" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_member_identity_cleanup_step"("target_organization_id" "uuid", "target_user_id" "uuid", "target_lease_nonce" "uuid", "new_cleanup_state" "text", "cleanup_error" "text") IS 'Records one Auth cleanup step for the run holding the lease, and releases the lease once the cleanup is done.';



CREATE OR REPLACE FUNCTION "public"."record_quote_decision"("target_quote_id" "uuid", "new_decision" "text", "decision_note" "text" DEFAULT NULL::"text", "expected_revision" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  clean_note text;
  published_version integer;
begin
  if new_decision is null or new_decision not in ('approved', 'declined') then
    raise exception 'A decision is either approved or declined.' using errcode = 'check_violation';
  end if;
  clean_note := nullif(trim(coalesce(decision_note, '')), '');
  if clean_note is not null and char_length(clean_note) > 1000 then
    raise exception 'That note is too long.' using errcode = 'check_violation';
  end if;

  select * into quote_row from public.quotes where id = target_quote_id for update;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.record_decision'
     ) then
    raise exception 'You do not have access to answer this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.status = new_decision then
    return jsonb_build_object(
      'quote_id', quote_row.id, 'status', quote_row.status, 'decision', quote_row.decision,
      'decided_at', quote_row.decided_at, 'already_decided', true
    );
  end if;

  if quote_row.status = 'draft' then
    -- Publishing here is the point: an answer with no sent document behind it would be a decision about
    -- nothing. publish_quote does its own permission check, and send sits with decision on every seeded role.
    perform public.publish_quote(quote_row.id, expected_revision);
    select * into quote_row from public.quotes where id = quote_row.id;
  elsif quote_row.status not in ('awaiting_response', 'changes_requested') then
    raise exception 'This quote is not waiting for an answer.' using errcode = 'check_violation';
  end if;

  update public.quotes
  set status = new_decision,
      decision = new_decision,
      decided_at = now(),
      decision_method = 'offline_verbal',
      decision_note = clean_note,
      decided_by = (select auth.uid())
  where id = quote_row.id
  returning * into quote_row;

  select version_number into published_version
  from public.quote_versions where id = quote_row.current_published_version_id;

  update public.quote_decisions
  set is_current = false
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and is_current;

  insert into public.quote_decisions (
    organization_id, quote_id, quote_version_id, outcome, actor_kind, actor_user_id,
    method, note
  ) values (
    quote_row.organization_id, quote_row.id, quote_row.current_published_version_id, new_decision,
    'staff', (select auth.uid()), 'offline_verbal', clean_note
  );

  insert into public.activity_events (
    organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
  ) values (
    quote_row.organization_id, 'quote', quote_row.id, 'quote.' || new_decision,
    case new_decision
      when 'approved' then 'Recorded the customer''s approval'
      else 'Recorded that the customer declined'
    end,
    (select auth.uid()),
    jsonb_build_object('version_number', published_version, 'method', 'offline_verbal')
  );

  return jsonb_build_object(
    'quote_id', quote_row.id, 'status', quote_row.status, 'decision', quote_row.decision,
    'decided_at', quote_row.decided_at, 'version_number', published_version,
    'already_decided', false
  );
end;
$$;


ALTER FUNCTION "public"."record_quote_decision"("target_quote_id" "uuid", "new_decision" "text", "decision_note" "text", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_quote_deposit_event"("target_quote_id" "uuid", "idempotency_key" "text", "method" "text", "reference" "text" DEFAULT NULL::"text", "note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  version_row public.quote_versions;
  existing_event public.quote_deposit_events;
  inserted_event public.quote_deposit_events;
  clean_reference text := nullif(trim(coalesce(reference, '')), '');
  clean_note text := nullif(trim(coalesce(note, '')), '');
begin
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if method not in ('cash', 'check', 'other', 'venmo', 'zelle', 'cash_app', 'e_transfer') then
    raise exception 'Choose how the deposit was received.' using errcode = 'check_violation';
  end if;

  select * into quote_row from public.quotes where id = target_quote_id for update;
  if quote_row.id is null or not private.member_has_permission(
    quote_row.organization_id, (select auth.uid()), 'quotes.record_deposit'
  ) then
    raise exception 'You do not have access to record a deposit on this quote.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into existing_event
  from public.quote_deposit_events
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and quote_deposit_events.idempotency_key = record_quote_deposit_event.idempotency_key;
  if existing_event.id is not null then
    return jsonb_build_object('status', 'recorded', 'event_id', existing_event.id);
  end if;

  select * into version_row from public.quote_versions
  where id = quote_row.current_published_version_id;
  if version_row.id is null or version_row.status <> 'published' then
    raise exception 'This quote has no published version to record a deposit against.'
      using errcode = 'check_violation';
  end if;
  if version_row.deposit_type is null or version_row.deposit_required_minor <= 0 then
    raise exception 'This quote does not require a deposit.' using errcode = 'check_violation';
  end if;

  if exists (
    select 1 from public.quote_deposit_events received
    where received.organization_id = version_row.organization_id
      and received.quote_id = version_row.quote_id
      and received.quote_version_id = version_row.id
      and received.event_type = 'received'
      and not exists (
        select 1 from public.quote_deposit_events reversal
        where reversal.organization_id = received.organization_id
          and reversal.reversed_event_id = received.id
      )
  ) then
    raise exception 'A deposit has already been recorded for this quote.'
      using errcode = 'check_violation';
  end if;

  insert into public.quote_deposit_events (
    organization_id, quote_id, quote_version_id, event_type, amount_minor, method, reference, note,
    recorded_by, idempotency_key
  )
  values (
    version_row.organization_id, version_row.quote_id, version_row.id, 'received',
    version_row.deposit_required_minor, method, clean_reference, clean_note,
    (select auth.uid()), idempotency_key
  )
  returning * into inserted_event;

  return jsonb_build_object('status', 'recorded', 'event_id', inserted_event.id);
end;
$$;


ALTER FUNCTION "public"."record_quote_deposit_event"("target_quote_id" "uuid", "idempotency_key" "text", "method" "text", "reference" "text", "note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_quote_in_person_signature"("target_quote_id" "uuid", "signer_name" "text", "signature_method" "text" DEFAULT 'in_person'::"text", "signature_object_key" "text" DEFAULT NULL::"text", "signature_byte_size" integer DEFAULT NULL::integer, "decision_note" "text" DEFAULT NULL::"text", "expected_revision" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  version_row public.quote_versions;
  new_decision_id uuid;
  clean_signer text;
  clean_note text;
begin
  clean_signer := nullif(trim(coalesce(signer_name, '')), '');
  if clean_signer is null or char_length(clean_signer) > 120 then
    raise exception 'A signature needs the name of the person signing.' using errcode = 'check_violation';
  end if;

  if signature_method is null or signature_method not in ('typed', 'in_person') then
    raise exception 'That is not a way to sign in person.' using errcode = 'check_violation';
  end if;

  if (signature_method = 'in_person') <> (signature_object_key is not null) then
    raise exception 'That signature is incomplete.' using errcode = 'check_violation';
  end if;

  clean_note := nullif(trim(coalesce(decision_note, '')), '');
  if clean_note is not null and char_length(clean_note) > 1000 then
    raise exception 'That note is too long.' using errcode = 'check_violation';
  end if;

  select * into quote_row from public.quotes where id = target_quote_id for update;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.record_decision'
     ) then
    raise exception 'You do not have access to answer this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.status = 'draft' then
    perform public.publish_quote(quote_row.id, expected_revision);
    select * into quote_row from public.quotes where id = quote_row.id;
  elsif quote_row.status not in ('awaiting_response', 'changes_requested') then
    raise exception 'This quote is not waiting for an answer.' using errcode = 'P0409';
  end if;

  select * into version_row
  from public.quote_versions where id = quote_row.current_published_version_id;
  if version_row.id is null then
    raise exception 'This quote has no sent version to sign.' using errcode = 'check_violation';
  end if;

  update public.quotes
  set status = 'approved',
      decision = 'approved',
      decided_at = now(),
      decision_method = 'in_person',
      decision_note = clean_note,
      decided_by = (select auth.uid())
  where id = quote_row.id
  returning * into quote_row;

  update public.quote_decisions
  set is_current = false
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and is_current;

  insert into public.quote_decisions (
    organization_id, quote_id, quote_version_id, outcome, actor_kind, actor_user_id, method, note
  ) values (
    quote_row.organization_id, quote_row.id, version_row.id, 'approved', 'staff',
    (select auth.uid()), 'in_person', clean_note
  )
  returning id into new_decision_id;

  insert into public.quote_signatures (
    organization_id, quote_id, quote_version_id, quote_decision_id, signer_name, method,
    document_hash, image_object_key, image_byte_size
  ) values (
    quote_row.organization_id, quote_row.id, version_row.id, new_decision_id, clean_signer,
    signature_method, version_row.document_hash, signature_object_key, signature_byte_size
  );

  insert into public.activity_events (
    organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
  ) values (
    quote_row.organization_id, 'quote', quote_row.id, 'quote.approved',
    'Collected ' || clean_signer || '''s signature in person', (select auth.uid()),
    jsonb_build_object(
      'version_number', version_row.version_number, 'method', 'in_person', 'signed', true
    )
  );

  return jsonb_build_object(
    'quote_id', quote_row.id, 'status', quote_row.status, 'decision', quote_row.decision,
    'decided_at', quote_row.decided_at, 'version_number', version_row.version_number,
    'signed', true
  );
end;
$$;


ALTER FUNCTION "public"."record_quote_in_person_signature"("target_quote_id" "uuid", "signer_name" "text", "signature_method" "text", "signature_object_key" "text", "signature_byte_size" integer, "decision_note" "text", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_quote_link_view"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.quote_access_links;
  quote_row public.quotes;
  was_first boolean;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row from public.quote_access_links where token_hash = supplied_token_hash;
  if link_row.id is null
     or link_row.revoked_at is not null
     or (link_row.expires_at is not null and link_row.expires_at <= now()) then
    return null;
  end if;

  select * into quote_row from public.quotes where id = link_row.quote_id;
  if quote_row.id is null
     or quote_row.status = 'archived'
     or quote_row.current_published_version_id is distinct from link_row.quote_version_id then
    return null;
  end if;

  was_first := link_row.first_viewed_at is null;

  update public.quote_access_links
  set first_viewed_at = coalesce(first_viewed_at, now()),
      last_viewed_at = now(),
      view_count = view_count + 1
  where id = link_row.id;

  if was_first then
    insert into public.activity_events (
      organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
    ) values (
      quote_row.organization_id, 'quote', quote_row.id, 'quote.viewed_by_client',
      'The client opened this quote', null,
      jsonb_build_object('quote_access_link_id', link_row.id)
    );
  end if;

  return jsonb_build_object('recorded', true, 'first_view', was_first);
end;
$$;


ALTER FUNCTION "public"."record_quote_link_view"("supplied_token_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_team_invitation_delivery"("target_invitation_id" "uuid", "target_success" boolean, "target_error" "text" DEFAULT NULL::"text") RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_row public.organization_member_invitations;
begin
  update public.organization_member_invitations
  set last_sent_at = now(),
      last_delivery_error = case when target_success then null else target_error end
  where id = target_invitation_id and state = 'invited'
  returning * into updated_row;

  if not found then
    raise exception 'Invitation % is not invited; delivery cannot be recorded.', target_invitation_id
      using errcode = 'check_violation';
  end if;

  return updated_row;
end;
$$;


ALTER FUNCTION "public"."record_team_invitation_delivery"("target_invitation_id" "uuid", "target_success" boolean, "target_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_invoice_snapshots"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_service_property_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  invoice_row public.invoices;
  settings_row public.organization_settings;
  refreshed public.invoices;
begin
  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for share;
  if not found then
    raise exception 'That organization could not be found.' using errcode = 'P0404';
  end if;

  invoice_row := private.lock_invoice_for_edit(
    target_organization_id, target_invoice_id, expected_revision
  );
  perform private.require_invoice_price_access(target_organization_id);

  if invoice_row.document_frozen_at is not null then
    raise exception 'This invoice has already been issued, so its snapshot cannot be refreshed.'
      using errcode = 'check_violation';
  end if;
  if private.invoice_allocated_minor(target_organization_id, target_invoice_id) <> 0 then
    raise exception 'Return the money on this draft to client credit before refreshing it.'
      using errcode = 'check_violation';
  end if;

  update public.invoices
  set customer_snapshot = private.build_invoice_customer_snapshot(
        target_organization_id, invoice_row.client_id
      ),
      billing_address_snapshot = private.resolve_client_billing_address(
        target_organization_id, invoice_row.client_id
      ),
      service_properties = case
        when new_service_property_ids is null then service_properties
        else private.build_invoice_service_properties(
          target_organization_id, invoice_row.client_id, new_service_property_ids
        )
      end,
      currency_code = settings_row.currency_code,
      revision = invoice_row.revision + 1
  where organization_id = target_organization_id and id = target_invoice_id
  returning * into refreshed;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.snapshot_refreshed', caller, refreshed.revision, null,
    jsonb_build_object(
      'currency_changed', refreshed.currency_code is distinct from invoice_row.currency_code
    ), false, null
  );

  return jsonb_build_object(
    'revision', refreshed.revision,
    'currency_code', refreshed.currency_code,
    'billing_address', refreshed.billing_address_snapshot
  );
end;
$$;


ALTER FUNCTION "public"."refresh_invoice_snapshots"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_service_property_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_client_payment"("target_organization_id" "uuid", "target_payment_event_id" "uuid", "target_deposit_event_id" "uuid", "new_amount_minor" bigint, "new_method" "text", "new_refund_date" "date", "new_reference" "text", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  settings_row public.organization_settings;
  receipt public.client_payment_events;
  deposit public.quote_deposit_events;
  source_client_id uuid;
  source_currency text;
  available bigint;
  refund public.client_payment_events;
begin
  if caller is null then
    raise exception 'You must be signed in to record a refund.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.correct_payment') then
    raise exception 'You do not have access to refund payments here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  if (target_payment_event_id is not null) = (target_deposit_event_id is not null) then
    raise exception 'Refund either a recorded payment or a quote deposit, not both.'
      using errcode = 'check_violation';
  end if;
  -- Money went back by some route, and which route it was is part of the record.
  if new_method is null
     or new_method not in ('other', 'bank_transfer', 'cash', 'check', 'card_external', 'paypal') then
    raise exception 'That is not a refund method this product records.' using errcode = 'check_violation';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'refund_client_payment', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for share;
  if not found then
    raise exception 'That organization could not be found.' using errcode = 'P0404';
  end if;

  -- The original receipt is the row that has to be held: two refunds of the same money serialize here, and
  -- so does a refund racing an application of the same receipt.
  if target_payment_event_id is not null then
    select * into receipt
    from public.client_payment_events
    where organization_id = target_organization_id and id = target_payment_event_id
    for update;
    if not found then
      raise exception 'That payment could not be found.' using errcode = 'P0404';
    end if;
    if receipt.event_type <> 'received' then
      raise exception 'Only money that was received can be refunded.' using errcode = 'check_violation';
    end if;
    source_client_id := receipt.client_id;
    source_currency := receipt.currency_code;
    available := private.payment_event_available_minor(target_organization_id, receipt.id);
  else
    select * into deposit
    from public.quote_deposit_events
    where organization_id = target_organization_id and id = target_deposit_event_id
    for update;
    if not found then
      raise exception 'That deposit could not be found.' using errcode = 'P0404';
    end if;
    if deposit.event_type <> 'received' then
      raise exception 'Only a deposit that was received can be refunded.' using errcode = 'check_violation';
    end if;
    select quote.client_id into source_client_id
    from public.quotes as quote
    where quote.organization_id = target_organization_id and quote.id = deposit.quote_id;
    -- A deposit exists only on a published quote, which locks the organization's currency permanently, so
    -- the settings currency is still the currency that deposit arrived in.
    source_currency := settings_row.currency_code;
    available := private.deposit_event_available_minor(target_organization_id, deposit.id);
  end if;

  if source_client_id is null then
    raise exception 'That money is not attached to a client.' using errcode = 'check_violation';
  end if;
  if new_amount_minor is null or new_amount_minor <= 0 then
    raise exception 'A refund amount must be more than zero.' using errcode = 'check_violation';
  end if;
  if new_amount_minor > available then
    -- Deliberately one message for both causes. Money already refunded and money sitting on a bill are the
    -- same thing from here: it is not available to send back until somebody takes it off the bill.
    raise exception 'That is more than this payment has left to refund.'
      using errcode = 'check_violation',
      detail = format('%s available, %s offered', available, new_amount_minor),
      hint = 'Money applied to an invoice must be taken off that invoice before it can be refunded.';
  end if;

  insert into public.client_payment_events (
    organization_id, client_id, event_type, amount_minor, currency_code, method, payment_date,
    reference, note, actor_user_id, original_event_id, original_deposit_event_id
  ) values (
    target_organization_id, source_client_id, 'refunded', new_amount_minor, source_currency,
    new_method, coalesce(new_refund_date, private.organization_today(target_organization_id)),
    nullif(trim(coalesce(new_reference, '')), ''), nullif(trim(coalesce(new_note, '')), ''), caller,
    target_payment_event_id, target_deposit_event_id
  )
  returning * into refund;

  return private.complete_invoice_command(
    target_organization_id, 'refund_client_payment', new_idempotency_key,
    jsonb_build_object(
      'refund_event_id', refund.id,
      'client_id', refund.client_id,
      'amount_minor', refund.amount_minor,
      'currency_code', refund.currency_code,
      'refund_date', refund.payment_date,
      'source', case when target_deposit_event_id is not null then 'quote_deposit' else 'payment' end,
      'original_event_id', target_payment_event_id,
      'original_deposit_event_id', target_deposit_event_id,
      'remaining_refundable_minor', available - refund.amount_minor
    )
  );
end;
$$;


ALTER FUNCTION "public"."refund_client_payment"("target_organization_id" "uuid", "target_payment_event_id" "uuid", "target_deposit_event_id" "uuid", "new_amount_minor" bigint, "new_method" "text", "new_refund_date" "date", "new_reference" "text", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refund_client_payment"("target_organization_id" "uuid", "target_payment_event_id" "uuid", "target_deposit_event_id" "uuid", "new_amount_minor" bigint, "new_method" "text", "new_refund_date" "date", "new_reference" "text", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Records money actually sent back to a client against one original receipt -- a recorded payment or a quote deposit -- never more than that receipt still has unspent and unrefunded. The original receipt is kept exactly as it was; the refund is a new row pointing at it.';



CREATE OR REPLACE FUNCTION "public"."release_communication_worker_lease"("p_worker_name" "text", "p_lease_token" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with removed as (
    delete from private.communication_worker_leases
    where worker_name = p_worker_name and lease_token = p_lease_token
    returning 1
  )
  select exists (select 1 from removed);
$$;


ALTER FUNCTION "public"."release_communication_worker_lease"("p_worker_name" "text", "p_lease_token" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."release_communication_worker_lease"("p_worker_name" "text", "p_lease_token" "uuid") IS 'Releases a lease only if the token matches, so a wake can never release a lease a later wake took over.';



CREATE OR REPLACE FUNCTION "public"."release_member_identity_cleanup"("target_organization_id" "uuid", "target_user_id" "uuid", "target_lease_nonce" "uuid", "target_safe_error" "text") RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  released_row public.organization_members;
begin
  update public.organization_members as membership_row
  set identity_cleanup_error = left(nullif(btrim(target_safe_error), ''), 240),
      identity_cleanup_nonce = null,
      identity_cleanup_lease_expires_at = null
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
    and membership_row.identity_cleanup_nonce = target_lease_nonce
    and membership_row.identity_cleanup_lease_expires_at > now()
  returning membership_row.* into released_row;

  if not found then
    raise exception 'The identity cleanup lease is no longer valid.'
      using errcode = 'serialization_failure';
  end if;

  return released_row;
end;
$$;


ALTER FUNCTION "public"."release_member_identity_cleanup"("target_organization_id" "uuid", "target_user_id" "uuid", "target_lease_nonce" "uuid", "target_safe_error" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."release_member_identity_cleanup"("target_organization_id" "uuid", "target_user_id" "uuid", "target_lease_nonce" "uuid", "target_safe_error" "text") IS 'Hands back an identity cleanup lease after a failed Auth call and records why, so the next run retries immediately and a stuck cleanup stays visible.';



CREATE OR REPLACE FUNCTION "public"."release_team_invitation_reconciliation"("target_invitation_id" "uuid", "target_lease_nonce" "uuid", "target_safe_error" "text") RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  released_row public.organization_member_invitations;
begin
  update public.organization_member_invitations
  set identity_cleanup_error = left(nullif(trim(target_safe_error), ''), 240),
      reconciliation_nonce = null,
      reconciliation_lease_expires_at = null
  where id = target_invitation_id
    and identity_cleanup_state = 'required'
    and reconciliation_nonce = target_lease_nonce
    and reconciliation_lease_expires_at > now()
  returning * into released_row;

  if not found then
    raise exception 'The invitation cleanup lease is no longer valid.' using errcode = 'P0409';
  end if;
  return released_row;
end;
$$;


ALTER FUNCTION "public"."release_team_invitation_reconciliation"("target_invitation_id" "uuid", "target_lease_nonce" "uuid", "target_safe_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_invoice_payment_term"("target_organization_id" "uuid", "expected_revision" integer, "target_term_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings_row public.organization_settings;
  existing_term public.invoice_payment_terms;
  receipt_term public.invoice_payment_terms;
  changed text[] := array['payment_terms'];
begin
  settings_row := private.lock_invoice_settings_for_edit(target_organization_id, expected_revision);

  select * into existing_term
  from public.invoice_payment_terms
  where organization_id = target_organization_id and id = target_term_id
  for update;
  if not found then
    raise exception 'That payment term could not be found.' using errcode = 'P0404';
  end if;
  if existing_term.is_protected then
    raise exception 'This term is built in and cannot be removed.' using errcode = 'check_violation';
  end if;
  if existing_term.archived_at is not null then
    return jsonb_build_object(
      'term_id', existing_term.id,
      'invoice_settings_revision', settings_row.invoice_settings_revision
    );
  end if;

  select * into receipt_term
  from public.invoice_payment_terms
  where organization_id = target_organization_id and rule = 'on_receipt' and is_protected;

  if settings_row.invoice_default_term_residential_id = target_term_id
     or settings_row.invoice_default_term_commercial_id = target_term_id then
    update public.organization_settings
    set invoice_default_term_residential_id = case
          when invoice_default_term_residential_id = target_term_id then receipt_term.id
          else invoice_default_term_residential_id end,
        invoice_default_term_commercial_id = case
          when invoice_default_term_commercial_id = target_term_id then receipt_term.id
          else invoice_default_term_commercial_id end
    where organization_id = target_organization_id;
    changed := changed || array['defaults'];
  end if;

  update public.clients
  set billing_payment_term_id = null, updated_at = now()
  where organization_id = target_organization_id and billing_payment_term_id = target_term_id;

  update public.invoice_payment_terms
  set archived_at = now(), updated_at = now()
  where organization_id = target_organization_id and id = target_term_id;

  return jsonb_build_object(
    'term_id', target_term_id,
    'invoice_settings_revision', private.bump_invoice_settings(target_organization_id, changed)
  );
end;
$$;


ALTER FUNCTION "public"."remove_invoice_payment_term"("target_organization_id" "uuid", "expected_revision" integer, "target_term_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_job_checklist"("target_organization_id" "uuid", "target_job_id" "uuid", "target_checklist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  answers_lost integer;
begin
  if caller is null then
    raise exception 'You must be signed in to remove a checklist.' using errcode = 'insufficient_privilege';
  end if;
  if not private.can_view_job(target_organization_id, target_job_id)
    or not private.member_has_permission(target_organization_id, caller, 'jobs.edit') then
    raise exception 'You do not have access to change this job.' using errcode = 'insufficient_privilege';
  end if;

  select count(*) into answers_lost
  from public.visit_checklist_answers as answer
  join public.job_checklist_items as item
    on item.organization_id = answer.organization_id and item.id = answer.item_id
  where answer.organization_id = target_organization_id
    and item.job_checklist_id = target_checklist_id;

  delete from public.job_checklists
  where organization_id = target_organization_id
    and job_id = target_job_id
    and id = target_checklist_id;
  if not found then
    raise exception 'That checklist could not be found on this job.' using errcode = 'P0404';
  end if;

  return jsonb_build_object('id', target_checklist_id, 'answers_removed', answers_lost);
end;
$$;


ALTER FUNCTION "public"."remove_job_checklist"("target_organization_id" "uuid", "target_job_id" "uuid", "target_checklist_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_job_checklist"("target_organization_id" "uuid", "target_job_id" "uuid", "target_checklist_id" "uuid") IS 'Takes a checklist off a job, with the answers every visit gave it.';



CREATE OR REPLACE FUNCTION "public"."remove_organization_logo"("target_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  previous_object_key text;
  new_revision integer;
begin
  if not private.has_permission(target_organization_id, 'settings.business.edit') then
    raise exception 'You do not have access to change business settings.'
      using errcode = 'insufficient_privilege';
  end if;

  select logo_object_key into previous_object_key
  from public.organization_settings
  where organization_id = target_organization_id
  for update;

  update public.organization_settings
  set
    logo_object_key = null,
    branding_revision = branding_revision + 1,
    branding_updated_by = (select auth.uid()),
    branding_updated_at = now()
  where organization_id = target_organization_id
  returning branding_revision into new_revision;

  insert into public.organization_settings_audit (
    organization_id, section, changed_fields, actor_user_id
  )
  values (target_organization_id, 'branding', array['logo'], (select auth.uid()));

  return jsonb_build_object(
    'status', 'saved',
    'branding_revision', new_revision,
    'previous_object_key', previous_object_key
  );
end;
$$;


ALTER FUNCTION "public"."remove_organization_logo"("target_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_team_member"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members;
  name_at_removal text;
begin
  -- Owner-only: "Permanent removal is available only after deactivation and requires the Owner".
  membership := private.authorize_team_member_command(
    target_organization_id, actor_user_id, target_user_id, true
  );

  if membership.status = 'removed' then
    raise exception 'That person has already been removed.' using errcode = 'check_violation';
  end if;

  if membership.status <> 'deactivated' then
    raise exception 'Deactivate this person before removing them permanently.'
      using errcode = 'check_violation';
  end if;

  -- "An Administrator must first be demoted by the Owner." Two deliberate decisions, never one.
  if membership.role = 'admin' then
    raise exception 'Change this administrator to another role before removing them.'
      using errcode = 'check_violation';
  end if;

  select nullif(btrim(coalesce(profile.full_name, '')), '') into name_at_removal
  from public.profiles as profile
  where profile.id = target_user_id;

  -- A profile with no name still needs one here: the removed_keeps_a_name constraint refuses the row
  -- otherwise, and an unlabelled line in somebody's history is worse than a plain one.
  name_at_removal := left(coalesce(name_at_removal, 'Removed team member'), 160);

  -- The adjustments go now, not with the Auth cleanup: they grant access, and access ends here.
  delete from public.organization_member_permission_overrides as override
  where override.organization_id = target_organization_id
    and override.user_id = target_user_id;

  update public.organization_members as membership_row
  set status = 'removed',
      removed_at = now(),
      status_changed_at = now(),
      status_changed_by = actor_user_id,
      display_name_at_removal = name_at_removal,
      identity_cleanup_state = 'required',
      identity_cleanup_error = null,
      access_revision = membership_row.access_revision + 1
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  returning * into membership;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    target_organization_id, 'member.removed', 'member', actor_user_id, target_user_id, '{}'::jsonb
  );

  return membership;
end;
$$;


ALTER FUNCTION "public"."remove_team_member"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_team_member"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") IS 'Owner-only permanent removal of an already-deactivated member. Keeps the row as a tombstone with a name snapshot, drops their adjustments, and marks the Auth cleanup as required for 3B''s worker.';



CREATE OR REPLACE FUNCTION "public"."remove_website_chat_widget_origin"("target_organization_id" "uuid", "target_widget_id" "uuid", "target_origin_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  deleted_row public.website_chat_widget_origins;
begin
  if not private.has_permission(target_organization_id, 'conversations.manage_connections') then
    raise exception 'You do not have access to manage Website Chat.' using errcode = 'insufficient_privilege';
  end if;

  delete from public.website_chat_widget_origins
  where organization_id = target_organization_id
    and widget_id = target_widget_id
    and id = target_origin_id
  returning * into deleted_row;

  if deleted_row.id is null then
    raise exception 'That domain was not found.' using errcode = 'check_violation';
  end if;

  return jsonb_build_object('status', 'deleted', 'id', deleted_row.id);
end;
$$;


ALTER FUNCTION "public"."remove_website_chat_widget_origin"("target_organization_id" "uuid", "target_widget_id" "uuid", "target_origin_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_website_chat_widget_origin"("target_organization_id" "uuid", "target_widget_id" "uuid", "target_origin_id" "uuid") IS 'Removes one allowed origin from a Website Chat widget.';



CREATE OR REPLACE FUNCTION "public"."reopen_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  invoice_row public.invoices;
begin
  if caller is null then
    raise exception 'You must be signed in to reopen an invoice.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.record_payment') then
    raise exception 'You do not have access to reopen invoices here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  replayed := private.begin_invoice_command(
    target_organization_id, 'reopen_invoice', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  invoice_row := private.lock_invoice_for_payment(target_organization_id, target_invoice_id);

  if invoice_row.marked_received_at is null then
    raise exception 'This bill was not closed by hand, so there is nothing to reopen.'
      using errcode = 'check_violation';
  end if;

  update public.invoices
  set marked_received_at = null,
      marked_received_by = null,
      revision = invoice_row.revision + 1,
      updated_at = now()
  where organization_id = target_organization_id and id = invoice_row.id;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.reopened', caller, invoice_row.revision + 1, new_reason, '{}'::jsonb, false, null
  );

  return private.complete_invoice_command(
    target_organization_id, 'reopen_invoice', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', invoice_row.id,
      'invoice_number', invoice_row.invoice_number,
      'client_id', invoice_row.client_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."reopen_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reopen_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Undoes a by-hand closure, putting the bill back to awaiting payment or past due according to its due date. Both the closure and the reopening stay in its history.';



CREATE OR REPLACE FUNCTION "public"."reopen_job"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
begin
  if caller is null then
    raise exception 'You must be signed in to reopen a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.close') then
    raise exception 'You do not have access to reopen this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id
  for update;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  if current_job.status = 'active' then
    return jsonb_build_object('applied', true, 'already_active', true, 'revision', current_job.revision);
  end if;
  if current_job.revision is distinct from expected_revision then
    raise exception 'Someone else changed this job. Reload to see the latest.' using errcode = 'P0409';
  end if;

  update public.jobs
  set status = 'active', revision = current_job.revision + 1, updated_at = now()
  where organization_id = target_organization_id and id = target_job_id;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, new_status, metadata)
  values (target_organization_id, target_job_id, 'job_reopened', caller, 'active', '{}'::jsonb);

  return jsonb_build_object('applied', true, 'already_active', false, 'revision', current_job.revision + 1);
end;
$$;


ALTER FUNCTION "public"."reopen_job"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reopen_job"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer) IS 'Returns a closed job to active. Checks jobs.close, refuses a stale revision (P0409), is idempotent on an already-active job. Removed visits do not regenerate; scheduling more is a separate explicit action.';



CREATE OR REPLACE FUNCTION "public"."replace_invoice_lines"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  invoice_row public.invoices;
  line_count integer;
  money jsonb;
begin
  invoice_row := private.lock_invoice_for_edit(
    target_organization_id, target_invoice_id, expected_revision
  );
  perform private.require_invoice_price_access(target_organization_id);

  if new_lines is null or jsonb_typeof(new_lines) <> 'array' or jsonb_array_length(new_lines) = 0 then
    raise exception 'An invoice needs at least one line.' using errcode = 'check_violation';
  end if;

  perform private.retain_prior_invoice_document(invoice_row, caller, 'lines replaced');

  delete from public.invoice_lines
  where organization_id = target_organization_id and invoice_id = target_invoice_id;

  insert into public.invoice_lines (
    organization_id, invoice_id, position, source_catalog_item_id, source_job_id, source_job_line_id,
    service_date, line_kind, category, name, description, unit_label, quantity, unit_price_minor,
    is_taxable, progress_original_amount_minor
  )
  select
    target_organization_id,
    target_invoice_id,
    (row_number() over (order by (line.value->>'position')::integer, line.ordinality) - 1)::integer,
    nullif(line.value->>'source_catalog_item_id', '')::uuid,
    nullif(line.value->>'source_job_id', '')::uuid,
    nullif(line.value->>'source_job_line_id', '')::uuid,
    nullif(line.value->>'service_date', '')::date,
    coalesce(line.value->>'line_kind', 'priced'),
    nullif(line.value->>'category', ''),
    line.value->>'name',
    nullif(line.value->>'description', ''),
    nullif(line.value->>'unit_label', ''),
    (line.value->>'quantity')::numeric,
    (line.value->>'unit_price_minor')::bigint,
    coalesce((line.value->>'is_taxable')::boolean, true),
    nullif(line.value->>'progress_original_amount_minor', '')::bigint
  from jsonb_array_elements(new_lines) with ordinality as line(value, ordinality);

  get diagnostics line_count = row_count;

  money := private.store_invoice_money(target_invoice_id);

  update public.invoices
  set revision = invoice_row.revision + 1
  where organization_id = target_organization_id and id = target_invoice_id;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.lines_updated', caller, invoice_row.revision + 1, null,
    jsonb_build_object('line_count', line_count), false, null
  );

  return jsonb_build_object(
    'revision', invoice_row.revision + 1, 'line_count', line_count, 'totals', money - 'lines'
  );
end;
$$;


ALTER FUNCTION "public"."replace_invoice_lines"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_job_line_items"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  line_count integer;
begin
  current_job := private.lock_job_for_edit(target_organization_id, target_job_id, expected_revision);

  if new_lines is null or jsonb_typeof(new_lines) <> 'array' then
    raise exception 'The job scope must be a list of lines.' using errcode = 'check_violation';
  end if;

  delete from public.job_line_items
  where organization_id = target_organization_id
    and job_id = target_job_id;

  insert into public.job_line_items (
    organization_id, job_id, position, source_catalog_item_id, line_kind, category, is_labor,
    name, description, unit_label, quantity, unit_price_minor, unit_cost_minor, is_taxable,
    image_attachment_id
  )
  select
    target_organization_id,
    target_job_id,
    (row_number() over (order by (line.value->>'position')::integer, ordinality) - 1)::integer,
    nullif(line.value->>'source_catalog_item_id', '')::uuid,
    coalesce(line.value->>'line_kind', 'priced'),
    nullif(line.value->>'category', ''),
    coalesce((line.value->>'is_labor')::boolean, false),
    line.value->>'name',
    nullif(line.value->>'description', ''),
    nullif(line.value->>'unit_label', ''),
    (line.value->>'quantity')::numeric,
    (line.value->>'unit_price_minor')::bigint,
    (line.value->>'unit_cost_minor')::bigint,
    coalesce((line.value->>'is_taxable')::boolean, true),
    nullif(line.value->>'image_attachment_id', '')::uuid
  from jsonb_array_elements(new_lines) with ordinality as line(value, ordinality);

  get diagnostics line_count = row_count;

  perform private.store_job_money(target_job_id);

  update public.jobs
  set revision = current_job.revision + 1
  where organization_id = target_organization_id
    and id = target_job_id;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'scope_updated',
    caller,
    jsonb_build_object('line_count', line_count)
  );

  return jsonb_build_object('revision', current_job.revision + 1, 'line_count', line_count);
end;
$$;


ALTER FUNCTION "public"."replace_job_line_items"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_job_line_items"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") IS 'Replaces a job''s whole scope in one transaction, recalculates its money through private.calculate_job, bumps revision and appends a scope_updated history row.';



CREATE OR REPLACE FUNCTION "public"."replace_job_visit_line_items"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  current_visit public.job_visits;
  line_count integer := 0;
begin
  if caller is null then
    raise exception 'You must be signed in to price a visit.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.edit') then
    raise exception 'You do not have access to edit this job.' using errcode = 'insufficient_privilege';
  end if;

  if new_lines is null or jsonb_typeof(new_lines) <> 'array' then
    raise exception 'A visit''s pricing must be a list of lines.' using errcode = 'check_violation';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id
  for update;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  if current_job.status <> 'active' then
    raise exception 'A closed job''s visits cannot be repriced.' using errcode = 'P0410';
  end if;

  if current_job.price_basis is distinct from 'per_visit' then
    raise exception 'Only a job billed per visit can price its visits separately.'
      using errcode = 'check_violation',
      hint = 'Change the job''s billing to per visit first.';
  end if;

  select visit.* into current_visit
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.id = target_visit_id
  for update;
  if not found then
    raise exception 'That visit could not be found.' using errcode = 'P0404';
  end if;

  if current_visit.completed_at is not null then
    raise exception 'A completed visit''s pricing cannot be changed.' using errcode = 'P0410',
      hint = 'Reopen the visit first if the work was different from what was recorded.';
  end if;

  if exists (
    select 1
    from public.invoice_sources as claim
    where claim.organization_id = target_organization_id
      and claim.visit_id = target_visit_id
      and claim.source_kind = 'visit'
  ) then
    raise exception 'An invoiced visit''s pricing cannot be changed.' using errcode = 'P0410';
  end if;

  if current_visit.revision is distinct from expected_revision then
    raise exception 'Someone else changed this visit. Reload to see the latest.' using errcode = 'P0409';
  end if;

  delete from public.job_visit_line_items
  where organization_id = target_organization_id
    and visit_id = target_visit_id;

  insert into public.job_visit_line_items (
    organization_id, job_id, visit_id, position, source_job_line_item_id, source_catalog_item_id,
    line_kind, category, is_labor, name, description, unit_label, quantity, unit_price_minor,
    unit_cost_minor, is_taxable, image_attachment_id
  )
  select
    target_organization_id,
    target_job_id,
    target_visit_id,
    (numbered.rank - 1)::integer,
    case when numbered.source_rank = 1 then numbered.source_job_line_item_id end,
    numbered.source_catalog_item_id,
    numbered.line_kind,
    numbered.category,
    numbered.is_labor,
    numbered.name,
    numbered.description,
    numbered.unit_label,
    numbered.quantity,
    numbered.unit_price_minor,
    numbered.unit_cost_minor,
    numbered.is_taxable,
    numbered.image_attachment_id
  from (
    select
      row_number() over (order by (line.value->>'position')::integer, line.ordinality) as rank,
      nullif(line.value->>'source_job_line_item_id', '')::uuid as source_job_line_item_id,
      row_number() over (
        partition by nullif(line.value->>'source_job_line_item_id', '')::uuid
        order by (line.value->>'position')::integer, line.ordinality
      ) as source_rank,
      nullif(line.value->>'source_catalog_item_id', '')::uuid as source_catalog_item_id,
      coalesce(line.value->>'line_kind', 'priced') as line_kind,
      nullif(line.value->>'category', '') as category,
      coalesce((line.value->>'is_labor')::boolean, false) as is_labor,
      line.value->>'name' as name,
      nullif(line.value->>'description', '') as description,
      nullif(line.value->>'unit_label', '') as unit_label,
      (line.value->>'quantity')::numeric as quantity,
      (line.value->>'unit_price_minor')::bigint as unit_price_minor,
      (line.value->>'unit_cost_minor')::bigint as unit_cost_minor,
      coalesce((line.value->>'is_taxable')::boolean, true) as is_taxable,
      nullif(line.value->>'image_attachment_id', '')::uuid as image_attachment_id
    from jsonb_array_elements(new_lines) with ordinality as line(value, ordinality)
  ) as numbered;

  get diagnostics line_count = row_count;

  if exists (
    select 1
    from public.job_visit_line_items as item
    join public.job_line_items as source
      on source.organization_id = item.organization_id
     and source.id = item.source_job_line_item_id
    where item.organization_id = target_organization_id
      and item.visit_id = target_visit_id
      and source.job_id <> target_job_id
  ) then
    raise exception 'A visit can only change lines that belong to its own job.' using errcode = 'check_violation';
  end if;

  update public.job_visits
  set revision = current_visit.revision + 1,
      updated_at = now()
  where organization_id = target_organization_id
    and id = target_visit_id;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, related_visit_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'visit_updated',
    caller,
    target_visit_id,
    jsonb_build_object(
      'changed', to_jsonb(array['pricing']),
      'line_count', line_count,
      'has_override', line_count > 0
    )
  );

  return jsonb_build_object(
    'revision', current_visit.revision + 1,
    'line_count', line_count,
    'has_override', line_count > 0
  );
end;
$$;


ALTER FUNCTION "public"."replace_job_visit_line_items"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_job_visit_line_items"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") IS 'Replaces one visit''s own priced lines in one transaction. Checks jobs.edit, refuses a job that is not billed per visit, a completed or invoiced visit (P0410) and a stale revision (P0409). An empty list clears the override, putting the visit back on the job''s lines.';



CREATE OR REPLACE FUNCTION "public"."replace_quote_version_attachments"("target_quote_id" "uuid", "expected_revision" integer, "new_attachments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  draft_row public.quote_versions;
  attachment jsonb;
  attachment_index integer := 0;
  clean_attachment_id uuid;
  clean_display_name text;
  seen_ids uuid[] := '{}'::uuid[];
begin
  if new_attachments is null or jsonb_typeof(new_attachments) <> 'array' then
    raise exception 'Files must be sent as a list.' using errcode = 'check_violation';
  end if;
  if jsonb_array_length(new_attachments) > 50 then
    raise exception 'A quote can show up to 50 files.' using errcode = 'check_violation';
  end if;

  draft_row := private.lock_quote_draft(target_quote_id, expected_revision);

  delete from public.quote_version_attachments
  where organization_id = draft_row.organization_id
    and quote_version_id = draft_row.id;

  for attachment in select * from jsonb_array_elements(new_attachments)
  loop
    clean_attachment_id := nullif(attachment ->> 'attachment_id', '')::uuid;
    clean_display_name := nullif(trim(coalesce(attachment ->> 'display_name', '')), '');

    if clean_attachment_id is null then
      raise exception 'File % is missing.', attachment_index + 1 using errcode = 'check_violation';
    end if;
    if clean_attachment_id = any(seen_ids) then
      raise exception 'The same file was listed twice.' using errcode = 'check_violation';
    end if;
    seen_ids := seen_ids || clean_attachment_id;

    if not exists (
      select 1 from public.attachments
      where id = clean_attachment_id
        and organization_id = draft_row.organization_id
        and entity_type = 'quote'
        and entity_id = target_quote_id
    ) then
      raise exception 'File % was not uploaded to this quote.', attachment_index + 1
        using errcode = 'check_violation';
    end if;

    if clean_display_name is null or char_length(clean_display_name) > 255 then
      raise exception 'File % needs a name under 255 characters.', attachment_index + 1
        using errcode = 'check_violation';
    end if;

    insert into public.quote_version_attachments (
      organization_id, quote_id, quote_version_id, attachment_id, position, customer_visible, display_name
    ) values (
      draft_row.organization_id, draft_row.quote_id, draft_row.id, clean_attachment_id, attachment_index,
      coalesce((attachment ->> 'customer_visible')::boolean, false), clean_display_name
    );

    attachment_index := attachment_index + 1;
  end loop;

  return private.bump_quote_draft(draft_row.id);
end;
$$;


ALTER FUNCTION "public"."replace_quote_version_attachments"("target_quote_id" "uuid", "expected_revision" integer, "new_attachments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_quote_version_lines"("target_quote_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  draft_row public.quote_versions;
  line jsonb;
  line_index integer := 0;
  clean_kind text;
  clean_selection text;
  clean_recommended boolean;
  clean_quantity numeric;
  clean_price bigint;
  clean_cost bigint;
  clean_category text;
  clean_name text;
  clean_catalog_item_id uuid;
  clean_image_attachment_id uuid;
  new_count integer;
  result jsonb;
begin
  if new_lines is null or jsonb_typeof(new_lines) <> 'array' then
    raise exception 'Lines must be sent as a list.' using errcode = 'check_violation';
  end if;
  if jsonb_array_length(new_lines) > 200 then
    raise exception 'A quote can hold up to 200 lines.' using errcode = 'program_limit_exceeded';
  end if;

  draft_row := private.lock_quote_draft(target_quote_id, expected_revision);

  delete from public.quote_version_lines
  where organization_id = draft_row.organization_id
    and quote_id = draft_row.quote_id
    and quote_version_id = draft_row.id;

  for line in select * from jsonb_array_elements(new_lines)
  loop
    clean_name := nullif(trim(coalesce(line ->> 'name', '')), '');
    clean_kind := coalesce(nullif(line ->> 'line_kind', ''), 'priced');
    clean_selection := coalesce(nullif(line ->> 'selection_kind', ''), 'required');
    clean_recommended := coalesce((line ->> 'is_recommended')::boolean, false);

    if clean_kind not in ('priced', 'text', 'heading') then
      raise exception 'Line % is not a kind of line this quote understands.', line_index + 1
        using errcode = 'check_violation';
    end if;
    if clean_name is null or char_length(clean_name) < 2 or char_length(clean_name) > 160 then
      raise exception 'Line % needs a name between 2 and 160 characters.', line_index + 1
        using errcode = 'check_violation';
    end if;

    if clean_kind <> 'priced' then
      insert into public.quote_version_lines (
        organization_id, quote_id, quote_version_id, position, name, description, is_taxable,
        line_kind, selection_kind
      ) values (
        draft_row.organization_id, draft_row.quote_id, draft_row.id, line_index, clean_name,
        nullif(trim(coalesce(line ->> 'description', '')), ''), false, clean_kind, 'required'
      );
      line_index := line_index + 1;
      continue;
    end if;

    clean_category := coalesce(line ->> 'category', 'service');
    clean_quantity := coalesce((line ->> 'quantity')::numeric, 0);
    clean_price := coalesce((line ->> 'unit_price_minor')::bigint, 0);
    clean_cost := coalesce((line ->> 'unit_cost_minor')::bigint, 0);
    clean_catalog_item_id := nullif(line ->> 'catalog_item_id', '')::uuid;
    clean_image_attachment_id := nullif(line ->> 'image_attachment_id', '')::uuid;

    if clean_category not in ('product', 'service') then
      raise exception 'Line % must be a product or a service.', line_index + 1
        using errcode = 'check_violation';
    end if;
    if clean_quantity <= 0 or clean_quantity > 1000000 then
      raise exception 'Line % needs a quantity above zero.', line_index + 1
        using errcode = 'check_violation';
    end if;
    if clean_price < 0 or clean_price > 1000000000000 or clean_cost < 0 or clean_cost > 1000000000000 then
      raise exception 'Line % has a price or cost outside the allowed range.', line_index + 1
        using errcode = 'check_violation';
    end if;

    if clean_selection not in ('required', 'optional') then
      raise exception 'Line % must be required work or an add-on.', line_index + 1
        using errcode = 'check_violation';
    end if;
    if clean_recommended and clean_selection <> 'optional' then
      raise exception 'Line % cannot be marked as recommended.', line_index + 1
        using errcode = 'check_violation';
    end if;

    if clean_catalog_item_id is not null and not exists (
      select 1 from public.catalog_items
      where id = clean_catalog_item_id
        and organization_id = draft_row.organization_id
        and archived_at is null
    ) then
      raise exception 'Line % points at a price list item that is no longer available.', line_index + 1
        using errcode = 'check_violation';
    end if;

    if clean_image_attachment_id is not null
       and not exists (
         select 1 from public.attachments
         where id = clean_image_attachment_id
           and organization_id = draft_row.organization_id
           and entity_type = 'quote'
           and entity_id = target_quote_id
       )
       and not exists (
         select 1 from public.quote_version_lines
         where organization_id = draft_row.organization_id
           and quote_id = target_quote_id
           and image_attachment_id = clean_image_attachment_id
       ) then
      raise exception 'Line % points at an image that was not uploaded for this quote.', line_index + 1
        using errcode = 'check_violation';
    end if;

    insert into public.quote_version_lines (
      organization_id, quote_id, quote_version_id, position, source_catalog_item_id, category, is_labor,
      name, description, unit_label, quantity, unit_price_minor, unit_cost_minor, is_taxable,
      image_attachment_id, line_kind, selection_kind, is_recommended
    ) values (
      draft_row.organization_id,
      draft_row.quote_id,
      draft_row.id,
      line_index,
      clean_catalog_item_id,
      clean_category,
      coalesce((line ->> 'is_labor')::boolean, false),
      clean_name,
      nullif(trim(coalesce(line ->> 'description', '')), ''),
      nullif(trim(coalesce(line ->> 'unit_label', '')), ''),
      clean_quantity,
      clean_price,
      clean_cost,
      coalesce((line ->> 'is_taxable')::boolean, true),
      clean_image_attachment_id,
      'priced',
      clean_selection,
      clean_recommended
    );

    line_index := line_index + 1;
  end loop;

  select count(*) into new_count
  from public.quote_version_lines
  where organization_id = draft_row.organization_id
    and quote_id = draft_row.quote_id
    and quote_version_id = draft_row.id;

  result := private.bump_quote_draft(draft_row.id);

  return result || jsonb_build_object(
    'line_count', new_count,
    'subtotal_minor', (result -> 'totals' ->> 'subtotal_minor')::bigint
  );
end;
$$;


ALTER FUNCTION "public"."replace_quote_version_lines"("target_quote_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_request_pricing_lines"("target_request_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  request_row public.requests;
  line jsonb;
  line_index integer := 0;
  clean_quantity numeric;
  clean_price bigint;
  clean_cost bigint;
  clean_category text;
  clean_name text;
  clean_catalog_item_id uuid;
  clean_image_attachment_id uuid;
  new_revision integer;
  new_subtotal bigint;
  new_count integer;
begin
  if new_lines is null or jsonb_typeof(new_lines) <> 'array' then
    raise exception 'Pricing must be sent as a list of lines.' using errcode = 'check_violation';
  end if;
  if jsonb_array_length(new_lines) > 200 then
    raise exception 'A request can hold up to 200 pricing lines.' using errcode = 'program_limit_exceeded';
  end if;

  select * into request_row from public.requests where id = target_request_id for update;

  -- One answer for "no such request" and "not your request": a stranger learns nothing either way. Now the
  -- same decision the parent Request's own RLS makes, not plain membership.
  if request_row.id is null
     or not private.can_view_request(request_row.organization_id, target_request_id) then
    raise exception 'You do not have access to price this request.' using errcode = 'insufficient_privilege';
  end if;

  if request_row.status in ('converted', 'archived') then
    raise exception 'This request is closed and its pricing cannot be changed.'
      using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from request_row.pricing_revision then
    raise exception 'Someone else changed this pricing while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  delete from public.request_pricing_lines
  where organization_id = request_row.organization_id
    and request_id = target_request_id;

  for line in select * from jsonb_array_elements(new_lines)
  loop
    clean_name := nullif(trim(coalesce(line ->> 'name', '')), '');
    clean_category := coalesce(line ->> 'category', 'service');
    clean_quantity := coalesce((line ->> 'quantity')::numeric, 0);
    clean_price := coalesce((line ->> 'unit_price_minor')::bigint, 0);
    clean_cost := coalesce((line ->> 'unit_cost_minor')::bigint, 0);
    clean_catalog_item_id := nullif(line ->> 'catalog_item_id', '')::uuid;
    clean_image_attachment_id := nullif(line ->> 'image_attachment_id', '')::uuid;

    if clean_name is null or char_length(clean_name) < 2 or char_length(clean_name) > 160 then
      raise exception 'Line % needs a name between 2 and 160 characters.', line_index + 1
        using errcode = 'check_violation';
    end if;
    if clean_category not in ('product', 'service') then
      raise exception 'Line % must be a product or a service.', line_index + 1
        using errcode = 'check_violation';
    end if;
    if clean_quantity <= 0 or clean_quantity > 1000000 then
      raise exception 'Line % needs a quantity above zero.', line_index + 1
        using errcode = 'check_violation';
    end if;
    if clean_price < 0 or clean_price > 1000000000000 or clean_cost < 0 or clean_cost > 1000000000000 then
      raise exception 'Line % has a price or cost outside the allowed range.', line_index + 1
        using errcode = 'check_violation';
    end if;

    -- An archived item is still readable, because old lines reference it, but it cannot start a new one.
    if clean_catalog_item_id is not null and not exists (
      select 1 from public.catalog_items
      where id = clean_catalog_item_id
        and organization_id = request_row.organization_id
        and archived_at is null
    ) then
      raise exception 'Line % points at a price list item that is no longer available.', line_index + 1
        using errcode = 'check_violation';
    end if;

    -- A line may only claim a photo that was actually uploaded for this request, not some other record the
    -- caller happens to know the id of.
    if clean_image_attachment_id is not null and not exists (
      select 1 from public.attachments
      where id = clean_image_attachment_id
        and organization_id = request_row.organization_id
        and entity_type = 'request'
        and entity_id = target_request_id
    ) then
      raise exception 'Line % points at an image that was not uploaded for this request.', line_index + 1
        using errcode = 'check_violation';
    end if;

    insert into public.request_pricing_lines (
      organization_id, request_id, position, catalog_item_id, category, is_labor,
      name, description, unit_label, quantity, unit_price_minor, unit_cost_minor, is_taxable,
      image_attachment_id
    ) values (
      request_row.organization_id,
      target_request_id,
      line_index,
      clean_catalog_item_id,
      clean_category,
      coalesce((line ->> 'is_labor')::boolean, false),
      clean_name,
      nullif(trim(coalesce(line ->> 'description', '')), ''),
      nullif(trim(coalesce(line ->> 'unit_label', '')), ''),
      clean_quantity,
      clean_price,
      clean_cost,
      coalesce((line ->> 'is_taxable')::boolean, true),
      clean_image_attachment_id
    );

    line_index := line_index + 1;
  end loop;

  select coalesce(sum(line_total_minor), 0), count(*)
  into new_subtotal, new_count
  from public.request_pricing_lines
  where organization_id = request_row.organization_id
    and request_id = target_request_id;

  update public.requests
  set pricing_revision = pricing_revision + 1,
      pricing_subtotal_minor = new_subtotal
  where id = target_request_id
  returning pricing_revision into new_revision;

  return jsonb_build_object(
    'revision', new_revision,
    'line_count', new_count,
    'subtotal_minor', new_subtotal
  );
end;
$$;


ALTER FUNCTION "public"."replace_request_pricing_lines"("target_request_id" "uuid", "expected_revision" integer, "new_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_automation_worker_wake"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_worker_name constant text := 'automation-worker';
  v_job_name constant text := 'automation-worker-wake-on-write';
  v_correlation uuid := gen_random_uuid();
  v_target_url text;
  v_bearer text;
  v_request_id bigint;
begin
  select decrypted_secret into v_target_url
  from vault.decrypted_secrets where name = 'automation_worker_target_url';
  select decrypted_secret into v_bearer
  from vault.decrypted_secrets where name = 'automation_worker_secret';

  if v_bearer is null or v_target_url is null or v_target_url !~ '^https?://[^[:space:]]+$' then
    return;
  end if;

  select net.http_post(
    url := v_target_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_bearer,
      'X-Wake-Correlation-Id', v_correlation::text
    ),
    body := jsonb_build_object('wake_correlation_id', v_correlation),
    timeout_milliseconds := 50000
  ) into v_request_id;

  perform public.record_automation_worker_wake_dispatch(
    v_worker_name, v_job_name, v_correlation, v_request_id
  );
exception
  when others then
    raise warning 'The immediate automation worker wake could not be dispatched: %', sqlerrm;
end;
$_$;


ALTER FUNCTION "public"."request_automation_worker_wake"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_automation_worker_wake"() IS 'Best-effort immediate automation wake for the write path. Refuses to dispatch to an unconfigured or placeholder URL and swallows every dispatch failure, so it can never roll back the write that fired it. The minute Cron sweep remains the guarantee and the SKIP LOCKED claim remains the exactly-once boundary.';



