CREATE OR REPLACE FUNCTION "public"."request_communication_sms_outbox_wake"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_worker_name constant text := 'communications-sms-outbox';
  v_job_name constant text := 'communications-sms-outbox-wake-on-insert';
  v_correlation uuid := gen_random_uuid();
  v_target_url text;
  v_bearer text;
  v_request_id bigint;
begin
  select decrypted_secret into v_target_url
  from vault.decrypted_secrets
  where name = 'communications_sms_worker_target_url';
  select decrypted_secret into v_bearer
  from vault.decrypted_secrets
  where name = 'communications_worker_secret';

  -- Not configured yet, or still the placeholder: stay silent. The minute Cron sweep is the guarantee.
  if v_bearer is null or v_target_url is null or v_target_url !~ '^https?://[^[:space:]]+$' then
    return;
  end if;

  select net.http_post(
    url := v_target_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_bearer,
      'X-Wake-Correlation-Id', v_correlation::text
    ),
    body := jsonb_build_object('wake_correlation_id', v_correlation),
    timeout_milliseconds := 50000
  ) into v_request_id;

  perform public.record_communication_worker_wake_dispatch(v_worker_name, v_job_name, v_correlation, v_request_id);
exception
  when others then
    -- Best-effort by contract. Never let a wake failure roll back the send that produced it.
    raise warning 'The immediate SMS outbox wake could not be dispatched: %', sqlerrm;
end;
$_$;


