CREATE OR REPLACE FUNCTION "public"."request_ownership_transfer"("target_organization_id" "uuid", "requesting_user_id" "uuid", "target_user_id" "uuid") RETURNS "public"."organization_ownership_transfers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  new_row public.organization_ownership_transfers;
begin
  -- Same key space convention as private.assert_employee_seat_available: two concurrent requests for one
  -- organization serialize instead of both reading "no pending transfer" and both inserting.
  perform pg_advisory_xact_lock(hashtext('ownership_transfer:' || target_organization_id::text));

  if not exists (
    select 1
    from public.organization_members as membership
    where membership.organization_id = target_organization_id
      and membership.user_id = requesting_user_id
      and membership.role = 'owner'
      and membership.status = 'active'
  ) then
    raise exception 'Only the current owner can hand over ownership.' using errcode = 'check_violation';
  end if;

  -- An active administrator, and nothing else. A pending invitee, a deactivated administrator, or someone
  -- on another role is refused here and again at acceptance.
  if not exists (
    select 1
    from public.organization_members as membership
    where membership.organization_id = target_organization_id
      and membership.user_id = target_user_id
      and membership.role = 'admin'
      and membership.status = 'active'
  ) then
    raise exception 'Ownership can only be handed to an active administrator.'
      using errcode = 'check_violation';
  end if;

  if exists (
    select 1
    from public.organization_ownership_transfers as transfer
    where transfer.organization_id = target_organization_id
      and transfer.state = 'pending'
  ) then
    raise exception 'There is already an ownership handover waiting for an answer.'
      using errcode = 'unique_violation';
  end if;

  insert into public.organization_ownership_transfers (organization_id, from_user_id, to_user_id)
  values (target_organization_id, requesting_user_id, target_user_id)
  returning * into new_row;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    target_organization_id, 'ownership.transfer_requested', 'member', requesting_user_id, target_user_id,
    jsonb_build_object('transfer_id', new_row.id)
  );

  return new_row;
end;
$$;


ALTER FUNCTION "public"."request_ownership_transfer"("target_organization_id" "uuid", "requesting_user_id" "uuid", "target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_ownership_transfer"("target_organization_id" "uuid", "requesting_user_id" "uuid", "target_user_id" "uuid") IS 'Records that the active owner asked an active administrator to take over. Changes no roles. Refuses a second pending handover for the same organization.';



CREATE OR REPLACE FUNCTION "public"."request_pricing_line_money"("target_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  org uuid;
  can_cost boolean;
  answer jsonb;
begin
  select request.organization_id into org
  from public.requests as request
  where request.id = target_request_id;

  if org is null then
    return '{}'::jsonb;
  end if;

  if not private.can_view_request(org, target_request_id) then
    raise exception 'You do not have access to this request.' using errcode = 'insufficient_privilege';
  end if;

  can_cost := private.member_has_permission(org, caller, 'quotes.view_cost');
  if not can_cost then
    return '{}'::jsonb;
  end if;

  select coalesce(jsonb_object_agg(line.id::text, jsonb_build_object(
      'unit_cost_minor', line.unit_cost_minor,
      'line_cost_total_minor', line.line_cost_total_minor
    )), '{}'::jsonb)
  into answer
  from public.request_pricing_lines as line
  where line.organization_id = org
    and line.request_id = target_request_id;

  return answer;
end;
$$;


ALTER FUNCTION "public"."request_pricing_line_money"("target_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_pricing_line_money"("target_request_id" "uuid") IS 'Cost for one request''s pricing lines, keyed by line id. Needs the same view access as the pricing read itself, plus quotes.view_cost to see the cost; a caller holding the first but not the second gets an empty object.';



CREATE OR REPLACE FUNCTION "public"."request_status_counts"("target_organization_id" "uuid", "day_start" timestamp with time zone, "day_end" timestamp with time zone) RETURNS TABLE("display_status" "text", "total" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    case
      when r.status in ('assessment_completed', 'completed', 'converted', 'archived') then r.status
      when a.id is null or a.completed_at is not null then r.status
      when a.starts_at is null then 'unscheduled'
      when a.starts_at >= day_end then 'upcoming'
      when a.starts_at < day_start then 'overdue'
      else 'today'
    end as display_status,
    count(*) as total
  from public.requests r
  left join public.assessments a
    on a.organization_id = r.organization_id
   and a.request_id = r.id
  where r.organization_id = target_organization_id
  group by 1;
$$;


ALTER FUNCTION "public"."request_status_counts"("target_organization_id" "uuid", "day_start" timestamp with time zone, "day_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reschedule_job_visits"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_recurrence" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  receipt_id uuid;
  existing_receipt public.job_command_receipts;
  removed_count integer;
  created_count integer;
  completed_kept integer;
  next_position integer;
  window_first date;
  window_last date;
  final_result jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to schedule a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.schedule') then
    raise exception 'You do not have access to schedule this job.' using errcode = 'insufficient_privilege';
  end if;

  if new_recurrence is null or jsonb_typeof(new_recurrence) is distinct from 'object' then
    raise exception 'A repeating job needs a repeat schedule.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(new_idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if char_length(trim(coalesce(new_request_hash, ''))) < 1 then
    raise exception 'A request fingerprint is required.' using errcode = 'check_violation';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id
    and job.id = target_job_id
  for update;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  if current_job.job_type <> 'recurring' then
    raise exception 'Only a recurring job has a repeating schedule to edit.' using errcode = 'check_violation';
  end if;
  if current_job.is_as_needed then
    raise exception 'An as-needed job is dispatched when work comes up and has no repeating schedule.'
      using errcode = 'check_violation';
  end if;
  if current_job.status <> 'active' then
    raise exception 'A closed job cannot be rescheduled. Reopen it first.' using errcode = 'check_violation';
  end if;

  insert into public.job_command_receipts (organization_id, action, idempotency_key, request_hash)
  values (target_organization_id, 'reschedule_job_visits', new_idempotency_key, new_request_hash)
  on conflict (organization_id, action, idempotency_key) do nothing
  returning id into receipt_id;

  if receipt_id is null then
    select receipt.* into existing_receipt
    from public.job_command_receipts as receipt
    where receipt.organization_id = target_organization_id
      and receipt.action = 'reschedule_job_visits'
      and receipt.idempotency_key = new_idempotency_key;

    if existing_receipt.request_hash is distinct from new_request_hash then
      raise exception 'This job was already rescheduled differently.' using errcode = 'P0409';
    end if;

    return coalesce(existing_receipt.result, '{}'::jsonb) || jsonb_build_object('applied', false);
  end if;

  if current_job.revision is distinct from expected_revision then
    raise exception 'Someone else changed this job. Reload to see the latest.' using errcode = 'P0409';
  end if;

  delete from public.job_visits
  where organization_id = target_organization_id
    and job_id = target_job_id
    and completed_at is null;
  get diagnostics removed_count = row_count;

  select count(*), coalesce(max(position), -1) + 1
  into completed_kept, next_position
  from public.job_visits
  where organization_id = target_organization_id
    and job_id = target_job_id;

  created_count := private.write_job_recurrence(
    target_organization_id, target_job_id, new_recurrence, next_position
  );

  select min(visit.visit_date), max(visit.visit_date)
  into window_first, window_last
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.completed_at is null;

  update public.jobs
  set revision = current_job.revision + 1,
      updated_at = now()
  where organization_id = target_organization_id
    and id = target_job_id;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'schedule_replaced',
    caller,
    jsonb_build_object(
      'removed_count', removed_count,
      'created_count', created_count,
      'completed_kept', completed_kept
    )
  );

  final_result := jsonb_build_object(
    'applied', true,
    'removed_count', removed_count,
    'created_count', created_count,
    'completed_kept', completed_kept,
    'first_date', window_first,
    'last_date', window_last,
    'revision', current_job.revision + 1
  );
  update public.job_command_receipts set result = final_result where id = receipt_id;
  return final_result;
end;
$$;


ALTER FUNCTION "public"."reschedule_job_visits"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_recurrence" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reschedule_job_visits"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_recurrence" "jsonb", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Replaces a scheduled recurring job''s repeat rule and rebuilds every incomplete visit from it, keeping completed visits. Checks jobs.schedule, refuses a one-off, an as-needed or a closed job, refuses a stale revision (P0409), is idempotent by key, and appends a schedule_replaced history row.';



CREATE OR REPLACE FUNCTION "public"."resend_communication_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_original_intent_id" "uuid", "target_logical_send_key" "text", "target_quote_url" "text" DEFAULT NULL::"text", "target_quote_token_hash" "bytea" DEFAULT NULL::"bytea") RETURNS "public"."communication_delivery_intents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  original public.communication_delivery_intents;
  outbox public.communication_outbox_events;
  result public.communication_delivery_intents;
begin
  if not private.member_has_permission(target_organization_id, target_actor_user_id, 'conversations.send') then
    raise exception 'You do not have permission to send a customer message.' using errcode = 'insufficient_privilege';
  end if;

  select * into original from public.communication_delivery_intents
    where organization_id = target_organization_id and id = target_original_intent_id
    for share;
  if original.id is null then
    raise exception 'The original message could not be found.' using errcode = 'no_data_found';
  end if;

  select * into outbox from public.communication_outbox_events
    where delivery_intent_id = original.id for share;

  if not (
    original.status = 'cancelled'
    or (original.status = 'failed' and (outbox.id is null or outbox.available_at = 'infinity'::timestamptz))
  ) then
    raise exception 'This message cannot be resent right now.' using errcode = 'object_not_in_prerequisite_state';
  end if;

  if original.quote_id is not null then
    if target_quote_url is null or target_quote_token_hash is null then
      raise exception 'The quote delivery link is not available.' using errcode = 'check_violation';
    end if;
    result := public.enqueue_quote_communication_email(
      target_organization_id, target_actor_user_id, original.quote_id,
      target_logical_send_key, target_quote_url, target_quote_token_hash
    );
  else
    result := public.enqueue_manual_communication_email(
      target_organization_id, target_actor_user_id, original.client_id, original.client_contact_method_id,
      target_logical_send_key, original.subject, original.html_content, original.text_content
    );
  end if;

  -- Unconditional, not "only if unset": a replay of the same resend key must return the existing row
  -- rather than silently losing it because the guard no longer matched.
  update public.communication_delivery_intents
    set resent_from_intent_id = original.id
    where id = result.id
    returning * into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."resend_communication_email"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_original_intent_id" "uuid", "target_logical_send_key" "text", "target_quote_url" "text", "target_quote_token_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resend_team_invitation"("target_invitation_id" "uuid", "target_token_hash" "text", "target_expires_at" timestamp with time zone, "target_resent_by" "uuid") RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated_row public.organization_member_invitations;
begin
  update public.organization_member_invitations
  set token_hash = target_token_hash,
      expires_at = target_expires_at,
      last_sent_at = null,
      last_delivery_error = null
  where id = target_invitation_id and state = 'invited'
  returning * into updated_row;

  if not found then
    raise exception 'Invitation % is not invited; it cannot be resent.', target_invitation_id
      using errcode = 'check_violation';
  end if;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_invitation_id, summary
  )
  values (
    updated_row.organization_id, 'invitation.resent', 'member', target_resent_by, updated_row.id, '{}'::jsonb
  );

  return updated_row;
end;
$$;


ALTER FUNCTION "public"."resend_team_invitation"("target_invitation_id" "uuid", "target_token_hash" "text", "target_expires_at" timestamp with time zone, "target_resent_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_stripe_payment_refund"("target_organization_id" "uuid", "target_payment_event_id" "uuid", "new_amount_minor" bigint, "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  receipt public.client_payment_events;
  checkout public.payment_stripe_checkouts;
  available bigint;
  pending_holds bigint;
  refund_row public.payment_stripe_refunds;
begin
  if caller is null then
    raise exception 'You must be signed in to refund a payment.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.correct_payment') then
    raise exception 'You do not have access to refund payments here.' using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  replayed := private.begin_invoice_command(
    target_organization_id, 'reserve_stripe_payment_refund', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  select * into receipt
  from public.client_payment_events
  where organization_id = target_organization_id and id = target_payment_event_id
  for update;
  if not found then
    raise exception 'That payment could not be found.' using errcode = 'P0404';
  end if;
  if receipt.event_type <> 'received' or receipt.method not in ('stripe_card', 'stripe_bank', 'stripe_other') then
    raise exception 'Only a payment collected through Stripe can be refunded this way.'
      using errcode = 'check_violation';
  end if;

  select * into checkout
  from public.payment_stripe_checkouts
  where organization_id = target_organization_id and payment_event_id = receipt.id and status = 'paid'
  order by completed_at desc
  limit 1
  for update;
  if checkout.id is null or checkout.payment_intent_id is null then
    raise exception 'This payment has no Stripe checkout to refund it through.' using errcode = 'P0404';
  end if;

  if new_amount_minor is null or new_amount_minor <= 0 then
    raise exception 'A refund amount must be more than zero.' using errcode = 'check_violation';
  end if;

  select coalesce(sum(hold.amount_minor), 0) into pending_holds
  from public.payment_stripe_refunds as hold
  where hold.organization_id = target_organization_id
    and hold.checkout_id = checkout.id
    and hold.status = 'pending';
  available := private.payment_event_available_minor(target_organization_id, receipt.id) - pending_holds;

  if new_amount_minor > available then
    raise exception 'That is more than this payment has left to refund.'
      using errcode = 'check_violation',
      detail = format('%s available, %s offered', available, new_amount_minor),
      hint = 'Money applied to an invoice must be taken off that invoice before it can be refunded.';
  end if;

  insert into public.payment_stripe_refunds (
    organization_id, checkout_id, requested_by, amount_minor, currency_code, status
  ) values (
    target_organization_id, checkout.id, caller, new_amount_minor, checkout.currency_code, 'pending'
  )
  returning * into refund_row;

  return private.complete_invoice_command(
    target_organization_id, 'reserve_stripe_payment_refund', new_idempotency_key,
    jsonb_build_object(
      'refund_id', refund_row.id,
      'checkout_id', checkout.id,
      'payment_intent_id', checkout.payment_intent_id,
      'stripe_account_id', checkout.stripe_account_id,
      'amount_minor', refund_row.amount_minor,
      'currency_code', refund_row.currency_code
    )
  );
end;
$$;


ALTER FUNCTION "public"."reserve_stripe_payment_refund"("target_organization_id" "uuid", "target_payment_event_id" "uuid", "new_amount_minor" bigint, "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reserve_stripe_payment_refund"("target_organization_id" "uuid", "target_payment_event_id" "uuid", "new_amount_minor" bigint, "new_idempotency_key" "text", "new_request_hash" "text") IS 'Holds an amount against a Stripe-collected payment before the server asks Stripe to send it back. Does not move any money itself -- apply_stripe_refund_event does that once Stripe confirms.';



CREATE OR REPLACE FUNCTION "public"."resolve_client_marketing_unsubscribe_link"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.client_marketing_unsubscribe_links;
  method_value text;
  business_name text;
  current_state text;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row
  from public.client_marketing_unsubscribe_links
  where token_hash = supplied_token_hash;

  if link_row.id is null then
    return null;
  end if;

  select method.value into method_value
  from public.client_contact_methods as method
  where method.organization_id = link_row.organization_id
    and method.id = link_row.client_contact_method_id;

  if method_value is null then
    return null;
  end if;

  select organization.name into business_name
  from public.organizations as organization
  where organization.id = link_row.organization_id;

  select state into current_state
  from public.client_marketing_consent_state
  where organization_id = link_row.organization_id
    and client_contact_method_id = link_row.client_contact_method_id;

  return jsonb_build_object(
    'business_name', business_name,
    'email', method_value,
    'already_unsubscribed', coalesce(current_state, 'unknown') = 'opted_out'
  );
end;
$$;


ALTER FUNCTION "public"."resolve_client_marketing_unsubscribe_link"("supplied_token_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_communication_sms_attachment_access_link"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.communication_sms_attachment_access_links;
  attachment_row public.communication_outbound_attachments;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row
  from public.communication_sms_attachment_access_links
  where token_hash = supplied_token_hash;
  if link_row.id is null then
    return null;
  end if;

  select * into attachment_row
  from public.communication_outbound_attachments
  where id = link_row.attachment_id and organization_id = link_row.organization_id;
  if attachment_row.id is null then
    return null;
  end if;

  update public.communication_sms_attachment_access_links
  set first_viewed_at = coalesce(first_viewed_at, now())
  where id = link_row.id;

  return jsonb_build_object(
    'object_key', attachment_row.object_key,
    'mime_type', attachment_row.mime_type,
    'file_name', attachment_row.file_name
  );
end;
$$;


ALTER FUNCTION "public"."resolve_communication_sms_attachment_access_link"("supplied_token_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_inbound_message_review"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_sender_email" "text", "target_resolution" "text", "target_client_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  pending_ids uuid[];
  linked_client_id uuid;
  contact_method public.client_contact_methods;
  fallback_sender_id uuid;
  needs_fallback_sender boolean;
  resolved_count integer;
begin
  if target_resolution not in ('link', 'dismiss') then
    raise exception 'Unknown review resolution.' using errcode = 'invalid_parameter_value';
  end if;

  if not private.member_has_permission(
    target_organization_id, target_actor_user_id, 'conversations.manage_assignment'
  ) then
    raise exception 'You do not have permission to manage conversations.' using errcode = 'insufficient_privilege';
  end if;

  if target_resolution = 'link'
    and not private.member_has_permission(target_organization_id, target_actor_user_id, 'customers.view') then
    raise exception 'You do not have permission to manage conversations.' using errcode = 'insufficient_privilege';
  end if;

  select array_agg(locked.id) into pending_ids
  from (
    select message.id
    from public.communication_inbound_messages message
    where message.organization_id = target_organization_id
      and lower(message.sender_email) = lower(btrim(target_sender_email))
      and message.review_status = 'pending_review'
    for update
  ) locked;

  if pending_ids is null then
    raise exception 'This conversation no longer needs review.' using errcode = 'object_not_in_prerequisite_state';
  end if;

  if target_resolution = 'dismiss' then
    update public.communication_inbound_messages
    set review_status = 'dismissed',
        review_resolved_at = now(),
        review_resolved_by = target_actor_user_id,
        updated_at = now()
    where id = any(pending_ids);

    get diagnostics resolved_count = row_count;
    return resolved_count;
  end if;

  if target_client_id is null then
    raise exception 'Choose a client to link this conversation to.' using errcode = 'invalid_parameter_value';
  end if;

  select client.id into linked_client_id
  from public.clients client
  where client.organization_id = target_organization_id
    and client.id = target_client_id
    and client.deleted_at is null
  for share of client;

  if linked_client_id is null then
    raise exception 'That client is not available.' using errcode = 'foreign_key_violation';
  end if;

  select method.* into contact_method
  from public.client_contact_methods method
  where method.organization_id = target_organization_id
    and method.client_id = target_client_id
    and method.kind = 'email'
    and method.normalized_value = lower(btrim(target_sender_email));

  if contact_method.id is null then
    insert into public.client_contact_methods (organization_id, client_id, kind, value, label, is_primary)
    values (
      target_organization_id, target_client_id, 'email', lower(btrim(target_sender_email)),
      'From Conversations', false
    )
    returning * into contact_method;
  end if;

  select exists (
    select 1
    from public.communication_inbound_messages message
    left join public.communication_reply_aliases alias on alias.id = message.reply_alias_id
    where message.id = any(pending_ids) and alias.sender_id is null
  ) into needs_fallback_sender;

  if needs_fallback_sender then
    select email_sender.id into fallback_sender_id
    from public.communication_email_senders email_sender
    where email_sender.organization_id = target_organization_id
      and email_sender.lifecycle_state = 'enabled'
    order by email_sender.is_organization_default desc, email_sender.created_at, email_sender.id
    limit 1;

    if fallback_sender_id is null then
      raise exception 'This organization has no active sending address to link the conversation to.'
        using errcode = 'object_not_in_prerequisite_state';
    end if;
  end if;

  update public.communication_inbound_messages message
  set client_id = target_client_id,
      client_contact_method_id = contact_method.id,
      sender_id = coalesce(
        (
          select alias.sender_id from public.communication_reply_aliases alias
          where alias.id = message.reply_alias_id
        ),
        fallback_sender_id
      ),
      review_status = 'accepted',
      review_resolved_at = now(),
      review_resolved_by = target_actor_user_id,
      updated_at = now()
  where message.id = any(pending_ids);

  get diagnostics resolved_count = row_count;
  return resolved_count;
end;
$$;


ALTER FUNCTION "public"."resolve_inbound_message_review"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_sender_email" "text", "target_resolution" "text", "target_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_invoice_access_link"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.invoice_access_links;
  invoice_row public.invoices;
  applied_minor bigint;
  derived_status text;
  business_name text;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row from public.invoice_access_links where token_hash = supplied_token_hash;
  if link_row.id is null
     or link_row.revoked_at is not null
     or (link_row.expires_at is not null and link_row.expires_at <= now()) then
    return null;
  end if;

  select * into invoice_row from public.invoices where id = link_row.invoice_id;
  if invoice_row.id is null
     or invoice_row.issued_at is null
     or invoice_row.voided_at is not null
     or invoice_row.replaced_at is not null then
    return null;
  end if;

  select coalesce(sum(case when entry.entry_type = 'applied'
    then entry.amount_minor else -entry.amount_minor end), 0)::bigint
  into applied_minor
  from public.invoice_payment_allocations as entry
  where entry.organization_id = invoice_row.organization_id and entry.invoice_id = invoice_row.id;

  derived_status := private.invoice_live_status(
    invoice_row.voided_at, invoice_row.written_off_at, invoice_row.issued_at, invoice_row.recognized_at,
    invoice_row.marked_received_at, invoice_row.total_minor, applied_minor, invoice_row.due_date,
    private.organization_today(invoice_row.organization_id));

  select organization.name into business_name
  from public.organizations as organization
  where organization.id = invoice_row.organization_id;

  return private.invoice_customer_document(invoice_row, business_name, derived_status, true);
end;
$$;


ALTER FUNCTION "public"."resolve_invoice_access_link"("supplied_token_hash" "bytea") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_invoice_access_link"("supplied_token_hash" "bytea") IS 'The customer''s reader. Hashed token in, one customer document out, or null for every failure alike. Service role only.';



CREATE OR REPLACE FUNCTION "public"."resolve_job_report_access_link"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.job_report_access_links;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row from public.job_report_access_links where token_hash = supplied_token_hash;
  if link_row.id is null
     or link_row.revoked_at is not null
     or (link_row.expires_at is not null and link_row.expires_at <= now()) then
    return null;
  end if;

  return link_row.frozen_document;
end;
$$;


