COMMENT ON FUNCTION "public"."resolve_job_report_access_link"("supplied_token_hash" "bytea") IS 'The customer''s reader. Hashed token in, the document frozen onto this link at issue out, or null for every failure alike -- unknown, revoked, or expired. Service role only: not part of the Data API for anybody else.';



CREATE OR REPLACE FUNCTION "public"."resolve_payment_receipt_access_link"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.payment_receipt_access_links;
  receipt public.client_payment_events;
  business_name text;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row from public.payment_receipt_access_links where token_hash = supplied_token_hash;
  if link_row.id is null
     or link_row.revoked_at is not null
     or (link_row.expires_at is not null and link_row.expires_at <= now()) then
    return null;
  end if;

  select * into receipt from public.client_payment_events where id = link_row.client_payment_event_id;
  if receipt.id is null or receipt.event_type <> 'received' then
    return null;
  end if;

  select organization.name into business_name
  from public.organizations as organization
  where organization.id = receipt.organization_id;

  return private.payment_receipt_document(receipt, business_name);
end;
$$;


ALTER FUNCTION "public"."resolve_payment_receipt_access_link"("supplied_token_hash" "bytea") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_payment_receipt_access_link"("supplied_token_hash" "bytea") IS 'The customer''s reader for a payment receipt. Hashed token in, one receipt document out, or null for every failure alike. Service role only: not part of the Data API for anybody else.';



CREATE OR REPLACE FUNCTION "public"."resolve_quote_access_link"("supplied_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.quote_access_links;
  quote_row public.quotes;
  version_row public.quote_versions;
  recipient_row public.quote_recipients;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row from public.quote_access_links where token_hash = supplied_token_hash;
  if link_row.id is null or link_row.revoked_at is not null then
    return null;
  end if;

  if link_row.expires_at is not null and link_row.expires_at <= now() then
    return jsonb_build_object('expired', true);
  end if;

  select * into quote_row from public.quotes where id = link_row.quote_id;
  if quote_row.id is null
     or quote_row.status = 'archived'
     or quote_row.current_published_version_id is distinct from link_row.quote_version_id then
    return null;
  end if;

  select * into version_row from public.quote_versions where id = link_row.quote_version_id;
  if version_row.id is null or version_row.status <> 'published' then
    return null;
  end if;

  select * into recipient_row from public.quote_recipients where id = link_row.recipient_id;

  return private.quote_customer_document(
    quote_row, version_row, recipient_row.display_name, recipient_row.email, true
  );
end;
$$;


ALTER FUNCTION "public"."resolve_quote_access_link"("supplied_token_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_quote_access_link_logo"("supplied_token_hash" "bytea") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.quote_access_links;
  quote_row public.quotes;
  version_row public.quote_versions;
begin
  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row from public.quote_access_links where token_hash = supplied_token_hash;
  if link_row.id is null or link_row.revoked_at is not null then
    return null;
  end if;

  if link_row.expires_at is not null and link_row.expires_at <= now() then
    return null;
  end if;

  select * into quote_row from public.quotes where id = link_row.quote_id;
  if quote_row.id is null
     or quote_row.status = 'archived'
     or quote_row.current_published_version_id is distinct from link_row.quote_version_id then
    return null;
  end if;

  select * into version_row from public.quote_versions where id = link_row.quote_version_id;
  if version_row.id is null or version_row.status <> 'published' then
    return null;
  end if;

  return version_row.logo_object_key;
end;
$$;


