CREATE OR REPLACE FUNCTION "public"."resolve_website_chat_session_identity"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_session_id" "uuid", "target_client_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    SET "statement_timeout" TO '5000'
    AS $$
declare
  target_session public.website_chat_sessions;
  chosen_client_id uuid;
  backfilled_count integer;
begin
  if not private.member_has_permission(
    target_organization_id, target_actor_user_id, 'conversations.manage_assignment'
  ) then
    raise exception 'You do not have permission to manage conversations.'
      using errcode = 'insufficient_privilege';
  end if;

  if not private.member_has_permission(
    target_organization_id, target_actor_user_id, 'customers.view'
  ) then
    raise exception 'You do not have permission to manage conversations.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into target_session
  from public.website_chat_sessions s
  where s.organization_id = target_organization_id and s.id = target_session_id
  for update;
  if not found then
    raise exception 'That conversation is not available.' using errcode = 'foreign_key_violation';
  end if;

  if target_session.match_status <> 'needs_review' then
    raise exception 'This conversation no longer needs review.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;

  select c.id into chosen_client_id
  from public.clients c
  where c.organization_id = target_organization_id
    and c.id = target_client_id
    and c.deleted_at is null
  for share of c;

  if chosen_client_id is null then
    raise exception 'That client is not available.' using errcode = 'foreign_key_violation';
  end if;

  update public.website_chat_sessions
  set match_status = 'resolved',
      client_id = chosen_client_id
  where id = target_session.id;

  update public.website_chat_messages
  set client_id = chosen_client_id
  where organization_id = target_organization_id
    and session_id = target_session.id
    and client_id is null;

  get diagnostics backfilled_count = row_count;

  return jsonb_build_object(
    'status', 'resolved',
    'session_id', target_session.id,
    'client_id', chosen_client_id,
    'messages_backfilled', backfilled_count
  );
end;
$$;


ALTER FUNCTION "public"."resolve_website_chat_session_identity"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_session_id" "uuid", "target_client_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_website_chat_session_identity"("target_organization_id" "uuid", "target_actor_user_id" "uuid", "target_session_id" "uuid", "target_client_id" "uuid") IS 'Assigns a conflicting-identity Website Chat session to the Client a person chose, and backfills client_id onto that session''s messages so the whole thread joins that contact''s history.';



CREATE OR REPLACE FUNCTION "public"."restore_form"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  form_row public.forms;
begin
  if not private.has_permission(target_organization_id, 'settings.forms.manage') then
    raise exception 'You do not have access to manage forms.' using errcode = 'insufficient_privilege';
  end if;

  select * into form_row from public.forms
  where id = target_form_id and organization_id = target_organization_id
  for update;

  if form_row.id is null then
    raise exception 'That form was not found.' using errcode = 'check_violation';
  end if;
  if expected_revision is distinct from form_row.revision then
    raise exception 'Someone else changed this form while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;
  if form_row.archived_at is null then
    return jsonb_build_object('form_id', form_row.id, 'archived', false, 'revision', form_row.revision);
  end if;

  update public.forms
  set archived_at = null, revision = revision + 1, updated_by = (select auth.uid()), updated_at = now()
  where id = form_row.id
  returning * into form_row;

  return jsonb_build_object('form_id', form_row.id, 'archived', false, 'revision', form_row.revision);
end;
$$;


ALTER FUNCTION "public"."restore_form"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_invoice_from_write_off"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  invoice_row public.invoices;
  restored_minor bigint;
begin
  if caller is null then
    raise exception 'You must be signed in to undo a write-off.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.bad_debt') then
    raise exception 'You do not have access to undo write-offs here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  replayed := private.begin_invoice_command(
    target_organization_id, 'restore_invoice_from_write_off', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  invoice_row := private.lock_invoice_for_payment(target_organization_id, target_invoice_id);

  if invoice_row.written_off_at is null then
    raise exception 'This bill is not written off.' using errcode = 'check_violation';
  end if;

  restored_minor := invoice_row.total_minor
    - private.invoice_allocated_minor(target_organization_id, invoice_row.id);

  update public.invoices
  set written_off_at = null,
      written_off_by = null,
      write_off_note = null,
      revision = invoice_row.revision + 1,
      updated_at = now()
  where organization_id = target_organization_id and id = invoice_row.id;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.write_off_reversed', caller, invoice_row.revision + 1, new_reason,
    jsonb_build_object('restored_minor', restored_minor), true, null
  );

  return private.complete_invoice_command(
    target_organization_id, 'restore_invoice_from_write_off', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', invoice_row.id,
      'invoice_number', invoice_row.invoice_number,
      'client_id', invoice_row.client_id,
      'restored_minor', restored_minor
    )
  );
end;
$$;


ALTER FUNCTION "public"."restore_invoice_from_write_off"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_invoice_from_write_off"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Undoes a write-off, putting the bill''s remaining balance back into what the client owes. The write-off and the undo both stay in the invoice''s history.';



CREATE OR REPLACE FUNCTION "public"."restore_quote"("target_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  restored_status text;
begin
  select * into quote_row from public.quotes where id = target_quote_id for update;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.edit'
     ) then
    raise exception 'You do not have access to restore this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.status <> 'archived' then
    return jsonb_build_object('applied', false, 'status', quote_row.status);
  end if;

  restored_status := coalesce(quote_row.previous_status, 'draft');
  if restored_status not in ('draft', 'awaiting_response', 'changes_requested', 'approved', 'declined') then
    restored_status := 'draft';
  end if;

  update public.quotes
  set status = restored_status,
      previous_status = null,
      archived_at = null,
      archive_reason = null
  where id = quote_row.id;

  return jsonb_build_object('applied', true, 'status', restored_status);
end;
$$;


ALTER FUNCTION "public"."restore_quote"("target_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_team_member"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members;
begin
  membership := private.authorize_team_member_command(
    target_organization_id, actor_user_id, target_user_id
  );

  if membership.status = 'removed' then
    raise exception 'A permanently removed person cannot be restored. Invite them again instead.'
      using errcode = 'check_violation';
  end if;

  if membership.status <> 'deactivated' then
    raise exception 'That person is not deactivated.' using errcode = 'check_violation';
  end if;

  -- Takes the organization's advisory lock, so two restores cannot both read the last free seat.
  perform private.assert_employee_seat_available(target_organization_id);

  update public.organization_members as membership_row
  set status = 'active',
      deactivated_at = null,
      status_changed_at = now(),
      status_changed_by = actor_user_id,
      access_revision = membership_row.access_revision + 1
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  returning * into membership;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    target_organization_id, 'member.restored', 'member', actor_user_id, target_user_id,
    jsonb_build_object('restored_role', membership.role)
  );

  return membership;
end;
$$;


ALTER FUNCTION "public"."restore_team_member"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_team_member"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid") IS 'Brings a deactivated member back with the role they had, taking a seat. Refused when the organization has none free. Old work assignments are not restored -- that is deliberate.';



CREATE OR REPLACE FUNCTION "public"."resume_automation_enrollment"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  existing_receipt public.automation_enrollment_command_receipts%rowtype;
  enrollment private.automation_enrollments%rowtype;
  recipe_status text;
  resume_due timestamptz;
  command_result jsonb;
begin
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;

  select * into existing_receipt
  from public.automation_enrollment_command_receipts
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_receipt.result || jsonb_build_object('idempotent_replay', true);
  end if;

  select * into enrollment
  from private.automation_enrollments
  where id = p_enrollment_id and organization_id = p_organization_id
  for update;
  if not found then
    raise exception 'That enrollment does not exist.' using errcode = 'no_data_found';
  end if;
  if enrollment.state <> 'paused' then
    raise exception 'Only a paused enrollment can be resumed.' using errcode = 'restrict_violation';
  end if;

  select status into recipe_status
  from public.automation_recipes
  where id = enrollment.recipe_id and organization_id = p_organization_id;
  if recipe_status is distinct from 'active' then
    raise exception 'This automation is not active, so it cannot be resumed.' using errcode = 'restrict_violation';
  end if;

  resume_due := coalesce(enrollment.paused_work_due_at, now());

  update private.automation_work_items
  set state = 'pending', due_at = resume_due, available_at = resume_due,
      claim_token = null, claimed_at = null
  where enrollment_id = p_enrollment_id and step_index = enrollment.current_step_index;

  if not found then
    insert into private.automation_work_items (
      organization_id, enrollment_id, step_index, due_at, available_at
    ) values (
      p_organization_id, p_enrollment_id, enrollment.current_step_index, resume_due, resume_due
    )
    on conflict (enrollment_id, step_index) do nothing;
  end if;

  update private.automation_enrollments
  set state = 'active', paused_work_due_at = null
  where id = p_enrollment_id;

  perform public.request_automation_worker_wake();

  command_result := jsonb_build_object(
    'enrollment_id', p_enrollment_id, 'state', 'active', 'next_due_at', resume_due
  );

  insert into public.automation_enrollment_command_receipts (
    organization_id, idempotency_key, command, subject_type, subject_id, enrollment_id, result
  ) values (
    p_organization_id, p_idempotency_key, 'resume', enrollment.subject_type, enrollment.subject_id,
    p_enrollment_id, command_result
  );

  return command_result;
end;
$$;


ALTER FUNCTION "public"."resume_automation_enrollment"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resume_automation_enrollment"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_idempotency_key" "uuid") IS 'Resumes a paused enrollment at the step''s original due time (already past -> next worker cycle). Idempotent per organization + key. Service role only.';



CREATE OR REPLACE FUNCTION "public"."resume_automation_work_items"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_attention_reason" "text" DEFAULT NULL::"text", "p_batch_size" integer DEFAULT 100) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  resumed_count integer;
begin
  if p_batch_size < 1 or p_batch_size > 1000 then
    raise exception 'The resume batch size is outside its safe bounds.' using errcode = 'check_violation';
  end if;

  with resumable as (
    select w.id
    from private.automation_work_items as w
    join private.automation_enrollments as e on e.id = w.enrollment_id
    where w.state = 'needs_attention'
      and e.state = 'active'
      and (p_organization_id is null or w.organization_id = p_organization_id)
      and (p_attention_reason is null or w.attention_reason = p_attention_reason)
    order by w.organization_id, w.attention_at, w.id
    limit p_batch_size
    for update of w skip locked
  )
  update private.automation_work_items as w
  set state = 'pending',
    attention_reason = null,
    attention_at = null,
    attempts = 0,
    available_at = now(),
    claim_token = null,
    claimed_at = null,
    last_error_code = null,
    last_error_message = null
  from resumable
  where w.id = resumable.id;

  get diagnostics resumed_count = row_count;
  return resumed_count;
end;
$$;


ALTER FUNCTION "public"."resume_automation_work_items"("p_organization_id" "uuid", "p_attention_reason" "text", "p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resume_automation_work_items"("p_organization_id" "uuid", "p_attention_reason" "text", "p_batch_size" integer) IS 'Returns parked work to the claimable queue with a fresh attempt budget; every safety check runs again on the next claim. Skips rows whose enrollment is no longer active. Service role only until 6D-5.';



CREATE OR REPLACE FUNCTION "public"."resume_communication_email_reputation_pause"("p_organization_id" "uuid", "p_reason" "text", "p_actor_email" "text", "p_confirm_remediation" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  actor text := lower(btrim(coalesce(p_actor_email, '')));
  clean_reason text := btrim(coalesce(p_reason, ''));
  existing public.communication_email_sending_pauses%rowtype;
  still_breaching boolean;
  expired_count integer := 0;
begin
  if char_length(actor) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if char_length(clean_reason) not between 3 and 500 then
    raise exception 'A reason of 3 to 500 characters is required.' using errcode = 'check_violation';
  end if;

  select * into existing
  from public.communication_email_sending_pauses
  where scope = 'organization' and organization_id = p_organization_id
    and source = 'auto_reputation' and released_at is null
  for update;
  if not found then
    return jsonb_build_object('released', false, 'reason_code', 'no_active_reputation_pause');
  end if;

  select exists (
    select 1 from private.communication_email_reputation_metrics(p_organization_id, now()) m
    where m.status = 'pause'
  ) into still_breaching;

  if still_breaching and not coalesce(p_confirm_remediation, false) then
    raise exception 'This organization is still at or above a pause threshold. Confirm remediation review to resume.'
      using errcode = 'check_violation';
  end if;

  update public.communication_email_sending_pauses
  set released_at = now(), released_by_owner_email = actor, released_reason = clean_reason
  where id = existing.id;

  with stale as (
    select event.id as event_id, intent.id as intent_id
    from public.communication_outbox_events event
    join public.communication_delivery_intents intent on intent.id = event.delivery_intent_id
    where event.status in ('pending', 'failed')
      and intent.organization_id = p_organization_id
      and intent.allowance_class = 'optional'
      and intent.failure_code = 'sending_paused_reputation'
      and intent.created_at < now() - interval '24 hours'
  ),
  cancelled_intents as (
    update public.communication_delivery_intents intent
    set status = 'cancelled', provider_message_id = null, accepted_at = null,
      failure_code = 'optional_expired_during_pause',
      failure_message = 'Optional email expired while sending was paused and was not delivered.'
    from stale
    where intent.id = stale.intent_id
    returning intent.id
  ),
  cancelled_events as (
    update public.communication_outbox_events event
    set status = 'cancelled', claimed_at = null, claim_token = null,
      last_error = 'Optional email expired while sending was paused and was not delivered.'
    from stale
    where event.id = stale.event_id
    returning event.id
  )
  select count(*)::integer into expired_count from cancelled_events;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor, 'communications.email_reputation_pause_released', 'organization', p_organization_id::text,
    jsonb_build_object('pause_id', existing.id, 'engaged_reason', existing.reason,
      'evidence', existing.evidence),
    jsonb_build_object('released_reason', clean_reason, 'still_breaching', still_breaching,
      'remediation_confirmed', coalesce(p_confirm_remediation, false),
      'expired_optional_messages', expired_count)
  );

  return jsonb_build_object('released', true, 'pause_id', existing.id,
    'still_breaching', still_breaching, 'expired_optional_messages', expired_count);
end;
$$;


ALTER FUNCTION "public"."resume_communication_email_reputation_pause"("p_organization_id" "uuid", "p_reason" "text", "p_actor_email" "text", "p_confirm_remediation" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_automation_work_item"("p_work_item_id" "uuid", "p_claim_token" "uuid", "p_error_code" "text", "p_error_message" "text", "p_permanent" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  item private.automation_work_items%rowtype;
begin
  select * into item
  from private.automation_work_items
  where id = p_work_item_id and claim_token = p_claim_token and state = 'pending'
  for update;

  if not found then
    return 'claim_lost';
  end if;

  if p_permanent then
    update private.automation_work_items
    set state = 'needs_attention',
      attention_reason = left(coalesce(nullif(btrim(p_error_code), ''), 'permanent_failure'), 100),
      attention_at = now(),
      last_error_code = left(nullif(btrim(p_error_code), ''), 100),
      last_error_message = left(nullif(btrim(p_error_message), ''), 1000),
      claim_token = null,
      claimed_at = null
    where id = item.id;
    return 'parked';
  end if;

  update private.automation_work_items
  set available_at = now() + private.automation_retry_delay(item.attempts),
    last_error_code = left(nullif(btrim(p_error_code), ''), 100),
    last_error_message = left(nullif(btrim(p_error_message), ''), 1000),
    claim_token = null,
    claimed_at = null
  where id = item.id;
  return 'retry_scheduled';
end;
$$;


ALTER FUNCTION "public"."retry_automation_work_item"("p_work_item_id" "uuid", "p_claim_token" "uuid", "p_error_code" "text", "p_error_message" "text", "p_permanent" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."retry_automation_work_item"("p_work_item_id" "uuid", "p_claim_token" "uuid", "p_error_code" "text", "p_error_message" "text", "p_permanent" boolean) IS 'Records a failed transition: backs the row off with jittered exponential delay, or parks it for attention when the failure is permanent. Claim-token guarded. Service role only.';



CREATE OR REPLACE FUNCTION "public"."retry_communication_message"("p_delivery_intent_id" "uuid", "p_reason" "text", "p_actor_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  outbox public.communication_outbox_events;
  intent public.communication_delivery_intents;
  clean_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  clean_actor text := nullif(btrim(coalesce(p_actor_email, '')), '');
begin
  if clean_actor is null then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if clean_reason is null or char_length(clean_reason) < 3 or char_length(clean_reason) > 1000 then
    raise exception 'A reason of 3 to 1000 characters is required.' using errcode = 'check_violation';
  end if;

  select * into outbox from public.communication_outbox_events
  where delivery_intent_id = p_delivery_intent_id for update;
  if outbox.id is null then
    raise exception 'That message was not found.' using errcode = 'no_data_found';
  end if;
  select * into intent from public.communication_delivery_intents
  where id = p_delivery_intent_id for update;

  if outbox.status = 'submitted' then
    raise exception 'That message was already accepted by the provider.'
      using errcode = 'check_violation';
  end if;
  if outbox.status = 'processing' then
    raise exception 'That message is being sent right now.' using errcode = 'check_violation';
  end if;
  if outbox.status = 'cancelled' then
    raise exception 'That message was cancelled. Send it again instead of retrying it.'
      using errcode = 'check_violation';
  end if;

  if outbox.status = 'pending' and outbox.available_at <= now() then
    return jsonb_build_object('changed', false, 'delivery_intent_id', p_delivery_intent_id,
      'outbox_status', outbox.status, 'available_at', outbox.available_at);
  end if;

  update public.communication_outbox_events
  set status = 'pending', available_at = now(), claimed_at = null, claim_token = null,
    last_error = null
  where id = outbox.id;

  update public.communication_delivery_intents
  set status = 'queued', failure_code = null, failure_message = null
  where id = intent.id;

  perform private.record_communication_message_event(
    p_organization_id => intent.organization_id,
    p_delivery_intent_id => intent.id,
    p_event_kind => 'administrative_intervention',
    p_attempt_number => outbox.attempt_count,
    p_reason_code => 'platform_owner_retry',
    p_reason_message => clean_reason,
    p_actor_kind => 'platform_owner',
    p_actor_email => clean_actor
  );

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    clean_actor, 'communications.message_retried', 'communication_delivery_intent', intent.id::text,
    jsonb_build_object('organization_id', intent.organization_id, 'intent_status', intent.status,
      'outbox_status', outbox.status, 'failure_code', intent.failure_code,
      'attempt_count', outbox.attempt_count),
    jsonb_build_object('intent_status', 'queued', 'outbox_status', 'pending', 'reason', clean_reason)
  );

  return jsonb_build_object('changed', true, 'delivery_intent_id', intent.id,
    'outbox_status', 'pending', 'available_at', now());
end;
$$;


ALTER FUNCTION "public"."retry_communication_message"("p_delivery_intent_id" "uuid", "p_reason" "text", "p_actor_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_client_payment"("target_organization_id" "uuid", "target_payment_event_id" "uuid", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  original public.client_payment_events;
  available bigint;
  reversal public.client_payment_events;
begin
  if caller is null then
    raise exception 'You must be signed in to correct a payment.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.correct_payment') then
    raise exception 'You do not have access to correct payments here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  replayed := private.begin_invoice_command(
    target_organization_id, 'reverse_client_payment', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  select * into original
  from public.client_payment_events
  where organization_id = target_organization_id and id = target_payment_event_id
  for update;
  if not found then
    raise exception 'That payment could not be found.' using errcode = 'P0404';
  end if;

  if original.event_type = 'reversed' then
    raise exception 'A correction cannot itself be corrected away.' using errcode = 'check_violation';
  end if;
  if exists (
    select 1 from public.client_payment_events as existing
    where existing.organization_id = target_organization_id
      and existing.original_event_id = original.id
      and existing.event_type = 'reversed'
  ) then
    raise exception 'That entry has already been corrected.' using errcode = 'check_violation';
  end if;

  -- A receipt may only be taken back while it is untouched. Anything else has to be unwound explicitly,
  -- which is exactly what the unapply and refund commands are for.
  if original.event_type = 'received' then
    available := private.payment_event_available_minor(target_organization_id, original.id);
    if available <> original.amount_minor then
      raise exception 'That payment has already been used, so it cannot be marked as never received.'
        using errcode = 'check_violation',
        hint = 'Take it off any invoices, and undo any refund of it, before correcting it away.';
    end if;
  end if;

  insert into public.client_payment_events (
    organization_id, client_id, event_type, amount_minor, currency_code, method, payment_date,
    reference, note, actor_user_id, original_event_id
  ) values (
    target_organization_id, original.client_id, 'reversed', original.amount_minor, original.currency_code,
    null, private.organization_today(target_organization_id),
    original.reference, nullif(trim(coalesce(new_note, '')), ''), caller, original.id
  )
  returning * into reversal;

  return private.complete_invoice_command(
    target_organization_id, 'reverse_client_payment', new_idempotency_key,
    jsonb_build_object(
      'reversal_event_id', reversal.id,
      'original_event_id', original.id,
      'original_event_type', original.event_type,
      'client_id', reversal.client_id,
      'amount_minor', reversal.amount_minor,
      'currency_code', reversal.currency_code
    )
  );
end;
$$;


ALTER FUNCTION "public"."reverse_client_payment"("target_organization_id" "uuid", "target_payment_event_id" "uuid", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reverse_client_payment"("target_organization_id" "uuid", "target_payment_event_id" "uuid", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Records that a payment or a refund never actually happened, by appending a reversing row that points at it. The original stays visible. A receipt can only be reversed while nothing is sitting on a bill and nothing has been refunded out of it.';



CREATE OR REPLACE FUNCTION "public"."reverse_onboarding_application_payment"("target_application_id" "uuid", "actor_email" "text", "reason" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  app record;
  confirmation record;
begin
  select stage, payment_reversed_at
  into app
  from public.platform_onboarding_applications
  where id = target_application_id
  for update;

  if not found then
    raise exception 'The onboarding application does not exist.' using errcode = 'foreign_key_violation';
  end if;
  if app.stage not in ('payment_confirmed', 'needs_attention') then
    raise exception 'Only a confirmed payment can be reversed.' using errcode = 'check_violation';
  end if;
  if app.payment_reversed_at is not null then
    raise exception 'This payment was already reversed.' using errcode = 'check_violation';
  end if;

  select id, amount_usd_cents
  into confirmation
  from public.platform_onboarding_application_payment_confirmations
  where application_id = target_application_id
  order by confirmed_at desc
  limit 1;

  if not found then
    raise exception 'No payment confirmation exists for this application.' using errcode = 'check_violation';
  end if;

  insert into public.platform_onboarding_application_payment_reversals (
    application_id, confirmation_id, actor_owner_email, reason, reversed_amount_usd_cents
  ) values (
    target_application_id, confirmation.id, actor_email, reason, confirmation.amount_usd_cents
  );

  update public.platform_onboarding_applications
  set stage = 'needs_attention', payment_reversed_at = now()
  where id = target_application_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, after_state
  ) values (
    actor_email, 'onboarding_application.payment_reversed', 'onboarding_application',
    target_application_id::text,
    jsonb_build_object('reason', reason, 'reversed_amount_usd_cents', confirmation.amount_usd_cents)
  );
end;
$$;


ALTER FUNCTION "public"."reverse_onboarding_application_payment"("target_application_id" "uuid", "actor_email" "text", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_quote_deposit_event"("target_quote_id" "uuid", "target_event_id" "uuid", "idempotency_key" "text", "reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  original_event public.quote_deposit_events;
  existing_reversal public.quote_deposit_events;
  inserted_event public.quote_deposit_events;
  clean_reason text := nullif(trim(coalesce(reason, '')), '');
begin
  if char_length(trim(coalesce(idempotency_key, ''))) < 8 then
    raise exception 'A valid idempotency key is required.' using errcode = 'check_violation';
  end if;
  if clean_reason is null then
    raise exception 'Say why this deposit is being reversed.' using errcode = 'check_violation';
  end if;

  select * into quote_row from public.quotes where id = target_quote_id for update;
  if quote_row.id is null or not private.member_has_permission(
    quote_row.organization_id, (select auth.uid()), 'quotes.record_deposit'
  ) then
    raise exception 'You do not have access to reverse a deposit on this quote.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into existing_reversal
  from public.quote_deposit_events
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and quote_deposit_events.idempotency_key = reverse_quote_deposit_event.idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_reversal.id);
  end if;

  select * into original_event
  from public.quote_deposit_events
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and id = target_event_id
  for update;

  if original_event.id is null or original_event.event_type <> 'received' then
    raise exception 'That deposit record could not be found.' using errcode = 'check_violation';
  end if;
  if exists (
    select 1 from public.quote_deposit_events reversal
    where reversal.organization_id = original_event.organization_id
      and reversal.reversed_event_id = original_event.id
  ) then
    raise exception 'This deposit was already reversed.' using errcode = 'check_violation';
  end if;

  insert into public.quote_deposit_events (
    organization_id, quote_id, quote_version_id, event_type, amount_minor, method, reference, note,
    actor_user_id, reversed_event_id, idempotency_key
  ) values (
    quote_row.organization_id, quote_row.id, original_event.quote_version_id, 'reversed',
    original_event.amount_minor, original_event.method, original_event.reference, clean_reason,
    (select auth.uid()), original_event.id, idempotency_key
  ) returning * into inserted_event;

  return jsonb_build_object('applied', true, 'event_id', inserted_event.id);
end;
$$;


ALTER FUNCTION "public"."reverse_quote_deposit_event"("target_quote_id" "uuid", "target_event_id" "uuid", "idempotency_key" "text", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_import_batch"("payload" "jsonb") RETURNS "public"."import_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_batch_id uuid := (payload->>'batch_id')::uuid;
  target_batch public.import_batches;
begin
  if target_batch_id is null then
    raise exception 'batch_id is required.' using errcode = 'invalid_parameter_value';
  end if;

  select * into target_batch from public.import_batches where id = target_batch_id for update;
  if not found then
    raise exception 'That import was not found.' using errcode = 'no_data_found';
  end if;

  if not private.has_permission(
    target_batch.organization_id, private.import_batch_entity_permission(target_batch.entity_type)
  ) then
    raise exception 'You do not have permission to change this import.'
      using errcode = 'insufficient_privilege';
  end if;

  if target_batch.status not in ('mapped', 'reviewed') then
    raise exception 'This import can no longer be reviewed.'
      using errcode = 'invalid_parameter_value';
  end if;

  delete from public.import_rows where batch_id = target_batch_id;

  insert into public.import_rows (
    organization_id,
    batch_id,
    source_row_number,
    raw,
    planned_action,
    resolved_payload,
    match_client_id,
    match_reason,
    flags,
    error_message
  )
  select
    target_batch.organization_id,
    target_batch_id,
    row_in.source_row_number,
    row_in.raw,
    row_in.planned_action,
    row_in.resolved_payload,
    row_in.match_client_id,
    row_in.match_reason,
    coalesce(row_in.flags, '{}'),
    row_in.error_message
  from jsonb_to_recordset(coalesce(payload->'rows', '[]'::jsonb)) as row_in(
    source_row_number integer,
    raw jsonb,
    planned_action text,
    resolved_payload jsonb,
    match_client_id uuid,
    match_reason text,
    flags text[],
    error_message text
  );

  update public.import_batches
  set status = 'reviewed'
  where id = target_batch_id
  returning * into target_batch;

  return target_batch;
end;
$$;


ALTER FUNCTION "public"."review_import_batch"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_import_batch"("payload" "jsonb") IS 'Replaces a batch''s dry-run rows with the freshly computed set and moves it mapped/reviewed -> reviewed. Entity-agnostic: the write permission it backstops against comes from private.import_batch_entity_permission(batch.entity_type), not a hardcoded key.';



CREATE OR REPLACE FUNCTION "public"."revise_quote"("target_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  cloned jsonb;
begin
  select * into quote_row from public.quotes where id = target_quote_id for update;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.edit'
     ) then
    raise exception 'You do not have access to revise this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.status not in ('awaiting_response', 'changes_requested', 'approved', 'declined') then
    raise exception 'Only a quote the customer already has can be revised.' using errcode = 'check_violation';
  end if;

  cloned := public.clone_quote_version_to_draft(quote_row.id);

  update public.quotes
  set status = 'draft',
      decision = null, decided_at = null, decision_method = null,
      decision_note = null, decided_by = null
  where id = quote_row.id;

  -- The answer stays in history. It simply stops being the answer, because it was about a document that
  -- is no longer the one on the table.
  update public.quote_decisions
  set is_current = false
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and is_current;

  update public.quote_access_links
  set revoked_at = now(), revoked_reason = 'rotated'
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and revoked_at is null;

  insert into public.activity_events (
    organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
  ) values (
    quote_row.organization_id, 'quote', quote_row.id, 'quote.revised',
    'Started a new draft from the sent version', (select auth.uid()),
    jsonb_build_object('quote_version_id', cloned ->> 'quote_version_id')
  );

  return cloned || jsonb_build_object('status', 'draft');
end;
$$;


ALTER FUNCTION "public"."revise_quote"("target_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_job_report_access_link"("target_link_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  link_row public.job_report_access_links;
begin
  select * into link_row from public.job_report_access_links where id = target_link_id for update;

  if link_row.id is null
     or not private.member_has_permission(link_row.organization_id, caller, 'jobs.edit')
     or not private.can_view_job(link_row.organization_id, link_row.job_id) then
    raise exception 'You do not have access to change this link.' using errcode = 'insufficient_privilege';
  end if;

  if link_row.revoked_at is not null then
    return jsonb_build_object(
      'job_report_access_link_id', link_row.id, 'revoked_at', link_row.revoked_at,
      'already_revoked', true
    );
  end if;

  update public.job_report_access_links
  set revoked_at = now(), revoked_reason = 'revoked'
  where id = link_row.id
  returning * into link_row;

  insert into public.activity_events (
    organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
  ) values (
    link_row.organization_id, 'job', link_row.job_id, 'job.work_report_link_revoked',
    'Turned off the work report link', caller,
    jsonb_build_object('job_report_access_link_id', link_row.id)
  );

  return jsonb_build_object(
    'job_report_access_link_id', link_row.id, 'revoked_at', link_row.revoked_at,
    'already_revoked', false
  );
end;
$$;


