CREATE OR REPLACE FUNCTION "public"."rotate_website_chat_widget_public_token"("p_organization_id" "uuid", "p_widget_id" "uuid", "p_expected_revision" integer, "p_reason" "text", "p_actor_email" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  clean_reason text := btrim(coalesce(p_reason, ''));
  actor text := lower(btrim(coalesce(p_actor_email, '')));
  widget public.website_chat_widgets%rowtype;
  existing_event public.communication_website_chat_authority_events%rowtype;
  inserted_event public.communication_website_chat_authority_events%rowtype;
  next_token uuid := gen_random_uuid();
begin
  if char_length(clean_reason) not between 3 and 500 then
    raise exception 'A reason of 3 to 500 characters is required.' using errcode = 'check_violation';
  end if;
  if char_length(actor) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;

  perform pg_advisory_xact_lock(hashtext('website-chat-widget-authority:' || p_widget_id::text));
  select * into existing_event
  from public.communication_website_chat_authority_events
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_event.after_state || jsonb_build_object('applied', false, 'event_id', existing_event.id);
  end if;

  select * into widget
  from public.website_chat_widgets
  where organization_id = p_organization_id and id = p_widget_id
  for update;
  if not found then
    raise exception 'That widget was not found.' using errcode = 'foreign_key_violation';
  end if;
  if p_expected_revision is distinct from widget.revision then
    raise exception 'The widget changed while you were reviewing it. Reload and try again.'
      using errcode = 'serialization_failure';
  end if;

  update public.website_chat_widgets
  set public_token = next_token, revision = revision + 1, updated_at = now()
  where id = widget.id
  returning * into widget;

  insert into public.communication_website_chat_authority_events (
    organization_id, widget_id, event_kind, reason, actor_owner_email,
    before_state, after_state, idempotency_key
  ) values (
    p_organization_id, p_widget_id, 'public_token_rotated', clean_reason, actor,
    jsonb_build_object('revision', p_expected_revision),
    jsonb_build_object('widget_id', p_widget_id, 'revision', widget.revision,
      'public_token', widget.public_token),
    p_idempotency_key
  ) returning * into inserted_event;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor, 'communications.website_chat_public_token_rotated', 'website_chat_widget', p_widget_id::text,
    jsonb_build_object('revision', p_expected_revision),
    jsonb_build_object('revision', widget.revision, 'reason', clean_reason,
      'authority_event_id', inserted_event.id)
  );

  return inserted_event.after_state || jsonb_build_object('applied', true, 'event_id', inserted_event.id);
end;
$$;


ALTER FUNCTION "public"."rotate_website_chat_widget_public_token"("p_organization_id" "uuid", "p_widget_id" "uuid", "p_expected_revision" integer, "p_reason" "text", "p_actor_email" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_automation_recipe_draft"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_name" "text", "p_definition" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  clean_name text := btrim(coalesce(p_name, ''));
  existing_receipt public.automation_draft_command_receipts%rowtype;
  recipe public.automation_recipes%rowtype;
  next_revision integer;
begin
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;
  if p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'An expected revision is required.' using errcode = 'check_violation';
  end if;
  if char_length(clean_name) not between 1 and 120 then
    raise exception 'A recipe name of 1 to 120 characters is required.' using errcode = 'check_violation';
  end if;
  if p_definition is null or jsonb_typeof(p_definition) <> 'object' then
    raise exception 'A recipe definition is required.' using errcode = 'check_violation';
  end if;

  perform pg_advisory_xact_lock(hashtext('automation-recipe:' || p_recipe_id::text));

  select * into existing_receipt
  from public.automation_draft_command_receipts
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_receipt.result || jsonb_build_object('idempotent_replay', true);
  end if;

  select * into recipe
  from public.automation_recipes
  where id = p_recipe_id and organization_id = p_organization_id
  for update;
  if not found then
    raise exception 'That automation does not exist.' using errcode = 'no_data_found';
  end if;
  if recipe.status = 'archived' then
    raise exception 'An archived automation is read-only.' using errcode = 'restrict_violation';
  end if;

  if recipe.draft_revision <> p_expected_revision then
    return jsonb_build_object(
      'stale', true,
      'current_revision', recipe.draft_revision,
      'draft_updated_at', recipe.draft_updated_at,
      'draft_updated_by', recipe.draft_updated_by
    );
  end if;

  next_revision := recipe.draft_revision + 1;

  update public.automation_recipes
  set name = clean_name,
      draft_definition = p_definition,
      draft_revision = next_revision,
      draft_updated_by = p_actor_user_id,
      draft_updated_at = now()
  where id = p_recipe_id and organization_id = p_organization_id;

  insert into public.automation_draft_command_receipts (
    organization_id, idempotency_key, command, recipe_id, result
  ) values (
    p_organization_id, p_idempotency_key, 'save_draft', p_recipe_id,
    jsonb_build_object('recipe_id', p_recipe_id, 'draft_revision', next_revision, 'stale', false)
  );

  return jsonb_build_object('recipe_id', p_recipe_id, 'draft_revision', next_revision, 'stale', false);
end;
$$;


ALTER FUNCTION "public"."save_automation_recipe_draft"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_name" "text", "p_definition" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_automation_recipe_draft"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_name" "text", "p_definition" "jsonb", "p_idempotency_key" "uuid") IS 'Saves an existing recipe draft under optimistic-lock revision protection. Idempotent per organization + key; a stale revision returns the newer editor/time instead of overwriting.';



CREATE OR REPLACE FUNCTION "public"."save_invoice_payment_term"("target_organization_id" "uuid", "expected_revision" integer, "target_term_id" "uuid", "new_name" "text", "new_rule" "text", "new_net_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings_row public.organization_settings;
  existing_term public.invoice_payment_terms;
  saved_term public.invoice_payment_terms;
  clean_name text := nullif(trim(coalesce(new_name, '')), '');
  next_position integer;
begin
  settings_row := private.lock_invoice_settings_for_edit(target_organization_id, expected_revision);

  if clean_name is null or char_length(clean_name) < 2 or char_length(clean_name) > 60 then
    raise exception 'A payment term needs a name between 2 and 60 characters.'
      using errcode = 'check_violation';
  end if;
  if new_rule not in ('on_receipt', 'net_days', 'month_end', 'next_month_end') then
    raise exception 'Choose how this term works out its due date.' using errcode = 'check_violation';
  end if;
  if new_rule = 'net_days' and (new_net_days is null or new_net_days < 1 or new_net_days > 365) then
    raise exception 'A net term needs a day count between 1 and 365.' using errcode = 'check_violation';
  end if;

  if target_term_id is null then
    select coalesce(max(position), -1) + 1 into next_position
    from public.invoice_payment_terms
    where organization_id = target_organization_id;

    insert into public.invoice_payment_terms
      (organization_id, name, rule, net_days, is_protected, position, created_by)
    values (
      target_organization_id, clean_name, new_rule,
      case when new_rule = 'net_days' then new_net_days end,
      false, next_position, (select auth.uid())
    )
    returning * into saved_term;
  else
    select * into existing_term
    from public.invoice_payment_terms
    where organization_id = target_organization_id and id = target_term_id
    for update;
    if not found then
      raise exception 'That payment term could not be found.' using errcode = 'P0404';
    end if;
    if existing_term.archived_at is not null then
      raise exception 'That payment term has been removed.' using errcode = 'check_violation';
    end if;
    if existing_term.is_protected and new_rule is distinct from existing_term.rule then
      raise exception 'This term''s timing is built in and cannot be changed. Rename it instead.'
        using errcode = 'check_violation';
    end if;

    update public.invoice_payment_terms
    set name = clean_name,
        rule = new_rule,
        net_days = case when new_rule = 'net_days' then new_net_days end,
        updated_at = now()
    where organization_id = target_organization_id and id = target_term_id
    returning * into saved_term;
  end if;

  return jsonb_build_object(
    'term_id', saved_term.id,
    'invoice_settings_revision',
      private.bump_invoice_settings(target_organization_id, array['payment_terms'])
  );
end;
$$;


ALTER FUNCTION "public"."save_invoice_payment_term"("target_organization_id" "uuid", "expected_revision" integer, "target_term_id" "uuid", "new_name" "text", "new_rule" "text", "new_net_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_job_report"("target_job_id" "uuid", "new_include_service_details" boolean, "new_include_price" boolean, "new_signature_id" "uuid" DEFAULT NULL::"uuid", "new_summary" "text" DEFAULT NULL::"text", "photo_attachment_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "checklist_selections" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  job_row public.jobs;
  clean_summary text;
  had_content boolean;
  has_content_now boolean;
  photo_count integer;
  selection_count integer;
begin
  if caller is null then
    raise exception 'You must be signed in to save a report.' using errcode = 'insufficient_privilege';
  end if;

  select * into job_row from public.jobs where id = target_job_id for update;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  if not private.member_has_permission(job_row.organization_id, caller, 'jobs.edit')
     or not private.can_view_job(job_row.organization_id, target_job_id) then
    raise exception 'You do not have access to edit this job.' using errcode = 'insufficient_privilege';
  end if;

  if new_include_service_details is null or new_include_price is null then
    raise exception 'A report needs its options set.' using errcode = 'P0400';
  end if;
  if new_include_price and not new_include_service_details then
    raise exception 'Show the work list before showing its prices.' using errcode = 'P0400';
  end if;
  if new_include_price
     and not private.member_has_permission(job_row.organization_id, caller, 'jobs.view_price') then
    raise exception 'You do not have access to show prices on this report.'
      using errcode = 'insufficient_privilege';
  end if;

  clean_summary := nullif(trim(coalesce(new_summary, '')), '');
  if clean_summary is not null and char_length(clean_summary) > 2000 then
    raise exception 'That summary is too long.' using errcode = 'P0400';
  end if;

  -- The signature, if one is chosen, must be this job's.
  if new_signature_id is not null then
    if not exists (
      select 1 from public.job_signatures as sig
      where sig.organization_id = job_row.organization_id
        and sig.id = new_signature_id
        and sig.job_id = target_job_id
    ) then
      raise exception 'That signature is not on this job.' using errcode = 'P0404';
    end if;
  end if;

  -- Every chosen photo must be an image attached to this job or one of its visits.
  if photo_attachment_ids is not null and array_length(photo_attachment_ids, 1) is not null then
    select count(*) into photo_count
    from public.attachments as att
    where att.organization_id = job_row.organization_id
      and att.id = any(photo_attachment_ids)
      and att.mime_type like 'image/%'
      and (
        (att.entity_type = 'job' and att.entity_id = target_job_id)
        or (att.entity_type = 'visit' and att.entity_id in (
          select visit.id from public.job_visits as visit
          where visit.organization_id = job_row.organization_id and visit.job_id = target_job_id
        ))
      );
    if photo_count <> cardinality(array(select distinct unnest(photo_attachment_ids))) then
      raise exception 'One of those photos does not belong to this job.' using errcode = 'P0400';
    end if;
  end if;

  -- Every chosen checklist answer must name a question and a visit that are both this job's.
  if checklist_selections is not null and jsonb_array_length(checklist_selections) > 0 then
    select count(*) into selection_count
    from jsonb_array_elements(checklist_selections) as choice
    where exists (
      select 1 from public.job_checklist_items as item
      where item.organization_id = job_row.organization_id
        and item.id = (choice ->> 'item_id')::uuid
        and item.job_id = target_job_id
    )
    and exists (
      select 1 from public.job_visits as visit
      where visit.organization_id = job_row.organization_id
        and visit.id = (choice ->> 'visit_id')::uuid
        and visit.job_id = target_job_id
    );
    if selection_count <> jsonb_array_length(checklist_selections) then
      raise exception 'One of those checklist answers does not belong to this job.'
        using errcode = 'P0400';
    end if;
  end if;

  had_content := private.job_report_has_content(job_row.organization_id, target_job_id);

  insert into public.job_reports (
    organization_id, job_id, include_service_details, include_price, signature_id, summary, updated_by
  ) values (
    job_row.organization_id, target_job_id, new_include_service_details, new_include_price,
    new_signature_id, clean_summary, caller
  )
  on conflict (organization_id, job_id) do update
    set include_service_details = excluded.include_service_details,
        include_price = excluded.include_price,
        signature_id = excluded.signature_id,
        summary = excluded.summary,
        updated_by = excluded.updated_by,
        updated_at = now();

  delete from public.job_report_photos
  where organization_id = job_row.organization_id and job_id = target_job_id;
  if photo_attachment_ids is not null and array_length(photo_attachment_ids, 1) is not null then
    insert into public.job_report_photos (organization_id, job_id, attachment_id)
    select job_row.organization_id, target_job_id, chosen
    from (select distinct unnest(photo_attachment_ids) as chosen) as distinct_photos;
  end if;

  delete from public.job_report_checklist_items
  where organization_id = job_row.organization_id and job_id = target_job_id;
  if checklist_selections is not null and jsonb_array_length(checklist_selections) > 0 then
    insert into public.job_report_checklist_items (organization_id, job_id, visit_id, item_id)
    select distinct job_row.organization_id, target_job_id,
      (choice ->> 'visit_id')::uuid, (choice ->> 'item_id')::uuid
    from jsonb_array_elements(checklist_selections) as choice;
  end if;

  has_content_now := private.job_report_has_content(job_row.organization_id, target_job_id);

  -- Only a crossing is worth a feed line. A photo swap inside an already-live report changes every sent
  -- link silently, which is the whole point of "always current".
  if had_content <> has_content_now then
    insert into public.activity_events (
      organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
    ) values (
      job_row.organization_id, 'job', target_job_id,
      case when has_content_now then 'job.work_report_prepared' else 'job.work_report_cleared' end,
      case when has_content_now then 'Prepared a work report for the customer'
           else 'Cleared the work report' end,
      caller,
      jsonb_build_object('job_id', target_job_id)
    );
  end if;

  return jsonb_build_object('job_id', target_job_id, 'has_content', has_content_now);
end;
$$;


ALTER FUNCTION "public"."save_job_report"("target_job_id" "uuid", "new_include_service_details" boolean, "new_include_price" boolean, "new_signature_id" "uuid", "new_summary" "text", "photo_attachment_ids" "uuid"[], "checklist_selections" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_job_report"("target_job_id" "uuid", "new_include_service_details" boolean, "new_include_price" boolean, "new_signature_id" "uuid", "new_summary" "text", "photo_attachment_ids" "uuid"[], "checklist_selections" "jsonb") IS 'Replaces a job''s whole work-report selection in one call. Needs jobs.edit; include_price additionally needs jobs.view_price. Writes one feed line only when the report crosses between empty and not.';



CREATE OR REPLACE FUNCTION "public"."save_member_availability_exception"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "target_date" "date", "new_is_working" boolean, "new_starts_at" time without time zone, "new_ends_at" time without time zone, "new_reason" "text", "expected_availability_revision" integer) RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members;
  clean_reason text;
begin
  membership := private.authorize_member_availability_command(
    target_organization_id, actor_user_id, target_user_id
  );

  if expected_availability_revision is null
    or expected_availability_revision <> membership.availability_revision then
    raise exception 'Someone else changed this person''s availability while you were editing.'
      using errcode = 'P0409';
  end if;

  if target_date is null then
    raise exception 'An exception needs a date.' using errcode = 'check_violation';
  end if;

  clean_reason := nullif(btrim(coalesce(new_reason, '')), '');
  if clean_reason is not null and char_length(clean_reason) > 120 then
    raise exception 'That reason is too long.' using errcode = 'check_violation';
  end if;

  insert into public.organization_member_availability_exceptions (
    organization_id, user_id, exception_date, is_working, starts_at, ends_at, reason
  )
  values (
    target_organization_id, target_user_id, target_date,
    coalesce(new_is_working, false), new_starts_at, new_ends_at, clean_reason
  )
  on conflict (organization_id, user_id, exception_date) do update
  set is_working = excluded.is_working,
      starts_at = excluded.starts_at,
      ends_at = excluded.ends_at,
      reason = excluded.reason;

  update public.organization_members as membership_row
  set availability_revision = membership_row.availability_revision + 1
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  returning * into membership;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    target_organization_id, 'member.availability_updated', 'member', actor_user_id, target_user_id,
    jsonb_build_object('changed', jsonb_build_array('exceptions'))
  );

  return membership;
end;
$$;


ALTER FUNCTION "public"."save_member_availability_exception"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "target_date" "date", "new_is_working" boolean, "new_starts_at" time without time zone, "new_ends_at" time without time zone, "new_reason" "text", "expected_availability_revision" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_member_availability_exception"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "target_date" "date", "new_is_working" boolean, "new_starts_at" time without time zone, "new_ends_at" time without time zone, "new_reason" "text", "expected_availability_revision" integer) IS 'Adds or replaces one dated exception. One row per person per day, so saving the same date twice corrects it instead of stacking a second answer behind the first.';



CREATE OR REPLACE FUNCTION "public"."save_member_weekly_availability"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "new_pattern" "jsonb", "expected_availability_revision" integer) RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members;
  clearing boolean;
  day_count integer;
begin
  membership := private.authorize_member_availability_command(
    target_organization_id, actor_user_id, target_user_id
  );

  if expected_availability_revision is null
    or expected_availability_revision <> membership.availability_revision then
    raise exception 'Someone else changed this person''s availability while you were editing.'
      using errcode = 'P0409';
  end if;

  clearing := new_pattern is null
    or jsonb_typeof(new_pattern) <> 'array'
    or jsonb_array_length(new_pattern) = 0;

  delete from public.organization_member_availability
  where organization_id = target_organization_id
    and user_id = target_user_id;

  if not clearing then
    insert into public.organization_member_availability (
      organization_id, user_id, weekday, is_working, starts_at, ends_at
    )
    select
      target_organization_id,
      target_user_id,
      (item ->> 'weekday')::smallint,
      coalesce((item ->> 'is_working')::boolean, false),
      nullif(item ->> 'starts_at', '')::time,
      nullif(item ->> 'ends_at', '')::time
    from jsonb_array_elements(new_pattern) as item;

    select count(*) into day_count
    from public.organization_member_availability
    where organization_id = target_organization_id
      and user_id = target_user_id;

    if day_count <> 7 then
      raise exception 'A working week must cover every day.' using errcode = 'check_violation';
    end if;
  end if;

  update public.organization_members as membership_row
  set availability_revision = membership_row.availability_revision + 1
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  returning * into membership;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    target_organization_id, 'member.availability_updated', 'member', actor_user_id, target_user_id,
    jsonb_build_object('changed', jsonb_build_array('weekly_pattern'))
  );

  return membership;
end;
$$;


ALTER FUNCTION "public"."save_member_weekly_availability"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "new_pattern" "jsonb", "expected_availability_revision" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_member_weekly_availability"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "new_pattern" "jsonb", "expected_availability_revision" integer) IS 'Replaces one member''s ordinary working week in a single step. Seven days or none; an empty pattern means nobody has said when this person works, which is not the same as saying they never do.';



CREATE OR REPLACE FUNCTION "public"."save_organization_branding"("target_organization_id" "uuid", "expected_revision" integer, "new_brand_color" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  settings_row public.organization_settings;
  clean_brand_color text;
  new_revision integer;
  editor_name text;
  editor_at timestamptz;
begin
  if not private.has_permission(target_organization_id, 'settings.business.edit') then
    raise exception 'You do not have access to change business settings.'
      using errcode = 'insufficient_privilege';
  end if;

  clean_brand_color := nullif(trim(coalesce(new_brand_color, '')), '');
  if clean_brand_color is not null and clean_brand_color !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception 'Brand color must be a hex color.' using errcode = 'check_violation';
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for update;

  if settings_row.organization_id is null then
    raise exception 'Organization settings were not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from settings_row.branding_revision then
    select profile.full_name, settings_row.branding_updated_at into editor_name, editor_at
    from public.profiles as profile
    where profile.id = settings_row.branding_updated_by;

    return jsonb_build_object(
      'status', 'stale',
      'editor_name', editor_name,
      'edited_at', coalesce(editor_at, settings_row.updated_at)
    );
  end if;

  update public.organization_settings
  set
    brand_color = clean_brand_color,
    branding_revision = branding_revision + 1,
    branding_updated_by = (select auth.uid()),
    branding_updated_at = now()
  where organization_id = target_organization_id
  returning branding_revision into new_revision;

  if clean_brand_color is distinct from settings_row.brand_color then
    insert into public.organization_settings_audit (
      organization_id, section, changed_fields, actor_user_id
    )
    values (target_organization_id, 'branding', array['brand_color'], (select auth.uid()));
  end if;

  return jsonb_build_object(
    'status', 'saved', 'branding_revision', new_revision, 'brand_color', clean_brand_color
  );
end;
$_$;


ALTER FUNCTION "public"."save_organization_branding"("target_organization_id" "uuid", "expected_revision" integer, "new_brand_color" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_organization_business_hours"("target_organization_id" "uuid", "expected_revision" integer, "new_mode" "text", "new_hours" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings_row public.organization_settings;
  new_revision integer;
  editor_name text;
  editor_at timestamptz;
  offending_weekday smallint;
begin
  if not private.has_permission(target_organization_id, 'settings.business.edit') then
    raise exception 'You do not have access to change business settings.'
      using errcode = 'insufficient_privilege';
  end if;

  if new_mode is null or new_mode not in ('weekly', 'appointment_only') then
    raise exception 'Choose weekly hours or appointment only.' using errcode = 'check_violation';
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for update;

  if settings_row.organization_id is null then
    raise exception 'Organization settings were not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from settings_row.hours_revision then
    select profile.full_name, settings_row.hours_updated_at into editor_name, editor_at
    from public.profiles as profile
    where profile.id = settings_row.hours_updated_by;

    return jsonb_build_object(
      'status', 'stale',
      'editor_name', editor_name,
      'edited_at', coalesce(editor_at, settings_row.updated_at)
    );
  end if;

  delete from public.organization_business_hours where organization_id = target_organization_id;

  if new_mode = 'weekly' then
    if new_hours is null or jsonb_typeof(new_hours) <> 'array' then
      raise exception 'Business hours must include all seven days.' using errcode = 'check_violation';
    end if;

    insert into public.organization_business_hours (
      organization_id, weekday, period_index, is_open, is_open_24h, opens_at, closes_at
    )
    select
      target_organization_id,
      (item ->> 'weekday')::smallint,
      coalesce((item ->> 'period_index')::smallint, 0),
      coalesce((item ->> 'is_open')::boolean, false),
      coalesce((item ->> 'is_open_24h')::boolean, false),
      nullif(item ->> 'opens_at', '')::time,
      nullif(item ->> 'closes_at', '')::time
    from jsonb_array_elements(new_hours) as item;

    if (
      select count(distinct weekday) from public.organization_business_hours
      where organization_id = target_organization_id
    ) <> 7 then
      raise exception 'Business hours must cover every day of the week.' using errcode = 'check_violation';
    end if;

    select weekday into offending_weekday
    from public.organization_business_hours
    where organization_id = target_organization_id
    group by weekday
    having count(*) > 3 or max(period_index) <> count(*) - 1
    limit 1;

    if offending_weekday is not null then
      raise exception 'A day can have up to three time periods, one after another.'
        using errcode = 'check_violation';
    end if;

    select weekday into offending_weekday
    from public.organization_business_hours
    where organization_id = target_organization_id
    group by weekday
    having bool_or(not is_open or is_open_24h) and count(*) > 1
    limit 1;

    if offending_weekday is not null then
      raise exception 'A day that is closed or open 24 hours cannot also have time periods.'
        using errcode = 'check_violation';
    end if;

    select ordered.weekday into offending_weekday
    from (
      select
        weekday,
        extract(epoch from opens_at) / 60 as start_minute,
        lag(extract(epoch from opens_at) / 60)
          over (partition by weekday order by period_index) as previous_start,
        lag(case
              when closes_at <= opens_at then extract(epoch from closes_at) / 60 + 1440
              else extract(epoch from closes_at) / 60
            end)
          over (partition by weekday order by period_index) as previous_end
      from public.organization_business_hours
      where organization_id = target_organization_id and is_open and not is_open_24h
    ) as ordered
    where ordered.previous_start is not null
      and (ordered.start_minute <= ordered.previous_start or ordered.start_minute < ordered.previous_end)
    limit 1;

    if offending_weekday is not null then
      raise exception 'Time periods on the same day have to run in order without overlapping.'
        using errcode = 'check_violation';
    end if;
  end if;

  update public.organization_settings
  set
    hours_mode = new_mode,
    hours_revision = hours_revision + 1,
    hours_updated_by = (select auth.uid()),
    hours_updated_at = now()
  where organization_id = target_organization_id
  returning hours_revision into new_revision;

  insert into public.organization_settings_audit (
    organization_id, section, changed_fields, actor_user_id
  )
  values (
    target_organization_id,
    'hours',
    case when new_mode is distinct from settings_row.hours_mode
      then array['hours_mode', 'hours'] else array['hours'] end,
    (select auth.uid())
  );

  return jsonb_build_object('status', 'saved', 'hours_revision', new_revision, 'hours_mode', new_mode);
end;
$$;


ALTER FUNCTION "public"."save_organization_business_hours"("target_organization_id" "uuid", "expected_revision" integer, "new_mode" "text", "new_hours" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_organization_business_profile"("target_organization_id" "uuid", "expected_revision" integer, "new_name" "text", "new_trade" "text", "new_phone" "text", "new_website" "text", "new_description" "text", "new_address_line1" "text", "new_address_line2" "text", "new_city" "text", "new_region" "text", "new_postal_code" "text", "new_country_code" "text", "new_address_is_public" boolean, "new_timezone" "text", "new_currency_code" "text", "confirm_timezone" boolean, "confirm_currency" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  settings_row public.organization_settings;
  current_name text;
  clean_name text;
  clean_trade text;
  clean_phone text;
  clean_website text;
  clean_description text;
  clean_address_line1 text;
  clean_address_line2 text;
  clean_city text;
  clean_region text;
  clean_postal_code text;
  clean_country_code text;
  clean_address_is_public boolean;
  changed text[] := '{}';
  new_revision integer;
  editor_name text;
  editor_at timestamptz;
begin
  if not private.has_permission(target_organization_id, 'settings.business.edit') then
    raise exception 'You do not have access to change business settings.'
      using errcode = 'insufficient_privilege';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) < 2 or char_length(clean_name) > 120 then
    raise exception 'Business name must be between 2 and 120 characters.' using errcode = 'check_violation';
  end if;

  clean_trade := nullif(trim(coalesce(new_trade, '')), '');
  clean_phone := nullif(trim(coalesce(new_phone, '')), '');
  clean_website := nullif(trim(coalesce(new_website, '')), '');
  clean_description := nullif(trim(coalesce(new_description, '')), '');
  clean_address_line1 := nullif(trim(coalesce(new_address_line1, '')), '');
  clean_address_line2 := nullif(trim(coalesce(new_address_line2, '')), '');
  clean_city := nullif(trim(coalesce(new_city, '')), '');
  clean_region := nullif(trim(coalesce(new_region, '')), '');
  clean_postal_code := nullif(trim(coalesce(new_postal_code, '')), '');
  clean_country_code := nullif(upper(trim(coalesce(new_country_code, ''))), '');
  clean_address_is_public := coalesce(new_address_is_public, false);

  if clean_country_code is not null and clean_country_code !~ '^[A-Z]{2}$' then
    raise exception 'Choose a country from the list.' using errcode = 'check_violation';
  end if;

  if new_timezone is null or not exists (select 1 from pg_timezone_names where name = new_timezone) then
    raise exception 'Choose a valid timezone.' using errcode = 'check_violation';
  end if;

  if new_currency_code is null or new_currency_code !~ '^[A-Z]{3}$' then
    raise exception 'Choose a valid currency.' using errcode = 'check_violation';
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for update;

  if settings_row.organization_id is null then
    raise exception 'Organization settings were not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from settings_row.profile_revision then
    select profile.full_name, settings_row.profile_updated_at into editor_name, editor_at
    from public.profiles as profile
    where profile.id = settings_row.profile_updated_by;

    return jsonb_build_object(
      'status', 'stale',
      'editor_name', editor_name,
      'edited_at', coalesce(editor_at, settings_row.updated_at)
    );
  end if;

  if not coalesce(confirm_timezone, false) and new_timezone is distinct from settings_row.timezone then
    raise exception 'Confirm the timezone before saving it.' using errcode = 'check_violation';
  end if;

  if not coalesce(confirm_currency, false) and new_currency_code is distinct from settings_row.currency_code
  then
    raise exception 'Confirm the currency before saving it.' using errcode = 'check_violation';
  end if;

  if new_currency_code is distinct from settings_row.currency_code
     and exists (
       select 1 from public.quotes
       where organization_id = target_organization_id
         and (current_published_version_id is not null or sent_at is not null)
     )
  then
    raise exception 'Currency cannot change once a Quote has been sent to a customer.'
      using errcode = 'check_violation';
  end if;

  select organization.name into current_name
  from public.organizations as organization
  where organization.id = target_organization_id;

  changed := changed
    || case when clean_name is distinct from current_name then array['name'] else '{}' end
    || case when clean_trade is distinct from settings_row.trade then array['trade'] else '{}' end
    || case when clean_phone is distinct from settings_row.phone then array['phone'] else '{}' end
    || case when clean_website is distinct from settings_row.website then array['website'] else '{}' end
    || case when clean_description is distinct from settings_row.description
         then array['description'] else '{}' end
    || case when clean_address_line1 is distinct from settings_row.address_line1
         then array['address_line1'] else '{}' end
    || case when clean_address_line2 is distinct from settings_row.address_line2
         then array['address_line2'] else '{}' end
    || case when clean_city is distinct from settings_row.city then array['city'] else '{}' end
    || case when clean_region is distinct from settings_row.region then array['region'] else '{}' end
    || case when clean_postal_code is distinct from settings_row.postal_code
         then array['postal_code'] else '{}' end
    || case when clean_country_code is distinct from settings_row.country_code
         then array['country_code'] else '{}' end
    || case when clean_address_is_public is distinct from settings_row.address_is_public
         then array['address_is_public'] else '{}' end
    || case when new_timezone is distinct from settings_row.timezone then array['timezone'] else '{}' end
    || case when new_currency_code is distinct from settings_row.currency_code
         then array['currency_code'] else '{}' end
    || case when coalesce(confirm_timezone, false) and settings_row.timezone_confirmed_at is null
         then array['timezone_confirmed'] else '{}' end
    || case when coalesce(confirm_currency, false) and settings_row.currency_confirmed_at is null
         then array['currency_confirmed'] else '{}' end;

  update public.organizations set name = clean_name where id = target_organization_id;

  update public.organization_settings
  set
    trade = clean_trade,
    phone = clean_phone,
    website = clean_website,
    description = clean_description,
    address_line1 = clean_address_line1,
    address_line2 = clean_address_line2,
    city = clean_city,
    region = clean_region,
    postal_code = clean_postal_code,
    country_code = clean_country_code,
    address_is_public = clean_address_is_public,
    timezone = new_timezone,
    currency_code = new_currency_code,
    timezone_confirmed_at = case
      when coalesce(confirm_timezone, false) then now() else timezone_confirmed_at end,
    currency_confirmed_at = case
      when coalesce(confirm_currency, false) then now() else currency_confirmed_at end,
    profile_revision = profile_revision + 1,
    profile_updated_by = (select auth.uid()),
    profile_updated_at = now()
  where organization_id = target_organization_id
  returning profile_revision into new_revision;

  if array_length(changed, 1) is not null then
    insert into public.organization_settings_audit (
      organization_id, section, changed_fields, actor_user_id
    )
    values (target_organization_id, 'profile', changed, (select auth.uid()));
  end if;

  return jsonb_build_object(
    'status', 'saved',
    'profile_revision', new_revision,
    'name', clean_name,
    'timezone_confirmed', coalesce(confirm_timezone, false) or settings_row.timezone_confirmed_at is not null,
    'currency_confirmed',
      coalesce(confirm_currency, false) or settings_row.currency_confirmed_at is not null
  );
end;
$_$;


ALTER FUNCTION "public"."save_organization_business_profile"("target_organization_id" "uuid", "expected_revision" integer, "new_name" "text", "new_trade" "text", "new_phone" "text", "new_website" "text", "new_description" "text", "new_address_line1" "text", "new_address_line2" "text", "new_city" "text", "new_region" "text", "new_postal_code" "text", "new_country_code" "text", "new_address_is_public" boolean, "new_timezone" "text", "new_currency_code" "text", "confirm_timezone" boolean, "confirm_currency" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_pipeline_presentation"("target_organization_id" "uuid", "expected_revision" integer, "new_detailed_assessment_stages" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings_row public.organization_settings;
  new_revision integer;
  editor_name text;
  editor_at timestamptz;
begin
  if not private.has_permission(target_organization_id, 'settings.business.edit') then
    raise exception 'You do not have access to change business settings.'
      using errcode = 'insufficient_privilege';
  end if;

  if new_detailed_assessment_stages is null then
    raise exception 'Choose whether to show the detailed assessment stages.'
      using errcode = 'check_violation';
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for update;

  if settings_row.organization_id is null then
    raise exception 'Organization settings were not found.' using errcode = 'check_violation';
  end if;

  -- Somebody else saved first. The caller is told who and when, so it can offer to reload rather than
  -- silently overwrite a change it never saw.
  if expected_revision is distinct from settings_row.pipeline_revision then
    select profile.full_name, settings_row.pipeline_updated_at into editor_name, editor_at
    from public.profiles as profile
    where profile.id = settings_row.pipeline_updated_by;

    return jsonb_build_object(
      'status', 'stale',
      'editor_name', editor_name,
      'edited_at', coalesce(editor_at, settings_row.updated_at)
    );
  end if;

  update public.organization_settings
  set
    pipeline_detailed_assessment_stages = new_detailed_assessment_stages,
    pipeline_revision = pipeline_revision + 1,
    pipeline_updated_by = (select auth.uid()),
    pipeline_updated_at = now()
  where organization_id = target_organization_id
  returning pipeline_revision into new_revision;

  if new_detailed_assessment_stages
     is distinct from settings_row.pipeline_detailed_assessment_stages then
    insert into public.organization_settings_audit (
      organization_id, section, changed_fields, actor_user_id
    )
    values (
      target_organization_id, 'pipeline',
      array['pipeline_detailed_assessment_stages'], (select auth.uid())
    );
  end if;

  return jsonb_build_object(
    'status', 'saved',
    'pipeline_revision', new_revision,
    'pipeline_detailed_assessment_stages', new_detailed_assessment_stages
  );
end;
$$;


ALTER FUNCTION "public"."save_pipeline_presentation"("target_organization_id" "uuid", "expected_revision" integer, "new_detailed_assessment_stages" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_team_member_permissions"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "desired_overrides" "jsonb", "expected_access_revision" integer) RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members;
  added_keys text[];
  removed_keys text[];
begin
  membership := private.authorize_team_member_command(
    target_organization_id, actor_user_id, target_user_id
  );
  perform private.assert_membership_is_editable(membership);

  if expected_access_revision is null or expected_access_revision <> membership.access_revision then
    raise exception 'Someone else changed this person''s access while you were editing.'
      using errcode = 'P0409';
  end if;

  if desired_overrides is null or jsonb_typeof(desired_overrides) <> 'array' then
    raise exception 'The permission adjustments must be a list.' using errcode = 'check_violation';
  end if;

  -- Every entry names a real permission and one of the two states. An unknown key would be caught by the
  -- foreign key anyway, but the message it produces is not one anybody could act on.
  if exists (
    select 1
    from jsonb_array_elements(desired_overrides) as entry(item)
    where jsonb_typeof(entry.item) <> 'object'
      or (entry.item ->> 'permission_key') is null
      or (entry.item ->> 'override_state') not in ('grant', 'deny')
      or not exists (
        select 1 from public.permissions as permission
        where permission.key = entry.item ->> 'permission_key'
      )
  ) then
    raise exception 'One of those permission adjustments is not something we can save.'
      using errcode = 'check_violation';
  end if;

  -- The packet's rule, restated where it would be broken: no domain enforces "Assigned work only" yet, so
  -- the only scope this command will store is 'all'. A caller asking for anything else is refused here
  -- rather than by the scope trigger, which cannot explain itself as clearly.
  if exists (
    select 1
    from jsonb_array_elements(desired_overrides) as entry(item)
    where coalesce(entry.item ->> 'access_scope', 'all') <> 'all'
  ) then
    raise exception 'Assigned-only access is not available yet.' using errcode = 'check_violation';
  end if;

  if exists (
    select entry.item ->> 'permission_key'
    from jsonb_array_elements(desired_overrides) as entry(item)
    group by entry.item ->> 'permission_key'
    having count(*) > 1
  ) then
    raise exception 'The same permission was adjusted twice in one save.' using errcode = 'check_violation';
  end if;

  -- Added and removed are worked out against what is stored right now, before anything is written. A
  -- grant that becomes a deny appears in both lists, which is the truth: one adjustment left, another came.
  -- The wanted set is read straight out of the argument each time rather than staged in a temporary table:
  -- these are a handful of rows per member, and a temporary table on a transaction-pooled connection is
  -- catalog churn nobody asked for.
  select
    coalesce(array_agg(distinct changed.permission_key) filter (where changed.direction = 'added'), '{}'),
    coalesce(array_agg(distinct changed.permission_key) filter (where changed.direction = 'removed'), '{}')
  into added_keys, removed_keys
  from (
    select entry.item ->> 'permission_key' as permission_key, 'added' as direction
    from jsonb_array_elements(desired_overrides) as entry(item)
    where not exists (
      select 1
      from public.organization_member_permission_overrides as existing
      where existing.organization_id = target_organization_id
        and existing.user_id = target_user_id
        and existing.permission_key = entry.item ->> 'permission_key'
        and existing.override_state = entry.item ->> 'override_state'
    )
    union all
    select existing.permission_key, 'removed'
    from public.organization_member_permission_overrides as existing
    where existing.organization_id = target_organization_id
      and existing.user_id = target_user_id
      and not exists (
        select 1
        from jsonb_array_elements(desired_overrides) as entry(item)
        where entry.item ->> 'permission_key' = existing.permission_key
          and entry.item ->> 'override_state' = existing.override_state
      )
  ) as changed;

  -- Adjustments the save left out are gone. One that only changed sides is left to the upsert below, so a
  -- grant becoming a deny never passes through a moment of having no adjustment at all.
  delete from public.organization_member_permission_overrides as override
  where override.organization_id = target_organization_id
    and override.user_id = target_user_id
    and not exists (
      select 1
      from jsonb_array_elements(desired_overrides) as entry(item)
      where entry.item ->> 'permission_key' = override.permission_key
    );

  insert into public.organization_member_permission_overrides (
    organization_id, user_id, permission_key, override_state, access_scope
  )
  select
    target_organization_id,
    target_user_id,
    entry.item ->> 'permission_key',
    entry.item ->> 'override_state',
    'all'
  from jsonb_array_elements(desired_overrides) as entry(item)
  on conflict (organization_id, user_id, permission_key) do update
  set override_state = excluded.override_state,
      access_scope = excluded.access_scope,
      updated_at = now();

  -- Nothing moved, so nothing is recorded and no editor is invalidated. Saving an unchanged form is not an
  -- access change, and a history full of "changed nothing" lines is a history nobody reads.
  if array_length(added_keys, 1) is null and array_length(removed_keys, 1) is null then
    return membership;
  end if;

  update public.organization_members as membership_row
  set access_revision = membership_row.access_revision + 1
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  returning * into membership;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    target_organization_id, 'member.permissions_changed', 'member', actor_user_id, target_user_id,
    jsonb_strip_nulls(
      jsonb_build_object(
        'added_permissions',
          case when array_length(added_keys, 1) is null then null else to_jsonb(added_keys) end,
        'removed_permissions',
          case when array_length(removed_keys, 1) is null then null else to_jsonb(removed_keys) end
      )
    )
  );

  return membership;
end;
$$;


ALTER FUNCTION "public"."save_team_member_permissions"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "desired_overrides" "jsonb", "expected_access_revision" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_team_member_permissions"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "desired_overrides" "jsonb", "expected_access_revision" integer) IS 'Replaces one member''s individual permission adjustments with the set the screen saved, and records what actually moved as a single history line. Refuses assigned scope, which no domain enforces yet.';



CREATE OR REPLACE FUNCTION "public"."save_visit_checklist_answers"("target_organization_id" "uuid", "target_visit_id" "uuid", "answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  visit public.job_visits;
  job_active boolean;
  entry record;
  item public.job_checklist_items;
  saved integer := 0;
  cleared integer := 0;
begin
  if caller is null then
    raise exception 'You must be signed in to fill in a checklist.' using errcode = 'insufficient_privilege';
  end if;
  if jsonb_typeof(answers) <> 'array' then
    raise exception 'Those answers could not be read.' using errcode = 'P0400';
  end if;

  select job_visit.* into visit
  from public.job_visits as job_visit
  where job_visit.organization_id = target_organization_id and job_visit.id = target_visit_id;
  if not found then
    raise exception 'That visit could not be found.' using errcode = 'P0404';
  end if;

  if not private.can_view_visit(target_organization_id, target_visit_id) then
    raise exception 'You do not have access to this visit.' using errcode = 'insufficient_privilege';
  end if;

  select job.status = 'active' into job_active
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = visit.job_id;

  if job_active then
    if not private.member_has_permission(target_organization_id, caller, 'field_records.record')
      and not private.member_has_permission(target_organization_id, caller, 'field_records.manage_team') then
      raise exception 'You do not have access to fill in this checklist.' using errcode = 'insufficient_privilege';
    end if;
  elsif not private.member_has_permission(target_organization_id, caller, 'field_records.manage_team') then
    raise exception 'A closed job''s checklists can only be changed by someone who manages the team''s records.'
      using errcode = 'P0410';
  end if;

  for entry in
    select
      (element.value ->> 'item_id')::uuid as item_id,
      element.value -> 'value' as value
    from jsonb_array_elements(answers) as element(value)
  loop
    select checklist_item.* into item
    from public.job_checklist_items as checklist_item
    where checklist_item.organization_id = target_organization_id
      and checklist_item.id = entry.item_id
      and checklist_item.job_id = visit.job_id;
    if not found then
      raise exception 'That checklist question is not on this visit''s job.' using errcode = 'P0404';
    end if;

    if exists (
      select 1
      from public.job_checklists as checklist
      where checklist.organization_id = target_organization_id
        and checklist.id = item.job_checklist_id
        and visit.completed_at is not null
        and visit.completed_at < checklist.attached_at
    ) then
      raise exception 'That checklist was added after this visit was completed.' using errcode = 'P0410';
    end if;

    if entry.value is null or jsonb_typeof(entry.value) = 'null'
      or (jsonb_typeof(entry.value) = 'string' and length(trim(entry.value #>> '{}')) = 0) then
      delete from public.visit_checklist_answers
      where visit_id = target_visit_id and item_id = item.id;
      cleared := cleared + 1;
    else
      if not private.checklist_value_matches_type(item.item_type, item.options, entry.value) then
        raise exception 'That answer does not fit the question "%".', item.label using errcode = 'P0400';
      end if;

      insert into public.visit_checklist_answers (
        organization_id, job_id, visit_id, item_id, value, answered_by, answered_at
      )
      values (
        target_organization_id, visit.job_id, target_visit_id, item.id, entry.value, caller, now()
      )
      on conflict (visit_id, item_id) do update
      set value = excluded.value,
          answered_by = excluded.answered_by,
          answered_at = excluded.answered_at;
      saved := saved + 1;
    end if;
  end loop;

  return jsonb_build_object('saved', saved, 'cleared', cleared);
end;
$$;


ALTER FUNCTION "public"."save_visit_checklist_answers"("target_organization_id" "uuid", "target_visit_id" "uuid", "answers" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_visit_checklist_answers"("target_organization_id" "uuid", "target_visit_id" "uuid", "answers" "jsonb") IS 'Saves one visit''s checklist answers. Partial by design. Needs field_records.record.';



CREATE OR REPLACE FUNCTION "public"."schedule_calendar_context"("target_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case
    when not private.is_organization_member(target_organization_id) then null
    when not private.has_permission(target_organization_id, 'jobs.view') then null
    else jsonb_build_object(
      'timezone', coalesce(
        nullif(btrim((
          select settings.timezone
          from public.organization_settings as settings
          where settings.organization_id = target_organization_id
        )), ''),
        'UTC'
      ),
      'hours_mode', coalesce(
        (
          select settings.hours_mode
          from public.organization_settings as settings
          where settings.organization_id = target_organization_id
        ),
        'not_configured'
      ),
      'hours', coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'weekday', hours.weekday,
              'period_index', hours.period_index,
              'is_open', hours.is_open,
              'is_open_24h', hours.is_open_24h,
              'opens_at', hours.opens_at,
              'closes_at', hours.closes_at
            )
            order by hours.weekday, hours.period_index
          )
          from public.organization_business_hours as hours
          where hours.organization_id = target_organization_id
        ),
        '[]'::jsonb
      )
    )
  end;
$$;


ALTER FUNCTION "public"."schedule_calendar_context"("target_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."schedule_calendar_context"("target_organization_id" "uuid") IS 'The calendar''s operating facts for a member who can see jobs: timezone, whether weekly hours are kept, and the weekly open/close rows. Definer because organization_settings and organization_business_hours are gated to settings.business.view, which is a Settings-screen gate rather than a calendar one. Discloses nothing else from either table; null for a caller without jobs.view.';



CREATE OR REPLACE FUNCTION "public"."set_automation_recipe_lifecycle_state"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_action" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  existing_receipt public.automation_draft_command_receipts%rowtype;
  recipe public.automation_recipes%rowtype;
  target_status text;
  action_label text;
  allowed_sources text[];
  next_revision integer;
  command_result jsonb;
begin
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;
  if p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'An expected revision is required.' using errcode = 'check_violation';
  end if;

  case p_action
    when 'pause' then
      target_status := 'paused'; action_label := 'paused'; allowed_sources := array['active'];
    when 'resume' then
      target_status := 'active'; action_label := 'resumed'; allowed_sources := array['paused'];
    when 'archive' then
      target_status := 'archived'; action_label := 'archived'; allowed_sources := array['draft', 'active', 'paused'];
    when 'restore' then
      target_status := 'draft'; action_label := 'restored'; allowed_sources := array['archived'];
    else raise exception 'Unknown lifecycle action.' using errcode = 'check_violation';
  end case;

  perform pg_advisory_xact_lock(hashtext('automation-recipe:' || p_recipe_id::text));

  select * into existing_receipt
  from public.automation_draft_command_receipts
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_receipt.result || jsonb_build_object('idempotent_replay', true);
  end if;

  select * into recipe
  from public.automation_recipes
  where id = p_recipe_id and organization_id = p_organization_id
  for update;
  if not found then
    raise exception 'That automation does not exist.' using errcode = 'no_data_found';
  end if;

  if recipe.draft_revision <> p_expected_revision then
    return jsonb_build_object(
      'stale', true,
      'current_revision', recipe.draft_revision,
      'draft_updated_at', recipe.draft_updated_at,
      'draft_updated_by', recipe.draft_updated_by
    );
  end if;

  if not (recipe.status = any(allowed_sources)) then
    raise exception 'This automation cannot be % from its current state.', action_label
      using errcode = 'restrict_violation';
  end if;

  if p_action = 'restore' and recipe.draft_definition is null then
    raise exception 'This automation has no saved draft to restore.' using errcode = 'check_violation';
  end if;

  next_revision := recipe.draft_revision + 1;

  if p_action = 'restore' then
    update public.automation_recipes
    set status = 'draft',
        current_version_id = null,
        active_trigger_key = null,
        draft_revision = next_revision
    where id = p_recipe_id and organization_id = p_organization_id;
  else
    update public.automation_recipes
    set status = target_status,
        draft_revision = next_revision
    where id = p_recipe_id and organization_id = p_organization_id;
  end if;

  command_result := jsonb_build_object(
    'recipe_id', p_recipe_id,
    'status', target_status,
    'draft_revision', next_revision,
    'stale', false
  );

  insert into public.automation_draft_command_receipts (
    organization_id, idempotency_key, command, recipe_id, result
  ) values (
    p_organization_id, p_idempotency_key, p_action, p_recipe_id, command_result
  );

  return command_result;
end;
$$;


ALTER FUNCTION "public"."set_automation_recipe_lifecycle_state"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_action" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_automation_recipe_lifecycle_state"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" integer, "p_action" "text", "p_idempotency_key" "uuid") IS 'Pauses, resumes, archives, or restores a recipe over a closed set of state transitions. Idempotent per organization + key; enforces the valid source status and the caller-supplied revision. Restore returns to a fresh draft and clears the live version pointer without reactivating the old version.';



CREATE OR REPLACE FUNCTION "public"."set_checklist_template_archived"("target_organization_id" "uuid", "target_template_id" "uuid", "archived" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  updated public.checklist_templates;
begin
  if caller is null then
    raise exception 'You must be signed in to change a checklist.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'settings.checklists.manage') then
    raise exception 'You do not have access to change checklists.' using errcode = 'insufficient_privilege';
  end if;
  update public.checklist_templates as template
  set archived_at = case when archived then now() else null end, updated_at = now()
  where template.organization_id = target_organization_id and template.id = target_template_id
  returning * into updated;
  if not found then
    raise exception 'That checklist could not be found.' using errcode = 'P0404';
  end if;
  return jsonb_build_object('id', updated.id, 'archived', updated.archived_at is not null);
end;
$$;


ALTER FUNCTION "public"."set_checklist_template_archived"("target_organization_id" "uuid", "target_template_id" "uuid", "archived" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_checklist_template_archived"("target_organization_id" "uuid", "target_template_id" "uuid", "archived" boolean) IS 'Archives a checklist out of the library, or restores it. Never deletes.';



CREATE OR REPLACE FUNCTION "public"."set_client_billing"("target_organization_id" "uuid", "target_client_id" "uuid", "address_mode" "text", "billing_property_id" "uuid" DEFAULT NULL::"uuid", "new_address_line1" "text" DEFAULT NULL::"text", "new_address_line2" "text" DEFAULT NULL::"text", "new_city" "text" DEFAULT NULL::"text", "new_state_region" "text" DEFAULT NULL::"text", "new_postal_code" "text" DEFAULT NULL::"text", "new_country" "text" DEFAULT NULL::"text", "new_payment_term_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  client_row public.clients;
  chosen_property public.properties;
  clean_line1 text := nullif(trim(coalesce(new_address_line1, '')), '');
  clean_line2 text := nullif(trim(coalesce(new_address_line2, '')), '');
  clean_city text := nullif(trim(coalesce(new_city, '')), '');
  clean_region text := nullif(trim(coalesce(new_state_region, '')), '');
  clean_postal text := nullif(trim(coalesce(new_postal_code, '')), '');
  clean_country text := nullif(trim(coalesce(new_country, '')), '');
begin
  if caller is null then
    raise exception 'You must be signed in to change billing details.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'customers.edit') then
    raise exception 'You do not have access to change this client''s billing details.'
      using errcode = 'insufficient_privilege';
  end if;
  if address_mode not in ('property', 'custom', 'none') then
    raise exception 'Choose whether billing uses a property, a custom address, or neither.'
      using errcode = 'check_violation';
  end if;

  select * into client_row
  from public.clients
  where organization_id = target_organization_id and id = target_client_id
  for update;
  if not found then
    raise exception 'That client could not be found.' using errcode = 'P0404';
  end if;

  if new_payment_term_id is not null and not exists (
    select 1 from public.invoice_payment_terms
    where organization_id = target_organization_id
      and id = new_payment_term_id
      and archived_at is null
  ) then
    raise exception 'That payment term is not available.' using errcode = 'check_violation';
  end if;

  if address_mode = 'custom' then
    if clean_line1 is null or clean_city is null or clean_country is null then
      raise exception 'A custom billing address needs a street address, a city and a country.'
        using errcode = 'check_violation';
    end if;
  end if;

  update public.properties
  set is_billing_address = false, updated_at = now()
  where organization_id = target_organization_id
    and client_id = target_client_id
    and is_billing_address
    and (address_mode <> 'property' or id is distinct from billing_property_id);

  if address_mode = 'property' then
    select * into chosen_property
    from public.properties
    where organization_id = target_organization_id
      and id = billing_property_id
      and client_id = target_client_id
      and deleted_at is null
    for update;
    if not found then
      raise exception 'That property does not belong to this client.' using errcode = 'check_violation';
    end if;

    update public.properties
    set is_billing_address = true, updated_at = now()
    where organization_id = target_organization_id and id = chosen_property.id;
  end if;

  update public.clients
  set billing_payment_term_id = new_payment_term_id,
      billing_address_line1 = case when address_mode = 'custom' then clean_line1 end,
      billing_address_line2 = case when address_mode = 'custom' then clean_line2 end,
      billing_city = case when address_mode = 'custom' then clean_city end,
      billing_state_region = case when address_mode = 'custom' then clean_region end,
      billing_postal_code = case when address_mode = 'custom' then clean_postal end,
      billing_country = case when address_mode = 'custom' then clean_country end,
      updated_at = now()
  where organization_id = target_organization_id and id = target_client_id;

  return jsonb_build_object(
    'client_id', target_client_id,
    'billing_address', private.resolve_client_billing_address(target_organization_id, target_client_id),
    'payment_term_id', new_payment_term_id
  );
end;
$$;


ALTER FUNCTION "public"."set_client_billing"("target_organization_id" "uuid", "target_client_id" "uuid", "address_mode" "text", "billing_property_id" "uuid", "new_address_line1" "text", "new_address_line2" "text", "new_city" "text", "new_state_region" "text", "new_postal_code" "text", "new_country" "text", "new_payment_term_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_communication_email_organization_pause"("p_organization_id" "uuid", "p_engage" boolean, "p_reason" "text", "p_actor_email" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor text := lower(btrim(coalesce(p_actor_email, '')));
  clean_reason text := btrim(coalesce(p_reason, ''));
  existing public.communication_email_sending_pauses%rowtype;
  new_id uuid;
begin
  if char_length(actor) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if char_length(clean_reason) not between 3 and 500 then
    raise exception 'A reason of 3 to 500 characters is required.' using errcode = 'check_violation';
  end if;

  perform 1 from public.organizations where id = p_organization_id;
  if not found then
    raise exception 'That organization does not exist.' using errcode = 'foreign_key_violation';
  end if;

  select * into existing
  from public.communication_email_sending_pauses
  where scope = 'organization' and organization_id = p_organization_id
    and source = 'manual' and released_at is null
  order by engaged_at desc
  for update;

  if p_engage then
    if found then
      return existing.id;
    end if;
    insert into public.communication_email_sending_pauses (
      scope, organization_id, reason, engaged_by_owner_email, source, applies_to
    )
    values ('organization', p_organization_id, clean_reason, actor, 'manual', 'all')
    returning id into new_id;
    insert into public.platform_owner_audit_events (
      actor_owner_email, event_type, target_type, target_key, after_state
    ) values (
      actor, 'communications.email_organization_pause_engaged', 'organization',
      p_organization_id::text, jsonb_build_object('pause_id', new_id, 'reason', clean_reason)
    );
    return new_id;
  end if;

  if not found then
    return null;
  end if;
  update public.communication_email_sending_pauses
  set released_at = now(), released_by_owner_email = actor, released_reason = clean_reason
  where id = existing.id;
  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor, 'communications.email_organization_pause_released', 'organization',
    p_organization_id::text,
    jsonb_build_object('pause_id', existing.id, 'engaged_reason', existing.reason,
      'engaged_by', existing.engaged_by_owner_email),
    jsonb_build_object('released_reason', clean_reason)
  );
  return existing.id;
end;
$$;


ALTER FUNCTION "public"."set_communication_email_organization_pause"("p_organization_id" "uuid", "p_engage" boolean, "p_reason" "text", "p_actor_email" "text") OWNER TO "postgres";


