CREATE OR REPLACE FUNCTION "public"."set_communication_email_provider_capacity"("p_capacity" integer, "p_reserve_percent" integer, "p_reason" "text", "p_actor_email" "text", "p_confirm_platform_change" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor text := lower(btrim(coalesce(p_actor_email, '')));
  clean_reason text := btrim(coalesce(p_reason, ''));
  live public.communication_email_platform_sending_settings%rowtype;
  new_id uuid;
begin
  if char_length(actor) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if char_length(clean_reason) not between 3 and 500 then
    raise exception 'A reason of 3 to 500 characters is required.' using errcode = 'check_violation';
  end if;
  if p_capacity is not null and (p_capacity < 1 or p_capacity > 1000000000) then
    raise exception 'A provider-period capacity of 1 to 1,000,000,000 recipients is required, or none to turn the limit off.'
      using errcode = 'check_violation';
  end if;
  if p_reserve_percent is null or p_reserve_percent < 0 or p_reserve_percent > 100 then
    raise exception 'A reserve of 0 to 100 percent is required.' using errcode = 'check_violation';
  end if;
  if not coalesce(p_confirm_platform_change, false) then
    raise exception 'Changing the provider-period sending capacity requires explicit confirmation.'
      using errcode = 'check_violation';
  end if;

  select * into live
  from public.communication_email_platform_sending_settings
  where effective_to is null
  for update;
  if not found then
    raise exception 'No live platform sending settings row exists.'
      using errcode = 'foreign_key_violation';
  end if;

  update public.communication_email_platform_sending_settings
  set effective_to = now() where id = live.id;

  insert into public.communication_email_platform_sending_settings (
    short_term_window_minutes, short_term_max_recipients,
    provider_period_capacity, reserve_percent, reason, actor_owner_email
  ) values (
    live.short_term_window_minutes, live.short_term_max_recipients,
    p_capacity, p_reserve_percent, clean_reason, actor
  )
  returning id into new_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor, 'communications.email_provider_capacity_changed',
    'communication_email_platform_sending_settings', new_id::text,
    to_jsonb(live) - 'id',
    jsonb_build_object('provider_period_capacity', p_capacity, 'reserve_percent', p_reserve_percent,
      'reason', clean_reason)
  );

  return jsonb_build_object('id', new_id, 'provider_period_capacity', p_capacity,
    'reserve_percent', p_reserve_percent);
end;
$$;


ALTER FUNCTION "public"."set_communication_email_provider_capacity"("p_capacity" integer, "p_reserve_percent" integer, "p_reason" "text", "p_actor_email" "text", "p_confirm_platform_change" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_communication_email_reputation_threshold"("p_scope" "text", "p_organization_id" "uuid", "p_signal" "text", "p_window_key" "text", "p_window_hours" integer, "p_warn_rate" numeric, "p_pause_rate" numeric, "p_min_sample_recipients" integer, "p_min_event_count" integer, "p_reason" "text", "p_actor_email" "text", "p_confirm_platform_change" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor text := lower(btrim(coalesce(p_actor_email, '')));
  clean_reason text := btrim(coalesce(p_reason, ''));
  ceiling public.communication_email_reputation_thresholds%rowtype;
  existing public.communication_email_reputation_thresholds%rowtype;
  new_id uuid;
  impact_count integer := 0;
begin
  if char_length(actor) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if char_length(clean_reason) not between 3 and 500 then
    raise exception 'A reason of 3 to 500 characters is required.' using errcode = 'check_violation';
  end if;
  if p_scope not in ('platform', 'organization') then
    raise exception 'The threshold scope is invalid.' using errcode = 'check_violation';
  end if;
  if p_signal not in ('complaint', 'hard_bounce', 'unsubscribe')
    or p_window_key not in ('rolling_24h', 'rolling_7d') then
    raise exception 'The reputation signal or window is invalid.' using errcode = 'check_violation';
  end if;

  select * into ceiling
  from public.communication_email_reputation_thresholds
  where scope = 'platform' and signal = p_signal and window_key = p_window_key and effective_to is null
  for update;
  if not found then
    raise exception 'No platform threshold exists for that signal and window.'
      using errcode = 'foreign_key_violation';
  end if;

  if p_scope = 'platform' then
    if not coalesce(p_confirm_platform_change, false) then
      raise exception 'Changing the platform safety ceiling requires explicit confirmation.'
        using errcode = 'check_violation';
    end if;
    if p_organization_id is not null then
      raise exception 'A platform threshold has no organization.' using errcode = 'check_violation';
    end if;
    if p_window_hours is null or p_warn_rate is null or p_pause_rate is null
      or p_min_sample_recipients is null then
      raise exception 'A platform threshold needs a window, both rates, and a sample size.'
        using errcode = 'check_violation';
    end if;

    select count(*)::integer into impact_count
    from public.communication_email_reputation_thresholds org
    where org.scope = 'organization' and org.signal = p_signal
      and org.window_key = p_window_key and org.effective_to is null;

    update public.communication_email_reputation_thresholds
    set effective_to = now() where id = ceiling.id;

    insert into public.communication_email_reputation_thresholds (
      scope, signal, window_key, window_hours, warn_rate, pause_rate, min_sample_recipients,
      min_event_count, reason, actor_owner_email
    ) values (
      'platform', p_signal, p_window_key, p_window_hours, p_warn_rate, p_pause_rate,
      p_min_sample_recipients, p_min_event_count, clean_reason, actor
    )
    returning id into new_id;

    insert into public.platform_owner_audit_events (
      actor_owner_email, event_type, target_type, target_key, before_state, after_state
    ) values (
      actor, 'communications.email_reputation_platform_threshold_changed',
      'communication_email_reputation_threshold', new_id::text,
      to_jsonb(ceiling) - 'id',
      jsonb_build_object('signal', p_signal, 'window_key', p_window_key, 'window_hours', p_window_hours,
        'warn_rate', p_warn_rate, 'pause_rate', p_pause_rate,
        'min_sample_recipients', p_min_sample_recipients, 'min_event_count', p_min_event_count,
        'reason', clean_reason, 'organization_overrides_affected', impact_count)
    );

    return jsonb_build_object('id', new_id, 'scope', 'platform',
      'organization_overrides_affected', impact_count);
  end if;

  if p_organization_id is null then
    raise exception 'An organization is required for an organization threshold.'
      using errcode = 'check_violation';
  end if;
  if p_window_hours is not null then
    raise exception 'Observation windows are set at the platform level only.'
      using errcode = 'check_violation';
  end if;
  perform 1 from public.organizations where id = p_organization_id;
  if not found then
    raise exception 'That organization does not exist.' using errcode = 'foreign_key_violation';
  end if;

  select * into existing
  from public.communication_email_reputation_thresholds
  where scope = 'organization' and organization_id = p_organization_id
    and signal = p_signal and window_key = p_window_key and effective_to is null
  for update;

  if num_nonnulls(p_warn_rate, p_pause_rate, p_min_sample_recipients, p_min_event_count) = 0 then
    if not found then
      return jsonb_build_object('id', null, 'scope', 'organization', 'cleared', true);
    end if;
    update public.communication_email_reputation_thresholds
    set effective_to = now() where id = existing.id;
    insert into public.platform_owner_audit_events (
      actor_owner_email, event_type, target_type, target_key, before_state, after_state
    ) values (
      actor, 'communications.email_reputation_organization_threshold_cleared', 'organization',
      p_organization_id::text, to_jsonb(existing) - 'id',
      jsonb_build_object('reason', clean_reason)
    );
    return jsonb_build_object('id', existing.id, 'scope', 'organization', 'cleared', true);
  end if;

  if p_warn_rate is not null and p_warn_rate > ceiling.warn_rate then
    raise exception 'An organization warning rate cannot exceed the platform ceiling of %.',
      ceiling.warn_rate using errcode = 'check_violation';
  end if;
  if p_pause_rate is not null and p_pause_rate > ceiling.pause_rate then
    raise exception 'An organization pause rate cannot exceed the platform ceiling of %.',
      ceiling.pause_rate using errcode = 'check_violation';
  end if;
  if p_min_sample_recipients is not null and p_min_sample_recipients > ceiling.min_sample_recipients then
    raise exception 'An organization sample size cannot exceed the platform ceiling of %.',
      ceiling.min_sample_recipients using errcode = 'check_violation';
  end if;
  if p_min_event_count is not null and ceiling.min_event_count is not null
    and p_min_event_count > ceiling.min_event_count then
    raise exception 'An organization event trigger cannot exceed the platform ceiling of %.',
      ceiling.min_event_count using errcode = 'check_violation';
  end if;
  if p_warn_rate is not null and p_pause_rate is not null and p_warn_rate > p_pause_rate then
    raise exception 'The warning rate must be at or below the pause rate.'
      using errcode = 'check_violation';
  end if;

  if found then
    update public.communication_email_reputation_thresholds
    set effective_to = now() where id = existing.id;
  end if;

  insert into public.communication_email_reputation_thresholds (
    scope, organization_id, signal, window_key, warn_rate, pause_rate, min_sample_recipients,
    min_event_count, reason, actor_owner_email
  ) values (
    'organization', p_organization_id, p_signal, p_window_key, p_warn_rate, p_pause_rate,
    p_min_sample_recipients, p_min_event_count, clean_reason, actor
  )
  returning id into new_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor, 'communications.email_reputation_organization_threshold_changed', 'organization',
    p_organization_id::text,
    case when existing.id is not null then to_jsonb(existing) - 'id' end,
    jsonb_build_object('threshold_id', new_id, 'signal', p_signal, 'window_key', p_window_key,
      'warn_rate', p_warn_rate, 'pause_rate', p_pause_rate,
      'min_sample_recipients', p_min_sample_recipients, 'min_event_count', p_min_event_count,
      'reason', clean_reason)
  );

  return jsonb_build_object('id', new_id, 'scope', 'organization', 'cleared', false);
end;
$$;


ALTER FUNCTION "public"."set_communication_email_reputation_threshold"("p_scope" "text", "p_organization_id" "uuid", "p_signal" "text", "p_window_key" "text", "p_window_hours" integer, "p_warn_rate" numeric, "p_pause_rate" numeric, "p_min_sample_recipients" integer, "p_min_event_count" integer, "p_reason" "text", "p_actor_email" "text", "p_confirm_platform_change" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_communication_email_short_term_rate"("p_window_minutes" integer, "p_max_recipients" integer, "p_reason" "text", "p_actor_email" "text", "p_confirm_platform_change" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor text := lower(btrim(coalesce(p_actor_email, '')));
  clean_reason text := btrim(coalesce(p_reason, ''));
  live public.communication_email_platform_sending_settings%rowtype;
  new_id uuid;
begin
  if char_length(actor) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if char_length(clean_reason) not between 3 and 500 then
    raise exception 'A reason of 3 to 500 characters is required.' using errcode = 'check_violation';
  end if;
  if p_window_minutes is null or p_window_minutes < 1 or p_window_minutes > 1440 then
    raise exception 'A window of 1 to 1440 minutes is required.' using errcode = 'check_violation';
  end if;
  if p_max_recipients is null or p_max_recipients < 1 or p_max_recipients > 10000000 then
    raise exception 'A recipient ceiling of 1 to 10,000,000 is required.' using errcode = 'check_violation';
  end if;
  if not coalesce(p_confirm_platform_change, false) then
    raise exception 'Changing the short-term sending rate requires explicit confirmation.'
      using errcode = 'check_violation';
  end if;

  select * into live
  from public.communication_email_platform_sending_settings
  where effective_to is null
  for update;
  if not found then
    raise exception 'No live platform sending settings row exists.'
      using errcode = 'foreign_key_violation';
  end if;

  update public.communication_email_platform_sending_settings
  set effective_to = now() where id = live.id;

  insert into public.communication_email_platform_sending_settings (
    short_term_window_minutes, short_term_max_recipients,
    provider_period_capacity, reserve_percent, reason, actor_owner_email
  ) values (
    p_window_minutes, p_max_recipients,
    live.provider_period_capacity, live.reserve_percent, clean_reason, actor
  )
  returning id into new_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor, 'communications.email_short_term_rate_changed',
    'communication_email_platform_sending_settings', new_id::text,
    to_jsonb(live) - 'id',
    jsonb_build_object('window_minutes', p_window_minutes, 'max_recipients', p_max_recipients,
      'reason', clean_reason)
  );

  return jsonb_build_object('id', new_id, 'window_minutes', p_window_minutes,
    'max_recipients', p_max_recipients);
end;
$$;


ALTER FUNCTION "public"."set_communication_email_short_term_rate"("p_window_minutes" integer, "p_max_recipients" integer, "p_reason" "text", "p_actor_email" "text", "p_confirm_platform_change" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_communication_email_warmup_stage"("p_stage_key" "text", "p_daily_ceiling" integer, "p_reason" "text", "p_actor_email" "text", "p_confirm_platform_change" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor text := lower(btrim(coalesce(p_actor_email, '')));
  clean_reason text := btrim(coalesce(p_reason, ''));
  live public.communication_email_warmup_stages%rowtype;
  new_id uuid;
begin
  if char_length(actor) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if char_length(clean_reason) not between 3 and 500 then
    raise exception 'A reason of 3 to 500 characters is required.' using errcode = 'check_violation';
  end if;
  if p_stage_key not in ('days_1_3', 'days_4_7', 'days_8_14') then
    raise exception 'The warm-up stage is invalid.' using errcode = 'check_violation';
  end if;
  if p_daily_ceiling is null or p_daily_ceiling < 0 or p_daily_ceiling > 10000000 then
    raise exception 'A daily ceiling of 0 to 10,000,000 is required.' using errcode = 'check_violation';
  end if;
  if not coalesce(p_confirm_platform_change, false) then
    raise exception 'Changing a platform warm-up ceiling requires explicit confirmation.'
      using errcode = 'check_violation';
  end if;

  select * into live
  from public.communication_email_warmup_stages
  where scope = 'platform' and stage_key = p_stage_key and effective_to is null
  for update;
  if not found then
    raise exception 'No platform warm-up ceiling exists for that stage.'
      using errcode = 'foreign_key_violation';
  end if;

  update public.communication_email_warmup_stages
  set effective_to = now() where id = live.id;

  insert into public.communication_email_warmup_stages (
    scope, stage_key, daily_ceiling, reason, actor_owner_email
  ) values (
    'platform', p_stage_key, p_daily_ceiling, clean_reason, actor
  )
  returning id into new_id;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor, 'communications.email_warmup_stage_changed',
    'communication_email_warmup_stage', new_id::text,
    to_jsonb(live) - 'id',
    jsonb_build_object('stage_key', p_stage_key, 'daily_ceiling', p_daily_ceiling, 'reason', clean_reason)
  );

  return jsonb_build_object('id', new_id, 'stage_key', p_stage_key, 'daily_ceiling', p_daily_ceiling);
end;
$$;


ALTER FUNCTION "public"."set_communication_email_warmup_stage"("p_stage_key" "text", "p_daily_ceiling" integer, "p_reason" "text", "p_actor_email" "text", "p_confirm_platform_change" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_form_default"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  form_row public.forms;
begin
  if not private.has_permission(target_organization_id, 'settings.forms.manage') then
    raise exception 'You do not have access to manage forms.' using errcode = 'insufficient_privilege';
  end if;

  select * into form_row from public.forms
  where id = target_form_id and organization_id = target_organization_id
  for update;

  if form_row.id is null then
    raise exception 'That form was not found.' using errcode = 'check_violation';
  end if;
  if form_row.archived_at is not null then
    raise exception 'An archived form cannot be the default. Restore it first.'
      using errcode = 'check_violation';
  end if;
  if expected_revision is distinct from form_row.revision then
    raise exception 'Someone else changed this form while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  if form_row.is_default then
    return jsonb_build_object('form_id', form_row.id, 'is_default', true, 'revision', form_row.revision);
  end if;

  -- Clear the current default in the same group: "request" stands alone; "assessment" and "job" share the
  -- one "booking" default slot, matching "one default request form and one default booking form."
  update public.forms
  set is_default = false, revision = revision + 1, updated_by = (select auth.uid()), updated_at = now()
  where organization_id = target_organization_id
    and archived_at is null
    and is_default
    and id <> form_row.id
    and (outcome = 'request') = (form_row.outcome = 'request');

  update public.forms
  set is_default = true, revision = revision + 1, updated_by = (select auth.uid()), updated_at = now()
  where id = form_row.id
  returning * into form_row;

  return jsonb_build_object('form_id', form_row.id, 'is_default', true, 'revision', form_row.revision);
end;
$$;


ALTER FUNCTION "public"."set_form_default"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_import_batch_error_file"("target_batch_id" "uuid", "object_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if target_batch_id is null then
    raise exception 'batch_id is required.' using errcode = 'invalid_parameter_value';
  end if;
  update public.import_batches
  set error_file_object_key = nullif(trim(object_key), '')
  where id = target_batch_id;
end;
$$;


ALTER FUNCTION "public"."set_import_batch_error_file"("target_batch_id" "uuid", "object_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_import_batch_error_file"("target_batch_id" "uuid", "object_key" "text") IS 'Records the R2 object key of the per-row error file the import worker generated for a batch. Service-role only; the app never calls it (rule 12: import_batches has no update policy). SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."set_import_batch_mapping"("payload" "jsonb") RETURNS "public"."import_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_batch_id uuid := (payload->>'batch_id')::uuid;
  target_batch public.import_batches;
begin
  if target_batch_id is null then
    raise exception 'batch_id is required.' using errcode = 'invalid_parameter_value';
  end if;

  select * into target_batch from public.import_batches where id = target_batch_id;
  if not found then
    raise exception 'That import was not found.' using errcode = 'no_data_found';
  end if;

  if not private.has_permission(
    target_batch.organization_id, private.import_batch_entity_permission(target_batch.entity_type)
  ) then
    raise exception 'You do not have permission to change this import.'
      using errcode = 'insufficient_privilege';
  end if;

  if target_batch.status not in ('uploaded', 'mapped') then
    raise exception 'This import can no longer be changed.'
      using errcode = 'invalid_parameter_value';
  end if;

  update public.import_batches
  set column_mapping = coalesce(payload->'column_mapping', '{}'::jsonb),
      match_action = coalesce(payload->>'match_action', match_action),
      status = 'mapped'
  where id = target_batch_id
  returning * into target_batch;

  return target_batch;
end;
$$;


ALTER FUNCTION "public"."set_import_batch_mapping"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_import_batch_mapping"("payload" "jsonb") IS 'Saves a batch''s column mapping (+ match_action, for entity types that use it) and moves it uploaded/mapped -> mapped. Entity-agnostic: the write permission it backstops against comes from private.import_batch_entity_permission(batch.entity_type), not a hardcoded key.';



CREATE OR REPLACE FUNCTION "public"."set_inquiry_alert_recipients"("p_organization_id" "uuid", "p_actor_id" "uuid", "p_user_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  wanted uuid[] := coalesce((select array_agg(distinct u) from unnest(p_user_ids) as u where u is not null), '{}');
begin
  if p_organization_id is null or p_actor_id is null then
    raise exception 'An organization and an actor are required.' using errcode = 'check_violation';
  end if;
  if cardinality(wanted) > 50 then
    raise exception 'Choose at most 50 people.' using errcode = 'check_violation';
  end if;
  if not private.member_has_permission(p_organization_id, p_actor_id, 'conversations.manage_connections') then
    raise exception 'You do not have permission to change inquiry alerts.' using errcode = 'insufficient_privilege';
  end if;
  if exists (
    select 1 from unnest(wanted) as u
    where not private.member_receives_inquiry_alerts(p_organization_id, u)
  ) then
    raise exception 'Someone chosen cannot see every website inquiry.' using errcode = 'check_violation';
  end if;

  -- Serialize concurrent saves for one organization so the last save wins as a whole set.
  perform pg_advisory_xact_lock(hashtextextended('inquiry_alert_recipients:' || p_organization_id::text, 0));

  delete from public.inquiry_alert_recipients
  where organization_id = p_organization_id and user_id <> all (wanted);

  insert into public.inquiry_alert_recipients (organization_id, user_id, created_by)
  select p_organization_id, u, p_actor_id from unnest(wanted) as u
  on conflict (organization_id, user_id) do nothing;

  return cardinality(wanted);
end;
$$;


ALTER FUNCTION "public"."set_inquiry_alert_recipients"("p_organization_id" "uuid", "p_actor_id" "uuid", "p_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_invoice_discount"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_name" "text", "new_type" "text", "new_value" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  invoice_row public.invoices;
  clean_type text := nullif(trim(coalesce(new_type, '')), '');
  clean_name text := nullif(trim(coalesce(new_name, '')), '');
  money jsonb;
begin
  invoice_row := private.lock_invoice_for_edit(
    target_organization_id, target_invoice_id, expected_revision
  );
  perform private.require_invoice_price_access(target_organization_id);

  if clean_type is not null and clean_type not in ('fixed', 'percentage') then
    raise exception 'A discount is either a fixed amount or a percentage.' using errcode = 'check_violation';
  end if;
  if clean_type is not null and (new_value is null or new_value < 0) then
    raise exception 'A discount needs an amount.' using errcode = 'check_violation';
  end if;
  if clean_type = 'percentage' and new_value > 10000 then
    raise exception 'A percentage discount is between 0 and 100 percent.' using errcode = 'check_violation';
  end if;
  if clean_type is not null and clean_name is null then
    raise exception 'Give this discount a name the customer will recognize.'
      using errcode = 'check_violation';
  end if;

  perform private.retain_prior_invoice_document(invoice_row, caller, 'discount changed');

  update public.invoices
  set discount_name = case when clean_type is null then null else clean_name end,
      discount_type = clean_type,
      discount_value = case when clean_type is null then null else new_value end
  where organization_id = target_organization_id and id = target_invoice_id;

  money := private.store_invoice_money(target_invoice_id);

  update public.invoices
  set revision = invoice_row.revision + 1
  where organization_id = target_organization_id and id = target_invoice_id;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.discount_updated', caller, invoice_row.revision + 1, null,
    jsonb_build_object('type', clean_type), false, null
  );

  return jsonb_build_object('revision', invoice_row.revision + 1, 'totals', money - 'lines');
end;
$$;


ALTER FUNCTION "public"."set_invoice_discount"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_name" "text", "new_type" "text", "new_value" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_invoice_online_partial_payments"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_allowed" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  invoice_row public.invoices;
begin
  if caller is null
     or not private.member_has_permission(target_organization_id, caller, 'invoices.edit') then
    raise exception 'You do not have access to change this invoice.' using errcode = 'insufficient_privilege';
  end if;
  if new_allowed is null then
    raise exception 'Choose whether partial payments are allowed.' using errcode = 'check_violation';
  end if;

  select * into invoice_row
  from public.invoices
  where organization_id = target_organization_id and id = target_invoice_id
  for update;
  if not found then
    raise exception 'That invoice could not be found.' using errcode = 'P0404';
  end if;
  if new_allowed and private.invoice_progress_context(invoice_row) is not null then
    raise exception 'Progress invoices are always paid in full.' using errcode = 'check_violation';
  end if;

  if invoice_row.online_partial_payments_allowed is distinct from new_allowed then
    update public.invoices
    set online_partial_payments_allowed = new_allowed
    where organization_id = target_organization_id and id = target_invoice_id;

    perform private.record_invoice_event(
      invoice_row.organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
      case when new_allowed then 'invoice.online_partial_allowed' else 'invoice.online_partial_disallowed' end,
      caller, invoice_row.revision
    );
  end if;

  return jsonb_build_object('online_partial_payments_allowed', new_allowed);
end;
$$;


ALTER FUNCTION "public"."set_invoice_online_partial_payments"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_allowed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_invoice_tax"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_source" "text", "new_rate_id" "uuid" DEFAULT NULL::"uuid", "new_custom_name" "text" DEFAULT NULL::"text", "new_custom_rate_basis_points" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  invoice_row public.invoices;
  rate_row public.organization_tax_rates;
  resolved_tax record;
  first_property uuid;
  clean_name text;
  clean_rate integer;
  money jsonb;
begin
  invoice_row := private.lock_invoice_for_edit(
    target_organization_id, target_invoice_id, expected_revision
  );
  perform private.require_invoice_price_access(target_organization_id);

  if new_source not in ('business_default', 'property_default', 'saved_rate', 'no_tax', 'custom') then
    raise exception 'Choose a tax option.' using errcode = 'check_violation';
  end if;

  perform private.retain_prior_invoice_document(invoice_row, caller, 'tax changed');

  if new_source in ('business_default', 'property_default') then
    first_property := nullif(invoice_row.service_properties->0->>'property_id', '')::uuid;

    select * into resolved_tax
    from private.resolve_property_tax(target_organization_id, first_property);

    update public.invoices
    set tax_source = resolved_tax.source, tax_name = resolved_tax.name,
        tax_rate_basis_points = resolved_tax.rate_basis_points, tax_rate_id = resolved_tax.rate_id
    where organization_id = target_organization_id and id = target_invoice_id;

  elsif new_source = 'saved_rate' then
    select * into rate_row
    from public.organization_tax_rates
    where id = new_rate_id and organization_id = target_organization_id and is_active;
    if rate_row.id is null then
      raise exception 'Choose an active saved tax rate.' using errcode = 'check_violation';
    end if;

    update public.invoices
    set tax_source = 'saved_rate', tax_name = rate_row.name,
        tax_rate_basis_points = rate_row.rate_basis_points, tax_rate_id = rate_row.id
    where organization_id = target_organization_id and id = target_invoice_id;

  elsif new_source = 'no_tax' then
    update public.invoices
    set tax_source = 'no_tax', tax_name = null, tax_rate_basis_points = 0, tax_rate_id = null
    where organization_id = target_organization_id and id = target_invoice_id;

  else
    clean_rate := coalesce(new_custom_rate_basis_points, 0);
    if clean_rate <= 0 or clean_rate > 10000 then
      raise exception 'A tax rate is between 0 and 100 percent.' using errcode = 'check_violation';
    end if;
    clean_name := nullif(trim(coalesce(new_custom_name, '')), '');
    if clean_name is null or char_length(clean_name) > 80 then
      raise exception 'Give this tax a name the customer will recognize, under 80 characters.'
        using errcode = 'check_violation';
    end if;

    update public.invoices
    set tax_source = 'custom', tax_name = clean_name, tax_rate_basis_points = clean_rate,
        tax_rate_id = null
    where organization_id = target_organization_id and id = target_invoice_id;
  end if;

  money := private.store_invoice_money(target_invoice_id);

  update public.invoices
  set revision = invoice_row.revision + 1
  where organization_id = target_organization_id and id = target_invoice_id;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.tax_updated', caller, invoice_row.revision + 1, null,
    jsonb_build_object('source', new_source), false, null
  );

  return jsonb_build_object('revision', invoice_row.revision + 1, 'totals', money - 'lines');
end;
$$;


ALTER FUNCTION "public"."set_invoice_tax"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_source" "text", "new_rate_id" "uuid", "new_custom_name" "text", "new_custom_rate_basis_points" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_job_billing"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_price_basis" "text", "new_billing_timing" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  clean_basis text := nullif(trim(coalesce(new_price_basis, '')), '');
  clean_timing text := nullif(trim(coalesce(new_billing_timing, '')), '');
  changed text[] := array[]::text[];
begin
  current_job := private.lock_job_for_edit(target_organization_id, target_job_id, expected_revision);

  clean_basis := coalesce(clean_basis, current_job.price_basis);
  clean_timing := coalesce(clean_timing, current_job.billing_timing);

  if current_job.job_type = 'one_off' and clean_basis <> 'job_total' then
    raise exception 'A one-off job is priced as a whole job.' using errcode = 'check_violation';
  end if;
  if current_job.job_type = 'recurring' and clean_basis not in ('per_visit', 'fixed_per_period') then
    raise exception 'Repeating work is priced per visit or per billing period.' using errcode = 'check_violation';
  end if;
  if clean_timing not in ('on_closure', 'per_completed_visit', 'month_end', 'custom_dates', 'manual') then
    raise exception 'Choose when this job should be invoiced.' using errcode = 'check_violation';
  end if;

  if clean_basis is distinct from current_job.price_basis then
    changed := array_append(changed, 'price_basis');
  end if;
  if clean_timing is distinct from current_job.billing_timing then
    changed := array_append(changed, 'billing_timing');
  end if;

  update public.jobs
  set price_basis = clean_basis,
      billing_timing = clean_timing,
      revision = current_job.revision + 1
  where organization_id = target_organization_id
    and id = target_job_id;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'billing_updated',
    caller,
    jsonb_build_object(
      'changed', to_jsonb(changed),
      'price_basis', clean_basis,
      'billing_timing', clean_timing
    )
  );

  return jsonb_build_object(
    'revision', current_job.revision + 1,
    'price_basis', clean_basis,
    'billing_timing', clean_timing
  );
end;
$$;


ALTER FUNCTION "public"."set_job_billing"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_price_basis" "text", "new_billing_timing" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_job_billing"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_price_basis" "text", "new_billing_timing" "text") IS 'Sets a job''s price basis and invoicing timing. Never enables a charge: collection belongs to Payments.';



CREATE OR REPLACE FUNCTION "public"."set_job_discount"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_name" "text", "new_type" "text", "new_value" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  clean_type text := nullif(trim(coalesce(new_type, '')), '');
  clean_name text := nullif(trim(coalesce(new_name, '')), '');
begin
  current_job := private.lock_job_for_edit(target_organization_id, target_job_id, expected_revision);

  if clean_type is null then
    update public.jobs
    set discount_name = null, discount_type = null, discount_value = null
    where organization_id = target_organization_id and id = target_job_id;
  else
    if clean_type not in ('fixed', 'percentage') then
      raise exception 'A discount is either a fixed amount or a percentage.' using errcode = 'check_violation';
    end if;
    if clean_name is null then
      raise exception 'Give this discount a name the customer will recognize.' using errcode = 'check_violation';
    end if;
    if coalesce(new_value, 0) < 0 then
      raise exception 'A discount cannot be negative.' using errcode = 'check_violation';
    end if;
    if clean_type = 'percentage' and coalesce(new_value, 0) > 10000 then
      raise exception 'A percentage discount is between 0 and 100 percent.' using errcode = 'check_violation';
    end if;

    update public.jobs
    set discount_name = clean_name, discount_type = clean_type, discount_value = coalesce(new_value, 0)
    where organization_id = target_organization_id and id = target_job_id;
  end if;

  perform private.store_job_money(target_job_id);

  update public.jobs
  set revision = current_job.revision + 1
  where organization_id = target_organization_id and id = target_job_id;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'discount_updated',
    caller,
    jsonb_build_object('removed', clean_type is null, 'discount_type', clean_type)
  );

  return jsonb_build_object('revision', current_job.revision + 1);
end;
$$;


ALTER FUNCTION "public"."set_job_discount"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_name" "text", "new_type" "text", "new_value" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_job_discount"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_name" "text", "new_type" "text", "new_value" bigint) IS 'Sets or removes the job''s single discount and recalculates its money. A null type removes the discount.';



CREATE OR REPLACE FUNCTION "public"."set_job_payment_schedule"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  item_count integer := 0;
  locked_count integer;
  deposit_id uuid;
  priced jsonb;
  schedule_mode text;
begin
  current_job := private.lock_job_for_edit(target_organization_id, target_job_id, expected_revision);

  if current_job.job_type <> 'one_off' then
    raise exception 'Only a one-off job can carry a payment schedule.' using errcode = 'check_violation';
  end if;

  select count(*) filter (where stage.locked_amount_minor is not null)
  into locked_count
  from public.job_payment_schedule_items as stage
  where stage.organization_id = target_organization_id
    and stage.job_id = target_job_id;

  -- At most one stage carries the quote deposit's identity; the table's partial unique index says so.
  select stage.id
  into deposit_id
  from public.job_payment_schedule_items as stage
  where stage.organization_id = target_organization_id
    and stage.job_id = target_job_id
    and stage.is_deposit;

  if new_items is not null and jsonb_typeof(new_items) <> 'array' then
    raise exception 'Send the payment schedule as a list.' using errcode = 'check_violation';
  end if;
  if new_items is not null then
    item_count := jsonb_array_length(new_items);
  end if;

  if item_count = 0 then
    -- Back to billing the job as a whole. Only available while the plan is still only a plan.
    if locked_count > 0 then
      raise exception
        'One of these payment stages already has an invoice, so this schedule cannot be removed.'
        using errcode = 'check_violation';
    end if;

    delete from public.job_payment_schedule_items
    where organization_id = target_organization_id and job_id = target_job_id;
  else
    -- One answer for what the schedule is worth and whether it is allowed, shared with the reader below and
    -- with the invoice handoff in 5c-3. It refuses a mixed mode, a count outside 2..12, a total that does not
    -- reconcile, and any change to a stage that has already been invoiced.
    priced := private.price_job_payment_schedule(target_job_id, new_items);
    schedule_mode := priced ->> 'mode';

    -- Every stage that is still a plan is rewritten from the list; the invoiced ones are left exactly as they
    -- are. Rewriting rather than patching is what keeps positions unique without a reordering dance, and an
    -- unbilled stage is referenced by nothing, so nothing loses its footing when its row is replaced.
    delete from public.job_payment_schedule_items as stage
    where stage.organization_id = target_organization_id
      and stage.job_id = target_job_id
      and stage.locked_amount_minor is null;

    insert into public.job_payment_schedule_items (
      organization_id, job_id, position, description, value_type, value, is_deposit
    )
    select
      target_organization_id,
      target_job_id,
      (entry ->> 'position')::integer,
      entry ->> 'description',
      entry ->> 'value_type',
      (entry ->> 'value')::bigint,
      -- The quote deposit's identity travels with the stage that carries it, by id. A schedule authored on
      -- the job itself has no deposit stage: money that changed hands is a quote receipt, and this command
      -- never invents one.
      deposit_id is not null and nullif(entry ->> 'installment_id', '')::uuid = deposit_id
    from jsonb_array_elements(priced -> 'items') as entry
    where not exists (
      select 1
      from public.job_payment_schedule_items as kept
      where kept.organization_id = target_organization_id
        and kept.id = nullif(entry ->> 'installment_id', '')::uuid
    );
  end if;

  update public.jobs
  set revision = current_job.revision + 1
  where organization_id = target_organization_id and id = target_job_id;

  -- Counts and the mode only. A job's history rail is readable by anyone who may see the job, and stage
  -- amounts are not.
  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'payment_schedule_updated',
    caller,
    jsonb_build_object(
      'stage_count', item_count,
      'locked_count', locked_count,
      'mode', schedule_mode
    )
  );

  return jsonb_build_object(
    'revision', current_job.revision + 1,
    'stage_count', item_count,
    'mode', schedule_mode
  );
end;
$$;


ALTER FUNCTION "public"."set_job_payment_schedule"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_job_payment_schedule"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_items" "jsonb") IS 'Replaces a one-off job''s payment stages in one transaction. Stages that already have an invoice survive unchanged; an empty list removes the schedule, but only while none of it has been billed.';



CREATE OR REPLACE FUNCTION "public"."set_job_tax"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_source" "text", "new_rate_id" "uuid" DEFAULT NULL::"uuid", "new_custom_name" "text" DEFAULT NULL::"text", "new_custom_rate_basis_points" integer DEFAULT NULL::integer, "save_as_reusable" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  rate_row public.organization_tax_rates;
  resolved_tax record;
  clean_name text;
  clean_rate integer;
begin
  current_job := private.lock_job_for_edit(target_organization_id, target_job_id, expected_revision);

  if new_source not in ('business_default', 'property_default', 'saved_rate', 'no_tax', 'custom') then
    raise exception 'Choose a tax option.' using errcode = 'check_violation';
  end if;

  if new_source in ('business_default', 'property_default') then
    select * into resolved_tax
    from private.resolve_property_tax(target_organization_id, current_job.property_id);

    update public.jobs
    set tax_source = resolved_tax.source, tax_name = resolved_tax.name,
        tax_rate_basis_points = resolved_tax.rate_basis_points, tax_rate_id = resolved_tax.rate_id
    where organization_id = target_organization_id and id = target_job_id;

  elsif new_source = 'saved_rate' then
    select * into rate_row
    from public.organization_tax_rates
    where id = new_rate_id and organization_id = target_organization_id and is_active;

    if rate_row.id is null then
      raise exception 'Choose an active saved tax rate.' using errcode = 'check_violation';
    end if;

    update public.jobs
    set tax_source = 'saved_rate', tax_name = rate_row.name,
        tax_rate_basis_points = rate_row.rate_basis_points, tax_rate_id = rate_row.id
    where organization_id = target_organization_id and id = target_job_id;

  elsif new_source = 'no_tax' then
    update public.jobs
    set tax_source = 'no_tax', tax_name = null, tax_rate_basis_points = 0, tax_rate_id = null
    where organization_id = target_organization_id and id = target_job_id;

  else
    clean_rate := coalesce(new_custom_rate_basis_points, 0);
    if clean_rate <= 0 or clean_rate > 10000 then
      raise exception 'A tax rate is between 0 and 100 percent.' using errcode = 'check_violation';
    end if;

    clean_name := nullif(trim(coalesce(new_custom_name, '')), '');
    if clean_name is null or char_length(clean_name) > 80 then
      raise exception 'Give this tax a name the customer will recognize, under 80 characters.'
        using errcode = 'check_violation';
    end if;

    if coalesce(save_as_reusable, false) then
      if not private.has_permission(target_organization_id, 'settings.taxes.manage') then
        raise exception 'You do not have access to save a reusable tax rate.'
          using errcode = 'insufficient_privilege';
      end if;

      insert into public.organization_tax_rates (
        organization_id, name, rate_basis_points, created_by, updated_by
      ) values (target_organization_id, clean_name, clean_rate, caller, caller);
    end if;

    update public.jobs
    set tax_source = 'custom', tax_name = clean_name, tax_rate_basis_points = clean_rate,
        tax_rate_id = null
    where organization_id = target_organization_id and id = target_job_id;
  end if;

  perform private.store_job_money(target_job_id);

  update public.jobs
  set revision = current_job.revision + 1
  where organization_id = target_organization_id and id = target_job_id;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'tax_updated',
    caller,
    jsonb_build_object('source', new_source)
  );

  return jsonb_build_object('revision', current_job.revision + 1);
end;
$$;


ALTER FUNCTION "public"."set_job_tax"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_source" "text", "new_rate_id" "uuid", "new_custom_name" "text", "new_custom_rate_basis_points" integer, "save_as_reusable" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_job_tax"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_source" "text", "new_rate_id" "uuid", "new_custom_name" "text", "new_custom_rate_basis_points" integer, "save_as_reusable" boolean) IS 'Resolves the job''s tax from the business or property default, a saved rate, no tax, or a one-off custom rate, then recalculates its money. Saving a custom rate for reuse needs settings.taxes.manage.';



CREATE OR REPLACE FUNCTION "public"."set_member_cost_rate"("target_organization_id" "uuid", "target_user_id" "uuid", "new_cost_per_hour_minor" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
begin
  if caller is null or not private.member_has_permission(target_organization_id, caller, 'team.manage') then
    raise exception 'You do not have access to change what an employee costs.'
      using errcode = 'insufficient_privilege';
  end if;

  if not exists (
    select 1
    from public.organization_members as member
    where member.organization_id = target_organization_id
      and member.user_id = target_user_id
      and member.status <> 'removed'
  ) then
    raise exception 'That team member was not found.' using errcode = 'P0404';
  end if;

  insert into public.organization_member_cost_profiles (
    organization_id, user_id, cost_per_hour_minor, updated_by
  )
  values (target_organization_id, target_user_id, new_cost_per_hour_minor, caller)
  on conflict (organization_id, user_id) do update
  set cost_per_hour_minor = excluded.cost_per_hour_minor,
      updated_by = excluded.updated_by,
      updated_at = now();

  -- No costing event and no re-pricing pass. A rate change is forward-only by construction: every entry
  -- already carries the rate it was recorded with, and nothing here reaches back to them.
  return jsonb_build_object('cost_per_hour_minor', new_cost_per_hour_minor);
end;
$$;


ALTER FUNCTION "public"."set_member_cost_rate"("target_organization_id" "uuid", "target_user_id" "uuid", "new_cost_per_hour_minor" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_member_cost_rate"("target_organization_id" "uuid", "target_user_id" "uuid", "new_cost_per_hour_minor" bigint) IS 'Sets what an employee costs the business per hour, behind team.manage. Null means unknown, which is not zero: their hours are reported as unrated. Applies forward only -- recorded hours keep the rate they were recorded with.';



CREATE OR REPLACE FUNCTION "public"."set_organization_automation_authority"("p_organization_id" "uuid", "p_axis" "text", "p_engage" boolean, "p_reason" "text", "p_actor_email" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  clean_reason text := btrim(coalesce(p_reason, ''));
  actor text := lower(btrim(coalesce(p_actor_email, '')));
  existing_event public.automation_authority_events%rowtype;
  authority public.organization_automation_authority%rowtype;
  inserted_event public.automation_authority_events%rowtype;
  current_engaged boolean;
  event_kind text;
  before_json jsonb;
  after_json jsonb;
begin
  if p_axis not in ('operational', 'security') then
    raise exception 'An automation authority axis of operational or security is required.' using errcode = 'check_violation';
  end if;
  if char_length(clean_reason) not between 3 and 500 then
    raise exception 'A reason of 3 to 500 characters is required.' using errcode = 'check_violation';
  end if;
  if char_length(actor) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;
  if not exists (select 1 from public.organizations where id = p_organization_id) then
    raise exception 'That organization does not exist.' using errcode = 'foreign_key_violation';
  end if;

  perform pg_advisory_xact_lock(hashtext('automation-authority:' || p_organization_id::text));

  select * into existing_event
  from public.automation_authority_events
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id);
  end if;

  insert into public.organization_automation_authority (organization_id)
  values (p_organization_id)
  on conflict (organization_id) do nothing;

  select * into authority
  from public.organization_automation_authority
  where organization_id = p_organization_id
  for update;

  current_engaged := case p_axis
    when 'operational' then authority.operational_state = 'disabled'
    else authority.security_state = 'suspended'
  end;

  before_json := jsonb_build_object(
    'operational_state', authority.operational_state, 'security_state', authority.security_state
  );

  if current_engaged = p_engage then
    return jsonb_build_object('applied', false, 'no_change', true,
      'operational_state', authority.operational_state, 'security_state', authority.security_state);
  end if;

  if p_axis = 'operational' then
    update public.organization_automation_authority
    set operational_state = case when p_engage then 'disabled' else 'enabled' end,
        operational_reason = case when p_engage then clean_reason else null end,
        operational_changed_at = now()
    where organization_id = p_organization_id
    returning * into authority;
    event_kind := case when p_engage then 'operational_disable_engaged' else 'operational_disable_released' end;
  else
    update public.organization_automation_authority
    set security_state = case when p_engage then 'suspended' else 'active' end,
        security_reason = case when p_engage then clean_reason else null end,
        security_changed_at = now()
    where organization_id = p_organization_id
    returning * into authority;
    event_kind := case when p_engage then 'security_suspension_engaged' else 'security_suspension_released' end;
  end if;

  after_json := jsonb_build_object(
    'operational_state', authority.operational_state, 'security_state', authority.security_state
  );

  insert into public.automation_authority_events (
    organization_id, axis, event_kind, reason, actor_owner_email, before_state, after_state, idempotency_key
  ) values (
    p_organization_id, p_axis, event_kind, clean_reason, actor, before_json, after_json, p_idempotency_key
  ) returning * into inserted_event;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor, 'automations.authority_' || event_kind, 'organization', p_organization_id::text,
    before_json, after_json || jsonb_build_object('reason', clean_reason, 'authority_event_id', inserted_event.id)
  );

  return jsonb_build_object('applied', true, 'event_id', inserted_event.id,
    'operational_state', authority.operational_state, 'security_state', authority.security_state);
end;
$$;


ALTER FUNCTION "public"."set_organization_automation_authority"("p_organization_id" "uuid", "p_axis" "text", "p_engage" boolean, "p_reason" "text", "p_actor_email" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_organization_automation_authority"("p_organization_id" "uuid", "p_axis" "text", "p_engage" boolean, "p_reason" "text", "p_actor_email" "text", "p_idempotency_key" "uuid") IS 'Owner-only writer for one Automation authority axis (operational|security). Idempotent, advisory-locked, audited.';



CREATE OR REPLACE FUNCTION "public"."set_organization_invoice_defaults"("target_organization_id" "uuid", "expected_revision" integer, "new_residential_term_id" "uuid", "new_commercial_term_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings_row public.organization_settings;
begin
  settings_row := private.lock_invoice_settings_for_edit(target_organization_id, expected_revision);

  if new_residential_term_id is null or new_commercial_term_id is null then
    raise exception 'Both the residential and commercial defaults need a payment term.'
      using errcode = 'check_violation';
  end if;

  if exists (
    select 1
    from unnest(array[new_residential_term_id, new_commercial_term_id]) as chosen(term_id)
    where not exists (
      select 1 from public.invoice_payment_terms
      where organization_id = target_organization_id
        and id = chosen.term_id
        and archived_at is null
    )
  ) then
    raise exception 'One of those payment terms is not available.' using errcode = 'check_violation';
  end if;

  update public.organization_settings
  set invoice_default_term_residential_id = new_residential_term_id,
      invoice_default_term_commercial_id = new_commercial_term_id
  where organization_id = target_organization_id;

  return jsonb_build_object(
    'invoice_settings_revision',
      private.bump_invoice_settings(target_organization_id, array['defaults'])
  );
end;
$$;


ALTER FUNCTION "public"."set_organization_invoice_defaults"("target_organization_id" "uuid", "expected_revision" integer, "new_residential_term_id" "uuid", "new_commercial_term_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_organization_logo"("target_organization_id" "uuid", "new_object_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  previous_object_key text;
  new_revision integer;
begin
  if not private.has_permission(target_organization_id, 'settings.business.edit') then
    raise exception 'You do not have access to change business settings.'
      using errcode = 'insufficient_privilege';
  end if;

  if new_object_key is null
     or new_object_key !~ ('^' || target_organization_id::text || '/logo/')
  then
    raise exception 'That logo upload is invalid.' using errcode = 'check_violation';
  end if;

  select logo_object_key into previous_object_key
  from public.organization_settings
  where organization_id = target_organization_id
  for update;

  update public.organization_settings
  set
    logo_object_key = new_object_key,
    branding_revision = branding_revision + 1,
    branding_updated_by = (select auth.uid()),
    branding_updated_at = now()
  where organization_id = target_organization_id
  returning branding_revision into new_revision;

  insert into public.organization_settings_audit (
    organization_id, section, changed_fields, actor_user_id
  )
  values (target_organization_id, 'branding', array['logo'], (select auth.uid()));

  return jsonb_build_object(
    'status', 'saved',
    'branding_revision', new_revision,
    'logo_object_key', new_object_key,
    'previous_object_key', previous_object_key
  );
end;
$$;


