CREATE OR REPLACE FUNCTION "public"."set_organization_payment_settings"("target_organization_id" "uuid", "expected_revision" integer, "new_invoice_payments" boolean, "new_deposit_payments" boolean, "new_tips" boolean, "new_receipt_email" boolean, "new_venmo_username" "text", "new_cash_app_cashtag" "text", "new_paypal_me_username" "text", "new_zelle_contact" "text", "new_e_transfer_email" "text", "new_bank_transfer_instructions" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings_row public.organization_settings;
  editor_name text;
  changed text[] := array[]::text[];
begin
  if not private.has_permission(target_organization_id, 'settings.payments.manage') then
    raise exception 'You do not have access to manage online payments.' using errcode = 'insufficient_privilege';
  end if;

  if new_invoice_payments is null or new_deposit_payments is null or new_tips is null
     or new_receipt_email is null then
    raise exception 'Every payment setting needs a value.' using errcode = 'check_violation';
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for update;

  if settings_row.organization_id is null then
    raise exception 'Organization settings were not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from settings_row.payment_settings_revision then
    select profile.full_name into editor_name
    from public.profiles as profile
    where profile.id = settings_row.payment_settings_updated_by;

    return jsonb_build_object(
      'status', 'stale',
      'editor_name', editor_name,
      'edited_at', coalesce(settings_row.payment_settings_updated_at, settings_row.updated_at)
    );
  end if;

  if new_invoice_payments is distinct from settings_row.online_invoice_payments_enabled then
    changed := array_append(changed, 'online_invoice_payments_enabled');
  end if;
  if new_deposit_payments is distinct from settings_row.online_deposit_payments_enabled then
    changed := array_append(changed, 'online_deposit_payments_enabled');
  end if;
  if new_tips is distinct from settings_row.online_tips_enabled then
    changed := array_append(changed, 'online_tips_enabled');
  end if;
  if new_receipt_email is distinct from settings_row.online_receipt_email_enabled then
    changed := array_append(changed, 'online_receipt_email_enabled');
  end if;
  if new_venmo_username is distinct from settings_row.pay_by_app_venmo_username then
    changed := array_append(changed, 'pay_by_app_venmo_username');
  end if;
  if new_cash_app_cashtag is distinct from settings_row.pay_by_app_cash_app_cashtag then
    changed := array_append(changed, 'pay_by_app_cash_app_cashtag');
  end if;
  if new_paypal_me_username is distinct from settings_row.pay_by_app_paypal_me_username then
    changed := array_append(changed, 'pay_by_app_paypal_me_username');
  end if;
  if new_zelle_contact is distinct from settings_row.pay_by_app_zelle_contact then
    changed := array_append(changed, 'pay_by_app_zelle_contact');
  end if;
  if new_e_transfer_email is distinct from settings_row.pay_by_app_e_transfer_email then
    changed := array_append(changed, 'pay_by_app_e_transfer_email');
  end if;
  if new_bank_transfer_instructions is distinct from settings_row.pay_by_app_bank_transfer_instructions then
    changed := array_append(changed, 'pay_by_app_bank_transfer_instructions');
  end if;

  update public.organization_settings
  set online_invoice_payments_enabled = new_invoice_payments,
      online_deposit_payments_enabled = new_deposit_payments,
      online_tips_enabled = new_tips,
      online_receipt_email_enabled = new_receipt_email,
      pay_by_app_venmo_username = new_venmo_username,
      pay_by_app_cash_app_cashtag = new_cash_app_cashtag,
      pay_by_app_paypal_me_username = new_paypal_me_username,
      pay_by_app_zelle_contact = new_zelle_contact,
      pay_by_app_e_transfer_email = new_e_transfer_email,
      pay_by_app_bank_transfer_instructions = new_bank_transfer_instructions,
      payment_settings_revision = payment_settings_revision + 1,
      payment_settings_updated_by = (select auth.uid()),
      payment_settings_updated_at = now()
  where organization_id = target_organization_id
  returning payment_settings_revision into settings_row.payment_settings_revision;

  if cardinality(changed) > 0 then
    insert into public.organization_settings_audit (organization_id, section, changed_fields, actor_user_id)
    values (target_organization_id, 'payment_settings', changed, (select auth.uid()));
  end if;

  return jsonb_build_object(
    'status', 'saved',
    'payment_settings_revision', settings_row.payment_settings_revision
  );
end;
$$;


ALTER FUNCTION "public"."set_organization_payment_settings"("target_organization_id" "uuid", "expected_revision" integer, "new_invoice_payments" boolean, "new_deposit_payments" boolean, "new_tips" boolean, "new_receipt_email" boolean, "new_venmo_username" "text", "new_cash_app_cashtag" "text", "new_paypal_me_username" "text", "new_zelle_contact" "text", "new_e_transfer_email" "text", "new_bank_transfer_instructions" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_organization_quote_representative"("target_organization_id" "uuid", "expected_revision" integer, "new_enabled" boolean, "new_name" "text", "new_title" "text", "new_signature_object_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings_row public.organization_settings;
  clean_name text;
  clean_title text;
  previous_object_key text;
  editor_name text;
  editor_at timestamptz;
begin
  if not private.has_permission(target_organization_id, 'settings.quotes.manage') then
    raise exception 'You do not have access to manage Quote Settings.' using errcode = 'insufficient_privilege';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  clean_title := nullif(trim(coalesce(new_title, '')), '');

  if new_enabled and clean_name is null then
    raise exception 'Enter a representative name.' using errcode = 'check_violation';
  end if;
  if clean_name is not null and char_length(clean_name) > 160 then
    raise exception 'Keep the representative name under 160 characters.' using errcode = 'check_violation';
  end if;
  if clean_title is not null and char_length(clean_title) > 160 then
    raise exception 'Keep the title under 160 characters.' using errcode = 'check_violation';
  end if;

  if new_signature_object_key is not null
     and new_signature_object_key !~ ('^' || target_organization_id::text || '/quote-representative-signature/')
  then
    raise exception 'That signature upload is invalid.' using errcode = 'check_violation';
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for update;

  if settings_row.organization_id is null then
    raise exception 'Organization settings were not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from settings_row.quote_representative_revision then
    select profile.full_name, settings_row.quote_representative_updated_at into editor_name, editor_at
    from public.profiles as profile
    where profile.id = settings_row.quote_representative_updated_by;

    return jsonb_build_object(
      'status', 'stale',
      'editor_name', editor_name,
      'edited_at', coalesce(editor_at, settings_row.updated_at)
    );
  end if;

  previous_object_key := settings_row.quote_representative_signature_object_key;

  update public.organization_settings
  set quote_representative_enabled = new_enabled,
      quote_representative_name = clean_name,
      quote_representative_title = clean_title,
      quote_representative_signature_object_key = new_signature_object_key,
      quote_representative_revision = quote_representative_revision + 1,
      quote_representative_updated_by = (select auth.uid()),
      quote_representative_updated_at = now()
  where organization_id = target_organization_id
  returning quote_representative_revision into settings_row.quote_representative_revision;

  insert into public.organization_settings_audit (organization_id, section, changed_fields, actor_user_id)
  values (
    target_organization_id, 'quote_representative',
    array['quote_representative_enabled', 'quote_representative_name', 'quote_representative_title', 'quote_representative_signature_object_key'],
    (select auth.uid())
  );

  return jsonb_build_object(
    'status', 'saved',
    'quote_representative_revision', settings_row.quote_representative_revision,
    'quote_representative_enabled', new_enabled,
    'quote_representative_name', clean_name,
    'quote_representative_title', clean_title,
    'quote_representative_signature_object_key', new_signature_object_key,
    'previous_signature_object_key', previous_object_key
  );
end;
$$;


ALTER FUNCTION "public"."set_organization_quote_representative"("target_organization_id" "uuid", "expected_revision" integer, "new_enabled" boolean, "new_name" "text", "new_title" "text", "new_signature_object_key" "text") OWNER TO "postgres";


