CREATE OR REPLACE FUNCTION "public"."set_organization_tax_default"("target_organization_id" "uuid", "expected_revision" integer, "new_source" "text", "new_rate_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings_row public.organization_settings;
  rate_row public.organization_tax_rates;
  editor_name text;
  editor_at timestamptz;
begin
  if not private.has_permission(target_organization_id, 'settings.taxes.manage') then
    raise exception 'You do not have access to manage taxes.' using errcode = 'insufficient_privilege';
  end if;

  if new_source not in ('rate', 'no_tax') then
    raise exception 'Choose a saved rate or No tax.' using errcode = 'check_violation';
  end if;

  select * into settings_row
  from public.organization_settings
  where organization_id = target_organization_id
  for update;

  if settings_row.organization_id is null then
    raise exception 'Organization settings were not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from settings_row.tax_revision then
    select profile.full_name, settings_row.tax_updated_at into editor_name, editor_at
    from public.profiles as profile
    where profile.id = settings_row.tax_updated_by;

    return jsonb_build_object(
      'status', 'stale',
      'editor_name', editor_name,
      'edited_at', coalesce(editor_at, settings_row.updated_at)
    );
  end if;

  if new_source = 'rate' then
    select * into rate_row
    from public.organization_tax_rates
    where id = new_rate_id and organization_id = target_organization_id and is_active;

    if rate_row.id is null then
      raise exception 'Choose an active saved tax rate.' using errcode = 'check_violation';
    end if;
  else
    new_rate_id := null;
  end if;

  update public.organization_settings
  set tax_default_source = new_source, tax_default_rate_id = new_rate_id,
      tax_revision = tax_revision + 1, tax_updated_by = (select auth.uid()), tax_updated_at = now()
  where organization_id = target_organization_id
  returning tax_revision into settings_row.tax_revision;

  insert into public.organization_settings_audit (organization_id, section, changed_fields, actor_user_id)
  values (target_organization_id, 'taxes', array['tax_default_source'], (select auth.uid()));

  return jsonb_build_object(
    'status', 'saved',
    'tax_revision', settings_row.tax_revision,
    'tax_default_source', new_source,
    'tax_default_rate_id', new_rate_id
  );
end;
$$;


ALTER FUNCTION "public"."set_organization_tax_default"("target_organization_id" "uuid", "expected_revision" integer, "new_source" "text", "new_rate_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_organization_tax_rate_active"("target_organization_id" "uuid", "target_rate_id" "uuid", "expected_revision" integer, "new_is_active" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  rate_row public.organization_tax_rates;
begin
  if not private.has_permission(target_organization_id, 'settings.taxes.manage') then
    raise exception 'You do not have access to manage taxes.' using errcode = 'insufficient_privilege';
  end if;

  select * into rate_row
  from public.organization_tax_rates
  where id = target_rate_id and organization_id = target_organization_id
  for update;

  if rate_row.id is null then
    raise exception 'That tax rate was not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from rate_row.revision then
    raise exception 'Someone else changed this tax rate while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  update public.organization_tax_rates
  set is_active = coalesce(new_is_active, rate_row.is_active),
      revision = revision + 1, updated_by = (select auth.uid()), updated_at = now()
  where id = rate_row.id
  returning * into rate_row;

  return jsonb_build_object(
    'id', rate_row.id, 'name', rate_row.name, 'rate_basis_points', rate_row.rate_basis_points,
    'is_active', rate_row.is_active, 'revision', rate_row.revision
  );
end;
$$;


ALTER FUNCTION "public"."set_organization_tax_rate_active"("target_organization_id" "uuid", "target_rate_id" "uuid", "expected_revision" integer, "new_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_organization_website_chat_suspension"("p_organization_id" "uuid", "p_engage" boolean, "p_reason" "text", "p_actor_email" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  clean_reason text := btrim(coalesce(p_reason, ''));
  actor text := lower(btrim(coalesce(p_actor_email, '')));
  existing_event public.communication_website_chat_authority_events%rowtype;
  latest_event public.communication_website_chat_authority_events%rowtype;
  inserted_event public.communication_website_chat_authority_events%rowtype;
  affected_widgets integer;
  active boolean;
begin
  if char_length(clean_reason) not between 3 and 500 then
    raise exception 'A reason of 3 to 500 characters is required.' using errcode = 'check_violation';
  end if;
  if char_length(actor) not between 3 and 320 then
    raise exception 'An owner email is required.' using errcode = 'check_violation';
  end if;
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;
  if not exists (select 1 from public.organizations where id = p_organization_id) then
    raise exception 'That organization does not exist.' using errcode = 'foreign_key_violation';
  end if;

  perform pg_advisory_xact_lock(hashtext('website-chat-authority:' || p_organization_id::text));

  select * into existing_event
  from public.communication_website_chat_authority_events
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return jsonb_build_object('applied', false, 'event_id', existing_event.id,
      'suspended', existing_event.event_kind = 'suspension_engaged');
  end if;

  select * into latest_event
  from public.communication_website_chat_authority_events
  where organization_id = p_organization_id
    and event_kind in ('suspension_engaged', 'suspension_released')
  order by created_at desc, id desc
  limit 1;
  active := found and latest_event.event_kind = 'suspension_engaged';

  if active = p_engage then
    return jsonb_build_object('applied', false, 'event_id', latest_event.id, 'suspended', active);
  end if;

  update public.website_chat_widgets
  set suspended_at = case when p_engage then coalesce(suspended_at, now()) else null end,
      revision = revision + 1,
      updated_at = now()
  where organization_id = p_organization_id
    and (suspended_at is null) = p_engage;
  get diagnostics affected_widgets = row_count;

  insert into public.communication_website_chat_authority_events (
    organization_id, event_kind, reason, actor_owner_email, before_state, after_state,
    idempotency_key
  ) values (
    p_organization_id,
    case when p_engage then 'suspension_engaged' else 'suspension_released' end,
    clean_reason, actor,
    jsonb_build_object('suspended', active),
    jsonb_build_object('suspended', p_engage, 'affected_widgets', affected_widgets),
    p_idempotency_key
  ) returning * into inserted_event;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor,
    case when p_engage then 'communications.website_chat_suspension_engaged'
      else 'communications.website_chat_suspension_released' end,
    'organization', p_organization_id::text,
    jsonb_build_object('suspended', active),
    jsonb_build_object('suspended', p_engage, 'reason', clean_reason,
      'authority_event_id', inserted_event.id, 'affected_widgets', affected_widgets)
  );

  return jsonb_build_object('applied', true, 'event_id', inserted_event.id,
    'suspended', p_engage, 'affected_widgets', affected_widgets);
end;
$$;


ALTER FUNCTION "public"."set_organization_website_chat_suspension"("p_organization_id" "uuid", "p_engage" boolean, "p_reason" "text", "p_actor_email" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_quote_draft_copy"("target_quote_id" "uuid", "expected_revision" integer, "new_introduction" "text", "new_client_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  draft_row public.quote_versions;
  clean_introduction text;
  clean_client_message text;
begin
  draft_row := private.lock_quote_draft(target_quote_id, expected_revision);

  clean_introduction := nullif(trim(coalesce(new_introduction, '')), '');
  clean_client_message := nullif(trim(coalesce(new_client_message, '')), '');
  if clean_introduction is not null and char_length(clean_introduction) > 10000 then
    raise exception 'That introduction is too long.' using errcode = 'check_violation';
  end if;
  if clean_client_message is not null and char_length(clean_client_message) > 5000 then
    raise exception 'That client message is too long.' using errcode = 'check_violation';
  end if;

  update public.quote_versions
  set introduction = clean_introduction, client_message = clean_client_message
  where id = draft_row.id;

  return private.bump_quote_draft(draft_row.id);
end;
$$;


ALTER FUNCTION "public"."set_quote_draft_copy"("target_quote_id" "uuid", "expected_revision" integer, "new_introduction" "text", "new_client_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_quote_draft_deposit"("target_quote_id" "uuid", "expected_revision" integer, "new_deposit_type" "text", "new_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  draft_row public.quote_versions;
  item jsonb;
  item_index integer := 0;
  item_count integer;
  clean_description text;
  clean_value_type text;
  clean_value bigint;
  item_priced bigint;
  computed_sum bigint := 0;
  schedule_mode text;
  basis_points_total bigint := 0;
begin
  draft_row := private.lock_quote_draft(target_quote_id, expected_revision);

  if new_deposit_type is not null and new_deposit_type not in ('deposit_only', 'schedule') then
    raise exception 'A deposit is either a single deposit or a payment schedule.'
      using errcode = 'check_violation';
  end if;

  delete from public.quote_version_schedule_items
  where organization_id = draft_row.organization_id
    and quote_version_id = draft_row.id;

  if new_deposit_type is null then
    update public.quote_versions set deposit_type = null where id = draft_row.id;
    return private.bump_quote_draft(draft_row.id);
  end if;

  if new_items is null or jsonb_typeof(new_items) <> 'array' then
    raise exception 'Send the deposit installments as a list.' using errcode = 'check_violation';
  end if;

  item_count := jsonb_array_length(new_items);
  if item_count < 1 then
    raise exception 'Add at least one installment.' using errcode = 'check_violation';
  end if;
  if item_count > 12 then
    raise exception 'A payment schedule can hold up to 12 installments.' using errcode = 'check_violation';
  end if;
  if new_deposit_type = 'deposit_only' and item_count <> 1 then
    raise exception 'A deposit only has one installment.' using errcode = 'check_violation';
  end if;
  if new_deposit_type = 'schedule' and item_count < 2 then
    raise exception 'A payment schedule needs at least 2 installments.' using errcode = 'check_violation';
  end if;
  if new_deposit_type = 'schedule' and draft_row.total_minor <= 0 then
    raise exception 'Add line items to this quote before setting a payment schedule.'
      using errcode = 'check_violation';
  end if;

  for item in select * from jsonb_array_elements(new_items)
  loop
    clean_description := nullif(trim(coalesce(item ->> 'description', '')), '');
    clean_value_type := item ->> 'type';
    clean_value := nullif(item ->> 'value', '')::bigint;

    if clean_description is null or char_length(clean_description) < 2
       or char_length(clean_description) > 160 then
      raise exception 'Installment % needs a description between 2 and 160 characters.', item_index + 1
        using errcode = 'check_violation';
    end if;
    if clean_value_type not in ('fixed', 'percentage') then
      raise exception 'Installment % must be a fixed amount or a percentage.', item_index + 1
        using errcode = 'check_violation';
    end if;
    if new_deposit_type = 'schedule' then
      if schedule_mode is null then
        schedule_mode := clean_value_type;
      elsif schedule_mode <> clean_value_type then
        raise exception 'A payment schedule is either all fixed amounts or all percentages, not a mix.'
          using errcode = 'check_violation';
      end if;
    end if;
    if clean_value is null or clean_value < 1 then
      raise exception 'Installment % needs an amount above zero.', item_index + 1
        using errcode = 'check_violation';
    end if;
    if clean_value_type = 'percentage' and clean_value > 10000 then
      raise exception 'Installment % cannot be more than 100%%.', item_index + 1
        using errcode = 'check_violation';
    end if;
    if clean_value_type = 'fixed' and clean_value > 1000000000000 then
      raise exception 'Installment % is too large.', item_index + 1 using errcode = 'check_violation';
    end if;

    insert into public.quote_version_schedule_items (
      organization_id, quote_id, quote_version_id, position, description, value_type, value, is_deposit
    ) values (
      draft_row.organization_id, draft_row.quote_id, draft_row.id, item_index, clean_description,
      clean_value_type, clean_value, item_index = 0
    );

    if clean_value_type = 'fixed' then
      item_priced := clean_value;
    else
      item_priced := round(draft_row.total_minor * clean_value / 10000);
      basis_points_total := basis_points_total + clean_value;
    end if;
    computed_sum := computed_sum + item_priced;

    item_index := item_index + 1;
  end loop;

  if new_deposit_type = 'schedule' then
    if schedule_mode = 'percentage' then
      if basis_points_total <> 10000 then
        raise exception 'Percentage installments must add up to 100%%. They currently add up to %.',
          round(basis_points_total / 100.0, 2)::text || '%' using errcode = 'check_violation';
      end if;
    elsif computed_sum <> draft_row.total_minor then
      raise exception
        'Installments must add up to the quote total. They currently add up to % but the total is %.',
        computed_sum, draft_row.total_minor using errcode = 'check_violation';
    end if;
  end if;

  update public.quote_versions set deposit_type = new_deposit_type where id = draft_row.id;

  return private.bump_quote_draft(draft_row.id);
end;
$$;


ALTER FUNCTION "public"."set_quote_draft_deposit"("target_quote_id" "uuid", "expected_revision" integer, "new_deposit_type" "text", "new_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_quote_draft_discount"("target_quote_id" "uuid", "expected_revision" integer, "new_name" "text", "new_type" "text", "new_value" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  draft_row public.quote_versions;
  clean_name text;
begin
  draft_row := private.lock_quote_draft(target_quote_id, expected_revision);

  if new_type is null then
    update public.quote_versions
    set discount_name = null, discount_type = null, discount_value = null
    where id = draft_row.id;
    return private.bump_quote_draft(draft_row.id);
  end if;

  if new_type not in ('fixed', 'percentage') then
    raise exception 'A discount is either a fixed amount or a percentage.' using errcode = 'check_violation';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) > 80 then
    raise exception 'Give this discount a name the customer will understand, under 80 characters.'
      using errcode = 'check_violation';
  end if;

  if new_value is null or new_value < 0 then
    raise exception 'Enter a discount amount.' using errcode = 'check_violation';
  end if;
  if new_type = 'percentage' and new_value > 10000 then
    raise exception 'A discount cannot be more than 100 percent.' using errcode = 'check_violation';
  end if;
  if new_type = 'fixed' and new_value > 1000000000000 then
    raise exception 'That discount is too large.' using errcode = 'check_violation';
  end if;

  update public.quote_versions
  set discount_name = clean_name, discount_type = new_type, discount_value = new_value
  where id = draft_row.id;

  return private.bump_quote_draft(draft_row.id);
end;
$$;


ALTER FUNCTION "public"."set_quote_draft_discount"("target_quote_id" "uuid", "expected_revision" integer, "new_name" "text", "new_type" "text", "new_value" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_quote_draft_tax"("target_quote_id" "uuid", "expected_revision" integer, "new_source" "text", "new_rate_id" "uuid" DEFAULT NULL::"uuid", "new_custom_name" "text" DEFAULT NULL::"text", "new_custom_rate_basis_points" integer DEFAULT NULL::integer, "save_as_reusable" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  draft_row public.quote_versions;
  rate_row public.organization_tax_rates;
  resolved_tax record;
  clean_name text;
  clean_rate integer;
  saved_rate_id uuid;
begin
  draft_row := private.lock_quote_draft(target_quote_id, expected_revision);

  if new_source not in ('business_default', 'property_default', 'saved_rate', 'no_tax', 'custom') then
    raise exception 'Choose a tax option.' using errcode = 'check_violation';
  end if;

  if new_source in ('business_default', 'property_default') then
    select * into resolved_tax
    from private.resolve_property_tax(draft_row.organization_id, (
      select property_id from public.quotes where id = draft_row.quote_id
    ));

    update public.quote_versions
    set tax_source = resolved_tax.source, tax_name = resolved_tax.name,
        tax_rate_basis_points = resolved_tax.rate_basis_points, tax_rate_id = resolved_tax.rate_id
    where id = draft_row.id;

  elsif new_source = 'saved_rate' then
    select * into rate_row
    from public.organization_tax_rates
    where id = new_rate_id and organization_id = draft_row.organization_id and is_active;

    if rate_row.id is null then
      raise exception 'Choose an active saved tax rate.' using errcode = 'check_violation';
    end if;

    update public.quote_versions
    set tax_source = 'saved_rate', tax_name = rate_row.name,
        tax_rate_basis_points = rate_row.rate_basis_points, tax_rate_id = rate_row.id
    where id = draft_row.id;

  elsif new_source = 'no_tax' then
    update public.quote_versions
    set tax_source = 'no_tax', tax_name = null, tax_rate_basis_points = 0, tax_rate_id = null
    where id = draft_row.id;

  else -- custom
    clean_rate := coalesce(new_custom_rate_basis_points, 0);
    if clean_rate <= 0 or clean_rate > 10000 then
      raise exception 'A tax rate is between 0 and 100 percent.' using errcode = 'check_violation';
    end if;

    clean_name := nullif(trim(coalesce(new_custom_name, '')), '');
    if clean_name is null or char_length(clean_name) > 80 then
      raise exception 'Give this tax a name the customer will recognize, under 80 characters.'
        using errcode = 'check_violation';
    end if;

    saved_rate_id := null;
    if coalesce(save_as_reusable, false) then
      if not private.has_permission(draft_row.organization_id, 'settings.taxes.manage') then
        raise exception 'You do not have access to save a reusable tax rate.'
          using errcode = 'insufficient_privilege';
      end if;

      insert into public.organization_tax_rates (
        organization_id, name, rate_basis_points, created_by, updated_by
      ) values (
        draft_row.organization_id, clean_name, clean_rate, (select auth.uid()), (select auth.uid())
      )
      returning id into saved_rate_id;
    end if;

    update public.quote_versions
    set tax_source = 'custom', tax_name = clean_name, tax_rate_basis_points = clean_rate,
        -- Provenance only: a saved-as-reusable custom rate links back to the new row, but the source stays
        -- 'custom' -- this document was still priced as a one-off, not picked from the list.
        tax_rate_id = saved_rate_id
    where id = draft_row.id;
  end if;

  return private.bump_quote_draft(draft_row.id);
end;
$$;


ALTER FUNCTION "public"."set_quote_draft_tax"("target_quote_id" "uuid", "expected_revision" integer, "new_source" "text", "new_rate_id" "uuid", "new_custom_name" "text", "new_custom_rate_basis_points" integer, "save_as_reusable" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_quote_draft_visibility"("target_quote_id" "uuid", "expected_revision" integer, "new_show_quantities" boolean, "new_show_unit_prices" boolean, "new_show_line_totals" boolean, "new_show_totals" boolean) RETURNS "jsonb"
