ALTER FUNCTION "public"."set_quote_draft_visibility"("target_quote_id" "uuid", "expected_revision" integer, "new_show_quantities" boolean, "new_show_unit_prices" boolean, "new_show_line_totals" boolean, "new_show_totals" boolean) OWNER TO "postgres";


