CREATE OR REPLACE FUNCTION "public"."settle_team_invitation_identity_cleanup"("target_invitation_id" "uuid", "target_lease_nonce" "uuid") RETURNS "public"."organization_member_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settled_row public.organization_member_invitations;
begin
  update public.organization_member_invitations
  set state = case when state in ('reserving', 'invited', 'accepting') then 'abandoned' else state end,
      token_hash = null,
      lease_nonce = null,
      lease_expires_at = null,
      identity_cleanup_state = 'done',
      identity_cleanup_error = null,
      reconciliation_nonce = null,
      reconciliation_lease_expires_at = null
  where id = target_invitation_id
    and identity_cleanup_state = 'required'
    and reconciliation_nonce = target_lease_nonce
    and reconciliation_lease_expires_at > now()
  returning * into settled_row;

  if not found then
    raise exception 'The invitation cleanup lease is no longer valid.' using errcode = 'P0409';
  end if;

  return settled_row;
end;
$$;


ALTER FUNCTION "public"."settle_team_invitation_identity_cleanup"("target_invitation_id" "uuid", "target_lease_nonce" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_team_notification_email"("p_notification_id" "uuid", "p_claim_token" "uuid", "p_sent" boolean, "p_error" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  row_attempts integer;
  max_attempts constant integer := 5;
begin
  select email_attempts into row_attempts from public.team_notifications
  where id = p_notification_id and email_claim_token = p_claim_token and email_state = 'pending'
  for update;
  if not found then
    return 'claim_lost';
  end if;

  if p_sent then
    update public.team_notifications
    set email_state = 'sent', email_sent_at = now(), email_attempts = row_attempts + 1,
      email_claim_token = null, email_claimed_until = null, email_last_error = null
    where id = p_notification_id;
    return 'sent';
  end if;

  update public.team_notifications
  set email_attempts = row_attempts + 1,
    email_state = case when row_attempts + 1 >= max_attempts then 'failed' else 'pending' end,
    email_available_at = now() + make_interval(mins => power(2, row_attempts)::integer),
    email_claim_token = null, email_claimed_until = null,
    email_last_error = left(coalesce(p_error, 'The alert email could not be sent.'), 500)
  where id = p_notification_id;
  return case when row_attempts + 1 >= max_attempts then 'failed' else 'retry' end;
end;
$$;


ALTER FUNCTION "public"."settle_team_notification_email"("p_notification_id" "uuid", "p_claim_token" "uuid", "p_sent" boolean, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."skip_automation_enrollment_step"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  existing_receipt public.automation_enrollment_command_receipts%rowtype;
  enrollment private.automation_enrollments%rowtype;
  pending_item private.automation_work_items%rowtype;
  definition jsonb;
  step_count integer;
  next_index integer;
  new_state text;
  command_result jsonb;
begin
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;

  select * into existing_receipt
  from public.automation_enrollment_command_receipts
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_receipt.result || jsonb_build_object('idempotent_replay', true);
  end if;

  select * into enrollment
  from private.automation_enrollments
  where id = p_enrollment_id and organization_id = p_organization_id
  for update;
  if not found then
    raise exception 'That enrollment does not exist.' using errcode = 'no_data_found';
  end if;
  if enrollment.state not in ('active', 'paused') then
    raise exception 'Only a running enrollment has a step to skip.' using errcode = 'restrict_violation';
  end if;

  select * into pending_item
  from private.automation_work_items
  where enrollment_id = p_enrollment_id and state = 'pending'
  order by step_index
  limit 1
  for update;
  if found then
    update private.automation_work_items
    set state = 'cancelled', claim_token = null, claimed_at = null
    where id = pending_item.id;
  end if;

  select version.definition into definition
  from public.automation_recipe_versions as version
  where version.id = enrollment.recipe_version_id;
  step_count := jsonb_array_length(coalesce(definition -> 'steps', '[]'::jsonb));

  next_index := enrollment.current_step_index + 1;

  if next_index >= step_count then
    new_state := 'completed';
    update private.automation_enrollments
    set state = 'completed', completed_at = now(), current_step_index = next_index, paused_work_due_at = null
    where id = p_enrollment_id;
  else
    new_state := enrollment.state;
    update private.automation_enrollments
    set current_step_index = next_index,
        paused_work_due_at = case when enrollment.state = 'paused' then now() else null end
    where id = p_enrollment_id;

    if enrollment.state = 'active' then
      insert into private.automation_work_items (
        organization_id, enrollment_id, step_index, due_at, available_at
      ) values (
        p_organization_id, p_enrollment_id, next_index, now(), now()
      )
      on conflict (enrollment_id, step_index) do nothing;
    end if;
  end if;

  command_result := jsonb_build_object(
    'enrollment_id', p_enrollment_id, 'state', new_state, 'current_step_index', next_index
  );

  insert into public.automation_enrollment_command_receipts (
    organization_id, idempotency_key, command, subject_type, subject_id, enrollment_id, result
  ) values (
    p_organization_id, p_idempotency_key, 'skip', enrollment.subject_type, enrollment.subject_id,
    p_enrollment_id, command_result
  );

  return command_result;
end;
$$;


ALTER FUNCTION "public"."skip_automation_enrollment_step"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."skip_automation_enrollment_step"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_idempotency_key" "uuid") IS 'Cancels the pending step and advances to the next one (active: scheduled now; paused: parked; last step: completes). Idempotent per organization + key. Service role only.';



CREATE OR REPLACE FUNCTION "public"."stop_automation_enrollment"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_reason" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  existing_receipt public.automation_enrollment_command_receipts%rowtype;
  enrollment private.automation_enrollments%rowtype;
  command_result jsonb;
begin
  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.' using errcode = 'check_violation';
  end if;

  select * into existing_receipt
  from public.automation_enrollment_command_receipts
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if found then
    return existing_receipt.result || jsonb_build_object('idempotent_replay', true);
  end if;

  select * into enrollment
  from private.automation_enrollments
  where id = p_enrollment_id and organization_id = p_organization_id
  for update;
  if not found then
    raise exception 'That enrollment does not exist.' using errcode = 'no_data_found';
  end if;
  if enrollment.state not in ('active', 'paused') then
    raise exception 'This enrollment is already finished.' using errcode = 'restrict_violation';
  end if;

  update private.automation_work_items
  set state = 'cancelled', claim_token = null, claimed_at = null
  where enrollment_id = p_enrollment_id and state = 'pending';

  update private.automation_enrollments
  set state = 'stopped',
      stop_reason = nullif(left(btrim(p_reason), 200), ''),
      stopped_at = now(),
      paused_work_due_at = null
  where id = p_enrollment_id;

  command_result := jsonb_build_object('enrollment_id', p_enrollment_id, 'state', 'stopped');

  insert into public.automation_enrollment_command_receipts (
    organization_id, idempotency_key, command, subject_type, subject_id, enrollment_id, result
  ) values (
    p_organization_id, p_idempotency_key, 'stop', enrollment.subject_type, enrollment.subject_id,
    p_enrollment_id, command_result
  );

  return command_result;
end;
$$;


ALTER FUNCTION "public"."stop_automation_enrollment"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_reason" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."stop_automation_enrollment"("p_organization_id" "uuid", "p_actor_user_id" "uuid", "p_enrollment_id" "uuid", "p_reason" "text", "p_idempotency_key" "uuid") IS 'Terminally stops an enrollment with a reason and cancels its pending work. Never recalls a sent message. Idempotent per organization + key. Service role only.';



CREATE OR REPLACE FUNCTION "public"."submit_form_response"("target_organization_slug" "text", "target_form_slug" "text", "target_idempotency_key" "text", "target_contact" "jsonb", "target_answers" "jsonb", "target_photo_object_keys" "text"[] DEFAULT '{}'::"text"[], "target_selected_catalog_item_id" "uuid" DEFAULT NULL::"uuid", "target_requested_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "target_requested_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  resolved_org public.organizations;
  form_row public.forms;
  rules public.form_booking_rules;
  key_prefix text;
  bad_key text;
  existing_id uuid;
  new_id uuid;
  max_photos constant integer := 20;
  max_json_bytes constant integer := 32768;
  skip_reservation boolean;
  org_timezone text;
  local_start timestamp;
  local_end timestamp;
  resolved_member uuid;
  reservation_id uuid;
begin
  if target_idempotency_key is null or char_length(trim(target_idempotency_key)) = 0
    or char_length(target_idempotency_key) > 200
  then
    raise exception 'That submission could not be read.' using errcode = 'check_violation';
  end if;

  select * into resolved_org from public.organizations
  where slug = target_organization_slug and lifecycle_status = 'active';
  if resolved_org.id is null then
    raise exception 'That form is not available.' using errcode = 'check_violation';
  end if;

  select * into form_row from public.forms
  where organization_id = resolved_org.id
    and public_slug = target_form_slug
    and archived_at is null
    and is_enabled
    and current_published_version_id is not null;
  if form_row.id is null then
    raise exception 'That form is not available.' using errcode = 'check_violation';
  end if;

  if form_row.outcome = 'request' then
    if target_selected_catalog_item_id is not null
      or target_requested_starts_at is not null or target_requested_ends_at is not null
    then
      raise exception 'This form does not book a time.' using errcode = 'check_violation';
    end if;
  else
    if target_requested_starts_at is null or target_requested_ends_at is null then
      raise exception 'Choose a time for this visit.' using errcode = 'check_violation';
    end if;
    if target_selected_catalog_item_id is not null and not exists (
      select 1 from public.form_bookable_services
      where form_id = form_row.id and catalog_item_id = target_selected_catalog_item_id
    ) then
      raise exception 'Choose one of the listed services.' using errcode = 'check_violation';
    end if;

    -- Re-checked here for the same reason every other claim in this function is: the booking rules the app
    -- layer already validated against are re-read and re-applied against the caller's own numbers, never
    -- trusted a second time.
    select * into rules from public.form_booking_rules
    where form_id = form_row.id and organization_id = resolved_org.id;
    if rules.form_id is null then
      raise exception 'This form has no booking rules.' using errcode = 'check_violation';
    end if;
    if target_requested_ends_at - target_requested_starts_at
        <> make_interval(mins => rules.visit_duration_minutes) then
      raise exception 'Choose a valid time for this visit.' using errcode = 'check_violation';
    end if;
    if target_requested_starts_at < now() + make_interval(mins => rules.min_notice_minutes) then
      raise exception 'That time is no longer available. Please choose another.'
        using errcode = 'check_violation';
    end if;
  end if;

  if target_contact is null or jsonb_typeof(target_contact) <> 'object'
    or length(target_contact::text) > max_json_bytes
  then
    raise exception 'That submission could not be read.' using errcode = 'check_violation';
  end if;
  if target_answers is null or jsonb_typeof(target_answers) <> 'object'
    or length(target_answers::text) > max_json_bytes
  then
    raise exception 'That submission could not be read.' using errcode = 'check_violation';
  end if;

  if target_photo_object_keys is not null and array_length(target_photo_object_keys, 1) > max_photos then
    raise exception 'Too many photos on one submission.' using errcode = 'check_violation';
  end if;

  if target_photo_object_keys is not null then
    key_prefix := resolved_org.id || '/public-form-submissions/' || form_row.id || '/';
    select each_key into bad_key
    from unnest(target_photo_object_keys) as each_key
    where left(each_key, char_length(key_prefix)) <> key_prefix
    limit 1;
    if bad_key is not null then
      raise exception 'That photo does not belong to this form.' using errcode = 'check_violation';
    end if;
  end if;

  select id into existing_id from private.form_submissions
  where form_id = form_row.id and idempotency_key = target_idempotency_key;
  if existing_id is not null then
    return jsonb_build_object('submission_id', existing_id, 'already_received', true);
  end if;

  begin
    insert into private.form_submissions (
      organization_id, form_id, form_version_id, idempotency_key, contact, answers,
      photo_object_keys, selected_catalog_item_id, requested_starts_at, requested_ends_at
    ) values (
      resolved_org.id, form_row.id, form_row.current_published_version_id, target_idempotency_key,
      target_contact, target_answers, coalesce(target_photo_object_keys, '{}'::text[]),
      target_selected_catalog_item_id, target_requested_starts_at, target_requested_ends_at
    )
    returning id into new_id;
  exception
    when unique_violation then
      -- A concurrent retry of the same idempotency key lost the race; the row it collided with is the real
      -- answer, not an error the customer should see. Nothing is reserved on this path -- the winning
      -- request already holds (or is about to hold) the only reservation that matters.
      select id into new_id from private.form_submissions
      where form_id = form_row.id and idempotency_key = target_idempotency_key;
      return jsonb_build_object('submission_id', new_id, 'already_received', true);
  end;

  -- Only the genuine first insert of a new idempotency key reaches here, so the slot is claimed exactly
  -- once per real submission -- never wasted on a retry, never skipped for the one request that needed it.
  if form_row.outcome <> 'request' then
    skip_reservation := (form_row.outcome = 'assessment' and rules.requires_booking_approval);

    if not skip_reservation then
      select settings.timezone into org_timezone
      from public.organization_settings as settings
      where settings.organization_id = resolved_org.id;
      org_timezone := coalesce(org_timezone, 'UTC');

      local_start := target_requested_starts_at at time zone org_timezone;
      local_end := target_requested_ends_at at time zone org_timezone;

      resolved_member := private.form_booking_free_member_for_slot(
        resolved_org.id, local_start, local_end, rules.buffer_minutes, org_timezone
      );
      if resolved_member is null then
        raise exception 'That time is no longer available. Please choose another.'
          using errcode = 'check_violation';
      end if;

      reservation_id := public.claim_form_booking_reservation(
        resolved_org.id, form_row.id, resolved_member, target_requested_starts_at, target_requested_ends_at
      );
      if reservation_id is null then
        raise exception 'That time is no longer available. Please choose another.'
          using errcode = 'check_violation';
      end if;

      update private.form_submissions
      set assigned_user_id = resolved_member, booking_reservation_id = reservation_id
      where id = new_id;
    end if;
  end if;

  return jsonb_build_object('submission_id', new_id, 'already_received', false);
end;
$$;


ALTER FUNCTION "public"."submit_form_response"("target_organization_slug" "text", "target_form_slug" "text", "target_idempotency_key" "text", "target_contact" "jsonb", "target_answers" "jsonb", "target_photo_object_keys" "text"[], "target_selected_catalog_item_id" "uuid", "target_requested_starts_at" timestamp with time zone, "target_requested_ends_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_form_response"("target_organization_slug" "text", "target_form_slug" "text", "target_idempotency_key" "text", "target_contact" "jsonb", "target_answers" "jsonb", "target_photo_object_keys" "text"[], "target_selected_catalog_item_id" "uuid", "target_requested_starts_at" timestamp with time zone, "target_requested_ends_at" timestamp with time zone) IS 'Safely receives one public form answer into private.form_submissions. Re-checks everything the /api route already validated because an anonymous caller''s own claims are never trusted twice. Idempotent by {form, idempotency key}. For an instant-booking outcome (any job form, or an assessment form that does not require approval) it also claims the exact reservation Part 4D''s worker will honor, synchronously, so a lost race is told to the customer immediately.';



CREATE OR REPLACE FUNCTION "public"."submit_onboarding_application"("target_business_name" "text", "target_main_contact_name" "text", "target_main_contact_email" "text", "target_main_contact_phone" "text", "target_initial_administrator_name" "text", "target_initial_administrator_email" "text", "target_trade" "text", "target_city_country" "text", "target_time_zone" "text", "target_note" "text", "target_package_version_id" "uuid", "target_privacy_policy_version" "text", "target_submitted_data" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  version_status text;
  package_status text;
  package_snapshot jsonb;
  clean_business_name text;
  clean_contact_email text;
  clean_admin_email text;
  is_duplicate boolean;
  new_application_id uuid;
begin
  select version.status, package.status, jsonb_build_object(
    'display_name', version.display_name,
    'public_description', version.public_description,
    'value_explanation', version.value_explanation,
    'price_usd_cents', version.price_usd_cents,
    'currency', version.currency,
    'billing_period', version.billing_period,
    'version_number', version.version_number
  )
  into version_status, package_status, package_snapshot
  from public.platform_package_versions as version
  join public.platform_packages as package on package.package_id = version.package_id
  where version.id = target_package_version_id;

  if version_status is null then
    raise exception 'The selected package no longer exists.' using errcode = 'foreign_key_violation';
  end if;
  if version_status <> 'published' or package_status <> 'published' then
    raise exception 'The selected package is no longer available.' using errcode = 'check_violation';
  end if;

  clean_business_name := trim(target_business_name);
  clean_contact_email := lower(trim(target_main_contact_email));
  clean_admin_email := nullif(lower(trim(coalesce(target_initial_administrator_email, ''))), '');

  select exists (
    select 1
    from public.platform_onboarding_applications as existing
    where lower(existing.main_contact_email) = clean_contact_email
       or lower(existing.business_name) = lower(clean_business_name)
       or (clean_admin_email is not null
           and lower(existing.initial_administrator_email) = clean_admin_email)
  ) into is_duplicate;

  insert into public.platform_onboarding_applications (
    business_name, main_contact_name, main_contact_email, main_contact_phone,
    initial_administrator_name, initial_administrator_email, trade, city_country, time_zone,
    note, package_version_id, package_snapshot, possible_duplicate
  ) values (
    clean_business_name, trim(target_main_contact_name), clean_contact_email, trim(target_main_contact_phone),
    nullif(trim(coalesce(target_initial_administrator_name, '')), ''), clean_admin_email,
    trim(target_trade), trim(target_city_country), trim(target_time_zone),
    nullif(trim(coalesce(target_note, '')), ''), target_package_version_id, package_snapshot, is_duplicate
  )
  returning id into new_application_id;

  insert into public.platform_onboarding_application_submissions (
    application_id, submitted_data, package_snapshot, privacy_policy_version, agreement_accepted_at
  ) values (
    new_application_id, target_submitted_data, package_snapshot, target_privacy_policy_version, now()
  );

  return new_application_id;
end;
$$;


ALTER FUNCTION "public"."submit_onboarding_application"("target_business_name" "text", "target_main_contact_name" "text", "target_main_contact_email" "text", "target_main_contact_phone" "text", "target_initial_administrator_name" "text", "target_initial_administrator_email" "text", "target_trade" "text", "target_city_country" "text", "target_time_zone" "text", "target_note" "text", "target_package_version_id" "uuid", "target_privacy_policy_version" "text", "target_submitted_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_quote_customer_decision"("supplied_token_hash" "bytea", "new_outcome" "text", "customer_note" "text" DEFAULT NULL::"text", "supplied_evidence" "jsonb" DEFAULT '{}'::"jsonb", "signature_name" "text" DEFAULT NULL::"text", "signature_method" "text" DEFAULT NULL::"text", "signature_object_key" "text" DEFAULT NULL::"text", "signature_byte_size" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.quote_access_links;
  quote_row public.quotes;
  version_row public.quote_versions;
  current_decision public.quote_decisions;
  new_decision_id uuid;
  clean_note text;
  clean_signer text;
  new_status text;
begin
  if new_outcome is null or new_outcome not in ('approved', 'changes_requested') then
    raise exception 'That is not an answer this link can give.' using errcode = 'check_violation';
  end if;

  clean_note := nullif(trim(coalesce(customer_note, '')), '');
  if clean_note is not null and char_length(clean_note) > 1000 then
    raise exception 'That message is too long.' using errcode = 'check_violation';
  end if;

  clean_signer := nullif(trim(coalesce(signature_name, '')), '');

  -- Nobody signs a request to change something.
  if clean_signer is not null and new_outcome <> 'approved' then
    raise exception 'Only an approval is signed.' using errcode = 'check_violation';
  end if;

  if clean_signer is not null then
    if char_length(clean_signer) > 120 then
      raise exception 'That name is too long.' using errcode = 'check_violation';
    end if;
    if signature_method is null or signature_method not in ('typed', 'drawn') then
      raise exception 'That is not a way to sign.' using errcode = 'check_violation';
    end if;
    if (signature_method = 'drawn') <> (signature_object_key is not null) then
      raise exception 'That signature is incomplete.' using errcode = 'check_violation';
    end if;
  elsif signature_object_key is not null then
    -- A drawing with nobody's name on it is not a signature.
    raise exception 'That signature is incomplete.' using errcode = 'check_violation';
  end if;

  if supplied_token_hash is null or octet_length(supplied_token_hash) <> 32 then
    return null;
  end if;

  select * into link_row from public.quote_access_links where token_hash = supplied_token_hash;
  if link_row.id is null then
    return null;
  end if;

  select * into quote_row from public.quotes where id = link_row.quote_id for update;

  select * into link_row from public.quote_access_links where id = link_row.id;
  if link_row.revoked_at is not null
     or (link_row.expires_at is not null and link_row.expires_at <= now()) then
    return null;
  end if;

  if quote_row.id is null
     or quote_row.status = 'archived'
     or quote_row.current_published_version_id is distinct from link_row.quote_version_id then
    return null;
  end if;

  select * into version_row from public.quote_versions where id = link_row.quote_version_id;
  if version_row.id is null or version_row.status <> 'published' then
    return null;
  end if;

  select * into current_decision
  from public.quote_decisions
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and is_current;

  if current_decision.id is not null
     and current_decision.outcome = new_outcome
     and current_decision.quote_version_id = version_row.id
     and current_decision.actor_kind = 'customer' then
    return jsonb_build_object(
      'quote_id', quote_row.id, 'status', quote_row.status, 'outcome', current_decision.outcome,
      'decided_at', current_decision.decided_at, 'already_answered', true
    );
  end if;

  if quote_row.status not in ('awaiting_response', 'changes_requested') then
    raise exception 'This quote has already been answered.' using errcode = 'P0409';
  end if;

  if new_outcome = 'changes_requested' and quote_row.status = 'changes_requested' then
    raise exception 'You have already asked for changes on this quote.' using errcode = 'P0409';
  end if;

  new_status := new_outcome;

  update public.quote_decisions
  set is_current = false
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and is_current;

  insert into public.quote_decisions (
    organization_id, quote_id, quote_version_id, outcome, actor_kind, quote_access_link_id,
    method, note, evidence
  ) values (
    quote_row.organization_id, quote_row.id, version_row.id, new_outcome, 'customer', link_row.id,
    'online', clean_note, coalesce(supplied_evidence, '{}'::jsonb)
  )
  returning id into new_decision_id;

  -- Same transaction as the answer, on purpose. A signature that could arrive a moment later is a
  -- signature that could fail to arrive at all.
  if clean_signer is not null then
    insert into public.quote_signatures (
      organization_id, quote_id, quote_version_id, quote_decision_id, signer_name, method,
      document_hash, image_object_key, image_byte_size, evidence
    ) values (
      quote_row.organization_id, quote_row.id, version_row.id, new_decision_id, clean_signer,
      signature_method, version_row.document_hash, signature_object_key, signature_byte_size,
      coalesce(supplied_evidence, '{}'::jsonb)
    );
  end if;

  if new_outcome = 'approved' then
    update public.quotes
    set status = new_status,
        decision = 'approved',
        decided_at = now(),
        decision_method = 'online',
        decision_note = clean_note,
        decided_by = null
    where id = quote_row.id
    returning * into quote_row;
  else
    update public.quotes
    set status = new_status
    where id = quote_row.id
    returning * into quote_row;
  end if;

  insert into public.activity_events (
    organization_id, entity_type, entity_id, event_type, summary, actor_user_id, metadata
  ) values (
    quote_row.organization_id, 'quote', quote_row.id,
    case new_outcome when 'approved' then 'quote.approved' else 'quote.changes_requested' end,
    case new_outcome when 'approved' then 'The client approved this quote'
                     else 'The client asked for changes' end
      || case when clean_note is null then ''
              else ': ' || left(clean_note, 240) || case when char_length(clean_note) > 240 then '…' else '' end
         end,
    null,
    jsonb_build_object(
      'version_number', version_row.version_number,
      'method', 'online',
      'signed', clean_signer is not null,
      'quote_access_link_id', link_row.id
    )
  );

  return jsonb_build_object(
    'quote_id', quote_row.id, 'status', quote_row.status, 'outcome', new_outcome,
    'decided_at', now(), 'signed', clean_signer is not null, 'already_answered', false
  );
end;
$$;


ALTER FUNCTION "public"."submit_quote_customer_decision"("supplied_token_hash" "bytea", "new_outcome" "text", "customer_note" "text", "supplied_evidence" "jsonb", "signature_name" "text", "signature_method" "text", "signature_object_key" "text", "signature_byte_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sweep_communication_email_reputation"("batch_size" integer DEFAULT 200) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  candidate record;
  evaluated_count integer := 0;
begin
  if batch_size < 1 or batch_size > 2000 then
    raise exception 'The reputation sweep batch size is outside its safe bounds.'
      using errcode = 'check_violation';
  end if;

  for candidate in
    select state.organization_id, state.evaluation_requested_at
    from public.communication_email_reputation_state state
    where state.evaluation_requested_at is not null
    order by state.evaluation_requested_at
    limit batch_size
  loop
    perform public.evaluate_communication_email_reputation(candidate.organization_id, now());

    update public.communication_email_reputation_state
    set evaluation_requested_at = null
    where organization_id = candidate.organization_id
      and evaluation_requested_at = candidate.evaluation_requested_at;

    evaluated_count := evaluated_count + 1;
  end loop;

  return evaluated_count;
end;
$$;


ALTER FUNCTION "public"."sweep_communication_email_reputation"("batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sweep_team_invitation_reservations"("stale_after" interval DEFAULT '01:00:00'::interval) RETURNS SETOF "public"."organization_member_invitations"
    LANGUAGE "sql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select * from public.sweep_team_invitation_reservations_bounded(100, stale_after);
$$;


ALTER FUNCTION "public"."sweep_team_invitation_reservations"("stale_after" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sweep_team_invitation_reservations_bounded"("target_batch_size" integer DEFAULT 25, "target_stale_after" interval DEFAULT '01:00:00'::interval) RETURNS SETOF "public"."organization_member_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_row record;
  updated_row public.organization_member_invitations;
begin
  if target_batch_size not between 1 and 100
     or target_stale_after < interval '5 minutes'
     or target_stale_after > interval '24 hours' then
    raise exception 'The invitation reservation sweep is outside its safe bounds.'
      using errcode = 'check_violation';
  end if;

  for target_row in
    select invitation.id
    from public.organization_member_invitations as invitation
    where invitation.state = 'reserving'
      and invitation.created_at < now() - target_stale_after
    order by invitation.created_at, invitation.id
    limit target_batch_size
    for update skip locked
  loop
    update public.organization_member_invitations
    set state = case when auth_attempt_started_at is null then 'abandoned' else state end,
        identity_cleanup_state = case
          when auth_attempt_started_at is null then identity_cleanup_state
          else 'required'
        end,
        identity_cleanup_error = case
          when auth_attempt_started_at is null then identity_cleanup_error
          else null
        end
    where id = target_row.id
    returning * into updated_row;

    return next updated_row;
  end loop;

  return;
end;
$$;


ALTER FUNCTION "public"."sweep_team_invitation_reservations_bounded"("target_batch_size" integer, "target_stale_after" interval) OWNER TO "postgres";


