CREATE OR REPLACE FUNCTION "public"."unapply_client_payment"("target_organization_id" "uuid", "target_allocation_id" "uuid", "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  allocation_row public.invoice_payment_allocations;
  invoice_row public.invoices;
  reversal_id uuid;
begin
  if caller is null then
    raise exception 'You must be signed in to correct a payment.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.correct_payment') then
    raise exception 'You do not have access to correct payments here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  replayed := private.begin_invoice_command(
    target_organization_id, 'unapply_client_payment', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  select * into allocation_row
  from public.invoice_payment_allocations
  where organization_id = target_organization_id and id = target_allocation_id;
  if not found then
    raise exception 'That payment entry could not be found.' using errcode = 'P0404';
  end if;

  invoice_row := private.lock_invoice_for_payment(target_organization_id, allocation_row.invoice_id);

  reversal_id := private.reverse_invoice_allocation(invoice_row, allocation_row, caller, new_reason);

  return private.complete_invoice_command(
    target_organization_id, 'unapply_client_payment', new_idempotency_key,
    jsonb_build_object(
      'allocation_id', reversal_id,
      'reversed_allocation_id', allocation_row.id,
      'invoice_id', invoice_row.id,
      'invoice_number', invoice_row.invoice_number,
      'amount_minor', allocation_row.amount_minor
    )
  );
end;
$$;


ALTER FUNCTION "public"."unapply_client_payment"("target_organization_id" "uuid", "target_allocation_id" "uuid", "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."unapply_client_payment"("target_organization_id" "uuid", "target_allocation_id" "uuid", "new_reason" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Returns money from a bill to the client''s available credit, keeping both the original application and the entry that took it back. The money itself is untouched: this changes where it sits, not that it arrived.';



CREATE OR REPLACE FUNCTION "public"."uncomplete_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  current_visit public.job_visits;
begin
  if caller is null then
    raise exception 'You must be signed in to change a visit.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.complete') then
    raise exception 'You do not have access to complete this visit.' using errcode = 'insufficient_privilege';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id
  for update;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;
  if current_job.status = 'closed' then
    raise exception 'A closed job''s visits cannot be changed. Reopen the job first.' using errcode = 'P0410';
  end if;

  select visit.* into current_visit
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.id = target_visit_id
  for update;
  if not found then
    raise exception 'That visit could not be found.' using errcode = 'P0404';
  end if;

  if current_visit.completed_at is null then
    return jsonb_build_object('applied', true, 'already_incomplete', true, 'revision', current_visit.revision);
  end if;

  if exists (
    select 1
    from public.invoice_sources as claim
    where claim.organization_id = target_organization_id
      and claim.visit_id = target_visit_id
      and claim.source_kind = 'visit'
  ) then
    raise exception 'This visit is already on an invoice, so it cannot be reopened.' using errcode = 'P0410',
      hint = 'Correct the invoice instead if the work was different from what was billed.';
  end if;

  update public.job_visits
  set completed_at = null, completed_by = null, revision = revision + 1, updated_at = now()
  where organization_id = target_organization_id and id = target_visit_id
  returning * into current_visit;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, related_visit_id, metadata)
  values (target_organization_id, target_job_id, 'visit_uncompleted', caller, target_visit_id, '{}'::jsonb);

  return jsonb_build_object('applied', true, 'already_incomplete', false, 'revision', current_visit.revision);
end;
$$;


ALTER FUNCTION "public"."uncomplete_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."uncomplete_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid") IS 'Clears a visit''s completion. Checks jobs.complete, refuses on a closed job and on a visit an invoice already claims (P0410), is idempotent on an already-incomplete visit. Leaves any reminder the completion already raised untouched.';



CREATE OR REPLACE FUNCTION "public"."update_catalog_item"("target_organization_id" "uuid", "target_item_id" "uuid", "expected_revision" integer, "new_category" "text", "new_name" "text", "new_description" "text", "new_unit_label" "text", "new_is_labor" boolean, "new_unit_price_minor" bigint, "new_unit_cost_minor" bigint, "new_is_taxable" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  item_row public.catalog_items;
  clean_name text;
begin
  if not private.has_permission(target_organization_id, 'settings.price_book.manage') then
    raise exception 'You do not have access to manage the Price Book.' using errcode = 'insufficient_privilege';
  end if;

  select * into item_row
  from public.catalog_items
  where id = target_item_id and organization_id = target_organization_id
  for update;

  if item_row.id is null then
    raise exception 'That Price Book item was not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from item_row.revision then
    raise exception 'Someone else changed this item while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) < 2 or char_length(clean_name) > 160 then
    raise exception 'Give this item a name between 2 and 160 characters.' using errcode = 'check_violation';
  end if;

  if item_row.archived_at is null and exists (
    select 1 from public.catalog_items
    where organization_id = target_organization_id
      and archived_at is null
      and id <> item_row.id
      and lower(name) = lower(clean_name)
  ) then
    raise exception 'An active Price Book item is already named "%".', clean_name
      using errcode = 'unique_violation';
  end if;

  update public.catalog_items
  set category = new_category, name = clean_name, description = new_description,
      unit_label = new_unit_label, is_labor = coalesce(new_is_labor, item_row.is_labor),
      unit_price_minor = coalesce(new_unit_price_minor, item_row.unit_price_minor),
      unit_cost_minor = coalesce(new_unit_cost_minor, item_row.unit_cost_minor),
      is_taxable = coalesce(new_is_taxable, item_row.is_taxable),
      revision = revision + 1, updated_by = (select auth.uid())
  where id = item_row.id
  returning * into item_row;

  return jsonb_build_object('id', item_row.id, 'name', item_row.name, 'revision', item_row.revision);
end;
$$;


ALTER FUNCTION "public"."update_catalog_item"("target_organization_id" "uuid", "target_item_id" "uuid", "expected_revision" integer, "new_category" "text", "new_name" "text", "new_description" "text", "new_unit_label" "text", "new_is_labor" boolean, "new_unit_price_minor" bigint, "new_unit_cost_minor" bigint, "new_is_taxable" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_checklist_template"("target_organization_id" "uuid", "target_template_id" "uuid", "name" "text", "items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  existing public.checklist_templates;
  jobs_using integer;
begin
  if caller is null then
    raise exception 'You must be signed in to change a checklist.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'settings.checklists.manage') then
    raise exception 'You do not have access to change checklists.' using errcode = 'insufficient_privilege';
  end if;
  select template.* into existing from public.checklist_templates as template
  where template.organization_id = target_organization_id and template.id = target_template_id for update;
  if not found then
    raise exception 'That checklist could not be found.' using errcode = 'P0404';
  end if;
  update public.checklist_templates set name = trim(update_checklist_template.name), updated_at = now()
  where organization_id = target_organization_id and id = target_template_id;
  perform private.replace_checklist_template_items(target_organization_id, target_template_id, items);
  select count(*) into jobs_using from public.job_checklists
  where organization_id = target_organization_id and source_template_id = target_template_id;
  return jsonb_build_object('id', target_template_id, 'jobs_already_using', jobs_using);
end;
$$;


ALTER FUNCTION "public"."update_checklist_template"("target_organization_id" "uuid", "target_template_id" "uuid", "name" "text", "items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_checklist_template"("target_organization_id" "uuid", "target_template_id" "uuid", "name" "text", "items" "jsonb") IS 'Renames a checklist and replaces its questions. Jobs that already carry it keep the questions they were given; the count of those jobs comes back so the screen can say so.';



CREATE OR REPLACE FUNCTION "public"."update_client"("payload" "jsonb") RETURNS "public"."clients"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_organization_id uuid := (payload->>'organization_id')::uuid;
  target_client_id uuid := (payload->>'id')::uuid;
  updated_client public.clients;
  email_value text := nullif(trim(payload->>'email'), '');
  phone_value text := nullif(trim(payload->>'phone'), '');
  property_payload jsonb := payload->'property';
  preferences jsonb := payload->'preferences';
  tag_ids jsonb := payload->'tag_ids';
  existing_email_id uuid;
  existing_phone_id uuid;
  existing_property_id uuid;
begin
  update public.clients as target
  set
    display_name = payload->>'display_name',
    client_type = coalesce(nullif(payload->>'client_type', ''), target.client_type),
    first_name = nullif(trim(payload->>'first_name'), ''),
    last_name = nullif(trim(payload->>'last_name'), ''),
    company_name = nullif(trim(payload->>'company_name'), ''),
    lifecycle_status = coalesce(nullif(payload->>'lifecycle_status', ''), target.lifecycle_status),
    lead_source = nullif(trim(payload->>'lead_source'), ''),
    lead_temperature = nullif(payload->>'lead_temperature', ''),
    next_follow_up_at = nullif(payload->>'next_follow_up_at', '')::timestamptz
  where target.id = target_client_id
    and target.organization_id = target_organization_id
    and target.deleted_at is null
  returning target.* into updated_client;

  if updated_client.id is null then
    raise exception 'That client could not be found.' using errcode = 'P0002';
  end if;

  select id into existing_email_id
  from public.client_contact_methods
  where organization_id = target_organization_id
    and client_id = target_client_id
    and kind = 'email'
    and is_primary;

  if email_value is null then
    delete from public.client_contact_methods where id = existing_email_id;
  elsif existing_email_id is null then
    insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
    values (target_organization_id, target_client_id, 'email', email_value, true);
  else
    update public.client_contact_methods set value = email_value where id = existing_email_id;
  end if;

  select id into existing_phone_id
  from public.client_contact_methods
  where organization_id = target_organization_id
    and client_id = target_client_id
    and kind = 'phone'
    and is_primary;

  if phone_value is null then
    delete from public.client_contact_methods where id = existing_phone_id;
  elsif existing_phone_id is null then
    insert into public.client_contact_methods (organization_id, client_id, kind, value, is_primary)
    values (target_organization_id, target_client_id, 'phone', phone_value, true);
  else
    update public.client_contact_methods set value = phone_value where id = existing_phone_id;
  end if;

  if property_payload is not null and jsonb_typeof(property_payload) = 'object' then
    select id into existing_property_id
    from public.properties
    where organization_id = target_organization_id
      and client_id = target_client_id
      and deleted_at is null
      and is_primary;

    if existing_property_id is null then
      insert into public.properties (
        organization_id,
        client_id,
        label,
        address_line1,
        address_line2,
        city,
        state_region,
        postal_code,
        country,
        access_notes,
        is_billing_address
      )
      values (
        target_organization_id,
        target_client_id,
        coalesce(nullif(trim(property_payload->>'label'), ''), 'Primary property'),
        property_payload->>'address_line1',
        nullif(trim(property_payload->>'address_line2'), ''),
        property_payload->>'city',
        nullif(trim(property_payload->>'state_region'), ''),
        nullif(trim(property_payload->>'postal_code'), ''),
        coalesce(nullif(property_payload->>'country', ''), 'US'),
        nullif(trim(property_payload->>'access_notes'), ''),
        coalesce((property_payload->>'is_billing_address')::boolean, false)
      );
    else
      update public.properties as existing
      set
        label = coalesce(nullif(trim(property_payload->>'label'), ''), existing.label),
        address_line1 = property_payload->>'address_line1',
        address_line2 = nullif(trim(property_payload->>'address_line2'), ''),
        city = property_payload->>'city',
        state_region = nullif(trim(property_payload->>'state_region'), ''),
        postal_code = nullif(trim(property_payload->>'postal_code'), ''),
        country = coalesce(nullif(property_payload->>'country', ''), existing.country),
        access_notes = nullif(trim(property_payload->>'access_notes'), ''),
        is_billing_address = coalesce(
          (property_payload->>'is_billing_address')::boolean,
          existing.is_billing_address
        )
      where existing.id = existing_property_id;
    end if;
  end if;

  if preferences is not null and jsonb_typeof(preferences) = 'object' then
    update public.client_communication_preferences as saved
    set
      appointment_reminders = coalesce((preferences->>'appointment_reminders')::boolean, saved.appointment_reminders),
      quote_follow_ups = coalesce((preferences->>'quote_follow_ups')::boolean, saved.quote_follow_ups),
      invoice_reminders = coalesce((preferences->>'invoice_reminders')::boolean, saved.invoice_reminders),
      job_follow_ups = coalesce((preferences->>'job_follow_ups')::boolean, saved.job_follow_ups),
      review_requests = coalesce((preferences->>'review_requests')::boolean, saved.review_requests),
      contact_policy = coalesce(nullif(preferences->>'contact_policy', ''), saved.contact_policy)
    where saved.organization_id = target_organization_id
      and saved.client_id = target_client_id;
  end if;

  if tag_ids is not null and jsonb_typeof(tag_ids) = 'array' then
    delete from public.tag_assignments as assigned
    where assigned.organization_id = target_organization_id
      and assigned.entity_type = 'client'
      and assigned.entity_id = target_client_id
      and assigned.tag_id not in (
        select chosen.value::uuid from jsonb_array_elements_text(tag_ids) as chosen(value)
      );

    insert into public.tag_assignments (organization_id, tag_id, entity_type, entity_id, created_by)
    select
      target_organization_id,
      chosen.value::uuid,
      'client',
      target_client_id,
      (select auth.uid())
    from jsonb_array_elements_text(tag_ids) as chosen(value)
    on conflict (tag_id, entity_type, entity_id) do nothing;
  end if;

  return updated_client;
end;
$$;


ALTER FUNCTION "public"."update_client"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_form_booking_settings"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer, "new_requires_booking_approval" boolean, "new_service_area_enabled" boolean, "new_min_notice_minutes" integer, "new_slot_interval_minutes" integer, "new_visit_duration_minutes" integer, "new_arrival_window_minutes" integer, "new_buffer_minutes" integer, "new_service_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  form_row public.forms;
  rules_row public.form_booking_rules;
  org_settings public.organization_settings;
  clean_service_ids uuid[];
  invalid_service_count integer;
begin
  if not private.has_permission(target_organization_id, 'settings.forms.manage') then
    raise exception 'You do not have access to manage forms.' using errcode = 'insufficient_privilege';
  end if;

  select * into form_row from public.forms
  where id = target_form_id and organization_id = target_organization_id
  for update;

  if form_row.id is null then
    raise exception 'That form was not found.' using errcode = 'check_violation';
  end if;
  if form_row.outcome not in ('assessment', 'job') then
    raise exception 'Only assessment and job forms have booking rules.' using errcode = 'check_violation';
  end if;
  if form_row.archived_at is not null then
    raise exception 'Restore this form before editing it.' using errcode = 'check_violation';
  end if;

  select * into rules_row from public.form_booking_rules
  where form_id = target_form_id
  for update;

  if expected_revision is distinct from rules_row.revision then
    raise exception 'Someone else changed these booking rules while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  if new_min_notice_minutes is null or new_min_notice_minutes not between 0 and 43200 then
    raise exception 'Minimum notice must be between 0 minutes and 30 days.' using errcode = 'check_violation';
  end if;
  if new_slot_interval_minutes is null or new_slot_interval_minutes not between 5 and 480 then
    raise exception 'Slot length must be between 5 minutes and 8 hours.' using errcode = 'check_violation';
  end if;
  if new_visit_duration_minutes is null or new_visit_duration_minutes not between 5 and 1440 then
    raise exception 'Visit duration must be between 5 minutes and 24 hours.' using errcode = 'check_violation';
  end if;
  if new_arrival_window_minutes is not null and new_arrival_window_minutes not between 0 and 480 then
    raise exception 'Arrival window must be between 0 minutes and 8 hours.' using errcode = 'check_violation';
  end if;
  if new_buffer_minutes is null or new_buffer_minutes not between 0 and 480 then
    raise exception 'Buffer time must be between 0 minutes and 8 hours.' using errcode = 'check_violation';
  end if;

  if coalesce(new_service_area_enabled, false) then
    select * into org_settings from public.organization_settings
    where organization_id = target_organization_id;

    if org_settings.latitude is null or org_settings.longitude is null then
      raise exception 'Confirm your business location in Business Profile before turning on the service area.'
        using errcode = 'check_violation';
    end if;
    if org_settings.service_area_radius_miles is null then
      raise exception 'Set a service area radius in Business Profile before turning it on here.'
        using errcode = 'check_violation';
    end if;
  end if;

  -- De-duplicate while keeping the caller's chosen order, and cap the list the same way 4B-1 caps sections.
  select array_agg(distinct service_id) into clean_service_ids
  from unnest(coalesce(new_service_ids, '{}')) as service_id;
  clean_service_ids := coalesce(clean_service_ids, '{}');
  if array_length(clean_service_ids, 1) > 20 then
    raise exception 'A form can offer up to 20 bookable services.' using errcode = 'check_violation';
  end if;

  if array_length(clean_service_ids, 1) > 0 then
    select count(*) into invalid_service_count
    from unnest(clean_service_ids) as service_id
    where not exists (
      select 1 from public.catalog_items as item
      where item.id = service_id
        and item.organization_id = target_organization_id
        and item.category = 'service'
        and item.archived_at is null
    );
    if invalid_service_count > 0 then
      raise exception 'One of the selected services is no longer available.' using errcode = 'check_violation';
    end if;
  end if;

  update public.form_booking_rules
  set requires_booking_approval = coalesce(new_requires_booking_approval, rules_row.requires_booking_approval),
      service_area_enabled = coalesce(new_service_area_enabled, false),
      min_notice_minutes = new_min_notice_minutes,
      slot_interval_minutes = new_slot_interval_minutes,
      visit_duration_minutes = new_visit_duration_minutes,
      arrival_window_minutes = new_arrival_window_minutes,
      buffer_minutes = new_buffer_minutes,
      revision = revision + 1,
      updated_by = (select auth.uid()),
      updated_at = now()
  where form_id = target_form_id
  returning * into rules_row;

  delete from public.form_bookable_services where form_id = target_form_id;

  if array_length(clean_service_ids, 1) > 0 then
    insert into public.form_bookable_services (form_id, organization_id, catalog_item_id, position)
    select target_form_id, target_organization_id, service_id, ordinality - 1
    from unnest(clean_service_ids) with ordinality as service_id;
  end if;

  return jsonb_build_object(
    'form_id', target_form_id,
    'revision', rules_row.revision,
    'requires_booking_approval', rules_row.requires_booking_approval,
    'service_area_enabled', rules_row.service_area_enabled,
    'min_notice_minutes', rules_row.min_notice_minutes,
    'slot_interval_minutes', rules_row.slot_interval_minutes,
    'visit_duration_minutes', rules_row.visit_duration_minutes,
    'arrival_window_minutes', rules_row.arrival_window_minutes,
    'buffer_minutes', rules_row.buffer_minutes,
    'service_ids', to_jsonb(clean_service_ids)
  );
end;
$$;


ALTER FUNCTION "public"."update_form_booking_settings"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer, "new_requires_booking_approval" boolean, "new_service_area_enabled" boolean, "new_min_notice_minutes" integer, "new_slot_interval_minutes" integer, "new_visit_duration_minutes" integer, "new_arrival_window_minutes" integer, "new_buffer_minutes" integer, "new_service_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_form_draft"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer, "new_title" "text", "new_description" "text", "new_content" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  form_row public.forms;
  draft_row public.form_versions;
  clean_title text;
  clean_description text;
begin
  if not private.has_permission(target_organization_id, 'settings.forms.manage') then
    raise exception 'You do not have access to manage forms.' using errcode = 'insufficient_privilege';
  end if;

  select * into form_row from public.forms
  where id = target_form_id and organization_id = target_organization_id;
  if form_row.id is null then
    raise exception 'That form was not found.' using errcode = 'check_violation';
  end if;
  if form_row.draft_version_id is null then
    raise exception 'This form has no draft to edit. Start a new draft first.'
      using errcode = 'check_violation';
  end if;

  select * into draft_row from public.form_versions
  where id = form_row.draft_version_id and organization_id = target_organization_id
  for update;

  if expected_revision is distinct from draft_row.revision then
    raise exception 'Someone else changed this draft while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  clean_title := nullif(trim(coalesce(new_title, '')), '');
  if clean_title is null or char_length(clean_title) > 160 then
    raise exception 'Give this form a title customers will see, up to 160 characters.'
      using errcode = 'check_violation';
  end if;

  clean_description := nullif(trim(coalesce(new_description, '')), '');
  if clean_description is not null and char_length(clean_description) > 2000 then
    raise exception 'The form description is too long.' using errcode = 'check_violation';
  end if;

  if new_content is null or jsonb_typeof(new_content) <> 'object' then
    raise exception 'The form content is missing or malformed.' using errcode = 'check_violation';
  end if;
  if length(new_content::text) > 65536 then
    raise exception 'This form has too much content. Remove some questions and try again.'
      using errcode = 'check_violation';
  end if;

  update public.form_versions
  set title = clean_title, description = clean_description, content = new_content,
      revision = revision + 1, updated_by = (select auth.uid()), updated_at = now()
  where id = draft_row.id
  returning * into draft_row;

  return jsonb_build_object(
    'form_id', form_row.id, 'draft_version_id', draft_row.id,
    'title', draft_row.title, 'description', draft_row.description,
    'content', draft_row.content, 'revision', draft_row.revision
  );
end;
$$;


ALTER FUNCTION "public"."update_form_draft"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer, "new_title" "text", "new_description" "text", "new_content" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_form_identity"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer, "new_name" "text", "new_is_enabled" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  form_row public.forms;
  clean_name text;
begin
  if not private.has_permission(target_organization_id, 'settings.forms.manage') then
    raise exception 'You do not have access to manage forms.' using errcode = 'insufficient_privilege';
  end if;

  select * into form_row from public.forms
  where id = target_form_id and organization_id = target_organization_id
  for update;

  if form_row.id is null then
    raise exception 'That form was not found.' using errcode = 'check_violation';
  end if;
  if form_row.archived_at is not null then
    raise exception 'Restore this form before editing it.' using errcode = 'check_violation';
  end if;
  if expected_revision is distinct from form_row.revision then
    raise exception 'Someone else changed this form while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) > 120 then
    raise exception 'Give this form a name up to 120 characters.' using errcode = 'check_violation';
  end if;

  update public.forms
  set name = clean_name, is_enabled = coalesce(new_is_enabled, form_row.is_enabled),
      revision = revision + 1, updated_by = (select auth.uid()), updated_at = now()
  where id = form_row.id
  returning * into form_row;

  return jsonb_build_object(
    'form_id', form_row.id, 'name', form_row.name, 'is_enabled', form_row.is_enabled,
    'revision', form_row.revision
  );
end;
$$;


ALTER FUNCTION "public"."update_form_identity"("target_organization_id" "uuid", "target_form_id" "uuid", "expected_revision" integer, "new_name" "text", "new_is_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_invoice_contract_disclaimer"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_disclaimer" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  invoice_row public.invoices;
  clean_disclaimer text := nullif(trim(coalesce(new_disclaimer, '')), '');
  new_revision integer;
begin
  invoice_row := private.lock_invoice_for_edit(
    target_organization_id, target_invoice_id, expected_revision
  );

  if invoice_row.document_frozen_at is not null then
    raise exception 'This invoice has been issued, so its contract disclaimer cannot be changed.'
      using errcode = 'check_violation';
  end if;

  if clean_disclaimer is not null and char_length(clean_disclaimer) > 5000 then
    raise exception 'The contract disclaimer is too long.' using errcode = 'check_violation';
  end if;

  update public.invoices
  set contract_disclaimer = clean_disclaimer, revision = invoice_row.revision + 1
  where organization_id = target_organization_id and id = target_invoice_id
  returning revision into new_revision;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.disclaimer_updated', caller, new_revision, null, '{}'::jsonb, false, null
  );

  return jsonb_build_object('revision', new_revision);
end;
$$;


ALTER FUNCTION "public"."update_invoice_contract_disclaimer"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_disclaimer" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_invoice_contract_disclaimer"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_disclaimer" "text") IS 'Enters, saves or clears the draft''s contract disclaimer. Refused once the document has frozen -- the wording a customer could have already seen never quietly changes underneath them.';



CREATE OR REPLACE FUNCTION "public"."update_invoice_details"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_subject" "text", "new_issue_date" "date", "new_payment_term_id" "uuid", "new_custom_due_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  invoice_row public.invoices;
  term_row public.invoice_payment_terms;
  clean_subject text := nullif(trim(coalesce(new_subject, '')), '');
  issue_on date;
  due_on date;
  term_source text;
begin
  invoice_row := private.lock_invoice_for_edit(
    target_organization_id, target_invoice_id, expected_revision
  );

  if clean_subject is null or char_length(clean_subject) < 2 or char_length(clean_subject) > 160 then
    raise exception 'An invoice needs a subject between 2 and 160 characters.'
      using errcode = 'check_violation';
  end if;

  issue_on := coalesce(new_issue_date, invoice_row.issue_date);

  if new_custom_due_date is not null then
    if new_payment_term_id is not null then
      raise exception 'Choose either a payment term or a custom due date, not both.'
        using errcode = 'check_violation';
    end if;
    if new_custom_due_date < issue_on then
      raise exception 'A due date cannot be before the invoice date.' using errcode = 'check_violation';
    end if;
    term_source := 'custom';
    due_on := new_custom_due_date;
  else
    term_row := private.resolve_client_payment_term(
      target_organization_id, invoice_row.client_id, new_payment_term_id
    );
    term_source := 'term';
    due_on := greatest(private.invoice_due_date(issue_on, term_row), issue_on);
  end if;

  perform private.retain_prior_invoice_document(invoice_row, caller, 'details updated');

  update public.invoices
  set subject = clean_subject,
      issue_date = issue_on,
      due_date = due_on,
      due_date_source = term_source,
      payment_term_id = case when term_source = 'term' then term_row.id end,
      payment_term_snapshot = case when term_source = 'term' then jsonb_build_object(
        'term_id', term_row.id, 'name', term_row.name, 'rule', term_row.rule, 'net_days', term_row.net_days
      ) else jsonb_build_object('rule', 'custom_date') end,
      revision = invoice_row.revision + 1
  where organization_id = target_organization_id and id = target_invoice_id;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.details_updated', caller, invoice_row.revision + 1, null,
    jsonb_build_object('due_date_source', term_source), false, null
  );

  return jsonb_build_object(
    'revision', invoice_row.revision + 1, 'issue_date', issue_on, 'due_date', due_on
  );
end;
$$;


ALTER FUNCTION "public"."update_invoice_details"("target_organization_id" "uuid", "target_invoice_id" "uuid", "expected_revision" integer, "new_subject" "text", "new_issue_date" "date", "new_payment_term_id" "uuid", "new_custom_due_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_job_details"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_title" "text", "new_instructions" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_job public.jobs;
  clean_title text := trim(coalesce(new_title, ''));
  clean_instructions text := nullif(trim(coalesce(new_instructions, '')), '');
  changed text[] := array[]::text[];
begin
  if caller is null then
    raise exception 'You must be signed in to edit a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.edit') then
    raise exception 'You do not have access to edit this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.* into current_job
  from public.jobs as job
  where job.organization_id = target_organization_id
    and job.id = target_job_id
  for update;

  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  if current_job.revision is distinct from expected_revision then
    raise exception 'Someone else changed this job. Reload to see the latest.' using errcode = 'P0409';
  end if;

  if clean_title is distinct from current_job.title then
    changed := array_append(changed, 'title');
  end if;
  if clean_instructions is distinct from current_job.instructions then
    changed := array_append(changed, 'instructions');
  end if;

  update public.jobs
  set title = clean_title,
      instructions = clean_instructions,
      revision = current_job.revision + 1
  where organization_id = target_organization_id
    and id = target_job_id;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'details_updated',
    caller,
    jsonb_build_object('changed', to_jsonb(changed))
  );

  return jsonb_build_object('revision', current_job.revision + 1);
end;
$$;


ALTER FUNCTION "public"."update_job_details"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_title" "text", "new_instructions" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_job_details"("target_organization_id" "uuid", "target_job_id" "uuid", "expected_revision" integer, "new_title" "text", "new_instructions" "text") IS 'Staged save of a job''s title and instructions. Checks jobs.edit, refuses a stale revision (P0409), bumps revision and appends a details_updated history row. The only editor of these two fields.';



CREATE OR REPLACE FUNCTION "public"."update_job_expense"("target_organization_id" "uuid", "target_job_id" "uuid", "target_expense_id" "uuid", "name" "text", "expense_date" "date", "total_minor" bigint, "accounting_code" "text" DEFAULT NULL::"text", "description" "text" DEFAULT NULL::"text", "reimburse_to_user_id" "uuid" DEFAULT NULL::"uuid", "reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  job_closed boolean;
  existing public.job_expenses;
  updated public.job_expenses;
begin
  if caller is null then
    raise exception 'You must be signed in to change an expense.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.status <> 'active' into job_closed
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  select expense.* into existing
  from public.job_expenses as expense
  where expense.organization_id = target_organization_id
    and expense.job_id = target_job_id
    and expense.id = target_expense_id
  for update;
  if not found then
    raise exception 'That expense could not be found.' using errcode = 'P0404';
  end if;

  if not private.can_write_job_expense(target_organization_id, caller, existing.created_by, job_closed) then
    if job_closed then
      raise exception 'A closed job''s expenses can only be changed by someone who manages the team''s expenses.'
        using errcode = 'P0410';
    end if;
    raise exception 'You do not have access to change this expense.' using errcode = 'insufficient_privilege';
  end if;

  if reimburse_to_user_id is not null and not exists (
    select 1
    from public.organization_members as member
    where member.organization_id = target_organization_id
      and member.user_id = reimburse_to_user_id
      and member.status <> 'removed'
  ) then
    raise exception 'That person is not on this team.' using errcode = 'P0404';
  end if;

  update public.job_expenses as expense
  set name = trim(update_job_expense.name),
      accounting_code = nullif(trim(coalesce(update_job_expense.accounting_code, '')), ''),
      description = nullif(trim(coalesce(update_job_expense.description, '')), ''),
      expense_date = update_job_expense.expense_date,
      total_minor = update_job_expense.total_minor,
      reimburse_to_user_id = update_job_expense.reimburse_to_user_id
  where expense.organization_id = target_organization_id
    and expense.id = target_expense_id
  returning * into updated;

  insert into public.job_costing_events (
    organization_id, job_id, event_type, subject_kind, subject_id, actor_id, after_close,
    reason, prior_values, new_values
  )
  values (
    target_organization_id, target_job_id, 'expense_updated', 'expense', target_expense_id, caller,
    job_closed,
    nullif(trim(coalesce(update_job_expense.reason, '')), ''),
    jsonb_build_object(
      'name', existing.name,
      'accounting_code', existing.accounting_code,
      'expense_date', existing.expense_date,
      'total_minor', existing.total_minor,
      'reimburse_to_user_id', existing.reimburse_to_user_id
    ),
    jsonb_build_object(
      'name', updated.name,
      'accounting_code', updated.accounting_code,
      'expense_date', updated.expense_date,
      'total_minor', updated.total_minor,
      'reimburse_to_user_id', updated.reimburse_to_user_id
    )
  );

  return jsonb_build_object('id', updated.id, 'after_close', job_closed);
end;
$$;


ALTER FUNCTION "public"."update_job_expense"("target_organization_id" "uuid", "target_job_id" "uuid", "target_expense_id" "uuid", "name" "text", "expense_date" "date", "total_minor" bigint, "accounting_code" "text", "description" "text", "reimburse_to_user_id" "uuid", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_job_expense"("target_organization_id" "uuid", "target_job_id" "uuid", "target_expense_id" "uuid", "name" "text", "expense_date" "date", "total_minor" bigint, "accounting_code" "text", "description" "text", "reimburse_to_user_id" "uuid", "reason" "text") IS 'Corrects a recorded expense, keeping the person who recorded it. Needs expenses.manage_team, or expenses.record on an open job for their own. The before and after are written to job_costing_events.';



CREATE OR REPLACE FUNCTION "public"."update_job_time_entry"("target_organization_id" "uuid", "target_job_id" "uuid", "target_entry_id" "uuid", "started_at" timestamp with time zone, "minutes" integer, "target_visit_id" "uuid" DEFAULT NULL::"uuid", "notes" "text" DEFAULT NULL::"text", "reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  job_closed boolean;
  existing public.job_time_entries;
  updated public.job_time_entries;
begin
  if caller is null then
    raise exception 'You must be signed in to change hours.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_job_is_visible(target_organization_id, caller, target_job_id) then
    raise exception 'You do not have access to this job.' using errcode = 'insufficient_privilege';
  end if;

  select job.status <> 'active' into job_closed
  from public.jobs as job
  where job.organization_id = target_organization_id and job.id = target_job_id;
  if not found then
    raise exception 'That job could not be found.' using errcode = 'P0404';
  end if;

  -- The entry is locked, not the job: two corrections to the same entry queue, and corrections to different
  -- entries on the same job do not wait for each other.
  select entry.* into existing
  from public.job_time_entries as entry
  where entry.organization_id = target_organization_id
    and entry.job_id = target_job_id
    and entry.id = target_entry_id
  for update;
  if not found then
    raise exception 'Those hours could not be found.' using errcode = 'P0404';
  end if;

  if not private.can_write_job_time(target_organization_id, caller, existing.user_id, job_closed) then
    if job_closed then
      raise exception 'A closed job''s hours can only be changed by someone who manages the team''s time.'
        using errcode = 'P0410';
    end if;
    raise exception 'You do not have access to change these hours.' using errcode = 'insufficient_privilege';
  end if;

  if target_visit_id is not null and not exists (
    select 1
    from public.job_visits as visit
    where visit.organization_id = target_organization_id
      and visit.job_id = target_job_id
      and visit.id = target_visit_id
  ) then
    raise exception 'That visit could not be found on this job.' using errcode = 'P0404';
  end if;

  -- cost_per_hour_minor is absent on purpose. The rate stays as recorded; only the duration it applies to can
  -- change, and the generated cost column follows it.
  update public.job_time_entries as entry
  set visit_id = target_visit_id,
      started_at = update_job_time_entry.started_at,
      minutes = update_job_time_entry.minutes,
      notes = nullif(trim(coalesce(update_job_time_entry.notes, '')), '')
  where entry.organization_id = target_organization_id
    and entry.id = target_entry_id
  returning * into updated;

  insert into public.job_costing_events (
    organization_id, job_id, event_type, subject_kind, subject_id, actor_id, after_close,
    reason, prior_values, new_values
  )
  values (
    target_organization_id, target_job_id, 'time_entry_updated', 'time_entry', target_entry_id, caller,
    job_closed,
    nullif(trim(coalesce(update_job_time_entry.reason, '')), ''),
    jsonb_build_object(
      'visit_id', existing.visit_id,
      'started_at', existing.started_at,
      'minutes', existing.minutes,
      'cost_total_minor', existing.cost_total_minor
    ),
    jsonb_build_object(
      'visit_id', updated.visit_id,
      'started_at', updated.started_at,
      'minutes', updated.minutes,
      'cost_total_minor', updated.cost_total_minor
    )
  );

  return jsonb_build_object('id', updated.id, 'after_close', job_closed);
end;
$$;


ALTER FUNCTION "public"."update_job_time_entry"("target_organization_id" "uuid", "target_job_id" "uuid", "target_entry_id" "uuid", "started_at" timestamp with time zone, "minutes" integer, "target_visit_id" "uuid", "notes" "text", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_job_time_entry"("target_organization_id" "uuid", "target_job_id" "uuid", "target_entry_id" "uuid", "started_at" timestamp with time zone, "minutes" integer, "target_visit_id" "uuid", "notes" "text", "reason" "text") IS 'Corrects recorded hours, keeping the rate the entry was recorded with. Whose hours they are cannot change. Needs time.track_team for anyone else''s, time.track_own for their own on an open job. The before and after are written to job_costing_events.';



CREATE OR REPLACE FUNCTION "public"."update_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid", "expected_revision" integer, "new_visit_date" "date", "new_start_time" time without time zone, "new_end_time" time without time zone, "new_all_day" boolean, "new_title" "text", "new_instructions" "text", "new_assignee_ids" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  current_visit public.job_visits;
  clean_title text := nullif(trim(coalesce(new_title, '')), '');
  clean_instructions text := nullif(trim(coalesce(new_instructions, '')), '');
  changed text[] := array[]::text[];
  assignee_element jsonb;
begin
  if caller is null then
    raise exception 'You must be signed in to schedule a job.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'jobs.schedule') then
    raise exception 'You do not have access to schedule this job.' using errcode = 'insufficient_privilege';
  end if;

  select visit.* into current_visit
  from public.job_visits as visit
  where visit.organization_id = target_organization_id
    and visit.job_id = target_job_id
    and visit.id = target_visit_id
  for update;
  if not found then
    raise exception 'That visit could not be found.' using errcode = 'P0404';
  end if;

  if current_visit.completed_at is not null then
    raise exception 'A completed visit cannot be rescheduled.' using errcode = 'P0410';
  end if;

  if current_visit.revision is distinct from expected_revision then
    raise exception 'Someone else changed this visit. Reload to see the latest.' using errcode = 'P0409';
  end if;

  if new_visit_date is distinct from current_visit.visit_date
    or new_start_time is distinct from current_visit.start_time
    or new_end_time is distinct from current_visit.end_time
    or coalesce(new_all_day, false) is distinct from current_visit.all_day then
    changed := array_append(changed, 'schedule');
  end if;
  if clean_title is distinct from current_visit.title then
    changed := array_append(changed, 'title');
  end if;
  if clean_instructions is distinct from current_visit.instructions then
    changed := array_append(changed, 'instructions');
  end if;
  if new_assignee_ids is not null and jsonb_typeof(new_assignee_ids) = 'array' then
    changed := array_append(changed, 'assignees');
  end if;

  update public.job_visits
  set visit_date = new_visit_date,
      start_time = new_start_time,
      end_time = new_end_time,
      all_day = coalesce(new_all_day, false),
      title = clean_title,
      instructions = clean_instructions,
      revision = current_visit.revision + 1,
      updated_at = now()
  where organization_id = target_organization_id
    and id = target_visit_id;

  if new_assignee_ids is not null and jsonb_typeof(new_assignee_ids) = 'array' then
    delete from public.job_visit_assignments
    where organization_id = target_organization_id and visit_id = target_visit_id;
    for assignee_element in select value from jsonb_array_elements(new_assignee_ids) as a(value)
    loop
      insert into public.job_visit_assignments (organization_id, visit_id, user_id)
      values (target_organization_id, target_visit_id, (assignee_element #>> '{}')::uuid)
      on conflict do nothing;
    end loop;
  end if;

  insert into public.job_events (organization_id, job_id, event_type, actor_id, related_visit_id, metadata)
  values (
    target_organization_id,
    target_job_id,
    'visit_updated',
    caller,
    target_visit_id,
    jsonb_build_object('changed', to_jsonb(changed))
  );

  return jsonb_build_object('revision', current_visit.revision + 1);
end;
$$;


ALTER FUNCTION "public"."update_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid", "expected_revision" integer, "new_visit_date" "date", "new_start_time" time without time zone, "new_end_time" time without time zone, "new_all_day" boolean, "new_title" "text", "new_instructions" "text", "new_assignee_ids" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_job_visit"("target_organization_id" "uuid", "target_job_id" "uuid", "target_visit_id" "uuid", "expected_revision" integer, "new_visit_date" "date", "new_start_time" time without time zone, "new_end_time" time without time zone, "new_all_day" boolean, "new_title" "text", "new_instructions" "text", "new_assignee_ids" "jsonb") IS 'Edits one visit''s schedule shape, title, instructions and crew. Checks jobs.schedule, refuses a completed visit (P0410) and a stale revision (P0409), bumps the visit revision and appends a visit_updated row.';



CREATE OR REPLACE FUNCTION "public"."update_organization_service_area_radius"("target_organization_id" "uuid", "expected_revision" integer, "new_radius_miles" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings_row public.organization_settings;
  editor_name text;
  editor_at timestamptz;
begin
  if not private.has_permission(target_organization_id, 'settings.business.edit') then
    raise exception 'You do not have access to change business settings.'
      using errcode = 'insufficient_privilege';
  end if;

  if new_radius_miles is null or new_radius_miles < 0.1 or new_radius_miles > 500 then
    raise exception 'Service area radius must be between 0.1 and 500 miles.' using errcode = 'check_violation';
  end if;

  select * into settings_row from public.organization_settings
  where organization_id = target_organization_id
  for update;

  if settings_row.organization_id is null then
    raise exception 'Organization settings were not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from settings_row.profile_revision then
    select profile.full_name, settings_row.profile_updated_at into editor_name, editor_at
    from public.profiles as profile
    where profile.id = settings_row.profile_updated_by;

    return jsonb_build_object(
      'status', 'stale',
      'editor_name', editor_name,
      'edited_at', coalesce(editor_at, settings_row.updated_at)
    );
  end if;

  update public.organization_settings
  set service_area_radius_miles = new_radius_miles,
      profile_revision = profile_revision + 1,
      profile_updated_by = (select auth.uid()),
      profile_updated_at = now()
  where organization_id = target_organization_id
  returning * into settings_row;

  return jsonb_build_object(
    'status', 'saved',
    'profile_revision', settings_row.profile_revision,
    'service_area_radius_miles', settings_row.service_area_radius_miles
  );
end;
$$;


ALTER FUNCTION "public"."update_organization_service_area_radius"("target_organization_id" "uuid", "expected_revision" integer, "new_radius_miles" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_organization_tax_rate"("target_organization_id" "uuid", "target_rate_id" "uuid", "expected_revision" integer, "new_name" "text", "new_rate_basis_points" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  rate_row public.organization_tax_rates;
  clean_name text;
begin
  if not private.has_permission(target_organization_id, 'settings.taxes.manage') then
    raise exception 'You do not have access to manage taxes.' using errcode = 'insufficient_privilege';
  end if;

  select * into rate_row
  from public.organization_tax_rates
  where id = target_rate_id and organization_id = target_organization_id
  for update;

  if rate_row.id is null then
    raise exception 'That tax rate was not found.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from rate_row.revision then
    raise exception 'Someone else changed this tax rate while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) > 80 then
    raise exception 'Give this tax rate a name up to 80 characters.' using errcode = 'check_violation';
  end if;

  if new_rate_basis_points is null or new_rate_basis_points <= 0 or new_rate_basis_points > 10000 then
    raise exception 'A tax rate is greater than 0%% and no more than 100%%.' using errcode = 'check_violation';
  end if;

  update public.organization_tax_rates
  set name = clean_name, rate_basis_points = new_rate_basis_points,
      revision = revision + 1, updated_by = (select auth.uid()), updated_at = now()
  where id = rate_row.id
  returning * into rate_row;

  return jsonb_build_object(
    'id', rate_row.id, 'name', rate_row.name, 'rate_basis_points', rate_row.rate_basis_points,
    'is_active', rate_row.is_active, 'revision', rate_row.revision
  );
end;
$$;


ALTER FUNCTION "public"."update_organization_tax_rate"("target_organization_id" "uuid", "target_rate_id" "uuid", "expected_revision" integer, "new_name" "text", "new_rate_basis_points" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."platform_owner_settings" (
    "id" boolean DEFAULT true NOT NULL,
    "privacy_policy_url" "text" DEFAULT ''::"text" NOT NULL,
    "privacy_policy_version" "text" DEFAULT ''::"text" NOT NULL,
    "payment_instructions" "text" DEFAULT ''::"text" NOT NULL,
    "sender_display_name" "text" DEFAULT ''::"text" NOT NULL,
    "reply_to_address" "text" DEFAULT ''::"text" NOT NULL,
    "alert_recipient_emails" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "platform_owner_settings_id_check" CHECK ("id")
);


ALTER TABLE "public"."platform_owner_settings" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_owner_settings"("actor_email" "text", "new_privacy_policy_url" "text", "new_privacy_policy_version" "text", "new_payment_instructions" "text", "new_sender_display_name" "text", "new_reply_to_address" "text", "new_alert_recipient_emails" "text"[]) RETURNS "public"."platform_owner_settings"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  current record;
  before_state jsonb;
  after_state jsonb;
  updated public.platform_owner_settings;
begin
  if actor_email is null or char_length(trim(actor_email)) = 0 then
    raise exception 'An acting owner email is required to update settings.' using errcode = 'check_violation';
  end if;

  insert into public.platform_owner_settings (id)
  values (true)
  on conflict (id) do nothing;

  select privacy_policy_url, privacy_policy_version, payment_instructions,
    sender_display_name, reply_to_address, alert_recipient_emails
  into current
  from public.platform_owner_settings
  where id = true
  for update;

  before_state := jsonb_build_object(
    'privacy_policy_url', current.privacy_policy_url,
    'privacy_policy_version', current.privacy_policy_version,
    'payment_instructions', current.payment_instructions,
    'sender_display_name', current.sender_display_name,
    'reply_to_address', current.reply_to_address,
    'alert_recipient_emails', current.alert_recipient_emails
  );
  after_state := jsonb_build_object(
    'privacy_policy_url', new_privacy_policy_url,
    'privacy_policy_version', new_privacy_policy_version,
    'payment_instructions', new_payment_instructions,
    'sender_display_name', new_sender_display_name,
    'reply_to_address', new_reply_to_address,
    'alert_recipient_emails', new_alert_recipient_emails
  );

  update public.platform_owner_settings
  set privacy_policy_url = new_privacy_policy_url,
    privacy_policy_version = new_privacy_policy_version,
    payment_instructions = new_payment_instructions,
    sender_display_name = new_sender_display_name,
    reply_to_address = new_reply_to_address,
    alert_recipient_emails = new_alert_recipient_emails
  where id = true
  returning * into updated;

  insert into public.platform_owner_audit_events (
    actor_owner_email, event_type, target_type, target_key, before_state, after_state
  ) values (
    actor_email, 'owner_settings.updated', 'platform_owner_settings', 'singleton', before_state, after_state
  );

  return updated;
end;
$$;


ALTER FUNCTION "public"."update_owner_settings"("actor_email" "text", "new_privacy_policy_url" "text", "new_privacy_policy_version" "text", "new_payment_instructions" "text", "new_sender_display_name" "text", "new_reply_to_address" "text", "new_alert_recipient_emails" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_quote_draft"("target_quote_id" "uuid", "expected_revision" integer, "new_title" "text", "new_disclaimer" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  quote_row public.quotes;
  draft_row public.quote_versions;
  clean_title text;
  clean_disclaimer text;
  new_revision integer;
begin
  clean_title := nullif(trim(coalesce(new_title, '')), '');
  if clean_title is null or char_length(clean_title) < 2 or char_length(clean_title) > 160 then
    raise exception 'A quote needs a title between 2 and 160 characters.' using errcode = 'check_violation';
  end if;

  clean_disclaimer := nullif(trim(coalesce(new_disclaimer, '')), '');
  if clean_disclaimer is not null and char_length(clean_disclaimer) > 5000 then
    raise exception 'The contract disclaimer is too long.' using errcode = 'check_violation';
  end if;

  select * into quote_row from public.quotes where id = target_quote_id for update;

  if quote_row.id is null
     or not private.member_has_permission(
       quote_row.organization_id, (select auth.uid()), 'quotes.edit'
     ) then
    raise exception 'You do not have access to change this quote.' using errcode = 'insufficient_privilege';
  end if;

  if quote_row.status <> 'draft' then
    raise exception 'Only a draft quote can be changed.' using errcode = 'check_violation';
  end if;

  select * into draft_row
  from public.quote_versions
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id
    and status = 'draft'
  for update;

  if draft_row.id is null then
    raise exception 'This quote has no draft to change.' using errcode = 'check_violation';
  end if;

  if expected_revision is distinct from draft_row.revision then
    raise exception 'Someone else changed this quote while you were editing. Reload and try again.'
      using errcode = 'P0409';
  end if;

  update public.quote_versions
  set contract_disclaimer = clean_disclaimer, revision = revision + 1
  where id = draft_row.id
  returning revision into new_revision;

  update public.quotes set title = clean_title where id = quote_row.id;

  update public.opportunities
  set title = clean_title
  where organization_id = quote_row.organization_id
    and quote_id = quote_row.id;

  return jsonb_build_object('revision', new_revision, 'title', clean_title);
end;
$$;


ALTER FUNCTION "public"."update_quote_draft"("target_quote_id" "uuid", "expected_revision" integer, "new_title" "text", "new_disclaimer" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_team_member_profile"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "new_full_name" "text", "new_work_phone" "text", "new_job_title" "text", "new_schedule_color" "text", "expected_profile_revision" integer) RETURNS "public"."organization_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  membership public.organization_members;
  current_full_name text;
  clean_full_name text;
  clean_work_phone text;
  clean_job_title text;
  clean_schedule_color text;
  changed_fields text[] := '{}'::text[];
begin
  membership := private.authorize_team_member_command(
    target_organization_id, actor_user_id, target_user_id
  );
  perform private.assert_membership_is_editable(membership);

  if expected_profile_revision is null or expected_profile_revision <> membership.profile_revision then
    raise exception 'Someone else changed this person''s details while you were editing.'
      using errcode = 'P0409';
  end if;

  clean_full_name := nullif(btrim(coalesce(new_full_name, '')), '');
  clean_work_phone := nullif(btrim(coalesce(new_work_phone, '')), '');
  clean_job_title := nullif(btrim(coalesce(new_job_title, '')), '');
  clean_schedule_color := nullif(btrim(coalesce(new_schedule_color, '')), '');

  select profile.full_name into current_full_name
  from public.profiles as profile
  where profile.id = target_user_id;

  if clean_full_name is not null and clean_full_name is distinct from current_full_name then
    if char_length(clean_full_name) > 160 then
      raise exception 'That name is too long.' using errcode = 'check_violation';
    end if;

    update public.profiles as profile
    set full_name = clean_full_name,
        updated_at = now()
    where profile.id = target_user_id;

    changed_fields := changed_fields || 'full_name'::text;
  end if;

  if clean_work_phone is distinct from membership.work_phone then
    changed_fields := changed_fields || 'work_phone'::text;
  end if;

  if clean_job_title is distinct from membership.job_title then
    changed_fields := changed_fields || 'job_title'::text;
  end if;

  if clean_schedule_color is distinct from membership.schedule_color then
    changed_fields := changed_fields || 'schedule_color'::text;
  end if;

  if array_length(changed_fields, 1) is null then
    return membership;
  end if;

  update public.organization_members as membership_row
  set work_phone = clean_work_phone,
      job_title = clean_job_title,
      schedule_color = clean_schedule_color,
      profile_revision = membership_row.profile_revision + 1
  where membership_row.organization_id = target_organization_id
    and membership_row.user_id = target_user_id
  returning * into membership;

  insert into public.organization_member_access_events (
    organization_id, event_type, actor_kind, actor_user_id, subject_user_id, summary
  )
  values (
    target_organization_id, 'member.profile_updated', 'member', actor_user_id, target_user_id,
    jsonb_build_object('changed_fields', to_jsonb(changed_fields))
  );

  return membership;
end;
$$;


ALTER FUNCTION "public"."update_team_member_profile"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "new_full_name" "text", "new_work_phone" "text", "new_job_title" "text", "new_schedule_color" "text", "expected_profile_revision" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_team_member_profile"("target_organization_id" "uuid", "actor_user_id" "uuid", "target_user_id" "uuid", "new_full_name" "text", "new_work_phone" "text", "new_job_title" "text", "new_schedule_color" "text", "expected_profile_revision" integer) IS 'Saves one member''s business details. Work phone, job title and colour belong to this organization; the name belongs to the person, so a null name leaves it untouched instead of erasing it everywhere.';



CREATE OR REPLACE FUNCTION "public"."update_website_chat_widget"("target_organization_id" "uuid", "target_widget_id" "uuid", "expected_revision" integer, "new_name" "text", "new_launcher_position" "text", "new_teaser_text" "text", "new_greeting_text" "text", "new_contact_requirement" "text", "new_availability_visibility_mode" "text", "new_source_label" "text", "new_privacy_policy_url" "text", "new_channel_options" "jsonb", "new_published" boolean, "new_disabled" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  widget_row public.website_chat_widgets;
  clean_name text;
  clean_teaser text;
  clean_greeting text;
  clean_source text;
  clean_privacy text;
  option_count integer;
  option_item jsonb;
  reactivating boolean;
begin
  if not private.has_permission(target_organization_id, 'conversations.manage_connections') then
    raise exception 'You do not have access to manage Website Chat.' using errcode = 'insufficient_privilege';
  end if;

  select * into widget_row
  from public.website_chat_widgets
  where organization_id = target_organization_id and id = target_widget_id
  for update;

  if widget_row.id is null then
    raise exception 'That widget was not found.' using errcode = 'check_violation';
  end if;
  if expected_revision is distinct from widget_row.revision then
    raise exception 'Someone else changed this widget while you were editing. Reload and try again.'
      using errcode = 'serialization_failure';
  end if;

  clean_name := nullif(trim(coalesce(new_name, '')), '');
  if clean_name is null or char_length(clean_name) > 120 then
    raise exception 'Give this widget a name up to 120 characters.' using errcode = 'check_violation';
  end if;
  if new_launcher_position not in ('bottom_left', 'bottom_right') then
    raise exception 'Choose a valid launcher position.' using errcode = 'check_violation';
  end if;
  if new_contact_requirement not in ('phone', 'email', 'either') then
    raise exception 'Choose a valid identity requirement.' using errcode = 'check_violation';
  end if;
  if new_availability_visibility_mode not in ('hidden', 'show_when_available', 'always') then
    raise exception 'Choose a valid availability visibility mode.' using errcode = 'check_violation';
  end if;

  new_channel_options := coalesce(new_channel_options, '[]'::jsonb);
  if jsonb_typeof(new_channel_options) <> 'array' then
    raise exception 'Channel options must be a list.' using errcode = 'check_violation';
  end if;
  option_count := jsonb_array_length(new_channel_options);
  if option_count > 5 then
    raise exception 'Choose at most 5 additional channel options.' using errcode = 'check_violation';
  end if;
  for option_item in select * from jsonb_array_elements(new_channel_options) loop
    if (option_item ->> 'type') not in ('whatsapp', 'messenger') then
      raise exception 'Each channel option needs a valid type.' using errcode = 'check_violation';
    end if;
    if coalesce(trim(option_item ->> 'destination'), '') = '' then
      raise exception 'Each channel option needs a destination.' using errcode = 'check_violation';
    end if;
  end loop;

  clean_teaser := nullif(trim(coalesce(new_teaser_text, '')), '');
  clean_greeting := nullif(trim(coalesce(new_greeting_text, '')), '');
  clean_source := nullif(trim(coalesce(new_source_label, '')), '');
  clean_privacy := private.clean_website_chat_privacy_policy_url(new_privacy_policy_url);

  -- Re-enabling a previously self-disabled widget consumes a slot again, exactly like creating a new one.
  reactivating := widget_row.disabled_at is not null and not coalesce(new_disabled, false);
  if reactivating then
    perform private.assert_website_chat_widget_available(target_organization_id);
  end if;

  update public.website_chat_widgets
  set name = clean_name, launcher_position = new_launcher_position, teaser_text = clean_teaser,
      greeting_text = clean_greeting, contact_requirement = new_contact_requirement,
      availability_visibility_mode = new_availability_visibility_mode, source_label = clean_source,
      privacy_policy_url = clean_privacy,
      channel_options = new_channel_options, published = coalesce(new_published, false),
      disabled_at = case when coalesce(new_disabled, false) then coalesce(disabled_at, now()) else null end,
      revision = revision + 1, updated_by = (select auth.uid()), updated_at = now()
  where id = widget_row.id
  returning * into widget_row;

  return to_jsonb(widget_row);
end;
$$;


ALTER FUNCTION "public"."update_website_chat_widget"("target_organization_id" "uuid", "target_widget_id" "uuid", "expected_revision" integer, "new_name" "text", "new_launcher_position" "text", "new_teaser_text" "text", "new_greeting_text" "text", "new_contact_requirement" "text", "new_availability_visibility_mode" "text", "new_source_label" "text", "new_privacy_policy_url" "text", "new_channel_options" "jsonb", "new_published" boolean, "new_disabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."visit_checklist_rows"("target_organization_id" "uuid", "target_visit_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  visit public.job_visits;
  checklists jsonb;
  outstanding integer;
begin
  if caller is null then
    raise exception 'You must be signed in to view this visit.' using errcode = 'insufficient_privilege';
  end if;

  select job_visit.* into visit
  from public.job_visits as job_visit
  where job_visit.organization_id = target_organization_id and job_visit.id = target_visit_id;
  if not found then
    raise exception 'That visit could not be found.' using errcode = 'P0404';
  end if;
  if not private.can_view_visit(target_organization_id, target_visit_id) then
    raise exception 'You do not have access to this visit.' using errcode = 'insufficient_privilege';
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', checklist.id,
          'name', checklist.name,
          'items', coalesce(questions.items, '[]'::jsonb)
        )
        order by checklist.attached_at
      ),
      '[]'::jsonb
    ),
    coalesce(sum(questions.outstanding), 0)
  into checklists, outstanding
  from public.job_checklists as checklist
  left join lateral (
    select
      jsonb_agg(
        jsonb_build_object(
          'id', item.id,
          'position', item.position,
          'label', item.label,
          'item_type', item.item_type,
          'required', item.required,
          'options', coalesce(to_jsonb(item.options), 'null'::jsonb),
          'value', coalesce(answer.value, 'null'::jsonb),
          'answered_at', answer.answered_at,
          'answered_by', answer.answered_by
        )
        order by item.position
      ) as items,
      count(*) filter (
        where item.required
          and not private.checklist_answer_is_complete(item.item_type, answer.value)
      ) as outstanding
    from public.job_checklist_items as item
    left join public.visit_checklist_answers as answer
      on answer.visit_id = target_visit_id and answer.item_id = item.id
    where item.organization_id = checklist.organization_id and item.job_checklist_id = checklist.id
  ) as questions on true
  where checklist.organization_id = target_organization_id
    and checklist.job_id = visit.job_id
    and (visit.completed_at is null or visit.completed_at >= checklist.attached_at);

  return jsonb_build_object(
    'checklists', checklists,
    'outstanding_required', outstanding,
    'can_answer', private.member_has_permission(target_organization_id, caller, 'field_records.record')
      or private.member_has_permission(target_organization_id, caller, 'field_records.manage_team')
  );
end;
$$;


ALTER FUNCTION "public"."visit_checklist_rows"("target_organization_id" "uuid", "target_visit_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."visit_checklist_rows"("target_organization_id" "uuid", "target_visit_id" "uuid") IS 'One visit''s checklists with its own answers, plus how many required questions are still blank.';



CREATE OR REPLACE FUNCTION "public"."visit_line_money"("target_visit_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  org uuid;
  visit_job uuid;
  can_price boolean;
  can_cost boolean;
  answer jsonb;
begin
  select visit.organization_id, visit.job_id into org, visit_job
  from public.job_visits as visit
  where visit.id = target_visit_id;

  if org is null then
    return '{}'::jsonb;
  end if;

  if not private.member_job_is_visible(org, caller, visit_job) then
    raise exception 'You do not have access to this visit.' using errcode = 'insufficient_privilege';
  end if;

  can_price := private.member_has_permission(org, caller, 'jobs.view_price');
  can_cost := private.member_has_permission(org, caller, 'jobs.view_cost');
  if not can_price and not can_cost then
    return '{}'::jsonb;
  end if;

  select coalesce(jsonb_object_agg(item.id::text,
      (case when can_price then jsonb_build_object(
         'unit_price_minor', item.unit_price_minor,
         'line_total_minor', item.line_total_minor
       ) else '{}'::jsonb end)
      ||
      (case when can_cost then jsonb_build_object(
         'unit_cost_minor', item.unit_cost_minor,
         'line_cost_total_minor', item.line_cost_total_minor
       ) else '{}'::jsonb end)
    ), '{}'::jsonb)
  into answer
  from public.job_visit_line_items as item
  where item.organization_id = org
    and item.visit_id = target_visit_id;

  return answer;
end;
$$;


ALTER FUNCTION "public"."visit_line_money"("target_visit_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."visit_line_money"("target_visit_id" "uuid") IS 'Money for one visit''s own lines, keyed by line id. Prices need jobs.view_price and cost needs jobs.view_cost; a reader holding neither gets an empty object.';



CREATE OR REPLACE FUNCTION "public"."void_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_reason" "text", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  invoice_row public.invoices;
  ordinary_minor bigint;
  remaining_minor bigint;
  deposit_entry public.invoice_payment_allocations;
  released_minor bigint := 0;
  released_count integer := 0;
begin
  if caller is null then
    raise exception 'You must be signed in to void an invoice.' using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.void') then
    raise exception 'You do not have access to void invoices here.'
      using errcode = 'insufficient_privilege';
  end if;
  -- Whether this bill may be voided depends on what is sitting on it, so price visibility is part of the
  -- decision rather than only part of the display.
  perform private.require_invoice_price_access(target_organization_id);

  if new_reason is null
     or new_reason not in ('duplicate', 'created_in_error', 'client_request', 'other') then
    raise exception 'A void needs one of the four reasons.' using errcode = 'check_violation';
  end if;

  replayed := private.begin_invoice_command(
    target_organization_id, 'void_invoice', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  -- Already-voided is refused inside the lock helper, in the words the customer-facing product uses.
  invoice_row := private.lock_invoice_for_payment(target_organization_id, target_invoice_id);

  if invoice_row.issued_at is null and invoice_row.recognized_at is null then
    raise exception 'A draft is deleted rather than voided.' using errcode = 'check_violation';
  end if;
  if invoice_row.replaced_at is not null then
    raise exception 'That bill has already been replaced, so it is history rather than an open bill.'
      using errcode = 'check_violation';
  end if;
  if invoice_row.written_off_at is not null then
    raise exception 'Undo the write-off before voiding this bill.' using errcode = 'check_violation';
  end if;
  if invoice_row.marked_received_at is not null then
    raise exception 'Reopen this bill before voiding it.' using errcode = 'check_violation';
  end if;

  -- The contract's progress-invoice exclusion, real at last. 3b-2 could only leave this implied, because no
  -- installment claim existed for it to test. An installment's amount is fixed by the job's payment
  -- schedule, so cancelling one bill of that schedule outright would leave the schedule describing money
  -- nobody is being asked for; the correction chain replaces it instead, preserving the amount.
  if exists (
    select 1 from public.invoice_sources as claim
    where claim.organization_id = target_organization_id
      and claim.root_invoice_id = invoice_row.root_invoice_id
      and claim.source_kind = 'installment'
  ) then
    raise exception 'A progress invoice is corrected rather than voided.' using errcode = 'check_violation',
      hint = 'Prepare a correction: it keeps the payment schedule intact and replaces this bill.';
  end if;

  -- D2: ordinary money only. Deposits are counted separately because they are the one thing void resolves
  -- on the user's behalf.
  select coalesce(sum(case when entry.entry_type = 'applied'
    then entry.amount_minor else -entry.amount_minor end), 0)::bigint
  into ordinary_minor
  from public.invoice_payment_allocations as entry
  where entry.organization_id = target_organization_id
    and entry.invoice_id = invoice_row.id
    and entry.payment_event_id is not null;

  if ordinary_minor > 0 then
    raise exception 'This bill still has payments on it, so it cannot be voided yet.'
      using errcode = 'check_violation',
      detail = format('%s still applied to invoice #%s', ordinary_minor, invoice_row.invoice_number),
      hint = 'Take the payment back to client credit, move it to another invoice, or refund it first.';
  end if;

  remaining_minor := invoice_row.total_minor
    - private.invoice_allocated_minor(target_organization_id, invoice_row.id);
  if remaining_minor <= 0 then
    raise exception 'This bill is fully paid, so it cannot be voided.' using errcode = 'check_violation',
      hint = 'Take the money off it first if this bill should not have existed.';
  end if;

  -- The approved deposit release, in the same transaction as the void itself. Each live application gets
  -- the same retained unapplication an explicit unapply would have written.
  for deposit_entry in
    select entry.*
    from public.invoice_payment_allocations as entry
    where entry.organization_id = target_organization_id
      and entry.invoice_id = invoice_row.id
      and entry.entry_type = 'applied'
      and entry.deposit_event_id is not null
      and not exists (
        select 1 from public.invoice_payment_allocations as undone
        where undone.organization_id = entry.organization_id
          and undone.reversed_allocation_id = entry.id
      )
    order by entry.id
  loop
    perform private.reverse_invoice_allocation(
      invoice_row, deposit_entry, caller, 'Released because the invoice was voided'
    );
    released_minor := released_minor + deposit_entry.amount_minor;
    released_count := released_count + 1;
  end loop;

  update public.invoices
  set voided_at = now(),
      voided_by = caller,
      void_reason = new_reason,
      void_note = nullif(trim(coalesce(new_note, '')), ''),
      revision = invoice_row.revision + 1,
      updated_at = now()
  where organization_id = target_organization_id and id = invoice_row.id;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.voided', caller, invoice_row.revision + 1, new_note,
    jsonb_build_object(
      'reason', new_reason,
      'released_deposit_count', released_count,
      'released_deposit_minor', released_minor
    ),
    true, null
  );

  -- The cancellation notice to the client is a Communications send, queued after the state is secured. That
  -- seam belongs to Part 6 with the rest of invoice delivery; nothing is sent from inside these locks.
  return private.complete_invoice_command(
    target_organization_id, 'void_invoice', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', invoice_row.id,
      'invoice_number', invoice_row.invoice_number,
      'client_id', invoice_row.client_id,
      'reason', new_reason,
      'released_deposit_count', released_count,
      'released_deposit_minor', released_minor
    )
  );
end;
$$;


ALTER FUNCTION "public"."void_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_reason" "text", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."void_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_reason" "text", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Cancels an issued bill for good, keeping it and its reason forever. Refuses while ordinary payments are still applied to it and for progress invoices, which are corrected instead, and releases any quote deposits back to client credit in the same transaction.';



CREATE OR REPLACE FUNCTION "public"."withdraw_communication_email_suppression_removal"("p_organization_id" "uuid", "p_suppression_id" "uuid", "p_actor_user_id" "uuid", "p_actor_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor_email text := lower(btrim(coalesce(p_actor_email, '')));
  open_request public.communication_email_suppression_removal_requests%rowtype;
begin
  if char_length(actor_email) not between 3 and 320 then
    raise exception 'An administrator email is required.' using errcode = 'check_violation';
  end if;

  select * into open_request
  from public.communication_email_suppression_removal_requests
  where suppression_id = p_suppression_id
    and organization_id = p_organization_id
    and status = 'pending'
  for update;

  if not found then
    raise exception 'There is no open removal request for that address.'
      using errcode = 'no_data_found';
  end if;

  update public.communication_email_suppression_removal_requests
  set status = 'withdrawn',
    decided_by_kind = 'organization_admin',
    decided_by_user_id = p_actor_user_id,
    decided_by_email = actor_email,
    decided_at = now()
  where id = open_request.id;

  return public.communication_email_suppression_removal_request_json(open_request.id);
end;
$$;


ALTER FUNCTION "public"."withdraw_communication_email_suppression_removal"("p_organization_id" "uuid", "p_suppression_id" "uuid", "p_actor_user_id" "uuid", "p_actor_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."write_off_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  caller uuid := (select auth.uid());
  replayed jsonb;
  invoice_row public.invoices;
  remaining_minor bigint;
begin
  if caller is null then
    raise exception 'You must be signed in to write off a balance.'
      using errcode = 'insufficient_privilege';
  end if;
  if not private.member_has_permission(target_organization_id, caller, 'invoices.bad_debt') then
    raise exception 'You do not have access to write off balances here.'
      using errcode = 'insufficient_privilege';
  end if;
  perform private.require_invoice_price_access(target_organization_id);

  replayed := private.begin_invoice_command(
    target_organization_id, 'write_off_invoice', new_idempotency_key, new_request_hash, caller
  );
  if replayed is not null then
    return replayed;
  end if;

  invoice_row := private.lock_invoice_for_payment(target_organization_id, target_invoice_id);

  if invoice_row.issued_at is null and invoice_row.recognized_at is null then
    raise exception 'Only a bill the client has been given can be written off.'
      using errcode = 'check_violation';
  end if;
  if invoice_row.replaced_at is not null then
    raise exception 'That bill has already been replaced, so it is history rather than an open bill.'
      using errcode = 'check_violation';
  end if;
  if invoice_row.written_off_at is not null then
    raise exception 'This balance is already written off.' using errcode = 'check_violation';
  end if;
  -- The two closures make different financial statements. A bill cannot say both.
  if invoice_row.marked_received_at is not null then
    raise exception 'This bill is already closed as received. Reopen it before writing it off.'
      using errcode = 'check_violation';
  end if;

  remaining_minor := invoice_row.total_minor
    - private.invoice_allocated_minor(target_organization_id, invoice_row.id);
  if remaining_minor <= 0 then
    raise exception 'There is nothing left on this bill to write off.' using errcode = 'check_violation';
  end if;

  update public.invoices
  set written_off_at = now(),
      written_off_by = caller,
      write_off_note = nullif(trim(coalesce(new_note, '')), ''),
      revision = invoice_row.revision + 1,
      updated_at = now()
  where organization_id = target_organization_id and id = invoice_row.id;

  perform private.record_invoice_event(
    target_organization_id, invoice_row.id, invoice_row.invoice_number, invoice_row.client_id,
    'invoice.written_off', caller, invoice_row.revision + 1, new_note,
    jsonb_build_object('written_off_minor', remaining_minor), true, null
  );

  return private.complete_invoice_command(
    target_organization_id, 'write_off_invoice', new_idempotency_key,
    jsonb_build_object(
      'invoice_id', invoice_row.id,
      'invoice_number', invoice_row.invoice_number,
      'client_id', invoice_row.client_id,
      'written_off_minor', remaining_minor
    )
  );
end;
$$;


ALTER FUNCTION "public"."write_off_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."write_off_invoice"("target_organization_id" "uuid", "target_invoice_id" "uuid", "new_note" "text", "new_idempotency_key" "text", "new_request_hash" "text") IS 'Writes off the remaining balance of a bill that will not be collected. The bill and its payments stay exactly as they were; it simply stops counting as money the client owes.';



CREATE TABLE IF NOT EXISTS "private"."automation_enrollments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "recipe_id" "uuid" NOT NULL,
    "recipe_version_id" "uuid" NOT NULL,
    "subject_type" "text" NOT NULL,
    "subject_id" "uuid" NOT NULL,
    "trigger_event_id" "uuid",
    "source" "text" DEFAULT 'event'::"text" NOT NULL,
    "state" "text" DEFAULT 'active'::"text" NOT NULL,
    "current_step_index" integer DEFAULT 0 NOT NULL,
    "re_entry_key" "text" NOT NULL,
    "context" "jsonb" NOT NULL,
    "customer_messages_sent" integer DEFAULT 0 NOT NULL,
    "expires_at" timestamp with time zone,
    "stop_reason" "text",
    "stopped_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "enrolled_by" "uuid",
    "paused_work_due_at" timestamp with time zone,
    "compacted_at" timestamp with time zone,
    "anchor_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "customer_reply_after" timestamp with time zone,
    "paused_reason" "text",
    CONSTRAINT "automation_enrollments_current_step_index_check" CHECK (("current_step_index" >= 0)),
    CONSTRAINT "automation_enrollments_customer_messages_sent_check" CHECK (("customer_messages_sent" >= 0)),
    CONSTRAINT "automation_enrollments_paused_reason_check" CHECK (("paused_reason" = ANY (ARRAY['staff'::"text", 'customer_reply'::"text"]))),
    CONSTRAINT "automation_enrollments_re_entry_key_check" CHECK ((("char_length"("re_entry_key") >= 1) AND ("char_length"("re_entry_key") <= 200))),
    CONSTRAINT "automation_enrollments_source_check" CHECK (("source" = ANY (ARRAY['event'::"text", 'manual'::"text"]))),
    CONSTRAINT "automation_enrollments_source_evidence_ck" CHECK ((("compacted_at" IS NOT NULL) OR (("source" = 'event'::"text") = ("trigger_event_id" IS NOT NULL)))),
    CONSTRAINT "automation_enrollments_state_check" CHECK (("state" = ANY (ARRAY['active'::"text", 'paused'::"text", 'completed'::"text", 'stopped'::"text", 'failed'::"text"]))),
    CONSTRAINT "automation_enrollments_subject_type_check" CHECK (("subject_type" = ANY (ARRAY['quote'::"text", 'form_submission'::"text", 'website_chat_session'::"text"])))
);


ALTER TABLE "private"."automation_enrollments" OWNER TO "postgres";


COMMENT ON TABLE "private"."automation_enrollments" IS 'One subject executing one frozen recipe version. Pinned to its version and to send-time identity; all consent, status, and recipient truth is re-read from the owning domain before any effect.';



COMMENT ON COLUMN "private"."automation_enrollments"."enrolled_by" IS 'The user who manually enrolled this subject. Null for automatic (event-sourced) enrollments.';



COMMENT ON COLUMN "private"."automation_enrollments"."paused_work_due_at" IS 'While paused, the absolute due_at of the work item that pause cancelled. Resume re-creates the item at this time so pausing never delays a reminder. Null when active or when no step was pending at pause.';



COMMENT ON COLUMN "private"."automation_enrollments"."compacted_at" IS 'Set when retention stripped this terminal enrollment to a tombstone: context, enrolled_by, and trigger_event_id are cleared, but recipe_id + re_entry_key stay so re-enrollment is still blocked. Null for every live or un-compacted enrollment.';



COMMENT ON COLUMN "private"."automation_enrollments"."anchor_at" IS 'The original send this enrollment schedules against: the trigger event''s occurred_at, or creation time for a manual enrollment. Every wait is measured from here, so worker lateness never shifts a reminder.';



COMMENT ON COLUMN "private"."automation_enrollments"."customer_reply_after" IS 'Customer messages created after this moment count as a reply that pauses customer-facing steps. Null until the enrollment first reaches the customer. A reply-pause moves it to that reply, so Resume is not undone by the same reply.';



COMMENT ON COLUMN "private"."automation_enrollments"."paused_reason" IS 'Set while paused: customer_reply when a customer reply paused it (customer_reply_after moved), otherwise staff. Cleared when the enrollment leaves paused. Maintained by a trigger.';



CREATE TABLE IF NOT EXISTS "private"."automation_event_matches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "event_id" "uuid" NOT NULL,
