);


ALTER TABLE "private"."automation_event_matches" OWNER TO "postgres";


COMMENT ON TABLE "private"."automation_event_matches" IS 'One row per (event, active recipe): enrolled, or the plain reason it did not.';



CREATE TABLE IF NOT EXISTS "private"."automation_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "seq" bigint NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "payload_schema_version" integer DEFAULT 1 NOT NULL,
    "subject_type" "text" NOT NULL,
    "subject_id" "uuid" NOT NULL,
    "payload" "jsonb" NOT NULL,
    "occurred_at" timestamp with time zone NOT NULL,
    "source_module" "text" NOT NULL,
    "source_event_id" "uuid" NOT NULL,
    "created_xid" "xid8" DEFAULT "pg_current_xact_id"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "processed_at" timestamp with time zone,
    "processing_attempts" integer DEFAULT 0 NOT NULL,
    "processing_error" "text",
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "automation_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['quote.delivery_succeeded'::"text", 'website_inquiry.received'::"text"]))),
