    CONSTRAINT "automation_events_processing_attempts_check" CHECK (("processing_attempts" >= 0)),
    CONSTRAINT "automation_events_source_module_check" CHECK (("source_module" = ANY (ARRAY['communications'::"text", 'forms'::"text", 'website_chat'::"text"]))),
    CONSTRAINT "automation_events_subject_type_check" CHECK (("subject_type" = ANY (ARRAY['quote'::"text", 'form_submission'::"text", 'website_chat_session'::"text"])))
);


ALTER TABLE "private"."automation_events" OWNER TO "postgres";


COMMENT ON TABLE "private"."automation_events" IS 'Durable domain events for Automation, written in the same transaction as the fact that caused them. Internal: no contractor read path.';



COMMENT ON COLUMN "private"."automation_events"."available_at" IS 'When this event may next be claimed. Pushed out by intake backoff after a failed attempt; equal to creation time otherwise.';



ALTER TABLE "private"."automation_events" ALTER COLUMN "seq" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "private"."automation_events_seq_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "private"."automation_sms_email_fallbacks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "enrollment_id" "uuid" NOT NULL,
    "step_index" integer NOT NULL,
    "sms_delivery_intent_id" "uuid" NOT NULL,
    "email_delivery_intent_id" "uuid",
