    "sms_failure" "text",
    "reason" "text",
    "attempts" integer DEFAULT 0 NOT NULL,
    "available_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "automation_sms_email_fallbacks_attempts_check" CHECK (("attempts" >= 0)),
    CONSTRAINT "automation_sms_email_fallbacks_state_check" CHECK (("state" = ANY (ARRAY['watching'::"text", 'due'::"text", 'sent'::"text", 'not_needed'::"text", 'skipped'::"text"]))),
    CONSTRAINT "automation_sms_email_fallbacks_step_index_check" CHECK (("step_index" >= 0))
);


ALTER TABLE "private"."automation_sms_email_fallbacks" OWNER TO "postgres";


COMMENT ON TABLE "private"."automation_sms_email_fallbacks" IS 'One row per text a website-inquiry customer-message step sent. A provider-reported failure makes the email fallback due; delivered or any other outcome closes it. Written only by automation functions and the SMS intent outcome trigger.';



CREATE TABLE IF NOT EXISTS "private"."automation_work_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "enrollment_id" "uuid" NOT NULL,
    "step_index" integer NOT NULL,
    "due_at" timestamp with time zone NOT NULL,
    "state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claim_token" "uuid",
    "claimed_at" timestamp with time zone,
    "claimed_by" "text",
    "attempts" integer DEFAULT 0 NOT NULL,
    "last_error_code" "text",
    "last_error_message" "text",
    "attention_reason" "text",
    "attention_at" timestamp with time zone,
    CONSTRAINT "automation_work_items_attempts_check" CHECK (("attempts" >= 0)),
    CONSTRAINT "automation_work_items_attention_check" CHECK (((("state" = 'needs_attention'::"text") AND ("attention_reason" IS NOT NULL) AND ("attention_at" IS NOT NULL)) OR (("state" <> 'needs_attention'::"text") AND ("attention_reason" IS NULL) AND ("attention_at" IS NULL)))),
    CONSTRAINT "automation_work_items_attention_reason_check" CHECK ((("attention_reason" IS NULL) OR (("char_length"("attention_reason") >= 1) AND ("char_length"("attention_reason") <= 100)))),
    CONSTRAINT "automation_work_items_claimed_by_check" CHECK ((("claimed_by" IS NULL) OR (("char_length"("claimed_by") >= 1) AND ("char_length"("claimed_by") <= 100)))),
    CONSTRAINT "automation_work_items_last_error_code_check" CHECK ((("last_error_code" IS NULL) OR ("char_length"("last_error_code") <= 100))),
    CONSTRAINT "automation_work_items_last_error_message_check" CHECK ((("last_error_message" IS NULL) OR ("char_length"("last_error_message") <= 1000))),
    CONSTRAINT "automation_work_items_state_check" CHECK (("state" = ANY (ARRAY['pending'::"text", 'done'::"text", 'cancelled'::"text", 'needs_attention'::"text"]))),
    CONSTRAINT "automation_work_items_step_index_check" CHECK (("step_index" >= 0))
);


ALTER TABLE "private"."automation_work_items" OWNER TO "postgres";


COMMENT ON TABLE "private"."automation_work_items" IS 'The single next due transition per enrollment. 6D-2 adds claim leases, attempts, and recovery columns.';



COMMENT ON COLUMN "private"."automation_work_items"."available_at" IS 'When this row may next be claimed. The claim sets it to the lease expiry, so a claimed row is simply not due and an abandoned claim recovers on its own with no quarantine sweep.';



COMMENT ON COLUMN "private"."automation_work_items"."attempts" IS 'Incremented by the claim, not by the outcome, so a worker that dies mid-step still counts its attempt and a crash loop reaches the dead-letter cap instead of spinning forever.';



