    "answers" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "photo_object_keys" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "selected_catalog_item_id" "uuid",
    "requested_starts_at" timestamp with time zone,
    "requested_ends_at" timestamp with time zone,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "processing_error" "text",
    "processed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "assigned_user_id" "uuid",
    "booking_reservation_id" "uuid",
    "result" "jsonb",
    CONSTRAINT "form_submissions_booking_pair" CHECK ((("requested_starts_at" IS NULL) = ("requested_ends_at" IS NULL))),
    CONSTRAINT "form_submissions_booking_time_order" CHECK ((("requested_ends_at" IS NULL) OR ("requested_ends_at" > "requested_starts_at"))),
    CONSTRAINT "form_submissions_idempotency_key_check" CHECK ((("char_length"("idempotency_key") >= 1) AND ("char_length"("idempotency_key") <= 200))),
    CONSTRAINT "form_submissions_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processed'::"text", 'failed'::"text"])))
);


ALTER TABLE "private"."form_submissions" OWNER TO "postgres";


COMMENT ON TABLE "private"."form_submissions" IS 'Raw, safely-received public form answers, held for Part 4D to turn into a Lead/Request/Job. Written only by submit_form_response.';



COMMENT ON COLUMN "private"."form_submissions"."assigned_user_id" IS 'The team member whose calendar submit_form_response reserved for this exact slot. Null for a request-only form and for an approval-gated assessment, where nothing is reserved until staff acts.';



COMMENT ON COLUMN "private"."form_submissions"."booking_reservation_id" IS 'The private.form_booking_reservations row submit_form_response claimed at submit time, carried forward so the worker never re-derives or re-claims it.';



COMMENT ON COLUMN "private"."form_submissions"."result" IS 'Filled once processed: which client/property/request/assessment/job/visit this submission became, for support and debugging traceability back from one submission to its records.';



