CREATE TABLE IF NOT EXISTS "public"."automation_recipes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "source" "text" NOT NULL,
    "preset_key" "text",
    "preset_version" integer,
    "active_trigger_key" "text",
    "draft_definition" "jsonb",
    "draft_revision" integer DEFAULT 1 NOT NULL,
    "draft_updated_by" "uuid",
    "draft_updated_at" timestamp with time zone,
    "current_version_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "automation_recipes_active_trigger_check" CHECK (((("current_version_id" IS NULL) AND ("active_trigger_key" IS NULL)) OR (("current_version_id" IS NOT NULL) AND ("active_trigger_key" IS NOT NULL)))),
    CONSTRAINT "automation_recipes_draft_revision_check" CHECK (("draft_revision" >= 1)),
    CONSTRAINT "automation_recipes_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "name")) <= 120))),
    CONSTRAINT "automation_recipes_preset_key_check" CHECK ((("preset_key" IS NULL) OR (("char_length"(TRIM(BOTH FROM "preset_key")) >= 1) AND ("char_length"(TRIM(BOTH FROM "preset_key")) <= 120)))),
    CONSTRAINT "automation_recipes_preset_version_check" CHECK ((("preset_version" IS NULL) OR ("preset_version" >= 1))),
    CONSTRAINT "automation_recipes_source_check" CHECK (("source" = ANY (ARRAY['preset'::"text", 'custom'::"text"]))),
    CONSTRAINT "automation_recipes_source_preset_check" CHECK (((("source" = 'custom'::"text") AND ("preset_key" IS NULL) AND ("preset_version" IS NULL)) OR (("source" = 'preset'::"text") AND ("preset_key" IS NOT NULL) AND ("preset_version" IS NOT NULL)))),
    CONSTRAINT "automation_recipes_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'paused'::"text", 'archived'::"text"]))),
    CONSTRAINT "automation_recipes_status_version_check" CHECK (((("status" = 'draft'::"text") AND ("current_version_id" IS NULL) AND ("draft_definition" IS NOT NULL)) OR (("status" = 'active'::"text") AND ("current_version_id" IS NOT NULL)) OR (("status" = 'paused'::"text") AND ("current_version_id" IS NOT NULL)) OR ("status" = 'archived'::"text")))
);


ALTER TABLE "public"."automation_recipes" OWNER TO "postgres";


COMMENT ON TABLE "public"."automation_recipes" IS 'One automation recipe per row. Mutable draft buffer here; frozen versions in automation_recipe_versions. See docs/automation-behavior-contract.md § Recipe definition and lifecycle.';



CREATE TABLE IF NOT EXISTS "public"."catalog_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "category" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "unit_label" "text",
    "unit_price_minor" bigint DEFAULT 0 NOT NULL,
    "unit_cost_minor" bigint DEFAULT 0 NOT NULL,
    "is_taxable" boolean DEFAULT true NOT NULL,
    "is_labor" boolean DEFAULT false NOT NULL,
    "archived_at" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "revision" integer DEFAULT 1 NOT NULL,
    "updated_by" "uuid",
    CONSTRAINT "catalog_items_category_check" CHECK (("category" = ANY (ARRAY['product'::"text", 'service'::"text"]))),
    CONSTRAINT "catalog_items_description_check" CHECK ((("description" IS NULL) OR ("char_length"("description") <= 2000))),
    CONSTRAINT "catalog_items_labor_is_service" CHECK (((NOT "is_labor") OR ("category" = 'service'::"text"))),
    CONSTRAINT "catalog_items_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "name")) >= 2) AND ("char_length"(TRIM(BOTH FROM "name")) <= 160))),
    CONSTRAINT "catalog_items_unit_cost_minor_check" CHECK ((("unit_cost_minor" >= 0) AND ("unit_cost_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "catalog_items_unit_label_check" CHECK ((("unit_label" IS NULL) OR (("char_length"(TRIM(BOTH FROM "unit_label")) >= 1) AND ("char_length"(TRIM(BOTH FROM "unit_label")) <= 24)))),
    CONSTRAINT "catalog_items_unit_price_minor_check" CHECK ((("unit_price_minor" >= 0) AND ("unit_price_minor" <= '1000000000000'::bigint)))
);


ALTER TABLE "public"."catalog_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalog_items" IS 'Organization-owned reusable product and service defaults. Never history: a change here affects the next line added and never rewrites a request pricing row or a quote version line already written.';



COMMENT ON COLUMN "public"."catalog_items"."revision" IS 'Bumped once by every accepted update_catalog_item or delete_catalog_item call. A stale expected_revision is refused so two Settings managers editing the same item cannot silently overwrite or resurrect it.';



