);


ALTER TABLE "public"."client_communication_preferences" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."client_contact_methods" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "client_contact_id" "uuid",
    "kind" "text" NOT NULL,
    "value" "text" NOT NULL,
    "normalized_value" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("kind" = 'email'::"text") THEN "lower"(TRIM(BOTH FROM "value"))
    ELSE "regexp_replace"("value", '[^0-9]'::"text", ''::"text", 'g'::"text")
END) STORED NOT NULL,
    "label" "text",
    "is_primary" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "client_contact_methods_kind_check" CHECK (("kind" = ANY (ARRAY['email'::"text", 'phone'::"text"]))),
    CONSTRAINT "client_contact_methods_label_check" CHECK ((("label" IS NULL) OR (("char_length"(TRIM(BOTH FROM "label")) >= 1) AND ("char_length"(TRIM(BOTH FROM "label")) <= 40)))),
    CONSTRAINT "client_contact_methods_value_check" CHECK ((("char_length"(TRIM(BOTH FROM "value")) >= 3) AND ("char_length"(TRIM(BOTH FROM "value")) <= 254)))
);


ALTER TABLE "public"."client_contact_methods" OWNER TO "postgres";


