    CONSTRAINT "client_marketing_consent_events_evidence_check" CHECK (("jsonb_typeof"("evidence") = 'object'::"text")),
    CONSTRAINT "client_marketing_consent_events_kind_check" CHECK (("event_kind" = ANY (ARRAY['opt_in'::"text", 'opt_out'::"text"]))),
