);


ALTER TABLE "public"."client_marketing_consent_state" OWNER TO "postgres";


COMMENT ON TABLE "public"."client_marketing_consent_state" IS 'Current marketing-email consent per email contact method, projected from client_marketing_consent_events. Marketing eligibility reads this; a method with no row is not consented.';



CREATE TABLE IF NOT EXISTS "public"."client_marketing_unsubscribe_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "client_contact_method_id" "uuid" NOT NULL,
    "token_hash" "bytea" NOT NULL,
    "issued_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "client_marketing_unsubscribe_links_token_hash_check" CHECK (("octet_length"("token_hash") = 32))
);


ALTER TABLE "public"."client_marketing_unsubscribe_links" OWNER TO "postgres";


COMMENT ON TABLE "public"."client_marketing_unsubscribe_links" IS 'One marketing-email unsubscribe link, scoped to an organization and one email contact method. Stores only the token hash; the raw token exists solely in the URL placed in the email. Service role only — members never read this table, because every row is a credential.';



COMMENT ON COLUMN "public"."client_marketing_unsubscribe_links"."token_hash" IS 'SHA-256 of the raw token, computed by the server. The database never sees the token itself.';



CREATE TABLE IF NOT EXISTS "public"."client_opening_balances" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
