    "balance_type" "text" NOT NULL,
    "amount_minor" bigint NOT NULL,
    "currency_code" "text" NOT NULL,
    "as_of_date" "date" NOT NULL,
    "source_note" "text",
    "predecessor_opening_balance_id" "uuid",
    "root_opening_balance_id" "uuid" NOT NULL,
    "replaced_at" timestamp with time zone,
    "replaced_by_opening_balance_id" "uuid",
    "import_batch_id" "uuid" NOT NULL,
    "import_row_id" "uuid" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "client_opening_balances_amount_minor_check" CHECK (("amount_minor" > 0)),
    CONSTRAINT "client_opening_balances_balance_type_check" CHECK (("balance_type" = ANY (ARRAY['receivable'::"text", 'credit'::"text"]))),
    CONSTRAINT "client_opening_balances_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "client_opening_balances_predecessor_not_self" CHECK ((("predecessor_opening_balance_id" IS NULL) OR ("predecessor_opening_balance_id" <> "id"))),
    CONSTRAINT "client_opening_balances_replaced_facts_complete" CHECK ((("replaced_at" IS NULL) = ("replaced_by_opening_balance_id" IS NULL))),
    CONSTRAINT "client_opening_balances_source_note_check" CHECK ((("source_note" IS NULL) OR ("char_length"("source_note") <= 500)))
);


ALTER TABLE "public"."client_opening_balances" OWNER TO "postgres";


COMMENT ON TABLE "public"."client_opening_balances" IS 'The two opening facts assisted import may record for a Client: receivable or unused credit, as of a date. Members read this table and never write it; every row is created only by the assisted-import worker. A correction appends a new fact and marks the one it replaces, so history is never edited or deleted.';



COMMENT ON COLUMN "public"."client_opening_balances"."root_opening_balance_id" IS 'The first fact in this correction chain, set to the fact''s own id when it starts one.';



COMMENT ON COLUMN "public"."client_opening_balances"."replaced_at" IS 'When a correction superseded this fact. A replaced fact stays in reconciliation history but is excluded from the Client''s current opening balance.';



