    CONSTRAINT "communication_email_domains_dmarc_status_check" CHECK (("dmarc_status" = ANY (ARRAY['unchecked'::"text", 'pending'::"text", 'passing'::"text", 'failing'::"text"]))),
    CONSTRAINT "communication_email_domains_dns_records_check" CHECK (("jsonb_typeof"("dns_records") = 'array'::"text")),
    CONSTRAINT "communication_email_domains_dns_zone_check" CHECK ((("dns_zone" IS NULL) OR (("dns_zone" = "lower"("btrim"("dns_zone"))) AND (("char_length"("dns_zone") >= 4) AND ("char_length"("dns_zone") <= 253)) AND ("dns_zone" ~ '^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$'::"text")))),
    CONSTRAINT "communication_email_domains_domain_name_check" CHECK ((("domain_name" = "lower"("btrim"("domain_name"))) AND (("char_length"("domain_name") >= 4) AND ("char_length"("domain_name") <= 253)) AND ("domain_name" ~ '^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$'::"text"))),
    CONSTRAINT "communication_email_domains_inbound_mx_status_check" CHECK (("inbound_mx_status" = ANY (ARRAY['unchecked'::"text", 'pending'::"text", 'passing'::"text", 'failing'::"text"]))),
    CONSTRAINT "communication_email_domains_inbound_webhook_purpose_check" CHECK ((("provider_inbound_webhook_id" IS NULL) OR ("purpose" = 'receiving'::"text"))),
    CONSTRAINT "communication_email_domains_lifecycle_state_check" CHECK (("lifecycle_state" = ANY (ARRAY['pending_dns'::"text", 'verified'::"text", 'unhealthy'::"text", 'transitioning'::"text", 'removal_pending'::"text", 'removed'::"text"]))),
    CONSTRAINT "communication_email_domains_ownership_status_check" CHECK (("ownership_status" = ANY (ARRAY['unchecked'::"text", 'pending'::"text", 'passing'::"text", 'failing'::"text"]))),
    CONSTRAINT "communication_email_domains_provider_check" CHECK (("provider" = 'brevo'::"text")),
    CONSTRAINT "communication_email_domains_purpose_check" CHECK (("purpose" = ANY (ARRAY['sending'::"text", 'receiving'::"text"]))),
    CONSTRAINT "communication_email_domains_purpose_health_check" CHECK (((("purpose" = 'sending'::"text") AND ("inbound_mx_status" = 'unchecked'::"text")) OR (("purpose" = 'receiving'::"text") AND ("dkim_status" = 'unchecked'::"text") AND ("dmarc_status" = 'unchecked'::"text") AND ("spf_status" = 'unchecked'::"text") AND ("provider_authenticated" = false)))),
    CONSTRAINT "communication_email_domains_removed_cleanup_check" CHECK ((("lifecycle_state" <> 'removed'::"text") OR ("provider_cleanup_error" IS NULL))),
    CONSTRAINT "communication_email_domains_spf_status_check" CHECK (("spf_status" = ANY (ARRAY['unchecked'::"text", 'pending'::"text", 'passing'::"text", 'failing'::"text"]))),
    CONSTRAINT "communication_email_domains_transition_check" CHECK ((("lifecycle_state" = 'transitioning'::"text") = ("transition_until" IS NOT NULL))),
    CONSTRAINT "communication_email_domains_verified_state_check" CHECK ((("lifecycle_state" <> 'verified'::"text") OR ("provider_verified" AND ("ownership_status" = 'passing'::"text") AND ((("purpose" = 'sending'::"text") AND "provider_authenticated" AND ("dkim_status" = 'passing'::"text")) OR (("purpose" = 'receiving'::"text") AND ("inbound_mx_status" = 'passing'::"text"))))))
);


