    CONSTRAINT "communication_outbound_attachments_delivery_mode_check" CHECK (("delivery_mode" = ANY (ARRAY['inline_media'::"text", 'secure_link'::"text"]))),
    CONSTRAINT "communication_outbound_attachments_file_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "file_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "file_name")) <= 255))),
    CONSTRAINT "communication_outbound_attachments_mime_type_check" CHECK ((("char_length"(TRIM(BOTH FROM "mime_type")) >= 1) AND ("char_length"(TRIM(BOTH FROM "mime_type")) <= 127)))
);


ALTER TABLE "public"."communication_outbound_attachments" OWNER TO "postgres";


COMMENT ON COLUMN "public"."communication_outbound_attachments"."delivery_mode" IS '''inline_media'' rows are sent as the message''s own attachment (email attachment, or an MMS photo). ''secure_link'' rows (SMS only) were never handed to the provider directly -- the customer instead received a link to public.communication_sms_attachment_access_links baked into the frozen message body.';



CREATE TABLE IF NOT EXISTS "public"."communication_outbox_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "delivery_intent_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "claim_token" "uuid",
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finalized_claim_token" "uuid",
    "channel" "text" DEFAULT 'email'::"text" NOT NULL,
    CONSTRAINT "communication_outbox_events_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "communication_outbox_events_channel_check" CHECK (("channel" = ANY (ARRAY['email'::"text", 'sms'::"text"]))),
    CONSTRAINT "communication_outbox_events_claim_check" CHECK ((("status" = 'processing'::"text") = (("claimed_at" IS NOT NULL) AND ("claim_token" IS NOT NULL)))),
    CONSTRAINT "communication_outbox_events_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'submitted'::"text", 'failed'::"text", 'cancelled'::"text", 'submission_unknown'::"text"])))
);


ALTER TABLE "public"."communication_outbox_events" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_provider_callback_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
