    "provider_event_key" "text" NOT NULL,
    "delivery_intent_id" "uuid",
    "event_kind" "text" NOT NULL,
    "occurred_at" timestamp with time zone,
    "payload" "jsonb" NOT NULL,
    "received_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "organization_id" "uuid",
    "processed_at" timestamp with time zone,
    "normalized_kind" "text",
    "event_at" timestamp with time zone GENERATED ALWAYS AS (COALESCE("occurred_at", "received_at")) STORED,
    "processing_attempts" integer DEFAULT 0 NOT NULL,
    "processing_error" "text",
    "channel" "text" DEFAULT 'email'::"text" NOT NULL,
    CONSTRAINT "communication_provider_callback_events_channel_check" CHECK (("channel" = ANY (ARRAY['email'::"text", 'sms'::"text"]))),
    CONSTRAINT "communication_provider_callback_events_event_kind_check" CHECK ((("char_length"(TRIM(BOTH FROM "event_kind")) >= 1) AND ("char_length"(TRIM(BOTH FROM "event_kind")) <= 80))),
    CONSTRAINT "communication_provider_callback_events_normalized_kind_check" CHECK (("normalized_kind" = ANY (ARRAY['delivered'::"text", 'soft_bounce'::"text", 'hard_bounce'::"text", 'complaint'::"text", 'deferred'::"text", 'blocked'::"text", 'unsubscribed'::"text", 'opened'::"text", 'clicked'::"text", 'other'::"text", 'sms_delivered'::"text", 'sms_sent'::"text", 'sms_undelivered'::"text", 'sms_failed'::"text"]))),
    CONSTRAINT "communication_provider_callback_events_payload_check" CHECK (("jsonb_typeof"("payload") = 'object'::"text")),
    CONSTRAINT "communication_provider_callback_events_provider_channel_check" CHECK (((("channel" = 'email'::"text") AND ("provider" = 'brevo'::"text")) OR (("channel" = 'sms'::"text") AND ("provider" = 'twilio'::"text")))),
    CONSTRAINT "communication_provider_callback_events_provider_event_key_check" CHECK ((("char_length"(TRIM(BOTH FROM "provider_event_key")) >= 1) AND ("char_length"(TRIM(BOTH FROM "provider_event_key")) <= 300)))
);


ALTER TABLE "public"."communication_provider_callback_events" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_sms_attachment_access_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "delivery_intent_id" "uuid" NOT NULL,
