);


ALTER TABLE "public"."communication_sms_attachment_access_links" OWNER TO "postgres";


COMMENT ON TABLE "public"."communication_sms_attachment_access_links" IS 'One customer link per SMS attachment that could not go as real MMS media. Issued automatically inside communication_sms_enqueue_operational_core, not by a staff action -- no expiry, no rotation (Jafar 2026-09-16: matches the no-expiry precedent quote/invoice links already use). Stores only the token hash; the raw token exists once, in the link text baked into the frozen SMS body.';



CREATE TABLE IF NOT EXISTS "public"."communication_sms_credit_accounts" (
