    CONSTRAINT "communication_sms_credit_accounts_currency_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text"))
);


ALTER TABLE "public"."communication_sms_credit_accounts" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."communication_sms_credit_ledger_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "reservation_id" "uuid",
