    CONSTRAINT "communication_sms_credit_ledger_entries_reason_check" CHECK ((("reason" IS NULL) OR (("char_length"(TRIM(BOTH FROM "reason")) >= 1) AND ("char_length"(TRIM(BOTH FROM "reason")) <= 2000)))),
    CONSTRAINT "communication_sms_credit_ledger_entries_source_check" CHECK ((("char_length"(TRIM(BOTH FROM "source_key")) >= 1) AND ("char_length"(TRIM(BOTH FROM "source_key")) <= 200)))
);


ALTER TABLE "public"."communication_sms_credit_ledger_entries" OWNER TO "postgres";


COMMENT ON TABLE "public"."communication_sms_credit_ledger_entries" IS 'Append-only SMS money history. One logical source and kind can produce only one entry.';



COMMENT ON COLUMN "public"."communication_sms_credit_ledger_entries"."reason" IS 'The reasoned note behind an adjustment or refund entry. Null for credit/charge entries, which carry no separate reason of their own.';



CREATE TABLE IF NOT EXISTS "public"."communication_sms_message_snapshots" (
    "delivery_intent_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "channel" "text" DEFAULT 'sms'::"text" NOT NULL,
    "body" "text" NOT NULL,
    "encoding" "text" NOT NULL,
