    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "raw_body" "text" NOT NULL,
    CONSTRAINT "communication_sms_message_snapshots_body_check" CHECK ((("char_length"("body") >= 1) AND ("char_length"("body") <= 2000))),
    CONSTRAINT "communication_sms_message_snapshots_channel_check" CHECK (("channel" = 'sms'::"text")),
    CONSTRAINT "communication_sms_message_snapshots_encoding_check" CHECK (("encoding" = ANY (ARRAY['gsm7'::"text", 'ucs2'::"text"]))),
