    CONSTRAINT "communication_sms_message_snapshots_segments_check" CHECK ((("segment_count" >= 1) AND ("segment_count" <= 10)))
);


ALTER TABLE "public"."communication_sms_message_snapshots" OWNER TO "postgres";


COMMENT ON COLUMN "public"."communication_sms_message_snapshots"."raw_body" IS 'The composer''s own typed text, before any secure-link URL was appended for the wire body. Idempotent replay compares this column, never body, so a legitimately different link per attempt never causes a false payload-conflict.';



CREATE TABLE IF NOT EXISTS "public"."communication_sms_reconciliation_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
