    CONSTRAINT "communication_sms_reconciliation_items_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'processing'::"text", 'resolved'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."communication_sms_reconciliation_items" OWNER TO "postgres";


