    CONSTRAINT "communication_sms_registration_submissions_attestation_text_che" CHECK ((("char_length"(TRIM(BOTH FROM "attestation_text")) >= 1) AND ("char_length"(TRIM(BOTH FROM "attestation_text")) <= 2000))),
