    CONSTRAINT "communication_sms_submission_attempts_number_check" CHECK (("attempt_number" > 0)),
    CONSTRAINT "communication_sms_submission_attempts_outcome_check" CHECK (("outcome" = ANY (ARRAY['started'::"text", 'accepted'::"text", 'rejected'::"text", 'submission_unknown'::"text"]))),
