    CONSTRAINT "communication_sms_trust_hub_resources_provider_sid_check" CHECK ((("provider_sid" IS NULL) OR (("char_length"(TRIM(BOTH FROM "provider_sid")) >= 1) AND ("char_length"(TRIM(BOTH FROM "provider_sid")) <= 64)))),
    CONSTRAINT "communication_sms_trust_hub_resources_provider_status_check" CHECK ((("provider_status" IS NULL) OR ("char_length"("provider_status") <= 100))),
