CREATE TABLE IF NOT EXISTS "public"."communication_twilio_credentials" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "twilio_account_id" "uuid" NOT NULL,
    "credential_purpose" "text" NOT NULL,
    "lifecycle_state" "text" NOT NULL,
    "credential_sid" "text",
    "algorithm" "text" DEFAULT 'aes-256-gcm'::"text" NOT NULL,
    "format_version" smallint DEFAULT 1 NOT NULL,
    "encryption_key_id" "text" NOT NULL,
    "nonce" "bytea" NOT NULL,
    "ciphertext" "bytea" NOT NULL,
    "authentication_tag" "bytea" NOT NULL,
    "retire_after" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "communication_twilio_credentials_algorithm_check" CHECK (("algorithm" = 'aes-256-gcm'::"text")),
    CONSTRAINT "communication_twilio_credentials_ciphertext_check" CHECK (("octet_length"("ciphertext") > 0)),
    CONSTRAINT "communication_twilio_credentials_format_check" CHECK (("format_version" = 1)),
    CONSTRAINT "communication_twilio_credentials_key_id_check" CHECK (("encryption_key_id" ~ '^[A-Za-z0-9._-]{1,64}$'::"text")),
    CONSTRAINT "communication_twilio_credentials_lifecycle_check" CHECK (("lifecycle_state" = ANY (ARRAY['staged'::"text", 'current'::"text", 'prior'::"text"]))),
    CONSTRAINT "communication_twilio_credentials_nonce_check" CHECK (("octet_length"("nonce") = 12)),
    CONSTRAINT "communication_twilio_credentials_purpose_check" CHECK (("credential_purpose" = ANY (ARRAY['restricted_api_key'::"text", 'auth_token'::"text"]))),
    CONSTRAINT "communication_twilio_credentials_retirement_check" CHECK (((("lifecycle_state" = 'prior'::"text") AND ("retire_after" IS NOT NULL)) OR (("lifecycle_state" <> 'prior'::"text") AND ("retire_after" IS NULL)))),
    CONSTRAINT "communication_twilio_credentials_sid_check" CHECK (((("credential_purpose" = 'restricted_api_key'::"text") AND ("credential_sid" IS NOT NULL) AND ("credential_sid" ~ '^SK[0-9A-Fa-f]{32}$'::"text")) OR (("credential_purpose" = 'auth_token'::"text") AND ("credential_sid" IS NULL)))),
    CONSTRAINT "communication_twilio_credentials_tag_check" CHECK (("octet_length"("authentication_tag") = 16))
);


