    "raw" "jsonb" NOT NULL,
    "planned_action" "text" DEFAULT 'create'::"text" NOT NULL,
    "resolved_payload" "jsonb",
    "match_client_id" "uuid",
    "match_reason" "text",
    "flags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "status" "text" DEFAULT 'pending_review'::"text" NOT NULL,
    "error_message" "text",
    "result_client_id" "uuid",
    "processed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "import_rows_match_reason_check" CHECK ((("match_reason" IS NULL) OR ("char_length"("match_reason") <= 80))),
    CONSTRAINT "import_rows_planned_action_check" CHECK (("planned_action" = ANY (ARRAY['create'::"text", 'update'::"text", 'skip'::"text", 'hold'::"text", 'error'::"text"]))),
    CONSTRAINT "import_rows_source_row_number_check" CHECK (("source_row_number" >= 1)),
    CONSTRAINT "import_rows_status_check" CHECK (("status" = ANY (ARRAY['pending_review'::"text", 'ready'::"text", 'imported'::"text", 'skipped'::"text", 'held'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."import_rows" OWNER TO "postgres";


COMMENT ON TABLE "public"."import_rows" IS 'One data row from an import file: original cells, the Review dry-run decision, the concrete payload to write, and the per-row result. Read directly by the import screens (RLS); written only by the import /api RPCs and the service-role worker.';



COMMENT ON COLUMN "public"."import_rows"."resolved_payload" IS 'Fixed worker contract. planned_action=create: { "client": { client_type, first_name, last_name, company_name, display_name, lifecycle_status, lead_source, initial_note }, "email": text|null, "phone": text|null, "property": { label, address_line1, address_line2, city, state_region, postal_code, country }|null }. planned_action=update: the same shape but carrying ONLY the fields to change (the Review step drops any scalar field whose "don''t overwrite" toggle is on and whose target already has a value; email/phone/property are added only when the client lacks that kind and no earlier file row claimed the value; initial_note, being additive, is always carried); match_client_id names the client to update. Null for skip/hold/error rows.';



COMMENT ON COLUMN "public"."import_rows"."result_client_id" IS 'The id this row produced once the worker has run: a Client for entity_type=''client'' (create or update), an opening-balance fact for entity_type=''opening_balance'' (the fresh fact, or the correcting fact for a planned_action=''update'' row). Column name predates the second entity type; not renamed because nothing reads it yet for either type.';



