    CONSTRAINT "invoice_access_links_recipient_name_check" CHECK ((("recipient_name" IS NULL) OR (("char_length"(TRIM(BOTH FROM "recipient_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "recipient_name")) <= 200)))),
