    "position" integer NOT NULL,
    "source_catalog_item_id" "uuid",
    "source_job_id" "uuid",
    "source_job_line_id" "uuid",
    "service_date" "date",
    "line_kind" "text" DEFAULT 'priced'::"text" NOT NULL,
    "category" "text",
    "name" "text" NOT NULL,
    "description" "text",
    "unit_label" "text",
    "quantity" numeric(12,3),
    "unit_price_minor" bigint,
    "is_taxable" boolean DEFAULT true NOT NULL,
    "progress_original_amount_minor" bigint,
    "line_total_minor" bigint GENERATED ALWAYS AS ("public"."pricing_line_total_minor"("quantity", "unit_price_minor")) STORED,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "invoice_lines_description_check" CHECK ((("description" IS NULL) OR ("char_length"("description") <= 2000))),
    CONSTRAINT "invoice_lines_line_kind_check" CHECK (("line_kind" = ANY (ARRAY['priced'::"text", 'text'::"text", 'heading'::"text"]))),
    CONSTRAINT "invoice_lines_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "name")) >= 2) AND ("char_length"(TRIM(BOTH FROM "name")) <= 160))),
    CONSTRAINT "invoice_lines_position_check" CHECK (("position" >= 0)),
    CONSTRAINT "invoice_lines_progress_original_amount_minor_check" CHECK ((("progress_original_amount_minor" IS NULL) OR (("progress_original_amount_minor" >= 0) AND ("progress_original_amount_minor" <= '1000000000000'::bigint)))),
    CONSTRAINT "invoice_lines_shape_check" CHECK (((("line_kind" = 'priced'::"text") AND ("category" = ANY (ARRAY['product'::"text", 'service'::"text"])) AND ("quantity" > (0)::numeric) AND ("quantity" <= (1000000)::numeric) AND (("unit_price_minor" >= 0) AND ("unit_price_minor" <= '1000000000000'::bigint))) OR (("line_kind" = ANY (ARRAY['text'::"text", 'heading'::"text"])) AND ("category" IS NULL) AND ("quantity" IS NULL) AND ("unit_price_minor" IS NULL) AND (NOT "is_taxable") AND ("progress_original_amount_minor" IS NULL)))),
    CONSTRAINT "invoice_lines_unit_label_check" CHECK ((("unit_label" IS NULL) OR (("char_length"(TRIM(BOTH FROM "unit_label")) >= 1) AND ("char_length"(TRIM(BOTH FROM "unit_label")) <= 24))))
);


