CREATE TABLE IF NOT EXISTS "public"."invoice_sources" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "root_invoice_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "source_kind" "text" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "visit_id" "uuid",
    "reminder_id" "uuid",
    "installment_number" integer,
    "service_property_index" integer,
    "claimed_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "installment_id" "uuid",
    CONSTRAINT "invoice_sources_installment_number_check" CHECK ((("installment_number" IS NULL) OR ("installment_number" >= 1))),
    CONSTRAINT "invoice_sources_service_property_index_check" CHECK ((("service_property_index" IS NULL) OR ("service_property_index" >= 0))),
    CONSTRAINT "invoice_sources_shape" CHECK (
CASE "source_kind"
    WHEN 'job_total'::"text" THEN (("visit_id" IS NULL) AND ("reminder_id" IS NULL) AND ("installment_number" IS NULL) AND ("installment_id" IS NULL))
    WHEN 'visit'::"text" THEN (("visit_id" IS NOT NULL) AND ("reminder_id" IS NULL) AND ("installment_number" IS NULL) AND ("installment_id" IS NULL))
    WHEN 'reminder_period'::"text" THEN (("visit_id" IS NULL) AND ("reminder_id" IS NOT NULL) AND ("installment_number" IS NULL) AND ("installment_id" IS NULL))
    WHEN 'installment'::"text" THEN (("visit_id" IS NULL) AND ("reminder_id" IS NULL) AND ("installment_number" IS NOT NULL) AND ("installment_id" IS NOT NULL))
    ELSE NULL::boolean
END),
    CONSTRAINT "invoice_sources_source_kind_check" CHECK (("source_kind" = ANY (ARRAY['job_total'::"text", 'visit'::"text", 'reminder_period'::"text", 'installment'::"text"])))
);


ALTER TABLE "public"."invoice_sources" OWNER TO "postgres";


COMMENT ON TABLE "public"."invoice_sources" IS 'One canonical claim per unit of billable work, attached to the root of an invoice''s correction chain so a replacement inherits it rather than competing for it. Members read this table; only the commands in this file write it. A void keeps the claim (decision D4), which is what stops a cancelled bill from quietly putting the same work back in the queue.';



COMMENT ON COLUMN "public"."invoice_sources"."root_invoice_id" IS 'The first invoice of the chain that claimed this work. Every correction and rebill in that chain shares it, so the uniqueness indexes below let a chain be re-billed without ever letting the work be billed twice.';



COMMENT ON COLUMN "public"."invoice_sources"."installment_number" IS 'Position in the job''s payment schedule. Jobs 11c adds the foreign key to the schedule row; the number carries the identity until then.';



