ALTER TABLE "public"."job_checklists" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_checklists" IS 'One checklist attached to one job, frozen at the moment it was attached. Its questions are this job''s own copy, so editing the template it came from cannot rewrite answers a crew already gave.';



CREATE TABLE IF NOT EXISTS "public"."job_command_receipts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "action" "text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
