    CONSTRAINT "job_command_receipts_idempotency_key_check" CHECK (("char_length"(TRIM(BOTH FROM "idempotency_key")) >= 8)),
    CONSTRAINT "job_command_receipts_request_hash_check" CHECK (("char_length"(TRIM(BOTH FROM "request_hash")) >= 1))
);


ALTER TABLE "public"."job_command_receipts" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_command_receipts" IS 'Idempotency ledger for job commands with no other natural key. One row per (organization, action, key); a retry carrying the same key and request hash returns the first result.';



CREATE TABLE IF NOT EXISTS "public"."job_costing_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
