    CONSTRAINT "job_costing_events_subject_kind_check" CHECK (("subject_kind" = ANY (ARRAY['time_entry'::"text", 'expense'::"text"])))
);


ALTER TABLE "public"."job_costing_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_costing_events" IS 'Append-only history of every labor and expense change on a job, including corrections made after the job closed. Carries money in prior_values/new_values, so it is never granted to authenticated and is read only through a jobs.view_cost reader.';



CREATE TABLE IF NOT EXISTS "public"."job_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
