    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_events_event_type_check" CHECK ((("char_length"(TRIM(BOTH FROM "event_type")) >= 2) AND ("char_length"(TRIM(BOTH FROM "event_type")) <= 64))),
    CONSTRAINT "job_events_new_status_check" CHECK ((("new_status" IS NULL) OR ("new_status" = ANY (ARRAY['active'::"text", 'closed'::"text"])))),
    CONSTRAINT "job_events_prior_status_check" CHECK ((("prior_status" IS NULL) OR ("prior_status" = ANY (ARRAY['active'::"text", 'closed'::"text"]))))
);


ALTER TABLE "public"."job_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_events" IS 'Job lifecycle and activity history. Append only in practice: no command updates or deletes a row, and no grant lets a member write one.';



CREATE TABLE IF NOT EXISTS "public"."job_expenses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "accounting_code" "text",
    "description" "text",
    "expense_date" "date" NOT NULL,
    "total_minor" bigint NOT NULL,
    "reimburse_to_user_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_expenses_accounting_code_check" CHECK ((("accounting_code" IS NULL) OR (("char_length"(TRIM(BOTH FROM "accounting_code")) >= 1) AND ("char_length"(TRIM(BOTH FROM "accounting_code")) <= 64)))),
    CONSTRAINT "job_expenses_description_check" CHECK ((("description" IS NULL) OR ("char_length"("description") <= 2000))),
    CONSTRAINT "job_expenses_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "name")) >= 2) AND ("char_length"(TRIM(BOTH FROM "name")) <= 160))),
