);


ALTER TABLE "public"."job_expenses" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_expenses" IS 'A cost incurred on a job that is not labor and not a line item -- materials, dump fees, subcontractors. Receipts hang off this row as attachments with entity_type ''job_expense'', so a receipt can be a photo or a PDF without this table knowing anything about files.';



CREATE TABLE IF NOT EXISTS "public"."job_invoice_reminders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "reminder_kind" "text" NOT NULL,
    "visit_id" "uuid",
    "due_on" "date" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "resolution" "text",
    "resolved_at" timestamp with time zone,
    "resolved_by" "uuid",
    "note" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_invoice_reminders_note_check" CHECK ((("note" IS NULL) OR ("char_length"("note") <= 200))),
    CONSTRAINT "job_invoice_reminders_reminder_kind_check" CHECK (("reminder_kind" = ANY (ARRAY['on_completion'::"text", 'per_visit'::"text", 'monthly_last_day'::"text", 'custom_date'::"text"]))),
    CONSTRAINT "job_invoice_reminders_resolution_check" CHECK (("resolution" = ANY (ARRAY['dismissed'::"text", 'invoiced'::"text"]))),
    CONSTRAINT "job_invoice_reminders_resolution_pairs" CHECK ((("status" = 'resolved'::"text") = ("resolution" IS NOT NULL))),
    CONSTRAINT "job_invoice_reminders_resolved_stamp" CHECK ((("resolution" IS NULL) = ("resolved_at" IS NULL))),
    CONSTRAINT "job_invoice_reminders_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'resolved'::"text"]))),
    CONSTRAINT "job_invoice_reminders_visit_only_for_per_visit" CHECK ((("visit_id" IS NULL) OR ("reminder_kind" = 'per_visit'::"text")))
);


ALTER TABLE "public"."job_invoice_reminders" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_invoice_reminders" IS 'Internal invoice reminders for a job, never client-facing. A pending reminder whose due_on has arrived puts the job in the Requires invoicing derived status. Cleared by dismissing it or, once Invoices exist, by invoicing it (resolution = ''invoiced''). Rows are written only by the commands in this file.';



COMMENT ON COLUMN "public"."job_invoice_reminders"."status" IS 'pending until cleared. A pending row with due_on <= today is what the reader turns into Requires invoicing.';



CREATE TABLE IF NOT EXISTS "public"."job_line_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "source_catalog_item_id" "uuid",
    "line_kind" "text" DEFAULT 'priced'::"text" NOT NULL,
    "category" "text",
    "is_labor" boolean DEFAULT false NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "unit_label" "text",
    "quantity" numeric(12,3),
    "unit_price_minor" bigint,
    "unit_cost_minor" bigint,
    "is_taxable" boolean DEFAULT true NOT NULL,
    "image_attachment_id" "uuid",
    "line_total_minor" bigint GENERATED ALWAYS AS ("public"."pricing_line_total_minor"("quantity", "unit_price_minor")) STORED,
    "line_cost_total_minor" bigint GENERATED ALWAYS AS ("public"."pricing_line_total_minor"("quantity", "unit_cost_minor")) STORED,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_line_items_description_check" CHECK ((("description" IS NULL) OR ("char_length"("description") <= 2000))),
    CONSTRAINT "job_line_items_line_kind_check" CHECK (("line_kind" = ANY (ARRAY['priced'::"text", 'text'::"text", 'heading'::"text"]))),
    CONSTRAINT "job_line_items_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "name")) >= 2) AND ("char_length"(TRIM(BOTH FROM "name")) <= 160))),
    CONSTRAINT "job_line_items_position_check" CHECK (("position" >= 0)),
    CONSTRAINT "job_line_items_shape_check" CHECK (((("line_kind" = 'priced'::"text") AND ("category" = ANY (ARRAY['product'::"text", 'service'::"text"])) AND ("quantity" > (0)::numeric) AND ("quantity" <= (1000000)::numeric) AND (("unit_price_minor" >= 0) AND ("unit_price_minor" <= '1000000000000'::bigint)) AND (("unit_cost_minor" >= 0) AND ("unit_cost_minor" <= '1000000000000'::bigint)) AND ((NOT "is_labor") OR ("category" = 'service'::"text"))) OR (("line_kind" = ANY (ARRAY['text'::"text", 'heading'::"text"])) AND ("category" IS NULL) AND (NOT "is_labor") AND ("quantity" IS NULL) AND ("unit_price_minor" IS NULL) AND ("unit_cost_minor" IS NULL) AND (NOT "is_taxable")))),
    CONSTRAINT "job_line_items_unit_label_check" CHECK ((("unit_label" IS NULL) OR (("char_length"(TRIM(BOTH FROM "unit_label")) >= 1) AND ("char_length"(TRIM(BOTH FROM "unit_label")) <= 24))))
);


ALTER TABLE "public"."job_line_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_line_items" IS 'A job''s own copy of the work it covers. Copied from the approved quote version at conversion and owned by the job from that moment: nothing in the catalog and nothing on the quote can change these numbers again.';



CREATE TABLE IF NOT EXISTS "public"."properties" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "label" "text" DEFAULT 'Primary property'::"text" NOT NULL,
    "address_line1" "text" NOT NULL,
    "address_line2" "text",
    "city" "text" NOT NULL,
    "state_region" "text",
    "postal_code" "text",
    "country" "text" DEFAULT 'US'::"text" NOT NULL,
    "access_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_primary" boolean DEFAULT false NOT NULL,
    "is_billing_address" boolean DEFAULT false NOT NULL,
    "archived_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "latitude" numeric(9,6),
    "longitude" numeric(9,6),
    "tax_rate_id" "uuid",
    "geocode_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    CONSTRAINT "properties_address_line1_check" CHECK ((("char_length"(TRIM(BOTH FROM "address_line1")) >= 2) AND ("char_length"(TRIM(BOTH FROM "address_line1")) <= 160))),
    CONSTRAINT "properties_city_check" CHECK ((("char_length"(TRIM(BOTH FROM "city")) >= 2) AND ("char_length"(TRIM(BOTH FROM "city")) <= 80))),
    CONSTRAINT "properties_geocode_pair_check" CHECK ((("latitude" IS NULL) = ("longitude" IS NULL))),
    CONSTRAINT "properties_geocode_status_check" CHECK (("geocode_status" = ANY (ARRAY['pending'::"text", 'succeeded'::"text", 'failed'::"text"]))),
    CONSTRAINT "properties_label_check" CHECK ((("char_length"(TRIM(BOTH FROM "label")) >= 2) AND ("char_length"(TRIM(BOTH FROM "label")) <= 120))),
    CONSTRAINT "properties_latitude_check" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)))),
    CONSTRAINT "properties_longitude_check" CHECK ((("longitude" IS NULL) OR (("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric))))
);


ALTER TABLE "public"."properties" OWNER TO "postgres";


COMMENT ON COLUMN "public"."properties"."geocode_status" IS 'Where address-to-coordinate geocoding stands for this property: pending (queued/not yet done), succeeded (coordinates stored), failed (address does not resolve). Maintained by the private.mark_property_for_geocoding trigger and the background geocoding worker.';



CREATE OR REPLACE VIEW "public"."job_list_rows" WITH ("security_invoker"='true') AS
 SELECT "job"."id",
    "job"."organization_id",
    "job"."job_number",
    "job"."title",
    "job"."job_type",
    "job"."is_as_needed",
    "job"."status",
    "job"."price_basis",
    "job"."billing_timing",
    "job"."currency_code",
    "job"."contract_start_date",
    "job"."contract_end_date",
    "job"."quote_id",
    "job"."created_at",
    "private"."job_derived_status"("job"."status", "job"."job_type", "job"."contract_end_date", "calendar"."today", (EXISTS ( SELECT 1
           FROM "public"."job_invoice_reminders" "reminder"
          WHERE (("reminder"."organization_id" = "job"."organization_id") AND ("reminder"."job_id" = "job"."id") AND ("reminder"."status" = 'pending'::"text") AND ("reminder"."due_on" <= "calendar"."today"))))) AS "derived_status",
    "job"."client_id",
    "client"."display_name" AS "client_display_name",
    "client"."company_name" AS "client_company_name",
    "job"."property_id",
    "property"."label" AS "property_label",
    "property"."address_line1" AS "property_address_line1",
    "property"."city" AS "property_city",
    "property"."state_region" AS "property_state_region",
    "property"."postal_code" AS "property_postal_code"
   FROM ((("public"."jobs" "job"
     LEFT JOIN "private"."organization_calendars"() "calendar"("organization_id", "today") ON (("calendar"."organization_id" = "job"."organization_id")))
     LEFT JOIN "public"."clients" "client" ON ((("client"."organization_id" = "job"."organization_id") AND ("client"."id" = "job"."client_id"))))
     LEFT JOIN "public"."properties" "property" ON ((("property"."organization_id" = "job"."organization_id") AND ("property"."id" = "job"."property_id"))));


ALTER VIEW "public"."job_list_rows" OWNER TO "postgres";


COMMENT ON VIEW "public"."job_list_rows" IS 'What the Jobs list draws: identity, client and property context, and the derived status (now including Requires invoicing from due reminders). No money - that comes from public.job_money.';



CREATE TABLE IF NOT EXISTS "public"."job_payment_schedule_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "description" "text" NOT NULL,
    "value_type" "text" NOT NULL,
    "value" bigint NOT NULL,
    "is_deposit" boolean DEFAULT false NOT NULL,
    "locked_amount_minor" bigint,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_payment_schedule_items_description_check" CHECK ((("char_length"(TRIM(BOTH FROM "description")) >= 2) AND ("char_length"(TRIM(BOTH FROM "description")) <= 160))),
    CONSTRAINT "job_payment_schedule_items_locked_amount_minor_check" CHECK ((("locked_amount_minor" IS NULL) OR ("locked_amount_minor" >= 0))),
    CONSTRAINT "job_payment_schedule_items_position_check" CHECK (("position" >= 0)),
    CONSTRAINT "job_payment_schedule_items_value_range_check" CHECK (((("value_type" = 'percentage'::"text") AND (("value" >= 1) AND ("value" <= 10000))) OR (("value_type" = 'fixed'::"text") AND (("value" >= 1) AND ("value" <= '1000000000000'::bigint))))),
    CONSTRAINT "job_payment_schedule_items_value_type_check" CHECK (("value_type" = ANY (ARRAY['fixed'::"text", 'percentage'::"text"])))
);


ALTER TABLE "public"."job_payment_schedule_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_payment_schedule_items" IS 'A one-off job''s ordered payment stages. Either the job bills as a whole or it carries one schedule of 2 to 12 stages in a single mode that reconciles exactly to the job total. Copied from an approved quote at conversion and owned by the job from that moment.';



COMMENT ON COLUMN "public"."job_payment_schedule_items"."locked_amount_minor" IS 'The amount this stage was billed at, written when its invoice is created. A stage carrying one is locked.';



CREATE TABLE IF NOT EXISTS "public"."job_recurrence_rules" (
    "job_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "frequency" "text" NOT NULL,
    "interval_count" integer DEFAULT 1 NOT NULL,
    "weekdays" smallint[],
    "monthly_mode" "text",
    "month_day" smallint,
    "ordinal_week" smallint,
    "ordinal_weekday" smallint,
    "start_date" "date" NOT NULL,
    "end_mode" "text" NOT NULL,
    "duration_count" integer,
    "duration_unit" "text",
    "end_date" "date" NOT NULL,
    "start_time" time without time zone,
    "end_time" time without time zone,
    "all_day" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_recurrence_all_day_no_time" CHECK (((NOT "all_day") OR (("start_time" IS NULL) AND ("end_time" IS NULL)))),
    CONSTRAINT "job_recurrence_dates_ordered" CHECK (("end_date" >= "start_date")),
    CONSTRAINT "job_recurrence_duration_pairing" CHECK ((("end_mode" = 'after'::"text") = (("duration_count" IS NOT NULL) AND ("duration_unit" IS NOT NULL)))),
    CONSTRAINT "job_recurrence_monthly_shape" CHECK ((("frequency" <> 'monthly'::"text") OR (("monthly_mode" = 'day_of_month'::"text") AND ("month_day" IS NOT NULL) AND ("ordinal_week" IS NULL) AND ("ordinal_weekday" IS NULL)) OR (("monthly_mode" = 'last_day'::"text") AND ("month_day" IS NULL) AND ("ordinal_week" IS NULL) AND ("ordinal_weekday" IS NULL)) OR (("monthly_mode" = 'day_of_week'::"text") AND ("month_day" IS NULL) AND ("ordinal_week" IS NOT NULL) AND ("ordinal_weekday" IS NOT NULL)))),
    CONSTRAINT "job_recurrence_non_monthly_clean" CHECK ((("frequency" = 'monthly'::"text") OR ("monthly_mode" IS NULL))),
    CONSTRAINT "job_recurrence_rules_duration_count_check" CHECK ((("duration_count" >= 1) AND ("duration_count" <= 520))),
    CONSTRAINT "job_recurrence_rules_duration_unit_check" CHECK (("duration_unit" = ANY (ARRAY['day'::"text", 'week'::"text", 'month'::"text", 'year'::"text"]))),
    CONSTRAINT "job_recurrence_rules_end_mode_check" CHECK (("end_mode" = ANY (ARRAY['after'::"text", 'on'::"text"]))),
    CONSTRAINT "job_recurrence_rules_frequency_check" CHECK (("frequency" = ANY (ARRAY['daily'::"text", 'weekly'::"text", 'monthly'::"text", 'yearly'::"text"]))),
    CONSTRAINT "job_recurrence_rules_interval_count_check" CHECK ((("interval_count" >= 1) AND ("interval_count" <= 52))),
    CONSTRAINT "job_recurrence_rules_month_day_check" CHECK ((("month_day" >= 1) AND ("month_day" <= 31))),
    CONSTRAINT "job_recurrence_rules_monthly_mode_check" CHECK (("monthly_mode" = ANY (ARRAY['day_of_month'::"text", 'last_day'::"text", 'day_of_week'::"text"]))),
    CONSTRAINT "job_recurrence_rules_ordinal_week_check" CHECK ((("ordinal_week" >= 1) AND ("ordinal_week" <= 5))),
    CONSTRAINT "job_recurrence_rules_ordinal_weekday_check" CHECK ((("ordinal_weekday" >= 0) AND ("ordinal_weekday" <= 6))),
    CONSTRAINT "job_recurrence_span_bounded" CHECK (("end_date" <= ("start_date" + 3660))),
    CONSTRAINT "job_recurrence_time_order" CHECK ((("end_time" IS NULL) OR (("start_time" IS NOT NULL) AND ("end_time" > "start_time")))),
    CONSTRAINT "job_recurrence_weekdays_valid" CHECK ((("weekdays" IS NULL) OR ("weekdays" <@ ARRAY[(0)::smallint, (1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint]))),
    CONSTRAINT "job_recurrence_weekly_has_days" CHECK ((("frequency" <> 'weekly'::"text") OR (("weekdays" IS NOT NULL) AND (("array_length"("weekdays", 1) >= 1) AND ("array_length"("weekdays", 1) <= 7)))))
);


ALTER TABLE "public"."job_recurrence_rules" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_recurrence_rules" IS 'The repeat rule behind a recurring job. Stored as columns rather than an iCalendar string so the database can check it. An as-needed job has no row here.';



CREATE TABLE IF NOT EXISTS "public"."job_report_access_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "recipient_name" "text",
    "recipient_email" "text",
    "token_hash" "bytea" NOT NULL,
    "issued_by" "uuid",
    "issued_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "revoked_reason" "text",
    "first_viewed_at" timestamp with time zone,
    "last_viewed_at" timestamp with time zone,
    "view_count" integer DEFAULT 0 NOT NULL,
    "frozen_document" "jsonb" NOT NULL,
    CONSTRAINT "job_report_access_links_expiry_follows_issue" CHECK ((("expires_at" IS NULL) OR ("expires_at" > "issued_at"))),
    CONSTRAINT "job_report_access_links_recipient_email_check" CHECK ((("recipient_email" IS NULL) OR (("recipient_email" = "lower"(TRIM(BOTH FROM "recipient_email"))) AND (("char_length"("recipient_email") >= 6) AND ("char_length"("recipient_email") <= 320)) AND ("recipient_email" ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::"text")))),
    CONSTRAINT "job_report_access_links_recipient_name_check" CHECK ((("recipient_name" IS NULL) OR (("char_length"(TRIM(BOTH FROM "recipient_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "recipient_name")) <= 200)))),
    CONSTRAINT "job_report_access_links_revocation_agrees" CHECK ((("revoked_at" IS NULL) = ("revoked_reason" IS NULL))),
    CONSTRAINT "job_report_access_links_revoked_reason_check" CHECK ((("revoked_reason" IS NULL) OR ("revoked_reason" = ANY (ARRAY['rotated'::"text", 'revoked'::"text"])))),
    CONSTRAINT "job_report_access_links_token_hash_check" CHECK (("octet_length"("token_hash") = 32)),
    CONSTRAINT "job_report_access_links_view_count_check" CHECK (("view_count" >= 0))
);


ALTER TABLE "public"."job_report_access_links" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_report_access_links" IS 'One customer link to a job''s work report. Stores only the token hash -- the raw token exists once, in the URL handed to the staff member who created it, and must never appear in a row, a log line, or an activity payload.';



COMMENT ON COLUMN "public"."job_report_access_links"."first_viewed_at" IS 'Stamped once, by an explicit call from the customer''s browser after the report is on screen. Never by a page request, a HEAD, a mail scanner or a link preview.';



COMMENT ON COLUMN "public"."job_report_access_links"."frozen_document" IS 'The complete customer document as it stood the moment this link was issued. Set once, at insert, by issue_job_report_access_link -- never rebuilt later, so a later edit to the report cannot change what an already-shared link shows.';



