CREATE TABLE IF NOT EXISTS "public"."job_reports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "include_service_details" boolean DEFAULT true NOT NULL,
    "include_price" boolean DEFAULT false NOT NULL,
    "signature_id" "uuid",
    "summary" "text",
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_reports_price_requires_details" CHECK (((NOT "include_price") OR "include_service_details")),
    CONSTRAINT "job_reports_summary_check" CHECK ((("summary" IS NULL) OR (("char_length"(TRIM(BOTH FROM "summary")) >= 1) AND ("char_length"(TRIM(BOTH FROM "summary")) <= 2000))))
);


ALTER TABLE "public"."job_reports" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_reports" IS 'One living work report per job: the two customer-facing toggles, an optional chosen signature and a summary. Carries no copied content -- the photos and checklist answers it shows are chosen in the two join tables below and resolved live, so the customer link is always current.';



CREATE TABLE IF NOT EXISTS "public"."job_signatures" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "visit_id" "uuid",
    "signature_type" "text" NOT NULL,
    "signer_name" "text" NOT NULL,
    "signer_role" "text",
    "statement" "text" NOT NULL,
    "method" "text" NOT NULL,
    "document_snapshot" "jsonb" NOT NULL,
    "document_hash" "text" NOT NULL,
    "image_object_key" "text",
    "image_byte_size" integer,
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "collected_by" "uuid",
    "collected_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_signatures_document_hash_check" CHECK (("document_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "job_signatures_image_byte_size_check" CHECK ((("image_byte_size" IS NULL) OR (("image_byte_size" >= 1) AND ("image_byte_size" <= 262144)))),
    CONSTRAINT "job_signatures_image_matches_method" CHECK (((("method" = 'drawn'::"text") = ("image_object_key" IS NOT NULL)) AND (("image_object_key" IS NULL) = ("image_byte_size" IS NULL)))),
    CONSTRAINT "job_signatures_image_object_key_check" CHECK ((("image_object_key" IS NULL) OR (("char_length"("image_object_key") >= 1) AND ("char_length"("image_object_key") <= 500)))),
    CONSTRAINT "job_signatures_method_check" CHECK (("method" = ANY (ARRAY['typed'::"text", 'drawn'::"text"]))),
    CONSTRAINT "job_signatures_signature_type_check" CHECK (("signature_type" = ANY (ARRAY['work_authorization'::"text", 'work_completion'::"text", 'other'::"text"]))),
    CONSTRAINT "job_signatures_signer_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "signer_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "signer_name")) <= 120))),
    CONSTRAINT "job_signatures_signer_role_check" CHECK ((("signer_role" IS NULL) OR (("char_length"(TRIM(BOTH FROM "signer_role")) >= 1) AND ("char_length"(TRIM(BOTH FROM "signer_role")) <= 60)))),
    CONSTRAINT "job_signatures_statement_check" CHECK ((("char_length"(TRIM(BOTH FROM "statement")) >= 1) AND ("char_length"(TRIM(BOTH FROM "statement")) <= 500)))
);


ALTER TABLE "public"."job_signatures" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_signatures" IS 'A signature collected against a job, bound to a frozen copy of the job document as it stood at that moment and a hash of it. Append-only: there is no edit, no delete and no void. A later job edit does not rewrite the evidence -- it makes the signature stale, and the crew collects a new one beside it.';



COMMENT ON COLUMN "public"."job_signatures"."visit_id" IS 'Which visit the crew were on, for context. Cleared rather than cascaded when the visit goes: the signature is against the job, and a deleted visit must not take signed evidence with it.';



COMMENT ON COLUMN "public"."job_signatures"."document_snapshot" IS 'What was signed: identity, client, property, the priced work list and the total. Never read back through a plain grant -- job_signature_document serves it and strips the money without jobs.view_price.';



COMMENT ON COLUMN "public"."job_signatures"."document_hash" IS 'SHA-256 of the canonical snapshot, copied at signing. Recomputing it against the job''s current document is what tells a screen the job has changed since this was signed.';



CREATE OR REPLACE VIEW "public"."job_status_count_rows" WITH ("security_invoker"='true') AS
 SELECT "job"."organization_id",
    "private"."job_derived_status"("job"."status", "job"."job_type", "job"."contract_end_date", "calendar"."today", ("due_reminder"."job_id" IS NOT NULL)) AS "derived_status"
   FROM (("public"."jobs" "job"
     LEFT JOIN "private"."organization_calendars"() "calendar"("organization_id", "today") ON (("calendar"."organization_id" = "job"."organization_id")))
     LEFT JOIN ( SELECT "reminder"."organization_id",
            "reminder"."job_id"
           FROM ("public"."job_invoice_reminders" "reminder"
             JOIN "private"."organization_calendars"() "cal"("organization_id", "today") ON (("cal"."organization_id" = "reminder"."organization_id")))
          WHERE (("reminder"."status" = 'pending'::"text") AND ("reminder"."due_on" <= "cal"."today"))
          GROUP BY "reminder"."organization_id", "reminder"."job_id") "due_reminder" ON ((("due_reminder"."organization_id" = "job"."organization_id") AND ("due_reminder"."job_id" = "job"."id"))));


ALTER VIEW "public"."job_status_count_rows" OWNER TO "postgres";


COMMENT ON VIEW "public"."job_status_count_rows" IS 'One row per job with just its organization and derived status, the due-reminder check done as a single joined set. Feeds public.job_status_counts; the rich per-row job_list_rows feeds the paged list.';



CREATE TABLE IF NOT EXISTS "public"."job_time_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
