    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_time_entries_cost_per_hour_minor_check" CHECK ((("cost_per_hour_minor" IS NULL) OR (("cost_per_hour_minor" >= 0) AND ("cost_per_hour_minor" <= 100000000)))),
    CONSTRAINT "job_time_entries_minutes_check" CHECK ((("minutes" >= 1) AND ("minutes" <= 1440))),
    CONSTRAINT "job_time_entries_notes_check" CHECK ((("notes" IS NULL) OR ("char_length"("notes") <= 2000)))
);


ALTER TABLE "public"."job_time_entries" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_time_entries" IS 'Hours worked on a job, and what those hours cost. The rate is copied on at recording time, so changing someone''s rate never re-prices finished work.';



