CREATE TABLE IF NOT EXISTS "public"."job_visit_line_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "visit_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "source_job_line_item_id" "uuid",
    "source_catalog_item_id" "uuid",
    "line_kind" "text" DEFAULT 'priced'::"text" NOT NULL,
    "category" "text",
    "is_labor" boolean DEFAULT false NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "unit_label" "text",
    "quantity" numeric(12,3),
    "unit_price_minor" bigint,
    "unit_cost_minor" bigint,
    "is_taxable" boolean DEFAULT true NOT NULL,
    "image_attachment_id" "uuid",
    "line_total_minor" bigint GENERATED ALWAYS AS ("public"."pricing_line_total_minor"("quantity", "unit_price_minor")) STORED,
    "line_cost_total_minor" bigint GENERATED ALWAYS AS ("public"."pricing_line_total_minor"("quantity", "unit_cost_minor")) STORED,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_visit_line_items_description_check" CHECK ((("description" IS NULL) OR ("char_length"("description") <= 2000))),
    CONSTRAINT "job_visit_line_items_line_kind_check" CHECK (("line_kind" = ANY (ARRAY['priced'::"text", 'text'::"text", 'heading'::"text"]))),
    CONSTRAINT "job_visit_line_items_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "name")) >= 2) AND ("char_length"(TRIM(BOTH FROM "name")) <= 160))),
    CONSTRAINT "job_visit_line_items_position_check" CHECK (("position" >= 0)),
    CONSTRAINT "job_visit_line_items_shape_check" CHECK (((("line_kind" = 'priced'::"text") AND ("category" = ANY (ARRAY['product'::"text", 'service'::"text"])) AND ("quantity" > (0)::numeric) AND ("quantity" <= (1000000)::numeric) AND (("unit_price_minor" >= 0) AND ("unit_price_minor" <= '1000000000000'::bigint)) AND (("unit_cost_minor" >= 0) AND ("unit_cost_minor" <= '1000000000000'::bigint)) AND ((NOT "is_labor") OR ("category" = 'service'::"text"))) OR (("line_kind" = ANY (ARRAY['text'::"text", 'heading'::"text"])) AND ("category" IS NULL) AND (NOT "is_labor") AND ("quantity" IS NULL) AND ("unit_price_minor" IS NULL) AND ("unit_cost_minor" IS NULL) AND (NOT "is_taxable")))),
    CONSTRAINT "job_visit_line_items_unit_label_check" CHECK ((("unit_label" IS NULL) OR (("char_length"(TRIM(BOTH FROM "unit_label")) >= 1) AND ("char_length"(TRIM(BOTH FROM "unit_label")) <= 24))))
);


ALTER TABLE "public"."job_visit_line_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_visit_line_items" IS 'One visit''s own effective lines, for recurring per-visit jobs. No rows means the visit bills the job''s lines unchanged; rows mean this visit''s complete billable set, snapshotted when it was saved.';



CREATE TABLE IF NOT EXISTS "public"."job_visits" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "visit_date" "date",
    "start_time" time without time zone,
    "end_time" time without time zone,
    "all_day" boolean DEFAULT false NOT NULL,
    "title" "text",
    "instructions" "text",
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "completed_at" timestamp with time zone,
    "completed_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "revision" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "job_visits_all_day_needs_date" CHECK (((NOT "all_day") OR ("visit_date" IS NOT NULL))),
    CONSTRAINT "job_visits_all_day_no_time" CHECK (((NOT "all_day") OR (("start_time" IS NULL) AND ("end_time" IS NULL)))),
    CONSTRAINT "job_visits_completed_pairing" CHECK ((("completed_at" IS NULL) = ("completed_by" IS NULL))),
    CONSTRAINT "job_visits_instructions_check" CHECK ((("instructions" IS NULL) OR ("char_length"("instructions") <= 2000))),
    CONSTRAINT "job_visits_position_check" CHECK (("position" >= 0)),
    CONSTRAINT "job_visits_source_check" CHECK (("source" = ANY (ARRAY['manual'::"text", 'generated'::"text", 'return'::"text", 'duplicated'::"text"]))),
    CONSTRAINT "job_visits_time_order" CHECK ((("end_time" IS NULL) OR (("start_time" IS NOT NULL) AND ("end_time" > "start_time")))),
    CONSTRAINT "job_visits_timed_needs_date" CHECK ((("start_time" IS NULL) OR ("visit_date" IS NOT NULL))),
    CONSTRAINT "job_visits_title_check" CHECK ((("title" IS NULL) OR (("char_length"(TRIM(BOTH FROM "title")) >= 1) AND ("char_length"(TRIM(BOTH FROM "title")) <= 160))))
);


ALTER TABLE "public"."job_visits" OWNER TO "postgres";


COMMENT ON TABLE "public"."job_visits" IS 'One occurrence of doing a job''s work. Scheduled, anytime or unscheduled is read off visit_date and start_time, never stored. Members read this table; only the job commands write it.';



