    CONSTRAINT "member_access_event_shapes_required_keys_check" CHECK ("private"."member_access_required_keys_are_allowed"("summary_keys", "required_summary_keys")),
    CONSTRAINT "member_access_event_shapes_subject_kind_check" CHECK (("subject_kind" = ANY (ARRAY['member'::"text", 'invitation'::"text", 'organization'::"text"]))),
