    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "opportunity_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actor_user_id" "uuid",
    "reason" "text",
    "note" "text",
    "reopen_explanation" "text",
    "prior_request_status" "text",
    "restores_event_id" "uuid",
    "idempotency_key" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "prior_quote_status" "text",
    CONSTRAINT "opportunity_outcome_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['won'::"text", 'lost'::"text", 'reopened'::"text"]))),
    CONSTRAINT "opportunity_outcome_events_idempotency_key_check" CHECK (("char_length"(TRIM(BOTH FROM "idempotency_key")) >= 8)),
    CONSTRAINT "opportunity_outcome_events_note_length" CHECK ((("note" IS NULL) OR ("char_length"("note") <= 1000))),
    CONSTRAINT "opportunity_outcome_events_other_requires_note" CHECK ((("reason" IS DISTINCT FROM 'other'::"text") OR ("char_length"(TRIM(BOTH FROM COALESCE("note", ''::"text"))) > 0))),
    CONSTRAINT "opportunity_outcome_events_prior_status_valid" CHECK ((("prior_request_status" IS NULL) OR ("prior_request_status" = ANY (ARRAY['new'::"text", 'unscheduled'::"text", 'assessment_completed'::"text", 'completed'::"text"])))),
    CONSTRAINT "opportunity_outcome_events_reason_vocabulary" CHECK ((("reason" IS NULL) OR ("reason" = ANY (ARRAY['price_too_high'::"text", 'chose_another_contractor'::"text", 'no_response'::"text", 'project_postponed'::"text", 'work_not_a_fit'::"text", 'duplicate_or_test_request'::"text", 'other'::"text"])))),
    CONSTRAINT "opportunity_outcome_events_reopen_explanation_length" CHECK ((("reopen_explanation" IS NULL) OR (("char_length"(TRIM(BOTH FROM "reopen_explanation")) >= 1) AND ("char_length"(TRIM(BOTH FROM "reopen_explanation")) <= 500)))),
    CONSTRAINT "opportunity_outcome_events_type_fields_consistent" CHECK (((("event_type" = 'lost'::"text") AND ("reopen_explanation" IS NULL) AND ("restores_event_id" IS NULL) AND (("prior_request_status" IS NOT NULL) <> ("prior_quote_status" IS NOT NULL))) OR (("event_type" = 'won'::"text") AND ("reason" IS NULL) AND ("note" IS NULL) AND ("reopen_explanation" IS NULL) AND ("restores_event_id" IS NULL) AND ("prior_request_status" IS NULL)) OR (("event_type" = 'reopened'::"text") AND ("reason" IS NULL) AND ("note" IS NULL) AND ("prior_request_status" IS NULL) AND ("prior_quote_status" IS NULL) AND ("restores_event_id" IS NOT NULL))))
);


ALTER TABLE "public"."opportunity_outcome_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."opportunity_outcome_events" IS 'Immutable Lost/Reopen history for Sales Pipeline opportunities. Members may only read this table. Every row is written by public.pipeline_mark_opportunity_lost or public.pipeline_reopen_opportunity, which run as the table owner; nothing else may insert, update, or delete a row here.';



COMMENT ON COLUMN "public"."opportunity_outcome_events"."reopen_explanation" IS 'Required by public.pipeline_reopen_opportunity for a Request-backed reopen. Null for a Quote-backed reopen: that one fires automatically off quotes.status, with no separate Pipeline-side explanation step (Jafar, 2026-08-23 -- the existing quote.revised activity entry is the record).';



COMMENT ON COLUMN "public"."opportunity_outcome_events"."prior_quote_status" IS 'The quotes.status value the moment before a won/lost event fired, for a quote-backed opportunity. Audit only -- unlike prior_request_status, nothing restores a Quote to this value, because the Quote''s own command (Revise, Restore) already drives its own status independently of Pipeline.';



