CREATE TABLE IF NOT EXISTS "public"."organization_commercial_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "event_kind" "text" NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actor_kind" "text" DEFAULT 'platform_owner'::"text" NOT NULL,
    "actor_owner_email" "text",
    "summary" "text" NOT NULL,
    "private_reason" "text",
    "private_reference" "text",
    "amount_usd_cents" integer,
    "original_confirmation_id" "uuid",
    "source_event_id" "uuid",
    "suspension_category" "text",
    "is_legacy_import" boolean DEFAULT false NOT NULL,
    "paid_through_effect" "text" NOT NULL,
    "paid_through_before" "date",
    "paid_through_after" "date",
    "commercial_timezone_before" "text",
    "commercial_timezone_after" "text",
    "deadline_recalculated" boolean DEFAULT false NOT NULL,
    "grace_ends_at_after" timestamp with time zone,
    "idempotency_key" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "change_before" "jsonb",
    "change_after" "jsonb",
    CONSTRAINT "organization_commercial_events_actor_email_kind_check" CHECK (((("actor_kind" = 'system'::"text") AND ("actor_owner_email" IS NULL)) OR (("actor_kind" = 'platform_owner'::"text") AND ("is_legacy_import" OR ("actor_owner_email" IS NOT NULL))))),
    CONSTRAINT "organization_commercial_events_actor_kind_check" CHECK (("actor_kind" = ANY (ARRAY['platform_owner'::"text", 'system'::"text"]))),
    CONSTRAINT "organization_commercial_events_actor_owner_email_check" CHECK ((("actor_owner_email" IS NULL) OR (("char_length"(TRIM(BOTH FROM "actor_owner_email")) >= 3) AND ("char_length"(TRIM(BOTH FROM "actor_owner_email")) <= 320)))),
    CONSTRAINT "organization_commercial_events_adjustment_origin_check" CHECK ((("event_kind" <> ALL (ARRAY['payment_correction_recorded'::"text", 'refund_recorded'::"text", 'payment_reversal_recorded'::"text"])) OR ("original_confirmation_id" IS NOT NULL))),
    CONSTRAINT "organization_commercial_events_amount_usd_cents_check" CHECK ((("amount_usd_cents" IS NULL) OR ("amount_usd_cents" <> 0))),
    CONSTRAINT "organization_commercial_events_change_payload_check" CHECK (((("change_before" IS NULL) OR ("jsonb_typeof"("change_before") = 'object'::"text")) AND (("change_after" IS NULL) OR ("jsonb_typeof"("change_after") = 'object'::"text")))),
    CONSTRAINT "organization_commercial_events_deadline_recalculated_check" CHECK (((NOT "deadline_recalculated") OR ("event_kind" = 'commercial_timezone_changed'::"text"))),
    CONSTRAINT "organization_commercial_events_event_kind_check" CHECK (("event_kind" = ANY (ARRAY['initial_payment_confirmed'::"text", 'renewal_confirmed'::"text", 'payment_correction_recorded'::"text", 'refund_recorded'::"text", 'payment_reversal_recorded'::"text", 'paid_through_adjusted'::"text", 'commercial_timezone_changed'::"text", 'free_access_granted'::"text", 'free_access_extended'::"text", 'free_access_converted_forever'::"text", 'free_access_ended'::"text", 'organization_suspended'::"text", 'organization_reactivated'::"text", 'pending_setup_resolved'::"text", 'package_version_changed'::"text", 'feature_exception_changed'::"text", 'limit_exception_changed'::"text", 'organization_closure_started'::"text", 'organization_closure_restored'::"text", 'organization_closure_completed'::"text"]))),
    CONSTRAINT "organization_commercial_events_idempotency_key_check" CHECK ((("char_length"(TRIM(BOTH FROM "idempotency_key")) >= 8) AND ("char_length"(TRIM(BOTH FROM "idempotency_key")) <= 200))),
    CONSTRAINT "organization_commercial_events_paid_through_effect_check" CHECK (("paid_through_effect" = ANY (ARRAY['set'::"text", 'unchanged'::"text"]))),
    CONSTRAINT "organization_commercial_events_paid_through_result_check" CHECK (((("paid_through_effect" = 'set'::"text") AND ("paid_through_after" IS NOT NULL)) OR (("paid_through_effect" = 'unchanged'::"text") AND (NOT ("paid_through_after" IS DISTINCT FROM "paid_through_before"))))),
    CONSTRAINT "organization_commercial_events_private_reason_check" CHECK ((("private_reason" IS NULL) OR (("char_length"(TRIM(BOTH FROM "private_reason")) >= 1) AND ("char_length"(TRIM(BOTH FROM "private_reason")) <= 1000)))),
    CONSTRAINT "organization_commercial_events_private_reference_check" CHECK ((("private_reference" IS NULL) OR (("char_length"(TRIM(BOTH FROM "private_reference")) >= 1) AND ("char_length"(TRIM(BOTH FROM "private_reference")) <= 240)))),
    CONSTRAINT "organization_commercial_events_reason_check" CHECK (("is_legacy_import" OR ("event_kind" <> ALL (ARRAY['organization_suspended'::"text", 'organization_reactivated'::"text", 'paid_through_adjusted'::"text", 'refund_recorded'::"text", 'payment_reversal_recorded'::"text", 'payment_correction_recorded'::"text", 'commercial_timezone_changed'::"text", 'pending_setup_resolved'::"text", 'package_version_changed'::"text", 'feature_exception_changed'::"text", 'limit_exception_changed'::"text", 'organization_closure_started'::"text", 'organization_closure_restored'::"text"])) OR ("char_length"(TRIM(BOTH FROM COALESCE("private_reason", ''::"text"))) > 0))),
    CONSTRAINT "organization_commercial_events_self_confirmation_check" CHECK (("original_confirmation_id" <> "id")),
    CONSTRAINT "organization_commercial_events_self_source_check" CHECK (("source_event_id" <> "id")),
    CONSTRAINT "organization_commercial_events_summary_check" CHECK ((("char_length"(TRIM(BOTH FROM "summary")) >= 1) AND ("char_length"(TRIM(BOTH FROM "summary")) <= 300))),
    CONSTRAINT "organization_commercial_events_suspension_category_check" CHECK (("suspension_category" = ANY (ARRAY['nonpayment'::"text", 'payment_dispute'::"text", 'security'::"text", 'support'::"text", 'other'::"text"]))),
    CONSTRAINT "organization_commercial_events_suspension_check" CHECK (
CASE "event_kind"
    WHEN 'organization_suspended'::"text" THEN ("suspension_category" IS NOT NULL)
    WHEN 'pending_setup_resolved'::"text" THEN true
    ELSE ("suspension_category" IS NULL)
END),
    CONSTRAINT "organization_commercial_events_timezone_change_check" CHECK ((("event_kind" <> 'commercial_timezone_changed'::"text") OR (("commercial_timezone_before" IS NOT NULL) AND ("commercial_timezone_after" IS NOT NULL) AND ("commercial_timezone_before" <> "commercial_timezone_after"))))
);


