    "limit_value" integer,
    "is_unlimited" boolean DEFAULT false NOT NULL,
    "starts_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "limit_state" "text" DEFAULT 'numeric'::"text" NOT NULL,
    "reason" "text",
    "actor_owner_email" "text",
    "is_legacy_import" boolean DEFAULT true NOT NULL,
    CONSTRAINT "organization_limit_overrides_actor_email_check" CHECK ((("actor_owner_email" IS NULL) OR (("char_length"(TRIM(BOTH FROM "actor_owner_email")) >= 3) AND ("char_length"(TRIM(BOTH FROM "actor_owner_email")) <= 320)))),
    CONSTRAINT "organization_limit_overrides_limit_key_check" CHECK (("limit_key" = ANY (ARRAY['employee_seats'::"text", 'operational_email_recipients'::"text", 'essential_email_recipients'::"text", 'website_chat_widgets'::"text", 'website_chat_accepted_conversations'::"text", 'automation_active_recipes'::"text", 'automation_max_conditions_per_recipe'::"text", 'automation_max_steps_per_recipe'::"text", 'automation_max_customer_messages_per_enrollment'::"text", 'automation_min_customer_message_spacing_minutes'::"text", 'automation_max_delay_days'::"text", 'automation_max_enrollment_duration_days'::"text", 'marketing_email_recipients'::"text"]))),
    CONSTRAINT "organization_limit_overrides_reason_check" CHECK (("is_legacy_import" OR (("char_length"(TRIM(BOTH FROM COALESCE("reason", ''::"text"))) >= 1) AND ("char_length"(TRIM(BOTH FROM COALESCE("reason", ''::"text"))) <= 1000)))),
    CONSTRAINT "organization_limit_overrides_state_check" CHECK (("limit_state" = ANY (ARRAY['unlimited'::"text", 'not_included'::"text", 'numeric'::"text"]))),
    CONSTRAINT "organization_limit_overrides_state_value_check" CHECK (((("limit_state" = 'unlimited'::"text") AND "is_unlimited" AND ("limit_value" IS NULL)) OR (("limit_state" = 'not_included'::"text") AND (NOT "is_unlimited") AND ("limit_value" IS NULL)) OR (("limit_state" = 'numeric'::"text") AND (NOT "is_unlimited") AND ("limit_value" IS NOT NULL) AND ("limit_value" >= 0)))),
    CONSTRAINT "organization_limit_overrides_window_check" CHECK ((("expires_at" IS NULL) OR ("expires_at" > "starts_at")))
);


