    "quote_version_id" "uuid",
    "quote_deposit_event_id" "uuid",
    CONSTRAINT "payment_stripe_checkouts_amount_minor_check" CHECK ((("amount_minor" > 0) AND ("amount_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "payment_stripe_checkouts_applied_minor_check" CHECK ((("applied_minor" IS NULL) OR ("applied_minor" >= 0))),
    CONSTRAINT "payment_stripe_checkouts_checkout_session_id_check" CHECK (("checkout_session_id" ~ '^cs_[A-Za-z0-9_]{1,255}$'::"text")),
    CONSTRAINT "payment_stripe_checkouts_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "payment_stripe_checkouts_kind_check" CHECK (("kind" = ANY (ARRAY['invoice'::"text", 'quote_deposit'::"text"]))),
    CONSTRAINT "payment_stripe_checkouts_paid_shape" CHECK ((("status" = 'paid'::"text") = (("completed_at" IS NOT NULL) AND ("applied_minor" IS NOT NULL) AND ((("kind" = 'invoice'::"text") AND ("payment_event_id" IS NOT NULL)) OR (("kind" = 'quote_deposit'::"text") AND ("quote_deposit_event_id" IS NOT NULL)))))),
    CONSTRAINT "payment_stripe_checkouts_payment_intent_id_check" CHECK ((("payment_intent_id" IS NULL) OR ("payment_intent_id" ~ '^pi_[A-Za-z0-9_]{1,255}$'::"text"))),
    CONSTRAINT "payment_stripe_checkouts_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'processing'::"text", 'paid'::"text", 'failed'::"text"]))),
    CONSTRAINT "payment_stripe_checkouts_stripe_account_id_check" CHECK (("stripe_account_id" ~ '^acct_[A-Za-z0-9]{1,64}$'::"text")),
    CONSTRAINT "payment_stripe_checkouts_target_shape" CHECK (((("kind" = 'invoice'::"text") AND ("invoice_id" IS NOT NULL) AND ("quote_id" IS NULL) AND ("quote_version_id" IS NULL)) OR (("kind" = 'quote_deposit'::"text") AND ("invoice_id" IS NULL) AND ("quote_id" IS NOT NULL) AND ("quote_version_id" IS NOT NULL)))),
    CONSTRAINT "payment_stripe_checkouts_tip_minor_check" CHECK ((("tip_minor" >= 0) AND ("tip_minor" <= '1000000000000'::bigint)))
);


