    CONSTRAINT "payment_stripe_connections_account_id_check" CHECK (("stripe_account_id" ~ '^acct_[A-Za-z0-9]{1,64}$'::"text")),
    CONSTRAINT "payment_stripe_connections_check_status_check" CHECK (("last_check_status" = ANY (ARRAY['ok'::"text", 'key_rejected'::"text", 'permission_missing'::"text", 'account_unavailable'::"text", 'webhook_missing'::"text"]))),
    CONSTRAINT "payment_stripe_connections_ciphertext_check" CHECK ((("octet_length"("api_key_ciphertext") > 0) AND ("octet_length"("webhook_secret_ciphertext") > 0))),
    CONSTRAINT "payment_stripe_connections_display_name_check" CHECK ((("account_display_name" IS NULL) OR ("char_length"("account_display_name") <= 200))),
    CONSTRAINT "payment_stripe_connections_endpoint_id_check" CHECK (("webhook_endpoint_id" ~ '^we_[A-Za-z0-9]{1,64}$'::"text")),
    CONSTRAINT "payment_stripe_connections_key_id_check" CHECK (("encryption_key_id" ~ '^[A-Za-z0-9._-]{1,64}$'::"text")),
    CONSTRAINT "payment_stripe_connections_last4_check" CHECK (("api_key_last4" ~ '^[A-Za-z0-9]{4}$'::"text")),
    CONSTRAINT "payment_stripe_connections_nonce_check" CHECK ((("octet_length"("api_key_nonce") = 12) AND ("octet_length"("webhook_secret_nonce") = 12))),
    CONSTRAINT "payment_stripe_connections_tag_check" CHECK ((("octet_length"("api_key_tag") = 16) AND ("octet_length"("webhook_secret_tag") = 16)))
);


ALTER TABLE "public"."payment_stripe_connections" OWNER TO "postgres";


COMMENT ON TABLE "public"."payment_stripe_connections" IS 'Server-owned Stripe connection. AES-256-GCM ciphertext only; plaintext keys must never enter Postgres.';



CREATE TABLE IF NOT EXISTS "public"."payment_stripe_refunds" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "checkout_id" "uuid" NOT NULL,
    "requested_by" "uuid",
    "stripe_refund_id" "text",
    "amount_minor" bigint NOT NULL,
    "currency_code" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "failure_message" "text",
    "refund_event_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    CONSTRAINT "payment_stripe_refunds_amount_minor_check" CHECK ((("amount_minor" > 0) AND ("amount_minor" <= '1000000000000'::bigint))),
    CONSTRAINT "payment_stripe_refunds_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "payment_stripe_refunds_failure_message_check" CHECK ((("failure_message" IS NULL) OR ("char_length"("failure_message") <= 300))),
    CONSTRAINT "payment_stripe_refunds_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'succeeded'::"text", 'failed'::"text"]))),
    CONSTRAINT "payment_stripe_refunds_stripe_refund_id_check" CHECK ((("stripe_refund_id" IS NULL) OR ("stripe_refund_id" ~ '^re_[A-Za-z0-9_]{1,255}$'::"text"))),
    CONSTRAINT "payment_stripe_refunds_succeeded_shape" CHECK ((("status" = 'succeeded'::"text") = (("refund_event_id" IS NOT NULL) AND ("completed_at" IS NOT NULL))))
);


ALTER TABLE "public"."payment_stripe_refunds" OWNER TO "postgres";


COMMENT ON TABLE "public"."payment_stripe_refunds" IS 'One Stripe refund object, whether started in UCRM or seen for the first time in a webhook. Server-owned. Moves out of pending exactly once, keyed by Stripe''s own refund id so either origin, or a redelivered webhook, lands on the same row.';



CREATE TABLE IF NOT EXISTS "public"."payment_stripe_webhook_events" (
    "organization_id" "uuid" NOT NULL,
    "stripe_event_id" "text" NOT NULL,
    "event_type" "text" NOT NULL,
