    CONSTRAINT "payment_stripe_webhook_events_stripe_event_id_check" CHECK ((("stripe_event_id" ~ '^evt_[A-Za-z0-9_]{1,255}$'::"text") OR ("stripe_event_id" ~ '^evt_[A-Za-z0-9_]{1,255}:re_[A-Za-z0-9_]{1,255}$'::"text") OR ("stripe_event_id" ~ '^sync:re_[A-Za-z0-9_]{1,255}:re_[A-Za-z0-9_]{1,255}$'::"text")))
);


ALTER TABLE "public"."payment_stripe_webhook_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."payment_stripe_webhook_events" IS 'Every Stripe webhook event UCRM has acted on, by event id. Makes redelivery a no-op. Server-owned.';



