    "actor_kind" "text" NOT NULL,
    "actor_user_id" "uuid",
    "quote_access_link_id" "uuid",
    "method" "text" NOT NULL,
    "note" "text",
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
