    "decided_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "quote_decisions_actor_kind_check" CHECK (("actor_kind" = ANY (ARRAY['customer'::"text", 'staff'::"text"]))),
    CONSTRAINT "quote_decisions_actor_matches_method" CHECK (
CASE "actor_kind"
    WHEN 'customer'::"text" THEN ("method" = 'online'::"text")
    ELSE (("method" = ANY (ARRAY['offline_verbal'::"text", 'in_person'::"text"])) AND ("quote_access_link_id" IS NULL))
END),
    CONSTRAINT "quote_decisions_method_check" CHECK (("method" = ANY (ARRAY['online'::"text", 'offline_verbal'::"text", 'in_person'::"text"]))),
    CONSTRAINT "quote_decisions_note_check" CHECK ((("note" IS NULL) OR (("char_length"(TRIM(BOTH FROM "note")) >= 1) AND ("char_length"(TRIM(BOTH FROM "note")) <= 1000)))),
    CONSTRAINT "quote_decisions_outcome_check" CHECK (("outcome" = ANY (ARRAY['approved'::"text", 'changes_requested'::"text", 'declined'::"text"])))
);


ALTER TABLE "public"."quote_decisions" OWNER TO "postgres";


COMMENT ON TABLE "public"."quote_decisions" IS 'Immutable record of every answer a quote has received, from the customer through a link or from staff off the app. Exactly one row per quote is current. Rows are written only by the quote commands.';



COMMENT ON COLUMN "public"."quote_decisions"."evidence" IS 'Truncated IP and user agent for a customer answer, redacted before it arrives. Never shown to the customer and never treated as proof of who was holding the device.';



