    CONSTRAINT "quote_version_lines_position_check" CHECK (("position" >= 0)),
    CONSTRAINT "quote_version_lines_recommended_check" CHECK (((NOT "is_recommended") OR (("line_kind" = 'priced'::"text") AND ("selection_kind" = 'optional'::"text")))),
    CONSTRAINT "quote_version_lines_selection_check" CHECK (("selection_kind" = ANY (ARRAY['required'::"text", 'optional'::"text"]))),
    CONSTRAINT "quote_version_lines_shape_check" CHECK (((("line_kind" = 'priced'::"text") AND ("category" = ANY (ARRAY['product'::"text", 'service'::"text"])) AND ("quantity" > (0)::numeric) AND ("quantity" <= (1000000)::numeric) AND ("unit_price_minor" >= 0) AND ("unit_price_minor" <= '1000000000000'::bigint) AND ("unit_cost_minor" >= 0) AND ("unit_cost_minor" <= '1000000000000'::bigint) AND ((NOT "is_labor") OR ("category" = 'service'::"text"))) OR (("line_kind" = ANY (ARRAY['text'::"text", 'heading'::"text"])) AND ("category" IS NULL) AND (NOT "is_labor") AND ("quantity" IS NULL) AND ("unit_price_minor" IS NULL) AND ("unit_cost_minor" IS NULL) AND (NOT "is_taxable") AND ("selection_kind" = 'required'::"text") AND (NOT "is_recommended")))),
    CONSTRAINT "quote_version_lines_unit_label_check" CHECK ((("unit_label" IS NULL) OR (("char_length"(TRIM(BOTH FROM "unit_label")) >= 1) AND ("char_length"(TRIM(BOTH FROM "unit_label")) <= 24))))
);


