    CONSTRAINT "quote_version_schedule_items_value_range_check" CHECK (((("value_type" = 'percentage'::"text") AND (("value" >= 1) AND ("value" <= 10000))) OR (("value_type" = 'fixed'::"text") AND (("value" >= 1) AND ("value" <= '1000000000000'::bigint))))),
    CONSTRAINT "quote_version_schedule_items_value_type_check" CHECK (("value_type" = ANY (ARRAY['fixed'::"text", 'percentage'::"text"])))
);


ALTER TABLE "public"."quote_version_schedule_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."quote_version_schedule_items" IS 'A version''s own ordered payment installments. Deposit-only carries exactly one row; a milestone schedule carries several. The is_deposit row is the one approval must collect before the job is ready.';



CREATE TABLE IF NOT EXISTS "public"."request_pricing_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
