    "unit_price_minor" bigint DEFAULT 0 NOT NULL,
    "unit_cost_minor" bigint DEFAULT 0 NOT NULL,
    "is_taxable" boolean DEFAULT true NOT NULL,
    "line_total_minor" bigint GENERATED ALWAYS AS ("public"."pricing_line_total_minor"("quantity", "unit_price_minor")) STORED NOT NULL,
    "line_cost_total_minor" bigint GENERATED ALWAYS AS ("public"."pricing_line_total_minor"("quantity", "unit_cost_minor")) STORED NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
