    CONSTRAINT "request_pricing_lines_category_check" CHECK (("category" = ANY (ARRAY['product'::"text", 'service'::"text"]))),
    CONSTRAINT "request_pricing_lines_description_check" CHECK ((("description" IS NULL) OR ("char_length"("description") <= 2000))),
    CONSTRAINT "request_pricing_lines_labor_is_service" CHECK (((NOT "is_labor") OR ("category" = 'service'::"text"))),
    CONSTRAINT "request_pricing_lines_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "name")) >= 2) AND ("char_length"(TRIM(BOTH FROM "name")) <= 160))),
