    CONSTRAINT "request_pricing_lines_unit_label_check" CHECK ((("unit_label" IS NULL) OR (("char_length"(TRIM(BOTH FROM "unit_label")) >= 1) AND ("char_length"(TRIM(BOTH FROM "unit_label")) <= 24)))),
    CONSTRAINT "request_pricing_lines_unit_price_minor_check" CHECK ((("unit_price_minor" >= 0) AND ("unit_price_minor" <= '1000000000000'::bigint)))
);


ALTER TABLE "public"."request_pricing_lines" OWNER TO "postgres";


COMMENT ON TABLE "public"."request_pricing_lines" IS 'Priced product, service, and labor rows on a request. Members may read this table, never write it: the whole set is replaced atomically by public.replace_request_pricing_lines, which is also what keeps requests.pricing_subtotal_minor and requests.pricing_revision true.';



CREATE TABLE IF NOT EXISTS "public"."requests" (
