    CONSTRAINT "team_notifications_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 200)))
);


ALTER TABLE "public"."team_notifications" OWNER TO "postgres";


