CREATE TABLE IF NOT EXISTS "public"."website_chat_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "widget_id" "uuid" NOT NULL,
    "client_id" "uuid",
    "match_status" "text" DEFAULT 'resolved'::"text" NOT NULL,
    "candidate_client_id_by_phone" "uuid",
    "candidate_client_id_by_email" "uuid",
    "visitor_name" "text" NOT NULL,
    "submitted_phone_e164" "text",
    "submitted_email" "text",
    "normalized_phone" "text",
    "normalized_email" "text",
    "session_token_hash" "text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "attribution" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "consent_transactional_sms" boolean DEFAULT false NOT NULL,
    "ip_hash" "text",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_activity_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    "closed_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_by" "uuid",
    "sms_consent_disclosure" "text",
    CONSTRAINT "website_chat_sessions_attribution_check" CHECK (("jsonb_typeof"("attribution") = 'object'::"text")),
    CONSTRAINT "website_chat_sessions_client_presence_check" CHECK (((("match_status" = 'resolved'::"text") AND ("client_id" IS NOT NULL)) OR (("match_status" = 'needs_review'::"text") AND ("client_id" IS NULL)))),
    CONSTRAINT "website_chat_sessions_closed_reason_check" CHECK (("closed_reason" = ANY (ARRAY['visitor_ended'::"text", 'staff_ended'::"text", 'inactivity_timeout'::"text", 'widget_disabled'::"text"]))),
    CONSTRAINT "website_chat_sessions_closed_reason_present_check" CHECK (((("closed_at" IS NULL) AND ("closed_reason" IS NULL)) OR (("closed_at" IS NOT NULL) AND ("closed_reason" IS NOT NULL)))),
    CONSTRAINT "website_chat_sessions_idempotency_key_check" CHECK ((("char_length"("btrim"("idempotency_key")) >= 8) AND ("char_length"("btrim"("idempotency_key")) <= 200))),
    CONSTRAINT "website_chat_sessions_identifier_present_check" CHECK ((("submitted_phone_e164" IS NOT NULL) OR ("submitted_email" IS NOT NULL))),
    CONSTRAINT "website_chat_sessions_match_status_check" CHECK (("match_status" = ANY (ARRAY['resolved'::"text", 'needs_review'::"text"]))),
    CONSTRAINT "website_chat_sessions_sms_consent_disclosure_check" CHECK ((("sms_consent_disclosure" IS NULL) OR ("consent_transactional_sms" AND (("char_length"("btrim"("sms_consent_disclosure")) >= 1) AND ("char_length"("btrim"("sms_consent_disclosure")) <= 1000))))),
    CONSTRAINT "website_chat_sessions_submitted_email_check" CHECK ((("submitted_email" IS NULL) OR (("char_length"("btrim"("submitted_email")) >= 3) AND ("char_length"("btrim"("submitted_email")) <= 254)))),
    CONSTRAINT "website_chat_sessions_submitted_phone_e164_check" CHECK ((("submitted_phone_e164" IS NULL) OR ("submitted_phone_e164" ~ '^\+[1-9][0-9]{6,14}$'::"text"))),
    CONSTRAINT "website_chat_sessions_visitor_name_check" CHECK ((("char_length"("btrim"("visitor_name")) >= 2) AND ("char_length"("btrim"("visitor_name")) <= 120)))
);


ALTER TABLE "public"."website_chat_sessions" OWNER TO "postgres";


COMMENT ON TABLE "public"."website_chat_sessions" IS 'One visitor conversation on one widget. Sessions from distinct widgets stay separate; a later inquiry creates a new session linked to the same Client.';



COMMENT ON COLUMN "public"."website_chat_sessions"."visitor_name" IS 'The whole name the visitor typed into the identity form. Split at the first space into the Lead Client''s first and last name when the session created one.';



COMMENT ON COLUMN "public"."website_chat_sessions"."consent_transactional_sms" IS 'True only when the visitor ticked the service-SMS box and its disclosure was stored. Rows before 2026-10-05 came from a pre-ticked box and are not consent evidence; the SMS consent ledger is the source of truth.';



COMMENT ON COLUMN "public"."website_chat_sessions"."closed_by" IS 'The staff member who ended this session, when a person did. Null for inactivity_timeout, widget_disabled, and visitor_ended.';



COMMENT ON COLUMN "public"."website_chat_sessions"."sms_consent_disclosure" IS 'The exact service-SMS consent wording shown to the visitor when they ticked the box; null when not given.';



CREATE TABLE IF NOT EXISTS "public"."website_chat_widget_origins" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "widget_id" "uuid" NOT NULL,
    "origin" "text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "website_chat_widget_origins_origin_check" CHECK ((("origin" = "lower"("btrim"("origin"))) AND ("origin" ~ '^https?://[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+(:[0-9]{1,5})?$'::"text")))
);


ALTER TABLE "public"."website_chat_widget_origins" OWNER TO "postgres";


COMMENT ON TABLE "public"."website_chat_widget_origins" IS 'One row per allowed origin per Website Chat widget. Written only by the commands below.';



CREATE TABLE IF NOT EXISTS "public"."website_chat_widgets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "launcher_position" "text" DEFAULT 'bottom_right'::"text" NOT NULL,
    "teaser_text" "text",
    "greeting_text" "text",
    "contact_requirement" "text" DEFAULT 'either'::"text" NOT NULL,
    "availability_visibility_mode" "text" DEFAULT 'hidden'::"text" NOT NULL,
    "source_label" "text",
    "channel_options" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "published" boolean DEFAULT false NOT NULL,
    "disabled_at" timestamp with time zone,
    "suspended_at" timestamp with time zone,
    "public_token" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "revision" integer DEFAULT 1 NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "privacy_policy_url" "text",
    CONSTRAINT "website_chat_widgets_availability_visibility_mode_check" CHECK (("availability_visibility_mode" = ANY (ARRAY['hidden'::"text", 'show_when_available'::"text", 'always'::"text"]))),
    CONSTRAINT "website_chat_widgets_channel_options_check" CHECK (("jsonb_typeof"("channel_options") = 'array'::"text")),
    CONSTRAINT "website_chat_widgets_contact_requirement_check" CHECK (("contact_requirement" = ANY (ARRAY['phone'::"text", 'email'::"text", 'either'::"text"]))),
    CONSTRAINT "website_chat_widgets_greeting_text_check" CHECK ((("greeting_text" IS NULL) OR (("char_length"("btrim"("greeting_text")) >= 1) AND ("char_length"("btrim"("greeting_text")) <= 300)))),
    CONSTRAINT "website_chat_widgets_launcher_position_check" CHECK (("launcher_position" = ANY (ARRAY['bottom_left'::"text", 'bottom_right'::"text"]))),
    CONSTRAINT "website_chat_widgets_name_check" CHECK ((("char_length"("btrim"("name")) >= 1) AND ("char_length"("btrim"("name")) <= 120))),
    CONSTRAINT "website_chat_widgets_privacy_policy_url_check" CHECK ((("privacy_policy_url" IS NULL) OR (("privacy_policy_url" ~~ 'https://%'::"text") AND (("char_length"("privacy_policy_url") >= 12) AND ("char_length"("privacy_policy_url") <= 500))))),
    CONSTRAINT "website_chat_widgets_source_label_check" CHECK ((("source_label" IS NULL) OR (("char_length"("btrim"("source_label")) >= 1) AND ("char_length"("btrim"("source_label")) <= 120)))),
    CONSTRAINT "website_chat_widgets_teaser_text_check" CHECK ((("teaser_text" IS NULL) OR (("char_length"("btrim"("teaser_text")) >= 1) AND ("char_length"("btrim"("teaser_text")) <= 300))))
);


ALTER TABLE "public"."website_chat_widgets" OWNER TO "postgres";


COMMENT ON TABLE "public"."website_chat_widgets" IS 'Contractor-owned Website Chat widget configuration. Written only by the commands below -- never edited through RLS directly -- matching organization_tax_rates.';



COMMENT ON COLUMN "public"."website_chat_widgets"."privacy_policy_url" IS 'Contractor-owned https URL linked from the identity form (WC4.3). Null hides the link entirely.';



