CREATE POLICY "permitted members can view tax rates" ON "public"."organization_tax_rates" FOR SELECT TO "authenticated" USING (("private"."is_organization_member"("organization_id") AND ("private"."has_permission"("organization_id", 'settings.taxes.manage'::"text") OR "private"."has_permission"("organization_id", 'quotes.edit'::"text") OR "private"."has_permission"("organization_id", 'property.manage'::"text"))));



CREATE POLICY "permitted members can view time entries" ON "public"."job_time_entries" FOR SELECT TO "authenticated" USING ((("organization_id" = ( SELECT "private"."current_organization"() AS "current_organization")) AND ((( SELECT "private"."current_permission_scope"('jobs.view'::"text") AS "current_permission_scope") = 'all'::"text") OR ((( SELECT "private"."current_permission_scope"('jobs.view'::"text") AS "current_permission_scope") = 'assigned'::"text") AND "private"."is_assigned_to_job"("organization_id", "job_id"))) AND ((( SELECT "private"."current_permission_scope"('time.track_team'::"text") AS "current_permission_scope") <> 'none'::"text") OR (("user_id" = ( SELECT "auth"."uid"() AS "uid")) AND (( SELECT "private"."current_permission_scope"('time.track_own'::"text") AS "current_permission_scope") <> 'none'::"text")))));



CREATE POLICY "permitted members can view visit checklist answers" ON "public"."visit_checklist_answers" FOR SELECT TO "authenticated" USING ((("organization_id" = ( SELECT "private"."current_organization"() AS "current_organization")) AND ((( SELECT "private"."current_permission_scope"('jobs.view'::"text") AS "current_permission_scope") = 'all'::"text") OR ((( SELECT "private"."current_permission_scope"('jobs.view'::"text") AS "current_permission_scope") = 'assigned'::"text") AND "private"."is_assigned_to_job"("organization_id", "job_id")))));



CREATE POLICY "permitted members can view visit lines" ON "public"."job_visit_line_items" FOR SELECT TO "authenticated" USING ((("organization_id" = ( SELECT "private"."current_organization"() AS "current_organization")) AND ((( SELECT "private"."current_permission_scope"('jobs.view'::"text") AS "current_permission_scope") = 'all'::"text") OR ((( SELECT "private"."current_permission_scope"('jobs.view'::"text") AS "current_permission_scope") = 'assigned'::"text") AND "private"."is_assigned_to_job"("organization_id", "job_id")))));



