CREATE POLICY "users can view their own and teammate profiles" ON "public"."profiles" FOR SELECT TO "authenticated" USING (((( SELECT "auth"."uid"() AS "uid") = "id") OR (EXISTS ( SELECT 1
   FROM ("public"."organization_members" "viewer"
     JOIN "public"."organization_members" "target" ON (("target"."organization_id" = "viewer"."organization_id")))
  WHERE (("viewer"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("viewer"."status" = 'active'::"text") AND ("target"."user_id" = "profiles"."id") AND ("target"."status" <> 'removed'::"text"))))));



